-- Banco prontuario: prontuários eletrônicos FICTÍCIOS de 500 pacientes de uma rede de cardiologia.
-- É a fonte de dados da aula de RAG (o equivalente ao banco de chamados do projeto formacao-inteligencia-artificial/rag).
-- Nomes, histórias e médicos são inventados. Não use como referência clínica.
-- Roda automaticamente na primeira vez que o volume do compose.yaml é criado (docker compose down -v recria tudo).

create database prontuario;
\connect prontuario

begin;

create table medico (
  id_medico serial primary key,
  nome text not null,
  especialidade text not null
);

create table paciente (
  id_paciente serial primary key,
  nome text not null,
  sexo char(1) not null check (sexo in ('F', 'M')),
  data_nascimento date not null,
  cidade text not null,
  uf char(2) not null,
  profissao text not null,
  -- Comorbidades, hábitos, história familiar e medicamentos em uso antes do primeiro atendimento
  antecedentes text not null,
  alergias text not null
);

-- Cada consulta, retorno, teleconsulta, ida ao pronto-socorro ou internação
create table atendimento (
  id_atendimento serial primary key,
  id_paciente integer not null references paciente (id_paciente),
  id_medico integer not null references medico (id_medico),
  data_atendimento timestamp not null,
  tipo text not null check (tipo in ('consulta', 'retorno', 'teleconsulta', 'pronto_socorro', 'internacao')),
  queixa_principal text not null,
  pressao_sistolica integer,
  pressao_diastolica integer,
  frequencia_cardiaca integer,
  peso_kg numeric(5, 1),
  -- Texto livre do médico: história, exame físico e raciocínio
  evolucao text not null,
  -- Texto livre do médico: o que foi decidido e orientado
  conduta text not null
);

create index atendimento_paciente_idx on atendimento (id_paciente);

-- Diagnósticos registrados no atendimento (CID-10)
create table diagnostico (
  id_diagnostico serial primary key,
  id_atendimento integer not null references atendimento (id_atendimento),
  cid text not null,
  descricao text not null
);

create index diagnostico_atendimento_idx on diagnostico (id_atendimento);
create index diagnostico_cid_idx on diagnostico (cid);

-- Resultados de exames vistos no atendimento
create table exame (
  id_exame serial primary key,
  id_atendimento integer not null references atendimento (id_atendimento),
  nome text not null,
  resultado text not null
);

create index exame_atendimento_idx on exame (id_atendimento);

-- Receita vigente ao final do atendimento
create table prescricao (
  id_prescricao serial primary key,
  id_atendimento integer not null references atendimento (id_atendimento),
  medicamento text not null,
  dose text not null,
  posologia text not null
);

create index prescricao_atendimento_idx on prescricao (id_atendimento);

-- Como o caso terminou ou como estava no último registro
create table desfecho (
  id_paciente integer primary key references paciente (id_paciente),
  data_desfecho date not null,
  situacao text not null check (situacao in ('controlado', 'melhorou', 'estavel', 'piorou', 'obito', 'abandonou', 'transferido')),
  descricao text not null
);


