insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (1, 'Wellington Takeshi Yamamoto', 'M', '1978-05-12', 'São Paulo', 'SP', 'Motorista de aplicativo', 'Sem diagnóstico prévio de doenças crônicas. Sedentário, trabalha 10 a 12 horas por dia sentado e se alimenta na rua. Etilismo social aos fins de semana. Pai hipertenso, falecido de AVC aos 62 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1, 1, 1, '2023-03-06 18:20', 'consulta', 'Pressão alta na farmácia, deu 150 por 100', 152, 96, 82, 96.8, 'Homem de 44 anos, motorista de aplicativo, passa até 12 horas sentado e come salgado, refrigerante e marmitex na rua. Procurou o serviço por PA 150x100 em duas aferições na farmácia, com cefaleia occipital ocasional. Nega dor torácica, dispneia e palpitações. Pai com AVC aos 62 anos. Ao exame: obeso (IMC 31,5), RCR 2T BNF sem sopros, MV+ sem RA, sem edema, pulsos simétricos. PA 152x96 mmHg (média de 3 medidas, manguito adequado). HD: HAS estágio 1 com obesidade; confirmar com MRPA antes de iniciar fármaco.', 'Solicitado MRPA de 5 dias, perfil lipídico, glicemia, creatinina, potássio e urina tipo 1. Orientada MEV: reduzir sal e ultraprocessados, levar marmita três vezes por semana, caminhar 30 minutos cinco vezes por semana e fazer pausas a cada duas horas ao volante. Meta de perda de 5 kg em 3 meses. Retorno em 45 dias com os exames.'),
  (2, 1, 1, '2023-04-24 18:40', 'retorno', 'Trouxe o MRPA e os exames', 148, 94, 78, 94.9, 'Retorna com MRPA: média de 146x93 mmHg em 5 dias, sem valores abaixo de 135x85. Perdeu 1,9 kg, caminha três vezes por semana, mas ainda almoça na rua quase todo dia e diz que ''o sal está em tudo''. Refere cefaleia menos frequente. Sem sintomas cardiovasculares. Exames: LDL 142 mg/dL, glicemia 104 mg/dL, creatinina e potássio normais, urina tipo 1 sem proteinúria. HD: HAS estágio 1 confirmada por MRPA, persistente após 7 semanas de MEV, risco moderado.', 'Iniciada losartana 50 mg pela manhã. Reforçada orientação alimentar, com sugestão de encontrar restaurante por quilo e evitar frituras. Manter caminhadas. Repetir creatinina e potássio em 30 dias. Retorno em 60 dias com novo MRPA.'),
  (3, 1, 1, '2023-07-03 19:10', 'retorno', 'Vim mostrar a pressão de casa', 126, 78, 74, 91.2, 'Paciente refere boa adesão à losartana, sem tosse, tontura ou outros efeitos. Perdeu mais 3,7 kg desde a última consulta (total de 5,6 kg), leva marmita quatro dias por semana e reduziu o refrigerante a um por semana. Medidas domiciliares entre 120x76 e 130x82 mmHg. Cefaleia desapareceu. Ao exame: BEG, RCR 2T BNF, sem sopros. Creatinina 0,9 mg/dL e potássio 4,4 mEq/L após início do BRA.', 'Manter losartana 50 mg/dia e MEV. Meta de PA < 130/80 atingida. Solicitado novo perfil lipídico e glicemia em 6 meses. Retorno semestral, com orientação de recorrer antes se PA domiciliar acima de 140x90.');
