insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (1, '2023-07-10', 'controlado', 'Hipertensão estágio 1 controlada com MEV associada a losartana 50 mg/dia. Perdeu 5,6 kg, PA de consultório 126x78 mmHg e domiciliar na meta, sem efeitos adversos. Segue em acompanhamento semestral, com meta de nova redução de peso para tentar reduzir a medicação no futuro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (2, 'Rosângela Pereira da Conceição', 'F', '1962-11-03', 'Salvador', 'BA', 'Diarista', 'HAS há 9 anos e DM2 há 7 anos. Em uso de metformina 850 mg 12/12h e enalapril 10 mg 12/12h até 2 meses atrás, quando parou por conta própria por causa de tosse seca. Sedentária, obesidade grau I. Mãe diabética e hipertensa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (4, 2, 1, '2021-08-17 08:30', 'consulta', 'Tosse do remédio da pressão e a pressão subiu', 158, 92, 80, 78.5, 'Mulher de 58 anos, diarista, hipertensa e diabética, encaminhada da UBS. Relata que o enalapril provocou ''uma tosse seca que não deixava dormir'' e por isso parou há 2 meses sem avisar ninguém. Desde então PA em torno de 160x95 quando mede na unidade. Nega dor torácica, dispneia, edema, queixas visuais. Sem tosse atualmente. Ao exame: RCR 2T BNF sem sopros, MV+ sem RA, pulsos presentes, sem edema. Exames trazidos: HbA1c 8,1%, relação albumina/creatinina 148 mg/g, creatinina 0,9 mg/dL (TFGe 71). HD: HAS estágio 1 descontrolada, DM2 com albuminúria, tosse por IECA.', 'Substituir IECA por BRA: losartana 50 mg 12/12h, associada a anlodipino 5 mg/dia. Manter metformina. Repetir creatinina e potássio em 2 semanas. Encaminhar à endocrinologia para ajuste do diabetes. Orientada a nunca suspender medicamento sem avisar e a trazer a caixa dos remédios no retorno.'),
  (5, 2, 1, '2021-10-05 08:50', 'retorno', 'Sem tosse, só um inchaço no pé', 134, 82, 74, 77.9, 'Refere adesão regular, sem tosse. Notou edema discreto de tornozelos no fim do dia, mais ao ficar muito tempo em pé nas faxinas. Ao exame: edema 1+/4+ bilateral, depressível, sem sinais de congestão. PA 134x82 mmHg. Creatinina 1,0 mg/dL, potássio 4,9 mEq/L após BRA (aceitável). Relação albumina/creatinina caiu para 96 mg/g. HD: HAS quase na meta, edema leve por anlodipino, DM2 com albuminuria em queda.', 'Manter losartana. Reduzir anlodipino para 2,5 mg e observar o edema; se não houver controle, trocar por outra classe. Repetir potássio e creatinina em 3 meses. Reforçar redução de sal e elevação dos pés. Retorno em 90 dias.'),
  (6, 2, 1, '2022-06-20 09:10', 'retorno', 'Vim trazer os exames de rotina', 128, 78, 72, 76.0, 'Retorna após 8 meses, atrasou por causa de trabalho em outra cidade. Edema de tornozelo resolvido com a redução do anlodipino. Sem tosse. Segue em acompanhamento com a endocrinologia, perdeu 1,9 kg. Exames: HbA1c 7,4%, relação albumina/creatinina 82 mg/g (persiste albuminúria moderada), creatinina 1,0 mg/dL, potássio 4,8 mEq/L, LDL 118 mg/dL. PA de consultório na meta.', 'Adicionar dapagliflozina 10 mg/dia pelo benefício renal e cardiovascular no DM2 com albuminúria, orientando higiene íntima e hidratação. Manter losartana. Iniciar atorvastatina 20 mg. Repetir albuminúria e creatinina em 4 meses.');
