insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (2, '2022-06-20', 'estavel', 'PA na meta com losartana e anlodipino em dose baixa, sem tosse. Persiste albuminúria moderada (82 mg/g) e diabetes ainda acima da meta, motivo da introdução de dapagliflozina e estatina. Segue em acompanhamento conjunto com a endocrinologia, com reavaliação da albuminúria em 4 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (3, 'Osvaldo Brandão Meireles', 'M', '1955-02-20', 'Ribeirão Preto', 'SP', 'Pedreiro aposentado', 'HAS há 18 anos, sempre com picos de PA. Encaminhado como hipertensão resistente em uso de quatro medicamentos. Tabagista de 30 maços-ano, parou em 2012. Mora com a esposa, que cuida da casa; passa as manhãs na obra de um filho.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (7, 3, 2, '2020-02-10 10:00', 'consulta', 'Minha pressão não baixa de jeito nenhum', 168, 102, 68, 79.3, 'Pcte 64 anos, encaminhado da UBS com HAS ''resistente'' em uso de losartana 100 mg, hidroclorotiazida 25 mg, anlodipino 10 mg e carvedilol 12,5 mg 12/12h. Diz tomar ''tudo certinho''. Ao perguntar sobre rotina, a esposa informa que ele toma os comprimidos só quando sente dor de cabeça e que a farmácia popular só libera a losartana a cada dois meses. Pill count: sobraram muitos comprimidos. Braço de 36 cm medido com manguito padrão. Ao exame: RCR 2T BNF, B4 presente, sem sopros, MV+ sem RA. PA 168x102 mmHg (manguito adequado, 3 medidas). HD: suspeita de pseudorresistência por má adesão e técnica inadequada de medida.', 'Explicada a diferença entre hipertensão e dor de cabeça. Entregue caixa organizadora semanal, preenchida pela esposa. Manter os quatro fármacos por enquanto, com tomada supervisionada por 4 semanas. Solicitados creatinina, potássio, ECG e ECO. Retorno em 30 dias com MAPA.'),
  (8, 3, 2, '2020-03-16 10:20', 'retorno', 'A mulher me deu o remédio todo dia', 112, 68, 56, 78.8, 'Retorna com adesão total supervisionada pela esposa. Refere tontura ao levantar e cansaço nas últimas duas semanas. MAPA em uso regular das medicações: média 24h de 116x70 mmHg, vigília 120x72, sono 106x62, sem descenso excessivo. PA ortostática 104x62 com sintomas. FC 56 bpm. Ao exame: sem sinais de congestão. ECO: HVE leve (septo 12 mm), FEVE 62%. HD: pseudorresistência por má adesão, hoje com superdosagem relativa.', 'Suspender carvedilol (bradicardia e hipotensão, sem indicação específica) e reduzir anlodipino para 5 mg. Manter caixa organizadora. Orientado a levantar devagar. Retorno em 45 dias com MRPA para reavaliar necessidade de ajustes.'),
  (9, 3, 2, '2020-09-14 09:40', 'retorno', 'Trouxe as medidas de casa', 124, 76, 70, 78.0, 'Seis meses depois, sem tontura ao levantar e sem queixas. MRPA com média de 122x74 mmHg. A esposa mantém a caixa semanal e retira os remédios mensalmente por receita nova da farmácia popular. Ao exame: PA 124x76 mmHg, ortostática sem queda. RCR 2T BNF sem sopros, sem edema. Creatinina 1,1 mg/dL, potássio 4,2 mEq/L, sódio 139 mEq/L.', 'Manter esquema de três fármacos e caixa organizadora. Não há indicação de investigação de HAS secundária, pois o caso era pseudorresistência. Reforçar controle do sal. Retorno em 6 meses com creatinina e potássio.');
