insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (3, '2020-09-14', 'controlado', 'A suposta hipertensão resistente era pseudorresistência por má adesão e erro de manguito. Com a esposa supervisionando a caixa de comprimidos, a PA caiu para a meta com três fármacos (um a menos), sem investigação adicional. Segue estável, com retornos semestrais.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (4, 'Cláudia Regina Vasconcelos', 'F', '1971-07-30', 'Campinas', 'SP', 'Professora do ensino fundamental', 'HAS há 6 anos, diagnosticada aos 44 anos, em uso de losartana 100 mg/dia e anlodipino 10 mg/dia. Cãibras frequentes e noctúria há cerca de 2 anos. Nega tabagismo e etilismo. Mãe hipertensa. Sem DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (10, 4, 1, '2022-02-14 14:00', 'consulta', 'Pressão alta apesar de dois remédios e muita cãibra', 162, 100, 72, 68.4, 'Mulher de 50 anos, hipertensa desde os 44, com PA sempre acima de 150x95 apesar de losartana 100 mg e anlodipino 10 mg com boa adesão (confirmada por retirada regular na farmácia). Queixa-se de cãibras nas panturrilhas, fraqueza e noctúria 2 a 3 vezes por noite. Sem palpitações, sudorese ou cefaleia em crises. IMC 25. Ao exame: RCR 2T BNF, sem sopros, sem edema. Exame de rotina trazido: potássio 3,2 mEq/L sem uso de diurético. HD: HAS de início jovem com hipocalemia espontânea; suspeito de hiperaldosteronismo primário.', 'Investigar: aldosterona e atividade de renina plasmática (com repetição do potássio), TC de adrenais, creatinina, ECO. Reposição de potássio oral 600 mg 8/8h por ora. Manter losartana e anlodipino, pois não interferem de forma importante na triagem se o potássio for corrigido. Retorno em 3 semanas.'),
  (11, 4, 1, '2022-03-28 14:30', 'retorno', 'Trouxe os exames hormonais', 158, 98, 70, 68.0, 'Retorna com resultados. Aldosterona plasmática 38 ng/dL com atividade de renina suprimida (0,2 ng/mL/h), relação aldosterona/renina de 190. Teste de infusão salina: aldosterona pós-infusão 14 ng/dL (não suprimiu), confirmando o diagnóstico. TC de adrenais: nódulo hipodenso de 1,8 cm na adrenal esquerda, adrenal direita normal. Em paciente de 50 anos com nódulo unilateral, foi feito cateterismo seletivo de veias adrenais, com lateralização para a esquerda (índice de lateralização 5,2). PA 158x98 mmHg.', 'Diagnóstico de hiperaldosteronismo primário por adenoma esquerdo. Indicada adrenalectomia laparoscópica esquerda; encaminhada à cirurgia. Até a cirurgia, iniciar espironolactona 50 mg/dia, manter potássio oral e checar potássio e creatinina em 1 semana. Orientada sobre risco de ginecomastia ou mastalgia.'),
  (12, 4, 3, '2022-06-09 08:00', 'internacao', 'Primeiro dia após cirurgia da adrenal', 118, 72, 78, 67.2, '1º DPO de adrenalectomia laparoscópica esquerda sem intercorrências, por adenoma. Acorda bem, dor leve controlada, aceitando dieta, deambulando. Suspensos espironolactona e potássio no dia da cirurgia. PA 118x72 mmHg com anlodipino apenas. Potássio 4,1 mEq/L no pós-operatório. Sem sinais de insuficiência adrenal. Dreno retirado, ferida operatória limpa. Creatinina 0,9 mg/dL.', 'Alta hospitalar prevista para amanhã. Manter anlodipino 5 mg e suspender losartana por ora, monitorando PA em casa. Dosar potássio e creatinina em 7 dias, pelo risco de hipercalemia pós-adrenalectomia unilateral. Retorno em 3 meses com aldosterona e renina.'),
  (13, 4, 1, '2022-09-12 15:00', 'retorno', 'Estou bem, sem cãibra', 116, 72, 68, 68.9, 'Três meses após a cirurgia. Sem cãibras, sem noctúria, mais disposta. MRPA domiciliar com média de 118x74 mmHg usando só anlodipino 5 mg. Exames: potássio 4,3 mEq/L, aldosterona 6 ng/dL, renina ativa, relação aldosterona/renina normalizada. Ao exame: BEG, RCR 2T BNF, sem sopros, sem edema. Cicatrizes cirúrgicas em bom aspecto. Anatomopatológico: adenoma cortical adrenal de 1,8 cm.', 'Cura bioquímica e pressórica. Suspender anlodipino em teste, com MRPA semanal; retomar se PA acima de 130x80. Manter MEV. Controle anual de PA, potássio e creatinina. Alta do ambulatório de endocrinologia cardiovascular.');
