insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (4, '2023-03-06', 'melhorou', 'Hiperaldosteronismo primário curado por adrenalectomia esquerda. Seis meses depois mantém PA normal sem nenhum anti-hipertensivo, potássio normal e relação aldosterona/renina normalizada. Sem cãibras ou noctúria. Segue em controle anual de PA e potássio.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (5, 'Antônio Carlos Bellini', 'M', '1949-09-14', 'Santos', 'SP', 'Estivador aposentado', 'HAS há 25 anos em uso irregular de enalapril. Tabagista de 40 maços-ano, ainda fumava 10 cigarros por dia. Dislipidemia sem tratamento. Pai falecido de infarto aos 58 anos. Sedentário.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (14, 5, 6, '2021-05-08 03:15', 'pronto_socorro', 'Dor forte no peito que não passa há duas horas', 148, 92, 96, 84.0, 'Pcte 71 anos, tabagista, chega de madrugada por SAMU com dor retroesternal em aperto, intensa, com irradiação para braço E, sudorese fria e náuseas, iniciada há 2h durante o sono. ECG: supra de ST de 3 mm de V1 a V5 com infra especular em parede inferior. Killip I, MV+ sem RA, RCR 2T BNF. Recebeu AAS 300 mg, ticagrelor 180 mg e heparina. Troponina ultrassensível 2.400 ng/L. HD: IAMCSST de parede anterior, tempo porta-balão adequado.', 'Ativada hemodinâmica. Encaminhado a cateterismo primário com ATC da lesão culpada. Mantido AAS, ticagrelor e iniciado atorvastatina 80 mg, metoprolol e enalapril em baixa dose se estável. Internação na UTI coronariana. Orientada família sobre gravidade.'),
  (15, 5, 14, '2021-05-10 10:00', 'internacao', 'Sem dor, quer ir para casa', 122, 74, 64, 83.5, 'D2 de IAMCSST anterior. CATE na admissão: oclusão trombótica da DA proximal tratada com ATC primária e stent farmacológico 3,5x28 mm, fluxo TIMI 3 final; Cx e CD com lesões não obstrutivas (40%). Estável, sem dor, sem arritmias no monitor. ECO: hipocinesia anteroapical, FEVE 42%, sem trombo. Ausculta pulmonar limpa, sem sinais de IC. Troponina em queda.', 'Alta da UTI para enfermaria e alta hospitalar em 48h. Manter dupla antiagregação por 12 meses, estatina de alta potência, metoprolol succinato 50 mg e enalapril 5 mg 12/12h. Cessação do tabagismo com orientação e reposição de nicotina. Encaminhar para reabilitação cardiovascular.'),
  (16, 5, 1, '2021-06-14 09:00', 'retorno', 'Retorno pós-infarto, sem dor', 124, 74, 62, 82.0, 'Paciente refere que não fuma há 36 dias, usando adesivo de nicotina. Faz caminhada leve de 20 minutos e iniciou a reabilitação. Sem angina, sem dispneia. Queixa-se de dispneia leve ao subir ladeira, que atribui ao ticagrelor; sem sinais de congestão. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA, sem edema, punção femoral sem hematoma. LDL 62 mg/dL. Creatinina 1,0 mg/dL, potássio 4,5 mEq/L.', 'Manter todos os medicamentos. Orientar que a dispneia pelo ticagrelor costuma ser leve e não deve levar à suspensão sem avisar. Repetir ECO em 3 meses. Reforçar cessação do fumo e reabilitação cardiovascular 3x/semana. Retorno em 90 dias.'),
  (17, 5, 1, '2022-05-23 09:30', 'retorno', 'Um ano do infarto, vim ver como estou', 118, 70, 60, 80.4, 'Completou 12 meses de dupla antiagregação. Sem dor torácica, caminha 40 minutos diariamente, abstinente de tabaco há 12 meses. Sem dispneia aos esforços habituais. ECO de controle: FEVE 50%, hipocinesia apical residual. LDL 54 mg/dL, glicemia 98 mg/dL. Ao exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, sem edema.', 'Suspender ticagrelor após 12 meses. Manter AAS 100 mg indefinidamente, atorvastatina 80 mg, metoprolol e enalapril. Continuar atividade física regular e manter abstinência do tabaco. Retorno em 6 meses.');
