insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (5, '2022-05-23', 'melhorou', 'IAMCSST anterior tratado com angioplastia primária e stent na DA. Um ano depois, assintomático, FEVE recuperada de 42% para 50%, LDL na meta, sem fumar e com atividade física regular. Dupla antiagregação concluída, segue com AAS e demais medicamentos de prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (6, 'Maria das Graças Oliveira Nunes', 'F', '1958-03-08', 'Fortaleza', 'CE', 'Costureira', 'HAS há 20 anos, DM2 há 12 anos em uso de metformina e glibenclamida, dislipidemia. Nunca fumou. Sedentária, trabalha em casa costurando por encomenda. Mãe falecida de infarto aos 66 anos.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (18, 6, 2, '2022-04-11 08:20', 'consulta', 'Aperto no peito quando subo a ladeira de casa', 146, 86, 72, 74.6, 'Mulher de 64 anos, diabética e hipertensa, com dor em aperto retroesternal aos médios esforços há 3 meses, que melhora em 5 min com repouso, piorando nas últimas semanas (agora aos pequenos esforços, 2 a 3 vezes por semana). Sem dispneia em repouso nem síncope. Ao exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA. ECG de repouso: ritmo sinusal, alterações inespecíficas da repolarização. Teste ergométrico positivo com infra de ST de 2,5 mm a 5 METs. HD: angina estável CCS III, alto risco isquêmico.', 'Iniciar AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg e nitrato SL se dor. Solicitado cateterismo diagnóstico. Manter metformina e glibenclamida; encaminhar para ajuste do diabetes com a endocrinologia. Orientada sobre sinais de alarme e retornar ao PS se dor em repouso.'),
  (19, 6, 12, '2022-06-06 07:30', 'internacao', 'Pós-operatório da cirurgia do coração', 126, 70, 82, 75.0, 'CATE: lesão de 70% no tronco da coronária esquerda, DA com 90% proximal, Cx 80% e CD ocluída com circulação colateral, SYNTAX alto, diabética; indicada RM. Realizada RM com 3 enxertos (mamária interna E para DA, safena para Cx e safena para CD), CEC de 78 min. 5º PO: extubada no D1, sem drogas vasoativas, FA paroxística no D3 revertida com amiodarona. Dor controlada, esternotomia estável, ferida sem secreção, mantém glicemia 130-180 com insulina. Ausculta pulmonar limpa. ECO: FEVE 55%.', 'Alta hospitalar amanhã. Manter AAS, atorvastatina, metoprolol e retornar à metformina; suspender glibenclamida e manter insulina NPH até avaliação da endocrinologia. Amiodarona por 30 dias. Fisioterapia respiratória e cuidados com o esterno. Retorno ambulatorial em 3 semanas.'),
  (20, 6, 1, '2022-07-25 08:40', 'retorno', 'Pós-RM, sem dor no peito', 128, 74, 66, 73.8, 'Seis semanas de pós-operatório. Sem angina, ferida esternal cicatrizada, dor leve ao tossir. Retomou pequenas tarefas de costura. Refere dificuldade em comprar os remédios porque a insulina e a atorvastatina 80 mg ''pesam no bolso''. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA, esterno estável, safenectomia sem sinais flogísticos. ECG: ritmo sinusal, FC 66 bpm.', 'Concluir amiodarona e não renovar. Fornecida via do programa de medicamentos de alto custo para estatina e solicitada assistência social. Reabilitação cardiovascular 3x por semana. Retorno em 60 dias com perfil lipídico, glicemia e HbA1c. Reforçada a importância de não interromper AAS e estatina.');
