insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (6, '2023-03-10', 'abandonou', 'Após a revascularização cirúrgica e o último retorno em julho de 2022, não compareceu às consultas de setembro e janeiro nem à reabilitação. Contato telefônico sem sucesso. Segundo a vizinha, suspendeu os remédios por falta de dinheiro. Perdeu seguimento sem reavaliação do enxerto, lipídios ou diabetes.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (7, 'Iracema Tupinambá Costa', 'F', '1967-06-21', 'Manaus', 'AM', 'Feirante', 'HAS há 20 anos, com controle irregular. Cardiopatia hipertensiva com ICFEr diagnosticada há 1 ano, em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Obesidade. Consumo elevado de peixe salgado e embutidos. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (21, 7, 11, '2023-02-13 08:00', 'consulta', 'Falta de ar para subir a escada da feira', 146, 90, 84, 91.0, 'Pcte de 55 anos, ICFEr de etiologia hipertensiva, NYHA III, com dispneia aos médios esforços, edema vespertino de MMII e ortopneia de 2 travesseiros. Adere ao enalapril e carvedilol, mas come muito sal. Ao exame: ingurgitamento jugular a 45°, RCR 2T BNF com B3, estertores em bases, edema 2+/4+. PA 146x90 mmHg. NT-proBNP 2.900 pg/mL. ECO: FEVE 32% (Simpson), dilatação de VE, insuficiência mitral funcional leve. Creatinina 1,0 mg/dL, K 4,4 mEq/L. HD: ICFEr NYHA III, não otimizada.', 'Suspender enalapril, aguardar 36h e iniciar sacubitril/valsartana 24/26 mg 12/12h. Associar dapagliflozina 10 mg e espironolactona 25 mg/dia. Carvedilol 6,25 mg 12/12h mantido. Ajustar furosemida para 40 mg. Dieta com menos de 2 g de sódio e pesagem diária. Dosar K e creatinina em 1 semana. Retorno em 30 dias.'),
  (22, 7, 11, '2023-06-05 08:20', 'retorno', 'Melhorei muito, consigo trabalhar o dia todo', 108, 68, 66, 83.2, 'Retorna 4 meses depois, bem melhor: NYHA II, sem ortopneia, sem edema. Perdeu 7,8 kg, a maior parte líquido. Ficou tonta nas primeiras semanas, sem síncope. Ao exame: sem estase jugular, B3 ausente, pulmões limpos, sem edema. PA 108x68 mmHg. K 4,9 mEq/L, creatinina 1,1 mg/dL. NT-proBNP caiu para 780 pg/mL. Queixa-se do custo mensal do sacubitril/valsartana, que ''não cabe no orçamento da feira''. Tem receita do programa estadual em trâmite.', 'Aumentar sacubitril/valsartana para 49/51 mg 12/12h. Manter demais fármacos. Solicitado processo de dispensação pelo programa de medicamentos especializados e orientada a não interromper a medicação em caso de falta, avisando antes ao serviço. ECO em 6 meses. Retorno em 90 dias.'),
  (23, 7, 6, '2024-01-15 02:40', 'pronto_socorro', 'Acordei sufocada, sem conseguir deitar', 178, 104, 112, 90.6, 'Pcte com ICFEr, trazida pelo filho com dispneia intensa, tosse com expectoração rosada e ortopneia há 3h. Relata que o sacubitril/valsartana acabou há 3 semanas, não conseguiu comprar nem retirar no programa e voltou a tomar enalapril antigo ''que sobrava'' de forma irregular. Fim de ano com comida salgada. Ao exame: taquipneica, SpO2 86% em ar ambiente, estertores até ápices, B3, edema 3+/4+. Peso 90,6 kg (+7 kg). HD: EAP hipertensivo por descompensação de ICFEr secundária a abandono de medicação.', 'O2 suplementar, ventilação não invasiva, furosemida 80 mg EV, nitroglicerina EV para controle pressórico. Ingresso em UTI para monitorização. Retomar sacubitril/valsartana após 36 horas sem IECA e adesão ao programa de dispensação. Contato com assistência social do hospital.');
