insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (7, '2024-03-12', 'piorou', 'Evoluiu bem com sacubitril/valsartana, mas a dificuldade financeira levou à interrupção do fármaco e a edema agudo de pulmão. Após a internação, FEVE 28% e classe funcional III. Aguarda aprovação definitiva no programa de medicamentos especializados e segue em risco de nova descompensação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (8, 'Ernesto Kramer', 'M', '1944-12-01', 'Americana', 'SP', 'Aposentado (ex-tecelão)', 'HAS há 30 anos controlada com losartana 50 mg 12/12h. Lombalgia crônica, fez uso frequente de ibuprofeno. Ex-tabagista, parou há 25 anos. Mora com a esposa. Sem DM2. Sem diagnóstico prévio de arritmia.', 'Alergia a penicilina (rash cutâneo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (24, 8, 4, '2023-03-20 09:30', 'consulta', 'Coração batendo irregular e cansaço', 138, 82, 104, 74.0, 'Homem de 78 anos com palpitações irregulares e cansaço aos esforços há 2 meses. ECG: fibrilação atrial com resposta ventricular média de 104 bpm, sem sinais de isquemia. ECO: átrio esquerdo 48 mm, FEVE 58%, sem valvopatia importante. TSH normal. Creatinina 1,2 mg/dL (ClCr de Cockcroft-Gault 53 mL/min). CHA2DS2-VASc 3 (idade ≥ 75 anos = 2, HAS = 1). HAS-BLED 2 (idade, uso de AINE). FA permanente provável, assintomático em repouso. Ao exame: RCR irregular, sem sopros, sem edema.', 'Estratégia de controle de frequência com metoprolol succinato 50 mg/dia. Iniciar anticoagulação com rivaroxabana 20 mg com a refeição principal. Suspender ibuprofeno e outros AINE definitivamente; orientar paracetamol para a coluna. Retorno em 60 dias com Holter.'),
  (25, 8, 6, '2023-11-26 05:50', 'pronto_socorro', 'Fezes pretas e tontura', 104, 62, 98, 73.5, 'Pcte 78 anos em uso de rivaroxabana, chega com melena há 2 dias, tontura ao levantar e palidez. Admite ter voltado a tomar ibuprofeno 600 mg por dor lombar nas últimas 2 semanas: ''a dor da coluna não passava com o outro''. Sem hematêmese. Ao exame: descorado 2+/4+, hipotenso postural, RCR irregular, abdome indolor, toque retal com melena. Hb 8,9 g/dL (basal 13,5), ureia elevada, creatinina 1,3 mg/dL. HD: hemorragia digestiva alta por provável úlcera péptica associada a AINE e anticoagulante.', 'Internação. Suspensa rivaroxabana. Inibidor de bomba EV 80 mg em bolus, hidratação, 2 concentrados de hemácias. EDA em 24h. Avaliação cardiológica sobre reintrodução da anticoagulação após hemostasia e orientação rigorosa de evitar AINE.'),
  (26, 8, 4, '2024-02-19 10:00', 'retorno', 'Voltei para decidir sobre o anticoagulante', 134, 80, 76, 75.2, 'Alta hospitalar após 5 dias, sem recidiva do sangramento, Hb de saída 10,4 g/dL. Hoje sem melena, com Hb 12,8 g/dL. Úlcera gástrica por AINE tratada com pantoprazol 40 mg 12/12h por 8 semanas; EDA de controle com cicatrização. Controla a dor lombar com paracetamol e fisioterapia. FA permanente, FC 76 bpm com metoprolol. Ao exame: RCR irregular, sem sopros, sem edema. CHA2DS2-VASc 3 e fator de risco do sangramento (AINE) removido.', 'Retomar anticoagulação com rivaroxabana 20 mg, mantendo pantoprazol 40 mg/dia. Compartilhada decisão com paciente e esposa: benefício do AVC superior ao risco, com a causa do sangramento corrigida. Entregue lista escrita dos medicamentos proibidos (ibuprofeno, diclofenaco, AAS por conta própria). Hemograma em 30 dias e retorno em 90.');
