insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (8, '2024-02-19', 'estavel', 'FA permanente com frequência controlada e anticoagulação retomada após hemorragia digestiva por úlcera associada a AINE. Úlcera cicatrizada, hemoglobina recuperada e paciente orientado a evitar anti-inflamatórios. Segue em acompanhamento trimestral, com hemograma e função renal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (9, 'Giuseppe Fabrizio Moretti', 'M', '1941-04-17', 'São Paulo', 'SP', 'Aposentado (ex-alfaiate)', 'HAS há 35 anos e dislipidemia, em uso de anlodipino 5 mg e sinvastatina 20 mg. Sopro cardíaco conhecido há 10 anos sem acompanhamento regular. Mora sozinho no Bixiga, filhos na Itália. Ex-fumante, parou há 20 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (27, 9, 1, '2022-09-05 10:00', 'consulta', 'Quase desmaiei subindo a escada do prédio', 132, 70, 72, 68.0, 'Homem de 81 anos com dispneia e aperto no peito aos pequenos esforços há 6 meses e episódio de pré-síncope ao subir escada há duas semanas. Nega síncope franca. Ao exame: BEG, pulsos carotídeos de ascensão lenta, sopro sistólico ejetivo 4+/6+ em foco aórtico com irradiação para carótidas e B2 hipofonética, MV+ sem RA, sem edema. ECO: estenose aórtica grave calcificada (Vmax 4,6 m/s, gradiente médio 52 mmHg, área valvar 0,7 cm²), FEVE 58%, HVE moderada. HD: estenose aórtica grave sintomática (angina, dispneia e pré-síncope).', 'Indicação de intervenção valvar. Solicitar cateterismo e angiotomografia de aorta e acessos para avaliação de TAVI. Manter anlodipino 5 mg por ora, evitar vasodilatadores potentes e diuréticos. Orientado a evitar esforços até a intervenção. Encaminhado ao Heart Team.'),
  (28, 9, 10, '2022-11-14 14:30', 'retorno', 'Vim para saber qual cirurgia vão fazer', 128, 68, 70, 67.2, 'Retorna com cateterismo: coronárias sem lesões significativas (DA 30%). Angiotomografia: anel aórtico 23 mm, calcificação importante dos folhetos, acessos ilíacos e femorais adequados para via transfemoral. Escore STS 6,8%, fragilidade moderada e vive sozinho. Heart Team (cardiologia clínica, intervencionista e cirurgia cardíaca) indica TAVI transfemoral em vez de troca valvar cirúrgica. O paciente aceita: ''quero voltar a caminhar até a padaria''.', 'TAVI agendada para janeiro. Avaliação odontológica prévia e controle de foco infeccioso. Manter AAS, estatina e anlodipino. Orientadas filhas a organizar acompanhante no pós-procedimento e assistência social para cuidador nos primeiros dias.'),
  (29, 9, 10, '2023-01-17 08:30', 'internacao', 'Pós-TAVI, sem queixas', 124, 64, 68, 67.0, 'D1 de TAVI transfemoral com prótese autoexpansível 26 mm, sob sedação, sem intercorrências. Gradiente médio pós-implante 8 mmHg, sem regurgitação paravalvar relevante. Acessos femorais sem hematoma. ECG pós: ritmo sinusal com bloqueio de ramo esquerdo novo (QRS 138 ms), PR 190 ms. Monitorizado sem BAV. Deambulando, sem dor, dieta oral. Hb 12,1 g/dL, creatinina 1,0 mg/dL.', 'Observar monitorização por 48h pelo risco de BAV tardio. Se estável, alta no D3. Clopidogrel 75 mg por 3 meses e AAS 100 mg. Manter estatina. Reduzir anlodipino para 2,5 mg se PA < 110. Retorno ambulatorial em 30 dias com ECG e ECO.'),
  (30, 9, 1, '2023-05-08 10:30', 'retorno', 'Estou caminhando até a padaria', 126, 66, 66, 69.4, 'Quatro meses após TAVI. Caminha 1 km por dia, sem dispneia, sem angina e sem pré-síncope. Voltou a cozinhar e a fazer pequenos consertos de costura. Ao exame: RCR 2T BNF, discreto sopro sistólico ejetivo suave 2+/6+, sem sinais de IC. ECG: ritmo sinusal, BRE estável, sem BAV. ECO: prótese normofuncionante, gradiente médio 9 mmHg, sem leak, FEVE 60%, HVE em regressão.', 'Concluído clopidogrel; manter AAS 100 mg indefinidamente, sinvastatina 20 mg e anlodipino 5 mg. Profilaxia antibiótica para procedimentos dentários invasivos. Seguimento anual com ECO. Retorno em 6 meses.');
