insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (9, '2023-05-08', 'melhorou', 'Estenose aórtica grave tratada com TAVI transfemoral em paciente de alto risco cirúrgico. Quatro meses depois está assintomático, caminhando 1 km por dia, com prótese normofuncionante e gradiente médio de 9 mmHg. Segue em acompanhamento anual com ecocardiograma.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (10, 'Raimundo Nonato Barbosa', 'M', '1964-08-09', 'São José do Rio Preto', 'SP', 'Pedreiro (ex-lavrador)', 'Nasceu em zona rural do Piauí, morou em casa de taipa na infância, onde teve contato com barbeiro. Doença de Chagas diagnosticada há 8 anos (sorologia reagente), sem tratamento específico. Etilismo social. Nega tabagismo. HAS leve, sem medicação regular.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (31, 10, 4, '2021-03-02 09:00', 'consulta', 'Palpitação forte e quase desmaiei no serviço', 130, 84, 58, 77.0, 'Homem de 56 anos com Chagas crônica, queixa-se de palpitações, tontura e cansaço aos médios esforços há 4 meses, com episódio de pré-síncope na obra. Ao exame: RCR irregular por extrassístoles, B3, sem sopros, MV+ sem RA, sem edema. ECG: BRD + HBAE, extrassístoles ventriculares frequentes. Holter: 14.000 ESV/24h e 3 episódios de TV não sustentada. ECO: FEVE 36%, dilatação de VE, aneurisma apical. HD: cardiopatia chagásica crônica com disfunção ventricular e arritmia ventricular complexa.', 'Não indicado tratamento antiparasitário na fase crônica com cardiopatia estabelecida. Iniciar amiodarona 200 mg/dia, bisoprolol 2,5 mg, enalapril 5 mg 12/12h, espironolactona 25 mg. Orientado a evitar bebida alcoólica e esforço intenso na obra. Retorno em 30 dias com TSH, K e Mg.'),
  (32, 10, 4, '2021-07-12 07:30', 'internacao', 'Internado para colocar o aparelho no coração', 118, 74, 54, 76.4, 'Três semanas antes, TV sustentada monomórfica de 20 minutos tratada com cardioversão elétrica no PS de outro serviço, sem choque prévio. Chagas com FEVE 34%, aneurisma apical e TV sustentada recorrente, em uso de amiodarona e bisoprolol. Implantado CDI unicameral (prevenção secundária) sem intercorrências, limiares adequados. Raio X pós sem pneumotórax. Hoje D1, curativo limpo, sem dor, ritmo sinusal de base com FC 54 bpm.', 'Alta amanhã após interrogação do dispositivo. Manter amiodarona, bisoprolol, enalapril e espironolactona. Orientações sobre CDI: evitar fontes magnéticas, não dirigir por 6 meses, procurar o PS se choque único com sintomas ou mais de um choque. Seguimento do CDI em 30 dias e a cada 6 meses.'),
  (33, 10, 6, '2023-10-09 00:50', 'pronto_socorro', 'O aparelho deu três choques seguidos', 92, 58, 118, 79.5, 'Pcte com cardiopatia chagásica e CDI, chega de madrugada pela esposa após 3 choques apropriados do CDI em 1 hora, com palpitações e muita falta de ar. Há 3 semanas com piora da dispneia, ortopneia, edema de MMII e ganho de 3 kg. Parou amiodarona há 2 meses por conta própria porque o médico da UBS comentou sobre risco para a tireoide. Ao exame: pálido, sudoreico, estertores até 2/3 dos campos, B3, edema 3+/4+, PA 92x58 mmHg. Interrogação: TV sustentada com 3 terapias de choque eficazes. HD: tempestade arrítmica em Chagas com IC descompensada.', 'Internação em UTI. Reintroduzir amiodarona EV, furosemida EV, correção de K e Mg, suporte com dobutamina. Evitar bloqueadores neuro-hormonais por ora pela hipotensão. Equipe de arritmia avaliará ablação de TV e reprogramação do CDI. Orientados paciente e esposa quanto ao prognóstico reservado.');
