insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (10, '2024-02-11', 'obito', 'Após tempestade arrítmica, manteve-se em IC avançada com FEVE 22%, internações repetidas e intolerância a bloqueadores neuro-hormonais por hipotensão. Foi considerado para transplante, mas não era elegível. Faleceu em fevereiro de 2024 por choque cardiogênico refratário, internado, com a família presente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (11, 'Fábio Henrique Rezende', 'M', '1976-10-19', 'Uberlândia', 'MG', 'Vendedor de loja de material de construção', 'HAS há 8 anos. Há 3 anos iniciou metoprolol 100 mg/dia por outro médico, mas suspendeu por conta própria há 4 meses por disfunção erétil. Dislipidemia. Fuma 8 cigarros por dia há 20 anos. Etilismo aos fins de semana (cerveja). Mãe com AVC aos 68 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (34, 11, 2, '2022-09-12 16:00', 'consulta', 'Parei o remédio da pressão porque brochava', 174, 108, 88, 92.5, 'Homem de 45 anos, hipertenso, sem tratamento há 4 meses. Parou o metoprolol por disfunção erétil: ''estava me sentindo menos homem, doutor'', e não contou ao médico. Cefaleia pulsátil ocasional, sem dor torácica, dispneia, alteração visual ou neurológica. Fuma e bebe nos fins de semana. Ao exame: obeso (IMC 29,9), RCR 2T BNF, sem sopros, MV+ sem RA, pulsos femorais presentes, sem edema. Fundo de olho com cruzamento arteriovenoso patológico. PA 174x108 mmHg (duas medidas). Creatinina 1,0 mg/dL, potássio 4,2 mEq/L, LDL 158 mg/dL. HD: HAS estágio 2, descontrolada por abandono do betabloqueador por efeito colateral.', 'Betabloqueador retirado do esquema: não é primeira linha em hipertenso sem cardiopatia. Iniciada combinação em comprimido único de olmesartana 20 mg com anlodipino 5 mg uma vez ao dia, para facilitar a adesão. Solicitados ECG, ECO e microalbuminúria. Orientado sobre cessação do tabagismo. Retorno em 30 dias.'),
  (35, 11, 2, '2022-10-24 16:30', 'retorno', 'Estou me sentindo melhor, a dor de cabeça sumiu', 142, 88, 76, 91.8, 'Retorna 6 semanas depois. Toma o comprimido todo dia de manhã, sem esquecer. Relata que a função sexual melhorou de forma espontânea desde que o betabloqueador foi retirado. Ausência de edema de tornozelos. Fumando 4 cigarros por dia. ECG: ritmo sinusal, SVE por Sokolow-Lyon. ECO: HVE leve, FEVE 64%. Microalbuminúria 18 mg/g (normal). PA 142x88 mmHg, ainda acima da meta.', 'Aumentar olmesartana/anlodipino para 40 mg + 5 mg. Iniciar rosuvastatina 10 mg pelo LDL de 158 mg/dL e perfil de risco. Reforçar cessação do fumo (vareniclina oferecida, mas ele prefere tentar sozinho). Retorno em 45 dias com creatinina e potássio.'),
  (36, 11, 2, '2023-03-13 17:00', 'retorno', 'Vim mostrar a pressão de casa', 124, 78, 72, 89.0, 'Seguimento em 5 meses, em uso regular da combinação em dose fixa e da rosuvastatina. Sem edema, sem cefaleia, função sexual preservada. Parou de fumar há 2 meses com apoio da esposa, mas bebe mais nos fins de semana. Perdeu 3,5 kg. MRPA com média de 126x78 mmHg. Creatinina 1,0 mg/dL, potássio 4,3 mEq/L, LDL 82 mg/dL. Ao exame: RCR 2T BNF, sem sopros.', 'Meta pressórica atingida. Manter olmesartana/anlodipino 40/5 mg e rosuvastatina 10 mg. Orientado sobre limitar álcool a uma dose por dia e continuar abstinente do cigarro. Retorno em 6 meses.');
