insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (12, '2023-02-06', 'estavel', 'Hipotensão ortostática com queda e fratura de punho resolvida após desprescrição de atenolol e hidroclorotiazida. Mantém PA sistólica em torno de 140 mmHg, aceita para o perfil frágil, sem novas quedas, e segue com tratamento da osteoporose e fisioterapia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (13, 'Edivaldo Santana Reis', 'M', '1969-12-14', 'Guarulhos', 'SP', 'Vigilante noturno', 'HAS há 10 anos. Usava losartana 50 mg 12/12h e hidroclorotiazida 25 mg, mas parou há 3 meses ao ser demitido e perder o plano de saúde. Sedentário, trabalha em turno noturno. Etilismo moderado. Nega diabetes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (40, 13, 6, '2024-02-03 06:20', 'pronto_socorro', 'Dor de cabeça forte e a pressão não baixa', 214, 124, 86, 88.0, 'Pcte 54 anos, sem medicação há 3 meses, chega ao fim do plantão com cefaleia occipital, PA 214x124 mmHg em duas medidas. Nega dor torácica, dispneia, déficit neurológico, alteração visual, vômitos ou confusão. Ao exame: BEG, lúcido, RCR 2T BNF, B4, sem sopros, MV+ sem RA, sem edema, neurológico sem alterações, fundo de olho sem papiledema ou hemorragia. ECG: SVE sem isquemia aguda. Troponina negativa, creatinina 1,1 mg/dL, urina sem hematúria. HD: urgência hipertensiva (HAS grave sem lesão aguda de órgão-alvo) por abandono do tratamento.', 'Sem indicação de medicação EV ou internação. Reintroduzir losartana 50 mg 12/12h, anlodipino 5 mg/dia e captopril 25 mg VO uma vez no PS, com observação por 2h (PA 188x110). Redução gradual da PA em 24 a 48h, não imediata. Orientada importância de não parar medicamento. Retorno ambulatorial em 7 dias.'),
  (41, 13, 1, '2024-02-10 09:30', 'retorno', 'Retorno do pronto-socorro', 158, 98, 80, 87.6, 'Uma semana após a urgência hipertensiva, tomando losartana e anlodipino todos os dias. Cefaleia resolvida. Sem sintomas neurológicos nem dispneia. Não tem mais plano de saúde, retirou remédios pelo posto de saúde. Come marmitex, usa muito sal e bebe 4 cervejas por semana. Ao exame: PA 158x98 mmHg, RCR 2T BNF, sem sopros, MV+ sem RA, sem edema. ECO: HVE leve, FEVE 62%. Creatinina 1,0 mg/dL, K 4,2 mEq/L, albuminúria 24 mg/g.', 'Manter losartana e anlodipino, acrescentar clortalidona 12,5 mg pela manhã. Cadastrado na UBS do bairro para acompanhamento e farmácia popular. Orientações sobre sal e álcool. MRPA em 4 semanas. Retorno em 45 dias com creatinina e potássio.'),
  (42, 13, 1, '2024-04-02 10:00', 'retorno', 'Estou conseguindo tomar direitinho', 136, 84, 74, 86.0, 'Melhora importante. Aderente aos três fármacos, com MRPA de 134x82 mmHg. Conseguiu trabalho como vigilante diurno em um condomínio e dorme melhor. Sem cefaleia. Ao exame: PA 136x84 mmHg, sem edema. Sódio 138 mEq/L, potássio 3,9 mEq/L, creatinina 1,1 mg/dL.', 'Manter esquema atual. Está perto da meta (< 130/80), reforçada redução do sal e atividade física. Considerar ajuste de dose da losartana para 100 mg/dia se MRPA persistir acima da meta. Retorno em 60 dias.');
