insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (13, '2024-08-15', 'abandonou', 'Após controle quase na meta em abril de 2024, não compareceu à consulta de junho nem aos retornos seguintes. Duas ligações sem resposta. Pela UBS, parou de retirar os medicamentos desde julho. Perdeu seguimento com risco de nova crise hipertensiva.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (14, 'Thamires Silva Lacerda', 'F', '1996-08-30', 'Osasco', 'SP', 'Operadora de caixa', 'Primigesta, gestação de 34 semanas e 2 dias, pré-natal regular com 7 consultas. Sem hipertensão prévia. IMC pré-gestacional 29. Mãe teve pré-eclâmpsia na segunda gravidez. Nega diabetes gestacional.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (43, 14, 7, '2024-09-09 14:00', 'consulta', 'A pressão subiu no pré-natal e meus pés incharam', 148, 96, 88, 82.4, 'Gestante de 28 anos, 34 semanas e 2 dias, com PA 148x96 mmHg em duas medidas no pré-natal da UBS, edema de pés e ganho de 2 kg em duas semanas. Nega cefaleia, escotomas, epigastralgia ou dor em hipocôndrio direito. Movimentos fetais presentes. Ao exame: AU 33 cm, BCF 142 bpm, edema 2+/4+, reflexos normais, sem clônus. Proteinúria de fita 1+; relação proteína/creatinina urinária 0,42 mg/mg. Plaquetas 215.000, creatinina 0,7 mg/dL, TGO 22 U/L. HD: pré-eclâmpsia sem sinais de gravidade.', 'Iniciar nifedipino retard 20 mg 12/12h. Não usar IECA ou BRA na gestação. Cardiotocografia e perfil biofísico fetal, USG com Doppler. Orientadas sinais de alarme: cefaleia intensa, visão turva, dor no estômago, sangramento. PA domiciliar 2x/dia. Retorno em 14 dias, antes se alarme.'),
  (44, 14, 7, '2024-09-23 14:20', 'retorno', 'Pressão em casa em torno de 140 por 90', 140, 90, 84, 83.1, 'Gestante de 36 semanas e 2 dias, assintomática, sem cefaleia ou sinais de alarme. PA domiciliar entre 134x86 e 144x92 mmHg com nifedipino. Edema estável. Movimentos fetais presentes. USG: peso fetal estimado 2.850 g (P50), líquido normal, Doppler de artérias umbilicais normal. Exames de laboratório: plaquetas 198.000, creatinina 0,8 mg/dL, TGO/TGP normais, ácido úrico 5,8 mg/dL, proteína/creatinina 0,55 mg/mg. Ao exame: AU 35 cm, BCF 140 bpm, reflexos normais.', 'Mantida pré-eclâmpsia sem gravidade; manter nifedipino retard 20 mg 12/12h. Indicada resolução com 37 semanas completas, por indução do trabalho de parto, caso mantenha estabilidade. Internação eletiva em 2 semanas ou antes se sinais de gravidade. Repetir exames em 7 dias.'),
  (45, 14, 7, '2024-10-08 07:30', 'internacao', 'Internação para parto, 38 semanas', 144, 92, 80, 83.8, '38 semanas e 3 dias, internada para indução do trabalho de parto por pré-eclâmpsia sem gravidade. PA 144x92 mmHg, assintomática. Colo com 2 cm, 60% apagado. Feito misoprostol vaginal e, após 14h, ocitocina. Evoluiu com parto vaginal sem intercorrências às 22h, RN do sexo masculino, 3.120 g, Apgar 9/10. Sulfato de magnésio não necessário, sem sinais de gravidade; PA 138x88 mmHg no pós-parto imediato. Laboratório pós: plaquetas 190.000, TGO normal.', 'Alta hospitalar em 48h. Aleitamento materno. Controle de PA domiciliar 2x/dia por 2 semanas. Retorno em 7 dias para reavaliação da PA e das medicações no puerpério. Orientada sobre risco cardiovascular futuro após pré-eclâmpsia.'),
  (46, 14, 1, '2024-11-26 09:00', 'retorno', 'Retorno do parto, quero saber se vou ficar hipertensa', 122, 76, 74, 76.5, 'Puerpério de 7 semanas, amamentando. Ainda usou nifedipino retard por 3 semanas, com PA normal em casa desde o 20º dia; suspendeu por conta e manteve PA domiciliar média de 118x74 mmHg. Sem cefaleia ou edema. Perdeu 7 kg. Exames: creatinina 0,7 mg/dL, proteinúria ausente na urina tipo 1, glicemia 88 mg/dL, LDL 112 mg/dL. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA.', 'Pré-eclâmpsia resolvida, sem necessidade de anti-hipertensivo. Orientada sobre aumento do risco de HAS e doença cardiovascular na vida: manter peso, atividade física e checar PA anualmente. Considerar AAS em baixa dose em futura gestação a partir da 12ª semana. Contracepção sem estrogênio.');
