insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (14, '2024-11-26', 'melhorou', 'Pré-eclâmpsia sem sinais de gravidade, tratada com nifedipino e parto vaginal induzido às 38 semanas, com recém-nascido saudável. PA normalizou no puerpério, sem necessidade de tratamento contínuo. Orientada a manter vigilância anual da pressão pelo risco aumentado de hipertensão futura.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (15, 'Abdul Karim Haddad', 'M', '1960-03-05', 'Mogi das Cruzes', 'SP', 'Comerciante (loja de tecidos)', 'HAS há 15 anos e DM2 há 6 anos, em uso de losartana 50 mg 12/12h e metformina 850 mg 12/12h. Dislipidemia sem estatina. Tabagista de 25 maços-ano. Irmão com infarto aos 55 anos. Sedentário.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (47, 15, 6, '2021-11-14 22:30', 'pronto_socorro', 'Dor no peito que vai e volta desde a tarde', 152, 92, 88, 86.0, 'Pcte 61 anos, diabético e tabagista, com dor precordial em aperto desde a tarde, em crises de 15 a 20 min, a última em repouso e há 40 min, irradiada para o ombro E. Mantém desconforto leve. Ao exame: sudoreico, RCR 2T BNF, MV+ sem RA, sem edema. ECG: infradesnivelamento de ST de 1,5 mm em V4-V6 e T negativa em DI, aVL. Troponina ultrassensível 180 ng/L (corte 14) com delta ascendente em 3h (410 ng/L). HD: SCA sem supra de ST (IAMSSST), GRACE 128.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, nitroglicerina EV por dor e metoprolol. Internação na unidade coronariana e cateterismo nas próximas 24h (estratégia invasiva precoce). Controle glicêmico com insulina regular. Jejum.'),
  (48, 15, 10, '2021-11-16 09:00', 'internacao', 'Pós-cateterismo, sem dor', 130, 78, 64, 85.5, 'D2 de IAMSSST. CATE via radial D: lesão de 90% em circunflexa média (culpada), DA com lesão de 50% não crítica, CD sem lesões significativas. Realizada ATC com stent farmacológico 3,0x22 mm na Cx, com sucesso, TIMI 3 final. Sem dor desde o procedimento. Pico de troponina 1.900 ng/L. ECO: FEVE 52%, hipocinesia de parede lateral. Sem arritmias. Radial sem hematoma. Creatinina 1,0 mg/dL.', 'Alta hospitalar em 24h. Dupla antiagregação com AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses. Manter atorvastatina 80 mg, metoprolol e losartana. Adicionar empagliflozina 10 mg pelo diabetes e doença coronária. Tabagismo: interrompido na internação, oferecer terapia de reposição. Reabilitação cardiovascular.'),
  (49, 15, 1, '2022-01-17 15:00', 'retorno', 'Voltei para o retorno do infarto', 122, 74, 62, 83.0, 'Dois meses após IAMSSST com stent na Cx. Parou de fumar na internação e está sem cigarro há 9 semanas, ''foi o susto que resolveu''. Faz caminhada de 30 min e frequenta a reabilitação. Sem angina. Ao exame: RCR 2T BNF, sem sopros, sem edema. LDL 58 mg/dL, HbA1c 6,9%, creatinina 1,0 mg/dL, potássio 4,4 mEq/L.', 'Manter dupla antiagregação até novembro de 2022, estatina de alta potência, betabloqueador, losartana, empagliflozina e metformina. Meta de LDL < 50 mg/dL; reavaliar em 3 meses. Reforçar controle do tabagismo. Retorno em 90 dias.');
