insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (15, '2022-01-17', 'controlado', 'IAMSSST tratado com angioplastia e stent na circunflexa. Dois meses depois está sem angina, sem fumar, com LDL de 58 mg/dL, HbA1c de 6,9% e PA na meta. Completa dupla antiagregação até novembro de 2022 e segue em reabilitação cardiovascular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (16, 'Neusa Maria Kowalski', 'F', '1948-07-12', 'Curitiba', 'PR', 'Aposentada (ex-secretária)', 'HAS há 30 anos, obesidade, DM2 há 10 anos em uso de metformina. Insuficiência cardíaca com fração de ejeção preservada diagnosticada há 1 ano, usando losartana 50 mg 12/12h e furosemida 40 mg. Apneia do sono não investigada. Descendente de poloneses, família grande.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (50, 16, 11, '2023-05-08 09:00', 'consulta', 'Cansaço para andar até o mercado e pés inchados', 152, 84, 78, 94.5, 'Mulher de 74 anos com ICFEp, NYHA II-III. Dispneia aos médios esforços, edema de tornozelos e ortopneia leve. Come muito sal e cozinha para a família. Ao exame: obesa (IMC 37), turgência jugular a 30°, RCR 2T BNF, sopro sistólico 2+/6+ em foco mitral, estertores em bases, edema 2+/4+. PA 152x84 mmHg. ECO: FEVE 60%, HVE concêntrica, disfunção diastólica grau II, átrio esquerdo aumentado (volume indexado 44 mL/m²), PSAP 46 mmHg. NT-proBNP 1.450 pg/mL. TFGe 58. HD: ICFEp descompensada leve, hipertensão e obesidade.', 'Associar dapagliflozina 10 mg/dia e espironolactona 25 mg/dia (K 4,5, TFGe 58). Ajustar furosemida para 40 mg 12/12h por 7 dias e depois 40 mg/dia. Peso diário; dieta com menos de 2 g de sódio. Polissonografia para apneia. K e creatinina em 1 semana. Retorno em 45 dias.'),
  (51, 16, 11, '2023-07-17 09:20', 'retorno', 'Muito melhor, já faço o mercado sem parar', 132, 78, 70, 88.2, 'Perdeu 6,3 kg desde a consulta. Sem ortopneia nem edema; NYHA II. Faz caminhadas leves com a vizinha. Teve duas infecções urinárias leves tratadas na UBS, o que a preocupa com a dapagliflozina; nega glicosúria genital recorrente. Polissonografia: IAH 28/h (apneia moderada), dessaturação mínima 82%. Ao exame: sem estase jugular, estertores ausentes, sem edema. K 4,8 mEq/L, creatinina 1,2 mg/dL (TFGe 52).', 'Manter dapagliflozina com reforço de higiene íntima e hidratação. Encaminhar à pneumologia do sono para CPAP. Manter espironolactona 25 mg/dia e furosemida 40 mg pela manhã. Checar K em 1 mês. Retorno em 6 meses.'),
  (52, 16, 11, '2024-01-22 09:40', 'retorno', 'Retorno semestral', 128, 72, 68, 84.0, 'Adaptou-se ao CPAP (uso médio de 5,5 h por noite), menos sonolência diurna. Perdeu mais 4 kg com reeducação alimentar e caminhadas. NYHA I-II, sem hospitalizações no semestre. Ao exame: PA 128x72 mmHg, RCR 2T BNF, sopro mitral 2+/6+ inalterado, sem estertores, sem edema. NT-proBNP 520 pg/mL, K 4,7 mEq/L, creatinina 1,1 mg/dL, HbA1c 6,8%.', 'Manter dapagliflozina, espironolactona, losartana e furosemida. Considerar reduzir diurético se continuar perdendo peso. ECO anual. Vacinas de influenza e pneumococo em dia. Retorno em 6 meses.');
