insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (16, '2024-01-22', 'melhorou', 'ICFEp associada a obesidade e apneia do sono, tratada com dapagliflozina, espironolactona, CPAP e perda de 10 kg. Passou de NYHA III para I-II, NT-proBNP caiu de 1.450 para 520 pg/mL e não teve novas internações. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (17, 'Yoshiko Tanabe Hara', 'F', '1952-09-03', 'Bastos', 'SP', 'Avicultora aposentada', 'HAS há 18 anos em uso de losartana 50 mg 12/12h. Hipotireoidismo tratado. Nunca fumou. Irmã sofreu hemorragia digestiva grave com anticoagulante, o que a deixou com muito medo desse tipo de remédio. Mora em sítio com o marido.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (53, 17, 4, '2022-03-14 10:30', 'consulta', 'Coração dispara de vez em quando', 144, 86, 92, 63.0, 'Mulher de 69 anos com crises de palpitação irregular há 6 meses, que duram de 2 a 6 horas e cessam sozinhas. Holter 24h: FA paroxística com duração de 3h40, FC média 118 bpm no episódio, sem pausas. ECG em ritmo sinusal. ECO: átrio esquerdo 42 mm, FEVE 62%, sem valvopatia. TSH 2,4 mUI/L. CHA2DS2-VASc 3 (idade 65-74 anos, sexo feminino, HAS). Orientada sobre risco de AVC; paciente recusa anticoagulante: ''minha irmã quase morreu sangrando''. Ao exame: RCR 2T BNF, sem sopros.', 'Indicada anticoagulação com apixabana 5 mg 12/12h; paciente declina após longa conversa, aceita pensar. Mantido AAS 100 mg (esclarecido que é proteção insuficiente) e iniciado metoprolol succinato 25 mg/dia para controle de frequência. Reavaliar decisão em 30 dias; trazer a filha à consulta.'),
  (54, 17, 6, '2022-08-21 05:10', 'pronto_socorro', 'Boca torta e braço direito sem força', 168, 94, 112, 62.0, 'Pcte 69 anos, chega por SAMU com afasia, desvio de rima labial à D e hemiparesia direita (força grau 2) com início há 1h30 (acordou sem fala). Não retornou às consultas, nunca aceitou o anticoagulante. ECG: FA com resposta ventricular de 112 bpm. NIHSS 14. TC de crânio sem sangramento, ASPECTS 9. Glicemia 118 mg/dL. HD: AVC isquêmico cardioembólico por FA não anticoagulada, na janela terapêutica.', 'Código AVC: trombólise com alteplase iniciada em 2h40 do início dos sintomas (sem contraindicações) e angiotomografia de crânio e pescoço com oclusão de M1 E, indicando trombectomia mecânica. Transferência à UTI neurológica. Neurologia e equipe de neurorradiologia intervencionista acionadas. Informada a família.'),
  (55, 17, 13, '2022-08-25 09:00', 'internacao', 'Acompanhamento do AVC em enfermaria', 148, 88, 82, 61.0, 'D4 de AVC isquêmico cardioembólico em território da ACM E, tratado com trombólise e trombectomia mecânica com recanalização TICI 2b. NIHSS atual 7: afasia de expressão moderada e hemiparesia D grau 3, deglutição prejudicada, sonda enteral. RM de crânio: infarto subcortical e insular E de 28 mL, sem transformação hemorrágica. Ritmo de FA com FC controlada. Sem sinais de infecção.', 'Iniciar apixabana 5 mg 12/12h no D4 (infarto moderado, sem hemorragia, conforme protocolo). Estatina de alta potência. Fisioterapia motora e fonoaudiologia intensivas. Manter PA em torno de 130 a 140 mmHg: reintroduzir losartana 50 mg 12/12h e metoprolol. Alta para reabilitação hospitalar.'),
  (56, 17, 4, '2022-11-28 11:00', 'retorno', 'Voltei para ver o coração depois do derrame', 134, 80, 74, 59.5, 'Três meses depois do AVC, em cadeira de rodas para longas distâncias; deambula com apoio de andador. Persistem afasia leve e hemiparesia direita grau 4. Toma apixabana todos os dias, a filha organiza a caixa. Sem sangramentos. Humor deprimido, ''fui eu que não quis o remédio''. Ao exame: ritmo irregular, FC 74, sem sopros, sem edema. Hemoglobina 12,6 g/dL, creatinina 0,8 mg/dL, LDL 74 mg/dL.', 'Manter apixabana 5 mg 12/12h, atorvastatina, losartana e metoprolol. Suspender AAS (sem indicação com anticoagulação). Encaminhada para acompanhamento psicológico e reabilitação continuada. Discutir ablação ou controle do ritmo com a arritmologia no futuro. Retorno em 4 meses.');
