insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (17, '2022-11-28', 'piorou', 'A recusa do anticoagulante na FA paroxística levou a AVC cardioembólico extenso, tratado com trombólise e trombectomia. Evoluiu com afasia leve e hemiparesia direita residuais, dependente de apoio para deambular. Agora anticoagulada com apixabana, sem sangramentos, e em reabilitação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (18, 'Valdemar Pires de Sá', 'M', '1957-05-30', 'Uberaba', 'MG', 'Lavrador aposentado', 'Doença de Chagas diagnosticada há 15 anos. Cardiopatia chagásica com IC desde 2018, sem acompanhamento regular. HAS leve. Etilismo importante no passado, abstêmico há 4 anos. Mora em área rural, a 40 km da cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (57, 18, 11, '2020-08-17 08:30', 'consulta', 'Falta de ar e inchaço nas pernas', 104, 66, 88, 71.5, 'Homem de 63 anos com Chagas e cardiopatia dilatada, NYHA III, dispneia a pequenos esforços, ortopneia e edema vespertino. Abandonou o tratamento há um ano por morar longe. Ao exame: ingurgitamento jugular, RCR 2T BNF, B3, sopro sistólico 2+/6+ em foco mitral, estertores em bases, hepatomegalia dolorosa, edema 2+/4+. ECG: FA de alta resposta ausente; ritmo sinusal com BRD e HBAE. ECO: FEVE 28%, dilatação biventricular, aneurisma apical com trombo mural de 14 mm. NT-proBNP 4.200 pg/mL.', 'Doença de Chagas crônica com cardiopatia estabelecida: sem benznidazol. Iniciar varfarina 5 mg/dia com alvo de INR 2-3, por trombo apical, e heparina de baixo peso molecular até INR terapêutico. Carvedilol 3,125 mg 12/12h, enalapril 5 mg 12/12h, espironolactona 25 mg, furosemida 40 mg. Orientações de sal e líquidos. INR semanal no posto de saúde. Retorno em 30 dias.'),
  (58, 18, 11, '2020-10-26 08:50', 'retorno', 'Estou melhor da falta de ar', 108, 68, 72, 66.0, 'Retorna após 2 meses. Perdeu 5,5 kg de líquido, ortopneia resolvida, NYHA II. Mantém INR entre 1,8 e 3,2 nos controles do posto (hoje 2,6), sem sangramentos. Ao exame: PA 108x68 mmHg, sem estertores, sem edema, hepatomegalia regrediu. ECO: trombo apical menor (8 mm), FEVE 30%. K 4,7 mEq/L, creatinina 1,2 mg/dL. Tolerando carvedilol e enalapril sem hipotensão sintomática.', 'Manter varfarina com alvo de INR 2-3 por pelo menos 6 meses e reavaliar o trombo por ECO. Aumentar carvedilol para 6,25 mg 12/12h. Manter demais fármacos. Pesar-se diariamente e anotar. Retorno em 90 dias, trazer os INR.'),
  (59, 18, 14, '2022-02-07 18:20', 'internacao', 'Internado por piora da falta de ar', 86, 54, 102, 64.0, 'Pcte 64 anos, Chagas com FEVE 22%, readmitido em UTI com choque cardiogênico. Perdeu seguimento por 1 ano, sem INR e sem diuréticos há 2 meses. Dispneia em repouso, extremidades frias, perfusão lentificada, lactato 3,8 mmol/L, oligúria. PA 86x54 mmHg. Estertores até ápices, edema 3+/4+, ascite. Creatinina 2,4 mg/dL (síndrome cardiorrenal). NT-proBNP 18.000 pg/mL. ECO: FEVE 20%, trombo apical persistente, insuficiência mitral moderada. HD: IC Chagásica em estágio D, perfil frio e congesto.', 'Dobutamina EV, furosemida em infusão, suporte ventilatório não invasivo. Anticoagulação com heparina não fracionada pelo trombo. Suspensos IECA e espironolactona pelo choque e pela injúria renal. Conversado com família sobre prognóstico reservado e limite de suporte avançado: não candidato a transplante por caquexia e comorbidades.');
