insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (18, '2022-02-19', 'obito', 'Cardiopatia chagásica em estágio avançado, perdeu seguimento por um ano por morar longe, e foi internado em choque cardiogênico com síndrome cardiorrenal. Sem resposta ao suporte inotrópico, evoluiu com parada cardiorrespiratória e faleceu na UTI em 19/02/2022, com a família acompanhando.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (19, 'Hildegard Schmitt', 'F', '1939-11-20', 'Indaiatuba', 'SP', 'Aposentada (ex-professora de alemão)', 'HAS há 40 anos com losartana e anlodipino. Dislipidemia. Há 2 anos episódios de tontura. Ativa, caminha diariamente e cuida do jardim. Viúva, mora sozinha, filho vive em Campinas. Sem DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (60, 19, 6, '2021-04-05 04:10', 'pronto_socorro', 'Desmaiei no banheiro de madrugada', 158, 74, 34, 59.0, 'Pcte 81 anos, encontrada caída no banheiro após levantar à noite, com perda de consciência de poucos segundos e trauma em face (corte em supercílio). Refere tonturas e cansaço há 2 semanas. Ao exame: bradicárdica, palidez cutânea, RCR 2T BNF, sem sopros, pulmões limpos. ECG: bloqueio atrioventricular total com escape juncional de QRS estreito a 34 bpm, dissociação AV, sem isquemia aguda. K 4,1 mEq/L, creatinina 0,9 mg/dL, troponina negativa. HD: BAVT sintomático com síncope.', 'Suspensão do anlodipino, monitorização contínua, pás de marca-passo transcutâneo à beira leito. Sutura do supercílio. Internação em UTI e implante de marca-passo definitivo em até 48h. Atropina não indicada (escape juncional). Cardiologia (arritmologia) acionada. Contactado o filho.'),
  (61, 19, 4, '2021-04-07 08:00', 'internacao', 'Implante do marca-passo', 140, 72, 70, 58.8, 'D2 de BAVT sem causa reversível (sem drogas bradicardizantes, TSH normal, sem isquemia). Implantado marca-passo definitivo bicameral (DDD) por via subclávia esquerda sob anestesia local, sem intercorrências. Eletrodo atrial e ventricular com limiares adequados, sem pneumotórax no raio X. Hoje, FC 70 bpm, ritmo estimulado, sem tontura. Curativo limpo, sem hematoma. Orientada sobre cuidados com o MP.', 'Alta hospitalar amanhã. Evitar elevar o braço esquerdo acima do ombro por 4 semanas. Cefalexina 500 mg 6/6h por 5 dias como profilaxia. Retorno para revisão e interrogação do MP em 30 dias. Cartão de identificação do dispositivo entregue. Manter losartana 50 mg 12/12h; anlodipino não retomado.'),
  (62, 19, 4, '2021-05-10 10:00', 'retorno', 'Estou ótima, voltei para o jardim', 142, 76, 70, 59.4, 'Cicatriz da loja do MP limpa, sem hematoma nem sinais de infecção. Sem tontura, sem síncope; caminha 40 minutos. Interrogação: 100% de pacing ventricular, limiares estáveis, bateria 10,2 anos estimados, sem arritmias atriais. PA de consultório 142x76, domiciliar 138x74 mmHg com losartana.', 'Manter losartana. Meta individualizada para idosa ativa: PA < 140/80 mmHg. Seguimento do MP a cada 6 meses (presencial ou remoto). Orientado a evitar ressonância magnética não condicional e campos magnéticos intensos. Retorno em 6 meses.');
