insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (19, '2021-05-10', 'melhorou', 'Bloqueio atrioventricular total com síncope tratado com marca-passo definitivo bicameral. Sem novos episódios de tontura ou síncope, retomou caminhadas e jardinagem, ferida cicatrizada e dispositivo com parâmetros normais. Segue em controle semestral do marca-passo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (20, 'Thiago Nascimento Barreto', 'M', '1997-02-14', 'São Paulo', 'SP', 'Analista de suporte de TI', 'Sem comorbidades. Pratica musculação 4x/semana, nega uso de anabolizantes ou suplementos com estimulantes. Nega tabagismo e drogas ilícitas. Infecção de vias aéreas superiores há 10 dias, tratada com sintomáticos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (63, 20, 6, '2023-03-18 21:00', 'pronto_socorro', 'Dor no peito forte depois de uma gripe', 122, 74, 104, 82.0, 'Pcte 26 anos com dor precordial em pressão, contínua, desde a manhã, que piora ao deitar e alivia pouco ao sentar, após síndrome gripal há 10 dias. Nega febre atual, dispneia. Ao exame: BEG, afebril, RCR 2T BNF sem sopros ou atrito, MV+ sem RA, sem edema. ECG: supra de ST côncavo e difuso em DI, aVL e V2-V6, sem infra especular. Troponina ultrassensível 3.200 ng/L (pico 5.800 ng/L), PCR 48 mg/L. ECO: FEVE 52%, hipocinesia leve difusa, sem derrame. HD: miocardite aguda de provável origem viral, com pericardite associada.', 'Internação com monitorização contínua por risco de arritmia. Repouso absoluto e suspensão da musculação por 6 meses. AINE (ibuprofeno 600 mg 8/8h) com cuidado e colchicina 0,5 mg 12/12h para componente pericárdico. Colher painel viral e solicitar RM cardíaca após fase aguda. Betabloqueador em baixa dose se taquicardia.'),
  (64, 20, 11, '2023-03-27 10:00', 'internacao', 'Acompanhamento na enfermaria, sem dor', 116, 70, 76, 81.5, 'D9 de miocardite aguda com pericardite. Sem dor há 5 dias, afebril, sem arritmias no monitor (apenas extrassístoles ventriculares isoladas). Troponina em queda (210 ng/L). ECO de controle: FEVE 46%, hipocinesia anterolateral, sem derrame. Painel viral negativo, HIV e sorologias negativas. Ao exame: RCR 2T BNF, MV+ sem RA, sem edema, sem atrito pericárdico.', 'Alta hospitalar. Iniciar enalapril 5 mg 12/12h e carvedilol 3,125 mg 12/12h pela disfunção ventricular leve. Manter colchicina e suspender ibuprofeno. Repouso e proibição de esportes competitivos e musculação intensa por 6 meses. RM cardíaca em 4 semanas. Retorno ambulatorial em 4 semanas.'),
  (65, 20, 11, '2023-04-24 10:30', 'retorno', 'Trouxe a ressonância, estou sem sintomas', 118, 72, 66, 81.0, 'Assintomático, retomou o trabalho remoto. Ressonância cardíaca: edema miocárdico em parede lateral mediana, realce tardio subepicárdico em segmentos basal e médio inferolateral (padrão compatível com miocardite), sem realce transmural, FEVE 55%. Holter 24h: extrassístoles ventriculares isoladas (480/24h), sem TV. PA 118x72 e FC 66 bpm. Ao exame: RCR 2T BNF sem sopros, MV+ sem RA.', 'Manter enalapril e carvedilol por 6 meses. Colchicina até completar 3 meses. Esportes e musculação seguem suspensos até nova avaliação (ECO, Holter e teste ergométrico aos 6 meses). Orientado a procurar PS se palpitações, dor ou síncope. Retorno em 5 meses.'),
  (66, 20, 11, '2023-09-18 11:00', 'retorno', 'Seis meses depois, queria liberar a academia', 114, 70, 62, 80.2, 'Seis meses de seguimento, sem sintomas. ECO: FEVE 60%, sem alterações segmentares. Holter: poucas extrassístoles ventriculares isoladas (60/24h). Teste ergométrico máximo (12 METs): sem arritmias ou alterações isquêmicas, resposta pressórica adequada. Ao exame: RCR 2T BNF, MV+ sem RA, sem edema.', 'Liberada atividade física progressiva, iniciando com 50% da carga anterior. Suspender enalapril e carvedilol com redução gradual em 2 semanas. Novo ECO e Holter em 6 meses para confirmar estabilidade. Orientado a manter acompanhamento anual.');
