insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (20, '2023-09-18', 'melhorou', 'Miocardite viral com pericardite em jovem, com FEVE mínima de 46% e recuperação completa para 60% em seis meses. Sem arritmias relevantes ao Holter e teste ergométrico normal. Liberado para atividade física progressiva e medicações de proteção suspensas, com seguimento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (21, 'Larissa Moura Figueiredo', 'F', '1991-02-08', 'Sorocaba', 'SP', 'Engenheira de produção', 'Sem doenças crônicas. Sobrepeso (IMC 27,5), dieta rica em industrializados, trabalha 10 horas por dia no computador. Não fuma, bebe socialmente. Pai hipertenso desde os 45 anos. Usa anticoncepcional oral combinado há 8 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (67, 21, 1, '2022-08-15 12:30', 'consulta', 'Check-up da empresa deu pressão 134 por 86', 134, 86, 80, 76.0, 'Mulher de 31 anos assintomática, enviada pela empresa por PA 134x86 mmHg no check-up. Nega cefaleia, palpitações e dor torácica. Estressada com metas, dorme 5 a 6 horas, almoça fast-food, sedentária. Pai hipertenso. Ao exame: IMC 27,5, RCR 2T BNF sem sopros, MV+ sem RA, pulsos simétricos. PA 134x86 mmHg (3 medidas, braço D e E sem diferença). Exames: creatinina 0,8 mg/dL, potássio 4,1 mEq/L, glicemia 92 mg/dL, LDL 108 mg/dL, TSH 2,0 mUI/L, urina tipo 1 normal. HD: pré-hipertensão com fatores de risco, baixo risco cardiovascular.', 'Sem indicação de fármaco. MEV: dieta DASH, sódio < 2 g/dia, caminhada rápida 150 min por semana, higiene do sono e meta de perder 5 kg. Solicitado MRPA por 5 dias. Discutido com a ginecologista o uso do anticoncepcional combinado, que pode elevar a PA. Retorno em 3 meses.'),
  (68, 21, 1, '2022-12-12 12:40', 'retorno', 'Perdi uns quilos, quero ver como estou', 128, 82, 74, 72.5, 'Retorna após 4 meses. Segue a dieta DASH em boa parte do tempo, caminha 4x por semana e perdeu 3,5 kg. MRPA com média de 126x80 mmHg, sem valores acima de 135x85. A ginecologista trocou o anticoncepcional combinado por DIU hormonal. Ao exame: PA 128x82 mmHg, RCR 2T BNF, sem sopros. Sono ainda curto, em torno de 6 horas.', 'PA melhor, ainda no limite superior de pré-hipertensão. Manter MEV e metas de perda de mais 2 a 3 kg. Sem indicação de fármaco. Repetir MRPA se PA de consultório > 140x90. Retorno em 6 meses.'),
  (69, 21, 1, '2023-06-26 12:30', 'retorno', 'Retorno semestral', 118, 76, 70, 69.8, 'Pcte mantém hábitos novos: caminha 5x por semana, faz marmita e dorme melhor após reduzir as reuniões noturnas. Perdeu um total de 6,2 kg. Sem sintomas. Ao exame: IMC 25,5, PA 118x76 mmHg, RCR 2T BNF, sem sopros. LDL 96 mg/dL, glicemia 88 mg/dL.', 'PA normalizada exclusivamente com MEV. Manter orientações. Orientado a medir PA anualmente e voltar antes se houver gestação planejada. Alta ambulatorial com acompanhamento anual na atenção primária.');
