insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (21, '2023-06-26', 'controlado', 'Pré-hipertensão revertida apenas com mudança de estilo de vida: perda de 6,2 kg, dieta DASH, exercício regular e troca do anticoncepcional. PA de consultório 118x76 mmHg sem nenhum medicamento. Recebeu alta para acompanhamento anual na atenção primária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (22, 'Benedito Alves Taveira', 'M', '1962-09-27', 'Presidente Prudente', 'SP', 'Motorista de caminhão aposentado', 'HAS há 22 anos, atualmente com losartana 100 mg/dia, anlodipino 10 mg/dia e clortalidona 25 mg/dia, com PA acima de 150x90 mesmo assim. DM2 não. Ex-tabagista (30 maços-ano, parou há 8 anos). Sedentário, obesidade grau I. Dieta com muita carne salgada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (70, 22, 2, '2021-03-08 09:00', 'consulta', 'Pressão não baixa com três remédios', 164, 98, 76, 98.0, 'Homem de 58 anos com HAS ''de difícil controle'' em uso de losartana, anlodipino e clortalidona em doses plenas. Confirmada adesão: retira os remédios todo mês, a esposa dispensa e ele toma sob supervisão; não usa AINE, descongestionante ou antidepressivo. Ao exame: obeso (IMC 32,9), PA 164x98 mmHg com manguito apropriado. RCR 2T BNF, B4, sem sopros, sem sopro abdominal, pulsos presentes, sem edema. MAPA: média 24h de 158x94, vigília 162x96, sono 148x86. Exames: creatinina 1,1 mg/dL, potássio 4,0 mEq/L. HD: HAS resistente verdadeira (pseudorresistência excluída pela adesão e pela MAPA).', 'Investigação secundária: aldosterona e atividade de renina, TSH, ácido úrico, ECO, Doppler de artérias renais, questionário de apneia (STOP-Bang). Iniciar espironolactona 25 mg/dia como quarto fármaco, mantendo os demais; checar potássio e creatinina em 1 semana. Orientar dieta com pouco sal. Retorno em 30 dias.'),
  (71, 22, 2, '2021-04-19 09:10', 'retorno', 'Voltei com os exames', 146, 88, 72, 97.2, 'Tolerando espironolactona sem queixas, K 4,7 mEq/L e creatinina 1,2 mg/dL após 1 semana. Resultados da investigação: aldosterona 9 ng/dL, renina 2,1 ng/mL/h (relação 4,3, normal), TSH normal, ECO com HVE leve, FEVE 63%, Doppler de artérias renais normal, STOP-Bang 2 (baixo risco de apneia). Sem causa secundária identificada. PA 146x88 mmHg, ainda acima da meta. Peso: perdeu 800 g.', 'Aumentar espironolactona para 50 mg/dia. Controlar potássio e creatinina em 2 semanas. Manter losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Reforçar dieta com baixo sódio. Retorno em 45 dias.'),
  (72, 22, 2, '2021-10-11 09:20', 'retorno', 'Pressão boa, mas o peito ficou dolorido', 128, 78, 70, 94.0, 'Seis meses de seguimento. PA domiciliar média de 126x76 mmHg. Perdeu 4 kg. Queixa-se de sensibilidade mamária bilateral discreta há 2 meses, sem nódulos. Ao exame: ginecomastia leve bilateral, dolorosa à palpação, sem massas, sem secreção. PA 128x78 mmHg, sem edema. K 4,9 mEq/L, creatinina 1,2 mg/dL, sódio 140 mEq/L. MAPA de controle: média 24h de 124x76 mmHg.', 'Orientado que a ginecomastia é efeito da espironolactona, dose-dependente. Reduzir espironolactona para 25 mg/dia e acompanhar PA; se PA subir, considerar troca por amilorida. Manter demais fármacos. Controle de K a cada 3 meses. Retorno em 90 dias.');
