insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (22, '2021-10-11', 'controlado', 'Hipertensão resistente verdadeira, com adesão confirmada e causa secundária excluída, controlada com a adição de espironolactona como quarto fármaco. MAPA de controle na meta, perda de 4 kg e ginecomastia leve manejada com redução da dose. Segue em controle trimestral de potássio e creatinina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (23, 'Jorge Luiz Andreoli', 'M', '1974-03-18', 'Santo André', 'SP', 'Gerente de logística', 'HAS há 7 anos, em uso de losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg com controle ruim. Obesidade grau II (IMC 38). Ronco alto e sonolência diurna. Já cochilou ao volante duas vezes. Bebe cerveja 3x por semana. Sem DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (73, 23, 2, '2021-05-17 17:30', 'consulta', 'Pressão alta mesmo com três remédios, durmo mal e ronco muito', 166, 100, 84, 118.0, 'Homem de 47 anos, obeso, com HAS refratária a três fármacos, cefaleia matinal e sonolência diurna. A esposa relata roncos intensos e pausas respiratórias durante o sono. Epworth 16. Circunferência do pescoço 46 cm. Ao exame: IMC 38,3, Mallampati IV, RCR 2T BNF, B4, sem sopros, MV+ sem RA, sem edema. PA 166x100 mmHg. MRPA com média 160x98 mmHg. ECG: SVE por Sokolow-Lyon. HD: suspeita de apneia obstrutiva do sono como causa de hipertensão secundária.', 'Solicitada polissonografia e ECO. Aconselhado a não dirigir enquanto houver sonolência e a evitar álcool à noite. Manter losartana, anlodipino e hidroclorotiazida. Orientações de dieta e atividade física com meta de perder 10% do peso. Retorno em 30 dias com o exame.'),
  (74, 23, 2, '2021-07-12 17:40', 'retorno', 'Fiz o exame do sono', 158, 96, 80, 117.0, 'Retorna com polissonografia: IAH 52 eventos por hora (apneia grave), dessaturação mínima de 71%, SpO2 média de 90%, 38% do tempo com SpO2 abaixo de 90%. ECO: HVE moderada, FEVE 60%, átrio esquerdo 41 mm. Titulação de CPAP realizada com pressão de 11 cmH2O, normalizando o IAH para 3/h. Sem arritmias ao ECG. Ao exame: PA 158x96 mmHg, sem edema. Paciente relutou: ''achei que fosse máscara de astronauta'', mas aceitou testar.', 'Prescrito CPAP automático 8 a 14 cmH2O com máscara nasal, uso todas as noites e mínimo de 4 h por noite. Manter anti-hipertensivos até avaliar o efeito. Fisioterapia e nutrição para perda de peso. Cartão de CPAP com fornecedor. Retorno em 90 dias com relatório de uso do aparelho.'),
  (75, 23, 2, '2021-11-22 17:30', 'retorno', 'Dormindo muito melhor, voltei a ter disposição', 126, 78, 70, 109.5, 'Quatro meses de CPAP com uso médio de 6,2 h por noite, IAH residual 2/h pelo relatório do aparelho. Acabou a sonolência diurna, esposa dorme melhor, não ronca. Perdeu 8,5 kg. Epworth 5. Cefaleia matinal desapareceu. PA domiciliar média de 122x76 mmHg. Ao exame: PA 126x78 mmHg, sem edema. Creatinina 1,0 mg/dL e potássio 4,3 mEq/L.', 'Com PA controlada e algum risco de hipotensão com perda de peso, suspender hidroclorotiazida e manter losartana 100 mg e anlodipino 10 mg. Manter CPAP e incentivar perda de peso adicional. MRPA em 30 dias. Retorno em 3 meses.');
