insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (23, '2021-11-22', 'melhorou', 'Hipertensão secundária à apneia obstrutiva do sono grave tratada com CPAP e perda de 8,5 kg. PA passou de 166x100 para 126x78 mmHg com um anti-hipertensivo a menos, sonolência diurna resolvida e uso do aparelho acima de 6 horas por noite. Mantém controle trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (24, 'Sandra Regina Gonçalves Pimentel', 'F', '1968-12-04', 'Belo Horizonte', 'MG', 'Contadora', 'Sem diagnóstico de HAS. Pressões sempre normais em consultórios, mas percebe 14 por 9 em casa e na farmácia. Trabalho estressante, tabagista de 10 cigarros por dia, bebe 1 taça de vinho por noite. Pai teve AVC aos 65 anos.', 'Alergia a sulfa (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (76, 24, 2, '2023-02-13 11:00', 'consulta', 'No consultório a pressão é normal, em casa não', 126, 78, 84, 68.5, 'Mulher de 54 anos com PA de consultório repetidamente normal e leituras domiciliares de 140-150x88-94 mmHg com aparelho validado. Muito estressada com fechamento contábil, fuma 10 cigarros por dia e toma vinho diariamente. Nega sintomas. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA. PA 126x78 mmHg. ECG: SVE pelo critério de Cornell. Creatinina 0,8 mg/dL, glicemia 99 mg/dL. HD: suspeita de hipertensão mascarada (consultório normal, PA fora do consultório elevada).', 'Solicitada MAPA 24h para confirmar. ECO para avaliar HVE. Início de MEV: parar de fumar (oferecido apoio), reduzir álcool, atividade física regular. Retorno em 30 dias com o exame.'),
  (77, 24, 2, '2023-03-27 11:10', 'retorno', 'Trouxe a MAPA', 124, 76, 82, 68.0, 'MAPA 24h: média 24h de 138x86 mmHg, vigília 144x90 mmHg, sono 126x76 mmHg, confirmando HAS mascarada. ECO: HVE leve (massa indexada 112 g/m²), FEVE 66%. Albuminúria 12 mg/g. Segue fumando 6 cigarros por dia. PA de consultório 124x76 mmHg novamente normal. HD: HAS mascarada com lesão de órgão-alvo (HVE), risco cardiovascular elevado.', 'Iniciar losartana 50 mg/dia. Cessação do tabagismo com bupropiona e reposição de nicotina, a considerar. Evitar sulfa. Manter MRPA. Repetir MAPA em 3 meses. Orientadas medidas de redução do estresse e do álcool. Retorno em 60 dias.'),
  (78, 24, 2, '2023-09-18 11:20', 'retorno', 'Pressão de casa voltou ao normal', 120, 74, 72, 66.4, 'Paciente parou de fumar há 3 meses com apoio de bupropiona, reduziu o vinho para fins de semana e perdeu 1,6 kg. MRPA com média de 122x76 mmHg. MAPA repetida: média 24h de 120x74 mmHg, vigília 124x78, sono 108x64, controlada. Sem efeitos adversos da losartana. Ao exame: PA 120x74 mmHg, RCR 2T BNF, sem sopros. Creatinina 0,8 mg/dL, potássio 4,2 mEq/L.', 'Manter losartana 50 mg/dia. Seguir sem tabaco e com álcool reduzido. ECO em 12 meses para reavaliar a HVE. MRPA mensal em casa. Retorno em 6 meses.');
