insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (24, '2023-09-18', 'controlado', 'Hipertensão mascarada identificada por MAPA, com HVE leve, controlada com losartana 50 mg/dia e MEV (abandono do tabaco, redução do álcool). MAPA de controle na meta e MRPA normal. Segue em acompanhamento semestral com reavaliação do ecocardiograma em um ano.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (25, 'Reinaldo Sobral Machado', 'M', '1955-01-10', 'Porto Alegre', 'RS', 'Bancário aposentado', 'HAS há 20 anos, dislipidemia e pré-diabetes. Ex-fumante (parou em 2005). Joga bola com amigos aos sábados. Pai com infarto aos 63 anos. Em uso de losartana 50 mg 12/12h e sinvastatina 20 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (79, 25, 2, '2022-04-04 15:00', 'consulta', 'Dor no peito quando jogo bola ou subo rampa', 142, 86, 74, 86.0, 'Homem de 67 anos com dor retroesternal em aperto aos esforços moderados (corrida na partida de futebol e subida de rampa), que cede em 3 a 5 minutos com repouso, há 2 meses, sem mudança no padrão. CCS II. Sem síncope, sem dispneia em repouso. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA, sem edema. ECG de repouso normal. Cintilografia miocárdica: isquemia reversível moderada na parede anterior (12% do VE). LDL 112 mg/dL. HD: angina estável CCS II, risco intermediário.', 'Iniciar AAS 100 mg, metoprolol succinato 50 mg, atorvastatina 40 mg (suspender sinvastatina) e mononitrato de isossorbida 20 mg 12/12h. Nitroglicerina SL se dor. Solicitado cateterismo para estratificar anatomia. Suspender o futebol até a avaliação. Retorno em 45 dias.'),
  (80, 25, 10, '2022-05-23 15:10', 'retorno', 'Trouxe o resultado do cateterismo', 128, 74, 60, 85.2, 'Melhora importante com a terapia clínica: duas crises leves de angina em 45 dias, ambas em esforço intenso. CATE: lesão excêntrica de 60% na DA média com FFR 0,84 (não significativa), Cx e CD com irregularidades parietais. Função ventricular preservada (FEVE 62%). Considerada doença uniarterial com lesão sem repercussão hemodinâmica; estratégia inicial conservadora em paciente com sintomas controlados. Ao exame: PA 128x74 mmHg, FC 60 bpm, sem edema.', 'Manter tratamento clínico otimizado. Sem indicação de ATC no momento. LDL meta < 50 mg/dL: aumentar atorvastatina para 80 mg e repetir exames em 3 meses. Retomar exercício aeróbico supervisionado; futebol só após reabilitação. Reavaliar se angina piorar.'),
  (81, 25, 2, '2023-04-17 15:30', 'retorno', 'Quase sem dor no peito', 124, 72, 58, 83.0, 'Quase um ano de seguimento clínico. Faz reabilitação cardiovascular três vezes por semana e anda de bicicleta; angina rara, uma crise em seis meses ao correr atrás do ônibus. Sem uso de nitroglicerina SL. LDL 46 mg/dL, glicemia 104 mg/dL, creatinina 1,0 mg/dL. Ao exame: bradicardia sinusal assintomática, RCR 2T BNF, sem sopros, sem edema. Teste ergométrico: 10 METs, sem isquemia ao ECG, angina leve ao pico.', 'Manter AAS, atorvastatina 80 mg, metoprolol e nitrato; sem necessidade de revascularização. Reduzir mononitrato para 20 mg ao dia. Liberada atividade física moderada, incluindo futebol recreativo leve. Repetir teste funcional em 12 meses. Retorno em 6 meses.');
