insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (25, '2023-04-17', 'estavel', 'Doença coronariana uniarterial com lesão sem repercussão funcional, mantida em tratamento clínico otimizado e reabilitação. Angina rara, LDL em 46 mg/dL e boa capacidade funcional. Sem indicação de revascularização, segue em acompanhamento semestral com estratificação anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (26, 'Wagner Tadeu Lopes', 'M', '1952-07-22', 'Campinas', 'SP', 'Empresário do ramo de autopeças', 'HAS há 20 anos, dislipidemia, DM2 há 8 anos em uso de metformina. Ex-tabagista pesado (parou há 5 anos). Estresse laboral intenso. Sedentário. Mãe e irmão com doença coronariana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (82, 26, 6, '2020-11-09 19:40', 'pronto_socorro', 'Dor no peito há três dias que agora vem em repouso', 156, 92, 90, 92.0, 'Pcte 68 anos com angina aos esforços desde a semana passada, que evoluiu para crises em repouso, 4 episódios nas últimas 24h, duração de até 15 min, com sudorese. Última crise há 1h. Ao exame: desconforto leve, RCR 2T BNF, sem sopros, MV+ sem RA, sem edema. ECG: infradesnivelamento de ST de 1 mm em V4-V6, sem supra. Troponina ultrassensível seriada normal (8 e 9 ng/L). HD: angina instável de alto risco, TIMI 4.', 'AAS 300 mg e ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, betabloqueador e nitrato. Internação em unidade coronariana e cateterismo nas próximas 24h. Jejum. Controle glicêmico com insulina conforme glicemia.'),
  (83, 26, 10, '2020-11-11 10:00', 'internacao', 'Dia seguinte ao cateterismo', 134, 80, 66, 91.5, 'CATE radial: lesão crítica de 95% em DA proximal (culpada), Cx com 50% e CD com 40%. Realizada ATC com stent farmacológico 3,5x24 mm em DA proximal, com bom resultado, TIMI 3. Sem dor desde o procedimento. Pico de troponina 12 ng/L. ECO: FEVE 56%, sem alterações segmentares. Radial sem complicações. Orientado sobre dupla antiagregação mínima de 12 meses e que não deve interromper o ticagrelor sem falar com cardiologista.', 'Alta no D2. Manter AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses; atorvastatina 80 mg, metoprolol e losartana. Entregue cartão informativo do stent. Reabilitação cardiovascular. Retorno em 60 dias.'),
  (84, 26, 1, '2021-01-18 16:00', 'retorno', 'Estou bem, mas o dentista quer tirar uns dentes', 126, 76, 64, 90.0, 'Dois meses depois do stent, sem angina, retomou parte do trabalho. Perguntou sobre exodontia de dois molares marcada para março. Informado que procedimento odontológico simples deve ser feito sem suspender antiagregante, com hemostasia local. Ao exame: PA 126x76 mmHg, RCR 2T BNF, sem sopros. LDL 64 mg/dL, HbA1c 7,2%.', 'Não suspender AAS nem ticagrelor para o procedimento dentário; se o dentista exigir interrupção, entrar em contato com cardiologia antes. Entregue carta para o dentista com a explicação. Seguir reabilitação. Retorno em 60 dias.'),
  (85, 26, 6, '2021-03-02 04:30', 'pronto_socorro', 'Dor muito forte no peito, acordei suando', 98, 62, 108, 91.0, 'Pcte com stent em DA proximal há 16 semanas, chega com dor precordial intensa há 1h, sudorese fria, dispneia e hipotensão. Admite ter suspendido o ticagrelor 8 dias antes por orientação do dentista, ''para não sangrar'', fez a extração dos molares sem contar a ninguém. Ao exame: pálido, sudoreico, estertores em bases, B3. ECG: supra de ST de 4 mm de V1-V5 com BRE novo. Troponina 6.200 ng/L. HD: IAMCSST anterior extenso por provável trombose de stent após suspensão da dupla antiagregação, Killip III.', 'Ativada hemodinâmica de emergência. Reinício de AAS 300 mg e ticagrelor 180 mg. Heparina. Cateterismo imediato com trombectomia e nova ATC. Suporte hemodinâmico e UTI. Comunicados os familiares sobre gravidade e sobre a necessidade de não interromper a antiagregação.');
