insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (26, '2021-03-20', 'piorou', 'A suspensão do ticagrelor por orientação odontológica, 16 semanas após o stent, causou trombose e infarto anterior extenso, tratado com nova angioplastia. Evoluiu com FEVE de 35% e IC leve, em reabilitação. Reforçada a regra de nunca interromper a dupla antiagregação sem aval do cardiologista.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (27, 'Aparecida Benedita Moraes', 'F', '1960-10-15', 'São Paulo', 'SP', 'Ex-empregada doméstica, aposentada', 'Infarto há 3 anos tratado com angioplastia. HAS há 25 anos e dislipidemia. ICFEr isquêmica, em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg, sem outros pilares. Ex-tabagista. Mora com a neta em casa de dois andares.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (86, 27, 11, '2022-10-03 08:30', 'consulta', 'Cansaço para subir a escada de casa', 124, 74, 80, 69.0, 'Mulher de 62 anos com ICFEr isquêmica, NYHA II-III, dispneia aos médios esforços, ortopneia leve e edema discreto de tornozelos. ECO: FEVE 30%, dilatação de VE, hipocinesia difusa com acinesia anterior. NT-proBNP 1.800 pg/mL. Ao exame: sem turgência jugular, B3 discreto, estertores raros em bases, edema 1+/4+. Creatinina 1,1 mg/dL (TFGe 55), potássio 4,6 mEq/L. Está sem espironolactona e sem iSGLT2. HD: ICFEr NYHA II-III, otimização incompleta dos pilares do tratamento.', 'Suspender enalapril; aguardar 36 horas e iniciar sacubitril/valsartana 24/26 mg 12/12h. Adicionar dapagliflozina 10 mg/dia e espironolactona 25 mg/dia. Manter carvedilol 6,25 mg 12/12h e furosemida 40 mg. Controle de K e creatinina em 1 semana. Retorno em 60 dias.'),
  (87, 27, 11, '2022-12-12 08:40', 'retorno', 'Melhorei, mas fico tonta quando levanto', 98, 62, 68, 65.4, 'Dois meses depois, NYHA II, sem edema nem ortopneia. Perdeu 3,6 kg. Tontura postural nas últimas semanas, sem síncope. Ao exame: PA 98x62 mmHg sentada e 90x58 em pé. Sem estase jugular, pulmões limpos. Potássio 5,2 mEq/L, creatinina 1,3 mg/dL (TFGe 45). NT-proBNP 920 pg/mL. Hipercalemia leve e hipotensão sintomática, sem evidência de hipovolemia grave.', 'Suspender furosemida (paciente euvolêmica). Manter sacubitril/valsartana 24/26 mg, carvedilol, dapagliflozina e espironolactona reduzida para 12,5 mg/dia pelo potássio de 5,2. Orientação alimentar para evitar sal-light (rico em potássio). Repetir K e creatinina em 15 dias. Retorno em 60 dias.'),
  (88, 27, 11, '2023-05-29 08:30', 'retorno', 'Estou subindo a escada sem parar', 110, 68, 64, 66.0, 'NYHA I-II, sem internações. Sem tontura, sem edema, faz caminhada diária de 30 minutos. Adere bem, a neta organiza os remédios. K 4,8 mEq/L, creatinina 1,2 mg/dL (TFGe 49), NT-proBNP 410 pg/mL. ECO de controle: FEVE 40%, melhora da contratilidade global, dilatação de VE reduzida. Ao exame: PA 110x68 mmHg, sem hipotensão ortostática, RCR 2T BNF, pulmões limpos.', 'Titular sacubitril/valsartana para 49/51 mg 12/12h com checagem de PA, K e creatinina em 2 semanas. Manter espironolactona 12,5 mg, dapagliflozina e carvedilol (aumento para 12,5 mg 12/12h se FC > 60 e PA permitir). Reabilitação cardiovascular. Retorno em 90 dias.');
