insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (27, '2023-05-29', 'melhorou', 'ICFEr isquêmica otimizada com os quatro pilares, com ajustes para hipercalemia e hipotensão. FEVE subiu de 30% para 40%, NT-proBNP caiu de 1.800 para 410 pg/mL e a paciente passou a NYHA I-II, sem internações. Segue em titulação gradual e reabilitação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (28, 'Luís Eduardo Vilela', 'M', '1968-06-02', 'Jundiaí', 'SP', 'Gerente bancário', 'HAS há 6 anos com losartana 50 mg 12/12h. Sobrepeso. Consumo de cerveja nos fins de semana. Corredor amador, correu duas maratonas. Sem diabetes. Sem história de AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (89, 28, 4, '2021-08-23 17:00', 'consulta', 'Coração acelerado e cansaço nas corridas', 138, 88, 118, 88.0, 'Homem de 53 anos com palpitações irregulares e redução de rendimento nas corridas há 6 semanas, dispneia aos esforços moderados. ECG: fibrilação atrial com resposta ventricular de 118 bpm. ECO: átrio esquerdo 44 mm, FEVE 57%, sem valvopatia. TSH normal. CHA2DS2-VASc 1 (HAS). Início dos sintomas incerto, provavelmente há mais de 48h. Ao exame: RCR irregular, sem sopros, MV+ sem RA, sem edema. HD: FA persistente sintomática de primeiro episódio.', 'Estratégia de controle de ritmo. Anticoagular com rivaroxabana 20 mg por pelo menos 3 semanas antes da cardioversão elétrica eletiva. Iniciar metoprolol succinato 50 mg para controle da frequência. Orientado a reduzir álcool. Retorno em 3 semanas para CVE.'),
  (90, 28, 4, '2021-10-18 07:30', 'internacao', 'Internação para cardioversão elétrica', 130, 82, 92, 87.0, 'Após 8 semanas de anticoagulação contínua e sem falhas, ainda em FA, FC 92 bpm com metoprolol. ETE para descartar trombo atrial: sem trombos em apêndice atrial esquerdo, contraste espontâneo discreto. Realizada cardioversão elétrica sincronizada sob sedação com 150 J bifásico em choque único, com reversão a ritmo sinusal. ECG pós: ritmo sinusal, 66 bpm, sem pausas. Sem complicações. Alta no mesmo dia.', 'Manter rivaroxabana por pelo menos 4 semanas e depois seguir conforme risco; manter metoprolol 50 mg. Amiodarona 200 mg/dia por 3 meses para manter o ritmo sinusal. Orientado a evitar álcool excessivo e corrida de alta intensidade por 1 semana. Retorno em 30 dias.'),
  (91, 28, 4, '2022-02-14 17:20', 'retorno', 'A palpitação voltou depois do carnaval', 136, 86, 112, 88.5, 'Recidiva de FA há 10 dias, após fim de semana prolongado com muita bebida. Já tinha concluído amiodarona há 6 semanas. Rivaroxabana suspensa por conta própria no mês passado (''já estava curado''). Sintomático, dispneia aos esforços. ECG: FA com resposta de 112 bpm. Holter prévio: 4 episódios de FA paroxística de 2 a 6 horas. Ao exame: RCR irregular, sem sinais de congestão. HD: FA recorrente após cardioversão, ritmo sinusal não sustentado.', 'Retomar rivaroxabana 20 mg sem interrupção. Indicada ablação por cateter (isolamento de veias pulmonares) por FA sintomática recorrente. Abstinência alcoólica. Retomar amiodarona até o procedimento. Agendamento em 3 meses. Reforçado que o anticoagulante não é opcional após cardioversão.'),
  (92, 28, 4, '2022-05-23 07:00', 'internacao', 'Internação para ablação da fibrilação', 128, 80, 58, 85.0, 'Internado para ablação de FA, em uso de rivaroxabana ininterrupta e amiodarona. Em ritmo sinusal, FC 58 bpm. ETE pré-procedimento sem trombo. Realizado isolamento das quatro veias pulmonares por radiofrequência com mapeamento eletroanatômico, sem complicações, com bloqueio de entrada e saída confirmados. Sem derrame pericárdico ao ECO pós, punção femoral sem hematoma. Alta em 24h.', 'Manter rivaroxabana por pelo menos 2 meses após a ablação, independentemente do ritmo, e depois conforme risco. Suspender amiodarona em 6 semanas. Manter metoprolol e losartana. Retorno com ECG e Holter em 3 meses. Evitar álcool.');
