insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (28, '2023-04-30', 'abandonou', 'Submetido a ablação de FA em maio de 2022, sem complicações. Não compareceu ao retorno de três meses nem às consultas seguintes. Em ligação, referiu estar assintomático e ter parado todos os remédios por conta própria. Sem seguimento do ritmo, da anticoagulação ou da pressão desde agosto de 2022.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (29, 'Terezinha de Jesus Almeida Prado', 'F', '1963-08-19', 'Santos', 'SP', 'Cozinheira', 'Sopro cardíaco conhecido desde a juventude, sem acompanhamento. HAS leve com losartana 50 mg/dia. Não fuma. Dois filhos adultos, sustenta a casa. Trabalha em restaurante, em pé o dia todo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (93, 29, 1, '2020-02-24 08:30', 'consulta', 'Cansaço e batedeira, piorou nos últimos meses', 132, 70, 84, 68.0, 'Mulher de 56 anos com dispneia aos médios esforços, palpitações ocasionais e cansaço há 8 meses, que a obrigaram a reduzir o ritmo na cozinha. Ao exame: ictus desviado para a esquerda, sopro holossistólico 4+/6+ em foco mitral com irradiação para axila, B3, sem sinais de congestão. ECO transtorácico: prolapso do folheto posterior (P2) com insuficiência mitral grave excêntrica, diâmetro sistólico de VE 42 mm, FEVE 60%, átrio esquerdo aumentado (52 mm), PSAP 42 mmHg. HD: insuficiência mitral primária grave sintomática por prolapso.', 'Indicação de tratamento cirúrgico, preferencialmente plástica mitral. Solicitados cateterismo, doppler de carótidas e avaliação odontológica. Manter losartana 50 mg/dia. Discutir caso com o cirurgião. Orientada a retornar antes se ortopneia ou dispneia em repouso. Retorno em 30 dias.'),
  (94, 29, 12, '2020-06-15 14:00', 'retorno', 'Vim saber da cirurgia do coração', 128, 68, 88, 67.5, 'Avaliação cirúrgica. Persistem dispneia aos esforços e palpitações, agora com FA paroxística no Holter. Cateterismo: coronárias normais. ECO de reavaliação: DSVE 44 mm, FEVE 58% (limiar de disfunção), IM grave com jato excêntrico, anatomia favorável à plástica. Ao exame: sopro holossistólico mitral 4+/6+, sem edema, pulmões limpos. Escore STS baixo. Cirurgia indicada para evitar deterioração ventricular.', 'Plástica mitral com possível maze para FA. Como o serviço não realiza cirurgia mitral reparadora em volume suficiente, a paciente será transferida ao serviço de cirurgia cardíaca de referência, com relatório completo. Iniciar rivaroxabana 20 mg pela FA e manter losartana. Orientada sobre profilaxia de endocardite.');
