insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (29, '2020-06-15', 'transferido', 'Insuficiência mitral primária grave sintomática com FA paroxística, com indicação cirúrgica clara. Encaminhada a serviço de referência em cirurgia cardíaca para plástica mitral, com relatório e exames, e saiu do acompanhamento da rede. Medicamentos de transição prescritos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (30, 'Carolina Wanderley Aragão', 'F', '1994-04-22', 'Recife', 'PE', 'Fisioterapeuta', 'Palpitações súbitas desde a adolescência, 2 a 3 episódios por ano, com duração de minutos e término súbito. Sem cardiopatia conhecida. Consome café em excesso. Pratica corrida. Nega drogas ou anabolizantes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (95, 30, 6, '2022-01-08 23:50', 'pronto_socorro', 'Coração disparou de repente, não para', 104, 66, 186, 58.0, 'Pcte 27 anos com início súbito de palpitação taquicárdica há 50 min durante um plantão, com dor torácica leve e sensação de desmaio. Sem história de síncope franca. ECG: taquicardia regular de QRS estreito a 186 bpm, sem ondas P visíveis. Manobra vagal (Valsalva modificado) sem sucesso. Realizada adenosina 6 mg em bolus com reversão para ritmo sinusal em segundos. ECG pós: ritmo sinusal 78 bpm, intervalo PR curto e onda delta em derivações inferiores. HD: TSV por reentrada com pré-excitação ventricular (padrão de Wolff-Parkinson-White).', 'Observação por 4h sem recidiva. Alta com orientação de evitar cafeína e energéticos. Encaminhada à arritmologia para estudo eletrofisiológico. Contraindicados betabloqueador e verapamil sem avaliação especializada, e atenção ao risco de FA pré-excitada. Retornar ao PS se palpitação sustentada.'),
  (96, 30, 4, '2022-02-14 10:00', 'consulta', 'Vim para saber se tenho que fazer cirurgia', 110, 68, 72, 58.4, 'Assintomática desde o PS. ECG de repouso: pré-excitação ventricular com PR de 104 ms e onda delta em DII, DIII, aVF, sugerindo via acessória posteroseptal direita. ECO normal (FEVE 64%, sem cardiopatia estrutural, sem anomalia de Ebstein). Holter: pré-excitação intermitente, sem arritmias. Teste ergométrico: perda abrupta da pré-excitação a 130 bpm, indicando via de risco menor. Ao exame: RCR 2T BNF sem sopros. HD: Wolff-Parkinson-White com TSV sintomática, tratamento definitivo por ablação indicada.', 'Opção entre antiarrítmicos e ablação por cateter. A paciente prefere resolver de forma definitiva, e a ablação tem taxa de sucesso acima de 95%. Estudo eletrofisiológico com ablação agendado para abril. Evitar cafeína. Sem indicação de medicamento regular por ora.'),
  (97, 30, 4, '2022-04-11 07:00', 'internacao', 'Ablação da via acessória', 112, 70, 74, 58.0, 'Realizado estudo eletrofisiológico sob sedação: via acessória posteroseptal direita com condução anterógrada e retrógrada, TSV ortodrômica induzida com facilidade. Ablação por radiofrequência com perda imediata da pré-excitação após o segundo aplicativo, sem reinduzibilidade da taquicardia, inclusive sob isoproterenol. Sem BAV, sem derrame pericárdico no ECO pós. Punção venosa femoral sem hematoma. ECG pós: PR 148 ms, sem onda delta.', 'Alta no mesmo dia, repouso relativo por 48h e evitar esforço físico por 1 semana. Sem medicamentos de uso contínuo. Retorno em 3 meses com ECG. Retornar ao PS em caso de palpitações sustentadas ou dor torácica.'),
  (98, 30, 4, '2022-07-04 10:30', 'retorno', 'Estou bem, sem palpitação nenhuma', 108, 66, 64, 58.6, 'Quase 3 meses depois da ablação, sem nenhum episódio de palpitação, tolerando corridas de 8 km. Voltou a tomar café com moderação. ECG: ritmo sinusal, PR 150 ms, sem pré-excitação. Holter 24h: sem taquiarritmias. Ao exame: RCR 2T BNF, sem sopros, sem edema, punção sem alterações.', 'Cura clínica do WPW por ablação. Alta da arritmologia. Orientada a procurar atendimento se palpitações voltarem. Sem restrições à atividade física. Acompanhamento cardiológico opcional anual.');
