insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (30, '2022-07-04', 'melhorou', 'Wolff-Parkinson-White com taquicardia por reentrada curado por ablação de via acessória posteroseptal direita, sem recorrência em três meses. Voltou a correr sem sintomas, sem necessidade de medicamentos e com alta da arritmologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (31, 'Priscila Helena Fontoura', 'F', '1981-09-09', 'São José dos Campos', 'SP', 'Professora universitária', 'HAS há 8 anos, obesidade grau III (IMC 41) desde os 25 anos, SAHOS leve sem tratamento. Em uso de losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg. Candidata a cirurgia bariátrica. Sedentária, compulsão alimentar noturna. Mãe com DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (99, 31, 1, '2021-10-04 14:30', 'consulta', 'Avaliação cardiológica antes da bariátrica', 148, 94, 86, 112.0, 'Mulher de 40 anos, obesa grau III, hipertensa em uso de três fármacos com PA ainda acima da meta. Cirurgia bariátrica (gastrectomia vertical) marcada para novembro. Sem dor torácica, dispneia leve a esforços médios, ronco. Ao exame: IMC 41, circunferência abdominal 118 cm, RCR 2T BNF, sem sopros, MV+ sem RA, edema de tornozelos 1+/4+. ECG: sinusal, sem SVE. ECO: FEVE 64%, HVE leve, átrio esquerdo normal. Glicemia 96 mg/dL, creatinina 0,8 mg/dL, potássio 4,2 mEq/L. Risco cirúrgico cardiovascular baixo a intermediário.', 'Liberada para cirurgia bariátrica sob cuidados habituais. Manter losartana, anlodipino e hidroclorotiazida até o dia da cirurgia, mas orientada a procurar a equipe se pressão baixa após emagrecimento rápido. Reavaliar em 4 meses para ajuste de medicações. Reforçar que a perda de peso costuma reduzir a PA.'),
  (100, 31, 1, '2022-02-21 14:30', 'retorno', 'Estou meio fraca e com a pressão baixa', 106, 64, 78, 84.0, 'Quatro meses depois da gastrectomia vertical, perdeu 28 kg (peso 84 kg, IMC 30,8). Queixa-se de tontura ao se levantar e cansaço, com PA domiciliar entre 98x60 e 110x68 mmHg. Dieta fracionada, ingere pouca água. Ao exame: PA sentada 106x64 e em pé 98x60 mmHg, sem edema, pulmões limpos. Sódio 135 mEq/L, potássio 3,6 mEq/L, creatinina 0,8 mg/dL. HD: hipotensão sintomática por perda ponderal e polifarmácia anti-hipertensiva.', 'Suspender hidroclorotiazida e anlodipino. Manter apenas losartana 50 mg ao dia e reavaliar. Aumentar a ingestão de líquidos conforme orientação da nutrição. Repetir sódio, potássio e creatinina em 2 semanas. MRPA semanal. Retorno em 60 dias.'),
  (101, 31, 1, '2022-09-19 14:40', 'retorno', 'Pressão normal, queria saber se posso parar o remédio', 112, 70, 68, 72.5, 'Dez meses de pós-operatório, perda total de 39,5 kg (peso 72,5 kg, IMC 26,6). Sem tontura, sem sintomas, energia melhor, caminha 45 minutos diariamente. Ronco desapareceu. MRPA com média de 110x68 mmHg usando losartana 50 mg. Ao exame: PA 112x70 mmHg, sem edema. Creatinina 0,7 mg/dL, K 4,3 mEq/L, glicemia 84 mg/dL, LDL 88 mg/dL. HD: HAS controlada com perda de peso e doses mínimas.', 'Suspender losartana em teste, com MRPA duas vezes por semana por 8 semanas; retomar se média ≥ 130x80. Manter nutrição, suplementação vitamínica e atividade física. Retorno em 3 meses com MRPA.');
