insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (31, '2022-09-19', 'melhorou', 'Após gastrectomia vertical e perda de quase 40 kg, os três anti-hipertensivos foram reduzidos até a suspensão em teste. PA domiciliar média de 110x68 mmHg, sem medicamentos, sem ronco e com melhora do condicionamento. Segue em monitorização domiciliar e retorno trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (32, 'Plínio Cavalcanti Rangel', 'M', '1958-04-14', 'Piracicaba', 'SP', 'Engenheiro agrônomo aposentado', 'HAS há 14 anos tratada com losartana 50 mg 12/12h e anlodipino 5 mg. Colesterol limítrofe. Pratica caminhada e jardinagem. Tende a ficar tenso em consultórios médicos. Pai com HAS e AVC aos 72 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (102, 32, 2, '2022-02-07 10:00', 'consulta', 'Na consulta a pressão sempre sobe, em casa é normal', 152, 90, 78, 79.0, 'Homem de 63 anos, assintomático, HAS tratada com dois fármacos. Mede a PA em casa com aparelho de braço (validado) e traz registros de 118-130x70-82 mmHg, mas no consultório ela sempre passa de 150x90, o que levou a tentativas de intensificação por outros médicos, com um episódio de tontura há 2 meses. Ao exame: ansioso, PA 152x90 mmHg (medida 1) e 148x88 (medida 3), RCR 2T BNF, sem sopros, MV+ sem RA, sem edema. Creatinina 1,0 mg/dL, potássio 4,3 mEq/L, LDL 128 mg/dL. HD: efeito do avental branco em hipertenso tratado; possível risco de supertratamento.', 'Não intensificar o tratamento. Solicitado MRPA padronizado de 7 dias e MAPA 24h para confirmar. Manter losartana 50 mg 12/12h e anlodipino 5 mg. Orientado a mostrar o aparelho na próxima consulta para validar a técnica. Retorno em 30 dias.'),
  (103, 32, 2, '2022-03-14 10:10', 'retorno', 'Trouxe o MRPA e a MAPA', 146, 86, 74, 78.8, 'Trouxe MRPA de 7 dias com média de 122x74 mmHg (28 medidas válidas) e MAPA 24h com média de 120x72 mmHg, vigília 124x76 e sono 108x64, com descenso noturno preservado. O aparelho domiciliar, testado no consultório, tem diferença de 3 mmHg em relação ao esfigmomanômetro. PA de consultório de novo 146x86. Assintomático. Ao exame: RCR 2T BNF, sem sopros, sem edema.', 'HAS controlada fora do consultório. Manter losartana e anlodipino sem aumento de dose. As decisões terapêuticas devem se basear em MRPA ou MAPA. Atividade física regular e dieta. LDL 128 mg/dL: solicitado escore de cálcio coronariano para decidir estatina. Retorno em 6 meses com MRPA.'),
  (104, 32, 2, '2022-09-12 10:00', 'retorno', 'Retorno semestral, tudo bem', 142, 84, 72, 78.0, 'Paciente bem, MRPA com média de 120x72 mmHg. Escore de cálcio coronariano 38 (percentil 60), sem estenose. PA de consultório 142x84 mmHg novamente alta, com a mesma tensão de sempre. Sem tontura, sem edema. Atividade física 4x por semana. LDL 124 mg/dL, creatinina 1,0 mg/dL, glicemia 94 mg/dL.', 'Manter a mesma terapia, pois o controle fora do consultório está na meta. Iniciar rosuvastatina 10 mg dada a presença de cálcio coronariano e risco intermediário. Repetir lipídios em 3 meses. Retorno em 6 meses com MRPA.');
