insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (32, '2022-09-12', 'controlado', 'A PA elevada no consultório era efeito do avental branco em paciente já tratado. MRPA e MAPA mostraram controle na meta com losartana e anlodipino, evitando intensificação desnecessária e risco de hipotensão. Foi acrescentada estatina pelo escore de cálcio. Segue em retornos semestrais com MRPA.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (33, 'Eunice Maria Cardoso Bastos', 'F', '1955-05-28', 'Goiânia', 'GO', 'Aposentada (ex-merendeira)', 'HAS há 30 anos, em uso irregular de losartana e hidroclorotiazida. Diabetes não. Obesidade. Come muito embutido e caldo industrializado. Havia ficado 2 semanas sem receber os remédios do posto por falta na farmácia. Dois filhos vivem na mesma casa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (105, 33, 6, '2023-06-17 03:20', 'pronto_socorro', 'Acordei sem ar, afogada', 238, 128, 118, 86.0, 'Pcte 68 anos, chegou por SAMU sentada, taquipneica, com tosse e escarro espumoso róseo, iniciada há 2h, após jantar muito salgado e 2 semanas sem anti-hipertensivo. SpO2 82% em ar ambiente, FR 34 irpm, sudorese fria. Ao exame: PA 238x128 mmHg, estertores até ápices, B3, sem sopros importantes, edema 1+/4+. ECG: taquicardia sinusal, SVE com strain, sem supra de ST. Troponina 62 ng/L (discreta elevação, tipo 2). Creatinina 1,3 mg/dL. HD: edema agudo de pulmão hipertensivo (flash pulmonary edema), emergência hipertensiva.', 'Sentada, O2 suplementar e ventilação não invasiva com CPAP. Nitroglicerina EV em infusão contínua com titulação, furosemida 40 mg EV, monitorização contínua. Redução imediata da pós-carga, alvo de queda de 25% na primeira hora. Ingresso na UTI. ECO à beira leito e investigação de isquemia e estenose de artéria renal.'),
  (106, 33, 14, '2023-06-19 09:00', 'internacao', 'Melhor, já sem falta de ar', 138, 80, 82, 82.5, 'D2 de EAP hipertensivo. Desmamada da VNI no D1, sem O2 hoje (SpO2 96% em ar ambiente). Perdeu 3,5 kg com diurese. Nitroglicerina suspensa e iniciados losartana e anlodipino VO. PA 138x80 mmHg. Pulmões com raros estertores em bases, sem B3, edema discreto. ECO: FEVE 58% (preservada), HVE concêntrica importante (septo 15 mm), disfunção diastólica grau II, IM leve. Doppler de artérias renais sem estenose. Coronarianas sem isquemia: troponina estável, sem alterações dinâmicas. Creatinina 1,1 mg/dL.', 'Transferir à enfermaria e programar alta em 48h. Iniciar losartana 50 mg 12/12h, anlodipino 10 mg, clortalidona 12,5 mg e furosemida 40 mg. Educação sobre sal e adesão. Contato com o posto para garantir fornecimento. ECO e MAPA ambulatoriais. Retorno em 14 dias.'),
  (107, 33, 1, '2023-07-31 09:30', 'retorno', 'Retorno pós-internação, sem falta de ar', 130, 78, 72, 80.0, 'Sete semanas após o EAP, tomando os remédios todos os dias com o auxílio dos filhos, que organizam uma caixinha. Diminuiu o sal e parou de usar caldo industrializado. Sem ortopneia, sem edema, caminha 20 minutos. MAPA: média 24h de 126x76 mmHg. K 4,1 mEq/L, creatinina 1,1 mg/dL, NT-proBNP 340 pg/mL. Ao exame: pulmões limpos, sem estase jugular, RCR 2T BNF sem sopros.', 'Meta quase atingida. Manter esquema atual, suspender furosemida pelo euvolemia e adicionar espironolactona 25 mg/dia pela disfunção diastólica, a avaliar K e creatinina em 1 semana. Retorno em 60 dias. Orientada a ir ao PS se ortopneia ou PA acima de 180x110.');
