insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (33, '2023-07-31', 'melhorou', 'Edema agudo de pulmão hipertensivo por abandono do tratamento e sobrecarga de sal, tratado com ventilação não invasiva e nitroglicerina, sem isquemia nem estenose renal. Após seis semanas, assintomática, com PA na meta pela MAPA e NT-proBNP baixo, com adesão supervisionada pelos filhos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (34, 'Hélio Shigueo Nakamura', 'M', '1967-11-30', 'São Paulo', 'SP', 'Taxista', 'HAS há 15 anos sem acompanhamento regular, com uso intermitente de captopril e hidroclorotiazida. Obeso grau I. Passa 12 horas por dia no carro, dieta irregular. Pai hipertenso falecido de AVC. Ex-tabagista há 10 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (108, 34, 2, '2021-09-06 09:30', 'consulta', 'Cansaço ao subir escada e eletrocardiograma alterado no exame admissional', 164, 100, 76, 94.0, 'Homem de 53 anos, hipertenso crônico mal controlado, assintomático, apenas com cansaço aos esforços. Exame admissional mostrou alterações de ECG. Ao exame: IMC 31, B4, sem sopros, MV+ sem RA, sem edema. ECG: SVE com strain em V5-V6 (Sokolow-Lyon 42 mm). ECO: septo de 16 mm, parede posterior de 15 mm, massa ventricular esquerda aumentada (155 g/m²), FEVE 62%, disfunção diastólica grau I, sem obstrução em via de saída. Albuminúria 38 mg/g. HD: cardiopatia hipertensiva com HVE concêntrica, sem insuficiência cardíaca.', 'Diferenciar de cardiomiopatia hipertrófica com ressonância cardíaca (aguardar). Iniciar losartana 100 mg/dia e anlodipino 5 mg, foco em regressão da HVE. Meta PA < 130/80. Perda de 5 a 8 kg e dieta com baixo sódio. Repetir creatinina e potássio em 2 semanas. Retorno em 45 dias.'),
  (109, 34, 2, '2022-01-24 09:40', 'retorno', 'Retorno com ressonância', 140, 88, 72, 91.8, 'Uso regular de losartana e anlodipino, MRPA com média de 138x86 mmHg. Perdeu 2,2 kg. Ressonância cardíaca: HVE concêntrica simétrica (espessura máxima 16 mm), sem realce tardio por gadolínio, sem obstrução, compatível com cardiopatia hipertensiva, afastando CMH. Troponina negativa. Albuminúria 26 mg/g, creatinina 1,0 mg/dL, K 4,4 mEq/L. Ao exame: PA 140x88 mmHg, RCR 2T BNF, B4.', 'Acrescentar clortalidona 12,5 mg/dia para atingir a meta, por HVE. Manter losartana 100 mg e anlodipino 5 mg. Reduzir sal, mais caminhadas (taxista com pausas). Dosar K e creatinina em 2 semanas. Retorno em 60 dias.'),
  (110, 34, 2, '2023-02-13 09:30', 'retorno', 'Estou bem, queria ver o coração de novo', 126, 78, 70, 88.0, 'Um ano de tratamento, MRPA com média de 124x76 mmHg, adesão confirmada pelo pill count. Perdeu 6 kg e faz pausas para caminhar no trabalho. Sem edema, sem dispneia. ECO de controle: septo 13 mm, parede posterior 12 mm, massa 118 g/m² (redução de 24%), FEVE 64%. ECG: redução do índice de Sokolow-Lyon para 32 mm. Albuminúria 12 mg/g. Potássio 4,2 mEq/L, sódio 138 mEq/L, creatinina 1,0 mg/dL.', 'Regressão da HVE com controle pressórico. Manter losartana, anlodipino e clortalidona. Rever anualmente o ECO e a albuminúria. Reforçar MEV e perda de peso. Retorno em 6 meses.');
