insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (34, '2023-02-13', 'controlado', 'Cardiopatia hipertensiva com HVE concêntrica, diferenciada de cardiomiopatia hipertrófica por ressonância. Com três fármacos e perda de peso, PA de 126x78 mmHg, redução de 24% da massa ventricular e albuminúria normalizada. Sem insuficiência cardíaca. Segue em retornos semestrais.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (35, 'Osmar Peixoto de Lima', 'M', '1946-02-03', 'Bauru', 'SP', 'Aposentado (ex-ferroviário)', 'HAS há 40 anos e DM2 há 15 anos, ambos com controle irregular. Ex-tabagista pesado. Evita médicos e achou que a dor no peito ''era azia''. Mora com a esposa idosa em sítio a 30 km da cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (111, 35, 6, '2022-09-24 14:10', 'pronto_socorro', 'Dor no peito e na barriga desde anteontem, agora falta de ar', 92, 58, 110, 78.0, 'Pcte 76 anos com dor epigástrica e retroesternal em queimação há 36h, tratou com antiácido, procurou o PS por piora súbita da dispneia. Ao exame: pálido, sudoreico, hipotenso, estertores até ⅔ dos campos, B3 e novo sopro holossistólico 4+/6+ em borda esternal esquerda com frêmito. ECG: supra de ST inferior (DII, DIII, aVF) com Q patológica, BAV 1º grau. Troponina 18.000 ng/L. ECO: infarto inferior com ruptura do septo interventricular (comunicação de 12 mm), shunt E-D, FEVE 40%, VD hipocinético. HD: IAMCSST inferior com tardia apresentação complicado por CIV pós-infarto e choque cardiogênico (Killip IV).', 'Droga vasoativa (norepinefrina), furosemida EV, tentativa de estabilização com balão intra-aórtico e transferência imediata à UTI. Cirurgia cardíaca avaliada com urgência. Cateterismo antes de cirurgia se estável. Esposa informada do risco muito elevado, com mortalidade acima de 50%.'),
  (112, 35, 14, '2022-09-26 09:00', 'internacao', 'Choque cardiogênico em UTI', 88, 52, 104, 77.0, 'D3 de IAMCSST inferior com CIV pós-infarto em UTI. Em uso de norepinefrina, dobutamina e balão intra-aórtico, com lactato 4,2 mmol/L e oligúria, creatinina 2,1 mg/dL. Cateterismo: oclusão da CD proximal (culpada), DA com lesão de 60% e Cx de 50%; sem condições de ATC no momento. Mantém hipotensão, sem recuperação com suporte máximo, mas com estabilização hemodinâmica suficiente para tentar a cirurgia. Intubado no D2 por insuficiência respiratória.', 'Discussão em Heart Team: cirurgia de fechamento da CIV com ponte de safena para CD. Consentimento da esposa e dos filhos após conversa franca sobre risco. Manter suporte ventilatório, balão e inotrópico até a cirurgia. Antibioticoterapia profilática. Preparo para o centro cirúrgico.'),
  (113, 35, 12, '2022-09-30 08:00', 'internacao', 'Pós-operatório imediato de fechamento da CIV', 90, 50, 112, 79.5, 'Pós-operatório imediato de correção da CIV pós-infarto (patch de pericárdio bovino) e ponte de safena para CD, CEC de 148 minutos. Saiu do centro cirúrgico em uso de noradrenalina, adrenalina e balão intra-aórtico, ventilação mecânica, com sangramento pelos drenos de 450 mL nas primeiras 4h e coagulopatia. Anúria desde o pós-operatório. Lactato 7,8 mmol/L. ECO: shunt residual pequeno, FEVE 30%, disfunção grave de VD. Necessita hemodiálise de urgência.', 'Hemodiálise contínua, reposição de hemoderivados, controle de sangramento. Manter suporte inotrópico e vasopressor máximo. Discutidos limites terapêuticos com a família, que mantém suporte pleno. Reavaliação em 12h. Cuidados paliativos envolvidos na decisão, sem mudança de conduta no momento.');
