insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (35, '2022-10-04', 'obito', 'Infarto inferior de apresentação tardia, complicado por ruptura do septo interventricular e choque cardiogênico. Submetido a correção cirúrgica e revascularização, evoluiu com síndrome de baixo débito, falência renal e de VD refratárias ao suporte. Faleceu na UTI em 04/10/2022, com a família presente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (36, 'Vera Lúcia Cantarelli', 'F', '1964-02-17', 'Taubaté', 'SP', 'Vendedora de loja de calçados', 'Cardiomiopatia dilatada idiopática diagnosticada há 2 anos, em uso de enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h com titulação difícil por hipotensão. Etilismo moderado no passado, abstêmica há 5 anos. HAS leve prévia. Dois filhos, mora com a mãe idosa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (114, 36, 11, '2023-01-23 09:00', 'consulta', 'Cansaço, quase não consigo subir a escada da loja', 96, 60, 92, 64.0, 'Mulher de 58 anos com cardiomiopatia dilatada e ICFEr, NYHA III, dispneia aos pequenos esforços, ortopneia de 2 travesseiros, edema vespertino e plenitude pós-prandial. Ao exame: PA 96x60 mmHg, pulso fino, estase jugular a 45°, B3, sopro sistólico mitral 3+/6+, estertores bibasais, hepatomegalia discreta, edema 2+/4+. ECG: ritmo sinusal, BRE com QRS de 164 ms. ECO: FEVE 24%, DDVE 70 mm, insuficiência mitral funcional moderada, TAPSE 14 mm. NT-proBNP 5.600 pg/mL, Na 134 mEq/L, creatinina 1,3 mg/dL (TFGe 46). HD: ICFEr NYHA III com BRE, perfil quente e congesto.', 'Substituir enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36h, vigiando PA. Acrescentar dapagliflozina 10 mg e espironolactona 12,5 mg, mantendo carvedilol 6,25 mg 12/12h. Aumentar furosemida para 40 mg 12/12h. Indicação de ressincronização (TRC-D): encaminhar para avaliação e ECO. Pesagem diária. Retorno em 3 semanas.'),
  (115, 36, 11, '2023-04-17 09:20', 'retorno', 'Melhorei um pouco, mas sinto tontura e fraqueza', 88, 54, 88, 61.0, 'Três meses depois, sem internação. NYHA III. A PA fica entre 84x52 e 94x58 mmHg, com tontura aos levantar, o que impediu a titulação de sacubitril/valsartana e do carvedilol. Sem síncope. Ao exame: sem estase jugular importante, estertores raros, edema discreto. NT-proBNP 3.900 pg/mL. K 4,7 mEq/L, creatinina 1,4 mg/dL. Avaliação para TRC-D em andamento, ainda sem data de implante por fila de espera do hospital de referência.', 'Reduzir carvedilol para 3,125 mg 12/12h pela hipotensão e bradicardia relativa; manter sacubitril/valsartana 24/26 mg. Furosemida 40 mg pela manhã. Orientado a evitar ortostase súbita. Aguardar data do TRC-D. Retorno em 30 dias, ou antes se piora da dispneia ou ganho de peso > 2 kg.'),
  (116, 36, 6, '2023-10-29 01:15', 'pronto_socorro', 'Acordei sem ar e com o coração muito rápido', 84, 52, 138, 66.0, 'Pcte com ICFEr avançada chega com dispneia em repouso, tosse e ortopneia, com piora há 10 dias após infecção respiratória. Ganhou 5 kg. Ao exame: pálida, extremidades frias, perfusão lenta, estase jugular a 90°, B3, estertores até ápices, hepatomegalia, edema 3+/4+. SpO2 89% em ar ambiente. ECG: fibrilação atrial de início recente com resposta de 138 bpm e BRE. Lactato 3,1 mmol/L, creatinina 1,9 mg/dL, NT-proBNP 14.000 pg/mL, K 5,1 mEq/L. HD: IC avançada descompensada (perfil frio e úmido) com FA de alta resposta.', 'Internação em UTI. Suspender sacubitril/valsartana e espironolactona pela hipotensão e injúria renal. Furosemida EV, dobutamina em baixa dose, amiodarona EV para controle de ritmo. Anticoagulação com heparina. Cardioversão elétrica se instabilidade. Discutir com a família a gravidade e a possibilidade de dispositivos ou suporte avançado.');
