insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (36, '2024-01-15', 'piorou', 'Cardiomiopatia dilatada com FEVE de 24% e BRE evoluiu com hipotensão que impediu a titulação das drogas, FA nova e internação em baixo débito. Aguarda TRC-D, sem data, e avaliação para terapias avançadas. Mantém classe funcional III-IV, com segunda internação em três meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (37, 'Aldo Giovanni Ferrante', 'M', '1950-01-25', 'São Bernardo do Campo', 'SP', 'Metalúrgico aposentado', 'HAS há 25 anos, em uso de losartana 50 mg 12/12h e hidroclorotiazida 25 mg. DPOC leve por tabagismo antigo (50 maços-ano, parou há 15 anos). Dislipidemia. Sedentário, caminha pouco por falta de fôlego.', 'Alergia a AAS (broncoespasmo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (117, 37, 6, '2022-04-09 11:30', 'pronto_socorro', 'Coração disparado e cansaço há dois dias', 128, 80, 148, 81.0, 'Pcte 72 anos com palpitações regulares e fadiga há 2 dias, sem dor torácica nem síncope. Ao exame: FC 148 bpm regular, PA 128x80 mmHg, SpO2 93% em ar ambiente, sibilos esparsos, sem sinais de IC. ECG: taquicardia regular de QRS estreito com ondas F em serrilha em DII, DIII e aVF a 300 bpm de frequência atrial e condução AV 2:1 (FC 148). Troponina negativa, K 4,0 mEq/L, TSH normal. CHA2DS2-VASc 2 (idade 65-74 anos e HAS). HD: flutter atrial típico com condução 2:1.', 'Controle de frequência com metoprolol succinato 50 mg/dia, com cuidado pelo DPOC leve (sibilos esparsos). Anticoagulação com apixabana 5 mg 12/12h. Programada cardioversão elétrica eletiva, ou ablação do istmo cavotricuspídeo, com a arritmologia. Internação não necessária neste momento. Alta com retorno em 3 dias.'),
  (118, 37, 4, '2022-04-12 08:00', 'internacao', 'Ablação do flutter', 126, 78, 110, 80.5, 'Mantém flutter atrial típico, FC média 110 bpm com metoprolol, em apixabana há 3 dias. Estudo eletrofisiológico: flutter dependente do istmo cavotricuspídeo anti-horário, com ciclo de 240 ms. Realizada ablação por radiofrequência do istmo com bloqueio bidirecional confirmado, com reversão a ritmo sinusal durante o procedimento. Sem complicações; punção femoral sem hematoma. ECG pós: ritmo sinusal 72 bpm.', 'Alta em 24h. Continuar apixabana, pois o risco de FA futura persiste e CHA2DS2-VASc é 2. Manter metoprolol succinato 25 mg/dia e anti-hipertensivos. Retorno em 3 meses com Holter para pesquisa de FA. Orientado a procurar atendimento se palpitações.'),
  (119, 37, 4, '2022-07-18 09:00', 'retorno', 'Sem palpitação, mais disposto', 134, 80, 66, 81.5, 'Três meses depois da ablação, sem recorrência de palpitações, mais disposto. Holter 24h: ritmo sinusal, sem flutter nem FA, extrassístoles supraventriculares raras. Sem sangramentos com a apixabana. Hemoglobina 14,2 g/dL, creatinina 1,0 mg/dL. Ao exame: RCR 2T BNF, MV+ com sibilos raros, sem edema. PA 134x80 mmHg.', 'Manter apixabana 5 mg 12/12h (risco de FA futura em hipertenso de 72 anos). Metoprolol pode ser suspenso, se PA permitir, após avaliação. Reforçar vacinação para influenza e pneumococo. Retorno em 6 meses com Holter de 7 dias.');
