insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (37, '2022-07-18', 'controlado', 'Flutter atrial típico tratado com ablação do istmo cavotricuspídeo, sem recorrência no Holter três meses depois. Mantém anticoagulação por apixabana pelo risco de FA futura e controle pressórico com losartana e hidroclorotiazida. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (38, 'Neide Aparecida Ramos Cordeiro', 'F', '1970-05-21', 'Araraquara', 'SP', 'Auxiliar de enfermagem', 'Febre reumática na infância, com surtos repetidos e sem profilaxia regular com penicilina benzatina. Sopro cardíaco conhecido. Trabalha em plantões de 12 horas. Duas gestações na juventude, sem complicações. Sem HAS ou DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (120, 38, 1, '2022-07-04 08:30', 'consulta', 'Falta de ar nos plantões e coração acelerado', 118, 72, 96, 66.0, 'Mulher de 52 anos com dispneia aos médios esforços, palpitações e tosse noturna há 6 meses, que a obrigaram a pedir transferência de setor. Ao exame: ritmo irregular, hiperfonese de B1, estalido de abertura mitral e ruflar diastólico 3+/6+ em foco mitral, estertores em bases. ECG: fibrilação atrial, FC 96 bpm. ECO: estenose mitral reumática moderada a grave (área valvar 1,1 cm² por planimetria, gradiente médio 10 mmHg), AE 54 mm, PSAP 48 mmHg, FEVE 62%, valva com escore de Wilkins de 7. Sem trombo no AE à ETE. HD: estenose mitral reumática com FA e hipertensão pulmonar.', 'Anticoagular com varfarina (alvo de INR 2-3), pois DOAC não é indicado na estenose mitral moderada a grave. Iniciar metoprolol succinato 50 mg para controle de frequência. Indicada valvuloplastia mitral percutânea por balão (anatomia favorável). Profilaxia secundária com penicilina benzatina 1.200.000 UI IM a cada 21 dias. Orientações dos sinais de alarme.'),
  (121, 38, 10, '2022-09-12 07:30', 'internacao', 'Valvuloplastia mitral percutânea', 114, 70, 78, 65.5, 'Internada com INR 2,4 após suspensão programada da varfarina e transição com enoxaparina. FA com FC controlada. Realizada valvuloplastia mitral percutânea com balão de Inoue pela técnica transeptal, sem intercorrências. Área valvar pós-procedimento 1,9 cm², gradiente médio de 5 mmHg, sem insuficiência mitral relevante (grau I). Sem derrame pericárdico ao ECO. Punção femoral sem hematoma. PSAP 32 mmHg.', 'Alta no D2. Reintroduzir varfarina em associação com enoxaparina até INR ≥ 2. Manter metoprolol e penicilina benzatina. Controle de INR semanal no primeiro mês. ECO de controle em 3 meses. Retorno ambulatorial em 6 meses.'),
  (122, 38, 1, '2023-03-13 08:30', 'retorno', 'Voltei a trabalhar normalmente', 116, 70, 72, 66.4, 'Seis meses depois da valvuloplastia, NYHA I-II, sem dispneia nos plantões, voltou ao setor de internação. Mantém FA persistente com FC controlada. INR na faixa terapêutica em 80% dos exames, hoje 2,7, sem sangramentos. Adesão à penicilina benzatina quinzenal, às vezes atrasa a aplicação por conta dos plantões. ECO: área mitral 1,8 cm², gradiente médio 6 mmHg, PSAP 34 mmHg, AE 52 mm. Ao exame: ruflar diastólico discreto, pulmões limpos.', 'Manter varfarina com alvo de INR 2-3, metoprolol e penicilina benzatina a cada 21 dias (vai combinar as injeções na UBS do hospital). Controle de INR mensal. ECO a cada 12 meses. Discutir ablação ou controle de ritmo se piora dos sintomas. Retorno em 6 meses.');
