insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (38, '2023-03-13', 'melhorou', 'Estenose mitral reumática moderada a grave com FA tratada com valvuloplastia percutânea por balão, ganhando área valvar de 1,1 para 1,8 cm². Voltou ao trabalho sem dispneia, anticoagulada com varfarina e em profilaxia secundária com penicilina benzatina. Segue em controle de INR e ECO anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (39, 'Raquel Souza Bittencourt', 'F', '1982-12-03', 'Salvador', 'BA', 'Cirurgiã-dentista', 'Valva aórtica bicúspide diagnosticada há 8 anos, com insuficiência leve, sem acompanhamento regular. Fez tratamento de canal e extração de siso há 3 semanas, sem profilaxia antibiótica. Sem uso de drogas injetáveis. Sem comorbidades.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (123, 39, 6, '2024-05-11 16:40', 'pronto_socorro', 'Febre há duas semanas e cansaço', 118, 52, 108, 58.0, 'Pcte 41 anos com febre diária de 38,5 a 39 °C, sudorese noturna, adinamia e perda de 3 kg há 2 semanas, sem tosse. Ao exame: REG, febril, pálida, petéquias em conjuntiva e lesões de Janeway em palma, RCR 2T, sopro diastólico aspirativo 3+/6+ em foco aórtico (novo), pulso amplo. PA 118x52 mmHg (pressão de pulso alargada). Hemocultura (3 amostras) com crescimento de Streptococcus viridans. PCR 142 mg/L, leucocitose, VHS 90. ECO transtorácico: vegetação de 10 mm na valva aórtica bicúspide com insuficiência aórtica moderada. HD: endocardite infecciosa aguda por Streptococcus viridans em valva bicúspide.', 'Internação. Iniciar ceftriaxona 2 g EV 12/12h associada a gentamicina após coleta de hemoculturas. Solicitar ECO transesofágico, ressonância de crânio por possível embolia séptica e avaliação odontológica. Monitorização de ECG diária (PR), cirurgia cardíaca em sobreaviso. Retorno se piora.'),
  (124, 39, 1, '2024-05-14 09:00', 'internacao', 'Acompanhamento da endocardite em enfermaria', 112, 50, 92, 58.0, 'D4 de ceftriaxona. Afebril desde o 3º dia, hemoculturas de controle negativas. ETE: vegetação de 10 mm sem abscesso perivalvar, insuficiência aórtica moderada, sem fístula. Ressonância de crânio: pequenos focos embólicos corticais assintomáticos, sem hemorragia. PR 180 ms no ECG, sem BAV. Função renal normal, creatinina 0,7 mg/dL. Ao exame: sopro diastólico aspirativo 3+/6+ inalterado, sem sinais de IC, lesões de Janeway em regressão. Tolera bem a medicação.', 'Manter ceftriaxona 2 g EV 12/12h por 4 semanas no total (cepa sensível). Alta para tratamento em hospital-dia após D14. Extrações dentárias pendentes antes de cirurgia eletiva. Indicação cirúrgica apenas se IC, abscesso, vegetação > 10 mm com embolia ou persistência da bacteremia. ECO semanal.'),
  (125, 39, 1, '2024-08-19 10:00', 'retorno', 'Terminei o antibiótico, estou bem', 120, 56, 70, 60.0, 'Dois meses e meio do fim do tratamento, sem febre, ganhou 2 kg e voltou ao consultório. Sem dispneia. Ao exame: sopro diastólico aspirativo 2+/6+ aórtico, sem sinais de IC, sem lesões de pele. ECO: sem vegetação, insuficiência aórtica moderada estável, VE com DDVE de 54 mm e FEVE 62%. PCR 3 mg/L, VHS 12. Fez tratamento odontológico completo e profilaxia com amoxicilina antes dos procedimentos.', 'Cura clínica da endocardite. Profilaxia antibiótica obrigatória antes de procedimentos odontológicos (amoxicilina 2 g 1h antes). ECO a cada 6 meses para monitorar IAo e VE; avaliação cirúrgica quando houver sintomas, DSVE > 50 mm ou FEVE < 55%. Higiene bucal rigorosa. Retorno em 6 meses.');
