insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (39, '2024-08-19', 'melhorou', 'Endocardite por Streptococcus viridans em valva aórtica bicúspide, após procedimento odontológico sem profilaxia, tratada com 4 semanas de ceftriaxona sem necessidade de cirurgia. Hemoculturas negativas, ECO sem vegetação e insuficiência aórtica moderada estável, em seguimento semestral com profilaxia antes de procedimentos dentários.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (40, 'Adelmo Rodrigues Cardoso', 'M', '1955-08-12', 'Montes Claros', 'MG', 'Lavrador aposentado', 'Doença de Chagas conhecida há 20 anos, sem tratamento antiparasitário. HAS leve com captopril irregular. Nasceu e viveu em casa de pau a pique no norte de Minas. Já teve tonturas esporádicas, sem síncope. Tabagista de 20 maços-ano, parou há 10 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (126, 40, 4, '2020-11-09 09:00', 'consulta', 'Desmaiei na roça duas vezes essa semana', 158, 72, 38, 69.0, 'Homem de 65 anos com Chagas crônica, 2 episódios de perda súbita de consciência nesta semana, de segundos, com queda e escoriações, sem convulsão. Cansaço e tonturas há 1 mês. Ao exame: bradicárdico a 38 bpm, regular, B1 variável (ondas em canhão no pescoço), PA 158x72 mmHg, MV+ sem RA, sem edema. ECG: bloqueio atrioventricular total com escape ventricular a 38 bpm, BRD com HBAE de base, dissociação AV. ECO: FEVE 52%, aneurisma apical pequeno, sem trombo. HD: cardiopatia chagásica crônica com BAVT sintomático (síncope de Stokes-Adams).', 'Internação urgente para implante de marca-passo definitivo. Evitar betabloqueadores e antiarrítmicos. Sem benznidazol, pois a cardiopatia já está estabelecida. Monitor contínuo e pás transcutâneas de prontidão. Suspender captopril durante a instabilidade e reavaliar a PA depois do implante.'),
  (127, 40, 4, '2020-11-12 08:00', 'internacao', 'Marca-passo implantado, tudo certo', 138, 76, 72, 68.5, 'D1 de implante de marca-passo definitivo bicameral (DDD), sem intercorrências, via cefálica esquerda, com limiares adequados. Ritmo estimulado, FC 72 bpm. Sem hematoma de loja, sem pneumotórax ao Raio X de tórax. Sem síncope desde a internação. PA 138x76 mmHg. Aceitando dieta, deambulando. Orientado sobre cuidados com o MP em linguagem simples, esposa presente.', 'Alta amanhã. Cefalexina 500 mg 6/6h por 5 dias. Evitar elevação do braço esquerdo por 4 semanas. Retomar captopril 25 mg 12/12h para HAS. Interrogação do MP em 30 dias. Cartão do dispositivo entregue. Orientado a retornar se febre, dor ou tonturas.'),
  (128, 40, 4, '2021-02-22 09:30', 'retorno', 'Sem desmaio nenhum desde o aparelho', 136, 78, 70, 70.0, 'Três meses depois do implante, sem síncope, trabalhando na horta. Cicatriz limpa. Interrogação: pacing ventricular de 100%, limiares estáveis, sem taquiarritmias. Holter anterior sem TV. Dispneia leve aos grandes esforços, sem edema. ECO: FEVE 50%, aneurisma apical estável. PA 136x78 mmHg com captopril. Ao exame: RCR 2T BNF, sem congestão. Creatinina 1,0 mg/dL, K 4,5 mEq/L.', 'Substituir captopril por losartana 50 mg/dia por melhor tolerabilidade e posologia única. Programar interrogação semestral do MP. Avaliar necessidade de CDI se TV, síncope ou queda de FEVE. Holter anual. Anticoagulação não indicada (sem FA nem trombo). Retorno em 6 meses.'),
  (129, 40, 11, '2022-03-07 09:00', 'retorno', 'Estou bem, só um pouco de cansaço', 130, 76, 70, 70.8, 'Um ano depois, sem síncope, pequeno cansaço aos esforços intensos (NYHA II). Pacing 98% sem arritmias significativas. Holter: extrassístoles ventriculares isoladas, TV não sustentada de 4 batimentos uma vez. ECO: FEVE 46% (queda de 4 pontos), aneurisma apical sem trombo. NT-proBNP 480 pg/mL. Ao exame: sem estase jugular, pulmões limpos, sem edema. Creatinina 1,1 mg/dL.', 'Chagas com início de disfunção ventricular leve. Acrescentar bisoprolol 1,25 mg (cuidado: bradicardia já protegida por MP) e espironolactona 25 mg. Manter losartana 50 mg. Controlar K e creatinina em 2 semanas. Seguimento de arritmia em 6 meses, avaliar CDI se piora. Retorno em 6 meses.');
