insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (40, '2022-03-07', 'estavel', 'Cardiopatia chagásica com BAVT tratado com marca-passo bicameral, sem síncope desde o implante. Evolui com leve queda da FEVE (46%) e arritmia ventricular rara, em início de terapia para disfunção ventricular. Segue em acompanhamento semestral, com Holter e avaliação para CDI se piorar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (41, 'Bianca Rosário Sampaio', 'F', '1990-03-18', 'São Paulo', 'SP', 'Advogada', 'HAS crônica há 4 anos, diagnosticada aos 29 anos, controlada com losartana 50 mg 12/12h. Sobrepeso. Descobriu a gestação há uma semana, planejada, mas não trocou o anti-hipertensivo antes. Mãe e avó hipertensas. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (130, 41, 7, '2024-03-11 15:00', 'consulta', 'Estou grávida e tomo remédio de pressão', 134, 86, 82, 74.0, 'Gestante de 33 anos, 9 semanas, primigesta, com HAS crônica em uso de losartana 50 mg 12/12h, que continuou tomando até hoje por não saber do risco. Sem sangramento, sem cólicas. USG: gestação tópica única, embrião vivo, BCF presente. Ao exame: PA 134x86 mmHg, RCR 2T BNF, sem sopros, sem edema. Creatinina 0,8 mg/dL, potássio 4,1 mEq/L, proteinúria de 24h ausente (basal). HD: HAS crônica na gestação, em uso de BRA (contraindicado, exposição de poucas semanas).', 'Suspender losartana imediatamente. Iniciar metildopa 250 mg 8/8h, com ajuste conforme a PA. Orientado sobre exposição precoce ao BRA e risco de malformações baixo no primeiro trimestre se interrompido agora; USG morfológico no 2º trimestre. AAS 100 mg à noite a partir da 12ª semana para prevenção de pré-eclâmpsia e cálcio. PA domiciliar. Retorno em 4 semanas.'),
  (131, 41, 7, '2024-05-27 15:20', 'retorno', 'Estou me sentindo sonolenta, mas a pressão está boa', 124, 78, 80, 76.5, 'Gestante de 20 semanas, assintomática, com sonolência leve e cansaço atribuídos à metildopa. PA domiciliar entre 118x74 e 130x82 mmHg. USG morfológico normal: biometria compatível, sem malformações, placenta posterior, Doppler de uterinas normal. AU 20 cm, BCF 148 bpm. Sem edema, sem proteinúria na fita. Creatinina 0,7 mg/dL, hemograma normal. Ganho de peso adequado.', 'Manter metildopa 250 mg 8/8h com dose noturna maior para reduzir a sonolência (500 mg à noite). AAS 100 mg e cálcio mantidos. Pré-natal de alto risco com consultas a cada 4 semanas, USG com Doppler seriado no 3º trimestre. Orientados sinais de alarme de pré-eclâmpsia. Retorno em 4 semanas.'),
  (132, 41, 7, '2024-10-07 06:30', 'internacao', 'Internação para parto, 39 semanas', 130, 84, 84, 84.0, '39 semanas, gestação sem intercorrências, PA mantida entre 122x76 e 136x88 mmHg com metildopa 750 mg/dia, sem proteinúria, sem sinais de pré-eclâmpsia. Pré-natal de alto risco completo, feto adequado para idade gestacional (P55). Internada para indução eletiva às 39 semanas. Parto vaginal em 9h de indução, sem fórceps, RN feminino de 3.280 g, Apgar 9/10, laceração de 1º grau suturada. PA pós-parto 128x80 mmHg. Sem hemorragia.', 'Alta em 48h, aleitamento materno. Metildopa mantida por 24h e depois suspensa; reavaliar PA em 7 dias. Monitorar PA em casa 2x/dia. Retornar se cefaleia intensa, escotomas ou PA > 150x100. Retomar medicação anti-hipertensiva compatível com amamentação.'),
  (133, 41, 1, '2024-11-18 10:00', 'retorno', 'Voltar a tratar a pressão depois do parto', 144, 92, 78, 76.0, 'Puerpério de 6 semanas, amamentando exclusivamente. PA voltou a subir após suspender a metildopa, com valores domiciliares de 140-150x88-94 mmHg. Sem cefaleia. Perdeu 8 kg. Exames: creatinina 0,7 mg/dL, potássio 4,2 mEq/L, glicemia 90 mg/dL, sem proteinúria. Ao exame: PA 144x92 mmHg, RCR 2T BNF, sem sopros, sem edema.', 'No puerpério, e durante a amamentação, o enalapril é seguro. Iniciar enalapril 10 mg 12/12h. Contracepção segura (DIU, sem estrogênio) antes de nova gestação, com troca para metildopa ou nifedipino antes de engravidar. Controle de creatinina e potássio em 2 semanas. Retorno em 6 semanas com MRPA.');
