insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (41, '2024-11-18', 'controlado', 'HAS crônica na gestação conduzida com troca de losartana por metildopa na 9ª semana, sem pré-eclâmpsia e com parto vaginal de recém-nascido saudável. No puerpério, a PA voltou a subir e foi reiniciado enalapril, compatível com amamentação. Aguarda controle de MRPA e orientação pré-concepcional para futura gestação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (42, 'Zilda Oliveira Camargo', 'F', '1959-06-09', 'Campinas', 'SP', 'Bibliotecária aposentada', 'HAS há 15 anos, em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Encaminhada como hipertensão resistente porque a PA sempre sobe em consultórios. Ansiedade com consultas médicas. Eutrófica. Nunca fumou. Faz hidroginástica 3x por semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (134, 42, 2, '2022-05-16 10:00', 'consulta', 'Dizem que minha pressão é resistente', 178, 104, 88, 62.0, 'Mulher de 62 anos encaminhada por HAS resistente: PA nas consultas sempre entre 170-180x100-105 mmHg com três fármacos em doses plenas. A paciente refere sentir-se bem, sem cefaleia ou sintomas, e diz que ''fico nervosa só de ver o jaleco''. Na farmácia e em casa, a PA é de 120-130x70-80 mmHg, com aparelho validado. Uso regular dos medicamentos, confirmado. Ao exame: ansiosa, IMC 24, PA 178x104 mmHg na primeira medida e 168x100 na terceira, RCR 2T BNF, sem sopros, sem edema. HD: suspeita de pseudorresistência por efeito do avental branco; confirmar com MAPA antes de qualquer intensificação.', 'Não adicionar quarto fármaco. Solicitados MAPA 24h, MRPA, creatinina, potássio, ECO e fundo de olho. Manter esquema atual até a MAPA. Orientada a estar relaxada no dia do exame. Retorno em 30 dias com resultados.'),
  (135, 42, 2, '2022-06-27 10:10', 'retorno', 'Trouxe os exames, estava calma na MAPA', 164, 98, 84, 61.8, 'MAPA 24h: média de 118x70 mmHg, vigília 122x74, sono 106x62, com 96% das medidas dentro da meta. MRPA média de 120x72 mmHg. Diferença de mais de 40 mmHg entre consultório e MAPA, confirmando efeito do avental branco intenso e pseudorresistência. ECO normal (sem HVE), fundo de olho normal, albuminúria ausente. Potássio 3,4 mEq/L, provável efeito da clortalidona com paciente hipotensa em domicílio. PA de consultório 164x98 mmHg.', 'Desprescrição: suspender clortalidona (hipocalemia e PA fora do consultório já abaixo da meta). Manter losartana 100 mg e anlodipino 10 mg. Mudar a medida clínica para MRPA e MAPA. Reposição de potássio dietético. Repetir potássio em 2 semanas. Retorno em 3 meses com MRPA.'),
  (136, 42, 2, '2022-12-12 10:00', 'retorno', 'Pressão em casa continua boa', 150, 90, 78, 62.4, 'Seis meses depois, assintomática. MRPA com média de 122x74 mmHg sem a clortalidona. Potássio normalizado em 4,2 mEq/L. PA de consultório menor (150x90 mmHg), com menos ansiedade. Sem edema, nenhuma tontura, mantém hidroginástica três vezes por semana e dieta com pouco sal. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA.', 'Manter losartana 100 mg e anlodipino 10 mg. Reduzir anlodipino para 5 mg em teste se MRPA permanecer < 125x75. Decisões terapêuticas sempre baseadas em MRPA, não em PA de consultório. Retorno em 6 meses.');
