insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (42, '2022-12-12', 'controlado', 'A suposta hipertensão resistente era pseudorresistência por efeito do avental branco, confirmada por MAPA e MRPA. Em vez de intensificar, foi suspensa a clortalidona, corrigindo a hipocalemia, mantendo PA domiciliar média de 122x74 mmHg com dois fármacos. Segue com decisões baseadas em MRPA.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (43, 'Joaquim Vieira Salgado', 'M', '1961-02-12', 'Ribeirão Preto', 'SP', 'Mecânico de autos', 'DM2 há 18 anos, com mau controle prolongado e uso irregular de metformina e insulina NPH. HAS há 12 anos. Doença renal crônica diagnosticada há 3 anos (nefropatia diabética), sem acompanhamento. Tabagista de 30 maços-ano. Usou anti-inflamatórios para dor lombar.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (137, 43, 8, '2020-09-14 14:00', 'consulta', 'Pressão alta e urina com espuma', 164, 98, 80, 90.0, 'Homem de 59 anos com DM2 e DRC encaminhado ao nefrologista por piora da PA, edema de tornozelos e urina espumosa. Ao exame: PA 164x98 mmHg, edema 2+/4+ até joelhos, pulmões limpos, RCR 2T BNF sem sopros, retinopatia diabética moderada ao fundo de olho. Creatinina 2,1 mg/dL (TFGe 34, G3b), ureia 82 mg/dL, K 4,9 mEq/L, relação albumina/creatinina 820 mg/g (A3), Hb 11,4 g/dL, bicarbonato 20 mEq/L. HbA1c 9,2%. USG renal: rins de dimensões reduzidas com aumento de ecogenicidade cortical. HD: hipertensão secundária à DRC (nefropatia diabética), estágio G3b A3.', 'Suspender AINE definitivamente. Iniciar losartana 100 mg/dia, anlodipino 10 mg e clortalidona 25 mg. Dapagliflozina 10 mg pela proteção renal e controle glicêmico. Insulina NPH ajustada com a endocrinologia. Dieta com pouco sal, controle de fósforo e potássio. Bicarbonato de sódio 500 mg 8/8h. Creatinina e K em 1 semana.'),
  (138, 43, 8, '2021-06-21 14:10', 'retorno', 'A pressão melhorou mas o médico disse que o rim piorou', 134, 82, 76, 85.5, 'Nove meses depois. PA domiciliar média de 132x80 mmHg com adesão à medicação. Edema de MMII resolveu, perdeu 4,5 kg. Parou de fumar há 4 meses. Exames: creatinina 2,4 mg/dL (TFGe 29, G4), K 5,3 mEq/L, albuminúria 540 mg/g, Hb 10,6 g/dL, fósforo 5,0 mg/dL, PTH 180 pg/mL, HbA1c 8,1%. Piora progressiva da função renal apesar do controle pressórico. Ao exame: PA 134x82 mmHg, sem edema, sem sinais de uremia.', 'Hipercalemia leve: dieta pobre em potássio, manter losartana 50 mg/dia (reduzida) e acompanhar K a cada 2 semanas. Trocar clortalidona por furosemida 40 mg/dia (TFGe < 30). Iniciar eritropoetina por Hb baixa após estudo de ferro e vitamina D. Orientações sobre terapia renal substitutiva. Retorno em 3 meses.'),
  (139, 43, 8, '2022-10-24 14:00', 'retorno', 'Estou muito cansado e enjoado', 152, 90, 84, 88.0, 'Retorna após 16 meses, sem seguir o acompanhamento regular. Há 2 meses com fadiga, náuseas, inapetência, prurido e edema de MMII. Recebeu AINE de um pronto-socorro por dor lombar há 6 semanas. Ao exame: pálido, PA 152x90 mmHg, edema 2+/4+, hálito urêmico leve, sem atrito pericárdico. Creatinina 3,6 mg/dL (TFGe 18, G4), ureia 168 mg/dL, K 5,6 mEq/L, Hb 9,1 g/dL, bicarbonato 17 mEq/L. HD: DRC estágio 4 com progressão acelerada, sintomas urêmicos.', 'Suspender losartana por hipercalemia e piora da função renal. Manter anlodipino 10 mg e elevar furosemida para 80 mg/dia, adicionar hidralazina 25 mg 8/8h. Dieta restrita. Confecção de fístula arteriovenosa e preparação para terapia renal substitutiva (hemodiálise). Encaminhado à cirurgia vascular para a fístula. Retorno em 15 dias.');
