insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (43, '2022-10-24', 'piorou', 'Hipertensão secundária à doença renal crônica diabética, com perda progressiva da função renal de TFGe 34 para 18, hipercalemia e sintomas urêmicos, agravada por AINE. Perda de seguimento por 16 meses. Encaminhado para fístula arteriovenosa e preparo para terapia renal substitutiva.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (44, 'Jussara Lopes Medeiros', 'F', '1986-11-25', 'Natal', 'RN', 'Vendedora de loja de roupas', 'Sem HAS conhecida. Já teve dois episódios de cólica renal, tratados com analgésicos. Pouca ingestão de água durante o expediente. Não fuma. Pai hipertenso. Usa anticoncepcional oral combinado.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (140, 44, 6, '2023-02-18 20:10', 'pronto_socorro', 'Dor insuportável nas costas e a pressão está altíssima', 196, 118, 112, 63.0, 'Pcte 36 anos chega com dor lombar esquerda em cólica, de início súbito há 2h, irradiada para flanco e genitais, náuseas e vômitos, sudorese, agitada, sem encontrar posição. EVA 10/10. Sem febre, sem disúria, sem cefaleia, sem sintomas neurológicos ou dor torácica. PA 196x118 mmHg e FC 112 bpm. Ao exame: abdome flácido, Giordano positivo à esquerda, sem sinais de IC, fundo de olho sem papiledema, neurológico normal. EAS com hematúria 3+; creatinina 0,8 mg/dL. HD: cólica renal esquerda com pseudocrise hipertensiva por dor (sem lesão de órgão-alvo).', 'Não tratar a PA com anti-hipertensivo: analgesia primeiro. Cetorolaco 30 mg EV, hioscina e dipirona EV, hidratação. USG: cálculo de 6 mm em ureter distal à esquerda com hidronefrose leve. Reavaliação da PA em 1h após alívio da dor. Alta com analgesia, tamsulosina e retorno para reavaliar PA em 2 semanas.'),
  (141, 44, 5, '2023-03-13 10:30', 'retorno', 'Passou a pedra e vim ver a pressão', 118, 74, 72, 62.5, 'Após 40 min no PS, com a dor controlada, a PA caiu espontaneamente para 142x86 mmHg e à noite para 128x78. Eliminou o cálculo no 5º dia, sem febre ou infecção urinária. Sem dor, sem hematúria, sem dispneia ou cefaleia. MRPA de 5 dias: média de 116x72 mmHg. Ao exame: PA 118x74 mmHg, RCR 2T BNF sem sopros, abdome indolor. Creatinina 0,8 mg/dL, potássio 4,0 mEq/L, glicemia 86 mg/dL, cálcio e ácido úrico normais.', 'Confirmado: o pico pressórico foi reação à dor intensa, sem HAS. Sem medicação anti-hipertensiva. Orientada ingestão de 2,5 L de água por dia e redução de sal. Investigação metabólica da litíase com urina de 24h. Revisar uso de anticoncepcional combinado com a ginecologista. PA anual. Retorno em 6 meses.'),
  (142, 44, 5, '2023-09-18 10:30', 'teleconsulta', 'Retorno semestral sem queixas', 120, 76, 68, 62.0, 'Teleconsulta de seguimento. Informa PA domiciliar de 120x76 mmHg em medida do dia, com aparelho próprio. Sem novos episódios de cólica, bebe 2,5 L de água por dia com garrafa no balcão da loja. Urina de 24h: cálcio 180 mg/24h e citrato levemente baixo. Sem queixas cardiovasculares. Trocou o anticoncepcional por DIU de cobre, a pedido da ginecologista.', 'Sem diagnóstico de hipertensão; manter vigilância anual da PA. Citrato de potássio por 6 meses, discutir com urologia. Manter hidratação. Não são necessários exames cardiológicos adicionais. Alta do ambulatório de cardiologia.');
