insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (44, '2023-09-18', 'melhorou', 'Pseudocrise hipertensiva causada por dor de cólica renal, sem HAS: a PA normalizou ao tratar a dor e o cálculo foi eliminado. MRPA e PA domiciliar normais sem medicação. Recebeu alta da cardiologia, com vigilância anual da pressão e seguimento da litíase na urologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (45, 'Ivone Zanetti Ribeiro', 'F', '1957-10-03', 'Marília', 'SP', 'Comerciante (mercearia)', 'HAS há 22 anos, DM2 há 9 anos com metformina e dislipidemia. Sedentária, trabalha em pé o dia inteiro. Nunca fumou. Mãe falecida de infarto aos 70 anos. Usa losartana 50 mg 12/12h, metformina e sinvastatina.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (143, 45, 6, '2023-08-12 04:50', 'pronto_socorro', 'Dor forte no peito e suor frio de madrugada', 110, 66, 54, 76.0, 'Pcte 65 anos, atendida em hospital regional sem hemodinâmica, com dor retroesternal intensa há 90 min, sudorese, náuseas e vômitos. Ao exame: pálida, bradicárdica, PA 110x66 mmHg, MV+ sem RA. ECG: supra de ST de 3 mm em DII, DIII e aVF, com infra especular em DI e aVL, e BAV de 1º grau. Troponina 1.200 ng/L. Tempo previsto para transferência à hemodinâmica superior a 120 minutos. HD: IAMCSST inferior, Killip I.', 'Estratégia fármaco-invasiva: AAS 300 mg, clopidogrel 300 mg, enoxaparina 30 mg EV e tenecteplase em dose ajustada ao peso, com reperfusão confirmada pela queda do supra em 60 min e alívio da dor. Atropina 0,5 mg por bradicardia. Transferência para hemodinâmica de referência em 3 a 24h. Evitar nitrato por suspeita de infarto de VD.'),
  (144, 45, 10, '2023-08-14 10:00', 'internacao', 'Cateterismo após o trombolítico', 122, 72, 62, 75.5, 'D2 de IAMCSST inferior com tenecteplase e transferência. CATE radial: oclusão subtotal da CD proximal (95%), recanalizada, com trombo residual; DA com lesão de 50% e Cx sem lesões significativas. Realizada ATC com stent farmacológico 3,5x23 mm na CD, com ótimo resultado e TIMI 3. BAV de 1º grau resolvido. ECO: FEVE 52%, hipocinesia inferior, VD preservado. Sem sangramento no sítio de punção.', 'Alta em 48h. Dupla antiagregação com AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses (suspender clopidogrel). Atorvastatina 80 mg, metoprolol succinato 25 mg e losartana 50 mg 12/12h. Metformina mantida. Reabilitação cardiovascular. Retorno em 30 dias.'),
  (145, 45, 1, '2023-12-04 09:00', 'retorno', 'Estou me cuidando, queria ver os exames', 122, 74, 62, 72.0, 'Quase 4 meses do infarto. Sem angina, sem dispneia, fazendo reabilitação cardiovascular 3x por semana na cidade e passou a delegar mais o caixa da mercearia ao filho. Perdeu 4 kg com dieta, nunca mais frita. Sem sangramentos. Pequena dispneia aos grandes esforços, atribuída ao ticagrelor, tolerável. Exames: LDL 48 mg/dL, HbA1c 6,7%, creatinina 0,9 mg/dL, K 4,3 mEq/L. ECO: FEVE 58%, recuperação da contratilidade.', 'Manter dupla antiagregação até agosto de 2024 e depois AAS isolado. Manter atorvastatina 80 mg, metoprolol, losartana e metformina. Reabilitação até completar 12 semanas e exercício aeróbico contínuo. Vacina contra influenza anual. Retorno em 4 meses.');
