insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (45, '2023-12-04', 'controlado', 'IAMCSST inferior em hospital sem hemodinâmica, tratado com trombólise e angioplastia com stent na coronária direita (estratégia fármaco-invasiva). Evolução sem complicações, FEVE recuperada para 58%, LDL em 48 mg/dL, HbA1c em 6,7% e reabilitação em andamento. Mantém dupla antiagregação até agosto de 2024.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (46, 'Edson Aparecido Lourenço', 'M', '1969-03-30', 'Sumaré', 'SP', 'Pedreiro', 'Etilismo pesado há mais de 25 anos (cerca de 1 garrafa de cachaça por dia). Tabagista de 25 maços-ano. HAS leve nunca tratada. Perdeu o último emprego há 6 meses. Mora com a esposa e dois filhos. Sem DM2.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (146, 46, 11, '2022-03-21 08:30', 'consulta', 'Falta de ar, inchaço e cansaço, não consigo mais trabalhar', 112, 74, 104, 78.0, 'Homem de 52 anos com 3 meses de dispneia aos pequenos esforços, ortopneia, edema de pernas, tosse noturna e palpitações. Bebe todos os dias, desde a adolescência, e piorou depois do desemprego. Ao exame: emagrecido, ruborizado, PA 112x74 mmHg, FC 104 bpm irregular, estase jugular, B3, estertores em bases, hepatomegalia, edema 3+/4+. ECG: FA com resposta de 120 bpm no início; revertida espontaneamente para sinusal a 98 bpm, extrassístoles ventriculares frequentes. ECO: FEVE 25%, DDVE 68 mm, IM funcional moderada. NT-proBNP 6.900 pg/mL. TSH normal, ferritina normal. Coronárias sem lesões na angiotomografia. HD: cardiomiopatia alcoólica com ICFEr descompensada, NYHA III-IV.', 'Abstinência alcoólica total como parte do tratamento (encaminhamento ao CAPS-AD, tiamina 300 mg/dia). Iniciar carvedilol 3,125 mg 12/12h, enalapril 5 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg e furosemida 40 mg 12/12h. K e creatinina em 1 semana. Retorno em 2 semanas.'),
  (147, 46, 11, '2022-07-25 08:40', 'retorno', 'Estou conseguindo trabalhar de novo', 118, 76, 66, 73.0, 'Quatro meses de abstinência alcoólica, mantida com ajuda do CAPS e da igreja. Dispneia desapareceu para esforços habituais, sem ortopneia nem edema. Trabalha em obras leves. Perdeu 5 kg (líquido). Ao exame: PA 118x76 mmHg, FC 66 bpm, sem estase jugular, pulmões limpos, sem edema. Exames: K 4,4 mEq/L, creatinina 1,0 mg/dL, NT-proBNP 780 pg/mL, TGO e TGP normalizadas. ECO: FEVE 38%.', 'Boa resposta. Aumentar carvedilol para 12,5 mg 12/12h e enalapril para 10 mg 12/12h. Manter espironolactona, dapagliflozina e suspender furosemida por euvolemia. Continuar abstinência e CAPS, que são parte do tratamento. ECO em 4 meses. Retorno em 90 dias.'),
  (148, 46, 11, '2022-12-12 08:30', 'retorno', 'Vim buscar a receita, tô bem', 124, 78, 62, 76.0, 'Nove meses de seguimento, NYHA I, trabalhando em obra. Relata uma recaída de álcool no fim de semana do mês passado, ''só uns goles, doutor'', sem manter. Ao exame: bem, PA 124x78 mmHg, FC 62 bpm, sem congestão. ECO: FEVE 45%, DDVE 58 mm, IM discreta. NT-proBNP 240 pg/mL. K 4,5 mEq/L, creatinina 1,1 mg/dL. Fígado sem alterações. Peso aumentando por melhor apetite.', 'FEVE em recuperação, 45%, com abstinência quase total. Manter todos os fármacos e a abstinência rigorosa; recaída pode reverter o ganho. Conversa com a esposa e estímulo ao CAPS. Reavaliar ECO em 6 meses. Retorno em 90 dias.');
