insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (46, '2023-08-30', 'abandonou', 'Cardiomiopatia alcoólica com recuperação da FEVE de 25% para 45% durante a abstinência. Não compareceu aos retornos de março e junho de 2023. A esposa informou que ele voltou a beber e parou os medicamentos. Perdeu seguimento com alto risco de recidiva da insuficiência cardíaca.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (47, 'Raimunda Cristina Pantoja', 'F', '1990-01-17', 'Belém', 'PA', 'Professora de educação infantil', 'Gestação recente sem intercorrências, parto vaginal há 3 semanas, amamentando. Pré-natal sem pré-eclâmpsia. Sem HAS ou cardiopatia prévia.  Sem história familiar de cardiomiopatia. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (149, 47, 6, '2022-06-12 02:50', 'pronto_socorro', 'Acordei sem ar, não consigo deitar, e meus pés estão enormes', 138, 88, 118, 74.0, 'Pcte 32 anos, 3 semanas de puerpério, com dispneia progressiva há 10 dias, ortopneia, tosse noturna e edema importante de MMII. Sem febre, sem dor torácica. Ao exame: taquipneica, SpO2 91% em ar ambiente, estase jugular a 45°, taquicardia com B3, estertores até meio dos campos, edema 3+/4+, hepatomegalia. ECG: taquicardia sinusal, alterações inespecíficas de ST-T. NT-proBNP 4.800 pg/mL. Troponina discretamente elevada (28 ng/L). ECO: FEVE 28%, VE dilatado (DDVE 62 mm), IM funcional moderada, sem trombo, pequeno derrame pericárdico. HD: cardiomiopatia periparto com ICFEr descompensada.', 'Internação. Furosemida EV 40 mg, restrição hídrica, O2 suplementar. Iniciar enalapril 2,5 mg 12/12h (compatível com amamentação), carvedilol em baixa dose após estabilização e heparina profilática. Avaliar bromocriptina 2,5 mg/dia por 8 semanas com anticoagulação profilática. Orientações sobre risco em futura gestação.'),
  (150, 47, 11, '2022-06-14 09:30', 'internacao', 'Mais aliviada, queria voltar para casa para ver meu bebê', 112, 70, 92, 69.5, 'D3 de internação por cardiomiopatia periparto. Euvolêmica no terceiro dia, perdeu 4,5 kg, sem O2, sem ortopneia. Tolerando enalapril sem hipotensão. Pesquisa de miocardite viral negativa, sem coronariopatia por história e ECG. Ressonância cardíaca sem realce tardio extenso. Ao exame: PA 112x70 mmHg, FC 92 bpm, estertores raros, edema discreto. Bromocriptina iniciada, em conjunto com enoxaparina profilática. Sem dor torácica ou arritmia ao monitor.', 'Alta para casa. Manter enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg (reavaliar se parar de amamentar), bromocriptina 2,5 mg/dia e enoxaparina 40 mg/dia por 8 semanas. Furosemida 20 mg/dia. Dieta com baixo sódio. Retorno em 4 semanas. Orientadas sobre sinais de piora.'),
  (151, 47, 11, '2022-09-19 09:00', 'retorno', 'Voltei a trabalhar um pouco e estou bem', 108, 68, 70, 64.0, 'Três meses depois do parto. NYHA I-II, caminha, cuida do bebê, voltou à escola em meio período. Sem edema, sem ortopneia. Concluiu bromocriptina e enoxaparina. Parou de amamentar há duas semanas. ECO: FEVE 44%, DDVE 56 mm, IM discreta. NT-proBNP 360 pg/mL. K 4,6 mEq/L, creatinina 0,7 mg/dL. Ao exame: PA 108x68 mmHg, sem congestão.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (após 36h sem IECA) e acrescentar dapagliflozina 10 mg, agora que não amamenta. Manter carvedilol e espironolactona. Contracepção segura sem estrogênio é obrigatória enquanto a FEVE estiver < 50%, pois sacubitril/valsartana é teratogênico. ECO em 3 meses.'),
  (152, 47, 11, '2023-01-30 09:00', 'retorno', 'Retorno, sem sintomas', 110, 70, 66, 62.5, 'Oito meses após o diagnóstico, assintomática, NYHA I, corrida leve. ECO de controle: FEVE 54%, DDVE 52 mm, sem IM, função diastólica normal. NT-proBNP 110 pg/mL. PA 110x70 mmHg, FC 66 bpm, sem edema. K 4,5 mEq/L, creatinina 0,8 mg/dL. Usa DIU de cobre. Deseja outra gestação no futuro e pergunta sobre os riscos.', 'Recuperação da FEVE (> 50%), mas manter tratamento por pelo menos 12 a 24 meses antes de tentar retirada gradual. Nova gestação desaconselhada pelo risco de recidiva e descompensação; se for desejada, só com FEVE normal estável e aconselhamento pré-concepcional com obstetra de alto risco. Manter DIU. Retorno em 6 meses.');
