insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (47, '2023-01-30', 'melhorou', 'Cardiomiopatia periparto com FEVE de 28% tratada com IECA, betabloqueador, espironolactona, bromocriptina e anticoagulação profilática. Em 8 meses a FEVE chegou a 54%, assintomática e com NT-proBNP normal. Mantém tratamento, com contracepção sem estrogênio e aconselhamento contra nova gestação sem avaliação especializada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (48, 'Altair Manoel Coelho', 'M', '1938-03-05', 'Florianópolis', 'SC', 'Pescador artesanal aposentado', 'FA permanente há 6 anos. HAS há 40 anos e DRC estágio 3b (creatinina 1,9 mg/dL). Dois episódios de queda no último ano, sem fraturas. Em uso irregular de varfarina com INR instável, suspensa pelo médico da UBS. Mora com a filha, usa bengala.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (153, 48, 4, '2024-02-19 10:00', 'consulta', 'Querem que eu tome um remédio para o sangue e tenho medo de sangrar', 138, 78, 82, 62.0, 'Homem de 85 anos, frágil, com FA permanente, sem anticoagulação desde que a varfarina foi suspensa há 5 meses por INR lábil (entre 1,4 e 5,8). Já teve duas quedas, sem trauma craniano. CHA2DS2-VASc 3 (idade ≥ 75 anos = 2, HAS = 1) e HAS-BLED 3. Ao exame: RCR irregular, FC 82 bpm, sem sopros, sem edema, marcha lenta com bengala. Creatinina 1,9 mg/dL, ClCr (Cockcroft-Gault) 25 mL/min, Hb 12,4 g/dL, plaquetas normais. ECO: FEVE 52%, AE 50 mm. HD: FA permanente com alto risco tromboembólico e hemorrágico.', 'Decisão compartilhada com o paciente e a filha: benefício esperado maior que o risco. Iniciar apixabana 2,5 mg 12/12h (redução por idade ≥ 80 anos e creatinina ≥ 1,5 mg/dL). Evitar AINE e AAS. Fisioterapia para equilíbrio e retirar tapetes. Metoprolol succinato 25 mg/dia para a FC. Hemograma e creatinina em 1 mês.'),
  (154, 48, 4, '2024-05-27 10:00', 'retorno', 'Tomei tudo direitinho, só ficou uma mancha roxa no braço', 134, 76, 70, 62.8, 'Três meses de apixabana, sem sangramentos importantes, apenas equimose no antebraço após bater na mesa. A filha administra os remédios. Fisioterapia 2x por semana, sem novas quedas. Hemoglobina 12,6 g/dL, creatinina 1,9 mg/dL, plaquetas normais. Ao exame: FA, FC 70 bpm, PA 134x76 mmHg, sem edema, sem sinais de sangramento. Bem-humorado.', 'Manter apixabana 2,5 mg 12/12h. Reforçar a prevenção de quedas e a ausência de AINE. Hemograma e função renal a cada 3 meses. Se a ClCr cair abaixo de 15 mL/min, reavaliar a anticoagulação. Retorno em 3 meses.'),
  (155, 48, 6, '2024-09-16 03:40', 'pronto_socorro', 'Caí no banheiro e bati a cabeça', 150, 84, 88, 62.0, 'Pcte 86 anos em uso de apixabana, caiu no banheiro à noite, com trauma frontal e hematoma de 4 cm, sem perda de consciência, sem vômitos, lúcido, Glasgow 15. Sem déficit focal. Última dose de apixabana há 8h. Ao exame: PA 150x84 mmHg, FC 88 bpm irregular, hematoma frontal sem laceração, pupilas isocóricas, sem sinais de fratura. TC de crânio sem hemorragia, sem fratura. Repetida TC às 6h, mantida sem alterações. Hb 12,3 g/dL. HD: TCE leve em anticoagulado, sem lesão intracraniana.', 'Observação por 24h, sem alterações neurológicas. Manter apixabana, pois não há hemorragia; retomar na dose habitual no mesmo dia após liberação. Orientação à família: sinais de alarme (sonolência, vômitos, cefaleia nova). Solicitada avaliação do banheiro, barras de apoio e reavaliação da sedação noturna. Retorno em 15 dias.');
