insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (48, '2024-09-16', 'estavel', 'FA permanente em idoso frágil com alto risco tromboembólico e de quedas, mantido com apixabana 2,5 mg, por decisão compartilhada. Sofreu trauma craniano leve sem hemorragia intracraniana e segue anticoagulado, com adaptações no domicílio e seguimento de hemograma e função renal a cada três meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (49, 'Lourdes Aparecida Prestes', 'F', '1944-09-22', 'Itu', 'SP', 'Aposentada (ex-bordadeira)', 'HAS há 35 anos em uso de losartana. Episódios de palpitações e tonturas há 1 ano. Hipotireoidismo tratado. Mora com o marido, que depende dela. Começou metoprolol 50 mg por conta da UBS para as palpitações há 6 semanas.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (156, 49, 4, '2021-10-04 09:30', 'consulta', 'Tontura, quase desmaio e coração muito devagar às vezes', 146, 78, 44, 61.0, 'Mulher de 77 anos com palpitações rápidas intercaladas com períodos de pulso muito lento, tontura, cansaço e dois episódios de pré-síncope. Em uso de metoprolol há 6 semanas, com piora dos sintomas. Ao exame: FC 44 bpm, pulso irregular, PA 146x78 mmHg, sem sopros, sem edema. ECG: bradicardia sinusal de 44 bpm. Holter 24h: pausas sinusais de até 5,2 s durante a madrugada, FA paroxística com resposta rápida de até 146 bpm, e bradicardia sinusal com FC mínima de 32 bpm. TSH 2,2 mUI/L. ECO: FEVE 60%, AE 46 mm. HD: doença do nó sinusal (síndrome bradi-taquicardia) agravada pelo betabloqueador.', 'Suspender metoprolol. Indicado marca-passo definitivo (permite controlar a taquiarritmia depois com drogas). Anticoagular com apixabana 5 mg 12/12h (CHA2DS2-VASc 4: idade ≥ 75 anos = 2, HAS = 1, sexo feminino = 1). Evitar drogas cronotrópicas negativas até o implante. Internação eletiva em 2 semanas.'),
  (157, 49, 4, '2021-10-20 07:30', 'internacao', 'Implante do marca-passo', 140, 76, 48, 60.5, 'Internação eletiva. Sem síncope desde a suspensão do metoprolol, mas mantém bradicardia sinusal de 48 bpm e tontura. Implantado marca-passo definitivo bicameral (DDDR com modo anti-mudança de modo) sem intercorrências, por via subclávia esquerda. Limiares adequados. Raio X sem pneumotórax. Hoje D1, FC 70 bpm estimulada, sem tontura, curativo limpo. Apixabana mantida sem interrupção.', 'Alta em 24h. Orientações sobre cuidados com o MP, evitar elevar o braço esquerdo por 4 semanas. Profilaxia com azitromicina 500 mg por 3 dias, por alergia a penicilina. Retornar em 30 dias para revisão; depois do implante poderá usar betabloqueador em dose baixa se a FA tiver resposta rápida. Manter apixabana.'),
  (158, 49, 4, '2022-04-11 09:30', 'retorno', 'Sem tontura, quero voltar ao bordado', 138, 74, 68, 61.5, 'Seis meses após o implante, sem tontura nem pré-síncope. Percebeu duas crises curtas de palpitações, de 10 a 20 min, que passaram sozinhas. Interrogação: carga de FA de 3%, resposta ventricular de até 118 bpm em episódios curtos, pacing atrial de 62%, ventricular 5%. Sem sangramentos com apixabana. Hb 12,9 g/dL, creatinina 0,9 mg/dL. Ao exame: ritmo regular, FC 68 bpm, PA 138x74 mmHg, loja do MP sem alterações.', 'Agora com o MP, é seguro introduzir metoprolol succinato 25 mg/dia para suprimir resposta rápida durante a FA. Manter apixabana 5 mg 12/12h e losartana. Interrogação do MP a cada 6 meses. Retorno em 6 meses.');
