insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (49, '2022-04-11', 'melhorou', 'Síndrome bradi-taquicardia tratada com marca-passo bicameral, o que permitiu retomar o betabloqueador para a FA paroxística e manter apixabana. Sem tontura ou síncope desde o implante e voltou às atividades. Segue com interrogação do marca-passo a cada 6 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (50, 'Danilo Kuczynski Bonfim', 'M', '1983-07-14', 'São Paulo', 'SP', 'Personal trainer', 'Sopro cardíaco conhecido desde a adolescência, dispensado do esporte escolar. Pai morreu subitamente aos 41 anos, durante partida de futebol, sem diagnóstico. Irmão mais velho com hipertrofia ventricular. Nega uso de anabolizantes ou termogênicos. Sem HAS.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (159, 50, 11, '2023-01-30 08:30', 'consulta', 'Falta de ar e quase desmaiei dando aula', 118, 72, 76, 82.0, 'Homem de 39 anos, personal trainer, com piora da dispneia e dor torácica aos esforços intensos há 6 meses, e episódio de pré-síncope durante treino na semana passada. História familiar de morte súbita (pai aos 41 anos). Ao exame: pulso em duplo impulso, ictus sustentado, B4, sopro sistólico ejetivo 3+/6+ em borda esternal esquerda, que aumenta com Valsalva e diminui com agachamento. ECG: SVE com alterações de repolarização, ondas Q em derivações laterais. ECO: HVE assimétrica com septo de 24 mm, movimento sistólico anterior da mitral, gradiente em via de saída de 78 mmHg (após Valsalva), IM leve, FEVE 68%. HD: cardiomiopatia hipertrófica obstrutiva sintomática, NYHA II-III.', 'Suspender exercício intenso. Iniciar metoprolol succinato 100 mg/dia (aumentar até 200 mg), evitar vasodilatadores, diuréticos e desidratação. Solicitados Holter, ressonância cardíaca, teste ergométrico e painel genético. Estratificar o risco de morte súbita (escore HCM Risk-SCD). Rastreio de familiares de 1º grau. Retorno em 30 dias.'),
  (160, 50, 11, '2023-04-17 08:40', 'retorno', 'Melhorei da falta de ar, mas ainda sinto cansaço forte', 114, 70, 58, 81.0, 'Em uso de metoprolol 200 mg/dia, FC 58 bpm, sem pré-síncope, mas persistem dispneia leve e cansaço aos médios esforços e um episódio de dor torácica. Ressonância cardíaca: septo 25 mm, realce tardio em 12% da massa do VE, FEVE 70%, sem aneurisma apical. Holter: 2 episódios de TV não sustentada (5 e 7 batimentos). Escore HCM Risk-SCD 6,3% em 5 anos (risco alto). Teste ergométrico: queda da PA no pico do esforço. Gradiente em repouso 52 mmHg e 80 mmHg com provocação. Painel genético: variante patogênica em MYH7. Ao exame: sopro sistólico ejetivo 3+/6+, sem sinais de IC.', 'Risco de morte súbita elevado: indicado CDI para prevenção primária. Verapamil não associado pela FC já baixa. Sintomático, com gradiente > 50 mmHg refratário ao betabloqueador: indicação de terapia de redução septal. Encaminhar para centro de referência em miectomia septal. Orientado sobre rastreio familiar.'),
  (161, 50, 11, '2023-09-18 08:30', 'retorno', 'Tenho consulta no centro de referência, queria o relatório', 116, 72, 56, 80.5, 'Cinco meses depois, sintomas semelhantes (NYHA II-III), sem síncope. Relata ansiedade com o diagnóstico e com a perspectiva de CDI. Está evitando exercício intenso, mas treina alunos com atividade leve. CDI não implantado ainda por demora na liberação do dispositivo. Irmão mais velho com HVE confirmou mesma variante. Gradiente de via de saída 74 mmHg em repouso no ECO de hoje, MSA persistente. Ao exame: sopro 3+/6+, sem edema.', 'Manter metoprolol 200 mg/dia. Relatório completo emitido para centro de referência em cirurgia e cardiopatias genéticas (miectomia septal e implante de CDI). Sem alterações da medicação. Retorno ao serviço apenas se houver intercorrência antes da avaliação do centro. Orientado a evitar esportes de competição, desidratação e bebidas energéticas.');
