insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (50, '2023-09-18', 'transferido', 'Cardiomiopatia hipertrófica obstrutiva com gradiente de 74 mmHg, alto risco de morte súbita (HCM Risk-SCD 6,3%) e variante patogênica em MYH7. Encaminhado a centro de referência em cardiopatias genéticas para miectomia septal e implante de CDI, com relatório completo, e saiu do acompanhamento da rede.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (51, 'Thiago Kenji Nakamura Barreto', 'M', '1980-04-12', 'Niterói', 'RJ', 'Analista de sistemas', 'Sem diagnóstico prévio de HAS. Sedentário, trabalha 10 horas por dia sentado e almoça fora quase todos os dias. Pai hipertenso, infartou aos 58 anos. Bebe cerveja nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (162, 51, 1, '2024-02-05 08:30', 'consulta', 'Medi a pressão na farmácia e deu 15 por 9', 148, 94, 78, 96.2, 'Paciente de 43 anos, assintomático, procurou atendimento após aferição em farmácia com PA 150x92. Sem cefaleia, sem palpitações. Ao exame: obeso (IMC 31,4), RCR 2T BNF sem sopros, pulsos simétricos, sem edema. PA em duas medidas, braço direito, sentado: 148x94 e 146x92. Circunferência abdominal 108 cm. Alimentação rica em ultraprocessados e sal, sono de 5-6 horas. HD: HAS estágio 1, risco cardiovascular moderado, provável contribuição de obesidade e sedentarismo.', 'Confirmar com MRPA por 5 dias antes de iniciar medicação. Solicitado perfil lipídico, glicemia, creatinina, potássio, EAS e ECG. Orientada MEV: reduzir sal, caminhar 30 minutos 5x/semana, meta de perda de 5 kg em 3 meses, reduzir álcool. Retorno em 6 semanas com MRPA e exames.'),
  (163, 51, 1, '2024-03-20 08:50', 'retorno', 'Trouxe a planilha da pressão de casa', 144, 92, 74, 94.8, 'Trouxe MRPA de 5 dias (30 medidas válidas): média 142x90 mmHg, confirmando HAS. Perdeu 1,4 kg, caminha 3x/semana, mas ainda come fora. Exames: LDL 142, glicemia de jejum 98, creatinina 0,9, potássio 4,3, EAS sem proteinúria. ECG em ritmo sinusal, sem sinais de HVE. Sem queixas. Pela história familiar precoce e dois fatores de risco, optamos por iniciar medicação associada à MEV.', 'Iniciar losartana 50 mg ao dia. Manter MEV, levar marmita 3x/semana. Repetir creatinina e potássio em 30 dias. Retorno em 3 meses com MRPA. Orientado sobre a importância de não suspender se a pressão normalizar.'),
  (164, 51, 1, '2024-09-10 09:10', 'retorno', 'Vim mostrar que a pressão normalizou', 122, 78, 68, 88.5, 'Retorna muito satisfeito: perdeu 7,7 kg desde a primeira consulta, corre 3x/semana e trocou o almoço de restaurante por marmita. Toma losartana todos os dias, sem tosse ou outros efeitos. MRPA recente com média 121x77. Creatinina 0,9 e potássio 4,4 após introdução do BRA. LDL caiu para 118 apenas com dieta. Exame físico sem alterações.', 'Manter losartana 50 mg e MEV. Discutir redução futura da dose somente se perda de peso se mantiver por 1 ano. Retorno em 6 meses com MRPA e perfil lipídico.');
