insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (51, '2024-09-10', 'controlado', 'HAS estágio 1 controlada com losartana 50 mg e perda de quase 8 kg. PA de consultório 122x78 e MRPA na meta. Segue com MEV e retorno semestral; possível redução da dose se mantiver o peso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (52, 'Adriana Schmidt Pagung', 'F', '1971-09-03', 'Vitória', 'ES', 'Professora de ensino fundamental', 'HAS diagnosticada há 4 anos, usou losartana 50 mg por poucos meses e abandonou por conta própria. Dislipidemia sem tratamento. Mãe com AVC aos 66 anos. Não fuma, bebe socialmente.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (165, 52, 2, '2023-04-17 14:00', 'consulta', 'Dor de cabeça na nuca quase todo dia', 168, 104, 82, 74.0, 'Professora, 51 anos, queixa cefaleia occipital matinal há 3 semanas, sem déficit neurológico, sem dor torácica. Admite ter parado a losartana "porque tomar remédio todo dia é ruim". Ao exame PA 168x104 e 166x102, FC 82, ritmo regular, B4 audível, fundo de olho com cruzamentos arteriovenosos patológicos. Abdome sem sopros. HD: HAS estágio 2 com lesão de órgão-alvo provável (HVE a investigar).', 'Iniciar combinação em comprimido único para facilitar adesão: olmesartana 40 mg + anlodipino 5 mg, 1x ao dia. Solicitados ECO, ECG, creatinina, potássio, albuminúria, lipidograma. Explicado o risco de AVC dada a história familiar. Retorno em 30 dias.'),
  (166, 52, 2, '2023-05-22 14:20', 'retorno', 'A cabeça parou de doer', 138, 86, 76, 73.4, 'Sem cefaleia desde a segunda semana de tratamento. Tomando o comprimido único todas as manhãs, sem edema de tornozelo. ECO: FEVE 64%, hipertrofia concêntrica leve (septo 12 mm), átrio esquerdo de 40 mm. ECG com SVE por Sokolow-Lyon. Albuminúria normal. Creatinina 0,8, K 4,2. LDL 156, triglicerídeos 148.', 'Manter combinação, PA ainda acima da meta mas em queda. Iniciar rosuvastatina 10 mg à noite. Reforçado redução de sal. Retorno em 8 semanas com MRPA.'),
  (167, 52, 2, '2023-07-24 14:30', 'retorno', 'Trouxe o MRPA, acho que está boa', 126, 78, 72, 72.9, 'MRPA com média de 124x77 mmHg. Adesão ótima, usa lembrete no celular. Sem mialgia com a rosuvastatina. LDL de controle 84 mg/dL. Sem queixas cardiovasculares, sem tontura, sem edema de tornozelo. Exame físico sem alterações, ausculta cardíaca normal, pulsos simétricos. Relata que dá aula de pé e tem conseguido caminhar à noite com o marido.', 'Manter esquema atual. Meta de LDL abaixo de 100 atingida. Retorno semestral com exames; reavaliar ECO em 12 meses para acompanhar regressão da hipertrofia.');
