insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (52, '2023-07-24', 'controlado', 'HAS estágio 2 com hipertrofia ventricular leve controlada após troca para comprimido único de olmesartana com anlodipino. A cefaleia desapareceu, o LDL está na meta e a adesão se manteve boa. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (53, 'Raimundo Nonato Pessanha Gomes', 'M', '1965-11-20', 'Campos dos Goytacazes', 'RJ', 'Motorista de caminhão', 'HAS há 9 anos, prescrito losartana, anlodipino e hidroclorotiazida. Já foi ao PS três vezes por pressão alta. Fuma 10 cigarros por dia. Viaja de 4 a 6 dias seguidos, dorme no caminhão e come em beira de estrada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (168, 53, 2, '2022-08-09 10:00', 'consulta', 'Pressão não abaixa de jeito nenhum', 188, 108, 80, 91.0, 'Encaminhado como HAS resistente: refere uso de três drogas, PA 188x108 em duas medidas. Ao investigar, admite que só toma os comprimidos quando está em casa: na estrada "esquece, ou deixa na mochila". Estava com a cartela de losartana quase cheia. Manguito adequado, sem sopros abdominais, sem edema. Exames recentes: creatinina 1,0, K 4,0. Fumante. Provável pseudorresistência por má adesão.', 'Reconstruído o esquema de forma simples: trocar para clortalidona 25 mg + losartana 100 mg em dose única matinal e anlodipino 10 mg. Entregue caixa organizadora semanal e alarme no celular. Orientado cessar tabagismo. Solicitado MAPA 24h para retorno.'),
  (169, 53, 2, '2022-10-04 10:30', 'retorno', 'Estou tomando tudo junto de manhã, como o senhor mandou', 134, 84, 74, 89.8, 'Usa a caixa organizadora e leva para a cabine. PA 134x84, queda de 54 mmHg na sistólica sem aumentar o número de medicamentos, o que confirma pseudorresistência. MAPA 24h: média 128x80, descenso noturno preservado. Creatinina 1,1, K 3,7, sódio 138. Reduziu o cigarro para 5 por dia. Sem edema ou tosse.', 'Manter esquema. Repetir eletrólitos em 60 dias (clortalidona). Iniciar plano de cessação de tabagismo com adesivo de nicotina 21 mg. Retorno em 3 meses.'),
  (170, 53, 2, '2023-01-17 09:50', 'retorno', 'Parei de fumar faz um mês', 126, 80, 70, 92.6, 'Há 30 dias sem cigarro com adesivo. Ganhou 2,8 kg. Mantém os remédios na cabine e já passou duas viagens longas sem falhar. PA 126x80. Potássio 3,9, creatinina 1,0. Sem sintomas. Conta que a esposa confere a caixa quando ele volta da estrada.', 'Manter anti-hipertensivos. Reduzir adesivo para 14 mg por 4 semanas e depois 7 mg. Orientação nutricional para evitar o ganho de peso. Retorno em 4 meses.');
