insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (53, '2023-01-17', 'controlado', 'Pseudorresistência por má adesão em motorista de caminhão, resolvida com esquema em dose única matinal, caixa organizadora e apoio da esposa. PA em torno de 126x80 sem nenhuma droga a mais. Parou de fumar há um mês.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (54, 'Neuza Maria Vieira Zanotti', 'F', '1978-06-15', 'Cachoeiro de Itapemirim', 'ES', 'Auxiliar administrativa', 'HAS desde os 35 anos, em uso de losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg com PA ainda alta. Câimbras frequentes. Sem diabetes. Pai hipertenso, sem história de AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (171, 54, 8, '2023-05-08 15:30', 'consulta', 'Câimbras e fraqueza nas pernas, pressão sempre alta', 164, 102, 70, 68.5, 'Mulher de 44 anos, HAS de início precoce e refratária a três drogas, com câimbras e fraqueza proximal. Exames trazidos: potássio 3,0 mEq/L (repetido, sem coleta hemolisada), creatinina 0,8. Sem uso de laxantes, sem diarreia. Sem sinais cushingoides, sem sopro abdominal, sem episódios de palpitações ou sudorese. Hipocalemia espontânea com HAS resistente: suspeita de hiperaldosteronismo primário.', 'Repor potássio (cloreto de potássio xarope) e corrigir antes da coleta. Solicitar aldosterona e atividade de renina plasmática, urina de 24h com sódio e potássio. Suspender hidroclorotiazida e manter BRA e BCC. Retorno com exames em 3 semanas.'),
  (172, 54, 8, '2023-06-05 15:40', 'retorno', 'Trouxe os exames do sangue e da urina', 158, 98, 68, 68.0, 'Potássio 3,9 após reposição. Aldosterona plasmática 38 ng/dL, renina plasmática suprimida (0,2 ng/mL/h), relação aldosterona/renina de 190, teste positivo. Teste confirmatório com infusão salina: aldosterona 14 ng/dL após 4 h, confirma hiperaldosteronismo primário. Câimbras melhoraram. TC de adrenais: espessamento de ambas, sem nódulo definido.', 'Encaminhar para cateterismo de veias adrenais (AVS) no serviço de referência para definir lateralização, pois paciente jovem e candidata a cirurgia se unilateral. Introduzir espironolactona 25 mg e monitorar K e creatinina em 2 semanas. Retorno após AVS.'),
  (173, 54, 8, '2023-09-18 15:00', 'retorno', 'Fiz o exame do cateterismo das adrenais', 138, 86, 72, 67.4, 'AVS bem-sucedida com cateterização bilateral confirmada por cortisol: índice de lateralização 1,3 (abaixo de 4), sem lateralização, compatível com hiperplasia adrenal bilateral. Cirurgia não indicada. Em uso de espironolactona 25 mg, K 4,5 e creatinina 0,8. Mastalgia leve e ciclos menstruais um pouco irregulares nas últimas semanas. PA 138x86.', 'Tratamento clínico definitivo: aumentar espironolactona para 50 mg/dia. Informada sobre mastalgia e irregularidade menstrual, e que a eplerenona é alternativa se piorar. Contracepção não hormonal combinada. K e creatinina em 15 dias e após cada ajuste.'),
  (174, 54, 8, '2024-03-11 15:20', 'retorno', 'A pressão está boa, mas o peito dói um pouco', 122, 76, 66, 66.8, 'Sem câimbras há meses. PA 122x76 e MRPA em 120x75. K 4,7, creatinina 0,9, renina plasmática agora detectável (1,1), o que indica bloqueio mineralocorticoide adequado. Mastalgia persiste de intensidade leve, tolera. Ciclos regulares de novo após 2 meses. Sem outros efeitos adversos. Refere energia melhor para o trabalho e nenhuma falta ao serviço por câimbras nos últimos 6 meses.', 'Manter espironolactona 50 mg, losartana e anlodipino. Tentar reduzir anlodipino para 5 mg e reavaliar em 60 dias. Manter controle semestral de K e creatinina. Ecocardiograma anual.');
insert into diagnostico (id_atendimento, cid, descricao) values
