insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (54, '2024-03-11', 'controlado', 'Hiperaldosteronismo primário por hiperplasia adrenal bilateral (sem lateralização na AVS), tratado clinicamente com espironolactona 50 mg. Hipocalemia corrigida, PA 122x76 e dose de anlodipino reduzida. Mantém mastalgia leve tolerável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (55, 'Jair dos Anjos Cardoso', 'M', '1958-02-27', 'São Gonçalo', 'RJ', 'Pedreiro', 'HAS sem tratamento regular, usava enalapril quando lembrava. Tabagista de 30 maços-ano. Etilista social. Nunca fez exames de rotina. Irmão com AVC aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (175, 55, 6, '2025-08-14 03:40', 'pronto_socorro', 'Acordou com a boca torta e sem força no braço direito', 204, 114, 88, 82.0, 'Trazido pela esposa, última vez visto bem às 23h (início dos sintomas incerto, janela confirmada por TC de crânio e RM-DWI/FLAIR mismatch). Hemiparesia D grau 3, desvio de rima para a direita, disartria. NIHSS 11. Glicemia capilar 142. TC de crânio sem hemorragia. PA 204x114 mmHg. Candidato a trombólise: PA deve ficar abaixo de 185x110 antes da infusão. Tentado controle com labetalol EV.', 'Acionado protocolo AVC. Labetalol 10 mg EV, PA 178x104 após 15 min, liberada trombólise com alteplase 0,9 mg/kg. Manter PA < 180x105 por 24 horas. Encaminhado à UTI. Sem AAS ou heparina nas primeiras 24 h. Contato com neurologia.'),
  (176, 55, 14, '2025-08-14 11:30', 'internacao', 'Pós-trombólise, acompanhamento em UTI', 162, 92, 74, 82.0, 'Pós-alteplase sem sangramento, sem piora neurológica. NIHSS 6 após 6 horas. PA mantida entre 150-170 x 88-98 com nitroprussiato em baixa dose, depois suspenso. Angiotomografia: oclusão de ramo M2 esquerdo recanalizada parcialmente, placa em carótida interna E com 40% de estenose. ECG sem FA. TC controle em 24 h sem transformação hemorrágica.', 'Após TC às 24h: iniciar AAS 100 mg e atorvastatina 80 mg. Reintroduzir anti-hipertensivo oral gradualmente a partir do 3º dia (PA alvo < 140/90 na alta). Holter e ECO para investigar fonte embólica. Fisioterapia motora precoce.'),
  (177, 55, 13, '2025-09-22 10:00', 'retorno', 'Ainda arrasto a perna, mas já seguro a colher', 138, 82, 72, 80.6, 'Alta hospitalar há 3 semanas. NIHSS residual 2 (paresia leve em MSD, marcha ceifante). Faz fisioterapia 3x/semana. ECO: FEVE 60%, HVE leve, AE normal; Holter 24h sem FA. LDL 104. Parou de fumar na internação. PA 138x82 com anlodipino. Afastado do trabalho.', 'Associar losartana 50 mg ao anlodipino visando PA < 130/80. Manter AAS e atorvastatina. Doppler de carótidas em 6 meses. Continuar fisioterapia e terapia ocupacional. Retorno em 60 dias com K e creatinina.');
