insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (55, '2025-09-22', 'melhorou', 'AVC isquêmico de ACM esquerda tratado com trombólise após controle da PA com labetalol, evoluindo de NIHSS 11 para 2. Segue com sequela motora leve, em fisioterapia, com PA 138x82 e prevenção secundária instituída.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (56, 'Kelly Cristina Bonfim Siqueira', 'F', '1997-03-30', 'Duque de Caxias', 'RJ', 'Cabeleireira', 'Primeira gestação. Sem HAS prévia. Obesidade (IMC 32 antes da gestação). Mãe teve pré-eclâmpsia em duas gestações. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (178, 56, 7, '2024-05-02 09:00', 'consulta', 'Inchaço nos pés e pressão alta no pré-natal', 146, 96, 92, 88.4, 'Gestante de 27 anos, 28 semanas, encaminhada do posto por PA 146x96 em duas medições. Edema 2+ de MMII, sem cefaleia ou escotomas. Fita urinária com proteína 1+. AU compatível com idade gestacional, BCF 142 bpm. Ganhou 14 kg até agora. Alto risco para pré-eclâmpsia (nuliparidade, obesidade, história materna). HD: pré-eclâmpsia sem sinais de gravidade.', 'Iniciar nifedipino retard 20 mg 12/12 h. Solicitar hemograma, plaquetas, TGO/TGP, DHL, creatinina, ácido úrico e relação proteína/creatinina. Ultrassom obstétrico com Doppler. Orientados sinais de alarme. Retorno em 1 semana.'),
  (179, 56, 6, '2024-05-30 23:15', 'pronto_socorro', 'Dor de cabeça fortíssima e luzes piscando na vista', 176, 116, 104, 91.0, 'Gestante de 32 semanas com cefaleia intensa, escotomas cintilantes e dor epigástrica há 3 horas. PA 176x116 confirmada após 15 min. Hiperreflexia com clônus, edema generalizado. Fita urinária 3+. Plaquetas 98.000, TGO 142, TGP 118, DHL 640, creatinina 1,1. BCF 128. Quadro de pré-eclâmpsia grave com iminência de eclâmpsia e início de síndrome HELLP.', 'Sulfato de magnésio (ataque 4 g EV e manutenção 1 g/h), hidralazina 5 mg EV para PA < 160/110, corticoide para maturação pulmonar fetal (betametasona). Contato com obstetrícia: indicada interrupção da gestação por cesárea após estabilização. Reserva de UTI neonatal.'),
  (180, 56, 7, '2024-06-01 10:00', 'internacao', 'Pós-operatório de cesárea, 1º dia', 148, 94, 86, 84.5, 'Cesárea realizada em 31/05 com 32 semanas e 1 dia por pré-eclâmpsia grave e HELLP parcial. RN do sexo masculino, 1.780 g, Apgar 7/9, encaminhado à UTI neonatal. Sulfato de magnésio mantido por 24 h após o parto, diurese 80 mL/h. Plaquetas 74.000 no pós-operatório imediato com recuperação para 118.000. Sem sangramento anormal. PA oscilando 140-150 x 90-98.', 'Manter nifedipino retard 20 mg 12/12h. Controle de plaquetas e transaminases diários. Ordenha para o leite do prematuro. Alta prevista em 3-4 dias se PA estável e exames em queda.'),
  (181, 56, 7, '2024-07-15 09:30', 'retorno', 'Consulta do puerpério, bebê já está em casa', 130, 84, 78, 79.8, 'Puerpério de 6 semanas. Bebê teve alta da UTI neonatal com 38 dias, em aleitamento materno. Sem cefaleia. Cicatriz de cesárea ótima. PA 130x84 com nifedipino. Plaquetas 244.000, TGO 28, TGP 31, proteinúria de 24h 0,12 g. Perdeu 12 kg desde o parto. Orientada que pré-eclâmpsia grave aumenta o risco de HAS crônica e doença cardiovascular futura.', 'Trocar nifedipino por enalapril 10 mg 12/12h (compatível com amamentação). Aferição de PA domiciliar, retorno em 60 dias; checagem anual de PA, glicemia e lipídeos. AAS 100 mg em eventual próxima gestação desde 12 semanas.');
