insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (56, '2024-07-15', 'melhorou', 'Pré-eclâmpsia grave com início de HELLP, parto cesáreo prematuro aos 32 semanas sem eclâmpsia. Mãe recuperada, com exames laboratoriais normalizados e PA 130x84 em enalapril no puerpério. Bebê em casa, saudável. Segue com monitoramento de PA pelo risco de HAS crônica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (57, 'Alessandro Cavalcante Rocca', 'M', '1962-12-08', 'Petrópolis', 'RJ', 'Dono de loja de roupas', 'HAS há 10 anos com losartana 50 mg, dislipidemia sem estatina por intolerância autorreferida. Tabagista de 25 maços-ano. Pai morreu de infarto aos 55 anos. Estresse alto com o comércio.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (182, 57, 6, '2023-03-11 04:10', 'pronto_socorro', 'Dor no peito como um peso, suando frio', 156, 94, 98, 86.0, 'Dor retroesternal intensa irradiada para o braço esquerdo iniciada há 1h30, com sudorese e náuseas. Ao exame: ansioso, pálido, sudoreico, pulmões limpos, sem B3. ECG: supradesnivelamento de ST de 3 mm em V1-V4 e DI/aVL. Troponina inicial 0,9 ng/mL. IAMCSST anterior em Killip I. Tempo porta-balão de transferência para hemodinâmica da rede é de 40 min.', 'AAS 300 mg e ticagrelor 180 mg, heparina não fracionada, morfina 2 mg EV. Acionada hemodinâmica para ATC primária. Betabloqueador adiado até estabilização. Transferência em UTI móvel acompanhado.'),
  (183, 57, 10, '2023-03-11 07:00', 'internacao', 'Pós-angioplastia primária, UTI coronariana', 128, 80, 70, 86.0, 'CATE por via radial direita: oclusão trombótica do terço proximal da DA, lesão de 90% em CD média e circunflexa sem lesões significativas. ATC com implante de stent farmacológico em DA (fluxo TIMI 3 final), sem complicações. Dor resolvida. Evoluiu sem arritmias, sem sinais de IC. Pico de troponina de 68 ng/mL, CK-MB 210. Alta da UTI no 2º dia.', 'Dupla antiagregação por 12 meses (AAS + ticagrelor). Iniciar atorvastatina 80 mg, metoprolol succinato 50 mg e ramipril 5 mg. ECO antes da alta. Programar ATC eletiva da CD em 4-6 semanas. Cessação do tabagismo.'),
  (184, 57, 1, '2023-04-25 11:00', 'retorno', 'Primeira consulta depois da alta', 122, 76, 62, 84.2, 'Assintomático, sem angina, caminhando 30 min por dia. Parou de fumar há 6 semanas. ATC da CD realizada com sucesso há 2 semanas (stent farmacológico), sem intercorrências. Tolera bem as medicações, sem tosse. ECO: FEVE 52%, acinesia apical discreta. LDL 62, creatinina 1,0, potássio 4,5. Entrou em programa de reabilitação cardíaca.', 'Manter AAS, ticagrelor, atorvastatina, metoprolol e ramipril. Losartana suspensa (substituída pelo ramipril). Retorno em 6 meses para teste ergométrico e reavaliar tempo de dupla antiagregação.'),
  (185, 57, 1, '2023-10-17 10:30', 'retorno', 'Consulta de 6 meses, estou me sentindo ótimo', 118, 74, 60, 82.0, 'Sem angina, retomou a loja e a atividade física. Teste ergométrico: 10 METs, sem isquemia, resposta pressórica normal. FEVE 58% no ECO de controle. Sem tabagismo. LDL 54. Sem sangramentos. Pergunta se pode parar o ticagrelor por ter melhorado. Exame físico sem edema, pulmões limpos, pulsos periféricos presentes.', 'Manter dupla antiagregação até completar 12 meses do evento (março de 2024), depois AAS isolado. Manter demais medicações. Reabilitação cardíaca concluída. Retorno em 6 meses.');
