insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (57, '2023-10-17', 'controlado', 'IAMCSST anterior tratado com ATC primária da DA e, depois, da CD. Recuperou FEVE de 45% para 58%, parou de fumar, completou reabilitação e está sem angina, com LDL 54 e PA 118x74.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (58, 'Dalva Aparecida Rodrigues Pimentel', 'F', '1960-08-19', 'Linhares', 'ES', 'Agricultora aposentada', 'HAS há 25 anos, cardiopatia hipertensiva e provável componente dilatado. Sem coronariopatia no CATE de 2021. Edema de MMII recorrente. Mora em sítio, filha mora longe. Compra os remédios por quinzena quando recebe a aposentadoria.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (186, 58, 11, '2022-09-06 08:20', 'consulta', 'Falta de ar para subir a ladeira de casa', 138, 86, 88, 72.5, 'Dispneia aos pequenos esforços (NYHA III), ortopneia com 2 travesseiros, edema 2+/4+ até joelhos. Pcte usa enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Ao exame: turgência jugular a 45 graus, B3, estertores em bases, hepatomegalia dolorosa. NT-proBNP 3.800 pg/mL. ECO: FEVE 30%, VE dilatado (DDVE 66 mm), IM moderada funcional. HD: ICFEr NYHA III, perfil quente e congesto.', 'Aumentar furosemida para 40 mg 12/12h por 5 dias. Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após pausa de 36 horas, iniciar espironolactona 25 mg e dapagliflozina 10 mg. Pesar-se diariamente, restrição de sal. Controle de K e creatinina em 7 dias.'),
  (187, 58, 11, '2022-11-15 08:40', 'retorno', 'Estou respirando melhor, mas fico tonta quando levanto', 104, 64, 66, 66.8, 'Perdeu 5,7 kg de líquido. Dispneia agora só a grandes esforços (NYHA II), sem ortopneia. Tontura ao levantar, PA sentada 104x64, sem síncope. K 4,9, creatinina 1,2. Sem hipercalemia. Edema ausente. Refere que o remédio novo "é caro" e que está se virando com ajuda da vizinha para buscar na farmácia popular.', 'Reduzir furosemida para 20 mg ao dia (congestão resolvida). Manter os quatro pilares nas doses atuais, sem escalonar o sacubitril/valsartana por causa da PA. Levantar devagar. Assistente social para acesso aos medicamentos. Retorno em 8 semanas com K e creatinina.'),
  (188, 58, 6, '2023-06-02 01:50', 'pronto_socorro', 'Não consigo respirar deitada, parece que vou me afogar', 186, 112, 118, 71.0, 'Trazida pela vizinha, taquipneica (FR 34), sat O2 84% em ar ambiente, sudorese, estertores até ápices, tosse com escarro róseo. Filha informa que há 3 semanas não compra remédios por falta de dinheiro e dos transportes. PA 186x112 e FC 118. EAP hipertensivo em ICFEr por abandono de tratamento. Troponina negativa, ECG com fibrilação atrial de resposta rápida não previamente documentada.', 'O2 por máscara com reservatório, furosemida 80 mg EV, nitroglicerina EV, VNI. Internação em UTI. Reiniciar tratamento oral após estabilização. Serviço social acionado. Cardioversão não indicada na fase aguda; anticoagulação a definir.');
