insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (58, '2023-06-02', 'piorou', 'ICFEr evoluiu com edema agudo de pulmão após três semanas sem medicação por dificuldade financeira e de acesso, e com FA de resposta rápida nova. Admitida na UTI, estável após diurético e vasodilatador. Necessita retomar os quatro pilares, anticoagular e ter apoio social.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (59, 'Walter Ferreira da Mata Júnior', 'M', '1949-05-21', 'Goiânia', 'GO', 'Taxista aposentado', 'HAS e DM2 há 15 anos, em uso de losartana 50 mg e metformina 850 mg. Palpitações esporádicas há 1 ano. Ex-tabagista (parou há 20 anos). Sedentário.', 'Alergia a penicilina (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (189, 59, 4, '2023-03-20 14:30', 'consulta', 'Coração disparando e cansaço', 144, 88, 128, 84.6, 'Paciente de 73 anos, queixa palpitações irregulares e cansaço há 2 meses. ECG: fibrilação atrial com resposta ventricular média de 128 bpm, sem pré-excitação. TSH normal. ECO: FEVE 56%, átrio esquerdo aumentado (46 mm), sem valvopatia significativa. CHA2DS2-VASc 3 (idade 65-74, HAS, DM). Clearance de creatinina 62 mL/min. HAS-BLED 2.', 'Iniciar rivaroxabana 20 mg com jantar e metoprolol succinato 50 mg para controle de frequência. Estratégia de controle de frequência por ser assintomático em repouso e idoso. Holter 24h em 30 dias. Retorno em 30 dias.'),
  (190, 59, 4, '2023-04-24 14:45', 'retorno', 'Trouxe o exame do Holter', 134, 82, 78, 84.0, 'Melhora do cansaço e das palpitações. Holter 24h: FA permanente, FC média 76 bpm, máxima 118 bpm, sem pausas > 2,5 s, sem TV. Sem sangramentos, sem melena. Hemoglobina 13,8, creatinina 1,1. Aderente ao rivaroxabana com a refeição principal. Ainda sente cansaço quando sobe escadas.', 'Manter controle de frequência e anticoagulação. Encaminhar para programa de exercícios supervisionados. Hemograma e creatinina a cada 6 meses. Orientado sobre sinais de sangramento e evitar anti-inflamatórios. Retorno em 6 meses.'),
  (191, 59, 4, '2024-05-06 15:00', 'retorno', 'Consulta de rotina, sem queixas', 130, 78, 72, 82.8, 'Há mais de um ano em FA permanente com FC controlada, sem sintomas limitantes. Faz caminhada 3x/semana. Clearance de creatinina 54 mL/min mantém dose de 20 mg (não reduz até < 50). Hb 13,5. HbA1c 7,1%. Sem sangramentos nem quedas. Teme a rotina de exames; comenta que rivaroxabana "é bem mais fácil que a varfarina que meu irmão toma".', 'Manter conduta e dose. Reavaliar função renal em 3-4 meses, dada a queda do clearance, para ajuste da dose se < 50. Retorno em 6 meses.');
