insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (59, '2024-05-06', 'estavel', 'FA permanente em idoso com HAS e DM2, em controle de frequência e anticoagulado com rivaroxabana, sem sangramentos nem eventos embólicos. FC média 72 bpm e sem sintomas limitantes. Segue em acompanhamento semestral com função renal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (60, 'Maria Divina Gontijo Albuquerque', 'F', '1963-01-29', 'Bambuí', 'MG', 'Lavradora', 'Doença de Chagas diagnosticada aos 40 anos por sorologia positiva. Nasceu e morou em casa de pau a pique. HAS leve. Mãe morreu de morte súbita aos 52 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (192, 60, 11, '2022-02-10 09:00', 'consulta', 'Cansaço para o serviço da roça e batedeira', 126, 80, 58, 61.4, 'Cardiopatia chagásica crônica, queixa cansaço aos esforços moderados (NYHA II) e palpitações. Nega síncope. Ao exame: BEG, jugulares normais, RCR 2T BNF, B3 ausente, MV+ sem RA, sem edema. ECG: bloqueio de ramo direito e BDAS. Holter: 340 extrassístoles ventriculares isoladas por hora e 2 episódios de TV não sustentada. ECO: FEVE 38%, aneurisma apical.', 'Não há indicação de benznidazol, pois cardiopatia estabelecida. Iniciar carvedilol 3,125 mg 12/12h, enalapril 5 mg 12/12h, espironolactona 25 mg. Evitar iSGLT2 até segunda avaliação. Solicitar Holter de 24h e RM cardíaca. Retorno em 30 dias.'),
  (193, 60, 4, '2022-03-14 09:30', 'retorno', 'Quase desmaiei na roça semana passada', 118, 72, 52, 61.0, 'Episódio de pré-síncope há 1 semana, sem perda de consciência. FC 52 bpm sob carvedilol, pulso regular. Repetido Holter: FC mínima 38 bpm durante a vigília com pausa de 2,8 s, TV não sustentada mantida, sem BAV de alto grau. Risco de morte súbita elevado (FEVE 38%, TVNS, aneurisma apical).', 'Suspender carvedilol pela bradicardia sintomática, mantendo enalapril e espironolactona. Solicitar RM com realce tardio e avaliar CDI em prevenção primária. Holter prolongado 7 dias. Retorno em 3 semanas.'),
  (194, 60, 4, '2022-08-30 10:00', 'retorno', 'Quero saber do aparelhinho no peito', 122, 76, 64, 62.2, 'Em lista para CDI, ainda sem acesso na rede local. Sem síncope desde a suspensão do carvedilol. RM cardíaca: fibrose extensa no segmento apical e inferolateral, FEVE 36%. Holter 7 dias: 2 episódios de TVNS, a mais longa de 9 batimentos. Aguarda CDI com marca-passo associado devido à bradicardia sinusal.', 'Iniciar amiodarona 200 mg/dia para suprimir TV. TSH e prova de função hepática a cada 6 meses. Manter enalapril e espironolactona. Insistir na vaga de CDI. Retorno em 3 meses.');
