insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (60, '2022-08-30', 'estavel', 'Cardiopatia chagásica crônica com FEVE 36%, TV não sustentada e bradicardia sinusal, sem indicação de benznidazol. Em uso de enalapril, espironolactona e amiodarona, sem síncope. Aguardando CDI na fila do serviço de referência; segue acompanhada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (61, 'Zilda Maria Pereira Lacerda', 'F', '1944-07-02', 'Nova Friburgo', 'RJ', 'Cozinheira aposentada', 'HAS há 30 anos, em uso de losartana 50 mg 12/12h, anlodipino 10 mg e hidroclorotiazida 25 mg. Osteoporose. Mora sozinha, filha mora na mesma rua. Uma queda no banheiro em 2022 sem fraturas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (195, 61, 3, '2023-03-08 10:20', 'consulta', 'Caí de novo ao levantar da cama', 156, 84, 70, 58.2, 'Paciente de 78 anos, segunda queda em 6 meses, ambas ao se levantar, com escurecimento da visão e tontura por poucos segundos, sem perda de consciência. Hematoma em quadril esquerdo, sem fratura (RX normal). PA deitada 156x84, em pé após 3 min 118x68, FC sem aumento compensatório (70 para 72). Hipotensão ortostática com HAS supina. Tomou todos os remédios pela manhã. Sódio 134, creatinina 1,1.', 'Suspender hidroclorotiazida (sódio baixo, depleção de volume) e reduzir anlodipino para 5 mg. Manter losartana. Orientado levantar em etapas, hidratação, meias elásticas, retirar tapetes de casa. Fisioterapia para equilíbrio. Retorno em 30 dias com MAPA.'),
  (196, 61, 3, '2023-04-12 10:00', 'retorno', 'Não tive mais tontura, mas tive medo de tirar o remédio', 148, 80, 68, 58.6, 'Sem novas quedas. Sódio 138. MAPA 24h: média 138x74, vigília 142x76, sono 128x68, com episódios de queda de PA após as refeições (hipotensão pós-prandial 100x60). PA sentada 148x80 e em pé 130x72, queda de 18 mmHg, sem sintomas. Come pouco e pouca água. Meta individualizada: PA sentada < 140/90 por fragilidade e risco de queda.', 'Manter losartana e anlodipino 5 mg. Alvo individualizado em idosa frágil com queda recente. Orientado fracionar as refeições, beber 1,5 L de água por dia, evitar banho quente prolongado. Reavaliar em 3 meses.'),
  (197, 61, 3, '2023-11-14 09:40', 'retorno', 'Estou firme, até voltei a caminhar na praça', 140, 78, 66, 60.1, 'Sete meses sem queda. Fisioterapia concluída, usa bengala. Ganhou 1,5 kg. PA sentada 140x78 e em pé 134x76, ortostatismo ausente. Exame sem edema. Sódio 139, creatinina 1,0. A filha a ajuda a organizar a caixa de remédios. Relata sentir-se mais segura.', 'Manter esquema atual e meta flexibilizada. Vitamina D e cálcio pela osteoporose. Densitometria em 6 meses. Retorno semestral, com orientação para ligar se tontura.');
