insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (61, '2023-11-14', 'melhorou', 'Idosa com HAS e hipotensão ortostática com quedas recorrentes. Após suspender o diurético e reduzir o anlodipino, sem novas quedas por 7 meses, com PA sentada 140x78 sem queda ortostática. Alvo flexibilizado pela fragilidade.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (62, 'Edivaldo Lima Tonini', 'M', '1967-02-14', 'Serra', 'ES', 'Mecânico de automóveis', 'HAS há 8 anos e DM2 há 6 anos, em uso de metformina e enalapril esporádico. Dois cigarros de palha por dia. Sedentário, consome refrigerante diariamente. Pai com doença renal e diálise.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (198, 62, 2, '2021-09-23 16:00', 'consulta', 'Vim porque o médico do posto mandou ver o coração', 164, 100, 80, 94.0, 'Mecânico de 54 anos, HAS e DM2 mal controlados, sem sintomas. PA 164x100. Exames do posto: HbA1c 8,8%, creatinina 1,2 (TFGe 68), potássio 4,7, relação albumina/creatinina urinária de 240 mg/g (albuminúria moderadamente aumentada, confirmada em 2 amostras). Fundo de olho sem retinopatia. ECG com SVE. HD: HAS estágio 2 com nefropatia incipiente diabética e hipertensiva.', 'Trocar enalapril por losartana 100 mg/dia (tosse seca com enalapril). Associar anlodipino 5 mg. Orientação nutricional e encaminhamento à endocrinologia. Repetir creatinina e potássio em 15 dias. Retorno em 6 semanas.'),
  (199, 62, 9, '2021-11-04 16:20', 'retorno', 'Consulta com a endócrino, açúcar alto', 144, 88, 78, 93.0, 'Creatinina 1,2, K 4,9 após BRA, sem tosse. HbA1c 8,8% mantida, glicemia de jejum 176. Adesão parcial: toma losartana, mas esquece metformina da noite. Neuropatia leve ao monofilamento. Peso estável. Quer evitar insulina. Reconhece que bebe 2 litros de refrigerante por dia.', 'Adicionar dapagliflozina 10 mg ao dia, com benefício renal e cardiovascular, orientando sobre higiene genital e hidratação. Suspender refrigerante. Revisar HbA1c em 3 meses e RAC em 3-6 meses. Retorno ao cardiologista em 60 dias.'),
  (200, 62, 2, '2022-02-10 16:10', 'retorno', 'A pressão está melhor, né?', 134, 84, 74, 90.8, 'Perdeu 3,2 kg, parou o refrigerante. PA 134x84. HbA1c 7,4%, RAC 118 mg/g (queda de 50%), creatinina 1,3 (queda inicial esperada da TFGe com iSGLT2), potássio 4,8. Referiu dois episódios de candidíase balanopostite tratados no posto. Está tomando tudo. Fuma ainda 2 cigarros de palha.', 'Manter losartana 100 mg, anlodipino 5 mg, dapagliflozina e metformina. Meta PA < 130/80: adicionar clortalidona 12,5 mg. Reforçada higiene genital. Retorno em 60 dias com eletrólitos e creatinina.');
