insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (62, '2023-06-30', 'abandonou', 'HAS e DM2 com albuminúria em melhora (RAC de 240 para 118 mg/g) até fevereiro de 2022. Não retornou ao ambulatório após a última consulta nem atendeu três ligações da equipe. Sem exames de seguimento registrados, risco de progressão da doença renal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (63, 'Cláudio Ferrari Mendonça', 'M', '1972-10-09', 'Macaé', 'RJ', 'Técnico de operações em plataforma de petróleo', 'HAS há 6 anos, atualmente com losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg sem controle. Obeso. Ronco alto, sonolência diurna, cochilos no trabalho. Escala 14 dias embarcado por 14 de folga.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (201, 63, 1, '2022-05-17 08:15', 'consulta', 'Pressão alta com três remédios e muito sono', 172, 108, 84, 118.0, 'Homem de 49 anos, IMC 38,5, circunferência cervical 46 cm. Esposa relata roncos intensos e pausas respiratórias durante o sono. Acorda com cefaleia, sonolência excessiva (Epworth 17). PA elevada em três drogas, adesão boa conferida por contagem. Pulsos presentes, sem sopros abdominais. K 4,0, creatinina 1,0, TSH normal, aldosterona/renina normal. Alta suspeita de apneia obstrutiva do sono como causa de HAS resistente.', 'Solicitar polissonografia de noite inteira. Orientar perda de peso e redução do álcool. Sugerir evitar condução de veículos se sonolento. Manter esquema até resultado. Retorno em 30 dias.'),
  (202, 63, 1, '2022-06-28 08:30', 'retorno', 'Fiz a polissonografia na folga', 168, 104, 82, 117.5, 'Polissonografia: IAH 52 eventos/h (apneia obstrutiva grave), SpO2 mínima 71%, T90 de 28%. Dessaturação importante em sono REM. MAPA com ausência de descenso noturno (padrão non-dipper). Pcte desconhecia a gravidade da apneia e se mostrou assustado. Ecocardiograma: HVE leve, FEVE 62%.', 'Encaminhar à medicina do sono para titulação de CPAP, que será fornecido pelo plano da empresa. Iniciar espironolactona 25 mg para reduzir a PA (apneia + resistência). Controle de K e creatinina em 15 dias. Retorno em 60 dias.'),
  (203, 63, 1, '2022-10-04 08:45', 'retorno', 'Uso a máquina de dormir faz três meses', 128, 78, 72, 109.0, 'Usa CPAP automático (pressão média 11 cmH2O) mais de 6 horas por noite, inclusive embarcado, com adesão de 92% pelo relatório do aparelho; IAH residual 3,1/h. Acabou a sonolência e as cefaleias. Perdeu 8,5 kg. PA 128x78 e MAPA com descenso noturno restaurado (média 24h 124x76). K 4,6, creatinina 1,0.', 'Suspender espironolactona e reavaliar em 6 semanas. Manter losartana, anlodipino e clortalidona. Continuar CPAP e perda de peso. Atestar uso de CPAP na plataforma. Retorno em 90 dias com MRPA.');
