insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (63, '2022-10-04', 'controlado', 'Hipertensão secundária à apneia obstrutiva grave (IAH 52), resolvida em grande parte com CPAP e perda de 8,5 kg. PA passou de 172x108 para 128x78 e a espironolactona pôde ser suspensa. Mantém três anti-hipertensivos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (64, 'Vera Lúcia Brandão Teixeira', 'F', '1969-05-30', 'Volta Redonda', 'RJ', 'Costureira em confecção', 'HAS há 12 anos, em uso de anlodipino 5 mg e captopril 50 mg 12/12h. Sem diabetes. Na última semana ficou sem comprar os remédios por falta de dinheiro depois de perda de renda. Fumante de 5 cigarros por dia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (204, 64, 6, '2024-01-22 19:40', 'pronto_socorro', 'Dor de cabeça e a pressão deu 21 por 12', 214, 122, 88, 71.0, 'Cefaleia holocraniana leve há 2 dias após 8 dias sem anti-hipertensivos. Sem dor torácica, dispneia, déficit neurológico, alteração visual ou vômitos. Exame neurológico normal, fundo de olho sem papiledema nem hemorragias, ausculta pulmonar limpa, sem B3. ECG sem alterações isquêmicas agudas, SVE. Troponina negativa, creatinina 1,0. Urgência hipertensiva (PA > 180/120 sem lesão aguda de órgão-alvo) por interrupção do tratamento.', 'Repouso por 30 min e captopril 25 mg VO. PA em 3 h: 168x98 sem sintomas. Reintroduzir esquema oral, sem queda abrupta da PA e sem medicação venosa. Receita de 30 dias, orientada UBS para fornecimento. Retorno em 7 dias na cardiologia.'),
  (205, 64, 2, '2024-01-29 14:00', 'retorno', 'Voltei como mandaram', 154, 92, 80, 70.6, 'Uma semana de retomada do tratamento, sem cefaleia. PA 154x92. Conseguiu os medicamentos no posto de saúde. Refere que o captopril 3 vezes ao dia atrapalha pois trabalha, esquece doses do meio-dia. ECO: FEVE 66%, HVE concêntrica leve. Creatinina 0,9, K 4,3.', 'Trocar captopril por losartana 50 mg 12/12h e manter anlodipino 5 mg, para posologia mais simples. Falar com assistente social sobre acesso ao medicamento. Retorno em 30 dias.'),
  (206, 64, 2, '2024-03-18 14:20', 'retorno', 'Estou tomando direitinho', 128, 80, 72, 70.0, 'Tomando as duas medicações todos os dias, pega em dia no posto. PA 128x80. Creatinina 0,9, K 4,4. Reduziu para 3 cigarros por dia, aceitou apoio ao tabagismo. Sem cefaleia desde o PS. Exame físico sem alterações: ausculta cardíaca normal, pulmões limpos, sem edema. Conta que a patroa liberou o horário para ir ao posto buscar o remédio todo mês.', 'Manter losartana e anlodipino. Encaminhar para grupo de tabagismo da UBS. Retorno em 4 meses com MRPA. Orientada a nunca suspender sem conversar, e a procurar a UBS antes de acabar o remédio.');
