insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (64, '2024-03-18', 'controlado', 'Urgência hipertensiva (214x122, sem lesão de órgão-alvo aguda) após 8 dias sem medicação por falta de dinheiro, manejada no PS com captopril oral. Após simplificar o esquema e garantir o acesso pelo posto, PA 128x80 sem novos episódios.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (65, 'Fabiana Oliveira Gouveia', 'F', '1986-03-18', 'Itaperuna', 'RJ', 'Enfermeira', 'Sem comorbidades. Pais hipertensos. Atividade física regular (musculação). Não fuma. Quadro de ansiedade leve em consultas médicas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (207, 65, 1, '2022-09-12 15:00', 'consulta', 'A pressão sempre dá alta quando eu entro em consultório', 152, 94, 84, 63.5, 'Enfermeira de 36 anos, assintomática, fez avaliação para plano de saúde e foi orientada a tratar "pressão alta". PA de consultório 152x94 e 150x92 (FC 84, ansiosa). Em casa mede 118x74 com aparelho validado, e no hospital onde trabalha 120x76. Sem LOA: ECG normal, creatinina 0,7, EAS normal. Quadro sugestivo de hipertensão do avental branco.', 'Não iniciar medicação. Solicitado MAPA 24h para confirmação. Orientar manter atividade física, sal moderado. Retorno com resultado em 3 semanas.'),
  (208, 65, 1, '2022-10-05 15:10', 'retorno', 'Trouxe o resultado da MAPA', 148, 90, 80, 63.2, 'MAPA 24h: média 24h 117x73, vigília 121x76, sono 106x62, descenso noturno preservado. Efeito do avental branco de cerca de 30 mmHg na sistólica. ECO com FEVE 66% e geometria normal, sem HVE. Sem outros fatores de risco. Explicado o conceito de hipertensão do avental branco e que o risco é menor, mas requer seguimento por possível progressão.', 'Sem medicação. Manter MEV. MRPA ou MAPA anual para vigilância, pelo risco de evoluir para HAS sustentada. Orientada que aferições de consultório isoladas não devem ditar tratamento.'),
  (209, 65, 1, '2023-10-09 16:00', 'retorno', 'Vim fazer o acompanhamento anual', 138, 86, 70, 64.0, 'Assintomática. MRPA de 5 dias com média de 119x75. Pressão de consultório menor que em 2022 (138x86), embora ainda elevada. Mantém musculação 4x/semana. Glicemia de jejum 88, LDL 102, creatinina 0,7. Exame físico normal, sem sopros. Relata que na bancada do hospital mede a própria pressão sem alteração e que o consultório continua lhe dando tensão.', 'Manter conduta expectante sem medicamentos. Manter MRPA anual. Se média domiciliar ≥ 130/80, repetir MAPA. Orientação sobre dieta com sódio moderado.');
