insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (65, '2023-10-09', 'estavel', 'Hipertensão do avental branco confirmada por MAPA (média 117x73) e MRPA, sem lesão de órgão-alvo e sem necessidade de medicação. Em vigilância anual com MRPA, por risco de evolução para HAS sustentada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (66, 'Gilberto Wolff Albrecht', 'M', '1959-08-11', 'Curitiba', 'PR', 'Engenheiro civil', 'HAS e dislipidemia há 15 anos. Ex-fumante (parou aos 45). Pai com infarto aos 62 anos. Corre 3 vezes por semana, mas nas últimas semanas precisou parar por desconforto no peito.', 'Alergia a AAS (broncoespasmo leve)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (210, 66, 2, '2022-06-13 08:00', 'consulta', 'Aperto no peito quando corro ou subo ladeira', 136, 84, 66, 82.0, 'Engenheiro de 62 anos com dor torácica opressiva em esforço (CCS II), que melhora com repouso em 3-5 min, há 6 semanas, progressiva. ECG em repouso normal. Exame sem alterações. Usa losartana 50 mg e atorvastatina 20 mg. LDL 96, creatinina 1,0. Angina estável de probabilidade pré-teste alta. Alergia a AAS limita antiagregação.', 'Iniciar metoprolol succinato 50 mg e clopidogrel 75 mg (intolerância a AAS), atorvastatina para 80 mg. Nitrato SL SN. Solicitar cintilografia de perfusão miocárdica com estresse. Retorno em 2 semanas.'),
  (211, 66, 2, '2022-06-30 08:20', 'retorno', 'Fiz o exame de esforço com o contraste', 124, 74, 56, 81.6, 'Cintilografia com estresse farmacológico: isquemia de grau moderado em parede anterior e septal (12% do ventrículo), FEVE 58%. Dores aliviadas parcialmente com betabloqueador, ainda 1-2 episódios por semana. Pela extensão da isquemia e persistência dos sintomas, indicada estratificação anatômica. Sem dispneia em repouso, exame cardiovascular e pulmonar normais.', 'Encaminhar para cateterismo diagnóstico, com possível angioplastia no mesmo tempo. Manter clopidogrel até o procedimento. Orientado evitar esforços intensos até o resultado.'),
  (212, 66, 10, '2022-07-19 07:30', 'internacao', 'Internado para cateterismo e angioplastia', 130, 78, 58, 81.9, 'CATE por radial direita: lesão de 80% no terço proximal da DA, com calcificação moderada, CD e Cx sem lesões significativas. FFR de 0,72. Realizada ATC com stent farmacológico 3,5 x 24 mm após pré-dilatação, resultado angiográfico ótimo, sem dissecção. Sem complicações. Alta no dia seguinte. Ficou em jejum e hidratado. Sem sinais de contraste nefropatia.', 'Clopidogrel 75 mg por 6 meses (síndrome crônica) e depois reavaliar; sem AAS por alergia. Manter estatina em dose alta e betabloqueador. Reabilitação cardíaca. Retorno em 30 dias.');
