insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (66, '2022-09-15', 'melhorou', 'Angina estável com isquemia anterior moderada tratada com angioplastia e stent farmacológico em DA proximal. Sem recorrência de dor, retomou corrida leve em reabilitação cardíaca. Segue com clopidogrel por alergia a AAS, estatina e betabloqueador.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (67, 'Therezinha de Jesus Falcão Moretti', 'F', '1952-12-25', 'Guarapari', 'ES', 'Professora aposentada', 'HAS há 25 anos, DM2 e obesidade (IMC 34). Dispneia progressiva há 1 ano. Sem tabagismo. Faz hidroginástica esporadicamente. Mora com marido idoso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (213, 67, 11, '2023-08-03 10:00', 'consulta', 'Falta de ar e inchaço nas pernas à tarde', 152, 84, 76, 88.0, 'Professora de 70 anos, dispneia NYHA II-III, edema vespertino 2+/4+, ganhou 4 kg em 3 meses. Ao exame: turgência jugular discreta, RCR 2T BNF, B4, MV+ com estertores finos em bases, hepatomegalia leve. NT-proBNP 920 pg/mL. ECO: FEVE 62%, relação E/e'' 16, AE aumentado (volume 44 mL/m²), HVE concêntrica, PSAP 42 mmHg. HD: ICFEp hipertensiva, congesta, com obesidade e DM2.', 'Furosemida 40 mg/dia, dapagliflozina 10 mg (benefício na ICFEp e DM2) e espironolactona 25 mg. Manter losartana. Restrição de sal e controle diário do peso. Programa de exercício supervisionado. Retorno em 30 dias com K e creatinina.'),
  (214, 67, 11, '2023-09-05 10:20', 'retorno', 'Perdi o inchaço, mas estou com muita sede e urino demais', 132, 76, 72, 83.4, 'Perdeu 4,6 kg, sem edema e sem estertores. Dispneia NYHA I-II. Queixa de poliúria e noctúria que atribui aos remédios novos; K 5,0, creatinina 1,1. PA 132x76. Sem tontura. Tem dificuldade em fazer o controle de peso porque a balança é antiga. Glicemia de jejum 118.', 'Reduzir furosemida para 20 mg/dia, mantendo dapagliflozina e espironolactona. Orientar ingestão hídrica moderada e tomar o diurético pela manhã. Prescrito atividade física leve. Repetir K e creatinina em 4 semanas.'),
  (215, 67, 11, '2024-03-12 10:00', 'retorno', 'Consigo andar na orla sem parar', 126, 74, 70, 80.2, 'Seis meses de acompanhamento sem internação. Caminha 30 minutos na orla 4x/semana, NYHA I. Peso seco 80 kg, sem edema. NT-proBNP caiu para 340 pg/mL. HbA1c 6,8%. K 4,8, creatinina 1,0. PA 126x74. Sem infecção genital ou urinária com a dapagliflozina.', 'Manter esquema, sem alterações. Meta de peso por mais 5 kg. Vacinas de influenza e pneumocócica atualizadas. Retorno em 6 meses.');
