insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (67, '2024-03-12', 'controlado', 'ICFEp hipertensiva e diabética em NYHA I, com NT-proBNP de 920 para 340 pg/mL e peso seco em 80 kg. Sem internações após dapagliflozina, espironolactona e diurético em dose baixa. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (68, 'Odete Rosane Kunzler', 'F', '1950-09-04', 'Porto Alegre', 'RS', 'Aposentada, ex-secretária', 'HAS e artrose de joelhos. FA paroxística diagnosticada em 2021, em uso de apixabana 5 mg 12/12h. Usa ibuprofeno por conta própria para dor no joelho. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (216, 68, 6, '2023-07-04 06:20', 'pronto_socorro', 'Fezes pretas e fraqueza desde ontem', 96, 58, 112, 66.0, 'Paciente de 72 anos com melena há 2 dias, tontura e síncope ao se levantar. Pálida, taquicárdica, sudorética, extremidades frias. Toque retal com melena. Hemoglobina 6,8 g/dL (prévia 12,5). Ureia 78, creatinina 1,2. Uso de apixabana 5 mg 12/12h e ibuprofeno 600 mg 2x/dia nos últimos 20 dias. Hemorragia digestiva alta com repercussão hemodinâmica, relacionada a anticoagulante + AINE.', 'Dois acessos calibrosos, cristaloide e transfusão de 2 concentrados de hemácias. Suspender apixabana e ibuprofeno. Omeprazol 80 mg EV em bolus. Endoscopia em até 24 h. Última dose de apixabana há 10 h; sem uso de andexanet por ausência de sangramento ativo maciço. Internação.'),
  (217, 68, 14, '2023-07-05 10:00', 'internacao', 'Pós-endoscopia, enfermaria de gastro', 118, 70, 88, 66.0, 'Endoscopia: úlcera duodenal de 1 cm em bulbo com vaso visível (Forrest IIa), tratada com adrenalina e hemoclipes. Pesquisa de H. pylori positiva. Hb pós-transfusão 9,2, estável nas 24 h seguintes, sem novo sangramento. PA normalizada. FA com FC de 88 sem medicação específica. Ibuprofeno é o provável fator desencadeante, junto a H. pylori.', 'Omeprazol 40 mg 2x ao dia por 8 semanas, erradicação de H. pylori (amoxicilina, claritromicina e omeprazol por 14 dias). Anticoagulante mantido suspenso por 7 dias; reintroduzir se Hb estável e sem ressangramento. Contraindicar AINEs; dor com paracetamol.'),
  (218, 68, 4, '2023-07-24 14:00', 'retorno', 'Voltar a tomar o anticoagulante?', 134, 78, 74, 65.2, 'Alta há 18 dias, sem novas melenas. Hb 11,2, sem dor abdominal. Ritmo atual sinusal ao ECG (FA paroxística). CHA2DS2-VASc 4 (idade 65-74, sexo feminino, HAS e FA de risco para AVC); HAS-BLED 3 pelo evento. Risco embólico anual elevado: reintrodução do anticoagulante é benéfica, uma vez que o fator sangrante (AINE + H. pylori) foi tratado.', 'Reintroduzir apixabana 5 mg 12/12h, mantendo omeprazol 40 mg/dia (gastroproteção). Hemograma em 30 dias. Evitar totalmente AINEs. Reavaliar endoscopia de cicatrização em 8 semanas. Considerar oclusão de apêndice atrial se novo sangramento.');
