insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (70, 'Hilda Aparecida Fontenele Brito', 'F', '1941-11-17', 'Teresópolis', 'RJ', 'Aposentada, ex-professora de piano', 'HAS há 40 anos, em uso de anlodipino e losartana. Hipotireoidismo tratado. Sem cardiopatia conhecida. Duas quedas recentes com desmaio rápido.', 'Alergia a sulfa');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (222, 70, 6, '2022-07-08 05:30', 'pronto_socorro', 'Desmaiei no banheiro e bati a cabeça', 168, 74, 34, 62.0, 'Paciente de 80 anos, trazida pela filha após síncope súbita, sem pródromos, com trauma craniano leve e lacerações no supercílio. Nos últimos dias, tonturas e cansaço. Sem déficits neurológicos focais. Pulso lento regular, FC 34 bpm; PA 168x74, sem sinais de IC. ECG: bloqueio atrioventricular total com escape juncional a 34 bpm. Troponina negativa, K 4,4, TSH 3,2. TC de crânio sem lesões.', 'Monitorização, pás de marca-passo transcutâneo à beira-leito, atropina 0,5 mg sem resposta. Iniciada dopamina e acionada cardiologia para marca-passo provisório. Suspender anlodipino. Transferência para UTI.'),
  (223, 70, 4, '2022-07-09 09:00', 'internacao', 'Implante de marca-passo definitivo', 142, 70, 70, 62.0, 'Marca-passo provisório via veia jugular na noite anterior, estável. BAVT sem causa reversível (sem isquemia, K normal, TSH normal, sem fármacos bradicardizantes). Implantado MP definitivo dupla câmara (DDD) via veia subclávia esquerda, sem pneumotórax ao RX de controle. Programação: limite inferior 60 bpm. Teve ECG com ritmo estimulado com QRS de 130 ms.', 'Alta em 48 h. Cuidados com a ferida, sem elevar o braço esquerdo acima do ombro por 4 semanas. Cefalexina por 5 dias. Entregue carteira do dispositivo. Retorno para revisão da ferida em 10 dias e checagem do marca-passo em 30 dias.'),
  (224, 70, 4, '2022-08-08 10:00', 'retorno', 'Estou me sentindo outra pessoa', 150, 78, 70, 62.8, 'Sem novos desmaios ou tonturas. Exame com RCR 2T, sem sopros, MV+ sem RA. Voltou a tocar piano. Ferida cicatrizada sem hematoma. Interrogação do MP: limiar de captura atrial 0,6 V e ventricular 0,8 V a 0,4 ms, impedâncias normais, 98% de estimulação ventricular, sem arritmias atriais. PA 150x78 após suspensão do anlodipino.', 'Manter losartana e reintroduzir anlodipino 2,5 mg, buscando PA < 140/90 sem hipotensão. Seguimento do MP a cada 6 meses. Liberada para atividades normais, com cuidado com campos magnéticos intensos.'),
  (225, 70, 4, '2023-02-14 10:30', 'retorno', 'Revisão semestral do aparelho', 138, 76, 70, 63.0, 'Sem sintomas, sem síncope. Interrogação: parâmetros estáveis, sem eventos de alta frequência atrial, bateria em 98%. Ritmo de marca-passo com condução AV intrínseca ausente (dependente). PA 138x76. Faz caminhada diária de 40 minutos. TSH normal. Exame sem edema, pulmões limpos, ferida com cicatriz fina sem sinais de erosão do gerador. Filha diz que ela não voltou a ter desmaios nem quedas.', 'Manter programação e medicações. Revisão do MP a cada 6 meses e teletransmissão quando disponível. Orientada a ligar se tontura ou síncope.');
