insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (70, '2023-02-14', 'controlado', 'BAVT com síncope em idosa de 80 anos, resolvido com implante de marca-passo definitivo DDD. Sem novas síncopes, parâmetros do dispositivo estáveis, PA 138x76 com anti-hipertensivos em dose baixa, e voltou às atividades habituais.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (71, 'Anderson Luís Pimenta Cerqueira', 'M', '1975-06-22', 'Cariacica', 'ES', 'Motorista de aplicativo', 'HAS há 5 anos, em uso irregular de enalapril 10 mg. Come na rua, bebe refrigerante e dorme pouco. Fumante de 10 cigarros/dia. Pai falecido de AVC aos 63 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (226, 71, 5, '2022-03-29 18:30', 'consulta', 'Tosse seca que não passa há meses', 162, 100, 84, 92.5, 'Motorista de aplicativo de 46 anos com tosse seca irritativa há 4 meses, pior à noite, sem febre, sem dispneia. Raio X de tórax sem alterações. Parou o enalapril há 2 meses "porque a tosse piorava" e sem receita nova ficou sem tratamento. PA 162x100. Tosse persistente, sem expectoração, sem sibilos. Sem sinais de IC. Provável tosse por IECA (início ao uso, melhora parcial após pausa).', 'Trocar IECA por BRA: iniciar losartana 50 mg 12/12h, sem associações. Orientar que a tosse deve melhorar em 2-4 semanas após a suspensão total do IECA. Exames de rotina solicitados. Retorno em 30 dias. Orientado a tomar mesmo sentindo-se bem.'),
  (227, 71, 5, '2022-04-26 18:40', 'retorno', 'Tosse sumiu, acho que era o remédio mesmo', 142, 88, 80, 92.0, 'Tosse resolvida na terceira semana. Tomando losartana com regularidade, mas faltou duas vezes porque ficou na estrada. PA 142x88. K 4,5, creatinina 1,1. Dorme 5 horas por dia, bebe 1,5 L de refrigerante. Fuma 10 por dia. Sem queixas cardiovasculares. Prometeu levar um comprimido no carro.', 'Associar anlodipino 5 mg pela manhã para atingir a meta, com atenção a edema. Entregue folheto de dieta com pouco sal. Orientações de pausa e alimentação no trabalho. Retorno em 8 semanas.'),
  (228, 71, 5, '2022-07-12 19:00', 'retorno', 'A pressão tá ótima, vim pedir receita', 124, 78, 74, 90.6, 'PA 124x78, na meta. Sem tosse, sem edema relevante (leve edema de tornozelo vespertino, 1+). Perdeu 1,4 kg. Fala que pensa em parar os remédios "já que a pressão está boa e remédio vicia". Foi desmentido que os remédios viciam, mas que a PA normal é efeito do tratamento. Fuma 8 cigarros/dia.', 'Manter losartana 50 mg 12/12h e anlodipino 5 mg. Reforçado que é tratamento contínuo. Receita para 90 dias. Retorno em 3 meses com MRPA e exames.');
