insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (71, '2023-02-20', 'abandonou', 'Tosse por enalapril resolvida com a troca para losartana e PA na meta em julho de 2022. Não retornou para as consultas de acompanhamento; a UBS soube por contato telefônico que ele havia parado os remédios por achar que estava curado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (72, 'Marlene dos Reis Quintanilha', 'F', '1960-01-09', 'Rio de Janeiro', 'RJ', 'Empregada doméstica', 'HAS há 20 anos, dislipidemia e obesidade grau I. Usa losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg há 2 anos, sempre com PA acima da meta. Mãe com AVC. Dorme bem, não ronca.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (229, 72, 1, '2022-10-20 13:00', 'consulta', 'Mesmo tomando tudo a pressão não baixa', 168, 96, 74, 79.3, 'Encaminhada pela UBS com suspeita de HAS resistente. Avaliação: usa manguito adequado (circunferência braquial 31 cm), PA 168x96. Adesão confirmada por contagem de comprimidos e receitas retiradas todo mês. MAPA 24h: média 158x92, vigília 162x94, sem efeito do avental branco. Creatinina 0,9, K 4,0, sódio 140, aldosterona/renina normal. Sem sopros abdominais. Não usa AINE, descongestionantes ou corticoide. HAS resistente verdadeira.', 'Adicionar espironolactona 25 mg/dia (quarta droga). Dosar K e creatinina em 7 e 30 dias. Orientar dieta com pouco sal (excreção de sódio urinário de 24h altas). Retorno em 45 dias.'),
  (230, 72, 1, '2022-12-06 13:10', 'retorno', 'A pressão baixou bem', 136, 82, 70, 78.0, 'Tolera espironolactona, sem ginecomastia ou irregularidade menstrual (menopausa). PA 136x82. K 4,9 e creatinina 1,1 em 30 dias, aceitáveis. Reduziu sal depois de entender que o tempero pronto e o caldo de carne contêm muito sódio. Sem edema, sem câimbras. Peso em queda.', 'Subir espironolactona para 50 mg/dia. Repetir K e creatinina em 15 dias. Se K ≥ 5,5, reduzir a dose. Manter os demais fármacos. Retorno em 8 semanas.'),
  (231, 72, 1, '2023-02-14 13:20', 'retorno', 'Estou me sentindo bem, mas fiz exames', 124, 76, 68, 76.9, 'PA 124x76 e MRPA com média de 122x75. K 5,2 e creatinina 1,2 (TFGe 49), discreto aumento. Sem sintomas. Verificado: usa sal substituto "light" rico em potássio, nova compra da filha. Sem queixas de câimbras, sem arritmia no ECG (T normais).', 'Suspender substituto de sal com potássio. Manter espironolactona 50 mg e repetir K e creatinina em 2 semanas. Se K > 5,5, reduzir dose para 25 mg. Orientação nutricional. Retorno em 3 meses.'),
  (232, 72, 1, '2023-05-16 13:00', 'retorno', 'Vim ver os exames de novo', 122, 74, 68, 76.5, 'Sem substituto de sal. K 4,8 e creatinina 1,0. PA 122x74 e MRPA na meta. HAS resistente verdadeira controlada com quatro drogas, incluindo espironolactona. Sem efeitos adversos. Boa adesão, confere os comprimidos na caixa semanal. Peso estável. Exame cardiovascular sem alterações, sem edema, pulmões limpos. Diz que o trabalho de limpeza pesada voltou a ser tranquilo e que não sente mais a nuca latejar.', 'Manter esquema com espironolactona 50 mg. Controle de K e creatinina a cada 3 meses no primeiro ano. Retorno semestral. Orientada a evitar AINEs e suplementos de potássio.');
