insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (72, '2023-05-16', 'controlado', 'HAS resistente verdadeira, confirmada por MAPA com adesão comprovada, controlada com a adição de espironolactona 50 mg. Uma hipercalemia leve causada por sal substituto com potássio foi corrigida. PA 122x74 com monitoramento regular de K e creatinina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (73, 'Osvaldo Gomes Tinoco', 'M', '1955-03-26', 'Angra dos Reis', 'RJ', 'Pescador aposentado', 'Tabagista há 45 anos (60 maços-ano). HAS há 10 anos, DLP e doença arterial periférica com claudicação. Recentemente a PA ficou difícil de controlar. Sem diabetes.', 'Alergia a contraste iodado (urticária leve)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (233, 73, 8, '2022-04-05 10:00', 'consulta', 'Pressão descontrolada e urina diminuiu', 196, 106, 78, 74.0, 'Paciente de 67 anos, HAS com piora súbita há 3 meses mesmo em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Creatinina subiu de 1,3 para 2,1 após introdução de losartana há 2 meses. Sopro sistólico-diastólico em flanco esquerdo audível, pulsos femorais diminuídos, sopro em femoral. PA 196x106. Rim esquerdo 8,5 cm, direito 11,2 cm à ultrassonografia. Suspeita de estenose de artéria renal aterosclerótica com HAS renovascular.', 'Suspender losartana (queda abrupta da TFG com BRA). Manter anlodipino e clortalidona, associar carvedilol 12,5 mg 12/12h. Solicitar Doppler de artérias renais. Evitar contraste iodado (alergia). Retorno em 2 semanas.'),
  (234, 73, 8, '2022-04-19 10:10', 'retorno', 'Fiz o exame do rim', 178, 98, 66, 73.5, 'Creatinina em queda para 1,6 após suspender o BRA. Doppler de artérias renais: estenose significativa da artéria renal esquerda com velocidade de pico sistólico de 380 cm/s e índice renal-aórtico de 4,2; artéria renal direita com 40% de estenose. Ângio-RM sem gadolínio possível: confirma estenose de 80% à esquerda, com rim esquerdo atrófico. PA ainda 178x98.', 'Estenose aterosclerótica bilateral assimétrica, com função renal estável e PA controlável: iniciar terapia clínica máxima (estatina em alta potência, AAS, controle de PA). Intervenção por angioplastia reservada para edema agudo de pulmão recorrente, PA refratária ou perda de função. Reavaliar em 30 dias.'),
  (235, 73, 6, '2022-07-12 02:20', 'pronto_socorro', 'Acordei sem ar, afogado', 232, 124, 112, 75.2, 'Edema agudo de pulmão hipertensivo "flash" com dispneia súbita, sat O2 82%, estertores difusos, sem dor torácica. PA 232x124. ECG sem isquemia aguda, sem FA, troponina negativa. Creatinina 2,4. ECO: FEVE 58%, sem valvopatia importante, HVE. Quadro típico de EAP súbito em estenose renal aterosclerótica bilateral.', 'Nitroglicerina EV em dose crescente, furosemida 40 mg EV, VNI. Melhora em 2 horas, PA 150x84. Internação, evitando IECA/BRA. Programar angioplastia de artéria renal com stent (protocolo para alergia a contraste) via nefrologia e hemodinâmica.'),
  (236, 73, 10, '2022-09-20 09:30', 'retorno', 'Pós-angioplastia do rim, vim ver como está', 138, 80, 64, 73.0, 'Realizada angioplastia com stent em artéria renal esquerda com pré-medicação para alergia a contraste (prednisona e anti-histamínico), sem reação. Estenose residual < 10%, fluxo normal. Desde então sem crises de dispneia. PA 138x80 e creatinina em 1,5. Doppler pós-procedimento com PSV de 140 cm/s. Reduziu o cigarro para 5 por dia.', 'Manter AAS e clopidogrel por 1 mês, depois AAS isolado. Suspender furosemida. Considerar reintrodução de BRA em baixa dose apenas com monitoração. Doppler em 6 meses. Reforçado tabagismo.');
