insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (73, '2022-09-20', 'melhorou', 'Hipertensão renovascular por estenose aterosclerótica de artéria renal esquerda, com crise de edema agudo de pulmão em julho de 2022. Após angioplastia com stent, PA em 138x80, sem novos EAP e função renal mais estável. Mantém tabagismo reduzido e antiagregação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (74, 'Larissa Menezes Cardozo Teodoro', 'F', '1993-08-14', 'Belo Horizonte', 'MG', 'Estudante de direito', 'Sem comorbidades. Quadro de ansiedade em tratamento irregular. Período de provas da OAB, dorme 4 horas por noite e toma muito café e energético. Sem uso de drogas ilícitas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (237, 74, 6, '2025-03-06 22:50', 'pronto_socorro', 'Coração disparado, formigamento nas mãos e a pressão deu 18 por 10', 178, 104, 124, 58.0, 'Jovem de 31 anos chega após aferição domiciliar de 180x110. Início súbito de palpitações, sensação de morte iminente, falta de ar, formigamento perioral e nas mãos, sudorese fria, após receber notícia da prova. Sem dor torácica, sem déficit neurológico. Exame: ansiosa, hiperventilando, FR 26, sat 99%, ritmo regular, pulmões limpos. ECG: taquicardia sinusal a 124. Troponina negativa. Suspeita de crise de pânico com pseudocrise hipertensiva.', 'Sem anti-hipertensivo. Orientada respiração lenta, ambiente calmo. Alprazolam 0,25 mg SL, uma dose. Reavaliada em 45 min: PA 128x78, FC 84, sintomas resolvidos. Alta com orientação de procurar cardiologia e acompanhamento psicológico.'),
  (238, 74, 1, '2025-03-27 16:00', 'consulta', 'Quero saber se tenho pressão alta mesmo', 118, 72, 76, 58.4, 'Ansiosa mas colaborativa. Segue com palpitações esporádicas, melhora com respiração. Consome 5 cafés e 2 energéticos por dia. Exame cardiovascular normal, PA 118x72. MAPA 24h: média 114x70, sem períodos de hipertensão (picos de 146x88 durante crises de ansiedade). Holter 24h com taquicardia sinusal apenas em momentos de estresse, sem arritmias. ECO normal. TSH 2,0.', 'Sem diagnóstico de hipertensão. Suspender energéticos, reduzir café para 2 xícaras. Encaminhar para psicoterapia e avaliação psiquiátrica. Orientar que a medição da PA durante crise não representa o valor basal. Retorno apenas se sintomas.'),
  (239, 74, 1, '2025-06-17 16:30', 'teleconsulta', 'Passei na prova e estou bem melhor', 112, 70, 70, null, 'Teleconsulta. Em psicoterapia há 2 meses e em uso de sertralina 50 mg pela psiquiatria, com redução importante das crises: apenas uma crise leve em maio, sem ir ao PS. Parou os energéticos e toma 2 cafés por dia. Aferição domiciliar de PA entre 108-118 / 68-74 mmHg (informada). Sem palpitações persistentes.', 'Sem tratamento cardiológico. Alta do seguimento cardiológico. Manter sertralina e psicoterapia. Retornar ao PS somente para dor torácica, síncope ou dispneia. Recomenda-se MRPA anual por histórico familiar de pais hipertensos.');
