insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (74, '2025-06-17', 'melhorou', 'Pseudocrise hipertensiva por crise de pânico (178x104 no PS, normalizada em 45 minutos sem anti-hipertensivo). MAPA normal e sem cardiopatia. Melhorou com psicoterapia, sertralina e menos cafeína; recebeu alta do seguimento cardiológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (75, 'Jéssica Rayane Antunes Mattos', 'F', '1991-02-07', 'Nova Iguaçu', 'RJ', 'Atendente de telemarketing', 'Segunda gestação, sem HAS prévia. Primeira gestação sem intercorrências. IMC pré-gestacional 27. Não fuma. Mãe hipertensa tardia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (240, 75, 7, '2023-06-14 09:00', 'consulta', 'Pressão alta no pré-natal da UBS', 148, 94, 84, 76.0, 'Gestante de 32 anos, 34 semanas, assintomática. PA 148x94 e 146x92 com intervalo de 15 min, normal no pré-natal anterior (118x72 às 28 semanas). Sem cefaleia, sem escotomas, sem dor epigástrica, edema de MMII leve. Fita urinária negativa para proteína. Relação proteína/creatinina urinária 0,10. Plaquetas 248.000, TGO 22, TGP 19, creatinina 0,6. Ultrassom com crescimento fetal em P50, líquido normal e Doppler uterino normal. Hipertensão gestacional sem proteinúria nem sinais de gravidade.', 'Iniciar nifedipino retard 20 mg 12/12h. MAPA domiciliar duas vezes ao dia, exames de rotina semanais e vitalidade fetal com cardiotocografia 2x/semana. Orientados sinais de alarme: cefaleia, visão turva, dor epigástrica, sangramento, redução do movimento fetal. Retorno em 1 semana.'),
  (241, 75, 7, '2023-06-21 09:10', 'retorno', 'Trouxe os exames e a planilha da pressão', 132, 84, 80, 76.4, 'PA domiciliar entre 124-138 / 78-88 mmHg com nifedipino. Exame: PA 132x84, sem edema pulmonar, reflexos normais, BCF 140 bpm, altura uterina 34 cm. Sem proteinúria nova (fita negativa, relação P/C 0,08). Plaquetas 240.000. Cardiotocografia reativa. Doppler de artérias umbilicais normal. Sem sinais de pré-eclâmpsia.', 'Manter nifedipino 20 mg 12/12h. Programar parto entre 37 e 39 semanas para hipertensão gestacional controlada; indução com Bishop favorável. Manter vigilância. Retorno semanal, internação se PA ≥ 160/110 ou sintomas.'),
  (242, 75, 7, '2023-07-26 07:30', 'internacao', 'Internada para indução de parto, 38 semanas', 138, 86, 82, 78.2, 'Internada às 38+3 semanas para indução eletiva por hipertensão gestacional. PA 138x86, sem sintomas, exames laboratoriais normais. Colo 3 cm, 70% apagado, Bishop 8. Indução com ocitocina. Parto vaginal às 19h40, RN do sexo feminino, 3.180 g, Apgar 9/10. PA máxima 150x96 no trabalho de parto, sem necessidade de hipotensor extra. Sem hemorragia.', 'Alta no segundo dia de puerpério. Manter nifedipino por 7 dias e aferir a PA em casa 2x/dia. Orientada sobre risco de pico pressórico no 3º-6º dia de puerpério. Retorno em 10 dias.'),
  (243, 75, 1, '2023-09-18 10:00', 'retorno', 'Consulta de 8 semanas depois do parto', 116, 74, 72, 72.0, 'Puerpério de 8 semanas, amamentando. Suspendeu o nifedipino na primeira semana, PA domiciliar 108-120 / 68-76. PA 116x74 hoje. Sem proteinúria. Perdeu 6 kg desde o parto. Orientada que hipertensão gestacional aumenta o risco de HAS crônica e que é necessário controle anual da PA, glicemia e lipídeos.', 'Sem medicações. Aferição de PA anual (MRPA) e MEV. Nas próximas gestações iniciar AAS 100 mg a partir de 12 semanas. Retorno em 12 meses.');
