insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (75, '2023-09-18', 'controlado', 'Hipertensão gestacional sem proteinúria, controlada com nifedipino e parto vaginal induzido às 38 semanas, com RN saudável. PA normalizou no puerpério e a medicação foi suspensa. Segue com vigilância anual por risco de HAS futura.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (76, 'Rosângela Pires Trindade Campos', 'F', '1957-10-19', 'Vila Velha', 'ES', 'Comerciante (dona de mercearia)', 'HAS há 20 anos, DM2 há 10 anos (metformina e glibenclamida), dislipidemia. Tabagismo antigo (parou há 10 anos). Mora com o marido, que está acamado, e é a cuidadora principal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (244, 76, 6, '2022-11-18 06:30', 'pronto_socorro', 'Dor no peito em repouso, acordou de madrugada', 150, 86, 92, 77.0, 'Mulher de 65 anos com dor opressiva retroesternal em repouso, 30 minutos, 3 episódios nas últimas 24 h, após crescente desconforto aos esforços na última semana. Sudorese. ECG: infradesnivelamento de ST de 1,5 mm em V4-V6, sem supra. Troponina US 0,08 ng/mL na admissão e 0,06 em 3 h (limítrofe, sem delta), GRACE 142. Angina instável, risco intermediário-alto.', 'AAS 300 mg e clopidogrel 300 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol tartarato 25 mg, nitrato SL. Internação em unidade coronária. CATE em 24-48 h.'),
  (245, 76, 10, '2022-11-19 14:00', 'internacao', 'Cateterismo coronário, unidade coronária', 134, 78, 68, 77.0, 'CATE por radial: lesão de 90% em CD média, com trombo; DA com lesão de 50% proximal (FFR 0,86), Cx sem lesões. FEVE 60%. ATC da CD com implante de stent farmacológico, TIMI 3 ao final, sem complicações. Dor resolvida, sem recorrência. Alta no 2º dia. Estabelecido plano de DAPT por 12 meses.', 'AAS 100 mg + clopidogrel 75 mg por 12 meses, ambos sem interrupção sem avaliação do cardiologista. Atorvastatina 80 mg, metoprolol succinato 50 mg, ramipril 5 mg, metformina. Reabilitação cardíaca. Retorno em 30 dias.'),
  (246, 76, 6, '2023-01-11 09:00', 'pronto_socorro', 'Dor forte no peito de novo, pior que a primeira', 104, 66, 108, 76.5, 'Dor retroesternal intensa e sudorese iniciada há 50 minutos. Confessa que parou o clopidogrel há 10 dias por não ter dinheiro para comprar e porque o marido precisou de fraldas. ECG: supra de ST de 2,5 mm em DII, DIII e aVF, com infra espelhado em V1-V3. Troponina 1,4 ng/mL. Killip I, ausculta limpa. Suspeita de trombose de stent em CD por suspensão do clopidogrel (IAMCSST de parede inferior).', 'AAS 300 mg e ticagrelor 180 mg, heparina e morfina. Transferência imediata à hemodinâmica para angioplastia primária. Evitar nitrato por acometimento de VD possível. Acionada assistente social. Orientada ao uso contínuo do antiagregante.');
