insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (76, '2023-01-11', 'piorou', 'Angina instável tratada com ATC da CD. Após dez dias sem clopidogrel por dificuldade financeira, evoluiu com IAMCSST inferior por provável trombose do stent, e foi encaminhada à angioplastia primária. Necessita apoio social para garantir acesso ao antiagregante.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (77, 'Ademar Soares Figueiredo', 'M', '1953-07-01', 'São Paulo', 'SP', 'Metalúrgico aposentado', 'DM2 há 18 anos em uso de insulina NPH e metformina, HAS e dislipidemia. Ex-tabagista (40 maços-ano). Angina aos esforços há 1 ano. Irmão operou o coração aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (247, 77, 1, '2022-02-15 14:00', 'consulta', 'Dor no peito andando e falta de ar na subida', 146, 84, 72, 85.0, 'Homem de 68 anos, diabético de longa data, angina CCS III. Em uso de AAS, atorvastatina 40 mg, losartana 100 mg e carvedilol 12,5 mg 12/12h. Sem sinais de IC. ECG com onda Q em DIII, sem outros achados. Cintilografia: isquemia extensa, dilatação transitória do ventrículo, FEVE 48%. Cateterismo solicitado em hospital de referência: lesão de tronco de coronária esquerda de 60% com DA proximal 90%, Cx 80% e CD ocluída crônica.', 'Doença multiarterial com tronco, diabetes e SYNTAX 38: indicação de revascularização cirúrgica (Heart Team). Encaminhar ao cirurgião cardiovascular. Manter medicações. Retorno com pré-operatório.'),
  (248, 77, 12, '2022-03-22 07:00', 'internacao', 'Cirurgia de revascularização do miocárdio', 128, 72, 66, 84.6, 'Submetido a revascularização do miocárdio com circulação extracorpórea: mamária esquerda para DA, safena para marginal e para descendente posterior (3 pontes). Sem intercorrências intraoperatórias, extubado em 6 h. UTI por 48 h, sem arritmias, FA ausente. Dreno retirado no 2º dia. Controle glicêmico com insulina em bomba. Pico de troponina esperado. Sem sinais de mediastinite. Alta no 7º dia com cicatrização esternal boa.', 'AAS 100 mg contínuo, atorvastatina 80 mg, carvedilol, losartana e insulina. Fisioterapia respiratória e motora. Cuidados esternais por 6 semanas (sem carregar peso). Reabilitação cardíaca. Retorno em 30 dias.'),
  (249, 77, 1, '2022-05-03 14:30', 'retorno', 'Esterno ainda estala, mas não tenho mais dor no peito', 124, 74, 62, 83.0, '6 semanas de pós-operatório. Sem angina, sem dispneia. Esterno estável, ferida cicatrizada, safena de MIE com leve edema residual. Está na reabilitação cardíaca e caminha 40 minutos diários. Glicemia melhor, HbA1c 7,3%. LDL 58. PA 124x74. Sem sinais de infecção de ferida.', 'Manter AAS, estatina, BB e BRA. Acrescentar empagliflozina 10 mg pelo benefício cardiovascular e DM2. Teste ergométrico em 6 meses. Retorno em 3 meses.'),
  (250, 77, 1, '2022-11-08 14:00', 'retorno', 'Estou ótimo, andando bastante', 120, 72, 60, 81.5, '8 meses de cirurgia, sem dor no peito e sem dispneia. Teste ergométrico: 8,5 METs, sem sinais de isquemia, boa resposta pressórica. Caminha 5 km 4x por semana. HbA1c 6,9%, LDL 52, creatinina 1,1. Tolera empagliflozina sem infecção genital. Muito satisfeito: "voltei a viver".', 'Manter tratamento e reabilitação. Dispensado do programa estruturado de reabilitação. Retorno semestral com exames. Vacinas em dia.');
