insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (78, '2022-04-20', 'obito', 'Óbito em UTI por choque cardiogênico refratário em ICFEr isquêmica avançada (FEVE 22%), precipitado por gastroenterite com desidratação, lesão renal aguda e FA de alta resposta. A família decidiu pelo conforto, sem suporte invasivo, conforme o desejo prévio do paciente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (79, 'Expedito Nogueira Rego', 'M', '1961-04-28', 'Brumado', 'BA', 'Lavrador', 'Doença de Chagas diagnosticada em doação de sangue há 20 anos, sem acompanhamento. Nasceu em casa de taipa. Episódios de tontura e desmaios há 3 meses. Tabagista de 15 maços-ano. Sem HAS ou DM.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (255, 79, 6, '2023-05-22 11:20', 'pronto_socorro', 'Desmaiei na roça de novo e o coração tá muito devagar', 152, 70, 32, 64.5, 'Lavrador de 62 anos com síncope em plena roça, recuperação rápida. FC 32 bpm, pulso regular amplo, jugulares com ondas em canhão. PA 152x70. ECG: bloqueio atrioventricular total com escape ventricular largo (QRS 140 ms), BRD com BDAS de base. Sem sinais de IC grave. Sorologia positiva para Chagas. Troponina negativa, K 4,2. BAVT chagásico sintomático.', 'Monitorização. Sem resposta à atropina. Instalar marca-passo transcutâneo se bradicardia sintomática, e solicitar transferência para implante de marca-passo definitivo. Sem benznidazol. Internação.'),
  (256, 79, 4, '2023-05-24 08:00', 'internacao', 'Implante de marca-passo definitivo', 138, 74, 70, 64.5, 'Marca-passo provisório por 36 h. Implantado marca-passo dupla câmara via subclávia esquerda, com programação DDD 60-120 bpm. ECO: FEVE 44%, aneurisma apical pequeno, hipocinesia inferolateral, trombo ausente. Holter prévio não disponível. RX pós-implante sem pneumotórax, eletrodo ventricular em septo. Evoluiu bem, sem hematoma de loja, FC estimulada 70.', 'Alta em 3 dias. Iniciar enalapril 5 mg 12/12h e espironolactona 25 mg por FEVE 44% e IC incipiente. Betabloqueador agora seguro com MP: carvedilol 3,125 mg 12/12h. Retorno em 15 dias para retirada de pontos e checagem do MP.'),
  (257, 79, 4, '2023-06-12 10:00', 'retorno', 'Sem desmaio mais, o aparelho tá funcionando', 124, 74, 68, 65.0, 'Retorna após 3 semanas do implante, sem síncope ou pré-síncope. Ferida bem cicatrizada. Interrogação do MP: parâmetros normais, 100% de estimulação ventricular, sem arritmias atriais. Tolera enalapril e carvedilol, sem hipotensão. K 4,7, creatinina 1,0. Planeja voltar à roça. Mora longe e tem dificuldade de transporte, pergunta se pode fazer o acompanhamento no posto.', 'Manter medicações. Holter para pesquisa de TV (risco de CDI se TVNS). Mínimo esforço pesado nas próximas 4 semanas. Seguimento do MP a cada 6 meses e do coração (ECO) em 6 meses. Contra-referência com a UBS de Brumado.');
