insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (80, '2024-10-22', 'melhorou', 'Miopericardite por influenza B em atleta jovem, com FEVE 50% na fase aguda e recuperação completa (62%) em 6 meses. Medicamentos suspensos e retorno liberado aos esportes após ergométrico normal; segue com ECO e Holter anuais por pequeno realce tardio residual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (81, 'Cíntia Maria Bittencourt Salgado', 'F', '1984-12-04', 'Rio das Ostras', 'RJ', 'Gerente de agência bancária', 'Sem comorbidades. Sedentária, estresse no trabalho, sono irregular. IMC 28. Pai com HAS diagnosticada aos 50 anos. Usa anticoncepcional oral combinado há 8 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (262, 81, 5, '2024-01-15 17:30', 'consulta', 'Check-up da empresa disse que minha pressão está no limite', 134, 86, 78, 75.0, 'Mulher de 39 anos, assintomática. PA 134x86 e 132x84 em duas medições, em outras consultas 128-136/82-88. Circunferência abdominal 92 cm, IMC 28,3. Ingestão de sódio elevada (fast-food, embutidos), sem atividade física, 5 horas de sono. Sem lesão de órgão-alvo aparente: creatinina 0,7, EAS normal, glicemia 90, LDL 118. ECG normal. Pré-hipertensão (130-139/80-89) em paciente de risco moderado, em uso de ACO combinado.', 'Não iniciar fármaco. MEV intensiva: reduzir sal, DASH, caminhar 150 min/semana, meta de perda de 4 kg, sono de 7 horas. Orientada a avaliar com ginecologista a troca do ACO por método sem estrógeno. MRPA em 3 meses. Retorno em 3 meses.'),
  (263, 81, 5, '2024-04-22 17:40', 'retorno', 'Estou me cuidando, trouxe a planilha da pressão', 124, 80, 72, 71.2, 'Perdeu 3,8 kg em 3 meses, caminha 40 minutos 4 vezes na semana e reduziu o consumo de embutidos. Trocou o ACO por DIU hormonal de levonorgestrel com a ginecologista. MRPA de 5 dias com média de 122x78 (28 medidas). PA de consultório 124x80, sem tratamento medicamentoso. Dorme melhor. Sem cefaleia.', 'Manter MEV como único tratamento. Meta de perda de mais 2 kg. MRPA semestral e consulta anual. Sinais de alerta: PA domiciliar persistentemente ≥ 130/80.'),
  (264, 81, 5, '2025-01-20 17:30', 'retorno', 'Retorno anual', 118, 76, 70, 69.5, 'Mantém atividade física e dieta. IMC 26,5. PA 118x76, MRPA com média de 118x74. Glicemia 86, LDL 104. Sem queixas. Refere sentir-se mais disposta e que mudou a alimentação da família. Sem uso de medicamentos. Exame físico sem alterações, ausculta cardíaca e pulmonar normais, sem edema. Continua com a rotina de caminhadas ao amanhecer com uma colega do banco.', 'Manter acompanhamento anual com MRPA. Reforçada manutenção de peso e do exercício. Alta do ambulatório de cardiologia para a atenção primária, que fará o seguimento.');
