insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (82, '2023-10-09', 'controlado', 'HAS controlada confirmada por MRPA validado (média 122-124 / 76-78 mmHg), com leve efeito de consultório que não justificou intensificar o tratamento. Segue com losartana, hidroclorotiazida e estatina e vigilância anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (83, 'Leontina Garcia de Albuquerque', 'F', '1958-05-30', 'Vassouras', 'RJ', 'Professora aposentada', 'HAS há 18 anos. Usa losartana 100 mg, anlodipino 10 mg, clortalidona 25 mg e espironolactona 25 mg prescritos por outro serviço por "pressão resistente". Tontura ocasional. Sem diabetes. Muito ansiosa nas consultas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (268, 83, 1, '2022-08-24 09:00', 'consulta', 'Médico disse que minha pressão é resistente e aumentou os remédios', 176, 98, 86, 69.5, 'Paciente de 64 anos com PA de consultório persistentemente em 170-180x95-100 mesmo com 4 fármacos, inclusive espironolactona. Refere tonturas, queda da pressão em casa (por volta de 110x66) e cansaço. Aferição de consultório: ansiosa, FC 86, sem sinais de LOA, fundo de olho normal. Creatinina 1,2, K 4,6, Na 136. Suspeita de pseudorresistência por efeito do avental branco.', 'Solicitar MAPA 24h antes de qualquer ajuste, mantendo os remédios. Registrar MRPA de 7 dias. Orientada a não tomar nenhuma dose extra se o consultório for alto. Retorno com os resultados em 15 dias.'),
  (269, 83, 1, '2022-09-12 09:20', 'retorno', 'Trouxe a MAPA', 170, 96, 82, 69.0, 'MAPA 24h: média 24h 112x66, vigília 116x68, sono 100x58, com vários períodos de PA sistólica < 100 mmHg (hipotensão sintomática à tarde). Consultório 170x96: diferença de mais de 50 mmHg em relação à vigília, caracterizando importante efeito do avental branco. MRPA em casa: média 114x68. HAS resistente aparente, na verdade pseudorresistência com sobretratamento. Cansaço e tonturas compatíveis com hipotensão por excesso de fármacos.', 'Suspender espironolactona e reduzir anlodipino para 5 mg. Manter losartana 100 mg e clortalidona 25 mg. Valores de MRPA como guia, nunca a pressão de consultório. Controle de eletrólitos em 2 semanas. Retorno em 4 semanas.'),
  (270, 83, 1, '2022-12-05 09:00', 'retorno', 'A tontura passou, será que posso tirar mais remédio?', 158, 90, 78, 70.2, 'Sem tonturas desde a redução. MRPA com média 122x72. Consultório 158x90 (continua ansiosa, efeito do avental branco persiste). Creatinina 1,1, K 4,3. Aferição repetida em 3 medidas no consultório, com uma enfermeira em sala calma: 142x84. MAPA de controle realizada com média de 120x70, permitindo simplificar o esquema.', 'Suspender anlodipino; manter losartana 100 mg e clortalidona 25 mg. MAPA em 3 meses para confirmar. Orientações para registrar MRPA e levar as planilhas. Retorno em 90 dias.');
