insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (83, '2022-12-05', 'controlado', 'Falsa resistência por efeito do avental branco: a MAPA mostrava média 112x66 em quatro fármacos. Após suspender espironolactona e anlodipino, ficou com apenas losartana e clortalidona, MAPA 120x70, sem tonturas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (84, 'Wellington Santos de Oliveira Filho', 'M', '1964-03-11', 'São João de Meriti', 'RJ', 'Vigilante noturno', 'HAS há 15 anos, em uso errático de enalapril, às vezes anlodipino. Sem acompanhamento. Fumante de 15 cigarros/dia, bebe cerveja diariamente. Trabalha em plantão noturno de 12 horas e dorme mal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (271, 84, 2, '2021-05-18 14:30', 'consulta', 'Cansaço para andar e coração batendo forte', 182, 108, 80, 88.0, 'Paciente de 57 anos com HAS mal tratada, dispneia aos grandes esforços e palpitações. Ao exame: ictus desviado para esquerda e sustentado, B4 presente, sem edema. ECG: SVE por Sokolow-Lyon (SV1+RV5 = 48 mm) e strain. ECO: HVE concêntrica importante (septo 16 mm, parede posterior 15 mm), massa indexada 168 g/m², FEVE 60%, disfunção diastólica grau II, AE 46 mm. Creatinina 1,3. Cardiopatia hipertensiva com HVE importante.', 'Iniciar losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg (comprimidos em horários únicos). Orientações enfáticas sobre adesão, cessar tabagismo e álcool. Adaptar horário do plantão. MAPA em 2 meses. Retorno em 30 dias.'),
  (272, 84, 2, '2021-06-22 14:40', 'retorno', 'Melhorou o cansaço, mas parei os remédios 5 dias', 154, 94, 74, 86.5, 'Melhora parcial. Admite que ficou 5 dias sem os remédios por "enjoar" de tomar de manhã quando chega do plantão e vai dormir. PA 154x94, ainda acima da meta. Creatinina 1,3, K 3,8. Ainda fuma 12 por dia. Edema ausente. Fundo de olho com retinopatia hipertensiva grau II.', 'Passar toda a medicação para a noite antes do plantão (compatível com seu horário). Manter o esquema de três drogas. Plano de cessação de tabagismo. Retorno em 6 semanas.'),
  (273, 84, 6, '2022-11-08 02:40', 'pronto_socorro', 'Falta de ar de madrugada e coração disparado', 190, 112, 142, 92.0, 'Não retornou desde 2021; não toma remédios há meses. Chegou do plantão com dispneia intensa, ortopneia, palpitações, FR 30, sat 88%. Edema 3+/4+ em MMII, estertores até ápices, turgência jugular. ECG: fibrilação atrial com resposta ventricular rápida (142 bpm) e SVE. NT-proBNP 8.900, troponina negativa, creatinina 1,7. Diagnóstico: IC aguda com edema agudo de pulmão hipertensivo e FA nova.', 'O2 e VNI, furosemida 80 mg EV, nitroglicerina EV para PA, cardioversão não indicada na fase aguda (tempo de FA indeterminado). Iniciar anticoagulação plena com enoxaparina e controle de frequência com metoprolol quando congesto controlado. Internação em UTI.'),
  (274, 84, 11, '2022-12-12 10:00', 'retorno', 'Alta da UTI, vim para consulta', 138, 86, 96, 84.4, 'Hospitalizado por 8 dias, perdeu 7,6 kg de líquido. ECO: FEVE 48%, HVE importante, AE 52 mm; FA persistente, controle de FC insuficiente (96 em repouso). CHA2DS2-VASc 2 (IC e HAS). Dispneia NYHA II. K 4,2, creatinina 1,4. Tem dificuldade de aceitar que a doença é crônica e relata ainda fumar 8 cigarros/dia, bebe aos fins de semana.', 'Rivaroxabana 20 mg com jantar, metoprolol succinato 100 mg, sacubitril/valsartana 24/26 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg. Suspender losartana e clortalidona. Furosemida 20 mg. Encaminhar para programa de cessação de tabagismo. Retorno em 30 dias.');
