insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (84, '2022-12-12', 'piorou', 'Cardiopatia hipertensiva com HVE importante evoluiu para insuficiência cardíaca descompensada e fibrilação atrial nova, após 17 meses sem tratamento por problemas de adesão ligados ao trabalho noturno. FEVE caiu para 48%. Reiniciado tratamento completo, ainda fumante.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (85, 'Maria das Graças Bezerra de Menezes', 'F', '1955-02-26', 'Fortaleza', 'CE', 'Bancária aposentada', 'HAS e dislipidemia. ATC com stent farmacológico em DA em 2023 após angina instável. Obesa grau I. Pouca atividade física até o evento. Vive com o marido, que a incentiva.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (275, 85, 1, '2023-09-11 15:00', 'consulta', 'Quero fazer exercício com segurança depois do stent', 134, 80, 64, 78.5, 'Mulher de 68 anos, 4 semanas após ATC com stent farmacológico em DA proximal por angina instável. Sem dor torácica desde o procedimento. Em uso de AAS, ticagrelor, atorvastatina 80 mg, metoprolol succinato 50 mg e losartana 50 mg 12/12h. Exame: sem sinais de IC, PA 134x80. FEVE 58% no ECO. LDL 68. Quer iniciar atividade física, mas tem medo.', 'Encaminhar para reabilitação cardíaca fase II (36 sessões) com monitorização. Realizar ergoespirometria antes de começar. Orientações para sinais de alarme durante o exercício. Manter DAPT por 12 meses. Retorno em 3 meses.'),
  (276, 85, 1, '2023-12-18 15:00', 'retorno', 'Acabei o programa de reabilitação', 122, 74, 60, 74.0, 'Concluiu 36 sessões de reabilitação. Ergoespirometria: VO2 pico de 20,8 mL/kg/min (antes 14,2), limiar ventilatório em 14 mL/kg/min. Sem angina, sem arritmias no esforço. Perdeu 4,5 kg. Dispneia leve ao ticagrelor, tolerável. Humor muito melhor. PA 122x74. Exame cardiovascular normal, pulmões limpos, sem edema. Conta que faz as sessões acompanhada de duas colegas do grupo e que já voltou a dançar forró aos sábados.', 'Manter exercício regular fora do programa, 150 min por semana, em academia perto de casa. Manter medicações. Dispneia por ticagrelor: observar; se piora, trocar por clopidogrel. Retorno em 6 meses.'),
  (277, 85, 1, '2024-08-26 14:30', 'retorno', 'Completei um ano do stent', 118, 70, 58, 72.5, 'Um ano de ATC. Sem angina, mantém exercícios 5x/semana. Dispneia leve do ticagrelor persiste e melhora com repouso, sem repercussão funcional. LDL 54, creatinina 0,9, HbA1c 5,6%. PA 118x70. Sem sangramentos. Teste ergométrico: 9 METs, sem isquemia. Exame cardiovascular normal, pulmões limpos, sem edema, pulsos periféricos presentes. Orientada que o ticagrelor pode ser retirado.', 'Concluído período de DAPT: suspender ticagrelor e manter AAS 100 mg isolado. Manter estatina, betabloqueador e BRA. Retorno em 6 meses.');
