insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (85, '2024-08-26', 'controlado', 'Doença coronariana estável pós-ATC, com ótima resposta à reabilitação cardíaca (VO2 pico de 14,2 para 20,8). Ao completar um ano, o ticagrelor foi suspenso, mantendo AAS, estatina em dose alta e controle de PA. Sem angina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (86, 'Nelson Takeshi Yamada Pacheco', 'M', '1968-08-08', 'Resende', 'RJ', 'Soldador', 'Tabagista de 30 maços-ano, dislipidemia sem tratamento, HAS não tratada. Pai e tio com infarto antes dos 55 anos. Etilista de fim de semana. Sem plano de saúde.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (278, 86, 6, '2023-02-07 05:10', 'pronto_socorro', 'Aperto no peito que vem e passa há 2 dias, agora não passa', 164, 98, 92, 89.0, 'Homem de 54 anos com dor retroesternal em aperto de repouso, 3 episódios nos últimos 2 dias e um de 40 min hoje, aliviado com nitrato SL. Ao exame: ansioso, sem sinais de IC, PA 164x98. ECG: infra de ST 1 mm em V4-V6 e T negativa. Troponina US 0,02 ng/mL e 0,03 em 3 h (sem elevação). Angina instável, risco alto (TIMI 5).', 'AAS 300 mg, clopidogrel 300 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol 25 mg 12/12h, nitroglicerina EV por 12 horas. Internação e CATE em 24 horas. Orientado sobre o risco de interromper o tabagismo e seguimento.'),
  (279, 86, 10, '2023-02-08 11:00', 'internacao', 'Cateterismo, enfermaria cardiológica', 140, 84, 68, 89.0, 'CATE por radial direita: lesão de 85% em DA média, 70% em D1, circunflexa e CD com irregularidades parietais. FEVE 55%. Realizada ATC com stent farmacológico em DA média com ótimo resultado; D1 tratada clinicamente. Sem dor após o procedimento, sem complicações no acesso. Explicado o plano de antiagregação dupla por 12 meses e a importância de parar de fumar.', 'AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses, atorvastatina 80 mg, metoprolol succinato 50 mg, ramipril 5 mg. Retorno ambulatorial em 30 dias. Entregue encaminhamento para reabilitação cardíaca e para o programa de tabagismo.'),
  (280, 86, 1, '2023-03-13 16:00', 'retorno', 'Voltei para a primeira consulta depois do stent', 132, 80, 62, 88.0, 'Assintomático, voltou ao trabalho há 1 semana (soldador, esforço moderado). Parou de fumar por 3 semanas e recaiu, fuma 5 cigarros por dia. Reclama do custo do ticagrelor, pois não tem plano e compra na farmácia (R$ 280/mês); já ficou 2 dias sem. Exame normal. Não fez nenhuma sessão de reabilitação, por falta de tempo.', 'Substituir ticagrelor por clopidogrel 75 mg (disponível na rede pública) para evitar suspensão por custo. Reforço de que o stent exige antiagregação diária por 12 meses. Reencaminhado à reabilitação em horário noturno. Retorno em 60 dias.');
