insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (86, '2023-12-15', 'abandonou', 'Angina instável tratada com stent em DA. Na última consulta (março de 2023) trocou ticagrelor por clopidogrel por custo. Não compareceu ao retorno marcado nem às ligações da equipe; segue sem seguimento, com tabagismo ativo e risco de interrupção da antiagregação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (87, 'Silvio Roberto Calazans Paiva', 'M', '1970-01-15', 'Cachoeiras de Macacu', 'RJ', 'Pedreiro', 'Cardiomiopatia dilatada idiopática diagnosticada há 1 ano, sem doença coronariana no CATE. Álcool em quantidade moderada, parou há 8 meses. Sem HAS. Tabagista leve. Usa enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h há 1 ano sem ajuste.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (281, 87, 11, '2023-06-05 08:30', 'consulta', 'Ainda canso rápido para trabalhar', 112, 70, 78, 81.5, 'Pedreiro de 53 anos com cardiomiopatia dilatada. Dispneia aos moderados esforços (NYHA II-III), sem ortopneia, sem edema. PA 112x70, FC 78. Ausculta com B3 discreta, sem sopros. Em tratamento incompleto: enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida SN. NT-proBNP 1.850. ECO: FEVE 28%, DDVE 68 mm, IM leve funcional. Creatinina 1,0, K 4,5. Tratamento ainda sem espironolactona e iSGLT2.', 'Otimizar os quatro pilares: trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (pausa de 36 h), iniciar espironolactona 25 mg e dapagliflozina 10 mg, aumentar carvedilol para 12,5 mg 12/12h. Labs em 1 semana. Retorno em 30 dias.'),
  (282, 87, 11, '2023-07-06 08:30', 'retorno', 'Tá mais fácil de respirar', 104, 64, 66, 80.0, 'Melhora subjetiva: sobe dois lances de escada sem parar. PA 104x64, sem tontura. FC 66. K 4,8, creatinina 1,1 após uma semana e hoje 1,1. Sem edema. Tolera as quatro classes. Come sal normal, com pouco controle. Fumou 5 cigarros por dia no período. Exame cardiovascular com B3 discreta, pulmões limpos, sem edema, jugulares normais. Pediu atestado médico para a empresa liberar a função de menor esforço.', 'Subir sacubitril/valsartana para 49/51 mg 12/12h e carvedilol para 25 mg 12/12h. Manter espironolactona e dapagliflozina. Labs em 15 dias. Orientações para cessar tabagismo. Retorno em 45 dias.'),
  (283, 87, 11, '2023-09-18 08:30', 'retorno', 'Voltei a trabalhar na obra', 100, 62, 60, 80.8, 'NYHA I-II, voltou a trabalhar com restrições. PA 100x62, assintomático. FC 60 com carvedilol 25 mg 12/12h. K 4,9, creatinina 1,2. NT-proBNP caiu para 620 pg/mL. Parou de fumar há 4 semanas com adesivo. Sem hipoglicemia, sem infecção genital. Exame sem edema, pulmões limpos, B3 ausente.', 'Manter sacubitril/valsartana em 49/51 mg 12/12h, sem escalonar por PA de 100x62. Manter as demais doses. Repetir ECO em 3 meses. Orientar quanto a líquidos e sal. Retorno em 3 meses.'),
  (284, 87, 11, '2024-01-22 08:30', 'retorno', 'Vim ver o ecocardiograma novo', 106, 66, 62, 82.0, 'Sem sintomas, NYHA I. ECO: FEVE 42% (era 28%), DDVE 60 mm, sem IM significativa — remodelamento reverso. NT-proBNP 340. PA 106x66. Mantém abstinência de tabaco e álcool. Pergunta se pode parar os remédios. Orientado: com a melhora da FEVE, a suspensão pode levar à recaída, portanto manter.', 'Manter os quatro pilares e metas atuais. Não suspender. Controle semestral de eletrólitos e ECO anual. Avaliação de CDI dispensada pela melhora de FEVE. Retorno em 6 meses.');
