insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (87, '2024-01-22', 'melhorou', 'Cardiomiopatia dilatada com FEVE de 28% para 42% em 7 meses após otimização dos quatro pilares da IC. NT-proBNP de 1.850 para 340, NYHA I, abstinência de tabaco e álcool. Mantém terapia completa, sem indicação de CDI.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (88, 'Iracema Sampaio Cavalcanti', 'F', '1966-06-24', 'Manaus', 'AM', 'Servidora pública (técnica administrativa)', 'HAS controlada com losartana 50 mg. Fibrilação atrial paroxística evoluindo para persistente. Obesidade grau I. Consome 4-5 cafés por dia. Sem diabetes, sem valvopatia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (285, 88, 4, '2023-04-10 10:30', 'consulta', 'Coração desritmado e muito cansaço há 3 semanas', 138, 84, 118, 84.0, 'Mulher de 56 anos com palpitações e fadiga há 3 semanas, piora aos esforços. ECG: fibrilação atrial com resposta ventricular de 118 bpm. ECO: FEVE 55%, AE 44 mm (volume indexado 38 mL/m²), sem valvopatia. TSH 1,8. CHA2DS2-VASc 2 (sexo feminino, HAS). Sintomática, 56 anos, desejo de estratégia de controle de ritmo. Duração menor que 48 horas é incerta.', 'Anticoagular com apixabana 5 mg 12/12h por 3 semanas antes de cardioversão elétrica eletiva. Metoprolol succinato 50 mg para frequência. Reduzir café. Estudo de apneia (STOP-Bang 5) a pedir. Retorno em 3 semanas.'),
  (286, 88, 4, '2023-05-08 09:00', 'internacao', 'Cardioversão elétrica eletiva', 130, 80, 92, 83.4, 'Após 4 semanas de anticoagulação ininterrupta, sem falhas de dose. Em jejum, sob sedação com propofol, realizada cardioversão elétrica sincronizada com 150 J bifásicos, revertendo ao ritmo sinusal no primeiro choque. ECG pós: ritmo sinusal 72 bpm, sem pausas. Estável, alta no mesmo dia. Sem queimaduras de pele.', 'Manter apixabana por pelo menos 4 semanas e depois conforme risco (CHA2DS2-VASc 2). Iniciar amiodarona 200 mg/dia por 3 meses para manter ritmo, TSH e função hepática. Retorno em 30 dias.'),
  (287, 88, 4, '2023-11-20 10:30', 'retorno', 'As palpitações voltaram há 1 mês', 136, 82, 110, 85.5, 'Seis meses em ritmo sinusal, com recorrência de FA há 1 mês, após suspensão da amiodarona e período de estresse. Sintomática, com cansaço e palpitações. ECG: FA com FC 110. Polissonografia: IAH 22 (moderada), iniciou CPAP há 6 semanas. ECO: FEVE 54%, AE 46 mm. Prefere procedimento de ablação a antiarrítmico crônico (efeitos de amiodarona).', 'Indicada ablação por cateter (isolamento das veias pulmonares) por FA sintomática recorrente. Manter apixabana ininterrupta. Programar para fevereiro. Perda de peso e CPAP. Retorno após procedimento.'),
  (288, 88, 4, '2024-08-12 11:00', 'retorno', 'Seis meses depois da ablação', 124, 76, 64, 78.0, 'Ablação por cateter (isolamento das 4 veias pulmonares com crioablação) feita em março de 2024, sem complicações. Desde então sem palpitações. Holter de 7 dias: ritmo sinusal, FC média 66, 2 episódios de taquicardia atrial de 8 batimentos. Perdeu 7,5 kg e usa CPAP todas as noites. PA 124x76.', 'Manter anticoagulante por mais tempo (CHA2DS2-VASc 2, preferência de manter). Suspender metoprolol. Continuar CPAP e controle de peso. Retorno em 6 meses com Holter de 24h.');
