insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (88, '2024-08-12', 'melhorou', 'FA persistente sintomática: cardioversão elétrica inicial e recorrência em 6 meses, seguida de crioablação das veias pulmonares. Sem FA em Holter de 7 dias, com perda de 7,5 kg e CPAP para apneia moderada. Mantém apixabana e acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (89, 'Conceição Aparecida Ventura Xavier', 'F', '1972-11-03', 'Barra do Piraí', 'RJ', 'Costureira', 'Febre reumática na infância, com sopro conhecido desde os 20 anos. Estenose mitral reumática grave com fibrilação atrial persistente diagnosticada em 2021. Uso de varfarina com controle irregular de INR.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (289, 89, 2, '2022-03-14 10:00', 'consulta', 'Falta de ar e cansaço para costurar de pé e subir morro', 118, 72, 104, 58.0, 'Mulher de 49 anos com estenose mitral reumática, dispneia NYHA III, ortopneia leve, hemoptise esporádica. Ao exame: face mitral, ritmo irregular, B1 hiperfonética, estalido de abertura e ruflar diastólico em foco mitral, sopro sistólico sem irradiação. ECO: estenose mitral grave (área 0,9 cm², gradiente médio 14 mmHg), AE 58 mm, trombo ausente, PSAP 56 mmHg. FA persistente. Em uso de varfarina 5 mg, INR hoje 1,6.', 'Indicação de valvoplastia mitral por cateter-balão. Ajustar varfarina com INR-alvo 2-3 (anticoagulação obrigatória, DOAC contraindicado em EM moderada/grave), metoprolol succinato 50 mg para FC, furosemida 20 mg. ETE pré-procedimento. Retorno em 15 dias com INR.'),
  (290, 89, 10, '2022-05-23 08:00', 'internacao', 'Valvoplastia mitral por balão', 120, 70, 88, 58.4, 'ETE sem trombo em AE ou apêndice, escore de Wilkins 7, sem IM importante. Realizada valvoplastia mitral percutânea com balão de Inoue por via transeptal, com área valvar final de 1,8 cm², gradiente médio de 5 mmHg, e IM leve pós-procedimento. Sem derrame pericárdico. Alta em 48 h. Melhora clínica evidente, sem dispneia em repouso.', 'Manter varfarina com INR 2-3 (FA persistente com EM), metoprolol. Orientada a medir INR a cada 15 dias, e a não alterar a dieta com vegetais verdes bruscamente. ECO em 3 meses. Retorno em 30 dias.'),
  (291, 89, 6, '2022-11-02 04:20', 'pronto_socorro', 'Acordou com fala enrolada e fraqueza no lado direito', 164, 94, 112, 57.5, 'Paciente de 49 anos trazida pelo marido por início súbito de afasia e hemiparesia direita (NIHSS 14) às 2h30. Admite que não faz o INR há 2 meses por falta de acesso ao laboratório e ficou sem varfarina por alguns dias na semana passada. FA com FC 112, INR 1,2. TC de crânio sem hemorragia, ASPECTS 8. Acidente vascular cerebral isquêmico cardioembólico por FA com anticoagulação subterapêutica.', 'Dentro da janela de 4,5h, mas INR 1,2 (< 1,7): elegível a alteplase. Trombólise EV iniciada com PA controlada < 185/110 (labetalol). Angiotomografia: oclusão de M1 esquerda, encaminhada para trombectomia mecânica. Internação em UTI neurológica.'),
  (292, 89, 13, '2023-02-20 09:30', 'retorno', 'Sequela no braço e dificuldade para falar', 134, 80, 80, 56.0, 'Três meses após AVC isquêmico de ACM esquerda tratado com trombólise e trombectomia (recanalização TICI 2b). Sequelas: afasia motora leve a moderada e paresia de MSD grau 3, deambula com apoio. Mini-mental 22. Em reabilitação com fisioterapia e fonoaudiologia. INR agora 2,4 com varfarina 6 mg. Marido organizou o transporte para o laboratório e agendamento mensal.', 'Manter varfarina com INR 2-3 e controle mensal, agora com coleta domiciliar via UBS. Estatina de alta intensidade (atorvastatina 40 mg). Seguimento de fonoaudiologia, terapia ocupacional e fisioterapia. Avaliar fechamento de apêndice se novo evento. Retorno em 3 meses.');
