insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (89, '2023-02-20', 'piorou', 'Estenose mitral reumática tratada com valvoplastia por balão (área de 0,9 para 1,8 cm²), mas com AVC cardioembólico grave meses depois por INR subterapêutico (falta de acesso ao exame). Evolui com sequelas de afasia e hemiparesia, agora com INR em faixa.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (90, 'Vinícius Hideo Tavares Miyamoto', 'M', '1996-10-02', 'Campinas', 'SP', 'Programador', 'Palpitações de início súbito desde a adolescência, que duram minutos, 2-3 vezes ao ano. Sem síncope. Pai sem cardiopatia. Pratica corrida recreativa. Consumo moderado de energéticos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (293, 90, 6, '2024-03-12 19:20', 'pronto_socorro', 'Coração disparou de repente e não para', 122, 76, 204, 74.0, 'Jovem de 27 anos com palpitações regulares de início súbito há 40 minutos, FC 204 bpm, com dispneia leve e tontura. PA 122x76, perfusão preservada, sem dor torácica, pulmões limpos. ECG: taquicardia de QRS estreito regular a 204 bpm, sem ondas P visíveis. Estável hemodinamicamente. HD: taquicardia supraventricular paroxística.', 'Manobra de Valsalva modificada sem reversão; adenosina 6 mg EV rápida sem reversão, 12 mg EV com reversão imediata para ritmo sinusal. ECG pós: ritmo sinusal 78 bpm com onda delta e PR curto (pré-excitação). Observação e encaminhamento ao arritmologista.'),
  (294, 90, 4, '2024-03-26 10:00', 'consulta', 'Vim saber o que é esse negócio de pré-excitação', 118, 70, 66, 73.5, 'Paciente assintomático, ECG de repouso com PR curto (100 ms) e onda delta. Padrão de Wolff-Parkinson-White. ECO normal, FEVE 64%, sem cardiopatia estrutural. Holter 24h: pré-excitação intermitente, sem arritmias. Teste ergométrico: perda abrupta da pré-excitação a 150 bpm, indicando via acessória de período refratário intermediário. Risco moderado, e há indicação de ablação pela crise documentada e pela atividade esportiva.', 'Indicada ablação por cateter da via acessória, curativa em mais de 95% dos casos. Esclarecidos riscos (BAV < 1%, sangramento). Evitar energéticos e esportes extremos até a ablação. Agendar estudo eletrofisiológico. Retorno após o procedimento.'),
  (295, 90, 4, '2024-05-14 08:00', 'internacao', 'Estudo eletrofisiológico e ablação', 116, 68, 70, 74.0, 'Estudo eletrofisiológico: via acessória em parede lateral esquerda, com condução anterógrada e retrógrada, induzida taquicardia ortodrômica a 196 bpm. Realizada ablação por radiofrequência por acesso transeptal, com eliminação da via, sem pré-excitação ao final e sem indução de taquicardia mesmo com isoproterenol. Sem complicações. Alta no dia seguinte, ECG com PR normal sem onda delta.', 'Sem medicação. Repouso relativo 7 dias e retorno gradual aos exercícios. Retorno em 30 dias com ECG. Orientado procurar PS se palpitações sustentadas.');
