insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (92, '2022-10-24', 'obito', 'Óbito em UTI uma semana após tempestade elétrica com taquicardia ventricular recorrente, apesar de CDI e amiodarona, em ICFEr isquêmica avançada (FEVE 26%). Evoluiu com choque cardiogênico e falência renal refratária. Família acompanhou o caso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (93, 'Terezinha Pontes Nascimento Gaudio', 'F', '1949-07-27', 'Colatina', 'ES', 'Costureira aposentada', 'HAS há 30 anos, DM2 há 15 anos, DRC estágio 3a (TFGe 52). Obesa (IMC 33). ICFEp diagnosticada em 2022. FA paroxística. Mora com a filha. Usa losartana, anlodipino, metformina e furosemida 40 mg.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (303, 93, 11, '2023-03-14 09:00', 'consulta', 'Inchaço e falta de ar de novo, não dá para dormir deitada', 156, 82, 92, 86.5, 'Idosa de 73 anos com ICFEp, dispneia NYHA III, ortopneia, ganho de 5 kg em 1 mês. Come bastante sal, tomou diclofenaco por conta própria para dor no joelho por 10 dias. Edema 3+/4+ até coxas, estertores bibasais, jugular ingurgitada, FC 92 irregular. NT-proBNP 2.800, creatinina 1,6 (basal 1,2), K 4,9. ECO: FEVE 58%, E/e'' 18, AE dilatado, PSAP 50. IC descompensada por AINE e excesso de sal.', 'Furosemida 80 mg 12/12h. Suspender diclofenaco, usar paracetamol. Reavaliar em 5 dias com função renal. Restrição de sal e líquidos, peso diário. Retorno em 1 semana.'),
  (304, 93, 11, '2023-03-21 09:00', 'retorno', 'Perdi líquido, mas estou fraca', 118, 66, 84, 80.0, 'Perdeu 6,5 kg em 1 semana, dispneia NYHA II, edema 1+. Muita fraqueza e tontura ao levantar. PA 118x66. Creatinina 2,1 (piora), K 5,3, ureia 98. Síndrome cardiorrenal por congestão e diurese excessiva depois de AINE. Diurese mantida, mas ingestão oral baixa.', 'Reduzir furosemida para 40 mg/dia e suspender losartana temporariamente. Evitar metformina com TFGe < 30. Retomar em casa com hidratação oral cautelosa. Função renal em 3 dias. Retorno em 1 semana, internação se creatinina > 2,5.'),
  (305, 93, 14, '2023-04-03 07:50', 'internacao', 'Internada com piora de função renal e dispneia', 144, 78, 108, 84.0, 'Após dois dias de diarreia e redução de ingesta, voltou a ganhar peso (4 kg) com edema e dispneia, FA com FC 108. Creatinina 3,2, K 5,8, bicarbonato 17. Congestão pulmonar e edema periférico, hiporexia. Síndrome cardiorrenal tipo 1 com IC descompensada, sem indicação de diálise de urgência até o momento. Eletrocardiograma sem alterações de hipercalemia.', 'Furosemida EV em bolus e infusão, restrição de K, resina de troca, sem IECA/BRA/iSGLT2/espironolactona. Controle de diurese e eletrólitos de 12/12 h. Nefrologia avaliará terapia renal substitutiva se oligúria. Controle de FC com digoxina baixa dose.');
