insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (93, '2023-04-03', 'piorou', 'ICFEp hipertensiva descompensada por AINE e sal, evoluindo para síndrome cardiorrenal com creatinina de 1,6 para 3,2 e hipercalemia, exigindo internação. Perda importante de função renal em DRC prévia, com risco de hemodiálise e novas internações.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (94, 'Pedro Paulo Rangel Pontual', 'M', '1955-09-30', 'Macaé', 'RJ', 'Vigia aposentado', 'HAS há 15 anos. Fibrilação atrial permanente descoberta em check-up há 1 ano, em uso de varfarina 5 mg. Mora sozinho. Etilismo moderado. Sem valvopatia ou prótese.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (306, 94, 4, '2022-02-14 09:00', 'consulta', 'Vim pelo INR e pela fraqueza', 148, 88, 112, 79.0, 'Homem de 66 anos com FA permanente, FC 112 em repouso, cansaço. INR 1,4 (alvo 2-3), porque "esquece" a varfarina e come muito couve às vezes. CHA2DS2-VASc 2 (HAS e idade 65-74). ECO: FEVE 52%, AE 47 mm, sem valvopatia. Creatinina 1,1. Mora sozinho, bebe cachaça aos fins de semana. Sem sangramentos.', 'Trocar varfarina por rivaroxabana 20 mg com jantar, dispensando controle de INR e interações alimentares. Iniciar metoprolol succinato 50 mg para controle de FC (meta < 110 e depois < 80 em repouso). Reduzir álcool. Retorno em 30 dias.'),
  (307, 94, 4, '2022-03-21 09:10', 'retorno', 'O remédio novo é mais fácil', 134, 82, 82, 78.5, 'Adaptou-se bem à rivaroxabana, tomando no jantar. FC 82 em repouso com metoprolol. PA 134x82. Sem sangramentos. Hb 14,2, creatinina 1,1. Relata ficar sem o dinheiro para a passagem de ônibus até o ambulatório e que o remédio é fornecido pela farmácia municipal a cada 30 dias. Sem fraqueza hoje.', 'Manter conduta. Receita para 90 dias para reduzir deslocamentos, e autorização para retirada na farmácia da UBS do bairro. Retorno em 4 meses.'),
  (308, 94, 4, '2022-07-18 09:00', 'retorno', 'Receita acabou, mas me sinto bem', 150, 90, 96, 78.0, 'Veio sem agendamento, com receita vencida há 3 semanas. Parou rivaroxabana e metoprolol "porque me sinto bem e tinha medo de sangrar", mas continuou losartana. FC 96, PA 150x90. Sem déficit neurológico, sem sangramentos. Reforçado o risco de AVC cardioembólico sem anticoagulante: reluta, cita um vizinho que sangrou. INR dispensável.', 'Retomar rivaroxabana 20 mg e metoprolol 50 mg. Conversei com ele e com a vizinha que o acompanha sobre o risco de AVC (cerca de 4%/ano com CHA2DS2-VASc 2). Agendado retorno em 30 dias com agente comunitário para busca ativa.');
