insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (94, '2023-01-30', 'abandonou', 'FA permanente com CHA2DS2-VASc 2, que interrompeu o anticoagulante por medo de sangrar e foi reconvencido a retomar. Faltou ao retorno de 30 dias e à busca ativa; vizinhos relataram que continua sem tomar as medicações. Risco alto de AVC embólico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (95, 'Genivaldo Teixeira Brasil', 'M', '1962-12-22', 'Uberlândia', 'MG', 'Mecânico industrial', 'HAS há 10 anos, apneia do sono tratada com CPAP, flutter atrial típico desde 2021. Beber duas cervejas por dia. Corre 3 vezes por semana. Em uso de losartana 100 mg e bisoprolol 5 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (309, 95, 4, '2022-09-05 16:00', 'consulta', 'Coração batendo rápido e canso muito para correr', 132, 80, 138, 92.0, 'Homem de 59 anos com flutter atrial típico (onda F em DII, DIII, aVF, FC 138 com condução 2:1), sintomático com palpitações e cansaço, mesmo com bisoprolol 5 mg. ECO: FEVE 50% (levemente reduzida, possível taquicardiomiopatia), AE 44 mm. TSH normal. CHA2DS2-VASc 1 (HAS). Prefere estratégia de ritmo definitiva, com ablação do istmo cavotricuspídeo.', 'Iniciar apixabana 5 mg 12/12h (flutter requer anticoagulação como a FA). Controle de frequência com bisoprolol 10 mg. Orientado a reduzir álcool. Encaminhamento para ablação do flutter no serviço de eletrofisiologia universitário. Retorno em 30 dias.'),
  (310, 95, 4, '2022-10-17 16:00', 'retorno', 'Quero saber da ablação', 128, 78, 92, 91.0, 'FC mais controlada com bisoprolol 10 mg (92 em repouso), mas persiste sintomático aos esforços. Mantém flutter ao ECG. Aderente à apixabana por 6 semanas, sem sangramentos. O serviço local não realiza ablação de flutter com mapeamento tridimensional; o centro de referência universitário em Uberlândia tem a fila.', 'Encaminhado ao serviço de referência para ablação por cateter do istmo cavotricuspídeo, conforme sua preferência. Transferência do seguimento arritmológico para o hospital universitário, que fará o procedimento e o acompanhamento. Manter apixabana por 3 meses pós-ablação.');
