insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (95, '2022-10-17', 'transferido', 'Flutter atrial típico sintomático, anticoagulado com apixabana e sem controle satisfatório de frequência, encaminhado para ablação do istmo cavotricuspídeo em serviço de eletrofisiologia universitário, que assumiu o seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (96, 'Rubens Alcântara Guimarães Leite', 'M', '1957-06-14', 'São Paulo', 'SP', 'Professor universitário', 'HAS leve controlada com losartana. Sopro cardíaco conhecido desde os 40 anos. Corre maratonas leves. Sem diabetes, sem tabagismo. Sem história familiar relevante.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (311, 96, 2, '2022-05-09 11:00', 'consulta', 'Estou ficando cansado nas corridas', 138, 74, 78, 76.0, 'Homem de 64 anos, corredor amador, com queda de rendimento nos últimos 6 meses e dispneia aos esforços maiores. Sopro holossistólico 4+/6+ em ápice irradiado para axila. ECO: insuficiência mitral grave por prolapso do folheto posterior (flail de P2), regurgitação excêntrica, AE 54 mm, VE DDVE 62 mm e DSVE 41 mm, FEVE 61%, PSAP 44 mmHg. Cateterismo prévio sem lesões coronárias.', 'Insuficiência mitral primária grave, sintomática, com VE se aproximando de dilatação (DSVE 41 mm): indicação de plastia mitral cirúrgica. Encaminhamento ao cirurgião cardiovascular. Evitar corridas de alta intensidade até a cirurgia. Retorno em 3 semanas.'),
  (312, 96, 12, '2022-06-20 07:00', 'internacao', 'Plastia mitral cirúrgica', 118, 66, 72, 76.0, 'Submetido a plastia mitral com ressecção quadrangular de P2 e anuloplastia com anel rígido, por esternotomia mediana. Circulação extracorpórea de 98 min, clampeamento de 70 min. ETE intraoperatório sem refluxo residual ou gradiente significativo. Extubado em 5 h, UTI de 36 h, ritmo sinusal, sem fibrilação atrial. Drenos retirados no 2º dia, alta no 6º dia.', 'Varfarina por 3 meses (INR 2-3) após plastia com anel, depois AAS 100 mg. Carvedilol 3,125 mg 12/12h. Reabilitação cardíaca. Cuidados esternais. ECO em 30 dias. Retorno em 30 dias.'),
  (313, 96, 2, '2022-09-26 11:00', 'retorno', 'Já voltei a caminhar rápido', 122, 70, 64, 75.0, 'Três meses de pós-operatório. INR em 2,4 na faixa. ECO: plastia competente, sem IM residual, gradiente médio 3 mmHg, FEVE 56%, VE com DDVE 54 mm (remodelamento reverso), AE 48 mm. Esterno consolidado. Caminha 6 km diários, sem dispneia. PA 122x70. Pergunta quando poderá correr de novo.', 'Suspender varfarina e iniciar AAS 100 mg. Liberada corrida progressiva a partir de hoje, com reabilitação. Manter losartana e suspender carvedilol. Retorno em 6 meses com ECO.');
