insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (96, '2022-09-26', 'melhorou', 'Insuficiência mitral primária grave corrigida com plastia mitral cirúrgica, sem refluxo residual e com remodelamento reverso do VE. Em AAS e losartana, liberado para correr progressivamente. Segue com ECO semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (97, 'Odília Martins de Souza Lobato', 'F', '1957-03-08', 'Montes Claros', 'MG', 'Doméstica aposentada', 'Cardiopatia chagásica crônica, diagnosticada há 15 anos. IC com FEVE reduzida e TV sustentada documentada há 1 ano. Nasceu em zona rural. HAS leve. Usa enalapril e carvedilol com adesão boa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (314, 97, 4, '2022-03-28 09:00', 'consulta', 'Palpitações fortes e uma tontura que vem de repente', 118, 72, 58, 64.0, 'Paciente de 65 anos com cardiopatia chagásica e FEVE 34%. Episódios de palpitações súbitas seguidas de tontura, sem síncope, 2 vezes por mês. Holter: 1.100 extrassístoles ventriculares/24 h, 4 episódios de TV não sustentada (máx. 14 batimentos), bradicardia sinusal de 48 bpm à noite. ECG: BRD e BDAS. ECO: FEVE 34%, aneurisma apical de 22 mm, sem trombo. Sem indicação de benznidazol (cardiopatia estabelecida).', 'Iniciar amiodarona 200 mg/dia, manter enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h, adicionar espironolactona 25 mg. Indicar CDI (prevenção secundária pela TV sustentada prévia e FEVE < 35%). Anticoagulação não indicada (sem FA ou trombo). Retorno em 30 dias.'),
  (315, 97, 4, '2022-06-13 09:00', 'internacao', 'Implante de CDI', 114, 68, 60, 64.5, 'Implantado CDI dupla câmara, via subclávia esquerda, com teste de desfibrilação bem-sucedido (reversão de FV induzida com 21 J). Estimulação atrial de segurança por bradicardia sinusal. RX sem pneumotórax. Sem hematoma de loja. Alta em 2 dias. Programação: zona de TV 170 bpm com ATP inicial e choque a 200 bpm.', 'Manter amiodarona, enalapril, carvedilol (reduzido por bradicardia, agora protegida pelo MP do CDI) e espironolactona. Orientações sobre choques, braço esquerdo sem esforço por 4 semanas. Carteira do dispositivo. Retorno em 30 dias.'),
  (316, 97, 4, '2023-01-30 09:30', 'retorno', 'Senti um tranco no peito há duas semanas', 120, 74, 62, 65.2, 'Teve um choque do CDI há 2 semanas, ao levantar à noite, com leve tontura posterior, sem síncope. Interrogação: TV monomórfica a 188 bpm tratada com ATP sem sucesso e choque de 25 J com reversão. Ao exame estável, sem sinais de IC. Exames de controle da amiodarona: TSH 3,1 e TGO 28. K 4,6, Mg 2,0. Não faltou aos medicamentos.', 'Aumentar carvedilol para 12,5 mg 12/12h (FC 62 sob estimulação de segurança), manter amiodarona e enalapril. Reprogramar CDI com ATP em salvas mais agressivas. Se novos choques, ablação de TV no centro de referência. Retorno em 8 semanas.'),
  (317, 97, 4, '2023-08-14 09:30', 'retorno', 'Seis meses sem choque', 116, 72, 64, 65.0, 'Seis meses sem novos choques. Interrogação: sem TV sustentada, 3 episódios de TVNS (a mais longa 7 batimentos), 1 ATP bem-sucedido. NYHA II estável. Sem sintomas de hipotireoidismo, TSH 3,6. Função hepática normal. Tolerou a elevação do carvedilol, sem hipotensão ou bradicardia. Conta que o CDI "é como um anjo da guarda".', 'Manter esquema atual. Controle semestral de TSH, TGO/TGP e radiografia de tórax e oftalmologista anual (amiodarona). Revisão do CDI a cada 4 meses. Retorno em 4 meses.');
