insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (97, '2023-08-14', 'estavel', 'Cardiopatia chagásica com FEVE 34% e TV sustentada, protegida por CDI dupla câmara, que reverteu um episódio de TV com choque. Sem novos choques em 6 meses, em amiodarona, enalapril, carvedilol e espironolactona, NYHA II. Segue em revisões regulares.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (98, 'Gabriel Nogueira Sant''Anna Brito', 'M', '1968-05-06', 'Niterói', 'RJ', 'Músico (saxofonista)', 'Valva aórtica bicúspide conhecida desde a juventude, estenose aórtica leve. Usuário de drogas injetáveis no passado, abstinente há 5 anos, com recaída recente. Hepatite C tratada. Última consulta odontológica há anos.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (318, 98, 6, '2023-10-02 23:10', 'pronto_socorro', 'Febre alta há 10 dias e muito cansaço', 100, 52, 116, 66.0, 'Homem de 55 anos com febre de 39,5 °C, calafrios, perda de 6 kg, sudorese noturna e dispneia progressiva há 10 dias. Admite uso de cocaína injetável há 3 semanas. Ao exame: sopro diastólico em foco aórtico 3+/6+, novo, e sopro sistólico mais intenso. Petéquias conjuntivais, nódulos de Osler em dedos. Pulmões com estertores bibasais. Hemoculturas colhidas. Suspeita de endocardite infecciosa aguda em valva aórtica bicúspide.', 'Colher 3 pares de hemoculturas antes de antibiótico. Ecocardiograma urgente. Alergia a penicilina com urticária: iniciar vancomicina 25 mg/kg ataque + gentamicina conforme função renal, cefepime evitado inicialmente. Internação em UTI.'),
  (319, 98, 14, '2023-10-03 14:00', 'internacao', 'UTI, endocardite com insuficiência aórtica', 92, 40, 124, 66.0, 'ETE: vegetação de 14 mm em cúspide coronariana direita de valva aórtica bicúspide, com perfuração e insuficiência aórtica grave, abscesso periaórtico de 12 mm. FEVE 48%. Edema pulmonar leve, BNP 1.900. Sinais de insuficiência cardíaca aguda por valvopatia aguda, pressão de pulso alargada. Bloqueio AV de primeiro grau novo (PR 260 ms) sugerindo extensão perianular. TC de crânio sem embolia cerebral.', 'Discutir com cirurgia cardíaca em caráter de urgência: indicação de troca valvar aórtica e debridamento do abscesso pela IC, abscesso e vegetação > 10 mm. Manter vancomicina, furosemida EV e controle da PA com cautela. Evitar betabloqueador e balão intra-aórtico.'),
  (320, 98, 12, '2023-10-05 08:00', 'internacao', 'Pós-operatório imediato de troca valvar aórtica', 88, 50, 110, 67.0, 'Cirurgia de urgência com troca valvar aórtica por bioprótese e debridamento do abscesso. Pós-operatório com choque vasoplégico, necessitando noradrenalina e vasopressina, FEVE 35%. Em poucas horas: lactato 7,8, anúria, creatinina 3,4, sangramento difuso com coagulopatia. Evoluiu para disfunção de múltiplos órgãos, bloqueio AV total com marca-passo epicárdico. Sem resposta às medidas, apesar de suporte máximo.', 'Suporte máximo em UTI: vasopressores, hemoderivados, hemodiálise contínua. Antibioticoterapia mantida com oxacilina após dessensibilização controlada. Família informada sobre gravidade e prognóstico reservado.');
