insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (98, '2023-10-07', 'obito', 'Óbito no 5º dia de internação por choque séptico e cardiogênico refratário e falência de múltiplos órgãos após endocardite por Staphylococcus aureus em valva aórtica bicúspide, com abscesso periaórtico, apesar de troca valvar de urgência.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (99, 'Hermínio Abreu Bastos Nogueira', 'M', '1944-10-21', 'Cariacica', 'ES', 'Comerciante aposentado', 'HAS há 40 anos, usa anlodipino 5 mg e atenolol 50 mg há anos. Episódios de tontura e palpitações há 1 ano. Nega síncope. Ex-tabagista. Dois irmãos hipertensos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (321, 99, 4, '2022-04-11 10:00', 'consulta', 'Tonteira, coração hora disparado, hora devagar', 144, 78, 48, 72.0, 'Idoso de 77 anos com tontura, cansaço aos esforços e episódios de palpitações rápidas alternados com bradicardia, há 1 ano. ECG de repouso: bradicardia sinusal a 48 bpm. Holter 24h: FC média 52, FC mínima 34 bpm com pausas de até 4,2 s, e 3 episódios de FA paroxística de curta duração com FC até 150 bpm. Usa atenolol 50 mg, que agrava a bradicardia. Síndrome bradicardia-taquicardia (doença do nó sinusal).', 'Suspender atenolol por bradicardia sintomática. Betabloqueador só poderá voltar após o marca-passo. Anticoagulação: CHA2DS2-VASc 3 (idade ≥ 75 anos = 2, HAS = 1), iniciar apixabana 5 mg 12/12h. Indicado marca-passo definitivo. Retorno em 15 dias.'),
  (322, 99, 4, '2022-05-04 08:30', 'internacao', 'Implante de marca-passo definitivo', 148, 80, 52, 72.0, 'Internado eletivamente. Implante de marca-passo dupla câmara via veia cefálica esquerda, com eletrodos ativos em AD e VD, limiares ótimos. Apixabana suspensa por 24 h e retomada após o procedimento. Programação DDD com histerese para minimizar estimulação ventricular. RX de tórax sem pneumotórax. Sem hematoma. ECG pós com estimulação atrial a 60 bpm e condução AV intrínseca.', 'Alta no dia seguinte. Antibiótico profilático pós-implante por 3 dias. Cuidados com a ferida e restrição do braço esquerdo por 4 semanas. Reiniciar betabloqueador de baixa dose (bisoprolol 1,25 mg) para controle de FA, agora protegido por MP. Retorno em 30 dias.'),
  (323, 99, 4, '2022-06-06 10:00', 'retorno', 'Sem mais tonteira, só um pouco de dor na ferida', 138, 76, 64, 72.5, 'Sem tontura ou síncope. Ferida bem cicatrizada. Interrogação do MP: limiares estáveis, impedâncias normais, 78% de estimulação atrial, 3% ventricular, 1 episódio de FA de 14 minutos registrado. PA 138x76. Tolerando bisoprolol 1,25 mg e apixabana, sem sangramento. Exame cardiovascular normal, sem edema e pulmões limpos. Voltou a abrir a loja de um sobrinho três manhãs por semana e caminha na praça.', 'Manter conduta. Seguimento do MP a cada 6 meses. Orientado contra massagem sobre o gerador. Retorno em 6 meses.');
