insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (101, '2024-09-10', 'controlado', 'Hipertensão estágio 1 diagnosticada em consulta, controlada em sete meses com losartana 100 mg e mudança de estilo de vida. Perdeu 6,3 kg, PA 126x78 mmHg, exames metabólicos melhores. Segue em retorno semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (102, 'Zilda Maria Fonseca Braga', 'F', '1962-07-19', 'Diamantina', 'MG', 'Lavradora aposentada', 'HAS há 15 anos, em uso irregular de losartana, anlodipino e hidroclorotiazida. Mora em sítio a 40 km da cidade e só busca remédio quando consegue carona. Nunca fumou. Mãe falecida de AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (330, 102, 1, '2023-05-09 08:30', 'consulta', 'A pressão não abaixa de jeito nenhum, já tomo três remédios', 188, 108, 84, 71.0, 'Encaminhada por suspeita de hipertensão resistente (três drogas, incluindo diurético, sem controle). Ao investigar, relata que as caixas estão misturadas numa sacola, que ‘toma quando lembra’ e que o último pacote de remédios acabou há 10 dias. Pill count: sobraram comprimidos de todas as caixas de datas antigas. Sem cefaleia intensa ou déficit. Exame: BEG, RCR 2T BNF, B4 presente, sem sopros, MV+ sem RA, sem edemas. Fundo de olho com cruzamento arteriovenoso patológico. Pseudorresistência por má adesão.', 'Retomar losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg, todos pela manhã. Organizador semanal de comprimidos fornecido. Contato com agente comunitário de saúde da região para entrega mensal dos remédios. Exames e ECG. Retorno em 6 semanas.'),
  (331, 102, 1, '2023-06-20 09:10', 'retorno', 'Estou tomando tudo certinho agora', 138, 84, 72, 70.6, 'Dona Zilda chega animada: ‘agora eu abro a caixinha de segunda a domingo e acabou a confusão’. Agente comunitário entregou o segundo lote em casa. Sem tonteira, sem edema de tornozelo. PA 138x84 mmHg com a medicação tomada conforme prescrito, confirmando pseudorresistência. Exame cardiovascular sem alterações novas. ECO prévio de outro serviço mostra HVE leve, FEVE 62%.', 'Manter esquema atual, sem necessidade de quarta droga nem investigação secundária neste momento. Orientar a retirar sempre as caixas novas na UBS. Teleconsulta de seguimento em 5 meses.'),
  (332, 102, 1, '2023-11-14 15:00', 'teleconsulta', 'Pressão boa no posto, só queria renovar a receita', 130, 78, null, null, 'Teleconsulta com apoio da filha, que mora na cidade. PA aferida na UBS na semana passada: 130x78 mmHg. Mantém o organizador de comprimidos e diz que ‘esquecer não esquece mais’. Sem dispneia, sem dor torácica, sem edema. Relata câimbras ocasionais nas pernas, sem fraqueza. Potássio de outubro 3,9 mEq/L. Adesão boa confirmada pelo agente comunitário.', 'Renovada receita por 6 meses. Manter os três fármacos. Incentivar ingestão de banana e feijão. Retorno presencial em maio, com creatinina e potássio.');
