insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (102, '2023-11-14', 'controlado', 'Hipertensão aparentemente resistente que se mostrou pseudorresistência por má adesão e falta de acesso aos medicamentos na zona rural. Com organizador de comprimidos e entrega pelo agente comunitário, PA estabilizou em 130x78 mmHg com os mesmos três fármacos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (103, 'Anderson Luiz Pimenta Rocha', 'M', '1981-11-03', 'Montes Claros', 'MG', 'Pedreiro', 'HAS desde os 38 anos, usando losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg sem controle. Câimbras e fraqueza frequentes. Nega tabagismo. Pai hipertenso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (333, 103, 2, '2022-04-05 10:15', 'consulta', 'Pressão alta com três remédios e muita câimbra', 176, 106, 70, 82.3, 'Homem de 40 anos com HAS resistente em triterapia, hipocalemia persistente (K 2,9 mEq/L em exame de rotina) e poliúria noturna. Aderência confirmada por pill count e MRPA domiciliar com média de 168x102. Exame: BEG, RCR 2T BNF, sem sopros, sem edemas, força muscular preservada. Pelo quadro de hipertensão precoce com hipocalemia espontânea, suspeito de hiperaldosteronismo primário. Clortalidona pode agravar a hipocalemia.', 'Suspender clortalidona. Repor KCl e solicitar aldosterona e atividade de renina plasmática (após correção do potássio), ECG e ECO. Encaminhar à endocrinologia. Manter losartana e anlodipino por ora. Retorno em 3 semanas com resultados.'),
  (334, 103, 9, '2022-05-03 14:00', 'retorno', 'Vim ver o resultado dos exames do hormônio', 170, 104, 68, 82.0, 'Endocrinologia: aldosterona plasmática 38 ng/dL com atividade de renina suprimida (0,2 ng/mL/h), relação aldosterona/renina 190, com K 3,6 mEq/L após reposição. Teste confirmatório com sobrecarga salina: aldosterona 14 ng/dL após infusão. Tomografia de adrenais: nódulo de 1,6 cm em adrenal esquerda, hipodenso, contralateral normal. Diagnóstico de hiperaldosteronismo primário por provável adenoma. Paciente jovem, indicado cateterismo de veias adrenais.', 'Solicitado cateterismo de veias adrenais para lateralização. Iniciar espironolactona 50 mg/dia como ponte (monitorar K e creatinina em 2 semanas) e reduzir reposição de potássio. Orientado sobre possibilidade de cura cirúrgica.'),
  (335, 103, 9, '2022-07-12 09:30', 'retorno', 'Fiz o cateterismo das glândulas, vim saber o que deu', 148, 92, 66, 83.1, 'Cateterismo de veias adrenais com cortisol confirmando posicionamento: lateralização para a esquerda, índice de lateralização 9,4 e supressão contralateral. Com espironolactona 50 mg a PA melhorou, K 4,5 mEq/L e creatinina 1,0 mg/dL. Relata discreta mastalgia, sem outras queixas. Indicação clara de adrenalectomia esquerda laparoscópica, com a cirurgia geral já agendada.', 'Encaminhado para adrenalectomia esquerda. Manter espironolactona até a cirurgia. No pós-operatório, suspender espironolactona e monitorar potássio em 1 semana pelo risco de hipercalemia por supressão da zona glomerulosa contralateral. Retorno 30 dias após a cirurgia.'),
  (336, 103, 2, '2022-11-22 10:00', 'retorno', 'Operei a glândula e a pressão normalizou', 122, 76, 64, 80.4, 'Adrenalectomia esquerda laparoscópica em agosto sem intercorrências; histopatologia compatível com adenoma cortical de 1,5 cm. Teve hipercalemia leve (K 5,4) na primeira semana, corrigida com orientação alimentar. Hoje sem câimbras, sem poliúria, disposição melhor para o trabalho na obra. PA 122x76 mmHg com apenas anlodipino 5 mg. Potássio 4,4 mEq/L, aldosterona 6 ng/dL, renina normalizada. Cura bioquímica e clínica do hiperaldosteronismo.', 'Suspensas losartana e espironolactona, mantido apenas anlodipino 5 mg com plano de suspensão se PA seguir abaixo de 125x75. MRPA em 1 mês. Retorno em 6 meses para checar eletrólitos.');
