insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (103, '2022-11-22', 'melhorou', 'Hiperaldosteronismo primário por adenoma adrenal esquerdo, curado por adrenalectomia laparoscópica. Potássio e aldosterona normalizados, PA 122x76 mmHg com apenas anlodipino 5 mg, reduzida de três drogas e suplemento de potássio.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (104, 'Sueli Aparecida Tanaka Mendes', 'F', '1968-01-25', 'Londrina', 'PR', 'Professora de ensino fundamental', 'HAS há 8 anos. Parou a losartana há 3 meses porque ‘a pressão estava normal’. Mãe diabética, pai hipertenso. Nega tabagismo. Alto nível de estresse com turmas lotadas.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (337, 104, 6, '2025-08-17 21:30', 'pronto_socorro', 'Dor de cabeça e pressão 22 por 12 em casa', 214, 122, 88, 68.0, 'Pcte 57a com cefaleia holocraniana leve há 2 dias, aferiu PA em casa 220x120. Nega dor torácica, dispneia, déficit focal, alteração visual, vômitos ou rebaixamento. Parou losartana há ~3 meses. Ao exame: BEG, lúcida, orientada, pupilas isocóricas, sem déficit focal, sem rigidez de nuca. RCR 2T BNF, sem sopros, MV+ sem RA, sem edemas. ECG sem isquemia aguda. Fundo de olho sem papiledema ou hemorragias. Creatinina 0,8, troponina negativa. HD: urgência hipertensiva, sem lesão aguda de órgão-alvo.', 'Repouso em ambiente calmo por 1 hora e captopril 25 mg VO (PA após 90 min: 174x102). Alta com losartana 50 mg 12/12h e anlodipino 5 mg. Orientada a não suspender sem consultar. Evitar dipirona e anti-inflamatórios. Retorno ambulatorial em 7 dias.'),
  (338, 104, 1, '2025-08-25 08:00', 'retorno', 'Retorno depois do pronto-socorro', 152, 94, 78, 67.6, 'Retorna sem cefaleia, tomando a medicação de forma regular. Admite que parou o remédio por achar que ‘a pressão tinha sarado’ e por ter medo de depender dele. Explicado que hipertensão é doença crônica, controlada e não curada. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA. PA 152x94 mmHg, ainda acima da meta, após apenas uma semana de tratamento. ECG sem alterações. Albuminúria ausente.', 'Manter losartana 50 mg 12/12h e subir anlodipino para 10 mg. Orientações sobre sal e estresse. MRPA semanal e diário de pressão. Retorno em 30 dias.'),
  (339, 104, 1, '2025-10-20 08:20', 'retorno', 'Estou tomando direitinho, quero ver a pressão', 124, 76, 74, 66.8, 'Adesão plena, usa alarme no celular. MRPA com média 126x78 mmHg. Refere leve edema de tornozelo ao fim do dia, que melhora ao acordar. Sem cefaleia desde o PS. Exame: PA 124x76, RCR 2T BNF, MMII com edema discreto 1+/4+ sem cacifo importante. Creatinina 0,8 e potássio 4,2 mEq/L. Acredita que o edema seja do anlodipino 10 mg.', 'Reduzir anlodipino para 5 mg e manter losartana 50 mg 12/12h, com vigilância da PA. Se PA subir, associar clortalidona 12,5 mg. Elevar pernas ao fim do dia. Retorno em 4 meses.');
