insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (104, '2025-10-20', 'controlado', 'Urgência hipertensiva por abandono do losartana sem lesão de órgão-alvo, tratada com captopril no PS. Após orientação sobre doença crônica e retomada regular do tratamento, a PA ficou em 124x76 mmHg. Anlodipino reduzido por edema de tornozelo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (105, 'Olavo Bilac Ferreira dos Reis', 'M', '1964-05-09', 'Sete Lagoas', 'MG', 'Caminhoneiro', 'HAS há 10 anos sem acompanhamento regular, tabagista de 35 maços-ano, dislipidemia sem tratamento. Dorme mal e come em postos de estrada. Pai faleceu de IAM aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (340, 105, 6, '2023-09-12 03:10', 'pronto_socorro', 'Dor forte no peito com suor frio, começou na estrada', 158, 96, 92, 91.0, 'Pcte 59a, caminhoneiro, dor precordial em aperto 9/10 há 1h30 com irradiação para MSE e mandíbula, sudorese e náuseas. Ao exame: REG, sudoreico, pálido, RCR 2T BNF sem sopros, MV+ sem RA, perfusão boa. ECG com supra de ST de 3 mm em V1-V4 e DI/aVL. Troponina I 2,8 ng/mL (ref < 0,04). HD: IAMCSST de parede anterior, Killip I. Dupla antiagregação de ataque e encaminhado à hemodinâmica sem demora.', 'AAS 300 mg e ticagrelor 180 mg, heparina não fracionada, atorvastatina 80 mg, metoprolol. Acionada hemodinâmica para angioplastia primária. Internação em UTI após procedimento.'),
  (341, 105, 10, '2023-09-12 05:30', 'internacao', 'Angioplastia primária', 134, 82, 74, 91.0, 'CATE por via radial direita: oclusão trombótica proximal da descendente anterior (TIMI 0), lesão de 50% em coronária direita média e circunflexa sem lesões significativas. Realizada ATC com implante de stent farmacológico 3,5 x 28 mm na DA, fluxo TIMI 3 final, sem complicações. Pós-procedimento em UTI com ECG de queda do supra, assintomático. Pico de troponina 78 ng/mL. ECO: FEVE 46% (Simpson), hipocinesia anterosseptal e apical.', 'Dupla antiagregação (AAS e ticagrelor) por 12 meses, atorvastatina 80 mg, carvedilol e enalapril. Cessação absoluta do tabagismo. Alta da UTI em 48 horas e hospitalar em 4 dias. Reabilitação cardíaca e retorno em 30 dias.'),
  (342, 105, 1, '2023-10-24 10:40', 'retorno', 'Sem dor no peito, parei de fumar', 122, 74, 62, 88.7, 'Paciente refere recuperação tranquila, sem angina e sem dispneia, parou de fumar desde o infarto (‘o susto me curou’) com adesivo de nicotina. Está em afastamento do trabalho e iniciou reabilitação cardíaca. Tosse seca discreta que não o incomoda. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, sem edemas. LDL 62 mg/dL, creatinina 1,0 e potássio 4,5. PA 122x74, FC 62.', 'Manter dupla antiagregação, estatina em alta dose, carvedilol e enalapril. Repetir ECO em 3 meses para reavaliar FEVE. Conversar sobre o retorno às viagens longas com segurança. Retorno em 3 meses.'),
  (343, 105, 1, '2024-04-16 09:20', 'retorno', 'Voltei a dirigir e queria saber como estou', 118, 72, 60, 86.9, 'Sete meses após IAM, assintomático, concluiu reabilitação cardíaca e retornou ao trabalho com paradas a cada 3 horas. Sem tabagismo. Ecocardiograma com FEVE 55% e recuperação da contratilidade anterior. Teste ergométrico sem isquemia, atingindo 10 METs. LDL 58 mg/dL. Exame sem alterações, PA 118x72. Refere dispneia leve com ticagrelor às vezes, tolerável.', 'Manter terapia atual até completar 12 meses de dupla antiagregação (setembro), depois ficar só com AAS. Seguir atorvastatina 80 mg, carvedilol e enalapril. Retorno em 5 meses.');
