insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (105, '2024-04-16', 'melhorou', 'IAMCSST anterior tratado com angioplastia primária e stent farmacológico em DA. Recuperou FEVE de 46% para 55%, parou de fumar, voltou ao trabalho sem angina e com teste ergométrico sem isquemia. Mantém prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (106, 'Edvaldo Nunes Cavalcante', 'M', '1958-09-30', 'Uberlândia', 'MG', 'Aposentado (ex-metalúrgico)', 'HAS há 20 anos, cardiomiopatia dilatada idiopática diagnosticada em 2021. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Ex-tabagista, parou há 12 anos. Etilismo moderado até 2021.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (344, 106, 11, '2022-03-08 14:30', 'consulta', 'Cansaço para andar até a padaria', 118, 72, 78, 84.0, 'Paciente de 63 anos com ICFEr (FEVE 28% em 2021), classe funcional NYHA III. Dispneia aos pequenos esforços, sem ortopneia, edema discreto de tornozelos. Pesa 84 kg, estável. Exame: BEG, RCR 2T, B3 ausente, MV+ com estertores finos em bases, edema 1+/4+. NT-proBNP 2.140 pg/mL, creatinina 1,2 mg/dL (TFGe 65), K 4,6 mEq/L. Terapia incompleta: faltam sacubitril/valsartana, espironolactona e iSGLT2.', 'Suspender enalapril. Aguardar 36 horas e iniciar sacubitril/valsartana 24/26 mg 12/12h. Introduzir espironolactona 25 mg/dia e dapagliflozina 10 mg/dia. Manter carvedilol e furosemida. Exames em 2 semanas (K e creatinina). Restrição de sal e peso diário.'),
  (345, 106, 11, '2022-04-12 14:00', 'retorno', 'Tontura quando levanto da cama', 98, 62, 70, 81.9, 'Perdeu 2,1 kg e a dispneia melhorou para NYHA II, porém refere tontura postural leve nos primeiros dias da sacubitril/valsartana. PA sentado 98x62, ortostase 92x58 sem síncope. K 4,9 mEq/L, creatinina 1,3 mg/dL, aumento esperado. Sem hipoglicemia, diurese aumentada com dapagliflozina. Exame: euvolêmico, sem estertores, sem edemas. Paciente quase desistiu por causa da tontura.', 'Suspender furosemida (euvolêmico, diurético sobreposto aos efeitos do iSGLT2). Manter os quatro pilares nas mesmas doses. Orientar levantar devagar e hidratação adequada. Repetir K e creatinina em 2 semanas. Retorno em 3 meses.'),
  (346, 106, 11, '2022-07-19 15:10', 'retorno', 'Melhorei bastante, consigo caminhar 2 quarteirões', 110, 68, 64, 80.8, 'NYHA II, sem ortopneia, sem edema, sem tontura. Peso estável em 80,8 kg. PA 110x68, FC 64 em uso de carvedilol. K 4,7, creatinina 1,2. Exame: BEG, RCR 2T, sem B3, MV+ sem RA. Tolera bem as medicações, sem tosse ou angioedema. Relata ter diminuído a cerveja de fim de semana após a explicação sobre cardiomiopatia.', 'Titular sacubitril/valsartana para 49/51 mg 12/12h e carvedilol para 12,5 mg 12/12h. Manter espironolactona e dapagliflozina. K e creatinina em 2 semanas. Reabilitação cardiopulmonar encaminhada. ECO em 6 meses.'),
  (347, 106, 11, '2023-03-14 14:20', 'retorno', 'Estou bem, faço caminhada de 30 minutos', 112, 70, 58, 80.2, 'Há cerca de um ano em terapia quádrupla, NYHA I-II, sem internações. ECO: FEVE 41% (Simpson) com redução do diâmetro diastólico do VE de 68 para 62 mm, remodelamento reverso. NT-proBNP 480 pg/mL. K 4,8, creatinina 1,2. Sem hipotensão sintomática. Boa adesão, usa organizador. Tolerou subir carvedilol, FC 58 bpm assintomática.', 'Manter doses atuais, sem nova titulação por FC 58. Orientado a manter reabilitação. Considerar CDI apenas se FEVE seguir ≤ 35% após 3 meses de terapia otimizada, que não é o caso agora. Retorno em 6 meses.');
