insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (106, '2023-03-14', 'melhorou', 'ICFEr por cardiomiopatia dilatada com terapia dos quatro pilares otimizada. FEVE subiu de 28% para 41%, NT-proBNP caiu de 2.140 para 480 pg/mL, classe funcional passou de III para I-II. Sem internações, segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (107, 'Cleonice Aparecida Vasconcelos', 'F', '1951-12-02', 'Juiz de Fora', 'MG', 'Do lar', 'HAS há 25 anos, DM2 há 10 anos com metformina, dislipidemia. Em uso de losartana 50 mg 12/12h. Nunca fumou. Mora com o marido idoso e cuida dos netos pela manhã.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (348, 107, 4, '2022-02-15 09:00', 'consulta', 'Coração disparando e falta de ar quando subo a rua', 144, 86, 118, 74.5, 'Paciente de 70 anos com palpitações irregulares há cerca de 2 meses e cansaço aos médios esforços. Sem síncope, sem dor torácica. Exame: BEG, RCI 2T, FC 118 bpm, sem sopros, MV+ sem RA, sem edemas. ECG: fibrilação atrial com resposta ventricular média de 118 bpm. ECO: átrio esquerdo 46 mm, FEVE 58%, sem valvopatia significativa. TSH 2,1 mUI/L. CHA2DS2-VASc 4 (idade 65-74, sexo feminino, HAS, DM). Clcr 62 mL/min.', 'Iniciar apixabana 5 mg 12/12h e metoprolol succinato 50 mg/dia para controle de frequência. Estratégia inicial de controle de FC. Orientar sinais de sangramento. Evitar AINEs. Retorno em 30 dias.'),
  (349, 107, 4, '2022-03-22 09:30', 'retorno', 'Melhorou a falta de ar, mas sangrei do nariz', 132, 80, 76, 74.0, 'FC controlada em FA, 76 bpm. Dispneia melhorou muito. Relata dois episódios de epistaxe leve, autolimitados, após assoar. Sem melena ou hematúria. Hb 12,8 g/dL, plaquetas normais. Exame de fossas nasais com mucosa ressecada, sem sangramento ativo. PA 132x80. Aderência boa, controle de FC satisfatório.', 'Manter apixabana pelo benefício em prevenção de AVC. Orientar umidificação nasal com soro fisiológico. Metoprolol e demais drogas mantidos. Hemograma em 3 meses. Retorno em 3 meses.'),
  (350, 107, 4, '2023-08-29 10:10', 'retorno', 'Sem sintomas, vim fazer o controle', 128, 76, 70, 73.2, 'FA permanente, assintomática, FC 70 bpm. Sem novos episódios de epistaxe. Tomando apixabana sem falhas, o marido a ajuda com o horário. Hb 13,1, creatinina 0,9 (Clcr 66), sem indicação de redução de dose da apixabana (idade < 80, peso > 60, Cr < 1,5). HbA1c 6,9%. Exame sem alterações, ritmo irregular, sem sopros.', 'Estratégia de controle de frequência mantida; sem indicação de cardioversão pelo tempo de FA e átrio aumentado. Seguir apixabana 5 mg 12/12h e metoprolol. Creatinina e hemograma anuais. Retorno em 6 meses.');
