insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (107, '2023-08-29', 'estavel', 'Fibrilação atrial permanente com controle de frequência (FC 70 bpm) e anticoagulação com apixabana, sem eventos tromboembólicos. Epistaxe leve inicial resolvida com umidificação. Segue com acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (108, 'Raimundo Nonato Arantes', 'M', '1955-04-17', 'Janaúba', 'MG', 'Lavrador aposentado', 'Doença de Chagas crônica conhecida desde 2010 (sorologia positiva), nascido e criado em casa de pau a pique no norte de Minas. HAS leve controlada com enalapril. Etilismo ocasional. Sem tabagismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (351, 108, 6, '2020-02-11 03:20', 'pronto_socorro', 'Desmaiei no quintal e caí no chão', 150, 70, 34, 68.0, 'Pcte 64a, chagásico, trazido por familiares após síncope súbita, com escoriação em supercílio. Refere tontura e cansaço nos últimos dias. Ao exame: REG, pálido, FC 34 bpm regular, ritmo bradicárdico, B4 ausente, MV+ sem RA, sem edemas. ECG: BAVT com escape juncional a 34 bpm, BRD associado. Sem sinais de IC. HD: BAVT em cardiopatia chagásica com síncope. Bradicardia sintomática, indicação de MP definitivo.', 'Monitorização contínua e pás de marca-passo transcutâneo à beira leito. Atropina sem resposta. Internar para implante de MP definitivo com cardiologia. Suspender enalapril temporariamente. Sutura do supercílio.'),
  (352, 108, 4, '2020-02-12 14:00', 'internacao', 'Implante de marca-passo', 140, 80, 70, 68.0, 'Realizado implante de marca-passo definitivo bicameral (DDD) por acesso subclávio esquerdo, sem intercorrências, limiares adequados (ventrículo 0,6 V, átrio 0,8 V). ECO: FEVE 52%, aneurisma apical de VE pequeno sem trombo, átrio esquerdo 41 mm. Sem IC. Holter prévio com EV isoladas e raros pares. Sem indicação de benznidazol, dada cardiopatia estabelecida. Alta em 48 horas com raio X de controle adequado.', 'Antibioticoprofilaxia pré-operatória realizada, curativo oclusivo por 7 dias, evitar levantar o braço esquerdo acima do ombro por 4 semanas. Retomar enalapril. Cartão do marca-passo entregue. Retorno em 30 dias para revisão da loja do gerador.'),
  (353, 108, 4, '2020-03-10 09:00', 'retorno', 'Sem desmaio, só um dolorido no ombro', 138, 78, 72, 68.8, 'Ferida operatória cicatrizada, sem hiperemia, hematoma ou secreção, gerador móvel normal. Sem síncope. Ritmo atrial com estimulação ventricular, FC 72. Interrogação do MP: bateria 100%, estimulação ventricular 96%, limiares estáveis, sem arritmia ventricular sustentada. Nega dispneia. Orientado sobre viver com MP: evitar proximidade de ímãs, avisar equipes antes de ressonância.', 'Manter enalapril. Programação dos parâmetros mantida. Checagem do MP a cada 6 meses. Holter de 24h em 6 meses para vigiar arritmias ventriculares. Orientar manter consultas mesmo assintomático.'),
  (354, 108, 4, '2021-08-24 08:40', 'retorno', 'Vim fazer a revisão do aparelho', 134, 80, 70, 70.0, 'Dezoito meses após o implante, sem síncope, sem palpitações. Vem de Janaúba com o filho em viagem de 4 horas, o que dificultou seguimento mais frequente. Holter 24h: ritmo atrial com estimulação ventricular, 480 EV/24h, sem TV sustentada. ECO: FEVE 50%. Interrogação do MP sem alertas, bateria 92%. Nega dispneia, edema ou ortopneia. PA 134x80.', 'Manter enalapril 10 mg 12/12h. Agendar consultas semestrais com telemonitoramento do MP em posto próximo. Se palpitações, síncope ou dispneia, procurar o PS. Reforçar sorologia dos familiares para Chagas.');
