insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (108, '2021-08-24', 'estavel', 'Cardiopatia chagásica com BAVT tratada com marca-passo bicameral, sem recorrência de síncope. FEVE 50% sem IC, EV isoladas ao Holter. Segue em acompanhamento semestral com telemonitoramento do aparelho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (109, 'Hermínia Gonçalves Pacheco', 'F', '1940-10-08', 'Ouro Preto', 'MG', 'Aposentada (ex-professora)', 'HAS há 30 anos, DRC estágio 3a, osteoporose e fragilidade moderada (usa bengala). Mora com a filha. Em uso de anlodipino 5 mg e losartana 50 mg/dia. Sem tabagismo.', 'Alergia a penicilina (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (355, 109, 1, '2023-06-13 10:00', 'consulta', 'Falta de ar e dor no peito quando subo o morro de casa', 128, 62, 68, 57.5, 'Paciente de 82 anos com piora progressiva de dispneia e angina aos pequenos esforços há 4 meses, e um episódio de pré-síncope ao subir escada. Exame: frágil, RCR 2T com B4, sopro sistólico ejetivo 4+/6+ em foco aórtico irradiado para carótidas, 2ª bulha hipofonética, MV+ sem RA, sem edemas. ECO: estenose aórtica grave, área valvar 0,7 cm², gradiente médio 52 mmHg, velocidade máxima 4,6 m/s, FEVE 60%, HVE moderada. Creatinina 1,3 (TFGe 38).', 'Estenose aórtica grave sintomática: discutir com Heart Team. Alto risco cirúrgico (idade, fragilidade, DRC), indicação de TAVI. Solicitados angiotomografia de aorta/ilíacas e cateterismo (avaliar DAC). Suspender anlodipino se tonturas. Evitar esforços até o procedimento.'),
  (356, 109, 10, '2023-07-18 11:00', 'retorno', 'Vim ver o resultado dos exames do coração', 124, 60, 66, 57.0, 'Hemodinâmica: coronárias sem lesões obstrutivas (ateromatose discreta). Angiotomografia: acesso femoral direito com diâmetro de 6,8 mm, sem calcificação grave; anel aórtico 22 mm, adequado para prótese balão-expansível de 23 mm. Heart Team conclui por TAVI transfemoral. Paciente e filha informadas dos riscos (AVC, marca-passo, sangramento) e aceitam. Hidratação para proteção renal no dia do contraste.', 'Internação programada para TAVI transfemoral. Pré-medicação de alergia à penicilina: uso de cefazolina é aceitável pelo baixo risco cruzado. Manter losartana até 48h antes. Exames pré-operatórios e profilaxia dentária.'),
  (357, 109, 10, '2023-08-22 07:30', 'internacao', 'Internada para implante de prótese aórtica por cateter', 130, 64, 70, 57.2, 'TAVI transfemoral com prótese balão-expansível de 23 mm sob sedação, sem intercorrências. Gradiente médio pós-implante 8 mmHg, leve vazamento paravalvar (grau 1), sem BAV novo. Recuperação na UTI por 24h (Dr. Rafael), mobilização precoce, sem complicações vasculares. Creatinina pós 1,3 mg/dL, estável. Alta hospitalar no 3º dia. ECG sem BAV, apenas BRE novo parcial.', 'AAS 100 mg contínuo, atorvastatina 40 mg. Controle da PA com losartana. Antibioticoprofilaxia para procedimentos dentários. Fisioterapia motora e retorno em 30 dias.'),
  (358, 109, 1, '2023-10-03 10:30', 'retorno', 'Consigo subir a ladeira sem parar', 132, 66, 64, 58.4, 'Seis semanas após TAVI, sem angina, sem pré-síncope, voltou a caminhar na praça com a filha. Ganhou 1,2 kg. Exame: BEG, RCR 2T, sopro sistólico discreto 1+/6+, MV+ sem RA, sem edemas. Gradiente médio 9 mmHg ao ECO e FEVE 62%. Sem sangramentos. Creatinina 1,2 mg/dL. Satisfeita: ‘parece que ganhei dez anos’.', 'Manter AAS, atorvastatina e losartana. Reforçar profilaxia dentária. Fisioterapia seguida. ECO anual. Retorno em 6 meses.');
