insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (110, '2024-08-27', 'melhorou', 'Pericardite aguda pós-viral em jovem, tratada com anti-inflamatório e colchicina, sem recidiva. Ressonância sem miocardite, teste ergométrico normal. Liberado para esportes e dado alta do ambulatório.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (111, 'Luzia Helena Kobayashi Prado', 'F', '1975-06-12', 'São Paulo', 'SP', 'Contadora', 'Pré-hipertensa informada há 3 anos, sem tratamento. Sedentária, trabalha 10 horas por dia sentada, com picos de estresse no fechamento fiscal. Mãe com AVC aos 68 anos. Menopausa precoce aos 47 anos, sem reposição hormonal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (362, 111, 1, '2025-01-20 17:30', 'consulta', 'Dor de cabeça na nuca quase toda tarde', 168, 104, 82, 72.0, 'Paciente de 49 anos com cefaleia occipital vespertina há 2 meses e PA domiciliar entre 160-175 x 98-105 mmHg. Sem dor torácica, dispneia ou alterações visuais. Nega uso de anti-inflamatórios, descongestionantes ou anticoncepcionais. Exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, pulsos simétricos nos 4 membros, sem edemas. IMC 27,5. PA em ambos os braços semelhantes. Hipertensão estágio 2, risco cardiovascular alto pela soma de fatores.', 'Iniciar combinação em comprimido único: olmesartana 40 mg + anlodipino 5 mg pela manhã. Exames de rotina, ECG, ECO, relação albumina/creatinina. MEV: sal, 150 min/sem de atividade física. Retorno em 30 dias.'),
  (363, 111, 1, '2025-02-24 17:00', 'retorno', 'A cabeça parou de doer', 138, 86, 76, 71.2, 'Sem cefaleia desde a primeira semana. Tomou o comprimido único todos os dias, sem esquecimentos, graças à simplicidade do esquema. Sem edema, sem tosse. ECO: HVE leve (septo 12 mm), FEVE 64%. Albuminúria 8 mg/g, creatinina 0,8. LDL 132 mg/dL, glicemia normal. PA 138x86 mmHg, melhor, mas ainda acima da meta de 130/80.', 'Aumentar a combinação para olmesartana 40 mg + anlodipino 10 mg. Iniciar caminhada orientada de manhã. Não iniciar estatina ainda, reavaliar risco após meta pressórica. Retorno em 3 meses.'),
  (364, 111, 1, '2025-05-26 17:20', 'retorno', 'Vim mostrar o diário da pressão', 124, 76, 72, 69.8, 'MRPA com média de 122x75 mmHg. Passou a caminhar 40 minutos três vezes por semana e deixou de levar trabalho para casa nos fins de semana. Perdeu 2,2 kg desde o início. Edema vespertino discreto em tornozelos, sem cacifo, tolerável. Sem cefaleia. Exame: PA 124x76, RCR 2T BNF, sem sopros, MV+ sem RA.', 'Manter combinação 40/10 mg. Elevar membros inferiores à noite, avaliar redução do anlodipino se edema piorar. Retorno em 6 meses com exames de controle e lipidograma.');
