insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (111, '2025-05-26', 'controlado', 'Hipertensão estágio 2 em mulher de 49 anos, tratada com combinação em comprimido único (olmesartana/anlodipino), que facilitou a adesão. MRPA média 122x75 mmHg, HVE leve ao ECO, cefaleia resolvida. Perdeu 2,2 kg com caminhada regular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (112, 'Josué Batista de Almeida', 'M', '1960-02-08', 'Governador Valadares', 'MG', 'Comerciante (dono de mercearia)', 'HAS há 14 anos e DM2 há 9 anos. Usa losartana 50 mg e metformina 850 mg 12/12h, com adesão irregular porque trabalha de 7h às 21h na mercearia. Ex-fumante há 6 anos. Pai com insuficiência renal e diabetes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (365, 112, 3, '2022-08-09 13:30', 'consulta', 'Os exames de rotina deram alterados', 154, 92, 80, 94.0, 'Paciente de 62 anos, HAS e DM2, trazendo exames da empresa: HbA1c 8,4%, creatinina 1,1 mg/dL (TFGe 74), relação albumina/creatinina urinária 186 mg/g em duas amostras (albuminúria moderadamente aumentada). Sem edema ou espuma na urina. Exame: PA 154x92, RCR 2T BNF, sem sopros, MV+ sem RA, pulsos pediosos presentes, sensibilidade preservada. Fundo de olho sem retinopatia. Doença renal do diabetes e da hipertensão em estágio inicial.', 'Aumentar losartana para 100 mg/dia (bloqueio do SRAA como pilar na albuminúria). Adicionar dapagliflozina 10 mg/dia. Meta de PA abaixo de 130x80. Reforçar dieta e checagem de glicemia. Creatinina e potássio em 2 semanas. Retorno em 8 semanas.'),
  (366, 112, 1, '2022-10-04 14:00', 'retorno', 'Estou urinando bastante, mas me sinto bem', 136, 82, 74, 91.2, 'Perdeu 2,8 kg e relata poliúria leve com dapagliflozina, sem infecção urinária ou genital. Creatinina subiu discretamente a 1,2 (esperado), potássio 4,4. Glicemias de jejum entre 118 e 140 mg/dL. PA 136x82 mmHg, no caminho. Exame cardiovascular normal. Orientado sobre higiene genital e cetoacidose em jejuns prolongados ou doenças agudas.', 'Manter losartana 100 mg e dapagliflozina. Adicionar anlodipino 5 mg para atingir meta. Dieta com menos sal, e encaminhamento à nutrição. Repetir albuminúria e HbA1c em 3 meses.'),
  (367, 112, 1, '2023-04-18 13:40', 'retorno', 'Vim ver se melhorou o rim', 128, 78, 72, 88.9, 'Seguimento de 8 meses. PA 128x78 mmHg, MRPA 126x76. HbA1c 7,1%. Albuminúria caiu para 92 mg/g, creatinina 1,2 (TFGe 69), potássio 4,5. Perdeu 5 kg desde a primeira consulta. Sem edemas. Segue mais cuidadoso com o sal, mas confessa lanches rápidos no balcão. Albuminúria ainda em faixa moderada, justificando continuidade do bloqueio do SRAA e acompanhamento nefrológico.', 'Manter esquema atual. Encaminhar à nefrologia para acompanhamento conjunto. Estatina para prevenção: atorvastatina 20 mg à noite. Exames em 4 meses. Retorno em 4 meses.');
