insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (112, '2023-04-18', 'estavel', 'HAS e DM2 com albuminúria moderada, PA na meta e HbA1c 7,1%. Albuminúria caiu de 186 para 92 mg/g com losartana 100 mg e dapagliflozina, função renal estável. Segue com cardiologia, clínica e nefrologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (113, 'Nilton César Menezes Guimarães', 'M', '1969-10-21', 'Uberaba', 'MG', 'Gerente de fazenda', 'HAS há 11 anos em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Sobrepeso, não fuma, bebe cerveja aos fins de semana. Sem diabetes. Pai falecido de AVC aos 66 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (368, 113, 2, '2021-03-16 08:30', 'consulta', 'Mesmo tomando tudo a pressão não cai', 168, 102, 74, 91.0, 'Homem de 51 anos com PA persistentemente elevada apesar de três drogas em doses plenas, incluindo diurético. Adesão confirmada: usa caixinha semanal e a esposa confere. Técnica de medida correta, manguito adequado. MAPA em vigília 162x98 mmHg, sono 148x88, sem avental branco. Sem uso de AINEs, ingestão de sal estimada alta (natriurese 24h 210 mEq). K 4,2 mEq/L, aldosterona/renina normais, sem sinais de apneia. Hipertensão resistente verdadeira.', 'Adicionar espironolactona 25 mg/dia como quarta droga. Reduzir sal (natriurese alvo < 100 mEq/dia) e cerveja. Potássio e creatinina em 1 semana e 4 semanas. Retorno em 6 semanas.'),
  (369, 113, 2, '2021-04-27 08:40', 'retorno', 'Pressão melhorou, mas os peitos ficaram doloridos', 142, 86, 68, 90.2, 'PA 142x86 mmHg, queda de 26 mmHg na sistólica. Relata mastalgia à esquerda com ginecomastia leve, sem nódulos palpáveis, atribuída à espironolactona. K 4,9 mEq/L e creatinina 1,2 mg/dL, aceitáveis. Aderente. Orientado sobre o efeito antiandrogênico. Quer continuar porque ‘a pressão nunca esteve tão boa’. Exame cardiovascular sem alterações, sem edemas.', 'Manter espironolactona 25 mg, reavaliar sintomas em 6 semanas e considerar troca por eplerenona se piorar. Reforçar dieta sem sal, mas evitar suplementos de potássio. K e creatinina em 4 semanas. Retorno em 8 semanas.'),
  (370, 113, 2, '2021-06-29 09:00', 'retorno', 'A dor no peito de mulher passou', 128, 78, 66, 88.4, 'A mastalgia desapareceu em 3 semanas, ficando apenas um discreto aumento mamário sem dor. PA 128x78 mmHg, MRPA média 126x76. Natriurese reduzida a 128 mEq/24h, perdeu 2,6 kg. K 4,8, creatinina 1,2. Sem hipotensão ou câimbras. Nenhum efeito colateral limitante remanescente. Paciente motivado com a melhora, vai manter cerveja apenas esporadicamente.', 'Manter quatro drogas nas doses atuais. Potássio e creatinina a cada 4 meses. Estimular perda de mais 4 kg. Retorno em 6 meses.'),
  (371, 113, 2, '2022-01-11 08:50', 'retorno', 'Controle semestral', 124, 76, 64, 86.0, 'Seis meses depois, PA 124x76 mmHg, MAPA de controle com média de 24h de 122x74 e descenso noturno presente. Perdeu 5 kg no total. K 4,7, creatinina 1,1, ácido úrico 6,8. Nenhuma queixa, ginecomastia estável e indolor. Boa adesão. Fundo de olho e ECO sem progressão de lesão de órgão-alvo (HVE leve, FEVE 63%).', 'Manter os quatro fármacos. Tentativa de reduzir clortalidona para 12,5 mg no próximo retorno se PA se mantiver. Retorno em 6 meses.');
