insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (113, '2022-01-11', 'controlado', 'Hipertensão resistente verdadeira, com adesão confirmada e MAPA elevado, controlada com a adição de espironolactona 25 mg e redução do sal. MAPA de 24h com média 122x74 mmHg. Ginecomastia dolorosa inicial resolvida, potássio seguro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (114, 'Gilberto Kramer Hoffmann', 'M', '1972-03-30', 'Blumenau', 'SC', 'Representante comercial', 'HAS há 6 anos com tratamento crescente (hoje losartana 100 mg, anlodipino 10 mg, hidroclorotiazida 25 mg). Obesidade, ronco alto referido pela esposa, sonolência ao dirigir. Etilismo social, não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (372, 114, 2, '2022-09-13 16:30', 'consulta', 'Pressão alta mesmo com três remédios e durmo no volante', 174, 108, 84, 118.0, 'Paciente de 50 anos com HAS resistente (3 drogas, uso confirmado), obeso (IMC 37,8), pescoço 46 cm. Esposa relata roncos intensos e pausas respiratórias noturnas. Acorda com cefaleia matinal, sonolência diurna importante (Epworth 15), quase adormeceu ao volante duas vezes. Exame: Mallampati III, RCR 2T BNF, B4, sem sopros, edema discreto. Alta suspeita de apneia obstrutiva do sono como causa de hipertensão secundária e resistência.', 'Solicitada polissonografia de noite inteira. Orientado a não dirigir em viagens longas até o diagnóstico. Manter esquema, aderir à dieta e reduzir álcool. Retorno com resultado em 4 semanas.'),
  (373, 114, 2, '2022-11-08 16:00', 'retorno', 'Fiz o exame do sono, vim ver o resultado', 170, 104, 80, 117.2, 'Polissonografia: IAH 46 eventos/h (apneia grave), SpO2 mínima 71%, T90 de 24% do sono, predomínio de eventos obstrutivos. Excluída apneia central. ECO: HVE moderada, FEVE 59%, átrio esquerdo 42 mm. PA 170x104 mmHg. Paciente receptivo ao tratamento por querer voltar a dirigir sem sono. Conversa sobre CPAP e emagrecimento.', 'Iniciar CPAP automático com titulação, fornecido pelo plano. Encaminhamento à nutrição e atividade física. Manter anti-hipertensivos até reavaliação, sem intensificar por ora. Retorno em 10 semanas com relatório do CPAP.'),
  (374, 114, 2, '2023-03-21 16:20', 'retorno', 'Uso o CPAP todas as noites e estou outro homem', 128, 78, 70, 108.5, 'Uso do CPAP médio de 6h40 por noite em 94% das noites, IAH residual 3/h. Acorda descansado, sem cefaleia, Epworth 5. Perdeu 9,5 kg com acompanhamento nutricional. PA 128x78 mmHg, MAPA com média de 24h de 124x76 e descenso noturno restabelecido. Exame: RCR 2T BNF, sem edemas. Pressão normalizou em paralelo ao tratamento da apneia, confirmando o papel causal da AOS.', 'Suspender hidroclorotiazida e manter losartana 100 mg e anlodipino 10 mg. Seguir com CPAP e dieta; meta de IMC < 32. Reavaliar para reduzir mais um fármaco em 4 meses. Retorno em 4 meses.');
