insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (114, '2023-03-21', 'melhorou', 'Hipertensão resistente secundária à apneia obstrutiva do sono grave (IAH 46). Com CPAP e perda de 9,5 kg, a PA passou a 128x78 mmHg com duas drogas, uma a menos que antes. Sonolência resolvida e volta a dirigir com segurança.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (115, 'Arlete Nascimento Quintanilha', 'F', '1957-08-14', 'Salvador', 'BA', 'Cozinheira', 'HAS há 20 anos, sem acompanhamento nos últimos 2 anos. Sem remédio há cerca de 5 meses por falta de dinheiro. Tabagista (30 maços-ano), obesa, nega diabetes. Mãe falecida de AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (375, 115, 6, '2024-03-09 02:40', 'pronto_socorro', 'Cefaleia súbita muito forte e fraqueza no lado direito', 252, 142, 96, 88.0, 'Pcte 66a, trazida pelo filho após cefaleia súbita holocraniana de forte intensidade, vômitos e queda ao solo com hemiparesia à direita e disartria, às 23h30. Sem remédio há 5 meses. Ao exame: REG, sonolenta (Glasgow 12), hemiparesia direita grau II, desvio do olhar para a esquerda, pupilas isocóricas fotorreagentes. PA 252x142 mmHg. TC de crânio: hemorragia intraparenquimatosa em núcleos da base à esquerda, volume 48 mL, com inundação ventricular discreta. HD: AVC hemorrágico hipertensivo, emergência hipertensiva.', 'Nicardipina EV em bomba, meta de PAS entre 130-150 mmHg na primeira hora, cuidando para evitar quedas bruscas. Cabeceira a 30°, glicemia e coagulograma. Contato com neurologia e UTI. Vaga em UTI para monitorização, sem indicação cirúrgica imediata.'),
  (376, 115, 13, '2024-03-09 09:00', 'internacao', 'Avaliação neurológica em UTI', 148, 86, 82, 88.0, 'Neurologia: Glasgow 11, hemiplegia direita, afasia de expressão, anisocoria discreta ausente. Tomografia de controle 6h depois: hematoma 62 mL, aumento de 14 mL com edema perilesional e desvio de linha média de 5 mm. Crescimento do hematoma apesar do controle pressórico. Escore ICH 3. Discutido com a família o prognóstico reservado. Sem indicação de craniectomia dado o tamanho, topografia profunda e inundação ventricular.', 'Manter PAS 130-140 mmHg, manitol 20% 100 mL 6/6h para hipertensão intracraniana, cabeceira elevada, controle glicêmico e profilaxia de TVP com meia compressiva. Reavaliação neurológica a cada 4 horas. Cuidados de suporte em UTI.'),
  (377, 115, 14, '2024-03-12 07:30', 'internacao', 'Rebaixamento do nível de consciência', 178, 100, 54, 88.0, 'UTI, D3 de AVC hemorrágico. Piora neurológica: Glasgow 6, anisocoria com midríase à esquerda, padrão respiratório irregular, bradicardia e hipertensão (tríade de Cushing). TC: aumento do edema, desvio de linha média 11 mm, herniação subfalcina e uncal incipiente. Intubada e em ventilação mecânica. Sem resposta a medidas antiedema máximas, sem indicação neurocirúrgica por hematoma profundo extenso. Reunião com os filhos sobre limitação de suporte.', 'Manter suporte clínico, sem novas intervenções invasivas, por decisão conjunta com a família. Salina hipertônica, sedação, manutenção de PAS < 160. Vigiar protocolo de morte encefálica se houver evolução. Apoio psicológico à família.');
