insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (115, '2024-03-13', 'obito', 'Óbito por AVC hemorrágico hipertensivo (hematoma de núcleos da base com inundação ventricular e herniação) no 4º dia de internação em UTI. Havia abandonado o tratamento anti-hipertensivo por 5 meses por dificuldade financeira. Família informada e acompanhada pelo serviço social.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (116, 'Priscila Andrade Moura Cunha', 'F', '1984-09-05', 'Curitiba', 'PR', 'Advogada', 'Sem comorbidades conhecidas. PA elevada em duas consultas de rotina no trabalho, nunca confirmada fora do consultório. Ansiedade leve. Pratica corrida três vezes por semana. Usa anticoncepcional com progestágeno isolado.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (378, 116, 1, '2023-04-11 12:30', 'consulta', 'Pressão alta no consultório, mas normal em casa', 152, 96, 88, 62.0, 'Paciente de 38 anos, assintomática, encaminhada por PA 150-155x94-98 em duas consultas de rotina. Em casa, as aferições com aparelho validado variam de 112-124x70-78. Nervosa durante a consulta (‘fico tensa só de ver o aparelho’), FC 88. Em segunda medida, após 5 minutos de repouso, PA 146x92. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, sem edemas, IMC 22. Suspeita de hipertensão do avental branco.', 'Não iniciar medicação. Solicitada MAPA de 24h para confirmar. Orientada manter corrida, reduzir cafeína e sal. Exames laboratoriais e ECG de rotina. Retorno com o resultado em 3 semanas.'),
  (379, 116, 1, '2023-05-23 12:30', 'retorno', 'Vim ver o resultado do aparelho de 24 horas', 148, 92, 84, 61.6, 'MAPA 24h: média de vigília 118x74 mmHg, sono 104x62 mmHg, média de 24h 114x70, com descenso noturno preservado. PA no consultório 148x92 mmHg, dissociação clássica. Confirmado hipertensão do avental branco, sem lesão de órgão-alvo (ECO normal, albuminúria ausente). Risco cardiovascular baixo. Aliviada por não precisar de remédio. Explicado que existe risco de evolução futura para hipertensão sustentada.', 'Sem tratamento medicamentoso. Manter MEV e MRPA a cada 6 meses. Repetir MAPA em 1 ano. Reavaliar caso apareça lesão de órgão-alvo ou riscos associados. Avisar o clínico de rotina para não rotular como hipertensa. Retorno em 6 meses.');
insert into diagnostico (id_atendimento, cid, descricao) values
  (378, 'R03.0', 'Valor elevado da pressão arterial sem o diagnóstico de hipertensão'),
  (379, 'R03.0', 'Valor elevado da pressão arterial sem o diagnóstico de hipertensão');
