insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (116, '2023-05-23', 'estavel', 'Hipertensão do avental branco confirmada por MAPA (média de 24h 114x70 mmHg) com PA de consultório 148x92. Sem lesão de órgão-alvo, sem indicação de medicação. Segue com MRPA semestral e MEV.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (117, 'Maria da Penha Vieira Soares', 'F', '1956-11-26', 'Ipatinga', 'MG', 'Costureira aposentada', 'HAS há 18 anos, DM2 há 12 anos, dislipidemia. Usa losartana 50 mg 12/12h, metformina 850 mg 12/12h e sinvastatina 20 mg. Ex-fumante há 15 anos. Irmão faleceu de IAM aos 55 anos.', 'Alergia a AAS (broncoespasmo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (380, 117, 1, '2023-02-07 14:00', 'consulta', 'Aperto no peito quando ando rápido e passa se eu paro', 138, 82, 74, 76.0, 'Paciente de 66 anos com dor retroesternal em aperto desencadeada por esforço moderado (subir 1 lance de escada) há 2 meses, com alívio em cerca de 3 minutos de repouso, classe CCS II. Sem episódios em repouso. Exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, pulsos presentes, sem edemas. ECG de repouso normal. Alergia a AAS: broncoespasmo documentado. LDL 118 mg/dL em uso de sinvastatina 20 mg. HbA1c 7,4%. Angina estável provável.', 'Solicitar teste ergométrico. Iniciar metoprolol succinato 50 mg/dia, clopidogrel 75 mg (AAS contraindicado), trocar sinvastatina por atorvastatina 40 mg, isossorbida SL se dor. Manter losartana e metformina. Orientar retorno imediato ao PS se dor em repouso ou prolongada. Retorno em 3 semanas.'),
  (381, 117, 10, '2023-03-14 14:30', 'retorno', 'Fiz o teste da esteira e a cintilografia', 130, 78, 62, 75.4, 'Melhora parcial da angina, ainda tem dor 1x por semana ao subir ladeira. Teste ergométrico interrompido aos 5 METs por dor, com infradesnível de ST de 2 mm em V4-V6. Cintilografia de perfusão: isquemia leve (5% do VE) em parede anterolateral, FEVE 58%. Cateterismo realizado em seguida: lesão de 60% em DA média, 50% em Cx proximal, CD sem lesões, boa função ventricular. Lesões moderadas sem critérios de alto risco. Discutido em conjunto: tratamento clínico otimizado inicial.', 'Estratégia de tratamento clínico otimizado: aumentar metoprolol para 100 mg e associar anlodipino 5 mg. Meta de LDL < 55 mg/dL com atorvastatina 80 mg. Reabilitação cardíaca. Considerar ATC se angina persistir. Retorno em 6 meses.'),
  (382, 117, 1, '2023-09-19 14:10', 'retorno', 'Quase não sinto mais dor', 126, 74, 58, 73.8, 'Angina CCS I, apenas em esforços intensos. Frequentou reabilitação cardíaca duas vezes por semana, perdeu 1,6 kg. Usou isossorbida SL uma única vez em 6 meses. LDL 51 mg/dL. HbA1c 6,9%. FC 58 bpm em repouso, sem tontura ou fadiga. Leve edema de tornozelos relacionado ao anlodipino. Exame cardiovascular sem alterações. Prefere seguir sem procedimento invasivo.', 'Manter tratamento clínico otimizado. Se piorar, proceder ATC de DA. Manter clopidogrel como alternativa ao AAS. Reavaliação funcional com teste ergométrico em 1 ano. Retorno em 6 meses.');
