insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (117, '2023-09-19', 'estavel', 'Doença coronariana multiarterial moderada (DA 60%, Cx 50%) com angina estável tratada clinicamente. Alergia a AAS levou ao uso de clopidogrel. Angina CCS I, LDL 51 mg/dL, em reabilitação. Segue sem procedimento invasivo por escolha compartilhada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (118, 'Aparecida Rosa Teodoro', 'F', '1949-06-03', 'Patos de Minas', 'MG', 'Aposentada', 'HAS há 35 anos, obesidade, DM2 há 8 anos, DRC estágio 3a. Usa anlodipino 5 mg, losartana 100 mg, furosemida 40 mg e metformina. Mora sozinha, com filha vizinha que ajuda. Come bastante embutidos e feijão tropeiro.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (383, 118, 11, '2022-10-18 09:20', 'consulta', 'Inchaço nas pernas e cansaço pra caminhar', 152, 84, 80, 91.5, 'Paciente de 73 anos com dispneia aos médios esforços e edema bilateral de MMII há 6 semanas, ortopneia com 2 travesseiros. Exame: PA 152x84, RCR 2T B4, estertores finos em bases, turgência jugular a 45°, edema 2+/4+ bilateral. ECO: FEVE 60%, HVE concêntrica moderada, disfunção diastólica grau II, átrio esquerdo 44 mm, PSAP 42 mmHg. NT-proBNP 1.580 pg/mL. Creatinina 1,4. ICFEp, provável cardiopatia hipertensiva e obesidade.', 'Dapagliflozina 10 mg/dia, espironolactona 25 mg/dia, furosemida 40 mg mantida. Manter losartana e anlodipino, vigiar potássio e creatinina em 2 semanas. Dieta com menos sal e embutidos, peso diário. Retorno em 4 semanas.'),
  (384, 118, 6, '2023-01-09 05:20', 'pronto_socorro', 'Acordei sem ar de madrugada', 196, 104, 108, 94.0, 'Pcte 73a, ICFEp, acordou com dispneia intensa, tosse com secreção rosácea, sentada na cama. Houve festa de fim de ano com muito sal e parou a espironolactona por conta própria (‘a filha disse que tinha potássio demais’). SpO2 86% em ar ambiente, taquipneica, estertores até campos médios, B3 ausente, edema 3+/4+. PA 196x104. ECG: taquicardia sinusal, sem isquemia aguda. Raio X com congestão e derrame bilateral. Troponina negativa. HD: EAP hipertensivo (ICFEp descompensada), por transgressão de sal e suspensão de medicação.', 'O2 por máscara, furosemida 80 mg EV, nitroglicerina EV, posição sentada. Resposta em 2 horas, SpO2 95%, PA 148x82. Internação breve para diurese. Retomar espironolactona após orientação sobre monitorização do potássio.'),
  (385, 118, 11, '2023-02-13 09:40', 'retorno', 'Voltei a respirar bem', 134, 76, 70, 88.2, 'Peso seco atingido em 88 kg após perda de 5,8 kg desde o PS. Sem ortopneia, sem edema, dispneia só em grandes esforços. A filha agora separa os remédios semanalmente e confere o sal da comida. NT-proBNP 620 pg/mL. K 4,8, creatinina 1,3. PA 134x76 mmHg. Exame: estertores ausentes, jugulares normais, sem edema.', 'Furosemida reduzida para 40 mg/dia. Manter dapagliflozina, espironolactona, losartana e anlodipino. Orientado a pesar-se diariamente, e procurar a clínica se aumentar 2 kg em 3 dias. Exames em 3 meses. Retorno em 3 meses.');
