insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (118, '2023-02-13', 'estavel', 'ICFEp hipertensiva com um episódio de EAP após excesso de sal e suspensão da espironolactona. Recompensada, peso seco 88 kg, NT-proBNP 620 pg/mL, PA 134x76 mmHg. Filha assumiu a organização dos medicamentos; segue em acompanhamento trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (119, 'Valdemar Costa e Silva', 'M', '1948-01-19', 'Pelotas', 'RS', 'Aposentado (agricultor)', 'HAS há 25 anos, DM2 há 10 anos, ex-tabagista. FA descoberta em exame de rotina. Toma losartana 100 mg e metformina 850 mg 12/12h. Desconfiado de remédios que ‘afinam o sangue’ porque um cunhado teve hemorragia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (386, 119, 4, '2021-05-04 10:40', 'consulta', 'Médico do posto disse que meu coração está irregular', 146, 88, 92, 79.0, 'Paciente de 73 anos, FA persistente detectada em ECG do posto, assintomático salvo leve cansaço ao esforço. Exame: ritmo irregular, FC 92, sem sopros, MV+ sem RA, sem edemas. ECO: átrio esquerdo 49 mm, FEVE 55%, sem estenose mitral. CHA2DS2-VASc 3 (idade 65-74, HAS, DM). Expliquei o risco de AVC cardioembólico e a indicação de anticoagulação oral, mas ele resiste: ‘não quero tomar veneno de rato, quem toma sangra’. HAS-BLED 2.', 'Proposto rivaroxabana 20 mg com jantar, paciente recusa. Aceita apenas AAS 100 mg e betabloqueador. Documentada recusa informada e orientados sinais de AVC. Metoprolol succinato 50 mg/dia. Retorno em 30 dias para reavaliar a decisão com a esposa.'),
  (387, 119, 6, '2021-11-27 06:15', 'pronto_socorro', 'Acordei com a boca torta e o braço direito sem força', 182, 98, 104, 79.0, 'Pcte 73a, FA sem anticoagulação (recusou), encontrado ao acordar com desvio de rima à direita, plegia braço direito e afasia, última vez visto bem às 22h do dia anterior (fora da janela de trombólise). NIHSS 14. Glicemia 168. TC de crânio sem sangramento, sinais precoces de isquemia em território de ACM esquerda (ASPECTS 7). Angio-TC com oclusão do ramo M1 da ACM esquerda. ECG: FA com resposta ventricular de 104.', 'Fora de janela para trombólise. Encaminhado à neurologia para avaliação de trombectomia mecânica (disponível, dentro de 24h com perfusão favorável). Suspender anti-hipertensivos nas primeiras horas, permissividade da PA até 220x120 mmHg. AAS 300 mg após exclusão de hemorragia.'),
  (388, 119, 13, '2022-03-08 11:00', 'retorno', 'Não mexo bem o braço e a fala é difícil', 138, 84, 76, 73.5, 'Quatro meses após AVC cardioembólico de ACM esquerda, submetido à trombectomia mecânica com recanalização parcial (TICI 2b). Sequelas: hemiparesia direita braquiocrural grau IV com predomínio braquial, afasia de expressão moderada, Rankin 3. Em fisioterapia, fonoaudiologia e terapia ocupacional. Agora convencido pela experiência: ‘aceito tomar o remédio do sangue’. Peso caiu por disfagia inicial. Sem sangramentos. Humor deprimido, em acompanhamento.', 'Iniciar rivaroxabana 20 mg com o jantar (Clcr 68) e suspender AAS. Manter estatina de alta intensidade: atorvastatina 40 mg. Seguir reabilitação neuromotora. Sertralina 50 mg para depressão pós-AVC. Retorno em 2 meses.');
