insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (119, '2022-03-08', 'piorou', 'FA sem anticoagulação por recusa do paciente evoluiu com AVC isquêmico cardioembólico (oclusão de M1 esquerda), deixando hemiparesia direita, afasia moderada e Rankin 3. Iniciada rivaroxabana tardiamente, em reabilitação multiprofissional.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (120, 'Tatiane Bernardes Lacerda', 'F', '1992-04-27', 'Poços de Caldas', 'MG', 'Enfermeira', 'Hígida. Episódios de palpitações súbitas desde os 20 anos, com início e término abruptos, duração de alguns minutos, piores após café e plantões noturnos. Nega medicamentos contínuos. Usa DIU de cobre.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (389, 120, 6, '2023-06-19 03:50', 'pronto_socorro', 'Coração disparou no plantão e não parou', 104, 66, 188, 58.0, 'Pcte 31a, enfermeira, palpitações súbitas há 40 min com tontura leve e desconforto torácico, sem síncope. Exame: ansiosa, pálida, FC 188 regular, PA 104x66, MV+ sem RA, sem sopros audíveis na taquicardia. ECG: taquicardia de QRS estreito regular, RR fixo, sem onda P visível, FC 188. HD: TSV (provável reentrada nodal). Manobra de Valsalva modificada sem reversão.', 'Adenosina 6 mg EV em bolus rápido sem reversão; 12 mg EV, com reversão para ritmo sinusal a 82 bpm. ECG pós sem pré-excitação. Observação por 2 horas, alta sem medicamentos. Orientada a procurar ambulatório de arritmias. Evitar excesso de cafeína.'),
  (390, 120, 4, '2023-07-10 14:00', 'consulta', 'Quero resolver de vez essas crises', 110, 68, 72, 58.2, 'Nega novos episódios desde o PS. Nos últimos 4 meses teve mais 3 crises, uma delas abortada com manobra vagal. ECG de repouso normal, sem pré-excitação. ECO sem alterações estruturais, FEVE 65%. TSH normal. Holter de 24h sem arritmias. História típica de taquicardia por reentrada nodal. A paciente recusa uso contínuo de medicação porque quer engravidar em 1 ano e prefere tratamento definitivo.', 'Indicado estudo eletrofisiológico com ablação por radiofrequência. Orientada quanto a risco de BAV (menos de 1%) e sucesso acima de 95%. Manobras vagais se nova crise. Agendamento da ablação. Retorno após o procedimento.'),
  (391, 120, 4, '2023-09-05 07:30', 'internacao', 'Estudo eletrofisiológico e ablação', 112, 70, 70, 58.0, 'Estudo eletrofisiológico sob sedação: indução de TSV por reentrada nodal tipo comum (slow-fast), ciclo 320 ms, com jump AH de 70 ms. Ablação por radiofrequência da via lenta com 3 aplicações, sem PR prolongado nem BAV, e não indutibilidade final mesmo com isoproterenol. Sem complicações no acesso femoral. Alta no mesmo dia, ECG com PR 150 ms.', 'Repouso relativo 48 horas, evitar esforço físico por 1 semana. Curativo em virilha. Sem medicações contínuas. Retorno em 30 dias com ECG.'),
  (392, 120, 4, '2023-10-17 14:30', 'retorno', 'Nenhuma crise desde a ablação', 108, 66, 68, 58.6, 'Sem palpitações em 6 semanas, voltou aos plantões noturnos sem sintomas. Local da punção sem hematoma. Exame: RCR 2T BNF, sem sopros. ECG com ritmo sinusal, PR 148 ms, sem onda delta. Holter de 24h normal. Feliz por poder planejar a gestação. Orientada a manter café com moderação.', 'Alta do ambulatório de arritmias. Retornar se palpitações recorrentes. Liberada para gestação do ponto de vista cardiológico, com avaliação pré-concepcional rotineira. Sem medicações.');
