insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (120, '2023-10-17', 'melhorou', 'Taquicardia por reentrada nodal revertida com adenosina no PS e curada com ablação por radiofrequência da via lenta. Sem recorrência em 6 semanas, sem medicação, alta do ambulatório de arritmias e liberada para planejar gestação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (121, 'Ivone Celestino Barbosa', 'F', '1939-12-11', 'Cataguases', 'MG', 'Aposentada (ex-tecelã)', 'HAS há 40 anos, osteoporose e catarata operada. Em uso de losartana 50 mg 12/12h, anlodipino 10 mg e clortalidona 25 mg. Duas quedas nos últimos 3 meses, uma com fratura de punho. Mora com a neta, que cuida dos remédios.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (393, 121, 3, '2022-03-03 09:10', 'consulta', 'Caí duas vezes quando levantei da cama', 158, 78, 72, 55.0, 'Paciente de 82 anos, trazida pela neta após duas quedas ao levantar, com tontura e escurecimento visual de poucos segundos, sem perda de consciência prolongada, sem dor torácica ou palpitações. Sentada a PA é 158x78, mas em pé após 3 minutos cai para 114x62 mmHg (queda de 44 mmHg na sistólica), com sintomas. Exame: frágil, RCR 2T BNF, sem sopros, MV+ sem RA, sem edemas, desidratada leve. Na, 134 mEq/L. Hipotensão ortostática por excesso de anti-hipertensivos e diurético.', 'Suspender clortalidona (hiponatremia e desidratação). Reduzir anlodipino para 5 mg. Manter losartana. Orientar hidratação, levantar em etapas, meias elásticas. Evitar metas rígidas em idosa frágil. Retorno em 3 semanas para nova medida em pé.'),
  (394, 121, 1, '2022-04-14 10:00', 'retorno', 'Não caí mais, mas ainda fico tonta quando levanto', 146, 74, 70, 55.4, 'Sem novas quedas. Tontura postural persiste em menor grau. Sentada 146x74, em pé aos 3 minutos 130x70 mmHg, queda de 16 mmHg, assintomática. Na 139 mEq/L, creatinina 1,0. ECG com ritmo sinusal, bloqueio de ramo direito antigo. Holter 24h descartou bradiarritmias. ECO com FEVE 66%, HVE leve. Hipotensão ortostática melhorou ao tirar o diurético. Aceita que a PA fique um pouco mais alta que o ideal para evitar nova fratura.', 'Meta individualizada de PAS 130-150 mmHg sentada. Manter losartana 50 mg 12/12h e anlodipino 5 mg. Fisioterapia para equilíbrio e ajuste do ambiente doméstico. Vitamina D. Retorno em 6 meses.'),
  (395, 121, 1, '2022-10-06 09:30', 'retorno', 'Estou firme, sem cair', 140, 72, 68, 56.2, 'Seis meses sem quedas, caminha com andador no quintal, fez fisioterapia com ganho de equilíbrio. Sem tontura ao se levantar; PA sentada 140x72, em pé 136x70. Ganhou 1 kg. Neta reforça controle da água e do café da manhã reforçado. Sódio 140, creatinina 1,0. Exame sem alterações, sem edemas.', 'Manter losartana e anlodipino nas doses atuais. Monitorar PA em pé a cada consulta. Não intensificar o tratamento. Retorno em 6 meses.');
