insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (121, '2022-10-06', 'controlado', 'Idosa de 82 anos com hipotensão ortostática e quedas por excesso de anti-hipertensivos. Com retirada da clortalidona e redução do anlodipino, passou 6 meses sem quedas, PA sentada 140x72 mmHg e sem queda postural, dentro da meta individualizada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (122, 'Sebastião Lúcio Ramos', 'M', '1966-08-02', 'Teófilo Otoni', 'MG', 'Motorista de ônibus', 'HAS descoberta em exame admissional de renovação da carteira. Tabagista 25 maços-ano, sedentário. Pai hipertenso. Sem outras doenças conhecidas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (396, 122, 5, '2020-09-15 07:50', 'consulta', 'A pressão deu alta no exame da empresa', 164, 100, 78, 88.0, 'Paciente de 54 anos, assintomático, motorista de ônibus intermunicipal com jornada de 12 horas. PA 164x100 em duas medidas. Exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, sem edemas. IMC 29,8. Creatinina 0,9 mg/dL, potássio 4,2, glicemia de jejum 96, colesterol total 234. Hipertensão estágio 2. Explicado sobre risco de complicações e importância de manter o uso diário.', 'Iniciar enalapril 10 mg 12/12h. Orientar redução do sal, parar de fumar com apoio da UBS. Exames e ECG de rotina. Retorno em 30 dias.'),
  (397, 122, 5, '2020-10-27 08:00', 'retorno', 'Uma tosse seca que não passa, me incomoda a noite toda', 144, 90, 80, 88.4, 'Retorna com tosse seca, irritativa, sem expectoração ou febre, iniciada cerca de 2 semanas após o início do enalapril, pior ao deitar. Quase não consegue dormir. Fuma 10 cigarros por dia (reduziu). Ausculta pulmonar limpa, sem sibilos, sem sinais de IC. Raio X de tórax sem alterações. Tosse compatível com efeito do IECA. PA 144x90 com adesão boa. Explicado que a tosse é frequente e não perigosa, mas justifica troca.', 'Suspender enalapril e iniciar losartana 50 mg 12/12h. Tosse deve melhorar em 1 a 4 semanas. Reforçar cessação do tabagismo. Retorno em 30 dias.'),
  (398, 122, 5, '2021-02-09 07:50', 'retorno', 'A tosse sumiu, mas a pressão ainda está alta', 152, 94, 76, 87.0, 'Tosse resolvida em 3 semanas após a troca do enalapril por losartana, sem recorrência. Trabalhando em escala de madrugada, e confessa que esquece o comprimido da noite com frequência. PA 152x94 mmHg, ainda acima da meta. Reduziu o cigarro para 5 por dia. Exame sem alterações. Mantém boa relação com a UBS e não gosta de faltar ao serviço para consultar.', 'Aumentar para losartana 100 mg em dose única pela manhã, para facilitar a adesão, e associar hidroclorotiazida 25 mg. Recomendado MRPA. Retorno em 6 semanas com exames. Orientado novamente sobre risco de abandonar.');
