insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (122, '2021-09-30', 'abandonou', 'Hipertensão estágio 2 em motorista de ônibus. Tosse por enalapril resolvida com a troca por losartana, mas a PA seguia acima da meta. Faltou ao retorno agendado e não foi mais localizado após três tentativas de contato; perda de seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (123, 'Bruna Eduarda Salgado Vieira', 'F', '1998-05-20', 'Itabira', 'MG', 'Estudante de enfermagem', 'Hipertensão diagnosticada há 1 ano, em uso de anlodipino 10 mg e bisoprolol 5 mg sem controle. Sem história familiar de hipertensão. Anticoncepcional oral com drospirenona, suspenso por indicação clínica. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (399, 123, 2, '2022-07-12 15:00', 'consulta', 'Pressão alta aos 24 anos, ninguém na família tem', 172, 108, 66, 58.0, 'Mulher jovem, magra, com hipertensão estágio 2 de início precoce, sem história familiar, com resposta insuficiente a duas drogas. Cefaleia pulsátil e zumbido ocasional. Exame: sopro sistólico em flanco direito (epigástrio), pulsos simétricos, sem diferença entre braços e pernas, sem sinais de Cushing. Creatinina 0,8, K 4,0. Rastreio de causas secundárias: aldosterona/renina normais, metanefrinas normais. Suspeita de hipertensão renovascular, possível displasia fibromuscular.', 'Solicitar Doppler de artérias renais e angiotomografia de artérias renais e carótidas. Manter anlodipino e bisoprolol. Evitar IECA/BRA até esclarecimento. Retorno com os exames em 3 semanas.'),
  (400, 123, 8, '2022-08-09 14:30', 'retorno', 'Vim ver o resultado do exame das artérias do rim', 168, 104, 62, 57.6, 'Doppler: velocidade de pico sistólico 310 cm/s em artéria renal direita (média/distal), rim direito 9,2 cm e esquerdo 11,0 cm. Angiotomografia: aspecto em ‘colar de contas’ na porção média e distal da renal direita com estenose de cerca de 70%, esquerda normal, carótidas e ilíacas normais. Compatível com displasia fibromuscular multifocal. Renina plasmática elevada (4,8 ng/mL/h). Rim direito menor, função preservada.', 'Indicada angioplastia com balão da artéria renal direita (sem stent, padrão na displasia fibromuscular). Iniciar AAS 100 mg. Aconselhada contracepção não hormonal (DIU de cobre) e avaliação pré-gestacional. Encaminhada à hemodinâmica.'),
  (401, 123, 10, '2022-09-20 08:00', 'internacao', 'Angioplastia de artéria renal', 150, 92, 64, 57.8, 'Arteriografia renal confirma displasia fibromuscular multifocal com estenose de 72% e gradiente translesional de 28 mmHg na renal direita. Realizada angioplastia por balão (4,5 x 20 mm) com bom resultado angiográfico, estenose residual < 20% e gradiente de 4 mmHg, sem dissecção. Acesso femoral sem intercorrência. Pós-procedimento com PA 128x78 mmHg, creatinina 0,8 e sem hematoma. Alta em 24 horas.', 'AAS 100 mg contínuo, manter anlodipino e reduzir bisoprolol para 2,5 mg. Doppler de controle em 3 meses. Medidas diárias da PA em casa e retorno em 8 semanas.'),
  (402, 123, 2, '2022-11-15 15:20', 'retorno', 'Pressão normalizou, queria saber se posso parar os remédios', 116, 72, 70, 58.4, 'Dois meses após a angioplastia, sem cefaleia ou zumbido. MRPA com média de 114x70 mmHg. Doppler de controle com velocidade de pico de 140 cm/s na renal direita, sem reestenose, rim direito com 9,6 cm. Creatinina 0,8, renina plasmática normalizada. Usando DIU de cobre. Exame: sopro abdominal desapareceu, PA 116x72. Evoluiu com PA normal, havendo possibilidade de retirar a medicação.', 'Suspender bisoprolol e reduzir anlodipino para 5 mg por 4 semanas e depois suspender se PA < 125x80. Manter AAS 100 mg por 1 ano. Doppler em 6 e 12 meses. Retorno em 3 meses.');
