insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (123, '2022-11-15', 'melhorou', 'Hipertensão renovascular por displasia fibromuscular da artéria renal direita, tratada com angioplastia por balão sem stent. PA normalizou para 116x72 mmHg com redução progressiva da medicação; sem reestenose ao Doppler. Aguarda possível suspensão total dos anti-hipertensivos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (124, 'Daiane Cristina Moreira Silveira', 'F', '1994-02-17', 'Divinópolis', 'MG', 'Atendente de loja', 'Primigesta, gestação de 34 semanas, sem hipertensão prévia. Pré-natal irregular (4 consultas), obesidade (IMC 33 antes da gestação). Mãe com pré-eclâmpsia na gravidez. Sem outras doenças.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (403, 124, 7, '2025-03-18 10:30', 'consulta', 'Dor de cabeça e pés muito inchados', 146, 94, 88, 91.0, 'Gestante de 31 anos, IG 32 semanas e 2 dias, primigesta, com cefaleia leve e edema de pés e mãos há 1 semana, ganho de 3 kg em 2 semanas. PA 146x94 mmHg em duas medidas com 15 minutos de intervalo; antes, PA sempre < 130x80. Altura uterina compatível, BCF 142 bpm, movimentação fetal presente. Fita urinária: proteinúria 2+. Plaquetas 168.000, creatinina 0,7, AST 28. Hipertensão gestacional com proteinúria, pré-eclâmpsia sem sinais de gravidade neste momento.', 'Iniciar metildopa 500 mg 8/8h e nifedipino retard 20 mg 12/12h. Proteinúria de 24h, hemograma, enzimas hepáticas, LDH e USG com Doppler. Repouso relativo, orientados sinais de alarme (dor epigástrica, escotomas, convulsão). Retorno em 7 dias, ou antes se sintomas.'),
  (404, 124, 7, '2025-04-02 02:15', 'internacao', 'Dor forte na boca do estômago e enjoo', 178, 114, 102, 93.4, 'Gestante com IG 34 semanas e 1 dia, trazida ao PS obstétrico com dor epigástrica intensa em barra e vômitos há 6 horas, cefaleia e escotomas. Não retornou ao pré-natal após a primeira consulta. PA 178x114, reflexos vivos, clônus ausente. Exames: plaquetas 72.000, AST 214 U/L, ALT 168 U/L, LDH 860 U/L, bilirrubina indireta 2,1, haptoglobina baixa, esfregaço com esquizócitos, creatinina 1,2, proteinúria de 24h 4,8 g. Síndrome HELLP, pré-eclâmpsia grave. BCF 128 bpm, USG com oligoâmnio leve.', 'Sulfato de magnésio (4 g ataque, 1 g/h), hidralazina 5 mg EV em bolus para PAS acima de 160 e dexametasona 6 mg 12/12h para maturação pulmonar e plaquetas. Indicado parto: cesárea de urgência após estabilização em 4 horas. Reserva de concentrado de plaquetas. Informado o risco materno-fetal.'),
  (405, 124, 14, '2025-04-03 08:00', 'internacao', 'Pós-operatório de cesárea em UTI', 152, 96, 92, 88.0, 'UTI materna, D1 de cesárea de urgência por HELLP, recém-nascido masculino 2.150 g, Apgar 8/9, encaminhado à UTI neonatal. Sangramento controlado, sem hematoma de ferida ou de útero hipotônico, uso de plaquetas não necessário (nadir 61.000). Em magnésio por 24h, reflexos patelares presentes, diurese 70 mL/h. Hoje plaquetas 98.000, AST 142, LDH 520, creatinina 1,0. PA 152x96 mmHg. Sem convulsão, sem edema pulmonar. Em melhora laboratorial.', 'Completar sulfato de magnésio por 24h após o parto, manter nifedipino retard 20 mg 12/12h. Controle laboratorial a cada 12 horas. Alta da UTI para enfermaria quando plaquetas > 100.000. Estimular amamentação e contato com o bebê.'),
  (406, 124, 1, '2025-05-20 14:00', 'retorno', 'Consulta de puerpério, quero saber da pressão', 134, 86, 78, 79.0, 'Seis semanas de puerpério, amamentando. Alta hospitalar no 6º dia. Bebê com 2.600 g, saudável. Sem cefaleia ou edema. Plaquetas normalizadas (244.000), AST 24, LDH 190, creatinina 0,8, proteinúria de 24h 160 mg. PA 134x86 mmHg com nifedipino retard 20 mg 12/12h. Explicado que HELLP aumenta o risco de pré-eclâmpsia em nova gestação e de hipertensão e doença cardiovascular futuras. Perdeu 12 kg.', 'Trocar nifedipino por enalapril 10 mg 12/12h, compatível com amamentação. Monitorar PA com MRPA. Aspirina 100 mg em futura gestação a partir de 12 semanas. Retorno em 3 meses e avaliação anual do risco cardiovascular.');
