insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (124, '2025-05-20', 'melhorou', 'Pré-eclâmpsia que evoluiu para síndrome HELLP aos 34 semanas, tratada com sulfato de magnésio, anti-hipertensivos e cesárea de urgência. Plaquetas e enzimas hepáticas normalizadas, recém-nascido saudável. Mantém enalapril no puerpério e segue em acompanhamento cardiovascular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (125, 'Luiz Gonzaga Pimentel Neto', 'M', '1957-03-06', 'Vespasiano', 'MG', 'Aposentado (ex-bancário)', 'HAS há 22 anos, DM2 há 15 anos com HbA1c oscilante, dislipidemia, ex-tabagista (parou há 20 anos), obesidade. Usa losartana 50 mg 12/12h, metformina, glimepirida e sinvastatina 20 mg. Pai e irmão com DAC precoce.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (407, 125, 1, '2021-07-13 08:30', 'consulta', 'Dor no peito com pouco esforço, até pra tomar banho', 144, 84, 82, 97.0, 'Paciente de 64 anos, diabético, com angina em crescendo há 3 meses, hoje CCS III (dor ao tomar banho e vestir-se). Sem dor em repouso. Exame: PA 144x84, RCR 2T BNF, sem sopros, MV+ sem RA, edema ausente. ECG: ondas T negativas em parede anterior. LDL 142 em uso de sinvastatina. HbA1c 8,6%. Cateterismo (solicitado e realizado nesta semana): lesão de 90% em tronco de coronária esquerda distal, 80% em DA proximal, 90% em Cx e 70% em CD. Escore SYNTAX alto (38). FEVE 52%.', 'Doença triarterial com tronco, diabético: indicação de revascularização miocárdica cirúrgica. AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg. Encaminhar à cirurgia cardiovascular. Evitar esforço até a cirurgia.'),
  (408, 125, 12, '2021-08-24 07:00', 'internacao', 'Cirurgia de revascularização do miocárdio', 136, 80, 70, 96.0, 'Realizada revascularização miocárdica com circulação extracorpórea: enxerto de artéria torácica interna esquerda para DA, e safena para Cx (ramo marginal) e CD (descendente posterior). Tempo de CEC 98 minutos, sem intercorrências intraoperatórias. Pós-operatório em UTI com extubação em 6 horas, drenos retirados em 48 horas, fibrilação atrial transitória no 2º dia com reversão com amiodarona. Alta hospitalar no 8º dia, ferida limpa, esterno estável.', 'AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg. Insulinização temporária para controle glicêmico durante a internação. Cuidados com o esterno, fisioterapia respiratória. Reabilitação cardíaca. Retorno em 6 semanas.'),
  (409, 125, 12, '2021-10-05 09:00', 'retorno', 'Estou bem, só um repuxo na cicatriz', 128, 76, 64, 92.4, 'Seis semanas de pós-operatório, ferida esternal e de safena cicatrizadas, sem sinais de infecção. Sem angina e sem dispneia, caminhando 30 minutos por dia. Perdeu 3,6 kg. Exame: esterno estável, RCR 2T BNF, MV+ sem RA, sem edemas em MMII. LDL 66 mg/dL, HbA1c 7,4%. Dor muscular leve nas coxas, aventando relação com estatina.', 'Iniciar reabilitação cardíaca. Manter dupla de prevenção secundária e controle glicêmico. Dosar CPK. Alta cirúrgica, seguimento com cardiologia clínica. Retorno em 4 meses.'),
  (410, 125, 1, '2023-02-21 08:40', 'retorno', 'A dor voltou e estou com falta de ar de novo', 150, 90, 88, 99.5, 'Quase 18 meses depois, retorna após abandonar reabilitação e parar o metoprolol (‘cansava’). Recuperou o peso e parou a estatina por dor muscular. Angina CCS III há 2 meses e dispneia aos médios esforços com ortopneia 2 travesseiros. Exame: estertores nas bases, edema 1+/4+. ECO: FEVE 38%, acinesia anterior. Cintilografia: isquemia extensa. Cateterismo: enxertos de safena para Cx e CD ocluídos, ponte mamária pérvia, DA com boa fluxo. Progressão da DAC e IC isquêmica.', 'Reintroduzir metoprolol succinato 50 mg, trocar atorvastatina por rosuvastatina 20 mg + ezetimiba 10 mg por intolerância. Iniciar sacubitril/valsartana 24/26 mg 12/12h (parar losartana), espironolactona 25 mg, dapagliflozina 10 mg, e AAS. Discutido ATC de lesões nativas em Heart Team. Retorno em 3 semanas.');
