insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (125, '2023-02-21', 'piorou', 'Após revascularização miocárdica bem-sucedida, abandonou reabilitação e medicações, com oclusão de dois enxertos de safena, angina recorrente e insuficiência cardíaca isquêmica (FEVE 38%). Iniciada terapia otimizada e avaliação de ATC.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (126, 'Dirce Helena Zanetti Bragança', 'F', '1953-09-14', 'Varginha', 'MG', 'Aposentada (ex-comerciante)', 'HAS há 30 anos, IAM prévio em 2016 tratado com ATC de DA, ICFEr isquêmica (FEVE 33%), DRC estágio 3b. Usa carvedilol 12,5 mg 12/12h, sacubitril/valsartana 49/51 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg, furosemida 40 mg, AAS e rosuvastatina. Mora sozinha.', 'Alergia a iodo (contraste, reação cutânea)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (411, 126, 11, '2024-01-23 10:20', 'retorno', 'Controle da insuficiência cardíaca', 114, 68, 62, 66.0, 'Paciente de 70 anos em ICFEr isquêmica, NYHA II, estável. Sem ortopneia ou DPN, edema ausente. Peso seco 66 kg. PA 114x68, FC 62. Exame: BEG, RCR 2T B3 ausente, MV+ sem RA, jugulares normais. NT-proBNP 780 pg/mL, K 4,9, creatinina 1,5 (TFGe 36). Boa adesão, usa pílulas organizadas pela filha, que visita semanalmente. Última internação por IC foi há 14 meses.', 'Manter os quatro pilares nas mesmas doses. Orientar vacina contra influenza e pneumocócica. Monitorar K e creatinina em 3 meses. Retorno em 4 meses.'),
  (412, 126, 11, '2024-05-06 04:30', 'internacao', 'Falta de ar e inchaço, piorou depois de uma gripe', 102, 60, 98, 71.5, 'Internada com ICFEr descompensada após pneumonia comunitária tratada em casa, com ganho de 5,5 kg em 10 dias, ortopneia, dispneia em repouso, edema 3+/4+ até coxas. Exame: taquipneica, sat 90%, estertores até ápices, jugulares ingurgitadas, extremidades quentes (perfil B, quente e úmido). Raio X com congestão e derrame à direita. NT-proBNP 6.900, K 5,3, creatinina 2,0 (lesão renal aguda sobre DRC). Troponina estável, sem isquemia aguda no ECG.', 'Furosemida EV 80 mg 12/12h, suspensão temporária de espironolactona (K 5,3 e creatinina 2,0). Manter carvedilol (reduzir para 6,25 mg 12/12h por FC e PA) e dapagliflozina. Antibiótico por pneumonia: amoxicilina/clavulanato. Reintroduzir sacubitril/valsartana 24/26 mg quando creatinina melhorar.'),
  (413, 126, 11, '2024-06-04 10:30', 'retorno', 'Alta do hospital, vim reavaliar', 108, 64, 66, 66.4, 'Alta hospitalar após 9 dias, recuperou peso seco de 66,4 kg com diurese vigorosa. Pneumonia tratada, sem febre. Creatinina 1,5, K 4,7. Sem ortopneia, NYHA II. Filha agora a acompanha a todas as consultas e mora com ela temporariamente. Não vai mais para a rua sem agasalho, pois a gripe foi o gatilho. PA 108x64, FC 66. Exame sem estertores.', 'Reintroduzir sacubitril/valsartana 24/26 mg 12/12h (desde alta), espironolactona 12,5 mg/dia e depois 25 mg se K < 5,0. Manter carvedilol 6,25 mg 12/12h e dapagliflozina. Furosemida 40 mg/dia. K e creatinina em 1 semana. Vacinação. Retorno em 6 semanas.');
