insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (126, '2024-06-04', 'estavel', 'ICFEr isquêmica com DRC que descompensou após pneumonia, com lesão renal aguda transitória. Recompensada com diurético e reintrodução gradual dos pilares da terapia, peso seco 66,4 kg. Estável em NYHA II, com filha dando apoio na rotina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (127, 'Haroldo Eisenberg Lima', 'M', '1969-07-23', 'Belo Horizonte', 'MG', 'Engenheiro civil', 'HAS leve em uso de losartana 50 mg/dia. Roncador, sem diagnóstico de apneia. Corre 5 km três vezes por semana. Etilismo social intenso nos finais de semana. Sem diabetes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (414, 127, 6, '2022-10-02 10:10', 'pronto_socorro', 'Coração acelerado desde ontem à noite', 128, 80, 148, 86.0, 'Pcte 53a com palpitações regulares e cansaço desde a noite anterior, após churrasco com álcool. Sem síncope, sem dor torácica. Exame: ansioso, PA 128x80, FC 148 regular, MV+ sem RA, sem sopros, sem edemas. ECG: flutter atrial típico com condução 2:1, ondas F negativas em D2, D3, aVF (padrão de dente de serra), FC 148. Troponina negativa, TSH normal, K 4,2. Início há menos de 48h.', 'Metoprolol 5 mg EV e depois 50 mg VO, FC 98 bpm em condução 3:1/4:1 variável. Início de rivaroxabana 20 mg (CHA2DS2-VASc 1, mas ambulatorial até cardioversão eletiva). Alta, com agendamento em 3 semanas no ambulatório de arritmias.'),
  (415, 127, 4, '2022-10-24 09:00', 'consulta', 'Ainda sinto o coração batendo rápido e cansado', 126, 78, 96, 85.5, 'Segue em flutter atrial típico com condução variável, FC 96 bpm, com cansaço aos esforços e queda de rendimento na corrida. ECO: sem cardiopatia estrutural, FEVE 60%, átrio esquerdo 41 mm, sem trombo (ETT). Usando rivaroxabana há 22 dias sem falhas. Polissonografia solicitada pelo ronco: IAH 11/h (leve). Discutidas opções: cardioversão elétrica ou ablação do istmo cavotricúspide. Prefere tratamento definitivo.', 'Manter anticoagulante. Indicada ablação do istmo cavotricúspide eletiva. Ablação garante cardioversão no procedimento. Exame de sangue pré-procedimento. Orientado a reduzir álcool, principal gatilho. Internação programada em 6 semanas.'),
  (416, 127, 4, '2022-12-06 07:00', 'internacao', 'Ablação do flutter atrial', 124, 76, 88, 85.0, 'Estudo eletrofisiológico: flutter atrial típico anti-horário com ciclo de 240 ms. Realizada ablação linear do istmo cavotricúspide por radiofrequência, com reversão para ritmo sinusal durante as aplicações e bloqueio bidirecional confirmado. Sem complicações. Ecocardiograma de controle sem derrame pericárdico. Alta no mesmo dia com ritmo sinusal, FC 68.', 'Manter rivaroxabana por 4 semanas pós-ablação e depois reavaliar (CHA2DS2-VASc 1). Retomar atividades leves em 3 dias. Evitar álcool excessivo. Retorno em 8 semanas com ECG e Holter.'),
  (417, 127, 4, '2023-02-14 09:20', 'retorno', 'Voltei a correr e estou ótimo', 122, 76, 60, 83.0, 'Dois meses e meio após ablação, em ritmo sinusal, sem palpitações, correndo 6 km sem limitação. Holter de 7 dias: ritmo sinusal em 100% do tempo, sem episódios de flutter ou FA, algumas extrassístoles supraventriculares isoladas. Rivaroxabana suspensa após 4 semanas pelo baixo escore (CHA2DS2-VASc 1). Reduziu consumo de álcool aos fins de semana. PA 122x76.', 'Sem anticoagulante e sem antiarrítmico. Manter losartana. Alertar para a possibilidade de FA futura e procurar PS se palpitações. CPAP não indicado (IAH 11, assintomático). Retorno em 6 meses.');
