insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (127, '2023-02-14', 'melhorou', 'Flutter atrial típico tratado com ablação do istmo cavotricúspide, com bloqueio bidirecional e ritmo sinusal mantido. Holter de 7 dias sem recorrência. Sem anticoagulante nem antiarrítmico, retomou a corrida e reduziu o álcool.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (128, 'Ana Lúcia Pereira Gonçalves', 'F', '1962-10-05', 'Pirapora', 'MG', 'Lavradora', 'Doença de Chagas crônica (sorologia positiva em 2015), nasceu em casa de pau a pique. HAS leve. Mora em comunidade ribeirinha a 35 km da cidade, sem carro. Cinco filhos. Já foi tratada com benznidazol aos 40 anos, sem completar.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (418, 128, 11, '2020-11-10 09:40', 'consulta', 'Cansaço pra caminhar e pernas inchadas', 110, 70, 84, 55.0, 'Paciente de 58 anos com dispneia aos pequenos esforços (NYHA III), ortopneia e edema vespertino de MMII há 3 meses. Exame: emagrecida, jugulares ingurgitadas a 45°, RCR 2T com B3, sopro sistólico mitral 2+/6+, estertores em bases, hepatomegalia 3 cm, edema 2+/4+. ECG: BRD + BDAS, ESV frequentes. ECO: dilatação biventricular, FEVE 30%, aneurisma apical sem trombo. Holter: 3.200 ESV e TVNS de 5 batimentos. Cardiopatia chagásica crônica, forma dilatada.', 'Sem benznidazol (cardiopatia já estabelecida, sem benefício demonstrado). Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg e furosemida 40 mg. Sal restrito. Exames de eletrólitos em 2 semanas. Discutir CDI quando otimizada a terapia. Retorno em 6 semanas.'),
  (419, 128, 11, '2021-01-19 10:00', 'retorno', 'Melhorou um pouco do cansaço', 104, 66, 70, 52.2, 'Perda de 2,8 kg com diurese, edema desapareceu, dispneia NYHA II. Tosse seca discreta, tolerável. K 4,8, creatinina 0,9. Sem síncope ou palpitações. PA 104x66. Relata dificuldade de transporte (ônibus intermunicipal a cada 2 dias, 3 horas) e que o dinheiro da passagem pesa no orçamento. Sem sinais de congestão no exame, B3 ausente. Assistente social acionada para transporte pela prefeitura.', 'Aumentar carvedilol para 6,25 mg 12/12h e enalapril para 10 mg 12/12h. Manter espironolactona e reduzir furosemida para 20 mg. Entregar medicamentos para 3 meses. Agendar retorno junto ao transporte sanitário. K e creatinina em 2 semanas na UBS.'),
  (420, 128, 11, '2021-04-27 09:50', 'retorno', 'Cheguei de carona, foi difícil vir', 106, 68, 66, 53.0, 'Compensada, NYHA II, sem edema. Chegou de carona de vizinho e diz que não conseguiu mais passagem para as consultas do mês anterior. Nova ECO: FEVE 32%, sem trombo. Holter com TVNS curtas e ESV, sem TV sustentada. K 5,0, creatinina 1,0. Discutido indicação de CDI como prevenção primária: precisaria de vaga em centro de referência. Paciente hesita, pois teme operação e tem medo de ficar longe dos filhos.', 'Manter todas as medicações; sem alterações. Reiterada a importância do seguimento a cada 3 meses. Encaminhar solicitação de CDI para centro de referência em Belo Horizonte e orientar a procurar PS se síncope. Entregue receita para 4 meses.');
