insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (128, '2022-03-01', 'abandonou', 'Cardiopatia chagásica com ICFEr (FEVE 30-32%) e TVNS, sem seguimento desde abril de 2021 por dificuldade de transporte da zona rural e medo do CDI. Não compareceu a três retornos nem à marcação do centro de referência; sem contato.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (129, 'Lauro Ferreira Maciel', 'M', '1950-02-28', 'Barbacena', 'MG', 'Aposentado (ex-ferroviário)', 'HAS leve, ex-tabagista. Sopro cardíaco conhecido há 20 anos, sem acompanhamento. Cansaço progressivo há 1 ano. Em uso de enalapril 10 mg 12/12h. Mora com a esposa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (421, 129, 2, '2023-05-16 10:00', 'consulta', 'Falta de ar para andar e o coração disparando', 138, 70, 108, 74.0, 'Paciente de 73 anos com dispneia aos pequenos esforços (NYHA III) e palpitações irregulares há 2 meses. Exame: irregular, FC 108, sopro holossistólico 4+/6+ em foco mitral irradiado para axila, B3 presente, estertores em bases, edema 1+/4+. ECG: FA com resposta ventricular de 108. ECO: insuficiência mitral importante por prolapso do folheto posterior (flail P2), jato excêntrico, ERO 0,48 cm², volume regurgitante 70 mL, átrio esquerdo 56 mm, FEVE 54%, DSVE 41 mm, PSAP 52 mmHg.', 'Insuficiência mitral degenerativa grave sintomática e FA nova: indicação cirúrgica. Iniciar rivaroxabana 20 mg, metoprolol succinato 50 mg, furosemida 20 mg. ETE e cateterismo para planejamento. Encaminhar à avaliação com cirurgia cardiovascular.'),
  (422, 129, 2, '2023-06-27 09:30', 'retorno', 'Vim mostrar os exames', 130, 68, 82, 72.5, 'Melhor da dispneia com o diurético, NYHA II-III. FC 82 em FA. ETE: prolapso com ruptura de cordas em P2, anel mitral dilatado (38 mm), sem trombo em apêndice atrial esquerdo, anatomia favorável à plastia. Cateterismo: coronárias sem lesões obstrutivas. Creatinina 1,0. Discutido o caso com cirurgia cardiovascular: preferência por plastia mitral; serviço local não realiza plastia complexa. Casal aceita transferência.', 'Manter medicações. Encaminhar para cirurgia de plastia mitral em centro universitário de referência, com alta prioridade. Orientar sinais de piora (ortopneia, edema). Contato com a central de regulação.'),
  (423, 129, 12, '2023-08-15 11:00', 'retorno', 'Aguardando a vaga para a cirurgia', 126, 66, 78, 73.0, 'Avaliação cirúrgica: assintomático em repouso, NYHA II, estável com tratamento. Sem aumento do VE desde o último ECO (DSVE 41 mm, FEVE 53%). PSAP 48 mmHg. Risco cirúrgico baixo-moderado (EuroSCORE II 1,9%), plastia mitral com ablação cirúrgica da FA (Maze) bem indicada. Vaga confirmada em hospital universitário de referência em Belo Horizonte para outubro. Paciente e esposa esclarecidos sobre riscos e seguimento.', 'Transferência do acompanhamento ao serviço de referência para cirurgia de plastia mitral. Manter rivaroxabana, metoprolol, furosemida e enalapril até a internação. Relatório e exames enviados. Retorno em nosso serviço após alta cirúrgica, se necessário.');
