insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (129, '2023-08-15', 'transferido', 'Insuficiência mitral degenerativa grave (flail de P2) com FA nova, em NYHA II. Anatomia favorável à plastia, encaminhado para cirurgia com ablação cirúrgica da FA em hospital universitário de referência em Belo Horizonte, saindo do acompanhamento da clínica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (130, 'Rogério Tadeu Matsuda', 'M', '1987-12-09', 'Contagem', 'MG', 'Soldador', 'Usuário de crack e cocaína injetável intermitente nos últimos 3 anos, em recaída recente. Hepatite C não tratada. Sem cardiopatia conhecida. Mora com a mãe, que o levou ao hospital. Tabagista.', 'Alergia a sulfa (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (424, 130, 6, '2024-02-14 22:10', 'pronto_socorro', 'Febre há duas semanas, calafrios e tosse com sangue', 108, 64, 114, 61.0, 'Pcte 36a, usuário de drogas injetáveis, febre de 39,2°C há 14 dias, calafrios, sudorese noturna, dor pleurítica e tosse com escarro hemoptoico. Perdeu 6 kg. Exame: toxemiado, emagrecido, taquicárdico, sopro sistólico de insuficiência tricúspide 3+/6+ em borda esternal esquerda inferior, aumenta com inspiração, hepatomegalia dolorosa, múltiplas marcas de punção em antebraços. Raio X de tórax com múltiplos nódulos periféricos cavitados bilaterais (êmbolos sépticos). Leucócitos 18.400 com desvio, PCR 190.', 'Coletadas 3 amostras de hemocultura antes dos antibióticos. Iniciar vancomicina EV empiricamente (cobertura MRSA) e internação. ECO transtorácico e ETE. Contato com a infectologia e com o serviço de apoio ao usuário de drogas.'),
  (425, 130, 1, '2024-02-16 10:00', 'internacao', 'Resultado de hemocultura e ecocardiograma', 112, 68, 98, 61.0, 'Hemoculturas 3/3 positivas para Staphylococcus aureus sensível à oxacilina (MSSA). ETE: vegetação de 14 x 9 mm em folheto septal da valva tricúspide, insuficiência tricúspide moderada, valvas esquerdas normais, sem abscesso, FEVE 62%. TC de tórax com êmbolos sépticos pulmonares múltiplos. Endocardite infecciosa de valva tricúspide (câmaras direitas) por MSSA. Febre persistiu 72h, depois defervescência. Sorologias para HIV negativas.', 'Trocar vancomicina por oxacilina 2 g EV de 4/4h por 6 semanas (MSSA). Hemoculturas de controle a cada 48h até negativar. Dispensa de cirurgia no momento (vegetação < 20 mm, sem disfunção ventricular direita). Avaliação de saúde mental e programa de dependência química.'),
  (426, 130, 1, '2024-03-26 09:00', 'internacao', 'Fim do tratamento antibiótico em regime hospitalar', 118, 72, 76, 66.5, 'Concluídas 6 semanas de oxacilina em regime de internação, com acesso periférico, sem recidiva de febre. Hemoculturas de controle negativas desde o 4º dia. ETE de controle: vegetação reduzida a 6 mm, insuficiência tricúspide moderada, sem abscesso. PCR 8 mg/L, leucócitos 6.800. Cavitações pulmonares em regressão no Raio X. Ganhou 5,5 kg. Aderiu ao programa de redução de danos e recebeu alta para casa com acompanhamento ambulatorial.', 'Alta hospitalar. Vinculação ao CAPS-AD e à clínica da infectologia para tratamento da hepatite C. Aconselhamento a não reutilizar agulhas. Profilaxia antibiótica odontológica a partir de agora (endocardite prévia). Retorno em 8 semanas com ECO.'),
  (427, 130, 1, '2024-05-14 10:30', 'retorno', 'Estou limpo há dois meses e sem febre', 120, 74, 72, 70.2, 'Dois meses de alta, afebril, sem tosse, em seguimento no CAPS-AD e abstinente segundo ele e a mãe. Voltou a trabalhar parcialmente como soldador. Exame: BEG, sopro sistólico de IT 2+/6+, sem estigmas periféricos, MV+ sem RA, fígado palpável 1 cm. ECO: vegetação não identificada, insuficiência tricúspide moderada, câmaras direitas de dimensões normais, FEVE 63%. Hemograma e PCR normais. Hepatite C com carga viral detectável, em início de tratamento com antivirais.', 'Alta do tratamento da endocardite. ECO anual para vigiar a insuficiência tricúspide. Profilaxia odontológica sempre. Retornar se febre. Manter acompanhamento no CAPS-AD e na infectologia.');
