insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (130, '2024-05-14', 'melhorou', 'Endocardite de valva tricúspide por Staphylococcus aureus em usuário de drogas injetáveis, curada com 6 semanas de oxacilina, sem cirurgia. Sem vegetação ao ECO, insuficiência tricúspide moderada residual. Abstinente, em CAPS-AD e tratamento da hepatite C.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (131, 'Maurício Yoshida Brandão', 'M', '1990-04-18', 'São Paulo', 'SP', 'Analista de sistemas', 'Sem doenças crônicas. Trabalha em home office, 10 horas sentado, pede delivery quase todos os dias. Sedentário, bebe 3 a 4 energéticos por dia. Pai hipertenso desde os 45 anos. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (428, 131, 5, '2023-01-17 19:00', 'consulta', 'Vim fazer um check-up, a pressão estava um pouco alta no relógio', 134, 86, 84, 92.0, 'Paciente de 32 anos, assintomático, relógio inteligente alertando PA alta. MRPA de 4 dias com média de 132x84 mmHg. Consumo de energéticos e cafeína elevado, sal em excesso nos pedidos de delivery, sem atividade física. IMC 29,1, circunferência abdominal 98 cm. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, pulsos simétricos, sem edemas. Glicemia 92, LDL 138, creatinina 0,9, TSH normal. Pré-hipertensão com fator de risco familiar, sem indicação de remédio.', 'Tratamento apenas com MEV: cortar energéticos, reduzir sal e ultraprocessados, 150 min/semana de atividade física, meta de perder 5 kg. MRPA mensal. Retorno em 3 meses.'),
  (429, 131, 5, '2023-04-25 19:20', 'retorno', 'Mudei a rotina, quero ver se funcionou', 124, 80, 74, 87.4, 'Parou os energéticos e o refrigerante, caminha 40 minutos 4x por semana, usa pouco sal nas marmitas que passou a preparar aos domingos. Perdeu 4,6 kg em 3 meses. PA 124x80, MRPA 122x78 mmHg, sem queixas. Exame cardiovascular normal. FC 74 bpm, circunferência abdominal 92 cm. Orgulhoso do resultado. Sem necessidade de medicação.', 'Manter MEV e meta de mais 3 kg. MRPA a cada 3 meses. Retorno em 6 meses ou antes se PA > 140x90 em casa. Lipidograma e glicemia anuais.');
