insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (131, '2023-12-15', 'abandonou', 'Pré-hipertensão tratada só com mudança de estilo de vida, com PA normalizada e perda de 4,6 kg. Não compareceu ao retorno de 6 meses, nem respondeu às mensagens de lembrete; seguimento perdido apesar da evolução favorável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (132, 'Francielle Oliveira Santana', 'F', '1996-10-08', 'Feira de Santana', 'BA', 'Manicure', 'Primigesta, 37 semanas, sem comorbidades prévias, mas com obesidade (IMC 34). Pré-natal com 5 consultas em UBS. PA de 138x88 na última consulta, orientada a repetir em 1 semana. Mãe e irmã tiveram pré-eclâmpsia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (430, 132, 7, '2025-06-10 09:00', 'consulta', 'Inchaço no rosto e dor de cabeça desde ontem', 150, 98, 90, 92.0, 'Gestante de 28 anos, IG 36 semanas e 1 dia, queixa-se de cefaleia frontal e edema facial há 1 dia. Ganhou 2 kg na última semana. PA 150x98 mmHg confirmada após repouso. Exame: edema facial e de MMII 2+/4+, reflexos vivos, sem epigastralgia, sem visão turva. BCF 144, movimentos fetais presentes. Fita urinária com proteína 1+. Exames laboratoriais colhidos: plaquetas 190.000, AST 31. Pré-eclâmpsia sem sinais de gravidade.', 'Iniciar nifedipino retard 20 mg 12/12h e metildopa 250 mg 8/8h. Retorno em 3 dias com PA domiciliar anotada e exames de proteinúria. Orientados sinais de alarme e que procure maternidade na presença de cefaleia intensa, escotomas ou convulsão. Nova avaliação com 37 semanas.'),
  (431, 132, 7, '2025-06-19 04:30', 'internacao', 'Convulsão em casa, trazida pelo SAMU', 186, 118, 112, 94.0, 'Gestante de 37 semanas e 3 dias, sem retorno após a primeira consulta, teve crise tônico-clônica generalizada em casa, com duração de 2 minutos, seguida de sonolência. No SAMU: nova crise. Na chegada: Glasgow 13, PA 186x118, ausculta com estertores basais discretos, reflexos exaltados, edema 3+/4+. BCF 118 bpm, sem contrações. Plaquetas 142.000, AST 56, creatinina 1,1, proteinúria 3+. Eclâmpsia anteparto, com sofrimento fetal leve.', 'Sulfato de magnésio 4 g EV em 20 min e manutenção de 1 g/h por 24h após o parto, mantendo diurese e reflexos monitorados. Hidralazina 5 mg EV para PAD > 110. Resolução da gestação por cesárea imediata após estabilização. UTI materna após o parto.'),
  (432, 132, 14, '2025-06-20 09:00', 'internacao', 'Pós-operatório de cesárea por eclâmpsia', 148, 92, 86, 89.0, 'UTI, D1 de cesárea de urgência. Recém-nascido feminino 2.980 g, Apgar 6/8, em UTI neonatal por desconforto leve, evoluindo bem. Sem novas crises desde a admissão. Sulfato de magnésio mantido sem sinais de intoxicação (reflexos presentes, FR 16, diurese 60 mL/h). Despertou, orientada, sem déficits focais. TC de crânio sem hemorragia, edema discreto occipital compatível com PRES. Plaquetas 118.000, AST 44. Sangramento uterino normal.', 'Completar sulfato de magnésio por 24 horas. Manter nifedipino retard 20 mg 12/12h. Transferir para enfermaria após o término do magnésio. Ressonância cerebral se qualquer déficit. Estímulo à amamentação e alta em 4-5 dias.'),
  (433, 132, 7, '2025-08-12 10:00', 'retorno', 'Consulta do pós-parto', 128, 82, 76, 80.5, 'Sete semanas após parto, bebê saudável, mamando exclusivamente no peito. Sem cefaleia, convulsão ou alterações visuais desde a alta. Perdeu 8,5 kg. Lactação adequada. PA em casa 124-132 x 78-84 mmHg com nifedipino retard 20 mg 12/12h. Proteinúria de 24h 120 mg, creatinina 0,8 mg/dL, plaquetas 262.000. Exame: sem edema, ferida de cesárea cicatrizada, útero involuído. Orientada sobre risco de recorrência e hipertensão crônica no futuro.', 'Manter nifedipino com plano de desmame se PA < 120/75 por 2 semanas. Contracepção com DIU de cobre. Em nova gestação: AAS 100 mg desde 12 semanas e consulta pré-concepcional. Rastreio anual de PA, glicemia e perfil lipídico. Retorno em 3 meses.');
