insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (132, '2025-08-12', 'melhorou', 'Eclâmpsia anteparto com 37 semanas, tratada com sulfato de magnésio, hidralazina e cesárea de urgência, sem sequelas neurológicas. Mãe e bebê saudáveis, PA 128x82 mmHg em nifedipino, proteinúria normalizada. Orientada sobre risco em gestação futura.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (133, 'Elias Rodrigues Cavalheiro', 'M', '1966-11-14', 'Juiz de Fora', 'MG', 'Mecânico de automóveis', 'HAS há 15 anos, em uso irregular de enalapril 10 mg. Tabagista ativo (40 maços-ano), etilista moderado, obesidade e dislipidemia sem tratamento. Pai falecido de morte súbita aos 64 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (434, 133, 6, '2024-09-07 18:20', 'pronto_socorro', 'Dor lancinante no peito que foi pras costas', 232, 128, 108, 102.0, 'Pcte 57a, mecânico, dor torácica súbita, lancinante, intensidade 10/10, em região anterior com irradiação interescapular, iniciada durante esforço na oficina, associada a sudorese fria e síncope breve. Ao exame: REG, pálido, sudoreico. PA no braço direito 232x128 e esquerdo 184x100 (diferença de 48 mmHg). Pulso radial esquerdo diminuído, sopro diastólico aórtico 2+/4+ novo. ECG: HVE com alterações de repolarização, sem supra de ST. Troponina discretamente elevada. Raio X: alargamento do mediastino.', 'Suspeita de síndrome aórtica aguda. Esmolol EV com meta de FC < 60 e nitroprussiato para PAS 100-120 mmHg. Analgesia com fentanil. Angio-TC de aorta de urgência: dissecção de aorta ascendente estendendo ao arco e descendente (Stanford A, DeBakey I) com insuficiência aórtica e hemopericárdio pequeno. Acionada cirurgia cardiovascular.'),
  (435, 133, 12, '2024-09-07 22:30', 'internacao', 'Cirurgia de emergência por dissecção aguda de aorta', 110, 60, 62, 102.0, 'Cirurgia de emergência sob circulação extracorpórea e parada circulatória hipotérmica: troca de aorta ascendente com enxerto de Dacron e hemiarco, ressuspensão da valva aórtica, evacuação do hemopericárdio. Tempo de CEC 214 minutos, parada circulatória de 28 minutos. Sangramento importante no pós-operatório imediato, com necessidade de 8 concentrados de hemácias, plasma e plaquetas. Transferido à UTI intubado, com noradrenalina em dose moderada e função ventricular preservada.', 'UTI cirúrgica, ventilação mecânica, reposição volêmica e hemoderivados, controle rigoroso de PA e sangramento. Controle de lactato e débito urinário. Informada a família sobre gravidade e mortalidade alta nas primeiras 48 horas.'),
  (436, 133, 14, '2024-09-09 06:30', 'internacao', 'Choque refratário no 2º dia de pós-operatório', 74, 40, 128, 105.0, 'UTI, D2 de cirurgia de aorta. Evoluiu com choque misto (hemorrágico e vasoplégico), coagulopatia, lactato 9,8, injúria renal aguda oligúrica (creatinina 3,2) e isquemia mesentérica suspeita por distensão abdominal e acidose metabólica grave. Noradrenalina e vasopressina em doses altas, terceira reposição de hemoderivados. TC de abdome: sinais de isquemia intestinal extensa (má perfusão mesentérica por dissecção residual da aorta descendente). Sem condições cirúrgicas adicionais.', 'Discutido com cirurgião e família: sem benefício de laparotomia, risco proibitivo. Manter suporte máximo e conforto. Reavaliação em 6 horas. Família ciente do mau prognóstico e presente à beira do leito.');
