  (434, 'Troponina', 'Discretamente elevada (0,12 ng/mL)'),
  (434, 'ECG', 'Ritmo sinusal, HVE com alteração de repolarização, sem supra de ST'),
  (435, 'ECO transesofágico intraoperatório', 'FEVE 55%, insuficiência aórtica leve após ressuspensão da valva'),
  (436, 'Lactato arterial', '9,8 mmol/L'),
