insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (133, '2024-09-09', 'obito', 'Óbito no 2º dia de pós-operatório de dissecção aguda de aorta tipo A, por choque refratário, coagulopatia e isquemia mesentérica. Hipertenso mal controlado, tabagista, sem tratamento regular. Família acompanhada pelo serviço de psicologia do hospital.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (134, 'Antônio Carlos Bittencourt Filho', 'M', '1962-02-03', 'Niterói', 'RJ', 'Taxista', 'HAS há 18 anos, tratada de forma irregular com enalapril 10 mg quando se lembra. Sobrepeso, ex-fumante há 10 anos. Dor de cabeça frequente. Pai e avô hipertensos. Come bastante sal, fala que ‘comida sem sal não tem gosto’.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (437, 134, 2, '2021-08-17 14:00', 'consulta', 'Cansaço ao subir escadas e coração batendo forte', 168, 96, 78, 89.0, 'Paciente de 59 anos, dispneia aos médios esforços e palpitações esporádicas há 4 meses. Sem edema, sem ortopneia, sem dor torácica. PA 168x96 mmHg, ritmo regular. Exame: BEG, ictus desviado para esquerda, impulsivo, RCR 2T com B4, sem sopros, MV+ sem RA, sem edemas. ECG: sobrecarga ventricular esquerda com strain, Sokolow-Lyon 42 mm. ECO: HVE concêntrica moderada (septo 14 mm, parede posterior 13 mm), massa 138 g/m², FEVE 62%, disfunção diastólica grau I. Albuminúria 38 mg/g. Cardiopatia hipertensiva com HVE.', 'Iniciar losartana 100 mg/dia e anlodipino 5 mg/dia, regressão de HVE como alvo. Dieta hipossódica e perda de 6 kg. Orientado a manter o uso diário, mesmo sem sintomas. MAPA de 24 horas. Retorno em 8 semanas.'),
  (438, 134, 2, '2021-10-26 14:20', 'retorno', 'Tomando todo dia, a cabeça parou de doer', 138, 84, 72, 86.5, 'Boa adesão com alarme no celular do táxi. Perdeu 2,5 kg. Sem palpitações, dispneia melhor. MAPA: média de 24h 136x82, vigília 140x85, sono 124x72, descenso noturno preservado. PA de consultório 138x84, acima da meta. Edema discreto de tornozelos com anlodipino. K 4,4, creatinina 1,0. Exame sem alterações novas. Ainda abusa de sal nas marmitas compradas.', 'Associar clortalidona 12,5 mg à losartana 100 mg e trocar anlodipino por manutenção em 5 mg. Orientar rótulos e temperos sem sal. K e creatinina em 2 semanas. Retorno em 3 meses.'),
  (439, 134, 2, '2022-08-16 14:10', 'retorno', 'Vim fazer o eco de novo, estou ótimo', 122, 76, 68, 82.8, 'Um ano de tratamento regular, perdeu 6,2 kg. Sem dispneia nem palpitações. PA 122x76, MRPA 120x74 mmHg. ECO: massa ventricular reduzida para 112 g/m² (septo 12 mm), FEVE 64%, melhora da função diastólica. Albuminúria 14 mg/g. ECG com redução da voltagem (Sokolow-Lyon 33 mm). K 4,5, creatinina 1,0, ácido úrico 6,6. Sem edema. Boa adesão e menos sal.', 'Manter esquema atual. Orientar atividade física 3x por semana. Voltar a avaliar HVE em 18 meses com novo ECO. Retorno em 6 meses.');
