insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (134, '2022-08-16', 'controlado', 'Cardiopatia hipertensiva com HVE moderada, com regressão da massa ventricular de 138 para 112 g/m² após um ano de tratamento regular com losartana, anlodipino e clortalidona. PA 122x76 mmHg, albuminúria normalizada e perda de 6 kg.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (135, 'Domingos Sávio Teixeira Prado', 'M', '1959-06-21', 'Montes Claros', 'MG', 'Vendedor autônomo', 'HAS há 12 anos e dislipidemia, tabagista ativo (30 maços-ano), sedentário. Uso irregular de losartana 50 mg e sinvastatina 20 mg. Angina esforço-induzida não investigada há 6 meses, ignorada. Pai com IAM aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (440, 135, 6, '2022-11-03 02:50', 'pronto_socorro', 'Dor no peito em repouso, me acordou da cama', 164, 94, 88, 84.0, 'Pcte 63a, dor torácica precordial em aperto em repouso há 3 horas, duas crises de 20 minutos com sudorese e dispneia, melhorando parcialmente com repouso. Nos últimos 15 dias, dor aos esforços cada vez menores. Exame: ansioso, sem sinais de congestão, RCR 2T BNF sem sopros, MV+ sem RA. ECG: infradesnível de ST de 1,5 mm em V4-V6 e T invertidas em parede lateral, sem supra. Troponina I seriada: 0,02 ng/mL e 0,03 ng/mL em 3 horas (negativas). HD: angina instável, escore GRACE intermediário.', 'AAS 300 mg e ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol 50 mg, nitrato SL. Internar em unidade coronariana e estratificação invasiva em 24-48 horas. Jejum para cateterismo.'),
  (441, 135, 10, '2022-11-04 10:30', 'internacao', 'Cateterismo cardíaco', 142, 82, 70, 84.0, 'Sem dor desde a internação. Cateterismo por via radial direita: lesão crítica de 90% em DA proximal, 50% em Cx e CD sem lesões significativas, FEVE 58%. Realizada angioplastia da DA com stent farmacológico 3,0 x 24 mm, resultado angiográfico ótimo, TIMI 3. Sem complicações. Alta no 2º dia. Tabagista, aconselhado enfaticamente a parar, com adesivo de nicotina e orientação.', 'Dupla antiagregação (AAS + ticagrelor) por 12 meses. Atorvastatina 80 mg, metoprolol, losartana 50 mg 12/12h. Cessação do tabagismo. Reabilitação cardíaca. Retorno em 30 dias.'),
  (442, 135, 1, '2022-12-13 11:00', 'retorno', 'Sem dor, parei de fumar há um mês', 124, 76, 62, 82.4, 'Cinco semanas após a ATC, assintomático. Parou de fumar com o adesivo de nicotina e apoio da esposa. Faz caminhadas leves, voltou a vender com cuidado para não carregar muito peso. Sem sangramentos ou dispneia importante com ticagrelor. LDL 58 mg/dL. Exame: BEG, RCR 2T BNF, MV+ sem RA, punção radial sem hematoma. ECG sem alterações isquêmicas. PA 124x76, FC 62.', 'Manter AAS, ticagrelor, atorvastatina 80 mg, metoprolol e losartana. Seguir reabilitação. Reforçar abstinência ao tabaco e retorno em 3 meses. ECO de controle e teste ergométrico em 6 meses.');
