insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (135, '2022-12-13', 'melhorou', 'Angina instável com lesão crítica de DA tratada com angioplastia e stent farmacológico. Sem dor, parou de fumar, LDL 58 mg/dL e PA controlada. Mantém dupla antiagregação por 12 meses e reabilitação cardíaca.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (136, 'Valter Augusto Lombardi', 'M', '1951-05-30', 'Uberlândia', 'MG', 'Aposentado (ex-engenheiro)', 'IAM extenso de parede anterior em 2018 com ATC tardia, HAS, DM2 em uso de insulina, DRC estágio 3b. Ex-tabagista. Quadro de ICFEr isquêmica (FEVE 25%) com CDI implantado em 2019 em prevenção primária. Três filhos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (443, 136, 11, '2021-06-08 14:30', 'consulta', 'Falta de ar para ir ao banheiro', 98, 60, 70, 72.5, 'Paciente de 70 anos com ICFEr isquêmica avançada, NYHA III-IV, já com carvedilol 6,25 mg 12/12h, enalapril 5 mg 12/12h, espironolactona 25 mg, furosemida 80 mg. Dispneia em esforços mínimos, ortopneia e fadiga. PA 98x60. Exame: extremidades frias, jugulares ingurgitadas, B3, estertores em bases, edema 2+/4+. NT-proBNP 5.400 pg/mL, creatinina 2,1 (TFGe 31), K 5,0, Na 133. ECO: FEVE 22%, dilatação importante de VE, insuficiência mitral funcional moderada. Hipotensão e piora renal limitam titulação.', 'Manter carvedilol, reduzir enalapril para 2,5 mg 12/12h pela PA baixa (sacubitril/valsartana não tolerado nesse nível de PA), furosemida 80 mg 12/12h. Introduzir dapagliflozina 10 mg. Restrição hídrica 1,5 L/dia. Avaliar para terapia avançada. Retorno em 4 semanas.'),
  (444, 136, 11, '2022-02-14 03:10', 'internacao', 'Sem ar, inchado, quase sem urinar', 86, 52, 96, 79.0, 'Terceira internação por IC em 8 meses. Ganhou 6,5 kg em duas semanas, anasarca, ascite, oligúria. Perfil frio e úmido: pele fria, pulsos finos, PA 86x52 e creatinina 3,0 (síndrome cardiorrenal), Na 129, lactato 3,1. ECO: FEVE 20%, VD hipocinético, PSAP 58. Sem arritmia no CDI. Piora após suspender diurético por conta própria por incontinência urinária. Necessidade de inotrópico para otimizar perfusão e diurese.', 'Dobutamina 5 mcg/kg/min, furosemida em infusão contínua, suspensão do enalapril e espironolactona (creatinina e K). Manter carvedilol 3,125 mg 12/12h. Ultrafiltração se refratário. Discussão com a família sobre prognóstico e cuidados paliativos junto ao cuidado cardiológico.'),
  (445, 136, 11, '2022-09-20 15:00', 'retorno', 'Estou cansado de ficar internado', 90, 56, 74, 69.0, 'Desde fevereiro: alta após 18 dias, mais duas visitas ao PS por congestão, sem intubação. Hoje em NYHA IV, caquexia cardíaca, perda de peso de 10 kg, apetite ruim. Intolerância a doses de IECA por hipotensão e piora renal, creatinina 2,4 e K 5,2. FEVE 20%, CDI sem terapias nos últimos 6 meses. Candidato a terapia avançada descartado: idade, DRC e fragilidade. Em uso de furosemida 120 mg/dia e dapagliflozina com TFGe < 25 (suspensa). Família quer manter o paciente em casa.', 'Manter carvedilol 3,125 mg 12/12h e furosemida 80 mg 12/12h; sem IECA/espironolactona. Suspender dapagliflozina. Encaminhar para cuidados paliativos domiciliares, acompanhamento conjunto, plano antecipado de cuidados e desativação futura dos choques do CDI. Retorno em 6 semanas.');
