insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (136, '2022-09-20', 'piorou', 'ICFEr isquêmica terminal, FEVE 20%, com três internações em 8 meses, síndrome cardiorrenal e caquexia cardíaca. Intolerante à terapia modificadora de doença, não candidato a terapia avançada. Encaminhado para cuidados paliativos domiciliares com acompanhamento cardiológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (137, 'Zuleica Antunes de Paula', 'F', '1944-03-12', 'Goiânia', 'GO', 'Aposentada (ex-professora)', 'FA permanente há 8 anos em uso de varfarina, HAS e DRC estágio 3b, osteoartrose e uso frequente de ibuprofeno para dores nos joelhos. Peso baixo. Mora com a filha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (446, 137, 4, '2022-04-05 08:30', 'consulta', 'Consulta de rotina da anticoagulação', 138, 76, 74, 58.0, 'Paciente de 78 anos com FA permanente, CHA2DS2-VASc 4 (idade 75+ vale 2, sexo feminino, HAS), em varfarina com tempo na faixa terapêutica de 48% nos últimos 6 meses, INR flutuando entre 1,6 e 4,2. Come muito verde escuro de forma irregular e usa ibuprofeno de modo recorrente. Hoje INR 3,9 (alvo 2-3), sem sangramento. Creatinina 1,6 (TFGe 32), Hb 11,8. Exame: BEG, ritmo irregular, FC 74, sem edemas, sem estigmas hemorrágicos.', 'Suspender 1 dose de varfarina e reduzir dose semanal em 10%. Proibido ibuprofeno e outros AINEs (usar paracetamol). Considerar troca para apixabana pela labilidade do INR; paciente prefere manter por ora, mas fica avisada. Repetir INR em 7 dias. Retorno em 1 mês.'),
  (447, 137, 6, '2022-09-18 05:10', 'pronto_socorro', 'Fezes pretas e fraqueza, quase desmaiei', 88, 50, 118, 56.5, 'Pcte 78a em uso de varfarina e AINE (voltou a tomar ibuprofeno escondido para dor no joelho) com melena há 2 dias, tontura e síncope. PA 88x50, FC 118 irregular, pele e mucosas pálidas, sudorese. Toque retal com melena. INR 8,4, Hb 6,3 g/dL (era 11,8), ureia 112, creatinina 2,2. Choque hemorrágico classe III por hemorragia digestiva alta, provável úlcera péptica por AINE.', 'Dois acessos calibrosos, cristaloide, 2 concentrados de hemácias, vitamina K 10 mg EV lenta e complexo protrombínico (INR 8,4 com sangramento ativo). Suspender varfarina. Inibidor de bomba EV em alta dose e EDA em até 12 horas. Internação em UTI.'),
  (448, 137, 14, '2022-09-19 09:00', 'internacao', 'Pós-endoscopia na UTI', 108, 64, 92, 56.0, 'UTI, D1 de hemorragia digestiva alta. EDA mostrou úlcera gástrica antral de 1,5 cm com vaso visível (Forrest IIa), tratada com clipes e adrenalina, sem sangramento ativo. Recebeu 4 concentrados de hemácias no total, Hb pós 8,2 g/dL. INR 1,4. Função renal melhorando (creatinina 1,8). Sem arritmias malignas. Estabilizada, em dieta zero e inibidor de bomba contínuo. Biópsia com H. pylori positivo.', 'Tratar H. pylori (claritromicina, amoxicilina e IBP por 14 dias) após dieta liberada. Anticoagulação suspensa por 7 dias, depois reiniciar com apixabana 2,5 mg 12/12h (peso ≤ 60 kg e creatinina ≥ 1,5). Repor ferro EV. AINE definitivamente proscrito.'),
  (449, 137, 4, '2022-11-22 10:20', 'retorno', 'Estou fraca, mas sem sangramento', 118, 66, 78, 54.2, 'Dois meses após o sangramento. Erradicação do H. pylori concluída. Segue com astenia importante e anemia persistente (Hb 9,4, ferritina 18). Perdeu 4 kg. Apixabana 2,5 mg 12/12h reiniciada há 6 semanas com adesão; sem novos sangramentos. DRC piorou: creatinina 2,0 (TFGe 24) após episódio de choque. EDA de controle com cicatrização da úlcera. A filha relata declínio funcional e menos autonomia (usa andador).', 'Manter apixabana 2,5 mg 12/12h (critérios: peso ≤ 60 kg + creatinina ≥ 1,5), pantoprazol 40 mg/dia indefinido. Ferro EV, nefrologia para DRC. Hb e creatinina em 4 semanas. Retorno em 2 meses.');
