insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (137, '2022-11-22', 'piorou', 'FA com varfarina lábil e uso escondido de AINE evoluiu com hemorragia digestiva alta grave, necessitando UTI e transfusões. Mudou para apixabana em dose reduzida. Ficou com anemia persistente, DRC agravada (TFGe 24) e perda funcional e de peso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (138, 'Eliseu Marcondes Tavares', 'M', '1961-12-02', 'Bambuí', 'MG', 'Pedreiro', 'Doença de Chagas crônica (sorologia positiva), cardiopatia chagásica com FEVE 38% em ECO de 2021, em uso de enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h. Nascido em zona rural, depois mudou para a cidade. Etilista moderado.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (450, 138, 6, '2022-04-09 21:40', 'pronto_socorro', 'Coração disparou e quase apaguei', 92, 58, 178, 77.0, 'Pcte 60a, chagásico, palpitações súbitas intensas há 30 minutos com pré-síncope, sudorese fria e dispneia. Exame: pálido, sudoreico, FC 178 regular, PA 92x58, MV+ com estertores finos nas bases, sem edema. ECG: taquicardia com QRS largo (160 ms), morfologia de BRD com desvio do eixo à esquerda, FC 178, dissociação AV. HD: taquicardia ventricular monomórfica sustentada, hemodinamicamente limítrofe. K 4,0, Mg 1,9.', 'Cardioversão elétrica sincronizada sob sedação (100 J, 1 choque) com reversão para ritmo sinusal, FC 74. Amiodarona 150 mg EV em 10 minutos seguida de infusão contínua. Internar e encaminhar para implante de CDI em prevenção secundária.'),
  (451, 138, 4, '2022-04-11 08:00', 'internacao', 'Implante de CDI', 120, 74, 64, 76.0, 'Estável em ritmo sinusal. ECO: FEVE 36%, aneurisma apical sem trombo, dilatação de VE moderada. Coronariografia: coronárias normais, afastando origem isquêmica. Realizado implante de CDI bicameral por TV sustentada, sem complicações, limiares adequados, teste de indução de fibrilação ventricular revertido adequadamente. Amiodarona iniciada via oral. Não é indicado benznidazol (cardiopatia estabelecida).', 'Amiodarona 200 mg/dia (após dose de ataque), carvedilol 12,5 mg 12/12h, enalapril, espironolactona 25 mg. Cuidados com a ferida, não levantar braço por 4 semanas, orientações sobre choques e proibição de dirigir por 6 meses. Retorno em 4 semanas.'),
  (452, 138, 4, '2022-05-17 09:30', 'retorno', 'Estou me acostumando com o aparelho no peito', 114, 70, 58, 77.2, 'Ferida cicatrizada, sem hematoma. Sem palpitações. Interrogação do CDI: sem episódios de TV/FV, 0 terapias, estimulação atrial/ventricular raras. FC 58 bpm em amiodarona e carvedilol. TSH normal e função hepática normal. Medo de dirigir e de sofrer choque; orientado sobre procedimentos em caso de choque único ou múltiplo. Dispneia leve a esforços (NYHA II). Parou de beber depois do susto.', 'Manter amiodarona, carvedilol, enalapril e espironolactona. TSH e transaminases a cada 6 meses. Raio X de tórax e avaliação oftalmológica anual. Retorno em 4 meses. Não dirigir até completar 6 meses sem eventos.'),
  (453, 138, 4, '2023-03-14 09:10', 'retorno', 'Levei um choque no peito semana passada', 110, 68, 56, 78.0, 'Há 6 dias, durante esforço no trabalho, sentiu palpitação seguida de choque único no peito, sem síncope. Interrogação do CDI: episódio de TV monomórfica a 172 bpm terminada com ATP sem sucesso, seguida de choque de 20 J com reversão. Único episódio em 11 meses. Havia reduzido a amiodarona por conta própria por receio dos efeitos colaterais. Sem sintomas de IC, FEVE 35% ao ECO. TSH 3,1.', 'Choque apropriado. Retomar amiodarona 200 mg/dia sem interrupção, adicionar espironolactona 25 mg (já em uso). Reprogramar zonas de ATP no CDI. Conversar sobre ablação de TV se recorrer. Retorno em 8 semanas.');
