insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (138, '2023-03-14', 'estavel', 'Cardiopatia chagásica com TV monomórfica sustentada, tratada com cardioversão, CDI e amiodarona. Teve um único choque apropriado após reduzir a amiodarona por conta própria. FEVE 35%, sem sinais de IC; segue em acompanhamento com a arritmologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (139, 'Pedro Henrique Salazar Nunes', 'M', '2000-07-15', 'Belo Horizonte', 'MG', 'Estudante e atleta amador de futebol', 'Hígido. Palpitações súbitas desde os 16 anos, ocorrendo em jogos, com duração de 5 a 20 minutos. Nunca desmaiou. Avô materno morreu de morte súbita aos 50 anos. Não usa suplementos ou drogas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (454, 139, 4, '2023-02-08 16:00', 'consulta', 'Coração dispara durante o jogo e demora a voltar', 118, 70, 66, 74.0, 'Atleta de 22 anos com palpitações súbitas e regulares durante o futebol, a última há 3 semanas com duração de 25 minutos, tontura e necessidade de sair do campo. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA. ECG de repouso: PR curto (96 ms), onda delta positiva, QRS alargado (120 ms) e alterações de repolarização secundárias, padrão de pré-excitação ventricular. ECO normal, FEVE 64%. Holter: períodos de pré-excitação intermitente. Teste ergométrico: pré-excitação persistente em esforço, sem arritmia. Síndrome de Wolff-Parkinson-White.', 'Afastado de esforços intensos até a ablação. Indicado estudo eletrofisiológico e ablação da via acessória. Orientar sobre risco de FA pré-excitada com morte súbita. Não iniciar antiarrítmico. Se crise com tontura ou síncope, ir ao PS. Agendar ablação em 6 semanas.'),
  (455, 139, 4, '2023-03-22 07:30', 'internacao', 'Estudo eletrofisiológico e ablação', 120, 72, 68, 74.0, 'Estudo eletrofisiológico: via acessória póstero-septal direita com propriedades de condução anterógrada rápida (período refratário efetivo 240 ms). Induzida taquicardia atrioventricular ortodrômica (ciclo 300 ms). Ablação por radiofrequência da via acessória, com perda da onda delta no primeiro disparo e bloqueio de via comprovado, sem reconexão após 30 minutos de observação e isoproterenol. Sem complicações. Alta no mesmo dia, ECG com PR 150 ms e QRS 90 ms sem onda delta.', 'Repouso relativo 3 dias, evitar esforço intenso por 1 semana. Curativo em virilha e revisão em 7 dias. Retorno em 30 dias com ECG para liberar atividade esportiva.'),
  (456, 139, 4, '2023-04-26 16:30', 'retorno', 'Quero voltar a jogar bola', 116, 68, 62, 75.2, 'Cinco semanas após a ablação, sem palpitações e já faz caminhadas leves. ECG: PR 148 ms, QRS 88 ms, sem onda delta. Holter de 24h sem arritmias. Teste ergométrico máximo, 15 METs, sem pré-excitação e sem arritmia. Exame físico normal. Paciente ansioso para voltar às peladas de fim de semana e ao time da faculdade.', 'Liberado para atividade esportiva sem restrições. Sem medicações. Orientado a retornar se palpitações. Alta ambulatorial; considerar avaliação familiar de primeiro grau com ECG pela história de morte súbita no avô.');
