insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (139, '2023-04-26', 'melhorou', 'Síndrome de Wolff-Parkinson-White em atleta jovem, curada com ablação por radiofrequência de via acessória póstero-septal direita. ECG sem onda delta, teste ergométrico normal e sem arritmias. Liberado para esportes sem medicação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (140, 'Tamires Gabriela Oliveira Rangel', 'F', '1993-03-25', 'Recife', 'PE', 'Auxiliar administrativa', 'Segunda gestação, parto vaginal há 4 semanas de bebê saudável, amamentando. Pré-natal com leve elevação da PA no fim da gestação (sem diagnóstico de pré-eclâmpsia). Sem cardiopatia conhecida. Mãe com hipertensão. Origem afrodescendente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (457, 140, 6, '2024-04-28 04:20', 'pronto_socorro', 'Falta de ar de madrugada e pernas inchadas depois do parto', 142, 92, 118, 78.0, 'Pcte 31a, 4 semanas de puerpério, com dispneia progressiva há 2 semanas, ortopneia, DPN, tosse noturna e edema de MMII. Piora súbita hoje. Exame: taquipneica, SpO2 89% em ar ambiente, estertores até campos médios, jugulares ingurgitadas, B3, taquicárdica, edema 2+/4+. ECG: taquicardia sinusal, T invertidas em parede lateral. Raio X com cardiomegalia e congestão. BNP 1.640 pg/mL, troponina discretamente elevada (0,09 ng/mL). Edema agudo de pulmão por provável cardiomiopatia periparto.', 'O2 suplementar, furosemida 40 mg EV com boa diurese, sentada, nitrato EV. Sem contraindicação ao uso de IECA no puerpério. D-dímero e angio-TC afastaram TEP. Internar em UTI/unidade de IC. ECO imediato.'),
  (458, 140, 11, '2024-04-29 09:30', 'internacao', 'Avaliação de insuficiência cardíaca no puerpério', 118, 74, 96, 75.2, 'Melhorou com diurético, SpO2 96% em ar ambiente, perda de 2,8 kg. ECO: FEVE 24% (Simpson), dilatação de VE (DDVE 62 mm), insuficiência mitral funcional leve, sem trombo, sem derrame pericárdico. Cardiomiopatia periparto confirmada, após exclusão de miocardite aguda por clínica e ressonância adiada. Coronárias não investigadas (baixo risco). TSH normal. Mãe amamentando e quer manter se possível.', 'Iniciar enalapril 2,5 mg 12/12h (compatível com amamentação), carvedilol 3,125 mg 12/12h, furosemida 40 mg/dia, espironolactona 25 mg. Bromocriptina 2,5 mg 12/12h por 2 semanas e depois 2,5 mg/dia por 6 semanas, com anticoagulação profilática com enoxaparina 40 mg/dia pelo risco trombótico. Interromper aleitamento (efeito da bromocriptina), aconselhamento e apoio psicológico.'),
  (459, 140, 11, '2024-06-18 14:00', 'retorno', 'Voltei a conseguir cuidar do bebê sem cansar', 110, 68, 72, 69.8, 'Seis semanas após a alta, NYHA I-II, sem ortopneia ou edema. Peso seco 69,8 kg. Triste por não amamentar, em acompanhamento psicológico. ECO: FEVE 38%, DDVE 57 mm. Bromocriptina na fase de manutenção. PA 110x68, FC 72. K 4,5, creatinina 0,8. Escolheu implante de DIU de cobre com contracepção eficaz, pois nova gestação é de alto risco. Boa adesão.', 'Subir enalapril para 5 mg 12/12h e carvedilol 6,25 mg 12/12h. Manter espironolactona 25 mg, suspender furosemida. Bromocriptina até o fim do ciclo e enoxaparina suspensa ao final. Contracepção segura (evitar gestação). Retorno em 2 meses.'),
  (460, 140, 11, '2024-10-22 14:20', 'retorno', 'Retorno para ver o coração', 108, 66, 64, 68.5, 'Seis meses do início do quadro, assintomática, NYHA I, trabalhando normalmente e cuidando dos filhos. ECO: FEVE 52%, DDVE 50 mm, sem insuficiência mitral. NT-proBNP 85 pg/mL. PA 108x66, FC 64. Mantém DIU de cobre. Entendeu que precisa continuar o tratamento por 12-24 meses mesmo recuperada e que nova gestação carrega risco de recidiva. Sem tosse ou outros efeitos adversos.', 'Manter enalapril 5 mg 12/12h, carvedilol 6,25 mg 12/12h, espironolactona 25 mg. Reavaliar em 6 meses com ECO e RM cardíaca. Não suspender medicações antes de 12 a 24 meses de FEVE normal. Aconselhamento sobre gestação futura. Retorno em 6 meses.');
