insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (140, '2024-10-22', 'melhorou', 'Cardiomiopatia periparto com FEVE inicial de 24% e edema agudo de pulmão, tratada com terapia para IC e bromocriptina. Em seis meses a FEVE recuperou para 52%, NYHA I. Mantém medicação por 12-24 meses e contracepção por risco de recidiva.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (141, 'Rosângela Pires Cordeiro', 'F', '1967-09-02', 'Sabará', 'MG', 'Auxiliar de serviços gerais', 'HAS há 3 anos, obesidade grau II e pré-diabetes. Em uso de losartana 50 mg 12/12h e anlodipino 5 mg. Fez dieta várias vezes e recuperou o peso. Pai falecido de AVC aos 72 anos. Trabalha em pé e cuida de dois netos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (461, 141, 1, '2023-03-07 08:40', 'consulta', 'Estou tomando dois remédios e a pressão ainda fica em 14 por 9', 144, 90, 80, 104.0, 'Paciente de 55 anos, obesa (IMC 41,6), PA 144x90 em uso de losartana e anlodipino, com boa adesão confirmada pelos comprimidos entregues. Dispneia leve aos esforços, ronco e cansaço matinal. Exame: RCR 2T BNF, MV+ sem RA, edema 1+/4+ de tornozelos. Glicemia de jejum 108, HbA1c 5,9%, LDL 126, creatinina 0,8. Conversa sobre a relação direta entre peso e pressão: cada kg perdido reduz em média 1 mmHg.', 'Manter losartana 50 mg 12/12h e anlodipino 5 mg. Encaminhar à nutrição e ao programa de emagrecimento da UBS, caminhada na hora do almoço, meta de perder 10% do peso em 6 meses. Polissonografia solicitada. Retorno em 6 meses.'),
  (462, 141, 1, '2023-11-14 08:30', 'retorno', 'Emagreci bastante, a roupa tá folgando', 122, 76, 70, 94.0, 'Perdeu 10 kg em 8 meses com reeducação alimentar, redução de pão e doces, e caminhadas. PA 122x76, MRPA 118x72 mmHg, com episódios de tontura ao levantar à tarde. Edema de tornozelos desapareceu. Polissonografia com IAH 6/h (normal). HbA1c 5,5%, LDL 104. Boa tolerância ao esquema. Sem sintomas de hipotensão importante, mas as medidas mostram margem para reduzir medicação.', 'Suspender anlodipino 5 mg. Manter losartana 50 mg 12/12h. MRPA em 4 semanas por telefone. Manter dieta e atividade. Retorno em 6 meses.'),
  (463, 141, 1, '2024-09-10 08:50', 'retorno', 'Vim ver se posso tirar outro remédio', 118, 72, 66, 86.0, 'Perda total de 18 kg em 18 meses, mantendo o peso nos últimos 4 meses. MRPA com média de 116x70 mmHg com losartana 50 mg 12/12h. Sem sintomas. HbA1c 5,4%, LDL 98 mg/dL, creatinina 0,8, potássio 4,3. Exame normal. Orgulhosa: ‘a balança me motivou a continuar’. O objetivo é verificar se há espaço para reduzir mais um comprimido.', 'Reduzir losartana para 50 mg uma vez ao dia, com MRPA semanal. Retorno em 3 meses. Se PA > 130x80, voltar para 12/12h. Manter MEV, em especial a atividade física e o controle do sal.');
