insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (141, '2024-09-10', 'controlado', 'Hipertensão associada a obesidade, com perda de 18 kg em 18 meses permitindo suspender o anlodipino e reduzir a losartana para dose única. PA 118x72 mmHg com monoterapia, HbA1c 5,4% e polissonografia normal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (142, 'Jorge Luís Machado Bastos', 'M', '1963-01-26', 'Belo Horizonte', 'MG', 'Gerente de banco', 'HAS há 10 anos, dislipidemia e tabagismo (25 maços-ano, ainda fumando). Muito estresse no trabalho. Sem diabetes. Em uso de anlodipino 5 mg e sinvastatina 20 mg. Pai com IAM aos 62 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (464, 142, 10, '2022-06-15 05:40', 'internacao', 'Dor no peito durante a madrugada, que não passava', 152, 90, 84, 86.0, 'Pcte 59a admitido pelo PS por dor torácica prolongada (2h), sem supra de ST ao ECG: infradesnível de ST de 2 mm em DII, DIII e aVF, T negativas laterais. Troponina I 4,2 ng/mL (elevada, curva ascendente). Estável hemodinamicamente, Killip I, GRACE 142. IAMSSST. Cateterismo em 12 horas: oclusão subtotal da CD proximal (95%) com trombo, DA com 40% e Cx sem lesões, FEVE 56%. ATC da CD com stent farmacológico 3,5 x 18 mm, TIMI 3 final, sem intercorrências.', 'AAS 100 mg, ticagrelor 90 mg 12/12h por 12 meses, atorvastatina 80 mg, metoprolol succinato 50 mg, losartana 50 mg. Cessação do tabagismo, reabilitação cardíaca. Alta em 3 dias. Retorno em 30 dias.'),
  (465, 142, 1, '2022-07-26 10:30', 'retorno', 'Retorno depois do infarto', 126, 78, 64, 84.4, 'Quarenta dias após o IAMSSST. Sem angina, sem dispneia. Reduziu o cigarro para 3 por dia, mas não parou totalmente. Voltou ao trabalho há 2 semanas e sente-se pressionado pelas metas. Ainda não iniciou a reabilitação cardíaca por falta de tempo. Exame: BEG, RCR 2T BNF, MV+ sem RA, PA 126x78, FC 64. LDL 71 mg/dL. Dispneia leve com ticagrelor, aceitável. ECO: FEVE 57%.', 'Reforçar reabilitação cardíaca, cessação do fumo com adesivo de nicotina e bupropiona. Manter dupla antiagregação, estatina e betabloqueador. Orientado a não interromper o ticagrelor. Retorno em 3 meses.'),
  (466, 142, 1, '2022-10-18 11:00', 'retorno', 'Estou bem, mas o remédio é muito caro', 134, 82, 68, 86.8, 'Quatro meses do IAM. Sem angina. Voltou a fumar 10 cigarros por dia nos meses de pico de trabalho e não frequentou a reabilitação. Queixa-se do custo do ticagrelor e está cortando doses (‘tomo uma vez por dia para durar mais’). Pressão acima da meta, LDL 94, ganho de 2,4 kg. Exame cardiovascular normal. Explicado o risco de trombose do stent com a dupla antiagregação interrompida antes de 12 meses. Concordou em trocar por clopidogrel.', 'Trocar ticagrelor por clopidogrel 75 mg/dia (mais barato, disponível no SUS), completando 12 meses. Reforçar adesão, reabilitação e parada do tabagismo. Aumentar losartana para 100 mg/dia. Retorno em 8 semanas.');
