insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (142, '2023-06-30', 'abandonou', 'IAMSSST tratado com angioplastia e stent em CD. Não manteve cessação do tabagismo nem a reabilitação, e reduziu o ticagrelor por custo, sendo trocado por clopidogrel. Faltou aos retornos de dezembro e de fevereiro e não atendeu aos contatos; seguimento perdido.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (143, 'Marta Lúcia Pontes Albuquerque', 'F', '1958-12-19', 'Fortaleza', 'CE', 'Professora aposentada', 'HAS há 15 anos, tratada com losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg, e espironolactona 25 mg adicionada há 6 meses por outro médico por suspeita de hipertensão resistente. Hipotireoidismo tratado. Muito ansiosa com médicos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (467, 143, 1, '2023-09-12 09:00', 'consulta', 'Com quatro remédios e a pressão no consultório continua 17 por 9', 168, 94, 86, 64.0, 'Paciente de 64 anos encaminhada por hipertensão resistente em quatro drogas (incluindo diurético e espironolactona). Em casa, a PA medida pela filha com aparelho validado costuma ser 118-126 x 66-74. No consultório há tensão evidente, PA 168x94, que cai para 150x88 em outra medida após 10 minutos. Queixa-se de tontura, câimbras e fadiga, com K 3,4 e Na 133. Sem sinais de lesão de órgão-alvo (ECO normal, albuminúria ausente). Suspeita de efeito do avental branco com sobretratamento.', 'MAPA de 24 horas para confirmar pseudorresistência antes de intensificar. Suspender clortalidona (hiponatremia e hipocalemia). Manter losartana, anlodipino e espironolactona por ora. Repor potássio via dieta. Retorno com MAPA em 3 semanas.'),
  (468, 143, 1, '2023-10-24 09:20', 'retorno', 'Vim buscar o resultado do aparelho de 24 horas', 160, 92, 80, 64.2, 'MAPA com média de 24h de 112x64 mmHg, vigília 118x68, sono 98x56, com hipotensão em vários períodos (PA mínima de 84x50) e episódios de tontura registrados no diário. Em consultório 160x92 mmHg, dissociação importante. Pseudorresistência por avental branco, com sobretratamento: tomando quatro fármacos sem necessidade. Na 137, K 3,9 após suspender a clortalidona.', 'Retirar espironolactona e reduzir anlodipino para 5 mg; manter losartana 100 mg. Medir PA em casa para ajustes e evitar tratar pelo consultório. Nova MAPA em 3 meses. Retorno em 8 semanas.'),
  (469, 143, 1, '2024-03-19 09:10', 'retorno', 'Não tenho mais tonturas', 144, 86, 74, 65.0, 'Sem tontura, sem câimbras. Fadiga melhorou. PA de consultório 144x86 mmHg, MRPA com média de 124x72. Nova MAPA: média de 24h 120x70, vigília 124x74, sono 106x60 mmHg, descenso preservado, dentro da meta. Na 139, K 4,1, creatinina 0,8. Mantém o diário de PA em casa e entende que o consultório superestima a pressão. Mais tranquila na consulta.', 'Manter losartana 100 mg + anlodipino 5 mg. Considerar a PA de casa e MAPA para decisões. Repetir MAPA em 1 ano. Retorno em 6 meses.');
