insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (143, '2024-03-19', 'controlado', 'Pseudorresistência por efeito do avental branco, descoberta na MAPA (média de 24h 112x64 mmHg com hipotensões). Retiradas a espironolactona e a clortalidona, que causavam hiponatremia e hipocalemia. Controlada com losartana e anlodipino, MAPA de controle 120x70 mmHg.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (144, 'Ricardo Augusto Schmitt', 'M', '1952-08-11', 'Porto Alegre', 'RS', 'Aposentado (ex-professor universitário)', 'HAS há 25 anos, dislipidemia, DM2 em uso de metformina, ex-tabagista. Dor torácica aos esforços há 5 meses. Irmão operou o coração aos 60 anos. Usa losartana 50 mg 12/12h e rosuvastatina 10 mg. Faz caminhadas diárias.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (470, 144, 2, '2021-03-23 10:00', 'consulta', 'Aperto no peito ao caminhar na subida', 136, 80, 76, 81.0, 'Paciente de 68 anos com dor retroesternal em aperto, após caminhar 400 m em subida, aliviando em 3-5 minutos com repouso, CCS II. Sem síncope. Exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, pulsos presentes. ECG de repouso normal. Teste ergométrico: angina aos 7 METs, infradesnível de ST de 2,5 mm em V4-V6, com recuperação lenta. Cintilografia: isquemia moderada em território anterior (12% do VE), FEVE 55%. Angina estável de risco intermediário-alto.', 'Iniciar AAS 100 mg e metoprolol succinato 50 mg, rosuvastatina 20 mg, nitrato SL se dor. Cateterismo eletivo. Manter losartana e metformina. Orientar sinais de alarme. Retorno após o cateterismo.'),
  (471, 144, 10, '2021-05-05 07:30', 'internacao', 'Cateterismo eletivo', 140, 82, 66, 81.0, 'Cateterismo: estenose de 85% em DA proximal, lesão de 40% em CD e Cx sem lesões significativas, FEVE 56%. Por isquemia moderada, sintomas e anatomia favorável, realizada ATC da DA com stent farmacológico 3,5 x 22 mm, resultado excelente, TIMI 3, sem complicações. Alta em 24 horas, sem hematoma no sítio radial.', 'Clopidogrel 75 mg por 6 meses associado a AAS 100 mg. Manter estatina, betabloqueador e demais drogas. Reabilitação cardíaca. Retorno em 6 semanas.'),
  (472, 144, 2, '2021-06-22 10:30', 'retorno', 'Sem dor, comecei a reabilitação', 126, 74, 60, 79.8, 'Seis semanas pós-ATC sem angina. Iniciou reabilitação cardíaca duas vezes por semana, com ótima tolerância, chegando a 8 METs. Sem sangramentos com dupla antiagregação. LDL 62, HbA1c 6,8%. Exame: BEG, RCR 2T BNF, PA 126x74, FC 60. Nenhum efeito adverso da rosuvastatina. Fez questão de perguntar se pode viajar de avião para visitar a filha na Alemanha.', 'Liberado para viagem de avião com caminhadas durante o voo e hidratação. Manter dupla antiagregação até novembro, depois só AAS. Manter doses das demais medicações. Retorno em 6 meses.'),
  (473, 144, 2, '2022-06-14 10:00', 'retorno', 'Tudo bem, voltei da Alemanha', 122, 72, 58, 78.2, 'Um ano de ATC, assintomático. Viajou sem problemas, caminha 5 km diariamente. Suspendeu o clopidogrel conforme planejado e segue com AAS. LDL 54 mg/dL, HbA1c 6,6%, creatinina 1,0. ECO com FEVE 58%. Teste ergométrico sem isquemia aos 9 METs. Exame: PA 122x72, FC 58, sem sopros, MV+ sem RA.', 'Manter AAS 100 mg, rosuvastatina 20 mg, metoprolol, losartana e metformina. Seguir caminhadas. Retorno anual com LDL, HbA1c e creatinina.');
