insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (144, '2022-06-14', 'controlado', 'Angina estável com isquemia anterior, tratada com angioplastia de DA e stent farmacológico e reabilitação cardíaca. Um ano depois, assintomático, teste ergométrico sem isquemia, LDL 54 mg/dL e HbA1c 6,6%, mantendo AAS e prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (145, 'Osvaldo Campos Rezende', 'M', '1948-04-07', 'Patrocínio', 'MG', 'Cafeicultor aposentado', 'HAS há 20 anos em uso de enalapril 10 mg 12/12h, DM2 em dieta. Ex-fumante há 5 anos. Mora na fazenda, a 60 km do hospital. Pai faleceu de infarto aos 67 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (474, 145, 6, '2021-02-18 22:30', 'pronto_socorro', 'Dor no peito há quase um dia e suor frio', 98, 60, 48, 80.0, 'Pcte 72a, dor torácica em aperto há 18 horas, que não procurou antes por estar na fazenda e ''achar que era azia''. Sudorese, náuseas, bradicardia. Exame: REG, pálido, sudoreico, RCR 2T BNF, FC 48, PA 98x60, MV+ sem RA, sem sinais de congestão. ECG: supra de ST de 3 mm em DII, DIII e aVF, infra recíproco em DI e aVL, BAV de 1º grau com bloqueio de Mobitz I. Troponina I 14 ng/mL. IAMCSST de parede inferior, Killip I, apresentação tardia (> 12h), mas com dor persistente.', 'AAS 300 mg, ticagrelor 180 mg, heparina, atorvastatina 80 mg, sem betabloqueador (bradicardia). Evitar nitrato por suspeita de infarto de VD. ECG com derivações direitas para confirmar. Transferido para hemodinâmica para angioplastia por dor persistente em até 24h.'),
  (475, 145, 10, '2021-02-19 01:10', 'internacao', 'Angioplastia por IAM inferior', 110, 64, 62, 80.0, 'Cateterismo: oclusão trombótica da coronária direita proximal, DA com 50%, Cx sem lesões. Angioplastia da CD com stent farmacológico 3,5 x 26 mm, fluxo TIMI 3 recuperado, com resolução do BAV. FEVE 48% (hipocinesia inferior). Sem arritmias nas 24h seguintes. Ritmo sinusal, FC 62. Em UTI, cursando estável e sem sinais de choque. Alta no 5º dia.', 'AAS + ticagrelor por 12 meses, atorvastatina 80 mg, iniciar metoprolol succinato 25 mg e enalapril 10 mg 12/12h (manter). Reabilitação cardíaca próxima de casa. Retorno em 30 dias.'),
  (476, 145, 1, '2021-04-06 09:30', 'retorno', 'Estou bem, só um cansaço leve', 124, 72, 58, 78.2, 'Sem angina. Cansaço leve em esforços maiores (NYHA I-II). ECO: FEVE 50%, hipocinesia inferior residual. ECG em ritmo sinusal, PR 190 ms, sem BAV. LDL 64 mg/dL. Abandonou o ticagrelor por dispneia por 1 semana, mas retomou. Ainda não foi à reabilitação por distância; fez caminhada no pasto. Exame: PA 124x72, FC 58, sem sinais de IC.', 'Manter dupla antiagregação, estatina, metoprolol 25 mg e enalapril. Reabilitação domiciliar orientada com caminhadas progressivas. Controle glicêmico e HbA1c em 3 meses. Retorno em 6 meses.'),
  (477, 145, 1, '2021-10-19 09:40', 'retorno', 'Voltei a trabalhar na lavoura devagar', 128, 74, 60, 79.0, 'Oito meses de IAM, assintomático, supervisiona a colheita do café sem esforço pesado. Sem dor torácica, dispneia ou palpitações. HbA1c 6,9%, LDL 58 mg/dL, creatinina 1,0, potássio 4,5. ECG: ritmo sinusal, onda Q inferior. Aderente, sem sangramentos. Aviso de que em dezembro é preciso trocar a dupla antiagregação por AAS isolado. Relata que o relevo do sítio dificulta a ida ao hospital em emergência.', 'Manter conduta atual. Ao completar 12 meses (fevereiro), suspender ticagrelor e seguir só com AAS. Orientado a chamar o SAMU (192) imediatamente em caso de dor torácica, sem esperar. Retorno em 6 meses.');
