insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (145, '2021-10-19', 'estavel', 'IAMCSST inferior com apresentação tardia e BAV transitório, tratado com angioplastia de CD. FEVE recuperou de 48% para 50%, assintomático e em prevenção secundária. Sequela de hipocinesia inferior residual; segue com acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (146, 'Marlene Aparecida Furtado', 'F', '1958-05-16', 'Lavras', 'MG', 'Costureira', 'Etilismo crônico por 25 anos (aguardente diária), parou em 2022 após internação. HAS e tabagismo (40 maços-ano), parou há 1 ano. Cardiomiopatia alcoólica diagnosticada em 2022. Perdeu o marido em 2023.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (478, 146, 11, '2023-05-02 14:00', 'consulta', 'Quero saber se meu coração melhorou depois que parei de beber', 122, 76, 80, 58.0, 'Paciente de 64 anos com cardiomiopatia alcoólica (FEVE 30% em 2022), abstinente há 11 meses. NYHA II, sem ortopneia, sem edema. Perdeu 5 kg, emagrecida, com leve desnutrição. PA 122x76, FC 80. Exame: BEG, RCR 2T B3 ausente, sem sopros, MV+ sem RA. ECO: FEVE 38%, DDVE 60 mm. NT-proBNP 920. Creatinina 0,9, K 4,4. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 20 mg. Tem tido insônia e tristeza desde a morte do marido.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (após 36 horas sem IECA). Acrescentar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol, suspender furosemida. Encaminhar ao CAPS para luto e abstinência. Retorno em 4 semanas.'),
  (479, 146, 11, '2023-09-11 23:50', 'internacao', 'Falta de ar e barriga inchada, voltei a beber', 100, 64, 104, 64.5, 'Paciente voltou a beber (admite 1 garrafa de cachaça por semana, depois diária) após aniversário da morte do marido e parou os remédios porque ‘não adiantava nada’. Chega com 3 semanas de dispneia progressiva, ortopneia, edema até a raiz da coxa e ascite. Exame: taquipneica, jugulares ingurgitadas, estertores até campos médios, hepatomegalia dolorosa, ascite, edema 3+/4+. ECO: FEVE 24%, dilatação biventricular, PSAP 54. NT-proBNP 7.800, K 4,9, creatinina 1,2, TGO 88 e GGT elevada. ICFEr descompensada por álcool e abandono.', 'Furosemida EV 80 mg 12/12h, tiamina 300 mg/dia, acompanhamento da abstinência com escala CIWA (benzodiazepínico se necessário). Reintroduzir carvedilol 3,125 mg 12/12h e espironolactona 25 mg. Avaliação do CAPS-AD e psicologia. Orientação da família.'),
  (480, 146, 11, '2024-02-27 10:00', 'retorno', 'Cansada de tudo, não consigo mais ficar sem beber', 96, 60, 92, 60.2, 'Alta em setembro após 12 dias, mas voltou a beber quase diariamente e usa os remédios de modo irregular. Duas idas ao PS por congestão no período. Hoje NYHA III, ortopneia, edema 2+/4+, tonta, desnutrida (perdeu massa muscular). PA 96x60 limita titulação. ECO: FEVE 22%. NT-proBNP 4.200, creatinina 1,4, K 5,0. Resistente a internação no CAPS-AD: ‘eu só quero ir para casa’. Filha vive em outra cidade e liga toda semana.', 'Manter carvedilol 3,125 mg 12/12h, espironolactona 25 mg e furosemida 40 mg/dia. Sacubitril/valsartana suspenso pela PA baixa. Reforçada abstinência, novo encaminhamento ao CAPS-AD com visita domiciliar da equipe e da filha. Avaliação de cuidados paliativos. Retorno em 4 semanas.');
