insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (146, '2024-02-27', 'piorou', 'Cardiomiopatia alcoólica que melhorou com abstinência (FEVE 38%) e piorou após recaída no álcool e abandono da medicação, após o luto do marido. FEVE 22%, NYHA III, duas visitas ao PS. Em reavaliação com CAPS-AD e cuidados paliativos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (147, 'Benedito Aparecido Monteiro', 'M', '1945-10-30', 'Brasília', 'DF', 'Aposentado (ex-servidor público)', 'HAS há 35 anos, DM2 há 20 anos, DRC estágio 3b, ICFEr isquêmica (IAM em 2015, FEVE 30%). Em uso de losartana 50 mg, carvedilol 12,5 mg 12/12h, espironolactona 25 mg, furosemida 40 mg, insulina NPH. Hiperplasia prostática com retenção urinária recorrente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (481, 147, 11, '2023-01-24 15:00', 'consulta', 'Quero reorganizar meus remédios do coração', 118, 68, 66, 82.0, 'Paciente de 77 anos, ICFEr isquêmica com NYHA II, estável. Ganho de 1,5 kg nas últimas semanas, edema discreto de tornozelos. PA 118x68, FC 66. Exame: BEG, RCR 2T, estertores raros nas bases, edema 1+/4+. NT-proBNP 1.680, creatinina 1,7 (TFGe 40), K 4,9. ECO: FEVE 31%, VE dilatado, IM funcional leve. Está em BRA em vez de sacubitril/valsartana e sem iSGLT2, por razões de custo e desconhecimento anteriores.', 'Trocar losartana por sacubitril/valsartana 24/26 mg 12/12h (obtido pelo programa farmacêutico) e acrescentar dapagliflozina 10 mg. Manter carvedilol e espironolactona. Reduzir furosemida para 20 mg. K e creatinina em 2 semanas. Retorno em 3 meses.'),
  (482, 147, 11, '2023-06-13 15:20', 'retorno', 'Estou me sentindo melhor, caminho no parque', 110, 64, 62, 79.5, 'Cinco meses depois: NYHA I-II, perdeu 2,5 kg, sem edema, ortopneia ausente. NT-proBNP 640. Creatinina 1,6, K 4,8, sem hipotensão sintomática. Teve uma infecção urinária tratada em casa, resolvida, sem relação clara com a dapagliflozina; orientado quanto a higiene e hidratação. ECO: FEVE 34%. Boa adesão, esposa organiza a medicação.', 'Subir sacubitril/valsartana para 49/51 mg 12/12h se PA permitir, K e creatinina em 2 semanas. Manter os demais. Vacinação (influenza, pneumococo). Alerta de cuidados na ocorrência de febre, dor ao urinar e diminuição do volume. Retorno em 4 meses.'),
  (483, 147, 11, '2024-01-08 20:40', 'internacao', 'Febre alta, confusão e urinando muito pouco', 84, 50, 112, 81.0, 'Pcte 78a com retenção urinária há 2 dias e febre 39°C, calafrios, confusão mental e oligúria. Exame: desidratado, quente, PA 84x50, FC 112, taquipneico, estertores discretos, bexigoma palpável, sem edema. Sondagem vesical com saída de 900 mL de urina turva. Leucócitos 21.000 com desvio, PCR 260, lactato 4,6, creatinina 3,4 (basal 1,6), K 5,6, glicemia 340. Sepse de foco urinário com disfunção renal e piora da IC (ECO sem alterações significativas em relação ao último). Dapagliflozina e espironolactona em uso.', 'Suspender dapagliflozina, espironolactona, sacubitril/valsartana e furosemida (sepse, K 5,6 e LRA). Cristaloide em volume cuidadoso, meropeném e controle de foco, insulina EV. Hemoculturas e urocultura colhidas. Vaga em UTI.'),
  (484, 147, 14, '2024-01-12 07:00', 'internacao', 'Choque séptico refratário em UTI', 78, 44, 124, 85.0, 'UTI, D4 de sepse urinária. Evoluiu com choque séptico com disfunção cardíaca associada (FEVE 24% ao ECO beira-leito), IC aguda com edema pulmonar, ventilação mecânica, noradrenalina em dose crescente e dobutamina. Urocultura e hemocultura: E. coli produtora de ESBL, sensível a meropeném. Anúria, oligúria sem resposta a diurético; hemodiálise indicada, mas instabilidade hemodinâmica grave. Lactato 7,2. Discutidos com a família limites terapêuticos.', 'Manter meropeném, vasopressores e dobutamina, diálise contínua se estabilizar. Sem reanimação cardiopulmonar em caso de parada, por decisão conjunta com a família (esposa e filhos). Conforto e presença familiar liberada.');
