insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (147, '2024-01-16', 'obito', 'Óbito em UTI por choque séptico de foco urinário (E. coli ESBL) sobre ICFEr isquêmica e DRC, após retenção urinária. Havia melhorado clinicamente com terapia otimizada nos meses anteriores. Limitação de suporte discutida com a família.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (148, 'Leandro Faria Cunha', 'M', '1974-03-11', 'Ponte Nova', 'MG', 'Professor de educação física', 'Corredor amador de longa distância (maratonas), sem comorbidades. Palpitações irregulares recorrentes há 2 anos, cada vez mais frequentes. Café em excesso. Não fuma, bebe pouco. Sem hipertensão.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (485, 148, 4, '2022-08-30 11:00', 'consulta', 'Coração irregular, perdi rendimento nas corridas', 122, 76, 54, 72.0, 'Paciente de 48 anos, atleta, com episódios de palpitação irregular, 4 por mês, de 2-8 horas, com dispneia e cansaço desproporcional. Último episódio documentado em relógio com ritmo irregular e ECG de 1 derivação sugestivo de FA. ECG de repouso: bradicardia sinusal 54 bpm, sem pré-excitação. ECO: átrio esquerdo 40 mm, FEVE 62%, sem cardiopatia estrutural. Holter de 7 dias: três episódios de FA paroxística (1h30 a 6h), resposta ventricular de 110-150. TSH normal. CHA2DS2-VASc 0.', 'FA paroxística em atleta, sintomática. Suspender cafeína em excesso e energéticos. Preferência por estratégia de controle de ritmo: discutida ablação de veias pulmonares (após falha de bloqueador por bradicardia basal). Betabloqueadores evitados. Anticoagulação não indicada (CHA2DS2-VASc 0). Agendar procedimento.'),
  (486, 148, 4, '2023-01-17 07:00', 'internacao', 'Ablação de fibrilação atrial', 120, 74, 56, 72.5, 'Ablação por crioablação com balão, isolamento das quatro veias pulmonares com bloqueio de entrada e saída confirmados, sob anestesia geral e guiada por ETE (sem trombo em apêndice). Duração 110 minutos, temperatura mínima do balão -52°C. Sem lesão do nervo frênico, sem derrame pericárdico no ECO ao final. Ritmo sinusal 58 bpm. Alta no dia seguinte, assintomático, sem hematoma inguinal.', 'Rivaroxabana 20 mg com jantar por 3 meses após a ablação, omeprazol 20 mg por 4 semanas (proteção esofágica). Evitar esforço intenso por 7 dias. Retorno em 3 meses com Holter de 7 dias.'),
  (487, 148, 4, '2023-04-25 11:30', 'retorno', 'Voltei a correr e não tive mais crise', 118, 72, 52, 72.0, 'Três meses da ablação sem palpitações, voltou aos treinos de 60 km semanais e fez 21 km sem sintomas. Holter de 7 dias: ritmo sinusal em 100% do tempo, FC média 56, sem FA. Concluiu 3 meses de rivaroxabana sem sangramentos. ECO sem derrame pericárdico, átrio esquerdo 38 mm. Exame físico normal. Sem disfagia ou dor torácica.', 'Suspender rivaroxabana (CHA2DS2-VASc 0) e omeprazol. Sem antiarrítmico. Retornar em caso de palpitações. Acompanhamento anual com Holter e ECG. Liberado para esporte sem restrições.');
