insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (148, '2023-04-25', 'melhorou', 'FA paroxística sintomática em atleta, tratada com crioablação de veias pulmonares sem complicações. Três meses sem recorrência ao Holter de 7 dias, sem anticoagulante nem antiarrítmico, e retorno aos treinos de longa distância.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (149, 'Rosiane Baré Azevedo', 'F', '1981-06-24', 'Manaus', 'AM', 'Agente comunitária de saúde', 'Febre reumática na infância (aos 9 anos) sem profilaxia regular com penicilina benzatina. Sopro cardíaco descoberto aos 30 anos. Três gestações, a última há 4 anos. Sem outras doenças. Vive em área ribeirinha e usa barco para se deslocar.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (488, 149, 1, '2022-06-14 09:30', 'consulta', 'Falta de ar ao subir a rampa do porto e palpitações', 112, 70, 104, 56.0, 'Paciente de 41 anos, agente comunitária, com dispneia aos médios esforços há 8 meses, piora na última semana, tosse seca noturna e palpitações irregulares. Exame: ritmo irregular, FC 104, estalido de abertura e ruflar diastólico mitral 3+/4+ com reforço pré-sistólico ausente, hiperfonese de B1, estertores finos em bases, sem edema. ECG: FA com resposta ventricular de 104 bpm. ECO: estenose mitral reumática, área valvar 0,9 cm² (planimetria), gradiente médio 12 mmHg, átrio esquerdo 55 mm, calcificação mínima, folhetos pouco espessados, PSAP 58 mmHg, FEVE 62%. Estenose mitral reumática importante com FA.', 'Iniciar varfarina 5 mg (INR alvo 2-3; não usar DOAC na estenose mitral), metoprolol succinato 50 mg para controle de FC e furosemida 20 mg. Penicilina benzatina 1.200.000 UI IM a cada 21 dias. Solicitar ETE para avaliar viabilidade de valvuloplastia por balão. Retorno em 6 semanas com INR.'),
  (489, 149, 1, '2022-08-02 09:00', 'retorno', 'Melhorou um pouco o cansaço, mas a vida no rio é difícil', 108, 68, 76, 55.4, 'FC controlada em 76 bpm com metoprolol, dispneia NYHA II. INR 2,4 após ajustes semanais. ETE: estenose mitral com escore de Wilkins 7 (folhetos móveis, calcificação leve, subvalvar com espessamento moderado), sem trombo atrial esquerdo, regurgitação mitral discreta. Anatomia favorável a valvuloplastia mitral percutânea por balão. A região não tem hemodinâmica, e a paciente precisa de local com equipe experiente em intervenção valvar.', 'Indicada valvuloplastia mitral por balão. Contatar centro de referência em cardiologia estrutural em São Paulo por regulação (TFD, tratamento fora de domicílio). Manter varfarina, metoprolol, furosemida e penicilina benzatina. Retorno em 8 semanas.'),
  (490, 149, 1, '2022-09-27 09:20', 'retorno', 'Saiu a vaga para São Paulo', 110, 70, 78, 55.0, 'Regulação aprovou o procedimento em hospital de referência em São Paulo, com passagem aérea custeada pelo TFD e acompanhante. Estável em NYHA II, INR 2,6, sem sangramento. Sem sinais de congestão. Orientações para o procedimento. Dúvidas da paciente sobre os cuidados com os filhos pequenos durante a viagem. Documentação e exames (ETE, ECO, laudos e INR) reunidos para o encaminhamento.', 'Transferência do seguimento ao serviço de São Paulo para valvuloplastia mitral por balão e acompanhamento posterior. Manter varfarina com INR 2-3, metoprolol e penicilina benzatina. Retornar à nossa unidade apenas se necessário após a alta.');
insert into diagnostico (id_atendimento, cid, descricao) values
  (488, 'I05.0', 'Estenose mitral'),
