insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (149, '2022-09-27', 'transferido', 'Estenose mitral reumática importante (área 0,9 cm², Wilkins 7) com FA, anticoagulada com varfarina e com FC controlada. Encaminhada ao hospital de referência em São Paulo, por regulação do TFD, para valvuloplastia mitral por balão, saindo do acompanhamento local.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (150, 'Geralda Aparecida Viana Torres', 'F', '1946-01-05', 'Itajubá', 'MG', 'Aposentada (ex-merendeira)', 'HAS há 30 anos, usando anlodipino 5 mg e losartana 50 mg. Tonturas e desmaios curtos nos últimos 6 meses, um deles com queda e corte na testa. Mora com a filha. Sem diabetes.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (491, 150, 4, '2023-03-21 10:30', 'consulta', 'Desmaio sem avisar e coração devagar', 134, 70, 42, 62.0, 'Paciente de 77 anos com três episódios de síncope sem pródromo, um com trauma de face, e tontura recorrente aos esforços. Cansaço e intolerância ao exercício. Sem dor torácica. Exame: pulso regular lento, FC 42, RCR 2T BNF, sem sopros, MV+ sem RA. ECG: bradicardia sinusal 42 bpm, PR 180 ms, QRS estreito. Holter de 24h: bradicardia sinusal média 45 bpm, pausas sinusais de até 5,2 s durante o dia e episódios de FA paroxística com resposta rápida, alternando com bradicardia (síndrome taqui-bradi). TSH 2,2. Sem uso de betabloqueador, digoxina ou BCC não diidropiridínico. ECO normal, FEVE 62%.', 'Doença do nó sinusal sintomática (forma taquicardia-bradicardia): indicado marca-passo definitivo bicameral. Iniciar anticoagulação por FA (CHA2DS2-VASc 4: idade 75+ vale 2, sexo feminino, HAS): apixabana 5 mg 12/12h. Orientada a não dirigir ou subir escadas sozinha até o implante. Internação eletiva em 4 semanas.'),
  (492, 150, 4, '2023-04-18 07:30', 'internacao', 'Implante de marca-passo definitivo', 138, 72, 44, 62.0, 'Admitida para implante eletivo. Duas pausas de 4 s na telemetria na véspera, assintomática no leito. Implantado marca-passo bicameral (DDD) por acesso subclávio esquerdo, com limiares adequados (átrio 0,7 V, ventrículo 0,6 V), sem pneumotórax, controle radiológico adequado. Apixabana suspensa 24h antes e reiniciada 48 horas depois, sem hematoma de loja. Alta em 48 horas, FC 70 bpm com estimulação.', 'Retomar apixabana 5 mg 12/12h. Curativo oclusivo por 7 dias, evitar levantar o braço esquerdo por 4 semanas. Cartão de marca-passo entregue. Revisão da ferida em 7 dias e programação em 30 dias.'),
  (493, 150, 4, '2023-06-06 09:40', 'retorno', 'Nunca mais desmaiei, estou melhor de ânimo', 128, 70, 68, 63.0, 'Sem síncope ou tontura desde o implante, já caminha com a filha na praça. Ferida cicatrizada, gerador sem sinais inflamatórios. Interrogação do marca-passo: estimulação atrial 62%, ventricular 8% (condução AV preservada), limiares estáveis, bateria 100%, 2 episódios de FA paroxística (mode-switch) curtos, de 12 e 40 minutos. Sem sangramento com apixabana. PA 128x70, FC 68. Aceitou bem o aparelho: ‘parece que voltei a viver’.', 'Manter apixabana 5 mg 12/12h, anlodipino e losartana. Checagem do marca-passo em 6 meses e monitorização remota. Alertar para alarmes do equipamento e procedimentos com eletrocautério. Retorno em 6 meses.');
