insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (150, '2023-06-06', 'estavel', 'Síndrome do nó sinusal (forma taqui-bradi) com síncopes, tratada com marca-passo bicameral e anticoagulação por FA paroxística. Sem novos desmaios, boa evolução funcional, e FA curta detectada pelo aparelho. Segue em acompanhamento com monitorização remota.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (151, 'Rosângela Maria Bastos Cerqueira', 'F', '1979-03-12', 'Salvador', 'BA', 'Professora da rede estadual', 'HAS diagnosticada há 4 anos, em uso de losartana, hidroclorotiazida e anlodipino sem controle. Nega diabetes e tabagismo. Pai hipertenso, falecido de AVC aos 61 anos. Dois partos normais.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (494, 151, 2, '2022-02-08 08:30', 'consulta', 'Pressão que não baixa e cãibras nas pernas', 178, 108, 82, 79.6, 'Paciente de 42 anos com HAS há 4 anos, refere uso regular de três anti-hipertensivos, mas PA domiciliar sempre acima de 160x100. Queixa de cãibras, fraqueza em membros inferiores e noctúria 3x por noite, sem outros sintomas. Ao exame: BEG, RCR 2T BNF, sem sopros, sem sopro abdominal, pulsos simétricos. Fundo de olho com cruzamento arteriovenoso patológico. Suspeito de causa secundária pela resistência associada a hipocalemia sob tiazídico e piora dos sintomas.', 'Suspender hidroclorotiazida. Repor potássio por 3 semanas e manter losartana e anlodipino. Solicitar renina, aldosterona, ECG, ecocardiograma e creatinina. Orientada a manter ingestão normal de sal para a coleta. Retorno em 3 semanas com os exames.'),
  (495, 151, 2, '2022-03-01 09:10', 'retorno', 'Trouxe os exames', 170, 102, 78, 79.2, 'Retorna com exames. Aldosterona 34 ng/dL, atividade de renina plasmática suprimida (0,2 ng/mL/h), relação aldosterona/renina 170, com potássio 3,6 após reposição. Teste positivo para hiperaldosteronismo primário. Ecocardiograma com HVE leve e FEVE 64%. TC de adrenais: nódulo hipodenso de 1,7 cm em adrenal esquerda (HU 4), adrenal direita normal. Cãibras melhoraram com o potássio. Discutido que provavelmente é um adenoma produtor de aldosterona e que existe tratamento cirúrgico.', 'Iniciar espironolactona 50 mg/dia e suspender reposição de potássio. Controle de potássio e creatinina em 10 dias. Encaminhar para cateterismo seletivo de veias adrenais, pois a imagem isolada não define a lateralidade com segurança. Retorno em 6 semanas.'),
  (496, 151, 8, '2022-06-20 10:00', 'retorno', 'Seio dolorido e vontade de saber da cirurgia', 136, 84, 74, 77.8, 'Em uso de espironolactona 50 mg com PA em torno de 135x85 em casa, porém com mastalgia incômoda. Potássio 4,5 e creatinina 0,8. Realizado cateterismo seletivo de adrenais com lateralização para a esquerda (índice de lateralização 6,8). Quadro compatível com adenoma de Conn unilateral. Paciente deseja resolver cirurgicamente e não quer usar o remédio para sempre. Avaliação conjunta com a cirurgia, que aceita realizar adrenalectomia laparoscópica esquerda.', 'Manter espironolactona até a cirurgia, marcada para agosto. Potássio e creatinina semanais nos primeiros 10 dias após a cirurgia, pois há risco de hipercalemia por supressão da adrenal contralateral. Suspender espironolactona 1 dia antes da cirurgia. Retorno 4 semanas após a alta.'),
  (497, 151, 2, '2022-09-26 09:30', 'retorno', 'Pós-operatório, vim mostrar a pressão', 118, 74, 70, 76.5, 'Adrenalectomia esquerda laparoscópica em 22/08/2022 sem intercorrências, alta no segundo dia. Anatomopatológico: adenoma cortical de 1,8 cm. Potássio pós-operatório 4,3 e 4,6, sem hipercalemia. Em casa PA entre 112x70 e 124x78 usando apenas anlodipino 5 mg, que reduzi para suspensão experimental há 10 dias. Sem cãibras, noctúria resolvida. Ferida operatória sem sinais de infecção.', 'Suspender anlodipino com monitorização domiciliar da PA por 2 semanas. Se PA acima de 130x80 em média, retomar. Dosar aldosterona e renina em 3 meses para confirmar cura bioquímica. Manter dieta e atividade física. Retorno em 3 meses.');
