insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (151, '2023-03-14', 'melhorou', 'Cura bioquímica confirmada três meses após a adrenalectomia (aldosterona 6 ng/dL, renina normalizada, potássio 4,4). PA domiciliar média 118x74 sem nenhum anti-hipertensivo. Em seguimento anual, sem recorrência de hipocalemia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (152, 'Edmilson Aragão Tavares', 'M', '1971-06-04', 'Aracaju', 'SE', 'Motorista de ônibus urbano', 'Sem diagnósticos prévios. Fuma 10 cigarros por dia há 25 anos, bebe cerveja aos fins de semana. Sedentário, come lanche durante o turno. Pai hipertenso e mãe diabética.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (498, 152, 5, '2023-04-17 16:20', 'consulta', 'Fui doar sangue e disseram que minha pressão estava alta', 154, 96, 80, 94.3, 'Homem de 51 anos, assintomático, encaminhado do banco de sangue com PA 160x100. Trabalha em escalas de 8 horas sentado, almoça marmita com muito sal e embutidos, 2 cafés açucarados por dia. IMC 31. Ao exame: RCR 2T BNF, sem sopros, pulsos presentes, circunferência abdominal 108 cm. PA no consultório 154x96 e 150x94 em duas medidas. Estágio 1 com risco cardiovascular moderado a alto pelo tabagismo e obesidade.', 'Confirmar com MRPA por 5 dias. Solicitar perfil lipídico, glicemia, creatinina, potássio, urina tipo 1, ECG. Orientações detalhadas: reduzir sal, trocar refrigerante, caminhadas de 30 minutos, tentar parar de fumar. Sem medicação por enquanto. Retorno com MRPA e exames em 3 semanas.'),
  (499, 152, 5, '2023-05-08 16:40', 'retorno', 'Trouxe a medida de casa e os exames', 152, 94, 78, 93.8, 'MRPA com média de 148x92 mmHg em 5 dias, confirmando HAS estágio 1. Glicemia 104, LDL 148, HDL 38, triglicerídeos 210, creatinina 1,0, potássio 4,3, urina sem proteinúria. ECG sinusal sem sobrecarga. Perdeu 500 g, ainda fuma 8 cigarros ao dia. Concordou em iniciar medicação porque o trabalho exige renovação de CNH e ele teme complicações.', 'Iniciar losartana 50 mg/dia, com aumento de dose se PA persistir acima da meta. Manter MEV. Oferecido apoio para cessação do tabagismo no grupo da unidade. Estatina a discutir após reavaliação do risco. Retorno em 30 dias com MRPA.'),
  (500, 152, 5, '2023-09-25 17:00', 'retorno', 'Pressão boa, vim renovar receita', 126, 78, 72, 88.1, 'Perdeu 5,7 kg desde a primeira consulta. Trocou o lanche do posto por marmita preparada pela esposa, caminha 40 minutos 4x por semana. Parou de fumar há 2 meses com auxílio de adesivo de nicotina. Sem tosse, sem tontura. MRPA com média 124x76. Potássio 4,4, creatinina 1,0. Orgulhoso porque a CNH foi renovada sem restrição.', 'Manter losartana 50 mg/dia. Iniciar atorvastatina 20 mg à noite pelo LDL e risco. Repetir lipidograma em 3 meses. Reforçar manutenção da abstinência do cigarro. Retorno em 6 meses.');
