insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (152, '2024-03-18', 'controlado', 'Em seguimento na unidade de saúde, PA na meta (média domiciliar 122x76), abstinente do tabaco há 8 meses, peso 86 kg e LDL 84 mg/dL com atorvastatina. Mantém caminhadas e dieta com menos sal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (153, 'Zilda Pereira de Albuquerque', 'F', '1948-11-20', 'Maceió', 'AL', 'Aposentada, ex-merendeira', 'HAS há 30 anos, em uso de enalapril, hidroclorotiazida, anlodipino e atenolol. Osteoporose. Uma queda em casa há 2 meses. Mora com a filha. Nunca fumou.', 'Sulfa (erupção cutânea)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (501, 153, 1, '2022-05-10 14:30', 'consulta', 'Tontura quando levanto da cama e caí no banheiro', 132, 74, 58, 61.2, 'Idosa de 73 anos, com queda da própria altura há 2 meses e outra quase queda ontem ao levantar de madrugada para ir ao banheiro. Refere escurecimento visual ao levantar, sem síncope, sem dor torácica. Usa 4 anti-hipertensivos. PA deitada 148x80, em pé 1 minuto 112x66 e em pé 3 minutos 106x62: queda de 42 mmHg na sistólica. FC sem elevação compensatória (bradicardia com atenolol). RCR 2T BNF, sem sopros. Quadro de hipotensão ortostática por polifarmácia anti-hipertensiva, com HAS controlada em excesso.', 'Suspender atenolol e hidroclorotiazida (alergia a sulfa documentada). Manter enalapril 10 mg e anlodipino 5 mg. Orientar levantar devagar, ingerir 1,5 a 2 litros de água, elevar cabeceira e meias elásticas. ECG e Holter 24h. Retorno em 3 semanas com MRPA sentada e em pé.'),
  (502, 153, 1, '2022-06-07 15:10', 'retorno', 'Não tive mais tontura', 138, 78, 68, 61.8, 'Sem tonturas desde a retirada do atenolol e da hidroclorotiazida. Ortostatismo: deitada 142x78, em pé 3 minutos 130x74 (queda de 12 mmHg), sem sintomas. Holter com ritmo sinusal, FC média 66, sem pausas ou BAV avançado, extrassístoles raras. Filha instalou barra de apoio e tapete antiderrapante no banheiro. MRPA média 134x76. Entendeu que a meta no idoso frágil é mais flexível.', 'Manter enalapril 10 mg e anlodipino 5 mg. Meta individualizada, aceito PA sentada até 140x80 enquanto houver risco de queda. Fisioterapia para equilíbrio e reposição de vitamina D pelo clínico. Retorno em 4 meses.');
