insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (153, '2022-10-18', 'estavel', 'Sem novas quedas em 5 meses de acompanhamento. PA domiciliar entre 128x72 e 140x78 com dois anti-hipertensivos, sem sintomas ortostáticos. Segue em acompanhamento cardiológico semestral com meta individualizada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (154, 'Raimundo Nonato Sampaio Barreto', 'M', '1964-09-02', 'Feira de Santana', 'BA', 'Pedreiro', 'HAS há 15 anos, em uso de quatro medicamentos segundo a receita, mas com PA sempre alta no posto. Tabagista de 30 maços-ano. Bebe cachaça aos sábados. Obesidade grau 1. Braço largo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (503, 154, 2, '2022-08-03 10:20', 'consulta', 'Remédio nenhum controla minha pressão', 184, 104, 84, 98.0, 'Homem de 57 anos encaminhado por suposta HAS resistente: losartana 100 mg, hidroclorotiazida 25 mg, anlodipino 10 mg e metoprolol 100 mg. Interrogado, admite que toma as medicações no máximo 3 dias por semana porque ''a obra acaba tarde e eu esqueço'', e que o remédio da tarde fica na marmita. PA aferida com manguito padrão no braço de 38 cm de circunferência: 184x104. Com manguito largo: 168x98. Ao exame RCR 2T BNF, B4 presente, sem sopros abdominais. Quadro sugestivo de pseudorresistência por má adesão e técnica de aferição inadequada.', 'Simplificar o esquema: comprimido único de losartana 100 mg + hidroclorotiazida 25 mg pela manhã, mais anlodipino 10 mg no mesmo horário. Suspender metoprolol sem indicação. Caixa organizadora semanal e alarme no celular. MAPA 24h, creatinina, potássio, ECG e ecocardiograma. Retorno em 4 semanas.'),
  (504, 154, 2, '2022-09-14 10:00', 'retorno', 'Trouxe o resultado da MAPA', 142, 88, 76, 97.2, 'Refere que agora toma tudo de manhã, antes de ir para a obra, e falhou apenas 2 vezes. MAPA 24h com manguito largo: média de vigília 138x86, sono 124x74, descenso preservado, sem sinal de resistência verdadeira. Potássio 4,2. Ecocardiograma com HVE concêntrica leve e FEVE 62%. Confirma-se pseudorresistência: com adesão e manguito adequado, a PA caiu 40 mmHg sem acréscimo de drogas.', 'Manter o esquema simplificado de manhã. Não é necessário espironolactona neste momento. Orientar redução de sal e do álcool. Utilizar sempre manguito largo na unidade de saúde (carta explicativa entregue). Retorno em 8 semanas com MRPA.'),
  (505, 154, 2, '2022-11-23 10:30', 'retorno', 'Pressão boa em casa', 128, 80, 72, 94.6, 'Tomou todos os dias, conta que a esposa confere a caixinha. MRPA com média 126x78. Perdeu 2,6 kg, reduziu a cachaça para uma dose no sábado. Ainda fuma 10 cigarros ao dia, recusa tratamento por ora. Sem edema de tornozelos relevante. Potássio 4,3 e creatinina 1,1.', 'Seguir esquema. Reavaliar cessação do tabagismo a cada consulta. Perfil lipídico e iniciar estatina se LDL acima do alvo. Retorno em 4 meses.');
