insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (154, '2023-03-29', 'controlado', 'Pseudorresistência resolvida com simplificação do esquema, adesão supervisionada pela esposa e uso de manguito adequado. PA em consultório 126x78, sem necessidade de quarto fármaco. Segue fumando e em acompanhamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (155, 'Marilene Cristina Vasconcelos Dantas', 'F', '1976-01-30', 'Lagarto', 'SE', 'Cabeleireira autônoma', 'HAS há 10 anos, abandonou o tratamento há 1 ano por achar que a pressão tinha normalizado. Sem outras doenças conhecidas. Não fuma. Mãe com AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (506, 155, 6, '2023-02-18 02:40', 'pronto_socorro', 'Dor de cabeça muito forte, vômito e estou confusa', 238, 142, 98, 74.0, 'Mulher de 47 anos trazida pelo marido com cefaleia occipital intensa há 2 dias, náuseas, vômitos, turvação visual e sonolência progressiva. Pcte desorientada no tempo, Glasgow 14, sem déficit focal, pupilas isocóricas, rigidez de nuca ausente. Fundo de olho com papiledema bilateral e hemorragias em chama de vela. PA 238x142 em ambos os braços. TC de crânio sem sangramento. HD: encefalopatia hipertensiva. Creatinina 1,9 e urina com proteinúria.', 'Transferir para UTI. Iniciar nitroprussiato de sódio em bomba de infusão com meta de redução de 20 a 25% da PA média na primeira hora. Manter em decúbito elevado, monitorização contínua, solicitar RM de crânio. Evitar quedas bruscas da PA. Avaliação da UTI e da neurologia.'),
  (507, 155, 14, '2023-02-18 07:30', 'internacao', 'Cefaleia melhorando, ainda sonolenta', 170, 102, 84, 74.0, 'UTI D0. Nitroprussiato com queda gradual da PA para 170x102 em 5 horas, sem hipotensão. Glasgow 15 após 4 horas, cefaleia 3/10, visão melhorando. RM de encéfalo com hipersinal em FLAIR em regiões parieto-occipitais bilaterais compatível com PRES (síndrome da encefalopatia posterior reversível). Troponina negativa, creatinina 1,7. Iniciadas medicações orais e desmame do vasodilatador endovenoso.', 'Associar anlodipino 10 mg e losartana 50 mg 12/12h com retirada progressiva do nitroprussiato. Meta de 160x100 nas primeiras 24h, depois 140x90 em 1 semana. Avaliar causa secundária: renina e aldosterona, metanefrinas, Doppler de artérias renais, ultrassom de rins e vias. Alta da UTI em 48 horas se estável.'),
  (508, 155, 13, '2023-03-14 09:00', 'retorno', 'Retorno após alta, sem dor de cabeça', 144, 90, 80, 73.4, 'Alta hospitalar em 7 dias. Sem convulsões, sem déficits, visão normalizada. Exame neurológico normal. Fundo de olho com papiledema resolvido. RM de controle: regressão completa das alterações do PRES. Doppler de artérias renais normal, metanefrinas urinárias normais e razão aldosterona/renina de 12, afastando causas secundárias mais comuns. Creatinina 1,2, proteinúria em recuperação. Conta que ''achei que a pressão tinha ido embora'' e que se assustou muito.', 'Alta da neurologia, sem necessidade de anticonvulsivante. Manter terapia anti-hipertensiva com reforço de adesão. Retornar ao cardiologista em 2 semanas. Orientado que o tratamento é para a vida toda e a falta de sintomas não significa controle.'),
  (509, 155, 1, '2023-04-04 14:20', 'retorno', 'Vim ver minha pressão', 128, 78, 74, 72.9, 'Em uso regular de anlodipino e losartana, com alarme no celular e cartela de cada dia. PA domiciliar média 126x78. Sem cefaleia, sem edema. Creatinina 1,0, potássio 4,4, relação albumina/creatinina 28 mg/g (queda). Ecocardiograma com HVE moderada e FEVE 60%. Compreendeu a gravidade do episódio e pediu que a filha acompanhe as consultas.', 'Manter esquema atual. Repetir albuminúria em 6 meses. MRPA mensal. Retorno em 3 meses. Orientada a procurar o PS se PA acima de 180x110 com sintomas.');
