insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (155, '2023-04-04', 'melhorou', 'Recuperação completa do episódio de encefalopatia hipertensiva sem sequelas neurológicas. PA em torno de 126x78 com anlodipino e losartana, boa adesão após o susto, causas secundárias investigadas e negativas. Segue em acompanhamento trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (156, 'Hamilton Seiji Yamashita', 'M', '1961-10-08', 'Vitória da Conquista', 'BA', 'Proprietário de loja de ferragens', 'HAS e dislipidemia em uso de losartana e sinvastatina. Ex-tabagista (parou há 8 anos, 25 maços-ano). Irmão com IAM aos 54 anos. Sedentário.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (510, 156, 1, '2022-07-12 15:00', 'consulta', 'Aperto no peito quando subo a ladeira da loja', 144, 86, 78, 86.5, 'Paciente de 60 anos com dor retroesternal em aperto, irradiada para mandíbula, desencadeada por esforço (subir ladeira, carregar caixas) há 6 semanas, aliviada com repouso em 3 a 5 minutos. Sem dispneia em repouso nem síncope. Angina típica classe CCS II. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA, pulsos simétricos. ECG de repouso sem alterações. Risco alto de DAC pelo quadro típico, idade, HAS, dislipidemia, tabagismo prévio e história familiar.', 'Iniciar AAS 100 mg, metoprolol succinato 50 mg, atorvastatina 40 mg (suspender sinvastatina) e nitrato sublingual SN. Solicitar teste ergométrico ou cintilografia, perfil lipídico e HbA1c. Orientado a procurar PS se dor em repouso ou com duração acima de 20 minutos. Retorno em 3 semanas.'),
  (511, 156, 10, '2022-08-02 15:30', 'retorno', 'Teste de esteira deu alterado', 130, 80, 62, 86.0, 'Teste ergométrico interrompido aos 6 minutos por angina e infradesnivelamento de ST de 2,5 mm em V4-V6, alto risco pelo escore de Duke (-14). Ainda com dor 2 vezes por semana mesmo com metoprolol. Ecocardiograma com FEVE 58% sem alteração segmentar. Avaliado com a hemodinâmica, indicada coronariografia.', 'Coronariografia por via radial na próxima semana. Manter AAS, estatina e betabloqueador. Suspender losartana na manhã do exame para reduzir risco de nefropatia por contraste. Explicado sobre possível angioplastia no mesmo ato.'),
  (512, 156, 10, '2022-08-11 07:50', 'internacao', 'Cateterismo agendado', 138, 82, 60, 86.0, 'Coronariografia radial direita: lesão de 90% em descendente anterior proximal, lesão de 60% em coronária direita média, circunflexa sem lesões significativas. Realizada angioplastia da DA com implante de um stent farmacológico 3,0 x 24 mm com bom resultado angiográfico, fluxo TIMI 3. Sem complicações. Paciente sem dor após o procedimento. Mantida a lesão da CD para tratamento clínico.', 'Iniciar clopidogrel 75 mg por 6 meses associado ao AAS. Alta no dia seguinte. Manter betabloqueador e estatina em dose alta, atorvastatina 80 mg. Reabilitação cardiovascular, parar de fumar de vez (recaída ocasional relatada). Retorno em 30 dias.'),
  (513, 156, 1, '2023-02-21 15:10', 'retorno', 'Sem dor no peito, vim para o retorno', 124, 76, 58, 82.4, 'Seis meses após a angioplastia da DA, assintomático, caminha 40 minutos 5x por semana no programa de reabilitação. Perdeu 3,6 kg. LDL 54 mg/dL com atorvastatina 80 mg. Sem sangramentos. PA 124x76, FC 58. Último cigarro em setembro, mantém abstinência. Completou clopidogrel por 6 meses.', 'Suspender clopidogrel e manter AAS 100 mg indefinidamente. Manter atorvastatina 80, metoprolol e losartana. Cintilografia miocárdica anual para avaliar lesão residual da CD. Retorno em 6 meses.');
