insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (156, '2023-02-21', 'controlado', 'Doença coronariana estável após angioplastia com stent na DA, sem angina, LDL na meta e PA 124x76. Segue em prevenção secundária com AAS, estatina em dose alta e betabloqueador, mantendo reabilitação e abstinência do tabaco.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (157, 'Walter Henrique Kowalski', 'M', '1958-04-25', 'Curitiba', 'PR', 'Aposentado, ex-operário metalúrgico', 'HAS e DM2 há 15 anos, em uso irregular de metformina e enalapril. Tabagista ativo, 40 maços-ano. Hipercolesterolemia sem tratamento. Mora sozinho, filhos em outra cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (514, 157, 6, '2021-11-20 05:10', 'pronto_socorro', 'Dor forte no peito, suando frio', 98, 64, 108, 88.5, 'Homem de 63 anos com dor precordial em aperto, intensa, irradiada para braço esquerdo, iniciada há 2h30, com sudorese fria e náuseas. Ao exame: REG, pálido, sudoreico, PA 98x64, FC 108, estertores finos em bases pulmonares (Killip II). ECG com supradesnivelamento de ST de 4 mm de V1 a V5 e DI/aVL. HD: IAMCSST de parede anterior extensa. Troponina ultrassensível 1.850 ng/L. Acionada a hemodinâmica.', 'AAS 300 mg, ticagrelor 180 mg, heparina não fracionada. Encaminhar à angioplastia primária imediata, janela de 3 horas. Oxigênio se SatO2 menor que 90%. Evitar betabloqueador pelo Killip II e hipotensão. Internar em UTI após o procedimento.'),
  (515, 157, 14, '2021-11-22 09:00', 'internacao', 'Cansaço aos mínimos esforços na UTI', 102, 66, 96, 88.5, 'UTI D2. Angioplastia primária com stent farmacológico em DA proximal totalmente ocluída; doença multiarterial associada (CD 80%, Cx 70%). Evolui com dispneia, necessidade de furosemida endovenosa e dobutamina por 24 horas por baixo débito. Ecocardiograma com acinesia anterior extensa e apical, FEVE 28%, sem trombo. BNP 1.420. Desmamado de inotrópico. Creatinina 1,5.', 'Iniciar carvedilol 3,125 mg 12/12h assim que estabilizar, enalapril 2,5 mg 12/12h com titulação, espironolactona 25 mg e dapagliflozina 10 mg com cuidado por glicemia e rins. Dupla antiagregação por 12 meses. Programar revascularização das demais artérias de forma eletiva. Alta para enfermaria quando sem inotrópico por 48h.'),
  (516, 157, 11, '2022-01-18 10:30', 'retorno', 'Falta de ar aos médios esforços', 108, 68, 74, 84.0, 'Alta hospitalar há 7 semanas. Mantém dispneia NYHA II-III, sem ortopneia, sem edema. Parou de fumar após o infarto, usa adesivo. Em uso de carvedilol 6,25 mg 12/12h, enalapril 5 mg 12/12h, espironolactona 25 mg e dapagliflozina 10 mg. Potássio 4,9 e creatinina 1,3. ECO de controle ainda com FEVE 30%. A revascularização das outras artérias foi adiada pois ele tem receio da cirurgia.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36 horas de intervalo da última dose do IECA. Repetir potássio e creatinina em 7 dias. Manter demais pilares. Discutir CDI se FEVE menor que 35% após 3 meses de terapia otimizada. Reforçar a necessidade da revascularização das lesões residuais.'),
  (517, 157, 6, '2022-04-09 23:50', 'pronto_socorro', 'Desmaiei em casa e minha vizinha chamou o SAMU', 86, 54, 142, 85.0, 'Trazido pelo SAMU após síncope em domicílio. À chegada, taquicardia regular de QRS largo a 142 bpm, PA 86x54, sudorese, rebaixamento de consciência leve. Cardioversão elétrica sincronizada 100 J com reversão a ritmo sinusal. Pós-cardioversão ECG com onda Q anterior, QTc 470. TV monomórfica sustentada em cardiopatia isquêmica com FEVE de 30%. Eletrólitos normais, troponina discretamente elevada sem nova isquemia. Internado na UTI.', 'Amiodarona endovenosa e depois oral. Manter terapia da IC. Encaminhar para implante de CDI em prevenção secundária. Interromper sacubitril/valsartana se hipotensão persistente. Avaliação da arritmologia e cateterismo na internação.');
