insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (157, '2022-04-21', 'obito', 'Durante a internação aguardando implante de CDI, apresentou nova TV seguida de fibrilação ventricular no 12º dia, sem resposta a manobras de reanimação por 40 minutos. Óbito por morte súbita arrítmica em cardiomiopatia isquêmica com FEVE 30%, após IAM anterior extenso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (158, 'Denise Aparecida Moura Falcão', 'F', '1955-12-14', 'Salvador', 'BA', 'Aposentada, ex-auxiliar de enfermagem', 'HAS há 25 anos, DM2 há 12 anos, IAM prévio em 2016 com angioplastia da CD. IC com FEVE reduzida diagnosticada em 2020. Em uso de losartana, carvedilol, furosemida, metformina. Obesidade.', 'Dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (518, 158, 11, '2022-09-06 09:00', 'consulta', 'Inchaço nas pernas e cansaço para tomar banho', 134, 82, 82, 86.3, 'Paciente de 66 anos com ICFEr isquêmica, NYHA III, com piora há 3 semanas: ortopneia com dois travesseiros, edema de MMII 2+/4+, ganho de 3 kg. Sem dor torácica. Usa losartana 50 mg 12/12h, carvedilol 6,25 mg 12/12h, furosemida 40 mg. Ao exame: BEG, turgência jugular a 45 graus, RCR 3T, estertores nas bases, hepatomegalia dolorosa leve. ECO: FEVE 32%. NT-proBNP 3.280. Potássio 4,5, creatinina 1,2 (TFGe 48). Ainda sem espironolactona nem iSGLT2.', 'Furosemida 40 mg 2x/dia por 5 dias. Trocar losartana por sacubitril/valsartana 24/26 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Aumentar carvedilol para 12,5 mg 12/12h assim que euvolêmica. Peso diário, restrição de sal e de líquidos a 1,5 L. Retorno em 2 semanas com potássio e creatinina.'),
  (519, 158, 11, '2022-09-22 09:20', 'retorno', 'Estou respirando melhor', 112, 70, 70, 82.1, 'Perdeu 4,2 kg, edema desapareceu, dorme com um travesseiro. Sem tontura importante, sem queixas urinárias, refere mais diurese. Potássio 5,1 (limite) e creatinina 1,3. Sem hipoglicemia. Ao exame: sem estase jugular, MV+ sem RA, RCR 2T com B3 discreta. PA 112x70, boa tolerância. Faz as refeições com a filha que controla o sal. Glicemias domiciliares entre 110 e 160.', 'Manter sacubitril/valsartana 24/26 mg e espironolactona. Evitar banana, sal light e anti-inflamatórios. Repetir potássio em 10 dias; se acima de 5,5, reduzir espironolactona para 12,5 mg. Aumentar carvedilol para 12,5 mg 12/12h. Reduzir furosemida para 20 mg. Retorno em 6 semanas.'),
  (520, 158, 11, '2023-04-13 09:40', 'retorno', 'Estou bem, subo a escada de casa', 118, 72, 64, 79.8, 'Sete meses depois, NYHA I-II, sem internações, peso estável em 79,8 kg. Tolerou aumento de carvedilol. Potássio 4,8, creatinina 1,2. ECO de controle com FEVE 42%, melhora do remodelamento. NT-proBNP 780. HbA1c 6,9% sem metformina na dose anterior, que foi reduzida pelo clínico. Voltou a caminhar 30 minutos na orla três vezes por semana. Conta que ''a dapagliflozina fez eu perder o inchaço e a barriga''.', 'Manter os quatro pilares nas doses atuais. Tentar subir sacubitril/valsartana para 49/51 mg se PA permitir, reavaliar em 6 semanas. Vacinas de gripe e pneumococo em dia. Retorno em 3 meses.');
