insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (158, '2023-04-13', 'melhorou', 'Otimização dos quatro pilares da IC levou a melhora funcional de NYHA III para I-II e recuperação parcial da fração de ejeção (de 32% para 42%). Sem internações no último ano. Segue em acompanhamento trimestral na clínica de insuficiência cardíaca.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (159, 'Adailton Cavalcante Neves', 'M', '1952-07-16', 'Juazeiro', 'BA', 'Agricultor aposentado (fruticultor)', 'HAS há 20 anos em uso de enalapril e hidroclorotiazida. Etilista social. Sem diabetes. Dois irmãos com AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (521, 159, 4, '2021-03-09 08:40', 'consulta', 'Coração disparando, sensação de peso no peito', 152, 90, 128, 78.0, 'Homem de 68 anos com palpitações irregulares há 4 dias, cansaço e discreta tontura, sem síncope. ECG: fibrilação atrial com resposta ventricular média de 128 bpm. Ao exame: pulso irregular, RCR irregular em 2T, sem sopros, MV+ sem RA, sem edema. Ecocardiograma: átrio esquerdo 46 mm, FEVE 58%, sem valvopatia significativa. TSH normal. CHA2DS2-VASc 2 (idade 65 a 74 anos e HAS), com indicação de anticoagulação.', 'Iniciar rivaroxabana 20 mg ao jantar (ClCr 72 mL/min) e metoprolol succinato 50 mg para controle de frequência. Se persistir sintomático, cardioversão eletiva após 3 semanas de anticoagulação. Esclarecido sobre risco de AVC e sangramento. Retorno em 4 semanas.'),
  (522, 159, 4, '2021-04-06 08:50', 'retorno', 'Passou a falta de ar, mas ainda sinto o coração irregular', 138, 84, 92, 77.5, 'Após 4 semanas de rivaroxabana sem falhas, mantém FA com FC 92 bpm, mas persiste cansaço aos esforços. Sem sangramentos. Conta que não quer ''viver de remédio'' e pergunta se pode voltar ao ritmo normal. Candidato a cardioversão elétrica eletiva.', 'Cardioversão elétrica eletiva sob sedação na próxima semana, mantendo rivaroxabana sem interrupção. Após o procedimento, manter anticoagulante por no mínimo 4 semanas e, dado o escore, a longo prazo. Metoprolol mantido.'),
  (523, 159, 4, '2021-05-18 09:10', 'retorno', 'Voltei ao normal depois do choque', 130, 80, 66, 77.0, 'Cardioversão elétrica 150 J bifásica com reversão para ritmo sinusal em 1 choque. ECG de hoje: ritmo sinusal, FC 66. Sem palpitações. Refere que agora ele ''se sente bem'' e, por isso, já não vê motivo para tomar a rivaroxabana: ficou sem o remédio por 5 dias. Reforçado que o risco de AVC persiste mesmo em ritmo sinusal.', 'Manter rivaroxabana 20 mg e metoprolol. Explicado novamente o risco de AVC, citando os irmãos que tiveram. Retorno em 3 meses com ECG e hemograma. Entregue receita para 90 dias.');
