insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (159, '2022-02-10', 'abandonou', 'Não compareceu ao retorno de agosto de 2021 nem às duas tentativas de contato telefônico. Em contato com o filho, soube-se que parou a rivaroxabana por conta própria por achar que estava curado após a cardioversão. Sem registro de AVC até a data da última tentativa de contato.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (160, 'Josué Pereira dos Anjos', 'M', '1963-02-17', 'Livramento de Nossa Senhora', 'BA', 'Lavrador aposentado', 'Nasceu e viveu em casa de taipa no interior. Doença de Chagas diagnosticada em 2012, bloqueio de ramo direito conhecido. Etilista pesado até 2018. Hipertenso leve, sem tratamento regular.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (524, 160, 11, '2021-05-25 08:30', 'consulta', 'Cansaço para andar e inchaço nos pés', 108, 70, 56, 64.2, 'Homem de 58 anos com Chagas crônica e dispneia NYHA III há 8 meses, ortopneia, edema vespertino de MMII 2+/4+. Ao exame: emagrecido, RCR 2T BNF, B3, estertores em bases, hepatomegalia. ECG: bloqueio de ramo direito + bloqueio divisional anterossuperior esquerdo, extrassístoles ventriculares frequentes. ECO: dilatação de VE, FEVE 34%, aneurisma apical sem trombo. Holter: 5.800 ESV/24h e 3 episódios de TVNS. Cardiopatia chagásica com IC e arritmia ventricular. Sem indicação de benznidazol por cardiopatia estabelecida.', 'Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h com titulação lenta, espironolactona 25 mg, dapagliflozina 10 mg e furosemida 40 mg. Amiodarona 200 mg/dia pela TVNS. Orientada restrição de sal e peso diário. Solicitar ressonância cardíaca. Retorno em 3 semanas.'),
  (525, 160, 11, '2021-09-14 09:00', 'retorno', 'Melhorei do inchaço, mas tenho tontura', 100, 64, 50, 62.0, 'Melhora do edema e da dispneia, NYHA II. Queixa tonturas ao levantar e uma pré-síncope na roça. FC 50 bpm em repouso. Holter: FC mínima 38 bpm com pausas de até 2,6 segundos à noite e BAV 2:1 transitório, além de 12 episódios de TVNS. Efeito somado da amiodarona e do carvedilol sobre doença de condução chagásica. FEVE 33%.', 'Suspender amiodarona e reduzir carvedilol para 3,125 mg 1x/dia. Avaliação da arritmologia para marca-passo e CDI. Manter enalapril, espironolactona e dapagliflozina. Orientado a não conduzir motocicleta. Retorno em 1 mês.'),
  (526, 160, 4, '2022-02-08 10:15', 'internacao', 'Implante de aparelho no coração', 104, 66, 48, 62.8, 'Internado eletivamente para implante de CDI com função de marca-passo bicameral por doença do sistema de condução (BAV 2:1 intermitente), TVNS recorrente e FEVE 33%. Realizado sem intercorrências por punção subclávia esquerda, limiares adequados, sem pneumotórax na radiografia de controle. Teste de desfibrilação satisfatório. Alta no dia seguinte, ferida limpa. Paciente e a esposa foram orientados sobre os cuidados com o gerador.', 'Programar CDI com zona de TV de 180 bpm. Manter terapia da IC. Retornar para revisão da ferida em 10 dias e checagem do dispositivo em 30 dias. Evitar esforço com o braço esquerdo por 6 semanas. Cartão de identificação do aparelho entregue.'),
  (527, 160, 6, '2023-08-30 21:40', 'pronto_socorro', 'Falta de ar de repente e choque no peito', 92, 60, 112, 66.0, 'Retorna com dispneia grave há 2 dias, ortopneia, edema até a raiz da coxa e um choque do CDI em casa. Parou a furosemida e a dapagliflozina há 3 semanas por falta na unidade de saúde e custo. Ao exame: REG, taquipneico, SatO2 88% em ar ambiente, estase jugular a 60 graus, estertores até ápices, hepatomegalia. BNP 2.900. Interrogação do CDI: 1 terapia apropriada de ATP para TV rápida. FEVE 24%. Creatinina 1,8.', 'Furosemida endovenosa 80 mg em bolus e nitroglicerina conforme PA. Oxigênio suplementar. Internar em UTI. Reinstituir iSGLT2 após estabilização. Avaliação da equipe de IC avançada para possível terapia de resgate e discussão de transplante cardíaco.');
