insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (160, '2023-09-20', 'piorou', 'Progressão da cardiopatia chagásica para IC refratária (FEVE 24%, NYHA III-IV) após a descompensação por falta de medicamentos. Alta da UTI com ajuste de diuréticos, em seguimento na clínica de IC avançada e lista de avaliação para transplante em andamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (161, 'Josefa Gomes de Andrade Pinto', 'F', '1966-05-09', 'Estância', 'SE', 'Costureira em facção de confecção', 'HAS há 10 anos e DM2 há 7 anos, em uso de losartana 50 mg uma vez ao dia, anlodipino 5 mg e metformina 850 mg 12/12h. Nunca fumou. Sedentária, passa 9 horas sentada na máquina. Mãe com insuficiência renal e diálise.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (528, 161, 1, '2022-03-15 10:10', 'consulta', 'Médica do posto disse que achou proteína na urina', 152, 90, 76, 81.0, 'Mulher de 55 anos, HAS + DM2, encaminhada por albuminúria. Assintomática. Medidas domiciliares em torno de 150x90. Ao exame: obesa (IMC 33), RCR 2T BNF, sem sopros, sem edema, pulsos periféricos presentes. Relação albumina/creatinina urinária 480 mg/g, confirmada em segunda amostra. Creatinina 1,0 (TFGe 64). Fundo de olho com retinopatia leve. HbA1c 8,1%. Paciente com HAS estágio 2 não controlada, DM2 e lesão de órgão-alvo renal (albuminúria moderadamente aumentada a grave).', 'Aumentar losartana para 100 mg/dia (dose máxima) e manter anlodipino 5 mg. Iniciar empagliflozina 10 mg pelo benefício renal e cardiovascular. Orientada sobre higiene genital. Repetir potássio e creatinina em 2 semanas. Atorvastatina 40 mg pelo alto risco. Encaminhar à nefrologia para ciência do caso. Retorno em 6 semanas.'),
  (529, 161, 8, '2022-06-07 10:30', 'retorno', 'Vim para ver os rins', 132, 80, 74, 79.2, 'Retorno com melhora da PA domiciliar (média 130x78), perdeu 1,8 kg. Creatinina subiu discretamente para 1,2 (TFGe 52), o que é esperado após iSGLT2 e dose máxima de BRA; potássio 4,7. Albuminúria 210 mg/g. Sem queixas urinárias genitais. Ultrassom de rins com dimensões normais e ecogenicidade discretamente aumentada. Nefrologia concorda com tratamento atual e sem indicação de investigação adicional.', 'Manter losartana 100 mg, anlodipino 5 mg e empagliflozina. Evitar anti-inflamatórios e orientada a suspender iSGLT2 em dias de vômito ou diarreia (sick day). Repetir albuminúria e creatinina em 4 meses. Considerar finerenona se albuminúria persistir acima de 30 mg/g com potássio adequado.'),
  (530, 161, 1, '2023-01-24 10:00', 'retorno', 'Trouxe os exames de rotina', 126, 76, 72, 77.5, 'PA na meta tanto no consultório quanto no domicílio (média 124x76). Albuminúria caiu para 95 mg/g, creatinina estável em 1,2. HbA1c 7,0%, LDL 62. Perdeu 3,5 kg no total e agora faz pausas de 5 minutos a cada hora de costura para se alongar. Sem infecção urinária ou genital. Concluiu que ''o remédio novo ajudou até na diabetes''.', 'Manter o esquema. Manter controle da albuminúria a cada 6 meses. Consulta oftalmológica anual. Retorno em 6 meses com exames. Orientada a manter peso e atividade física.');
