insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (161, '2023-01-24', 'controlado', 'PA na meta (124x76), albuminúria reduzida de 480 para 95 mg/g e função renal estável com BRA em dose máxima e iSGLT2. Diabetes com HbA1c 7,0%. Segue em acompanhamento semestral com nefrologia e cardiologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (162, 'Cláudio Roberto Bomfim Silveira', 'M', '1974-08-30', 'Santo Amaro', 'BA', 'Vendedor externo de autopeças', 'HAS há 3 anos em uso de losartana, hidroclorotiazida e anlodipino. Obesidade grau II, pré-diabetes. Refeições em restaurantes de estrada e muita cerveja. Pai falecido de infarto aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (531, 162, 2, '2022-02-22 18:00', 'consulta', 'Quero emagrecer e tomar menos remédio', 148, 94, 80, 112.4, 'Paciente de 47 anos, IMC 37, três anti-hipertensivos com PA ainda de 148x94 e tornozelos edemaciados (edema 1+/4+ por anlodipino 10 mg). Circunferência abdominal 124 cm. Glicemia 112, HbA1c 5,9%, LDL 138, triglicerídeos 260, ácido úrico 8,2, creatinina 1,0. Está disposto a mudar de estilo de vida pois quer ver os filhos crescerem. Triagem de apneia negativa (STOP-Bang 3, sem sonolência).', 'Meta de perda de 10% do peso em 6 meses: nutricionista, dieta hipossódica, parar a cerveja durante a semana, caminhada de 40 minutos 5x por semana. Manter os 3 fármacos por ora. Aferir PA em casa. Retorno em 3 meses.'),
  (532, 162, 2, '2022-08-30 18:20', 'retorno', 'Estou me sentindo meio fraco e tonto', 110, 68, 68, 98.7, 'Perdeu 13,7 kg em 6 meses, caminha todo dia e cortou refrigerante e cerveja. Passou a ter tontura leve ao levantar e fraqueza no fim da tarde. PA domiciliar média 112x68 com os mesmos três fármacos. Edema de tornozelo resolvido. Sódio 135, potássio 3,6 e ácido úrico 6,4. Glicemia de jejum 94. Hipotensão sintomática por excesso de tratamento após perda de peso.', 'Suspender hidroclorotiazida e reduzir anlodipino para 5 mg. Manter losartana 100 mg/dia. Hidratar bem. Repetir eletrólitos em 15 dias. Parabenizado. Retorno em 8 semanas com MRPA.'),
  (533, 162, 2, '2023-04-18 18:10', 'retorno', 'Pressão ótima, posso parar mais remédio?', 118, 72, 64, 89.5, 'Perdeu mais 9 kg, total de 22,9 kg (20% do peso inicial). PA domiciliar média 116x72 com losartana 100 + anlodipino 5. Sem sintomas. Triglicerídeos 118, LDL 96, HbA1c 5,4%. Faz musculação e corre 5 km nos fins de semana. Passou a levar marmita nas viagens. Questiona se pode ficar sem medicação.', 'Suspender anlodipino. Manter losartana 50 mg/dia com monitorização rigorosa por MRPA. Se PA acima de 130x80 retornar à dose anterior. Orientado que a hipertensão pode reaparecer se recuperar o peso. Retorno em 3 meses com MRPA.');
