insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (162, '2023-08-15', 'controlado', 'Com perda de 23 kg e mudanças de estilo de vida, passou de três anti-hipertensivos para losartana 50 mg isolada, com MRPA média de 120x74. Pré-diabetes revertida. Mantém acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (163, 'Benedita Santana Rodrigues', 'F', '1961-03-22', 'Alagoinhas', 'BA', 'Cozinheira de escola municipal', 'HAS há 18 anos. Em uso de losartana 100 mg/dia, clortalidona 25 mg e anlodipino 10 mg há 2 anos, sem atingir a meta. Obesidade. Não fuma, não bebe. Irmã com doença renal crônica.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (534, 163, 1, '2021-10-19 09:30', 'consulta', 'Três remédios e a pressão nunca abaixa de 160', 168, 98, 70, 88.0, 'Mulher de 60 anos com HAS em uso de três classes em doses plenas, inclusive diurético tiazídico-símile, e PA de consultório 168x98. Adesão checada: caixa de comprimidos com contagem correta, farmácia popular com retiradas regulares. Manguito adequado (braço 33 cm). Sem uso de AINE, antigripal ou regaliz. Ao exame: RCR 2T BNF, B4, sem sopros abdominais, sem edema. Suspeita de hipertensão resistente verdadeira. Potássio 4,0, creatinina 0,9, TSH normal.', 'Solicitar MAPA 24h e MRPA para excluir efeito do avental branco, dosagem de aldosterona e renina, Doppler de artérias renais, ECO e polissonografia se MAPA confirmar. Manter esquema atual. Orientações de dieta com baixo sódio. Retorno com exames em 3 semanas.'),
  (535, 163, 1, '2021-11-09 09:20', 'retorno', 'Trouxe todos os exames', 164, 96, 72, 87.6, 'MAPA 24h com médias de vigília 158x94, sono 148x86 (descenso ausente): resistência verdadeira, sem avental branco. Aldosterona 9 ng/dL com renina normal (relação 8), afastando aldosteronismo primário. Doppler de artérias renais sem estenose. ECO com HVE concêntrica moderada, FEVE 62%. Polissonografia sem apneia significativa (IAH 6). Albuminúria 38 mg/g. Excluídas as causas secundárias comuns.', 'Associar espironolactona 25 mg ao esquema (quarto fármaco). Dosar potássio e creatinina em 1 semana e 4 semanas, atenção para hipercalemia em uso de BRA. Manter dieta com menos sal. Retorno em 4 semanas.'),
  (536, 163, 1, '2021-12-14 09:40', 'retorno', 'Pressão baixou, mas sinto fraqueza', 134, 80, 68, 86.0, 'Com espironolactona 25 mg, PA domiciliar média 132x80. Queixa fraqueza discreta nas pernas. Potássio 5,4 (limítrofe) e creatinina 1,1 (TFGe 56). Não usa sal light nem AINE. Refere ter exagerado em suco de laranja e banana todos os dias ''porque faz bem''. Orientada sobre dieta. Sem alterações no ECG.', 'Manter espironolactona, mas suspender o sal de potássio e reduzir alimentos ricos em potássio. Repetir potássio em 7 dias. Se acima de 5,5, reduzir losartana para 50 mg. Não aumentar espironolactona agora. Retorno em 6 semanas.'),
  (537, 163, 1, '2022-03-08 09:50', 'retorno', 'Vim receber o resultado e renovar receita', 126, 76, 66, 84.1, 'Na dieta ajustada, potássio caiu para 4,8 e creatinina 1,0. PA de consultório 126x76 e MRPA com média 124x76, primeira vez na meta em 18 anos de HAS. Sem ginecomastia ou irregularidade menstrual (pós-menopausa). Perdeu 3,9 kg. Albuminúria 14 mg/g. Disse que sente ''a cabeça mais leve''.', 'Manter os quatro fármacos. Controle de potássio e creatinina a cada 3 meses. Orientada a procurar a unidade se vômitos ou diarreia prolongados (suspender espironolactona e losartana nesses dias). Retorno em 4 meses.');
