insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (163, '2022-10-04', 'controlado', 'Hipertensão resistente verdadeira, confirmada por MAPA e sem causa secundária, controlada com quatro fármacos incluindo espironolactona 25 mg. Hipercalemia leve corrigida com ajuste alimentar. PA domiciliar média 124x76 e função renal estável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (164, 'Ubiratan Lopes de Siqueira', 'M', '1970-01-19', 'Camaçari', 'BA', 'Vigilante noturno', 'HAS há 6 anos com PA difícil de controlar, em uso de losartana, anlodipino e hidroclorotiazida. Obesidade grau II, ronco alto relatado pela esposa. Dorme mal, cochila no trabalho. Fuma 5 cigarros por dia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (538, 164, 2, '2022-05-17 08:20', 'consulta', 'Dor de cabeça pela manhã e muito sono durante o dia', 164, 104, 82, 118.6, 'Homem de 52 anos, trabalho noturno, com cefaleia matinal frequente, sonolência diurna (Epworth 15) e ronco com pausas respiratórias testemunhadas pela esposa. IMC 38, circunferência de pescoço 46 cm, Mallampati III. PA 164x104 mesmo em uso de três fármacos. STOP-Bang 7. Sugere apneia obstrutiva do sono como causa de hipertensão de difícil controle (HAS secundária). Fundo de olho com estreitamento arteriolar. ECG com SVE.', 'Solicitar polissonografia, ecocardiograma, glicemia, TSH e creatinina. Manter anti-hipertensivos. Evitar álcool e sedativos à noite, tentar dormir em decúbito lateral. Orientado sobre perda de peso. Retorno com polissonografia em 4 semanas.'),
  (539, 164, 2, '2022-06-21 08:40', 'retorno', 'Fiz o exame do sono, deu ruim', 158, 100, 80, 118.0, 'Polissonografia com IAH 42 eventos/h (apneia grave), saturação mínima de 71% e 18% do tempo total com SatO2 abaixo de 90%. ECO com HVE concêntrica leve, FEVE 60%, átrio esquerdo 41 mm. Glicemia 118, HbA1c 6,0%. Quadro de hipertensão secundária à AOS grave. Paciente aceita testar CPAP, mas teme ficar dependente do aparelho.', 'Prescrever CPAP automático (auto-CPAP 5 a 15 cmH2O) com titulação pela pneumologia do sono. Manter anti-hipertensivos até a resposta ao CPAP. Meta de 7 horas por noite de uso. Procurar a nutricionista. Retorno em 8 semanas com relatório do aparelho.'),
  (540, 164, 2, '2022-11-08 08:30', 'retorno', 'Estou dormindo melhor, o sono sumiu', 132, 82, 72, 111.4, 'Há 4 meses com CPAP, uso médio de 6,4 horas por noite e IAH residual de 3,1 no relatório. Cefaleia matinal desapareceu, Epworth 6 e a esposa diz que ''o ronco acabou''. Perdeu 6,6 kg. PA domiciliar caiu de 160x100 para média de 130x80. Parou de fumar há 6 semanas. Sem tontura, sem hipotensão.', 'Suspender a hidroclorotiazida, mantendo losartana 100 mg e anlodipino 5 mg. Continuar o CPAP todas as noites. Reavaliar MAPA em 3 meses para considerar nova redução. Retorno em 3 meses.');
