insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (164, '2023-02-14', 'melhorou', 'Hipertensão secundária à apneia do sono grave com resposta ao CPAP e perda de peso: PA domiciliar passou de 160x100 para 126x78, com redução de três para dois fármacos. Sonolência resolvida e abstinente do cigarro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (165, 'Anselmo Rufino de Oliveira Filho', 'M', '1951-02-11', 'Arapiraca', 'AL', 'Agricultor aposentado (fumicultor)', 'HAS há 25 anos com adesão irregular, DRC estágio 3a conhecida. Sem diabetes. Ex-fumante. Come carne de sol e charque com frequência. Mora com a esposa em sítio, longe do posto de saúde.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (541, 165, 6, '2023-06-04 03:15', 'pronto_socorro', 'Acordei sem ar, quase morrendo afogado', 228, 124, 118, 76.0, 'Homem de 72 anos com dispneia súbita há 1 hora, ortopneia, tosse com expectoração rósea espumosa e sudorese. Há 3 dias sem tomar losartana e anlodipino, que acabaram. Ao exame: REG, taquipneico (FR 34), SatO2 82% em ar ambiente, estertores até ápices, RCR 3T, sem sopros, sem edema. PA 228x124. ECG sem supra de ST, taquicardia sinusal, SVE. Troponina 0,09 (leve elevação). RX com congestão pulmonar bilateral. HD: edema agudo de pulmão hipertensivo (crise hipertensiva emergencial).', 'Sentar o paciente, oxigênio com máscara e VNI (CPAP). Nitroglicerina endovenosa em bomba, furosemida 80 mg EV. Meta de redução de 25% da PA na primeira hora. Monitorização, gasometria. Solicitar leito de UTI. Evitar betabloqueador. Dosar BNP e creatinina.'),
  (542, 165, 14, '2023-06-05 10:00', 'internacao', 'Melhor da falta de ar', 148, 86, 84, 73.2, 'UTI D1. Diurese de 2.600 mL em 24 horas, perda de 2,8 kg. Desmamado da VNI após 6 horas, SatO2 96% em cateter. PA 148x86 com nitroglicerina já suspensa e anlodipino iniciado via oral. Troponina em queda (0,05), sem dinâmica isquêmica, interpretada como lesão por sobrecarga. ECO: HVE concêntrica importante, FEVE 52%, disfunção diastólica grau II, IM leve. NT-proBNP 4.800. Creatinina 1,4. Causa desencadeante: abandono de medicação por falta.', 'Transferir para enfermaria. Reintroduzir losartana 50 mg 12/12h e anlodipino 10 mg; adicionar clortalidona 12,5 mg após 48h se creatinina estável. Furosemida oral 40 mg. Investigar estenose de artéria renal com Doppler dada a DRC. Assistente social para garantir fornecimento mensal dos remédios.'),
  (543, 165, 1, '2023-06-27 09:30', 'retorno', 'Voltei para ver como estou', 138, 82, 70, 72.5, 'Alta hospitalar em 5 dias. Sem dispneia, dorme com um travesseiro. Esposa trouxe todas as caixas de remédio. Doppler de artérias renais: sem estenose hemodinamicamente significativa; rins com redução de volume e ecogenicidade aumentada (nefroesclerose). Creatinina 1,4, potássio 4,6, albuminúria 180 mg/g. Aprendeu a aferir PA com aparelho que a filha comprou.', 'Manter losartana, anlodipino e furosemida; iniciar clortalidona 12,5 mg. Dapagliflozina 10 mg pelo benefício renal e cardíaco. Nefrologia em conjunto. Fornecimento mensal pela farmácia municipal acertado com o posto. Retorno em 6 semanas.');
