insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (165, '2023-10-10', 'melhorou', 'Recuperação do edema agudo de pulmão hipertensivo precipitado por falta de medicamentos. Hoje com PA domiciliar média 130x78, sem nova descompensação em 4 meses, e medicação garantida pela farmácia do município. Mantido em acompanhamento cardiológico e nefrológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (166, 'Taíssa Moreira Almeida Brito', 'F', '1996-09-14', 'Aracaju', 'SE', 'Atendente de farmácia', 'Primeira gestação, 35 semanas e 2 dias na primeira consulta desta clínica. Pré-natal com PA sempre normal até a 32ª semana. Sem HAS prévia, IMC pré-gestacional 29. Mãe teve pré-eclâmpsia. Sem tabagismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (544, 166, 7, '2025-03-11 14:00', 'consulta', 'Pressão alta no pré-natal e pés inchados', 146, 94, 88, 82.6, 'Gestante de 28 anos, 35 semanas, encaminhada pela UBS por PA 148x96. Refere edema de pés e mãos e cefaleia leve ontem, sem escotomas, sem epigastralgia, movimentação fetal presente. PA 146x94 e 142x92 com 15 minutos de intervalo. Altura uterina 34 cm, BCF 142 bpm. Reflexos normais, sem clônus. Fita de urina com proteína 2+. Hipótese de pré-eclâmpsia sem sinais de gravidade.', 'Internar para avaliação e monitorização por 24 horas. Solicitar hemograma, plaquetas, TGO/TGP, creatinina, DHL, ácido úrico e proteinúria de 24h; cardiotocografia e perfil biofísico fetal. Iniciar nifedipino retard 20 mg 12/12h. Sulfato de magnésio não é indicado sem critérios de gravidade. Orientados sinais de alerta.'),
  (545, 166, 7, '2025-03-12 09:00', 'internacao', 'Sem dor de cabeça, quero saber os resultados', 134, 86, 82, 82.4, 'Internada há 24 horas, assintomática. PA entre 128x82 e 140x90 com nifedipino. Plaquetas 214 mil, TGO 22, TGP 19, creatinina 0,6, DHL normal, ácido úrico 5,2. Proteinúria de 24 horas: 0,46 g. Cardiotocografia reativa, ILA normal, Doppler de artérias uterinas sem incisura. Confirmada pré-eclâmpsia sem sinais de gravidade, sem HELLP. Gestação de 35 semanas e 3 dias.', 'Alta hospitalar com seguimento semanal na obstetrícia: PA em casa 2x ao dia, contagem de movimentos fetais, exames laboratoriais semanais, CTG semanal. Manter nifedipino. Interrupção planejada com 37 semanas. Retornar ao PS se PA acima de 160x110, cefaleia intensa, visão turva, dor em barra ou perda de líquido.'),
  (546, 166, 7, '2025-03-25 07:30', 'internacao', 'Internação para parto, 37 semanas', 138, 88, 86, 83.0, 'Internada com 37 semanas e 3 dias para resolução da gestação por pré-eclâmpsia. PA em casa estável (130-142x84-92), exames semanais normais (plaquetas 198 mil, creatinina 0,6), ILA normal. Colo favorável, realizada indução com misoprostol e ocitocina. Parto vaginal às 19h30, recém-nascido do sexo feminino, 2.980 g, Apgar 9 e 10. Sulfato de magnésio profilático por 24 horas no pós-parto por decisão da equipe. Sem hemorragia.', 'Manter nifedipino retard 20 mg 12/12h no puerpério. Monitorizar PA a cada 6 horas, alta em 48h. Orientações de aleitamento (nifedipino é compatível). Retorno em 7 dias para aferir PA e em 45 dias para revisão puerperal.'),
  (547, 166, 1, '2025-05-08 10:20', 'retorno', 'Revisão do parto, pressão está normal', 116, 72, 74, 71.2, 'Sete semanas após o parto, amamentando exclusivamente. PA em casa média 114x70 desde o 10º dia puerperal, nifedipino suspenso há 3 semanas por orientação da obstetra. Perdeu 11 kg. Sem cefaleia. Urina tipo 1 sem proteinúria, creatinina 0,7. Foi explicado que a pré-eclâmpsia aumenta o risco cardiovascular futuro e que é preciso aferir a PA todo ano.', 'Sem medicação. Controle anual da PA, glicemia e lipídios. Em nova gestação, AAS 100 mg desde 12 semanas e acompanhamento de alto risco. Manter atividade física e peso. Alta do ambulatório de gestação.');
