insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (166, '2025-05-08', 'melhorou', 'Pré-eclâmpsia sem sinais de gravidade resolvida após parto vaginal com 37 semanas e PA normalizada no puerpério, sem anti-hipertensivos. Recém-nascido saudável. Orientada sobre risco cardiovascular futuro e controle anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (167, 'Sebastião Teodoro Marques Guimarães', 'M', '1957-06-30', 'Goiânia', 'GO', 'Contador aposentado', 'HAS, DM2 e dislipidemia há mais de 15 anos. Ex-fumante, parou em 2010. Irmão com IAM aos 56 anos. Em uso de losartana, metformina e sinvastatina 20 mg. Angina aos esforços há 4 meses, que ele escondia da família.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (548, 167, 6, '2022-10-03 06:40', 'pronto_socorro', 'Dor no peito em repouso, acordou de madrugada', 158, 92, 88, 85.0, 'Homem de 65 anos com 3 episódios de dor precordial em repouso nas últimas 12 horas, cada um com 15 a 20 minutos, aliviada parcialmente com repouso, associada a sudorese. Última dor há 40 minutos. Pcte com antecedente de angina aos esforços. ECG: infradesnivelamento de ST de 1,5 mm em V4-V6 e T negativa em DII, DIII e aVF. Troponina ultrassensível 18 ng/L e 22 ng/L (seriada, ref. 34). HD: angina instável de alto risco (GRACE 138).', 'AAS 300 mg, clopidogrel 300 mg, enoxaparina 1 mg/kg de 12/12h, atorvastatina 80 mg e metoprolol 25 mg. Nitroglicerina EV se dor. Internar na unidade coronariana. Coronariografia em até 48 horas.'),
  (549, 167, 10, '2022-10-05 10:30', 'internacao', 'Coronariografia', 134, 80, 64, 85.0, 'Assintomático desde a internação. Coronariografia: lesão de 70% no tronco de coronária esquerda distal, DA com lesão de 90% proximal, Cx com lesão de 80% em marginal e CD ocluída crônica com circulação colateral. SYNTAX score 34. FEVE 55% pela ventriculografia. ECO com hipocinesia inferior discreta. Diabético com doença triarterial e lesão de tronco: indicação de revascularização cirúrgica pelo heart team.', 'Manter dupla antiagregação até 5 dias antes da cirurgia (suspender clopidogrel). Seguir AAS. Encaminhar para cirurgia cardiovascular eletiva em 7 a 10 dias. Compensação glicêmica com insulina NPH durante a internação, suspender metformina antes do contraste.'),
  (550, 167, 12, '2022-10-17 07:00', 'internacao', 'Cirurgia de ponte de safena', 126, 74, 66, 84.6, 'Realizada revascularização do miocárdio com circulação extracorpórea: LIMA para DA, veia safena para marginal da Cx e veia safena para descendente posterior da CD (3 pontes). Tempo de CEC 78 minutos, pinçamento 52 minutos. Sem intercorrências intraoperatórias. UTI com extubação em 6 horas, drenos retirados no 2º dia. FA transitória no 3º pós-operatório revertida com amiodarona venosa. Alta da UTI no 3º dia, alta hospitalar no 7º dia. Esternotomia sem sinais de infecção.', 'Manter AAS 100 mg, estatina em dose alta, metoprolol. Amiodarona oral por 6 semanas e depois suspender. Fisioterapia respiratória e reabilitação cardíaca. Retorno com cirurgião em 30 dias. Cuidados com a ferida e dos membros inferiores.'),
  (551, 167, 1, '2023-02-14 09:30', 'retorno', 'Estou fazendo a reabilitação, sem dor no peito', 122, 74, 60, 81.0, 'Quatro meses após a RM, assintomático, caminha 5 km 4x por semana. Esternotomia cicatrizada, consolidada. Perdeu 4 kg. LDL 52, HbA1c 6,8%. Suspendeu amiodarona há 2 meses, ritmo sinusal, sem recorrência de FA. Sem dispneia, sem edema. Esposa acompanha todas as consultas e controla os remédios. PA domiciliar média 120x72.', 'Manter AAS, atorvastatina 80, metoprolol e losartana. Teste ergométrico em 6 meses. Vacinas em dia. Retorno em 6 meses. Orientado a procurar o PS se dor torácica.');
