insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (167, '2023-02-14', 'melhorou', 'Revascularização miocárdica com três pontes por doença triarterial com lesão de tronco, evolução sem complicações importantes além de FA transitória. Assintomático, em reabilitação, LDL e HbA1c na meta.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (168, 'Odete Maria da Hora Bittencourt', 'F', '1946-10-03', 'Itabuna', 'BA', 'Aposentada, ex-professora primária', 'HAS há 40 anos, DM2 há 15 anos, obesidade, FA permanente em uso de apixabana. Insuficiência cardíaca com fração de ejeção preservada diagnosticada em 2022. Mora sozinha, filha visita nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (552, 168, 11, '2024-02-06 09:00', 'consulta', 'Falta de ar para ir ao banheiro e pés inchados', 146, 84, 88, 91.4, 'Idosa de 77 anos com ICFEp, NYHA III, piora há 1 mês: dispneia aos mínimos esforços, ortopneia, edema de MMII 3+/4+ até joelhos, ganho de 5 kg. Usa furosemida 40 mg, losartana 50 mg, apixabana 5 mg 12/12h, metformina. Ao exame: ECG FA com FC 88, estase jugular, estertores nas bases, RCR irregular, sopro sistólico mitral discreto. ECO: FEVE 58%, HVE concêntrica, átrio esquerdo 52 mm, disfunção diastólica grau III, PSAP 52 mmHg. NT-proBNP 2.940. Creatinina 1,3 (TFGe 40).', 'Furosemida 80 mg pela manhã por 7 dias, depois 40 mg. Iniciar empagliflozina 10 mg e espironolactona 12,5 mg com controle de potássio. Manter losartana e apixabana. Restrição de sódio 2 g/dia e líquidos 1,5 L. Peso diário. Retorno em 2 semanas.'),
  (553, 168, 11, '2024-06-18 09:20', 'retorno', 'Melhorei, mas as pernas voltam a inchar à tarde', 138, 80, 78, 84.7, 'Há 4 meses mais compensada, NYHA II, peso 84,7 kg (seco 83 a 84). Edema leve vespertino 1+/4+. Potássio 4,9, creatinina 1,2. NT-proBNP 1.150. HbA1c 7,4%. Tem dificuldade para seguir a dieta pois come salgado das vizinhas e não tem balança confiável. Quase foi internada em maio por piora, resolvida com dose extra de furosemida orientada pela filha por telefone.', 'Manter empagliflozina, espironolactona 12,5 e losartana. Furosemida 40 mg com 20 mg extra se ganho acima de 1,5 kg em 3 dias. Balança doméstica fornecida pela unidade. Agente comunitário fará visita semanal. Retorno em 3 meses.'),
  (554, 168, 6, '2024-11-22 01:50', 'pronto_socorro', 'Muito cansaço e tosse, a filha me trouxe', 118, 66, 112, 89.0, 'Idosa de 78 anos com 4 dias de febre baixa, tosse produtiva, e piora da dispneia nas últimas horas, edema de MMII 3+/4+ e queda da diurese. Ao exame: REG, taquipneica (FR 28), SatO2 89%, FA com FC 112, estertores difusos e crepitações em base direita. RX: congestão com consolidação em base direita. Leucocitose 16.800, PCR 128, creatinina 2,1 (lesão renal aguda), potássio 5,6. NT-proBNP 6.800. HD: ICFEp descompensada por pneumonia, com LRA cardiorrenal.', 'Internar. Suspender espironolactona, empagliflozina e losartana por LRA e hipercalemia. Furosemida EV, oxigênio, antibiótico (ceftriaxona e azitromicina). Manter apixabana 5 mg 12/12h (apenas um critério de redução de dose presente). Monitorizar creatinina e potássio a cada 12 horas.'),
  (555, 168, 11, '2025-03-04 09:40', 'retorno', 'Fiquei internada muito tempo, ainda me canso', 128, 72, 80, 82.0, 'Internada por 16 dias em novembro, com alta com hipotensão e fraqueza muscular. Hoje NYHA III, anda com andador. Creatinina basal agora 1,6 (TFGe 31), potássio 4,8; dapagliflozina retomada após 2 meses, losartana não retomada pela função renal. Teve nova internação curta em janeiro por descompensação leve. NT-proBNP 2.300. Mora com a filha desde dezembro. Piora funcional e renal após o episódio.', 'Manter empagliflozina 10 mg, espironolactona 12,5 mg em dias alternados e furosemida 40 mg. Manter apixabana 5 mg 12/12h (só um critério de redução de dose, creatinina acima de 1,5). Reabilitação motora domiciliar. Discutido plano de cuidados e metas com a família. Retorno em 2 meses.');
