insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (168, '2025-03-04', 'piorou', 'Duas internações em quatro meses (pneumonia com descompensação e lesão renal aguda), com perda funcional e evolução para DRC estágio 3b. Retornou à classe funcional III, dependente de andador e de cuidador. Segue em acompanhamento com foco em qualidade de vida.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (169, 'Cleber Augusto Nakamura Ferraz', 'M', '1965-12-02', 'Recife', 'PE', 'Engenheiro civil', 'HAS leve em uso de losartana 50 mg. Corredor amador (10 km, 3x por semana) até o ano passado. Café em excesso (6 xícaras/dia) e poucas horas de sono. Sem diabetes. Pai com FA.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (556, 169, 4, '2023-01-12 18:30', 'consulta', 'Palpitações há 6 semanas que me param na corrida', 136, 84, 118, 84.0, 'Homem de 57 anos com palpitações irregulares há 6 semanas, cansaço desproporcional na corrida e perda de rendimento. ECG: fibrilação atrial, FC média 118 bpm. Pulso irregular, RCR irregular, sem sopros, sem sinais de IC. ECO: AE 44 mm, FEVE 60%, sem valvopatia. TSH 1,8, eletrólitos normais. Holter: FA persistente durante todo o exame. CHA2DS2-VASc 1 (HAS). Sintomático, quer retornar ao ritmo sinusal.', 'Iniciar anticoagulação com rivaroxabana 20 mg ao jantar (CHA2DS2-VASc 1, sintomas, cardioversão planejada). Metoprolol succinato 50 mg para controle de FC. Reduzir cafeína e álcool. Cardioversão elétrica após 3 semanas de anticoagulação. Retorno em 3 semanas.'),
  (557, 169, 4, '2023-02-14 18:20', 'retorno', 'Fiz o choque e voltou, mas durou pouco', 132, 80, 104, 83.5, 'Cardioversão elétrica em 01/02 com reversão para ritmo sinusal e 8 dias bem. Recorrência da FA há 20 dias, com palpitações e queda do rendimento. Hoje em FA com FC 104. Anticoagulado sem falhas. Tem pouco tempo e quer solução definitiva: cogita ablação por cateter. Discutido tratamento antiarrítmico, ao qual teme efeitos colaterais.', 'Iniciar propafenona 150 mg 8/8h tendo ECO sem cardiopatia estrutural, com betabloqueador associado; cardioversão química ou elétrica após 1 mês. Se houver recorrência, encaminhar para ablação por cateter (isolamento de veias pulmonares). Retorno em 6 semanas.'),
  (558, 169, 4, '2023-07-04 19:00', 'teleconsulta', 'A FA voltou de novo apesar do remédio', 130, 82, 96, null, 'Teleconsulta. Com propafenona manteve ritmo sinusal por 3 meses, mas teve 2 recidivas sintomáticas de FA com 4 a 6 horas, e a última há uma semana persistiu por 2 dias, exigindo ida ao PS (ECG em outro serviço confirmou FA). Relata mal-estar, tontura leve e queda do rendimento no trabalho. Mede FC 96 e PA 130x82 pelo relógio e aparelho domiciliar. Falha do controle de ritmo com antiarrítmico classe IC em paciente jovem, sem cardiopatia estrutural: indicação de ablação.', 'Manter anticoagulação, propafenona e metoprolol até o procedimento. Encaminhar para o serviço de eletrofisiologia de referência (hospital universitário) para ablação por cateter com isolamento das veias pulmonares. Relatório de transferência e cópia de ECOs e Holter enviados. Contato pós-procedimento.');
