insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (169, '2023-07-10', 'transferido', 'Encaminhado ao serviço de eletrofisiologia de referência para ablação por cateter de FA paroxística/persistente refratária ao antiarrítmico. Saiu do acompanhamento da clínica com relatório completo e anticoagulação mantida.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (170, 'Edvaneide Santos Menezes', 'F', '1978-04-27', 'Propriá', 'SE', 'Agente comunitária de saúde', 'Febre reumática na infância com cardite e penicilina benzatina interrompida na adolescência. Dois partos normais. Dispneia progressiva aos esforços há 2 anos, palpitações ocasionais. Sem HAS.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (559, 170, 1, '2022-03-08 08:50', 'consulta', 'Canso para subir a ladeira do bairro e sinto o coração batendo forte', 118, 72, 96, 62.0, 'Mulher de 43 anos com dispneia NYHA II-III e palpitações. Ao exame: pulso irregular, RCR irregular, estalido de abertura e ruflar diastólico em foco mitral com reforço pré-sistólico ausente (FA), hiperfonese de B1, MV+ sem RA, sem edema. ECG: FA com FC média 96, sinais de sobrecarga atrial esquerda prévia. ECO: estenose mitral reumática, área valvar 0,9 cm² (planimetria), gradiente médio 14 mmHg, átrio esquerdo 54 mm, PSAP 48 mmHg, FEVE 62%. Escore de Wilkins 7. Estenose mitral importante com FA.', 'Varfarina com alvo de INR 2 a 3 (DOAC contraindicado em estenose mitral moderada a grave). Metoprolol succinato 50 mg para controle da FC. Furosemida 20 mg SN. ETE para descartar trombo e avaliar viabilidade de valvuloplastia por cateter-balão. Retorno em 3 semanas.'),
  (560, 170, 10, '2022-04-05 09:10', 'retorno', 'Trouxe o exame do esôfago', 114, 70, 78, 61.5, 'FC controlada (78) com metoprolol. INR 2,4 após ajuste de varfarina. ETE: estenose mitral com folhetos de mobilidade preservada, pouco calcificados, ausência de trombo em AE e apêndice, regurgitação mitral discreta (grau I). Anatomia favorável para valvoplastia mitral percutânea por balão (Wilkins 7). Esclarecida sobre procedimento, riscos (IM aguda, tamponamento, AVC) e alternativa de troca valvar com prótese mecânica.', 'Agendar valvoplastia mitral por cateter-balão (técnica de Inoue) em maio. Manter varfarina até 5 dias antes, com INR menor que 1,5 no dia, e ponte com heparina. Retorno após o procedimento.'),
  (561, 170, 10, '2022-05-17 07:30', 'internacao', 'Procedimento da válvula', 112, 68, 82, 61.3, 'Valvoplastia mitral percutânea por balão (Inoue 26 mm) via transeptal. Área valvar passou de 0,9 para 1,9 cm² e gradiente médio de 14 para 4 mmHg; pressão em átrio esquerdo caiu de 28 para 12 mmHg. Insuficiência mitral discreta, sem aumento. Sem tamponamento nem complicações vasculares. Paciente assintomática. Alta em 48 horas, ECO de controle sem derrame pericárdico.', 'Retornar varfarina na noite do procedimento com enoxaparina até INR acima de 2. Controle de INR em 3 dias. Manter metoprolol. Profilaxia secundária da febre reumática com penicilina benzatina 1.200.000 UI a cada 21 dias. Retorno em 30 dias com ECO.'),
  (562, 170, 1, '2023-03-21 08:40', 'retorno', 'Estou bem, subo a ladeira sem parar', 110, 68, 70, 63.2, 'Dez meses após a valvoplastia, NYHA I, trabalha normalmente nas visitas domiciliares. INR dentro da faixa em 80% das medições (último 2,6). FA controlada, FC 70. ECO: área mitral 1,8 cm², gradiente médio 5 mmHg, IM leve, PSAP 32 mmHg, AE 50 mm. Aderente à penicilina benzatina, refere dor no local da aplicação, tolerável. Sem sangramentos.', 'Manter varfarina com INR mensal, metoprolol e profilaxia secundária. ECO anual. Orientada sobre gestação (já laqueadura prévia) e procurar atendimento se piora dos sintomas. Retorno em 6 meses.');
