insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (170, '2023-03-21', 'melhorou', 'Estenose mitral reumática tratada com valvoplastia por balão com excelente resultado: área valvar de 0,9 para 1,8 cm², classe funcional I e INR estável com varfarina. Segue em profilaxia secundária de febre reumática e controle anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (171, 'Genivaldo Santos Prado Lima', 'M', '1967-02-14', 'Nossa Senhora do Socorro', 'SE', 'Taxista', 'Sem diagnóstico prévio de HAS, nunca mediu a pressão. Passa 10 horas por dia sentado no carro, come em lanchonete. Bebe 4 cervejas aos sábados. Ex-fumante, parou há 5 anos. Mãe hipertensa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (563, 171, 5, '2022-11-08 15:10', 'consulta', 'Dor de cabeça na nuca ao fim do dia', 162, 100, 78, 91.0, 'Homem de 55 anos que veio por cefaleia occipital vespertina há 2 meses. Nunca usou anti-hipertensivo. Ao exame: IMC 30, RCR 2T BNF, sem sopros, pulsos presentes, sem edema. PA 162x100 e 158x98 em duas medidas, nos dois braços sem diferença. Creatinina 0,9, potássio 4,2, glicemia 98, LDL 142. ECG com ritmo sinusal sem HVE. Diagnóstico de HAS estágio 2 (confirmação por MRPA em andamento).', 'Iniciar enalapril 10 mg 12/12h. Orientações: reduzir sal, evitar frituras do ponto, caminhar após o turno, cerveja só um dia. MRPA por 5 dias. Retorno em 3 semanas com MRPA.'),
  (564, 171, 5, '2022-12-01 15:30', 'retorno', 'Estou com tosse seca que não passa', 140, 88, 76, 90.4, 'Há 12 dias com tosse seca irritativa, pior à noite, sem febre, sem dispneia, sem coriza. Iniciou 3 semanas após o enalapril. Pensou em parar o remédio sozinho porque ''o remédio dá tosse e eu preciso falar o dia inteiro com passageiros''. MRPA com média 142x88. Ausculta pulmonar normal, orofaringe sem alterações. Tosse por IECA, efeito de classe, comum e não perigoso.', 'Suspender enalapril. Iniciar losartana 50 mg/dia, que não causa tosse. Orientado que a tosse deve melhorar em 1 a 4 semanas após a suspensão. Orientado a não interromper o tratamento por conta própria. Retorno em 4 semanas.'),
  (565, 171, 5, '2023-04-12 15:20', 'retorno', 'A tosse sumiu, pressão boa', 124, 78, 72, 87.2, 'Tosse desapareceu em 3 semanas após a troca. MRPA média 122x76. Perdeu 3,8 kg ao deixar de comer pastel e refrigerante no ponto, e leva marmita e frutas. Potássio 4,3, creatinina 0,9. Sem tontura. Conta que, após a troca, ''tomo sem esquecer porque agora é só uma vez por dia''.', 'Manter losartana 50 mg/dia. Atorvastatina 20 mg pelo LDL de 142 e risco. Manter caminhadas. Retorno em 6 meses com exames.');
