insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (171, '2023-04-12', 'controlado', 'HAS estágio 2 controlada com losartana 50 mg após suspensão do enalapril por tosse. PA domiciliar média 122x76, tosse resolvida e perda de 4 kg. Mantém consultas semestrais na unidade.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (172, 'Lúcia Helena Tenório Calheiros', 'F', '1957-06-12', 'Rio Largo', 'AL', 'Aposentada, ex-operária de usina de açúcar', 'HAS há 14 anos, encaminhada como hipertensa resistente: losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Sem diabetes. Em casa a pressão ''nunca passa de 130''. Cardiopatia não conhecida. Vive com o marido.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (566, 172, 2, '2023-03-21 10:40', 'consulta', 'No consultório a pressão é sempre alta, em casa é normal', 172, 94, 80, 68.5, 'Mulher de 65 anos, com PA de consultório entre 168 e 176 sistólica nas últimas 6 consultas, com três fármacos em dose plena. Em casa refere valores entre 118x70 e 128x76 (aparelho de braço validado levado hoje: diferença de 4 mmHg). Fica muito tensa em consultas médicas. Adesão excelente, caixa de comprimidos organizada. Fundo de olho normal, ECO sem HVE (resultados anteriores). Creatinina 0,9, sódio 131 (hiponatremia por tiazídico), potássio 3,7. Suspeita de efeito do avental branco com pseudorresistência.', 'MAPA 24h para confirmar. Repetir sódio. Não acrescentar fármaco. Se confirmado, reduzir esquema, sobretudo o diurético pela hiponatremia. Retorno com MAPA em 2 semanas.'),
  (567, 172, 2, '2023-04-04 10:20', 'retorno', 'Trouxe a MAPA', 168, 92, 78, 68.2, 'MAPA 24h: médias de vigília 122x72, sono 108x62, 24 horas 118x69, com 96% das medidas válidas, descenso noturno preservado. Em contraste, PA de consultório hoje 168x92. Confirmado o efeito do avental branco em hipertensa tratada, com pressão controlada fora do consultório: pseudorresistência. Sódio 133, potássio 3,8. Sem sintomas de hipotensão, sem tontura. Paciente aliviada por não precisar de mais remédios.', 'Suspender clortalidona (hiponatremia e PA ambulatorial já na meta). Manter losartana e anlodipino. Orientado que doses futuras serão decididas por MAPA ou MRPA e não por medidas isoladas no consultório. Repetir sódio em 3 semanas. Retorno em 2 meses com MRPA.'),
  (568, 172, 2, '2023-06-20 10:30', 'retorno', 'Sem a pílula da água, estou me sentindo bem', 154, 88, 74, 68.9, 'Sem clortalidona há 2 meses. Sódio normalizou para 138 e potássio 4,1. MRPA com média 120x72, apesar de PA de 154x88 no consultório (reduziu em relação ao anterior, mas ainda com reação de avental branco). Sem tontura, sem edema. Orientada técnica de medida com repouso de 5 minutos e respiração tranquila. Está contente com menos comprimidos.', 'Manter losartana 100 mg e anlodipino 10 mg. Para as próximas consultas, considerar valor do MRPA como referência de decisão. Retorno em 6 meses com MRPA e eletrólitos.');
