insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (172, '2023-06-20', 'controlado', 'A suposta hipertensão resistente era efeito do avental branco: a MAPA mostrou PA ambulatorial controlada (média 118x69). Sem necessidade de espironolactona; foi suspensa a clortalidona por hiponatremia. Segue com dois fármacos e controle domiciliar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (173, 'Antônio Marcos Dourado Leal', 'M', '1964-12-05', 'Jequié', 'BA', 'Marceneiro', 'HAS leve há 6 anos, bem controlada com losartana 50 mg até 2 anos atrás. Lombalgia crônica por esforço, em uso diário de diclofenaco 75 mg 12/12h e, há 6 meses, etoricoxibe 90 mg por conta própria. Sem diabetes. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (569, 173, 2, '2023-04-25 08:50', 'consulta', 'Pressão subiu e as pernas incharam', 176, 104, 80, 90.2, 'Homem de 58 anos com HAS que estava controlada e piorou progressivamente nos últimos 18 meses, agora com 176x104 apesar de losartana 100 mg e anlodipino 10 mg acrescentado pelo clínico. Edema de MMII 2+/4+ e ganho de 4 kg. Uso diário de dois AINEs (diclofenaco e etoricoxibe) para lombalgia. Creatinina subiu de 0,9 para 1,5 (TFGe 52), potássio 4,9, sem proteinúria. ECO com FEVE normal e HVE leve. Hipertensão induzida por AINE, com retenção de sódio e redução do efeito dos anti-hipertensivos.', 'Suspender diclofenaco e etoricoxibe. Dor: paracetamol 750 mg até 3x/dia, fisioterapia e orientações posturais. Furosemida 20 mg por 7 dias. Manter losartana e anlodipino. Retorno em 3 semanas com creatinina e potássio. Orientado a não usar AINE sem avaliação.'),
  (570, 173, 2, '2023-05-16 08:40', 'retorno', 'A dor nas costas voltou mas a pressão baixou', 146, 88, 74, 86.0, 'Três semanas sem AINE. Perdeu 4,2 kg (retirada do edema), PA domiciliar caiu para média de 140x86. Creatinina 1,2, potássio 4,6. Lombalgia 5/10 com paracetamol, aceitável mas incomoda no trabalho. Tentou voltar o diclofenaco uma vez, notou o inchaço na manhã seguinte e parou. Fisioterapia iniciada.', 'Manter AINE suspenso. Associar ciclobenzaprina 5 mg à noite por 2 semanas e continuar fisioterapia. Manter losartana 100 e anlodipino 10 e reavaliar redução quando PA estiver abaixo de 130x80. Retorno em 6 semanas com MRPA.'),
  (571, 173, 2, '2023-08-08 09:00', 'retorno', 'Pressão boa, dor suportável', 122, 76, 70, 84.8, 'Quatro meses sem AINE. MRPA com média 120x74. Sem edema, creatinina 1,0 (TFGe 83), potássio 4,4. Peso estável 84,8 kg. Lombalgia 3/10 com fisioterapia e exercícios de fortalecimento. Refere tontura leve ao levantar rápido, sem queda. Contou que o médico da ortopedia quis renovar o diclofenaco, mas ele recusou mostrando o cartão com a orientação.', 'Suspender anlodipino 10 mg, manter losartana 100 mg/dia. Se PA subir, retomar dose menor. Manter alerta de AINE no prontuário e orientação para evitar os de balcão. MRPA em 4 semanas. Retorno em 3 meses.');
