insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (174, '2024-10-22', 'controlado', 'Pseudocrise hipertensiva por enxaqueca e estresse sem lesão de órgão-alvo, resolvida sem anti-hipertensivo. Após suspensão do anticoncepcional combinado e estilo de vida, PA domiciliar média 120x76. Segue em controle anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (175, 'Aline Sobral Machado', 'F', '1992-03-03', 'Nossa Senhora da Glória', 'SE', 'Técnica em enfermagem', 'HAS diagnosticada aos 26 anos, em uso de losartana 50 mg/dia. Obesidade grau I. Mãe e avó hipertensas. Primeira gestação, 9 semanas, planejada. Não sabia que a losartana é contraindicada na gravidez.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (576, 175, 7, '2024-01-16 08:30', 'consulta', 'Descobri que estou grávida e tomo remédio de pressão', 138, 88, 80, 84.5, 'Gestante de 31 anos, 9 semanas por USG, HAS crônica em uso de losartana até a data da consulta (exposição de cerca de 3 semanas). Assintomática, sem proteinúria, creatinina 0,7. USG com embrião único, BCF presente, translucência nucal a seguir. Ao exame: PA 138x88, RCR 2T BNF, MV+ sem RA. Orientada sobre o risco da exposição a BRA no 1º trimestre (menor) e 2º/3º trimestres. HD: HAS crônica na gestação, risco alto para pré-eclâmpsia.', 'Suspender losartana hoje. Iniciar metildopa 500 mg 8/8h (nifedipino como segunda opção). AAS 100 mg à noite a partir de 12 semanas e carbonato de cálcio 1 g/dia. Ácido fólico. Proteinúria de 24h e ácido úrico basais. PA em casa 2x ao dia. Retorno quinzenal.'),
  (577, 175, 7, '2024-05-07 08:40', 'retorno', 'Pré-natal, 24 semanas', 128, 80, 84, 86.9, 'Gestante com 24 semanas e 2 dias, PA domiciliar média 126x78 com metildopa 500 mg 8/8h. Refere sonolência e lentidão leve que atrapalham o plantão. Sem edema, sem cefaleia. Altura uterina 24 cm, BCF 148. Morfológico de 2º trimestre normal, Doppler das artérias uterinas com IP médio de 1,1 (normal). Proteinúria 0,11 g/24h, creatinina 0,6, plaquetas 248 mil. Ganho de peso de 2,4 kg desde o início.', 'Manter metildopa, AAS e cálcio. Orientar alimentação. Ecocardiograma fetal não necessário. Avaliar crescimento fetal com USG em 30 e 36 semanas. Sinais de alerta de pré-eclâmpsia reforçados. Retorno em 3 semanas.'),
  (578, 175, 7, '2024-09-09 06:50', 'internacao', 'Internação programada para o parto, 38 semanas', 140, 90, 86, 93.0, 'Gestante de 38 semanas e 1 dia, HAS crônica sem proteinúria superposta durante todo o pré-natal, PA entre 124x78 e 142x90 com metildopa 750 mg/dia + nifedipino retard 20 mg 12/12h adicionado na 34ª semana. Feto em apresentação pélvica, peso estimado 3.280 g. Optado por cesárea eletiva. Cesárea sem intercorrências, recém-nascido masculino 3.210 g, Apgar 9/10. Perda sanguínea estimada em 500 mL. PA no pós-operatório entre 120x76 e 138x88.', 'Suspender a metildopa após o parto. Manter nifedipino retard e iniciar enalapril 10 mg 12/12h no puerpério (compatível com aleitamento) se PA acima de 140x90. Monitorizar PA a cada 6 horas. Alta em 3 dias. Retorno em 7 dias para aferir PA.'),
  (579, 175, 1, '2024-10-22 09:00', 'retorno', 'Retorno do puerpério, queria voltar ao remédio de antes', 134, 84, 76, 84.2, 'Sete semanas de puerpério, amamentando. MRPA média 132x84 com nifedipino. Edema nulo, creatinina 0,7. Perdeu 8,8 kg desde o parto. Quer o esquema anterior (losartana) mas amamenta; enalapril é a opção preferida na lactação. Sem planos de nova gestação nos próximos 2 anos, vai usar método contraceptivo (DIU de cobre).', 'Trocar nifedipino por enalapril 10 mg 12/12h durante o aleitamento, com potássio e creatinina em 2 semanas. Se engravidar de novo, procurar a unidade imediatamente para suspender o IECA. Retorno em 6 semanas.');
