insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (175, '2024-10-22', 'melhorou', 'Gestação com HAS crônica conduzida com troca do BRA por metildopa e nifedipino, AAS e cálcio, sem pré-eclâmpsia. Cesárea eletiva a termo com recém-nascido saudável. No puerpério, transição para enalapril compatível com amamentação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (176, 'Roberval Santos Pinheiro', 'M', '1975-11-20', 'Lauro de Freitas', 'BA', 'Gerente de agência bancária', 'Sem diagnóstico de HAS. Pressão sempre normal em consultas (120 a 128 sistólica). Rotina de trabalho com muita pressão, 11 horas por dia, fuma 10 cigarros, bebe vinho todos os dias. Pai com HVE e infarto aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (580, 176, 1, '2023-03-14 07:50', 'consulta', 'Check-up anual, tudo normal', 126, 80, 84, 90.0, 'Homem de 47 anos, assintomático. PA de consultório 126x80 e 124x82. No check-up, ECG com SVE por Sokolow-Lyon (36 mm) e ECO com HVE leve (septo 12 mm, massa indexada aumentada), achado incompatível com PA normal. Relata que a pressão de casa vive acima de 140 (aparelho no escritório, nos dias de fechamento). Fundo de olho com estreitamento arteriolar. Creatinina 1,0, albuminúria 24 mg/g. Suspeita de hipertensão mascarada.', 'MAPA 24h em dia de trabalho e MRPA por 7 dias. Reduzir vinho para 2 taças nos fins de semana e parar o cigarro (aceita adesivo). Aguardar resultados para decidir tratamento. Retorno em 2 semanas.'),
  (581, 176, 1, '2023-03-28 07:40', 'retorno', 'Trouxe MAPA e MRPA', 128, 82, 80, 89.4, 'MAPA 24h: vigília 146x92, sono 134x80 (sem descenso, perfil non-dipper), média das 24h 142x88. MRPA: média 144x90. Consultório normal e MAPA/MRPA elevadas: hipertensão mascarada confirmada, com HVE e microalbuminúria discreta, portanto lesão de órgão-alvo. Diz que ''nunca imaginei, me sinto ótimo''. Entendeu que sem a MAPA o diagnóstico passaria despercebido.', 'Iniciar losartana 50 mg/dia e acrescentar anlodipino 5 mg se MRPA permanecer acima da meta em 4 semanas. Manter MEV com foco em álcool e tabagismo. Potássio e creatinina em 2 semanas. MRPA semanal. Retorno em 4 semanas.'),
  (582, 176, 1, '2023-05-30 07:50', 'retorno', 'Pressão em casa melhorou, mas ainda oscila', 118, 76, 76, 87.6, 'MRPA média 134x84 com losartana 50 mg, ainda acima da meta. Potássio 4,5, creatinina 1,0. Parou de fumar há 8 semanas e bebe duas taças de vinho por semana, perdeu 2,4 kg. Sem efeitos colaterais. PA de consultório 118x76, ilustrando que o consultório não representa o controle real. Ainda trabalha 11 horas por dia, com picos de estresse.', 'Aumentar losartana para 100 mg/dia e associar anlodipino 5 mg. Nova MAPA em 3 meses para guiar o tratamento. Repetir o ECO em 12 meses para avaliar regressão da HVE. Retorno em 6 semanas com MRPA.');
