insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (176, '2023-09-12', 'controlado', 'Hipertensão mascarada com HVE leve diagnosticada pela MAPA, apesar de consultório normal. Com losartana 100 mg e anlodipino 5 mg, abstinência do cigarro e menos álcool, MAPA de controle com média 24h de 122x76.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (177, 'Gilvan Pedrosa Cavalcanti', 'M', '1964-01-09', 'Maceió', 'AL', 'Motorista de aplicativo', 'HAS e dislipidemia sem tratamento regular. Fumante de 1 maço por dia há 35 anos. Sedentário, dorme pouco. Pai falecido de infarto aos 52 anos. Sem plano de saúde, paga consultas e remédios do próprio bolso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (583, 177, 6, '2022-09-20 04:30', 'pronto_socorro', 'Dor no peito que começou no carro e foi para o braço', 164, 98, 92, 95.0, 'Homem de 58 anos com dor precordial em aperto há 2 horas, irradiada para braço esquerdo e mandíbula, sudorese, náusea. Parou o carro e pediu ajuda. ECG: infradesnivelamento de ST de 2 mm em V3-V6, sem supra. Troponina ultrassensível 420 ng/L e 880 ng/L (seriada). Exame: PA 164x98, RCR 2T BNF, MV+ sem RA, sem estertores (Killip I). HD: IAM sem supra de ST (IAMSSST) de risco alto (GRACE 152).', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol 25 mg. Internar em unidade coronariana. Cateterismo em até 24 horas por hemodinâmica. Família orientada.'),
  (584, 177, 10, '2022-09-21 09:30', 'internacao', 'Cateterismo', 144, 86, 70, 95.0, 'Coronariografia: lesão de 95% em coronária direita média (culpada), DA com lesão de 50% proximal e Cx sem lesões significativas. Angioplastia da CD com stent farmacológico 3,5 x 28 mm, resultado angiográfico excelente. Sem complicações. FEVE 52% com hipocinesia inferior. Alta em 48 horas com orientações de reabilitação e abstinência do tabaco. Dupla antiagregação indicada por 12 meses.', 'AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses; atorvastatina 80 mg; metoprolol succinato 50 mg; losartana 50 mg ao dia. Reabilitação cardiovascular. Parar de fumar com adesivo e acompanhamento. Retorno em 3 semanas. Explicado que não se pode parar o antiplaquetário por conta própria.'),
  (585, 177, 1, '2022-10-18 16:00', 'retorno', 'Estou bem, queria saber se posso voltar a dirigir o dia todo', 134, 82, 66, 94.2, 'Quatro semanas após o IAM e angioplastia, sem dor torácica, sem dispneia. Voltou a trabalhar 12 horas por dia, não fez reabilitação (''não tenho tempo e o carro não pode parar''). Reduziu o cigarro para 5 por dia. Queixa que o ticagrelor dá falta de ar leve e o custo do remédio pesa nas finanças. PA 134x82, FC 66. Ausculta normal. LDL 98 com atorvastatina 80 e boa adesão referida. Receita de 30 dias entregue com orientação de comprar mensalmente.', 'Substituir ticagrelor por clopidogrel 75 mg (custo menor e menos dispneia), mantendo AAS por 12 meses. Manter demais medicamentos. Reforçar que não pode interromper antiagregante. Reabilitação em horário noturno. Retorno em 6 semanas. Contato telefônico se faltar à consulta.');
