insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (177, '2023-01-20', 'abandonou', 'Não compareceu ao retorno de dezembro nem atendeu a duas ligações. Em contato com a esposa, soube-se que parou o clopidogrel e a estatina por custo e sensação de estar curado, voltou a fumar um maço por dia e não fez reabilitação. Perda de seguimento sem intercorrência registrada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (178, 'Hilda Noronha Villela', 'F', '1943-05-18', 'Belo Horizonte', 'MG', 'Aposentada, ex-costureira', 'IAM de parede anterior em 2015 com sequela. IC com fração de ejeção reduzida há 6 anos. HAS e DM2 há 25 anos. DRC estágio 3b. Internações por IC em 2020 e 2021. Mora com a filha, que cuida dos remédios.', 'AAS (broncoespasmo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (586, 178, 11, '2022-02-10 10:00', 'consulta', 'Cansada o tempo todo, mal consigo ir da cama para a cadeira', 96, 58, 68, 58.4, 'Idosa de 78 anos com ICFEr isquêmica avançada, NYHA IV, caquexia cardíaca e edema de MMII 2+/4+. Ao exame: pálida, PA 96x58, estase jugular, estertores nas bases, B3, hepatomegalia. ECO: FEVE 22%, dilatação importante de VE, IM moderada a grave funcional. NT-proBNP 11.400. Creatinina 1,9 (TFGe 26), potássio 4,9, sódio 131. Não tolera sacubitril/valsartana por hipotensão e piora renal. Usa carvedilol 6,25 mg 12/12h, espironolactona 12,5 mg, furosemida 80 mg 12/12h e hidralazina com nitrato.', 'Manter carvedilol, hidralazina 25 mg 8/8h + isossorbida 20 mg 8/8h. Manter espironolactona 12,5 mg com controle semanal do potássio. Não iniciar iSGLT2 com TFGe 26. Discutido com paciente e filha sobre prognóstico reservado e cuidados paliativos. Retorno em 3 semanas.'),
  (587, 178, 11, '2022-07-19 10:20', 'retorno', 'Passei 3 semanas internada, ainda inchada', 92, 56, 72, 60.8, 'Alta de internação de 12 dias por descompensação com baixo débito, tratada com dobutamina por 48 horas e furosemida em infusão. Retorna com edema de MMII 2+/4+ e ortopneia, mas lúcida. Peso 60,8 kg, PA 92x56. Creatinina 2,3, sódio 129, potássio 5,2. Ajustes: espironolactona suspensa durante a internação pelo potássio. Pensou-se em implante de ressincronizador, descartado por QRS estreito (QRS 104 ms) e baixa expectativa de vida. Filha cansada, sem apoio para o cuidado noturno.', 'Furosemida 80 mg 12/12h + metolazona 2,5 mg 3x por semana em dias alternados com controle de eletrólitos. Manter carvedilol, hidralazina e nitrato. Acompanhamento domiciliar com equipe de cuidados paliativos. Retorno em 1 mês ou antes se piora.'),
  (588, 178, 6, '2022-12-03 22:40', 'pronto_socorro', 'Muito cansaço, não consigo respirar deitada', 84, 50, 108, 57.0, 'Idosa de 79 anos trazida pela filha com dispneia grave há 2 dias, extremidades frias e diminuição da diurese. Ao exame: REG, sonolenta, pele fria e pegajosa, PA 84x50, FC 108, SatO2 86%, estertores até ápices, edema de MMII 3+/4+. Lactato 4,2, creatinina 2,9, potássio 5,6, troponina discretamente elevada sem dinâmica ECG. NT-proBNP 19.800. HD: choque cardiogênico por ICFEr terminal descompensada.', 'Conversa com família. Suporte em UTI com dobutamina em baixa dose, diurético EV, oxigênio por máscara. Sem indicação de intubação ou reanimação cardiopulmonar conforme vontade registrada da paciente e da filha. Medidas de conforto associadas.');
