insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (178, '2022-12-08', 'obito', 'Faleceu na UTI em 08/12/2022, cinco dias após a admissão, por choque cardiogênico refratário em insuficiência cardíaca avançada (FEVE 22%) com disfunção renal. Medidas de conforto instituídas conforme desejo da paciente, com a filha presente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (179, 'Expedito Frota Aguiar', 'M', '1944-08-25', 'Fortaleza', 'CE', 'Aposentado, ex-comerciante', 'HAS e FA permanente há 8 anos, em uso de rivaroxabana 20 mg e AAS 100 mg (por antiga indicação), losartana e metoprolol. DRC leve. Dispepsia frequente tratada com antiácido de balcão. Etilista social.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (589, 179, 6, '2023-01-14 19:20', 'pronto_socorro', 'Fezes pretas e fraqueza, quase desmaiei', 92, 54, 112, 74.0, 'Idoso de 78 anos com 3 dias de melena (4 episódios), tontura, fraqueza e uma pré-síncope hoje. Usa rivaroxabana + AAS + ibuprofeno por conta própria para dor no joelho. Ao exame: REG, descorado 3+/4+, PA 92x54, FC 112 irregular (FA). Hb 6,8 (era 13), ureia 78, creatinina 1,5, INR 1,6, plaquetas 210 mil. ECG FA com resposta ventricular alta sem isquemia. HD: hemorragia digestiva alta por provável úlcera péptica, associada a anticoagulante, AAS e AINE.', 'Suspender rivaroxabana, AAS e ibuprofeno. Dois acessos calibrosos, ressuscitação com cristaloide e transfusão de 2 concentrados de hemácias. Omeprazol 80 mg EV em bolus e depois infusão. Internar na UTI. Endoscopia digestiva alta nas primeiras 24 horas.'),
  (590, 179, 14, '2023-01-15 08:30', 'internacao', 'Melhor, sem novos episódios de sangramento', 118, 70, 88, 74.0, 'UTI D1. Estabilizado após 2 concentrados de hemácias, Hb 8,6. Endoscopia: úlcera duodenal de 12 mm com vaso visível (Forrest IIa) tratada com hemoclips e adrenalina, H. pylori positivo no teste da urease. Sem novo sangramento em 24 horas. FC controlada em 88. CHA2DS2-VASc 3 (idade a partir de 75 anos e HAS) e HAS-BLED 4. Risco alto de sangramento, mas também risco de AVC elevado. Discussão sobre reintrodução da anticoagulação após cicatrização.', 'Omeprazol 40 mg 12/12h por 8 semanas, tratamento de erradicação do H. pylori após estabilização. Suspender AAS definitivamente (sem indicação). Evitar AINE. Reavaliar reintrodução de anticoagulante (apixabana 5 mg 12/12h) em 7 a 14 dias após hemostasia. Controle de hemoglobina.'),
  (591, 179, 4, '2023-02-14 10:00', 'retorno', 'Não tive mais sangramento, mas ainda estou fraco', 136, 78, 82, 72.5, 'Quatro semanas após a hemorragia, Hb 10,8, sem melena, completou erradicação do H. pylori com claritromicina, amoxicilina e omeprazol. Sem anticoagulação há 30 dias, FA persistente com FC 82. Pouca disposição. Explicado risco de AVC (CHA2DS2-VASc 3, risco anual de aproximadamente 3 a 4%) versus novo sangramento. Esposa e filho presentes. Paciente receoso: ''depois que sangrei não quero mais anticoagulante''. Discutiu-se oclusão do apêndice atrial como alternativa.', 'Recomendada reintrodução da apixabana 5 mg 12/12h (menor risco de sangramento) com IBP contínuo, e sem AAS/AINE. Paciente pediu tempo para decidir e prefere aguardar 1 mês. Solicitar avaliação para oclusão do apêndice atrial esquerdo. Retorno em 4 semanas.'),
  (592, 179, 13, '2023-04-02 07:10', 'pronto_socorro', 'Acordei sem força no braço e perna direitos e não consigo falar direito', 168, 94, 96, 71.0, 'Acordou com os sintomas (última vez visto bem às 22h, janela indeterminada acima de 4,5 h). Hemiparesia direita grau 2, desvio de rima labial, afasia mista. NIHSS 14. Em FA, sem anticoagulação há 11 semanas (não retornou na data combinada, adiou a decisão). Glicemia 138. TC de crânio sem sangramento, ASPECTS 9. Angiotomografia com oclusão proximal da artéria cerebral média esquerda (M1). AVC isquêmico cardioembólico.', 'Sem indicação de trombólise pela janela incerta; encaminhar para trombectomia mecânica (oclusão de grande vaso, ASPECTS 9, dentro de 24 horas). Internar em unidade de AVC. Controle de PA até 185x110 antes do procedimento. Anticoagulação só após estudo de imagem de controle e avaliação.');
