insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (179, '2023-05-10', 'piorou', 'AVC isquêmico cardioembólico da ACM esquerda após 11 semanas sem anticoagulação, com recanalização parcial por trombectomia, mas sequela de hemiparesia direita e afasia moderada (Rankin 4). Alta para reabilitação e retomada da anticoagulação com apixabana e IBP.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (180, 'Ingrid Helga Schneider Becker', 'F', '1948-09-30', 'Porto Alegre', 'RS', 'Aposentada, ex-professora universitária', 'HAS há 30 anos controlada com anlodipino e losartana. Osteoporose. Cursa com tonturas esporádicas há 3 meses. Pratica hidroginástica. Marido falecido há 2 anos, mora sozinha, filha em outra cidade.', 'Penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (593, 180, 6, '2022-06-12 05:40', 'pronto_socorro', 'Caí no banheiro, desmaiei por um minuto', 176, 80, 32, 61.0, 'Idosa de 73 anos com síncope sem pródromos ao levantar de madrugada, com trauma facial leve. Nos últimos meses cansaço e tontura. Ao exame: pálida, pulso bradicárdico regular a 32 bpm, PA 176x80, ausculta com B1 variável (ondas em canhão no pescoço), MV+ sem RA, sem déficits neurológicos. ECG: bloqueio atrioventricular total com ritmo de escape juncional a 32 bpm, dissociação AV. Eletrólitos normais, troponina negativa, TSH normal. Em uso de losartana 50 mg e anlodipino 5 mg (sem betabloqueador ou verapamil). BAVT de provável causa degenerativa (doença de Lenègre).', 'Monitorização contínua, pás de marca-passo transcutâneo à beira do leito. Atropina não resolve. Internar em UTI para marca-passo transvenoso provisório e implante de marca-passo definitivo. Suspender anlodipino e manter PA sem tratar agressivamente. Cobertura da ferida facial.'),
  (594, 180, 4, '2022-06-14 09:30', 'internacao', 'Implante do marca-passo', 150, 84, 72, 61.0, 'Marca-passo provisório transvenoso colocado no PS, sem intercorrências. Hoje, implante de marca-passo definitivo bicameral (modo DDD) via veia cefálica esquerda, com limiares adequados (VD 0,6 V, AD 0,8 V) e sem pneumotórax. Frequência base programada em 60 bpm. Ecocardiograma: FEVE 64%, sem valvopatia importante, HVE leve. Assintomática, sem tontura, alta em 24 horas. Ferida limpa, curativo oclusivo mantido.', 'Orientações sobre cuidados com ferida, evitar elevar o braço esquerdo acima do ombro por 4 semanas. Retomar losartana 50 mg uma vez ao dia. Anlodipino mantido suspenso. Cartão do marca-passo entregue. Retorno em 10 dias para revisão da ferida e em 30 dias para teste do aparelho.'),
  (595, 180, 4, '2022-07-14 10:00', 'retorno', 'Revisão do marca-passo', 144, 82, 64, 61.4, 'Quatro semanas após implante, sem tontura nem síncope, voltou à hidroginástica sem movimentos bruscos do braço. Ferida com boa cicatrização, sem hematoma. Interrogação do dispositivo: bateria normal, limiares estáveis, estimulação ventricular em 98% do tempo, sem arritmias atriais. PA 144x82 com losartana, MRPA média 138x80, ligeiramente acima da meta para a idade. A filha pergunta sobre restrição de exames de ressonância.', 'Reintroduzir anlodipino 2,5 mg para atingir a meta, com controle de edema. Orientada que o marca-passo é compatível com ressonância condicional (modelo RM-condicional) mediante programação. Controle do dispositivo a cada 6 meses (presencial) com monitorização remota. Retorno em 6 meses.');
