insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (180, '2022-07-14', 'melhorou', 'BAV total degenerativo com síncope tratado com implante de marca-passo bicameral definitivo. Sem novas tonturas ou quedas, dispositivo com parâmetros normais e retorno às atividades. Segue em controle semestral do marca-passo e da PA.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (181, 'Tatiane Nascimento Brandão', 'F', '1986-03-25', 'Santo Antônio de Jesus', 'BA', 'Operadora de telemarketing', 'Cefaleia frequente, nunca tratou pressão. Mãe e duas tias hipertensas, uma delas com AVC aos 50 anos. Usa anticoncepcional injetável trimestral. Come muito embutido e macarrão instantâneo, pouco tempo para cozinhar. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (596, 181, 5, '2023-07-11 12:30', 'consulta', 'Dor de cabeça quase todo dia', 168, 104, 84, 78.5, 'Mulher de 37 anos, cefaleia holocraniana vespertina diária há 3 meses, sem sintomas neurológicos. Em medidas na farmácia, 160x100 a 170x105. PA hoje 168x104 e 164x102, nos dois braços iguais. IMC 29. Fundo de olho com cruzamento AV patológico leve. Exames: creatinina 0,8, potássio 4,1, urina 1 normal, glicemia 90, TSH normal. ECG normal. Hipertensão estágio 2 em mulher jovem, com história familiar importante. Rastreio de causa secundária básico negativo; a idade e a gravidade justificam atenção.', 'Iniciar olmesartana 20 mg + anlodipino 5 mg em comprimido único pela manhã (facilita adesão por ser um comprimido por dia). Orientar redução de sal e embutidos. Manter o injetável trimestral (só progestágeno). Orientada contracepção segura (BRA é contraindicado em gestação). MRPA e retorno em 3 semanas.'),
  (597, 181, 5, '2023-08-01 12:40', 'retorno', 'Dor de cabeça diminuiu bastante', 138, 86, 78, 77.9, 'Cefaleia reduziu de diária para 1 vez por semana. MRPA com média de 136x86. Sem edema, sem tontura, sem tosse. Aderência total, relata que o comprimido único ''facilitou, só tomo no almoço do trabalho''. Perdeu 600 g. Segue com muito sal na marmita do trabalho. Ainda acima da meta de 130x80.', 'Aumentar para olmesartana 40 mg + anlodipino 5 mg em comprimido único. Reforçar redução de sal e sugerir preparo de marmitas congeladas aos domingos. Dosar potássio e creatinina em 2 semanas. Retorno em 6 semanas com MRPA.'),
  (598, 181, 5, '2024-02-06 12:20', 'retorno', 'Vim buscar a receita nova', 124, 78, 72, 75.2, 'MRPA com média 122x76 há 5 meses, sem cefaleia. Perdeu 3,3 kg, cozinha em casa aos domingos e diminuiu os embutidos. Sem edema de tornozelos. Creatinina 0,8 e potássio 4,3. Mudou para método contraceptivo de barreira associado a DIU de cobre por escolha. Entende que a hipertensão em idade jovem pede acompanhamento por toda a vida.', 'Manter o comprimido único de olmesartana 40 mg + anlodipino 5 mg. Controle laboratorial anual. Se planejar gravidez, procurar a unidade antes de interromper contracepção para troca do esquema. Retorno em 6 meses.');
