insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (181, '2024-02-06', 'controlado', 'HAS estágio 2 em mulher jovem controlada com associação em comprimido único. MRPA com média 122x76, cefaleia resolvida e aderência total. Orientada sobre contracepção e contraindicação de BRA em gestação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (182, 'Matheus Okamoto Andrade', 'M', '1987-09-18', 'São Paulo', 'SP', 'Analista de sistemas', 'Saudável, sedentário, ansioso. Pressão alta em consultas, normal em casa segundo ele. Bebe 1 cerveja por semana, não fuma. Pai hipertenso aos 60 anos. Nenhum medicamento em uso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (599, 182, 1, '2023-05-09 18:30', 'consulta', 'Pressão alta em exame de admissão do emprego novo', 152, 96, 90, 82.0, 'Homem de 35 anos, assintomático, com PA de 156x98 no exame de admissão e 152x96 hoje (média de duas medidas). Visivelmente tenso, relata palpitações em consultórios desde a adolescência. MRPA de 7 dias levado hoje: média de 118x74 mmHg, sem valores acima de 130x80. Exame físico normal, IMC 26,5. Creatinina 0,9, potássio 4,2, ECG normal. Suspeita de hipertensão do avental branco; MAPA para confirmação.', 'Realizar MAPA 24h antes de decisão. Sem medicação. Orientações para atividade física regular e redução da cafeína (5 cafés por dia). Retorno com MAPA em 10 dias.'),
  (600, 182, 1, '2023-05-23 18:40', 'retorno', 'Trouxe o resultado da MAPA', 148, 94, 88, 81.6, 'MAPA 24h: média de vigília 120x76, sono 104x62, 24h 114x71, sem valores sustentados acima da meta, com descenso noturno preservado. PA de consultório 148x94 novamente. Concluído como hipertensão do avental branco (efeito isolado no consultório), sem indicação de tratamento medicamentoso. Ecocardiograma sem HVE (septo 9 mm) e albuminúria negativa: sem lesão de órgão-alvo. Aliviado em não precisar de remédio.', 'Sem fármacos. Reavaliação com MRPA ou MAPA a cada 12 meses, pois portadores de avental branco têm maior risco de desenvolver HAS sustentada. Manter atividade física (corrida 3x/semana) e menos cafeína. Retorno em 1 ano.');
