insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (182, '2023-05-23', 'estavel', 'Hipertensão do avental branco confirmada por MRPA e MAPA, sem lesão de órgão-alvo e sem necessidade de tratamento. Mantido em vigilância com MAPA ou MRPA anual, estilo de vida saudável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (183, 'Joaquim Elias Haddad Neto', 'M', '1960-07-02', 'Itabaiana', 'SE', 'Comerciante de tecidos', 'HAS há 12 anos em uso de losartana, dislipidemia sem tratamento, tabagista de 20 cigarros por dia há 40 anos. Pai falecido de infarto. Muito estressado com dívidas da loja.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (601, 183, 6, '2023-08-12 06:20', 'pronto_socorro', 'Dor forte no peito e mal-estar, suor frio', 90, 56, 48, 86.0, 'Homem de 63 anos com dor precordial em aperto, intensa, há 90 minutos, com náuseas, vômitos e sudorese. Ao exame: pálido, sudoreico, PA 90x56, FC 48, pulmões limpos, sem estase jugular. ECG: supradesnivelamento de ST em DII, DIII e aVF (4 mm em DIII) com infra especular em DI e aVL e BAV de 1º grau (PR 260 ms). Troponina 640 ng/L. HD: IAMCSST inferior, com bradicardia e hipotensão (provável acometimento vagal ou de VD). ECG direito com supra em V4R.', 'AAS 300 mg e ticagrelor 180 mg, heparina não fracionada, hidratação cautelosa com SF 0,9% 500 mL, evitar nitrato e diurético (infarto de VD). Atropina 0,5 mg EV para a bradicardia. Acionar hemodinâmica para angioplastia primária imediata e UTI.'),
  (602, 183, 10, '2023-08-12 09:30', 'internacao', 'Angioplastia primária', 108, 66, 62, 86.0, 'Coronariografia com oclusão trombótica da CD proximal (TIMI 0), DA com lesão de 40% e Cx sem lesões. Angioplastia com stent farmacológico 3,5 x 32 mm com fluxo TIMI 3 final, tempo porta-balão de 62 minutos. Pós-procedimento com PA 108x66 e FC 62, resolução do supra de ST (mais de 70%) e da dor. ECO: FEVE 50%, hipocinesia inferior e de VD leve. Sem complicações. Transferido para UTI.', 'UTI por 48 horas. Dupla antiagregação (AAS + ticagrelor) por 12 meses, atorvastatina 80 mg, metoprolol succinato 25 mg quando PA permitir. Suspender losartana por 48 horas. Cessação do tabagismo (aceita reposição de nicotina). Reabilitação cardíaca.'),
  (603, 183, 1, '2023-09-19 10:00', 'retorno', 'Primeiro retorno depois do infarto', 128, 76, 60, 84.0, 'Cinco semanas do infarto, assintomático, caminha 30 minutos por dia. Parou de fumar no dia do infarto e se mantém abstinente. Está no programa de reabilitação, com boa adaptação. Sem dispneia, sem bradicardia sintomática (FC 60 em uso de betabloqueador), BAV de 1º grau resolvido no ECG. PA 128x76. Vendeu parte do estoque da loja para pagar dívidas, relata menos estresse. LDL 64.', 'Retomar losartana 50 mg/dia (HAS e pós-IAM). Manter AAS, ticagrelor, atorvastatina e metoprolol. ECO de controle em 3 meses. Orientado retomada do trabalho em período parcial. Retorno em 3 meses.'),
  (604, 183, 1, '2024-03-12 10:20', 'retorno', 'Seis meses do infarto, tudo bem', 122, 74, 58, 82.8, 'Seis meses após IAMCSST inferior, sem angina, faz reabilitação 3x por semana e caminha 5 km aos sábados. Mantém abstinência do cigarro. ECO: FEVE 58%, sem hipocinesia residual significativa. LDL 58, glicemia 96. PA domiciliar média 120x72. Voltou à loja em tempo integral, está mais sereno. Sem sangramentos, sem dispneia pelo ticagrelor.', 'Manter o esquema atual até completar 12 meses de dupla antiagregação, depois AAS isolado. Manter estatina em dose alta, betabloqueador e losartana. Retorno em 6 meses.');
