insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (183, '2024-03-12', 'melhorou', 'IAMCSST inferior com acometimento de ventrículo direito tratado com angioplastia primária. Recuperação completa da função ventricular (FEVE 58%), abstinente do cigarro, LDL na meta e em reabilitação. Segue em prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (184, 'Marlene Tavares Costa Ferro', 'F', '1951-11-06', 'Penedo', 'AL', 'Aposentada, ex-pescadora artesanal', 'HAS e DM2 há 20 anos. Angina aos esforços há 1 ano, sem investigação até agora. Em uso de losartana 50 mg 12/12h, metformina 850 mg e glibenclamida. Nunca fumou. Mora em povoado ribeirinho, a 2 horas de barco e carro da cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (605, 184, 1, '2022-11-15 09:20', 'consulta', 'Aperto no peito quando caminho até o rio', 150, 86, 84, 72.0, 'Paciente de 71 anos com dor torácica em aperto, aos pequenos esforços (andar 100 metros, carregar balde), aliviada em 5 minutos com repouso. Angina CCS III. Diabética e hipertensa, portadora de claudicação em panturrilha direita. Ao exame: PA 150x86, RCR 2T BNF, sopro sistólico suave em foco aórtico, pulsos pediosos diminuídos. ECG: ritmo sinusal, alteração de repolarização em parede lateral. Glicose 210, HbA1c 8,9%, LDL 154, creatinina 1,1. Probabilidade alta de DAC multiarterial.', 'AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg, mononitrato de isossorbida 20 mg 2x/dia. Suspender glibenclamida pelo risco de hipoglicemia na idosa e manter metformina; solicitada consulta com endócrino. Solicitar cintilografia miocárdica e ECO. Retorno em 3 semanas.'),
  (606, 184, 10, '2022-12-06 09:30', 'retorno', 'Trouxe o exame do coração', 138, 80, 62, 71.4, 'Persistem crises de angina 3x por semana, mesmo com betabloqueador e nitrato. Cintilografia com isquemia extensa em paredes anterior e lateral (SDS 14, 28% do VE), FEVE 52%. ECO com HVE leve e esclerose aórtica sem estenose. Dado o perfil (diabética, longa duração, isquemia extensa), indicada coronariografia. Dificuldade de deslocamento dela, que pergunta se pode fazer tudo num só lugar.', 'Coronariografia agendada para janeiro. Associar anlodipino 5 mg pela angina persistente e PA. Manter metoprolol. Orientada sobre jejum e suspensão de metformina 48 horas antes do contraste. Alojamento da família providenciado pela assistência social.'),
  (607, 184, 10, '2023-01-17 07:40', 'internacao', 'Cateterismo', 142, 82, 60, 71.0, 'Coronariografia: lesão de 80% em tronco de coronária esquerda distal, DA com 90% proximal e oclusão de 70% em segmento médio, Cx com 85% em ramo marginal e CD com 75% em terço médio. SYNTAX score 38. FEVE 52%. Não candidata a angioplastia isolada pela complexidade e pelo diabetes. Indicada revascularização cirúrgica do miocárdio. Serviço de cirurgia cardiovascular local sem disponibilidade de vaga eletiva em menos de 3 meses. Discutido com centro de referência de Recife, que aceitou a transferência.', 'Manter AAS, estatina, betabloqueador. Transferência com relatório completo e imagens do cateterismo ao hospital de referência em cirurgia cardíaca em Recife (PE), em ambulância, com vaga confirmada. Informada a família. Orientação de procurar PS se dor em repouso até a transferência.');
