insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (184, '2023-01-19', 'transferido', 'Transferida em ambulância para hospital de referência em cirurgia cardiovascular em Recife para revascularização miocárdica por doença multiarterial com lesão de tronco (SYNTAX 38). Saiu do acompanhamento da rede com relatório completo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (185, 'Edgar Matos Teixeira da Cruz', 'M', '1978-05-14', 'Simões Filho', 'BA', 'Soldador industrial', 'Etilismo pesado há 20 anos (mais de 1 litro de cachaça por dia nos fins de semana, cerveja diária). Tabagista. HAS leve sem tratamento. Sem diabetes. Separado, mora com a mãe. Sem histórico familiar de cardiopatia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (608, 185, 11, '2022-05-10 08:30', 'consulta', 'Falta de ar para andar e inchaço nos pés', 118, 78, 104, 78.0, 'Homem de 43 anos com dispneia progressiva há 5 meses, NYHA III, ortopneia e edema de MMII 2+/4+. Etilista crônico. Ao exame: taquicárdico, PA 118x78, estase jugular, estertores bibasais, B3, ascite discreta, hepatomegalia dolorosa. ECG: taquicardia sinusal com bloqueio de ramo esquerdo incompleto. ECO: VE dilatado (DDVE 68 mm), FEVE 26%, IM funcional moderada. NT-proBNP 4.900. Creatinina 1,2, TSH normal, coronariografia prévia sem lesões. Cardiomiopatia alcoólica (diagnóstico de exclusão).', 'Abstinência total de álcool (principal tratamento), apoio do CAPS-AD. Sacubitril/valsartana 24/26 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg e dapagliflozina 10 mg, tiamina 300 mg/dia. Furosemida 40 mg. Dosar potássio e creatinina em 1 semana. Retorno em 3 semanas.'),
  (609, 185, 11, '2022-10-04 08:40', 'retorno', 'Estou bem melhor, faz 4 meses que não bebo', 110, 70, 64, 71.2, 'Abstinente há 4 meses com acompanhamento no CAPS-AD, sem recaídas. NYHA I-II, sem edema, sem ortopneia. Peso seco 71 kg. PA 110x70, FC 64, boa tolerância ao quadro de quatro pilares (sacubitril/valsartana 49/51 mg e carvedilol 12,5 mg 12/12h). Potássio 4,6 e creatinina 1,1. ECO: FEVE subiu para 41% e DDVE reduziu para 62 mm. NT-proBNP 620. Voltou ao trabalho em área administrativa da empresa.', 'Manter os quatro pilares e a tiamina. Furosemida SN. Repetir ECO em 6 meses; se FEVE ≥ 50% manter o tratamento mesmo assim. Reforçar abstinência definitiva: qualquer recaída leva a nova deterioração. Retorno em 3 meses.'),
  (610, 185, 11, '2023-04-18 09:00', 'retorno', 'Voltei a ficar cansado', 124, 80, 96, 77.5, 'Admite recaída: voltou a beber após separação e demissão há 2 meses, ''só uma cervejinha'' que virou garrafas de cachaça nos fins de semana. Parou de ir ao CAPS e deixou de tomar sacubitril/valsartana e espironolactona por mais de 3 semanas. Dispneia NYHA III, edema 2+/4+, ganho de 6,3 kg. PA 124x80, FC 96. ECO: FEVE caiu para 29%. NT-proBNP 3.800. Creatinina 1,3, potássio 4,7.', 'Reiniciar sacubitril/valsartana 24/26 mg, espironolactona e dapagliflozina; furosemida 40 mg 12/12h por uma semana. Encaminhar de volta ao CAPS-AD com agendamento imediato e apoio da assistência social. Reforçado que o coração recuperou antes e pode recuperar novamente com abstinência. Retorno em 2 semanas.');
