insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (185, '2023-04-18', 'piorou', 'Após melhora expressiva (FEVE de 26% para 41%) durante a abstinência, houve recaída alcoólica com perda do emprego, abandono dos medicamentos e retorno da descompensação (FEVE 29%, NYHA III). Retomado tratamento e encaminhamento ao CAPS-AD.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (186, 'Sônia Regina Fonseca Albuquerque', 'F', '1959-01-22', 'Campina Grande', 'PB', 'Professora aposentada', 'HAS há 15 anos controlada com losartana 50 mg. Hipotireoidismo tratado. Sem tabagismo, atividade física regular (pilates). Sem episódios arrítmicos prévios.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (611, 186, 4, '2023-02-07 10:10', 'consulta', 'Coração dispara de repente e não passa', 128, 76, 148, 67.0, 'Mulher de 64 anos com palpitações regulares há 5 dias, dispneia leve e cansaço. ECG: flutter atrial típico (ondas F em dente de serra em D2, D3, aVF, negativas) com condução AV 2:1 e FC de 148 bpm. Ao exame: taquicárdica, regular, sem sinais de IC, PA 128x76. ECO: AE 42 mm, FEVE 60%, sem valvopatia. TSH 2,0 (em reposição). CHA2DS2-VASc 2 (sexo feminino e HAS). Indicada anticoagulação e controle do ritmo ou frequência.', 'Iniciar apixabana 5 mg 12/12h e metoprolol succinato 50 mg para reduzir a FC. Orientada sobre cardioversão elétrica após 3 semanas ou ablação do istmo cavotricuspídeo, que tem taxa de cura acima de 90% no flutter típico. Preferiu ablação. Retorno em 4 semanas.'),
  (612, 186, 4, '2023-04-04 07:30', 'internacao', 'Ablação do flutter', 124, 74, 96, 66.5, 'Internação eletiva após 8 semanas de anticoagulação sem falhas. Mantém flutter com FC 96 em uso de metoprolol. ETE prévio sem trombo. Realizada ablação por cateter do istmo cavotricuspídeo com radiofrequência e irrigação, com bloqueio bidirecional confirmado ao fim do procedimento e reversão a ritmo sinusal durante a aplicação. Sem complicações, hemostasia da via femoral satisfatória. Alta no mesmo dia à tarde, em ritmo sinusal, FC 68.', 'Manter apixabana por no mínimo 3 meses e depois reavaliar conforme CHA2DS2-VASc e achados do monitor. Manter metoprolol por 1 mês, depois suspender se FC baixa. Repouso relativo por 3 dias, evitar esforço intenso por 1 semana. Retorno em 4 semanas.'),
  (613, 186, 4, '2023-10-10 10:00', 'retorno', 'Seis meses depois, nenhuma palpitação', 126, 74, 64, 66.8, 'Seis meses após a ablação, ritmo sinusal em todos os registros: Holter de 7 dias sem flutter nem FA, FC média 66. Voltou aos exercícios de pilates sem sintomas. Sem sangramentos com apixabana. Questiona se pode parar o anticoagulante. Pontua CHA2DS2-VASc 2 (sexo feminino e HAS), ou seja, apenas um fator de risco além do sexo; sem registro de FA.', 'Após decisão compartilhada, suspender apixabana (apenas um fator de risco além do sexo, ritmo sinusal estável por 6 meses e sem FA documentada). Metoprolol já suspenso. Manter losartana. Monitor de eventos anual por 2 anos. Retorno em 6 meses; se palpitações, fazer ECG imediato.');
