insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (186, '2023-10-10', 'melhorou', 'Flutter atrial típico tratado com ablação do istmo cavotricuspídeo, sem recorrência em 6 meses de Holter (ritmo sinusal em 100%). Anticoagulante suspenso por decisão compartilhada e segue em vigilância com monitor de eventos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (187, 'Ivo Zanotelli Pagnoncelli', 'M', '1942-02-08', 'Vitória', 'ES', 'Aposentado, ex-despachante aduaneiro', 'HAS há 40 anos, dislipidemia, hipotireoidismo. Estenose aórtica degenerativa conhecida há 6 anos, em seguimento com ecocardiogramas anuais. Joga bocha com amigos. Mora com a esposa de 78 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (614, 187, 1, '2023-03-14 09:30', 'consulta', 'Quase desmaiei na quadra de bocha', 118, 74, 70, 74.5, 'Homem de 81 anos com episódio de síncope ao esforço há 10 dias, dispneia aos médios esforços e angina leve em subida. Ao exame: PA 118x74, pulso parvus et tardus, sopro sistólico ejetivo 4+/6+ em foco aórtico irradiado para carótidas, B2 hipofonética, sem sinais de congestão. ECO: valva aórtica calcificada, área valvar 0,7 cm², gradiente médio 52 mmHg, velocidade máxima 4,8 m/s, FEVE 58%, HVE moderada. Estenose aórtica grave sintomática (síncope, dispneia e angina).', 'Indicação de intervenção valvar. Proibido esforço físico intenso. Evitar vasodilatadores e depleção volêmica; manter losartana em dose baixa. Solicitar angiotomografia de aorta e ilíaco-femorais, coronariografia e avaliação do heart team (risco cirúrgico STS elevado pela idade). Retorno em 2 semanas.'),
  (615, 187, 10, '2023-04-04 09:20', 'retorno', 'Resultado dos exames e do heart team', 124, 72, 68, 74.0, 'Coronariografia sem lesões obstrutivas. Angiotomografia: anel aórtico de 24 mm, bom acesso transfemoral bilateral, calcificação valvar importante, sem calcificação excessiva da raiz. O heart team indicou TAVI (implante transcateter de bioprótese aórtica) por idade acima de 80 anos, fragilidade moderada e risco cirúrgico intermediário a alto. Paciente e esposa concordam. Escore de fragilidade preservado: caminha 1 km sem parar.', 'Agendar TAVI transfemoral. Antes do procedimento, avaliação odontológica, urina 1 e swab nasal. Manter profilaxia endocardite. Orientado a procurar PS se síncope ou dor torácica antes da data. Retorno com cirurgia cardíaca em 2 meses.'),
  (616, 187, 10, '2023-06-06 07:00', 'internacao', 'Implante da válvula', 130, 76, 72, 73.8, 'TAVI transfemoral com bioprótese autoexpansível 29 mm sob sedação, sem intercorrências. Gradiente médio pós-implante de 8 mmHg, leve regurgitação paravalvar. Sem bloqueio atrioventricular de alto grau nas primeiras 48 horas (BRE novo, QRS 138 ms). Sem complicações no acesso. Alta no 3º dia, deambulando. Sem síncope, dispneia melhor. Mantido AAS isolado como antiagregação.', 'AAS 100 mg indefinidamente. Monitorar bloqueios por ECG seriado e Holter em 30 dias dado BRE novo. Profilaxia de endocardite em procedimentos odontológicos (portador de prótese). Retorno em 30 dias com ECO.'),
  (617, 187, 1, '2023-09-12 09:40', 'retorno', 'Voltei a jogar bocha', 134, 76, 66, 75.0, 'Três meses após TAVI, sem síncope, sem dispneia e sem angina, voltou à bocha duas vezes por semana. Holter sem BAV de alto grau, apenas BAV de 1º grau persistente. ECO: prótese normofuncionante, gradiente médio 9 mmHg, regurgitação paravalvar discreta, FEVE 62%. Hemoglobina 13,4. Faz a higiene bucal rigorosa e foi ao dentista. PA domiciliar 130 a 138 sistólica, aceitável para a idade.', 'Manter AAS 100 mg e atorvastatina. Aumentar losartana para 50 mg para PA de consultório. ECO anual e Holter em 1 ano. Profilaxia de endocardite antes de procedimentos dentários. Retorno em 6 meses.');
