insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (187, '2023-09-12', 'melhorou', 'Estenose aórtica grave sintomática tratada com TAVI transfemoral aos 81 anos. Prótese normofuncionante, assintomático, sem síncope e de volta à atividade esportiva leve. Segue com ECO anual e profilaxia para endocardite.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (188, 'Eunice Rodrigues Pitombo', 'F', '1965-10-29', 'Barreiras', 'BA', 'Lavradora', 'Doença de Chagas diagnosticada em 2009 após doação de sangue, bloqueio de ramo direito. Nasceu em casa de pau a pique no interior. Hipertensão leve, sem tratamento. Viúva, cria dois netos, depende de transporte intermunicipal para ir ao centro de saúde.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (618, 188, 6, '2021-08-05 03:50', 'pronto_socorro', 'Desmaiei duas vezes de madrugada e o coração está muito devagar', 156, 70, 30, 58.0, 'Mulher de 55 anos, chagásica, com duas síncopes na última semana e uma hoje, sem pródromos, com queda e laceração no supercílio. Ao exame: bradicárdica a 30 bpm, pulso regular, PA 156x70, ondas a em canhão, estertores discretos em bases, sem edema. ECG: bloqueio atrioventricular total com escape ventricular a 30 bpm, QRS largo (BRD prévio). Eletrólitos normais, troponina negativa. HD: BAVT por cardiopatia chagásica (síndrome de Stokes-Adams).', 'Monitorização, marca-passo transcutâneo à beira leito, atropina sem resposta. Internar na UTI para marca-passo provisório e implante de marca-passo definitivo. Suturar o supercílio. Sem medicação cronotrópica negativa. ECO e Holter após estabilização.'),
  (619, 188, 4, '2021-08-07 10:00', 'internacao', 'Implante do marca-passo', 138, 78, 70, 58.0, 'Marca-passo provisório sem intercorrências. Implantado marca-passo definitivo bicameral por punção da subclávia esquerda, limiares estáveis. ECO: VE com FEVE 48%, hipocinesia inferior e aneurisma de ponta pequeno, sem trombo. Holter prévio com extrassístoles ventriculares frequentes e uma TVNS de 5 batimentos. Indicado tratamento da IC leve, sem benznidazol por cardiopatia chagásica crônica estabelecida. Alta em 48h, assintomática.', 'Iniciar enalapril 5 mg 12/12h e carvedilol 3,125 mg 12/12h (protegida pelo MP). Reavaliar ECO em 6 meses. Cartão do marca-passo e orientações de ferida. Retorno em 3 semanas. Agendar assistência social para o transporte intermunicipal.'),
  (620, 188, 4, '2021-09-01 09:30', 'retorno', 'Estou me sentindo bem, mas moro longe', 128, 76, 68, 58.6, 'Quatro semanas do implante, ferida cicatrizada, sem síncopes, boa tolerância ao enalapril e ao carvedilol. Interrogação do marca-passo normal. PA 128x76, FC 68 (estimulada). Relata dificuldade financeira para pagar o transporte (dois ônibus e 80 km) e que alguém precisa ficar com os netos no dia das consultas. Orientada sobre a doença de Chagas e a importância de manter o seguimento para tratar a insuficiência cardíaca e as arritmias.', 'Manter enalapril e carvedilol com renovação para 90 dias para reduzir deslocamentos. Contato com a unidade básica de Barreiras para acompanhamento de PA e emissão de receitas. Controle do marca-passo em 6 meses. Retorno em 6 meses.'),
  (621, 188, 11, '2022-03-08 09:50', 'retorno', 'Vim fazer o controle do aparelho', 124, 74, 70, 59.2, 'Seis meses depois, NYHA I-II, sem síncopes. Marca-passo com parâmetros normais. ECO: FEVE 44%. Holter com ESV 2.400/24h, sem TVNS. Ficou 3 semanas sem carvedilol por falta na farmácia municipal. Receitas renovadas hoje para 120 dias. Combinado envio de relatório à unidade básica de saúde.', 'Manter enalapril 5 mg 12/12h e carvedilol 6,25 mg 12/12h (aumento). Adicionar espironolactona 25 mg pela redução da FEVE, com potássio em 2 semanas via unidade básica. ECO e controle do MP em 6 meses. Reforçada a importância de não faltar às consultas.');
