insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (188, '2023-03-20', 'abandonou', 'Não compareceu aos retornos de setembro de 2022 e março de 2023 e não foi localizada por telefone; a unidade básica informou que mudou de município com os netos. Último registro: marca-passo funcionante e FEVE 44%, com adesão irregular por distância e custo de transporte.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (189, 'Wellington Cunha Bispo', 'M', '1990-12-14', 'Paulo Afonso', 'BA', 'Policial militar', 'Saudável, praticante de musculação. Episódios de palpitações súbitas desde os 22 anos, de início e término abruptos, duração de minutos, sem síncope. Usa suplemento pré-treino com cafeína. Sem medicamentos contínuos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (622, 189, 6, '2023-04-02 20:40', 'pronto_socorro', 'Coração disparou de repente, não passa há 40 minutos', 118, 76, 188, 88.0, 'Homem de 32 anos com palpitações de início súbito durante o treino, FC 188, sem dor torácica, tontura leve e leve dispneia. Ao exame: ansioso, bom estado geral, PA 118x76, pulso regular rápido, sem sinais de congestão. ECG: taquicardia regular de QRS estreito a 188 bpm, sem ondas P visíveis, sem pré-excitação. HD: taquicardia supraventricular paroxística (provável reentrada nodal). Estável hemodinamicamente. Manobras vagais com Valsalva modificado falharam.', 'Adenosina 6 mg EV em bolus rápido seguida de flush: reversão para ritmo sinusal em 15 segundos, com pausa transitória e sensação de desconforto torácico. ECG pós-reversão sem pré-excitação, FC 72. Liberado com orientação de agendar cardiologia e evitar suplementos estimulantes.'),
  (623, 189, 4, '2023-04-25 17:30', 'consulta', 'Quero resolver de vez, não posso ter isso no serviço', 120, 74, 66, 87.6, 'Terceira crise documentada em 10 anos, a segunda em 2023 (anterior em fevereiro, resolvida sozinha após 10 minutos). Atividade como policial exige prontidão. Exame: coração normal, sem sopros. ECO normal (FEVE 64%, sem cardiopatia estrutural). Holter 24h: ritmo sinusal, sem pré-excitação, sem outras arritmias. Teste ergométrico normal sem arritmia. Hipótese de TRN (taquicardia por reentrada nodal) pelo padrão do ECG, reversão com adenosina e ausência de pré-excitação. Discutidas opções: betabloqueador, antiarrítmico ou ablação com sucesso acima de 95%.', 'Optou por ablação por cateter. Enquanto aguarda, metoprolol succinato 25 mg/dia e manobra de Valsalva modificado na crise. Suspender suplemento pré-treino com cafeína. Estudo eletrofisiológico com ablação agendado. Retorno depois do procedimento.'),
  (624, 189, 4, '2023-07-11 07:30', 'internacao', 'Procedimento de ablação', 122, 72, 62, 87.0, 'Estudo eletrofisiológico: indução de taquicardia por reentrada nodal AV típica (lenta-rápida) com intervalo VA curto de 45 ms, sem via acessória. Ablação por radiofrequência da via lenta na região do septo posteroinferior, com ritmo juncional acelerado durante a aplicação, sem BAV. Sem indução de taquicardia após o procedimento, mesmo com isoproterenol e atropina. PR 150 ms mantido. Alta no mesmo dia, sem complicações no acesso femoral.', 'Suspender metoprolol. Evitar esforços intensos por 5 dias, retornar à musculação em 1 semana. Retorno em 30 dias com ECG e em 3 meses se sem recidiva.'),
  (625, 189, 4, '2023-10-17 17:40', 'retorno', 'Três meses sem nenhuma crise', 118, 72, 64, 88.4, 'Três meses após ablação da via lenta, sem palpitações, sem crises, sem tonturas. Voltou ao serviço operacional e à musculação sem restrições. ECG: ritmo sinusal, PR 152 ms, sem pré-excitação. Evita pré-treino com cafeína. Satisfeito: ''nunca mais senti o coração disparar''. Ferida inguinal cicatrizada, sem hematoma.', 'Alta do seguimento arritmológico com orientação de retornar se recorrência dos sintomas. Seguimento clínico anual com a unidade. Check-up cardiovascular conforme rotina da corporação. Sem medicamentos.');
