insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (190, '2024-06-18', 'melhorou', 'Pericardite aguda viral não complicada tratada com anti-inflamatório e colchicina por 3 meses, com resolução clínica e dos marcadores em duas semanas. Liberada para exercício após 3 meses, sem recidiva e sem sequelas ao ECO.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (191, 'Cristiane Pontes Altenhofen', 'F', '1982-04-19', 'Salvador', 'BA', 'Gerente de banco', 'Sem doenças crônicas conhecidas. Sedentária, trabalha 10 horas sentada, almoça fora todos os dias. Ganhou 9 kg em 3 anos. Pai com HAS. Usa DIU de cobre. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (629, 191, 1, '2023-08-22 17:30', 'consulta', 'Check-up da empresa disse que minha pressão está no limite', 132, 86, 80, 79.0, 'Mulher de 41 anos, assintomática, com PA 134x88 no check-up. Hoje 132x86 e 130x84. IMC 29,6, circunferência abdominal 94 cm. Exame cardiovascular normal. Glicemia 96, LDL 128, creatinina 0,7, potássio 4,2, TSH normal. ECG normal. MRPA de 5 dias: média 128x82. Classificada como pré-hipertensão (130-139/80-89) com risco cardiovascular baixo, sem lesão de órgão-alvo. Fatores modificáveis: sobrepeso, sedentarismo e muito sal.', 'Sem medicação. Mudança de estilo de vida: perda de 5 a 7% do peso, caminhar 150 minutos por semana, reduzir sal (almoço fora), mais frutas e verduras. Reavaliar com MRPA em 3 meses. Orientada a medir a PA periodicamente.'),
  (630, 191, 1, '2023-11-28 17:40', 'retorno', 'Perdi uns quilos, vim mostrar a pressão', 118, 76, 72, 73.8, 'Perdeu 5,2 kg em 3 meses: marmita preparada aos domingos, troca do elevador por escada, caminhada de 40 minutos 4x/semana, parou o refrigerante. PA no consultório 118x76, MRPA média 120x74. Sem queixas. Está motivada pelo resultado. Circunferência abdominal 88 cm.', 'Manter as mudanças de estilo de vida, sem medicamentos. Meta de peso 70 kg. Nova avaliação com MRPA em 6 meses. Reforçado que a pré-hipertensão pode evoluir para HAS sem a manutenção das medidas.'),
  (631, 191, 1, '2024-08-13 17:20', 'retorno', 'Retorno anual', 116, 72, 68, 71.0, 'Um ano depois, manteve a perda de peso (71 kg, IMC 26,6) e a atividade física. MRPA média 118x72. LDL 104, glicemia 90. Faz musculação duas vezes por semana. Sem sintomas. PA no consultório e em casa na faixa normal. Pergunta se pode ter alta; informada sobre vigilância anual.', 'Alta do ambulatório de cardiologia para a unidade básica, com aferição anual da PA e perfil lipídico. Retornar se MRPA acima de 130x80. Manter peso e estilo de vida.');
