insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (191, '2024-08-13', 'controlado', 'Pré-hipertensão revertida apenas com mudança de estilo de vida: perda de 8 kg, atividade física regular e menos sal. PA normal em consultório e MRPA (118x72) sem medicação. Recebeu alta para vigilância anual na unidade básica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (192, 'Osvaldo Brito Mendonça', 'M', '1955-02-23', 'Aracaju', 'SE', 'Advogado aposentado', 'HAS há 20 anos e dislipidemia, em uso de losartana 50 mg 12/12h e rosuvastatina 10 mg. Ex-fumante (parou em 2005). Sedentário, caminha pouco. Irmão com stent aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (632, 192, 2, '2022-03-08 15:30', 'consulta', 'Dor no peito ao caminhar rápido, passa quando paro', 138, 82, 80, 84.0, 'Homem de 67 anos com desconforto retroesternal em aperto ao caminhar rápido ou subir uma ladeira, há 3 meses, com duração de 3 a 4 minutos e alívio com repouso, 2 a 3 vezes por semana. Angina típica CCS II. Sem dispneia em repouso, sem síncope. Ao exame: RCR 2T BNF, sem sopros, pulsos presentes. ECG de repouso normal. LDL 112. Teste ergométrico: infra de ST de 1,5 mm em V5-V6 aos 7 minutos com dor, sem arritmias. Probabilidade pré-teste alta e isquemia leve a moderada.', 'Iniciar AAS 100 mg, metoprolol succinato 50 mg, trocar rosuvastatina por atorvastatina 80 mg. Nitrato sublingual SN. Solicitar ecocardiograma e cintilografia para estratificar. Estratégia inicial de tratamento clínico otimizado. Retorno em 4 semanas.'),
  (633, 192, 2, '2022-04-05 15:40', 'retorno', 'A dor diminuiu, mas ainda aparece', 124, 74, 58, 83.5, 'Crises de angina reduzidas para 1 por semana, aos esforços maiores. FC 58, PA 124x74. Cintilografia miocárdica: isquemia leve em parede lateral (SDS 4, 8% do VE), FEVE 60%. ECO com FEVE 61%, sem alterações segmentares. Perfil de baixo risco para eventos, sem critérios de alto risco que exijam cateterismo imediato. Concorda com tratamento clínico e reabilitação.', 'Manter AAS, atorvastatina, losartana, metoprolol. Associar anlodipino 5 mg pela angina residual. Reabilitação cardiovascular supervisionada. Cateterismo se piora de classe funcional. Retorno em 3 meses.'),
  (634, 192, 2, '2023-03-14 15:20', 'retorno', 'Quase não sinto mais dor, faço hidroginástica', 122, 72, 60, 80.2, 'Há um ano em tratamento clínico otimizado e reabilitação, caminha 4 km e faz hidroginástica 2x por semana, angina apenas 1 vez ao mês. Perdeu 3,8 kg. LDL 58 e PA domiciliar média 120x72. Sem edema. Uso do nitrato SN apenas 2 vezes no ano. Capacidade funcional de 9 METs em novo ergométrico, com infra de ST discreto sem dor (isquemia silenciosa leve).', 'Manter o tratamento clínico. Ergométrico anual. Cateterismo apenas se sintomas limitantes ou aumento da área de isquemia. Reforçar adesão a AAS e estatina. Retorno em 6 meses.');
