insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (192, '2023-03-14', 'controlado', 'Angina estável com isquemia leve controlada por tratamento clínico otimizado e reabilitação, sem necessidade de cateterismo. Angina rara (1x por mês), LDL 58 e PA 122x72. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (193, 'Priscila Andrade Lacerda', 'F', '1993-08-12', 'Maceió', 'AL', 'Designer gráfica', 'Primeira gestação de 37 semanas, sem intercorrências, parto vaginal há 5 semanas. Sem doenças prévias, sem história familiar de cardiopatia. Amamenta exclusivamente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (635, 193, 11, '2023-11-14 09:00', 'consulta', 'Falta de ar ao deitar e para trocar o bebê', 104, 66, 112, 63.0, 'Puérpera de 30 anos, 5 semanas após parto vaginal, com dispneia progressiva há 2 semanas, ortopneia com três travesseiros, tosse noturna, cansaço intenso e edema de pés. Ao exame: taquicárdica, PA 104x66, estase jugular a 45 graus, B3, sopro sistólico de IM funcional, estertores bibasais, edema 2+/4+. ECG: taquicardia sinusal, alterações inespecíficas de T. ECO: VE dilatado (DDVE 62 mm), FEVE 27%, sem trombo, IM moderada funcional. NT-proBNP 5.200. Troponina normal. Hipótese: cardiomiopatia periparto.', 'Internar para compensação. Furosemida EV, restrição de sal. Iniciar enalapril 5 mg 12/12h (compatível com amamentação), carvedilol 3,125 mg 12/12h e espironolactona 25 mg. Contracepção segura (IECA contraindicado em gestação). Discutir bromocriptina para suspender a lactação com a equipe, após decisão da paciente. Anticoagulação profilática com heparina.'),
  (636, 193, 11, '2024-02-20 09:20', 'retorno', 'Estou bem melhor, já consigo carregar meu filho', 108, 68, 66, 58.4, 'Alta hospitalar em 6 dias. Hoje NYHA I-II, sem ortopneia e sem edema. Optou por manter o aleitamento por 6 meses. ECO: FEVE 42%, DDVE 56 mm, IM leve. NT-proBNP 410. Potássio 4,4, creatinina 0,7. PA 108x68, FC 66, boa tolerância. Usa DIU de cobre colocado há 1 mês. Marido ajuda nas noites, ela retomou o trabalho em casa. Ansiosa com a possibilidade de nova gravidez.', 'Dobrar enalapril para 10 mg 12/12h e carvedilol para 6,25 mg 12/12h. Manter espironolactona. Reforçada a contracepção e a necessidade de aconselhamento pré-concepcional (gravidez novamente tem risco alto se FEVE abaixo de 50%). ECO em 3 meses. Retorno em 3 meses.'),
  (637, 193, 11, '2024-09-17 09:10', 'retorno', 'Retorno com o ecocardiograma novo', 110, 70, 62, 57.8, 'Dez meses do diagnóstico, assintomática e com plena rotina. ECO: FEVE 55%, DDVE 50 mm, IM mínima: recuperação da função ventricular. NT-proBNP 120. Ressonância cardíaca sem fibrose (sem realce tardio). Desmamou do aleitamento há 3 meses. PA 110x70, FC 62. Continua com contracepção. Discussão sobre manter ou não o tratamento: orientada que a retirada deve ser cuidadosa e que a manutenção por pelo menos 12 meses após a normalização é a prática.', 'Manter enalapril, carvedilol e espironolactona por mais 12 meses antes de tentar retirada gradual sob monitorização. Contracepção obrigatória enquanto em uso de IECA e espironolactona. Aconselhamento pré-concepcional com obstetrícia antes de qualquer nova gestação. Retorno em 4 meses.');
