insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (193, '2024-09-17', 'melhorou', 'Cardiomiopatia periparto com FEVE inicial de 27% teve recuperação completa da função ventricular (FEVE 55%) em 10 meses com terapia da IC e contracepção segura. Mantém o tratamento por mais 12 meses e aconselhamento antes de nova gestação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (194, 'Adelmo Santana Dória', 'M', '1957-03-28', 'Simão Dias', 'SE', 'Eletricista aposentado', 'HAS há 25 anos e DM2 há 10 anos, obesidade grau II (IMC 36). Apneia do sono não investigada. Em uso de losartana 100 mg, anlodipino 10 mg, metformina 1 g 12/12h e furosemida 40 mg. Come muito salgado. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (638, 194, 11, '2022-02-15 09:30', 'consulta', 'Cansaço e inchaço nas pernas há 2 meses', 148, 88, 76, 108.0, 'Homem de 64 anos, obeso, hipertenso e diabético, com dispneia NYHA II-III, ortopneia leve e edema de MMII 2+/4+ há 2 meses, com ganho de 5 kg. Exame: PA 148x88, estase jugular discreta, RCR 2T B4, estertores em bases, edema, hepatomegalia leve. ECO: FEVE 60%, HVE concêntrica (septo 14 mm), átrio esquerdo 46 mm, disfunção diastólica grau II (E/e'' 16), PSAP 44 mmHg. NT-proBNP 1.480. Creatinina 1,2. HbA1c 8,2%. ICFEp com congestão em obeso diabético hipertenso.', 'Furosemida 40 mg 12/12h por 7 dias, depois 40 mg/dia. Iniciar empagliflozina 10 mg (benefício na ICFEp e no DM2) e espironolactona 25 mg. Manter losartana e anlodipino. Restrição de sal, redução de peso e atividade física leve. Polissonografia. Retorno em 3 semanas.'),
  (639, 194, 11, '2022-03-08 09:40', 'retorno', 'Perdi o inchaço', 134, 80, 72, 100.4, 'Perdeu 7,6 kg em 3 semanas (líquido), edema resolvido, dorme com um travesseiro. Potássio 4,9, creatinina 1,3. Glicemias menores em casa. Sem infecção genital. PA 134x80. Dificuldade para o transporte até a clínica (60 km) e para pagar a empagliflozina, que a farmácia popular não fornece. Aceitou continuar porque ''o inchaço sumiu''.', 'Manter esquema. Fornecer amostras e cadastrar para dispensação no programa estadual. Peso diário. Retorno em 3 meses. Dosar potássio e creatinina em 1 mês na unidade de saúde local.'),
  (640, 194, 11, '2022-07-12 09:50', 'retorno', 'Estou bem, mas o remédio caro acabou', 144, 86, 80, 103.8, 'Quatro meses depois, peso subiu 3,4 kg e edema 1+/4+ voltou. A empagliflozina acabou há 5 semanas, e o cadastro no programa estadual não saiu. Parou também a espironolactona por ''ficar com a boca seca'' e porque não consegue ir ao laboratório local. Dispneia NYHA II. Potássio não dosado desde março. PA 144x86. Aceita retomar mas diz que o transporte é difícil. Orientado a não suspender medicamentos sem avisar.', 'Reiniciar empagliflozina (receita entregue com carta ao programa), espironolactona 25 mg e furosemida 40 mg. Dosar potássio e creatinina em 1 semana na unidade local. Retorno em 2 meses. Agente comunitário de saúde avisado para visita domiciliar e conferência dos remédios.');
