insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (194, '2023-01-10', 'abandonou', 'Não compareceu aos retornos de setembro e novembro de 2022. O agente comunitário relatou que o paciente não conseguia custear o transporte de 60 km e ficou sem empagliflozina e espironolactona. Sem notícia de internação até o último contato.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (195, 'Nelson Hideo Takahashi', 'M', '1950-12-02', 'São José do Rio Preto', 'SP', 'Engenheiro agrônomo aposentado', 'HAS e DM2 há 20 anos, em uso de losartana e metformina. Dislipidemia. Praticante de natação. Nega tabagismo e etilismo. Esposa falecida em 2020, mora sozinho, filha vizinha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (641, 195, 4, '2023-01-24 10:30', 'consulta', 'Coração irregular e cansaço na natação', 146, 82, 118, 79.0, 'Homem de 72 anos com palpitações irregulares há 3 semanas, queda do rendimento na natação e discreta dispneia. ECG: fibrilação atrial com resposta ventricular média de 118 bpm. Ao exame: pulso irregular, RCR irregular em 2T, sem sopros, sem congestão. ECO: AE 48 mm, FEVE 56%, sem valvopatia significativa. TSH normal. Creatinina 1,1 (ClCr 64 mL/min). CHA2DS2-VASc 3 (idade 65 a 74 anos, HAS e DM). FA de início recente, provavelmente persistente.', 'Iniciar rivaroxabana 20 mg ao jantar e bisoprolol 5 mg pela manhã para controle da FC. Estratégia inicial de controle de frequência, com possibilidade de cardioversão depois de 3 semanas de anticoagulação. Retorno em 4 semanas.'),
  (642, 195, 4, '2023-03-07 10:40', 'retorno', 'Estou mais calmo, a natação voltou', 132, 78, 74, 78.4, 'Após 6 semanas de anticoagulação e bisoprolol, FC em repouso de 74 bpm e melhora dos sintomas, mantendo FA. Holter: FA permanente com FC média 78 bpm e máxima 112, sem pausas. Voltou à natação 3x por semana sem limitação. Quer evitar cardioversão por ter pouca sintomatologia com a FC controlada e por medo de procedimento. Sem sangramentos, hemoglobina 14,2. Estratégia de controle de frequência é adequada.', 'Adotar controle de frequência (alvo menor que 110 bpm em repouso). Manter rivaroxabana e bisoprolol. Hemograma e creatinina anuais. Orientado sobre sinais de sangramento e de AVC. Evitar AINE. Retorno em 6 meses.'),
  (643, 195, 4, '2024-03-19 15:00', 'teleconsulta', 'Teleconsulta de rotina, estou bem', 128, 76, 70, null, 'Teleconsulta. Aos 73 anos, mantém a natação e viagens, sem palpitações importantes, sem dispneia, sem tontura. PA e FC aferidas por aparelho domiciliar. Aderente à rivaroxabana, sem sangramentos, sem equimoses. Exames de dezembro: hemoglobina 14,0, creatinina 1,1 (ClCr 62), HbA1c 6,9%, LDL 66. Pergunta se pode passar para um anticoagulante com menos comprimidos: já toma um por dia.', 'Manter rivaroxabana 20 mg e bisoprolol 5 mg. Reavaliar função renal a cada 12 meses (ajuste de dose se ClCr abaixo de 50). Retorno presencial em 6 meses com ECG e ECO. Orientado a avisar sobre sangramentos, dor torácica ou déficits neurológicos.');
