insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (195, '2024-03-19', 'controlado', 'FA permanente com controle de frequência (FC média 78 bpm) e anticoagulação plena com rivaroxabana, sem sangramentos nem eventos embólicos. Mantém a natação e a vida ativa. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (196, 'Valdemar Alves Pereira Sobrinho', 'M', '1960-01-30', 'Bom Jesus da Lapa', 'BA', 'Pescador aposentado', 'Doença de Chagas desde 2005 (sorologia positiva). Aneurisma apical conhecido. Sem HAS prévia. Etilista social. Mora em área ribeirinha, casa de barro na infância. Esposa cuida dos remédios.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (644, 196, 4, '2021-03-16 08:40', 'consulta', 'Tive um desmaio e o coração batia muito rápido antes', 104, 64, 62, 66.0, 'Homem de 61 anos com Chagas crônica e um episódio de síncope há 2 semanas precedido de palpitações rápidas. Sem dor torácica. Ao exame: PA 104x64, FC 62, RCR 2T B3, estertores discretos nas bases, edema 1+/4+. ECG: bloqueio de ramo direito, BDAS e extrassístoles ventriculares frequentes. Holter: TV monomórfica sustentada de 17 batimentos a 190 bpm (duas vezes) e 6.400 ESV/24h. ECO: FEVE 31%, aneurisma apical de 3 cm sem trombo. TV sustentada com síncope e cardiopatia chagásica: alto risco de morte súbita.', 'Indicação de CDI em prevenção secundária. Iniciar amiodarona 200 mg/dia, carvedilol 3,125 mg 12/12h, enalapril 5 mg 12/12h e espironolactona 25 mg. Sem benznidazol (cardiopatia estabelecida). Aguardar implante do CDI. Orientado a não dirigir. Retorno em 4 semanas.'),
  (645, 196, 4, '2021-04-20 09:00', 'internacao', 'Implante do CDI', 110, 68, 60, 66.4, 'Implante de CDI bicameral por punção subclávia esquerda, sem intercorrências, limiares adequados, teste de desfibrilação com sucesso. Radiografia sem pneumotórax. Programadas zonas de detecção de TV (180 bpm) e FV (220 bpm) com terapia de ATP. Alta no dia seguinte, ferida sem hematoma. Paciente e esposa orientados sobre choques: ligar para o SAMU se mais de um choque seguido.', 'Manter amiodarona, carvedilol, enalapril e espironolactona. Revisão da ferida em 10 dias, checagem do CDI em 30 dias e a cada 6 meses. Não carregar peso com o braço esquerdo por 6 semanas. Cartão do CDI entregue.'),
  (646, 196, 11, '2022-05-10 09:30', 'retorno', 'Cansaço maior e dois choques no peito esse mês', 100, 62, 66, 64.0, 'Um ano após o implante, piora da dispneia (NYHA III), edema vespertino e dois choques apropriados do CDI neste mês para TV (episódio de TV rápida com choque efetivo). Interrogação: 14 episódios de TV tratados com ATP e 2 com choque em 6 meses. ECO: FEVE 24%, VE dilatado. NT-proBNP 6.100. Creatinina 1,4, potássio 5,0. Tireoide normal (TSH 3,1). Passou meses sem comprar espironolactona e furosemida.', 'Retomar espironolactona 25 mg e adicionar dapagliflozina 10 mg e furosemida 40 mg. Manter amiodarona, carvedilol e enalapril. Discutir ablação de TV por cateter e avaliação para transplante em centro de referência. Retorno em 4 semanas.'),
  (647, 196, 6, '2022-12-05 23:30', 'pronto_socorro', 'O aparelho deu vários choques seguidos', 78, 48, 148, 61.0, 'Trazido pelo SAMU após 6 choques do CDI em 2 horas (tempestade elétrica). À chegada: sudoreico, pálido, PA 78x48, FC 148 com TV monomórfica sustentada, estertores até ápices, extremidades frias. Cardioversão elétrica 150 J reverteu para ritmo sinusal transitório, com recorrência. Amiodarona venosa e lidocaína iniciadas, sedação e intubação orotraqueal por instabilidade e edema pulmonar. Lactato 5,6, creatinina 2,4, potássio 5,1. Encaminhado à UTI com choque cardiogênico e tempestade elétrica.', 'UTI. Amiodarona em infusão, lidocaína, sedação profunda e ventilação mecânica, dobutamina em baixa dose. Suspender carvedilol. Reprogramação do CDI. Avaliar ablação de TV de urgência e suporte circulatório mecânico. Conversa com a família sobre gravidade e limites terapêuticos.');
