insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (197, '2023-05-16', 'melhorou', 'Insuficiência mitral degenerativa grave por prolapso com ruptura de cordoalha tratada com plástica mitral (ressecção de P2 e anel). Sem IM residual, átrio e ventrículo com remodelamento reverso e classe funcional I. Segue em controle anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (198, 'Caio Henrique Rosário Matos', 'M', '2001-07-09', 'Jacobina', 'BA', 'Estudante universitário', 'Saudável. Jogador de futebol amador. Dois episódios de taquicardia súbita aos 17 e 19 anos, resolvidos em poucos minutos. Um primo morreu subitamente aos 25 anos durante uma partida, sem causa esclarecida. Não fuma, não usa drogas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (652, 198, 4, '2022-02-08 10:20', 'consulta', 'Coração dispara no futebol e meu primo morreu de morte súbita', 118, 70, 74, 72.0, 'Jovem de 20 anos com episódios de palpitações súbitas durante esforço, o último há 3 semanas com 15 minutos de duração, tontura e sem síncope. Histórico familiar de morte súbita (primo). Ao exame: coração normal, sem sopros. ECG de repouso: intervalo PR curto (100 ms), onda delta positiva em parede lateral e QRS alargado discretamente (115 ms): padrão de pré-excitação ventricular, compatível com via acessória lateral esquerda. ECO normal, FEVE 65%. Teste ergométrico: a pré-excitação persiste em esforço (via com período refratário curto), sem FA. Síndrome de Wolff-Parkinson-White com risco de FA pré-excitada.', 'Indicação de estudo eletrofisiológico e ablação da via acessória (sintomático, atleta, história familiar). Evitar competições até o procedimento. Não usar bloqueadores nodais (verapamil, digoxina). Orientado a procurar o PS se palpitações prolongadas. Agendar procedimento.'),
  (653, 198, 4, '2022-04-12 07:30', 'internacao', 'Ablação da via acessória', 120, 72, 70, 72.4, 'Estudo eletrofisiológico: via acessória lateral esquerda com condução anterógrada e retrógrada e período refratário anterógrado de 220 ms (alto risco). Induzida taquicardia ortodrômica a 192 bpm. Ablação por radiofrequência via transeptal com desaparecimento da onda delta em 3,4 segundos de aplicação. Ausência de condução na via acessória em teste com isoproterenol e adenosina. Sem complicações. Alta no mesmo dia, ECG sem pré-excitação, PR 148 ms.', 'Sem antiarrítmicos. Repouso relativo 3 dias, evitar chute forçado por 1 semana. Retorno com ECG em 30 dias e liberação gradual para o futebol. Esclarecido sobre taxa de sucesso (cerca de 95%) e chance baixa de recorrência.'),
  (654, 198, 4, '2022-07-19 10:00', 'retorno', 'Voltei a jogar sem crise', 116, 70, 62, 73.0, 'Três meses após a ablação, sem palpitações, voltou ao futebol aos domingos e à academia. ECG de repouso sem onda delta, PR 150 ms. Teste ergométrico novo, sem pré-excitação nem arritmias, capacidade de 14 METs. Holter 24h: ritmo sinusal sem arritmias. Preocupado com a história familiar, solicitado também rastreio com ECO e ECG dos pais, que foi normal. Alta tranquila.', 'Alta do seguimento arritmológico, sem medicamentos e sem restrição para esportes. Retornar se palpitações. Avaliação cardiológica de rotina a cada 2 anos. Orientado a relatar a história de morte súbita do primo em exames futuros.');
