insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (198, '2022-07-19', 'melhorou', 'Síndrome de Wolff-Parkinson-White com via acessória lateral esquerda de alto risco curada por ablação por radiofrequência. Sem recorrência de pré-excitação ou taquicardia, retorno ao futebol sem restrições e alta do seguimento arritmológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (199, 'Rita de Cássia Lopes Ventura', 'F', '1974-05-15', 'Ilhéus', 'BA', 'Vendedora em loja de calçados', 'Prolapso de valva mitral com insuficiência leve conhecido, sem seguimento. Extração dentária há 5 semanas sem profilaxia. Não fuma, hipertensa leve em uso de enalapril 10 mg/dia. Mãe diabética.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (655, 199, 1, '2022-09-20 11:00', 'consulta', 'Febre e suor de noite há quase 3 semanas, muito cansaço', 112, 58, 104, 56.0, 'Mulher de 48 anos com febre vespertina (38 a 39 graus), sudorese noturna, astenia e emagrecimento de 4 kg em 3 semanas. Extração dentária há 5 semanas. Ao exame: pálida, febril (38,4), taquicárdica, sopro holossistólico 3+/6+ mitral irradiado para axila, mais intenso que o prévio, e hemorragias em chama de vela subungueais, petéquias conjuntivais. Hemoglobina 9,8, VHS 92, PCR 118, leucócitos 13.400. Hemocultura colhida em 3 amostras. ETT: prolapso do folheto posterior com vegetação móvel de 12 mm e regurgitação importante. Suspeita de endocardite infecciosa (critérios de Duke maiores).', 'Internar de imediato. Iniciar antibiótico empírico após as hemoculturas: ceftriaxona 2 g/dia e gentamicina 3 mg/kg/dia. Solicitar ETE, TC de crânio e avaliação do cirurgião cardiovascular. Evitar anticoagulantes. Suspender enalapril (se hipotensão).'),
  (656, 199, 14, '2022-09-27 08:30', 'internacao', 'Dor de cabeça forte e fraqueza no braço direito', 142, 80, 96, 55.4, 'Dia 7 de internação. Hemoculturas positivas em 3/3 amostras para Streptococcus gallolyticus/viridans sensível a penicilina. ETE: vegetação de 14 mm com cordoalha rota e IM grave. Hoje, déficit motor súbito em membro superior direito (força grau 3), disartria leve e cefaleia. TC de crânio: infarto subagudo de território de ACM esquerda (embolia séptica), sem hemorragia. IC com congestão pulmonar e creatinina 1,3. Antibiótico ajustado para penicilina cristalina e ceftriaxona.', 'UTI. Penicilina cristalina 4 milhões UI 4/4h + gentamicina por 2 semanas. Furosemida EV. Angiotomografia cerebral para excluir aneurisma micótico. Discutido com a cirurgia: indicação de troca valvar mitral precoce pelo risco de novos êmbolos, IC e IM grave, aguardando 72 horas por causa do infarto cerebral e risco hemorrágico.'),
  (657, 199, 12, '2022-10-04 07:00', 'internacao', 'Cirurgia da válvula mitral', 118, 64, 88, 55.0, 'Troca valvar mitral por bioprótese (porcina 29 mm), com ressecção de vegetação e debridamento do folheto posterior, 7 dias após o infarto cerebral e com uma semana de antibiótico dirigido efetivo. CEC 118 minutos. Cultura da vegetação negativa. Pós-operatório com FA transitória revertida com amiodarona e sem sangramento intracraniano em TC de controle. Persistência de paresia braquial direita leve (grau 4) e afasia discreta. Extubada em 14h.', 'Completar 4 semanas de penicilina cristalina contadas a partir da cirurgia. Fisioterapia motora e fonoaudiologia. Anticoagulação não é necessária (bioprótese em ritmo sinusal): iniciar AAS 100 mg após 1 mês se estável. Reavaliação de dentes com odontologia. Profilaxia de endocardite a vida toda.'),
  (658, 199, 1, '2023-01-24 10:30', 'retorno', 'Ainda tenho fraqueza no braço direito', 124, 72, 72, 58.2, 'Quatro meses após a cirurgia, completou o antibiótico, sem febre, PCR 3. Bioprótese mitral normofuncionante ao ECO (gradiente médio 4 mmHg, sem regurgitação paravalvar), FEVE 56%. Sequelas neurológicas: paresia braquial direita grau 4 e dificuldade para encontrar palavras; não conseguiu voltar ao trabalho de vendedora e está afastada pelo INSS. Fisioterapia semanal e fonoterapia. Ritmo sinusal, usa AAS desde novembro. Muito abatida emocionalmente; arrependida de não ter feito profilaxia.', 'Manter AAS 100 mg e enalapril 10 mg. ECO semestral no primeiro ano. Profilaxia de endocardite antes de qualquer procedimento dentário (amoxicilina 2 g, 1 hora antes). Encaminhar à neurologia e psicologia. Reabilitação funcional em curso. Retorno em 6 meses.');
