insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (199, '2023-01-24', 'piorou', 'Endocardite infecciosa em valva mitral prolapsada por estreptococo, complicada por embolia séptica cerebral e IM grave, tratada com antibiótico e troca valvar por bioprótese. Infecção curada, mas com sequela neurológica (paresia braquial direita e afasia discreta) e afastamento do trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (200, 'Dorval Nunes Kerber', 'M', '1951-09-17', 'Pelotas', 'RS', 'Motorista de caminhão aposentado', 'Tabagista de 50 maços-ano (ainda fuma 15 cigarros por dia), HAS há 15 anos em uso de enalapril 20 mg/dia, DPOC leve. Irmão operado de aneurisma de aorta. Sem diabetes. Vida sedentária.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (659, 200, 2, '2023-02-21 10:00', 'consulta', 'Acharam um aneurisma no ultrassom da barriga', 156, 88, 78, 82.0, 'Homem de 71 anos, assintomático, com achado incidental de aneurisma de aorta abdominal no ultrassom pedido por dor lombar. Refere dor lombar mecânica, sem dor abdominal súbita, sem síncope. Ao exame: PA 156x88, massa pulsátil periumbilical expansiva palpável de cerca de 5 cm, sopro sistólico abdominal, pulsos femorais presentes e simétricos. Ultrassom: aneurisma infrarrenal de 5,3 cm, com trombo mural. Fatores de risco: sexo masculino, idade, tabagismo pesado, HAS e história familiar. Alto risco de ruptura (diâmetro maior que 5,5 cm ou crescimento rápido).', 'Solicitar angiotomografia de aorta e ilíacas para planejamento. Controle rigoroso da PA (alvo menor que 130/80) com associação de betabloqueador. Parar de fumar com apoio medicamentoso. Evitar esforços de carga. Orientado a procurar o PS imediatamente se dor abdominal ou lombar súbita e intensa. Avaliação do cirurgião vascular.'),
  (660, 200, 12, '2023-03-14 10:20', 'retorno', 'Avaliação com o cirurgião', 138, 80, 64, 81.5, 'Angiotomografia: aneurisma infrarrenal fusiforme de 5,6 cm (crescimento em 3 semanas), colo proximal de 22 mm de diâmetro e 28 mm de comprimento, angulação de 40 graus, artérias ilíacas comuns de 11 mm, boa anatomia para correção endovascular (EVAR). Sem sinais de ruptura iminente. Artérias renais e viscerais pérvias, sem aneurisma de ilíaca. Função renal normal. Espirometria com VEF1 de 68% (DPOC leve). Paciente com idade de 71 anos e risco cirúrgico moderado. Indicada correção eletiva.', 'Agendar reparo endovascular (EVAR) em 3 semanas. Manter estatina e betabloqueador. Hidratação antes do contraste. Nova orientação sobre cessação do tabaco antes da cirurgia. Se dor abdominal súbita, ir ao PS imediatamente.'),
  (661, 200, 12, '2023-04-04 06:30', 'internacao', 'Cirurgia do aneurisma', 134, 78, 62, 81.0, 'EVAR com endoprótese bifurcada via acessos femorais bilaterais sob anestesia peridural, sem intercorrências. Angiografia final sem endoleak. Tempo cirúrgico de 2h10, perda sanguínea mínima. Pós-operatório em UTI por 12 horas, sem alterações de ECG ou troponina. Pulsos distais presentes, creatinina 1,0. Deambulou no 1º dia e teve alta no 2º, sem febre e com feridas inguinais limpas.', 'AAS 100 mg e estatina. Angiotomografia ou Doppler em 30 dias para detectar endoleak, depois anual. Evitar esforço por 4 semanas. Reforçada abstinência do tabaco, que influencia o crescimento do saco aneurismático. Retorno em 30 dias.'),
  (662, 200, 2, '2024-04-09 10:10', 'retorno', 'Controle de um ano da cirurgia', 128, 76, 62, 83.4, 'Um ano após o EVAR, assintomático, parou de fumar há 8 meses com bupropiona e reposição de nicotina, mantendo abstinência. Angiotomografia de controle: endoprótese íntegra, sem endoleak, saco aneurismático reduzido de 5,6 para 4,7 cm. Pulsos distais presentes, sem claudicação. PA domiciliar média 124x74. LDL 62. Respiração melhorada após parar de fumar. Quer fazer caminhadas diárias.', 'Manter AAS, atorvastatina, metoprolol e enalapril. Angiotomografia ou Doppler anual. Rastreio de aneurisma de aorta torácica e de ilíacas. Orientação ao irmão e filhos homens para ultrassom de rastreio de aorta. Retorno em 6 meses.');
