insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (200, '2024-04-09', 'melhorou', 'Aneurisma de aorta abdominal de 5,6 cm corrigido eletivamente por EVAR antes de romper, sem endoleak e com regressão do saco aneurismático para 4,7 cm em um ano. Abstinente do tabaco, PA controlada, rastreio familiar orientado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (201, 'Josué Barbosa de Albuquerque', 'M', '1981-04-12', 'Caruaru', 'PE', 'Motorista de aplicativo', 'Sem diagnóstico prévio de HAS. Sobrepeso há anos, come na rua entre as corridas e dorme cerca de 5 horas por noite. Nega tabagismo, etilismo social nos fins de semana. Pai hipertenso, falecido de IAM aos 61 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (663, 201, 5, '2025-03-11 17:20', 'consulta', 'Aferi a pressão no posto e deu 15 por 9', 158, 98, 82, 96.4, 'Homem de 43 anos, motorista de aplicativo, procura a UBS após PA de 150x92 numa campanha na praça. Assintomático, refere cefaleia occipital ocasional ao fim do dia. Almoça marmita de lanchonete, refrigerante diário, sem atividade física. IMC 31,5. Ao exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, abdome globoso, sem edemas. PA em duas medidas sentado 158x98 e 156x96. HD: HAS estágio 1 a confirmar, obesidade grau I.', 'Solicitado MRPA por 7 dias, exames de rotina e ECG. Orientado MEV: reduzir sal e refrigerante, caminhar 30 minutos 5x/semana, tentar dormir 7 horas. Sem medicação por ora. Retorno com MRPA e exames em 6 semanas.'),
  (664, 201, 5, '2025-04-22 18:05', 'retorno', 'Trouxe o caderninho da pressão', 154, 96, 80, 95.8, 'Retorna com MRPA de 7 dias, 28 medidas, média 152x94 mmHg, nenhuma abaixo de 140x90. Conseguiu caminhar apenas duas vezes por semana por causa da jornada. Diz que reduziu o refrigerante pela metade. Sem cefaleia desde a última consulta. Exame inalterado, peso praticamente estável. Confirmada HAS estágio 1 com MEV insuficiente isolada; risco cardiovascular moderado pelo LDL e obesidade.', 'Iniciar losartana 50 mg uma vez ao dia, de manhã. Mantidas as MEV, meta de perda de 5 kg em 3 meses. Orientado sobre efeitos adversos e não suspender ao se sentir bem. Repetir creatinina e potássio em 4 semanas. Retorno em 60 dias.'),
  (665, 201, 5, '2025-09-16 17:45', 'retorno', 'Vim mostrar que a pressão normalizou', 126, 78, 72, 90.2, 'Em uso regular de losartana, sem tosse ou edema. Perdeu 5,6 kg desde o início, passou a levar marmita e faz caminhada no fim da tarde 4x por semana. MRPA recente com média 124x76. Creatinina e potássio sem alterações após o início da medicação. Pergunta se pode parar o remédio; explicado que a pressão está controlada justamente pelo tratamento e que a retirada, se houver, será gradual e supervisionada.', 'Manter losartana 50 mg/dia. Meta de PA < 130/80 atingida. Reforçado MEV e perda de mais 3 a 4 kg. Repetir perfil lipídico em 3 meses. Retorno semestral com MRPA.');
