insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (201, '2025-09-16', 'controlado', 'Hipertensão estágio 1 diagnosticada com MRPA, controlada com losartana 50 mg e mudança de estilo de vida. Perdeu 5,6 kg, PA domiciliar média 124x76 mmHg. Segue em acompanhamento semestral na UBS, orientado a não suspender a medicação por conta própria.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (202, 'Maria das Neves Pereira Bezerra', 'F', '1962-11-03', 'Campina Grande', 'PB', 'Agricultora aposentada', 'HAS há 15 anos e DM2 há 9 anos, em uso de losartana 50 mg 12/12h e metformina 850 mg 12/12h. Nunca fumou. Mãe diabética e hipertensa. Mora em sítio, cuida de pequena horta e de dois netos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (666, 202, 1, '2023-05-09 08:30', 'consulta', 'Médico do posto mandou procurar o coração por causa da proteína na urina', 152, 88, 78, 71.0, 'Paciente de 60 anos, HAS e DM2, encaminhada da UBS por albuminúria. Toma losartana e metformina, mas diz que esquece o comprimido da noite quando passa o dia na roça. Sem dispneia, sem edema, sem dor torácica. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, pulsos pediosos presentes, sem edemas. PA 152x88 mmHg. Exames trazidos mostram RAC 148 mg/g e HbA1c 8,1%. HD: HAS + DM2 com nefropatia incipiente, controle inadequado.', 'Trocar para losartana 100 mg em dose única matinal, facilitando a adesão. Associar anlodipino 5 mg. Iniciar dapagliflozina 10 mg pelo benefício renal e cardiovascular. Orientado hidratação. Repetir creatinina, potássio e RAC em 8 semanas. Contato com a UBS para ajuste do DM2.'),
  (667, 202, 1, '2023-08-22 09:10', 'retorno', 'Estou bem, só uma coceira nas partes íntimas', 134, 80, 74, 69.6, 'Retorna com melhora da adesão desde a dose única. Refere prurido genital leve há duas semanas, sem corrimento nem disúria; exame sem candidíase evidente. Orientada higiene e hidratação. Sem edema de tornozelo com anlodipino. PA 134x80. Exames: creatinina subiu discretamente (queda esperada da TFGe com iSGLT2), potássio normal, RAC caiu de 148 para 62 mg/g.', 'Manter esquema. Orientado higiene local, retorno antecipado se piora do prurido ou febre. Reavaliar HbA1c com a UBS. Aferir PA em casa 3x/semana. Retorno em 6 meses.'),
  (668, 202, 1, '2024-08-13 08:50', 'retorno', 'Vim ver os exames do ano', 128, 76, 70, 68.4, 'Paciente de 61 anos, sem queixas. Mantém horta e caminhada diária até a casa da filha. PA 128x76, MRPA domiciliar entre 120 e 132 por 78 a 82. Exame cardiovascular normal. HbA1c 7,0%, RAC 38 mg/g, TFGe estável em 58. Sem hipoglicemias, sem infecções urinárias. Refere que agora toma tudo pela manhã e não esquece mais, pegou o hábito de deixar a caixa ao lado da garrafa de café.', 'Manter losartana, anlodipino e dapagliflozina. Meta pressórica < 130/80 atingida. Repetir RAC, creatinina e potássio em 6 meses. Fundo de olho anual e cuidado com os pés. Retorno em 6 a 8 meses.');
