insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (203, '2024-07-23', 'controlado', 'Falsa hipertensão resistente por efeito do avental branco, descoberta na MAPA. Esquema reduzido de quatro para dois fármacos, com PA domiciliar média 126x77 mmHg e resolução da tontura e do edema. Recebeu alta para a UBS com MRPA semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (204, 'Wellington Fábio Gomes de Lira', 'M', '1974-02-28', 'Garanhuns', 'PE', 'Comerciante (loja de materiais de construção)', 'HAS diagnosticada aos 38 anos, mal controlada. Usa losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Refere câimbras frequentes. Não fuma, bebe cerveja aos sábados. Mãe hipertensa que teve AVC aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (672, 204, 1, '2023-09-18 14:20', 'consulta', 'Pressão não controla e tenho câimbra toda noite', 178, 108, 70, 88.0, 'Homem de 49 anos, HAS há 11 anos, hoje com 3 anti-hipertensivos em dose plena (um diurético) e PA 178x108. Adesão confere (compra a receita no mesmo balcão há anos). Cansaço, fraqueza em pernas e câimbras noturnas. Ao exame: sem sopros, sem sopro abdominal, pulsos simétricos, sem edemas. Potássio 3,1 mEq/L mesmo antes de repor. HD: HAS resistente com hipocalemia espontânea; investigar hiperaldosteronismo primário.', 'Solicitar aldosterona plasmática e atividade de renina (coleta matinal, suspender nada, repor potássio via oral antes). Pedir ECO e TC de abdome com cortes em adrenais. Prescrito cloreto de potássio. Retorno em 4 semanas. Orientado dieta com pouco sal.'),
  (673, 204, 9, '2023-10-30 08:40', 'retorno', 'Vim ver o exame dos hormônios', 172, 106, 68, 87.6, 'Atendido pela endocrinologia. Aldosterona 31 ng/dL com renina suprimida, relação aldosterona/renina 62 (positivo). Teste de sobrecarga salina com aldosterona mantida em 14 ng/dL, confirmando autonomia. TC de adrenais: nódulo hipodenso de 1,8 cm na adrenal esquerda, direita normal. Potássio 3,6 após reposição. Sem sintomas de hipercortisolismo, supressão com dexametasona 1 mg normal (cortisol 1,1 mcg/dL).', 'Diagnóstico de hiperaldosteronismo primário. Iniciar espironolactona 50 mg e suspender clortalidona e potássio. Programar cateterismo de veias adrenais para definir lateralização. Controle de potássio e creatinina em 10 dias. Explicada possibilidade de cura cirúrgica.'),
  (674, 204, 9, '2024-03-19 07:30', 'internacao', 'Internação para cirurgia da suprarrenal', 138, 84, 66, 86.2, 'Cateterismo de veias adrenais em janeiro com índice de lateralização 6,2 para a esquerda, sem supressão contralateral. Internado eletivamente para adrenalectomia laparoscópica esquerda, realizada hoje sem intercorrências. Potássio pré-operatório 4,3 sob espironolactona. PA 138x84 no pós-operatório imediato. Dieta liberada em 6 horas, deambulou no mesmo dia.', 'Suspender espironolactona. Monitorar potássio diariamente pelo risco de hipercalemia pós-operatória transitória. Manter anlodipino, suspender losartana temporariamente enquanto avalia PA. Alta em 48 horas, se estável. Retorno ambulatorial em 6 semanas.'),
  (675, 204, 9, '2024-06-10 09:00', 'retorno', 'Não tenho mais câimbra', 118, 74, 72, 85.0, 'Quase três meses de pós-operatório de adrenalectomia esquerda. Sem câimbras, energia melhor, voltou a trabalhar na loja integralmente. Anatomopatológico: adenoma cortical de 1,8 cm. Aldosterona 4 ng/dL com renina normalizada. Potássio 4,4 mEq/L sem suplementação. PA 118x74 com apenas anlodipino 5 mg, ele mesmo notou que "nunca mais passou de 130". Sem sinais de insuficiência adrenal.', 'Suspender anlodipino com monitorização da PA em casa. Manter dieta com pouco sal. Controle de potássio e creatinina em 3 meses. Alta da endocrinologia e retorno com cardiologia em 6 meses para seguimento de risco cardiovascular.');
