insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (205, '2023-06-13', 'melhorou', 'IAM sem supra com emergência hipertensiva tratado com angioplastia de DA e stent farmacológico. Parou de fumar, completou reabilitação, teste ergométrico sem isquemia, PA 126x78 e LDL 58 mg/dL. Mantém lesão residual em Cx assintomática em tratamento clínico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (206, 'Kenji Hideo Matsuda', 'M', '1977-05-30', 'Londrina', 'PR', 'Gerente de tecnologia da informação', 'Sem diagnóstico de HAS. Trabalha 10 a 12 horas por dia, sedentário, toma de 5 a 6 cafés por dia e consome muito sal em comida japonesa industrializada. Ex-fumante há 8 anos. Pai com AVC aos 63 anos.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (680, 206, 2, '2024-08-20 16:30', 'consulta', 'Check-up. Meu relógio mostra pressão alta em casa, mas no consultório é normal', 128, 80, 74, 88.0, 'Paciente de 47 anos, assintomático. Registros domiciliares com aparelho de braço validado mostram 146 a 154 por 90 a 96 nas últimas duas semanas, enquanto nas consultas de rotina dos últimos anos a PA sempre ficou entre 120 e 130. PA hoje 128x80 (média de três medidas). Ao exame: IMC 28,6, RCR 2T BNF, sem sopros, MV+ sem RA. Suspeita de hipertensão mascarada; estresse e carga de trabalho elevados.', 'Solicitar MAPA de 24 horas e ecocardiograma, além de RAC, creatinina e perfil lipídico. Orientado reduzir cafeína e sal, e iniciar atividade aeróbica. Retorno com os exames em 30 dias.'),
  (681, 206, 2, '2024-09-24 17:00', 'retorno', 'Trouxe a MAPA e o eco', 130, 82, 76, 88.4, 'MAPA 24h: média 24h 138x88, vigília 144x92, sono 122x76, descenso reduzido (pressão elevada na vigília com PA de consultório normal), confirmando hipertensão mascarada. ECO: espessura septal 12 mm, parede posterior 11 mm, massa indexada no limite superior, FEVE 64%, átrio esquerdo 38 mm. RAC 11 mg/g. LDL 128 mg/dL. Reforçada relação do estresse no trabalho com os picos pressóricos observados.', 'Iniciar telmisartana 40 mg pela manhã (dose única, adesão com rotina de trabalho). MEV: reduzir sal, café, exercícios 150 min/semana. Reavaliar com MRPA em 6 semanas por teleconsulta. Manter aferição domiciliar.'),
  (682, 206, 2, '2025-01-21 19:10', 'teleconsulta', 'Retorno por vídeo, pressão em casa', 124, 78, 70, 85.5, 'Teleconsulta. Em uso de telmisartana 40 mg sem efeitos colaterais. MRPA de 7 dias com média de 124x78 mmHg, sem valores acima de 138x86. Reduziu o café para duas xícaras por dia e voltou a correr duas vezes por semana, perdeu 2,5 kg. Dormindo melhor desde que passou a desligar o notebook às 21h. Informa sentir-se mais disposto no fim do dia.', 'Manter telmisartana 40 mg. Meta atingida (< 130/80). Repetir MAPA em 12 meses ou antes se mudança de rotina. Manter atividade física. Atenção para uso de AINEs, evitar. Retorno presencial em 6 meses.');
