insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (206, '2025-01-21', 'controlado', 'Hipertensão mascarada diagnosticada por MAPA, apesar de PA normal em consultório. Controlada com telmisartana 40 mg e redução de cafeína e sal, com MRPA média 124x78 mmHg. Segue em seguimento semestral com monitorização domiciliar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (207, 'Odete Maria Fernandes Rangel', 'F', '1951-01-17', 'Natal', 'RN', 'Professora aposentada', 'HAS há 25 anos e dislipidemia, em uso de anlodipino 5 mg e sinvastatina 20 mg. Nunca fumou. Vive com o marido, caminha pouco por causa de dor no joelho. Irmão com revascularização do miocárdio aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (683, 207, 1, '2021-03-16 10:20', 'consulta', 'Aperto no peito quando subo a rampa da igreja', 144, 82, 68, 72.0, 'Paciente de 70 anos com HAS e dislipidemia refere há 3 meses dor retroesternal em aperto aos médios esforços, irradiada para mandíbula, com alívio em 3 a 5 minutos ao repouso, CCS II. Sem dor em repouso, sem síncope. Ao exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, pulsos presentes. ECG em repouso normal. Teste ergométrico: infradesnível de ST de 2 mm em V5-V6 aos 6 METs, com dor típica. HD: DAC estável com isquemia significativa.', 'Iniciar AAS 100 mg, trocar sinvastatina por atorvastatina 40 mg, metoprolol succinato 50 mg e dinitrato de isossorbida SL se dor. Agendado cateterismo eletivo. Orientada a procurar o PS se dor em repouso ou > 20 minutos.'),
  (684, 207, 10, '2021-04-08 07:30', 'internacao', 'Cateterismo e angioplastia eletivos', 136, 80, 60, 71.6, 'Internada para cateterismo eletivo, assintomática no pré. CATE por acesso radial: lesão de 80% em DA proximal, lesão de 40% em CD, CX sem lesões, FEVE 62%. Realizada ATC com implante de stent farmacológico 3,5 x 18 mm em DA proximal, sem complicações. Mantida estável, alta no dia seguinte, com dupla antiagregação.', 'AAS e clopidogrel 75 mg por 6 meses (síndrome estável). Atorvastatina 40 mg, metoprolol. Orientada repouso relativo por 5 dias e retomada gradual de atividades. Retorno em 30 dias com ECG.'),
  (685, 207, 1, '2021-05-20 10:00', 'retorno', 'Sem dor no peito, mas com hematomas nas pernas', 130, 76, 58, 71.2, 'Retorno 6 semanas após ATC de DA. Sem angina, subiu a rampa da igreja sem sintomas. Refere pequenos hematomas em antebraços e pernas, sem sangramento digestivo; fezes de cor normal. Sítio de punção radial sem alterações. FC 58 com betabloqueador, sem tontura. Exame cardiovascular normal. Hemoglobina 12,8 g/dL, estável. Explicado que os hematomas decorrem da dupla antiagregação.', 'Manter AAS e clopidogrel até completar 6 meses. Associar omeprazol 20 mg para gastroproteção. Iniciar caminhada supervisionada 3x/semana, reabilitação cardíaca. Retorno em 6 meses.'),
  (686, 207, 1, '2022-05-17 09:30', 'retorno', 'Venho para a revisão do ano', 128, 74, 62, 70.4, 'Um ano após ATC. Assintomática, caminha 30 minutos quase todos os dias com a vizinha. Clopidogrel suspenso em outubro conforme programado, mantém AAS. Sem dor torácica, dispneia ou palpitações. PA 128x74. LDL 62 mg/dL com atorvastatina 40 mg. Sem queixas de mialgia. Exame físico sem alterações. Ainda com dor no joelho, o que limita corridas mais longas, sem relação com o coração.', 'Manter AAS 100 mg, atorvastatina 40 mg, metoprolol e anlodipino. Se LDL permanecer acima de 55 mg/dL, considerar ezetimiba na próxima. Retorno anual com exames, e antes se dor torácica.');
