insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (207, '2022-05-17', 'estavel', 'Angina estável tratada com angioplastia e stent farmacológico em DA proximal. Há um ano sem angina, com PA 128x74 e LDL 62 mg/dL, em AAS, estatina, betabloqueador e anlodipino. Segue em acompanhamento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (208, 'Salim Khalil Haddad', 'M', '1955-03-08', 'Recife', 'PE', 'Comerciante', 'IAM prévio em 2017 com angioplastia de DA e ICFEr isquêmica com FEVE 28%. HAS e DM2. Ex-tabagista pesado. Em uso de carvedilol 6,25 mg 12/12h, enalapril 10 mg 12/12h, furosemida 40 mg e AAS. Mora com a esposa, adora comida típica e reclama da restrição de sal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (687, 208, 11, '2023-01-16 08:40', 'consulta', 'Falta de ar para tomar banho', 108, 70, 84, 84.6, 'Pcte de 67 anos com ICFEr isquêmica (FEVE 28%) em CF III NYHA, dispneia aos mínimos esforços, ortopneia com 2 travesseiros e edema de MMII 1+/4+. Sem angina. Usa carvedilol 6,25 mg, enalapril 10 mg, furosemida e AAS; nunca recebeu espironolactona nem iSGLT2. Ao exame: PA 108x70, FC 84, turgência jugular a 45 graus, B3, estertores em bases, hepatomegalia leve. NT-proBNP 3.240 pg/mL. Creatinina 1,2 e potássio 4,5.', 'Suspender enalapril e, após 36 horas, iniciar sacubitril/valsartana 24/26 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol 6,25 mg, furosemida 40 mg. Peso diário, restrição de sódio. Creatinina e potássio em 7 dias. Retorno em 3 semanas.'),
  (688, 208, 11, '2023-02-27 09:00', 'retorno', 'Melhorei do cansaço, mas fico tonto às vezes', 102, 64, 72, 80.8, 'Perdeu 3,8 kg de peso e a dispneia melhorou: já toma banho sem parar, caminha dois quarteirões. Tontura leve ao levantar, sem síncope. PA 102x64, FC 72. Sem edema, sem jugulares ingurgitadas. Sem tosse, nem angioedema. Creatinina 1,3, potássio 4,9. Esposa informa que ele voltou a comer a feijoada do fim de semana, mas dentro do possível.', 'Reduzir furosemida para 20 mg. Manter sacubitril/valsartana 24/26, espironolactona 25, dapagliflozina e carvedilol, sem titulação por ora pela PA baixa. Reforçada dieta com sal controlado e pesagem diária. Potássio e creatinina em 4 semanas. Retorno em 8 semanas.'),
  (689, 208, 6, '2024-04-09 22:50', 'pronto_socorro', 'Falta de ar de repente, não consigo deitar', 168, 100, 108, 85.5, 'Pcte com ICFEr, chega ao PS com dispneia intensa há 4h, após comer em festa de família (kibe, charutos, salgados) e esquecer furosemida por 3 dias. Taquipneico, SpO2 88% em ar ambiente, sudoreico, PA 168x100, FC 108. Estertores até ápices, B3, edema 2+/4+. Rx de tórax com congestão e derrame bilateral. NT-proBNP 8.900. HD: EAP por descompensação de ICFEr, sem IAM (troponina normal).', 'O2 suplementar com VNI, furosemida 80 mg EV, nitroglicerina EV enquanto PA elevada. Repor medicações habituais. Observação com monitorização. Reavaliar diurese e balanço em 6 horas. Encaminhar para internação se não houver melhora.'),
  (690, 208, 11, '2024-05-14 09:20', 'retorno', 'Vim depois do hospital, me sinto fraco', 110, 70, 76, 80.2, 'Retorno 5 semanas após EAP. Hospitalizado 3 dias, ficou compensado com furosemida e dieta. Hoje sem ortopneia, dispneia aos médios esforços (CF II-III). PA 110x70, FC 76, peso seco 80,2 kg. ECO atual: FEVE 25%, VE muito dilatado, IM moderada a importante. Discussão em equipe sobre CDI primário: já em tratamento otimizado há mais de 3 meses com FEVE < 35% e expectativa de vida > 1 ano.', 'Manter os quatro pilares nas doses toleradas. Aumentar carvedilol para 12,5 mg 12/12h. Encaminhado à arritmologia para avaliação de CDI e ressincronização. Orientado e explicado com a esposa o que fazer em caso de piora. Retorno em 30 dias.');
