insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (208, '2025-11-20', 'piorou', 'ICFEr isquêmica com piora progressiva: após edema agudo de pulmão em abril de 2024, FEVE caiu para 25% com insuficiência mitral relevante. Em novembro de 2025 foi internado novamente por descompensação, classe NYHA III e em avaliação para CDI e terapias avançadas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (209, 'Ivanilde Souza Cordeiro', 'F', '1946-06-21', 'Uberaba', 'MG', 'Do lar', 'HAS há 30 anos, em uso de enalapril 10 mg 12/12h e hidroclorotiazida 25 mg. Sem diabetes. Nunca fumou. Mora com a filha, aposentada com um salário mínimo. Mãe faleceu de AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (691, 209, 4, '2022-04-05 14:00', 'consulta', 'Coração disparando e muito cansaço há uma semana', 138, 84, 118, 64.2, 'Paciente de 75 anos, HAS, com palpitações irregulares e cansaço há 7 dias. Sem síncope, sem dor torácica, sem déficit neurológico. Ao exame: ritmo irregular, FC 118, sem sopros, MV+ sem RA, sem edema. ECG: fibrilação atrial de resposta ventricular elevada. ECO: AE 46 mm, FEVE 60%, sem valvopatia significativa. TSH normal. CHA2DS2-VASc 4 (idade >= 75, sexo feminino, HAS). HAS-BLED 1. ClCr estimada 52 mL/min.', 'FA persistente com indicação de anticoagulação plena: iniciar rivaroxabana 20 mg ao jantar. Controle de frequência com metoprolol succinato 50 mg. Manter enalapril e suspender hidroclorotiazida pela fraqueza. Orientada sinais de sangramento. Retorno em 30 dias.'),
  (692, 209, 4, '2022-05-17 15:10', 'retorno', 'Melhorou muito, não sinto mais o coração correr', 128, 76, 76, 63.8, 'Retorna sem palpitações, FC 76 em FA, controle de frequência adequado. Cansaço resolveu. Toma o rivaroxabana no jantar, sem sangramentos. A filha comenta que o custo é pesado, cerca de um quinto do benefício da mãe, mas por ora consegue comprar. PA 128x76. Exame sem alterações.', 'Manter rivaroxabana 20 mg, metoprolol e enalapril. Solicitado Holter de 24h para avaliar controle de frequência. Conversei com a família sobre opções de acesso (farmácia popular, UBS). Retorno em 4 meses; avisar se faltar dinheiro, para ajustarmos.'),
  (693, 209, 4, '2023-03-14 14:30', 'retorno', 'Estou há uns meses sem tomar o remédio do sangue, ficou caro', 154, 92, 92, 62.0, 'Primeiro retorno em 10 meses. Parou a rivaroxabana há cerca de 3 meses por custo, após a farmácia deixar de ter o preço promocional; também tomava o metoprolol de forma irregular. Refere cansaço leve e palpitações ocasionais. Sem sinais de AVC ou AIT. PA 154x92, FC 92 em FA. Explicado o risco de AVC cardioembólico (CHA2DS2-VASc 4, ~4,8%/ano). Filha entende o risco, mas diz que "não tem como pagar sempre".', 'Reintroduzir anticoagulação em esquema acessível: varfarina 5 mg com INR no posto de saúde, meta 2,0 a 3,0, após orientação alimentar. Retomar metoprolol. Agendada orientação com enfermagem para anticoagulação e INR em 1 semana. Retorno em 30 dias.');
