insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (209, '2023-10-05', 'abandonou', 'Fibrilação atrial com alto risco embólico que interrompeu a rivaroxabana por custo. Foi orientada a trocar por varfarina com INR na UBS, mas não retornou aos agendamentos nem fez os controles. Contato telefônico com a filha em outubro: sem anticoagulante regular, perdeu seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (210, 'Edvaldo Pinheiro Amaral', 'M', '1960-10-14', 'Montes Claros', 'MG', 'Lavrador aposentado', 'Doença de Chagas crônica diagnosticada há 12 anos (sorologia positiva), morou em casa de pau a pique na infância. Cardiopatia chagásica com bloqueio de ramo direito e BDAS. Usa enalapril 10 mg 12/12h. Etilista moderado. Dois irmãos faleceram subitamente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (694, 210, 11, '2022-06-07 09:30', 'consulta', 'Cansaço para trabalhar na roça e batedeira no peito', 118, 74, 66, 69.5, 'Pcte de 61 anos, Chagas crônico, refere dispneia aos médios esforços e palpitações esporádicas. Sem síncope. Ao exame: BEG, RCR irregular por extrassístoles, B3 discreto, MV+ sem RA, sem edema. ECG: BRD + BDAS, extrassístoles ventriculares frequentes. Holter: 8.400 EV/24h e 3 episódios de TVNS. ECO: FEVE 38%, aneurisma apical de VE. Sem trombo identificado. CF II. Sem indicação de tratamento etiológico por cardiopatia estabelecida.', 'Iniciar carvedilol 3,125 mg 12/12h, titular a cada 2 semanas; manter enalapril 10 mg 12/12h; espironolactona 25 mg. Furosemida 20 mg se edema. Amiodarona adiada para avaliação da arritmologia. Orientado limitar álcool. Encaminhar ao Dr. Fernando (arritmologia).'),
  (695, 210, 4, '2023-02-14 10:00', 'retorno', 'Desmaiei na semana passada no curral', 104, 66, 58, 68.0, 'Retorna após síncope súbita durante esforço, sem prodromos, com recuperação rápida. Em uso de carvedilol 6,25 mg 12/12h, enalapril e espironolactona. Holter repetido: TV sustentada de 14 segundos, FC 190, assintomática, e 11 episódios de TVNS. FEVE 35% ao ECO. K 4,4. Síncope em Chagas com TV sustentada documentada: alto risco de morte súbita. Discutido caso com a equipe.', 'Indicação de CDI para prevenção secundária. Iniciar amiodarona 200 mg/dia para suprimir arritmia na espera do implante. Orientado a não dirigir nem trabalhar em altura. Programado implante de CDI. Pedidos TSH e função hepática pela amiodarona.'),
  (696, 210, 4, '2023-09-05 07:40', 'internacao', 'Internação eletiva para colocar o desfibrilador', 110, 68, 54, 68.2, 'Internado eletivamente. Assintomático desde a última consulta, sem novas síncopes. Realizado implante de CDI bicameral por via subclávia esquerda sem intercorrências, testes de limiar e detecção adequados, programação de zonas de TV (> 170 bpm) e FV. Radiografia pós-procedimento sem pneumotórax. Alta em 24 horas com cuidados da ferida.', 'Orientações de carteira do dispositivo, cuidados com o membro, evitar esforço com o braço por 4 semanas, avisar choques. Manter amiodarona, carvedilol, enalapril, espironolactona. Revisão do dispositivo em 30 dias e a cada 6 meses.'),
  (697, 210, 6, '2024-11-19 03:20', 'pronto_socorro', 'Levou três choques do aparelho e está muito cansado', 92, 58, 122, 71.4, 'Trazido pela esposa após 3 choques do CDI em 1 hora, madrugada. Dispneia, edema de MMII 3+/4+ há 10 dias, ganho de peso de 3 kg, parou furosemida por falta na UBS. PA 92x58, FC 122 irregular, SpO2 91%. Ao exame: estase jugular, B3, estertores até terço médio, ascite leve. Interrogação do CDI: TV sustentada tratada com choques, episódio de TV incessante. K 3,6. IC descompensada com TV recorrente.', 'Internar. Reposição de potássio e magnésio, amiodarona EV, furosemida EV, suspender enalapril pela hipotensão. Avaliar necessidade de dobutamina e transferência para UTI. Interrogação do CDI e ajuste de zonas. Rever aderência e acesso a medicações com assistente social.');
