insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (210, '2025-03-02', 'obito', 'Cardiopatia chagásica avançada com CDI e IC refratária. Teve alta após a internação por TV incessante e descompensação, mas manteve piora progressiva. Faleceu em casa em 02/03/2025, por insuficiência cardíaca refratária, segundo a família; sem novos choques relatados.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (211, 'Severino Ramos da Silva Filho', 'M', '1944-12-03', 'João Pessoa', 'PB', 'Aposentado (ex-funcionário da Companhia de Águas)', 'HAS há 35 anos, hiperplasia prostática benigna. Em uso de anlodipino 10 mg, losartana 100 mg, clortalidona 25 mg e doxazosina 4 mg à noite (prescrita pelo urologista). Dois episódios de queda no último ano. Viúvo, mora com a filha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (698, 211, 3, '2025-02-18 09:10', 'consulta', 'Caí no banheiro de noite, fico tonto quando levanto', 164, 84, 66, 61.0, 'Idoso de 80 anos, trazido pela filha após queda ao levantar para urinar de madrugada, sem trauma grave, com equimose no quadril. Refere tontura e escurecimento visual ao ficar de pé. Ao exame: PA deitado 168x88, em pé 1 min 128x68 e 3 min 118x62 com FC 68 sem aumento compensatório; hipotensão ortostática. Sódio 130 mEq/L, creatinina 1,2. Quatro anti-hipertensivos, incluindo alfabloqueador à noite e diurético, em paciente frágil.', 'Suspender doxazosina e clortalidona. Reduzir anlodipino para 5 mg, manter losartana 100 mg. Orientado levantar-se devagar, sentar antes de ficar de pé, ingerir líquidos e usar luz de vigília. Repetir sódio em 15 dias. Avisar o urologista. Retorno em 6 semanas.'),
  (699, 211, 3, '2025-04-08 09:40', 'retorno', 'Não caí mais, mas a pressão no posto deu 14 por 8', 146, 82, 68, 62.2, 'Sem novas quedas nem tontura desde o ajuste. Anda com bengala e a filha instalou barras no banheiro. PA sentado 146x82 e em pé 138x78 após 3 minutos, ortostase resolvida. Sódio 137. Ganhou 1,2 kg e voltou a comer melhor. Em casa, medidas matinais entre 138 e 150. Para idoso frágil com antecedente de queda, aceita-se meta menos rígida, individualizada.', 'Manter losartana 100 mg e anlodipino 5 mg, sem aumentar doses. Meta de PA sentado < 140-150 com PA em pé sem queda. Continuar orientações de prevenção de quedas. Fisioterapia para equilíbrio. Retorno em 6 meses, antes se tontura.'),
  (700, 211, 3, '2025-10-14 10:00', 'retorno', 'Estou andando melhor com a fisioterapia', 138, 76, 64, 63.0, 'Seis meses sem quedas. Concluiu o ciclo de fisioterapia, caminha até a padaria da esquina sem bengala. PA sentado 138x76 e em pé 134x72, sem queda ortostática. Nega tontura, nega edema, nicturia 2x. Creatinina 1,2 e potássio 4,5. Pede para tirar mais um comprimido, mas explicado que os dois atuais são o mínimo para manter a pressão sem risco cardiovascular.', 'Manter losartana 100 mg e anlodipino 5 mg. Reforçar hidratação e atividade física. Reavaliar função renal em 6 meses. Retorno em 6 meses; medir PA em pé se tontura.');
