insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (211, '2025-10-14', 'melhorou', 'Idoso frágil com quedas por hipotensão ortostática secundária a polifarmácia anti-hipertensiva. Após suspender doxazosina e clortalidona e reduzir o anlodipino, ficou sem quedas e sem queda de PA em pé, com PA sentado 138x76, e segue com meta individualizada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (212, 'Cleide Aparecida Nakamura Prado', 'F', '1977-09-01', 'São José do Rio Preto', 'SP', 'Vendedora de loja', 'Sem diagnóstico prévio de HAS, não passava em consulta há 6 anos. Nega comorbidades. Pais hipertensos. Não fuma, não bebe. Ganhou peso após a menopausa precoce. Trabalha em pé, 8 horas por dia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (701, 212, 2, '2025-02-04 11:00', 'consulta', 'Dor de cabeça forte que não passa, pressão 17 por 10', 172, 106, 82, 78.5, 'Paciente de 47 anos com cefaleia frontal há 2 semanas e valores de PA domiciliar entre 165 e 178 por 100 a 106, medidos pela vizinha. Sem déficit, sem dor torácica, sem dispneia. Ao exame: RCR 2T BNF, sem sopros, sem sopro abdominal, pulsos simétricos, FO sem alterações. PA 172x106 e 174x108. HD: HAS estágio 2 recente, sem sinais de lesão aguda de órgão-alvo. Exames de rotina normais, RAC 14 mg/g.', 'Iniciar associação em comprimido único de telmisartana 80 mg + anlodipino 5 mg, uma vez ao dia, para facilitar a adesão. Dieta com menos sal, perda de peso. Solicitado ECO, MRPA em 2 semanas. Retorno em 6 semanas ou antes se cefaleia intensa.'),
  (702, 212, 2, '2025-03-18 11:20', 'retorno', 'A dor de cabeça acabou, mas inchou o tornozelo', 148, 92, 78, 77.8, 'Cefaleia resolvida após 1 semana de tratamento. Adesão referida em 100%, toma com o café da manhã. MRPA com média 146x90. Queixa-se de edema maleolar leve ao fim do dia (1+/4+), sem dispneia. ECO: HVE discreta (septo 12 mm), FEVE 66%. PA ainda acima da meta, mas cai a cada semana. Desconforto com o edema; explicado que é efeito dose-dependente do anlodipino.', 'Trocar para telmisartana 80 mg + anlodipino 5 mg + adicionar clortalidona 12,5 mg, em vez de elevar anlodipino pelo edema. Elevação das pernas, meias elásticas de média compressão. Controle de potássio e creatinina em 4 semanas. Retorno em 8 semanas.'),
  (703, 212, 2, '2025-06-10 10:40', 'retorno', 'Vim ver se posso diminuir o remédio', 124, 76, 74, 75.2, 'Sem cefaleia, edema de tornozelo praticamente resolvido com as meias. PA hoje 124x76; MRPA com média 122x74. Perdeu 3,3 kg desde o início, começou caminhada de 30 minutos, 4x/semana. Potássio 4,0, sódio 139, creatinina 0,8. Sem câimbras, sem queixas urinárias. Pergunta se pode reduzir, mas explicado que o controle depende dos 3 fármacos e que a retirada de algum será avaliada depois de 6 meses de PA estável.', 'Manter esquema. Meta < 130/80 atingida. Reforço de MEV e perda de mais 3 kg. Exames de sangue e eletrólitos em 6 meses. Retorno em 6 meses; reavaliar redução se PA < 120/75 em MRPA.');
