insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (212, '2025-06-10', 'controlado', 'Hipertensão estágio 2 de diagnóstico recente, controlada com associação de telmisartana/anlodipino em comprimido único e clortalidona. PA domiciliar média 122x74, perda de 3,3 kg e resolução da cefaleia e do edema. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (213, 'Genivaldo Pessoa de Sousa', 'M', '1967-05-24', 'Cajazeiras', 'PB', 'Motorista de ônibus intermunicipal', 'HAS há 14 anos, obesidade e ronco intenso. Usa losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Etilista social, não fuma. Pai e dois irmãos hipertensos. Dorme mal, cochila no volante nos intervalos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (704, 213, 2, '2023-06-13 14:00', 'consulta', 'Estou com três remédios e a pressão não desce', 176, 104, 76, 112.0, 'Paciente de 56 anos com HAS resistente suspeita. Traz as caixas com adesão verificada por contagem de comprimidos. MRPA de 7 dias com média 168x100, afastando avental branco. Ronco alto relatado pela esposa, pausas respiratórias e sonolência diurna (Epworth 14). IMC 36. Sem AINEs. Aldosterona/renina normal. Creatinina 1,1, K 4,2. Polissonografia prévia com IAH 38 eventos/hora. HD: HAS resistente verdadeira, SAOS grave.', 'Adicionar espironolactona 25 mg ao esquema triplo. Encaminhar para CPAP. Orientado dieta hipossódica e perda de peso. Monitorar potássio e creatinina em 1 semana e em 4 semanas. Motorista: avisar sobre risco de sonolência ao volante. Retorno em 6 semanas.'),
  (705, 213, 2, '2023-08-01 14:30', 'retorno', 'Meu peito está dolorido e inchado', 138, 86, 72, 109.8, 'PA caiu de 176x104 para 138x86 após espironolactona, mas desenvolveu ginecomastia dolorosa bilateral há 3 semanas. Potássio 4,9, creatinina 1,3 (de 1,1), aceitável. Já iniciou CPAP há 10 dias, ainda se adaptando. Sonolência já menor. Preocupado com a aparência do peito, quer largar o remédio. Explicado que a ginecomastia é efeito do bloqueio androgênico da espironolactona.', 'Trocar espironolactona por eplerenona 50 mg/dia. Manter demais anti-hipertensivos. Potássio e creatinina em 2 semanas. CPAP todas as noites, mínimo de 4 horas. Retorno em 6 semanas.'),
  (706, 213, 2, '2024-02-20 15:10', 'retorno', 'Estou dormindo bem e emagreci', 126, 78, 68, 104.0, 'Usa o CPAP em média 5,5 horas por noite, ronco sumiu e a sonolência melhorou (Epworth 6). Perdeu 8 kg desde o início, trocou a marmita da estrada por salada e frango. Ginecomastia regrediu bastante após a troca. PA 126x78 e MRPA média 124x76. Potássio 4,6 e creatinina 1,2. Sem hipercalemia. Satisfeito, quer saber se um dia poderá reduzir remédios com a perda de peso.', 'Manter os 4 fármacos por ora, pois o controle ainda é recente. Se mantiver peso e CPAP por 6 meses, tentar retirada do diurético. Meta de mais 6 kg. Retorno em 4 meses com exames.');
