insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (213, '2024-02-20', 'controlado', 'Hipertensão resistente verdadeira associada a apneia grave do sono, controlada com quatro fármacos (incluindo eplerenona após ginecomastia com espironolactona), CPAP e perda de 8 kg. PA domiciliar média 124x76 mmHg, potássio normal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (214, 'Rosimere Alcântara Lopes', 'F', '1962-08-15', 'Natal', 'RN', 'Cozinheira aposentada', 'DM2 há 18 anos em uso de insulina NPH, HAS há 20 anos. Doença renal crônica diabética conhecida, creatinina em torno de 1,8. Usa losartana 100 mg e anlodipino 10 mg. Nunca fumou. Mãe falecida em hemodiálise.', 'Alergia a sulfa (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (707, 214, 8, '2022-10-04 08:20', 'consulta', 'Pés inchados e pressão muito alta', 178, 104, 78, 74.0, 'Paciente de 60 anos com DM2 e DRC com piora recente: creatinina 2,1 mg/dL, TFGe 25 (estágio G4), RAC 1.240 mg/g. Edema de MMII 2+/4+, dispneia leve, ganho de 3 kg em 1 mês. Doppler de artérias renais sem estenose, rins com ecotextura aumentada e tamanho reduzido (9,4 cm). Hipertensão secundária à doença renal, com componente de sobrecarga volêmica. Potássio 5,3.', 'Furosemida 40 mg 12/12h. Manter anlodipino 10 mg e reduzir losartana para 50 mg diários pelo potássio. Adicionar carvedilol 12,5 mg 12/12h. Dieta com restrição de sódio e potássio. Controle em 2 semanas. Encaminhamento para educação em doença renal e esclarecimentos sobre terapia renal substitutiva.'),
  (708, 214, 8, '2023-01-17 08:40', 'retorno', 'Estou me sentindo cansada e enjoada', 142, 84, 72, 70.6, 'Edema reduziu com furosemida, peso caiu 3,4 kg. Queixa-se de cansaço, hiporexia e náuseas matinais. PA 142x84. Creatinina 2,4 (TFGe 22), potássio 5,0, bicarbonato 19, hemoglobina 10,2 g/dL, PTH 188. Sem dispneia nem dor torácica. Diurese preservada. Entende a evolução e pergunta com ansiedade sobre diálise. Explicado que ainda não há indicação, mas que o preparo deve começar.', 'Iniciar bicarbonato de sódio 1 g 12/12h, carbonato de cálcio com as refeições e investigar anemia com ferro e ferritina. Manter anti-hipertensivos. Peso diário. Retorno em 3 meses. Avaliação cirúrgica para fístula arteriovenosa se TFGe < 20.'),
  (709, 214, 8, '2023-11-07 09:00', 'retorno', 'Estou com coceira, sem apetite e inchada de novo', 156, 90, 80, 75.3, 'Progressão da DRC. Creatinina 3,1 (TFGe 16), potássio 5,4, ureia 148, bicarbonato 17. Prurido, anorexia e edema 2+/4+ com ganho de 4,7 kg. PA 156x90 com hipervolemia. Diurese ainda 800 mL/dia. Hemoglobina 9,1. Pouca adesão à dieta pelas festas de fim de ano da igreja. FAV braquiocefálica esquerda confeccionada em setembro, em maturação.', 'Aumentar furosemida para 80 mg 12/12h. Suspender losartana por K 5,4 e TFGe. Associar hidralazina 50 mg 8/8h. Iniciar eritropoetina e ferro EV conforme protocolo. Retorno em 6 semanas e preparo para diálise se TFGe < 10.'),
  (710, 214, 8, '2024-04-23 08:30', 'retorno', 'Vim ver quando começo a diálise', 150, 88, 84, 72.4, 'Quadro urêmico: náuseas, vômitos, soluços e dispneia aos esforços. Creatinina 5,6, ureia 210, potássio 5,8, TFGe 8. Diurese de 400 mL/dia. FAV com frêmito bom, mas ainda sem condição de punção. PA 150x88. Estertores finos em bases, edema 2+/4+. Indicada diálise: iniciará hemodiálise por cateter de duplo lúmen provisório e programará a fístula.', 'Hemodiálise 3x/semana por cateter, iniciando esta semana. Dieta com restrição de potássio, fósforo e líquidos. Ajuste de anti-hipertensivos pelo peso seco. Acompanhamento no serviço de nefrologia da diálise.');
