insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (214, '2024-04-23', 'piorou', 'Hipertensão secundária à doença renal crônica diabética, com progressão de G4 para G5 em 18 meses apesar de tratamento. Indicada hemodiálise em abril de 2024, com início por cateter e fístula em maturação. PA ainda de difícil controle pela sobrecarga volêmica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (215, 'Cícero Romão Batista Neto', 'M', '1975-03-30', 'Juazeiro do Norte', 'CE', 'Pedreiro', 'HAS diagnosticada há 6 anos, tratada de forma irregular. Sem DM ou DLP conhecidas. Etilista, consome aguardente nos fins de semana. Tabagismo de 10 maços-ano. Vive com a esposa e três filhos, renda instável.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (711, 215, 6, '2024-01-20 23:30', 'pronto_socorro', 'Dor de cabeça forte e pressão muito alta', 214, 126, 88, 86.0, 'Pcte de 48 anos, HAS, sem medicação há 2 meses ("achei que a pressão tinha normalizado e parei"). Cefaleia occipital há 2 dias, sem alteração visual, sem vômitos, sem dor torácica, sem dispneia, sem déficit focal. PA 214x126 em duas medidas, simétrica. Ao exame: BEG, lúcido, pupilas normais, FO sem papiledema nem hemorragias, RCR 2T B4+, MV+ sem RA. ECG com HVE. Troponina negativa, creatinina 1,0, EAS sem hematúria. HD: urgência hipertensiva, sem lesão aguda de órgão-alvo.', 'Captopril 25 mg VO, repouso e reavaliação em 1 hora, sem redução abrupta da PA. Após resposta (PA 178x104), alta com losartana 50 mg 12/12h e anlodipino 5 mg. Orientado a não interromper por conta própria. Retorno em 72 horas na UBS.'),
  (712, 215, 5, '2024-01-23 10:00', 'retorno', 'Voltei como mandaram, a cabeça está melhor', 160, 98, 80, 85.6, 'Cefaleia resolvida, está tomando losartana e anlodipino conforme receita. Sem edema, sem tosse, sem sintomas neurológicos. PA 160x98, em queda gradual. Perguntei por que parou o remédio antes: faltou dinheiro após um acidente de trabalho do cunhado e depois "achei que não precisava". Orienta-se a retirar os remédios na farmácia da UBS. Sem sinais de dano agudo em órgãos-alvo.', 'Manter losartana e anlodipino. Cadastrar na UBS para recebimento gratuito dos medicamentos. Reduzir sal e álcool. Exames de rotina e ECO. Retorno em 30 dias com MRPA.'),
  (713, 215, 5, '2024-03-05 09:30', 'retorno', 'Vim buscar o resultado do coração', 132, 82, 74, 84.0, 'PA de 132x82, MRPA média 130x80. Adesão regular, retirou os medicamentos na UBS. ECO: HVE concêntrica leve (septo 13 mm), FEVE 62%. Colesterol total 218, LDL 138. Glicemia 96. Refere que reduziu a bebida durante a semana, mas continua com a cachaça no fim de semana. Sem queixas.', 'Manter losartana e anlodipino. Iniciar atorvastatina 20 mg. Orientado a reduzir o álcool e cessar do tabagismo. Retorno em 3 meses com creatinina e potássio. Reforçar que o tratamento é contínuo.');
