insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (215, '2024-09-10', 'abandonou', 'Urgência hipertensiva por abandono de tratamento, com boa resposta ao reinício. Voltou a ter PA controlada em março de 2024, mas não compareceu aos retornos seguintes. Em contato telefônico em setembro, informou que parou de tomar os remédios porque "estava bem" e que trabalhava fora da cidade.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (216, 'Thaynara Vitória Lima de Oliveira', 'F', '2000-02-12', 'Olinda', 'PE', 'Operadora de caixa de supermercado', 'Primeira gestação, 34 semanas e 1 dia por DUM. Pré-natal com 6 consultas, PA anterior até 120x76. Obesidade (IMC pré-gestacional 32). Sem HAS prévia. Mãe com pré-eclâmpsia na gestação da paciente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (714, 216, 7, '2026-03-10 09:30', 'consulta', 'Dor de cabeça e as mãos e o rosto muito inchados', 172, 112, 92, 88.4, 'Gestante de 26 anos, G1P0, 34 semanas, em consulta de pré-natal com cefaleia frontal há 3 dias, edema de face e mãos, epigastralgia leve e escotomas cintilantes ontem. PA 172x112 e 168x110 em repouso. Reflexos aumentados, sem clônus. BCF 142 bpm, altura uterina 33 cm. Fita urinária 3+ de proteína. Ganho de 6 kg em 3 semanas. HD: pré-eclâmpsia grave com sinais de HELLP incipiente.', 'Encaminhada imediatamente à maternidade de referência para internação, sulfato de magnésio, anti-hipertensivo e avaliação para resolução da gestação. Realizado transporte com acompanhante. Exames laboratoriais completos e cardiotocografia no hospital.'),
  (715, 216, 7, '2026-03-10 14:20', 'internacao', 'Internação obstétrica por pré-eclâmpsia grave', 176, 114, 96, 88.4, 'Admitida com PA 176x114. Plaquetas 98.000, TGO 112, TGP 98, LDH 640, ácido úrico 7,8, creatinina 0,9, proteinúria 24h 3,2 g. Cardiotocografia com variabilidade preservada. USG: feto 2.050 g, líquido normal, Doppler de artéria umbilical com resistência aumentada. Quadro compatível com pré-eclâmpsia grave e HELLP parcial. Iniciado sulfato de magnésio (4 g EV de ataque e 1 g/h de manutenção) e betametasona 12 mg IM, 2 doses em 24h.', 'Controle de PA com nifedipino 10 mg VO a cada 30 minutos até PA < 160x110 e metildopa 500 mg de 8/8h. Monitorização materno-fetal contínua, balanço hídrico, diurese horária e gluconato de cálcio à beira do leito. Programar cesariana após conclusão do esquema de corticoide em 24h, ou antes se piora.'),
  (716, 216, 7, '2026-03-11 15:00', 'internacao', 'Cesariana por piora laboratorial', 158, 102, 88, 86.2, 'Após 24h de magnésio e corticoide, plaquetas caíram para 71.000 e TGO subiu para 168, sem eclâmpsia. Diurese 40 mL/h. Mantidos reflexos presentes e frequência respiratória normal. Indicada resolução: cesariana sob raquianestesia (plaquetas > 70.000), sem intercorrências. Recém-nascido do sexo feminino, 2.080 g, Apgar 8 e 9, encaminhado à UTI neonatal para observação. Útero contraído, sangramento normal.', 'Manter sulfato de magnésio por 24h no pós-operatório. Metildopa e nifedipino mantidos até PA estável. Controle de plaquetas e transaminases a cada 12h. Aleitamento materno estimulado. Reavaliação diária da PA. Alta prevista em 4 a 5 dias.'),
  (717, 216, 7, '2026-04-14 10:30', 'retorno', 'Revisão do pós-parto, estou amamentando', 134, 84, 76, 78.0, 'Puerpério de 34 dias de cesariana. Alta hospitalar no 5º dia com PA ainda 150x96, em uso de nifedipino. Passou a 134x84 após troca para enalapril, que é compatível com a amamentação. Bebê saiu da UTI neonatal com 12 dias e está em aleitamento. Cicatriz íntegra, loquiação ausente. Plaquetas 214.000, TGO 28, TGP 24, proteinúria de 24h 0,2 g. Sem cefaleia.', 'Manter enalapril 10 mg 12/12h, suspender nifedipino e metildopa. Reavaliar em 6 semanas para tentar retirada. Orientada que pré-eclâmpsia aumenta o risco cardiovascular futuro: controle anual de PA, glicemia e lipídios. Contracepção sem estrogênio. Aconselhamento para próxima gestação com AAS 100 mg a partir de 12 semanas.');
