insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (216, '2026-04-14', 'melhorou', 'Pré-eclâmpsia grave com HELLP parcial a 34 semanas, resolvida com sulfato de magnésio e cesariana. Recém-nascido de 2.080 g evoluiu bem. No puerpério, PA 134x84 com enalapril, plaquetas e transaminases normalizadas, orientada sobre risco cardiovascular futuro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (217, 'Wilson Kazuo Tanaka', 'M', '1972-11-09', 'Manaus', 'AM', 'Taxista', 'Tabagismo de 30 maços-ano (ainda fuma). Dislipidemia sem tratamento, sobrepeso. Sem HAS ou DM diagnosticados. Pai com IAM aos 58 anos. Sedentário, passa 10 horas por dia dirigindo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (718, 217, 6, '2023-08-05 05:10', 'pronto_socorro', 'Dor forte no peito há uma hora e meia', 148, 92, 98, 91.0, 'Pcte de 50 anos, taxista, dor precordial em aperto intensa há 90 minutos, com irradiação para mandíbula e sudorese fria. PA 148x92, FC 98. ECG: supradesnível de ST de 4 mm de V1 a V4 com espelhamento em parede inferior. Ao exame: REG, pálido, sudoreico, RCR 2T BNF, MV+ sem RA (Killip I). Troponina inicial 0,6 ng/mL. HD: IAMCSST de parede anterior.', 'AAS 300 mg, ticagrelor 180 mg, heparina não fracionada 70 UI/kg. Acionada hemodinâmica para ATC primária, tempo porta-balão alvo < 90 min. Morfina em baixa dose, O2 se SpO2 < 90%. Sem betabloqueador IV pela FC elevada. Transferência para hemodinâmica imediata.'),
  (719, 217, 10, '2023-08-06 09:00', 'internacao', 'Pós-ATC primária, sem dor', 124, 78, 74, 91.0, 'CATE na madrugada: oclusão trombótica de DA proximal (TIMI 0), CD e CX sem lesões significativas. Realizada ATC primária com stent farmacológico 3,5 x 28 mm em DA, com fluxo TIMI 3 final e porta-balão de 62 minutos. Pico de troponina 98 ng/mL. ECO: FEVE 42%, hipocinesia anterior e apical, sem trombo. Evoluiu estável em unidade coronariana, sem arritmias.', 'Dupla antiagregação por 12 meses. Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h e atorvastatina 80 mg. Cessação do tabagismo com reposição de nicotina. Reabilitação cardiovascular. Alta em 4 dias. Retorno em 30 dias.'),
  (720, 217, 1, '2023-09-12 10:00', 'retorno', 'Voltei para revisar depois do infarto', 118, 72, 64, 89.4, 'Retorno de 5 semanas após IAMCSST anterior com ATC primária. Sem angina, dispneia de grandes esforços. Tabagismo: parou no dia do infarto, mantém adesivo de nicotina. Tosse seca leve que atribui ao enalapril, intermitente. PA 118x72, FC 64. Exame cardiovascular sem alterações. ECO de controle: FEVE 46%. Iniciou reabilitação cardiovascular, 12 sessões feitas, bom desempenho.', 'Manter AAS, ticagrelor, atorvastatina e carvedilol, aumentar carvedilol para 6,25 mg 12/12h. Enalapril para 10 mg 12/12h; se tosse piorar, trocar por losartana. Retorno em 3 meses com lipidograma e ECO.'),
  (721, 217, 1, '2024-03-19 09:30', 'retorno', 'Voltei a dirigir, estou bem', 122, 74, 62, 86.0, 'Sete meses de IAM. Sem angina, completou reabilitação, caminha 40 minutos 5x/semana e voltou à praça de táxi. Sem cigarro desde o evento. A tosse com enalapril persistiu e foi trocado para losartana 50 mg 12/12h pela UBS há 2 meses, com resolução. LDL 48 mg/dL, glicemia 98, creatinina 1,0. ECO: FEVE 52%. PA 122x74. Menos pesado, perdeu 5 kg. Ainda preocupado com o custo do ticagrelor.', 'Manter AAS, ticagrelor até completar 12 meses (agosto), atorvastatina 80 mg, carvedilol 6,25 mg e losartana. Suspender ticagrelor em agosto. Retorno em 6 meses com exames. Orientado vacinação para influenza e pneumo.');
