insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (217, '2024-03-19', 'melhorou', 'IAMCSST anterior tratado com ATC primária e stent farmacológico em DA em 62 minutos. FEVE recuperou de 42% para 52%. Parou de fumar, voltou ao trabalho, LDL 48 mg/dL. Tosse com enalapril resolvida após troca por losartana. Segue em tratamento clínico otimizado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (218, 'Eunice Gouveia Maciel', 'F', '1959-10-21', 'Campina Grande', 'PB', 'Costureira', 'DM2 há 14 anos em uso de metformina 850 mg 12/12h e gliclazida. HAS há 20 anos, dislipidemia. Ex-tabagista (parou há 10 anos). Mãe falecida de IAM aos 62 anos. Cuida de uma neta pequena.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (722, 218, 1, '2025-01-14 10:30', 'consulta', 'Aperto no peito quando ando rápido, cada vez mais frequente', 146, 86, 70, 78.0, 'Paciente de 65 anos, DM2 e HAS, com dor torácica em aperto aos pequenos esforços há 2 meses, CCS III, aliviada com repouso. Sem dor em repouso. Ao exame: PA 146x86, RCR 2T BNF, sem sopros, sem edema. Cintilografia miocárdica com isquemia extensa nas paredes anterior e inferior. CATE: lesão de 90% em DA proximal, 80% em CX e oclusão crônica de CD, FEVE 55%. SYNTAX 34. Diabetes + multiarterial: favorece RM.', 'Indicada revascularização do miocárdio cirúrgica. Iniciar AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg e dinitrato de isossorbida SL se dor. Encaminhada ao cirurgião cardiovascular. Programar cirurgia eletiva com exames pré-operatórios.'),
  (723, 218, 12, '2025-02-24 07:30', 'internacao', 'Cirurgia de ponte de safena', 138, 82, 64, 77.0, 'Internada para RM eletiva. Cirurgia com circulação extracorpórea: ponte de artéria mamária esquerda para DA, safena para ramo marginal de CX e safena para CD, três pontes. Tempo de CEC 78 minutos, pinçamento 52 minutos, sem intercorrências. Extubada em 6 horas, sem sangramento exacerbado, dreno de mediastino com débito de 220 mL nas primeiras 12h.', 'Encaminhada à UTI cardiológica. Manter AAS, estatina e betabloqueador, insulinoterapia em protocolo de controle glicêmico. Fisioterapia respiratória precoce. Retirada de drenos em 48h. Cuidados com a ferida do esterno e do membro inferior.'),
  (724, 218, 14, '2025-02-27 20:15', 'internacao', 'Palpitações no 3º dia pós-operatório', 112, 68, 136, 78.5, 'UTI. No 3º PO, apresentou palpitações e episódio de FA de alta resposta (136 bpm), PA 112x68, sem dor torácica nem sinais de baixo débito. Eletrólitos: K 3,7, Mg 1,6. Ferida esternal limpa. Mantida SpO2 96% em ar ambiente. Sem sinais de IAM perioperatório (troponina em queda). CHA2DS2-VASc 4 (sexo, idade 65-74, DM, HAS).', 'Reposição de K e Mg. Amiodarona EV 150 mg em 10 minutos e manutenção. Rever betabloqueador. Reverteu para ritmo sinusal em 4 horas. Iniciar anticoagulação se FA recorrente > 48h. Monitorização contínua por mais 48 horas.'),
  (725, 218, 12, '2025-04-08 09:00', 'retorno', 'Revisão da cirurgia, a ferida está boa', 126, 76, 68, 75.4, '6 semanas de pós-operatório de RM. Ferida esternal bem cicatrizada, esterno estável à tosse, ferida da safena sem sinais de infecção. Sem angina, sem dispneia, sem recorrência de FA. Dor torácica leve na incisão apenas ao espirrar. Dirigindo a bicicleta ergométrica em casa. PA 126x76, FC 68. ECG em ritmo sinusal, sem alteração do QT sob amiodarona.', 'Suspender amiodarona. Manter AAS, atorvastatina e metoprolol. Liberada para reabilitação cardiovascular. Evitar esforço com os braços por mais 4 semanas. Retorno com cardiologia clínica em 2 meses.'),
  (726, 218, 1, '2025-10-21 10:00', 'retorno', 'Estou bem, queria ver o resultado do teste', 124, 72, 66, 72.8, '8 meses após RM. Sem angina e sem dispneia, voltou a costurar e cuida da neta. Concluiu reabilitação cardiovascular. Teste ergométrico: 8 METs, sem isquemia, sem arritmias. LDL 52, HbA1c 6,9%, creatinina 0,9. PA 124x72. Perdeu mais 2,6 kg. Reclama apenas de formigamento leve na perna da safena. Segue com adesão boa e sem sangramentos.', 'Manter AAS, atorvastatina 80 mg, metoprolol e metformina. Considerar iSGLT2 (empagliflozina 10 mg) pelo benefício cardiovascular no DM2: iniciada. Retorno anual com exames e antes se sintomas.');
