insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (218, '2025-10-21', 'melhorou', 'Doença coronariana triarterial com diabetes tratada com revascularização cirúrgica (mamária-DA e duas safenas). FA transitória no pós-operatório revertida com amiodarona. Assintomática, teste ergométrico sem isquemia, LDL 52 e HbA1c 6,9%, em prevenção secundária otimizada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (219, 'Ivonete Cavalcante de França', 'F', '1946-12-05', 'Santa Rita', 'PB', 'Aposentada (ex-lavadeira)', 'HAS há 30 anos, DM2 há 12 anos e obesidade. Usa losartana 50 mg 12/12h, anlodipino 5 mg e metformina 850 mg 12/12h. Nunca fumou. Duas filhas cuidam dela, uma delas é técnica de enfermagem.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (727, 219, 11, '2024-05-07 08:50', 'consulta', 'Falta de ar e pernas muito inchadas', 148, 84, 78, 92.0, 'Paciente de 77 anos, HAS, DM2 e obesidade (IMC 38), com dispneia aos pequenos esforços e edema de MMII 3+/4+ há 2 meses, ortopneia de 2 travesseiros. Sem dor torácica. Ao exame: PA 148x84, estase jugular a 45 graus, estertores nas bases, hepatomegalia leve, edema até joelhos. NT-proBNP 1.480 pg/mL. ECO: FEVE 58%, E/e'' 17, átrio esquerdo com volume indexado de 48 mL/m², HVE. HD: ICFEp (IC com FE preservada), descompensada.', 'Furosemida 40 mg 12/12h por 2 semanas, depois ajustar. Iniciar empagliflozina 10 mg/dia. Espironolactona 25 mg com controle de K e creatinina em 7 dias. Manter losartana 50 mg 12/12h, suspender anlodipino pelo edema. Peso diário, restrição de sal, atividade física leve.'),
  (728, 219, 11, '2024-06-18 09:10', 'retorno', 'Respiro melhor, mas me sinto fraca', 130, 76, 72, 84.6, 'Perdeu 7,4 kg de líquido, sem ortopneia, edema residual 1+/4+. Dispneia aos médios esforços. Fraqueza, tontura leve. Exames: potássio 5,3 e creatinina 1,4 (TFGe 38), elevações esperadas, mas limítrofes. Na ingestão, refere que usou sal de cozinha e bacalhau no fim de semana e pelo que a filha anota, faltaram duas doses de furosemida. PA 130x76.', 'Reduzir espironolactona para 12,5 mg/dia (meio comprimido) pelo potássio. Furosemida 40 mg pela manhã. Reforçar baixa ingestão de potássio e sódio, evitar substitutos do sal (cloreto de potássio). Repetir exames em 10 dias. Retorno em 2 meses.'),
  (729, 219, 11, '2025-01-14 08:40', 'retorno', 'Vim fazer o controle, estou me cuidando', 128, 74, 70, 82.0, 'Retorno de 7 meses. CF II, sem internações, caminha 20 minutos na rua de casa com a filha. Peso seco estável em 82 kg (perdeu 10 kg desde o início). Sem edema, sem ortopneia. Potássio 4,8 e creatinina 1,2 (TFGe 45) estáveis. NT-proBNP 690 pg/mL. PA 128x74. Diz que "agora conhece o corpo" e pesa-se toda manhã, anotando em um caderno.', 'Manter furosemida 40 mg, empagliflozina 10 mg, espironolactona 12,5 mg e losartana. Evitar anti-inflamatórios. Vacina anti-influenza e pneumocócica. Exames de potássio e creatinina a cada 4 meses. Retorno em 4 meses.');
