insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (219, '2025-01-14', 'estavel', 'ICFEp em idosa hipertensa e obesa, descompensada na primeira consulta e estabilizada com furosemida, empagliflozina e espironolactona em dose reduzida por hipercalemia. Perdeu 10 kg, NT-proBNP caiu para 690, em CF II e sem internações no período.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (220, 'Jaime Wanderley Lins', 'M', '1944-06-02', 'Petrolina', 'PE', 'Fruticultor aposentado', 'HAS há 25 anos, dislipidemia. Usa losartana 50 mg 12/12h e sinvastatina 20 mg. Nega DM e tabagismo. Pai falecido de morte súbita. Ainda cuida de um pequeno sítio de uva e manga, relatou ficar "sem fôlego" nos últimos meses.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (730, 220, 2, '2025-02-11 09:00', 'consulta', 'Quase desmaiei na roça e canso para tudo', 134, 70, 72, 74.0, 'Homem de 80 anos com dispneia progressiva, angina leve aos esforços e episódio pré-sincopal na colheita há 3 semanas. Ao exame: pulso parvus et tardus, sopro sistólico ejetivo 4+/6+ em foco aórtico irradiado para carótidas, B2 hipofonética, MV+ sem RA, sem edema. ECO: valva aórtica calcificada, área valvar 0,7 cm², gradiente médio 52 mmHg, Vmax 4,6 m/s, FEVE 55%. HD: estenose aórtica grave sintomática.', 'Indicada intervenção valvar. Suspender esforços físicos intensos. Solicitar angiotomografia de coronárias e de aorta/ilíacas, cálculo de risco STS e discussão em Heart Team. Manter losartana. Evitar vasodilatadores potentes. Retorno com resultados em 4 semanas.'),
  (731, 220, 10, '2025-03-20 10:30', 'retorno', 'Vim saber o que vão fazer com o meu coração', 138, 68, 70, 73.4, 'Discussão do Heart Team. Angiotomografia de coronárias: sem lesões obstrutivas significativas (escore de cálcio 1.340), acessos femoral e ilíacos adequados, anel aórtico 26 mm. STS 6,8% e fragilidade moderada. Vive com a esposa e quer continuar trabalhando um pouco. Sem síncope desde a primeira consulta, mas com piora da dispneia (CF III).', 'Indicação de TAVI transfemoral em vez de cirurgia convencional pela idade e fragilidade. Explicados riscos e benefícios, consentimento obtido. Suspender losartana na manhã do procedimento. Agendada internação para fim de abril. Exames pré: urina, hemograma, coagulação.'),
  (732, 220, 10, '2025-04-29 07:00', 'internacao', 'Internação para implante de válvula aórtica', 140, 72, 68, 73.0, 'Realizada TAVI transfemoral direita sob sedação, com prótese autoexpansível 29 mm, sem pré-dilatação e sem complicações vasculares. Gradiente médio pós-implante 8 mmHg, regurgitação paraprotética mínima. Bloqueio de ramo esquerdo novo, sem BAV. Marca-passo temporário retirado após 24 horas. Alta no 3º dia, deambulando e sem dispneia ao repouso.', 'AAS 100 mg indefinidamente. Atorvastatina 40 mg. Monitorização do ECG no ambulatório pelo BRE novo. Profilaxia de endocardite antes de procedimentos dentários. Retorno em 30 dias com ECO.'),
  (733, 220, 1, '2025-06-03 10:00', 'retorno', 'Estou bem, voltei a andar no sítio', 138, 72, 66, 74.6, 'Cinco semanas após TAVI. Sem dispneia aos esforços habituais, sem angina, sem síncope. Voltou a andar no sítio e a cuidar da mangueira. Sem sangramentos. ECG com BRE estável, PR 192 ms, sem BAV. ECO de controle: gradiente médio 9 mmHg, regurgitação paraprotética mínima, FEVE 58%. PA 138x72. Pede para voltar à rotina completa, sem restrições.', 'Manter AAS, atorvastatina e losartana. Liberado para atividades habituais, evitar cargas pesadas por mais 4 semanas. Holter em 3 meses pelo BRE novo. Retorno em 3 meses, depois semestral com ECO anual.');
