insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (221, '2025-02-18', 'abandonou', 'Hipertensa que teve tosse por enalapril, resolvida com losartana, mas que abandonou o tratamento por duas vezes por acreditar que estava curada. Não compareceu ao retorno de 30 dias nem aos contatos da UBS; em fevereiro de 2025 seguia sem tratamento regular e sem retorno ao serviço.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (222, 'Hélio Augusto Wanderley Sá', 'M', '1959-07-07', 'Sousa', 'PB', 'Pecuarista', 'HAS há 22 anos, obesidade e esteatose hepática. Usa losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Evita sal, mas gosta de carne de sol e queijo coalho. Não fuma. Pai faleceu de AVC aos 67 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (737, 222, 2, '2023-04-18 08:30', 'consulta', 'Tomo tudo direitinho e a pressão não abaixa', 182, 104, 74, 98.0, 'Paciente de 63 anos com HAS que não controla com 3 fármacos em dose plena, um deles diurético. Adesão verificada com a esposa e pelas retiradas na farmácia. MAPA 24h: média 176x98, vigília 180x100, sono 168x92, sem avental branco. Sem AINEs, sem álcool, sem descongestionantes. Aldosterona/renina normal, creatinina 1,2, potássio 4,3. Doppler de artérias renais sem estenose. IMC 33. HD: HAS resistente verdadeira.', 'Adicionar espironolactona 25 mg/dia. Controle de potássio e creatinina em 10 dias e em 4 semanas. Reduzir queijo e carne de sol, perda de peso gradual. Polissonografia solicitada para descartar apneia. Retorno em 6 semanas.'),
  (738, 222, 2, '2023-06-06 08:50', 'retorno', 'Melhorou, mas ainda tem dia que passa de 150', 148, 88, 70, 96.5, 'Melhora com espironolactona: PA média domiciliar caiu de 170 para 148 por 86. Potássio 4,8, creatinina 1,3. Sem ginecomastia, sem hipercalemia. Polissonografia mostrou IAH 12 (apneia leve), sem indicação de CPAP no momento. Perdeu 1,5 kg. Reclama de nicturia, relacionada ao diurético, e de não sentir diferença; explicado que PA alta silenciosa também é a que dá AVC.', 'Aumentar espironolactona para 50 mg/dia. Repetir potássio e creatinina em 2 semanas. Manter o resto. Reforçar redução do sal e caminhada. Retorno em 8 semanas com MRPA.'),
  (739, 222, 2, '2023-09-19 09:10', 'retorno', 'Estou me sentindo melhor, a pressão baixou', 128, 78, 68, 93.0, 'MRPA de 7 dias com média 126x77. Perdeu 5 kg, deixou o queijo coalho para o domingo. Potássio 5,0 e creatinina 1,3 estáveis em dois controles. Sem câimbras, sem ginecomastia, nicturia aceitável. Descenso noturno restabelecido em MAPA de controle (média 24h 124x74). Orgulhoso porque o filho notou a diferença e quer manter o esquema.', 'Manter os 4 fármacos. Evitar suplementos e substitutos de sal com potássio. Controle de K e creatinina a cada 3 meses. Retorno em 4 meses, antes se vômitos ou diarreia (suspender espironolactona).');
