insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (222, '2023-09-19', 'controlado', 'Hipertensão resistente verdadeira (MAPA sem avental branco, adesão confirmada), controlada com a adição de espironolactona até 50 mg. PA média na MAPA de 124x74, potássio 5,0 estável, perda de 5 kg. Segue em controle trimestral de eletrólitos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (223, 'Sandra Mara Ferreira Galvão', 'F', '1980-03-18', 'Natal', 'RN', 'Técnica de enfermagem', '"Hipertensão difícil" desde os 40 anos, tratada com losartana 50 mg 12/12h, sem controle. Episódios de dor de cabeça, suor e coração disparado há 2 anos. Não fuma, não usa drogas. Sem história familiar de tumores endócrinos. Trabalha em plantão noturno.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (740, 223, 2, '2023-10-16 10:00', 'consulta', 'Crises de dor de cabeça com suor frio e coração disparado', 168, 102, 96, 58.0, 'Paciente de 43 anos com HAS de difícil controle e crises paroxísticas há 2 anos, 2 a 3 por semana, de cefaleia pulsátil, sudorese profusa, palpitações e palidez, durando 15 a 30 min. Última com PA aferida em 196x112 pela colega. Perda de 4 kg em 6 meses. Ao exame: ansiosa, pálida, sudorese de mãos, FC 96, sem sopros. Metanefrinas urinárias de 24h: metanefrina 1.850 µg (ref. < 350) e normetanefrina 920 µg. TC: massa adrenal direita de 4,2 cm, heterogênea, 38 UH. HD: feocromocitoma.', 'Internação para preparo pré-operatório com bloqueio alfa antes de qualquer betabloqueador. Iniciar doxazosina 2 mg à noite, titular. Orientada dieta livre em sal, hidratação, evitar betabloqueador isolado, metoclopramida e opioides. Encaminhada à endocrinologia e cirurgia.'),
  (741, 223, 9, '2023-11-06 08:00', 'internacao', 'Internação para preparo da cirurgia da suprarrenal', 144, 88, 88, 58.4, 'Internada para preparo pré-operatório. Doxazosina titulada até 8 mg/dia nos últimos 14 dias, com queda de crises para 1 por semana, hipotensão postural leve e congestão nasal. PA 144x88 sentada e 128x78 em pé. Cintilografia com MIBG com captação na massa adrenal direita, sem focos extra-adrenais. Hematócrito 44%. Iniciado propranolol 40 mg de 8/8h somente após bloqueio alfa adequado, com FC alvo de 70 a 80 bpm. Hidratação oral e dieta rica em sal.', 'Manter doxazosina 8 mg e propranolol 40 mg de 8/8h. Soro isotônico 1 a 2 L na véspera da cirurgia. Suspender losartana. Cirurgia laparoscópica agendada para dezembro. Dosagem de cálcio e PTH para descartar NEM; pedido de aconselhamento genético.'),
  (742, 223, 12, '2023-12-05 07:30', 'internacao', 'Cirurgia de retirada do tumor da suprarrenal', 118, 70, 68, 58.2, 'Adrenalectomia direita laparoscópica realizada com monitorização invasiva de PA. Picos hipertensivos durante manipulação do tumor, até 240x130, tratados com nitroprussiato e esmolol; após ligadura da veia adrenal, hipotensão tratada com volume e noradrenalina por 3 horas. Extubada na sala. Pós-operatório em UTI, glicemia 64 mg/dL às 6h tratada com glicose. PA 118x70 sem aminas ao fim do dia.', 'Suspender doxazosina e propranolol. Controle de glicemia por 24h, atenção para hipotensão e hipoglicemia de rebote. Dieta liberada em 6 horas. Alta em 3 dias. Retorno com dosagem de metanefrinas em 6 semanas.'),
  (743, 223, 9, '2024-02-12 09:00', 'retorno', 'Não tive mais nenhuma crise', 116, 72, 70, 60.4, '10 semanas pós-adrenalectomia. Sem crises de cefaleia, suor ou palpitações. Voltou ao plantão noturno. Ganhou 2,2 kg, apetite recuperado. PA 116x72 sem nenhuma medicação, MRPA média 114x70. Metanefrinas urinárias normalizadas (metanefrina 120 µg/24h, normetanefrina 280 µg/24h). Teste genético para variantes de SDHx/RET/VHL negativo. Alegre, comenta que "nem sabia que dava para viver sem essa dor de cabeça".', 'Sem medicação. Seguimento anual com metanefrinas e PA por pelo menos 10 anos pelo risco de recorrência. Alta da endocrinologia com retorno em 12 meses. Orientada procurar o serviço se novas crises.');
