insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (223, '2024-02-12', 'melhorou', 'Feocromocitoma de adrenal direita com hipertensão paroxística, tratado com preparo alfa e beta-bloqueador e adrenalectomia laparoscópica. Metanefrinas normalizadas, sem crises e normotensa sem nenhum medicamento. Seguimento anual por 10 anos pelo risco de recorrência.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (224, 'Osvaldo Tenório Barros Filho', 'M', '1953-02-03', 'Caruaru', 'PE', 'Feirante aposentado', 'HAS há 25 anos, com adesão irregular. Usava captopril 25 mg 8/8h e hidroclorotiazida. Ex-etilista, tabagismo de 30 maços-ano, parou há 6 anos. Dislipidemia sem tratamento. Irmão com AVC aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (744, 224, 6, '2022-09-10 06:40', 'pronto_socorro', 'Acordou sem mexer o lado direito e sem conseguir falar', 218, 118, 88, 84.0, 'Pcte de 69 anos, HAS. Última vez visto bem às 04h30 pelo filho; às 06h10 com hemiparesia direita, desvio de rima labial e afasia. Código AVC acionado. PA 218x118, FC 88, glicemia capilar 142. NIHSS 14. TC de crânio sem sangramento e sem sinais precoces extensos (ASPECTS 9). Angio-TC com oclusão de ACM esquerda M1. ECG com fibrilação atrial, FC 88 bpm. HD: AVC isquêmico de circulação anterior, provavelmente cardioembólico, em janela para trombólise.', 'Redução cautelosa da PA para < 185/110 antes da trombólise com labetalol EV; alteplase 0,9 mg/kg iniciada 85 min após início da janela. Após trombólise, PA < 180/105 por 24h. Encaminhar para trombectomia mecânica e UTI neurológica. Jejum, cabeceira a 30 graus, sem antitrombóticos por 24h.'),
  (745, 224, 13, '2022-09-11 10:00', 'internacao', 'Acompanhamento pós-trombólise na UTI neurológica', 156, 88, 78, 84.0, 'Trombectomia mecânica realizada com recanalização TICI 2b-3. Ressonância de 24h: infarto cortical-subcortical em território da ACM esquerda, sem transformação hemorrágica. NIHSS 8 após o procedimento, com melhora da força. PA mantida 140-160 por 88-96, sem hipotensão. ECO transtorácico: átrio esquerdo 52 mm, FEVE 54%, sem trombo. Holter confirma FA persistente. CHA2DS2-VASc 5 (AVC, HAS, idade 65-74).', 'Iniciar AAS 100 mg nas primeiras 24h; programar anticoagulação com DOAC após 3 a 5 dias, conforme extensão do infarto. Atorvastatina 80 mg. Fisioterapia, fonoaudiologia e avaliação de deglutição. Reiniciar anti-hipertensivo oral gradualmente após 48h.'),
  (746, 224, 13, '2022-10-24 09:30', 'retorno', 'Ainda tenho dificuldade de falar e a mão direita é fraca', 138, 82, 72, 80.2, '6 semanas pós-AVC isquêmico com trombólise e trombectomia. Sequelas: afasia de expressão leve a moderada, paresia braquiocrural direita grau 4, marcha com ceifa. Nega novos déficits. Deglutição normal, dieta oral. Faz fisioterapia e fonoterapia 3x por semana. Humor deprimido, chora com facilidade. PA 138x82, FC 72 irregular. NIHSS 4. Mantém anticoagulação sem sangramentos. Filho acompanha e cuida das medicações com caixa organizadora.', 'Manter rivaroxabana 20 mg ao jantar (ClCr 74) e suspender AAS. Atorvastatina 80 mg, anlodipino 5 mg e losartana 50 mg 12/12h para PA < 130/80. Iniciar sertralina 50 mg para depressão pós-AVC. Manter reabilitação intensiva. Retorno em 3 meses.'),
  (747, 224, 1, '2023-04-11 10:30', 'retorno', 'Pressão boa, mas não consigo mais trabalhar', 130, 78, 66, 79.0, '7 meses após o AVC. PA 130x78, FC 66 (FA com controle adequado). Persistem afasia leve e fraqueza da mão direita, que o impede de voltar a mexer na banca da feira. Melhor do humor com sertralina, vai à fisioterapia duas vezes por semana. Sem sangramentos. LDL 61 mg/dL. Anda com bengala. A esposa preocupa-se com a independência e com o custo do transporte para as terapias.', 'Manter rivaroxabana, atorvastatina, losartana, anlodipino e sertralina. Solicitado benefício assistencial e transporte do município para terapias. Meta de LDL < 55 mg/dL: acrescentar ezetimiba 10 mg. Retorno em 4 meses com exames.');
