insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (224, '2023-04-11', 'piorou', 'AVC isquêmico cardioembólico por FA não diagnosticada, com PA de 218x118 na chegada. Tratado com trombólise e trombectomia, mas ficou com afasia leve e paresia de membro superior direito que o impediram de voltar ao trabalho. Anticoagulado e com PA controlada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (225, 'Natália Ferreira Ramalho', 'F', '1996-12-14', 'Bayeux', 'PB', 'Auxiliar administrativa', 'Segunda gestação, G2P1, 31 semanas. Primeiro parto normal sem intercorrências. Sem HAS prévia. PA de pré-natal até 112x70. Peso pré-gestacional 64 kg. Mãe com hipertensão após os 50 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (748, 225, 7, '2026-01-14 09:20', 'consulta', 'Pressão alta na consulta do pré-natal', 146, 94, 84, 74.6, 'Gestante de 29 anos, G2P1, 31 semanas, encaminhada do pré-natal da UBS por PA 148x96 e 144x92 em duas ocasiões com intervalo de 4 horas. Assintomática: sem cefaleia, sem escotomas, sem epigastralgia, movimentos fetais presentes. Edema leve de tornozelos. Reflexos normais. Fita de urina negativa para proteína, relação proteína/creatinina 0,09. Plaquetas 248.000, TGO 22, creatinina 0,6, ácido úrico 4,8. BCF 140. HD: hipertensão gestacional sem proteinúria.', 'Iniciar metildopa 250 mg 8/8h. Orientação para sinais de alarme (cefaleia, escotomas, dor epigástrica, redução de movimentos fetais). Automonitorização domiciliar da PA. USG com Doppler. Pré-natal de alto risco com retornos quinzenais e labs a cada 2 semanas.'),
  (749, 225, 7, '2026-02-04 09:00', 'retorno', 'Sem queixas, só cansaço da barriga', 134, 86, 80, 77.0, '34 semanas. Assintomática. PA domiciliar entre 130 e 142 por 82 e 90, consultório 134x86 sob metildopa. Sem proteinúria em fita, edema leve. USG com Doppler: feto adequado para a idade gestacional, percentil 55, ILA normal, Doppler de artérias uterinas e umbilical normais. Labs: plaquetas 236.000, TGO 24, TGP 20, creatinina 0,6. Relata leve sonolência pela metildopa. Boa adesão. Gestação sem sinais de pré-eclâmpsia.', 'Manter metildopa 250 mg 8/8h. Repetir labs e proteinúria em 2 semanas. Cardiotocografia semanal a partir de 36 semanas. Reforçar sinais de alarme. Planejar parto com 39-40 semanas se estabilidade; antecipar se piora.'),
  (750, 225, 7, '2026-03-02 09:30', 'retorno', 'Estou com 38 semanas, quero saber do parto', 142, 90, 82, 79.4, '38 semanas, PA 142x90, assintomática, sem proteinúria (relação 0,11), plaquetas 221.000, TGO 26. Cardiotocografia reativa. Colo uterino com 2 cm de dilatação, apagado em 50%. Boa adesão à metildopa, mantém PA em casa entre 132 e 144. Quer parto normal como na primeira gestação, em hospital próximo de casa. Sem cefaleia, sem dor epigástrica.', 'Indicada indução do parto com 39 semanas por hipertensão gestacional. Internar em 7 dias para indução com misoprostol ou balão. Manter metildopa até o parto. Manter orientações e comparecer ao hospital se qualquer sinal de alarme ou trabalho de parto espontâneo.'),
  (751, 225, 7, '2026-04-21 10:00', 'retorno', 'Revisão do pós-parto, 6 semanas', 118, 74, 72, 66.8, 'Puerpério de 6 semanas. Parto normal induzido com 39 semanas e 2 dias, sem intercorrências, RN de 3.240 g, Apgar 9 e 10, em aleitamento exclusivo. A PA normalizou ainda na primeira semana e a metildopa foi suspensa na alta no 2º dia pós-parto. PA hoje 118x74, MRPA média 116x72. Sem cefaleia. Peso já próximo ao basal. Contracepção com DIU de cobre colocado hoje.', 'Sem medicação anti-hipertensiva. HAG resolvida. Orientada risco aumentado de hipertensão futura: PA anual e controle de peso, glicemia e lipídios. Considerar AAS 100 mg desde 12 semanas em próxima gestação. Alta do ambulatório de alto risco.');
