insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (225, '2026-04-21', 'controlado', 'Hipertensão gestacional sem proteinúria, controlada com metildopa até o parto normal induzido com 39 semanas, recém-nascido de 3.240 g. A PA normalizou no puerpério sem medicação (118x74). Orientada quanto ao risco de hipertensão futura e seguimento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (226, 'Nelson Alves de Araújo Neto', 'M', '1962-04-19', 'Currais Novos', 'RN', 'Serralheiro', 'HAS há mais de 20 anos, sem controle adequado. Toma anlodipino 10 mg e hidroclorotiazida 25 mg quando consegue. Tabagista de 20 maços-ano, parou há 10 anos. Consome sal em excesso. Pai faleceu de insuficiência cardíaca.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (752, 226, 1, '2024-05-14 08:40', 'consulta', 'Cansaço aos esforços e coração batendo forte', 164, 98, 76, 85.0, 'Paciente de 62 anos com HAS antiga mal controlada, cansaço aos médios esforços e palpitações ocasionais há 6 meses. Sem edema, sem ortopneia, sem angina. Ao exame: PA 164x98, ictus desviado para baixo e à esquerda, sopro sistólico suave em foco aórtico, B4. ECG: SVE com padrão de sobrecarga (strain), Sokolow-Lyon 48 mm. ECO: septo 15 mm, parede posterior 14 mm, massa VE indexada 142 g/m², FEVE 62%, disfunção diastólica grau 1, AE 43 mm. HD: cardiopatia hipertensiva com HVE.', 'Trocar hidroclorotiazida por clortalidona 25 mg; acrescentar losartana 100 mg/dia, manter anlodipino 10 mg. Dieta com restrição de sal. Alvo PA < 130/80 para regressão de HVE. Exames de função renal em 2 semanas. Rastreio de apneia do sono e MAPA. Retorno em 8 semanas.'),
  (753, 226, 1, '2024-07-30 09:00', 'retorno', 'Estou melhor, mas inchou o pé', 138, 84, 70, 83.4, 'Melhora do cansaço e das palpitações. Edema maleolar 1+/4+ ao fim do dia, atribuído ao anlodipino 10 mg. MAPA: média 24h 136x82, vigília 140x85, sono 124x74. Creatinina 1,2, potássio 4,2 (K normal), sódio 138. Aderente aos 3 comprimidos. Trabalha em pé o dia todo, com solda e esforço físico. PA 138x84 em consultório, ainda fora da meta.', 'Reduzir anlodipino para 5 mg, adicionar espironolactona 25 mg, com controle de K em 1 semana. Meias elásticas. Fazer caminhada 3x/semana, perder 4 a 5 kg. Retorno em 8 semanas.'),
  (754, 226, 1, '2025-02-11 08:30', 'retorno', 'Vim fazer o eco de controle', 126, 76, 66, 80.0, 'Sem sintomas, voltou a trabalhar normalmente e caminha à tarde. PA 126x76, MRPA 122x74. Perdeu 5 kg. Edema resolveu com redução do anlodipino. ECO de controle após 9 meses de PA controlada: septo 13 mm, parede posterior 12 mm, massa indexada 118 g/m², FEVE 63%, função diastólica melhor (E/e'' 10). ECG ainda com SVE, mas menor (Sokolow-Lyon 38 mm). Potássio 4,7 e creatinina 1,2 estáveis.', 'Manter os 4 fármacos. Regressão parcial da HVE mostra o benefício do controle pressórico. Controle de potássio semestral. Novo ECO em 12 meses. Reforçar redução do sal e do cigarro. Retorno em 6 meses.');
insert into diagnostico (id_atendimento, cid, descricao) values
  (752, 'I11.9', 'Doença cardíaca hipertensiva sem insuficiência cardíaca (congestiva)'),
