insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (227, '2024-08-12', 'transferido', 'Angina instável com doença triarterial e lesão de tronco de coronária esquerda, com indicação de revascularização cirúrgica. Estável com tratamento clínico, foi transferida com relatório e cateterismo para hospital de referência em outro estado, onde seria operada. Sai do acompanhamento do serviço.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (228, 'Ademar Schneider Vogel', 'M', '1951-05-17', 'Santa Cruz do Sul', 'RS', 'Produtor rural aposentado', 'Etilista pesado há mais de 30 anos (cerca de 1 litro de cachaça por semana mais cerveja). HAS e dislipidemia. Ex-fumante. Cardiomiopatia dilatada de causa provavelmente alcoólica, sem coronariopatia no cateterismo de 2021. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h. Viúvo, mora com o irmão.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (758, 228, 11, '2023-03-06 10:20', 'consulta', 'Muito cansado, inchado e sem fôlego', 104, 66, 98, 76.5, 'Pcte de 71 anos com IC de causa alcoólica, CF III-IV, dispneia aos mínimos esforços, DPN, edema de MMII 3+/4+ e ascite leve. Ainda bebe cerca de 5 doses de cachaça por dia. Ao exame: PA 104x66, FC 98, turgência jugular, B3, estertores até meio dos campos, hepatomegalia dolorosa. NT-proBNP 7.800 pg/mL. ECO: FEVE 22%, DDVE 72 mm, insuficiência mitral funcional moderada, PSAP 52 mmHg. HD: cardiomiopatia alcoólica com ICFEr descompensada.', 'Abstinência alcoólica como principal medida terapêutica, com tiamina 300 mg/dia e encaminhamento ao CAPS-AD. Furosemida 80 mg/dia. Iniciar espironolactona 25 mg e dapagliflozina 10 mg; trocar enalapril por sacubitril/valsartana 24/26 mg após 36h. Manter carvedilol. Retorno em 2 semanas.'),
  (759, 228, 11, '2023-05-15 10:00', 'retorno', 'Estou bem melhor, parei de beber', 112, 70, 72, 69.0, 'Abstinente há 10 semanas, com apoio do CAPS-AD e do irmão. Emagreceu 7,5 kg de líquido, edema ausente, caminha 300 metros sem parar (CF II). PA 112x70, FC 72. NT-proBNP 2.100. ECO de controle: FEVE 34%, DDVE 66 mm, IM leve. Creatinina 1,2, potássio 4,6. Orgulhoso, mostra a ficha do CAPS e diz que "nunca mais vou encostar numa garrafa".', 'Manter os quatro pilares. Aumentar carvedilol para 12,5 mg 12/12h. Reduzir furosemida para 40 mg ao dia. Orientar vacinas. Controle de K e creatinina em 4 semanas. Reavaliar ECO em 3 meses para definir necessidade de CDI. Retorno em 6 semanas.'),
  (760, 228, 6, '2023-12-04 02:30', 'pronto_socorro', 'Falta de ar muito forte, voltou a beber', 86, 54, 118, 79.8, 'Trazido pelo irmão. Recaiu no álcool há cerca de 3 semanas após a morte de um amigo, estava bebendo todos os dias e parou de tomar os remédios. Dispneia grave, extremidades frias e pegajosas, oligúria. PA 86x54, FC 118, SpO2 84%, estase jugular, estertores até ápices, edema 3+/4+. Lactato 4,2; creatinina 2,1; K 5,3; NT-proBNP 16.000. HD: IC aguda descompensada com baixo débito (perfil C frio e úmido), precipitada por recaída alcoólica.', 'VNI, furosemida EV em bolus, dobutamina em baixa dose, suspender sacubitril/valsartana e espironolactona pelo choque e hipercalemia limítrofe. Internar em UTI. Monitorização de abstinência com benzodiazepínico. Informar o irmão do prognóstico reservado.'),
  (761, 228, 11, '2024-02-12 09:30', 'retorno', 'Saí do hospital, estou fraco e sem fôlego', 94, 60, 88, 71.0, 'Retorno após 18 dias de internação, 6 em UTI, com alta em janeiro. Mantém abstinência desde a alta, mas fraco, CF III-IV, caquético, com perda de massa muscular. PA 94x60, FC 88. ECO: FEVE 20%, DDVE 74 mm, IM moderada-importante, trombo ausente. Creatinina 1,7, potássio 4,9, NT-proBNP 5.600. Hipotensão limita a titulação dos pilares. Discussão sobre cuidados paliativos e terapias avançadas com o paciente e o irmão.', 'Reiniciar espironolactona 12,5 mg e dapagliflozina 10 mg. Manter carvedilol 3,125 mg, furosemida 40 mg. Aguardar PA para reintroduzir sacubitril/valsartana. Avaliação para cuidados paliativos. Retorno em 3 semanas e orientações de alerta sobre piora.');
