insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (228, '2024-05-18', 'obito', 'Cardiomiopatia alcoólica com melhora inicial da FEVE (22% para 34%) durante a abstinência, seguida de recaída alcoólica e choque cardiogênico em dezembro de 2023. Evoluiu com FEVE 20% e caquexia. Faleceu em casa em 18/05/2024, por insuficiência cardíaca refratária, em cuidados de conforto.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (229, 'Benedita do Socorro Matos Pantoja', 'F', '1950-02-26', 'Belém', 'PA', 'Aposentada (ex-merendeira)', 'FA permanente e HAS. Em uso de varfarina 5 mg, metoprolol succinato 50 mg e enalapril 10 mg 12/12h. Faz uso de diclofenaco quando tem dor no joelho. Nunca fumou. Mora com a neta, que ajuda com as medicações. Dieta rica em açaí e folhas verdes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (762, 229, 4, '2022-08-09 14:30', 'consulta', 'Manchas roxas pelo corpo e dor no estômago', 136, 80, 82, 62.0, 'Paciente de 72 anos com FA permanente e CHA2DS2-VASc 4, em uso de varfarina. INR de hoje 3,9 (meta 2,0 a 3,0), equimoses em antebraços e coxas, epigastralgia há 3 semanas. Usa diclofenaco 50 mg quase diariamente para dor no joelho e come bastante açaí e jambu. Sem sangramento aparente, fezes normais. Hb 11,6 g/dL. Ao exame: FC 82 irregular, equimoses múltiplas, sem sopros. Interação provável de AINE com varfarina e dieta.', 'Suspender diclofenaco imediatamente. Reduzir varfarina para 2,5 mg em dias alternados com 5 mg e repetir INR em 1 semana. Iniciar omeprazol 40 mg/dia. Orientar manter dieta consistente. Paracetamol 750 mg SN para dor. Retorno em 15 dias com INR.'),
  (763, 229, 6, '2022-09-20 23:50', 'pronto_socorro', 'Fezes pretas e tontura', 88, 52, 112, 61.0, 'Pcte de 72 anos, FA em uso de varfarina, trazida pela neta com melena há 2 dias, hematêmese de borra de café hoje, tontura, palidez e sudorese. PA 88x52, FC 112 irregular. Extremidades frias, mucosas descoradas, abdome doloroso no epigástrio sem sinais de peritonite. Hb 7,2 g/dL, INR 6,8, ureia 78. Voltou a tomar diclofenaco por conta própria, por causa da dor no joelho. HD: hemorragia digestiva alta com choque hipovolêmico em uso de anticoagulante, INR supraterapêutico.', 'Suspender varfarina. Reposição volêmica, 2 unidades de concentrado de hemácias, vitamina K 10 mg EV e complexo protrombínico por INR 6,8 com instabilidade. Omeprazol 80 mg EV em bolus. Endoscopia em 12h. Internar em UTI.'),
  (764, 229, 14, '2022-09-21 10:00', 'internacao', 'Pós-endoscopia na UTI, sem novos sangramentos', 112, 68, 92, 61.0, 'Endoscopia digestiva alta: úlcera duodenal de 12 mm com vaso visível (Forrest IIa), tratada com adrenalina e hemoclipes, com hemostasia. Teste de urease positivo para H. pylori. Recebeu 2 concentrados de hemácias, Hb pós 9,1 g/dL. INR 1,4 após vitamina K. Estável, sem aminas, diurese 60 mL/h. FC 92 em FA. Sem novos episódios de melena em 18h.', 'IBP em dose plena EV por 72h, depois via oral. Tratar H. pylori com amoxicilina, claritromicina e omeprazol por 14 dias. Manter anticoagulante suspenso por 7 dias e reiniciar com DOAC após estabilidade da hemoglobina. Alta da UTI em 24h.'),
  (765, 229, 4, '2022-11-08 14:00', 'retorno', 'Vim ver se posso voltar a tomar o remédio do sangue', 128, 74, 76, 62.4, 'Seis semanas após hemorragia digestiva alta. Concluiu erradicação de H. pylori, sem dor epigástrica e sem melena. Hb 11,8 g/dL, creatinina 1,0 (ClCr 49 mL/min). Parou definitivamente o diclofenaco e usa paracetamol; neta tirou o remédio de casa. PA 128x74, FC 76. FA mantida em ritmo controlado. Após revisão do risco/benefício (CHA2DS2-VASc 4 contra HAS-BLED 3 após modificação de fatores), decidimos por DOAC com menor risco de sangramento que a varfarina instável.', 'Iniciar apixabana 5 mg de 12/12h (sem critérios de redução: idade < 80, peso > 60 kg, creatinina < 1,5). Manter omeprazol 20 mg por tempo indeterminado como gastroproteção. Metoprolol e enalapril mantidos. Evitar AINEs. Retorno em 3 meses com hemograma e função renal.');
