insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (229, '2022-11-08', 'melhorou', 'Hemorragia digestiva alta por úlcera duodenal com H. pylori, favorecida por diclofenaco e INR de 6,8 em uso de varfarina. Tratada com endoscopia terapêutica e erradicação. Retornou à anticoagulação com apixabana e gastroproteção, hemoglobina recuperada (11,8 g/dL), sem novos sangramentos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (230, 'Gilberto Cândido Rezende', 'M', '1941-09-22', 'Goiânia', 'GO', 'Contador aposentado', 'HAS e hiperplasia prostática. Em uso de losartana 50 mg 12/12h e tamsulosina. Nega DM, nega tabagismo. Joga dominó e caminha 30 minutos por dia. Um episódio de tontura em julho, sem investigação. Mora com a esposa, 78 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (766, 230, 6, '2023-11-03 20:30', 'pronto_socorro', 'Desmaiou na sala, ficou roxo e voltou sozinho', 168, 72, 34, 74.0, 'Pcte de 82 anos, HAS, apresentou síncope súbita durante o jantar, com perda de consciência de cerca de 30 segundos e recuperação espontânea, sem convulsão. Cansaço e tontura há 2 semanas. Ao exame: bradicárdico, FC 34, PA 168x72, ausculta com B1 variável (ondas em canhão no pescoço), MV+ sem RA, sem edema. ECG: BAVT com escape juncional de QRS estreito a 34 bpm, dissociação AV. Troponina negativa, K 4,3, TSH normal. HD: BAVT sintomático.', 'Monitorização contínua e acesso venoso, atropina sem resposta. Implante de marca-passo transvenoso provisório pela veia jugular direita sem intercorrências, FC 70 bpm. Internação em UTI. Suspender losartana e tamsulosina. Programar marca-passo definitivo.'),
  (767, 230, 4, '2023-11-05 08:00', 'internacao', 'Implante de marca-passo definitivo', 150, 80, 70, 74.0, 'Estável com marca-passo provisório, sem novas síncopes. ECO: FEVE 58%, HVE leve, sem valvopatias significativas. Implante de marca-passo dupla câmara DDD por via subclávia esquerda sem intercorrências, parâmetros de limiar 0,6 V, sensibilidade de onda R 12 mV, impedância adequada. Radiografia de controle sem pneumotórax. FC programada em 60 bpm, resposta de frequência ativa. Alta em 24h.', 'Cuidados da ferida, restrição de elevação do braço esquerdo acima do ombro por 4 semanas, carteira do dispositivo. Retomar losartana 50 mg 12/12h para PA 150x80. Evitar ressonância não condicional. Controle do dispositivo em 30 dias.'),
  (768, 230, 4, '2023-12-12 10:00', 'retorno', 'Vim fazer a revisão da maquininha', 134, 78, 64, 74.6, 'Retorno de 5 semanas. Sem síncopes, sem tontura, voltou às caminhadas diárias. Ferida cirúrgica bem cicatrizada, loja do gerador sem hematoma. Interrogação do marca-passo: bateria 100%, limiar atrial 0,75 V, ventricular 0,75 V, sem arritmias, 98% de estimulação ventricular. Comparece com a esposa, que se queixa de cuidado excessivo, brinca que "agora ele tem bateria que dura mais que a minha".', 'Ajuste de programação com saída de segurança. Manter losartana. Reativar atividade física leve a moderada. Controle em 6 meses e depois anual. Orientado a evitar contato próximo do telefone celular com o gerador e a atravessar portais de segurança com cartão.'),
  (769, 230, 4, '2024-12-17 10:30', 'retorno', 'Controle anual do marca-passo', 132, 76, 62, 75.0, 'Um ano de implante. Sem tontura, síncope, dispneia ou palpitações; faz caminhadas de 40 minutos e joga dominó duas vezes por semana. PA 132x76. Interrogação: bateria 97%, limiares estáveis (A 0,75 V, V 0,75 V), estimulação ventricular 98%, episódios de FA atrial ausentes. ECO sem piora da FEVE (57%) apesar da estimulação ventricular elevada. Estável e satisfeito, sem queixas.', 'Manter losartana. Controle do marca-passo a cada 6 a 12 meses, ECO anual pela alta taxa de estimulação ventricular. Atenção a sintomas de IC. Retorno em 12 meses.');
