insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (230, '2024-12-17', 'controlado', 'BAVT sintomático em idoso de 82 anos tratado com marca-passo provisório e depois definitivo dupla câmara. Sem síncope desde o implante, limiares estáveis, FEVE preservada em 57%, PA controlada com losartana. Em acompanhamento anual do dispositivo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (231, 'Rejane Maria Nóbrega Cunha', 'F', '1971-06-13', 'Cabedelo', 'PB', 'Secretária escolar', 'HAS há 9 anos, obesidade grau II. Usa losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg. Sedentária, come muito pão e frituras. Pai e irmã hipertensos. Menopausa aos 49 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (770, 231, 1, '2023-02-07 10:30', 'consulta', 'Quero emagrecer para largar os remédios', 148, 94, 80, 104.0, 'Paciente de 51 anos com HAS, IMC 40, em uso de 3 anti-hipertensivos com PA 148x94 e edema de tornozelo pelo anlodipino 10 mg. Adesão boa. Comeu "de tudo" na pandemia e engordou 25 kg. Já tentou dietas sem sustentação. Sem dispneia, sem angina, sem apneia relatada. Ao exame: circunferência abdominal 112 cm, RCR 2T BNF, sem sopros, edema maleolar 1+. Glicemia de jejum 108, HbA1c 5,9%. HD: HAS + obesidade grau III, pré-diabetes.', 'Encaminhada à nutricionista e ao programa de atividade física da UBS. Meta de perda de 10% do peso em 6 meses. Manter esquema atual. Orientada redução de sal e ultraprocessados. Avaliar tratamento farmacológico da obesidade com endocrinologia. Retorno em 5 meses.'),
  (771, 231, 1, '2023-09-12 10:00', 'retorno', 'Estou com 12 quilos a menos e fico tonta de vez em quando', 118, 72, 70, 92.0, 'Perdeu 12 kg em 7 meses com acompanhamento nutricional, caminhada de 40 minutos 5x/semana e hidroginástica. Relata tonturas ocasionais ao levantar, mais pela manhã, sem síncope. PA 118x72 no consultório e MRPA média 112x68, com mínimas de 98x60. Edema desapareceu. Sódio 138, potássio 3,8, creatinina 0,8. HbA1c 5,4%. Está animada e diz que "se eu soubesse que perder peso fazia tanto efeito, tinha feito antes".', 'Suspender hidroclorotiazida e reduzir anlodipino para 5 mg, mantendo losartana 100 mg, pela hipotensão relativa e queda de peso. MRPA por 7 dias e retorno em 8 semanas. Manter dieta e exercício. Meta de perda de mais 8 kg.'),
  (772, 231, 1, '2024-05-14 10:20', 'retorno', 'Perdi mais peso, será que posso tirar outro remédio?', 116, 70, 66, 84.0, 'Perdeu 20 kg desde o início (IMC 32). Mantém exercícios e dieta. MRPA recente, média 114x70, sem valores acima de 130x82. Sem tonturas desde a redução. Creatinina 0,8, potássio 4,2. LDL 98 sem estatina. PA no consultório 116x70, sem edema. Afirma ter mais disposição no trabalho e menos dor no joelho.', 'Suspender anlodipino e manter somente losartana 50 mg/dia (redução da dose). Acompanhar com MRPA mensal por 3 meses. Se PA > 130/80 em média, retornar à dose anterior. Manter perda de peso. Retorno em 3 meses.');
