insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (231, '2024-05-14', 'controlado', 'Hipertensa obesa que perdeu 20 kg em 15 meses com dieta e exercício, reduzindo o tratamento de três fármacos para losartana 50 mg isolada, com PA domiciliar média 114x70. Segue em monitorização mensal da PA e acompanhamento do peso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (232, 'Luís Fernando Albuquerque Maia', 'M', '1964-12-02', 'Paulista', 'PE', 'Vigilante', 'Tabagista de 35 maços-ano, ainda fuma. HAS sem tratamento, dislipidemia. Pai com IAM aos 56 anos. Trabalha em escala 12x36, com alimentação irregular. Etilismo social.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (773, 232, 6, '2021-06-14 04:20', 'pronto_socorro', 'Dor forte no peito e suor frio no plantão', 98, 60, 52, 88.0, 'Pcte de 56 anos chega por dor precordial intensa há 2h, náuseas e sudorese. Ao exame: pálido, sudoreico, PA 98x60, FC 52, pulmões limpos, sem estase jugular. ECG: supradesnível de ST em DII, DIII e aVF, com espelhamento em DI e aVL, BAV 1º grau. Troponina 1,9 ng/mL. Sem hospital de hemodinâmica disponível em 2 horas na cidade, indicada fibrinólise. HD: IAMCSST inferior (Killip I), sem sinais de VD.', 'Tenecteplase em dose ajustada ao peso, AAS 300 mg, clopidogrel 300 mg e enoxaparina. Evitar nitrato e morfina excessiva pela PA baixa. Reperfusão confirmada pela redução de ST > 50% e resolução da dor. Transferido para hemodinâmica em até 24h.'),
  (774, 232, 10, '2021-06-15 11:00', 'internacao', 'Cateterismo pós-fibrinólise', 118, 74, 62, 88.0, 'Estável, sem angina. CATE por via radial: oclusão trombótica residual com estenose crítica de 95% de CD média, fluxo TIMI 2, DA com lesão de 50%, CX sem lesões. FEVE 48% com hipocinesia inferior. Realizada ATC com stent farmacológico 3,5 x 24 mm em CD, sem complicações, fluxo TIMI 3. BAV resolveu.', 'Dupla antiagregação (AAS + clopidogrel) por 12 meses. Iniciar atorvastatina 80 mg, metoprolol succinato 25 mg e enalapril 5 mg 12/12h. Cessação do tabagismo com bupropiona e reposição de nicotina. Alta em 3 dias. Retorno em 2 meses.'),
  (775, 232, 1, '2021-08-23 10:30', 'retorno', 'Estou bem, mas o clopidogrel está caro', 124, 76, 58, 85.0, 'Sem angina, retornou ao trabalho. Parou de fumar por 4 semanas, mas voltou a fumar 5 cigarros/dia após o plantão. Reclama do custo do clopidogrel, comprado no varejo. PA 124x76, FC 58. ECO: FEVE 50%. LDL 74 mg/dL. Explicado que a dupla antiagregação até 12 meses é essencial para evitar trombose do stent, e que há opção de retirada pelo programa de farmácia popular/UBS.', 'Manter AAS, clopidogrel, atorvastatina, metoprolol e enalapril. Orientações escritas sobre a importância de não parar o clopidogrel. Encaminhado ao programa de tabagismo. Pedir à UBS o fornecimento do clopidogrel. Retorno em 3 meses.'),
  (776, 232, 6, '2022-03-17 03:10', 'pronto_socorro', 'Dor no peito de novo, igual à do infarto', 90, 56, 108, 86.0, 'Pcte de 57 anos, 9 meses pós-IAMCSST inferior com stent em CD. Dor precordial intensa há 1h30 durante o plantão, sudorese e dispneia. Admite que parou o clopidogrel há cerca de 3 meses por custo e voltou a fumar 15 cigarros/dia. PA 90x56, FC 108, estertores nas bases, B3. ECG: supra de ST em DII, DIII, aVF. Troponina 4,8 ng/mL. Killip III. HD: IAMCSST inferior recorrente por provável trombose tardia do stent, com IC.', 'AAS 300 mg, ticagrelor 180 mg, heparina e ATC primária. Furosemida EV 40 mg para congestão, evitar vasodilatador pela PA baixa. Sala de hemodinâmica imediata. Internação em UTI. Comunicar a família da gravidade.');
