insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (232, '2022-06-20', 'piorou', 'IAM inferior com stent em CD que evoluiu com trombose tardia do stent após interrupção do clopidogrel por custo e retorno ao tabagismo. Novo IAM com FEVE 36% e insuficiência cardíaca, com alta em abril de 2022 e seguimento em ICFEr isquêmica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (233, 'Terezinha Aparecida Matoso Dantas', 'F', '1957-03-09', 'Parnamirim', 'RN', 'Costureira aposentada', 'HAS há 18 anos, dislipidemia, sedentária. IAM em dezembro de 2021, tratado com angioplastia e stent farmacológico em DA. Em uso de AAS, clopidogrel, atorvastatina 40 mg, metoprolol e losartana. Nunca fumou. Mora sozinha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (777, 233, 1, '2022-01-18 09:00', 'consulta', 'Tenho medo de andar depois do infarto', 130, 78, 60, 74.0, 'Paciente de 64 anos, 5 semanas pós-IAMSSST com ATC e stent em DA. Sem angina, sem dispneia aos esforços habituais. Está de repouso quase total por medo de infartar de novo e perdeu massa muscular, pressão em casa em torno de 130x80. Ao exame: RCR 2T BNF, sem sopros, pulmões limpos, sem edema. ECG: ritmo sinusal, onda Q em V1-V3 pequena. LDL 71 mg/dL. FEVE 52% no ECO da alta.', 'Encaminhada ao programa de reabilitação cardiovascular (3 sessões semanais por 12 semanas), com avaliação ergoespirométrica inicial. Manter medicações. Explicado que o exercício supervisionado é seguro e melhora o prognóstico. Retorno ao fim do programa.'),
  (778, 233, 1, '2022-05-17 09:20', 'retorno', 'Terminei a reabilitação, estou outra pessoa', 124, 72, 58, 71.2, 'Completou 34 sessões de reabilitação cardiovascular. Capacidade funcional inicial de 5 METs no teste ergométrico, agora com 8,5 METs, sem angina nem arritmias. Perdeu 2,8 kg e ganhou massa magra. Sentiu cãibras nas pernas com atorvastatina 40 mg no início, mas melhorou. PA 124x72, FC 58. Passou a caminhar 5x por semana e participa de grupo de convivência, onde fez amigas. Diz que "aprendi a escutar o corpo, sem medo".', 'Manter AAS, clopidogrel (até completar 12 meses), atorvastatina, metoprolol e losartana. Manutenção do exercício regular em academia ao ar livre, 150 minutos/semana. Dosar CK se mialgia persistir. Retorno em 6 meses.'),
  (779, 233, 1, '2023-02-14 09:40', 'retorno', 'Consulta de rotina, estou muito bem', 122, 70, 60, 70.6, '14 meses do IAM. Clopidogrel suspenso em dezembro conforme programado, mantém AAS. Assintomática, mantém caminhadas e a hidroginástica, 3 METs a mais de capacidade que no início. PA 122x70. LDL 54 mg/dL, HbA1c 5,6%, creatinina 0,8. Sem queixas de mialgia, sem sangramentos. Pergunta se pode viajar de ônibus para ver a filha em outro estado; liberada.', 'Manter AAS, atorvastatina 40 mg, metoprolol e losartana. Manter exercício regular. Vacinas anuais. Retorno em 6 meses; procurar PS se dor torácica, dispneia ou síncope.');
