insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (234, '2023-06-30', 'abandonou', 'ICFEr isquêmica com FEVE 30% e várias barreiras ao tratamento: disfunção erétil atribuída ao betabloqueador, custo dos fármacos e negativa do componente especializado. Voltou descompensado e recusou internação. Não compareceu ao retorno de uma semana nem às buscas telefônicas posteriores.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (235, 'Aurelina Gomes de Lima Sobral', 'F', '1958-01-30', 'Guarabira', 'PB', 'Agente comunitária de saúde aposentada', 'HAS de longa data (25 anos), mal controlada. Diagnóstico de cardiomiopatia dilatada há 8 meses, sem doença coronariana no cateterismo. Em uso de enalapril 10 mg 12/12h, furosemida 40 mg e carvedilol 3,125 mg 12/12h. Nunca fumou, não bebe. Ajuda a cuidar de dois netos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (783, 235, 11, '2023-08-22 09:00', 'consulta', 'Falta de ar para varrer a casa', 134, 84, 88, 68.0, 'Paciente de 65 anos com ICFEr não isquêmica, provável cardiopatia hipertensiva dilatada, em CF II-III. Ortopneia leve e edema vespertino de tornozelos 1+. Ao exame: PA 134x84, FC 88, B3 sutil, pulmões limpos. NT-proBNP 2.050. ECO: FEVE 30%, DDVE 62 mm, IM leve. Cateterismo prévio sem lesões obstrutivas. Ressonância: realce tardio ausente. Creatinina 1,0, K 4,3, TFGe 61.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após pausa de 36 horas. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Titular carvedilol para 6,25 mg 12/12h. Dieta com sal restrito, peso diário. Controle de K e creatinina em 1 semana. Retorno em 4 semanas.'),
  (784, 235, 11, '2023-10-17 09:20', 'retorno', 'Melhorei bastante, só fico tonta às vezes', 104, 64, 66, 65.4, 'Quase sem dispneia (CF I-II). Perdeu 2,6 kg de líquido, sem edema. Tonturas leves ao levantar, PA 104x64 e 98x60 em pé. Potássio 4,8, creatinina 1,1. NT-proBNP caiu para 780. Tolera todos os fármacos; passou a ir à academia da UBS. Reduzimos furosemida há duas semanas por conta própria (pelo balanço de líquidos), peso estável. Diz que "nunca imaginei voltar a carregar um neto no colo".', 'Suspender furosemida (euvolêmica). Manter sacubitril/valsartana 24/26, carvedilol 12,5 mg 12/12h, espironolactona 25 mg e dapagliflozina. Não aumentar sacubitril/valsartana pela PA baixa. ECO em 3 meses. Orientar levantar devagar. Retorno em 3 meses.'),
  (785, 235, 11, '2024-04-23 09:30', 'retorno', 'Vim ver o resultado do eco', 110, 68, 64, 66.0, 'Assintomática (CF I), peso estável, PA 110x68, FC 64. ECO após 8 meses de terapia otimizada: FEVE 46% (de 30%), DDVE 56 mm, IM mínima. NT-proBNP 410 pg/mL. Cardiomiopatia dilatada com recuperação parcial da função (IC com fração de ejeção melhorada). Mantém espironolactona sem ginecomastia ou hipercalemia: K 4,7. Fica ansiosa quando pensa em parar remédios; orientada a manter, pois a retirada pode provocar recaída.', 'Manter os quatro pilares sem retirada. Aumentar sacubitril/valsartana para 49/51 mg 12/12h se PA permitir; PA 110x68, tentar com vigilância. Controle de K e creatinina em 2 semanas. ECO semestral. Retorno em 4 meses.');
