insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (235, '2024-04-23', 'melhorou', 'Cardiomiopatia dilatada hipertensiva com FEVE 30%, que recuperou parcialmente (46%) após otimização dos quatro pilares da IC. NT-proBNP de 2.050 para 410, assintomática em CF I e sem internações. Mantém terapia completa sem retirada, com ECO semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (236, 'Everton Ramos de Menezes', 'M', '1974-08-08', 'Natal', 'RN', 'Personal trainer', 'Sem HAS ou DM. Praticante de corrida e musculação desde jovem, usa suplemento de pré-treino com cafeína. Etilismo social. Apneia leve não tratada. Sem história familiar de FA.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (786, 236, 4, '2022-07-12 15:00', 'consulta', 'Coração irregular e perda de rendimento nos treinos', 132, 84, 108, 82.0, 'Homem de 47 anos, atleta amador, com palpitações irregulares há 3 semanas, queda de desempenho e cansaço aos esforços moderados. Sem síncope, sem dor torácica. Relata uso de pré-treino com cafeína e noites de pouco sono. Ao exame: ritmo irregular, FC 108, sem sopros, PA 132x84. ECG: fibrilação atrial, resposta ventricular 108. ECO: AE 41 mm, FEVE 60%, sem valvopatia. TSH 1,6. CHA2DS2-VASc 0. Início < 48h não confirmado.', 'Controle de frequência com metoprolol succinato 50 mg. Anticoagulação com apixabana 5 mg 12/12h por 3 semanas antes da cardioversão elétrica eletiva (CHA2DS2-VASc 0, mas início incerto). Suspender pré-treino e reduzir álcool. Polissonografia. Retorno em 4 semanas.'),
  (787, 236, 4, '2022-09-06 07:30', 'internacao', 'Cardioversão elétrica eletiva', 128, 80, 78, 81.5, 'Após 8 semanas de anticoagulação regular, internado para cardioversão elétrica eletiva sob sedação. ETE descartou trombo em apêndice atrial esquerdo. Realizado choque sincronizado de 150 J bifásico com reversão para ritmo sinusal ao primeiro choque. ECG pós: sinusal, FC 64. Alta no mesmo dia. Sem sintomas neurológicos nem arritmias após o procedimento.', 'Manter apixabana por pelo menos 4 semanas pós-cardioversão e metoprolol 50 mg. Retorno em 30 dias com ECG e Holter. Evitar estimulantes e álcool. Liberação gradual para exercício.'),
  (788, 236, 4, '2023-02-14 15:20', 'retorno', 'Voltou o coração desordenado depois de uma corrida', 130, 82, 112, 82.0, 'Manteve ritmo sinusal por 4 meses, com recorrência em fevereiro após corrida de 10 km, com palpitações e queda do rendimento. Apixabana suspensa em outubro por conta própria e retomada na recorrência. ECG: FA com resposta ventricular de 112. Polissonografia: IAH 14 (apneia leve). Holter mostra FA persistente, sem pausas. Quer permanecer no esporte e prefere evitar antiarrítmico crônico. Discutido ablação por cateter e antiarrítmicos.', 'Indicada ablação por crioenergia (isolamento das veias pulmonares), eletiva. Manter apixabana ininterrupta antes do procedimento e metoprolol. Tratar apneia com perda de peso e posição lateral. Internação programada em 8 semanas.'),
  (789, 236, 4, '2023-04-18 07:00', 'internacao', 'Ablação de fibrilação atrial', 124, 78, 92, 80.8, 'Internado para ablação de FA. Realizado isolamento elétrico das quatro veias pulmonares com crioballoon sob anestesia geral, com bloqueio de entrada e saída confirmado. Cardioversão elétrica ao final do procedimento para ritmo sinusal. Sem complicações (derrame pericárdico, lesão do nervo frênico ou do esôfago). Alta no dia seguinte, assintomático, ECG em ritmo sinusal.', 'Manter apixabana por no mínimo 2 meses. IBP por 4 semanas. Repouso relativo 7 dias. Alertar sobre dor torácica, febre ou disfagia. Evitar exercícios intensos por 4 semanas. Retorno em 30 dias.'),
  (790, 236, 4, '2023-10-10 15:30', 'retorno', 'Voltei a treinar e correr sem problemas', 122, 76, 60, 78.5, '6 meses pós-ablação. Sem palpitações, voltou a correr 10 km e a dar aulas. Holter de 7 dias: ritmo sinusal em 100% do tempo, sem episódios de FA. Perdeu 2 kg, reduzindo o álcool. Em uso de apixabana desde a ablação, sem sangramentos. CHA2DS2-VASc 0; após 6 meses de ritmo sinusal sem recorrência, anticoagulação desnecessária. PA 122x76, FC 60.', 'Suspender apixabana (CHA2DS2-VASc 0 e sem recorrência) e metoprolol. Orientado a procurar atendimento se palpitações. Manter MEV, tratamento da apneia. Holter anual. Alta para seguimento com retorno em 6 meses.');
