insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (236, '2023-10-10', 'controlado', 'Fibrilação atrial persistente em atleta amador, com recorrência após cardioversão elétrica e cura funcional com ablação por crioballoon. Seis meses depois, Holter de 7 dias em ritmo sinusal 100% do tempo, voltou a correr e dispensou anticoagulante e betabloqueador.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (237, 'Zuleide Gomes de Albuquerque Cavalcanti', 'F', '1949-04-04', 'Arcoverde', 'PE', 'Aposentada (ex-costureira)', 'HAS há 30 anos e DM2 há 8 anos, tratados com losartana 50 mg 12/12h e metformina 850 mg 12/12h. Pneumonia há 2 anos. Nunca fumou. Duas filhas ajudam com consultas. Sentia-se cansada nos últimos meses, atribuía à idade.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (791, 237, 4, '2024-01-16 10:30', 'consulta', 'Coração muito acelerado e canseira', 124, 76, 148, 67.0, 'Paciente de 74 anos com palpitações regulares, dispneia aos esforços e tontura há 5 dias. Sem síncope nem dor torácica. Ao exame: ritmo regular, FC 148 fixa, PA 124x76, pulmões limpos, sem edema. ECG: flutter atrial típico com condução AV 2:1, ondas F em dente de serra em DII, DIII e aVF, FC 148. ECO: AE 44 mm, FEVE 56%. CHA2DS2-VASc 5 (idade 65-74, sexo feminino, HAS, DM). TSH normal.', 'Iniciar apixabana 5 mg 12/12h (indicação formal) e metoprolol succinato 50 mg. Programar cardioversão elétrica ou ablação do istmo cavotricuspídeo, esta com maior taxa de cura. Hemograma, coagulação e função renal. Retorno em 3 semanas.'),
  (792, 237, 4, '2024-02-20 07:30', 'internacao', 'Ablação do flutter atrial', 128, 78, 126, 66.4, 'Internada para ablação. Persistência do flutter com FC 126 mesmo com betabloqueador, cansaço aos esforços. Estudo eletrofisiológico: circuito macrorreentrante dependente do istmo cavotricuspídeo, confirmado por mapeamento 3D. Aplicação de radiofrequência linear no istmo, com bloqueio bidirecional confirmado, reversão para ritmo sinusal durante a aplicação. Sem complicações; alta no dia seguinte.', 'Manter apixabana por pelo menos 2 meses e após reavaliar pelo escore CHA2DS2-VASc, mantendo se for alto risco. Manter metoprolol. Cuidados do acesso femoral, evitar esforços por 1 semana. Retorno em 8 semanas com Holter.'),
  (793, 237, 4, '2024-04-23 10:00', 'retorno', 'Estou bem, sem aperreio no peito', 126, 74, 64, 66.8, 'Assintomática, voltou à rotina doméstica e às caminhadas até a feira. Holter de 24h: ritmo sinusal, FC média 66, sem flutter nem FA, 2 extrassístoles supraventriculares isoladas. PA 126x74. Sem sangramentos com apixabana. Mantendo uso de metoprolol, mas FC de repouso baixa para a idade; sem tontura. ClCr 57 mL/min, hemoglobina 12,6 g/dL. Pergunta se pode parar o "remédio do sangue" agora que está curada.', 'Manter apixabana 5 mg 12/12h indefinidamente: CHA2DS2-VASc 5, risco de FA futura é alto mesmo após ablação do flutter. Suspender metoprolol, manter losartana. Controle de hemoglobina e creatinina a cada 6 meses. Retorno em 6 meses.');
