insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (237, '2024-04-23', 'melhorou', 'Flutter atrial típico com resposta de 148 bpm, curado com ablação do istmo cavotricuspídeo. Em ritmo sinusal ao Holter, assintomática. Mantém apixabana por escore CHA2DS2-VASc de 5 e suspendeu o betabloqueador. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (238, 'Giovanna Pellegrini Moretti', 'F', '1960-03-02', 'Ribeirão Preto', 'SP', 'Professora universitária', 'Sopro cardíaco conhecido desde a juventude (prolapso de valva mitral). HAS leve em uso de losartana 50 mg/dia. Corre 3x por semana, mas vem notando menos fôlego. Nunca fumou. Descendente de italianos, mãe com doença valvar.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (794, 238, 2, '2023-05-09 14:00', 'consulta', 'Perdi o fôlego nas corridas e sinto o coração batendo errado', 138, 78, 84, 62.0, 'Paciente de 63 anos com piora gradual da tolerância ao exercício há 1 ano e palpitações ocasionais. Ao exame: ictus deslocado, sopro holossistólico 4+/6+ em foco mitral irradiado para axila, B3. ECO: prolapso do folheto posterior com flail de P2, regurgitação mitral grave excêntrica, AE 52 mm, VE com DSVE 42 mm (limítrofe), FEVE 58%, PSAP 46 mmHg. NT-proBNP 480. Sintomática (CF II). HD: insuficiência mitral primária grave.', 'Indicada correção cirúrgica, preferindo plástica valvar. ETE para planejamento e CATE de rotina. Manter losartana, adicionar furosemida 20 mg para dispneia. Evitar esforço intenso até a cirurgia. Orientada profilaxia de endocardite nos procedimentos dentários. Retorno com ETE em 4 semanas.'),
  (795, 238, 12, '2023-06-13 14:30', 'retorno', 'Vim conversar com o cirurgião sobre a operação', 134, 76, 80, 61.6, 'Consulta de cirurgia cardiovascular. ETE confirma flail de P2 com 2 cordoalhas rotas, jato excêntrico dirigido ao septo, aparelho valvar favorável à plástica (sem calcificação, tecido espesso mínimo). CATE sem lesões coronárias. Discute-se plástica com anel e neocordas versus troca com bioprótese; paciente prefere reparo para evitar anticoagulação. Risco cirúrgico baixo (STS 0,8%).', 'Indicada plástica mitral eletiva com anuloplastia. Consentimento informado. Exames pré-operatórios e avaliação odontológica. Internação em 4 semanas. Manter furosemida e losartana, suspender losartana 24h antes. Retorno ao hospital na véspera.'),
  (796, 238, 12, '2023-07-10 07:00', 'internacao', 'Cirurgia de reparo da valva mitral', 118, 70, 78, 61.0, 'Plástica da valva mitral por esternotomia mínima: ressecção triangular de P2, neocordas de PTFE e anuloplastia com anel semirrígido de 32 mm. CEC 96 minutos, pinçamento aórtico 68 minutos. ETE intraoperatório sem regurgitação residual significativa (traço), sem gradiente. Extubada em 4 horas, fase de UTI de 24 horas. Fibrilação atrial transitória no 2º PO revertida com amiodarona. Alta no 6º dia.', 'AAS 100 mg e anticoagulação com varfarina por 3 meses (INR 2,0-3,0) pelo anel e FA transitória. Reabilitação cardíaca. Cuidado com a ferida. Profilaxia de endocardite. Retorno em 30 dias com ECO.'),
  (797, 238, 2, '2023-09-12 14:00', 'retorno', 'Respiro como há 10 anos', 122, 72, 68, 62.4, 'Dois meses de pós-operatório. Sem dispneia, retomou caminhadas e voltou a dar aula. Ferida esternal cicatrizada. PA 122x72, FC 68, sem sopros. ECO: plástica mitral competente, IM mínima, gradiente médio 3 mmHg, AE 44 mm, DSVE 36 mm, FEVE 60%, PSAP 28. INR 2,4. NT-proBNP 140. Satisfeita, mas queixa de hematomas pequenos e cuidado com a alimentação por causa da varfarina.', 'Suspender varfarina ao completar 3 meses, mantendo AAS 100 mg. Suspender furosemida. Manter losartana. ECO anual. Profilaxia de endocardite antes de procedimentos dentários invasivos. Retorno em 6 meses.');
