insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (238, '2023-09-12', 'melhorou', 'Insuficiência mitral primária grave por flail de P2, corrigida com plástica valvar e anuloplastia, sem prótese. ECO mostra insuficiência mínima, FEVE 60% e pressão pulmonar normal. Assintomática, voltou a trabalhar e a caminhar, com seguimento ecocardiográfico anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (239, 'Zacarias Moreira dos Anjos', 'M', '1957-12-10', 'Guanambi', 'BA', 'Lavrador aposentado', 'Doença de Chagas crônica (sorologia positiva há 15 anos), nasceu e viveu em casa de taipa. BRD com BDAS ao ECG. Hipertensão leve em uso de enalapril 10 mg 12/12h. Não fuma, bebe pouco. Irmã com marca-passo por Chagas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (798, 239, 11, '2021-09-14 09:00', 'consulta', 'Tonturas e vista escurecendo', 138, 74, 48, 66.0, 'Paciente de 63 anos, Chagas crônico com cardiopatia (BRD + BDAS), refere episódios de tontura e escurecimento visual aos esforços e ao se levantar, últimas semanas. Sem síncope. Ao exame: pulso lento, FC 48 regular, ondas A em canhão ocasionais, sem sinais de IC. ECG: BRD + BDAS, BAV de 2º grau Mobitz II intermitente. Holter: pausas de até 3,4 s, BAV 2:1 intermitente. ECO: FEVE 52%, sem aneurisma. HD: cardiopatia chagásica com bloqueio AV avançado.', 'Indicação de marca-passo definitivo pelo bloqueio AV avançado sintomático. Sem tratamento etiológico (cardiopatia estabelecida). Suspender medicações cronotrópicas negativas, manter enalapril. Orientado a evitar esforços e dirigir. Encaminhado ao Dr. Fernando para o implante.'),
  (799, 239, 6, '2022-01-25 22:40', 'pronto_socorro', 'Desmaiou na roça e bateu a cabeça', 150, 64, 32, 65.0, 'Pcte de 64 anos, Chagas, não conseguiu agendar o implante do marca-passo, apresentou síncope súbita com trauma craniano leve e laceração frontal. Chega confuso, lúcido ao fim de 10 minutos. PA 150x64, FC 32, pulso lento e regular. ECG: BAVT com escape ventricular a 32 bpm, QRS largo (BRD + BDAS). Sem sinais de TCE grave (TC de crânio normal). Glicemia 96, K 4,1. HD: BAVT sintomático em Chagas, síncope de Stokes-Adams.', 'Marca-passo transcutâneo e dopamina enquanto prepara o transvenoso provisório. Sutura da laceração. Internação em UTI. Pedir marca-passo definitivo em caráter de urgência. Suspender qualquer fármaco bradicardizante.'),
  (800, 239, 4, '2022-01-27 09:00', 'internacao', 'Implante de marca-passo definitivo', 140, 80, 70, 65.0, 'Estabilizado com marca-passo provisório. Implante de marca-passo dupla câmara DDD por acesso subclávio esquerdo sem intercorrências, com limiares ventricular de 0,5 V e atrial de 0,7 V adequados. Radiografia sem pneumotórax. Alta em 24h, sem tontura, FC 70 estimulada. Laceração frontal cicatrizando.', 'Orientações do dispositivo, cuidados com a ferida, evitar elevação do braço por 4 semanas. Retomar enalapril 10 mg 12/12h. Revisão em 30 dias e a cada 6 meses. Considerar CDI se surgir TV sustentada pela doença de base. Retorno com ECO.'),
  (801, 239, 11, '2023-03-14 09:30', 'retorno', 'Estou bem, vim pegar a receita', 132, 78, 66, 67.0, '14 meses de marca-passo. Sem síncope, sem tontura, voltou a trabalhar um pouco na roça de subsistência, mas se queixa de cansaço aos grandes esforços. PA 132x78. Interrogação: bateria 94%, limiares estáveis, 62% de estimulação ventricular, 8 episódios de TVNS. ECO: FEVE 46% (queda de 52%), hipocinesia inferobasal. NT-proBNP 480. Início de disfunção sistólica da Chagas. Holter com extrassístoles ventriculares frequentes.', 'Iniciar carvedilol 3,125 mg 12/12h (agora protegido pelo marca-passo), espironolactona 25 mg e manter enalapril. Considerar dapagliflozina caso a FEVE caia mais. Evitar benznidazol (cardiopatia estabelecida). Monitorar TVNS e risco de CDI. Retorno em 3 meses.');
