insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (239, '2023-03-14', 'estavel', 'Cardiopatia chagásica com BAVT sintomático, tratado com marca-passo definitivo após síncope com trauma. Sem novas síncopes desde o implante, mas com início de disfunção sistólica (FEVE 46%) e TVNS. Em tratamento de IC e vigilância do risco de CDI.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (240, 'Priscila Yumi Hayashi Teixeira', 'F', '1990-11-20', 'Niterói', 'RJ', 'Analista de sistemas', 'Palpitações súbitas desde a adolescência, que iniciam e terminam bruscamente, com duração de minutos, que aliviava com manobra de Valsalva. Ansiedade. Sem HAS, sem DM, sem cardiopatia estrutural. Não fuma. Bebe café em excesso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (802, 240, 4, '2023-03-02 16:30', 'consulta', 'Crises de coração disparado que vêm e vão do nada', 116, 72, 78, 58.0, 'Mulher de 32 anos com episódios de palpitações regulares, início e término súbitos, FC de 170-190 pelo relógio, mais frequentes nos últimos 6 meses (1 por mês, de 20 a 40 minutos), com tontura e aperto no peito discreto. Sem síncope. Um episódio terminou com manobra de Valsalva. Ao exame fora da crise: normal, sem sopros. ECG de repouso: ritmo sinusal, PR 140 ms, sem onda delta. ECO normal. Holter sem arritmia no período. HD: taquicardia por reentrada nodal (TRN) provável.', 'Orientar manobra vagal modificada e redução do café. Metoprolol 25 mg para prevenção em crises frequentes, com a opção de ablação por cateter. Discussão dos riscos e benefícios. Registro de ECG de crises por celular. Retorno em 3 meses.'),
  (803, 240, 6, '2023-07-18 21:40', 'pronto_socorro', 'Coração disparado há 50 minutos que não passa', 104, 66, 184, 57.5, 'Paciente de 32 anos, com TSV conhecida, chega com palpitações há 50 minutos, tontura e desconforto torácico leve. Manobra de Valsalva modificada sem sucesso em casa. PA 104x66, FC 184 regular, pulmões limpos, sem sinais de IC. ECG: taquicardia regular de QRS estreito, sem onda P visível, RP curto, FC 184 bpm. Sem sinais de instabilidade. HD: taquicardia supraventricular paroxística (TRN).', 'Manobra de Valsalva modificada repetida, sem sucesso. Adenosina 6 mg EV rápida com reversão para ritmo sinusal em 15 segundos, sem recorrência. ECG pós: sinusal, sem pré-excitação. Observada 2 horas e liberada. Orientada a procurar o ambulatório para ablação definitiva.'),
  (804, 240, 4, '2023-09-20 07:30', 'internacao', 'Ablação por cateter da taquicardia', 112, 68, 74, 57.8, 'Internada para estudo eletrofisiológico e ablação. Estudo confirmou dupla fisiologia nodal e TRN típica induzida com isoproterenol, ciclo de taquicardia de 330 ms. Ablação da via lenta por radiofrequência com perda de condução dessa via, sem indução após o procedimento. Intervalo AH preservado, sem BAV. Sem complicações. Alta no mesmo dia, assintomática.', 'Suspender metoprolol. Repouso relativo por 3 dias, evitar esforço físico por 1 semana. Procurar atendimento se taquicardia, febre ou dor no local da punção. Retorno em 6 meses com ECG.'),
  (805, 240, 4, '2024-03-12 16:00', 'retorno', 'Nunca mais tive a crise, queria saber se estou liberada', 114, 70, 70, 58.4, 'Seis meses após ablação, sem nenhuma crise de taquicardia. Volta a praticar corrida leve e relata menos ansiedade, pois já não tem medo de ter crise no trabalho. Mantém café com moderação. ECG: ritmo sinusal, PR 148 ms, sem pré-excitação, sem BAV. Holter de 24h normal, sem episódios de taquicardia. Ao exame, normal. Pergunta sobre risco para uma gestação futura.', 'Alta do ambulatório de arritmias, sem medicação. Liberada para atividade física sem restrição. Explicado que a gestação não é contraindicada, devendo avisar a obstetra. Retornar se palpitações ou tontura.');
