insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (240, '2024-03-12', 'controlado', 'Taquicardia por reentrada nodal tratada com ablação por radiofrequência da via lenta. Seis meses depois, sem crises, Holter e ECG normais, sem medicações. Teve alta do ambulatório de arritmias e foi liberada para atividade física sem restrições.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (241, 'Thiago Moura Falcão', 'M', '1987-08-19', 'Cabo de Santo Agostinho', 'PE', 'Analista de logística', 'Sem diagnóstico prévio de HAS. Sobrepeso, trabalha sentado 9 horas por dia, dorme 6 horas. Fuma socialmente nos fins de semana. Pai hipertenso desde os 45 anos. Bebe cerveja 2 a 3 vezes por semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (806, 241, 5, '2024-09-03 18:00', 'consulta', 'Pressão 13 por 8 na farmácia, queria saber se é preocupante', 134, 86, 76, 91.0, 'Homem de 37 anos, assintomático, buscou a UBS após aferir 132x84 e 138x88 em farmácia. IMC 29,8, circunferência abdominal 98 cm. Sem queixas cardiovasculares. Ao exame: RCR 2T BNF, sem sopros, PA 134x86 e 132x84 em duas medidas, sem hipotensão postural. MRPA de 5 dias: média 130x83. LDL 126 mg/dL, glicemia 98 mg/dL. Pré-hipertensão, sem lesão de órgão-alvo nem outros fatores de alto risco; indicada apenas MEV.', 'Sem medicação. MEV: dieta DASH, redução de sal, 150 min/semana de exercício, perder 6 kg em 4 meses, parar de fumar, reduzir álcool. Novo MRPA em 4 meses. Retorno em 4 meses.'),
  (807, 241, 5, '2025-01-14 18:20', 'retorno', 'Vim mostrar o resultado, perdi peso', 122, 78, 68, 85.4, 'Perdeu 5,6 kg em 4 meses, entrou na academia perto do trabalho e passou a levar marmita; parou de fumar com apoio do grupo da UBS. Álcool reduzido a 1 vez por semana. PA 122x78, MRPA média 120x76. Circunferência abdominal 92 cm. Sem queixas. Pergunta se "o estágio vai voltar" e se ainda precisa vir. Explicado que pré-hipertensão pode evoluir para HAS e que o acompanhamento é anual.', 'Manter MEV e metas de peso. Sem fármacos. Reavaliar PA em 6 meses; MRPA anual. Pedir lipidograma e glicemia em 1 ano.'),
  (808, 241, 5, '2025-09-02 19:00', 'teleconsulta', 'Teleconsulta de acompanhamento', 118, 74, null, 83.0, 'Teleconsulta. Mantém a academia 4x por semana, peso de 83 kg informado pela balança de casa. PA domiciliar média de 118x74 nas últimas duas semanas (aparelho de braço validado, 14 medidas). Sem sintomas, sem tabagismo, álcool moderado. Dormindo 7 horas. Refere que o pai teve que iniciar medicação aos 45 anos e que ele quer "fugir dessa história".', 'Sem medicação. Manter MEV. Consulta presencial em 12 meses com MRPA e exames. Voltar antes se PA domiciliar média > 130/80 em 1 semana ou sintomas.');
