insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (241, '2025-09-02', 'controlado', 'Pré-hipertensão em adulto jovem com história familiar, tratada apenas com mudança de estilo de vida: perdeu 8 kg, parou de fumar e reduziu o álcool. PA domiciliar média 118x74 mmHg sem medicação, em acompanhamento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (242, 'Neusa Maria Dutra Pinheiro', 'F', '1955-11-18', 'Pombal', 'PB', 'Agricultora aposentada', 'HAS há 20 anos, DM2 há 12 anos e dislipidemia. Cateterismo em 2021 em outro serviço: oclusão crônica total (CTO) da coronária direita e lesão de 70% em DA média, tratados clinicamente. Em uso de AAS, atorvastatina 40 mg, metoprolol succinato 100 mg e metformina. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (809, 242, 10, '2023-04-11 09:30', 'consulta', 'Dor no peito todo dia quando vou à roça', 138, 80, 58, 72.0, 'Paciente de 67 anos com angina CCS III há 6 meses, com dor retroesternal ao andar 100 metros, aliviada com repouso em 5 minutos. Em uso de betabloqueador em dose alta, FC 58. Ao exame: sem sopros, pulmões limpos, sem edema. ECO: FEVE 58%, hipocinesia inferior. Cintilografia: isquemia extensa de parede inferior e anterior (20% do VE). Cateterismo prévio revisto: CTO de CD com circulação colateral, DA média 70%. HD: DAC estável com angina refratária ao tratamento mínimo.', 'Associar ranolazina 500 mg de 12/12h e dinitrato de isossorbida 20 mg de 12/12h. Manter AAS, atorvastatina e metoprolol. Reavaliar após 3 meses. Considerar angioplastia da DA com avaliação funcional (FFR). Orientada procurar PS se dor em repouso.'),
  (810, 242, 10, '2023-07-18 09:00', 'retorno', 'Continuo com dor, mas um pouco menos', 132, 78, 56, 71.0, 'Angina CCS II-III, com melhora parcial. Crises 3 vezes por semana, antes diárias. Sem cefaleia importante com o nitrato. Sem edema, sem síncope. FC 56 em repouso, PA 132x78. Discutido caso com paciente e filha: opção de angioplastia da DA com FFR e tentativa de recanalização da CTO de CD. Paciente aceita, mas "só se for tudo no mesmo dia", pois mora distante e viaja 3 horas de ônibus.', 'Manter esquema clínico. Agendar internação para estudo funcional (FFR) e angioplastia de DA com tentativa de recanalização da CTO de CD em seguida. Exames pré-procedimento e pré-hidratação. Retorno ao hospital em outubro.'),
  (811, 242, 10, '2023-10-24 07:30', 'internacao', 'Angioplastia programada', 134, 76, 60, 71.4, 'FFR da DA média = 0,72 (significativa). Realizada ATC com stent farmacológico 3,0 x 20 mm em DA, sem complicações. Em seguida, tentativa de recanalização anterógrada da CTO de CD (calcificada, extensão 30 mm, cotovelo proximal ambíguo): três tentativas com fios de alta carga, sem sucesso em transpor a oclusão. Procedimento encerrado após 2h40 e 220 mL de contraste, sem complicações vasculares. Alta no dia seguinte.', 'Clopidogrel 75 mg + AAS por 6 meses. Hidratação oral, controle de creatinina em 48h. Manter ranolazina e betabloqueador. Reavaliar a angina em 3 meses. Se persistir, encaminhar para centro de referência em recanalização de CTO.'),
  (812, 242, 10, '2024-02-20 09:40', 'retorno', 'A dor melhorou mas ainda volta quando subo ladeira', 128, 74, 58, 70.8, '4 meses após ATC da DA. Melhora importante: angina CCS II, 1 episódio por semana ao subir ladeira. Teste ergométrico: 6 METs, isquemia em parede inferior ao fim do estágio, sem arritmias. Sem estertores, sem edema. Ainda com território da CD sob isquemia por CTO sem revascularização. LDL 58. Paciente quer "tentar de novo" com equipe que faça esse tipo de procedimento complexo.', 'Encaminhada ao centro de referência em recanalização de CTO (hospital terciário), com relatório e mídia do cateterismo. Manter medicações clínicas e dupla antiagregação até avaliação. Alta do ambulatório com retorno se piora da angina.');
