insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (242, '2024-03-05', 'transferido', 'Angina estável com lesão de DA tratada com stent guiado por FFR e oclusão crônica total de coronária direita sem sucesso à recanalização. Angina melhorou, mas persistem sintomas ao esforço; foi encaminhada a centro terciário de referência em CTO e deixou o seguimento do serviço.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (243, 'Cláudia Regina Bandeira Muniz', 'F', '1971-10-08', 'João Pessoa', 'PB', 'Advogada', 'Câncer de mama HER2-positivo diagnosticado em 2022, em quimioterapia com doxorrubicina e ciclofosfamida (4 ciclos concluídos), em seguida paclitaxel e trastuzumabe. HAS leve em uso de losartana. Sem doença cardíaca prévia. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (813, 243, 11, '2022-08-02 14:00', 'consulta', 'Oncologista pediu avaliação do coração, o eco caiu', 122, 76, 92, 66.0, 'Paciente de 50 anos em tratamento de câncer de mama HER2+, após 4 ciclos de antraciclina e 3 de trastuzumabe. Assintomática do ponto de vista cardíaco, apenas cansaço atribuído à quimioterapia. ECO de rotina: FEVE 44% (basal 63%), strain longitudinal global -13% (basal -20%), sem derrame. NT-proBNP 410, troponina US 28 ng/L (levemente elevada). Ao exame: sem estase jugular, pulmões limpos, sem edema. HD: cardiotoxicidade por antraciclina e trastuzumabe, FEVE 44%.', 'Discutido com a oncologia. Suspender temporariamente o trastuzumabe. Suspender losartana e iniciar enalapril 5 mg 12/12h e carvedilol 3,125 mg 12/12h para cardioproteção, com titulação lenta. ECO em 4 semanas. Atividade física leve. Retorno em 4 semanas.'),
  (814, 243, 11, '2022-10-18 14:30', 'retorno', 'Posso voltar para o trastuzumabe?', 116, 70, 70, 65.4, 'Em uso de enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h, tolera bem. Sem dispneia, sem edema. PA 116x70, FC 70. ECO: FEVE 52%, strain global -17,5%. NT-proBNP 140, troponina US 10 ng/L. Oncologia ansiosa para retomar o trastuzumabe. Paciente temerosa de "prejudicar o coração", mas a prioridade é completar o tratamento do câncer. Discutido benefício maior do que o risco com monitorização estreita.', 'Liberada para retomar trastuzumabe com ECO a cada 3 meses e troponina antes de cada ciclo. Manter enalapril e carvedilol. Procurar atendimento se dispneia, edema ou palpitações. Retorno em 3 meses.'),
  (815, 243, 11, '2023-04-11 14:00', 'retorno', 'Terminei o trastuzumabe, vim fazer o balanço do coração', 112, 68, 68, 64.0, 'Completou 1 ano de trastuzumabe sem novas quedas de função: ECO em janeiro com FEVE 54% e hoje 56%, strain -19%. Sem sintomas cardíacos, caminha 40 minutos 5x/semana. PA 112x68, FC 68. NT-proBNP normal. Radioterapia concluída em novembro, sem relatos de dor torácica. Alegre por ter acabado o tratamento oncológico e tem receio de que o coração "fique fraco para sempre".', 'Manter enalapril 10 mg 12/12h e carvedilol 6,25 mg por pelo menos 12 meses mais, com reavaliação ecocardiográfica a cada 6 meses. Controle de lipídios, PA e atividade física. Retorno em 6 meses.');
