insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (243, '2023-04-11', 'melhorou', 'Cardiotoxicidade por antraciclina e trastuzumabe com queda da FEVE para 44%, recuperada para 56% com enalapril e carvedilol, o que permitiu retomar e concluir o trastuzumabe. Assintomática, mantém cardioproteção e ecocardiograma semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (244, 'Altamiro Bezerra da Mota', 'M', '1936-07-12', 'Caicó', 'RN', 'Agricultor aposentado', 'FA permanente, ICFEp e HAS há 40 anos. Insuficiência renal leve (creatinina 1,5). Viúvo, mora com a filha mais nova. Queda de bicicleta no ano passado, sem sequelas. Usa bengala de forma irregular. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (816, 244, 4, '2024-02-06 10:00', 'consulta', 'Vim ver se continuo o remédio do sangue, tenho medo de cair', 134, 72, 70, 58.0, 'Idoso de 87 anos com FA permanente, CHA2DS2-VASc 4 e HAS-BLED 3 (idade, HAS, função renal). Em uso de apixabana 5 mg 12/12h por 3 anos sem sangramentos, mas com peso 58 kg, idade >= 80 e creatinina 1,5, o que implica redução de dose. Marcha lenta, quedas ocasionais, duas no último ano. Ao exame: PA 134x72, FC 70 irregular, edema 1+. Discutido risco/benefício com o paciente e a filha, que preferem manter anticoagulação.', 'Reduzir apixabana para 2,5 mg 12/12h (critérios: idade >= 80, peso <= 60 kg e creatinina >= 1,5). Manter bisoprolol 2,5 mg e furosemida 20 mg. Fisioterapia para prevenir quedas, retirar tapetes, bengala sempre. Retorno em 4 meses.'),
  (817, 244, 4, '2024-06-18 10:30', 'retorno', 'Estou bem, só ando mais devagar', 128, 70, 66, 57.2, 'Sem sangramentos nem quedas desde o último retorno. Faz fisioterapia com a filha, caminha devagar no quintal com a bengala. Sem dispneia nem ortopneia, edema discreto. PA 128x70, FC 66. Hemoglobina 12,6 e creatinina 1,5, estáveis. Em conversa, o paciente afirma que a prioridade é "passar o tempo que me resta sem ter derrame", o que reforça a escolha de anticoagulação.', 'Manter apixabana 2,5 mg 12/12h, bisoprolol e furosemida. Revisar o ambiente em casa. Alerta para sinais de sangramento e para avaliação imediata se queda com batida na cabeça. Retorno em 4 meses.'),
  (818, 244, 6, '2024-09-17 14:20', 'pronto_socorro', 'Caiu no quintal e bateu a cabeça, está sonolento', 168, 88, 82, 57.0, 'Pcte de 88 anos, FA em uso de apixabana, caiu no quintal batendo a região parietal direita há 2h, sem perda de consciência, mas com cefaleia, vômito e sonolência progressiva. Glasgow 13 (O3 V4 M6), pupilas isocóricas, hematoma e escoriação parietal. PA 168x88, FC 82 irregular. TC de crânio: hematoma subdural agudo à direita de 14 mm, com desvio de linha média de 7 mm. Última dose de apixabana ontem à noite. INR 1,3. HD: hematoma subdural agudo associado a anticoagulante.', 'Suspender apixabana. Reversão com andexanet alfa ou complexo protrombínico 50 UI/kg (disponível no serviço), cabeceira a 30 graus, controle de PA < 160 mmHg, avaliação da neurocirurgia. Internação em UTI. Alinhamento com a família sobre prognóstico reservado pela idade.'),
  (819, 244, 14, '2024-09-18 08:00', 'internacao', 'Rebaixamento do nível de consciência na UTI', 176, 92, 58, 57.0, 'Após reversão do anticoagulante, piorou o nível de consciência para Glasgow 8 (O2 V2 M4), com anisocoria à direita e bradicardia, sinais de herniação. TC de controle: aumento do hematoma subdural para 22 mm, desvio de 12 mm, apagamento de cisternas. Avaliação neurocirúrgica: cirurgia de drenagem de alto risco e com baixa chance de benefício funcional (idade 88, grande hematoma). Reunião com a família, que optou por não realizar craniotomia, mantendo medidas de conforto.', 'Cuidados paliativos e medidas de conforto: sedação e analgesia se necessário, cabeceira a 30 graus, não intubar. Sem reintrodução do anticoagulante. Acompanhamento da família e apoio espiritual. Registro de decisão compartilhada no prontuário.');
