insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (244, '2024-09-22', 'obito', 'Idoso de 88 anos com FA e quedas recorrentes, em uso de apixabana em dose ajustada, que sofreu queda com hematoma subdural agudo. Evoluiu com herniação cerebral, sem cirurgia por decisão compartilhada com a família, e faleceu em 22/09/2024 em cuidados de conforto na UTI.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (245, 'Francineide Lima Araújo', 'F', '1983-05-14', 'Sertânia', 'PE', 'Professora de ensino fundamental', 'Febre reumática na infância (aos 9 anos), com uso irregular de penicilina benzatina por 2 anos. Sem outras comorbidades. Dois partos normais. Nunca fumou. Mora em zona rural, a 90 km de Caruaru.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (820, 245, 2, '2024-02-27 09:30', 'consulta', 'Cansaço, falta de ar ao subir escada e tosse com um pouco de sangue', 108, 68, 108, 58.0, 'Mulher de 40 anos com dispneia progressiva há 8 meses (CF III), ortopneia, palpitações irregulares e um episódio de hemoptise leve. História de febre reumática. Ao exame: FC 108 irregular, estalido de abertura e ruflar diastólico em foco mitral, B1 hiperfonética, estertores finos nas bases. ECG: fibrilação atrial, AE sobrecarregado. ECO: estenose mitral reumática, área valvar 1,0 cm², gradiente médio 12 mmHg, AE 54 mm, PSAP 52 mmHg, sem trombo, escore de Wilkins 7. HD: estenose mitral moderada a grave sintomática com FA.', 'Iniciar varfarina (INR 2,0-3,0), porque DOAC não é indicado em estenose mitral moderada a grave. Metoprolol succinato 50 mg para controle de FC. Furosemida 20 mg. Penicilina benzatina 1.200.000 UI IM a cada 21 dias para profilaxia secundária. Indicada valvoplastia mitral percutânea por balão. Retorno em 3 semanas.'),
  (821, 245, 10, '2024-04-16 07:30', 'internacao', 'Valvoplastia mitral percutânea', 112, 70, 84, 57.6, 'INR 2,4 na admissão. ETE pré-procedimento sem trombo no AE ou apêndice, anatomia favorável (Wilkins 7, sem calcificação comissural importante). Valvoplastia mitral com balão de Inoue por via transeptal, balão de 26 mm, com aumento da área valvar para 1,9 cm² e queda do gradiente médio de 12 para 4 mmHg. Insuficiência mitral discreta pós-procedimento (grau 1). Sem derrame pericárdico. Alta em 48h assintomática.', 'Manter varfarina (FA persistente) e metoprolol. Suspender furosemida. Manter penicilina benzatina. Controle do INR semanal por 1 mês, depois mensal. Retorno em 3 meses com ECO. Orientações sobre planejamento familiar: gestação só com acompanhamento especializado.'),
  (822, 245, 2, '2024-07-23 09:00', 'retorno', 'Subo as escadas da escola sem cansar', 112, 70, 72, 59.0, 'Três meses após valvoplastia. Assintomática (CF I), voltou a dar aula e a andar em feira livre. Ritmo ainda FA, FC 72 com metoprolol. INR 2,6, com ajuste mensal; reclama apenas de comer verduras com cuidado. Sem sangramentos nem fenômenos embólicos. ECO: área valvar 1,9 cm², gradiente médio 4 mmHg, IM discreta, PSAP 32 mmHg. Penicilina benzatina em dia a cada 21 dias na UBS da cidade.', 'Manter varfarina, metoprolol e penicilina benzatina. Discutir cardioversão ou controle de ritmo em 6 meses. Manter INR mensal na UBS. ECO anual. Retorno em 6 meses; planejamento de gestação com cardio-obstetra.');
