insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (245, '2024-07-23', 'melhorou', 'Estenose mitral reumática moderada a grave com FA, tratada com valvoplastia percutânea por balão (área de 1,0 para 1,9 cm²). Assintomática, voltou ao trabalho, em uso de varfarina com INR 2,6 e profilaxia secundária de febre reumática. Segue em ECO anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (246, 'Domingos Sávio Alves Pimenta', 'M', '1965-02-17', 'Bambuí', 'MG', 'Pedreiro', 'Doença de Chagas crônica com cardiopatia (diagnóstico há 10 anos). BRD + BDAS, IC com FEVE reduzida, extrassístoles frequentes. Usa enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h. Etilista social. Mora em casa de alvenaria, a esposa é diabética.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (823, 246, 11, '2023-03-14 10:00', 'consulta', 'Cansaço para carregar saco de cimento', 112, 70, 64, 72.0, 'Pcte de 58 anos, Chagas crônico com ICFEr CF II, dispneia aos médios esforços. Sem edema, sem ortopneia, sem síncope. Ao exame: B3 discreto, pulmões limpos, PA 112x70. ECG: BRD + BDAS, extrassístoles ventriculares polimórficas. ECO: FEVE 36%, aneurisma apical de VE de 3 cm sem trombo, DDVE 62 mm. Holter com TVNS curtas. Sem indicação de tratamento etiológico (benznidazol) pela cardiopatia já estabelecida.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após pausa de 36h. Aumentar carvedilol para 12,5 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Considerar anticoagulação se trombo ao ECO. Reduzir álcool. Retorno em 8 semanas.'),
  (824, 246, 6, '2023-08-22 07:30', 'pronto_socorro', 'Acordou com o lado esquerdo do corpo fraco', 156, 92, 78, 71.0, 'Pcte de 58 anos, Chagas com aneurisma apical, acorda às 06h30 com hemiparesia esquerda e desvio de rima, com horário de início desconhecido (visto bem às 22h). NIHSS 7. PA 156x92, FC 78. Ritmo sinusal ao monitor. TC de crânio sem hemorragia, ASPECTS 9; angio-TC com oclusão distal de M2 direita. Fora da janela para trombólise, sem critérios para trombectomia (oclusão distal, déficit leve a moderado). HD: AVC isquêmico cardioembólico, provável trombo em aneurisma apical chagásico.', 'AAS 300 mg inicial, estatina de alta potência, internação em unidade de AVC, manter PA em permissiva até 220x120. Solicitar ECO transesofágico/ressonância cardíaca para avaliar trombo e iniciar anticoagulação em 48 a 72 horas, conforme extensão do infarto.'),
  (825, 246, 13, '2023-08-24 10:00', 'internacao', 'Acompanhamento na unidade de AVC', 148, 86, 70, 71.0, 'Hemiparesia esquerda com melhora (NIHSS 4). Ressonância cerebral: infarto subcortical e cortical em território de M2 direita, sem transformação hemorrágica. Ressonância cardíaca: aneurisma apical de 3,2 cm com trombo laminar de 18 mm, realce tardio extenso. FEVE 32%. Confirmada fonte cardioembólica. Sem sinais de FA. Liberado para anticoagulação com heparina e transição para varfarina, pois DOAC não é rotina em trombo ventricular chagásico.', 'Enoxaparina 1 mg/kg 12/12h sobreposta à varfarina até INR 2,0-3,0. Suspender AAS. Fisioterapia e fonoaudiologia. Educação sobre INR semanal. Encaminhar à arritmologia para avaliação de CDI (FEVE 32% e TVNS). Alta em 7 dias.'),
  (826, 246, 11, '2024-01-16 10:30', 'retorno', 'A mão esquerda ainda é fraca e o INR não para quieto', 118, 72, 68, 69.0, 'Retorna com hemiparesia esquerda residual leve (mão fraca) e dispneia agravada (CF III). INR instável: 1,6, 4,2, 2,1 nos últimos 3 meses, pois o posto fica a 40 km e falha no deslocamento; também mudou de dieta ao tentar emagrecer. Sem sangramentos. ECO: FEVE 30%, trombo em organização de 12 mm no aneurisma. Perdeu 3 kg de peso seco. Não conseguiu voltar ao trabalho de pedreiro, renda reduzida. Sem CDI, pois aguarda vaga na arritmologia.', 'Manter varfarina com monitorização mais frequente; combinar INR com o agente de saúde da cidade. Ajuste de dose para 7,5 mg em dias alternados. Sacubitril/valsartana 49/51 mg se PA permitir. Pedido de benefício assistencial. Priorizar avaliação para CDI. Retorno em 6 semanas.');
