insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (249, '2024-06-18', 'melhorou', 'Endocardite subaguda por Streptococcus gordonii em valva aórtica bicúspide, após exodontia sem profilaxia. Evoluiu com insuficiência aórtica importante e foi tratado com antibiótico e troca valvar por bioprótese. Curado, sem infecção residual, com ECO normal e retorno ao trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (250, 'Ilma Rodrigues de Albuquerque Maranhão', 'F', '1957-06-03', 'Goiana', 'PE', 'Aposentada (ex-comerciária)', 'HAS leve em uso de losartana 50 mg/dia. Hipotireoidismo tratado com levotiroxina. Sem DM, sem tabagismo. Viúva há 2 dias: o marido faleceu de câncer de pâncreas. Nunca teve dor no peito antes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (839, 250, 6, '2023-11-08 11:15', 'pronto_socorro', 'Dor forte no peito logo depois do enterro do meu marido', 148, 92, 94, 64.0, 'Pcte de 66 anos, HAS, dor precordial em aperto intensa há 3h, iniciada após o enterro do marido, com dispneia e sudorese. Ao exame: ansiosa, chorosa, PA 148x92, FC 94, pulmões com estertores finos em bases, sem sopros. ECG: supradesnível de ST de 2 mm em V2-V5 e T negativa precoce. Troponina US 1.840 ng/L (pico), BNP 640. ECO à beira-leito: balonamento apical do VE com hipercinesia basal, FEVE 35%. HD: IAMCSST anterior x síndrome de takotsubo; indicado cateterismo.', 'AAS 300 mg, clopidogrel 300 mg, heparina e transferência para hemodinâmica de urgência. Dieta zero. Cuidado com nitrato e betabloqueador até a definição. Atenção psicológica e presença do filho durante a espera.'),
  (840, 250, 10, '2023-11-09 09:00', 'internacao', 'Resultado do cateterismo e conduta', 124, 78, 80, 64.0, 'Cateterismo de urgência: coronárias angiograficamente normais, sem lesões obstrutivas ou trombo. Ventriculografia esquerda com acinesia apical com hipercinesia basal (aspecto de "balonamento"), FEVE 38%, sem gradiente intraventricular. Diagnóstico de síndrome de takotsubo (cardiomiopatia por estresse), provocada por estresse emocional intenso. Sem arritmias ventriculares na monitorização. Estável, dor resolvida.', 'Suspender dupla antiagregação e manter AAS 100 mg. Iniciar enalapril 5 mg 12/12h e carvedilol 3,125 mg 12/12h (suspender losartana). Suporte psicológico e antidepressivo se necessário. Anticoagulação profilática se trombo apical. ECO em 7 dias e alta em 4 dias.'),
  (841, 250, 1, '2023-12-12 10:30', 'retorno', 'Sem dor, mas muito triste e sem dormir', 118, 72, 66, 62.4, 'Um mês após o evento. Sem dor, sem dispneia. ECO de controle: FEVE 52%, discreta hipocinesia apical residual, sem trombo. PA 118x72, FC 66. Emocionalmente abalada pela perda: insônia, choro frequente, perda de 1,6 kg, apetite reduzido. Avaliada pela psicologia do serviço, em acompanhamento semanal, sem critérios para depressão maior até o momento. Filho acompanha e está morando com ela temporariamente.', 'Manter enalapril 5 mg 12/12h e carvedilol. Manter acompanhamento psicológico, rede de apoio, retomar atividade física leve. ECO em 3 meses para documentar normalização. Retorno em 3 meses; avisar se dor ou dispneia.'),
  (842, 250, 1, '2024-03-05 10:00', 'retorno', 'Estou melhor, vim mostrar o eco', 122, 74, 64, 63.6, 'Quatro meses após takotsubo. Retomou as caminhadas, frequenta grupo de luto da paróquia e a psicoterapia quinzenal. Dorme melhor. Sem dor torácica nem dispneia. PA 122x74, FC 64. ECO: FEVE 60%, contração segmentar normal, sem hipocinesia apical. Completa recuperação funcional, como esperado. Sem recorrência. Explicado que há risco pequeno de recorrência com novo estresse intenso, portanto manter rede de apoio.', 'Suspender carvedilol e AAS. Manter enalapril 5 mg 12/12h para HAS. Seguimento anual com PA e ECO. Procurar PS se dor no peito. Manter psicoterapia pelo tempo que for útil.');
