insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (250, '2024-03-05', 'melhorou', 'Síndrome de takotsubo desencadeada por luto, com supra de ST e balonamento apical, coronárias normais e FEVE de 35%. Normalização completa do ECO em 4 meses (FEVE 60%), suspensão do carvedilol e do AAS, e acompanhamento psicológico em curso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (251, 'Francisco Evandro Bezerra Cavalcante', 'M', '1971-05-14', 'Sobral', 'CE', 'Motorista de ônibus intermunicipal', 'Sobrepeso há anos, faz as refeições em paradas de estrada (muito frito e embutido). Sedentário, bebe cerveja nos fins de semana. Pai hipertenso, faleceu de AVC aos 62 anos. Nunca mediu a pressão de forma regular.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (843, 251, 1, '2022-04-12 08:30', 'consulta', 'Pressão alta no exame da empresa', 158, 98, 80, 96.4, 'Paciente de 50 anos, assintomático, encaminhado após exame periódico da empresa de ônibus com PA 160x100. Nega cefaleia, dor torácica ou dispneia. Refere dieta rica em sal e frituras pela rotina de viagens, cerveja aos sábados. IMC 31,5, circunferência abdominal 108 cm. Exame cardiovascular sem alterações, sem sopros, pulsos simétricos. PA medida 3 vezes em duas posições, média 158x98 mmHg. Sem lesão de órgão-alvo ao ECG.', 'Confirmar diagnóstico com MRPA por 5 dias. Iniciar MEV: redução de sal, trocar marmita de parada por marmita própria, caminhada 30 min 5x/semana, reduzir álcool. Meta de peso -5 kg. Retorno em 5 semanas com o diário da MRPA.'),
  (844, 251, 1, '2022-05-17 09:10', 'retorno', 'Trouxe o caderninho da pressão', 154, 96, 78, 94.8, 'Retorna com MRPA de 5 dias: média 152x95 mmHg, sem valores abaixo de 140x90. Perdeu 1,6 kg, diminuiu o sal mas "na estrada é difícil". Sem sintomas. HAS estágio 1 confirmada, risco cardiovascular moderado pelo conjunto de fatores. Discutido que a profissão exige PA controlada e que o tratamento medicamentoso agora é indicado por não ter atingido a meta apenas com MEV.', 'Iniciar losartana + hidroclorotiazida 50/12,5 mg em comprimido único pela manhã. Manter MEV. Solicito sódio, potássio e creatinina em 4 semanas. Retorno em 90 dias com MRPA.'),
  (845, 251, 1, '2022-09-20 08:50', 'retorno', 'Veio mostrar a pressão', 126, 78, 72, 90.2, 'Sem queixas, sem tosse, sem cãibras. Peso caiu 6,2 kg desde a primeira consulta, anda 40 min no fim da tarde quando está em casa e leva marmita nas viagens mais longas. MRPA recente média 124x77. Exames de controle sem alteração de eletrólitos. PA na meta (< 130/80).', 'Manter losartana/hidroclorotiazida. Reforçar manutenção do peso e do sal reduzido. Repetir creatinina, potássio, glicemia e perfil lipídico em 6 meses. Retorno em 6 meses.');
