insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (251, '2023-03-10', 'controlado', 'HAS estágio 1 diagnosticada aos 50 anos, controlada em uso de comprimido único e MEV. Perdeu cerca de 8 kg em um ano, PA de consultório e MRPA dentro da meta, mantém a carteira de motorista profissional sem restrições.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (252, 'Maria das Dores Nunes Carvalho', 'F', '1949-11-03', 'Teresina', 'PI', 'Aposentada (ex-lavradeira)', 'HAS há 25 anos em uso de enalapril, anlodipino e hidroclorotiazida. Osteoporose em tratamento. Mora com a filha, cozinha e cuida do quintal. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (846, 252, 1, '2023-02-08 10:20', 'consulta', 'Caí no quintal e fico tonta quando levanto', 148, 84, 72, 61.0, 'Paciente de 73 anos, trazida pela filha após queda da própria altura há 10 dias, sem fratura (raio X de punho normal). Refere tontura ao levantar da cama e da cadeira, "a vista escurece". PA sentada 148x84; em pé após 3 min 118x70 com tontura, queda de 30 mmHg na sistólica, sem aumento da FC. Em uso de enalapril 20 mg 12/12h, anlodipino 10 mg e hidroclorotiazida 25 mg. Bebe pouca água. HD: hipotensão ortostática associada a anti-hipertensivos e desidratação.', 'Suspender hidroclorotiazida. Reduzir anlodipino para 5 mg. Manter enalapril. Orientada a aumentar a ingestão de água, levantar devagar e dormir com a cabeceira elevada. Solicito exames e retorno em 6 semanas com MRPA.'),
  (847, 252, 1, '2023-03-22 10:00', 'retorno', 'Tontura melhorou', 136, 78, 70, 61.8, 'Sem novas quedas. Tontura quase some, só uma vez ao levantar rápido da cama. Bebendo cerca de 1,5 L de água ao dia, sódio sérico subiu para 137. PA sentada 136x78, em pé 130x76, sem queda postural relevante. MRPA média 134x78. Mantém bom humor, voltou a regar as plantas sem ajuda.', 'Manter o esquema atual sem a tiazida. Evitar metas rígidas de PA em idosa com quedas: aceitar até 140x90 por ora. Encaminhar para fisioterapia de equilíbrio. Retorno em 11 meses ou antes se tontura.'),
  (848, 252, 1, '2024-02-27 10:30', 'retorno', 'Vim para a revisão do ano', 138, 80, 68, 62.3, 'Um ano sem quedas. Fez fisioterapia por 3 meses. PA sentada 138x80 e em pé 134x78, sem sintomas ortostáticos. Mantém hidratação. Exames estáveis, potássio normal, função renal igual. Filha confirma que ela toma todos os remédios com caixinha organizadora semanal.', 'Manter enalapril e anlodipino 5 mg. Sem indicação de retomar diurético. Repetir exames em 1 ano. Manter acompanhamento da osteoporose com a clínica médica.');
