insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (252, '2024-02-27', 'estavel', 'Idosa com HAS e hipotensão ortostática por excesso de anti-hipertensivos e pouca ingestão de água. Após retirar o diurético e reduzir o anlodipino, não teve mais quedas, mantém PA em torno de 138x80 e segue em acompanhamento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (253, 'Raimundo Nonato Pereira Sousa', 'M', '1962-02-20', 'Caxias', 'MA', 'Pedreiro', 'HAS há 9 anos, encaminhado como hipertensão resistente em uso de três drogas. Tabagista de 15 cigarros por dia. Trabalho informal, renda variável. Pai com HAS.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (849, 253, 2, '2021-08-17 14:20', 'consulta', 'Tomo três remédios e a pressão não baixa', 178, 108, 84, 78.0, 'Paciente de 59 anos, encaminhado da UBS por HAS resistente: receitados losartana 50 mg 12/12h, anlodipino 10 mg e hidroclorotiazida 25 mg. Ao investigar, relata que "compra quando sobra dinheiro", fica semanas sem o anlodipino e a losartana e toma a tiazida só nos dias de pressão alta. Esquece doses ao sair cedo para a obra. PA 178x108 em duas medidas, técnica adequada, manguito correto. Sem sinais de lesão de órgão-alvo ao exame. HD: pseudorresistência por má adesão e custo.', 'Não escalonar a medicação. Orientado a retirar os três remédios na farmácia da UBS/Farmácia Popular, caixinha semanal e alarme no celular. Encaminho para assistente social do ambulatório. Pedido de exames de rotina. Retorno em 6 semanas com as caixas dos remédios.'),
  (850, 253, 2, '2021-09-28 14:00', 'retorno', 'Estou tomando direitinho', 132, 82, 74, 77.4, 'Conseguiu retirar os três medicamentos gratuitamente e usa organizador semanal. Contagem de comprimidos confere com uso regular. PA 132x82 sem nenhum ajuste de dose, o que confirma pseudorresistência. Reduziu o cigarro para 5 por dia. Sem cefaleia ou tontura, sem cansaço na obra, dormindo bem.', 'Manter exatamente o mesmo esquema. Reforçado o fim do tabagismo, encaminhado ao grupo de cessação da UBS. Solicitado MRPA. Retorno em 8 meses.'),
  (851, 253, 2, '2022-06-14 15:10', 'retorno', 'Trouxe o papel da pressão de casa', 126, 80, 70, 76.9, 'MRPA com média 128x78. Não fuma há 3 meses, "foi o médico da UBS que me convenceu". Mantém retirada mensal dos remédios sem falhas. Sem edema de tornozelo, sem tosse. Feito acordo com a UBS para que ele retire os remédios por 90 dias de cada vez.', 'Considerar redução de esquema em 6 meses se PA seguir abaixo de 125x75, começando pela hidroclorotiazida. Manter por ora. Retorno em 6 meses.');
