insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (253, '2022-06-14', 'controlado', 'Pseudorresistência: a PA não respondia por falta de acesso e uso irregular dos medicamentos. Com a retirada gratuita e o organizador semanal, normalizou sem mudar doses. Parou de fumar e segue controlado na meta.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (254, 'Antônio Carlos Medeiros Pinheiro', 'M', '1974-09-09', 'Fortaleza', 'CE', 'Motorista de caminhão', 'Obesidade grau II, HAS há 4 anos com controle ruim em uso de losartana 100 mg e anlodipino 10 mg. Ronco alto referido pela esposa. Álcool socialmente. Dorme em cabine de caminhão em viagens longas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (852, 254, 1, '2021-05-10 08:00', 'consulta', 'Acordo cansado e quase dormi no volante', 164, 104, 78, 118.6, 'Homem de 46 anos com PA mal controlada apesar de dois fármacos. Esposa relata ronco alto e "pausas na respiração" durante o sono. Sonolência diurna importante, Epworth 17, cefaleia matinal, quase acidente por cochilo. Pescoço 46 cm, IMC 37,6, Mallampati III. Ausculta cardíaca normal. Suspeita de apneia obstrutiva do sono como causa secundária de HAS.', 'Solicitar polissonografia de noite inteira. Manter losartana 100 mg e anlodipino 10 mg. Orientado a não dirigir caminhão enquanto estiver sonolento. Rastrear causas endócrinas após polissonografia se persistir PA elevada. Retorno com o exame.'),
  (853, 254, 1, '2021-07-19 08:20', 'retorno', 'Trouxe o exame do sono', 160, 100, 76, 118.0, 'Polissonografia: IAH 38 eventos/hora (apneia grave), saturação mínima 76%, 22% do tempo com SpO2 < 90%. Pressão sempre mais alta pela manhã. Diagnóstico de HAS secundária à AOS grave. Discutido que tratar o sono é parte do tratamento da pressão e que a perda de peso é essencial.', 'Iniciar CPAP com titulação automática (APAP 8 a 14 cmH2O) via convênio com a empresa. Encaminhar para nutrição. Manter anti-hipertensivos. Reavaliar PA em 4 meses com uso do CPAP.'),
  (854, 254, 1, '2021-11-22 08:10', 'retorno', 'Dormindo melhor com a máscara', 138, 86, 70, 111.4, 'Usa o CPAP em média 6 h por noite (relatório do aparelho: IAH residual 4). Sem sonolência, Epworth 6. Perdeu 6,6 kg. Cefaleia matinal desapareceu. PA caiu 22 mmHg na sistólica sem mudar medicamentos. Voltou a dirigir normalmente e a esposa diz que o ronco praticamente sumiu.', 'Manter CPAP todas as noites, inclusive nas viagens (levar o aparelho). Continuar dieta com nutricionista. Manter medicamentos. Retorno em 8 meses.'),
  (855, 254, 1, '2022-08-08 08:40', 'retorno', 'Vim ver se posso diminuir o remédio', 124, 76, 66, 104.2, 'Peso 104,2 kg (-14 kg desde o início). Mantém o CPAP com uso de 6,5 h por noite. MRPA média 122x75. Sem edema ou sintomas. Boa evolução: PA na meta com perda de peso e tratamento da AOS, o que permite desescalonar a medicação.', 'Reduzir anlodipino para 5 mg. Manter losartana 100 mg. Se MRPA permanecer < 130/80 em 8 semanas, manter esquema. Retorno em 6 meses.');
