insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (254, '2022-08-08', 'melhorou', 'HAS secundária a apneia obstrutiva grave. Com CPAP e perda de 14 kg, a PA passou de 164x104 para 124x76 e foi possível reduzir o anlodipino. Sem sonolência ao volante, mantém seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (255, 'Luiz Gonzaga Alencar Rocha', 'M', '1958-07-30', 'Crateús', 'CE', 'Comerciante (mercadinho de bairro)', 'Tabagista de 40 maços-ano, HAS e dislipidemia sem tratamento regular. Pai faleceu de infarto aos 58 anos. Trabalha 12 horas por dia no balcão, sedentário.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (856, 255, 6, '2023-06-04 03:50', 'pronto_socorro', 'Dor forte no peito há 2 horas', 150, 92, 88, 84.0, 'Dor retroesternal em aperto, irradiada para braço esquerdo e mandíbula, com sudorese fria e náuseas, iniciada às 01h50. Pcte pálido, REG, SpO2 95% AA. ECG: supra de ST em DII, DIII e aVF com infra especular em DI e aVL. Pulmões limpos, sem sinais de congestão. Troponina elevada. HD: IAMCSST de parede inferior, Killip I.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina e atorvastatina 80 mg. Acionada hemodinâmica de plantão para angioplastia primária. Analgesia com morfina fracionada. Família informada.'),
  (857, 255, 10, '2023-06-04 05:30', 'internacao', 'Angioplastia primária', 134, 80, 74, 84.0, 'Porta-balão em 62 minutos. Coronariografia por via radial direita: oclusão aguda da coronária direita proximal, DA com lesão de 40% e Cx sem lesões significativas. Realizada angioplastia com implante de stent farmacológico em CD com fluxo TIMI 3 final. Sem complicações do acesso. Dor resolvida. Admitido em unidade coronariana, estável hemodinamicamente. ECO à beira leito com hipocinesia inferior e FEVE estimada de 52%.', 'Dupla antiagregação (AAS + ticagrelor) por 12 meses. Iniciar bisoprolol e ramipril em dose baixa, manter estatina de alta potência. Cessação do tabagismo com reposição de nicotina. Alta prevista em 48 horas se estável.'),
  (858, 255, 1, '2023-07-18 09:00', 'retorno', 'Vim para a revisão depois do infarto', 124, 74, 58, 80.2, 'Seis semanas pós-IAM. Sem angina, sem dispneia. Parou de fumar desde o dia do infarto, "o susto foi grande". Contratou um funcionário para o balcão e começou a caminhar. Em uso de AAS, ticagrelor, bisoprolol, ramipril e atorvastatina sem efeitos adversos, apenas dispneia leve com ticagrelor nos primeiros dias, já resolvida. ECO de controle com FEVE 54%. FC 58 em uso de bisoprolol.', 'Manter dupla antiagregação até junho/2024. Iniciar reabilitação cardíaca supervisionada 3x/semana. Ajustar bisoprolol para 5 mg se FC permitir (mantido 2,5 mg por FC 58). Lipidograma em 8 semanas, meta de LDL < 50. Retorno em 4 meses.');
