insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (255, '2023-12-12', 'melhorou', 'IAM inferior tratado com angioplastia primária em tempo ideal. Seis meses depois está sem angina, ex-fumante, em reabilitação cardíaca, FEVE preservada e PA na meta. Segue com dupla antiagregação até completar 12 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (256, 'Tereza Cristina Yamamoto Ferreira', 'F', '1961-03-12', 'São Paulo', 'SP', 'Professora aposentada', 'DM2 há 10 anos em uso de metformina, HAS e dislipidemia. Ex-tabagista (10 maços-ano, parou há 20 anos). Mãe com infarto aos 66 anos. Caminha irregularmente.', 'Alergia a iodo (urticária leve com contraste em tomografia antiga)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (859, 256, 1, '2022-02-15 14:30', 'consulta', 'Dor no peito quando subo ladeira', 144, 86, 82, 71.5, 'Paciente de 60 anos com 2 meses de dor retroesternal em aperto, ao subir ladeiras ou acelerar o passo, que melhora com repouso em 3 a 5 minutos. Angina típica, CCS II. Sem dor em repouso. Exame: sem sopros, pulsos simétricos. ECG de repouso sem alterações isquêmicas. DM2 com HbA1c 7,6%. Pré-teste de DAC alto.', 'Iniciar AAS, estatina de alta potência e metoprolol succinato. Solicito teste ergométrico e ECO. Nitrato sublingual SN. Orientada a procurar o PS se dor em repouso ou > 20 min. Retorno em 6 semanas com exames.'),
  (860, 256, 1, '2022-03-29 14:00', 'retorno', 'Trouxe os exames', 128, 76, 64, 71.0, 'Teste ergométrico interrompido aos 5 min por angina e infradesnivelamento de ST de 2,5 mm em V4 a V6, escore de Duke -9 (alto risco). ECO com FEVE 60%, sem alterações segmentares em repouso. Persistem crises 2 a 3 vezes por semana apesar do metoprolol. Indicada estratificação invasiva. Alergia ao iodo apenas leve, discutido preparo com anti-histamínico e corticoide.', 'Encaminhar para cateterismo diagnóstico com preparo para alergia ao iodo (prednisona e loratadina). Manter medicação. Se lesão com indicação, angioplastia no mesmo tempo.'),
  (861, 256, 10, '2022-04-20 07:30', 'internacao', 'Cateterismo eletivo', 132, 78, 62, 71.0, 'Coronariografia por via radial direita com premedicação, sem reação ao contraste. Lesão de 85% em DA média, demais artérias com lesões não obstrutivas (CD 30%, Cx 25%). Realizada angioplastia com stent farmacológico 3,0 x 18 mm em DA, bom resultado angiográfico. Metformina suspensa por 48 h. Sem intercorrências, alta no dia seguinte.', 'Adicionar clopidogrel 75 mg por 6 meses com AAS. Retomar metformina após 48 h com creatinina. Manter estatina e betabloqueador. Reabilitação cardíaca. Retorno em 5 meses.'),
  (862, 256, 1, '2022-10-04 14:20', 'retorno', 'Sem dor no peito, vim fazer a revisão', 122, 72, 60, 69.8, 'Cinco meses pós-angioplastia. Assintomática, faz hidroginástica 3 vezes por semana e caminhada. Sem uso de nitrato SN desde a alta. HbA1c 6,8%, LDL 58 mg/dL. Completou 6 meses de clopidogrel. Sem sangramentos. PA e FC adequadas, sem queixas de impotência com o betabloqueador.', 'Suspender clopidogrel, manter AAS 100 mg indefinidamente. Manter rosuvastatina 20 mg com meta de LDL < 55. Manter demais medicamentos. Retorno em 6 meses.');
