insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (256, '2022-10-04', 'melhorou', 'Angina estável com isquemia extensa tratada com angioplastia da DA. Está sem angina, com LDL e HbA1c na meta, completou a dupla antiagregação e mantém exercício regular. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (257, 'José Ribamar Costa Mendes', 'M', '1955-12-01', 'São Luís', 'MA', 'Pescador aposentado', 'IAM em 2017 sem revascularização, evoluiu com ICFEr (FEVE 28%). Em uso de enalapril, carvedilol, furosemida, AAS e sinvastatina. HAS e ex-tabagista. Vive com a esposa em casa de palafita, renda de um salário mínimo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (863, 257, 11, '2021-03-09 09:30', 'consulta', 'Falta de ar para andar até o mercado', 108, 70, 84, 74.5, 'Pcte de 65 anos, ICFEr isquêmica, CF III NYHA. Dispneia aos mínimos esforços, ortopneia com 2 travesseiros, edema de tornozelos 1+/4+. Ao exame: BEG, estase jugular a 45º discreta, RCR 2T com B3, MV+ com estertores finos em bases. FEVE 28% no ECO. NT-proBNP 4.200 pg/mL. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Sem espironolactona nem iSGLT2.', 'Suspender enalapril e, após 36 h, iniciar sacubitril/valsartana 24/26 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol e furosemida. Exames de K e creatinina em 1 semana. Orientado a pesar-se todos os dias.'),
  (864, 257, 11, '2021-05-18 09:40', 'retorno', 'Estou melhor, consigo andar mais', 104, 66, 68, 70.2, 'Melhora de classe funcional para II, perdeu 4,3 kg de líquido, sem ortopneia, edema resolvido. Tolerou os quatro pilares. K 5,0 e creatinina 1,4, sem hipotensão sintomática. Conseguiu a sacubitril/valsartana por doação do programa de apoio, mas avisa que o fornecimento termina em 2 meses.', 'Manter todas as medicações. Se acabar a sacubitril/valsartana sem acesso, voltar ao enalapril 10 mg 12/12h (após 36 h de pausa) e avisar no ambulatório. Repetir K e creatinina em 4 semanas. Retorno em 3 meses.'),
  (865, 257, 6, '2022-08-30 04:10', 'pronto_socorro', 'Sufocado, não consigo deitar', 190, 110, 118, 77.0, 'Trazido pela esposa com dispneia intensa há 3 horas, sentado, falando frases curtas, sudoreico, SpO2 84% em ar ambiente, FR 34. Ausculta com estertores até ápices, edema em MMII 3+. Relata que "acabou o remédio caro" há 10 dias e ficou apenas com a furosemida. Sem dor torácica. ECG: taquicardia sinusal, onda Q anterior antiga. HD: EAP hipertensivo por descompensação de ICFEr por interrupção do tratamento.', 'O2 e VNI com CPAP, furosemida 80 mg EV, nitroglicerina EV em bomba para PA elevada, monitorização. Solicitada vaga em UTI. Troponina e gasometria colhidas. Família orientada sobre gravidade.'),
  (866, 257, 14, '2022-09-02 08:00', 'internacao', 'Evolução na UTI após EAP', 86, 52, 112, 75.0, 'Terceiro dia de UTI. Houve melhora inicial do edema, mas evoluiu com hipotensão, extremidades frias, lactato 4,2 e oligúria, perfil frio-úmido. Creatinina 3,1. ECO com FEVE 20%. Introduzida dobutamina e suspensos vasodilatadores, diurético em bomba. Resposta parcial. Paciente não candidato a transplante ou dispositivo de assistência pela idade, comorbidades e acesso. Conversado com a família sobre prognóstico reservado.', 'Manter dobutamina 5 mcg/kg/min, furosemida em infusão contínua, controle de diurese e lactato seriado. Avaliar suporte dialítico caso piora renal. Cuidados de conforto discutidos com a família, sem ressuscitação em caso de parada.');
