insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (257, '2022-09-11', 'obito', 'Faleceu na UTI após 12 dias de internação por choque cardiogênico refratário e disfunção renal, decorrente de ICFEr isquêmica descompensada após interrupção da sacubitril/valsartana por falta de acesso ao medicamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (258, 'Ana Lúcia Fonteneles Barros', 'F', '1952-04-25', 'Parnaíba', 'PI', 'Costureira aposentada', 'HAS há 15 anos controlada com losartana e hidroclorotiazida. Lombalgia crônica com uso frequente de anti-inflamatórios por conta própria. Sem DM. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (867, 258, 4, '2022-01-12 10:00', 'consulta', 'Coração disparado e cansaço', 146, 88, 118, 66.0, 'Paciente de 69 anos com palpitações irregulares há 3 semanas e cansaço aos médios esforços. Pulso irregular, RCR em 2T sem sopros, MV+ sem RA. ECG: fibrilação atrial com resposta ventricular de 118 bpm. ECO: átrio esquerdo 46 mm, FEVE 60%, sem valvopatia relevante. TSH normal. CHA2DS2-VASc 3 (idade 65-74, sexo feminino, HAS). HAS-BLED 2 por uso de AINE.', 'Anticoagular com rivaroxabana 20 mg com o jantar (ClCr 72). Iniciar metoprolol succinato 50 mg para controle de FC. Suspender AINEs. Orientações sobre sinais de sangramento. Retorno em 6 semanas.'),
  (868, 258, 4, '2022-03-02 10:30', 'retorno', 'Melhorei bastante', 128, 76, 72, 65.4, 'Sem palpitações, FC 72 em FA controlada. Consegue caminhar até a feira. Sem sangramentos. Toma rivaroxabana no jantar. Ainda sente dor lombar mas diz que "está aguentando sem o remédio de dor". PA 128x76, sem sinais de insuficiência cardíaca ao exame, pulmões limpos.', 'Manter estratégia de controle de frequência com anticoagulação. Se sintomas retornarem, discutir cardioversão. Para dor lombar: fisioterapia e paracetamol, evitar AINE. Retorno em 12 meses com hemograma e creatinina.'),
  (869, 258, 6, '2023-05-24 20:40', 'pronto_socorro', 'Fezes pretas e tontura', 98, 60, 104, 64.0, 'Dois dias de melena e tontura, uma lipotímia em casa. Admite uso de diclofenaco por 10 dias para dor lombar, "a dor voltou forte", junto com rivaroxabana. Descorada ++/4+, abdome sem peritonismo. Hb 8,1 g/dL (12,8 prévio). PA 98x60, FC 104 em FA. HD: hemorragia digestiva alta associada a AINE e anticoagulante.', 'Suspender rivaroxabana e AINE, acesso venoso calibroso, reposição volêmica, omeprazol EV 80 mg. Endoscopia nas próximas 24 h. Internação em enfermaria. Transfusão se Hb < 7.'),
  (870, 258, 4, '2023-08-30 10:00', 'retorno', 'Vim ver se posso voltar o remédio do sangue', 130, 78, 70, 65.0, 'Recuperada do sangramento, Hb 11,6 g/dL, sem melena há 2 meses. Teste de H. pylori positivo, tratou com esquema de erradicação, úlcera cicatrizada em EDA de controle. Sem novas dores lombares fortes, faz fisioterapia. CHA2DS2-VASc mantém 3: risco de AVC alto, sangramento tinha causa corrigível (AINE + úlcera).', 'Reintroduzir anticoagulação com apixabana 5 mg 12/12h, com pantoprazol 40 mg por 3 meses. Reforçado: nunca usar anti-inflamatório sem avisar. Hemograma em 1 mês. Retorno em 6 meses.');
