insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (258, '2024-02-20', 'estavel', 'FA permanente controlada com betabloqueador, anticoagulada com apixabana após hemorragia digestiva causada por AINE e úlcera por H. pylori. Sem novos sangramentos, Hb normal e sem eventos tromboembólicos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (259, 'Walter Müller Becker', 'M', '1944-08-17', 'Blumenau', 'SC', 'Aposentado (ex-gerente de indústria têxtil)', 'HAS e dislipidemia em tratamento, sopro cardíaco conhecido há 15 anos sem seguimento. Ex-tabagista (parou em 1990). Viúvo, mora sozinho, filhos moram na mesma cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (871, 259, 1, '2023-03-20 09:00', 'consulta', 'Quase desmaiei subindo as escadas de casa', 132, 76, 70, 78.5, 'Homem de 78 anos com dispneia progressiva há 6 meses (CF III) e um episódio de síncope ao esforço no mês passado, além de aperto no peito ao carregar compras. Sopro sistólico ejetivo 4+/6+ em foco aórtico, irradiado para carótidas, B2 hipofonética, pulso parvus et tardus. ECO: calcificação valvar aórtica, área valvar 0,7 cm², gradiente médio 52 mmHg, Vmax 4,6 m/s, FEVE 58%. Estenose aórtica grave sintomática.', 'Indicada intervenção valvar. Heart team: risco cirúrgico intermediário (STS 6,1%) e fragilidade leve, favorecendo TAVI. Solicitada angiotomografia de aorta e ilíacas. Evitar esforços até o procedimento. Evitar vasodilatadores potentes. Retorno com tomografia.'),
  (872, 259, 10, '2023-05-08 07:30', 'internacao', 'Internação eletiva para TAVI', 128, 72, 66, 78.0, 'Angiotomografia com anel aórtico de 25 mm, acessos ilíacos e femorais adequados, coronárias sem lesões obstrutivas. Realizado TAVI transfemoral com prótese autoexpansível 29 mm sob sedação, sem intercorrências. Gradiente transvalvar residual 9 mmHg, sem vazamento paravalvar significativo. ECG pós-procedimento com BRE novo transitório, sem BAV. Extubado na sala e deambulando em 24 h.', 'Monitorização de ritmo por 48 h por risco de bloqueio. AAS 100 mg contínuo. Alta no terceiro dia se ritmo estável. Profilaxia de endocardite e orientações sobre higiene oral. ECO de controle em 30 dias.'),
  (873, 259, 1, '2023-06-26 09:30', 'retorno', 'Voltei a subir as escadas sem falta de ar', 126, 74, 64, 79.2, 'Um mês e meio do TAVI. Sem síncope, sem angina, CF I. Voltou a caminhar 40 minutos diariamente. Ausculta com sopro sistólico suave 2+/6+. ECO: prótese normofuncionante, gradiente médio 11 mmHg, sem leak paravalvar, FEVE 60%. ECG com ritmo sinusal e BRE estável, sem BAV.', 'Manter AAS 100 mg. Higiene oral e antibiótico profilático em procedimentos dentários. ECO anual. Seguir PA < 130/80. Retorno em 6 meses.');
