insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (259, '2023-12-18', 'melhorou', 'Estenose aórtica grave sintomática tratada com TAVI transfemoral sem complicações. Assintomático, prótese com bom gradiente e sem leak, voltou às caminhadas e ao convívio. Segue com ECO anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (260, 'Josefa Alves de Lima', 'F', '1960-10-05', 'Quixadá', 'CE', 'Agricultora', 'Doença de Chagas diagnosticada há 20 anos, nunca tratada. Nasceu e viveu em casa de taipa no sertão. Sem HAS conhecida. Mãe faleceu de morte súbita aos 55 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (874, 260, 11, '2022-04-06 08:30', 'consulta', 'Inchaço nas pernas e cansaço', 104, 68, 62, 58.0, 'Paciente de 61 anos, chagásica, com 6 meses de dispneia aos esforços (CF III) e edema de MMII. Ao exame: pulso 62 irregular por extrassístoles, estase jugular 2+, B3, edema 2+/4+. ECG: BRD + HBAE, ESV frequentes. ECO: cardiomiopatia dilatada, FEVE 33%, aneurisma apical de VE sem trombo. Holter 24h: TV não sustentada em 3 episódios. Cardiopatia chagásica crônica com ICFEr, já estabelecida: sem indicação de benznidazol.', 'Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg e furosemida 40 mg. Pedir NT-proBNP e eletrólitos em 1 semana. Orientações de sal e peso diário. Retorno em 3 meses, discutir amiodarona.'),
  (875, 260, 4, '2022-07-13 08:50', 'retorno', 'Palpitações e tontura', 100, 64, 58, 56.2, 'Melhora do edema, mas queixa de palpitações em crises e pré-síncope, 2 episódios no mês. Ritmo irregular com ESV frequentes. ECG com BRD + HBAE, bradicardia sinusal 58 bpm. Holter novo: TVNS 14 episódios, até 15 batimentos a 190 bpm. FEVE 31%. Alto risco de morte súbita pelo substrato chagásico com aneurisma apical e TVNS.', 'Iniciar amiodarona 200 mg ao dia (aceitando a bradicardia, FC ainda acima de 50). Aumentar enalapril para 10 mg 12/12h, carvedilol mantido em 3,125 mg. Discutir CDI para prevenção primária. Perfil tireoidiano e provas hepáticas basais. Retorno em 8 semanas.'),
  (876, 260, 6, '2023-02-02 22:15', 'pronto_socorro', 'Desmaiei na roça', 82, 50, 186, 56.0, 'Síncope durante a colheita, trazida por vizinhos. Chegou sudoreica, hipotensa, taquicardia regular de QRS largo a 186 bpm, consciente mas torporosa. ECG: TV monomórfica sustentada com morfologia de BRD. Sem dor torácica. HD: TV sustentada em chagásica com instabilidade hemodinâmica.', 'Cardioversão elétrica sincronizada 100 J sob sedação com reversão para ritmo sinusal. Amiodarona EV, corrigidos K e Mg. Transferida para internação em cardiologia para estratificação e indicação de CDI.'),
  (877, 260, 4, '2023-02-08 09:00', 'internacao', 'Implante de CDI', 106, 66, 60, 56.5, 'Sem novos episódios após cardioversão. ECO com FEVE 30%, aneurisma apical sem trombo. Indicação de CDI em prevenção secundária (TV sustentada com instabilidade). Realizado implante de CDI unicâmara via subclávia esquerda, sem intercorrências, limiares adequados. Programada terapia por ATP e choque para zona de TV acima de 170 bpm. Orientações dadas à paciente e ao marido.', 'Manter amiodarona e o tratamento de IC. Restrição do braço esquerdo por 4 semanas. Controle do dispositivo em 30 dias. Orientada a procurar o PS se receber choque. Retorno ambulatorial em 6 semanas.');
