insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (260, '2023-11-20', 'piorou', 'Cardiopatia chagásica com TV sustentada e CDI. Nos meses seguintes recebeu dois choques apropriados e voltou a ter dispneia em repouso (CF III-IV), com internações por descompensação. Bradicardia e hipotensão limitam titulação. Em avaliação para IC avançada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (261, 'Isaías Ferreira Lustosa', 'M', '1966-01-22', 'Picos', 'PI', 'Professor de ensino médio', 'DM2 há 8 anos em uso de metformina 850 mg 12/12h, HAS diagnosticada há 3 anos sem tratamento regular. Sobrepeso, sedentário, passa o dia na escola e corrige provas à noite. Pai diabético e hipertenso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (878, 261, 1, '2022-03-08 10:00', 'consulta', 'Diabetes e pressão fora do controle', 152, 92, 78, 88.0, 'Homem de 56 anos, assintomático, traz exames do endocrinologista com HbA1c 7,9% e relação albumina/creatinina urinária de 185 mg/g (albuminúria moderadamente aumentada, confirmada em duas amostras). PA 152x92 em duas medidas. Fundo de olho sem retinopatia. Pulsos normais, sem sopros. IMC 30,5. Compreende que "o açúcar e a pressão judiam do rim". HAS estágio 1 com DM2 e lesão renal incipiente.', 'Iniciar losartana 100 mg ao dia (BRA por albuminúria) e dapagliflozina 10 mg. Manter metformina. Dosar creatinina e potássio em 2 semanas. Reduzir sal e iniciar caminhada à noite. Retorno em 8 semanas.'),
  (879, 261, 1, '2022-05-03 10:20', 'retorno', 'Vim mostrar os exames novos', 138, 84, 74, 85.6, 'Peso caiu 2,4 kg. Sem sintomas genitourinários com a dapagliflozina, refere higiene redobrada. Creatinina subiu de 1,0 para 1,2 (aumento esperado de 20% com bloqueio do SRAA e iSGLT2), potássio 4,9. RAC reduziu para 120 mg/g. PA ainda acima da meta, 138x84, MRPA com média 136x83.', 'Associar anlodipino 5 mg pela manhã. Manter losartana e dapagliflozina. Não aumentar mais o BRA por ora devido ao potássio. Repetir creatinina e potássio em 4 semanas. Retorno em 6 meses.'),
  (880, 261, 1, '2022-11-15 10:00', 'retorno', 'Consulta de rotina', 126, 76, 72, 83.1, 'Perdeu 4,9 kg desde o início, caminha 40 minutos 5 vezes por semana com um colega da escola. HbA1c 6,9%. RAC caiu para 48 mg/g. Creatinina estável em 1,2 mg/dL, potássio 4,7. Sem edema de tornozelo com anlodipino. PA 126x76 e MRPA média 124x75, dentro da meta de < 130/80.', 'Manter o esquema atual. Repetir RAC, creatinina e potássio a cada 6 meses. Fundo de olho anual. Seguir com a endocrinologia para metas de glicemia. Retorno em 6 meses.');
