insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (261, '2023-05-16', 'controlado', 'HAS e DM2 com albuminúria, controlados em oito meses de tratamento com BRA, anlodipino e iSGLT2. A albuminúria caiu de 185 para 48 mg/g, PA na meta e HbA1c abaixo de 7%, mantendo função renal estável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (262, 'Francisca Edileuza Moura Lima', 'F', '1964-08-08', 'Imperatriz', 'MA', 'Empregada doméstica', 'HAS há 14 anos, obesidade grau I, apneia não investigada, DLP. Em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg há mais de 1 ano. Retira os remédios no posto e traz as caixas vazias a cada mês.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (881, 262, 2, '2020-10-06 09:00', 'consulta', 'Pressão alta mesmo com três remédios', 168, 102, 80, 86.2, 'Mulher de 56 anos, encaminhada por HAS refratária. Uso regular dos três fármacos confirmado por dispensação mensal e pelo relato da família. Dieta com pouco sal segundo ela ("cozinho sem sal e uso limão"). PA 168x102 com manguito de tamanho correto, 3 medidas. Sem sopros abdominais, sem uso de AINE ou descongestionantes. Nega ronco. Suspeita de HAS resistente verdadeira; necessário descartar efeito do avental branco.', 'Solicitar MAPA de 24 h. Pedir potássio, creatinina, aldosterona e renina, sódio urinário de 24 h e TSH. Manter os três fármacos. Retorno com exames.'),
  (882, 262, 2, '2020-11-17 09:10', 'retorno', 'Trouxe a MAPA e os exames', 164, 100, 78, 86.0, 'MAPA 24h: média 158x96, vigília 162x98, sono 148x88, descenso noturno atenuado. Isso exclui o avental branco. Aldosterona 9 ng/dL e renina ativa 1,8 ng/mL/h (relação aldosterona/renina baixa, sem sugestão de hiperaldosteronismo), K 3,8, TSH normal, sódio urinário 142 mEq/24h (consumo de sal moderado). Confirmada HAS resistente verdadeira, sem causa secundária evidente.', 'Adicionar espironolactona 25 mg ao dia. Monitorar potássio e creatinina em 1 e 4 semanas. Orientar sobre ginecomastia ou irregularidade menstrual (menopausada, sem risco). Reduzir sal ainda mais. Retorno em 8 semanas.'),
  (883, 262, 2, '2021-01-12 09:00', 'retorno', 'Pressão melhorou muito', 134, 82, 72, 84.4, 'Após 8 semanas de espironolactona, PA 134x82 e MRPA com média 132x80. Potássio 4,9 e creatinina 1,0 após 4 semanas, sem hipercalemia. Sem mastalgia, sem cólica. Perdeu 1,6 kg. Consegue manter uso regular mesmo trabalhando em duas casas, e a filha confere as caixas todo domingo.', 'Manter os quatro fármacos. Repetir potássio e creatinina em 3 meses (risco de hipercalemia, evitar suplementos de potássio e AINE). Meta de PA < 130/80: aumentar espironolactona para 50 mg se MRPA > 130/80 no próximo retorno. Retorno em 3 meses.');
