insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (262, '2021-04-20', 'controlado', 'HAS resistente verdadeira confirmada por MAPA e sem causa secundária, controlada após adicionar espironolactona 25 mg ao esquema de três drogas. PA em torno de 130x80, potássio e creatinina estáveis sob monitorização trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (263, 'Rosimeire Gomes da Silva', 'F', '1978-05-02', 'Fortaleza', 'CE', 'Operadora de telemarketing', 'Sem diagnóstico prévio de HAS. Crises de ansiedade em fases de estresse, uso de anticoncepcional oral combinado por muitos anos (suspenso há 2 anos). Dorme mal, muito café. Mãe hipertensa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (884, 263, 6, '2024-02-19 21:30', 'pronto_socorro', 'Medi a pressão no posto e deu 200', 192, 112, 104, 68.0, 'Pcte de 45 anos veio ao PS após medir PA no posto de saúde, 200x110, depois de uma discussão com o supervisor no trabalho. Refere palpitação, aperto no peito sem irradiação, formigamento nas mãos e medo. Nega cefaleia intensa, alteração visual, déficit motor, dispneia ou dor torácica típica. Ao exame: ansiosa, hiperventilando, pulmões limpos, sem sopros, neurológico normal, fundo de olho sem papiledema. Repouso de 30 min em sala calma: PA 154x94, FC 84. HD: pseudocrise hipertensiva (elevação de PA sem lesão de órgão-alvo, reação de ansiedade).', 'Sem indicação de anti-hipertensivo no PS (não usar nifedipino sublingual). Orientações de respiração lenta, repouso, reduzir café. Encaminhar para ambulatório de cardiologia para MAPA. Retorno se cefaleia, dor no peito ou déficit.'),
  (885, 263, 1, '2024-03-12 15:00', 'consulta', 'Vim investigar a pressão alta do pronto-socorro', 142, 88, 82, 67.8, 'Mulher de 45 anos, assintomática no momento. Relata que a pressão sobe quando fica nervosa e que em casa mediu 120x80 algumas vezes. Consumo de 5 a 6 cafés ao dia, dorme 5 horas. PA de consultório 142x88, a primeira medida mais alta que as demais. Exame cardiovascular e abdominal normais. Suspeita de reação de alarme/ansiedade; confirmar com MAPA antes de qualquer diagnóstico de HAS.', 'Solicitar MAPA de 24h e MRPA. Não iniciar anti-hipertensivo. Reduzir café, higiene do sono, atividade física. Encaminhar à psicologia da UBS. Retorno com os exames.'),
  (886, 263, 1, '2024-04-23 15:10', 'retorno', 'Trouxe o resultado da MAPA', 130, 82, 76, 66.9, 'MAPA de 24h: média 124x78, vigília 128x82, sono 114x68, descenso noturno preservado, sem picos acima de 150x95 exceto um durante reunião no trabalho. MRPA média 122x77. Sem diagnóstico de HAS. A crise do PS foi uma pseudocrise por ansiedade. Reduziu café para 2 ao dia, caminha 3 vezes por semana, iniciou psicoterapia na UBS.', 'Nenhum medicamento anti-hipertensivo. Manter MEV e psicoterapia. Repetir MAPA em 12 meses ou antes se novos picos. Orientada a usar aparelho validado em casa e não se tratar por picos isolados. Retorno em 6 meses.');
