insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (264, '2024-12-10', 'melhorou', 'Síndrome HELLP aos 33 semanas tratada com sulfato de magnésio, corticoide e cesariana. Recuperação completa das plaquetas e enzimas, bebê prematuro com boa evolução. Seis meses depois está normotensa sem medicação e orientada sobre risco futuro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (265, 'Pedro Henrique Nogueira Lins', 'M', '1969-10-11', 'Juazeiro do Norte', 'CE', 'Mototaxista', 'Tabagismo de 25 maços-ano, HAS sem tratamento, nunca fez exames de rotina. Trabalha 12 horas por dia, alimenta-se de lanches. Irmão com infarto aos 52 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (891, 265, 6, '2024-01-23 22:00', 'pronto_socorro', 'Dor no peito parada há quase 1 hora', 168, 100, 96, 92.0, 'Dor retroesternal em aperto, em repouso, com duração de 40 min e recorrência 2 vezes no dia, sudorese. ECG: infradesnivelamento de ST de 1,5 mm em V4-V6 e T negativa em DI e aVL, sem supra. Troponina I 0,9 ng/mL, repetida em 3 h: 3,2 ng/mL. PA 168x100, SpO2 96%, pulmões limpos. GRACE 142 (alto risco). HD: IAMSSST (SCA sem supra de ST).', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg, atorvastatina 80 mg, metoprolol 25 mg VO. Internar em unidade coronariana, cateterismo em até 24 h. Analgesia com nitrato sublingual e controle da PA.'),
  (892, 265, 10, '2024-01-24 11:00', 'internacao', 'Cateterismo na unidade coronariana', 142, 86, 70, 92.0, 'Sem dor desde a madrugada. Coronariografia radial direita: lesão de 90% em DA proximal (culpada, com trombo), Cx 70% com FFR 0,76 em segunda marginal, CD com 50% sem significado. Angioplastia com stent farmacológico em DA e em Cx no mesmo tempo, fluxo TIMI 3. ECO: FEVE 48%, hipocinesia anterior. HbA1c de admissão 8,4%, diabetes novo diagnosticado.', 'Dupla antiagregação por 12 meses. Iniciar metoprolol succinato, losartana, metformina e empagliflozina (DM2 + doença coronariana). Abandono imediato do tabaco com apoio. Reabilitação cardíaca. Alta em 48 h. Retorno em 6 semanas.'),
  (893, 265, 1, '2024-03-05 08:30', 'retorno', 'Voltei para revisão do infarto', 130, 80, 62, 89.4, 'Sem angina, voltou a trabalhar com a moto há 3 semanas, mas "sinto cansaço no fim do dia". Parou de fumar, mas recaiu duas vezes em ''cigarro de festa''. Tolerando ticagrelor, com leve falta de ar nos primeiros dias, já resolvida. Peso -2,6 kg. FC 62 com betabloqueador. ECO de controle com FEVE 50%.', 'Manter esquema. Reforçar cessação do tabagismo, prescrito adesivo de nicotina por 8 semanas. Reabilitação cardíaca duas vezes por semana (acordo com horário de trabalho). Lipidograma em 8 semanas. Retorno em 6 meses.'),
  (894, 265, 1, '2024-09-10 08:40', 'retorno', 'Consulta de seguimento', 122, 74, 60, 86.8, 'Oito meses de pós-IAMSSST. Sem dor torácica, está sem fumar há 5 meses, caminha 30 minutos por dia. LDL 49 mg/dL, HbA1c 6,6%. Sem sangramentos. PA 122x74. Ainda tem dúvida se precisa tomar tantos comprimidos, mas "entendi que são os stents que estão protegidos".', 'Manter dupla antiagregação até janeiro/2025, depois apenas AAS. Manter demais fármacos. Exames a cada 6 meses. Retorno em 4 meses para definir fim da dupla antiagregação.');
