insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (265, '2024-09-10', 'melhorou', 'IAMSSST de alto risco tratado com angioplastia de DA e Cx, com diabetes diagnosticado no evento. Oito meses depois está assintomático, sem fumar, LDL e HbA1c na meta, FEVE recuperada para 50% e de volta ao trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (266, 'Dalva Aparecida Ribeiro Santana', 'F', '1948-03-27', 'Goiânia', 'GO', 'Aposentada (ex-secretária escolar)', 'HAS há 30 anos, obesidade, osteoartrose de joelhos com uso ocasional de ibuprofeno. Em uso de losartana e anlodipino. Mora com o marido, que também é hipertenso. Nunca fumou.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (895, 266, 11, '2022-07-11 09:30', 'consulta', 'Falta de ar e pernas inchadas', 158, 86, 76, 74.8, 'Paciente de 74 anos com 3 meses de dispneia aos médios esforços, ortopneia leve e edema vespertino de tornozelos. Ao exame, estase jugular discreta, RCR 2T com B4, estertores em bases, edema 2+/4+. ECO: FEVE 62%, HVE concêntrica, átrio esquerdo aumentado (volume 48 mL/m²), E/e'' 16. NT-proBNP 1.150 pg/mL. ICFEp por cardiopatia hipertensiva, PA descontrolada pelo uso de ibuprofeno.', 'Suspender ibuprofeno (retenção de sal). Iniciar empagliflozina 10 mg e espironolactona 25 mg. Manter losartana 50 mg 12/12h e anlodipino 5 mg, e acrescentar furosemida 40 mg. Exames de K e creatinina em 1 semana. Restrição de sal.'),
  (896, 266, 11, '2022-09-20 09:40', 'retorno', 'Consigo andar no condomínio de novo', 136, 78, 70, 71.2, 'Perdeu 3,6 kg de líquido, sem ortopneia, edema residual discreto. Joelhos doloridos, usando paracetamol e fisioterapia. K 4,8, creatinina 1,2. Sem infecção urinária com empagliflozina, sem hipotensão postural ao levantar. PA 136x78, pulmões limpos, sem estase jugular. Voltou a cuidar da horta e subir os dois lances de escada de casa sem parar. CF II.', 'Manter o esquema, reduzir furosemida para 20 mg ao dia se peso se manter. Evitar AINE. Hidratação em dias de calor. Retorno em 6 meses.'),
  (897, 266, 6, '2023-03-14 05:30', 'pronto_socorro', 'Acordei sem ar', 172, 94, 102, 76.5, 'Acordou com dispneia súbita, tosse com secreção rosada. Ontem foi a um casamento e "comi de tudo", também voltou a tomar ibuprofeno para dor no joelho. Peso +5 kg em 6 dias. SpO2 89% em ar ambiente, estertores até terço médio, edema 3+/4+. PA 172x94. ECG: ritmo sinusal com taquicardia, sem FA. HD: EAP hipertensivo por descompensação de ICFEp (sal e AINE).', 'O2 suplementar, furosemida 80 mg EV, nitroglicerina EV em baixa dose para PA elevada, posição sentada. Resposta com diurese de 1.800 mL em 3 h, SpO2 95%. Mantida em observação por 24 h. Reforçada a proibição de ibuprofeno.'),
  (898, 266, 11, '2023-04-17 09:30', 'retorno', 'Consulta depois do pronto-socorro', 130, 76, 68, 71.0, 'Recuperada, peso voltou a 71 kg. Sem dispneia, CF II. Marido e filha agora conferem o sal da comida e escondem o ibuprofeno. Tem balança em casa e anota o peso. K 4,7 e creatinina 1,2. PA 130x76, ausculta pulmonar limpa e sem estase jugular, edema ausente ao exame.', 'Manter furosemida 40 mg pela manhã e demais fármacos. Plano de ação: se ganhar 2 kg em 3 dias, tomar dose extra e ligar. Vacinas contra influenza e pneumococo. Retorno em 4 meses.');
