insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (266, '2023-10-10', 'estavel', 'ICFEp hipertensiva com um episódio de EAP desencadeado por sal e ibuprofeno. Desde então peso estável, sem novas internações, classe funcional II e PA em torno de 130x76 com empagliflozina, espironolactona e diurético.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (267, 'Manoel Ferreira Neto', 'M', '1957-06-06', 'Codó', 'MA', 'Vigilante noturno', 'HAS há 10 anos, DM2 há 6 anos em uso de metformina, sobrepeso. Trabalha à noite e dorme mal, toma café e energéticos. Nega tabagismo. Etilismo social.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (899, 267, 4, '2020-09-15 08:30', 'consulta', 'Coração batendo desordenado', 152, 94, 128, 90.5, 'Homem de 63 anos com palpitações e cansaço há cerca de 2 semanas, pior à noite durante o plantão. Pulso irregular, RCR em 2T, sem sopros, pulmões limpos. ECG: fibrilação atrial com resposta ventricular média de 128 bpm. ECO: átrio esquerdo 44 mm, FEVE 56%. TSH normal. CHA2DS2-VASc 2 (HAS e DM2). Início de FA sem data precisa (> 48 h).', 'Anticoagular com rivaroxabana 20 mg com o jantar. Metoprolol succinato 50 mg para controle de FC. Programar cardioversão elétrica após 3 semanas de anticoagulação efetiva. Suspender energéticos. Retorno em 6 semanas.'),
  (900, 267, 4, '2020-11-03 08:40', 'retorno', 'Ainda sinto o coração batendo errado', 138, 86, 92, 89.8, 'Anticoagulado há 7 semanas, com adesão confirmada. Persiste FA, FC 92 com betabloqueador, mas sintomático (cansaço, dispneia aos esforços). Ainda ativo no trabalho, não aceita conviver com a FA e prefere controle de ritmo. Sem sangramentos. Hemoglobina 14,2 e creatinina 1,0.', 'Agendar cardioversão elétrica eletiva com sedação, anticoagulação ininterrupta por pelo menos 4 semanas após. Iniciar amiodarona 200 mg ao dia após a CVE para manter ritmo sinusal. Jejum de 8 h no dia.'),
  (901, 267, 4, '2021-01-12 07:30', 'internacao', 'Cardioversão elétrica programada', 140, 88, 88, 89.5, 'Hospital-dia para CVE. Em jejum, anticoagulado sem falhas por 14 semanas. Sedação com propofol, choque sincronizado 120 J (um choque) com reversão imediata para ritmo sinusal. ECG pós: ritmo sinusal 66 bpm, PR 180 ms. Sem queixas após recuperação anestésica. Alta no mesmo dia.', 'Iniciar amiodarona 200 mg ao dia. Manter rivaroxabana ininterruptamente por 4 semanas no mínimo e depois conforme CHA2DS2-VASc (mantém indicação). Manter metoprolol. Retorno em 3 meses com TSH e provas hepáticas.'),
  (902, 267, 4, '2021-04-20 08:30', 'retorno', 'Estou bem, queria parar os remédios', 134, 84, 56, 88.9, 'Em ritmo sinusal ao ECG, FC 56. Sem palpitações desde a cardioversão. Admite falhas frequentes na rivaroxabana: "o plantão atrapalha e eu já estou bom". Explicado que ritmo sinusal não dispensa a anticoagulação com CHA2DS2-VASc 2, mas o paciente demonstra pouca adesão. TSH 2,4 e TGP normal em uso de amiodarona.', 'Reforçada orientação sobre risco de AVC mesmo em ritmo sinusal. Manter rivaroxabana e amiodarona, reduzir metoprolol para 25 mg pela FC de 56. Combinar lembrete no celular para o horário do jantar antes do plantão. Retorno em 8 semanas.');
