insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (267, '2022-05-10', 'abandonou', 'FA persistente revertida com cardioversão elétrica, mantendo ritmo sinusal. Não compareceu aos três retornos seguintes; em contato telefônico da equipe, informou ter parado a rivaroxabana e os demais remédios por conta própria por se sentir bem.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (268, 'Gabriela Ramos Furtado', 'F', '1990-12-19', 'Natal', 'RN', 'Fisioterapeuta', 'Previamente hígida. Episódios de palpitação súbita desde a adolescência, 2 a 3 por ano, com duração de poucos minutos, que passavam com tosse forçada. Pratica corrida. Sem uso de medicamentos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (903, 268, 4, '2023-04-03 16:00', 'consulta', 'Crises de coração disparado', 118, 72, 82, 61.0, 'Mulher de 32 anos, com crises de palpitação de início e término súbitos, regulares, a mais recente há 3 semanas durando 25 min com tontura e poliúria ao final. Durante crise, medida por relógio, FC 180. Exame cardiovascular normal. ECG de repouso: ritmo sinusal, PR 140 ms, sem onda delta, QT normal. ECO normal. TSH normal. Holter com um episódio de taquicardia regular a 168 bpm por 4 min e início súbito. HD: TSV paroxística por reentrada nodal provável.', 'Ensinar manobra de Valsalva modificada. Iniciar bisoprolol 2,5 mg ao dia para reduzir crises. Orientar a procurar o PS em crises > 20 min. Discutir ablação por cateter como tratamento definitivo. Retorno em 8 semanas.'),
  (904, 268, 6, '2023-05-22 19:10', 'pronto_socorro', 'Crise de coração disparado que não passa', 104, 66, 192, 60.5, 'Crise de palpitações há 40 min com tontura e dor leve no peito, sem síncope. Chegou estável, consciente, PA 104x66. ECG: taquicardia regular de QRS estreito a 192 bpm, sem ondas P visíveis. Tentou Valsalva modificado duas vezes sem sucesso. HD: TSV por reentrada nodal.', 'Adenosina 6 mg EV em bolus rápido sem reversão, seguida de 12 mg EV com reversão para ritmo sinusal, sensação de calor e opressão torácica transitória como esperado. ECG pós sem pré-excitação. Alta com indicação de ablação eletiva.'),
  (905, 268, 4, '2023-07-11 07:00', 'internacao', 'Ablação por cateter agendada', 112, 70, 64, 60.2, 'Estudo eletrofisiológico sob sedação: indução de taquicardia com intervalo VA curto e atrasos em cadeia de condução nodal, compatível com AVNRT típica (lenta-rápida). Ablação por radiofrequência da via lenta com ritmo juncional durante as aplicações e sem bloqueio AV. Não induzível ao final, mesmo com isoproterenol. Repouso 4 h, sem hematoma, alta no mesmo dia.', 'Suspender bisoprolol. Sem restrições após 1 semana. Retorno em 8 semanas com ECG. Procurar atendimento se nova crise.'),
  (906, 268, 4, '2023-09-05 16:00', 'retorno', 'Sem crises desde o procedimento', 114, 70, 66, 60.8, 'Dois meses da ablação. Sem palpitações, voltou a correr 10 km. Sem medicação. Ritmo sinusal ao ECG, PR 150 ms sem alteração da condução AV. Ficou ansiosa nos primeiros dias pelo medo de nova crise, hoje tranquila e sem usar nenhum remédio, com sono regular e menos café.', 'Alta do ambulatório de arritmia com retorno somente se sintomas. Orientada a documentar com ECG qualquer nova crise. Atividade física liberada sem restrições.');
