insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (269, '2024-10-08', 'melhorou', 'Miocardite aguda pós-viral com função ventricular preservada, tratada com repouso e proteção miocárdica. Recuperação completa em sete meses, RM com resolução do edema, sem arritmias, liberado para o futebol com seguimento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (270, 'Antônio Pedro Gonçalves Brito', 'M', '1953-04-09', 'Floriano', 'PI', 'Lavrador aposentado', 'Doença de Chagas sorologia positiva desde a juventude. Cresceu em casa de taipa em zona rural. HAS leve. Dois episódios de desmaio no último ano atribuídos a calor. Etilismo moderado.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (911, 270, 6, '2020-02-10 16:40', 'pronto_socorro', 'Caí desmaiado na rua', 150, 70, 32, 70.0, 'Homem de 66 anos, trazido por vizinhos após síncope súbita, sem pródromos, com recuperação rápida. Referia cansaço há semanas. Pcte pálido, lúcido, bradicárdico com FC 32, pulso regular, B1 variável com ondas em canhão no pescoço. ECG: dissociação AV completa, escape juncional a 32 bpm, BRD. HD: BAVT em chagásico crônico, síncope por bradicardia.', 'Atropina sem resposta. Passagem de marca-passo provisório transvenoso com captura adequada e FC 70. Internar na unidade coronariana, solicitar vaga em cardiologia para MP definitivo. Eletrólitos, troponina e ECO.'),
  (912, 270, 4, '2020-02-12 08:30', 'internacao', 'Implante de marca-passo', 144, 80, 70, 70.0, 'Dependente do marca-passo provisório, sem mais síncopes. Realizado implante de marca-passo definitivo dupla-câmara por via subclávia esquerda sob anestesia local, limiares adequados (ventricular 0,6 V a 0,4 ms, onda R 9 mV). Sem pneumotórax no raio X de controle. Dor leve no local da incisão.', 'Retirar MP provisório. Antibioticoprofilaxia pós-operatória conforme protocolo. Restringir elevação do braço esquerdo por 4 semanas. Carteira do dispositivo entregue. Seguimento da Chagas com ECO e controle do MP em 30 dias. Sem indicação de benznidazol na fase crônica com cardiopatia.'),
  (913, 270, 11, '2021-08-17 09:00', 'retorno', 'Falta de ar e inchaço nas pernas', 110, 68, 72, 74.6, 'Seguimento em dia do MP (funcionamento normal na interrogação, 98% de estimulação ventricular). Há 4 meses com piora progressiva da dispneia (CF III), ortopneia e edema de MMII. ECO: FEVE 30%, dilatação biventricular, aneurisma apical sem trombo. NT-proBNP 3.600. Estimulação ventricular direita crônica pode agravar a disfunção. K 4,7, creatinina 1,2. Evolução para ICFEr chagásica.', 'Trocar losartana por sacubitril/valsartana 49/51 mg 12/12h (troca direta de BRA, sem necessidade de washout). Carvedilol 6,25 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg, furosemida 40 mg. Avaliar upgrade para ressincronização no futuro.'),
  (914, 270, 11, '2022-11-08 09:20', 'retorno', 'Muito cansado, internei duas vezes', 94, 60, 78, 66.2, 'Duas internações por descompensação nos últimos 6 meses. Hoje CF III-IV, extremidades frias, caquexia cardíaca, PA 94x60. ECO: FEVE 22%, insuficiência mitral moderada. Creatinina 1,6, sódio 131. Tolerou todas as medicações mas não permitem titular a dose por hipotensão. Já em dose máxima tolerada, ainda com sintomas. Sem trombo. Avaliação de IC avançada indicada.', 'Encaminhar para serviço de referência em insuficiência cardíaca avançada e transplante cardíaco na capital. Manter tratamento. Conversado com paciente e família sobre prognóstico e opções. Relatório de transferência entregue, contra-referência para acompanhamento local.');
