insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (270, '2022-12-01', 'transferido', 'Cardiopatia chagásica com BAVT tratado com marca-passo e evolução para ICFEr avançada com FEVE 22% e internações recorrentes. Encaminhado a centro de referência em IC avançada e transplante cardíaco, saindo do acompanhamento local.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (271, 'Cícero Romão Batista Alves', 'M', '1958-03-15', 'Barbalha', 'CE', 'Agricultor', 'HAS há 10 anos, em uso de enalapril 10 mg 12/12h e hidroclorotiazida 25 mg. Nunca fumou, bebe cachaça aos domingos. Trabalha na lida do canavial e mora em sítio a 14 km do posto.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (915, 271, 5, '2021-06-22 08:00', 'consulta', 'Tosse seca e parei o remédio da pressão', 168, 100, 80, 72.5, 'Homem de 63 anos com tosse seca, irritativa, noturna há 6 meses, que piora ao deitar. Sem febre, sem expectoração, sem dispneia. Há 1 mês parou o enalapril por conta própria porque "o remédio dá tosse e me deixa sem dormir", e passou a tomar só a hidroclorotiazida. PA 168x100. Ausculta pulmonar normal, sem estertores, sem edema. Raio X de tórax sem alterações. HD: tosse por IECA, HAS descontrolada por abandono parcial do tratamento.', 'Suspender enalapril definitivamente (registrar intolerância no prontuário). Iniciar losartana 50 mg 12/12h, manter hidroclorotiazida. A tosse deve desaparecer em 2 a 4 semanas. Dosar creatinina e potássio. Retorno em 6 semanas.'),
  (916, 271, 5, '2021-08-10 08:20', 'retorno', 'A tosse acabou', 142, 88, 76, 72.0, 'A tosse sumiu em duas semanas após a troca. Dorme bem. Toma losartana e hidroclorotiazida sem falhas. PA 142x88 e MRPA com média 140x86, ainda acima da meta. Sem tontura, sem cãibras. Creatinina e potássio normais após introdução do BRA.', 'Aumentar losartana para 100 mg ao dia em dose única e associar anlodipino 5 mg pela manhã. Manter hidroclorotiazida. Mudar a retirada dos remédios para 90 dias, dado o deslocamento até o posto. Retorno em 6 meses.'),
  (917, 271, 1, '2022-02-08 08:30', 'retorno', 'Vim buscar a receita', 128, 78, 70, 71.8, 'Sem queixas. Sem tosse, sem edema de tornozelos com o anlodipino. Retira os remédios a cada 90 dias e tem boa adesão. MRPA com média 126x77. Potássio 4,2 e creatinina 1,0 mg/dL. Orientado a reduzir cachaça. Referiu que antes achava que "remédio de pressão vicia", hoje entende que precisa continuar.', 'Manter losartana 100 mg, anlodipino 5 mg e hidroclorotiazida 25 mg. Anotar a intolerância ao enalapril (tosse) na ficha. Exames anuais. Retorno em 6 meses na UBS.');
