insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (271, '2022-02-08', 'controlado', 'A tosse por enalapril levou ao abandono do tratamento. Com a troca por losartana, a tosse sumiu, a adesão voltou e a PA ficou na meta com três fármacos. Segue em acompanhamento na UBS com retirada trimestral dos medicamentos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (272, 'Helena Maria Kowalski Nascimento', 'F', '1975-01-29', 'Florianópolis', 'SC', 'Arquiteta', 'Sem comorbidades conhecidas. Pai e irmão com HAS. Trabalha em escritório e em obras, dorme pouco, sedentária. Nunca fumou, vinho nos fins de semana. Descobriu a pressão alta em avaliação para seguro de vida.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (918, 272, 2, '2023-01-17 11:00', 'consulta', 'Pressão alta no check-up', 172, 104, 78, 69.5, 'Mulher de 48 anos, assintomática, com PA 172x104 no consultório (média de 3 medidas) e 168x102 no check-up. MRPA de 3 dias trazida: média 164x100. Nega cefaleia, uso de anti-inflamatórios, descongestionantes ou anticoncepcional. Exame sem sopros, pulsos femorais normais, sem massas abdominais. IMC 25,6. ECG: sobrecarga ventricular esquerda discreta. HAS estágio 2 sem causa secundária aparente.', 'Iniciar tratamento medicamentoso imediato com associação em comprimido único (valsartana 160 mg + anlodipino 5 mg) para facilitar adesão. MEV: sal, álcool e exercício. Exames de rotina e albuminúria. Retorno em 6 semanas.'),
  (919, 272, 2, '2023-03-07 11:00', 'retorno', 'Estou bem, só inchou o pé', 138, 86, 74, 69.0, 'Seis semanas de tratamento. PA 138x86 e MRPA média 136x84, melhora grande, mas ainda acima da meta. Edema discreto vespertino de tornozelos (1+/4+) desde a segunda semana, sem repercussão. Sem tosse, sem tontura. Boa adesão, a dose única foi bem aceita.', 'Trocar para valsartana 160 mg + anlodipino 10 mg em comprimido único (aumento da dose do BCC). Elevar membros ao fim do dia. Se edema piorar, trocar por associação com hidroclorotiazida. Retorno em 8 semanas.'),
  (920, 272, 2, '2023-08-22 10:40', 'retorno', 'Vim mostrar a pressão', 124, 76, 70, 67.2, 'PA 124x76, MRPA média 122x75. Edema de tornozelos persiste mas leve, sem incômodo, e não impede as caminhadas de 5 km aos fins de semana. Perdeu 2,3 kg, reduziu o vinho. Função renal e potássio normais, sem albuminúria e sem queixas de tontura, tosse ou palpitações.', 'Manter comprimido único valsartana 160 mg + anlodipino 10 mg. Exames de rotina anuais. Retorno em 6 meses.');
