insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (272, '2023-08-22', 'controlado', 'HAS estágio 2 diagnosticada em check-up, controlada em sete meses com um único comprimido combinado e MEV. Efeito colateral limitado a edema discreto de tornozelo, sem impacto na adesão.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (273, 'Domingos Savio Teles Furtado', 'M', '1966-07-21', 'Teresina', 'PI', 'Mecânico de automóveis', 'DRC por glomerulonefrite crônica em hemodiálise três vezes por semana há 18 meses (segunda, quarta e sexta). Fístula arteriovenosa em braço esquerdo. HAS de longa data. Anemia da DRC em uso de eritropoetina.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (921, 273, 8, '2021-10-05 14:00', 'consulta', 'A pressão sobe muito antes da diálise', 178, 104, 82, 82.4, 'Homem de 55 anos, em HD, vem por PA pré-diálise de 170-190/100-110 e cefaleia nos dias de intervalo longo. Ganho interdialítico de 4 kg (sal e líquido, "gosto de caldo e refrigerante"). Edema de tornozelos 2+/4+. Peso seco prescrito 78 kg. K pré-diálise 5,6. Cãibras e hipotensão no final das sessões. HAS secundária à DRC, volume-dependente.', 'Reduzir peso seco em 1,5 kg para 76,5 kg com ultrafiltração gradual, orientar restrição de sal (< 5 g/dia) e líquidos (800 mL). Iniciar anlodipino 10 mg e carvedilol 12,5 mg 12/12h à noite. Evitar IECA/BRA por K 5,6. Retorno em 6 semanas.'),
  (922, 273, 8, '2021-11-16 14:10', 'retorno', 'As sessões estão melhores', 148, 86, 72, 78.0, 'Peso seco atual de 76,5 kg, ganhos interdialíticos de 2,4 kg. PA pré-diálise 148x86, pós 126x74. Sem hipotensão intradialítica relevante, mas relata cãibras na terceira hora das sessões de sexta-feira. Cefaleia desapareceu. K 5,1. Aderência melhor à restrição de líquido com garrafa graduada.', 'Manter o peso seco, ajustar o banho de sódio da diálise para 138 mEq/L e orientar alongamento das pernas antes de cada sessão. Manter anti-hipertensivos à noite. Solicitar ECO para avaliar hipertrofia e função ventricular. Encaminhar à cardiologia.'),
  (923, 273, 1, '2022-05-24 10:00', 'retorno', 'Avaliação do coração para a fila de transplante', 140, 84, 66, 77.2, 'Avaliação cardiológica de rotina para inscrição em lista de transplante renal. Sem angina, sem dispneia. Exame cardiovascular sem estase jugular, sem sopros, pulmões limpos. ECO: HVE concêntrica moderada (septo 14 mm), FEVE 56%, sem valvopatia relevante. Teste de isquemia sem alterações. PA pré-diálise 140x84, pós 124x76 nas últimas semanas, na meta para o dialítico.', 'Sem contraindicação cardiológica para a lista de transplante. Manter peso seco, anlodipino e carvedilol. Controle de lipídios com estatina baixa dose. Retorno em 12 meses.');
