insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (273, '2022-05-24', 'estavel', 'HAS volume-dependente de paciente em hemodiálise, controlada com ajuste do peso seco, restrição de sal e líquidos e dois anti-hipertensivos. HVE moderada com função sistólica preservada, liberado para a lista de transplante renal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (274, 'Wellington Souza Carneiro', 'M', '1983-02-08', 'São Luís', 'MA', 'Pintor autônomo', 'Sabia ser hipertenso desde os 33 anos, mas nunca fez tratamento contínuo ("só tomava quando sentia dor de cabeça"). Tabagista de 20 cigarros ao dia. Sem exames recentes. Mãe com doença renal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (924, 274, 6, '2023-08-12 05:20', 'pronto_socorro', 'Dor de cabeça forte, vista embaçada e vômitos', 248, 152, 98, 79.0, 'Homem de 40 anos com cefaleia occipital intensa há 3 dias, turvação visual progressiva, náuseas e vômitos, urina escassa e espumosa. PA 248x152 confirmada nos dois braços. Sonolento mas orientado, sem déficit focal. Fundoscopia: hemorragias em chama de vela, exsudatos algodonosos e papiledema (retinopatia grau IV). Edema periorbitário e de MMII. Creatinina 3,8 mg/dL (sem exame prévio), ureia 142, K 5,4. Urina com proteinúria e hematúria. HD: hipertensão maligna com LRA e retinopatia grave.', 'Internar na UTI. Iniciar nitroprussiato de sódio em bomba com meta de redução de 20 a 25% da PA na primeira hora, depois redução gradual em 24 a 48 h. Solicitar USG renal, ECO e coleta de culturas se febre. Nefrologia avisada.'),
  (925, 274, 14, '2023-08-14 09:30', 'internacao', 'Evolução na UTI', 156, 96, 84, 77.5, 'Terceiro dia de UTI. PA reduzida gradualmente de 248x152 para 156x96, nitroprussiato desmamado e substituído por anlodipino, carvedilol e hidralazina VO. Cefaleia e vômitos resolvidos, visão ainda borrada. Creatinina 4,2 no pico, hoje 3,6, diurese 1.600 mL/24h sem diálise. USG renal: rins de tamanho normal-reduzido, ecogenicidade aumentada. ECO: HVE concêntrica, FEVE 54%. Sem hemólise. Sorologias e complementos normais.', 'Manter vasodilatadores orais, evitar IECA/BRA enquanto LRA instável. Restringir sal. Pedir renina e aldosterona, metanefrinas e Doppler de artérias renais para excluir causa secundária. Alta da UTI para enfermaria e depois seguimento com nefrologia.'),
  (926, 274, 8, '2023-09-20 14:00', 'retorno', 'Visão ainda ruim e urina espumosa', 150, 94, 80, 76.0, 'Alta hospitalar há 3 semanas. PA domiciliar em torno de 150/92. Creatinina 2,6 mg/dL (TFGe 29), proteinúria de 24h 2,1 g. Doppler de renais normal, aldosterona/renina e metanefrinas normais, sorologias negativas. Sem biópsia por rins pequenos. Parou de fumar após o susto, "nunca mais quero passar por aquilo". Oftalmologia: atrofia óptica parcial e hemorragias em reabsorção.', 'Associar furosemida 40 mg 12/12h (volume e perda de função). Reintroduzir losartana 25 mg com monitorização rigorosa de K e creatinina em 1 semana, dado a proteinúria. Manter os demais. Dieta com sal < 4 g. Retorno mensal.'),
  (927, 274, 8, '2024-02-13 14:20', 'retorno', 'Consulta de acompanhamento do rim', 138, 86, 74, 75.2, 'Seis meses da crise. PA 138x86 com cinco fármacos. Creatinina 3,1 mg/dL (TFGe 24), K 4,9, proteinúria 1,8 g/24h. Persistência de comprometimento visual (acuidade 20/60 bilateral). Paciente com doença renal crônica estágio 4 secundária à nefroesclerose hipertensiva maligna, não recuperou função renal. Começa a pintar apenas esporadicamente por dificuldade visual.', 'Manter esquema anti-hipertensivo. Orientar o preparo para terapia renal substitutiva: educação sobre diálise e avaliação de acesso vascular. Evitar nefrotóxicos. Retorno em 2 meses com exames.');
