insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (274, '2024-02-13', 'piorou', 'Hipertensão maligna após anos sem tratamento, com LRA e retinopatia grau IV. A PA foi controlada, mas ficou com doença renal crônica estágio 4 (TFGe 24), proteinúria persistente e baixa visual permanente. Em preparo para terapia renal substitutiva.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (275, 'Cleide Maria Rufino Gadelha', 'F', '1963-09-17', 'Iguatu', 'CE', 'Cozinheira de restaurante', 'HAS há 12 anos, dislipidemia, obesidade grau I. Menopausa aos 49 anos. Mãe com infarto aos 61 anos. Fica em pé 9 horas por dia na cozinha, come bem e muito.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (928, 275, 1, '2022-09-13 14:00', 'consulta', 'Dor no peito quando carrego panela pesada', 148, 88, 84, 84.0, 'Paciente de 59 anos com 3 meses de dor retroesternal em aperto, aos esforços como carregar panelas ou subir rampa, durando 5 minutos e cedendo com repouso. Sem dor em repouso. Exame com PA 148x88, sem sopros, sem edema. ECG de repouso normal. LDL 152 mg/dL em uso irregular de sinvastatina. Angina estável, CCS II, probabilidade pré-teste intermediária-alta.', 'Iniciar AAS 100 mg, atorvastatina 40 mg, metoprolol succinato 50 mg e anlodipino 5 mg. Solicitar teste ergométrico e ECO. Orientações de perda de peso. Nitrato SN. Retorno com exames.'),
  (929, 275, 1, '2022-10-25 14:10', 'retorno', 'Trouxe os exames e o resultado do cateterismo', 134, 80, 62, 83.0, 'Teste ergométrico com alterações de ST duvidosas, angina leve em 7 minutos, capacidade funcional reduzida. Cintilografia com isquemia leve em parede anterior. Coronariografia: DA média com lesão de 60% e FFR 0,86 (não significativa), Cx 50% e CD 40%, FEVE 62%. Doença coronariana não obstrutiva funcionalmente significativa. Dor melhorou com BB, crises 1 vez por semana.', 'Tratamento clínico otimizado: manter AAS, atorvastatina, metoprolol e anlodipino, acrescentar mononitrato de isossorbida 20 mg 12/12h para os dias de maior esforço na cozinha. Reabilitação. Retorno em 6 meses.'),
  (930, 275, 1, '2023-04-11 14:00', 'retorno', 'Dor no peito quase não vem mais', 126, 76, 58, 78.2, 'Perdeu 5,8 kg em 6 meses com reeducação alimentar e caminhadas. Angina muito rara, CCS I, só em esforços extremos. Usa nitrato SN uma vez a cada 2 meses. LDL 61 mg/dL. FC 58 com metoprolol. Sem edema ou tonturas.', 'Manter tratamento clínico. Meta de LDL < 55: aumentar atorvastatina para 80 mg. Manter demais. Seguir exercício. Retorno em 6 meses. Reavaliar com novo teste se piora dos sintomas.');
