insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (275, '2023-04-11', 'estavel', 'Angina estável com doença coronariana sem lesão funcionalmente significativa ao cateterismo, tratada clinicamente. Com perda de peso e tratamento otimizado, tem angina rara, LDL próximo da meta e segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (276, 'Osvaldo Martins Pires', 'M', '1950-05-23', 'Campo Grande', 'MS', 'Pecuarista aposentado', 'IAM de parede anterior em 2018 sem revascularização, evoluiu com ICFEr. HAS e DM2 (insulina há 2 anos). Ex-tabagista (40 maços-ano, parou em 2018). Em uso de enalapril 20 mg 12/12h, carvedilol 12,5 mg 12/12h e furosemida 40 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (931, 276, 11, '2023-01-24 10:00', 'consulta', 'Cansaço para tudo e dormindo sentado', 118, 72, 76, 86.8, 'Paciente de 72 anos, ICFEr isquêmica, CF III apesar de enalapril 20 mg 12/12h e carvedilol 12,5 mg 12/12h. Ortopneia, dispneia ao tomar banho e edema de MMII 2+/4+. ECO: FEVE 30%, acinesia anterior, VE dilatado. NT-proBNP 3.100 pg/mL. K 4,4, creatinina 1,3 (TFGe 55). Falta espironolactona e iSGLT2, sacubitril/valsartana não utilizado.', 'Suspender enalapril; após 36 h iniciar sacubitril/valsartana 49/51 mg 12/12h. Aumentar carvedilol para 25 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Reduzir insulina em 20% (risco de hipoglicemia) e orientar. K e creatinina em 1 semana.'),
  (932, 276, 11, '2023-03-28 10:10', 'retorno', 'Estou conseguindo dormir deitado', 106, 64, 62, 82.4, 'Perdeu 4,4 kg, sem ortopneia, edema mínimo, CF II. Tontura leve ao levantar nas primeiras semanas, já melhor. K 4,9 e creatinina 1,4 em controle de 4 semanas, sem hipoglicemias após redução da insulina. FC 62, PA 106x64, sem hipotensão sintomática.', 'Manter os quatro pilares nas doses atuais. Reduzir furosemida para 20 mg. Controle de K em 1 mês. Solicitar ECO em 6 meses para reavaliar FEVE e discutir CDI se persistir ≤ 35%.'),
  (933, 276, 11, '2023-10-17 10:00', 'retorno', 'Voltei a cavalgar um pouco', 112, 68, 60, 81.0, 'Nove meses de terapia otimizada. CF I-II, sem internações. Volta a ir à fazenda dos filhos e a cavalgar devagar. ECO de controle: FEVE 40% (era 30%), remodelamento reverso com DDVE 61 mm. NT-proBNP 780 pg/mL. K 4,8, creatinina 1,3. Sem tontura. Insulina em dose menor, HbA1c 7,1%.', 'FEVE acima de 35%: dispensa indicação de CDI neste momento. Manter os quatro pilares em doses atuais. Vacinação anual. ECO em 12 meses. Retorno em 4 meses.');
