insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (276, '2023-10-17', 'melhorou', 'ICFEr isquêmica otimizada com os quatro pilares. A FEVE subiu de 30 para 40%, NT-proBNP caiu de 3.100 para 780, classe funcional I-II e sem internações. Mantém acompanhamento a cada 4 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (277, 'Rita de Cássia Oliveira Pontes', 'F', '1948-12-10', 'Piripiri', 'PI', 'Aposentada', 'HAS há 20 anos em uso de losartana. Palpitações ocasionais nunca investigadas. Nunca fumou. Mora com a neta, caminha todos os dias até a igreja.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (934, 277, 6, '2021-03-09 07:45', 'pronto_socorro', 'Perdeu a força do lado direito e não consegue falar direito', 178, 98, 124, 63.0, 'Idosa de 72 anos trazida pela neta, com início súbito às 06h10 (a neta a viu bem às 06h00) de hemiparesia direita, desvio de rima e afasia. NIHSS 14. Glicemia capilar 118. Pulso irregular, FC 124. ECG: fibrilação atrial. TC de crânio sem sangramento e sem sinais precoces extensos. Dentro da janela de 4,5 h, sem anticoagulante em uso. PA 178x98 (< 185x110 para trombólise). HD: AVC isquêmico cardioembólico por FA não diagnosticada.', 'Código AVC acionado: neurologia avisada. Alteplase EV 0,9 mg/kg (10% em bolus, restante em 1 hora), controle de PA < 180/105. Angiotomografia: oclusão de M1 esquerda, discutida trombectomia. Transferência para UTI/unidade de AVC.'),
  (935, 277, 13, '2021-03-10 08:00', 'internacao', 'Evolução na unidade de AVC', 150, 86, 92, 63.0, 'Após trombólise e trombectomia mecânica com recanalização TICI 2b, NIHSS caiu de 14 para 8. Sem sangramento intracraniano na TC de 24 h, apenas infarto subcortical esquerdo em evolução. Afasia motora ainda importante, hemiparesia direita grau III. FA controlada com metoprolol, FC 92. ECO transtorácico: AE 52 mm, FEVE 55%, sem trombo. Sem disfagia ao teste da água após fonoaudiologia.', 'Iniciar anticoagulação com apixabana 5 mg 12/12h no sétimo dia (infarto moderado), conforme TC de controle. Antes, AAS 100 mg apenas após 24 h de trombólise. Fisioterapia, fonoaudiologia e terapia ocupacional. Estatina em alta potência. Controle da PA.'),
  (936, 277, 13, '2021-04-27 09:00', 'retorno', 'Primeira consulta depois da alta', 138, 82, 74, 60.5, 'Seis semanas pós-AVC, em fisioterapia três vezes por semana e fonoaudiologia. NIHSS 4: hemiparesia direita leve a moderada (força grau 4 no membro superior), anda com bengala, fala frases curtas com disartria. Em uso de apixabana 5 mg 12/12h desde o 7º dia, sem sangramentos. Sem crises convulsivas. Humor deprimido, chora com facilidade.', 'Manter apixabana (suspender AAS). Manter reabilitação intensiva. Avaliar depressão pós-AVC com psicologia, considerar sertralina. Controle de PA < 130/80, estatina de alta potência. Retorno em 4 meses.'),
  (937, 277, 4, '2022-03-15 10:00', 'retorno', 'Consulta anual do coração', 132, 78, 70, 59.8, 'Um ano pós-AVC. FA permanente, FC 70 com metoprolol. Mantém apixabana com boa adesão, a neta organiza os comprimidos. Sequela: hemiparesia direita leve, anda com bengala, afasia leve com disartria, depende da neta para banho e remédios (Rankin 3). Humor melhor com sertralina. Sem novo evento isquêmico ou sangramentos. Hb 12,1, creatinina 0,9.', 'Manter anticoagulação vitalícia (CHA2DS2-VASc 6). Manter demais medicamentos. Reavaliar dose de apixabana se creatinina ≥ 1,5 ou idade ≥ 80. Continuar fisioterapia domiciliar. Retorno em 6 meses.');
