insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (277, '2022-03-15', 'piorou', 'AVC isquêmico cardioembólico por FA nunca anticoagulada, com sequelas permanentes: hemiparesia direita, afasia leve e dependência parcial (Rankin 3). Agora anticoagulada, sem novos eventos, em reabilitação e com acompanhamento neurológico e cardiológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (278, 'Joana D''Arc Medeiros Cunha', 'F', '1972-04-04', 'Belém', 'PA', 'Auxiliar de enfermagem', 'Febre reumática na infância com cardite, profilaxia secundária interrompida na adolescência. Dois partos normais. Nunca fumou. Trabalha em plantões noturnos em hospital municipal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (938, 278, 1, '2022-05-10 09:00', 'consulta', 'Cansaço e coração acelerado nos plantões', 118, 74, 108, 64.0, 'Paciente de 50 anos com 8 meses de dispneia progressiva (CF III), palpitações e tosse noturna. Pulso irregular. Ausculta: B1 hiperfonética, estalido de abertura mitral e ruflar diastólico em foco mitral com reforço pré-sistólico ausente. ECG: fibrilação atrial, FC 108. ECO: estenose mitral reumática com área valvar 1,0 cm² (PHT), gradiente médio 12 mmHg, PSAP 55 mmHg, AE 52 mm, sem trombo. Estenose mitral grave com FA.', 'Iniciar varfarina 5 mg ao dia com alvo de INR 2,0-3,0 (DOACs contraindicados na estenose mitral moderada a grave). Metoprolol succinato 50 mg para FC. Furosemida 20 mg. Reiniciar penicilina benzatina. Avaliar valvuloplastia percutânea. Controle de INR semanal.'),
  (939, 278, 1, '2022-07-26 09:00', 'retorno', 'Melhor da falta de ar, mas ainda canso', 114, 70, 78, 63.2, 'Dez semanas de tratamento. INR 2,4 na última medida, dose estável de varfarina 5 mg com ajuste de 7,5 mg aos sábados. FC 78 em FA. Sem sangramentos. Dispneia CF II-III. Raio X com sinais de congestão leve. Aceita valvuloplastia. Score de Wilkins 7 na avaliação ecocardiográfica, sem trombo em AE no ETE e IM leve, favorável.', 'Encaminhar para valvuloplastia mitral percutânea por balão. Manter varfarina até o procedimento, INR alvo no dia < 2,5. Manter betabloqueador e diurético. Retorno após o procedimento.'),
  (940, 278, 10, '2022-09-20 07:30', 'internacao', 'Valvuloplastia mitral percutânea', 112, 68, 82, 63.0, 'INR 1,9 no dia, ETE sem trombo. Valvuloplastia mitral por balão (técnica de Inoue) com punção transeptal, balão de 26 mm. Área valvar passou de 1,0 para 1,9 cm², gradiente médio de 12 para 4 mmHg, PSAP 55 para 38. Insuficiência mitral discreta pós-procedimento (1+/4+). Sem derrame pericárdico ou embolia. Alta no segundo dia.', 'Retomar varfarina na mesma noite, INR em 1 semana, alvo 2,0-3,0 enquanto estiver em FA. Manter penicilina benzatina a cada 21 dias. Reduzir furosemida se mantiver sem edema. ECO de controle em 30 dias.'),
  (941, 278, 1, '2023-02-14 09:00', 'retorno', 'Estou trabalhando de novo sem falta de ar', 110, 68, 70, 64.5, 'Quase 5 meses da valvuloplastia. CF I, voltou aos plantões. FA persistente, FC 70. INR 2,6 (dentro do alvo na maioria das medidas, com mapa de controle na UBS). ECO: área mitral 1,8 cm², gradiente 5 mmHg, PSAP 34, IM discreta estável. Sem sangramentos nem eventos embólicos.', 'Manter varfarina com INR 2,0-3,0, metoprolol e penicilina benzatina profilática (mantida por tempo prolongado pelo acometimento valvar). ECO anual. Retorno em 6 meses.');
