insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (278, '2023-02-14', 'melhorou', 'Estenose mitral reumática grave com FA tratada com varfarina e valvuloplastia por balão. A área valvar passou de 1,0 para 1,8 cm², sem dispneia, de volta aos plantões e mantendo INR no alvo, em profilaxia secundária da febre reumática.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (279, 'Joaquim Armando Pacheco Vieira', 'M', '1941-10-28', 'Fortaleza', 'CE', 'Aposentado (ex-contador)', 'HAS há 30 anos em uso de anlodipino e losartana. Hiperplasia prostática. Duas quedas recentes atribuídas a tonturas. Viúvo, mora com a filha. Jogava dominó todo dia até o último mês.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (942, 279, 4, '2022-08-19 10:00', 'consulta', 'Quase desmaio e muito cansaço', 168, 72, 38, 71.0, 'Paciente de 80 anos com 3 semanas de tonturas, cansaço aos pequenos esforços e um episódio de síncope em casa, sem convulsão. Pulso regular e lento, 38 bpm, ondas A em canhão no pescoço. ECG: bloqueio atrioventricular total com escape ventricular a 38 bpm, QRS 118 ms. PA sistólica elevada, 168x72, em padrão de HAS sistólica do idoso e bradicardia. Sem uso de betabloqueador nem digoxina. K 4,6, TSH normal. HD: BAVT idiopático degenerativo.', 'Internar hoje para implante de marca-passo definitivo. Monitorização contínua, atropina disponível. Não prescrever bradicardizantes. Jejum a partir de agora.'),
  (943, 279, 4, '2022-08-22 08:00', 'internacao', 'Implante de marca-passo definitivo', 150, 78, 70, 71.0, 'Marca-passo provisório transvenoso na admissão, sem síncopes. Hoje implante de marca-passo definitivo dupla-câmara por veia cefálica esquerda, sob anestesia local e sedação leve. Limiares ventriculares 0,5 V a 0,4 ms, onda R de 11 mV. Sem pneumotórax, sem hematoma de loja. FC 70 estimulada. Deambulando no dia seguinte, sem tontura.', 'Antibioticoprofilaxia pós-procedimento por 24 h. Limitar elevação do braço esquerdo por 4 semanas. Carteira do dispositivo e orientações sobre ressonância e aparelhos eletromagnéticos. Controle em 30 dias. Retornar ao PS se febre, dor local intensa ou síncope.'),
  (944, 279, 4, '2022-10-04 09:30', 'retorno', 'Estou voltando ao dominó', 140, 76, 68, 72.5, 'Sete semanas do implante. Sem tontura, sem síncope, caminha 30 minutos com a filha e voltou a jogar dominó na praça. Ferida cicatrizada sem hematoma. Interrogação do marca-passo: funcionamento normal, 92% de estimulação ventricular, sem arritmias atriais registradas, bateria estimada em 10 anos. PA 140x76.', 'Manter anlodipino e losartana (PA aceitável para a idade e histórico de quedas, meta flexibilizada em < 140/80). Controles do dispositivo a cada 6 meses. Retorno em 6 meses.');
