insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (279, '2022-10-04', 'melhorou', 'BAVT degenerativo em idoso de 80 anos com síncope, resolvido com marca-passo dupla-câmara. Sem tontura ou quedas, de volta às atividades sociais, dispositivo funcionando normalmente e PA aceitável em uso de dois anti-hipertensivos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (280, 'Expedito Alves Rodrigues', 'M', '1959-06-14', 'Bom Jesus', 'PI', 'Vaqueiro', 'Doença de Chagas conhecida desde 2008, nunca fez acompanhamento regular. Palpitações e desmaio ao correr atrás do gado. Pai morreu subitamente aos 52 anos. Tabagismo leve, cachaça nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (945, 280, 11, '2020-06-09 09:30', 'consulta', 'Cansaço e palpitação', 112, 70, 54, 68.0, 'Vaqueiro de 61 anos com palpitações em crises e dois episódios de pré-síncope no último mês, além de cansaço crescente (CF II-III). Sorologia reagente para Chagas. ECG: BRD + HBAE, ESV polimórficas. ECO: FEVE 35%, dilatação de VE, aneurisma apical. Holter: 6.800 ESV/24h e 5 episódios de TV não sustentada de 8 a 14 batimentos. Escore de Rassi alto (risco de morte súbita). Sem indicação de benznidazol em cardiopatia chagásica já instalada.', 'Iniciar amiodarona 200 mg ao dia, enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h e espironolactona 25 mg. Discutir CDI para prevenção primária pelo alto risco. Pedir RM cardíaca se disponível. Evitar esforços intensos. Retorno em 8 semanas.'),
  (946, 280, 4, '2020-09-22 08:00', 'internacao', 'Implante de CDI', 108, 68, 56, 68.4, 'Mantém TV não sustentada no Holter apesar da amiodarona e novo episódio de pré-síncope no mês passado. Após discussão em equipe e com a família, indicado CDI. Realizado implante de CDI unicâmara, sem intercorrências, limiares adequados, teste de indução com TV sustentada revertida por choque de 25 J. Alta no segundo dia.', 'Programação: ATP seguido de choque para TV acima de 180 bpm. Manter amiodarona e tratamento de IC. Evitar esforço físico intenso e proximidade de ímãs ou cercas elétricas do gado. Orientações sobre choque: ligar para o serviço se mais de um choque. Controle em 30 dias.'),
  (947, 280, 4, '2021-07-13 09:00', 'retorno', 'O aparelho me deu choque duas vezes', 104, 66, 58, 66.0, 'Dois choques apropriados (um em março e outro em junho) durante esforço no trabalho, ambos para TV monomórfica rápida confirmada na interrogação, ambos com recuperação sem perda de consciência após o segundo. Cansaço crescente (CF III), edema de tornozelos 1+/4+, peso -2 kg, NT-proBNP 2.800. Voltou a trabalhar com gado apesar do aviso. FEVE 28% ao ECO.', 'Manter amiodarona 200 mg e acrescentar furosemida 40 mg e dapagliflozina 10 mg. Aumentar carvedilol a 12,5 mg 12/12h conforme FC. Orientado a afastar-se da lida com gado, solicitei laudo para o INSS. Retorno em 2 meses.'),
  (948, 280, 6, '2022-01-18 03:20', 'pronto_socorro', 'O aparelho deu choque várias vezes seguidas', 88, 54, 142, 65.0, 'Trazido pela família de caminhonete a 90 km, após 7 choques do CDI em 3 horas, assustado e dispneico. Na chegada, PA 88x54, FC 142, extremidades frias, SpO2 91%, estertores bibasais. Monitor com TV monomórfica recorrente interrompida por choques. HD: tempestade elétrica em chagásico com CDI e ICFEr descompensada, em baixo débito.', 'Amiodarona EV 150 mg em bolus e manutenção, sedação com midazolam, correção de K e Mg, evitar betabloqueador EV pelo baixo débito. O2 suplementar. Transferência para UTI com cardiologia. Família informada do risco elevado de óbito.'),
  (949, 280, 14, '2022-01-20 09:00', 'internacao', 'Evolução na UTI', 82, 50, 118, 64.0, 'Terceiro dia de UTI. Novas recorrências de TV a cada poucas horas apesar de amiodarona, lidocaína e sedação profunda; CDI com choques adicionais. Choque cardiogênico com lactato 5,8, creatinina 2,4 e piora da congestão. FEVE 18%. Iniciada noradrenalina e dobutamina. Candidato a ablação de TV ou assistência ventricular não disponível no serviço, sem vaga de transferência. Reunião com família sobre prognóstico muito reservado.', 'Manter suporte inotrópico e vasopressor, antiarrítmicos e sedação. Solicitada transferência para centro com ablação de TV, sem vaga. Conforto e presença da família. Combinada limitação de suporte caso nova parada.');
