insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (280, '2022-01-24', 'obito', 'Faleceu na UTI por choque cardiogênico refratário após tempestade elétrica em cardiopatia chagásica avançada, apesar do CDI, amiodarona e suporte intensivo. Teve seguimento irregular e retomou a lida com gado após os primeiros choques.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (281, 'Neide Aparecida Fujimoto', 'F', '1968-02-02', 'Londrina', 'PR', 'Contadora', 'HAS há 9 anos com três anti-hipertensivos, obesidade grau II, DLP. Sedentária, trabalha sentada 10 horas por dia e belisca doces o dia todo. Pai japonês-brasileiro com HAS e AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (950, 281, 2, '2021-03-16 15:30', 'consulta', 'Quero emagrecer e tomar menos remédio', 148, 92, 80, 98.4, 'Mulher de 53 anos, IMC 36,5, circunferência abdominal 112 cm. Em uso de losartana 50 mg 12/12h, anlodipino 5 mg e hidroclorotiazida 25 mg com PA 148x92, inchaço de tornozelos e ganho de peso de 15 kg em 5 anos. Quer sair dos remédios. Exame sem sopros, pulmões limpos, edema discreto. Glicemia de jejum 104, LDL 138, ácido úrico 7,4. Entendeu que perda de peso é o tratamento mais efetivo da pressão dela.', 'Manter os três fármacos por ora. Encaminhar à nutricionista e iniciar programa de caminhada supervisionada 3x/semana. Meta: perder 10% do peso em 6 meses. Reavaliar a necessidade de cada remédio a cada 3 meses. Retorno em 5 meses com MRPA.'),
  (951, 281, 2, '2022-02-08 15:30', 'retorno', 'Perdi 14 quilos', 118, 72, 68, 84.4, 'Em 11 meses perdeu 14 kg com acompanhamento nutricional (déficit calórico, corte de açúcar e ultraprocessados) e caminhada de 40 minutos 4x por semana. PA de consultório 118x72 e MRPA média 114x70, com tonturas leves ao levantar e cãibras. Potássio 3,4 mEq/L e ácido úrico 6,6 sob tiazida. Edema de tornozelos desapareceu.', 'Suspender hidroclorotiazida (hipocalemia e PA baixa). Manter losartana e anlodipino por ora. Orientar ingestão de frutas ricas em potássio. Recheck de K em 4 semanas. Se PA seguir < 115/70, retirar anlodipino. Retorno em 4 meses.'),
  (952, 281, 2, '2022-12-13 15:00', 'retorno', 'Pressão boa, posso diminuir de novo?', 116, 70, 64, 76.5, 'Perdeu um total de 22 kg em 21 meses, IMC 29,5. Potássio normalizado em 4,3 após retirar a tiazida. PA 116x70, MRPA média 112x68, sem edema e sem sintomas. Boa adesão ao exercício, "agora tenho prazer de caminhar". Glicemia 92, LDL 112, ácido úrico 5,8.', 'Suspender anlodipino. Manter losartana 50 mg uma vez ao dia, reduzindo da dose anterior de 12/12h. MRPA em 4 semanas; se > 130/80, retomar dose anterior. Manter nutricionista. Retorno em 4 meses.');
