insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (281, '2023-04-18', 'controlado', 'A perda de 22 kg permitiu reduzir a medicação de três fármacos para um, losartana 50 mg ao dia, mantendo PA em torno de 115x70. Foi mantido o programa de exercício e acompanhamento nutricional.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (282, 'Antônia Lindalva Sales Girão', 'F', '1967-09-25', 'Quixeramobim', 'CE', 'Agricultora', 'HAS há 6 anos, obesidade grau III, em uso de losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg. Mora na zona rural, pega o ônibus 2h para consultar. Mãe diabética e hipertensa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (953, 282, 1, '2020-11-03 09:00', 'consulta', 'Encaminhada porque a pressão não baixa', 186, 110, 88, 104.0, 'Paciente de 53 anos, encaminhada da UBS como HAS resistente (PA 180-190/110 com três fármacos). Adesão confirmada pela filha. Circunferência do braço 41 cm; na UBS medem com manguito comum (adulto) que subestima o ajuste do braço e superestima a PA. Aqui, primeira medida com manguito padrão 186x110, sem sintomas. Fica muito tensa em consulta ("treme tudo quando vejo jaleco"). Exame físico sem sopros, sem massas, sem sinais de lesão de órgão-alvo. HD: pseudorresistência por técnica inadequada e provável efeito do avental branco.', 'Usar manguito largo para obesos (circunferência 42-50 cm) em todas as medidas. Solicitar MAPA de 24 h e MRPA com aparelho e manguito adequados. Manter medicações até o resultado. Pedir exames de rotina.'),
  (954, 282, 1, '2020-12-15 09:10', 'retorno', 'Trouxe a MAPA', 154, 94, 80, 103.2, 'Com manguito largo, a PA de consultório foi 154x94 (32 mmHg abaixo da anterior). MAPA de 24h com manguito adequado: média 122x74, vigília 126x78, sono 112x66, descenso preservado. Ou seja, normotensa fora do consultório sob três fármacos: hipertensão controlada com efeito do avental branco, não resistente. Ela tem tonturas leves em casa à tarde.', 'Reduzir esquema: suspender hidroclorotiazida e reduzir losartana para 50 mg 12/12h, mantendo anlodipino 10 mg. Repetir MRPA em 4 semanas. Importante: nunca decidir pela medida de consultório isolada. Orientar perda de peso, encaminhar à nutrição.'),
  (955, 282, 1, '2021-06-08 09:00', 'retorno', 'A tontura passou', 138, 84, 76, 99.8, 'Seis meses do ajuste. Tontura sumiu. PA no consultório 138x84 com manguito correto, MRPA com média 124x76 em casa. Perdeu 4,2 kg. Sem edema de tornozelos. O posto de saúde recebeu manguito largo e passou a medir corretamente. Já não faz uso de hidroclorotiazida e relata se sentir "mais leve".', 'Manter losartana e anlodipino. Manter manguito largo em todas as aferições, registrado na ficha. MRPA como referência de controle. Retorno em 6 meses.');
