insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (282, '2021-06-08', 'controlado', 'Pseudorresistência: a PA era superestimada por manguito pequeno para o braço de 41 cm e pelo efeito do avental branco. Confirmado pela MAPA, o esquema foi reduzido de três para dois fármacos, com PA domiciliar na meta.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (283, 'Camila Vitória Souza Bandeira', 'F', '1993-07-07', 'Recife', 'PE', 'Designer gráfica', 'Usa anticoncepcional oral combinado (etinilestradiol 30 mcg + drospirenona 3 mg) há 3 anos. PA normal em consultas até 2020. Sem tabagismo, atividade física regular. Mãe hipertensa tardia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (956, 283, 1, '2023-05-09 16:00', 'consulta', 'Pressão alta descoberta na farmácia', 156, 98, 76, 66.0, 'Mulher de 29 anos, assintomática, com PA 150-160/95-100 em medidas em farmácia e no consultório, há 4 meses. Usa ACO combinado há 3 anos. MRPA com média 152x96. IMC 23, sem sopros abdominais, pulsos femorais normais. Investigação de HAS secundária por idade < 30: aldosterona/renina normais, TSH normal, creatinina 0,7, urina I normal, Doppler de renais sem estenose. Impressão: HAS induzida por anticoncepcional oral combinado.', 'Suspender o ACO combinado e orientar método contraceptivo sem estrogênio (DIU de levonorgestrel ou DIU de cobre) com a ginecologia. Sem anti-hipertensivos por ora. MEV, restringir sal. Nova MRPA em 8 semanas. Retorno em 10 semanas.'),
  (957, 283, 1, '2023-07-18 16:00', 'retorno', 'Parei a pílula, vim ver a pressão', 122, 76, 72, 65.4, 'Suspendeu o ACO há 9 semanas e colocou DIU de levonorgestrel. PA 122x76 no consultório e MRPA média 120x74, sem uso de nenhum anti-hipertensivo. Sem sintomas. Retomou corrida de 5 km, 3 vezes por semana. Entendeu que a pressão alta era efeito do hormônio.', 'Sem anti-hipertensivo. Anotar na ficha a restrição a ACO combinado. Repetir PA em 6 meses e anualmente. Orientada a avisar qualquer médico sobre isso antes de nova prescrição de estrogênio.'),
  (958, 283, 1, '2024-01-23 17:00', 'teleconsulta', 'Seguimento por telefone', 118, 74, null, null, 'Teleconsulta de seguimento. Seis meses sem ACO, assintomática. PA domiciliar informada com aparelho validado: média de 118x74 nos últimos 14 dias, sem picos. Adaptada ao DIU, sem sangramento anormal. Mantém exercício e dieta com pouco sal. Sem dor torácica, cefaleia ou palpitações.', 'HAS associada a ACO considerada resolvida. Controle anual da PA com a clínica médica. Não usar contraceptivos com estrogênio. Alta do ambulatório de cardiologia.');
