insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (283, '2024-01-23', 'controlado', 'Hipertensão secundária ao anticoncepcional oral combinado, resolvida após a suspensão do estrogênio e troca por DIU de levonorgestrel. PA normal sem medicação em seguimento de oito meses. Recebeu alta do ambulatório.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (284, 'Eliseu Barbosa Mourão', 'M', '1964-01-30', 'Pedreiras', 'MA', 'Pedreiro', 'HAS sem tratamento regular, "só tomo remédio quando sinto a cabeça pesando". Tabagista de 30 maços-ano e etilismo importante nos fins de semana. Sem exames de rotina. Pai faleceu de AVC aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (959, 284, 6, '2023-11-04 17:40', 'pronto_socorro', 'Dor de cabeça muito forte e braço esquerdo mole', 238, 130, 88, 82.0, 'Homem de 59 anos, trabalhando na obra quando teve cefaleia súbita e intensa, seguida de vômitos, queda do braço esquerdo e desvio da rima labial. Glasgow 13, hemiparesia esquerda grau 2, disartria. PA 238x130. Glicemia capilar 134. TC de crânio sem contraste: hematoma intraparenquimatoso nos núcleos da base à direita, volume estimado de 28 mL, com discreto desvio de linha média e sem hemoventrículo. HD: AVC hemorrágico hipertensivo.', 'Nicardipina EV em bomba, meta de PAS entre 130 e 150 mmHg (redução rápida, sem queda abaixo de 130). Cabeceira a 30º, controle glicêmico. Contraindicado antitrombótico. Neurocirurgia e neurologia acionadas. Transferência para UTI.'),
  (960, 284, 14, '2023-11-05 10:00', 'internacao', 'Evolução na UTI', 148, 86, 80, 82.0, 'Primeiro dia de UTI. PAS mantida entre 140 e 150 com nicardipina, em transição para anti-hipertensivos orais. Glasgow 14, hemiparesia esquerda grau 2 estável, sem novos vômitos. TC de 24 h: hematoma estável em 29 mL, sem expansão. Teste de deglutição reprovado, sonda nasoenteral. Sem indicação cirúrgica, pelo tamanho e boa evolução clínica.', 'Iniciar anlodipino 10 mg e losartana 50 mg via sonda. Manter sonda e fonoaudiologia. Profilaxia mecânica de TVP. Evitar antitrombóticos. Neurologia para seguimento. Reabilitação precoce.'),
  (961, 284, 13, '2023-12-15 09:00', 'retorno', 'Quero voltar a andar sozinho', 138, 84, 72, 79.4, 'Alta hospitalar há 3 semanas. Hemiparesia faciobraquiocrural esquerda residual (força grau 3 no braço, grau 4 na perna), anda com ajuda de andador, disartria leve. Deglutição liberada. Sem crises convulsivas. Parou de fumar e de beber. Esposa administra os remédios. PA 138x84. TC de controle com reabsorção parcial do hematoma. Rankin 3.', 'Manter fisioterapia e terapia ocupacional intensivas. Adicionar clortalidona 12,5 mg para alcançar meta < 130/80. Reavaliar em 3 meses. Investigar causas secundárias de HAS (idade 59 sem outros fatores). Retorno em 3 meses.'),
  (962, 284, 1, '2024-06-18 14:00', 'retorno', 'Consulta de seguimento da pressão', 126, 78, 70, 80.0, 'Sete meses do AVC. PA 126x78, MRPA com média 124x76. Sequela motora estável: anda com bengala, não consegue retornar à construção civil, afastado pelo INSS. Humor deprimido, pouco ânimo. Aldosterona/renina e metanefrinas normais, Doppler de renais sem estenose. Excluída causa secundária.', 'Manter anlodipino, losartana e clortalidona. Encaminhar à psicologia/psiquiatria. Seguir reabilitação. Retorno em 6 meses.');
