insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (284, '2024-06-18', 'piorou', 'AVC hemorrágico hipertensivo causado por crise hipertensiva em HAS não tratada. Sobreviveu, mas ficou com hemiparesia esquerda e incapacidade para o trabalho de pedreiro. PA hoje controlada com três fármacos, sem tabaco ou álcool.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (285, 'Moacir Antunes Ferraz', 'M', '1956-08-22', 'Porto Alegre', 'RS', 'Motorista de táxi aposentado', 'DM2 há 14 anos em uso de metformina e gliclazida, HAS, dislipidemia, ex-tabagista (40 maços-ano, parou há 8 anos). Angina de esforço havia 2 meses atribuída a "gases". Irmão faleceu de infarto aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (963, 285, 6, '2022-04-12 21:00', 'pronto_socorro', 'Dor no peito em repouso desde a tarde', 160, 92, 84, 88.0, 'Paciente de 65 anos com angina em crescendo nas últimas 2 semanas e hoje 3 episódios de dor em repouso de 15 min, com sudorese. Sem dispneia. Exame: PA 160x92, B4, sem sopros, pulmões limpos. ECG: inversão simétrica de onda T em V2-V4, sem supra. Troponina de alta sensibilidade negativa em 0 e 3 h. HD: angina instável em diabético com alto risco.', 'AAS 300 mg, clopidogrel 300 mg, enoxaparina, atorvastatina 80 mg, metoprolol e nitrato. Internação em unidade coronariana. Cateterismo em até 48 h. Suspender metformina se contraste.'),
  (964, 285, 10, '2022-04-14 10:00', 'internacao', 'Cateterismo', 138, 80, 66, 88.0, 'Sem dor desde a admissão. Coronariografia: lesão de tronco de coronária esquerda de 50%, DA proximal 80%, Cx proximal 90% e CD ocluída crônica com circulação colateral da DA. FEVE 52%. DM2 e doença triarterial com tronco: SYNTAX score 34. Heart team decide por revascularização cirúrgica, superior à angioplastia nesse perfil.', 'Manter AAS, estatina e betabloqueador, suspender clopidogrel 5 dias antes da cirurgia. Encaminhar para cirurgia cardíaca em 10 a 14 dias. Controle glicêmico com insulina na internação. Orientações pré-operatórias.'),
  (965, 285, 12, '2022-04-27 07:00', 'internacao', 'Cirurgia de revascularização', 130, 76, 68, 87.5, 'Cirurgia de revascularização miocárdica com circulação extracorpórea, 3 enxertos: artéria mamária interna esquerda para DA, safena para ramo marginal da Cx e safena para descendente posterior da CD. Tempo de CEC 78 min, pinçamento 52 min, sem intercorrências. Extubado em 6 h, drenos retirados no 2º dia, FA pós-operatória transitória no 3º dia revertida com amiodarona. Alta da UTI no 3º dia, alta hospitalar no 7º.', 'AAS 100 mg e estatina, metoprolol. Amiodarona por 6 semanas. Reabilitação cardíaca após 30 dias. Fisioterapia respiratória e cuidados com ferida esternal e da perna. Retorno em 6 semanas.'),
  (966, 285, 1, '2022-07-12 10:30', 'retorno', 'Estou me sentindo outra pessoa', 124, 72, 60, 84.6, 'Três meses da cirurgia. Sem angina, sem dispneia. Ferida esternal e da safena cicatrizadas. Reabilitação cardíaca 3x por semana há 6 semanas, caminha 5 km. Perdeu 3,4 kg. Amiodarona suspensa, ritmo sinusal ao ECG. LDL 54 mg/dL, HbA1c 6,9%. Sem tosse ou queixas medicamentosas. PA 124x72.', 'Manter AAS, atorvastatina 80 mg, metoprolol e metformina. Iniciar empagliflozina 10 mg pelo benefício cardiovascular no diabético. Reabilitação até 12 semanas. Retorno em 6 meses com teste ergométrico.');
