insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (285, '2022-07-12', 'melhorou', 'Angina instável com doença triarterial e lesão de tronco, tratada com revascularização cirúrgica de três enxertos. Três meses depois está sem angina, em reabilitação, com LDL e HbA1c na meta e em ritmo sinusal.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (286, 'Francisca Zuleide Aguiar Pinto', 'F', '1946-09-29', 'Tianguá', 'CE', 'Aposentada (ex-agricultora)', 'HAS há 35 anos, tratada de forma irregular. Doença renal crônica leve (TFGe 55). Dispneia progressiva há 1 ano. Mora com o filho, que a traz às consultas de moto. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (967, 286, 11, '2021-08-24 10:00', 'consulta', 'Falta de ar e pernas inchadas', 156, 88, 92, 62.0, 'Paciente de 74 anos com dispneia aos pequenos esforços (CF III), ortopneia e edema de MMII 3+/4+. Estase jugular, B3, estertores até terço médio. PA 156x88. ECO: ICFEr por cardiopatia hipertensiva, FEVE 30%, HVE e VE dilatado. NT-proBNP 5.600. Creatinina 1,2 (TFGe 55), K 4,6. Sem uso prévio de medicações de IC. HD: ICFEr descompensada, hipertensiva.', 'Furosemida 40 mg 12/12h inicial. Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h após euvolemia. Dapagliflozina 10 mg. Espironolactona 25 mg só depois de dosar K em 1 semana. Orientações de peso diário e sal. Retorno em 3 semanas.'),
  (968, 286, 11, '2021-11-02 10:00', 'retorno', 'Já posso andar na rua sem parar', 124, 72, 68, 56.4, 'Perdeu 5,6 kg e voltou a deitar sem travesseiros extras. CF II. Edema residual discreto. Tolerou enalapril e carvedilol. Espironolactona 25 mg iniciada há 4 semanas com K 5,3 em exame de 1 semana, mantida com controle. Hoje K 5,5 e creatinina 1,5. Sem fraqueza ou alteração do ECG.', 'Manter espironolactona 25 mg, reduzir enalapril para 5 mg ao dia, orientar dieta pobre em potássio e evitar suplementos. Repetir K e creatinina em 2 semanas. Retorno em 5 meses.'),
  (969, 286, 11, '2022-04-19 10:30', 'retorno', 'Fraqueza nas pernas e coração devagar', 110, 66, 52, 57.0, 'Fraqueza muscular e palpitações há 5 dias. Chegou com atraso de 5 meses ao retorno (o filho perdeu a moto, ficou sem como trazer). Potássio 6,1 mEq/L, creatinina 1,8. ECG: bradicardia sinusal com T apiculadas. Estava tomando espironolactona 25 mg, enalapril e suplemento de pó de banana "para dar força". Sem sinais de congestão. Hipercalemia moderada associada a espironolactona + IECA + DRC.', 'Suspender espironolactona e o suplemento. Gluconato de cálcio, insulina com glicose e resina trocadora no PS ambulatorial, com repetição do K em 6 horas. Manter enalapril 5 mg/dia e dapagliflozina. K e creatinina em 1 semana. Retorno em 2 semanas. Orientada a retornar ao PS se piorar a fraqueza.');
