insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (286, '2022-12-15', 'abandonou', 'ICFEr hipertensiva compensada com tratamento, mas o seguimento foi prejudicado por distância e falta de transporte. Após o episódio de hipercalemia não retornou nas consultas agendadas e a equipe da UBS não conseguiu contato; o último registro é de abril de 2022.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (287, 'Sebastião Lopes Andrade Filho', 'M', '1960-07-15', 'Altos', 'PI', 'Mecânico', 'IAM com stent farmacológico em 2018, HAS, DM2. Tabagista até o infarto. Ex-etilista. Faz uso diário de AAS 100 mg desde o stent e de rivaroxabana desde o diagnóstico de FA há 2 anos. Dor epigástrica ocasional tratada com antiácidos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (970, 287, 4, '2022-02-08 09:00', 'consulta', 'Revisão da FA e dos remédios', 136, 82, 74, 84.0, 'Homem de 61 anos, FA persistente controlada com metoprolol, anticoagulado com rivaroxabana 20 mg e ainda em uso de AAS 100 mg desde o stent de 2018. CHA2DS2-VASc 4 (HAS, DM2, DAC/IAM prévio). Mais de 3 anos do stent, estável, sem angina. Tem dor epigástrica ocasional e queixa de pequenas equimoses. Hb 13,8. HAS-BLED 3. Não há mais indicação de manter AAS com anticoagulante, associação aumenta sangramento.', 'Orientar suspender o AAS e manter apenas rivaroxabana. Paciente prefere manter o AAS por "medo do infarto"; combinado reavaliar no próximo retorno. Iniciar omeprazol 20 mg. Orientado sobre sinais de sangramento. Retorno em 4 meses.'),
  (971, 287, 6, '2022-06-14 23:50', 'pronto_socorro', 'Fezes pretas e fraqueza forte', 92, 58, 116, 82.0, 'Há 2 dias com melena (3 episódios) e fraqueza intensa, hoje com tontura ao levantar e quase desmaiou. Pálido, sudoreico, extremidades frias. PA 92x58, FC 116 irregular (FA). Hb 7,4 g/dL (13,8 em fevereiro). Ureia elevada. Sem hematêmese. Em uso de rivaroxabana e AAS, sem AINE. HD: hemorragia digestiva alta com repercussão hemodinâmica, associada à anticoagulação e antiagregação.', 'Suspender rivaroxabana e AAS. Dois acessos calibrosos, cristaloide e transfusão de 2 concentrados de hemácias, omeprazol EV 80 mg. EDA em 12 h. Internar em enfermaria de clínica médica. Reversão específica (andexanet) não necessária pela estabilização.'),
  (972, 287, 3, '2022-06-16 10:00', 'internacao', 'Evolução após endoscopia', 118, 72, 88, 82.0, 'Após 2 concentrados de hemácias, Hb 9,2 g/dL, hemodinamicamente estável, sem novos episódios de melena. EDA realizada: úlcera duodenal em bulbo de 10 mm com vaso visível (Forrest IIa), tratada com injeção de adrenalina e clipes hemostáticos, pesquisa de H. pylori positiva. Mantido em jejum 24 h, inibidor de bomba em dose alta. Cardiologia consultada para o plano antitrombótico.', 'Tratar H. pylori com esquema de 14 dias. Pantoprazol 40 mg 12/12h por 8 semanas. Suspender o AAS definitivamente; anticoagulante retorna em 7 dias se não ressangrar, com troca para apixabana (menor risco GI). Hemograma seriado. Alta prevista em 3 dias.'),
  (973, 287, 4, '2022-09-27 09:00', 'retorno', 'Voltei a trabalhar e estou me sentindo bem', 132, 80, 70, 84.5, 'Três meses do sangramento. Sem melena, Hb 13,2. H. pylori erradicado, EDA de controle com cicatrização da úlcera. Anticoagulado com apixabana 5 mg 12/12h desde 1 semana após a alta, sem AAS. FA persistente, FC 70 com metoprolol. Entendeu que "o AAS junto não protegia mais, só sangrava". Sem angina.', 'Manter apixabana 5 mg 12/12h isolada, sem AAS. Manter pantoprazol 40 mg por 3 meses e depois suspender. Estatina e metoprolol. Doença coronariana estável, sem indicação de antiagregante. Hemograma em 3 meses. Retorno em 6 meses.');
