insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (287, '2022-09-27', 'melhorou', 'Hemorragia digestiva alta por úlcera duodenal em paciente com FA usando rivaroxabana e AAS. Após transfusão, tratamento endoscópico, erradicação do H. pylori, suspensão do AAS e troca por apixabana, recuperou a hemoglobina e voltou ao trabalho sem novo sangramento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (288, 'Isabela Cristina Wanderley Maia', 'F', '2000-03-03', 'Salvador', 'BA', 'Estudante de Direito', 'Palpitações desde os 15 anos, atribuídas a ansiedade. Sem uso de medicamentos. Nega drogas, bebe esporadicamente. Sem história familiar de morte súbita.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (974, 288, 4, '2022-03-21 15:00', 'consulta', 'Crises de palpitação durante provas', 108, 66, 82, 55.0, 'Jovem de 22 anos com crises de palpitação regulares, início súbito, 150-200 bpm, que cessam abruptamente, 3 episódios no último ano, o último há 3 semanas durante uma prova. Exame normal. ECG de repouso: PR curto (100 ms), onda delta positiva em V1-V2 e QRS alargado de 130 ms, padrão de pré-excitação ventricular (Wolff-Parkinson-White). ECO normal. Sem histórico de FA ou síncope.', 'Evitar drogas AV nodais (verapamil, digoxina) em caso de FA pré-excitada. Discutir ablação por cateter. Em crise: procurar PS. Teste ergométrico e Holter para estratificar risco. Retorno em 4 semanas.'),
  (975, 288, 6, '2022-04-30 22:30', 'pronto_socorro', 'Coração disparou e não passa', 98, 62, 206, 55.0, 'Crise de taquicardia há 50 min com palpitações, tontura e dor precordial leve. Estável, PA 98x62. ECG: taquicardia regular de QRS estreito a 206 bpm, sem onda P distinguível, sem pré-excitação durante a taquicardia (AVRT ortodrômica). Valsalva modificada sem resposta. HD: taquicardia por reentrada AV em portadora de via acessória.', 'Adenosina 6 mg EV sem resposta, repetida 12 mg com reversão para ritmo sinusal, com onda delta reaparecendo no ECG. Alta com encaminhamento prioritário para ablação eletiva. Evitar verapamil. Retornar se nova crise > 20 min.'),
  (976, 288, 4, '2022-06-14 07:00', 'internacao', 'Ablação programada', 110, 68, 76, 54.8, 'Estudo eletrofisiológico sob anestesia geral: via acessória lateral esquerda com condução anterógrada e retrógrada, período refratário anterógrado de 280 ms (risco intermediário), AVRT ortodrômica induzida com isoproterenol. Ablação por radiofrequência por acesso transeptal com desaparecimento da pré-excitação em 4 segundos. Sem recorrência após 30 min de observação e adenosina. Sem complicações.', 'Repouso de 6 h. Alta no mesmo dia ou na manhã seguinte. Sem medicamentos. Retorno em 8 semanas com ECG. Liberada para atividades normais em uma semana.'),
  (977, 288, 4, '2022-08-30 15:30', 'retorno', 'Sem crises desde o procedimento', 106, 64, 70, 55.4, 'Dois meses da ablação, sem palpitações e sem uso de medicação. Voltou à academia e fez as provas do semestre sem crises, "a ansiedade era do meu coração, não da minha cabeça". ECG: ritmo sinusal, PR 150 ms, sem onda delta, QRS 90 ms.', 'Alta do ambulatório de arritmia, sem restrições. Retorno apenas se sintomas. Orientada a levar o ECG sempre que procurar atendimento e a informar que fez ablação para WPW.');
