insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (288, '2022-08-30', 'melhorou', 'Wolff-Parkinson-White com taquicardias recorrentes, tratada com ablação por radiofrequência da via acessória lateral esquerda. Sem crises, sem pré-excitação ao ECG e sem medicação, recebeu alta do ambulatório de arritmia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (289, 'Genival Pereira dos Santos', 'M', '1967-10-10', 'Santa Inês', 'MA', 'Vendedor ambulante', 'Etilismo crônico: cerca de meia garrafa de cachaça por dia há 25 anos. Tabagista. Má alimentação, perda de peso nos últimos meses. Sem HAS ou DM conhecidos. Nenhum acompanhamento médico anterior.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (978, 289, 11, '2022-10-04 08:30', 'consulta', 'Cansaço, barriga inchada e pernas grossas', 104, 68, 108, 61.0, 'Paciente de 54 anos, com 4 meses de dispneia progressiva, ortopneia, edema de MMII 3+/4+ e aumento do volume abdominal. Desnutrido, mucosas descoradas ++/4+. FC 108 regular, estase jugular a 45º, B3, estertores bibasais, hepatomegalia dolorosa. ECO: miocardiopatia dilatada com FEVE 26% e DDVE 70 mm. Angiotomografia de coronárias sem lesões obstrutivas. TSH normal, sorologias para Chagas e HIV negativas, ferritina normal. HD: cardiomiopatia alcoólica com ICFEr descompensada.', 'Abstinência alcoólica total como parte essencial do tratamento. Tiamina 300 mg/dia e ácido fólico. Furosemida 40 mg 12/12h, enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg e dapagliflozina 10 mg. Encaminhar ao CAPS-AD. Retorno em 3 semanas.'),
  (979, 289, 11, '2023-01-24 08:30', 'retorno', 'Estou sem beber há três meses', 112, 70, 80, 64.8, 'Abstinente desde a primeira consulta, com apoio do CAPS-AD e da esposa que o acompanha. Perdeu o edema, ganhou 3,8 kg de massa magra, dorme deitado. CF II. Teve uma recaída leve em dezembro (dois dias de bebida), logo interrompida. FC 80 com carvedilol. K 4,8, creatinina 1,0. Refere ainda tontura ao levantar rápido.', 'Aumentar carvedilol para 6,25 mg 12/12h e enalapril para 10 mg 12/12h, conforme PA. Manter demais fármacos. Reforçar acompanhamento no CAPS. ECO em 6 meses. Retorno em 3 meses.'),
  (980, 289, 11, '2023-08-22 08:40', 'retorno', 'Voltei a vender e não canso', 116, 72, 64, 69.2, 'Dez meses de abstinência confirmada pela esposa e GGT normal. Voltou a trabalhar como ambulante, caminha o dia inteiro sem falta de ar, CF I. ECO: FEVE 44% (de 26%), DDVE 60 mm, com regressão da insuficiência mitral para discreta. NT-proBNP 310. Sem edema, ganhou 8 kg desde o início. Sem fumar há 6 meses.', 'Manter abstinência total (recaída pode levar à perda da recuperação). Manter enalapril, carvedilol, espironolactona e dapagliflozina; suspender furosemida e tiamina. ECO em 6 meses. Retorno em 4 meses.');
