insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (289, '2023-08-22', 'melhorou', 'Cardiomiopatia dilatada alcoólica com FEVE de 26%, revertida parcialmente após abstinência total e tratamento para ICFEr. Em dez meses, a FEVE subiu para 44%, sem edema, NT-proBNP normalizado, e voltou ao trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (290, 'Tânia Mara Borges Leal', 'F', '1985-11-08', 'Campinas', 'SP', 'Enfermeira', 'Saudável, sem comorbidades. Infecção de vias aéreas superiores 10 dias antes do quadro. Corredora recreativa. Uso de anticoncepcional oral combinado. Sem história de doenças autoimunes.', 'Alergia a sulfa (rash cutâneo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (981, 290, 6, '2024-08-20 18:00', 'pronto_socorro', 'Dor no peito que piora quando deito ou respiro fundo', 124, 78, 96, 62.0, 'Mulher de 38 anos com dor precordial pleurítica há 2 dias, em pontada, pior em decúbito e à inspiração profunda, melhora sentada inclinada para frente. Quadro gripal na semana anterior. Febre 37,8. Atrito pericárdico à ausculta, pulmões limpos, sem sinais de congestão. ECG: supradesnivelamento côncavo de ST difuso com infradesnivelamento de PR. Troponina normal. PCR 38. ECO: derrame pericárdico mínimo, sem tamponamento, função preservada. HD: pericardite aguda provavelmente viral.', 'Ibuprofeno 600 mg 8/8h por 2 semanas com redução gradual, omeprazol 20 mg e colchicina 0,5 mg 12/12h por 3 meses para reduzir recorrência. Evitar exercício até resolução. Retorno em 2 semanas.'),
  (982, 290, 1, '2024-09-03 09:00', 'retorno', 'A dor melhorou muito', 116, 72, 72, 62.2, 'Dor praticamente resolvida após 4 dias de tratamento, sem febre. Diarreia leve por colchicina nos primeiros dias, já resolvida. Sem atrito pericárdico à ausculta. PCR caiu para 4 mg/L. ECG com normalização do ST. ECO de controle sem derrame. Pergunta se pode voltar a correr.', 'Reduzir ibuprofeno para 400 mg 8/8h por 1 semana e depois suspender. Manter colchicina 0,5 mg 12/12h até completar 3 meses. Sem exercício intenso por 3 meses por ser pericardite aguda. Retorno em 4 semanas.'),
  (983, 290, 1, '2024-09-26 09:00', 'retorno', 'Tudo bem, sem dor', 114, 70, 68, 62.0, 'Cinco semanas do início, assintomática, sem recorrência após suspender o anti-inflamatório. Voltou ao trabalho no plantão. PCR < 1 mg/L e ECG normal. Sem derrame ao ECO. Mantém colchicina com boa tolerância gastrointestinal, sem diarreia. ECO de controle estável. Faz caminhadas leves, dorme bem e não tem mais dor ao deitar nem ao respirar fundo.', 'Manter colchicina até completar 3 meses (novembro). Retorno em dezembro para alta, ou antes se a dor voltar. Exercício leve liberado, esforço intenso após o término da colchicina.');
