insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (290, '2024-09-26', 'melhorou', 'Pericardite aguda pós-viral com derrame mínimo, tratada com ibuprofeno e colchicina. Dor resolvida em poucos dias, PCR normalizada, sem derrame e sem recorrência. Segue com colchicina até completar três meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (291, 'Valdemir Bezerra Lacerda', 'M', '1980-12-24', 'Russas', 'CE', 'Vendedor de loja de eletrodomésticos', 'Sobrepeso progressivo, sedentário, toma 1 litro de refrigerante por dia e come muito embutido. Pai hipertenso. Nunca fumou. Sem exames de rotina há 5 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (984, 291, 5, '2022-08-02 17:00', 'consulta', 'A enfermeira da empresa disse que minha pressão está no limite', 134, 86, 78, 91.0, 'Homem de 41 anos, assintomático, com PA 134x86 no consultório (média de 3 medidas) e MRPA de 4 dias com média de 132x84. IMC 31,2 e circunferência abdominal de 104 cm. Come fora, sal em excesso e refrigerante. Exame cardiovascular normal. ECG normal. Classificação: pré-hipertensão (120-139/80-89) associada a obesidade, com risco de evoluir para HAS. Sem indicação de medicamento.', 'Tratamento apenas com MEV: dieta com redução de sal e fim do refrigerante, caminhada de 150 min por semana, perda de pelo menos 5 kg. Exames de rotina. Encaminhar para a nutricionista do NASF. Retorno em 3 meses com MRPA.'),
  (985, 291, 5, '2022-11-15 17:00', 'retorno', 'Perdi 5 quilos', 124, 78, 72, 86.2, 'Caminha 30 minutos 4 vezes por semana depois do expediente, trocou o refrigerante por água com gás e limão, passou a levar marmita. Perdeu 4,8 kg. PA 124x78, MRPA com média 122x77. Sente-se disposto, dorme melhor. A esposa passou a cozinhar com menos sal.', 'Manter MEV sem medicação. Meta: mais 5 kg. Repetir MRPA em 6 meses. Reavaliar lipídios em 6 meses. Retorno em 6 meses.'),
  (986, 291, 1, '2023-05-23 17:20', 'retorno', 'Vim fazer a revisão', 120, 76, 68, 83.4, 'Perdeu 7,6 kg em 9 meses, IMC 28. PA 120x76 e MRPA média 118x75, sem nenhum medicamento. Corre 5 km aos domingos. LDL caiu para 112 e glicemia de jejum normalizou em 92. Mantém o hábito da marmita e não voltou ao refrigerante.', 'Normotenso com MEV. Manter hábitos, pesar-se mensalmente. PA anual. Se voltar a ganhar peso e PA ≥ 130/80 repetida, reavaliar. Alta do ambulatório de cardiologia, seguimento na UBS.');
