insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (291, '2023-05-23', 'controlado', 'Pré-hipertensão com obesidade, tratada somente com mudança de estilo de vida. Perdeu 7,6 kg e normalizou a PA e a glicemia sem uso de medicamentos. Recebeu alta para seguimento na UBS, com PA anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (292, 'Jéssica Rayane Alves Monteiro', 'F', '1992-05-16', 'Caucaia', 'CE', 'Gerente de loja', 'HAS crônica desde os 25 anos, em uso de losartana 50 mg 12/12h até descobrir a gestação. Obesidade grau I. Sem diabetes. Mãe com pré-eclâmpsia na gestação dela. Primeira gestação.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (987, 292, 7, '2023-02-14 10:00', 'consulta', 'Estou grávida e sou hipertensa', 138, 88, 84, 84.0, 'Gestante de 30 anos, primigesta, 14 semanas, com HAS crônica. Suspendeu a losartana ao saber da gestação, há 3 semanas, ficou sem tratamento. PA 138x88. Sem sintomas. Proteinúria de 24 h basal de 120 mg e creatinina normal. Risco alto para pré-eclâmpsia (HAS crônica, obesidade, antecedente materno, primigesta).', 'Pré-natal de alto risco. Iniciar metildopa 500 mg 12/12h (losartana contraindicada na gestação), AAS 100 mg à noite desde agora até 36 semanas e cálcio 1,5 g/dia. USG morfológico e Doppler de uterinas. Monitorar PA em casa. Retorno em 4 semanas.'),
  (988, 292, 7, '2023-07-04 10:00', 'consulta', 'Dor de cabeça e inchaço, a pressão não baixa', 164, 108, 92, 92.5, '34 semanas, pré-natal sem intercorrências até 30 semanas, PA em torno de 130/85 com metildopa. Há 5 dias com cefaleia frontal, edema de face e mãos, ganho de 5 kg em 3 semanas. PA 164x108 repetida em 15 min 168x110. Reflexos vivos. Proteinúria de fita 3+, relação proteína/creatinina 1,2. Plaquetas 168.000, TGO 38, creatinina 0,9. BCF 144, feto com crescimento no percentil 15. HD: pré-eclâmpsia superposta à HAS crônica, com sinais de gravidade (PA ≥ 160/110, cefaleia).', 'Internar para resolução. Sulfato de magnésio, nifedipino VO 20 mg e manter metildopa. Betametasona para maturação fetal. Cardiotocografia e perfil fetal. Avaliar indução versus cesárea após corticoide.'),
  (989, 292, 7, '2023-07-06 07:30', 'internacao', 'Evolução e parto', 150, 96, 84, 92.0, 'Dois dias de internação com sulfato de magnésio por 24 h e corticoide completo. PA controlada em torno de 150/95 com nifedipino e metildopa, cefaleia melhorou. Plaquetas 152.000, enzimas normais. Indução do trabalho de parto sem sucesso após 14 h e sinais de sofrimento fetal leve na cardiotocografia, optado por cesárea com 34 semanas e 2 dias. RN feminino, 2.250 g, Apgar 8 e 9, UTI neonatal por prematuridade. Sem hemorragia, PA pós-parto 144x92.', 'Sulfato de magnésio por 24 h pós-parto. Suspender metildopa, manter nifedipino e iniciar enalapril após a primeira semana (compatível com amamentação). AAS e cálcio suspensos. Alta no 4º dia. Retorno em 5 semanas.'),
  (990, 292, 1, '2023-09-12 10:00', 'retorno', 'Consulta do pós-parto e da pressão', 134, 84, 76, 82.4, 'Dois meses do parto. Bebê em casa, com bom ganho de peso, amamentando. Em uso de enalapril 10 mg 12/12h, bem tolerado, sem tosse. PA 134x84, MRPA com média 132x82. Proteinúria de 24 horas regrediu para 150 mg. Perdeu 9,6 kg. Tem consciência de que a HAS crônica volta ao tratamento de longo prazo e de que pode ter nova pré-eclâmpsia.', 'Manter enalapril por ora, ajustar para losartana se parar de amamentar. Planejar contracepção segura (DIU), pois gestações futuras devem ser planejadas, com troca prévia de BRA/IECA por metildopa/nifedipino e AAS desde 12 semanas. Retorno em 3 meses.');
