insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (292, '2023-09-12', 'melhorou', 'Pré-eclâmpsia superposta à HAS crônica com sinais de gravidade aos 34 semanas, resolvida por cesárea. Mãe sem complicações, proteinúria normalizada e PA em controle com enalapril compatível com a amamentação; o bebê prematuro evoluiu bem.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (293, 'Maria Eunice Veloso Brandão', 'F', '1959-03-30', 'Timon', 'MA', 'Professora aposentada', 'Pressão alta "só no médico", há anos. Nunca tratada. Ansiosa com consultas e exames. Sem diabetes, sem tabagismo. Caminha e faz hidroginástica.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (991, 293, 5, '2021-05-18 09:00', 'consulta', 'Minha pressão sempre dá alta no consultório', 160, 96, 88, 66.0, 'Mulher de 62 anos, assintomática. PA de consultório 160x96 na primeira medida e 152x92 na terceira. Refere que em casa mede 120/75 com aparelho de pulso emprestado. Tensão evidente na consulta, "tremo só de ver o aparelho". Exame normal, sem sopros, sem sinais de lesão de órgão-alvo. ECG normal. Suspeita de HAS do avental branco.', 'Não iniciar medicamentos antes de MAPA de 24 h e MRPA com aparelho de braço validado. Orientações para a MRPA: duas medidas manhã e noite, 5 dias. Exames de rotina. Retorno com a MAPA.'),
  (992, 293, 1, '2021-06-29 09:00', 'retorno', 'Trouxe a MAPA e o caderno da pressão', 156, 94, 84, 65.4, 'MAPA de 24 h: média 24h 118x72, vigília 122x76, sono 108x64, descenso noturno preservado. MRPA: média 119x73. Contraste com 156x94 no consultório, diferença de mais de 30 mmHg: HAS do avental branco. Sem lesão de órgão-alvo. Risco cardiovascular baixo no momento. Explicado que não precisa de medicação, mas que o diagnóstico exige seguimento porque pode evoluir para HAS sustentada.', 'Sem medicação. MEV: manter exercícios e baixo sal. Repetir MAPA ou MRPA em 12 meses. Usar a MRPA como referência da PA. Voltar antes se sintomas ou se PA domiciliar acima de 135/85. Retorno em 12 meses.');
