insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (293, '2023-08-30', 'abandonou', 'HAS do avental branco confirmada por MAPA, sem indicação de medicamentos. Não compareceu à MAPA/MRPA de controle em 2022 nem em 2023 e não atendeu aos contatos da UBS; segue sem acompanhamento e sem registro de PA posterior.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (294, 'Aluísio Gomes Teixeira', 'M', '1957-09-14', 'Fortaleza', 'CE', 'Bancário aposentado', 'HAS há 18 anos, em uso irregular de losartana 50 mg e hidroclorotiazida 25 mg. Tabagismo prévio (parou há 10 anos). Apneia suspeita, nunca investigada. Sem diabetes. Dispneia leve aos grandes esforços há 1 ano.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (993, 294, 1, '2021-09-08 10:00', 'consulta', 'Falta de ar quando subo dois lances de escada', 154, 92, 74, 84.0, 'Homem de 64 anos com HAS de longa data e controle ruim. Dispneia aos grandes esforços, sem ortopneia, sem edema. Ausculta com B4 e sem sopros. ECG: SVE com padrão de sobrecarga (strain) em V5-V6. ECO: HVE concêntrica com septo de 15 mm e parede posterior de 14 mm, massa indexada 142 g/m², FEVE 60%, disfunção diastólica grau 1, átrio esquerdo de 40 mm. Cardiopatia hipertensiva com HVE.', 'Otimizar tratamento para regressão de HVE: aumentar losartana para 100 mg ao dia, manter hidroclorotiazida e adicionar anlodipino 5 mg. Restrição de sal e MRPA. Pedir polissonografia pelo ronco. Retorno em 8 semanas.'),
  (994, 294, 1, '2022-01-11 10:00', 'retorno', 'A falta de ar melhorou', 132, 80, 68, 82.0, 'Quatro meses de tratamento regular. Dispneia só em esforços maiores. PA 132x80, MRPA com média 128x78. Polissonografia mostrou apneia leve (IAH 9), sem indicação de CPAP, orientada perda de peso. Sem tosse, sem edema de tornozelo com anlodipino. K 4,2 e creatinina 1,0.', 'Manter o esquema atual. Meta de 130/80 atingida na MRPA. Emagrecimento e exercício. ECO para avaliar regressão da HVE em 12 meses. Retorno em 6 meses.'),
  (995, 294, 1, '2023-01-17 10:00', 'retorno', 'Vim ver o resultado do ecocardiograma', 122, 74, 64, 79.2, 'Mais de um ano de controle da PA, MRPA média 120x74. Assintomático, sobe escadas sem falta de ar. ECO de controle: septo 12 mm, parede posterior 11 mm, massa indexada 104 g/m² (queda de 27%), FEVE 62%, relação E/A normalizada. ECG com redução da voltagem (Sokolow-Lyon 31 mm) e sem strain. Perdeu 4,8 kg.', 'Regressão da HVE com tratamento. Manter losartana, hidroclorotiazida e anlodipino. Exames anuais incluindo potássio e creatinina. ECO a cada 2 anos. Retorno em 6 meses.');
