insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (294, '2023-01-17', 'melhorou', 'Cardiopatia hipertensiva com HVE e disfunção diastólica, tratada com controle estrito da PA. Em 16 meses a massa ventricular caiu 27%, a função diastólica normalizou e a dispneia aos esforços desapareceu.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (295, 'Ivanilde Torres Cordeiro', 'F', '1954-11-21', 'Parnaíba', 'PI', 'Vendedora de tapioca na orla', 'HAS há 15 anos sem acompanhamento, sedentária, ex-tabagista. DM2 não tratado. Trabalha em pé 10 horas por dia, renda diária variável. Viúva, mora com a filha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (996, 295, 6, '2022-11-05 14:30', 'pronto_socorro', 'Dor no peito há 4 horas, muito forte', 170, 100, 102, 78.0, 'Paciente de 67 anos com dor retroesternal em aperto de forte intensidade há 4 horas, com suor frio e náuseas. ECG: supra de ST de 4 mm em V1-V5. Pulmões limpos, sem choque. Troponina alta. O serviço de hemodinâmica fica a mais de 3 horas por transporte. HD: IAMCSST de parede anterior, Killip I, tempo de sintomas 4 h.', 'Terapia fibrinolítica com tenecteplase (dose por peso) após exclusão de contraindicações, AAS 300 mg, clopidogrel 300 mg, enoxaparina. Transferência em ambulância UTI para hemodinâmica (estratégia fármaco-invasiva). Monitorização.'),
  (997, 295, 10, '2022-11-06 09:30', 'internacao', 'Cateterismo após fibrinólise', 138, 84, 76, 78.0, 'Reperfusão clínica com resolução da dor e queda de 70% do supra de ST em 90 min. Coronariografia nas primeiras 24 h: DA proximal com estenose residual de 90% e trombo, CD com 40%, Cx sem lesões. Angioplastia com stent farmacológico em DA com bom resultado (TIMI 3). ECO: FEVE 45% com hipocinesia anterior e apical. Glicemia de 286 e HbA1c 10,2%, diabetes descompensado.', 'Dupla antiagregação (AAS + clopidogrel, ticagrelor evitado por custo) por 12 meses. Betabloqueador, IECA e atorvastatina 80 mg. Iniciar metformina e insulina NPH para controle glicêmico. Educação sobre diabetes. Alta em 3 dias. Retorno em 6 semanas.'),
  (998, 295, 1, '2022-12-20 14:00', 'retorno', 'Vim para a revisão do infarto', 128, 78, 62, 76.0, 'Sem angina, volta ao trabalho com a tapioca em turnos mais curtos. Refere cansaço leve. Glicemia melhor com metformina, HbA1c 8,1%. Preocupada com o custo e o número de remédios: "são muitos comprimidos e os do posto às vezes acabam". PA 128x78, FC 62 com betabloqueador. Sem sangramentos. Orientada sobre importância do clopidogrel por 12 meses.', 'Manter AAS, clopidogrel, atorvastatina, metoprolol e enalapril. Pedir ajuda da assistente social para garantir o fornecimento via SUS. Reabilitação cardíaca em Parnaíba. LDL e HbA1c em 3 meses. Retorno em 3 meses.'),
  (999, 295, 1, '2023-04-11 14:20', 'retorno', 'Parei uns remédios, estava sem dinheiro para vir', 152, 92, 80, 77.5, 'Quatro meses depois, vem após falta a dois retornos. Há 6 semanas suspendeu o clopidogrel e o metoprolol "porque senti fraqueza e achei que já estava curada". Mantém AAS e metformina. Sem angina, mas dispneia aos esforços moderados. PA 152x92. Sem edema. HbA1c 8,9%. Foi explicado o risco de trombose de stent com a suspensão do clopidogrel antes de um ano.', 'Retomar clopidogrel e metoprolol imediatamente. Reforçada a gravidade do risco de trombose do stent e novo infarto. Marcado ECO, lipidograma e retorno em 4 semanas; entregue transporte municipal e carta ao CRAS para auxílio transporte.');
