insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (295, '2023-12-12', 'abandonou', 'IAM de parede anterior tratado com fibrinólise e angioplastia da DA. Após a recuperação inicial, interrompeu medicamentos por custo e falta de transporte. Não compareceu aos retornos marcados após abril de 2023 e a equipe perdeu o contato.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (296, 'Roberto Shimizu Oliveira', 'M', '1962-04-17', 'São Paulo', 'SP', 'Engenheiro civil', 'Revascularização miocárdica em 2014 (mamária esquerda para DA, safenas para Cx e CD). DM2 há 15 anos, HAS, dislipidemia, ex-tabagista. Estresse alto no trabalho, abandonou a reabilitação cardíaca após alguns meses e retomou pouco exercício.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1000, 296, 1, '2021-02-23 11:00', 'consulta', 'A dor no peito voltou', 146, 86, 78, 90.0, 'Paciente de 58 anos, 6 anos de pós-RM, com angina CCS II-III há 2 meses ao subir ladeiras e em situações de estresse, antes ausente. Em uso irregular de estatina, LDL 118. HbA1c 8,6%. Exame sem sopros novos, sem edema. ECG: ondas Q em parede inferior (IAM antigo) sem novas alterações. Teste de esforço positivo para isquemia anterolateral e inferior em 6 minutos. Suspeita de falência de enxerto venoso.', 'Otimizar tratamento clínico (metoprolol, atorvastatina 80 mg, mononitrato de isossorbida, AAS). Cateterismo diagnóstico com enxertos. Controle glicêmico com endocrinologia. Retorno após exame.'),
  (1001, 296, 10, '2021-03-30 07:30', 'internacao', 'Cateterismo e angioplastia de enxerto', 138, 80, 66, 89.5, 'Coronariografia: mamária esquerda para DA pérvia, safena para Cx ocluída, safena para CD com lesão de 80% no terço médio, com sinais de degeneração. Nativas com oclusão crônica. Realizada angioplastia do enxerto de safena para CD com stent farmacológico e proteção embólica distal. Resultado angiográfico excelente. Cx não passível de recanalização. FEVE 50%.', 'Dupla antiagregação (AAS + clopidogrel) por 12 meses. Estatina de alta potência, ezetimiba 10 mg para LDL < 50. Manter betabloqueador. Reabilitação cardíaca. Alta no dia seguinte, retorno em 6 semanas.'),
  (1002, 296, 6, '2021-11-09 02:40', 'pronto_socorro', 'Dor no peito forte que acordou', 110, 70, 96, 90.0, 'Acordou com dor precordial intensa e dispneia, com suor frio. Contou que parou o clopidogrel há 1 mês por causa de sangramento gengival e cansaço. PA 110x70, SpO2 92%, estertores bibasais. ECG: infra de ST de 2 mm em V2-V5. Troponina 12 ng/mL. ECO: hipocinesia anterior extensa, FEVE 38%. HD: IAMSSST com disfunção ventricular e congestão, possível trombose do stent do enxerto.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina, furosemida EV, nitroglicerina EV. Internação em unidade coronariana, cateterismo precoce. Discussão em equipe sobre nova revascularização cirúrgica e riscos.'),
  (1003, 296, 11, '2022-02-15 11:00', 'retorno', 'Cansaço com qualquer esforço', 114, 68, 64, 87.2, 'Três meses do segundo infarto. O cateterismo mostrou nova oclusão do stent de safena para CD (trombose tardia) e DA nativa e mamária com lesões moderadas, sem alvo viável para angioplastia, e a equipe decidiu por tratamento clínico, dada a oclusão difusa. Hoje em IC isquêmica CF III, FEVE 36%, edema leve de tornozelos. NT-proBNP 2.100. Dependente dos medicamentos e preocupado com o trabalho.', 'Iniciar sacubitril/valsartana 24/26 mg 12/12h (suspender losartana, troca direta), espironolactona 25 mg e dapagliflozina 10 mg. Manter AAS e ticagrelor. Avaliar CDI se FEVE ≤ 35% após 3 meses de terapia otimizada. Retorno em 8 semanas.');
