insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (296, '2022-02-15', 'piorou', 'Doença coronariana pós-RM com degeneração de enxertos venosos. Após a angioplastia de safena, suspendeu o clopidogrel por conta própria, teve trombose do stent e novo infarto, evoluindo com ICFEr isquêmica (FEVE 36%) e sem alvo para revascularização.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (297, 'Lourdes Matilde Albuquerque Neri', 'F', '1944-08-13', 'Fortaleza', 'CE', 'Aposentada (ex-comerciante)', 'HAS há 40 anos, DM2 há 20 anos, obesidade, DRC estágio 3b (TFGe 38). ICFEp diagnosticada há 2 anos. Já internou duas vezes por congestão. Mora com uma cuidadora, comorbidades múltiplas.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1004, 297, 11, '2023-05-09 09:00', 'consulta', 'Pernas inchadas e falta de ar para ir ao banheiro', 148, 76, 72, 82.0, 'Paciente de 78 anos com ICFEp, CF III, peso 82 kg (peso seco 76). Edema 2+/4+, estase jugular a 45º, estertores em bases, hepatomegalia. ECO: FEVE 60%, E/e'' 18, átrio esquerdo muito dilatado, PSAP 52. NT-proBNP 4.900. TFGe 38. K 4,8. Tomava ibuprofeno ocasional para dor nos joelhos, orientada a suspender. Múltiplas comorbidades limitam o tratamento.', 'Aumentar furosemida para 80 mg pela manhã. Manter empagliflozina 10 mg e espironolactona 12,5 mg (monitorar K). Suspender ibuprofeno. Controle de sal e líquidos. K e creatinina em 1 semana. Retorno em 3 semanas.'),
  (1005, 297, 6, '2023-10-17 04:00', 'pronto_socorro', 'Acordou sufocada', 196, 102, 110, 84.0, 'Acordou com dispneia súbita, tosse com secreção espumosa. Cuidadora refere que a paciente andava sem seguir a dieta e que tomou os remédios irregularmente na última semana. SpO2 82% em ar ambiente, FR 36, estertores até ápices, edema 3+/4+. PA 196x102. ECG: taquicardia sinusal, SVE. Creatinina 2,1. HD: EAP hipertensivo em ICFEp com DRC.', 'O2 e VNI, furosemida 80 mg EV, nitroglicerina EV para PA elevada, monitorização. Evoluiu com melhora da SpO2 para 94%. Transferida para UTI, sem indicação de intubação. Avaliar ultrafiltração caso falha ao diurético. Conversado com a família sobre a gravidade.'),
  (1006, 297, 11, '2024-02-27 09:30', 'retorno', 'Alta da internação, quero saber como estou', 134, 70, 70, 77.0, 'Após a internação de 12 dias, está em CF III. Peso 77 kg, edema residual leve. Creatinina estável em 1,7 (TFGe 30), K 5,0 limitando a espironolactona, suspensa. Apetite ruim, perda de massa muscular, dependente para banho. Cuidadora organiza os remédios, mas a paciente recusa dieta com pouco sal. ECO: FEVE 58%, PSAP 48. Discutidos cuidados paliativos e metas de cuidado com a filha.', 'Manter furosemida 80 mg e empagliflozina; suspender espironolactona. Conciliar plano de cuidados paliativos e preferências de internação. Peso diário, tolerância a diurético extra com orientação. Retorno em 3 meses.'),
  (1007, 297, 14, '2024-06-04 20:30', 'internacao', 'Internação por pneumonia e descompensação', 92, 50, 118, 74.0, 'Admitida com febre, tosse produtiva e dispneia há 4 dias. Pneumonia comunitária à direita com sepse, hipotensão, lactato 3,6, creatinina 3,2, insuficiência respiratória aguda e congestão associada. Iniciado antibiótico de amplo espectro, ventilação não invasiva, volume cuidadoso e noradrenalina. Evolução com piora da hipoxemia e acidose, sem resposta. Seguindo diretiva combinada com a família, sem intubação.', 'Antibioticoterapia, VNI, noradrenalina, diurético titulado, conforto e analgesia. Mantidas medidas de conforto e presença da filha conforme preferência previamente discutida. Ordem de não intubar e não reanimar documentada.');
