insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (297, '2024-06-11', 'obito', 'Faleceu na UTI aos 79 anos por choque séptico secundário a pneumonia, em paciente com ICFEp avançada, DRC estágio 3b e diabetes, após internação anterior por edema agudo de pulmão. Cuidados de conforto conforme as preferências discutidas com a família.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (298, 'Wagner Luís Teixeira Campos', 'M', '1971-05-05', 'Belo Horizonte', 'MG', 'Motorista de aplicativo', 'HAS há 15 anos com adesão ruim, obesidade grau II, tabagista. Dispneia progressiva nos últimos 8 meses. Pai com IC. Passa 12 horas por dia sentado no carro e come lanches rápidos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1008, 298, 11, '2022-09-13 11:00', 'consulta', 'Falta de ar e cansaço no trabalho', 150, 94, 92, 108.0, 'Homem de 51 anos com dispneia progressiva (CF II-III) e edema vespertino de tornozelos. HAS mal controlada há anos. ECO: dilatação de VE (DDVE 64 mm), FEVE 32%, hipertrofia leve. Coronariografia normal. TSH normal. NT-proBNP 1.800. K 4,5, creatinina 1,1. Etiologia hipertensiva, com álcool excluído. Em uso irregular de enalapril 10 mg 12/12h e hidroclorotiazida.', 'Iniciar tratamento dos quatro pilares: manter enalapril por ora, carvedilol 6,25 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg e furosemida 40 mg. Parar de fumar com reposição de nicotina. Reduzir sal. Retorno em 8 semanas para trocar enalapril por sacubitril/valsartana.'),
  (1009, 298, 11, '2022-11-22 11:00', 'retorno', 'Estou conseguindo trabalhar mais horas', 128, 78, 70, 100.4, 'Perdeu 7,6 kg, quase todo líquido, CF II. Parou de fumar há 6 semanas, com adesivo. K 4,8, creatinina 1,2. PA 128x78, sem hipotensão. Tolera bem. Disponibilidade de sacubitril/valsartana pelo programa estadual confirmada. Pausa de 36 horas do enalapril combinada com ele e a esposa para evitar angioedema.', 'Suspender enalapril; após 36 h iniciar sacubitril/valsartana 24/26 mg 12/12h. Aumentar carvedilol para 12,5 mg 12/12h. Manter demais. K e creatinina em 1 semana. Retorno em 8 semanas.'),
  (1010, 298, 11, '2023-06-06 11:00', 'retorno', 'Estou ótimo, trabalhando normal', 118, 72, 62, 94.2, 'Seis meses após a troca. Sem dispneia, CF I, sem edema. Sem fumar há 8 meses. Perdeu um total de 13,8 kg. ECO de controle: FEVE 45% (era 32%), DDVE 58 mm. NT-proBNP 240. Sem hipotensão, sem tosse, sem angioedema. K 4,9 e creatinina 1,2. Voltou a trabalhar 12 horas por dia.', 'Manter os quatro pilares em doses atuais, aumentar sacubitril/valsartana para 49/51 mg 12/12h, já que a PA permite. Furosemida só se ganho de peso. ECO em 12 meses. Não suspender medicamentos mesmo melhorando. Retorno em 4 meses.');
