insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (298, '2023-06-06', 'melhorou', 'ICFEr por cardiopatia hipertensiva com FEVE de 32%, tratada com os quatro pilares e troca de IECA por sacubitril/valsartana. A FEVE subiu para 45%, NT-proBNP normalizou, parou de fumar e voltou ao trabalho sem sintomas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (299, 'Marlene Cavalcante Dutra', 'F', '1963-02-18', 'Aracati', 'CE', 'Proprietária de pousada', 'HAS há 10 anos, controlada com losartana 50 mg 12/12h. Hipotireoidismo tratado. Sem diabetes. Pratica caminhada. Consome café em excesso para atender hóspedes na madrugada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1011, 299, 4, '2023-03-14 09:00', 'consulta', 'Coração batendo muito rápido há dias', 128, 80, 148, 71.0, 'Mulher de 60 anos com palpitações regulares e cansaço há 6 dias. Hoje FC 148 regular. ECG: flutter atrial típico com condução 2:1 (ondas F em dente de serra em DII, DIII, aVF), frequência atrial de 296 bpm. ECO: FEVE 62%, AE 41 mm. TSH 2,0 em uso de levotiroxina. CHA2DS2-VASc 2 (sexo feminino + HAS). Sem instabilidade hemodinâmica.', 'Iniciar rivaroxabana 20 mg com o jantar e metoprolol succinato 50 mg para controle da FC. Discutir ablação do istmo cavotricúspide, tratamento de primeira escolha para flutter típico. Evitar excesso de café. Retorno em 6 semanas.'),
  (1012, 299, 4, '2023-04-25 09:00', 'retorno', 'Ainda sinto cansaço e o coração acelerado', 122, 76, 98, 70.4, 'Seis semanas de anticoagulação regular. Flutter persiste com FC 98 no betabloqueador (condução 3:1 variável), mas com sintomas de cansaço e intolerância ao esforço, dificultando o trabalho na pousada. Sem sangramentos. Preferiu tentar o procedimento para sair dos remédios e voltar a dormir bem.', 'Agendar ablação por cateter do istmo cavotricúspide. Manter rivaroxabana ininterrupta. Manter metoprolol até o procedimento. Orientações pré-procedimento, jejum de 8 horas.'),
  (1013, 299, 4, '2023-05-30 07:00', 'internacao', 'Ablação do flutter', 124, 74, 96, 70.0, 'Procedimento sob sedação, ETE prévio sem trombo em apêndice atrial esquerdo. Mapeamento mostrou flutter dependente do istmo cavotricúspide, interrompido na primeira aplicação de radiofrequência. Linha de ablação completa com bloqueio bidirecional confirmado. Não foi induzida arritmia ao final. Ritmo sinusal 72 bpm ao término. Sem complicações, alta no mesmo dia.', 'Manter rivaroxabana por pelo menos 2 meses após ablação, depois decidir pelo risco. Suspender metoprolol. Retorno em 3 meses com ECG e Holter para detectar FA. Evitar esforços por 1 semana.'),
  (1014, 299, 4, '2023-08-29 09:00', 'retorno', 'Estou ótima, sem palpitações', 120, 74, 68, 70.8, 'Três meses da ablação, sem palpitações, voltou a atender na pousada normalmente. Holter de 48 h: ritmo sinusal o tempo todo, sem FA, sem recorrência do flutter. ECG sinusal 68 bpm. Sem sangramentos com rivaroxabana. PA 120x74, sem edema, sem tonturas e sem queixas de intolerância ao esforço.', 'Sem recorrência. Com CHA2DS2-VASc 2 e ritmo sinusal sustentado, discutida suspensão da anticoagulação; optado por manter por mais 6 meses e reavaliar com Holter prolongado para excluir FA subclínica. Retorno em 6 meses.');
