insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (299, '2023-08-29', 'controlado', 'Flutter atrial típico tratado com ablação do istmo cavotricúspide, com bloqueio bidirecional. Três meses depois está em ritmo sinusal, sem sintomas e sem recorrência no Holter. Segue anticoagulada e em reavaliação do risco tromboembólico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (300, 'Nelson Tadeu Pagliarini', 'M', '1957-01-09', 'Ribeirão Preto', 'SP', 'Advogado aposentado', 'Sopro cardíaco conhecido há 20 anos, prolapso de valva mitral com insuficiência leve acompanhado de forma esporádica. HAS controlada com valsartana 160 mg. Faz caminhadas e natação. Ex-tabagista.', 'Alergia a contraste iodado (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1015, 300, 1, '2024-02-06 14:00', 'consulta', 'Cansaço na natação e coração acelerado de vez em quando', 130, 74, 82, 79.0, 'Homem de 67 anos com piora progressiva da tolerância ao esforço nos últimos 6 meses, dispneia ao nadar 800 m, antes fazia 2 km. Ausculta com sopro holossistólico 4+/6+ em foco mitral irradiado para axila, B3. ECO: prolapso de folheto posterior (P2) com ruptura de cordoalhas, insuficiência mitral grave excêntrica anterior, vena contracta 8 mm, FEVE 58%, DSVE 42 mm (limítrofe), AE 52 mm, PSAP 48 mmHg. ECG: ritmo sinusal com extrassístoles atriais.', 'Indicada cirurgia da valva mitral (plastia preferencial) pela sintomatologia e sinais de remodelamento. Solicito ETE, cateterismo ou angiotomografia sem contraste iodado dado a alergia. Manter valsartana. Encaminhar para a cirurgia cardiovascular. Retorno em 8 semanas.'),
  (1016, 300, 12, '2024-04-16 10:00', 'retorno', 'Quero saber sobre a cirurgia', 126, 72, 78, 78.5, 'Avaliação cirúrgica. ETE confirma ruptura de cordoalhas de P2, IM grave, anel mitral dilatado 40 mm, boa chance de plastia (tipo II de Carpentier). Coronárias sem lesões em angiotomografia com preparo antialérgico. Risco cirúrgico baixo (STS 0,8%). Vinha com dispneia aos médios esforços (CF II-III) e episódios de palpitação. Discutido acesso minimamente invasivo, que o serviço local não realiza.', 'Indicação de plastia mitral minimamente invasiva em centro de referência. Suspender valsartana 24 h antes. Solicitado encaminhamento para serviço terciário com experiência em plastia mitral robótica/minimamente invasiva. Orientações de higiene oral e profilaxia de endocardite.'),
  (1017, 300, 12, '2024-06-25 10:00', 'retorno', 'Estou cansado e aceitei ir para outro hospital', 122, 70, 88, 77.8, 'Aguardando vaga há 10 semanas. Piorou para CF III, com palpitações mais frequentes e um episódio de FA paroxística documentada (Holter), revertida espontaneamente. FEVE 55%, DSVE 45 mm: aproximando-se do limite para disfunção. AE 56 mm. PSAP 52. Aceita ir para o centro de referência na capital, onde fará plastia minimamente invasiva e provável ablação concomitante de FA.', 'Encaminhamento e transferência definitiva do caso para o serviço terciário de cirurgia valvar, com relatório completo, ECOs e angiotomografia anexados. Iniciar rivaroxabana 20 mg pelo episódio de FA (CHA2DS2-VASc 2). Manter valsartana. Alta do ambulatório local.');
