insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (300, '2024-06-25', 'transferido', 'Insuficiência mitral grave por ruptura de cordoalhas com indicação de plastia valvar. Pela necessidade de técnica minimamente invasiva e pelo surgimento de FA paroxística, foi transferido a serviço terciário de referência em cirurgia valvar, saindo do acompanhamento local.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (301, 'Ingrid Mahlmann Vieira', 'F', '1979-05-12', 'Lages', 'SC', 'Professora de ensino fundamental', 'HAS diagnosticada aos 38 anos, em uso de hidroclorotiazida 25 mg e losartana 50 mg sem controle. Cãibras frequentes e fraqueza há cerca de 1 ano. Nunca fumou, sedentária. Pai hipertenso, falecido de AVC aos 61 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1018, 301, 1, '2022-03-08 08:30', 'consulta', 'Pressão alta e cãibras nas pernas todo dia', 168, 104, 78, 71.6, 'Paciente de 42 anos, professora, hipertensa há 4 anos, relata que a pressão nunca ficou abaixo de 150x95 apesar de tomar os dois remédios direitinho. Queixa-se de cãibras noturnas e de fraqueza ao subir os degraus da escola. Ao exame: BEG, corada, RCR 2T BNF sem sopros, MV+ sem RA, sem edema. Exames trazidos hoje mostram potássio 2,9 mEq/L mesmo sem diarreia ou vômitos. Hipocalemia espontânea com HAS de difícil controle em paciente jovem levanta suspeita de causa secundária, em especial hiperaldosteronismo primário.', 'Suspender hidroclorotiazida, manter losartana. Iniciar cloreto de potássio xarope e repor até K > 4,0. Solicitar aldosterona e renina após correção do potássio, ECG e ECO. Retorno em 5 semanas com resultados.'),
  (1019, 301, 9, '2022-04-19 09:00', 'retorno', 'Vim buscar o resultado dos exames do hormônio', 164, 100, 74, 71.2, 'Retorna com exames. Aldosterona plasmática 42 ng/dL, atividade de renina plasmática suprimida (< 0,6 ng/mL/h), relação aldosterona/renina > 70, com K corrigido para 3,9 na coleta. Quadro compatível com hiperaldosteronismo primário. TC de adrenais: nódulo hipodenso de 1,7 cm na adrenal esquerda, adrenal direita sem alterações. Pcte mantém cãibras leves. Sem sinais de hipercortisolismo no exame físico. Discutido que, pela idade e pela imagem, ela é boa candidata à cura cirúrgica, mas a lateralização precisa ser confirmada.', 'Solicitar cateterismo seletivo de veias adrenais para confirmar lateralização. Enquanto isso, iniciar espironolactona 50 mg/dia, manter anlodipino e suspender o cloreto de potássio. Controle de K e creatinina em 2 semanas.'),
  (1020, 301, 12, '2022-09-20 07:00', 'internacao', 'Internação eletiva para cirurgia da adrenal', 132, 84, 70, 70.5, 'Admitida para adrenalectomia laparoscópica esquerda. Cateterismo seletivo de adrenais (julho) mostrou lateralização à esquerda, índice de lateralização 5,8, sem supressão contralateral. Espironolactona suspensa 4 semanas antes e substituída por anlodipino e doxazosina, K pré-operatório 4,2. Procedimento sem intercorrências, 90 minutos, sangramento mínimo. Anatomopatológico: adenoma cortical de 1,7 cm. Pós-operatório sem hipotensão, K 4,5 no 1º dia, alta no 2º dia deambulando e com dieta liberada.', 'Alta hospitalar com analgesia simples. Suspender anlodipino se PA < 120/80 em casa. Dosar K, creatinina e aldosterona em 6 semanas. Retorno ambulatorial em 45 dias.'),
  (1021, 301, 1, '2022-11-10 10:15', 'retorno', 'Estou bem, as cãibras sumiram', 122, 76, 68, 69.8, 'Seis semanas de pós-operatório. Sem cãibras, voltou a dar aula. Parou o anlodipino há 3 semanas por conta própria depois de medir 110x70 em casa. PA no consultório 122x76. Exames: K 4,4 mEq/L, aldosterona 4 ng/dL, renina normalizada. Cicatrizes em bom aspecto. Compatível com cura bioquímica e clínica do hiperaldosteronismo primário. Orientada quanto à necessidade de vigilância da PA, já que parte dos operados mantém hipertensão residual.', 'Sem anti-hipertensivos. MRPA por 5 dias a cada 6 meses e K anual. Manter MEV, reduzir sal. Alta do ambulatório de endócrino; seguimento com cardiologia semestral.');
