insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (301, '2023-05-16', 'melhorou', 'Cura do hiperaldosteronismo primário após adrenalectomia esquerda. Na última revisão, a PA ficou em 118x74 mmHg sem nenhum anti-hipertensivo, com potássio normal e sem cãibras. Segue com MRPA semestral e controle laboratorial anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (302, 'Vinícius Zanotto Bertolini', 'M', '1984-11-03', 'Caxias do Sul', 'RS', 'Analista de sistemas', 'Sem diagnóstico prévio de HAS. Sobrepeso, trabalha 10 horas sentado, come fora de casa na maioria dos dias. Ingere 2 a 3 doses de destilado nos fins de semana. Ex-fumante há 6 anos. Pai e avô paternos hipertensos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1022, 302, 5, '2023-02-14 18:20', 'consulta', 'Medi a pressão na farmácia e deu 15 por 10', 152, 98, 80, 96.4, 'Homem de 38 anos, procurou a unidade após aferições alteradas na farmácia (150x96 e 148x94). Assintomático. IMC 31,2. Refere dieta com muito embutido e salgadinho, nenhuma atividade física. Ao exame: PA 152x98 no braço direito, 150x96 no esquerdo, após 5 min de repouso e manguito adequado. Ausculta cardíaca e pulmonar normais, pulsos simétricos, sem edemas. HD: hipertensão arterial estágio 1, a confirmar com MAPA. Orientado sobre MEV; recusa medicação por ora.', 'Solicitar MAPA 24h, perfil lipídico, glicemia, creatinina, potássio, EAS, ECG. Orientações: dieta com restrição de sódio, caminhadas 150 min/semana, reduzir álcool. Retorno com exames em 30 dias.'),
  (1023, 302, 1, '2023-03-20 18:00', 'retorno', 'Trouxe a MAPA e os exames', 148, 94, 78, 95.8, 'MAPA de 24h: média 144x91 na vigília e 128x80 no sono, descenso noturno preservado, sem eventos. Confirma hipertensão estágio 1. Laboratório: LDL 148, glicemia 96, creatinina 0,9, K 4,3, EAS normal. ECG com ritmo sinusal e sem sinais de HVE. Perdeu 600 g em um mês, mas manteve a rotina de restaurante. Risco cardiovascular baixo a moderado; mesmo assim, com HAS confirmada e IMC > 30, optei por iniciar tratamento medicamentoso associado à MEV.', 'Iniciar losartana 50 mg uma vez ao dia, titular para 100 mg se PA acima da meta. Registrar MRPA por 5 dias antes do retorno. Nutricionista e meta de 5 kg em 3 meses. Retorno em 60 dias.'),
  (1024, 302, 1, '2023-09-12 19:10', 'retorno', 'Vim mostrar a pressão de casa', 124, 78, 72, 88.1, 'Pcte retorna com MRPA de 5 dias: média 122x76. Perdeu 8 kg desde o início, entrou numa academia perto do trabalho e leva marmita três vezes por semana. Sem efeitos adversos com losartana. Relata: “nunca imaginei que o sal fizesse tanta diferença”. Exame físico sem alterações. Creatinina 0,9 e K 4,2. Meta atingida com dose baixa.', 'Manter losartana 50 mg/dia. Se mantiver o peso por 6 meses, discutir tentativa de retirada gradual. Perfil lipídico em 6 meses. Retorno em 6 meses.');
