insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (302, '2023-09-12', 'controlado', 'Hipertensão estágio 1 confirmada por MAPA e hoje controlada: MRPA média 122x76 mmHg com losartana 50 mg e perda de 8 kg com MEV. Segue em acompanhamento semestral, com possibilidade de retirada do fármaco se o peso se mantiver.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (303, 'Leocádia Borowski Kunz', 'F', '1952-02-27', 'Chapecó', 'SC', 'Agricultora aposentada', 'HAS há mais de 20 anos, DLP. Usava anlodipino 5 mg e losartana 50 mg, mas parou ambos há 3 semanas porque terminou o medicamento e a filha, que buscava na unidade, estava viajando. Nunca fez ECO. Sedentária, usa sal à vontade na comida.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1025, 303, 6, '2023-01-09 03:10', 'pronto_socorro', 'Falta de ar muito forte, não consigo deitar', 238, 126, 112, null, 'Pcte 70a trazida pela filha com dispneia súbita há 2h, ortopneia, tosse com expectoração rósea. REG, sudoreica, taquipneica FR 34, SatO2 82% em ar ambiente. RCR 3T com B3, MV com estertores crepitantes até ápices bilaterais. PA 238x126, FC 112. Sem dor torácica. ECG: taquicardia sinusal, SVE com strain, sem supra de ST. Troponina 1ª amostra 0,04 (limite 0,03). RX com congestão e cefalização. HD: EAP hipertensivo por suspensão de anti-hipertensivos.', 'O2 por máscara com reservatório, VNI (CPAP), nitroglicerina IV em bomba com titulação, furosemida 40 mg IV, monitorização contínua, repetir troponina em 3h. Vaga em UTI solicitada.'),
  (1026, 303, 14, '2023-01-09 09:00', 'internacao', 'Internação em UTI por edema agudo de pulmão', 156, 88, 92, 74.0, 'Em UTI após 6h de VNI e nitroglicerina, com queda da PA para 156x88, SatO2 96% em cateter nasal 2 L/min, diurese de 1.800 mL com furosemida. Troponina 2ª e 3ª amostras estáveis em 0,04, afastando IAM, mantida como lesão por estresse hipertensivo. Creatinina 1,3, K 4,0. ECO à beira leito: HVE concêntrica importante, FEVE 62%, disfunção diastólica grau 2, sem estenose aórtica. Iniciado anlodipino e losartana por via oral no 2º dia, desmame da nitroglicerina. Alta da UTI em 48h e do hospital em 5 dias, euvolêmica.', 'Alta com anlodipino, losartana e furosemida em dose baixa. Orientação detalhada à filha sobre adesão, pillbox semanal, restrição de sal e pesagem diária. Cardiologia em 15 dias.'),
  (1027, 303, 1, '2023-01-25 14:00', 'retorno', 'Consulta depois do hospital, estou respirando bem', 142, 84, 76, 71.8, 'Retorna 16 dias após alta, sem dispneia, dorme com 1 travesseiro. A filha comprou um organizador de comprimidos e aprendeu a medir a pressão. Peso de alta 72,6 kg, hoje 71,8. Ao exame: sem estase jugular, MV+ sem RA, RCR 2T B4, sem edema. Creatinina 1,2 e K 4,4. PA ainda acima da meta, mas satisfatória para a fase inicial.', 'Manter esquema. Aumentar losartana para 100 mg/dia se PA domiciliar > 140x90 em 2 semanas. Retornos mensais por 3 meses. Reforçar que não deve interromper os remédios, mesmo sem sintomas.');
