insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (303, '2023-01-25', 'melhorou', 'Recuperada do edema agudo de pulmão hipertensivo, com alta em 5 dias, FEVE preservada e hipertrofia ventricular. Segue com anti-hipertensivos e organizador semanal organizado pela filha, em retornos mensais para ajuste de dose.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (304, 'Raquel Albuquerque Tenório', 'F', '1997-08-19', 'Caruaru', 'PE', 'Auxiliar administrativa', 'Primigesta, 36 semanas por DUM e ultrassom precoce. Sem hipertensão prévia. Pré-natal iniciado com 12 semanas, 7 consultas. Obesidade grau 1 prévia à gestação. Mãe com pré-eclâmpsia na primeira gestação.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1028, 304, 7, '2024-03-04 10:30', 'consulta', 'Dor de cabeça e inchaço nos pés nesta semana', 146, 94, 88, 84.5, 'Gestante de 34 semanas, 26 anos, ganho de 3 kg em 3 semanas. Refere cefaleia frontal intermitente e edema de MMII e mãos. PA 146x94, confirmada após 15 min (144x92). Sem escotomas, epigastralgia ou perda de líquido. Movimentos fetais presentes, BCF 142 bpm, altura uterina 33 cm. Fita urinária com proteinúria 1+. HD: pré-eclâmpsia, a esclarecer se com sinais de gravidade. Orientada a internar para observação, mas recusou e voltou para casa por não ter com quem deixar a casa.', 'Solicitados hemograma, plaquetas, TGO/TGP, DHL, creatinina, ácido úrico e proteinúria de 24h. Iniciar nifedipino retard, repouso relativo e retorno em 48h ou antes se cefaleia forte, escotomas ou dor epigástrica. Orientada sobre sinais de alarme.'),
  (1029, 304, 6, '2024-03-07 23:50', 'pronto_socorro', 'Convulsão em casa, família trouxe de ambulância', 188, 118, 104, null, 'Gestante de 35 semanas e 3 dias, marido relata crise tônico-clônica generalizada de cerca de 2 min em casa, precedida de cefaleia intensa e visão turva. À chegada: sonolenta, Glasgow 14, PA 188x118, FC 104, SatO2 95%, reflexos exaltados, clônus. Segunda convulsão no PS. BCF 118 bpm. Laboratório: plaquetas 142.000, TGO 58, TGP 49, DHL 320, creatinina 1,0, proteinúria 3+. Eclâmpsia. Contato imediato com a obstetrícia.', 'Sulfato de magnésio, ataque 4 g IV em 20 min e manutenção 1 g/h, com controle de reflexo patelar, diurese e FR. Hidralazina 5 mg IV para PA ≥ 160x110. Monitorização fetal e encaminhamento ao centro obstétrico para resolução da gestação por cesárea.'),
  (1030, 304, 14, '2024-03-08 03:30', 'internacao', 'Pós-operatório de cesárea por eclâmpsia', 152, 96, 86, null, 'Cesariana de urgência às 01h10, RN feminino 2.480 g, Apgar 7 e 9, encaminhado à neonatologia. Paciente em UTI, extubada, em sulfato de magnésio com reflexos patelares presentes, diurese 80 mL/h, sem novas crises. PA 152x96 sob nifedipino. Plaquetas estáveis em 138.000, TGO 61. Sem sinais de hemorragia, sem edema pulmonar. Após 24h de magnésio, sem recorrência, PA 138x88. Mantém-se em enfermaria obstétrica a partir de D2, com amamentação iniciada.', 'Completar 24h de sulfato de magnésio. Manter nifedipino, associar enalapril (compatível com amamentação) se PA persistente acima de 150x100. Alta no 5º dia com PA domiciliar anotada. Retorno com obstetra em 7 dias.'),
  (1031, 304, 1, '2024-04-18 09:20', 'retorno', 'Revisão do puerpério, pressão ainda anda alta', 138, 88, 80, 78.3, 'Puerpério tardio de 6 semanas, amamentando. Sem cefaleia desde a alta. Bebê ganhando peso bem. PA domiciliar entre 130-145 por 85-92 em uso de nifedipino. Creatinina 0,7, plaquetas normalizadas em 246.000, TGO 24, proteinúria de 24h 130 mg (resolvida). Ainda com hipertensão no puerpério tardio, o que sugere hipertensão crônica de base e não só doença gestacional. Conversado sobre risco de recorrência e uso de AAS em próxima gestação.', 'Trocar nifedipino por enalapril 10 mg 12/12h (compatível com amamentação), com anticoncepção segura, pois IECA é contraindicado na gestação. MRPA em 4 semanas. Perda de peso gradual. Retorno em 60 dias.');
