insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (304, '2024-04-18', 'melhorou', 'Eclâmpsia tratada com sulfato de magnésio e cesariana de urgência, sem sequelas maternas e com recém-nascido saudável. Proteinúria e plaquetas normalizadas, mas mantém hipertensão arterial no puerpério, agora em seguimento com enalapril e contracepção.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (305, 'Olavo Kranz Menezes', 'M', '1965-06-30', 'Santa Maria', 'RS', 'Motorista de caminhão', 'HAS há 10 anos, DM2 há 6 anos (metformina), DLP. Tabagista de 35 maços-ano, ainda fuma 10 cigarros/dia. Pai com infarto aos 58 anos. Passa até 4 dias seguidos na estrada, alimentação em postos de beira de estrada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1032, 305, 2, '2021-04-13 08:00', 'consulta', 'Aperto no peito quando subo a carroceria', 154, 92, 82, 98.2, 'Homem de 55 anos refere dor retroesternal em aperto há 2 meses, desencadeada por esforço (lonar o caminhão, subir rampa) e que melhora em cerca de 5 min ao parar. Sem dor em repouso. Ao exame: BEG, RCR 2T BNF, sem sopros, sem edema, pulsos presentes. ECG de repouso normal. Angina estável CCS II, probabilidade pré-teste alta. Glicemia de jejum 148, HbA1c 7,6%, LDL 132 mg/dL. Orientado sobre cessação do tabagismo e riscos de dirigir na estrada com sintomas.', 'Iniciar AAS, atorvastatina 40 mg, metoprolol succinato 50 mg e nitrato SL se dor. Solicitar teste ergométrico e ECO. Aconselhamento antitabagismo, oferecida terapia de reposição de nicotina. Retorno com exames em 3 semanas.'),
  (1033, 305, 10, '2021-05-04 08:30', 'retorno', 'Teste deu ruim, me mandaram para o hemodinamicista', 138, 84, 64, 97.5, 'Teste ergométrico interrompido no 2º estágio por angina e infradesnível de ST de 2,5 mm em V4-V6, queda da PA no pico. Escore de Duke -14, alto risco. ECO com FEVE 58%, hipocinesia leve da parede anterior. Mantém angina CCS III mesmo com metoprolol e isossorbida. Indicado CATE. Realizado no mesmo dia por acesso radial: DA proximal com lesão de 85%, Cx sem lesões, CD com lesão de 40% no terço médio. ATC com stent farmacológico 3,5 x 24 mm na DA, bom resultado angiográfico, TIMI 3.', 'Dupla antiagregação com AAS 100 mg e clopidogrel 75 mg por 6 meses (SCC). Manter estatina e betabloqueador. Alta no dia seguinte. Parar de fumar. Atestado de afastamento por 15 dias.'),
  (1034, 305, 2, '2021-12-07 09:10', 'retorno', 'Estou sem dor, mas ainda fumo escondido', 128, 78, 62, 94.0, 'Seis meses do stent, assintomático, voltou a dirigir com trechos mais curtos. Fumando 4 cigarros/dia, reduziu mas não parou. LDL 58 mg/dL com atorvastatina 80, HbA1c 6,9%, glicose melhor. Sem sangramento com clopidogrel. PA 128x78, FC 62. ECG sem alterações.', 'Suspender clopidogrel (completou 6 meses), manter AAS indefinidamente. Reforçar cessação do tabagismo; iniciar bupropiona. Manter demais medicações. Retorno em 6 meses; discutir reabilitação cardíaca.');
