insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (305, '2021-12-07', 'controlado', 'Angina estável tratada com stent farmacológico na DA, sem angina há 6 meses, LDL e glicemia na meta. Mantém tabagismo reduzido, em tentativa de cessação com bupropiona. Segue em acompanhamento semestral e voltou ao trabalho como caminhoneiro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (306, 'Edson Kruger Machado', 'M', '1970-09-08', 'Blumenau', 'SC', 'Mestre de obras', 'HAS sem tratamento regular, tabagista de 30 maços-ano, consome cerveja aos fins de semana. Nunca fez exames de rotina. Irmão operou o coração aos 54 anos.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1035, 306, 6, '2022-08-17 05:40', 'pronto_socorro', 'Dor forte no peito há 2 horas, suando frio', 164, 100, 96, 91.0, 'Pcte 51a, acordou às 3h30 com dor precordial em aperto, intensidade 9/10, irradiação para MSE e mandíbula, sudorese e náuseas. Sem melhora com repouso. Ao exame: ansioso, pálido, sudoreico, RCR 2T B4, sem sopros, MV+ sem RA. ECG às 5h50: supra de ST de 4 mm de V1 a V5 e DI/aVL, com infra espelhado em parede inferior. Troponina 1,8 ng/mL. HD: IAMCSST de parede anterior, Killip I, 2h de dor, dentro da janela para reperfusão mecânica.', 'AAS 300 mg, ticagrelor 180 mg, heparina não fracionada, morfina titulada. Acionada hemodinâmica para angioplastia primária; tempo porta-balão alvo < 90 min. Atorvastatina 80 mg e metoprolol assim que estável.'),
  (1036, 306, 10, '2022-08-17 07:10', 'internacao', 'Angioplastia primária por IAM de parede anterior', 112, 70, 78, 91.0, 'CATE por via radial direita: oclusão trombótica da DA proximal, TIMI 0; CD e Cx com lesões de 30%. ATC primária com stent farmacológico 3,0 x 28 mm na DA, TIMI 3 final, sem complicações. Porta-balão de 74 min. Pico de troponina 62 ng/mL e CK-MB 280. ECO no 3º dia: FEVE 38% com acinesia anteroapical, sem trombo no VE. Evolui em UTI sem arritmias, em Killip I. Alta no 6º dia com ticagrelor, AAS, estatina de alta potência, betabloqueador e iECA em dose baixa. Tabagismo suspenso à força, aceita reabilitação.', 'Dupla antiagregação (AAS + ticagrelor) por 12 meses. Iniciar enalapril, carvedilol, espironolactona se FEVE persistir < 40% em 40 dias. Reabilitação cardíaca e cessação do tabagismo. Retorno em 30 dias.'),
  (1037, 306, 11, '2022-10-04 10:00', 'retorno', 'Cansaço para subir escada, voltei a fumar', 118, 72, 66, 93.8, 'Retorna 48 dias pós-IAM com dispneia aos médios esforços (NYHA II), ganho de 2,8 kg, edema vespertino de tornozelos e ortopneia leve. Admite ter voltado a fumar 10 cigarros/dia e não ter ido à reabilitação por causa do trabalho. Ao exame: B3 ausente, estertores em bases, edema 1+. ECO de controle: FEVE 33%, remodelamento ventricular, sem trombo. NT-proBNP 1.840 pg/mL. IC pós-infarto com FE reduzida, agravada por adesão parcial ao tratamento e tabagismo.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (após pausa de 36h), manter carvedilol, iniciar espironolactona 25 mg e dapagliflozina 10 mg. Furosemida 40 mg. Dosar K e creatinina em 1 semana. Discutir CDI se FEVE persistir < 35% após 3 meses de terapia otimizada.');
