insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (306, '2023-02-20', 'piorou', 'Evoluiu com insuficiência cardíaca de FEVE reduzida (33%) após o infarto anterior, apesar de angioplastia precoce. Mantém tabagismo e baixa adesão à reabilitação. Segue em terapia otimizada e avaliação de CDI para prevenção primária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (307, 'Noêmia Schwengber Prates', 'F', '1961-12-15', 'Novo Hamburgo', 'RS', 'Costureira em fábrica de calçados', 'Cardiomiopatia dilatada de etiologia indeterminada (cateterismo sem lesões, 2021). HAS leve. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Nunca fumou. Duas internações por descompensação nos últimos 12 meses.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1038, 307, 11, '2022-05-10 14:00', 'consulta', 'Tosse seca que não passa e cansaço', 116, 74, 68, 69.5, 'Mulher de 60 anos com ICFEr (FEVE 29% no último ECO) em classe funcional III, refere tosse seca irritativa noturna há 5 meses que atribui à IC, mas começou depois de aumentar o enalapril. Sem ortopneia, edema discreto. Usa sal em excesso por gostar de comida salgada, "faz parte da cultura da casa". Ao exame: BEG, jugulares sem ingurgitamento, RCR 3T com sopro sistólico mitral 2+/6, MV+ com raros crepitantes. Considerada tosse por IECA. Candidata a terapia dos quatro pilares.', 'Suspender enalapril; após 36 horas iniciar sacubitril/valsartana 24/26 mg 12/12h. Iniciar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol e furosemida. K e creatinina em 7 dias. Orientação nutricional com redução de sódio. Retorno em 3 semanas.'),
  (1039, 307, 11, '2022-06-01 14:30', 'retorno', 'A tosse sumiu, mas fico tonta quando levanto', 98, 62, 64, 67.2, 'Três semanas de esquema completo. Tosse resolvida em poucos dias após suspender o enalapril. Refere tontura ao levantar-se rápido, sem síncope. PA 98x62 sentada, 90x58 em pé. K 4,9 e creatinina 1,2 (leve aumento esperado com iSGLT2 e espironolactona). Perdeu 2,3 kg com diurese. Ao exame, congestão ausente, sem edema. Boa tolerância geral, mas hipotensão sintomática postural leve.', 'Reduzir furosemida para 20 mg/dia, manter os demais fármacos. Orientada a levantar devagar e manter hidratação. Repetir K e creatinina em 2 semanas. Retorno em 6 semanas para tentar titular carvedilol.'),
  (1040, 307, 11, '2022-12-13 15:00', 'retorno', 'Voltei a fazer minhas costuras sem cansar', 108, 66, 60, 66.4, 'Seis meses de terapia otimizada, classe funcional II, sem internação. Voltou ao trabalho em meio período. Carvedilol subiu para 12,5 mg 12/12h, sacubitril/valsartana para 49/51 mg 12/12h há 2 meses. NT-proBNP caiu de 2.900 para 710 pg/mL. K 4,6, creatinina 1,1. ECO: FEVE 41%, DDVE 58 mm, IM discreta. Sem hipotensão sintomática. Resposta favorável, com remodelamento reverso.', 'Manter esquema atual, sem mais titulação por limite da PA. Repetir ECO em 6 meses; se FEVE ≥ 50% manter terapia e discutir. Vacina de influenza e pneumococo. Retorno em 4 meses.');
