insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (307, '2023-04-18', 'melhorou', 'Cardiomiopatia dilatada com otimização dos quatro pilares: FEVE subiu de 29% para 41%, NT-proBNP caiu para 710, classe funcional II e sem internação em 11 meses. A tosse por IECA desapareceu após a troca para sacubitril/valsartana.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (308, 'Aristides Cardozo Peixoto', 'M', '1955-01-20', 'Pelotas', 'RS', 'Aposentado, ex-pescador', 'HAS há 15 anos em uso de anlodipino 5 mg e losartana 50 mg. Sobrepeso. Etilista social moderado. Sem diabetes. Primeiro episódio de palpitações há 3 semanas. Esposa relata roncos intensos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1041, 308, 4, '2023-03-21 10:30', 'consulta', 'Coração disparado e cansaço há 3 semanas', 144, 86, 124, 91.2, 'Homem de 68 anos com palpitações irregulares, cansaço aos médios esforços e sensação de peso no peito há 3 semanas, sem síncope. Ao exame: RCI 2T, FC 124, sem sopros, MV+ sem RA, sem edema. ECG: fibrilação atrial com resposta ventricular de 124 bpm, sem isquemia. ECO: átrio esquerdo 49 mm, FEVE 54%. TSH normal. CHA2DS2-VASc 2 (idade 65-74 e HAS), HAS-BLED 1. Início provável há 3 semanas, portanto sem tempo de segurança para cardioversão sem anticoagulação prévia.', 'Iniciar rivaroxabana 20 mg/dia com a janta e metoprolol succinato 50 mg para controle de FC. Cardioversão elétrica eletiva após 3 semanas de anticoagulação efetiva. Solicitar polissonografia. Retorno em 3 semanas.'),
  (1042, 308, 4, '2023-04-25 11:00', 'retorno', 'Vim para a cardioversão que marcaram', 138, 82, 88, 90.8, 'Após 5 semanas de anticoagulação sem falhas, FC controlada em 88 bpm. Polissonografia mostrou IAH 38/h, apneia obstrutiva grave, com dessaturação de até 79%. Realizada cardioversão elétrica sincronizada sob sedação com 150 J bifásico, reversão para ritmo sinusal ao primeiro choque. ECG pós: ritmo sinusal, FC 72. Sem complicações. Orientado a manter anticoagulação por pelo menos 4 semanas e por tempo indefinido pelo escore de risco.', 'Manter rivaroxabana e metoprolol. Encaminhar para CPAP via pneumologia/sono. Reduzir bebida alcoólica. Holter de 24h em 2 meses. Retorno em 8 semanas.'),
  (1043, 308, 4, '2024-01-16 09:30', 'retorno', 'O coração voltou a disparar umas vezes no mês', 134, 80, 70, 88.0, 'Dez meses depois, refere 2 episódios curtos de palpitações, o último há 3 semanas, resolvidos espontaneamente em horas. Holter de 24h: ritmo sinusal predominante, FA paroxística de 3h, FC média 78. Usa CPAP há 5 meses com boa adesão e reduziu 3 kg. Sem sangramento em uso do DOAC. Hb 14,2 e creatinina 1,0 (ClCr 78). PA 134x80 em ritmo sinusal.', 'Manter estratégia de controle de ritmo com observação por ora, mantendo anticoagulação sem interrupção. Discutir ablação se recorrência frequente. Reduzir álcool a zero. Retorno em 6 meses com Holter.');
