insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (308, '2024-01-16', 'estavel', 'FA com cardioversão elétrica bem-sucedida e recorrência paroxística rara, em anticoagulação contínua com rivaroxabana e tratamento de apneia grave com CPAP. Sem AVC ou sangramento. Segue em observação para possível ablação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (309, 'Eurico Waldmann Teixeira', 'M', '1941-03-05', 'Porto Alegre', 'RS', 'Aposentado, ex-professor de matemática', 'HAS, DLP, prótese total de joelho direito. Estenose aórtica degenerativa conhecida, acompanhada com ECO anual. Vive com a esposa, que é seu principal apoio. Caminha pouco, usa bengala. Sem diabetes.', 'Alergia a penicilina (exantema)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1044, 309, 1, '2022-02-08 09:30', 'consulta', 'Tive uma tontura forte e quase desmaiei no mercado', 130, 74, 70, 72.5, 'Paciente de 80 anos com estenose aórtica degenerativa, última avaliação há 14 meses com gradiente médio 32 mmHg. Nos últimos 2 meses, dispneia aos pequenos esforços e dois episódios de pré-síncope ao caminhar. Sem angina. Ao exame: pulsos parvus et tardus, sopro sistólico ejetivo 4+/6 em foco aórtico com irradiação para carótidas, B2 hipofonética. ECO: área valvar 0,7 cm², gradiente médio 48 mmHg, velocidade máxima 4,6 m/s, FEVE 55%. Estenose aórtica importante sintomática.', 'Indicação de intervenção valvar. Encaminhar ao Heart Team (cirurgia e hemodinâmica); solicitar angiotomografia de aorta e ilíacas, cateterismo coronário e avaliação geriátrica. Evitar esforços até lá. Retorno em 2 semanas.'),
  (1045, 309, 12, '2022-03-22 14:00', 'retorno', 'Quero saber se vou ser operado de peito aberto', 126, 72, 68, 72.0, 'Heart Team discutiu o caso: aos 81 anos, STS 5,8%, fragilidade moderada (marcha lenta), coronariografia sem lesões obstrutivas significativas, angiotomografia com anel de 24 mm, bom acesso transfemoral, boas ilíacas. Opção preferencial por TAVI transfemoral. Paciente e esposa informados sobre riscos (AVC, bloqueio, sangramento) e benefícios. "Prefiro a que me deixa menos tempo no hospital", diz o paciente. Termo de consentimento assinado.', 'Agendar TAVI transfemoral em abril. Suspender losartana 48h antes, manter estatina, preparo pré-procedimento e odontologia (profilaxia com clindamicina por alergia a penicilina). Retorno após alta.'),
  (1046, 309, 10, '2022-04-19 07:30', 'internacao', 'Internado para implante transcateter de valva aórtica', 132, 76, 72, 71.8, 'TAVI transfemoral sob sedação e anestesia local, com prótese autoexpansível de 26 mm, pós-dilatação com balão. Gradiente residual médio de 8 mmHg, sem regurgitação paravalvar relevante. ECG pós: BRE novo, intervalo PR de 220 ms, sem BAV de alto grau após 48h de monitorização. Hematoma discreto em local de punção, sem sangramento maior. Dor controlada, caminhando no 1º dia. Alta no 3º dia, Hb 11,8, creatinina 1,0.', 'AAS 100 mg indefinidamente. Atorvastatina mantida; retomar losartana se PA > 140x90. Holter em 30 dias para pesquisa de BAV tardio, ECO em 30 dias, profilaxia de endocardite e orientações de higiene oral. Retorno em 30 dias.'),
  (1047, 309, 1, '2022-05-24 10:00', 'retorno', 'Sem tonturas, voltei a caminhar na praça', 138, 78, 66, 73.4, 'Um mês após TAVI, sem síncope, caminha 30 minutos por dia na praça e subiu um lance de escada sem parar. Sem sangramentos. Holter 24h: ritmo sinusal, BRE persistente, BAV de 1º grau, sem pausas ou BAV avançado. ECO: prótese normofuncionante, gradiente médio 9 mmHg, FEVE 58%. Pulsos de punção sem complicações. PA 138x78 sem losartana.', 'Manter AAS e atorvastatina. Seguimento com ECO anual e ECG a cada 6 meses pela condução. Reforçar profilaxia antes de procedimentos odontológicos. Retorno em 6 meses.');
