insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (309, '2022-05-24', 'melhorou', 'Estenose aórtica importante sintomática tratada com TAVI transfemoral. Resolveu a pré-síncope e a dispneia, gradiente residual de 9 mmHg e FEVE preservada. Mantém BRE novo com BAV de 1º grau, sem necessidade de marca-passo até o momento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (310, 'Olegário Miranda Bastos', 'M', '1962-04-02', 'Bambuí', 'MG', 'Lavrador aposentado', 'Doença de Chagas diagnosticada há 14 anos; nasceu e cresceu em casa de pau a pique. IC por cardiopatia chagásica desde 2019 com FEVE 30%. Em uso de enalapril, carvedilol e furosemida. Dois irmãos com Chagas. Sem hábitos tóxicos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1048, 310, 4, '2021-10-14 10:00', 'consulta', 'Quase desmaiei e o coração bateu muito rápido', 104, 66, 58, 64.0, 'Homem de 59 anos com cardiopatia chagásica e IC em CF III, refere um episódio de palpitação intensa seguida de pré-síncope há 10 dias, com duração de cerca de 1 minuto. Ao exame: emagrecido, jugulares ingurgitadas a 45°, RCR 3T com B3, MV+ com crepitantes bibasais discretos, edema 2+. ECG: BRD + HBAE, extrassístoles ventriculares frequentes. Holter: 11.800 ESV e 4 episódios de TVNS de até 14 batimentos. ECO: FEVE 26%, aneurisma apical, sem trombo. Alto risco de morte súbita; não há indicação de tratamento etiológico com benznidazol na fase crônica com cardiopatia estabelecida.', 'Iniciar amiodarona 200 mg/dia, manter carvedilol, trocar enalapril por sacubitril/valsartana, adicionar espironolactona. Indicar implante de CDI para prevenção secundária/prevenção primária de alto risco. Encaminhar à arritmologia.'),
  (1049, 310, 4, '2022-01-20 08:00', 'internacao', 'Internação para implante de CDI', 108, 68, 56, 63.5, 'Internado eletivamente para implante de CDI unicameral por prevenção em cardiopatia chagásica com FEVE 26%, TVNS e pré-síncope. Procedimento sem intercorrências, limiar de ventrículo 0,6 V, onda R 9 mV, teste de fibrilação com cardioversão eficaz. Mantido com amiodarona. Alta no dia seguinte, ferida limpa, sem pneumotórax. Familiares orientados sobre choque, carteira do CDI e dirigir.', 'Programação ambulatorial do CDI em 30 dias. Manter amiodarona, carvedilol, sacubitril/valsartana e espironolactona. Orientações: se choque único e assintomático, ligar; se dois ou mais choques, ir ao PS. Controle de TSH/TGO a cada 6 meses (amiodarona).'),
  (1050, 310, 6, '2022-11-02 03:20', 'pronto_socorro', 'Três choques seguidos no peito e falta de ar', 88, 54, 132, null, 'Homem de 60 anos com CDI, trazido por familiares após três choques em 20 minutos às 2h, seguidos de dispneia intensa e mal-estar. Chegou taquicárdico, FC 132, PA 88x54, SatO2 88%, sudoreico, extremidades frias, estertores até campos médios. ECG: TV monomórfica sustentada a 132 bpm, interrompida na sala de emergência com cardioversão elétrica após piora hemodinâmica. Interrogação do CDI: TV rápida, 3 choques apropriados. Hipocalemia (K 3,2), lactato 4,1. Quadro de tempestade elétrica com IC descompensada e choque cardiogênico.', 'Cardioversão elétrica sincronizada, reposição de K e magnésio IV, amiodarona IV, O2, furosemida IV e noradrenalina em baixa dose para PA. Transferir à UTI. Avaliar ajuste do CDI com arritmologia.'),
  (1051, 310, 14, '2022-11-04 10:00', 'internacao', 'UTI, choque cardiogênico por IC chagásica', 86, 52, 98, 59.0, 'Dia 2 de UTI com choque cardiogênico refratário, lactato 5,0, creatinina 2,8 (lesão renal por baixo débito), oligúria, sem TV recorrente após ajuste de amiodarona. ECO: FEVE 17%, VE dilatado, trombo apical móvel de 1,2 cm. Iniciado dobutamina e heparina não fracionada. Não é candidato a transplante cardíaco pela caquexia e disfunção renal, conforme discussão com a equipe de IC e a família. Piora progressiva com anasarca, necessidade de aumento de dobutamina. Familiares optam por abordagem de conforto na ausência de resposta.', 'Manter dobutamina e heparina, suspender sacubitril/valsartana e espironolactona por hipotensão e lesão renal. Conversa franca com a família sobre prognóstico; cuidados paliativos junto à UTI; sem escalada de suporte.');
