insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (310, '2022-11-08', 'obito', 'Óbito em UTI após quatro dias de internação por choque cardiogênico refratário em cardiopatia chagásica terminal (FEVE 17%, trombo apical, lesão renal aguda), precipitado por tempestade elétrica com choques apropriados do CDI. Família acompanhou, cuidados de conforto.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (311, 'Marlene Dalla Vecchia Rigo', 'F', '1963-07-24', 'Joaçaba', 'SC', 'Vendedora de loja de roupas', 'HAS há 14 anos e DM2 há 9 anos, em uso de metformina 850 mg 12/12h e enalapril 10 mg/dia, com tosse seca eventual. Obesidade grau 1. Nunca fumou. Mãe diabética com IRC em hemodiálise.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1052, 311, 1, '2022-05-10 08:50', 'consulta', 'Vim ver a pressão e o diabetes, os exames deram alterados', 158, 96, 82, 84.0, 'Mulher de 58 anos, HAS e DM2 mal controlados. Trouxe exames: HbA1c 8,4%, creatinina 1,0 (TFGe 62), relação albumina/creatinina urinária 180 mg/g em duas amostras, LDL 124. Queixa-se de tosse seca noturna que piora com o enalapril. Ao exame: PA 158x96, RCR 2T BNF, sem sopros, pulsos pediosos presentes, sem edema. Fundo de olho recente com retinopatia leve. Diagnóstico de albuminúria moderadamente aumentada (nefropatia diabética incipiente).', 'Trocar enalapril por losartana 50 mg 12/12h (tosse), associar anlodipino 5 mg, iniciar dapagliflozina 10 mg pela nefroproteção e atorvastatina 40 mg. Dieta e caminhada. K e creatinina em 2 semanas, RAC em 3 meses. Retorno em 8 semanas.'),
  (1053, 311, 1, '2022-07-12 09:10', 'retorno', 'A tosse parou, pressão em casa anda melhor', 136, 82, 78, 82.2, 'Tosse resolvida após a troca do IECA. Refere dois episódios de candidíase vaginal tratados na unidade, sem necessidade de suspender a dapagliflozina. PA domiciliar 130-140 por 80-86. Creatinina 1,1 (esperado leve aumento inicial), K 4,7. RAC caiu de 180 para 95 mg/g. HbA1c 7,5%. Perdeu 1,8 kg. Resposta muito satisfatória, ainda um pouco acima da meta pressórica de 130/80.', 'Manter losartana 50 mg 12/12h por ora e confirmar a PA com MRPA antes de qualquer aumento. Orientada sobre higiene íntima e sinais de infecção urinária. Repetir RAC e HbA1c em 3 meses. Retorno em 3 meses.'),
  (1054, 311, 1, '2022-11-22 16:00', 'teleconsulta', 'Os remédios estão acabando e a dapagliflozina é cara', 144, 88, null, null, 'Teleconsulta. Paciente informa PA domiciliar média de 144x88 nas últimas duas semanas. Admite que a loja reduziu a jornada e a renda, e que não consegue comprar dapagliflozina há dois meses, pois não está disponível na farmácia municipal. Tomando só losartana, anlodipino e metformina. Sem sintomas novos, sem edema, sem dispneia. Ainda não realizou RAC nem HbA1c de controle por causa do deslocamento até o laboratório.', 'Orientada a buscar dapagliflozina via programa de assistência da prefeitura, laudo emitido. Manter demais medicamentos. Agendado laboratório na unidade e consulta presencial em 30 dias. Contato ativo da enfermagem se faltar.');
