insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (311, '2023-06-30', 'abandonou', 'Não compareceu à consulta presencial marcada nem aos dois retornos seguintes; três tentativas de contato telefônico pela enfermagem sem sucesso. Último registro: HAS acima da meta, albuminúria em tratamento parcial e sem acesso contínuo à dapagliflozina. Perda de seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (312, 'Zeferino Tiecher Ramos', 'M', '1946-10-11', 'Santa Cruz do Sul', 'RS', 'Aposentado, ex-agricultor', 'HAS há 30 anos, em uso de anlodipino 10 mg, losartana 100 mg, clortalidona 25 mg e doxazosina 4 mg. Prostatismo leve. Viúvo, mora sozinho. Duas quedas no último ano que atribui ao piso molhado. Nega tabagismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1055, 312, 6, '2022-06-06 19:40', 'pronto_socorro', 'Caí no banheiro de noite, levantei rápido', 150, 84, 74, 70.0, 'Pcte 75a, queda da própria altura ao levantar para urinar de madrugada, com tontura e escurecimento visual antes de cair, sem perda total de consciência. Escoriação em cotovelo e ombro direito. Sem TCE. BEG, RCR 2T BNF, MV+ sem RA, neurológico sem déficits. PA deitado 150x84, em pé após 1 minuto 118x68 (queda de 32 mmHg), FC 74 sem aumento compensatório. ECG: ritmo sinusal, BRD incompleto. Glicemia 104. Radiografia de ombro sem fratura. HD: hipotensão ortostática por excesso de anti-hipertensivos e alfa-bloqueador.', 'Suspender doxazosina e clortalidona hoje. Manter anlodipino e losartana. Orientações sobre levantar em etapas, uso de luz noturna e tapete antiderrapante. Retorno ambulatorial em 2 semanas com PA deitado e em pé.'),
  (1056, 312, 3, '2022-06-22 10:00', 'retorno', 'Ainda fico tonto ao levantar da cama', 146, 82, 72, 69.5, 'Duas semanas após suspender doxazosina e clortalidona, tonturas menos frequentes mas persistentes pela manhã. PA deitado 146x82, em pé 3 min 124x74. Ingere pouca água, 1 litro por dia, por medo de levantar à noite. Sódio 138, K 4,1, creatinina 1,1, Hb 12,9. Sem tremores, sem sinais de Parkinson. Avaliar neuropatia autonômica: glicemia e B12 normais. Paciente idoso frágil com piora da marcha, risco de nova queda.', 'Reduzir losartana para 50 mg e manter anlodipino 5 mg, intuito de meta flexível em idoso frágil (< 140/90 em pé). Aumentar ingesta hídrica para 1,5-2 L, meia elástica. Fisioterapia para marcha e equilíbrio. Retorno em 30 dias.'),
  (1057, 312, 1, '2022-09-14 09:30', 'retorno', 'Não caí mais, mas a pressão anda subindo e descendo', 138, 78, 70, 71.0, 'Três meses depois, sem novas quedas, caminha 20 minutos com a fisioterapeuta, ganhou 1,5 kg. MAPA 24h: média 24h 132x74, vigília 136x78, sono 120x66, sem hipotensão em vigília, queda matinal de 16 mmHg. PA ortostática: deitado 138x78, em pé 3 min 128x72, assintomático. Creatinina 1,0 e K 4,3. Considero que a PA está em faixa adequada para a idade e fragilidade, sem tontura.', 'Manter anlodipino 5 mg e losartana 50 mg. Não intensificar. Seguimento semestral com PA ortostática em toda consulta. Avaliar densitometria óssea e vitamina D. Mantidas orientações de prevenção de quedas.');
