insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (312, '2022-09-14', 'estavel', 'Hipotensão ortostática por excesso de anti-hipertensivos resolvida com desprescrição de doxazosina e clortalidona e redução de doses. Sem novas quedas em 3 meses, PA em torno de 136x78 na MAPA. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (313, 'Dirlene Pavei Locks', 'F', '1966-02-14', 'Criciúma', 'SC', 'Cozinheira de restaurante industrial', 'HAS há 9 anos, atualmente em uso de losartana 100 mg, clortalidona 25 mg, anlodipino 10 mg e atenolol 50 mg. Encaminhada como hipertensão resistente. Obesidade grau 1, sedentária, trabalha em pé 9 horas por dia. Ansiosa. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1058, 313, 1, '2023-04-18 14:00', 'consulta', 'Minha pressão não baixa nem com quatro remédios', 176, 104, 62, 86.5, 'Mulher de 57 anos encaminhada por HAS "resistente" em quatro fármacos. Nas consultas anteriores, PA entre 170-180 por 100-105. Nesta, 176x104 no consultório, medida por técnico, manguito de 13 cm no braço de 34 cm de circunferência. Remisura com manguito de 17 x 36 cm: 162x98. Em casa, nunca mediu. Refere nervosismo na presença de médico e batimentos nas têmporas ao sair da cozinha. Sem sinais de hipertensão secundária (K 4,2, TSH 2,0, creatinina 0,8, sem sopros abdominais). Suspeita de pseudorresistência por técnica de medida e efeito do avental branco.', 'Solicitar MAPA 24h e MRPA para avaliar a verdadeira PA. Manter por ora o esquema, confirmar adesão (relata tomar tudo certinho, farmácia com retirada em dia). Orientar dieta e manguito adequado. Retorno com MAPA em 3 semanas.'),
  (1059, 313, 1, '2023-05-23 14:20', 'retorno', 'Trouxe o resultado da MAPA', 170, 100, 60, 86.0, 'MAPA de 24h com quatro fármacos: média 24h 122x72, vigília 126x76, sono 112x64, descenso preservado. Pressões do consultório 170x100: efeito do avental branco de 44 mmHg na sistólica. Pseudorresistência confirmada, ou seja, hipertensão controlada na vida real com sobretratamento. FC de repouso 60 com atenolol. Relatou fraqueza e tontura às vezes no trabalho nos dias de calor, possivelmente de excesso de medicação e desidratação na cozinha.', 'Desescalonar: suspender atenolol (reduzir em 1 semana para 25 mg e parar) e clortalidona. Manter losartana 100 e anlodipino 10. Fazer MRPA de 5 dias após 3 semanas. Orientar para não decidir terapia pela medida do consultório.'),
  (1060, 313, 1, '2023-11-14 15:10', 'retorno', 'Estou me sentindo mais disposta', 148, 90, 74, 83.2, 'Seis meses após o desescalonamento, melhorou a disposição, sem tonturas, edema discreto de tornozelos com anlodipino 10 mg. MRPA de 5 dias (30 medidas): média 126x78. Consultório 148x90, de novo com efeito do avental branco, mas sem implicação terapêutica. Perdeu 2,8 kg. Creatinina 0,8 e K 4,4. Recomendada a manter automonitorização como referência de decisão.', 'Manter losartana 100 mg e anlodipino 10 mg. Se edema incomodar, trocar anlodipino por 5 mg e retomar clortalidona 12,5 mg. MRPA a cada 3 meses. Retorno em 6 meses.');
