insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (313, '2023-11-14', 'controlado', 'Pseudorresistência por efeito do avental branco e técnica inadequada de medida, comprovada por MAPA. Esquema reduzido de quatro para dois fármacos, com MRPA média de 126x78 mmHg e melhora da disposição. Segue com automonitorização domiciliar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (314, 'Osvaldo Rossatto Tonin', 'M', '1954-05-16', 'Passo Fundo', 'RS', 'Comerciante de material de construção', 'HAS há 15 anos, agravada nos últimos 2 anos. Tabagista de 45 maços-ano (parou há 3 anos), DLP, claudicação leve em panturrilhas. Em uso de enalapril 20 mg 12/12h, hidroclorotiazida 25 mg e anlodipino 10 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1061, 314, 1, '2021-06-15 09:00', 'consulta', 'Pressão cada vez mais alta e os exames pioraram', 190, 104, 80, 78.0, 'Homem de 67 anos, aterosclerótico, com HAS de piora progressiva, PA 190x104 com três fármacos. Creatinina subiu de 1,3 para 2,1 mg/dL em 2 meses após aumentar enalapril, K 5,3. Ao exame: sopro sistólico-diastólico em flanco direito e epigástrio, pulsos femorais diminuídos, edema ausente. ECO: HVE moderada, FEVE 60%. Episódio de edema agudo de pulmão há 1 mês, sem internação. Aumento da creatinina com IECA e HAS grave sugerem estenose de artéria renal.', 'Suspender enalapril e hidroclorotiazida. Iniciar carvedilol 12,5 mg 12/12h e hidralazina 25 mg 3x/dia, manter anlodipino 10 mg. Doppler de artérias renais urgente. Encaminhar à nefrologia. Retorno em 15 dias.'),
  (1062, 314, 8, '2021-07-20 10:30', 'retorno', 'Vim com o resultado do Doppler', 168, 94, 68, 77.2, 'Doppler de artérias renais: estenose hemodinamicamente significativa à direita, com velocidade de pico 380 cm/s, relação renal/aórtica 4,8, índice de resistividade 0,68; rim esquerdo atrófico com 8,3 cm, sem fluxo útil. Angiotomografia confirma estenose aterosclerótica ostial de 80% da artéria renal direita, rim direito de 11 cm. Creatinina 1,8 após suspensão do IECA. Proteinúria leve. Rim único funcionante, HAS refratária e episódios de EAP: indicação de revascularização por angioplastia com stent.', 'Encaminhar à hemodinâmica para angioplastia com stent na artéria renal direita. Manter esquema atual, evitar IECA/BRA e AINEs. Controle de creatinina e K semanal até o procedimento.'),
  (1063, 314, 10, '2021-09-14 07:30', 'internacao', 'Internado para angioplastia de artéria renal', 160, 90, 66, 77.0, 'Angioplastia com implante de stent na artéria renal direita por via femoral, com pré-hidratação e baixa carga de contraste (60 mL). Estenose ostial de 85% com gradiente translesional de 48 mmHg. Stent expansível por balão 6 x 15 mm, resultado angiográfico sem estenose residual e gradiente zero. Sem complicações de acesso. Creatinina 1,9 no 2º dia, 1,7 no 3º. PA caiu para 142x84 antes da alta, já em carvedilol, anlodipino e hidralazina em menor dose.', 'Dupla antiagregação: AAS 100 mg e clopidogrel 75 mg por 30 dias, depois só AAS. Reduzir hidralazina para 25 mg 8/8h. Creatinina e K em 1 semana. Doppler de controle em 3 meses. Retorno em 3 semanas.'),
  (1064, 314, 1, '2022-03-01 09:40', 'retorno', 'Estou ótimo, não tive mais falta de ar', 134, 80, 64, 79.5, 'Seis meses do stent renal. Sem episódios de EAP, caminha 40 minutos sem dispneia. PA em casa média 130x78 com anlodipino e carvedilol, hidralazina suspensa por mim em 3 meses por PA baixa. Doppler: stent pérvio, VPS 105 cm/s, sem reestenose. Creatinina 1,3 e K 4,5. ECO: regressão parcial da HVE. Claudicação leve mantida em panturrilha direita, ITB 0,78.', 'Manter anlodipino 10 mg e carvedilol 12,5 mg 12/12h, AAS e atorvastatina. Retomar o diálogo sobre IECA/BRA apenas com cautela futura e monitoramento (rim único funcionante). Doppler anual do stent. Retorno em 6 meses.');
