insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (314, '2022-03-01', 'melhorou', 'Hipertensão renovascular por estenose aterosclerótica da artéria renal direita tratada com stent. PA caiu de 190x104 para 134x80 com dois fármacos, sem EAP e com creatinina estável em 1,3 mg/dL. Mantém rim esquerdo atrófico e doença arterial periférica leve em seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (315, 'Abelardo Wiggers Fontoura', 'M', '1960-12-02', 'Curitiba', 'PR', 'Contador', 'HAS, DM2 em uso de metformina e glibenclamida, DLP. Ex-fumante há 8 anos. Pai faleceu de infarto aos 62 anos. Angina de esforço há 6 meses, nunca investigada. Sedentário, trabalha muitas horas em frente ao computador na época de declarações.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1065, 315, 6, '2020-09-08 21:30', 'pronto_socorro', 'Dor no peito mesmo parado, piora a cada dia', 150, 88, 74, 90.0, 'Pcte 59a com aperto torácico que passou a ocorrer ao repouso, 3 episódios hoje, de 15 a 20 min, o último há 40 min, aliviado parcialmente com repouso. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, sem edema. ECG: infradesnível de ST de 1,5 mm em V4-V6, sem supra. Troponina ultrassensível 1ª e 2ª amostras negativas (6 e 7 ng/L). Escore GRACE de risco intermediário. HD: angina instável, SCA sem supra, troponina negativa.', 'Internar em unidade coronariana. AAS 300 mg, clopidogrel 300 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg e metoprolol. Estratificação invasiva em 24-48h. Nitroglicerina IV se dor recorrente.'),
  (1066, 315, 10, '2020-09-10 08:00', 'internacao', 'Coronariografia na internação por angina instável', 130, 78, 60, 89.5, 'Sem dor desde o PS. CATE radial direito: doença triarterial, DA com lesão de 90% proximal e 70% no terço médio, Cx com lesão de 80% na marginal, CD com oclusão crônica de 100% no terço médio com circulação colateral. Tronco com lesão de 40%. FEVE 52% na ventriculografia. SYNTAX score 33. Com diabetes, multiarterial e lesões complexas, discussão em Heart Team favorece revascularização cirúrgica com enxerto de artéria mamária interna.', 'Encaminhar à cirurgia cardiovascular. Manter AAS, atorvastatina e metoprolol; suspender clopidogrel 5 dias antes da cirurgia e enoxaparina na véspera. Cirurgia agendada para 14 dias. Alta hospitalar para casa com restrição de esforços.'),
  (1067, 315, 12, '2020-09-25 06:30', 'internacao', 'Cirurgia de revascularização do miocárdio', 126, 74, 62, 89.0, 'Revascularização miocárdica com circulação extracorpórea: mamária esquerda para DA, safena para marginal da Cx e safena para descendente posterior da CD, 3 pontes. Tempo de CEC 78 min. Pós-operatório em UTI, extubado em 6 horas, sem arritmia, sem sangramento relevante. Dreno removido no 2º dia. FA transitória no 3º dia, revertida com amiodarona. Ferida esternal e da perna sem sinais de infecção. Alta no 7º dia com PA 124x70, FC 66. Glicemia mantida com insulina durante a internação.', 'Alta com AAS, estatina e betabloqueador, metformina. Fisioterapia e reabilitação cardíaca. Cuidados com ferida, cinta torácica, sem esforços por 6 semanas. Retorno em 30 dias.'),
  (1068, 315, 2, '2021-03-09 09:00', 'retorno', 'Seis meses depois da cirurgia, vim para revisão', 122, 72, 58, 85.0, 'Seis meses de pós-operatório de RM. Fez 24 sessões de reabilitação cardíaca, sem angina, caminha 5 km sem sintomas. Perdeu 5 kg, abandonou a glibenclamida por conta própria, mantém metformina. Esterno estável, cicatrizes boas. LDL 52 mg/dL com atorvastatina 80, HbA1c 6,8%. Teste ergométrico: 10 METs, sem alterações isquêmicas. FEVE 56% ao ECO. PA 122x72, FC 58.', 'Manter AAS, atorvastatina e metoprolol. Retorno semestral e teste de esforço anual. Orientações: dieta mediterrânea, exercício aeróbico regular, controle da glicemia. Vacina anual de influenza.');
