insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (315, '2021-03-09', 'melhorou', 'Doença coronariana triarterial com angina instável tratada com revascularização cirúrgica de três pontes. Sem angina, LDL 52 e teste ergométrico de 10 METs na revisão de 6 meses. Segue em acompanhamento semestral e já retomou a atividade física regular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (316, 'Hildegard Pfeifer Oliveira', 'F', '1948-09-09', 'Gramado', 'RS', 'Aposentada, ex-governanta de hotel', 'HAS de longa data, obesidade grau 2, DM2 há 12 anos, DRC estágio 3 (TFGe 48). Pernas inchadas há 2 anos. Em uso de anlodipino 10 mg, losartana 50 mg e metformina 500 mg. Vive com a filha, que organiza os remédios.', 'Alergia a sulfa (reação cutânea)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1069, 316, 11, '2022-10-04 10:00', 'consulta', 'Falta de ar para subir o degrau de casa e pernas inchadas', 148, 84, 78, 91.0, 'Mulher de 74 anos, obesa, com dispneia aos pequenos esforços (NYHA III) há 4 meses, ortopneia com 2 travesseiros e edema de MMII até joelhos. Ao exame: jugulares a 45° com refluxo hepatojugular positivo, RCR 2T B4, crepitantes em bases, edema 3+/4+. NT-proBNP 1.540 pg/mL. ECO: FEVE 60%, HVE concêntrica, átrio esquerdo aumentado (índice 42 mL/m²), relação E/e'' 17, PSAP 46 mmHg. Preenche critérios de IC com fração de ejeção preservada. Anlodipino contribui para o edema.', 'Iniciar dapagliflozina 10 mg e furosemida 40 mg pela manhã (sulfonamida não-antibiótica, orientada a observar reação cutânea). Reduzir anlodipino para 5 mg. Manter losartana. K e creatinina em 1 semana. Pesagem diária e restrição de sódio. Retorno em 30 dias.'),
  (1070, 316, 6, '2023-03-14 02:20', 'pronto_socorro', 'Acordei sem ar e não consegui mais deitar', 182, 92, 108, 96.0, 'Pcte 74a, ICFEp, com dispneia súbita há 2h após churrasco em família no domingo, com muito sal e cerveja. Admite ter suspendido a furosemida na semana passada porque "fazia muito xixi na serra". REG, taquipneica, FR 30, SatO2 88% AA. Jugulares ingurgitadas, crepitantes até ápices, edema 3+. PA 182x92, FC 108. ECG: taquicardia sinusal, sem isquemia aguda. Troponina negativa. NT-proBNP 4.800. Peso +5 kg do habitual.', 'Furosemida 80 mg IV, nitroglicerina IV, VNI intermitente. Internação em enfermaria de cardiologia. Restrição hídrica, balanço diário e monitorização de creatinina e potássio.'),
  (1071, 316, 11, '2023-03-15 08:00', 'internacao', 'Internação por IC descompensada', 138, 78, 82, 92.0, 'D2 de internação. Boa diurese (3,2 L em 24h, -4 kg), sem necessidade de VNI, SatO2 95% AA. Creatinina 1,6 (basal 1,3), K 3,6, sem reação cutânea à furosemida. Ao exame: jugulares sem estase, MV+ com crepitantes residuais em bases, edema 1+. Transição para furosemida oral 40 mg 2x/dia e adição de espironolactona 12,5 mg com cautela (K, função renal). Alta em D5 com peso seco de 90 kg. Filha e paciente orientadas por nutricionista e enfermeira de IC.', 'Alta com furosemida 40 mg 12/12h, espironolactona 12,5 mg, dapagliflozina, losartana. Monitorizar K e creatinina em 5 dias. Peso diário e ligar se ganho > 2 kg em 3 dias. Retorno em 15 dias.'),
  (1072, 316, 11, '2024-02-20 11:00', 'retorno', 'Estive internada de novo duas vezes no ano', 126, 72, 70, 88.0, 'No último ano, mais duas internações por descompensação (junho e novembro de 2023), ambas por infecção urinária e transgressão alimentar. Creatinina progrediu para 1,9 (TFGe 27), K 5,2 com espironolactona. Dapagliflozina mantida. Sem tosse, edema 2+, CF III. NT-proBNP 3.100 mesmo no peso seco. Interrompida espironolactona, o que causou piora do edema. Ao exame: estertores bibasais, jugulares a 30°, RCR 2T. Evolução desfavorável com perda de função renal e IC com internações recorrentes.', 'Suspender espironolactona (K 5,2 e TFGe 27). Aumentar furosemida para 80 mg pela manhã e 40 mg à tarde. Encaminhar à nefrologia. Plano de cuidados e conversa com a filha sobre limitações; acompanhamento domiciliar de enfermagem.');
