insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (316, '2024-02-20', 'piorou', 'ICFEp com três internações em 11 meses por descompensação, perda progressiva da função renal (TFGe de 42 para 27) e necessidade de suspensão da espironolactona por hipercalemia. Mantém classe funcional III, em seguimento conjunto com nefrologia e enfermagem domiciliar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (317, 'Erasmo Hoffmeister Lopes', 'M', '1951-04-28', 'São Leopoldo', 'RS', 'Taxista aposentado', 'FA permanente há 6 anos em varfarina com INR instável, CHA2DS2-VASc 4 (idade, HAS, DM2). HAS e DM2 em uso de losartana 50 mg 12/12h e metformina. Dor lombar crônica, usa diclofenaco por conta própria. Etilismo social.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1073, 317, 6, '2022-09-13 06:10', 'pronto_socorro', 'Evacuei preto, mole e fedido, tonto de manhã', 100, 60, 108, 78.0, 'Pcte 71a com FA em uso de varfarina 5 mg/dia, refere dois dias de melena e tontura, associando uso de diclofenaco 50 mg 3x/dia há 10 dias por dor lombar, e ciprofloxacino por infecção urinária há 5 dias. REG, descorado 3+/4+, taquicárdico, PA 100x60, FC 108 irregular. Abdome doloroso em epigastro sem peritonismo. Toque retal com melena. Hb 7,4 g/dL, INR 7,8, creatinina 1,3. Hemorragia digestiva alta em paciente anticoagulado com INR supraterapêutico.', 'Suspender varfarina. Vitamina K 10 mg IV lenta e complexo protrombínico, 2 acessos venosos, reposição volêmica, concentrado de hemácias (2 U), omeprazol 80 mg IV em bolus e depois infusão. EDA nas primeiras 24h. Internar em UTI semi-intensiva.'),
  (1074, 317, 2, '2022-09-14 09:00', 'internacao', 'Endoscopia e acompanhamento da hemorragia', 118, 72, 86, 78.0, 'Após 2 U de hemácias, Hb 9,1, INR 1,9, estável. EDA: úlcera gástrica de 1,2 cm em antro com vaso visível (Forrest IIa), tratada com adrenalina e clipe hemostático, sem sangramento ativo. H. pylori positivo no teste da urease. FA com FC controlada em 86 sem fármacos. Discutida estratégia: ocorrência de hemorragia maior com INR muito lábil (TTR 38%) e AINE, mas FA com CHA2DS2-VASc 4 mantém indicação de anticoagulação. Retomar anticoagulação em 7-10 dias com DOAC, que tem menor risco de sangramento intracraniano, após cicatrização inicial.', 'Omeprazol 40 mg 12/12h por 8 semanas, esquema para H. pylori (omeprazol, claritromicina, amoxicilina por 14 dias). Suspender definitivamente AINE. Apixabana 5 mg 12/12h a partir do 7º dia, sem varfarina. Retorno ambulatorial em 3 semanas.'),
  (1075, 317, 1, '2022-11-08 10:30', 'retorno', 'Voltei para ver como estão o sangue e o remédio novo', 132, 76, 72, 79.5, 'Seis semanas após a hemorragia, sem melena, sem novos sangramentos, em uso de apixabana desde o dia 8 pós-evento. Hb 12,6 g/dL, creatinina 1,2 (ClCr 62), plaquetas normais. Completou erradicação do H. pylori. Dor lombar controlada com fisioterapia e paracetamol. Ao exame: FA com FC 72, sem sopros, sem edema. Apixabana 5 mg 12/12h adequada (idade < 80, peso > 60, creatinina < 1,5).', 'Manter apixabana 5 mg 12/12h, sem varfarina. Manter omeprazol até completar 8 semanas e depois suspender. Reforçar: nunca usar AINE. Hemograma e creatinina a cada 6 meses. Retorno em 6 meses.');
