insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (317, '2022-11-08', 'estavel', 'Hemorragia digestiva por úlcera gástrica com INR de 7,8 associada a AINE e ciprofloxacino, tratada com endoscopia e transfusão. Anticoagulação mantida com apixabana e H. pylori erradicado. Hb recuperada para 12,6 g/dL, sem novos sangramentos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (318, 'Querubina Sganzerla Moreira', 'F', '1942-08-21', 'Ijuí', 'RS', 'Agricultora aposentada', 'HAS em uso de metoprolol succinato 50 mg e hidroclorotiazida 25 mg. Catarata operada. Sem DM. Mora com o filho em área rural a 25 km da cidade. Há 2 meses com cansaço e episódios de escurecimento visual.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1076, 318, 6, '2021-03-30 11:40', 'pronto_socorro', 'Desmaiei na lavoura e caí no chão', 164, 72, 34, 62.0, 'Pcte 78a, síncope súbita enquanto colhia na horta, sem prodromos, recuperação em 1 minuto, mordedura de língua negativa. Hematoma frontal pequeno, sem TCE grave. Fria, pálida. FC 34 regular, PA 164x72, SatO2 96%. Ausculta cardíaca com bulhas bradicárdicas e intensidade variável de B1 (ondas em canhão no pescoço). ECG: dissociação atrioventricular completa, ondas P a 82 bpm, QRS estreito a 34 bpm: BAVT. K 4,0, TSH 3,1. HD: BAVT sintomático com síncope.', 'Suspender metoprolol imediatamente. Monitorização contínua, atropina disponível, pás de marca-passo transcutâneo na cabeceira. Internar para implante de marca-passo definitivo, contato com arritmologia. Jejum a partir de agora.'),
  (1077, 318, 4, '2021-03-31 08:30', 'internacao', 'Implante de marca-passo definitivo', 148, 70, 40, 62.0, 'Marca-passo provisório transvenoso implantado à noite por episódio de pausa de 5 segundos. Hoje, implante de marca-passo definitivo dupla câmara DDD, via veia cefálica esquerda, eletrodo atrial no apêndice e ventricular em septo. Limiares estáveis, sensibilidade adequada: P 3,2 mV, R 11 mV. RX de tórax sem pneumotórax. Ecocardiograma: FEVE 62%, esclerose valvar aórtica leve sem estenose. Após o implante, FC 70, bolsa com curativo limpo, sem hematoma. Alta no 2º dia.', 'Antibioticoprofilaxia pós-implante, curativo limpo por 10 dias, evitar levantar o braço esquerdo acima do ombro por 4 semanas. Carteira do MP entregue. Manter hidroclorotiazida, sem betabloqueador. Controle do dispositivo em 30 dias.'),
  (1078, 318, 4, '2021-05-11 09:30', 'retorno', 'Estou bem, voltei para a horta', 146, 80, 70, 63.5, 'Um mês e meio de pós-implante, sem síncope, ferida cicatrizada, sem dor na loja do gerador. Voltou às tarefas leves, disposta. Interrogação do dispositivo: DDD, estimulação ventricular 100% como esperado em BAVT, limiares estáveis (atrial 0,6 V, ventricular 0,5 V), bateria 100%, sem arritmias atriais. PA 146x80 apenas com hidroclorotiazida e sem betabloqueador. Conversa sobre acessos: mora longe, filho a traz para controle.', 'Adicionar anlodipino 5 mg pela PA. Controle do MP a cada 6 meses (presencial) e telemetria se disponível. Retorno em 6 meses com ECG. Orientar para procurar atendimento se tontura, síncope ou soluços persistentes.');
