insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (318, '2021-05-11', 'melhorou', 'BAVT com síncope resolvido com implante de marca-passo definitivo dupla câmara. Sem novos episódios de síncope, parâmetros do dispositivo estáveis e retorno às atividades na horta. Segue com revisões semestrais do marca-passo e anti-hipertensivo sem betabloqueador.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (319, 'Genivaldo Pereira Alencastro', 'M', '1967-11-18', 'Goiânia', 'GO', 'Pedreiro', 'Doença de Chagas conhecida há 10 anos (sorologia reagente). BAVT com marca-passo dupla câmara implantado em 2018. IC com FEVE 31% em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h, espironolactona 25 mg e furosemida 40 mg. Nasceu no interior de Goiás em casa de taipa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1079, 319, 11, '2021-08-24 08:40', 'consulta', 'Não consigo mais carregar peso, canso muito', 102, 64, 72, 66.0, 'Homem de 53 anos com cardiopatia chagásica, MP dupla câmara e IC. Dispneia aos pequenos esforços há 3 meses (NYHA III), edema vespertino de tornozelos, sem ortopneia. Parou de trabalhar como pedreiro há 5 meses. Ao exame: emagrecido, jugulares a 45°, RCR com B3, sopro sistólico mitral 2+/6, hepatomegalia a 3 cm. ECO: FEVE 27%, DDVE 69 mm, IM moderada funcional, sem trombos. NT-proBNP 3.400. Sem indicação de benznidazol (cardiopatia crônica estabelecida). Alta taxa de estimulação ventricular direita pelo MP pode contribuir para a piora.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36h de pausa, adicionar dapagliflozina 10 mg. Manter carvedilol e espironolactona, aumentar furosemida para 40 mg 12/12h. Solicitar reprogramação do MP e Holter. Encaminhar para benefício previdenciário. Retorno em 30 dias.'),
  (1080, 319, 11, '2022-02-15 09:00', 'retorno', 'Melhorei um pouco, mas ainda canso', 98, 60, 68, 64.8, 'Seis meses depois, NYHA III persistente, sem internação desde o último retorno. Reprogramação do MP para reduzir estimulação ventricular não resultou em melhora importante (BAV completo, dependente). ECO: FEVE 25%, QRS 168 ms por estimulação VD. Mantém hipotensão limítrofe (98x60) que limita titulação de carvedilol e sacubitril/valsartana. K 5,0, creatinina 1,2. Discussão sobre upgrade para ressincronização (CRT/CDI) devido a QRS largo e FEVE < 35%.', 'Encaminhar à arritmologia para upgrade para ressincronizador com CDI (CRT-D). Manter esquema sem titulação. Dieta com 1,5 L de líquido/dia, peso diário. Retorno em 3 meses.'),
  (1081, 319, 11, '2022-09-27 04:50', 'internacao', 'Internado por falta de ar e inchaço no corpo todo', 92, 58, 84, 71.0, 'Admitido em PS de madrugada com dispneia em repouso, ortopneia, edema de MMII até raiz de coxas e ascite. Ganho de 6 kg em 3 semanas, extremidades frias e perfusão lentificada, perfil frio-úmido. PA 92x58, SatO2 90%. Creatinina 1,8, lactato 2,6, Na 130. Internado para diuréticos IV e inotrópico (dobutamina 5 mcg/kg/min por 48h). Boa resposta: -7 kg em 8 dias, sem arritmias graves no monitor. ECO: FEVE 22%. Alta com peso seco de 64 kg. A equipe de IC avalia que o paciente tem critérios de IC avançada: 2 internações em 12 meses, hipotensão e dependência de inotrópico transitório.', 'Alta com esquema ajustado: furosemida 80 mg pela manhã, 40 mg à tarde; manter demais. Encaminhar a serviço de referência de IC avançada e transplante cardíaco. Reunir documentos e exames. Retorno em 15 dias.'),
  (1082, 319, 11, '2023-02-07 10:30', 'retorno', 'Vim buscar o encaminhamento para São Paulo', 96, 60, 70, 65.5, 'Compensado desde a alta, NYHA III, sem internação nos últimos 4 meses. Exames para listagem: sorologia atualizada, função renal estável (creatinina 1,5), prova de função pulmonar normal, cateterismo direito prévio com resistência pulmonar 2,4 WU. Hemoglobina 12,4. Sem contraindicações absolutas. CRT-D não foi implantado por limitação financeira do serviço; a equipe do centro de referência fará a reavaliação junto com a decisão de transplante. Paciente e esposa bem orientados e concordam com a transferência.', 'Encaminhado para centro de referência em IC avançada e transplante cardíaco em São Paulo com resumo clínico completo e exames. Manter esquema atual até a avaliação. Contato com a central de regulação para vaga de avaliação. Alta do ambulatório.');
