insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (319, '2023-02-07', 'transferido', 'Cardiopatia chagásica com IC avançada (FEVE 22%, MP convencional, internação com perfil frio-úmido) encaminhada para centro de referência em São Paulo para avaliação de ressincronização e transplante cardíaco. Saiu do acompanhamento local.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (320, 'Tales Brandão Nascimento', 'M', '1999-01-22', 'Florianópolis', 'SC', 'Estudante de engenharia e remador amador', 'Hígido, sem comorbidades. Praticava remo 5 vezes por semana. Quadro gripal com febre e mialgia há 7 dias, tratado com sintomáticos. Pai com hipertensão. Não fuma, bebe pouco.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1083, 320, 6, '2023-05-12 01:40', 'pronto_socorro', 'Dor forte no peito, parece que vou infartar', 126, 74, 102, 78.5, 'Jovem de 24 anos com dor torácica retroesternal em pontada, piora ao decúbito e melhora sentado e inclinado para frente, iniciada há 6h, após síndrome gripal há 1 semana. Febre baixa 37,6. BEG, eupneico, RCR 2T BNF, sem atrito, MV+ sem RA. ECG: supradesnivelamento côncavo de ST de 1-2 mm em DI, DII, aVF e V2-V6, com infra de PR. Troponina I 4,8 ng/mL (valor de referência < 0,03), PCR 62. Sem fatores de risco coronariano. HD: miopericardite aguda viral.', 'Internar para monitorização, repouso absoluto, colchicina 0,5 mg 12/12h, ibuprofeno 600 mg 8/8h com omeprazol. Solicitar ECO urgente e RM cardíaca. Orientado a suspender remo por 6 meses. Telemetria por 48h.'),
  (1084, 320, 2, '2023-05-13 10:00', 'internacao', 'Dor melhor, investigando miocardite', 118, 70, 78, 78.0, 'Dor torácica muito reduzida após analgesia e colchicina. Telemetria sem arritmias. ECO: FEVE 48% com hipocinesia da parede lateral e discreto derrame pericárdico (6 mm). RM cardíaca: edema miocárdico lateral e realce tardio subepicárdico em parede inferolateral, compatível com miocardite, sem sinais de isquemia. Troponina caiu para 2,1 no 2º dia. Painel viral, cultura e sorologias solicitados. Sem indicação de biópsia ou imunossupressor. Segue estável, sem sinais de IC.', 'Manter colchicina e ibuprofeno. Sem sinais de IC, não há indicação de IECA neste momento. Alta no 5º dia com restrição de esforço físico. Segue com ECO, Holter e RM em 3 meses. Retorno ambulatorial em 3 semanas.'),
  (1085, 320, 1, '2023-06-06 08:30', 'retorno', 'Sem dor, quando posso voltar a remar?', 114, 68, 64, 77.5, 'Três semanas depois, sem dor, sem palpitações, sem dispneia. Terminou o ibuprofeno e mantém colchicina. ECO: FEVE 58%, sem derrame. PCR 3 mg/L, troponina normalizada. Holter sem arritmias ventriculares relevantes. Ansioso para voltar ao treino e às provas de campeonato. Reforçada a regra de repouso esportivo mínimo de 3 a 6 meses após miocardite, porque atividade intensa precoce aumenta o risco de arritmia.', 'Manter colchicina até completar 3 meses. Proibido esporte competitivo ou treino intenso até nova RM e teste ergométrico em 6 meses. Caminhadas leves liberadas. Retorno em 3 meses.'),
  (1086, 320, 1, '2023-12-12 09:00', 'retorno', 'Vim para a liberação do esporte', 112, 66, 58, 79.0, 'Seis meses após o episódio, assintomático, mantendo caminhadas e bicicleta leve. RM cardíaca de controle: ausência de edema, realce tardio subepicárdico residual pequeno e fixo, FEVE 60%. Teste ergométrico máximo (13 METs) sem arritmias e sem alterações de ST. Holter normal. Troponina e PCR normais. Evolução favorável.', 'Liberado para retornar gradualmente ao remo e treinos, com progressão semanal. Se palpitações, síncope ou dor, parar e procurar atendimento. Retorno em 6 meses com ECG e Holter. Vacina anual da influenza.');
