insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (320, '2023-12-12', 'melhorou', 'Miocardite aguda pós-viral com função ventricular recuperada (FEVE 48% para 60%) e troponina normalizada. Teste ergométrico de 13 METs sem arritmias; liberado para retorno gradual ao esporte. Mantém pequeno realce tardio residual em seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (321, 'Tatiane Schmitz Corrêa', 'F', '1976-03-30', 'Canoas', 'RS', 'Atendente de telemarketing', 'Sem diagnóstico de HAS. PA elevada em duas aferições de serviço (160-170/100) no último ano, nunca investigada. Sedentária, estresse no trabalho, dorme cerca de 5 horas por noite. Mãe hipertensa em hemodiálise por nefroesclerose.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1087, 321, 5, '2024-01-23 12:20', 'consulta', 'A enfermeira do trabalho disse que a pressão está muito alta', 168, 104, 84, 79.0, 'Mulher de 47 anos, assintomática, com PA de 168x104 e 172x106 em duas medidas separadas no braço direito, também 166x102 no esquerdo. IMC 29,6. Ao exame: sem sopros, pulsos simétricos, sem edema, sem sinais de Cushing. Exames: creatinina 0,8, K 4,1, glicemia 94, LDL 138, EAS normal, TSH 1,9. ECG com ritmo sinusal e sinais de início de SVE. Hipertensão estágio 2 com lesão de órgão-alvo inicial. Opto por tratamento imediato com combinação, associada a MEV.', 'Iniciar olmesartana 40 mg + anlodipino 5 mg em comprimido único, 1x/dia. MRPA em 2 semanas, perfil lipídico em 3 meses, sono e ingestão de sal. Retorno em 5 semanas. Orientada a não usar descongestionantes.'),
  (1088, 321, 5, '2024-02-27 12:40', 'retorno', 'Os pés estão um pouco inchados no fim do dia', 138, 86, 78, 78.5, 'Retorna com MRPA de 5 dias: média 140x88. Boa adesão, comprimido único facilitou, esquece pouco. Queixa de edema leve de tornozelos vespertino, 1+, relacionado ao anlodipino, sem cefaleia. Creatinina 0,8 e K 4,2. PA caiu quase 30 mmHg, mas ainda acima da meta de < 130/80. Reduziu o refrigerante, caminha 2x por semana no intervalo do almoço.', 'Manter olmesartana 40 mg + anlodipino 5 mg e associar hidroclorotiazida 12,5 mg, em vez de subir o anlodipino, para não piorar o edema. Elevar pernas ao fim do dia. Retorno em 8 semanas.'),
  (1089, 321, 5, '2024-06-11 12:30', 'retorno', 'Pressão boa, vim mostrar os valores de casa', 122, 76, 74, 76.4, 'Quatro meses depois, sem edema nem tosse. MRPA média 124x76. Perdeu 2,6 kg, dorme 6h30 por noite, mantém caminhadas. Exames: creatinina 0,8, K 4,0, Na 140, ácido úrico 5,4, glicemia 92, LDL 112 (sem estatina, baixo risco). ECG sem progressão. Meta de PA atingida com dois fármacos em dois comprimidos.', 'Manter esquema atual, controle de K e creatinina a cada 6 meses. Reforçar sono e MEV. Retorno semestral com MRPA. Se perda ponderal continuar e PA < 120/70, reavaliar a redução de dose.');
