insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (321, '2024-06-11', 'controlado', 'Hipertensão estágio 2 iniciada com combinação em comprimido único e depois acrescida de hidroclorotiazida. MRPA de 124x76 mmHg, edema resolvido, perda de 2,6 kg e melhor sono. Segue em acompanhamento semestral na atenção primária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (322, 'Ananias Gomes Seixas', 'M', '1960-01-09', 'Itajaí', 'SC', 'Trabalhador portuário avulso', 'HAS há 18 anos, em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Sobrepeso, apneia suspeitada por roncos. Consome 2-3 cervejas por dia. Pai falecido de AVC aos 66 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1090, 322, 1, '2021-03-09 08:10', 'consulta', 'Mesmo com três remédios a pressão não passa de 17', 178, 104, 76, 94.0, 'Homem de 61 anos, hipertenso com PA 178x104 apesar de losartana 100, anlodipino 10 e clortalidona 25. Adesão checada: pegou os remédios na farmácia nos últimos 6 meses, contou os comprimidos e traz a caixinha vazia; toma pela manhã com café. MAPA na vigília 168x98, sono 152x88, confirmando HAS resistente verdadeira. Exames: creatinina 1,1, K 3,9, aldosterona 11 ng/dL com renina 1,8 ng/mL/h (relação baixa), TSH normal. Sem sopros abdominais. Álcool e sal elevados, IAH ainda não avaliado.', 'Iniciar espironolactona 25 mg/dia como 4º fármaco. K e creatinina em 1 semana. Reduzir álcool e sal. Solicitar polissonografia. Retorno em 6 semanas.'),
  (1091, 322, 1, '2021-04-20 08:30', 'retorno', 'A pressão melhorou, estou com o peito sensível', 148, 88, 72, 93.0, 'Após 6 semanas de espironolactona, PA 148x88 (queda de 30 mmHg sistólica). K 4,6 e creatinina 1,2, aceitáveis. Polissonografia: IAH 14/h, apneia moderada, sem dessaturação grave. Relata sensibilidade mamilar discreta bilateral. Exame: nódulo palpável retroareolar de 1 cm, doloroso, bilateral, mais à esquerda. Compatível com ginecomastia por espironolactona. Resistência verdadeira, pois PA subiu com a 4ª droga e normalizou parcialmente.', 'Manter espironolactona 25 mg por ora, com troca por eplerenona se a ginecomastia ficar dolorosa. Reavaliar em 2 meses, associando perda de peso e redução do álcool. Orientado sobre CPAP caso IAH aumente.'),
  (1092, 322, 1, '2021-09-14 08:00', 'retorno', 'Os peitos doem, dói até encostar na camisa', 134, 82, 70, 90.5, 'Cinco meses de espironolactona 25 mg. PA 134x82, MRPA em torno de 130x80, boa resposta. Ginecomastia dolorosa progressiva, constrangimento no trabalho, evitando tirar a camisa na quadra. Perdeu 3,5 kg e reduziu cerveja para fins de semana. K 4,7, creatinina 1,2. Exame: ginecomastia bilateral de 3 cm, dolorosa. Sem outras causas (testosterona e TSH normais). Dor limita adesão.', 'Trocar espironolactona por eplerenona 50 mg/dia (menor efeito antiandrogênico). K em 1 semana. Manter demais fármacos. Retorno em 2 meses.'),
  (1093, 322, 1, '2022-03-08 08:20', 'retorno', 'Dor nos peitos passou e a pressão tá boa', 128, 78, 68, 89.2, 'Seis meses de eplerenona, dor mamária resolvida em poucas semanas, ginecomastia residual leve. PA 128x78, MRPA média 126x76. K 4,9, creatinina 1,2, TFGe 68. Sem edema, sem sintomas. Perdeu 4,8 kg em um ano. Ainda consome álcool aos fins de semana, mas bem menos. Satisfeito: "agora consigo jogar bola de camisa".', 'Manter os quatro fármacos. Monitorar K e creatinina a cada 4 meses. Meta de peso < 85 kg. Reavaliar apneia anualmente. Retorno em 4 meses.');
