insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (322, '2022-03-08', 'controlado', 'Hipertensão resistente verdadeira, confirmada por MAPA com adesão comprovada, controlada com quatro fármacos. A espironolactona causou ginecomastia dolorosa e foi trocada por eplerenona. MRPA de 126x76 mmHg, perda de 4,8 kg e potássio monitorado a cada 4 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (323, 'Zuleica Brandt Ferreira', 'F', '1968-09-17', 'Lajeado', 'RS', 'Proprietária de padaria', 'HAS há 6 anos, em uso irregular de losartana 50 mg. Parou por conta própria há 2 semanas porque "deu tontura". Estresse importante com a reforma do negócio. Sono ruim. Não fuma, consome sal em abundância no pão e frios.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1094, 323, 6, '2023-08-19 21:10', 'pronto_socorro', 'Dor de cabeça na nuca e pressão 21 por 12 em casa', 214, 124, 88, 74.0, 'Pcte 54a, cefaleia occipital há 4h, sem vômitos, sem alterações visuais, sem déficit neurológico, sem dor torácica ou dispneia. Pressão de 214x124 em ambos os braços, confirmada após 30 min de repouso (206x120). ECG: ritmo sinusal, SVE leve, sem isquemia. Fundoscopia sem papiledema nem hemorragias. Troponina negativa, creatinina 0,9, EAS sem hematúria ou proteinúria. Neurológico sem focais. Urgência hipertensiva sem lesão aguda de órgão-alvo, desencadeada por suspensão de losartana e estresse.', 'Repouso em ambiente calmo, captopril 25 mg VO e reavaliar em 60 min. Evitar redução abrupta da PA e não usar nifedipino sublingual. PA após 2h: 176x102. Alta com losartana e anlodipino, retorno em 7 dias, orientada sobre sinais de alarme.'),
  (1095, 323, 1, '2023-08-28 08:30', 'retorno', 'Vim ver como está a pressão depois do susto', 152, 92, 80, 74.2, 'Retorno 9 dias após urgência hipertensiva. Cefaleia resolvida no dia seguinte. Tomando losartana 50 mg 12/12h e anlodipino 5 mg regularmente, sem tontura, ajudada por alarme no celular. PA 152x92, FC 80. O que ela chamou de tontura com o losartana foi hipotensão relativa de um dia em que tomou em jejum com pouca água. Exame físico sem alterações. Relata dormir mal e consumir muito café e salgadinhos na padaria.', 'Manter esquema. Solicitar MAPA, perfil lipídico, glicemia e ecocardiograma. Orientação de sal e horários de sono. Mostrar que a pressão alta não dá sintomas e que parar o remédio é perigoso. Retorno em 30 dias.'),
  (1096, 323, 1, '2023-11-21 08:40', 'retorno', 'Estou tomando tudo certo, pressão boa', 128, 80, 72, 72.8, 'Retorna com MAPA: média 24h 126x78, vigília 130x82, sono 114x68, descenso preservado. ECO com hipertrofia concêntrica leve (septo 12 mm), FEVE 64%. Glicemia 98, LDL 128, creatinina 0,9, K 4,2. Reduziu o sal na padaria, mudou o café por descafeinado à tarde. Mantém boa adesão com despertador. Relata que levou o susto muito a sério.', 'Manter losartana e anlodipino. Controle de LDL com MEV por 6 meses. Retorno semestral com MRPA. Reforçada a regra: nunca suspender o remédio sem conversar. Vacina da gripe.');
