insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (323, '2023-11-21', 'controlado', 'Urgência hipertensiva por suspensão do losartana sem lesão de órgão-alvo, tratada ambulatorialmente. Três meses depois a MAPA mostra média 126x78 mmHg com boa adesão, hipertrofia leve no ECO e seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (324, 'Moisés Zimmermann Aguiar', 'M', '1978-06-03', 'São José', 'SC', 'Motorista de ônibus urbano', 'Sem diagnóstico de HAS. PA de consultório sempre normal-limítrofe (126-132/80-84). Tabagista leve (5 cigarros/dia). Trabalha em turnos, dorme mal e consome 6 cafés por dia e energéticos nas madrugadas. Pai hipertenso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1097, 324, 5, '2022-10-04 16:30', 'consulta', 'Dor de cabeça no fim do plantão e o exame do trabalho deu alteração', 128, 82, 76, 84.0, 'Homem de 44 anos, motorista de ônibus. Exame periódico mostrou SVE no ECG (Sokolow-Lyon 38 mm) e relação albumina/creatinina de 42 mg/g. PA de consultório 128x82, 126x80 em medidas repetidas, normal-limítrofe. Queixa de cefaleia vespertina no fim do plantão. Sem outros sintomas. Exame físico normal. Lesão de órgão-alvo (HVE e albuminúria) com PA de consultório normal sugere hipertensão mascarada. Estresse ocupacional e cafeína em excesso como fatores.', 'Solicitar MAPA 24h, ECO, creatinina e perfil lipídico. Redução de cafeína, energéticos e cigarro. Retorno em 30 dias com resultados.'),
  (1098, 324, 1, '2022-11-08 16:50', 'retorno', 'Trouxe a MAPA e o ecocardiograma', 130, 82, 74, 84.5, 'MAPA 24h: média da vigília 146x92, média do sono 124x76, média 24h 138x86. PA de consultório 130x82. Isso configura hipertensão mascarada. ECO: HVE concêntrica leve (septo 12 mm, massa indexada 118 g/m²), FEVE 62%, disfunção diastólica grau 1. Creatinina 0,9, K 4,3, LDL 142. Apesar de a PA de consultório ser normal, o risco é igual ao dos hipertensos sustentados. Explicado ao paciente com figuras.', 'Iniciar losartana 50 mg e acompanhar com MRPA. Estatina não indicada ainda (baixo risco, LDL 142), MEV e cessação do tabagismo. Reduzir café a 3 por dia. Retorno em 2 meses com MRPA.'),
  (1099, 324, 1, '2023-03-14 17:10', 'retorno', 'Parei de fumar faz dois meses', 120, 76, 70, 82.6, 'Quatro meses após o início do tratamento. Parou de fumar, reduziu o café para 2 por dia, sem energéticos, cefaleia do fim do plantão desapareceu. MRPA com média 124x78 (antes, em casa, sua média era 142x90 no folheto de automedida). Sem efeitos adversos do losartana. Creatinina 0,9, K 4,2, relação albumina/creatinina 18 mg/g (normalizou). Perdeu 1,9 kg.', 'Manter losartana 50 mg. MAPA de controle em 12 meses e ECO em 1 ano para avaliar regressão da HVE. Retorno em 6 meses.');
