insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (324, '2023-03-14', 'controlado', 'Hipertensão mascarada identificada por MAPA em motorista com HVE e albuminúria e PA de consultório normal. Com losartana, cessação do tabagismo e menos cafeína, o MRPA ficou em 124x78 mmHg e a albuminúria normalizou. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (325, 'Graciliana Dambros Teixeira', 'F', '1953-01-14', 'Erechim', 'RS', 'Comerciante', 'HAS, DM2 em uso de metformina, obesidade grau 1, ex-tabagista (parou há 15 anos). Dona de loja de armarinhos, trabalha sozinha e tem a renda reduzida após a pandemia. Mãe com infarto aos 70 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1100, 325, 6, '2021-11-09 22:30', 'pronto_socorro', 'Dor no peito com suor frio e enjoo, depois do jantar', 168, 94, 92, 78.0, 'Mulher de 68 anos com dor retroesternal em aperto, duração de 40 min, irradiada para o dorso e ombro esquerdo, náusea e sudorese. Dor ainda presente à chegada (6/10). Ao exame: ansiosa, RCR 2T B4, MV+ sem RA, sem edema. ECG: infradesnível de ST de 2 mm em V4 a V6 e DI, sem supra. Troponina ultrassensível 480 ng/L (referência < 14), segunda amostra 920 ng/L. Killip I. HD: IAMSSST, GRACE alto risco, indicada estratificação invasiva em 24h.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 60 mg SC 12/12h, atorvastatina 80 mg, nitroglicerina IV para dor. Internar em UCO e CATE em < 24h. Manter metformina suspensa.'),
  (1101, 325, 10, '2021-11-10 15:00', 'internacao', 'CATE e angioplastia na internação por IAM sem supra', 134, 76, 66, 78.0, 'CATE por via radial direita: lesão culpada na artéria circunflexa média, 95% com trombo, DA com lesão de 50% no terço médio, CD sem lesões, FEVE 54%. ATC com implante de stent farmacológico 3,0 x 18 mm na Cx, resultado final com TIMI 3 e sem lesão residual. Pico de troponina 3.600 ng/L. Evolui sem angina, sem arritmias, sem insuficiência cardíaca. ECO: FEVE 54%, hipocinesia lateral. Alta no 4º dia com orientações sobre antiagregação dupla por 12 meses, mudança alimentar, glicemia.', 'AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses, atorvastatina 80, carvedilol 6,25 mg 12/12h, metformina retomada, losartana 50 mg 12/12h. Reabilitação cardíaca. Retorno em 30 dias. Alertada sobre nunca interromper o ticagrelor sem falar com o médico.'),
  (1102, 325, 2, '2022-02-15 14:30', 'retorno', 'Estou sem dor, mas o remédio do sangue é muito caro', 136, 80, 62, 76.5, 'Três meses do IAM e stent, assintomática, sem angina. Não compareceu à reabilitação por falta de tempo e de transporte, loja sem funcionários. Admite que, nas últimas 3 semanas, tomou ticagrelor só quando lembrava, pelo preço (R$ 140 a caixa), e que "os remédios do coração estão me deixando falida". PA 136x80, FC 62. LDL 78 com atorvastatina, HbA1c 7,4%. Foi alertada do risco de trombose do stent com a suspensão do antiagregante antes de 12 meses. Concorda em buscar clopidogrel genérico.', 'Trocar ticagrelor por clopidogrel 75 mg/dia (mais barato, disponível na UBS) até completar 12 meses do evento. Manter AAS, atorvastatina, carvedilol e losartana. Contato com assistente social para alternativas de retirada. Retorno em 2 meses.');
