insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (326, '2023-04-13', 'obito', 'Óbito em enfermaria de cuidados paliativos, 2 dias após chegar ao pronto-socorro com choque cardiogênico por ICFEr isquêmica terminal (FEVE 22%, anúria e caquexia). Sem intubação e sem reanimação, conforme plano combinado com o paciente e o filho, que estava presente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (327, 'Amélia Vorpagel Doná', 'F', '1944-11-28', 'Tubarão', 'SC', 'Professora aposentada', 'FA permanente descoberta há 2 anos, HAS e dislipidemia. CHA2DS2-VASc 5 (idade ≥ 75, mulher, HAS, previamente sem AVC). Viúva, vive com a filha. Usa losartana 50 mg 12/12h e sinvastatina 20 mg. Medo de sangramento por ter visto um vizinho sangrar com anticoagulante.', 'Alergia a iodo (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1107, 327, 2, '2022-05-03 10:30', 'consulta', 'Vim ver se preciso mesmo do remédio para afinar o sangue', 140, 82, 86, 62.0, 'Mulher de 77 anos com FA permanente, assintomática, em uso de metoprolol e losartana. Recusou anticoagulação até agora por medo de sangramento. Ao exame: RCI 2T, FC 86, sem sopros, sem edema. ECO: átrio esquerdo 46 mm, FEVE 60%, sem valvopatia relevante. Hb 13,0, creatinina 1,1 (ClCr 42 mL/min), plaquetas normais. CHA2DS2-VASc 5 (risco de AVC ~7%/ano), HAS-BLED 2. Explicados benefícios e riscos com apoio da filha, que acompanhou a consulta.', 'Indicada anticoagulação: rivaroxabana 15 mg/dia com a refeição (ClCr 15-49). Manter metoprolol succinato e losartana. Hemograma e creatinina em 3 meses. Orientações sobre sinais de sangramento e interações. Retorno em 60 dias.'),
  (1108, 327, 6, '2022-10-22 07:50', 'pronto_socorro', 'Acordou com o braço e a perna direita moles e sem falar direito', 196, 104, 96, null, 'Pcte 77a, a filha encontrou-a às 6h45 com hemiparesia direita completa, desvio de rima labial e afasia expressiva. Última vez vista bem: 23h da véspera, portanto janela > 4,5h. A filha informa que a mãe parou a rivaroxabana há cerca de 4 meses, pois "melhorou da coisa do coração" e pela fala do vizinho. NIHSS 15. PA 196x104, ECG com FA a 96 bpm, glicemia 142. TC de crânio sem sangramento, sinal da artéria cerebral média hiperdensa à esquerda. HD: AVC isquêmico cardioembólico em território da ACM esquerda, fora da janela de trombólise.', 'Avaliação neurológica imediata e angiotomografia de crânio e pescoço para avaliar trombectomia (alergia a iodo: pré-medicação com corticoide e anti-histamínico). Evitar reduzir a PA abaixo de 220x120. Internação em unidade de AVC.'),
  (1109, 327, 13, '2022-10-23 09:00', 'internacao', 'Internação em unidade de AVC', 168, 90, 84, 61.0, 'Angiotomografia: oclusão do segmento M1 da ACM esquerda, com boa circulação colateral. Trombectomia mecânica realizada em 12h do início (janela estendida), recanalização TICI 2b. NIHSS caiu de 15 para 9. TC de controle com infarto subcortical e cortical frontoparietal esquerdo, sem transformação hemorrágica. Deglutição prejudicada, passagem de sonda nasoenteral. Hemiparesia direita (força grau 2 no MS e 3 no MI) e afasia mista. PA 168x90 controlada para alvo. Iniciada fisioterapia e fonoaudiologia no 2º dia.', 'Reintroduzir anticoagulação com apixabana 5 mg 12/12h no 7º dia (infarto moderado) após nova TC. Estatina de alta potência, controle de PA com losartana e anlodipino. Reabilitação multiprofissional intensiva. Alta com sonda, após treinamento da filha, em 3 semanas.'),
  (1110, 327, 13, '2023-03-14 14:00', 'retorno', 'Minha mãe ainda não fala e não anda sozinha', 134, 76, 72, 56.0, 'Cinco meses após o AVC, vem de cadeira de rodas, acompanhada pela filha. Mantém hemiparesia direita (força 3 no MI, 2 no MS, sem uso funcional da mão), disartria e afasia motora com compreensão preservada para ordens simples. Escala de Rankin 4. Em uso regular de apixabana, sem sangramentos. Alimentação por via oral com dieta pastosa, perda de 5 kg. Humor deprimido. PA 134x76. Filha exausta, sem apoio de cuidadores.', 'Manter apixabana, atorvastatina e losartana. Iniciar sertralina 50 mg. Manter fisioterapia e fonoterapia 3x por semana. Encaminhar ao serviço social para cuidador e adaptação domiciliar. Retorno em 3 meses.');
