insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (327, '2023-03-14', 'piorou', 'AVC isquêmico cardioembólico extenso após suspensão por conta própria da rivaroxabana por medo de sangramento. Deixou sequelas importantes: hemiparesia direita, afasia, dependência para as atividades diárias (Rankin 4) e depressão. Mantém apixabana e segue em reabilitação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (328, 'Raimunda Kobayashi Pontes', 'F', '1957-03-08', 'Londrina', 'PR', 'Técnica de enfermagem aposentada', 'Sopro cardíaco conhecido desde a juventude, acompanhado de forma irregular. HAS leve em uso de losartana 50 mg. Mãe de ascendência japonesa. Nunca fumou, caminha 3x por semana, mas há 1 ano interrompeu por cansaço.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1111, 328, 1, '2023-05-16 14:20', 'consulta', 'Cansaço e palpitação quando subo escadas', 136, 78, 82, 58.0, 'Mulher de 66 anos com dispneia aos moderados esforços há 1 ano (NYHA II-III), palpitações ocasionais e fadiga. Ao exame: RCR 2T, sopro holossistólico 4+/6 em foco mitral com irradiação para axila, B3 presente, estertores bibasais discretos, sem edema. ECO transtorácico: prolapso do folheto posterior (P2) com regurgitação mitral importante, jato excêntrico, DSVE 42 mm, FEVE 58%, PSAP 44 mmHg, átrio esquerdo 52 mm. Insuficiência mitral importante sintomática por prolapso, FEVE no limiar de intervenção.', 'Solicitar ETE para avaliar a anatomia e a possibilidade de plástica. Encaminhar para a cirurgia cardíaca. Manter losartana e adicionar furosemida 20 mg para alívio dos sintomas. ECG e Holter para pesquisa de FA. Retorno em 30 dias.'),
  (1112, 328, 12, '2023-06-27 09:00', 'retorno', 'Vim saber se vou ter que trocar a válvula', 130, 76, 78, 57.8, 'Retorna com ETE: prolapso do segmento P2 por ruptura de cordoalha, valva com tecido redundante porém sem calcificação e sem endocardite, anel de 38 mm, fração de regurgitação 55%. Holter: ritmo sinusal, ESV isoladas, sem FA. Cateterismo: coronárias normais. Pela anatomia favorável, o cirurgião indica plástica mitral (ressecção quadrangular de P2 + anuloplastia com anel), com alta probabilidade de reparo sem prótese. Paciente prefere não usar anticoagulante pelo resto da vida, razão pela qual a plástica é a melhor opção.', 'Agendar cirurgia de plástica mitral em agosto. Exames pré-operatórios e avaliação odontológica. Manter furosemida e losartana, suspender losartana 24h antes. Consentimento informado explicado com a filha presente.'),
  (1113, 328, 12, '2023-08-22 07:00', 'internacao', 'Cirurgia de plástica da valva mitral', 128, 74, 76, 57.5, 'Plástica mitral por esternotomia mediana com ressecção quadrangular de P2, implante de anel flexível de 34 mm e neocordoalhas. Tempo de CEC 112 min, pinçamento 78 min. ETE intraoperatório: IM residual mínima, sem SAM, gradiente médio 3 mmHg. Pós-operatório em UTI, extubada em 5h, sem sangramento nem arritmias, FA breve no 2º dia revertida com amiodarona. Alta no 7º dia, ferida limpa, sem complicações, em ritmo sinusal.', 'Alta com AAS 100 mg e varfarina por 3 meses (INR 2 a 3), furosemida, amiodarona por 30 dias, losartana. Fisioterapia respiratória e motora. Profilaxia de endocardite com amoxicilina antes de dentista. Retorno em 30 dias com INR.'),
  (1114, 328, 1, '2024-01-16 14:30', 'retorno', 'Estou ótima, voltei a caminhar na praça', 124, 72, 66, 59.0, 'Cinco meses de pós-operatório de plástica mitral, sem dispneia, voltou às caminhadas de 40 minutos. Varfarina concluída aos 3 meses, hoje só AAS. ECO: anel bem posicionado, IM discreta (grau 1), FEVE 60%, DSVE 36 mm, PSAP 28 mmHg, átrio esquerdo 44 mm. ECG: ritmo sinusal. Cicatriz esternal boa, sem queixas. Satisfeita por não depender de anticoagulante.', 'Suspender furosemida, manter losartana e AAS 100 mg. ECO anual e controle odontológico semestral com profilaxia de endocardite. Retorno em 6 meses.');
