insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (328, '2024-01-16', 'melhorou', 'Insuficiência mitral importante por prolapso tratada com plástica mitral sem prótese. Sem dispneia em 5 meses, IM discreta e FEVE 60% ao ECO; anticoagulante suspenso após 3 meses. Mantém seguimento anual com ecocardiograma e profilaxia de endocardite.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (329, 'Larissa Medeiros Quintanilha', 'F', '1991-02-11', 'Brasília', 'DF', 'Advogada', 'Hígida. Palpitações esporádicas desde a adolescência, com episódios súbitos de início e término abruptos. Consome 4 cafés por dia e energéticos em semanas de audiência. Não fuma. Sem uso de medicações contínuas. Mãe com arritmia não especificada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1115, 329, 6, '2024-01-20 14:10', 'pronto_socorro', 'Coração disparou de repente, não para', 112, 70, 188, 61.0, 'Pcte 32a, durante uma audiência, início súbito de palpitação regular, tontura leve, aperto no peito, sem síncope. Há 50 min. REG, ansiosa, pálida, PA 112x70, FC 188, SatO2 98%. ECG: taquicardia regular de QRS estreito, 188 bpm, sem onda P visível. HD: taquicardia supraventricular paroxística (provável reentrada nodal). Manobra de Valsalva modificada sem reversão. Adenosina 6 mg IV em bolus rápido: reversão imediata para ritmo sinusal com FC 78.', 'ECG pós-reversão sem pré-excitação, sem alteração de repolarização. Alta após 2h de observação. Orientada a reconhecer episódios, manobras vagais, evitar cafeína e energéticos. Referenciar à arritmologia para avaliar estudo eletrofisiológico e ablação.'),
  (1116, 329, 4, '2024-02-13 10:00', 'consulta', 'Quero resolver, tenho medo de acontecer no tribunal', 110, 68, 72, 60.8, 'Mulher de 33 anos, tem episódios de palpitação súbita 2 a 3 vezes ao ano, cada um com duração de 20 minutos a 1 hora, o último na semana passada reverteu sozinho. Exames: ECO normal (FEVE 64%, sem cardiopatia estrutural), TSH 1,6, Holter de 24h com ritmo sinusal e ESV raras, sem pré-excitação. Perfil clínico típico de TRN (taquicardia por reentrada nodal). Discutimos as opções: betabloqueador contínuo ou ablação por cateter com taxa de cura > 95% e risco de BAV < 1%. Ela prefere ablação.', 'Agendar estudo eletrofisiológico com ablação por radiofrequência. No intervalo, decidido em conjunto não usar medicação contínua. Seguir com manobras vagais e retorno ao PS se crise > 30 min.'),
  (1117, 329, 4, '2024-03-26 07:30', 'internacao', 'Internação para ablação', 114, 70, 70, 60.5, 'Estudo eletrofisiológico sob sedação: indução de taquicardia por reentrada nodal tipo slow-fast com ciclo de 320 ms, sem via acessória. Ablação por radiofrequência da via lenta no triângulo de Koch, com ritmo juncional acelerado durante a aplicação, sem BAV. Após a ablação, nenhuma taquicardia inducível mesmo com isoproterenol. PR pós-ablação 150 ms. Sem complicações no acesso femoral, alta após 6h de repouso.', 'Alta no mesmo dia. Evitar esforços intensos e carregar peso por 7 dias. Sem necessidade de antiagregante após este procedimento. Retornar se palpitações. Consulta de retorno com ECG em 3 meses.'),
  (1118, 329, 4, '2024-06-18 10:20', 'retorno', 'Sem nenhuma palpitação desde a ablação', 108, 66, 66, 61.5, 'Três meses depois, assintomática, retomou a rotina e as audiências sem episódios de taquicardia. Mantém café moderado (2 por dia), parou com energéticos. ECG de repouso normal, PR 152 ms, sem pré-excitação. Sem hematoma ou dor inguinal. Nenhuma medicação em uso. Expectativa de cura e alta definitiva do ambulatório de arritmia.', 'Alta do seguimento arritmológico. Orientada a procurar atendimento se retornarem palpitações regulares súbitas. Controle cardiológico anual preventivo, opcional.');
