  (1116, 'Holter 24h', 'Ritmo sinusal, FC média 74 bpm, ESV raras, sem taquicardia ou pré-excitação'),
  (1116, 'Ecocardiograma transtorácico', 'Estrutura normal, FEVE 64%'),
  (1116, 'TSH', '1,6 mUI/L'),
  (1117, 'Estudo eletrofisiológico', 'TRN slow-fast, ciclo 320 ms; ablação da via lenta bem-sucedida, sem taquicardia inducível pós-isoproterenol'),
  (1117, 'ECG pós-ablação', 'Ritmo sinusal, PR 150 ms, sem pré-excitação'),
