insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (329, '2024-06-18', 'controlado', 'Taquicardia por reentrada nodal tratada com ablação por radiofrequência da via lenta, procedimento sem complicações. Sem palpitações em 3 meses, ECG normal sem medicação, com alta do ambulatório de arritmia e retorno às atividades profissionais.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (330, 'Hermínio Wolski Prestes', 'M', '1955-02-19', 'São Bento do Sul', 'SC', 'Marceneiro aposentado', 'Tabagista de 50 maços-ano, parou há 1 ano após um quadro pulmonar. HAS, DLP, DM2 em tratamento com metformina. Doença coronariana não conhecida. Pai com amputação de perna por doença vascular. Mantém atividades de marcenaria no quintal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1119, 330, 1, '2023-06-13 09:20', 'consulta', 'Dor na panturrilha direita quando ando uns 150 metros', 152, 86, 74, 83.0, 'Homem de 68 anos com dor em queimação na panturrilha direita ao caminhar cerca de 150 metros, que obriga a parar e cede em 3 a 5 minutos de repouso, há 8 meses, com piora progressiva. Sem dor em repouso ou lesões nos pés. Ao exame: pulsos femorais presentes, poplíteo e pediosos direitos ausentes, esquerdos diminuídos, pele fria, pelos escassos no pé direito, sem úlceras. ITB direito 0,58 e esquerdo 0,76. Quadro compatível com doença arterial periférica sintomática, Fontaine IIb, Rutherford 3.', 'Iniciar AAS 100 mg e atorvastatina 80 mg, associar cilostazol 100 mg 12/12h. Programa de caminhada supervisionada, cessação total do tabagismo mantida, cuidados com os pés. Solicitar Doppler arterial de MMII e ECG. Retorno em 2 meses.'),
  (1120, 330, 1, '2023-08-22 09:00', 'retorno', 'Ando um pouco mais, mas ainda paro para descansar', 138, 80, 72, 82.0, 'Dois meses depois, distância de claudicação melhorou para 250 m. Faz caminhada 3x por semana com a fisioterapeuta. Cefaleia e diarreia leve na primeira semana de cilostazol, resolvidas. Doppler arterial: oclusão do segmento superficial da artéria femoral direita (longa extensão), reenchimento do poplíteo por colaterais, artéria tibial posterior pérvia; esquerda com estenose de 60% em femoral superficial. LDL 62 com atorvastatina, HbA1c 7,0%. ECG normal, sem angina nem equivalentes. Optado por manejo clínico e exercício, sem indicação de revascularização por ora.', 'Manter cilostazol, AAS e estatina. Intensificar o programa de caminhada, até 45 min 3x por semana. Podoscopia e cuidados com os pés. Avaliação vascular se dor em repouso, úlcera ou claudicação < 100 m. Retorno em 6 meses.'),
  (1121, 330, 1, '2024-02-27 10:00', 'retorno', 'Consigo andar quase 400 metros, voltei à oficina', 130, 78, 70, 81.0, 'Oito meses de tratamento clínico. Claudicação a cerca de 400 m, sem dor em repouso ou lesões nos pés. Mantém abstinência de tabaco e caminhadas. ITB direito 0,66 e esquerdo 0,80. LDL 58, HbA1c 6,8%, creatinina 1,0. PA 130x78. Sem sinais de isquemia crítica. Voltou a trabalhar na marcenaria por algumas horas por dia, com pausas para descansar. Foi explicado que a doença é um marcador de risco coronariano e cerebrovascular elevado.', 'Manter tratamento clínico e exercícios. ECO e teste de esforço com avaliação coronária, caso apareça dispneia ou dor torácica. Retorno em 6 meses com ITB. Vacina de influenza anual e inspeção diária dos pés.');
