insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (330, '2024-02-27', 'estavel', 'Doença arterial periférica com claudicação intermitente em tratamento clínico: distância de caminhada de 150 para 400 metros, sem dor em repouso ou úlceras, abstinência de tabaco mantida e LDL de 58. Segue com ITB semestral e sem indicação de revascularização.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (331, 'Priscila Hasselmann Dutra', 'F', '1990-05-22', 'Santa Rosa', 'RS', 'Bancária', 'Sem comorbidades conhecidas. Sedentária, trabalha sentada 8 horas por dia, almoça fora e consome muito embutido e salgadinhos. IMC 28,5. Anticoncepcional oral combinado há 8 anos. Mãe e avó hipertensas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1122, 331, 5, '2024-03-05 12:10', 'consulta', 'Quero fazer um check-up, minha mãe tem pressão alta', 128, 84, 78, 76.5, 'Mulher de 33 anos, assintomática, procura check-up. PA em consultório 128x84 e 130x86 em duas medidas, faixa de pré-hipertensão. MRPA de 5 dias com média 126x82. Peso 76,5 kg, altura 1,64 m (IMC 28,4), circunferência abdominal 92 cm. Ao exame: ausculta normal, sem edema. Exames: glicemia 91, LDL 118, creatinina 0,7, K 4,1, TSH normal. Anticoncepcional combinado pode elevar discretamente a PA, a ser reavaliado com a ginecologia. Risco cardiovascular baixo.', 'Sem medicação. MEV: dieta DASH, redução de embutidos e sal, atividade física 150 min por semana, meta de perda de 5 kg. Reavaliar método contraceptivo com ginecologia. Retorno em 3 meses com MRPA.'),
  (1123, 331, 5, '2024-06-18 12:30', 'retorno', 'Voltei para ver a pressão depois da dieta', 118, 76, 70, 72.0, 'Perdeu 4,5 kg em 3 meses, caminha 30 minutos 4x por semana e leva marmita ao trabalho. Trocou o anticoncepcional por DIU de cobre. MRPA média 116x74. PA no consultório 118x76. Sem sintomas. Cintura 84 cm. Orgulhosa do resultado: "nunca imaginei que ia ver a pressão baixar sem remédio". PA normal, sem indicação de tratamento farmacológico.', 'Manter MEV. MRPA a cada 6 meses e consulta anual. Orientada a não abandonar os hábitos. Lipidograma em 1 ano.'),
  (1124, 331, 5, '2024-09-10 18:00', 'teleconsulta', 'Vou me mudar para Manaus, preciso do relatório', 116, 74, null, 71.5, 'Teleconsulta. Paciente informa transferência de trabalho para Manaus (AM) em 15 dias. Mantém exercícios e dieta, sem sintomas. MRPA domiciliar que ela mandou por foto: médias entre 114x72 e 118x76. Peso informado 71,5 kg. Nenhuma medicação em uso. Sem queixas cardiovasculares. Preparado relatório de encaminhamento à UBS de Manaus para acompanhamento anual de pressão e MEV.', 'Emitido relatório de transferência com MRPA e exames. Orientada a procurar UBS próxima da nova residência nos primeiros 30 dias. Manter MEV e checagem anual da PA. Alta do ambulatório.');
