insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (331, '2024-09-10', 'transferido', 'Pré-hipertensão controlada apenas com mudança de estilo de vida (perda de 5 kg, dieta DASH, exercício), PA em 116x74 mmHg sem medicação. Transferida para acompanhamento na atenção primária de Manaus por mudança de cidade, com relatório entregue.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (332, 'Nilton Raulino Sevegnani', 'M', '1964-08-14', 'Brusque', 'SC', 'Supervisor de tecelagem', 'HAS há 7 anos, em uso de atenolol 100 mg e hidroclorotiazida 25 mg. Sobrepeso. Parou o atenolol há 3 semanas sem avisar ninguém. Não fuma. Bebe cerveja nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1125, 332, 2, '2021-10-05 10:00', 'consulta', 'Parei o remédio da pressão, não sou mais homem na cama', 168, 102, 84, 91.0, 'Homem de 57 anos, hipertenso, constrangido, relata que desde que começou o atenolol há 2 anos perdeu a ereção e a libido, atribuiu ao remédio e parou há 3 semanas. Desde então, PA domiciliar entre 160-175 por 95-105 e cefaleia matinal. Ao exame: PA 168x102, FC 84, sem sopros, sem edema. Exames: glicemia 108, creatinina 1,0, K 4,3, testosterona total 420 ng/dL (normal). Embora a disfunção erétil possa ter vários fatores (HAS, sobrepeso, estresse), o betabloqueador e a tiazida podem contribuir.', 'Suspender definitivamente o atenolol. Iniciar losartana 50 mg 12/12h e anlodipino 5 mg, mantendo hidroclorotiazida 12,5 mg. Explicado que o controle da PA e a perda de peso também melhoram a função erétil. Retorno em 6 semanas. Avaliação da urologia se persistir.'),
  (1126, 332, 2, '2021-11-16 10:30', 'retorno', 'A pressão baixou e já estou melhor', 138, 86, 72, 90.0, 'Seis semanas depois, PA domiciliar média 136x84. Cefaleia ausente. Refere melhora parcial das ereções, que voltaram a ocorrer pela manhã, ainda sem firmeza total em relações. Sem tosse nem edema relevante. Creatinina 1,0 e K 4,2. Emagreceu 1 kg, caminha 20 min de manhã antes do trabalho. Explicado que o sofrimento psicológico atribuído ao remédio também influencia.', 'Manter esquema. Encaminhar à urologia para avaliação de sildenafil, que é seguro com anlodipino e losartana (sem nitratos). Reforçar MEV e retorno em 3 meses. Dosar glicemia e lipídios.'),
  (1127, 332, 2, '2022-05-24 10:00', 'retorno', 'Estou tomando tudo e a vida voltou ao normal', 126, 78, 70, 86.5, 'Seis meses de novo esquema. Perdeu 4,5 kg. MRPA média 124x78. Usando sildenafil 50 mg conforme orientado pela urologia, com boa resposta. Adesão total: "agora tomo na hora do café, junto da esposa". Exames: glicemia 98, LDL 130, creatinina 1,0, K 4,3. PA na meta, sem efeitos adversos. Expectativa de manter só duas medicações com a perda de peso.', 'Manter losartana, anlodipino e hidroclorotiazida. Se mantiver o peso por 6 meses e PA < 120/75, tentar retirar a hidroclorotiazida. Lipidograma em 6 meses. Retorno em 6 meses.');
