insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (332, '2022-05-24', 'controlado', 'Má adesão por disfunção erétil atribuída ao atenolol, resolvida com troca para losartana e anlodipino e abordagem da queixa sexual com urologia. MRPA de 124x78 mmHg, perda de 4,5 kg e plena adesão ao tratamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (333, 'Edvaldo Santana Bonfim', 'M', '1969-04-09', 'Camaçari', 'BA', 'Operador de planta petroquímica em turnos', 'HAS há 10 anos, em uso de losartana 50 mg 12/12h, anlodipino 10 mg, clortalidona 25 mg e carvedilol 25 mg 12/12h. Trabalha em escala 4x2 com plantões noturnos de 12 horas. Obesidade grau 1. Encaminhado por HAS resistente. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1128, 333, 1, '2023-06-20 08:00', 'consulta', 'Dizem que minha pressão é resistente, não baixa de jeito nenhum', 172, 108, 66, 99.0, 'Homem de 54 anos encaminhado por HAS resistente a quatro fármacos. PA 172x108, FC 66. Ao investigar a adesão: toma ''quando lembra'', pois tem 4 comprimidos em 6 horários e nas semanas de noturno perde o horário e pula as doses. Registros da farmácia mostram retirada em 40% dos meses. Em casa, o aparelho mede 170-180 por 100-110. Sem sintomas. Sem sopros abdominais, K 4,0, aldosterona e renina normais, creatinina 1,0, polissonografia sem apneia. Pseudorresistência por má adesão (esquema complexo).', 'Simplificar para dose única diária: olmesartana 40 mg + anlodipino 10 mg + hidroclorotiazida 25 mg em comprimido único, tomado ao acordar (qualquer que seja o turno). Suspender carvedilol com redução em 1 semana. Orientar organizador e alarme no celular. Retorno em 6 semanas.'),
  (1129, 333, 1, '2023-08-01 08:30', 'retorno', 'Estou tomando o comprimido único todos os dias', 144, 90, 74, 98.0, 'Seis semanas de esquema simplificado, adesão referida de 100% com alarme e registro no caderninho; farmácia dispensou duas caixas. PA caiu de 172x108 para 144x90, com FC 74 após retirar o carvedilol. Sem tontura, sem edema. Creatinina 1,0 e K 3,9. O fato de PA ter caído 28 mmHg com menos comprimidos confirma que o problema era a adesão, não resistência verdadeira. Ainda acima da meta.', 'Manter o comprimido único. Acrescentar espironolactona 25 mg se MRPA permanecer acima de 130/80 no próximo retorno. Dieta com menos sal e peso: nutricionista. MRPA por 7 dias. Retorno em 3 meses.'),
  (1130, 333, 1, '2023-11-14 08:20', 'retorno', 'Pressão boa em casa, bom demais', 128, 80, 70, 94.5, 'Tomando o comprimido único sem falhas. MRPA de 7 dias: média 126x78. Perdeu 4,5 kg com a nutricionista. Sem edema, sem tosse, K 4,1 e creatinina 1,0. Dispensou a espironolactona. Passou por mudança de turno sem perder doses, pois o alarme está programado conforme o relógio biológico. Satisfeito: "foi só colocar tudo num comprimido".', 'Manter. Reavaliar em 6 meses com MRPA. Se atingir peso < 90 kg, tentar reduzir a dose de hidroclorotiazida. Check-up anual (lipídios, glicemia, ECG).');
