insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (333, '2023-11-14', 'melhorou', 'Pseudorresistência por má adesão em trabalhador de turnos: esquema de seis comprimidos em quatro horários trocado por comprimido único triplo. PA caiu de 172x108 para 128x80, MRPA 126x78 mmHg, perda de 4,5 kg, sem necessidade de espironolactona.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (334, 'Jhonatan Rufino Araújo', 'M', '1992-12-05', 'Porto Alegre', 'RS', 'Garçom de casa noturna', 'Sem HAS prévia conhecida. Usuário ocasional de cocaína inalada e crack nos fins de semana, tabagista de 8 maços-ano, etilista social. Nunca fez acompanhamento médico regular. Sem história familiar conhecida.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1131, 334, 6, '2023-11-18 04:20', 'pronto_socorro', 'Dor no peito e coração disparado depois de cheirar', 226, 134, 128, null, 'Pcte 30a, trazido por colega de trabalho após uso de cocaína inalatória há 3h. Dor precordial em aperto, intensa, sudorese, agitação e cefaleia. REG, ansioso, midríase bilateral, pele suada, PA 226x134 em MSD e 218x130 em MSE, FC 128, SatO2 98%, T 37,8. Sem déficits focais. ECG: taquicardia sinusal, repolarização precoce, sem supra. Troponina 0,12 ng/mL (referência < 0,03). Crise hipertensiva por intoxicação por cocaína com dor torácica e possível lesão miocárdica; descartada dissecção (sem diferença de pulsos, RX com mediastino normal).', 'Benzodiazepínico (diazepam 10 mg IV) como primeira linha, resfriamento, hidratação, nitroglicerina IV para dor e PA, AAS 200 mg. Evitar betabloqueadores isolados na fase aguda. Monitorização contínua e repetição de troponina em 3 h. Internar em UTI.'),
  (1132, 334, 14, '2023-11-18 10:00', 'internacao', 'Internação em UTI por crise hipertensiva por cocaína', 144, 86, 88, 74.0, 'Após diazepam e nitroglicerina, PA caiu para 144x86 em 6 h, FC 88, assintomático. Troponina 2ª e 3ª amostras 0,16 e 0,09, em queda, sem alterações dinâmicas no ECG. ECO: FEVE 58%, sem alterações segmentares. CK total 880 sem rabdomiólise franca. Creatinina 1,0, EAS sem hematúria. Sem lesão neurológica, TC de crânio dispensada. Nitroglicerina desligada em 12h. Alta em 36h com PA 126x78 sem medicação, após conversa sobre uso de drogas e riscos cardiovasculares (IAM, dissecção, AVC).', 'Alta sem anti-hipertensivo. Orientação mandatória de abstinência de cocaína e crack. Encaminhamento ao CAPS-AD. Retorno ambulatorial em 2 semanas com ECG e MAPA para descartar HAS de base. Preferir bloqueadores de canal de cálcio se futura necessidade.'),
  (1133, 334, 1, '2024-01-23 15:40', 'retorno', 'Vim só porque minha mãe insistiu', 138, 88, 82, 76.0, 'Retorna 9 semanas depois do evento, depois de faltar à consulta de 2 semanas. Admite que voltou a usar cocaína uma vez, ''só pra aguentar o carnaval'', e não procurou o CAPS-AD. Sem dor torácica. PA 138x88 em consultório. MAPA feita no mês passado: média 24h 130x80, vigília 134x84, mantendo PA no limite superior, mas sem HAS comprovada. ECG normal, ECO normal. Não quer tomar remédios (''só se ficar ruim''). Ouviu novamente os riscos, aparentemente sem muita adesão ao cuidado.', 'Sem anti-hipertensivo por ora. Reforçada importância de abstinência e CAPS-AD (novo encaminhamento com agendamento). Retorno em 2 meses com MRPA e perfil lipídico. Orientado a procurar PS se dor torácica ou palpitações.');
