insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (334, '2024-05-10', 'abandonou', 'Crise hipertensiva com dor torácica por cocaína, resolvida sem lesão miocárdica significativa. Voltou a usar a droga, não compareceu ao CAPS-AD nem ao retorno marcado em março e maio; telefones sem resposta. Perda de seguimento com risco cardiovascular persistente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (335, 'Leovegildo Padilha Mello', 'M', '1957-01-26', 'Vacaria', 'RS', 'Agricultor, produtor de maçã', 'HAS há 12 anos, DLP, DM2 há 8 anos. Ex-tabagista, parou há 10 anos. Colheita da safra exige esforços intensos. Em uso de losartana 50 mg 12/12h, metformina, sinvastatina 20 mg. Pai com infarto aos 66 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1134, 335, 2, '2022-03-15 09:00', 'consulta', 'Aperto no peito quando carrego caixa na colheita', 146, 86, 76, 85.0, 'Homem de 65 anos com dor torácica em aperto retroesternal aos esforços intensos (carregar caixas de maçã, subir ladeira) há 3 meses, que cede em 3 a 5 minutos ao parar. Sem dor em repouso. Ao exame: PA 146x86, RCR 2T BNF, sem sopros, sem edema, pulsos presentes. ECG de repouso normal. LDL 112 mg/dL em uso de sinvastatina 20 mg, HbA1c 7,2%. Angina estável típica CCS II, probabilidade intermediária-alta, com HAS, DM2 e DLP.', 'Iniciar AAS 100 mg, trocar sinvastatina por atorvastatina 40 mg e iniciar metoprolol succinato 50 mg. Nitrato SL se dor. Solicitar cintilografia de perfusão miocárdica com estresse. Retorno com exame em 6 semanas.'),
  (1135, 335, 2, '2022-04-26 09:30', 'retorno', 'Trouxe o resultado da cintilografia', 134, 78, 62, 84.0, 'Cintilografia com estresse farmacológico: isquemia de grau moderado (12% do VE) em parede anterior e ápice, defeito reversível, FEVE 55%. Com tratamento, a dor passou a aparecer só com esforços maiores (CCS I-II). PA 134x78, FC 62. LDL 82 mg/dL. Pelo território de isquemia anterior (DA), extensão considerável e diabetes, indicada coronariografia para definir anatomia e se há indicação de revascularização.', 'CATE eletivo com avaliação funcional (FFR) se lesão intermediária. Manter AAS, estatina, betabloqueador e nitrato. Retorno após o exame.'),
  (1136, 335, 10, '2022-06-07 07:30', 'internacao', 'Coronariografia eletiva', 136, 80, 60, 84.0, 'Coronariografia por via radial: lesão de 65% em DA média, com FFR 0,86 (não significativa funcionalmente), Cx e CD com irregularidades parietais sem estenoses relevantes, FEVE 56%. Sem indicação de angioplastia, pois FFR > 0,80 e sintomas controlados com tratamento clínico. Sem complicações do acesso. Alta no mesmo dia com orientação de tratamento clínico otimizado, sem necessidade de stent.', 'Manter tratamento clínico otimizado. Meta de LDL < 55 mg/dL, aumentar atorvastatina para 80 mg. Adicionar anlodipino 5 mg se angina persistir. Reabilitação cardíaca ou atividade física orientada. Retorno em 3 meses.'),
  (1137, 335, 2, '2023-01-10 09:20', 'retorno', 'Passei a colheita sem dor no peito', 124, 74, 58, 82.5, 'Sete meses depois, fez toda a safra sem angina, usou nitrato SL só uma vez. Frequentou a academia da prefeitura. LDL 48 mg/dL com atorvastatina 80, HbA1c 6,9%. PA 124x74, FC 58. Sem edema ou dispneia. Compreendeu que o ''entupimento'' não foi desobstruído, mas a carga de aterosclerose está sob controle com remédios e exercícios.', 'Manter esquema. Teste ergométrico em 1 ano ou antes se sintomas. Vacinas anuais. Retorno em 6 meses.');
