insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (335, '2023-01-10', 'controlado', 'Angina estável por lesão intermediária da DA sem significado funcional (FFR 0,86), tratada clinicamente sem angioplastia. Sem angina na safra, LDL de 48 mg/dL e HbA1c de 6,9%. Segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (336, 'Carmelita Gonçalves Dequech', 'F', '1963-02-02', 'Joinville', 'SC', 'Merendeira escolar', 'HAS em uso irregular de enalapril 10 mg. Menopausa aos 49 anos. Tabagista de 25 maços-ano, 10 cigarros/dia. DLP sem tratamento. Mãe falecida de infarto aos 63 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1138, 336, 6, '2024-02-24 11:30', 'pronto_socorro', 'Dor forte no peito e enjoo, achei que era o estômago', 92, 58, 48, 72.0, 'Pcte 61a, dor epigástrica e retroesternal em aperto há 1h30, com náuseas, vômitos e sudorese. REG, pálida, sudoreica, PA 92x58, FC 48. Pulmões limpos, sem estase jugular. ECG: supra de ST de 3 mm em DII, DIII e aVF, com infra recíproco em DI/aVL e V1-V3 a 1 mm; BAV de 1º grau com PR 280 ms. Troponina 0,9 ng/mL. HD: IAMCSST de parede inferior, Killip I, hipotensão e bradicardia vagal; investigar acometimento do VD (V4R com supra 1 mm).', 'AAS 300 mg, ticagrelor 180 mg, heparina, atropina 0,5 mg IV para bradicardia e hidratação com SF 0,9% 500 mL (VD). Evitar nitratos e morfina. Angioplastia primária imediata, acionada hemodinâmica.'),
  (1139, 336, 10, '2024-02-24 13:10', 'internacao', 'Angioplastia primária por IAM de parede inferior', 108, 66, 62, 72.0, 'CATE por via radial direita: oclusão trombótica da CD proximal (culpada), DA e Cx com lesões discretas, FEVE 50%. ATC primária com stent farmacológico 3,5 x 28 mm na CD, fluxo TIMI 3 final, tempo porta-balão de 62 min. Durante o procedimento, BAV transitório com pausas curtas, revertido após reperfusão sem marca-passo. Evolução em UTI sem arritmias, sem choque. Pico de troponina 38 ng/mL. ECO: FEVE 50%, hipocinesia inferior, VD levemente disfuncional. Alta no 5º dia, tabagismo interrompido na internação.', 'AAS 100 mg e ticagrelor 90 mg 12/12h por 12 meses, atorvastatina 80 mg, bisoprolol 2,5 mg, enalapril 5 mg 12/12h. Reabilitação cardíaca, cessação do tabagismo com adesivo de nicotina. Retorno em 30 dias.'),
  (1140, 336, 2, '2024-03-30 10:00', 'retorno', 'Estou me sentindo bem, mas ainda dá vontade de fumar', 118, 70, 56, 70.5, 'Trinta e cinco dias do IAM. Sem angina, sem dispneia. Fumou 3 cigarros em duas ocasiões de estresse, mas voltou ao adesivo. Iniciou reabilitação cardíaca 2x por semana. PA 118x70, FC 56 em bisoprolol. Dispneia ausente. Sangramentos ausentes. Por FC de 56 e PA baixa-normal, sem sintomas, mantenho a dose atual. Exames: LDL 61, creatinina 0,8, K 4,4. ECO de controle: FEVE 56%, hipocinesia inferior discreta.', 'Manter AAS, ticagrelor, atorvastatina, bisoprolol e enalapril. Reforçar cessação do tabagismo. Reabilitação até completar 36 sessões. Retorno em 3 meses.'),
  (1141, 336, 1, '2024-09-17 10:20', 'retorno', 'Sete meses depois, parei de fumar de verdade', 122, 72, 60, 71.0, 'Sete meses após IAM inferior. Abstinente do tabaco há 4 meses, completou a reabilitação, caminha 5 km sem sintomas. LDL 49. Sem sangramentos. Retomou o trabalho de merendeira. PA 122x72, FC 60. Mantém ticagrelor, previsto para 12 meses. Disse que o susto mudou sua vida.', 'Manter esquema atual, suspender ticagrelor em fevereiro de 2025 e manter AAS. Teste ergométrico em 6 meses. Lipidograma e glicemia anuais. Retorno em 4 meses.');
