insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (337, '2023-02-21', 'melhorou', 'Cardiomiopatia alcoólica com FEVE inicial de 25% recuperada para 46% após 10 meses de abstinência total e terapia dos quatro pilares. Classe funcional I, NT-proBNP de 180 pg/mL e fim do tabagismo. Mantém tratamento e vigilância ecocardiográfica.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (338, 'Maurício Takeshi Yamada', 'M', '1966-10-12', 'Campinas', 'SP', 'Engenheiro civil', 'HAS leve em uso de valsartana 160 mg/dia. Palpitações irregulares há 2 anos, diagnosticadas como FA paroxística. Corredor amador (corre 10 km, 3x por semana), consome 2 taças de vinho por noite. Sem DM.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1145, 338, 4, '2022-09-13 16:00', 'consulta', 'A FA volta toda semana e me atrapalha nos treinos', 132, 82, 92, 82.0, 'Homem de 55 anos, FA paroxística sintomática, 1-2 episódios por semana com 2 a 6 horas de duração, palpitação e queda do rendimento nos treinos. Já usou propafenona 150 mg 8/8h por 4 meses, com recorrência e sensação de fadiga, e metoprolol, que baixou a performance. ECG hoje em ritmo sinusal. ECO: átrio esquerdo 41 mm (índice 32 mL/m²), FEVE 62%, sem valvopatia. Holter: 14 episódios de FA em 7 dias. CHA2DS2-VASc 1 (HAS). Coronárias sem lesões em angiotomografia prévia.', 'Dado o perfil (jovem, sintomático, sem cardiopatia estrutural), indicada ablação por cateter (isolamento das veias pulmonares). Iniciar apixabana 5 mg 12/12h até o procedimento e por 3 meses após, depois reavaliar. Reduzir álcool, uso de cafeína. Retorno com exames.'),
  (1146, 338, 4, '2022-11-29 16:20', 'retorno', 'Tive uma crise longa na semana passada', 138, 84, 110, 81.5, 'Teve um episódio de FA com 14h de duração na semana passada, reverteu espontaneamente, com palpitações e leve sudorese. Hoje, FA com resposta ventricular de 110 bpm; assintomático. Sem sangramentos com apixabana. Hemograma e função renal normais. A ablação está agendada em fevereiro. Conversa sobre taxa de sucesso (~70-80% na primeira abordagem em FA paroxística), risco de complicações (tamponamento 1%, estenose de veia pulmonar, lesão esofágica) e possíveis recorrências nos 3 primeiros meses.', 'Manter apixabana ininterrupta, sem pular doses (essencial antes da ablação). Manter valsartana. Abstinência de álcool antes do procedimento. ECG e ETE antes da ablação se algum esquecimento da apixabana. Retorno após o procedimento.'),
  (1147, 338, 4, '2023-02-14 07:00', 'internacao', 'Internação para ablação de fibrilação atrial', 128, 78, 66, 81.0, 'Ablação por cateter de FA sob anestesia geral, com mapeamento eletroanatômico e crioablação por balão. Isolamento elétrico das quatro veias pulmonares com bloqueio de entrada e saída confirmados. ETE prévio sem trombo em apêndice atrial esquerdo. Sem tamponamento, sem lesão frênica, esôfago monitorado por temperatura. Ritmo sinusal ao final. Hematoma inguinal pequeno à direita, resolvido. Alta no 2º dia, assintomático, sem dor torácica nem disfagia.', 'Manter apixabana por pelo menos 3 meses. Pantoprazol 40 mg por 4 semanas. Evitar esforço intenso por 7 dias. Atenção para disfagia, febre ou dor torácica nas primeiras semanas (fístula atrioesofágica). Holter em 3 meses. Retorno em 30 dias.'),
  (1148, 338, 4, '2023-09-19 16:30', 'retorno', 'Voltei a correr, só tive uma crise curta', 124, 76, 58, 79.5, 'Sete meses após a crioablação. Voltou a correr 10 km com FC média 148. Teve um único episódio de palpitação com 20 minutos de duração no 2º mês (período de blanking), depois nenhum. Holter de 7 dias: ritmo sinusal, sem FA, raras ESV, FC média 62. Parou o vinho nos dias de semana. Apixabana suspensa há 4 meses, conforme CHA2DS2-VASc 1 e ausência de recorrência. ECG normal. PA 124x76.', 'Sem anticoagulante. Manter valsartana. Holter anual. Se recorrência, discutir nova ablação. Retorno em 6 meses.');
