insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (338, '2023-09-19', 'estavel', 'FA paroxística sintomática refratária ao antiarrítmico tratada com crioablação das veias pulmonares. Holter de 7 dias sem recorrência após o período de blanking; voltou a correr 10 km. Anticoagulante suspenso, segue em vigilância anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (339, 'Cleonice Pires Sobral', 'F', '1961-03-17', 'Barreiras', 'BA', 'Lavradora', 'Doença de Chagas diagnosticada há 12 anos, cardiopatia chagásica dilatada com IC em CF II. Em uso de carvedilol 6,25 mg 12/12h, enalapril 10 mg 12/12h e espironolactona. Nasceu em casa de barro no interior da Bahia; parentes com Chagas. Mora na zona rural, a 40 km do centro.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1149, 339, 11, '2021-09-21 10:30', 'consulta', 'Vim trazer o ecocardiograma, o doutor disse que tem coágulo', 110, 70, 68, 58.0, 'Mulher de 60 anos com cardiopatia chagásica, assintomática para embolia. ECO de rotina: FEVE 35%, aneurisma apical com trombo mural de 1,6 cm, hipocinesia difusa, átrio esquerdo normal. ECG: BRD + HBAE, ritmo sinusal 68 bpm. Holter: ESV frequentes e TVNS de 5 batimentos. Sem FA. Ao exame: leve estase jugular, B3 ausente, sem edema. Trombo intracardíaco em Chagas é indicação de anticoagulação oral com antagonista de vitamina K (varfarina); DOAC sem evidência robusta nessa condição.', 'Iniciar varfarina 5 mg/dia com INR alvo 2 a 3, mantendo o enalapril e o carvedilol. INR a cada 5 a 7 dias no início. Discutir ECO de controle em 3 meses. Amiodarona não indicada ainda. Orientações alimentares (vitamina K) e sobre sangramentos.'),
  (1150, 339, 11, '2022-03-08 11:00', 'retorno', 'Meu sangue ficou muito fino e saiu sangue do nariz', 106, 68, 70, 57.0, 'Seis meses de varfarina. O INR variou de 1,4 a 4,8, difícil de controlar por viver longe e fazer o exame uma vez por mês no posto. Dois episódios de epistaxe leve no último mês, o último com INR 4,8. Hematomas em braços. Ao exame: sem sangramento ativo. Hb 11,8. ECO: trombo reduziu para 0,8 cm, FEVE 33%. Pelo risco de AVC e pelas dificuldades de acesso, é preciso melhorar o controle do INR. Cuidadora (a filha) comparece às consultas e pode ajudar com o diário alimentar.', 'Reduzir varfarina para 2,5 mg alternando com 5 mg. INR a cada 2 semanas no posto de saúde do povoado com agente comunitário e retorno aqui com resultados por telefone. Manter carvedilol, enalapril e espironolactona. Reforçar sinais de alarme. Retorno em 3 meses.'),
  (1151, 339, 11, '2023-02-14 10:40', 'retorno', 'Estou bem, só o INR que dá trabalho', 104, 66, 64, 58.5, 'Quase 1 ano depois, estável. INR nos últimos 6 meses: 2,1 a 3,0 em 70% das medidas, após o monitoramento no povoado. Nenhum sangramento. ECO: FEVE 34%, sem trombo, aneurisma apical persistente (3,1 cm). Holter: TVNS esporádica, sem sintomas. CF II, sem internações. Hb 12,4. Sem AVC ou embolia. Em discussão a necessidade de continuar a anticoagulação (aneurisma apical + FEVE < 35% mantêm risco embólico).', 'Manter varfarina por tempo indeterminado, com INR alvo 2-3. Continuar carvedilol, enalapril e espironolactona; considerar sacubitril/valsartana e dapagliflozina na próxima consulta se acesso. Holter semestral. Discutida avaliação de CDI com a arritmologia se TV sustentada.');
