insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (339, '2023-02-14', 'estavel', 'Cardiopatia chagásica com FEVE de 34%, aneurisma apical e trombo mural resolvido sob varfarina, com INR lábil no início e melhor controle após monitoramento no posto local. Sem eventos embólicos ou sangramentos maiores, em CF II, seguimento mantido.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (340, 'Odete Brum Scherer', 'F', '1944-01-12', 'Cruz Alta', 'RS', 'Aposentada, ex-comerciária', 'HAS e hipotireoidismo tratado (levotiroxina 50 mcg). Tonturas e episódios de palpitação nos últimos 2 anos, com 2 quedas. Sem DM. Mora com o filho. Usava atenolol 25 mg, suspenso recentemente em outro serviço por bradicardia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1152, 340, 4, '2023-03-07 09:40', 'consulta', 'Desmaios e palpitação, já caí duas vezes', 138, 72, 46, 64.0, 'Mulher de 79 anos com tonturas, 2 episódios de síncope no último ano e palpitações rápidas intermitentes. Ao exame: RCI com bradicardia, FC 46, sem sopros, sem edema. ECG: bradicardia sinusal 46 bpm, extrassístoles atriais. Holter 48h: pausas sinusais de até 6,2 s durante a vigília, alternando com episódios de FA e flutter atrial paroxístico de resposta rápida a 140 bpm (síndrome bradicardia-taquicardia) após suspensão do atenolol. TSH 2,4. Eletrólitos normais. Doença do nó sinusal sintomática com pausas > 3 s.', 'Indicado implante de marca-passo definitivo dupla câmara. Evitar fármacos cronotrópicos negativos. CHA2DS2-VASc 4 (idade ≥ 75, sexo F, HAS): anticoagulação com apixabana 5 mg 12/12h (sem critérios para redução de dose: idade < 80 anos, peso > 60 kg e creatinina 1,0). Internação eletiva em 2 semanas.'),
  (1153, 340, 4, '2023-03-21 07:30', 'internacao', 'Internação para colocar o marca-passo', 134, 70, 50, 64.0, 'Implante de marca-passo dupla câmara DDDR pela veia subclávia esquerda, sem intercorrências. Apixabana suspensa 48h antes. Limiares atrial 0,8 V e ventricular 0,7 V, ondas P 2,8 mV e R 10 mV, impedâncias normais. RX sem pneumotórax. Após o implante, FC mínima programada de 60 bpm, assintomática. Antibioticoprofilaxia com cefazolina. Alta em 24h com curativo seco e orientações. Retomada de apixabana no dia seguinte.', 'Curativo e cuidados da ferida por 10 dias. Retomar apixabana 5 mg 12/12h em 24h após o implante. Retorno para revisão da ferida em 10 dias e do dispositivo em 30 dias. Orientações sobre sinais de infecção na loja.'),
  (1154, 340, 6, '2023-09-12 22:50', 'pronto_socorro', 'Febre há 4 dias e a ferida do marca-passo está vermelha e saindo pus', 104, 60, 108, 60.0, 'Pcte 79a, 6 meses pós-implante de marca-passo, com febre de 38,9 oC há 4 dias, calafrios, hiperemia e dor da loja do gerador, com saída de secreção purulenta e gerador parcialmente exposto. REG, taquicárdica, PA 104x60, FC 108, SatO2 94%. Sopro sistólico novo 2+/6 em foco tricúspide. Leucócitos 17.800, PCR 210, creatinina 1,5. Duas hemoculturas colhidas. Infecção de dispositivo com bacteremia, suspeita de endocardite associada ao eletrodo.', 'Internar. Vancomicina e ceftriaxona IV após coletas, suspender apixabana, hidratação. Solicitar ETE e avaliação para extração completa do sistema. Contactar arritmologia. Monitorização contínua.'),
  (1155, 340, 4, '2023-09-14 09:00', 'internacao', 'Retirada do marca-passo infectado', 110, 64, 98, 60.0, 'Hemoculturas positivas para Staphylococcus aureus sensível à meticilina. ETE: vegetação de 14 mm aderida ao eletrodo ventricular na cavidade direita, insuficiência tricúspide leve, sem abscesso. Endocardite relacionada ao dispositivo. Extração percutânea completa do gerador e eletrodos por laser/tração, sem complicações, com marca-passo provisório transvenoso na veia jugular para dependência parcial (pausas de 3 s). Antibioticoterapia ajustada para oxacilina. Febre cedeu em 72h; hemoculturas de controle negativas. Evoluiu com fraqueza e perda de 4 kg.', 'Oxacilina 2 g IV 4/4h por 6 semanas. Novo implante de marca-passo definitivo no lado contralateral somente após 2 hemoculturas negativas por 72h e ausência de febre. Anticoagulação suspensa até resolução do quadro, depois reavaliar.');
