insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (340, '2023-11-06', 'piorou', 'Doença do nó sinusal tratada com marca-passo que evoluiu com infecção do dispositivo e endocardite por S. aureus, exigindo extração completa do sistema, seis semanas de antibiótico e novo implante contralateral. Alta com fraqueza importante e perda de 4 kg.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (341, 'Rudimar Fagundes Zanella', 'M', '1962-09-03', 'Gravataí', 'RS', 'Vigilante noturno', 'HAS há 8 anos em uso de losartana 50 mg 12/12h, anlodipino 10 mg e hidroclorotiazida 25 mg. Obesidade grau 2, dieta rica em frituras e refrigerante, trabalha à noite e dorme de dia. Ex-fumante há 5 anos. Pai com AVC aos 68 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1156, 341, 1, '2019-03-12 14:00', 'consulta', 'Tomo três remédios e a pressão continua alta', 158, 96, 80, 118.0, 'Homem de 56 anos, IMC 38, circunferência abdominal 126 cm, com PA 158x96 em uso de três fármacos, adesão boa (traz as caixas). Sem sintomas. Ao exame: pescoço 46 cm, sem sopros, edema 1+ de tornozelos. Exames: glicemia 112, HbA1c 5,9%, LDL 144, triglicerídeos 260, creatinina 1,0, ácido úrico 7,8. O peso é o principal fator de sua HAS e do pré-diabetes. Roncos importantes referidos pela esposa; polissonografia solicitada.', 'Manter os três fármacos até a perda de peso. Nutricionista, meta de 15% de perda ponderal (18 kg) em 12 meses com dieta hipocalórica e caminhada de 40 min diários mesmo no turno da noite. Polissonografia, ECG, ECO. Retorno em 3 meses.'),
  (1157, 341, 1, '2020-03-10 14:20', 'retorno', 'Perdi uns quilos e estou me sentindo melhor', 134, 82, 74, 106.0, 'Perdeu 12 kg em 12 meses com acompanhamento nutricional, caminha 45 min e cortou refrigerante. PA 134x82, MRPA média 130x80. Polissonografia mostrou IAH 22/h (apneia moderada), usa CPAP há 4 meses com melhora do sono. K 4,3, creatinina 1,0, glicemia 98, HbA1c 5,6%. Sem edema. Boa resposta ao emagrecimento: PA caiu 24 mmHg sistólica com o mesmo esquema.', 'Suspender hidroclorotiazida (primeira droga a retirar), manter losartana e anlodipino. Seguir com dieta e exercício, meta de 96 kg. MRPA em 4 semanas após a retirada. Retorno em 3 meses.'),
  (1158, 341, 1, '2021-04-13 14:10', 'retorno', 'Mais seis quilos a menos e pressão baixa em casa', 122, 76, 68, 96.0, 'Atingiu a meta de peso (96 kg, perda de 22 kg em 25 meses). MRPA média 118x72, com algumas medidas de 105x65 pela manhã. Edema de tornozelos desaparecido. Sem tontura, mas relata cansaço no plantão. IMC 31. Sono melhor com CPAP. Mantém caminhada 5x por semana. Creatinina 0,9, K 4,4. PA abaixo de 120/75 em casa: possível retirar um fármaco.', 'Suspender anlodipino. Manter losartana 50 mg 12/12h, reduzir para 100 mg/dia em uma tomada. MRPA por 7 dias em 1 mês. Voltar se PA > 135/85 em casa. Retorno em 3 meses.'),
  (1159, 341, 1, '2022-05-17 14:30', 'retorno', 'Só vim mostrar que continuo bem', 124, 76, 66, 94.5, 'Um ano com losartana isolada, manteve peso entre 94 e 96 kg. MRPA média 122x76. Sem queixas. LDL 98 com dieta. HbA1c 5,5%. Usa CPAP 6 noites por semana. Criou o grupo de caminhada dos vigilantes. Ao exame: sem sopros, sem edema, abdome globoso.', 'Manter losartana 100 mg/dia. Seguimento semestral. Lipidograma e glicemia anuais. Reforçar CPAP, alimentação e peso estável.');
