insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (342, '2024-07-25', 'controlado', 'Coarctação da aorta diagnosticada em adulto jovem por diferença de pressão entre braço e perna, tratada com stent revestido, com gradiente residual de 3 mmHg. PA de 126x74 mmHg com apenas metoprolol e AAS. Segue vigilância vitalícia com imagem anual e acompanhamento da valva bicúspide.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (343, 'Kelly Cristina Moraes Pozzebon', 'F', '1995-06-14', 'Esteio', 'RS', 'Professora de educação infantil', 'Primigesta, 37 semanas, sem comorbidades prévias. Pré-natal com 9 consultas, PA normal até a 34ª semana (110/70). Ganho de peso de 14 kg na gestação. Mãe com hipertensão na gestação. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1164, 343, 7, '2024-04-23 09:30', 'consulta', 'Pressão alta na consulta do pré-natal e um pouco de inchaço', 148, 96, 84, 78.0, 'Gestante de 28 anos, 37 semanas e 0 dia, com PA 148x96 e 150x98 em duas aferições com 4 horas de intervalo. Assintomática: sem cefaleia, escotomas, dor epigástrica, dispneia ou sangramento. Movimentos fetais presentes, BCF 144 bpm, altura uterina 35 cm, edema leve de tornozelos. Fita urinária 1+. Relação proteinúria/creatinina urinária 0,38. Plaquetas 210.000, TGO 22, TGP 18, DHL 180, creatinina 0,6, ácido úrico 5,4. ECO obstétrico com Doppler: líquido normal, Doppler de artéria umbilical normal. Pré-eclâmpsia sem sinais de gravidade.', 'Iniciar nifedipino retard 20 mg 12/12h. Controle ambulatorial a cada 48-72h com PA domiciliar e orientação de sinais de alarme (cefaleia, escotomas, epigastralgia, redução de movimentos fetais). Planejar parto com 37 a 38 semanas. Evitar IECA/BRA.'),
  (1165, 343, 7, '2024-04-26 10:00', 'retorno', 'Vim para a reavaliação, sem sintomas', 146, 92, 82, 78.3, 'Gestante de 37 semanas e 3 dias, assintomática, PA 146x92 mesmo com nifedipino 20 mg 12/12h. PA domiciliar entre 135-148 por 88-95. Sem sinais de gravidade: sem cefaleia, sem escotomas, sem dor epigástrica. BCF 140 bpm, movimentos fetais bons, colo posterior e impérvio. Labs de repetição: plaquetas 204.000, TGO 24, creatinina 0,6 e relação P/C 0,42. Pelo termo e pela pré-eclâmpsia com PA persistente, indicado parto programado.', 'Internar na próxima terça-feira (37 semanas e 6 dias) para indução do trabalho de parto com misoprostol seguido de ocitocina. Manter nifedipino. Sulfato de magnésio não indicado se permanecer sem sinais de gravidade. Orientações de sinais de alarme.'),
  (1166, 343, 7, '2024-04-30 07:30', 'internacao', 'Internação para indução do parto', 140, 90, 80, 78.5, 'Gestação de 37 semanas e 6 dias. PA 140x90 com nifedipino. Colo com 1 cm, 30% apagado. Indução com misoprostol 25 mcg vaginal 6/6h, depois ocitocina. Trabalho de parto progressivo, dilatação completa em 14h. Parto vaginal às 22h40 sem intercorrências, RN masculino 3.150 g, Apgar 9 e 10. PA durante o parto entre 138x88 e 148x94, sem picos graves. Sem hemorragia no pós-parto. No puerpério imediato, PA 132x82; alta no 2º dia com nifedipino.', 'Manter nifedipino por mais 2 semanas com PA domiciliar. Se PA < 130/80, suspender. Amamentação liberada. Retorno ambulatorial em 6 semanas. Aconselhamento sobre risco de hipertensão futura e uso de AAS em gestação futura.'),
  (1167, 343, 1, '2024-06-11 09:00', 'retorno', 'Revisão depois do parto, a pressão normalizou', 122, 78, 72, 69.5, 'Seis semanas e meia pós-parto, amamentando, sem sintomas. Suspendeu o nifedipino há 4 semanas com PA domiciliar entre 112-124 por 70-80. Perdeu 8,5 kg desde o parto. Exames: proteinúria ausente na fita, creatinina 0,6, plaquetas normais, TGO 20. PA de consultório 122x78. Pré-eclâmpsia resolvida. A paciente tem maior risco de HAS e doença cardiovascular ao longo da vida e de recorrência em nova gestação.', 'Sem medicação. Aferir PA anualmente e glicemia/perfil lipídico. Em futura gestação, iniciar pré-natal precoce com AAS 100 mg a partir de 12 semanas e cálcio. MEV.');
