insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (343, '2024-06-11', 'melhorou', 'Pré-eclâmpsia sem sinais de gravidade a termo, tratada com nifedipino e indução do parto com 37 semanas e 6 dias, sem complicações maternas ou neonatais. Seis semanas depois, PA normalizada sem medicação. Orientada sobre risco cardiovascular futuro e AAS em nova gestação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (344, 'Genésio Alvarenga Costa', 'M', '1960-10-21', 'Uberlândia', 'MG', 'Mecânico de automóveis', 'HAS diagnosticada há 14 anos, tratada de forma intermitente com captopril ocasional. Nunca fez ECO. Etilismo social, ex-fumante há 12 anos. Sobrepeso. Come muito sal, ''gosto de comida bem temperada''. Pai falecido de AVC hemorrágico aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1168, 344, 1, '2021-02-16 10:00', 'consulta', 'Cansaço ao subir escada e dor de cabeça', 168, 100, 78, 88.0, 'Homem de 60 anos com HAS mal controlada por anos, cansaço aos esforços moderados (NYHA II) e cefaleia ocipital. Ao exame: PA 168x100, RCR 2T B4, sem sopros, sem edema, pulmões limpos. ECG: HVE com strain em V5-V6 (Sokolow-Lyon 46 mm). ECO: septo 15 mm, parede posterior 14 mm, massa indexada 142 g/m², FEVE 62%, disfunção diastólica grau 1, átrio esquerdo 41 mm. Creatinina 1,0, albuminúria 38 mg/g. Cardiopatia hipertensiva com HVE concêntrica, sem IC.', 'Iniciar losartana 100 mg/dia, anlodipino 5 mg e clortalidona 12,5 mg. Redução de sal (< 5 g/dia), álcool e perda de peso. K e creatinina em 2 semanas. MRPA. Retorno em 6 semanas.'),
  (1169, 344, 1, '2021-04-06 10:20', 'retorno', 'Cabeça não dói mais, mas estou mais cansado de manhã', 142, 88, 72, 86.5, 'Seis semanas de tratamento, adesão boa. PA 142x88, MRPA média 138x86. Cefaleia desapareceu. Cansaço matinal discreto, ao acordar tem ''tontura''. K 3,9, creatinina 1,1. Perdeu 1,5 kg. Ainda ingere bastante sal na marmita e nos petiscos da oficina. Explicada a importância da retirada gradual do sal para regressão da HVE, que reduz o risco de IC e arritmias.', 'Aumentar anlodipino para 10 mg e clortalidona 25 mg. Consulta com nutricionista. Reduzir uso de temperos prontos. MRPA em 4 semanas. Retorno em 2 meses.'),
  (1170, 344, 1, '2022-02-08 10:10', 'retorno', 'Um ano de tratamento, vim fazer o ECO de novo', 128, 78, 68, 84.0, 'Um ano de tratamento regular. MRPA média 126x78. Perdeu 4 kg, diminuiu muito o sal (''a esposa tirou o saleiro da mesa''). ECO de controle: septo 12 mm, parede posterior 11 mm, massa indexada 108 g/m² (regressão da HVE), FEVE 63%, disfunção diastólica grau 1. ECG com redução de voltagem (Sokolow-Lyon 36 mm). Albuminúria 14 mg/g, K 4,2, creatinina 1,1. Sem sintomas.', 'Manter os três fármacos. Controle semestral de K, creatinina e albuminúria. ECO a cada 12-18 meses. Manter dieta com baixo sódio. Se peso continuar a cair, discutir reduzir dose da clortalidona.');
