insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (344, '2022-02-08', 'estavel', 'Cardiopatia hipertensiva com HVE concêntrica tratada com três fármacos e restrição de sódio: massa ventricular indexada caiu de 142 para 108 g/m², MRPA de 126x78 mmHg e albuminúria normalizada. Sem insuficiência cardíaca. Mantém acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (345, 'Anselmo Dall''Agnol Finkler', 'M', '1957-02-26', 'Bento Gonçalves', 'RS', 'Viticultor', 'RM com três pontes (mamária para DA, safena para Cx e CD) em junho de 2019 após IAM sem supra. HAS, DM2 em metformina e DLP. Ex-tabagista. Toma vinho todos os dias (''um copo na refeição''). Trabalha na vinícola da família.', 'Alergia a AAS (broncoespasmo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1171, 345, 2, '2019-09-10 09:30', 'consulta', 'Três meses da cirurgia do coração, vim ver como estou', 132, 78, 62, 86.0, 'Homem de 62 anos, 3 meses de pós-operatório de RM. Sem angina, caminha 30 minutos no sítio. Cicatriz esternal consolidada, ferida da perna boa. Alérgico a AAS: usa clopidogrel 75 mg isolado como antiagregante. LDL 71 mg/dL com atorvastatina 80, HbA1c 7,3%. ECO: FEVE 52%, hipocinesia inferior discreta. Ao exame: PA 132x78, FC 62, pulmões limpos, sem edema. Indicada reabilitação cardíaca, que ainda não fez por receio.', 'Manter clopidogrel 75 mg, atorvastatina 80 mg, metoprolol 50 mg e losartana. Ingressar na reabilitação cardíaca (3x por semana, 36 sessões). Controle glicêmico. Reduzir vinho para fins de semana. Retorno em 6 meses.'),
  (1172, 345, 2, '2021-09-21 09:40', 'retorno', 'Voltou aquele aperto no peito quando subo a ladeira da vinícola', 146, 84, 70, 90.0, 'Dois anos sem consultas regulares (pandemia, falta de transporte). Há 3 meses, angina aos esforços moderados, com piora nas últimas semanas (CCS III), sem dor de repouso. Ganhou 4 kg, parou a reabilitação na 12ª sessão, voltou a beber mais vinho e esqueceu a metformina em alguns dias. Ao exame: PA 146x84, sem sopros, pulsos presentes. ECG sem alterações agudas. Teste ergométrico positivo com infradesnível de ST em V4-V6 no 3º estágio. Indicado CATE para investigar falência de enxertos.', 'Adicionar isossorbida 20 mg 12/12h e nitrato SL SN. Solicitar CATE de urgência eletiva. Reorientar sobre dieta e uso correto dos remédios. Retorno após o exame.'),
  (1173, 345, 10, '2021-10-19 07:30', 'internacao', 'Cateterismo e angioplastia por angina após cirurgia', 138, 80, 64, 89.0, 'CATE: enxerto de mamária para DA pérvio; enxerto de safena para Cx ocluído; enxerto de safena para CD pérvio com estenose de 40% na anastomose; artéria circunflexa nativa com lesão de 90% proximal e fluxo TIMI 2. FEVE 50%. Angioplastia com stent farmacológico 3,0 x 20 mm na Cx nativa, com bom resultado e TIMI 3. Sem complicações. Alta no dia seguinte. Antiagregação com clopidogrel mantido por conta da alergia a AAS; discutida dessensibilização futura.', 'Clopidogrel 75 mg diário por tempo prolongado (alergia a AAS). Intensificar estatina (ezetimiba 10 mg, LDL 71 meta < 50). Reabilitação cardíaca novamente. Retorno em 30 dias.');
