insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (345, '2022-03-30', 'melhorou', 'Angina recorrente 2 anos após RM, por oclusão de enxerto de safena para Cx, tratada com stent na artéria nativa. Último registro: sem angina desde o procedimento, em uso de clopidogrel (alergia a AAS), estatina com ezetimiba e reabilitação cardíaca.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (346, 'Vicentina Cavalcanti Arruda', 'F', '1939-08-28', 'Recife', 'PE', 'Aposentada, ex-professora do ensino fundamental', 'HAS de longa data, obesidade grau 1, DM2 e osteoartrite de joelhos com uso frequente de diclofenaco (comprado sem receita). Viúva, mora com a filha. ICFEp diagnosticada há 1 ano. Uso de anlodipino 10 mg e losartana 50 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1174, 346, 11, '2023-05-09 14:00', 'consulta', 'Pernas muito inchadas e cansaço até para tomar banho', 156, 84, 74, 78.0, 'Mulher de 83 anos com ICFEp e HAS, piora do edema de MMII e da dispneia há 3 semanas, após aumentar o diclofenaco para 50 mg 3x/dia por dor nos joelhos. Ganho de 4 kg. Ao exame: jugulares a 45° com refluxo hepatojugular, estertores nas bases, edema 3+. PA 156x84. Creatinina 1,6 (TFGe 31), K 4,9, NT-proBNP 2.600. ECO: FEVE 60%, HVE concêntrica, E/e'' 18. AINE causando retenção hídrica, piora da função renal e elevação da PA. Descompensação de IC por AINE.', 'Suspender totalmente o diclofenaco (paracetamol e dipirona para a dor, fisioterapia). Furosemida 40 mg 12/12h, manter losartana e anlodipino reduzido a 5 mg. Iniciar dapagliflozina após estabilização da função renal. Creatinina e K em 5 dias. Retorno em 2 semanas.'),
  (1175, 346, 11, '2023-05-23 14:30', 'retorno', 'Estou mais leve, os pés desincharam', 138, 76, 70, 73.5, 'Duas semanas depois, sem diclofenaco (a filha guardou os frascos). Perdeu 4,5 kg, dispneia melhor (NYHA II), edema 1+. Creatinina 1,3 (TFGe 40), K 4,5. PA 138x76. Joelhos doloridos, mas aceitável com paracetamol e fisioterapia. Sem tontura. Pode iniciar iSGLT2 com função renal estável.', 'Iniciar dapagliflozina 10 mg pela manhã, reduzir furosemida para 40 mg/dia. Creatinina e K em 1 semana e após 1 mês. Pesar-se diariamente. Fisioterapia para os joelhos. Retorno em 2 meses.'),
  (1176, 346, 11, '2023-11-14 15:00', 'teleconsulta', 'Minha mãe está bem, só preciso da receita', 134, 74, null, 72.0, 'Teleconsulta com a filha, que mede a PA e o peso em casa. Paciente sem dispneia, peso estável em 72 kg, PA entre 130-138 por 72-78. Sem edema segundo a filha, usando as medicações corretamente. Joelhos controlados com paracetamol. Exames de 15 dias atrás: creatinina 1,2, K 4,6. Combinado ECO e NT-proBNP no retorno presencial, que ainda precisa ser agendado.', 'Receita renovada por 6 meses. Retornar presencial para ECO e exames em 2 meses. Orientadas a não retornar ao diclofenaco ou outros AINEs. Procurar PS se ganho de peso > 2 kg em 3 dias.');
