insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (346, '2024-06-15', 'abandonou', 'ICFEp descompensada por uso de AINE, compensada após suspensão do diclofenaco e início de dapagliflozina. A paciente e a filha não voltaram para o retorno presencial com ECO e exames, marcado duas vezes, e as ligações não foram atendidas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (347, 'Jaílson Brito Dantas', 'M', '1954-10-20', 'Natal', 'RN', 'Pescador aposentado', 'IAM de parede anterior há 6 anos tratado só com trombolítico, sem angioplastia. IC com FEVE reduzida desde então. HAS, DM2 em metformina e glibenclamida, tabagista de 40 maços-ano que parou há 2 anos. Tomava enalapril, carvedilol e furosemida de forma irregular.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1177, 347, 11, '2020-02-11 08:50', 'consulta', 'Falta de ar quando ando, pernas inchando de novo', 118, 74, 84, 76.0, 'Homem de 65 anos, ICFEr isquêmica com piora da dispneia aos pequenos esforços e edema de MMII nos últimos 2 meses (NYHA III). Ao exame: jugulares a 45°, B3, estertores bibasais, hepatomegalia, edema 2+. ECG: sinusal 84 bpm, onda Q anterior, BRE. ECO: FEVE 27%, aneurisma apical, DDVE 67 mm. NT-proBNP 3.800. Creatinina 1,3, K 4,8. Aderência irregular por limitações do SUS e dificuldade de ir à cidade, pois mora em comunidade de pescadores.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (pausa de 36h), carvedilol titulado para 6,25 mg 12/12h, adicionar espironolactona 25 mg e dapagliflozina 10 mg. Furosemida 40 mg. K e creatinina em 1 semana. Agente comunitário vai acompanhar a adesão. Retorno em 30 dias.'),
  (1178, 347, 11, '2020-08-18 09:00', 'retorno', 'Estou melhor, mas ainda canso nos esforços grandes', 108, 66, 64, 71.5, 'Seis meses de terapia otimizada com boa adesão pelo agente comunitário. NYHA II, perdeu 4,5 kg de edema. ECO de controle: FEVE 30%, aneurisma apical persistente. Holter: ESV frequentes e 3 episódios de TVNS. K 4,9, creatinina 1,3. Carvedilol em 12,5 mg 12/12h. Paciente preencheria critério de CDI em prevenção primária (FEVE ≤ 35% em CF II-III com 3 meses de terapia otimizada), porém recusa: "não quero máquina no peito". Esposa preocupada.', 'Reforçada a indicação de CDI, discutindo risco de morte súbita (cerca de 1 em 5 em 5 anos nessa situação). Concordou em pensar. Encaminhar à arritmologia para consulta. Manter terapia. Retorno em 3 meses.'),
  (1179, 347, 4, '2021-03-09 04:30', 'internacao', 'Choque do coração em casa e desmaio', 96, 60, 142, 72.0, 'Trazido de madrugada por ambulância após síncope e relato da esposa de que ''ficou roxo e caído'', recuperando-se em 2 minutos. Admitido com TV monomórfica sustentada a 142 bpm, PA 96x60, estável, cardiovertido eletricamente com 100 J, reversão para ritmo sinusal. K 3,4 e Mg 1,5, repostos. Troponina negativa. ECO: FEVE 28%. Iniciada amiodarona IV. Neste momento aceitou o CDI: "agora entendi, doutor". Aguarda vaga regulada pelo SUS para implante em 2 semanas, tendo alta com amiodarona oral e monitorização domiciliar orientada.', 'Alta com amiodarona 200 mg 12/12h por 10 dias e depois 200 mg/dia. Manter terapia da IC. Suspender atividades exigentes. Orientação para retornar ao PS se palpitações ou tontura. CDI agendado pela regulação.');
