insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (347, '2021-03-22', 'obito', 'Óbito súbito em domicílio 13 dias após a alta, antes do implante do CDI que aguardava na regulação do SUS. Sem atendimento médico, a esposa relata colapso súbito durante a madrugada, compatível com arritmia ventricular em paciente com ICFEr isquêmica e FEVE de 28%.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (348, 'Dorival Zanini Bertucci', 'M', '1955-08-14', 'Jundiaí', 'SP', 'Representante comercial', 'HAS em uso de losartana 50 mg 12/12h. Sedentário, sobrepeso e etilismo social. Há 2 meses percebeu cansaço e coração acelerado, que atribuiu ao estresse do trabalho; não procurou ajuda. Sem diabetes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1180, 348, 2, '2022-05-10 15:00', 'consulta', 'Estou cansado e o coração está acelerado há uns dois meses', 138, 86, 136, 91.0, 'Homem de 66 anos com palpitações e cansaço aos esforços moderados há 2 meses. Ao exame: pulso irregular, FC 136, RCI 2T, sem sopros, MV+ sem RA, sem edema. ECG: fibrilação atrial com resposta ventricular de 136 bpm. ECO: átrio esquerdo 48 mm, FEVE 48%, DDVE 56 mm, sem valvopatia. TSH normal. CHA2DS2-VASc 2 (idade 65-74, HAS). FA persistente com alta resposta ventricular, provavelmente com mais de 8 semanas, sem anticoagulação prévia.', 'Iniciar apixabana 5 mg 12/12h e metoprolol succinato 50 mg, titular para FC < 110. Cardioversão elétrica após 3 semanas de anticoagulação ou ETE prévio. Reduzir álcool. Retorno em 3 semanas.'),
  (1181, 348, 2, '2022-08-23 15:30', 'retorno', 'A cardioversão não aconteceu e continuo cansado', 126, 80, 104, 93.0, 'Retorno com 3 meses de atraso por viagens de trabalho e adiamento da cardioversão. FC 104 em FA persistente, com ganho de 2 kg, edema discreto vespertino de tornozelos e dispneia aos esforços moderados. ECO: FEVE 38% (queda de 10 pontos), DDVE 60 mm, sugerindo taquicardiomiopatia. NT-proBNP 1.200. Mantém apixabana sem falhas e metoprolol 50 mg. Hb 14,8, creatinina 1,0. A queda da FEVE em FA persistente sustenta a necessidade de controle de ritmo.', 'Programar cardioversão elétrica urgente (anticoagulação > 3 semanas comprovada) com amiodarona 200 mg/dia depois. Aumentar metoprolol para 100 mg, adicionar furosemida 20 mg. Reduzir ao mínimo viagens a trabalho até a cardioversão. Retorno em 3 semanas.'),
  (1182, 348, 11, '2022-12-13 03:40', 'internacao', 'Acordei sem ar, não consigo deitar', 150, 94, 128, 97.0, 'Internado por IC descompensada em FA com resposta rápida (128 bpm), SatO2 89% em ar ambiente, estertores até campos médios, edema 3+, ganho de 4 kg. NT-proBNP 4.900, FEVE 28% ao ECO, DDVE 63 mm. Cardioversão elétrica durante a internação (150 J) com reversão para ritmo sinusal, iniciada amiodarona. Diurese com furosemida IV, -5 kg em 5 dias. Admite que adiou de novo a cardioversão. Introduzidos carvedilol, sacubitril/valsartana e dapagliflozina com boa tolerância. Alta em ritmo sinusal com FC 66.', 'Alta com amiodarona 200 mg/dia, apixabana 5 mg 12/12h, terapia da IC (sacubitril/valsartana, carvedilol, espironolactona, dapagliflozina). Retorno em 15 dias para ECG e exames. Perda de peso e abstinência de álcool.'),
  (1183, 348, 4, '2023-06-20 15:00', 'retorno', 'O coração voltou a disparar e estou cansado de novo', 120, 76, 118, 92.0, 'Seis meses depois, FA recidivou há 3 meses apesar da amiodarona, com FC 118 em repouso e dispneia aos médios esforços (NYHA III). Peso estável, sem edema. ECO: FEVE 30%, mantendo disfunção apesar da terapia otimizada, com FA persistente. Hipotireoidismo induzido por amiodarona: TSH 11, T4 livre baixo. TGO normal. Falência do controle de ritmo clínico com amiodarona, FA recorrente e IC com FEVE reduzida: indicação de ablação por cateter.', 'Suspender amiodarona (hipotireoidismo), iniciar levotiroxina 50 mcg. Encaminhar à ablação de FA (isolamento de veias pulmonares); se falhar, considerar ablação do nó AV com ressincronização. Manter terapia da IC. Retorno em 6 semanas.');
