insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (348, '2023-06-20', 'piorou', 'FA persistente de alta resposta não tratada precocemente evoluiu com taquicardiomiopatia (FEVE de 48% para 30%) e internação por IC. Houve recidiva da FA após cardioversão, mesmo com amiodarona, que causou hipotireoidismo. Encaminhado para ablação por cateter.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (349, 'Zilda Maria Sartori Bolzan', 'F', '1971-09-10', 'Santiago', 'RS', 'Costureira autônoma', 'Febre reumática na infância, sem profilaxia secundária completa. Sopro conhecido desde os 20 anos. Dispneia progressiva há 2 anos, palpitações. Sem outras comorbidades. Mãe com valvopatia reumática operada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1184, 349, 1, '2023-02-14 10:00', 'consulta', 'Falta de ar para subir escada e coração batendo irregular', 116, 74, 104, 62.0, 'Mulher de 51 anos com dispneia aos moderados esforços e palpitações irregulares há 6 meses. Ao exame: pulso irregular, RCI, estalido de abertura mitral e ruflar diastólico 3+/6 em foco mitral com reforço pré-sistólico ausente (FA), B1 hiperfonética, estertores bibasais discretos, edema ausente. ECG: fibrilação atrial, resposta ventricular de 104. ECO: estenose mitral reumática, área valvar 1,1 cm² (pressure half-time), gradiente médio 11 mmHg, átrio esquerdo 52 mm, PSAP 52 mmHg, FEVE 62%, score de Wilkins 7, sem trombo. Estenose mitral moderada a importante com FA.', 'Anticoagulação com varfarina (INR 2 a 3), pois DOAC não é indicado em estenose mitral moderada a grave. Metoprolol succinato 50 mg para controle de FC. Profilaxia secundária de febre reumática com penicilina benzatina 1.200.000 UI IM a cada 21 dias. Avaliar valvoplastia por balão.'),
  (1185, 349, 12, '2023-03-28 10:30', 'retorno', 'Trouxe o ETE e o INR', 112, 72, 88, 61.5, 'Seis semanas de varfarina, INR 2,4 hoje (alvo atingido em 3 das últimas 4 medidas). ETE: válvula mitral com folhetos espessados, fusão comissural e boa mobilidade, calcificação leve, aparelho subvalvar com acometimento moderado, sem trombo em apêndice atrial esquerdo, insuficiência mitral discreta. Wilkins 7. Morfologia favorável a valvoplastia mitral por cateter-balão em paciente sintomática com FA. Discutido com hemodinâmica. Dispneia NYHA II-III, FC 88.', 'Indicada valvoplastia mitral percutânea com balão (técnica de Inoue). Internação eletiva em 2 meses. Manter varfarina até 5 dias antes e ponte com heparina. Orientações pré-procedimento. Retorno após o procedimento.'),
  (1186, 349, 10, '2023-05-23 07:30', 'internacao', 'Internação eletiva para valvoplastia mitral', 114, 70, 82, 61.5, 'Valvoplastia mitral por balão (Inoue 28 mm) por punção transeptal, guiada por ECO. Antes: gradiente médio 12 mmHg, área 1,1 cm². Após dilatação gradual: gradiente médio 4 mmHg, área 1,9 cm², sem aumento da insuficiência mitral (grau discreto), sem derrame pericárdico. PA 112x70. Sem complicações. Alta no 2º dia com ECO de controle: PSAP caiu para 34 mmHg. Retomada a varfarina com heparina até INR terapêutico.', 'Manter varfarina (FA persiste) com INR 2 a 3 e penicilina benzatina a cada 21 dias. Reduzir metoprolol conforme FC. Retorno em 30 dias com ECO.'),
  (1187, 349, 1, '2023-11-14 10:20', 'retorno', 'Respirando bem, a costura rende de novo', 118, 74, 76, 63.0, 'Seis meses de valvoplastia, NYHA I, sem dispneia nem palpitações importantes. Voltou a coser 8 horas por dia. ECG: FA de FC controlada, 76 bpm. ECO: área mitral 1,8 cm², gradiente médio 5 mmHg, IM discreta, AE 50 mm, PSAP 32 mmHg, FEVE 64%. INR dentro da faixa em 75% das medidas, sem sangramento. Penicilina benzatina em dia, aplicada na UBS.', 'Manter varfarina por tempo indeterminado (FA + EM), metoprolol e penicilina benzatina até pelo menos 40 anos ou 10 anos desde o último surto. ECO anual. Profilaxia de endocardite em procedimentos dentários. Retorno em 6 meses.');
