insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (349, '2023-11-14', 'melhorou', 'Estenose mitral reumática com FA tratada com varfarina e valvoplastia por balão bem-sucedida: área valvar de 1,1 para 1,8 cm², PSAP de 52 para 32 mmHg e classe funcional I. Mantém anticoagulação e profilaxia da febre reumática, retornou ao trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (350, 'Felipe Bortolotto Kaminski', 'M', '1985-03-17', 'Guarapuava', 'PR', 'Técnico em eletrônica', 'Hígido, sem comorbidades. Quadro viral de vias aéreas superiores há 10 dias. Ex-atleta amador de handebol, não fuma. Sem uso de medicações contínuas. Sem história familiar de cardiopatia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1188, 350, 6, '2023-10-05 18:40', 'pronto_socorro', 'Dor no peito que piora quando deito e quando respiro fundo', 128, 78, 100, 82.0, 'Pcte 38a com dor torácica pleurítica retroesternal, intensidade 7/10, piora ao decúbito dorsal e à inspiração profunda e alívio ao inclinar para a frente, iniciada ontem. Febre baixa (37,7). Quadro gripal há 10 dias. Ao exame: BEG, taquicárdico, atrito pericárdico audível em borda esternal esquerda, pulmões limpos. ECG: supra de ST côncavo difuso (DI, DII, aVF, V2-V6) e infradesnível de PR, sem recíprocos. Troponina negativa. PCR 48. ECO à beira leito: derrame pericárdico mínimo, sem tamponamento. HD: pericardite aguda idiopática/viral.', 'Ibuprofeno 600 mg 8/8h por 2 semanas com omeprazol, colchicina 0,5 mg 12/12h por 3 meses, repouso e restrição de exercícios. Alta com retorno em 1 semana. Orientado a retornar se dispneia, síncope ou piora da dor.'),
  (1189, 350, 1, '2023-10-20 08:30', 'retorno', 'A dor passou em três dias, vim ver se posso voltar a jogar', 118, 72, 68, 81.5, 'Quinze dias do início, sem dor torácica há 10 dias. Sem febre. Tomou o ibuprofeno por 14 dias e iniciou a redução progressiva. Ao exame: sem atrito, ausculta normal. ECG: normalizou, sem supra, PR isoelétrico. PCR 4. ECO: sem derrame, FEVE 62%. Boa evolução, mas explicado o risco de recorrência (~15-30%) e a necessidade de manter a colchicina por 3 meses para reduzir esse risco. Ansioso para voltar a treinar.', 'Manter colchicina 0,5 mg 12/12h até completar 3 meses e desmame gradual do ibuprofeno em 2 semanas. Sem esportes competitivos até normalização de ECG e PCR por 3 meses. Retorno em 3 meses.'),
  (1190, 350, 6, '2024-01-16 20:10', 'pronto_socorro', 'A dor no peito voltou igualzinha à primeira vez', 132, 80, 96, 82.0, 'Pcte 38a, 3 meses após o 1º episódio, 2 semanas após suspender a colchicina por conta própria ("fiquei bom, achei que já podia parar"). Recorrência de dor pleurítica, melhora ao inclinar o tronco, febre baixa. Atrito pericárdico leve. ECG: novo supra côncavo difuso de ST com infra de PR. PCR 38, troponina negativa. ECO: derrame mínimo. Pericardite recorrente, 1º recorrência sem sinais de mau prognóstico (sem febre alta, sem tamponamento, sem miocardite).', 'Reiniciar ibuprofeno 600 mg 8/8h com desmame lento e retomar colchicina 0,5 mg 12/12h por, no mínimo, 6 meses. Repouso. Retorno em 1 semana no ambulatório. Se nova recorrência, discutir anti-IL-1 e RM cardíaca.'),
  (1191, 350, 1, '2024-07-09 08:40', 'retorno', 'Sem dor nenhuma nos últimos meses', 120, 74, 62, 80.5, 'Seis meses após a recorrência, assintomático, completou 6 meses de colchicina sem falhas e fez a redução gradual do ibuprofeno sem dor. ECG normal, PCR 2, ECO sem derrame. RM cardíaca: pericárdio sem realce tardio ou espessamento, sem miocardite. Voltou a treinar handebol no último mês, sem sintomas. Paciente aprendeu a lição: "não paro mais remédio sem falar com o médico".', 'Suspender colchicina com redução (0,5 mg/dia por 4 semanas e parar). Liberado para esportes. Retornar imediatamente se dor torácica pleurítica. Seguimento em 6 meses e depois sob demanda.');
