insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (350, '2024-07-09', 'melhorou', 'Pericardite viral que recorreu 3 meses depois de a colchicina ter sido interrompida por conta própria. Com 6 meses de colchicina e anti-inflamatório, ficou assintomático, com PCR e RM normais. Liberado para esportes e em retirada da colchicina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (351, 'Cláudio Roberto Tanabe Andrade', 'M', '1979-05-12', 'Maringá', 'PR', 'Motorista de aplicativo', 'Sem diagnóstico prévio de HAS. Pai hipertenso e infartou aos 61 anos. Trabalha 12 horas por dia sentado, come lanches na rua e toma refrigerante diariamente. Sedentário, não fuma, bebe cerveja nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1192, 351, 1, '2023-09-18 14:20', 'consulta', 'Medi a pressão na farmácia e estava 15 por 10', 154, 96, 82, 96.4, 'Paciente de 44 anos, assintomático, procura por pressão elevada aferida em farmácia em três ocasiões (148-156 / 92-98). Rotina de motorista de aplicativo, muito tempo sentado, alimentação irregular, muito sódio. Ao exame: IMC 31, circunferência abdominal 106 cm, RCR 2T BNF sem sopros, MV+ sem RA, sem edemas, pulsos simétricos. ECG sem sobrecarga. HD: hipertensão estágio 1 com risco cardiovascular moderado, obesidade grau I.', 'Solicitados exames de rotina e albuminúria. Iniciar MEV: reduzir sal e refrigerante, caminhar 30 min em 5 dias, parar nas pausas para andar. MRPA por 5 dias para confirmar. Sem medicação por ora. Retorno em 40 dias com MRPA e exames.'),
  (1193, 351, 1, '2023-10-30 15:10', 'retorno', 'Trouxe a medida de casa e os exames', 150, 94, 78, 95.0, 'Trouxe MRPA de 5 dias: média 148x92 mmHg, confirmando hipertensão. Relata que reduziu refrigerante, mas não conseguiu caminhar por causa da jornada. Perdeu 1,4 kg. Exames mostram glicemia limítrofe e LDL elevado, função renal normal e albuminúria negativa. Sem sintomas. Ao exame, RCR 2T BNF, sem sopros. HD: HAS estágio 1 confirmada por MRPA, pré-diabetes, dislipidemia leve.', 'Iniciar losartana 50 mg pela manhã. Reforçado MEV, com meta de 20 min de caminhada nos intervalos entre corridas. Repetir creatinina e potássio em 30 dias. Retorno em 3 meses com nova MRPA.'),
  (1194, 351, 1, '2024-03-11 16:00', 'retorno', 'Vim mostrar a pressão que anda boa', 126, 78, 72, 90.1, 'Paciente refere adesão regular à losartana, sem tosse ou outros efeitos. Passou a levar marmita e caminha no parque nos intervalos. Perdeu 6 kg em 5 meses. MRPA com média de 124x76 mmHg. Potássio e creatinina estáveis após introdução do BRA. Ao exame: RCR 2T BNF, sem edemas. HD: HAS estágio 1 controlada, obesidade em perda de peso.', 'Manter losartana 50 mg. Incentivada continuidade da perda de peso, meta de 85 kg. Reavaliar necessidade do medicamento caso perca mais de 10 kg. Retorno em 6 meses com MRPA e perfil lipídico.');
