insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (351, '2024-03-11', 'controlado', 'Hipertensão estágio 1 controlada com losartana 50 mg e mudanças de estilo de vida. Perdeu 6 kg, MRPA média 124x76 mmHg e função renal preservada. Segue em acompanhamento semestral com meta de novo emagrecimento para eventual redução do medicamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (352, 'Zuleica Matsuda Ferreira', 'F', '1953-02-09', 'Dourados', 'MS', 'Agricultora aposentada', 'HAS há 25 anos, osteoporose, artrose de joelhos. Em uso de losartana, anlodipino e hidroclorotiazida. Mora sozinha em sítio, filha visita aos domingos. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1195, 352, 2, '2024-04-08 08:30', 'consulta', 'Caí no quintal, a cabeça roda quando levanto', 168, 82, 68, 58.2, 'Paciente de 71 anos, queda da própria altura há 10 dias ao levantar da cadeira, com escoriação em cotovelo, sem perda de consciência. Refere tontura e escurecimento visual ao ficar de pé, principalmente pela manhã após os remédios. PA sentada 168x82, em pé após 3 minutos 126x70 com sintomas, queda de 42 mmHg. Pulsos presentes, RCR 2T BNF. Sem déficit focal. HD: hipotensão ortostática por anti-hipertensivos, hipertensão sistólica do idoso.', 'Suspender hidroclorotiazida e reduzir anlodipino para 5 mg. Manter losartana 50 mg à noite. Orientada a levantar devagar, hidratação e meias elásticas. Exames de sódio, potássio e glicemia. Avaliar equilíbrio e acuidade visual. Retorno em 4 semanas com medidas em pé.'),
  (1196, 352, 2, '2024-05-06 08:50', 'retorno', 'Não tive mais tontura', 142, 78, 70, 58.6, 'Retorna sem novas quedas e sem tontura ao levantar. Está bebendo mais água e usa meias. PA sentada 142x78 e em pé 136x76, sem queda postural significativa. Sódio e potássio normalizados após suspender o diurético. Filha comprou aparelho de pressão e trouxe anotações com médias de 138/76. Ao exame: marcha estável, Romberg negativo. HD: hipotensão ortostática resolvida, HAS com PA aceitável para a idade e a fragilidade.', 'Manter regime atual, meta individualizada de PA sistólica até 140 mmHg, evitando medicação extra. Encaminhada para fisioterapia de equilíbrio e vitamina D. Retorno em 6 meses com anotações domiciliares.'),
  (1197, 352, 2, '2024-11-04 09:10', 'retorno', 'Vim para a revisão, estou bem', 138, 76, 66, 59.0, 'Seis meses sem quedas nem tontura. Frequenta fisioterapia duas vezes por semana, relata mais firmeza ao andar. Anotações domiciliares com média de 136x74 e nenhuma medida abaixo de 110 sistólica. Ortostatismo negativo hoje. Sem edema de tornozelo. Ao exame: RCR 2T BNF, MV+ sem RA. HD: HAS em controle adequado para o perfil, risco de queda reduzido.', 'Manter losartana 50 mg à noite e anlodipino 5 mg. Continuar fisioterapia e orientação sobre iluminação da casa e tapetes. Retorno em 6 meses.');
