insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (352, '2024-11-04', 'melhorou', 'Hipotensão ortostática resolvida após suspensão da hidroclorotiazida e redução do anlodipino. Sem novas quedas, com PA domiciliar média de 136x74 mmHg, fisioterapia de equilíbrio em andamento e filha acompanhando as medidas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (353, 'Wilson Carvalhal Duarte Neto', 'M', '1968-11-03', 'Campo Grande', 'MS', 'Vendedor de peças automotivas', 'HAS há 14 anos, em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg. Pai com AVC aos 66 anos. Não fuma, bebe pouco. Sobrepeso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1198, 353, 2, '2024-01-22 10:00', 'consulta', 'Três remédios e a pressão não desce', 186, 108, 74, 88.7, 'Paciente de 55 anos com HAS mal controlada apesar de três classes em dose plena. Adesão verificada: traz as caixas, usa pontualmente, farmácia registra retiradas mensais. Técnica de medida revisada com manguito adequado, PA 186x108 em três aferições. MAPA externa mostra média 24h de 178/104, sem descenso noturno. Sem ronco relevante, Epworth 6. Ao exame: B4, sem sopros, sem edemas. Fundo de olho com cruzamento arteriovenoso patológico. Hipertensão resistente verdadeira em investigação.', 'Solicitados aldosterona e renina, creatinina, potássio, TSH, ECO e relação albumina/creatinina. Polissonografia agendada. Adicionar espironolactona 25 mg pela manhã, com controle de potássio e creatinina em 2 semanas. Manter restrição de sódio. Retorno em 5 semanas.'),
  (1199, 353, 2, '2024-02-26 10:30', 'retorno', 'Pressão melhorou um pouco', 152, 92, 70, 87.9, 'Refere boa tolerância à espironolactona, sem câimbras. Exames: aldosterona 9 ng/dL com atividade de renina 1,8 ng/mL/h (relação 5), afastando hiperaldosteronismo primário. TSH normal, polissonografia com IAH 6/h. ECO com HVE concêntrica leve, FEVE 64%. Potássio 4,6 e creatinina 1,1 após o início do antagonista. Mantém PA domiciliar 148x90. HD: hipertensão resistente verdadeira com lesão de órgão-alvo (HVE e retinopatia).', 'Aumentar espironolactona para 50 mg/dia. Novo controle de potássio e creatinina em 15 dias. Seguir com dieta hipossódica. Retorno em 3 meses.'),
  (1200, 353, 2, '2024-06-10 11:00', 'retorno', 'Pressão boa, mas o peito ficou dolorido', 126, 78, 68, 86.5, 'PA domiciliar média de 124x76 nas últimas duas semanas. Queixa de desconforto e leve aumento da mama bilateral há dois meses, sem nódulo palpável. Aceita o incômodo para manter a pressão controlada. Potássio 4,8 mEq/L, creatinina 1,2. Sem tontura. Ao exame: ginecomastia leve bilateral, sem secreção, RCR 2T BNF, sem edemas. HD: hipertensão resistente controlada, ginecomastia por espironolactona.', 'Manter os quatro fármacos. Explicadas alternativas (eplerenona), mas paciente prefere seguir como está. Ultrassom de mamas para documentar. Potássio e creatinina a cada 3 meses. Retorno em 4 meses.');
