insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (353, '2024-06-10', 'controlado', 'Hipertensão resistente verdadeira, sem causa secundária identificada, controlada com a adição de espironolactona 50 mg (PA domiciliar média 124x76). Ginecomastia leve tolerada, potássio 4,8 e creatinina 1,2 mg/dL em monitorização trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (354, 'Sônia Regina Wachholz', 'F', '1974-04-02', 'Cascavel', 'PR', 'Motorista de ônibus urbano', 'HAS diagnosticada há 4 anos, usa losartana 50 mg e anlodipino 5 mg sem controle. Obesidade. Ronco alto, sonolência no trânsito, dor de cabeça ao acordar. Trabalha em turnos alternados. Não fuma.', 'Dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1201, 354, 2, '2023-08-14 07:50', 'consulta', 'Durmo mal, ronco muito e a pressão não controla', 168, 104, 78, 108.5, 'Paciente de 49 anos, motorista de ônibus, refere cochilar nos pontos finais e quase ter perdido a direção uma vez. Marido relata pausas respiratórias com engasgos durante a noite. Epworth 16. Cefaleia matinal frequente. IMC 41, circunferência cervical 43 cm, Mallampati 4. PA 168x104 em uso de losartana e anlodipino. RCR 2T BNF, sem sopros. Pulsos simétricos. HD: suspeita de apneia obstrutiva do sono grave como causa de hipertensão de difícil controle.', 'Solicitada polissonografia com urgência e exames de rotina, TSH e aldosterona/renina. Orientação sobre risco de sonolência ao volante e conversa sobre afastamento temporário se necessário. Aumentar losartana para 100 mg. Retorno com resultados.'),
  (1202, 354, 2, '2023-10-09 08:20', 'retorno', 'Vim ver o resultado do exame do sono', 150, 94, 74, 107.8, 'Polissonografia: IAH 46 eventos/h, saturação mínima 71%, T90 de 28%. Diagnóstico de apneia obstrutiva do sono grave. TSH normal, relação aldosterona/renina negativa, creatinina normal. Iniciou CPAP automático há 3 semanas, com máscara nasal. Relata adaptação difícil nas primeiras noites, mas já dorme melhor e sem cefaleia matinal. Epworth caiu para 9. PA domiciliar média de 146x90. HD: hipertensão secundária à apneia obstrutiva do sono, em tratamento com CPAP.', 'Manter CPAP automático e orientar uso mínimo de 6 horas por noite. Aumentar anlodipino para 10 mg. Encaminhada ao nutricionista e programa de emagrecimento. Liberada para trabalho com Epworth em queda. Retorno em 5 meses com relatório de adesão do aparelho.'),
  (1203, 354, 2, '2024-03-04 07:40', 'retorno', 'Acordo descansada pela primeira vez em anos', 128, 80, 70, 99.8, 'Relatório do CPAP: uso médio de 6,2 horas por noite, 91% das noites, IAH residual 3,1/h. Sem sonolência ao volante, sem cefaleia. Perdeu 8 kg com dieta e caminhadas. Queixa leve de edema de tornozelo vespertino, atribuído ao anlodipino 10 mg. PA domiciliar média de 124x78. Ao exame: edema discreto 1+/4+, RCR 2T BNF. HD: HAS secundária à apneia, controlada com CPAP e perda de peso.', 'Reduzir anlodipino para 5 mg para diminuir o edema, mantendo losartana 100 mg. Seguir CPAP todas as noites. Meta de peso 90 kg. Retorno em 6 meses.');
