insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (354, '2024-03-04', 'controlado', 'Apneia obstrutiva grave (IAH 46) tratada com CPAP, com boa adesão e PA domiciliar média de 124x78 mmHg. Perda de 8 kg e retorno seguro ao trabalho como motorista. Anlodipino reduzido para controlar o edema.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (355, 'Osvaldo Pietrzak Mendes', 'M', '1962-03-30', 'Ponta Grossa', 'PR', 'Pedreiro', 'Tabagista de 40 maços-ano, ativo. Hipertensão nunca tratada, nunca fez acompanhamento. Etilismo social. Pai falecido de aneurisma de aorta aos 68 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1204, 355, 6, '2025-06-17 03:20', 'pronto_socorro', 'Dor horrível que rasga do peito até as costas', 224, 118, 108, 84.0, 'Pcte de 63 anos, trazido pelo SAMU com dor torácica de início súbito há 1h30, lancinante, irradiada para região interescapular e abdome, com sudorese fria. PA braço D 224x118, braço E 168x90. FC 108. Pulsos femorais diminuídos à esquerda. Sopro diastólico aórtico novo 2+/6+. ECG sem supra de ST. Troponina negativa na admissão. Angiotomografia de aorta: dissecção Stanford A com flap desde a raiz até a ilíaca. HD: dissecção aguda de aorta tipo A, crise hipertensiva.', 'Analgesia com fentanil. Esmolol em bomba para FC alvo 55-60, seguido de nitroprussiato para PAS 100-120 mmHg. Acesso arterial. Contato imediato com cirurgia cardiovascular e UTI. Transferência direta para centro cirúrgico. Jejum, tipagem e reserva de hemoderivados.'),
  (1205, 355, 12, '2025-06-17 07:30', 'internacao', 'Pós-operatório imediato de cirurgia de aorta', 104, 58, 92, null, 'Submetido a troca de aorta ascendente e valva aórtica (Bentall-De Bono) com parada circulatória hipotérmica, tempo de CEC 214 min. Entrou em UTI intubado, em uso de noradrenalina 0,15 mcg/kg/min. Sangramento por dreno de mediastino de 400 mL na 1ª hora, coagulopatia corrigida com plasma e plaquetas. Pulsos de membros inferiores presentes. HD: PO imediato de Bentall por dissecção tipo A, vasoplegia.', 'Ventilação protetora, sedação leve, balanço hídrico rigoroso. Reposição de hemoderivados guiada por tromboelastograma. Noradrenalina em desmame conforme PAM > 65. Controle de lactato e diurese horária. Reavaliar função renal em 12 horas.'),
  (1206, 355, 14, '2025-06-22 06:10', 'internacao', 'Piora renal e instabilidade no 5º dia de UTI', 88, 46, 118, null, '5º PO, evolui com choque misto, febre de 38,9, secreção traqueal purulenta e leucocitose. Oligúria apesar de volume, creatinina de 1,0 para 3,9 mg/dL. Hemocultura com Klebsiella. Isquemia mesentérica suspeitada por lactato 7,2 e distensão abdominal; angiotomografia mostra hipoperfusão de alças e falso lúmen comprimindo tronco celíaco. Equipe cirúrgica avaliou como não candidato a nova cirurgia pelo estado hemodinâmico. HD: sepse pulmonar, IRA dialítica, isquemia mesentérica.', 'Meropenem, noradrenalina e vasopressina, hemodiálise contínua. Familiares informados sobre gravidade e prognóstico reservado; optado por manter suporte sem novas intervenções cirúrgicas. Reavaliação clínica a cada 6 horas.');
