insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (355, '2025-06-24', 'obito', 'Óbito no 7º dia de pós-operatório de dissecção aórtica tipo A, por choque séptico associado a isquemia mesentérica e insuficiência renal aguda. Hipertensão nunca tratada e tabagismo foram os principais fatores de risco; família orientada quanto ao rastreio de aneurisma nos parentes de primeiro grau.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (356, 'Maria das Neves Calheiros Barbosa', 'F', '1958-09-25', 'Recife', 'PE', 'Professora aposentada', 'HAS há 18 anos, dislipidemia e DM2 há 8 anos. Em uso de losartana 50 mg 12/12h, metformina e sinvastatina 20 mg. Sedentária. Mãe com infarto aos 64 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1207, 356, 1, '2022-05-09 15:00', 'consulta', 'Aperto no peito quando subo a ladeira de casa', 148, 86, 80, 74.6, 'Paciente de 63 anos com dor retroesternal em aperto aos esforços moderados há 2 meses, melhora com repouso em 5 minutos, sem dor em repouso. Angina típica CCS II. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA. ECG de repouso com ritmo sinusal e ondas T negativas discretas em V4-V6. HD: angina estável, alto risco por DM2, dislipidemia e HAS.', 'Solicitar teste ergométrico, ecocardiograma e perfil lipídico. Trocar sinvastatina por atorvastatina 40 mg. Iniciar AAS 100 mg e metoprolol succinato 50 mg. Nitrato sublingual se dor, com orientação de procurar PS se não melhorar. Retorno com os exames.'),
  (1208, 356, 10, '2022-06-20 09:30', 'internacao', 'Vim fazer o cateterismo', 138, 80, 62, 74.0, 'Teste ergométrico positivo com infradesnivelamento de ST de 2,5 mm em V5-V6 aos 6 METs, interrompido por angina. ECO com FEVE 58% e hipocinesia leve da parede anterior. LDL 118 mg/dL. Submetida a CATE por via radial direita: lesão de 80% em DA proximal, CD com lesão de 40%, Cx sem lesões. Realizada ATC com implante de stent farmacológico 3,0x18 mm em DA com bom resultado angiográfico. Sem intercorrências.', 'Dupla antiagregação com AAS 100 mg e clopidogrel 75 mg por 6 meses, depois manter AAS. Atorvastatina elevada para 80 mg, meta de LDL < 55. Alta no dia seguinte. Orientada reabilitação cardiovascular e controle glicêmico. Retorno em 3 meses.'),
  (1209, 356, 1, '2022-09-12 15:30', 'retorno', 'Sem dor no peito, só cansada às vezes', 124, 74, 58, 72.3, 'Sem angina desde a angioplastia. Iniciou hidroginástica duas vezes por semana na reabilitação. Tolera bem as medicações, sem sangramentos. FC de 58 bpm em uso de metoprolol, sem tontura. LDL 49 mg/dL e HbA1c 6,9%. PA domiciliar em torno de 122x72. Ao exame: RCR 2T BNF, MV+ sem RA. ECG sem alterações novas. HD: DAC uniarterial tratada com stent, assintomática, metas lipídicas atingidas.', 'Manter dupla antiagregação até completar 6 meses, depois suspender clopidogrel e seguir com AAS. Continuar reabilitação e atorvastatina 80 mg. Retorno em 6 meses com perfil lipídico e função hepática.');
