insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (356, '2022-09-12', 'controlado', 'Angina estável tratada com angioplastia e stent farmacológico em DA proximal. Assintomática, LDL 49 mg/dL, HbA1c 6,9% e PA 124x74 mmHg, em reabilitação cardiovascular e seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (357, 'Eliseu Cardoso Bortolotto', 'M', '1966-01-14', 'Três Lagoas', 'MS', 'Operador de máquinas em fábrica de celulose', 'Tabagista de 35 maços-ano. HAS sem tratamento regular, dislipidemia nunca tratada. Irmão infartou aos 52 anos. Sedentário e come muito frito.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1210, 357, 6, '2025-02-08 22:10', 'pronto_socorro', 'Dor forte no peito que não passa, suando frio', 150, 92, 54, 92.0, 'Pcte de 59 anos, com dor precordial intensa há 1h, opressiva, com náuseas e sudorese. Nega uso de medicação. Ao exame: pálido, sudorético, RCR 2T BNF, MV+ sem RA, pulmões limpos. ECG: supra de ST de 3 mm em DII, DIII e aVF com infra especular em DI e aVL, bradicardia sinusal 54 bpm. Troponina 0,9 ng/mL. HD: IAMCSST de parede inferior, Killip I.', 'Dupla antiagregação com AAS 300 mg e ticagrelor 180 mg de ataque, enoxaparina e atorvastatina 80 mg. Evitar nitrato por risco de acometimento de ventrículo direito. Acionado serviço de hemodinâmica para angioplastia primária, porta-balão estimado em 60 minutos.'),
  (1211, 357, 10, '2025-02-09 01:00', 'internacao', 'Pós angioplastia primária, sem dor', 118, 72, 66, 92.0, 'Cateterismo por via radial direita: oclusão trombótica de coronária direita média, lesão de 50% em DA, Cx sem lesões. Realizada ATC primária com stent farmacológico 3,5x24 mm em CD, fluxo TIMI 3 final. Ventrículo esquerdo com hipocinesia inferior e FEVE estimada 52%. Pico de troponina de 38 ng/mL. Sem arritmias, sem sangramento no sítio de punção. HD: IAMCSST inferior tratado com ATC primária da CD.', 'Internação em UTI coronariana por 24 horas. Iniciar bisoprolol 2,5 mg, ramipril 2,5 mg e manter dupla antiagregação por 12 meses. Orientações de cessação do tabagismo com reposição de nicotina. ECO antes da alta. Programa de reabilitação cardiovascular.'),
  (1212, 357, 1, '2025-04-28 08:20', 'retorno', 'Voltei a trabalhar, sem dor, mas parei o cigarro', 122, 76, 60, 89.4, 'Dois meses e meio após o IAM. Sem dor torácica, sem dispneia aos esforços habituais. Parou de fumar desde a internação com adesivo, hoje reduziu a dose. Frequenta reabilitação três vezes por semana e atingiu 9 METs. Tem leve dispneia ao ticagrelor, tolerável. Ao exame: RCR 2T BNF, pulmões limpos, punção radial sem alterações. LDL 58 mg/dL. HD: pós-IAMCSST inferior com boa evolução, FEVE recuperada.', 'Manter ticagrelor até 12 meses e AAS contínuo. Atorvastatina 80 mg, bisoprolol 2,5 mg e ramipril 2,5 mg mantidos. Reduzir adesivo para 14 mg. Retorno em 4 meses com ECO de controle e perfil lipídico.');
