insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (357, '2025-04-28', 'melhorou', 'IAMCSST inferior tratado com angioplastia primária e stent em coronária direita. FEVE recuperada para 60%, assintomático em reabilitação, ex-tabagista há 11 semanas e LDL 58 mg/dL. Segue com dupla antiagregação até 12 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (358, 'Terezinha Aparecida Sgarbi', 'F', '1951-12-05', 'Londrina', 'PR', 'Comerciante aposentada', 'HAS há 30 anos, DM2 há 15 anos, obesidade, osteoartrose. Em uso de anlodipino 10 mg, losartana 50 mg 12/12h, metformina e glibenclamida. Nunca fumou. Mora com a filha.', 'Sulfa (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1213, 358, 11, '2025-03-10 10:20', 'consulta', 'Falta de ar para subir os degraus da igreja', 146, 80, 76, 84.5, 'Paciente de 73 anos com dispneia aos pequenos esforços e inchaço em tornozelos há 3 meses, ortopneia com 2 travesseiros, sem DPN. Ao exame: ritmo regular, B4, sem sopros, estertores bibasais discretos, turgência jugular a 45 graus, edema 2+/4+ até joelhos. NT-proBNP 1.240 pg/mL. ECO: FEVE 60%, relação E/e'' 17, átrio esquerdo aumentado (volume 48 mL/m²), HVE concêntrica. HD: ICFEp (cardiopatia hipertensiva) em classe funcional III NYHA, descompensação leve.', 'Iniciar dapagliflozina 10 mg e furosemida 40 mg pela manhã. Suspender glibenclamida (risco de hipoglicemia com iSGLT2). Restrição de sódio a 2 g e peso diário. Creatinina e potássio em 1 semana. Retorno em 30 dias.'),
  (1214, 358, 11, '2025-04-14 10:40', 'retorno', 'Estou com menos inchaço, mas urino demais', 134, 76, 72, 80.2, 'Perdeu 4,3 kg em 5 semanas. Edema reduziu para 1+/4+, dorme com 1 travesseiro e consegue subir a rampa da igreja com pausa. Queixa de noctúria e prurido genital discreto, sem sintomas urinários. Creatinina 1,2 e potássio 4,3. Ao exame: pulmões limpos, jugular normal, B4 presente. Glicemia capilar média 118. HD: ICFEp melhor, classe II NYHA, quadro compatível com micose genital leve.', 'Tomar a furosemida apenas pela manhã. Higiene local e orientação sobre secura da área genital; creme antifúngico tópico. Iniciar espironolactona 25 mg com controle de potássio em 10 dias, dada hipertensão e FEp. Seguir hipossódica. Retorno em 3 meses.'),
  (1215, 358, 11, '2025-09-22 10:00', 'retorno', 'Quase não tenho mais falta de ar', 128, 72, 70, 78.0, 'Sem internações, sem dispneia aos esforços habituais, classe I-II. Peso seco 78 kg, edema ausente. Potássio 4,9 e creatinina 1,3 após espironolactona, estável. NT-proBNP caiu para 380 pg/mL. HbA1c 7,0%. Anlodipino provocou edema discreto de tornozelo apenas no fim do dia. Ao exame: pulmões limpos, sem estase jugular. HD: ICFEp compensada, HAS controlada, DRC estágio 3a.', 'Manter dapagliflozina, espironolactona e furosemida 40 mg, com redução da furosemida para 20 mg se peso cair abaixo de 77 kg. Reduzir anlodipino para 5 mg. Potássio e creatinina a cada 3 meses. Retorno em 4 meses.');
