insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (358, '2025-09-22', 'estavel', 'ICFEp compensada com dapagliflozina, espironolactona e furosemida, classe funcional I-II e NT-proBNP em 380 pg/mL. Função renal estável em estágio 3a e PA 128x72 mmHg, mantida em acompanhamento trimestral de potássio e creatinina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (359, 'Raimundo Nonato Pantoja Lobato', 'M', '1946-10-21', 'Belém', 'PA', 'Aposentado, ex-estivador', 'HAS há 35 anos, DM2 há 12 anos, AIT há 3 anos. FA permanente diagnosticada em 2022 e anticoagulada irregularmente. Ex-tabagista. Vive de aposentadoria de um salário mínimo, mora com a esposa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1216, 359, 4, '2024-02-05 09:00', 'consulta', 'Coração dispara e canso para andar', 142, 86, 118, 71.8, 'Paciente de 77 anos com FA de resposta ventricular elevada, palpitações e dispneia leve aos esforços. Usa metoprolol quando lembra e parou o anticoagulante há 2 meses por falta na farmácia. CHA2DS2-VASc 6 (idade, HAS, DM, AIT), HAS-BLED 2. Ao exame: ritmo irregular, FC 118, sem sopros, pulmões limpos, sem edemas. ECG: FA com resposta ventricular média de 120. ECO com FEVE 54%, átrio esquerdo 49 mm. Clearance de creatinina 52 mL/min.', 'Iniciar rivaroxabana 20 mg com a refeição e metoprolol succinato 100 mg ao dia, com meta de FC < 110 e depois < 80. Orientado sobre risco de AVC sem anticoagulação. Assistente social para garantir o fornecimento do remédio. Retorno em 6 semanas com Holter.'),
  (1217, 359, 4, '2024-03-18 09:20', 'retorno', 'Melhorei do coração, mas o remédio acabou', 132, 80, 82, 72.0, 'Palpitações cessaram. Holter 24h: FA permanente, FC média 78, máxima 118, sem pausas ou TV. Tomou rivaroxabana por 5 semanas conseguidas por doação de amostras da clínica; agora relata que o fornecimento da farmácia popular não chegou. Sem sangramentos. Pergunta se pode usar "aquele remédio mais barato". Ao exame: ritmo irregular, FC 82, sem sinais de IC. HD: FA permanente com FC controlada, alto risco embólico, barreira de acesso ao DOAC.', 'Fornecido kit de 30 dias e encaminhado à assistente social. Discutida varfarina como alternativa de custo com INR mensal; paciente mora longe do laboratório e prefere manter DOAC. Manter metoprolol 100 mg. Retorno em 3 meses.'),
  (1218, 359, 4, '2024-06-24 09:40', 'retorno', 'Vim buscar mais remédio', 148, 88, 94, 70.5, 'Retorna após 3 meses. Confessa que a rivaroxabana acabou há 5 semanas e que, para economizar, parou também o metoprolol "quando se sente bem". Sem sangramentos, sem sintomas neurológicos. Esposa confirma que a renda caiu depois de uma internação dela. Ao exame: FA com FC 94, sem sinais de congestão. HD: FA permanente, descontinuação do anticoagulante, risco de AVC muito alto.', 'Receita nova com rivaroxabana e metoprolol e fornecidas amostras para 30 dias. Orientados sinais de AVC. Agendada visita da assistente social para o mês seguinte e retorno em 30 dias para checar adesão. Discutida troca para varfarina se persistir a dificuldade de acesso.');
