insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (359, '2025-02-03', 'abandonou', 'Não compareceu ao retorno de julho de 2024 nem às duas remarcações. Contato telefônico com a esposa em fevereiro de 2025: o paciente parou rivaroxabana e metoprolol por falta de dinheiro e dificuldade de transporte, mas sem eventos neurológicos. Orientado a procurar a unidade básica de saúde mais próxima.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (360, 'Domingas Aparecida Ribeiro de Paula', 'F', '1963-03-17', 'Bambuí', 'MG', 'Lavradora aposentada', 'Nascida em casa de pau-a-pique na zona rural; sorologia para Chagas positiva desde 2008. Irmãos também chagásicos. HAS leve. Nunca fez tratamento específico, nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1219, 360, 11, '2021-08-16 08:40', 'consulta', 'Cansaço para varrer a casa e tonteira', 104, 66, 58, 54.3, 'Paciente de 58 anos, chagásica crônica, com dispneia aos médios esforços há 8 meses, edema vespertino de pés e 2 episódios de tonteira com palpitação. Ao exame: ritmo regular, B3, sopro sistólico de regurgitação mitral 2+/6+, estertores bibasais discretos, edema 1+/4+. ECO: cardiomiopatia dilatada com FEVE 28% e aneurisma apical. Holter com TVNS (4 episódios). HD: cardiopatia chagásica crônica em fase dilatada, ICFEr classe III, arritmia ventricular.', 'Iniciar sacubitril/valsartana 24/26 mg 12/12h, carvedilol 3,125 mg 12/12h e espironolactona 25 mg. Furosemida 40 mg. Não indicado benznidazol por cardiopatia estabelecida. Ressonância cardíaca e avaliação de CDI. Potássio e creatinina em 1 semana. Retorno em 30 dias.'),
  (1220, 360, 4, '2022-02-10 11:00', 'internacao', 'Desmaiei na cozinha, vim para colocar o aparelho', 98, 60, 52, 53.0, 'Internada eletivamente após síncope com TV monomórfica sustentada documentada em ECG de pronto-atendimento em janeiro, revertida com amiodarona. FEVE 26%. Otimizou carvedilol para 12,5 mg 12/12h e sacubitril/valsartana para 49/51 mg 12/12h. Submetida a implante de CDI bicameral sem intercorrências, testes de limiar adequados. Ressonância com realce tardio extenso no segmento apical-inferior. HD: cardiopatia chagásica com TV sustentada, prevenção secundária de morte súbita.', 'Implante de CDI realizado. Manter amiodarona 200 mg ao dia e carvedilol. Revisão do CDI em 30 dias e telemonitoração. Orientações sobre choques e restrições de direção. Manter acompanhamento com insuficiência cardíaca.'),
  (1221, 360, 11, '2023-05-15 09:00', 'retorno', 'Levei um choque no peito de madrugada', 96, 58, 56, 52.1, 'Uma semana antes teve um choque do CDI de madrugada, após palpitação, sem síncope. Interrogação do aparelho mostrou TV monomórfica rápida (FC 188) revertida com 1 choque apropriado. Sem novos episódios. Nega dispneia piora, mas refere cansaço. Hipotensão sintomática discreta ao levantar, sem queda. Tireoide: TSH 6,2 em uso de amiodarona. Ao exame: pulmões limpos, edema ausente, B3 audível. HD: cardiopatia chagásica com ICFEr e choque apropriado de CDI, classe II-III.', 'Adicionar dapagliflozina 10 mg. Manter amiodarona e betabloqueador. Reavaliar dose de furosemida para 20 mg dado PA baixa. TSH e T4L em 2 meses. Encaminhada ao Dr. Fernando para otimização antiarrítmica e possível ablação. Retorno em 3 meses.'),
  (1222, 360, 6, '2024-08-02 04:10', 'pronto_socorro', 'Acordei sem ar, afogada', 86, 52, 108, 56.8, 'Pcte de 61 anos, chagásica com CDI, chega ao PS com dispneia súbita de madrugada, taquipneia, SpO2 86% em ar ambiente, tosse com expectoração rosada. Parou furosemida e dapagliflozina há 2 semanas por "cansada de urinar". Ao exame: REG, extremidades frias, estertores até ápices, B3, edema 3+/4+, jugular ingurgitada. NT-proBNP 11.400 pg/mL, creatinina 1,8. Rx com congestão pulmonar. HD: EAP por descompensação de ICFEr chagásica com baixo débito, má adesão.', 'O2, furosemida 80 mg EV, nitroglicerina em baixas doses com atenção à PA, evitar betabloqueador agudo. Dobutamina se persistir hipoperfusão. Internação em UTI. Interrogação do CDI e avaliação para terapia avançada.');
