insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (360, '2024-09-05', 'piorou', 'Cardiopatia chagásica com ICFEr avançada, FEVE 22% e evolução para classe IV, com internação prolongada por EAP e baixo débito após interrupção dos diuréticos. Sem condições de alta domiciliar com suporte; encaminhada para avaliação em centro de insuficiência cardíaca avançada, aguardando lista de transplante.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (361, 'Lucimara Zanardo Pinheiro', 'F', '1981-08-14', 'Foz do Iguaçu', 'PR', 'Cabeleireira', 'Pressão alta aferida há 1 ano em campanha, nunca tratada. Fica em pé 10 horas por dia no salão. Mãe hipertensa. Não fuma, usa anticoncepcional oral combinado há 12 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1223, 361, 1, '2023-11-06 13:30', 'consulta', 'Dor de cabeça no fim do dia e pressão alta', 168, 104, 80, 78.2, 'Paciente de 42 anos com cefaleia occipital vespertina e PA elevada em várias medidas na farmácia (160-172 / 98-106). Sem dispneia, sem dor torácica. Usa anticoncepcional combinado, dieta com muito embutido e temperos prontos. Ao exame: IMC 29, RCR 2T BNF sem sopros, pulsos simétricos, sem edemas. Fundo de olho com leve estreitamento arteriolar. HD: hipertensão estágio 2, possível contribuição do anticoncepcional.', 'Iniciar telmisartana/anlodipino 40/5 mg em comprimido único pela manhã. Encaminhar para ginecologia revisar o anticoncepcional, trocando por método sem estrogênio. Exames de rotina, ECG e albuminúria. Reduzir sal e temperos prontos. Retorno em 30 dias.'),
  (1224, 361, 1, '2023-12-11 13:50', 'retorno', 'Melhorou, mas esqueço no fim de semana', 142, 88, 76, 77.4, 'Cefaleia desapareceu. Tolera bem o comprimido único, sem edema. Admite ter esquecido a medicação em alguns sábados e domingos, quando não vai ao salão. Ginecologista trocou o anticoncepcional por DIU de levonorgestrel há 3 semanas. PA domiciliar média de 138x86. Creatinina e potássio normais após BRA. Ao exame: RCR 2T BNF, sem edemas. HD: HAS estágio 2 em melhora, adesão irregular nos fins de semana.', 'Aumentar para telmisartana/anlodipino 80/5 mg. Colocar o remédio ao lado da escova de dentes e alarme no celular. Manter a retirada do estrogênio. MRPA em 4 semanas. Retorno em 90 dias.'),
  (1225, 361, 1, '2024-03-18 14:10', 'retorno', 'Vim mostrar a MRPA', 124, 76, 72, 75.6, 'Trouxe MRPA de 5 dias com média 122x74 mmHg, sem valores acima de 135/85. Adesão boa com alarme no celular. Sem edema de tornozelo, sem cefaleia. Perdeu 2,6 kg com caminhada no calçadão e menos embutidos. Ao exame: RCR 2T BNF, pulmões limpos. HD: HAS estágio 2 controlada com terapia combinada em comprimido único.', 'Manter telmisartana/anlodipino 80/5 mg. Reforçar atividade física e meta de IMC < 27. Exames de controle em 6 meses. Retorno semestral.');
