insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (361, '2024-03-18', 'controlado', 'Hipertensão estágio 2 controlada em comprimido único de telmisartana/anlodipino 80/5 mg, com MRPA média de 122x74 mmHg. Anticoncepcional com estrogênio substituído por DIU, adesão regularizada com alarme no celular e perda de 2,6 kg.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (362, 'Aristides Brandt Falcão', 'M', '1960-06-21', 'Campo Grande', 'MS', 'Caminhoneiro aposentado', 'HAS há 20 anos e DM2 há 14 anos, em uso de enalapril 20 mg 12/12h, anlodipino 10 mg, metformina 850 mg 2x/dia e gliclazida. Ex-tabagista (30 maços-ano, parou há 10 anos). Pai faleceu de IAM.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1226, 362, 1, '2021-03-15 09:10', 'consulta', 'Vim para trazer os exames do açúcar e da urina', 156, 90, 78, 96.8, 'Paciente de 60 anos, DM2 e HAS de longa data, assintomático. Come em postos de estrada há décadas e ainda tem hábito de fazer lanches fritos. Exames: HbA1c 8,4%, relação albumina/creatinina 480 mg/g (moderadamente a gravemente aumentada), creatinina 1,2, potássio 4,6. Ao exame: IMC 32, RCR 2T BNF, MMII sem edema, pulsos pediosos presentes, monofilamento alterado em hálux D. HD: HAS estágio 1 com albuminuria, DM2 mal controlado, possível nefropatia diabética.', 'Iniciar dapagliflozina 10 mg pelos benefícios renais e cardiovasculares. Suspender gliclazida. Manter enalapril e anlodipino. Fundo de olho e avaliação com endocrinologia. Retorno em 3 meses com creatinina, potássio e HbA1c.'),
  (1227, 362, 1, '2021-09-20 09:30', 'retorno', 'Me sinto bem, só cansado no fim do dia', 138, 82, 74, 92.3, 'Perdeu 4,5 kg. HbA1c 7,3%. Creatinina subiu de 1,2 para 1,4 após dapagliflozina, esperado como queda hemodinâmica inicial, estável desde então. Relação albumina/creatinina 360 mg/g. Sem hipoglicemias, sem infecção genital. Mantém adesão, mas relata que "não consegue deixar o pastel". Ao exame: RCR 2T BNF, sem edemas. HD: HAS estágio 1, DM2 melhorando, albuminúria persistente.', 'Manter esquema. Orientação nutricional com foco em redução de ultraprocessados. Repetir albuminúria e creatinina em 3 meses. Se persistir acima de 300 mg/g, considerar adicionar finerenona com controle de potássio. Retorno em 3 meses.'),
  (1228, 362, 8, '2023-02-20 10:30', 'retorno', 'Os pés estão inchando e urina espumosa', 164, 94, 80, 99.5, 'Reaparece após 17 meses sem retornos, encaminhado à nefrologia. Parou o acompanhamento por mudança de cidade e retomou a alimentação irregular, ganhou 7 kg. Edema 2+/4+ nos tornozelos, urina espumosa. HbA1c 9,1%, creatinina 1,9 (TFGe 38), relação albumina/creatinina 1.250 mg/g, potássio 5,3. Ultrassom de rins: tamanhos normais, ecogenicidade aumentada. HD: doença renal diabética em progressão, DRC estágio 3b A3, HAS descompensada.', 'Reduzir enalapril para 10 mg 12/12h até reavaliar potássio e adicionar diurético de alça. Suspender metformina (TFGe < 45 em queda). Insulina basal com a endocrinologia. Dieta com pouco potássio. Repetir exames em 10 dias. Retorno com a nefrologia em 30 dias.');
