insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (362, '2023-02-20', 'piorou', 'Progressão para doença renal diabética estágio 3b A3 após 17 meses sem acompanhamento, com albuminúria de 1.250 mg/g, HbA1c 9,1% e PA descompensada. Passa a ser seguido pela nefrologia, com insulina, ajuste do bloqueio do SRAA e controle rigoroso de potássio.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (363, 'Helena Yumi Kuroda', 'F', '1986-01-28', 'Curitiba', 'PR', 'Designer gráfica', 'Sem comorbidades conhecidas. Nunca teve pressão alta. Mãe com tireoidite autoimune. Dorme mal, ansiosa, muito café. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1229, 363, 1, '2023-04-17 10:40', 'consulta', 'Coração disparado, perdi peso e não consigo ficar parada', 158, 68, 112, 51.2, 'Paciente de 37 anos com palpitações, sudorese, tremor fino e insônia há 3 meses, perdeu 6 kg sem dieta. PA elevada em medidas recentes no trabalho, sistólica alta com diastólica baixa. Ao exame: inquieta, pele quente e úmida, tremor de extremidades, bócio difuso discreto, exoftalmia leve bilateral, RCR 2T BNF, FC 112 regular, hiperdinâmico, sem sopros. ECG com taquicardia sinusal. TSH < 0,01 e T4L 3,9 ng/dL. HD: hipertireoidismo (provável Graves) com hipertensão sistólica secundária.', 'Iniciar propranolol 40 mg 8/8h e metimazol 20 mg ao dia. Solicitar TRAb, anti-TPO, hemograma e transaminases (controle do metimazol). Encaminhada à endocrinologia. Evitar cafeína. Retorno em 3 semanas.'),
  (1230, 363, 9, '2023-06-05 14:00', 'retorno', 'O tremor passou, durmo melhor', 128, 76, 84, 53.0, 'Melhora importante dos sintomas, ganhou 1,8 kg. TRAb positivo em 12 UI/L, anti-TPO elevado, confirmando doença de Graves. Hemograma e transaminases normais. Hoje TSH ainda suprimido (0,03) e T4L 1,6 ng/dL, em queda. Oftalmopatia leve, sem diplopia. Ao exame: tremor discreto, pele menos úmida, bócio difuso pequeno. PA domiciliar média de 124x74. HD: Graves em tratamento, PA normalizando com controle do tireoidismo.', 'Reduzir metimazol para 15 mg e manter propranolol 20 mg 8/8h por mais algumas semanas. Controle de TSH e T4L em 6 semanas. Orientada a procurar atendimento se febre ou dor de garganta. Retorno em 2 meses.'),
  (1231, 363, 1, '2023-11-13 14:20', 'retorno', 'Vim ver a pressão depois que a tireoide ajustou', 114, 72, 68, 56.4, 'Eutireoidea há 3 meses, sem sintomas. Propranolol suspenso há 8 semanas sem taquicardia de rebote. PA domiciliar média 112x70, sem nenhum anti-hipertensivo. ECG de controle normal. Peso recuperado para 56 kg. Ao exame: RCR 2T BNF, FC 68, sem tremor. HD: hipertensão sistólica secundária ao hipertireoidismo, resolvida com o controle da tireoide.', 'Sem necessidade de anti-hipertensivo. Manter metimazol 5 mg por 12 a 18 meses conforme endocrinologia. Medidas domiciliares ocasionais. Alta da cardiologia, retornar se PA persistir > 140/90.');
