insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (363, '2023-11-13', 'controlado', 'Hipertensão sistólica secundária à doença de Graves resolvida após controle do hiper e suspensão do betabloqueador. Eutireoidea com metimazol 5 mg, PA domiciliar média de 112x70 mmHg sem anti-hipertensivos e alta da cardiologia com seguimento endocrinológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (364, 'Jaqueline Medeiros Vilhalva', 'F', '1995-09-09', 'Dourados', 'MS', 'Atendente de loja', 'Primigesta, sem comorbidades prévias, IMC pré-gestacional de 29. Mãe teve pré-eclâmpsia na gestação da paciente. Pré-natal pelo SUS na unidade de saúde, sem uso de medicação além do ácido fólico e do sulfato ferroso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1232, 364, 7, '2025-01-13 14:30', 'consulta', 'Disseram na unidade que minha pressão subiu', 146, 94, 88, 82.5, 'Gestante de 29 anos, 31 semanas e 4 dias, encaminhada ao pré-natal de alto risco por PA de 148x96 em duas medidas, com 4 horas de intervalo. Edema discreto de pés e mãos, sem cefaleia, sem escotomas, sem dor epigástrica. Movimentação fetal presente. Ao exame: AFU 31 cm, BCF 144 bpm, sem edema facial. Fita urinária com proteinúria 1+. HD: pré-eclâmpsia sem sinais de gravidade, alto risco.', 'Iniciar metildopa 500 mg 8/8h. Solicitar hemograma, plaquetas, creatinina, TGO/TGP, LDH, ácido úrico e proteinúria de 24h. USG obstétrico com Doppler. Orientados sinais de alarme (cefaleia, escotomas, dor epigástrica) e PA domiciliar duas vezes ao dia. Retorno em 1 semana.'),
  (1233, 364, 6, '2025-01-27 02:40', 'pronto_socorro', 'Dor de cabeça forte, luzes na visão e dor na boca do estômago', 178, 114, 96, 86.0, 'Gestante de 33 semanas, chega com cefaleia intensa há 6 horas, escotomas cintilantes e dor epigástrica. PA 178x114, confirmada após 15 minutos (176x112). Reflexos patelares vivos 3+/4+, clônus ausente, edema 3+. BCF 138 bpm. Proteinúria 3+. Plaquetas 118.000, TGO 74 e TGP 66, creatinina 1,0, LDH 310. Proteinúria de 24h da semana anterior: 3,6 g. HD: pré-eclâmpsia grave com iminência de eclâmpsia.', 'Sulfato de magnésio EV (ataque 4 g, manutenção 1 g/h) com vigilância de reflexos e diurese. Hidralazina EV 5 mg para PAS 160 e depois nifedipino retard 20 mg 12/12h. Betametasona 12 mg IM para maturação pulmonar. Obstetrícia e UTI avisadas; indicação de resolução da gestação após estabilização.'),
  (1234, 364, 7, '2025-01-28 19:00', 'internacao', 'Puerpério de cesárea, sem dor de cabeça', 138, 88, 80, 83.4, 'Cesárea realizada após estabilização e segunda dose de corticoide, por pré-eclâmpsia grave com 33 semanas e 1 dia. RN feminino, 1.920 g, Apgar 8/9, encaminhada à UTI neonatal. PA no pós-parto 138x88 em uso de nifedipino. Sem convulsão, plaquetas 124.000, TGO/TGP em queda. Sulfato de magnésio mantido por 24h, diurese adequada de 80 mL/h. Lóquios normais, útero contraído. HD: pré-eclâmpsia grave, puerpério imediato estável.', 'Suspender sulfato após 24 horas. Trocar nifedipino por enalapril 10 mg 12/12h, compatível com amamentação. Monitorar PA a cada 6h e exames de função renal e hepática. Alta prevista em 3 dias. Retorno em 7 dias para aferição de PA.'),
  (1235, 364, 7, '2025-03-11 10:00', 'retorno', 'Consulta do pós-parto, amamentando', 124, 78, 74, 74.8, '6 semanas de puerpério, bebê saudável, recebeu alta da neonatologia com 2.400 g e está em aleitamento. PA domiciliar média de 120x76 com enalapril, sem tosse. Sem cefaleia. Exames: proteinúria de 24h 0,15 g, creatinina 0,8, plaquetas normais. Cicatriz cirúrgica sem alterações. HD: pré-eclâmpsia grave resolvida, risco cardiovascular aumentado a longo prazo.', 'Reduzir enalapril para 5 mg 12/12h e suspender se PA < 110/70, em 3 meses reavaliar. Contracepção com DIU, orientada sobre risco de recorrência e uso de AAS 100 mg a partir de 12 semanas em nova gestação. Acompanhamento anual de PA, glicemia e lipídios.');
