insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (364, '2025-03-11', 'melhorou', 'Pré-eclâmpsia grave tratada com sulfato de magnésio, hidralazina e nifedipino, com cesárea às 33 semanas sem eclâmpsia. Recém-nascida em bom estado, PA normalizada no puerpério com enalapril em desmame e proteinúria resolvida.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (365, 'Rodolfo Giacomini Schuch', 'M', '1974-02-10', 'Porto Alegre', 'RS', 'Advogado', 'Pressão elevada em consultas desde os 40 anos, mas nunca medicada. Corre 5 km três vezes por semana. Não fuma, bebe vinho nos fins de semana. Pai com HAS diagnosticada aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1236, 365, 2, '2023-06-12 17:30', 'consulta', 'Pressão alta no consultório, normal em casa', 152, 96, 84, 79.0, 'Paciente de 49 anos, assintomático, vem para segunda opinião após o clínico sugerir iniciar anti-hipertensivo por pressões de 150-158/94-98 em consultas. Em casa, mede 118-126 / 74-80 com aparelho validado. Ansioso em ambiente médico, relata "sentir o coração acelerar quando vejo o jaleco". Ao exame: IMC 24,5, RCR 2T BNF, sem sopros, pulsos normais. ECG normal. HD: suspeita de hipertensão do avental branco, a confirmar com MAPA.', 'Solicitar MAPA de 24h e ECO para avaliar lesão de órgão-alvo. Sem medicação por enquanto. Orientar manter exercícios e reduzir álcool. Retorno com os exames.'),
  (1237, 365, 2, '2023-07-10 17:40', 'retorno', 'Trouxe o exame da pressão de 24 horas', 148, 92, 78, 78.6, 'MAPA 24h com média de 122x76 mmHg (vigília 126x80, sono 108x64), descenso noturno preservado, sem cargas pressóricas elevadas. Consultório 148x92, caracterizando hipertensão do avental branco. ECO normal, sem HVE, função diastólica normal. Creatinina 0,9 e albuminúria negativa. Sem lesão de órgão-alvo. Ao exame: ansioso no início, PA mais baixa após repetição. HD: hipertensão do avental branco, risco cardiovascular baixo.', 'Não iniciar anti-hipertensivo. MEV: manter atividade física, reduzir sal e álcool. Reavaliar com MRPA a cada 6 meses e MAPA anual, pelo risco de progredir para HAS sustentada. Orientado a não confiar apenas em medidas de consultório.'),
  (1238, 365, 2, '2024-07-15 18:00', 'retorno', 'Controle anual', 142, 90, 74, 78.0, 'Seguiu MRPA a cada 6 meses com médias de 120-124 / 76-80, a última 123x78. Corre normalmente, sem sintomas. Menos vinho no fim de semana. Consultório 142x90, ainda acima do domiciliar. MAPA de controle: média 24h 124x77, vigília 128x81. Creatinina e albuminúria inalteradas. Ao exame: RCR 2T BNF, sem sopros. HD: hipertensão do avental branco estável, sem indicação de tratamento medicamentoso.', 'Manter acompanhamento sem fármacos. Repetir MAPA em 12 meses e MRPA semestral. Se média da MAPA passar de 130/80, rediscutir tratamento. Manter exercício e dieta.');
