insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (365, '2024-07-15', 'estavel', 'Hipertensão do avental branco confirmada em duas MAPAs (médias 24h de 122x76 e 124x77), sem lesão de órgão-alvo e sem medicação. Mantém MEV e MRPA semestral, com nova MAPA anual para detectar eventual progressão.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (366, 'Altair Zanin Sobrinho', 'M', '1954-04-17', 'Maringá', 'PR', 'Comerciante aposentado', 'HAS há 25 anos, DM2 há 18 anos, dislipidemia. Em uso de losartana 50 mg 12/12h, metformina 850 mg 2x/dia, sinvastatina 20 mg e AAS 100 mg. Ex-tabagista há 15 anos. Irmão com RM aos 60 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1239, 366, 6, '2024-10-12 05:30', 'pronto_socorro', 'Dor no peito há três dias, agora até em repouso', 158, 88, 84, 85.0, 'Pcte de 70 anos com angina aos pequenos esforços há 3 semanas, progressiva, e dor em repouso com 20 minutos de duração hoje às 3h. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, sem edemas. ECG com infra de ST de 1 mm em V4-V6 e T negativa, sem supra. Troponina ultrassensível 8 ng/L e 10 ng/L na repetição após 3h (valores limítrofes, abaixo do ponto de corte). HD: angina instável de alto risco (GRACE 138), sem elevação de troponina.', 'AAS 200 mg, clopidogrel 300 mg de ataque, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg e metoprolol. Nitroglicerina IV se dor recorrente. Internar na unidade coronariana para estratificação invasiva em 24-48h.'),
  (1240, 366, 12, '2024-10-22 07:00', 'internacao', 'Cirurgia de coração', 112, 64, 88, 84.0, 'Cateterismo no dia 14: lesão de tronco de coronária esquerda de 50%, DA proximal 90% e média 70%, Cx 80% e CD ocluída crônica com circulação colateral. SYNTAX 33, DM2 e FEVE 48%; Heart Team indicou RM. Hoje submetido a cirurgia com CEC, com enxerto de mamária esquerda para DA, safena para Cx e safena para CD, tempo de CEC 98 min. Saiu do centro cirúrgico extubado em 6h, sem inotrópicos importantes. Dreno com 180 mL em 12h.', 'UTI cirúrgica, AAS 100 mg contínuo nas primeiras 24h, estatina em dose alta, betabloqueador após estabilização hemodinâmica, controle glicêmico com insulina. Fisioterapia respiratória precoce, retirada de drenos em 48h. Alta da UTI estimada em 48h.'),
  (1241, 366, 1, '2025-01-20 15:30', 'retorno', 'Estou ótimo, sem dor, fazendo hidroginástica', 124, 74, 62, 82.7, '3 meses de pós-operatório de RM com três pontes. Ferida esternal cicatrizada, sem instabilidade. Sem angina, caminha 40 minutos e faz reabilitação 3 vezes por semana. Tosse seca e persistente desde a troca para enalapril na alta, que o incomoda à noite. LDL 52 mg/dL, HbA1c 7,2%. ECO com FEVE 55%. Ao exame: RCR 2T BNF, MV+ sem RA. HD: DAC multiarterial com RM bem-sucedida, tosse por IECA.', 'Suspender enalapril e retornar ao losartana 50 mg 12/12h. Manter AAS, atorvastatina 80 mg, metoprolol e metformina. Manter reabilitação. Retorno em 4 meses com perfil lipídico.');
