insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (366, '2025-01-20', 'melhorou', 'Angina instável com doença triarterial e lesão de tronco tratada com RM de três pontes. Assintomático em reabilitação aos 3 meses, LDL 52 mg/dL, FEVE 55% e PA 124x74 mmHg, com troca de enalapril por losartana devido à tosse.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (367, 'Valdeci Ferreira Quaresma', 'M', '1962-07-30', 'Goiânia', 'GO', 'Mecânico de automóveis', 'IAM de parede anterior em 2019 tratado com ATC de DA (stent), HAS e dislipidemia. Em uso de AAS, atorvastatina 40 mg, enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Ex-tabagista, bebe cerveja aos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1242, 367, 11, '2022-02-14 08:00', 'consulta', 'Canso para trabalhar debaixo do carro', 118, 74, 76, 88.6, 'Paciente de 59 anos com cardiomiopatia isquêmica pós-IAM, dispneia aos médios esforços (NYHA II-III) e edema discreto vespertino. Ao exame: B3 ausente, sopro mitral sistólico leve, MV+ sem RA, edema 1+/4+. ECO: FEVE 30% (Simpson), acinesia anterior e apical, regurgitação mitral funcional leve. NT-proBNP 2.100 pg/mL. Creatinina 1,2, potássio 4,5. Em uso de apenas dois dos quatro pilares de tratamento. HD: ICFEr isquêmica, subtratada.', 'Suspender enalapril, aguardar 36 horas e iniciar sacubitril/valsartana 24/26 mg 12/12h. Adicionar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol e furosemida. Orientado a pesar-se diariamente. Potássio e creatinina em 7 dias. Retorno em 30 dias.'),
  (1243, 367, 11, '2022-04-04 08:20', 'retorno', 'Estou tonto quando levanto e o potássio veio alto', 98, 62, 64, 84.9, 'Perdeu 3,7 kg e o edema desapareceu. Queixa tontura postural nas primeiras horas após os remédios, sem síncope. Potássio 5,7 mEq/L e creatinina 1,5 (aumento esperado após os novos fármacos). Dieta: diz comer banana e usar sal light diariamente. PA 98x62. Ao exame: sem estase jugular, pulmões limpos. HD: ICFEr em melhora com hipotensão leve e hipercalemia por SRAA e espironolactona.', 'Suspender sal light e reduzir alimentos ricos em potássio. Reduzir espironolactona para 12,5 mg (meio comprimido) e furosemida para 20 mg. Manter sacubitril/valsartana. Repetir potássio e creatinina em 5 dias. Retorno em 30 dias.'),
  (1244, 367, 11, '2022-09-19 08:30', 'retorno', 'Voltei a trabalhar o dia inteiro', 110, 68, 60, 85.2, 'Potássio normalizou (4,8) e se mantém assim. Sem dispneia aos esforços habituais, NYHA I-II. Peso seco 85 kg. Tolera carvedilol 12,5 mg 12/12h, sem fadiga excessiva. Ao exame: pulmões limpos, edema ausente. ECO de controle: FEVE 38%, redução do diâmetro diastólico de 68 para 63 mm. NT-proBNP 640 pg/mL. HD: ICFEr isquêmica com remodelamento reverso parcial em quatro pilares.', 'Manter sacubitril/valsartana, carvedilol 12,5 mg 12/12h, espironolactona 12,5 mg, dapagliflozina e furosemida 20 mg SN. Avaliar indicação de CDI se FEVE persistir ≤ 35% após 3 meses. Retorno em 4 meses.');
