insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (367, '2022-09-19', 'melhorou', 'ICFEr isquêmica otimizada com os quatro pilares após ajuste de hipercalemia, FEVE de 30% para 38% e NT-proBNP de 2.100 para 640 pg/mL. Classe funcional I-II, de volta ao trabalho, com reavaliação de CDI se FEVE permanecer em 35% ou menos.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (368, 'Elza Benites Ortiz', 'F', '1956-05-23', 'Ponta Porã', 'MS', 'Costureira aposentada', 'HAS há 15 anos e hipotireoidismo tratado. Em uso de losartana 50 mg 12/12h e levotiroxina 75 mcg. Sedentária, cuida de dois netos. Nunca fumou.', 'Penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1245, 368, 4, '2023-01-23 10:00', 'consulta', 'Coração batendo desordenado há semanas, canso rápido', 136, 84, 124, 73.5, 'Paciente de 66 anos com palpitações irregulares e fadiga há 6 semanas, piora ao carregar o neto. ECG: fibrilação atrial com resposta ventricular média de 124. Ao exame: ritmo irregularmente irregular, sem sopros, pulmões limpos, sem edema. ECO: FEVE 52%, átrio esquerdo 44 mm (aumento leve), sem valvopatia. TSH 2,4. CHA2DS2-VASc 3 (idade 65-74, sexo feminino, HAS). HD: FA persistente sintomática, candidata a controle de ritmo.', 'Apixabana 5 mg 12/12h desde hoje e metoprolol succinato 50 mg. Programar cardioversão elétrica após 3 semanas de anticoagulação contínua. Orientada a não faltar nenhuma dose. Retorno em 6 semanas.'),
  (1246, 368, 4, '2023-03-06 09:00', 'internacao', 'Vim para a cardioversão', 130, 80, 88, 72.8, 'Internação em hospital-dia para cardioversão elétrica eletiva após 6 semanas de apixabana sem falhas. ETE sem trombo em apêndice atrial esquerdo, velocidade de esvaziamento 42 cm/s. Sob sedação com propofol, choque sincronizado bifásico de 150 J com reversão para ritmo sinusal na primeira tentativa. ECG pós: ritmo sinusal, FC 68, sem pausas. Sem complicações, alta em 4 horas.', 'Manter apixabana por no mínimo 4 semanas e a longo prazo pelo escore. Iniciar amiodarona 200 mg ao dia por 3 meses para manutenção do ritmo. Retorno em 6 meses com ECO e Holter. Alertar para retorno se palpitações.'),
  (1247, 368, 4, '2023-09-18 10:20', 'retorno', 'As palpitações voltaram', 140, 86, 112, 73.9, 'Manteve ritmo sinusal por 4 meses, depois recorrência de FA há 3 semanas, após suspender amiodarona. Palpitações e dispneia leve. Holter: FA persistente com resposta média de 108, sem pausas. TSH normal. Átrio esquerdo estável. Pergunta se existe algo definitivo. Ao exame: ritmo irregular, FC 112, sem sinais de IC. HD: recorrência de FA persistente após CVE, candidata a ablação por cateter.', 'Discutido risco-benefício: indicação de ablação por isolamento de veias pulmonares, com a paciente concordando. Manter apixabana ininterrupta e metoprolol 100 mg. Exames pré-ablação (angiotomografia de átrio esquerdo). Cirurgia no mês seguinte.'),
  (1248, 368, 4, '2024-03-04 10:00', 'retorno', 'Sem palpitações desde a ablação', 126, 76, 64, 71.0, 'Ablação por crioenergia com isolamento das quatro veias pulmonares em outubro de 2023, sem complicações. Holter de 7 dias, 4 meses depois, mostra ritmo sinusal em 100% do período, sem episódios de FA. Sem palpitações, nem dispneia. Hematoma no sítio de punção resolvido. Ao exame: ritmo regular, FC 64, sem sopros. HD: FA persistente tratada com ablação, sem recorrência na janela de 4 meses.', 'Manter apixabana por tempo indeterminado (CHA2DS2-VASc 3) e metoprolol 50 mg. Reduzir metoprolol para 50 mg dada FC de 64. Holter de 24h aos 12 meses. Retorno em 6 meses.');
