insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (368, '2024-03-04', 'controlado', 'FA persistente com recorrência após cardioversão, tratada com ablação por crioenergia. Mantém ritmo sinusal em 100% no Holter de 7 dias aos 4 meses, sem sintomas, e continua apixabana por tempo indeterminado com seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (369, 'Gumercindo Hoffmann Leal', 'M', '1943-12-03', 'Londrina', 'PR', 'Agricultor aposentado', 'HAS há 30 anos e dislipidemia. Em uso de anlodipino 5 mg, losartana 50 mg e sinvastatina. Ex-tabagista (parou aos 55 anos). Viúvo, mora com a filha, que o acompanha nas consultas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1249, 369, 2, '2023-08-21 09:00', 'consulta', 'Falta ar, aperto no peito e quase desmaiei na roça', 112, 68, 72, 70.4, 'Paciente de 79 anos com dispneia progressiva, angina e um episódio de pré-síncope aos esforços nos últimos 4 meses. Ao exame: pulsos parvus et tardus, sopro sistólico ejetivo rude 4+/6+ em foco aórtico com irradiação para carótidas, B2 hipofonética, pulmões limpos. ECO: valva aórtica calcificada, área valvar 0,7 cm², gradiente médio 52 mmHg, velocidade máxima 4,6 m/s, FEVE 55%, HVE moderada. HD: estenose aórtica grave sintomática (tríade clássica).', 'Suspender anlodipino pela PA 112x68 e evitar vasodilatadores. Solicitar cateterismo coronariano e angiotomografia de aorta e vias de acesso para avaliar TAVI. Avaliação do Heart Team. Orientado a evitar esforços e retornar ao PS se síncope.'),
  (1250, 369, 1, '2023-09-25 09:30', 'retorno', 'Vim com os exames para saber se opera', 118, 70, 68, 69.8, 'Cateterismo: coronárias sem lesões obstrutivas significativas. Angiotomografia: anel aórtico de 24 mm, cálcio da valva 3.100 UA, acesso femoral bilateral adequado (diâmetros mínimos 7,0 mm). Risco cirúrgico STS 8,2%, fragilidade moderada (marcha lenta). Heart Team indicou TAVI transfemoral em vez de troca valvar cirúrgica. Paciente e filha concordam. Ao exame: mesmos achados, sem sinais de IC.', 'Agendar TAVI na hemodinâmica estrutural com prótese autoexpansível. Avaliação odontológica e rastreio de infecção antes do procedimento. Manter losartana, atorvastatina e AAS 100 mg. Internação 24 horas antes.'),
  (1251, 369, 10, '2023-11-14 07:30', 'internacao', 'Internação para TAVI', 124, 72, 70, 70.0, 'TAVI transfemoral direita sob sedação, com implante de prótese autoexpansível 26 mm, pré-dilatação com balão e boa expansão. Gradiente residual médio 8 mmHg, sem regurgitação paravalvar relevante. Surgiu bloqueio de ramo esquerdo novo, sem BAV de alto grau, monitorado por 48h. Sem complicações vasculares. Alta no 3º dia, caminhando sem dispneia.', 'Manter AAS 100 mg. ECG seriado e Holter em 30 dias pelo BRE novo. Orientar profilaxia de endocardite antes de procedimentos dentários. Retorno em 2 meses com ECO. Fisioterapia leve em casa.'),
  (1252, 369, 2, '2024-01-15 09:30', 'retorno', 'Estou subindo a ladeira de novo', 130, 76, 66, 72.5, '2 meses após TAVI, sem dispneia, sem angina, voltou a cuidar da horta. Ganhou 2,5 kg. Holter: ritmo sinusal, BRE persistente, sem BAV de alto grau, sem pausas. ECO: gradiente médio 9 mmHg, sem refluxo, FEVE 58%. Ao exame: sopro ejetivo leve 1+/6+, pulsos normais, sem edemas. PA 130x76. HD: pós-TAVI com excelente resultado hemodinâmico, HAS controlada.', 'Manter AAS, losartana e atorvastatina. ECO de controle anual e consulta semestral. Reforçar profilaxia de endocardite. Alta da fisioterapia.');
