insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (369, '2024-01-15', 'melhorou', 'Estenose aórtica grave sintomática tratada com TAVI transfemoral, gradiente caindo de 52 para 9 mmHg e FEVE de 58%. Assintomático e ativo aos 80 anos, com BRE novo sem bloqueio de alto grau, mantido em seguimento semestral e ECO anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (370, 'Alícia Moura Tabosa', 'F', '1991-02-14', 'Fortaleza', 'CE', 'Enfermeira', 'Palpitações súbitas esporádicas desde a adolescência, nunca investigadas. Tabagismo ausente. Uso de energético em plantões noturnos. Sem comorbidades.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1253, 370, 6, '2022-06-05 03:50', 'pronto_socorro', 'Coração disparou do nada durante o plantão', 104, 66, 188, 58.0, 'Pcte de 31 anos, enfermeira, com palpitação de início súbito há 40 min, taquicárdica, com leve tontura e dor torácica discreta, sem síncope. Ao exame: ansiosa, PA 104x66, FC 188 regular, pulmões limpos. ECG: taquicardia de QRS estreito regular a 188 bpm sem ondas P visíveis. Sem resposta a manobra de Valsalva modificada. HD: taquicardia supraventricular paroxística, provável reentrada nodal.', 'Adenosina 6 mg EV rápida em acesso antecubital, sem reversão; segunda dose de 12 mg com reversão para ritmo sinusal FC 76. ECG pós-reversão sem pré-excitação. Observação por 4 horas. Orientado a evitar energéticos e agendar com arritmologia.'),
  (1254, 370, 4, '2022-07-18 14:00', 'consulta', 'Quero resolver, tenho medo de acontecer de novo', 110, 68, 72, 58.4, 'Teve mais 2 episódios curtos após o PS, um deles interrompido com manobra vagal. Descreve início e término abruptos, com pescoço pulsando. Ao exame normal. ECO normal, FEVE 64%, sem cardiopatia estrutural. Holter com um episódio de TSV de 12 batimentos a 172 bpm e ECG basal sem pré-excitação. TSH normal. HD: TSV por reentrada nodal (AVNRT), sintomática e recorrente.', 'Discutidas opções: betabloqueador ou ablação por cateter, com taxa de cura de 95%. Paciente escolheu ablação. Iniciar propranolol 40 mg 12/12h até o procedimento. Agendar estudo eletrofisiológico em hospital de referência. Orientar suspensão de energéticos.'),
  (1255, 370, 4, '2022-09-12 08:00', 'internacao', 'Ablação por cateter', 112, 70, 68, 58.6, 'Estudo eletrofisiológico sob sedação: reentrada nodal típica (AVNRT slow-fast) induzida com extraestímulo atrial, ciclo de 320 ms. Ablação por radiofrequência da via lenta com ritmo juncional e perda da indução após a aplicação. Sem BAV, sem complicações. Teste com isoproterenol sem reindução. Alta no mesmo dia, com curativo inguinal limpo.', 'Suspender propranolol. Repouso de 48 horas, sem esforço por 1 semana. Orientada sobre sinais de sangramento na virilha. Retorno em 4 meses com ECG. Pode voltar a plantões em 7 dias.'),
  (1256, 370, 4, '2023-01-16 14:30', 'retorno', 'Zero episódios desde a ablação', 108, 66, 70, 59.2, 'Quatro meses após ablação, sem palpitações, sem uso de medicação. Voltou aos plantões noturnos, sem energéticos. ECG: ritmo sinusal normal, PR 150 ms, sem pré-excitação. Ao exame: RCR 2T BNF, sem sopros, sem sinais de hematoma ou fístula no sítio de punção femoral. Pressão arterial e frequência cardíaca normais em repouso. HD: AVNRT tratada com ablação, sem recorrência.', 'Alta do ambulatório de arritmia. Retornar se novas palpitações com sintomas. Orientações para tentar manobras vagais caso recorra. Não é necessário medicamento de manutenção.');
