insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (371, '2023-11-20', 'controlado', 'Perda de 17 kg em 20 meses permitiu reduzir de dois anti-hipertensivos em dose plena para losartana 25 mg, com MRPA média de 116x72 mmHg. Pré-diabetes revertido e acompanhamento para possível suspensão do medicamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (372, 'Dalvino Arruda Cuellar', 'M', '1957-10-02', 'Corumbá', 'MS', 'Pescador aposentado', 'HAS há 15 anos, tratada com losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg, mas PA sempre alta no consultório. Tabagista passivo. Morou 30 anos em barco, longe de postos de saúde.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1260, 372, 2, '2023-05-08 09:00', 'consulta', 'Dizem que minha pressão é resistente, mas me sinto bem', 164, 96, 82, 78.0, 'Paciente de 65 anos com hipertensão aparentemente resistente (consultório 160-168/94-98 em três drogas). Assintomático, adesão boa. Sente-se muito tenso nas consultas, "o coração dispara". PA domiciliar em aparelho do posto: 120-128 / 72-78. Aferição com manguito adequado e três medidas: 164x96, 160x94, 162x96. Ao exame: IMC 27, RCR 2T BNF, sem sopros, fundo de olho normal, creatinina 1,0, potássio 4,2. HD: suspeita de pseudorresistência por efeito do avental branco.', 'Solicitar MAPA de 24h antes de qualquer aumento de medicação. Manter os três fármacos. Ensinado a registrar PA em casa. Retorno em 15 dias com a MAPA.'),
  (1261, 372, 2, '2023-05-23 09:20', 'retorno', 'Trouxe o exame das 24 horas', 160, 94, 80, 77.8, 'MAPA 24h: média geral 118x72 mmHg, vigília 122x76 e sono 106x62, com 2% das medidas acima da meta. No consultório continua 160x94. Em casa, 8 medidas da última semana: média 122x75. Confirmada pseudorresistência por hipertensão do avental branco em paciente tratado. Sem tontura ou sintomas de hipotensão relatados. ECO sem HVE, FEVE 62%. HD: hipertensão controlada fora do consultório, efeito do avental branco.', 'Sem necessidade de aumentar a medicação. Dada a PA da MAPA já na meta, reduzir clortalidona (suspender) e manter losartana 100 mg e anlodipino 10 mg. Repetir MRPA em 4 semanas para confirmar. Orientado a não mudar sozinho. Retorno em 2 meses.'),
  (1262, 372, 2, '2023-07-24 09:10', 'retorno', 'Passei as semanas medindo em casa', 156, 92, 76, 78.4, 'MRPA com média de 124x76 mmHg após a retirada da clortalidona, sem valores acima de 138/88. No consultório 156x92 mas relaxa em medidas repetidas. Sem cãibras, sem tontura, sem edema significativo de tornozelo. Sódio 139, potássio 4,4. Ao exame: RCR 2T BNF. HD: pseudorresistência por avental branco, controlado com 2 fármacos.', 'Manter losartana 100 mg e anlodipino 10 mg. Orientar MRPA mensal como principal referência de controle. Nova MAPA em 12 meses. Alta para a unidade básica com carta de referência explicando o diagnóstico.');
