insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (372, '2023-07-24', 'controlado', 'Pseudorresistência por avental branco descoberta na MAPA (média 118x72 mmHg) em paciente tratado com três fármacos. Clortalidona suspensa, MRPA média de 124x76 com losartana e anlodipino, e alta para a unidade básica com orientação de usar medidas domiciliares.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (373, 'Jurandir Cajazeira Bastos', 'M', '1972-12-19', 'Salvador', 'BA', 'Motorista de ônibus', 'Glomerulonefrite por IgA diagnosticada aos 38 anos, com seguimento irregular. HAS há 10 anos. Uso de enalapril 10 mg 12/12h e anti-inflamatórios sem receita para dor lombar.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1263, 373, 8, '2024-02-05 10:00', 'consulta', 'Pressão sempre alta, mesmo com remédio', 176, 108, 80, 85.3, 'Paciente de 51 anos, DRC secundária a glomerulonefrite por IgA, com HAS de difícil controle, cefaleia ocasional e edema vespertino de tornozelos. Usa diclofenaco 2-3 vezes por semana para dor lombar. Ao exame: pálido, edema 1+/4+, pulmões limpos, sem sopros. Creatinina 2,4 mg/dL (TFGe 29), ureia 88, proteinúria 2,1 g/24h, hemoglobina 10,2 g/dL, potássio 5,0, bicarbonato 19. USG: rins reduzidos, 9,2 cm bilateral. HD: HAS secundária a doença renal crônica estágio 4 (G4 A3), congestão e anti-inflamatório contribuindo.', 'Suspender diclofenaco definitivamente. Iniciar furosemida 40 mg 2 vezes ao dia, anlodipino 5 mg e bicarbonato de sódio. Manter enalapril 10 mg 12/12h com controle de potássio em 7 dias. Dieta com 2 g de sódio e baixa em potássio. Encaminhar para cardiologia para avaliação de risco.'),
  (1264, 373, 1, '2024-03-18 10:40', 'retorno', 'Vim para avaliar o coração', 148, 92, 76, 82.6, 'Referenciado pela nefrologia. Perdeu 2,7 kg de líquido, edema desaparecido. Evita anti-inflamatórios. PA domiciliar média 146x90. ECO: HVE concêntrica moderada, FEVE 58%, disfunção diastólica grau I. ECG com SVE. Potássio 4,8 e creatinina 2,5 estável. Ao exame: RCR 2T BNF, B4. HD: cardiopatia hipertensiva com HVE em DRC estágio 4, PA ainda acima da meta.', 'Aumentar anlodipino para 10 mg. Considerar clortalidona se a TFGe permitir, a combinar com a nefrologia. Mantidos enalapril e furosemida. Controle trimestral de creatinina e potássio. Retorno em 2 meses.'),
  (1265, 373, 8, '2024-09-09 10:00', 'retorno', 'Cansaço e enjoo, sem vontade de comer', 154, 94, 84, 79.8, 'Seis meses depois, queixa de astenia, náuseas e anorexia, com hemoglobina 8,9 g/dL. Creatinina 3,3 mg/dL (TFGe 21), ureia 128, potássio 5,6, fósforo 6,0, PTH elevado. Proteinúria 3,4 g/24h. Admite ter voltado a tomar diclofenaco em duas ocasiões. PA 154x94 mesmo com três fármacos. Ao exame: pálido, sem edema, sem atrito pericárdico. HD: DRC estágio 4 com progressão para G5 próxima, anemia e hipercalemia.', 'Reduzir enalapril para 5 mg 12/12h e iniciar resina de troca de potássio. Alfaepoetina por anemia e quelante de fósforo. Orientação sobre terapia renal substitutiva e criação de fístula arteriovenosa, com encaminhamento à cirurgia vascular. Proibido anti-inflamatório. Retorno em 4 semanas.');
