insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (373, '2024-09-09', 'piorou', 'Progressão da doença renal por IgA para estágio 4 avançado (TFGe 21), com proteinúria de 3,4 g, hipercalemia, anemia e pressão acima da meta. Reincidência no uso de anti-inflamatórios contribuiu; encaminhado para preparo de fístula e terapia renal substitutiva.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (374, 'Neide Kowalczuk Pereira', 'F', '1964-06-11', 'Toledo', 'PR', 'Agricultora', 'HAS há 14 anos. Interrompeu a losartana há 6 meses porque "achou que viciava". Tabagista de 25 maços-ano. Obesa. Pai e irmão com infarto precoce.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1266, 374, 6, '2025-03-23 03:40', 'pronto_socorro', 'Dor forte no peito e dor de cabeça, a pressão está lá em cima', 218, 118, 102, 91.0, 'Pcte de 60 anos, hipertensa sem tratamento, com dor retroesternal em aperto há 2h, irradiada para mandíbula, sudorese e dispneia. PA 218x118 em ambos os braços. Ao exame: ansiosa, RCR 2T BNF, B4, estertores em bases, SpO2 93%. ECG: infradesnivelamento de ST de 2 mm em V3-V6 e T negativa. Troponina ultrassensível 380 ng/L (referência < 14). Rx com leve congestão. HD: SCA sem supra de ST (IAMSSST), crise hipertensiva com lesão de órgão-alvo cardíaca.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg. Nitroglicerina IV com redução da PA em 25% na 1ª hora, depois alvo 160/100 nas primeiras horas. Metoprolol venoso após controle da congestão, furosemida 40 mg EV. Estatina em alta dose. Internar na UTI coronariana para cateterismo precoce.'),
  (1267, 374, 10, '2025-03-24 11:30', 'internacao', 'Sem dor após o remédio na veia', 148, 84, 74, 90.6, 'PA reduzida de forma gradual para 148x84 nas primeiras 18 horas, assintomática. Troponina com pico de 1.650 ng/L. Cateterismo radial: DA média com lesão de 90% (culpada) e CD com 60% não crítica; FEVE 48% com hipocinesia anterior. Realizada ATC com stent farmacológico em DA com ótimo resultado. Iniciados bisoprolol 2,5 mg, losartana 50 mg e atorvastatina 80 mg. Sem complicações. Creatinina estável.', 'Dupla antiagregação por 12 meses. Alta em 3 dias com orientações sobre uso contínuo das medicações, conversa explicando que o anti-hipertensivo não vicia e reforço do tabagismo. Encaminhar para reabilitação. Retorno em 30 dias.'),
  (1268, 374, 1, '2025-04-28 08:40', 'retorno', 'Tomando tudo certinho', 126, 78, 62, 88.4, 'Cinco semanas após o infarto, sem dor torácica nem falta de ar, tolerando os remédios, só queixa leve dispneia atribuída ao ticagrelor. Parou de fumar na internação, usa adesivo. Entendeu que perde risco ao manter o tratamento. PA domiciliar média de 124x76. LDL 61 mg/dL. Ao exame: RCR 2T BNF, MV+ sem RA, punção radial normal. HD: IAMSSST tratado com stent, HAS agora controlada.', 'Manter todas as medicações. Iniciar reabilitação cardiovascular. ECO de controle em 3 meses para reavaliar a FEVE. Reforçar ausência de tabagismo. Retorno em 3 meses.');
