insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (374, '2025-04-28', 'melhorou', 'Crise hipertensiva com IAMSSST em hipertensa sem tratamento, resolvida com redução gradual da PA, angioplastia com stent em DA e início de terapia completa. Cinco semanas depois está assintomática, sem fumar e com PA 126x78 mmHg, em reabilitação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (375, 'Edvaldo Terena Marques', 'M', '1966-08-24', 'Naviraí', 'MS', 'Vigilante noturno', 'Pressão "normal" em todas as consultas, mas pai faleceu de AVC aos 58 anos. Trabalha em turno noturno, dorme de dia, toma 6 a 8 cafés por noite. Fumante de 15 cigarros por dia. Sem medicação.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1269, 375, 1, '2023-04-10 08:30', 'consulta', 'Dor de cabeça ao acordar e o ECG deu alterado no exame admissional', 128, 82, 74, 86.4, 'Paciente de 56 anos com cefaleia matinal ocasional e ECG de trabalho com sinais de sobrecarga de VE. PA de consultório sempre 120-130 / 78-84. Ao exame: IMC 29, RCR 2T BNF, B4, sem sopros. ECG: SVE por Sokolow-Lyon 41 mm com alteração de repolarização. Trouxe medida da farmácia: 150x94 à noite. HD: suspeita de hipertensão mascarada com lesão de órgão-alvo (HVE).', 'Solicitar MAPA de 24h incluindo período de trabalho noturno, ECO e microalbuminúria. Orientado a cortar o excesso de cafeína e o cigarro. Sem medicação até os resultados. Retorno em 2 semanas.'),
  (1270, 375, 1, '2023-04-25 08:40', 'retorno', 'Trouxe os exames', 130, 84, 76, 86.0, 'MAPA 24h: média geral 142x90, vigília 148x92 (turno da noite) e sono diurno 124x78, descenso preservado, caracterizando hipertensão mascarada. ECO: HVE concêntrica (septo 13 mm, massa indexada 124 g/m²), FEVE 62%, disfunção diastólica grau I. Albumina/creatinina 22 mg/g. Creatinina 1,0, potássio 4,3. Ao exame, PA de consultório 130x84. HD: hipertensão mascarada com HVE (cardiopatia hipertensiva).', 'Iniciar losartana 50 mg à noite, antes do turno, e anlodipino 5 mg. Mostrado o laudo e explicado porque medir fora do consultório é crucial. MRPA no horário de trabalho. Retorno em 6 semanas.'),
  (1271, 375, 1, '2023-06-12 08:30', 'retorno', 'Dormindo melhor e sem dor de cabeça', 118, 76, 68, 85.2, 'Sem cefaleia, tomando os dois medicamentos às 18h, antes de sair para o plantão. Reduziu cafés para 2 por noite e fuma 5 cigarros por dia. MRPA no turno de trabalho com média 126x78. Sem edemas, sem tontura. Ao exame: RCR 2T BNF, PA consultório 118x76. HD: hipertensão mascarada controlada, HVE em tratamento.', 'Manter losartana 50 mg e anlodipino 5 mg à tarde. Insistir na cessação do tabagismo, oferecido bupropiona na próxima consulta. ECO de controle em 12 meses para avaliar regressão da HVE. Retorno em 4 meses.');
