insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (375, '2023-06-12', 'controlado', 'Hipertensão mascarada com HVE identificada pela MAPA em turno noturno, controlada com losartana e anlodipino à tarde (MRPA média 126x78 mmHg). Reduziu cafeína e cigarros, segue em acompanhamento com ECO anual para regressão da hipertrofia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (376, 'Iracema Fujimoto Salles', 'F', '1952-01-07', 'Santos', 'SP', 'Professora de piano aposentada', 'IAM tratado com stent em DA em 2016. HAS, dislipidemia e artrose de coluna. Uso de AAS, atorvastatina 40 mg (parou por mialgia), metoprolol e losartana. Caminha na orla duas vezes por semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1272, 376, 1, '2025-02-17 14:00', 'consulta', 'Estou há dois anos sem tomar a estatina, por causa das dores', 134, 78, 58, 64.0, 'Paciente de 73 anos, DAC estável pós-ATC de DA em 2016, assintomática. Suspendeu atorvastatina por mialgia difusa há 2 anos. LDL 142 mg/dL, CK normal. Faz caminhada de 40 minutos sem angina. FC 58 em uso de metoprolol 50 mg, sem tontura. Ao exame: RCR 2T BNF, sem sopros, MV+ sem RA. ECG: ritmo sinusal, bradicardia leve, sem alterações isquêmicas. HD: DAC crônica com LDL muito acima da meta (< 50), intolerância à atorvastatina.', 'Reiniciar com rosuvastatina 5 mg em dias alternados e subir gradualmente; associar ezetimiba 10 mg. Manter AAS, metoprolol e losartana. Repetir LDL e CK em 8 semanas. Orientar a avisar se mialgia. Retorno em 3 meses.'),
  (1273, 376, 1, '2025-05-05 14:20', 'retorno', 'Tomei tudo direitinho, sem dor', 126, 74, 60, 64.3, 'Boa tolerância à rosuvastatina em dias alternados e ezetimiba, sem mialgia. LDL caiu de 142 para 78 mg/dL em 8 semanas e agora 70. CK normal. Sem angina, sem dispneia. Entrou na reabilitação em academia da terceira idade. Ao exame: RCR 2T BNF, pulmões limpos, sem edemas. HD: DAC estável, LDL em queda, ainda acima da meta.', 'Passar rosuvastatina para 5 mg todos os dias. Manter ezetimiba. Repetir LDL em 3 meses. Se > 55, discutir inibidor de PCSK9. Manter os demais medicamentos. Retorno em 4 meses.'),
  (1274, 376, 1, '2025-09-01 14:10', 'retorno', 'Quero saber meus números do colesterol', 128, 76, 62, 63.8, 'LDL 56 mg/dL com rosuvastatina 5 mg diária e ezetimiba, sem sintomas musculares. Sem angina, mantém atividade física. Pergunta sobre injetável. ECO anterior com FEVE 58% sem alterações. Ao exame: RCR 2T BNF, sem edemas, pulsos normais. HD: DAC estável com LDL próximo à meta, intolerância parcial a estatinas controlada.', 'Aumentar rosuvastatina para 10 mg ao dia, com acompanhamento de sintomas musculares, antes de considerar PCSK9. Manter os demais. LDL e CK em 3 meses. Retorno em 6 meses.');
