insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (376, '2025-09-01', 'estavel', 'DAC crônica estável, sem angina, com LDL reduzido de 142 para 56 mg/dL após reintrodução gradual de rosuvastatina e ezetimiba. Segue em acompanhamento semestral, com ajuste progressivo da estatina conforme tolerância muscular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (377, 'Wellington Cândido Pavão', 'M', '1969-04-05', 'Nova Andradina', 'MS', 'Peão de fazenda', 'Tabagista de 30 maços-ano, HAS e dislipidemia sem tratamento. Etilista social. Mora em fazenda a 90 km da cidade, pouco acesso a transporte.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1275, 377, 6, '2021-11-06 21:40', 'pronto_socorro', 'Dor no peito há dois dias, piorando no esforço', 162, 98, 92, 82.0, 'Pcte de 52 anos, dor precordial em aperto há 2 dias, de repouso hoje à tarde com duração de 40 minutos, associada a sudorese. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, sem edemas. ECG: infra de ST de 1,5 mm em V4-V6 e T negativa em DI, aVL. Troponina ultrassensível 640 ng/L (referência < 14). HD: IAMSSST, GRACE 112, alto risco por elevação de troponina.', 'AAS 300 mg, clopidogrel 300 mg, enoxaparina 1 mg/kg, atorvastatina 80 mg, metoprolol. Internar na UTI coronariana para cateterismo nas próximas 24h. Orientado jejum.'),
  (1276, 377, 10, '2021-11-07 14:00', 'internacao', 'Cateterismo', 138, 82, 70, 81.8, 'Cateterismo radial direito: lesão de 95% em DA média, culpada, CD com 50% e Cx sem lesões. Realizada ATC com stent farmacológico 3,0x22 mm em DA com fluxo TIMI 3. FEVE 55%. Sem intercorrências, assintomático. Iniciados metoprolol, losartana e atorvastatina. Entendeu a importância da dupla antiagregação por 12 meses, mas relata que a fazenda fica longe e a farmácia da cidade nem sempre tem o clopidogrel.', 'Alta com AAS, clopidogrel por 12 meses, atorvastatina 80 mg, metoprolol e losartana. Entregue receita para retirada gratuita e explicado que nunca pode suspender o clopidogrel sem avisar. Retorno em 6 semanas. Cessação do tabagismo orientada.'),
  (1277, 377, 1, '2022-01-17 10:00', 'retorno', 'Tô bem, voltei a trabalhar com o gado', 136, 84, 66, 80.5, 'Dez semanas após o IAM, sem dor torácica, voltou a trabalhar a cavalo e a lidar com o gado. Reduziu o cigarro, mas ainda fuma 8 por dia. Falta de farmácia: tomou clopidogrel de forma irregular nas últimas 3 semanas. Perdeu 2 dos 6 comprimidos de cada cartela. PA domiciliar não medida. Ao exame: RCR 2T BNF, punção radial normal. LDL 94 mg/dL. HD: IAMSSST pós-ATC, adesão frágil ao clopidogrel.', 'Reforçada gravidade da suspensão precoce da dupla antiagregação. Entregues 3 cartelas de clopidogrel e carta para a unidade básica de Nova Andradina. Atorvastatina mantida e solicitado ezetimiba. Retorno em 3 meses para reavaliação e encaminhamento à reabilitação local.');
