insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (378, '2024-08-14', 'obito', 'Óbito em 14/08/2024 por choque cardiogênico secundário a ICFEr isquêmica terminal (FEVE 22%) com insuficiência renal avançada, após duas internações em 3 meses. Falecida na UTI com a filha ao lado, em cuidados de conforto conforme a vontade expressa.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (379, 'Tarcísio Álvares Peçanha', 'M', '1951-11-15', 'Belo Horizonte', 'MG', 'Contador aposentado', 'HAS há 20 anos com losartana e hidroclorotiazida, DM2 recente. Sedentário, ex-tabagista. Refere "coração irregular" em consultas anteriores, nunca investigado. Sem anticoagulante.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1282, 379, 6, '2023-04-10 07:15', 'pronto_socorro', 'Acordei sem força no braço direito e não consigo falar direito', 178, 98, 118, 82.0, 'Pcte de 71 anos, esposa relata último momento normal às 05:30 e déficit ao acordar às 06:40, com afasia de expressão e hemiparesia direita. NIHSS 12. Ao exame: pulso irregular, FC 118, PA 178x98, glicemia capilar 156. ECG: fibrilação atrial de resposta rápida. TC de crânio sem hemorragia, ASPECTS 9. Angiotomografia: oclusão de M1 esquerda. Dentro da janela de 4,5h do último momento normal. HD: AVC isquêmico cardioembólico por FA, oclusão de M1 esquerda.', 'Redução da PA para < 185/110 antes da trombólise. Alteplase 0,9 mg/kg iniciada em 55 min da chegada, seguida de trombectomia mecânica com recanalização TICI 2b. Neurologia e UTI neurológica. Monitorização contínua da FA, ECO e controle neurológico a cada hora.'),
  (1283, 379, 13, '2023-04-12 09:00', 'internacao', 'Dia 2 da internação neurológica', 144, 84, 82, 81.4, 'Pós-trombectomia, sem transformação hemorrágica na TC de 24h. NIHSS caiu para 6, com disartria e paresia braquiofacial direita leve a moderada. FC controlada com metoprolol, sem recorrência da FA de alta resposta. ECO: átrio esquerdo 51 mm, FEVE 50%, sem trombo. Hemoglobina glicada 7,6%. Iniciada deglutição assistida com fonoaudiologia. HD: AVC isquêmico de M1 esquerda tratado, FA recém-diagnosticada.', 'AAS 100 mg por 14 dias, depois trocar por anticoagulante oral quando TC confirmar ausência de hemorragia (regra 1-3-6-12 por gravidade moderada). Reabilitação motora e fonoaudiologia intensivas. Metoprolol 50 mg e rastreio de apneia. Alta prevista em 5 dias para reabilitação.'),
  (1284, 379, 13, '2023-06-12 10:00', 'retorno', 'Ainda arrasto a perna e a fala está enrolada', 134, 80, 72, 80.2, 'Dois meses do AVC, em reabilitação 5 vezes por semana. Disartria leve, paresia braquiofacial direita grau 4, marcha com leve cera. Tomando apixabana 5 mg 12/12h desde o dia 15, sem sangramentos. Humor deprimido, chora com facilidade, esposa preocupada. Ao exame: NIHSS 3, escala de Rankin modificada 2. PA 134x80. HD: sequela leve de AVC cardioembólico, depressão pós-AVC.', 'Manter apixabana e metoprolol, associar sertralina 50 mg. Continuar fisioterapia, fonoaudiologia e terapia ocupacional. Encaminhar à psicologia. Retorno ao cardiologista para avaliar ritmo. Retorno em 3 meses.'),
  (1285, 379, 4, '2023-12-04 10:30', 'retorno', 'Quero saber se dá para tirar a fibrilação', 130, 78, 76, 79.0, 'Oito meses do AVC. Persiste disartria discreta e redução de destreza fina da mão direita, Rankin 2, não consegue mais escrever com a mão dominante. Humor melhor com sertralina. Holter: FA permanente, FC média 74, sem pausas. Adesão total à apixabana. Sem sangramentos. Ao exame: ritmo irregular, FC 76, sem sinais de IC. HD: FA permanente, sequela de AVC, controle de frequência adequado.', 'Optado por controle de frequência. Manter apixabana, metoprolol 50 mg, estatina e BRA. Orientações de prevenção secundária e mudanças de estilo de vida. Ablação não indicada pela duração e tamanho do átrio. Retorno em 6 meses.');
