insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (379, '2023-12-04', 'piorou', 'FA não diagnosticada e sem anticoagulação levou a AVC isquêmico de M1 esquerda, tratado com trombólise e trombectomia. Evolui com sequelas permanentes (disartria discreta e perda da destreza da mão direita, Rankin 2) e depressão pós-AVC, hoje anticoagulado com apixabana.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (380, 'Priscila Stadler Okamoto', 'F', '2000-09-03', 'Curitiba', 'PR', 'Estudante de arquitetura', 'Saudável, sem uso de medicações além de anticoncepcional oral. Praticava corrida de rua. Gripe com febre há 10 dias, tratada com sintomáticos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1286, 380, 6, '2024-07-22 20:30', 'pronto_socorro', 'Dor no peito que piora ao deitar e coração acelerado', 112, 68, 104, 56.0, 'Pcte de 23 anos, 10 dias após quadro gripal, com dor torácica pleurítica e opressiva há 2 dias, pior em decúbito e melhor sentada, sem síncope. Ao exame: taquicárdica, afebril, sem sopros, sem atrito pericárdico, pulmões limpos. ECG: supra côncavo difuso de ST de 1-2 mm em DI, DII, aVF e V2-V6, sem imagem em espelho. Troponina ultrassensível 1.840 ng/L. PCR 38 mg/L. ECO beira-leito com FEVE 45% e hipocinesia difusa. HD: miocardite aguda provável pós-viral.', 'Internação em unidade coronariana por monitorização de arritmias. Suspender anticoncepcional e esportes. Colchicina e AINE avaliados em conjunto com cardiologia (precaução pelo ECO alterado). Solicitar ressonância cardíaca e painel viral. Evitar exercício por 6 meses.'),
  (1287, 380, 11, '2024-07-24 09:00', 'internacao', 'Dia 3 de internação, menos dor', 106, 64, 84, 55.6, 'Dor torácica em franca melhora, troponina em queda para 420 ng/L. Telemetria sem TV ou BAV de alto grau, apenas extrassístoles ventriculares isoladas. Ressonância cardíaca: edema miocárdico e realce tardio subepicárdico em parede lateral, FEVE 48%, critérios de Lake Louise positivos. Painel viral com influenza A positivo. Cateterismo não necessário pelo perfil. HD: miocardite aguda associada à influenza, com disfunção sistólica leve e boa evolução.', 'Iniciar enalapril 2,5 mg 12/12h e bisoprolol 1,25 mg para proteção ventricular, cientes da contraindicação em gravidez e necessidade de contracepção sem estrogênio (DIU). Alta em 2 dias. Sem esportes por 6 meses. Retorno em 4 semanas.'),
  (1288, 380, 11, '2024-08-19 08:30', 'retorno', 'Sem dor, mas sinto falta de correr', 104, 62, 64, 56.5, 'Quatro semanas depois, assintomática, sem palpitações. Troponina normalizada, PCR < 3. Holter: ritmo sinusal, 140 extrassístoles ventriculares isoladas, sem TV. ECO: FEVE 56%. Tolera os medicamentos, só um pouco de tontura ao levantar. Adotou DIU de cobre. Ao exame: PA 104x62, RCR 2T BNF, sem sopros. HD: miocardite aguda em recuperação, FEVE normalizando.', 'Manter enalapril e bisoprolol por 6 meses, depois reavaliar com ressonância. Continuar sem exercício competitivo. Retorno em 5 meses com ressonância cardíaca de controle.'),
  (1289, 380, 11, '2025-01-13 08:30', 'retorno', 'Quero saber se posso voltar a correr', 110, 68, 62, 57.0, 'Seis meses do episódio, sem sintomas, treinou caminhadas moderadas. Ressonância de controle: FEVE 62%, resolução do edema, realce tardio residual mínimo e sutil em parede lateral. Holter sem arritmias complexas. Teste ergométrico completo a 13 METs sem arritmias ou alterações do ST. Ao exame normal. HD: miocardite aguda curada com recuperação funcional completa e cicatriz mínima.', 'Suspender enalapril e bisoprolol de forma gradual em 4 semanas. Liberação para retorno gradual da corrida em 8 semanas com reavaliação. Orientada a procurar o serviço se dor torácica ou palpitações. Alta ambulatorial e retorno anual.');
