insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (380, '2025-01-13', 'melhorou', 'Miocardite aguda associada à influenza A, com FEVE inicial de 45%, recuperada para 62% em 6 meses. Teste ergométrico normal, medicações suspensas e retorno gradual à corrida autorizado, com cicatriz mínima à ressonância e acompanhamento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (381, 'Cristiano Wrubel Ribas', 'M', '1963-01-25', 'Guarapuava', 'PR', 'Policial militar reformado', 'HAS há 9 anos. Parou o enalapril há 4 meses por tosse seca e o atenolol há 1 ano porque "tirou o desempenho". Usa só hidroclorotiazida quando lembra. Fumante de 10 cigarros/dia. Irmão com AVC aos 55 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1290, 381, 2, '2022-08-15 08:30', 'consulta', 'Pressão alta e a tosse não me deixa tomar o remédio', 162, 98, 78, 90.2, 'Paciente de 59 anos, hipertenso, abandonou dois anti-hipertensivos por efeitos colaterais: tosse seca persistente com enalapril e disfunção erétil que atribuiu ao atenolol. Conta que "a pressão sobe quando tenho raiva e fico sem remédio". Mede em casa 150-165 / 92-100. Ao exame: IMC 29, RCR 2T BNF, sem sopros, pulmões limpos, sem edemas. ECG com SVE leve. Creatinina 1,0, potássio 4,2, LDL 148. HD: HAS estágio 2 mal controlada por má adesão associada a efeitos colaterais, tosse por IECA.', 'Substituir enalapril por losartana (tosse não ocorre com BRA). Iniciar anlodipino 5 mg. Evitar betabloqueador neste momento. Esclarecida a relação entre ED, tabagismo e pressão, sem comprovação com betabloqueador. Parar a hidroclorotiazida por ora. Retorno em 6 semanas.'),
  (1291, 381, 2, '2022-10-10 08:50', 'retorno', 'A tosse sumiu, mas o pé está inchando', 140, 86, 74, 89.0, 'A tosse cessou duas semanas após a troca. PA domiciliar média de 138x84. Queixa de edema vespertino nos tornozelos, que o incomoda de usar a bota. Mantém uso regular, usa pílulas organizadas por dia. Ainda fuma 8 cigarros por dia. Função sexual inalterada, concluiu que não era o betabloqueador. Ao exame: edema 1+/4+ em tornozelos, sem sinais de IC. HD: HAS estágio 1 em melhora, edema por anlodipino.', 'Reduzir anlodipino para 2,5 mg e aumentar losartana para 100 mg ao dia. Meias de compressão e elevação dos pés. Encaminhado ao programa antitabagismo. Retorno em 8 semanas.'),
  (1292, 381, 2, '2023-04-17 09:00', 'retorno', 'Voltei para ver como está', 126, 78, 70, 86.5, 'Seis meses de tratamento regular com dois fármacos em dose baixa. Parou de fumar há 3 meses com bupropiona e perdeu 3,5 kg. Sem edema importante. MRPA média de 124x76. Sem tosse e sem queixa sexual. Creatinina 1,0, potássio 4,4. Ao exame: RCR 2T BNF, MV+ sem RA. HD: HAS estágio 2 controlada após troca do IECA por BRA e cessação do tabagismo.', 'Manter losartana 100 mg e anlodipino 2,5 mg. Seguir sem fumar e com caminhada. Pedir LDL e glicemia no próximo retorno. Retorno em 6 meses.');
