insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (381, '2023-04-17', 'controlado', 'Adesão recuperada após troca de enalapril (tosse) por losartana e redução do anlodipino por edema, com MRPA média de 124x76 mmHg. Parou de fumar há 3 meses; a queixa de disfunção erétil não se confirmou como efeito do betabloqueador.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (382, 'Marcos Vinícius Aquino Delgado', 'M', '1971-09-12', 'Campo Grande', 'MS', 'Vendedor de loja de departamentos', 'HAS há 11 anos, prescrito com losartana, anlodipino, hidroclorotiazida e espironolactona por outro serviço como "hipertensão resistente". Sobrepeso, diabetes não diagnosticado. Toma os remédios "quando tem dor de cabeça". Pai falecido de AVC aos 62 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1293, 382, 2, '2024-05-06 10:30', 'consulta', 'Quatro remédios e a pressão não baixa', 178, 106, 84, 94.0, 'Paciente de 52 anos, encaminhado como hipertensão resistente em quatro fármacos. Ao revisar com calma: toma os comprimidos de forma irregular, mais quando surge cefaleia. Retiradas na farmácia popular mostram só 40% dos comprimidos no último semestre, e diz que "são muitos remédios, e os de manhã me deixam com sono". Ao exame: IMC 31, RCR 2T BNF, sem sopros, sem edemas. Potássio 4,3, creatinina 1,0, glicemia 118. HD: pseudorresistência por má adesão, hipertensão estágio 3.', 'Não aumentar a medicação. Suspender espironolactona e hidroclorotiazida e simplificar para telmisartana/anlodipino em comprimido único, 1 vez ao dia à noite. Caixa de comprimidos diária e alarme no celular. Acompanhamento de enfermagem por teleconsulta em 4 semanas.'),
  (1294, 382, 5, '2024-06-03 19:00', 'teleconsulta', 'Tomando todo dia, pressão de casa melhorou', 144, 88, 80, null, 'Teleconsulta de enfermagem e medicina de família, 4 semanas após a simplificação. Tomando o comprimido único à noite todos os dias, com alarme. Medidas domiciliares dos últimos 7 dias: média 142x88 informada por foto do aparelho. Sem sonolência, sem edema, sem tontura. Relata dificuldade com a alimentação do trabalho, com muito sódio. HD: HAS estágio 1 em melhora, resposta à adesão confirmada.', 'Manter a posologia. Reforçada redução de sódio e marmita. Se média domiciliar permanecer > 135/85 em 3 semanas, adicionar hidroclorotiazida ao comprimido. Aferir MRPA e retorno presencial em 4 semanas.'),
  (1295, 382, 2, '2024-09-30 10:40', 'retorno', 'Estou me sentindo bem, vim mostrar a pressão', 132, 82, 76, 91.4, 'Adesão mantida há 4 meses; MRPA média 134x84, ainda levemente acima da meta de 130/80. Perdeu 2,6 kg. HbA1c 5,9% (pré-diabetes) e potássio 4,1. Não tem queixa. Prefere continuar a usar um comprimido só. Ao exame: RCR 2T BNF, sem edemas. HD: pseudorresistência resolvida, HAS quase controlada com dois fármacos.', 'Trocar para olmesartana/anlodipino/hidroclorotiazida 40/5/12,5 mg em comprimido único. Mantém tomada noturna. Orientada atividade física 150 min por semana. Retorno em 3 meses com MRPA e exames.');
