insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (382, '2024-09-30', 'controlado', 'Falsa hipertensão resistente, causada por má adesão a quatro medicamentos, resolvida com simplificação para comprimido único e alarme de lembrete. Com MRPA próxima da meta e ajuste para tripla combinação em uma pílula, segue com pré-diabetes e MEV.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (383, 'Gabriela Haddad Moellmann', 'F', '1988-04-20', 'Curitiba', 'PR', 'Gerente de recursos humanos', 'HAS estágio 1 há 2 anos em uso irregular de losartana 50 mg. Estresse intenso no trabalho, dorme 5 horas por noite. Toma 4 a 5 cafés por dia. Mãe com ansiedade e HAS.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1296, 383, 6, '2025-06-10 18:20', 'pronto_socorro', 'Medi 19 por 11 e fiquei com medo de ter um AVC', 196, 112, 98, 68.0, 'Pcte de 37 anos, após reunião tensa, sentiu nervosismo, formigamento perioral e aferiu PA 190/110 em casa. Sem cefaleia intensa, sem dor torácica, sem dispneia, sem déficit neurológico, sem alterações visuais. Estava sem losartana há 5 dias, tomou 2 cafés duplos. Ao exame: ansiosa, hidratada, RCR 2T BNF sem sopros, pulmões limpos, neurológico normal, fundo de olho sem papiledema nem hemorragias. ECG normal. Creatinina 0,8, troponina negativa, urina I sem proteína. HD: pseudocrise hipertensiva (elevação da PA sem lesão aguda de órgão-alvo).', 'Repouso por 30-60 min em sala calma, sem nifedipino sublingual nem anti-hipertensivo venoso. Reavaliação após repouso: PA 158x94. Orientada a retomar a losartana e orientação sobre sinais de alarme. Alta com consulta de seguimento ambulatorial em 20 dias.'),
  (1297, 383, 1, '2025-06-30 16:00', 'consulta', 'Depois do PS não parei de pensar na pressão', 138, 86, 80, 67.6, 'Retoma losartana 50 mg todos os dias desde o PS. Mede a PA em casa várias vezes por dia, o que a deixa ainda mais ansiosa. Valores de 128-142 / 78-90. Persistem cefaleia tensional e insônia, sem sintomas de alarme. Ao exame: PA 138x86 após repouso, RCR 2T BNF. HD: HAS estágio 1 de longa data, episódio no PS foi pseudocrise por ansiedade e interrupção do tratamento.', 'Combinar medidas domiciliares em horários fixos (2 vezes ao dia, 3 dias) para evitar excesso de aferições. Manter losartana 50 mg e acrescentar anlodipino 5 mg. Higiene do sono, reduzir cafeína e acompanhamento psicológico. Retorno em 4 semanas com MRPA.'),
  (1298, 383, 1, '2025-08-04 16:10', 'retorno', 'Mais tranquila, a pressão se mantém boa', 120, 76, 72, 67.0, 'MRPA de 3 dias em horários fixos: média 122x76 mmHg. Dorme 7 horas desde que iniciou psicoterapia e reduziu cafeína a 2 xícaras. Cefaleia tensional rara. Sem edema de tornozelos. Ao exame: RCR 2T BNF, sem sopros. HD: HAS estágio 1 controlada, ansiedade em acompanhamento.', 'Manter losartana 50 mg e anlodipino 5 mg. Reforçada a importância de não suspender sem orientação. Retorno em 6 meses com exames de rotina.');
