insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (383, '2025-08-04', 'controlado', 'Pseudocrise hipertensiva no PS (196x112 sem lesão de órgão-alvo) tratada com repouso e retomada da medicação, sem anti-hipertensivo de resgate. Seguimento ambulatorial com MRPA média de 122x76 mmHg, controle da ansiedade e hábitos de sono melhores.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (384, 'Rosana Gimenes Verón', 'F', '1990-12-03', 'Sidrolândia', 'MS', 'Professora de educação infantil', 'HAS diagnosticada aos 28 anos, em uso de enalapril 10 mg 12/12h. Obesidade grau I. Segunda gestação, primeiro filho nasceu a termo. Mãe hipertensa. Faz pré-natal em unidade do SUS.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1299, 384, 7, '2024-11-18 09:00', 'consulta', 'Descobri que estou grávida, tomo remédio para pressão', 144, 92, 84, 84.5, 'Gestante de 33 anos com 9 semanas e 6 dias pela DUM, em uso de enalapril 10 mg 12/12h desde antes da concepção, descobriu a gravidez há 1 semana. Sem sintomas, sem sangramento. Ao exame: IMC 32, PA 144x92, RCR 2T BNF, edema ausente. USG: gestação tópica única, BCF 168 bpm. Creatinina 0,8, proteinúria de 24h 120 mg. HD: HAS crônica na gestação, exposição inicial a IECA, alto risco.', 'Suspender enalapril imediatamente e iniciar metildopa 500 mg 8/8h. AAS 100 mg à noite a partir de 12 semanas e cálcio 1 g/dia. Ácido fólico. USG morfológico em 20 semanas e Doppler de uterinas. PA em casa 2x/dia. Retorno em 10 semanas.'),
  (1300, 384, 7, '2025-02-03 09:30', 'retorno', 'Barriga crescendo, queria ver a pressão', 128, 80, 86, 86.0, 'Gestante de 20 semanas e 6 dias, PA domiciliar média de 126x78 sob metildopa 500 mg 8/8h. Queixa de sonolência diurna leve. Sem cefaleia, sem edema. USG morfológico normal, com artérias uterinas com IP médio de 1,0. Peso aumentou 1,5 kg. Ao exame: AFU 21 cm, BCF 146 bpm, sem edema. HD: HAS crônica na gestação controlada, sem sinais de pré-eclâmpsia.', 'Manter metildopa e AAS 100 mg. Orientadas sinais de alarme de pré-eclâmpsia (cefaleia, escotomas, epigastralgia, edema súbito). Retorno em 12 semanas com exames laboratoriais e USG com Doppler.'),
  (1301, 384, 7, '2025-05-05 09:00', 'retorno', 'PA subiu um pouco nos últimos dias', 142, 90, 88, 90.2, 'Gestante de 33 semanas e 6 dias, PA domiciliar de 138-146 / 88-94 na última semana, sem cefaleia, sem escotomas, sem dor epigástrica. Edema leve de pés. Exames: plaquetas 212.000, TGO 24, creatinina 0,8, proteinúria de 24h 140 mg, sem aumento significativo. Feto com crescimento adequado, percentil 50, líquido normal. Ao exame: PA 142x90, AFU 33 cm. HD: HAS crônica na gestação com elevação pressórica, sem pré-eclâmpsia sobreposta.', 'Associar nifedipino retard 20 mg 12/12h à metildopa. Vigilância semanal com cardiotocografia e perfil. Plano de parto com 38 semanas. Retornar ao PS se cefaleia intensa, escotomas ou dor epigástrica.'),
  (1302, 384, 7, '2025-06-02 07:30', 'internacao', 'Internação para o parto com 37 semanas e 6 dias', 136, 86, 80, 92.0, 'Internada para indução do parto, 37 semanas e 6 dias, PA 130-140 / 84-90 com a medicação, sem sinais de pré-eclâmpsia. Colo favorável, indução com misoprostol e ocitocina. Parto vaginal após 9 horas, sem intercorrências, RN masculino de 3.140 g, Apgar 9/10. Sangramento de 300 mL, sem hemorragia. PA no pós-parto 142x88. HD: HAS crônica, parto vaginal a termo, sem complicações.', 'Manter nifedipino retard 20 mg 12/12h e suspender a metildopa. Controle da PA a cada 6h por 48h. Orientada amamentação, contracepção com DIU e retorno para ajuste de anti-hipertensivo. Após alta, consulta cardiológica em 30 dias.');
