insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (384, '2025-06-02', 'controlado', 'HAS crônica com exposição inicial a IECA tratada na gestação com metildopa e nifedipino, AAS e cálcio, sem pré-eclâmpsia sobreposta. Parto vaginal a termo, RN saudável de 3.140 g, PA controlada no puerpério e plano de retorno ao IECA após a amamentação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (385, 'Leôncio Benedet Sartori', 'M', '1960-07-12', 'Cascavel', 'PR', 'Produtor rural', 'Tabagista de 45 maços-ano. HAS e dislipidemia sem tratamento, sem consultas há anos. Costuma "aguentar a dor" e só procurar médico quando não consegue trabalhar. Pai com infarto aos 55 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1303, 385, 6, '2024-09-14 22:10', 'pronto_socorro', 'Dor no peito desde de manhã, agora não aguento mais', 104, 68, 98, 84.0, 'Pcte de 64 anos, dor precordial em aperto desde as 08h, atribuída a "indigestão", só procurou o PS 14 horas depois. Ao exame: pálido, sudorético, PA 104x68, FC 98, estertores em bases, SpO2 92%. ECG: supra de ST de 4 mm de V1 a V5 com ondas Q em V1-V3. Troponina 18 ng/mL. ECO: FEVE 30%, acinesia anterior e apical. HD: IAMCSST anterior extenso, Killip II, chegada tardia (14h do início).', 'AAS 300 mg, ticagrelor 180 mg, heparina não fracionada. Angioplastia primária mesmo com chegada tardia pelo quadro de IC e dor persistente. Furosemida 40 mg EV. Evitar betabloqueador no momento pelo Killip II. Encaminhado à hemodinâmica.'),
  (1304, 385, 10, '2024-09-15 01:00', 'internacao', 'Pós-angioplastia, na UTI', 98, 62, 90, 83.5, 'Cateterismo: oclusão trombótica de DA proximal, lesão de 70% em CD e Cx sem lesões. ATC com stent farmacológico 3,5x28 mm em DA, fluxo TIMI 2 final por no-reflow parcial, recebeu adenosina intracoronária com melhora para TIMI 3. Persistência de congestão leve e FEVE 28%. Pico de troponina 220 ng/mL. Sem arritmias malignas. HD: IAMCSST anterior extenso com grande área de necrose e disfunção ventricular grave.', 'UTI coronariana 48h. Dupla antiagregação por 12 meses, atorvastatina 80 mg. Iniciar enalapril 2,5 mg e carvedilol 3,125 mg assim que PA permitir. Espironolactona 25 mg. Holter antes da alta e reavaliação da FEVE em 40 dias para decidir sobre CDI.'),
  (1305, 385, 11, '2024-11-25 08:30', 'retorno', 'Canso muito, sem força para a lida', 106, 66, 72, 80.2, 'Dez semanas pós-IAM extenso, NYHA III, dispneia ao caminhar 100 metros e ortopneia leve. Parou de fumar na internação, mas recaiu duas vezes. ECO: FEVE 30%, aneurisma apical sem trombo, regurgitação mitral funcional moderada. NT-proBNP 3.400. Creatinina 1,1, potássio 4,7. Ao exame: B3, estertores nas bases, edema 1+/4+. HD: cardiomiopatia isquêmica pós-IAM, ICFEr classe III, quadro com PA baixa limitando titulação.', 'Suspender enalapril, esperar 36 horas e começar sacubitril/valsartana 24/26 mg 12/12h. Adicionar dapagliflozina 10 mg. Manter carvedilol 6,25 mg e espironolactona. Colocar em plano de reabilitação. Reavaliar FEVE em 3 meses para CDI. Retorno em 4 semanas.'),
  (1306, 385, 11, '2025-07-14 08:40', 'retorno', 'Piorou o cansaço e acordei afogado duas vezes', 100, 62, 68, 83.4, 'Dez meses após o IAM. Voltou a fumar 10 cigarros por dia e abandonou a dapagliflozina por custo. Dispneia aos pequenos esforços, DPN duas vezes na semana e ganho de 3 kg. FEVE 28% mesmo após tratamento por 8 meses, aneurisma apical estável. Holter com 3 episódios de TV não sustentada. Ao exame: B3, estertores bibasais, jugular a 45 graus, edema 2+/4+. NT-proBNP 5.200. HD: ICFEr isquêmica progressiva, NYHA III-IV, com indicação de CDI para prevenção primária.', 'Aumentar furosemida para 80 mg e retomar dapagliflozina (fornecida pelo programa de alto custo). Solicitar CDI para prevenção primária. Reforçar a necessidade de parar de fumar. Avaliação para ressincronização, QRS 124 ms. Retorno em 15 dias.');
