insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (385, '2025-07-14', 'piorou', 'IAMCSST anterior extenso com chegada tardia (14 horas) evoluiu para cardiomiopatia isquêmica com FEVE 28% e ICFEr em classe III-IV. Piora por recaída no tabagismo e abandono da dapagliflozina; aguardando CDI para prevenção primária e avaliação de ressincronização.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (386, 'Hermes Dietrich Santana', 'M', '1968-02-27', 'Joinville', 'SC', 'Soldador industrial', 'Etilismo pesado há 25 anos (cerca de 1 litro de cachaça por dia nos fins de semana e cerveja no restante). Sem outras comorbidades. HAS leve nos últimos anos. Tabagista de 20 maços-ano.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1307, 386, 11, '2022-10-03 09:00', 'consulta', 'Falta de ar para subir um lance de escada e perna inchada', 124, 80, 104, 82.4, 'Paciente de 54 anos, dispneia progressiva há 5 meses, ortopneia, edema de pernas e distensão abdominal. Mantém consumo alcoólico diário. Ao exame: taquicárdico, B3, sopro de IM 2+/6+, estertores bibasais, jugular ingurgitada, hepatomegalia dolorosa, edema 2+/4+. ECG: ritmo sinusal com SVE e BRE incompleto. ECO: cardiomiopatia dilatada, FEVE 25%, DDVE 69 mm. Coronárias normais por angiotomografia. NT-proBNP 5.800. HD: cardiomiopatia alcoólica com ICFEr, NYHA III.', 'Abstinência alcoólica total, com encaminhamento ao CAPS-AD e tiamina. Iniciar sacubitril/valsartana 24/26 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg e furosemida 40 mg. Retorno em 15 dias.'),
  (1308, 386, 11, '2023-01-16 09:20', 'retorno', 'Estou há três meses sem beber, já respiro melhor', 112, 70, 70, 74.8, 'Abstinente há 3 meses, com acompanhamento no CAPS-AD e apoio da esposa. Perdeu 7,6 kg de líquido, edema ausente, dispneia só aos grandes esforços (NYHA II). Tolera bem os quatro pilares sem tontura, PA 112x70, FC 70. Potássio 4,6 e creatinina 1,0. Ao exame: ritmo regular, sem B3, estertores ausentes. ECO: FEVE 38%. HD: cardiomiopatia alcoólica em recuperação com abstinência.', 'Dobrar carvedilol para 6,25 mg 12/12h e aumentar sacubitril/valsartana para 49/51 mg 12/12h. Reduzir furosemida para 20 mg. Continuar CAPS-AD. Retorno em 8 semanas.'),
  (1309, 386, 11, '2023-08-14 09:00', 'retorno', 'Voltei a trabalhar e estou bem, sem álcool', 114, 72, 64, 77.0, 'Dez meses de abstinência, de volta ao trabalho com adaptações (sem levantar peso). Sem dispneia aos esforços habituais. Corre pouco em esteira. FEVE subiu para 50% no ECO de controle, DDVE 56 mm, sem regurgitação mitral relevante. NT-proBNP 210. Creatinina 1,0. Ao exame: pulmões limpos, sem edema. HD: cardiomiopatia alcoólica com recuperação da função ventricular, NYHA I.', 'Manter os quatro pilares por tempo indeterminado, mesmo com FEVE melhorada, conforme diretrizes. Suspender furosemida. Reforçado que a recaída alcoólica pode reverter o ganho. Retorno semestral com ECO anual.');
