insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (386, '2023-08-14', 'melhorou', 'Cardiomiopatia alcoólica com FEVE inicial de 25%, recuperada para 50% após 10 meses de abstinência e terapia dos quatro pilares. NYHA I, NT-proBNP 210 pg/mL, de volta ao trabalho e seguindo no CAPS-AD.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (387, 'Maria Eunice Galvão Câmara', 'F', '1948-06-18', 'Natal', 'RN', 'Costureira aposentada', 'HAS há 40 anos, usa anlodipino e hidroclorotiazida de forma irregular. DM2 há 10 anos. Obesidade. Mora sozinha em casa de dois andares, com poucos recursos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1310, 387, 6, '2022-11-20 01:50', 'pronto_socorro', 'Acordei sem ar e com o peito apertado', 204, 110, 108, 78.5, 'Pcte de 74 anos, dispneia súbita à noite, ortopneia e tosse com secreção rosada. Parou os remédios há 3 semanas por falta de dinheiro. Ao exame: sudorética, taquipneica, SpO2 84%, PA 204x110, FC 108, estertores até ápices, B3, edema 2+/4+. ECG: SVE com sobrecarga, sem supra de ST. Troponina 0,08 ng/mL. Rx com edema pulmonar. HD: EAP hipertensivo por cardiopatia hipertensiva, crise hipertensiva com lesão de órgão-alvo.', 'O2 com máscara e CPAP, nitroglicerina IV em infusão contínua, furosemida 80 mg EV. Meta de redução de 25% da PA na 1ª hora e depois gradual. Internar na enfermaria de cardiologia. Pedir ECO e laboratório.'),
  (1311, 387, 11, '2022-11-21 09:30', 'internacao', 'Melhor da falta de ar, quero ir para casa', 146, 84, 86, 75.2, 'Após diurético e vasodilatador, saiu do O2 em 8h, perdeu 3,3 kg e PA em 146x84. ECO: FEVE 38%, HVE concêntrica importante, E/e'' elevado, átrio esquerdo 46 mm. Creatinina 1,5 (TFGe 36), potássio 4,0, HbA1c 8,6%. Troponina em platô, sem dor torácica. Ainda com edema leve e murmúrio diminuído nas bases. HD: ICFEr/IC com FE levemente reduzida (cardiopatia hipertensiva), descompensação por interrupção do tratamento.', 'Iniciar losartana 25 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 12,5 mg, dapagliflozina 10 mg e furosemida 40 mg. Retornar para controle de creatinina e potássio. Assistente social para acesso aos remédios. Orientada a pesar-se. Alta em 2 dias.'),
  (1312, 387, 11, '2022-12-19 08:30', 'retorno', 'Já estou melhor, mas não consegui comprar tudo', 138, 82, 76, 73.0, 'Quatro semanas após a alta, sem dispneia em repouso, caminha até a esquina. Consegue só 3 dos 5 medicamentos: não comprou dapagliflozina e espironolactona por preço. Refere "tonteira e fraqueza" com a furosemida de manhã. Creatinina 1,4, potássio 4,3. Mora longe da unidade e depende de vizinha para ir às consultas. Ao exame: pulmões limpos, edema ausente. HD: IC compensada, tratamento parcial por barreiras econômicas.', 'Dispensação pelo programa estadual solicitada para dapagliflozina e espironolactona. Mantidos losartana, carvedilol e furosemida. Visita da equipe de saúde da família e retorno em 4 semanas para checar acesso e exames.');
