insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (387, '2023-06-30', 'abandonou', 'Não compareceu ao retorno de janeiro de 2023 nem às convocações seguintes. A equipe de saúde da família relatou em junho de 2023 que a paciente mora sozinha, tem dificuldade de transporte e não consegue comprar a medicação. Sem nova internação conhecida.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (388, 'Marta Schiavon Lopes', 'F', '1979-03-11', 'Campo Mourão', 'PR', 'Confeiteira', 'Febre reumática na infância com cardite. Palpitações esporádicas nos últimos anos, dispneia aos esforços, piora progressiva. Duas gestações aos 25 e 28 anos, sem complicações maiores. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1313, 388, 2, '2023-03-20 10:00', 'consulta', 'Canso muito e o coração dispara quando faço bolo em quantidade', 118, 74, 112, 64.0, 'Paciente de 44 anos com dispneia aos médios esforços (NYHA II-III), palpitações e fadiga. Ao exame: ritmo irregular, FC 112, B1 hiperfonética, estalido de abertura e sopro diastólico em ruflar em foco mitral 3+/4+, estertores discretos em bases. ECG: fibrilação atrial de resposta ventricular moderada. ETT: estenose mitral reumática, área valvar 1,0 cm² pelo PHT, gradiente médio 14 mmHg, átrio esquerdo 54 mm, PSAP 52 mmHg, FEVE 62%. HD: estenose mitral reumática moderada a grave com FA.', 'Varfarina com alvo de INR 2-3 (DOAC contraindicado na estenose mitral moderada/grave), iniciada com ajuste pelo INR semanal. Metoprolol succinato 50 mg para controle de frequência. Penicilina benzatina a cada 21 dias como profilaxia secundária. ETE e avaliação para valvoplastia por cateter-balão.'),
  (1314, 388, 2, '2023-05-15 10:30', 'retorno', 'Não sei se estou tomando a varfarina certo', 114, 72, 88, 63.5, 'Após 7 semanas de varfarina, INR variou entre 1,4 e 3,6 por dieta com muitas verduras e pela confeitaria com ovos e fígado. Sem sangramentos, mas equimoses leves. INR de hoje 1,8. ETE: sem trombo em apêndice, anatomia valvar favorável (escore de Wilkins 7), sem regurgitação mitral importante. Dispneia ainda NYHA II-III. Ao exame: FA com FC 88, estertores discretos. HD: EM reumática moderada a grave, anatomia favorável para valvoplastia, INR lábil.', 'Mantém varfarina com ajustes e dieta estável (sem excessos de vegetais verdes). Marcar valvoplastia mitral por cateter-balão. INR a cada 7 dias. Receita de furosemida 20 mg se edema. Retorno antes do procedimento.'),
  (1315, 388, 10, '2023-08-21 07:30', 'internacao', 'Internação para valvoplastia mitral', 116, 70, 80, 63.0, 'Internada eletivamente com INR 2,3 (varfarina mantida). Valvoplastia mitral por cateter-balão (técnica de Inoue) via transeptal sob ECO. Balão de 28 mm com aumento da área de 1,0 para 1,9 cm² e gradiente médio de 14 para 5 mmHg. Pequeno aumento da regurgitação mitral para grau leve, sem tamponamento. Sem complicações vasculares. Alta no dia seguinte, assintomática.', 'Manter varfarina e metoprolol. ECO de controle em 1 mês. Seguir com penicilina benzatina. Alta no 2º dia, retorno em 30 dias. Orientada profilaxia de endocardite.'),
  (1316, 388, 2, '2023-11-27 10:00', 'retorno', 'Consigo fazer bolo o dia inteiro sem cansar', 112, 70, 74, 64.2, 'Três meses após valvoplastia, assintomática (NYHA I), voltou a trabalhar normalmente e a caminhar. INR estável entre 2,1 e 2,8 nos últimos 2 meses com dieta regular e controle semanal. ETT: área valvar 1,8 cm², gradiente médio 6 mmHg, PSAP 34 mmHg, regurgitação mitral leve. Ao exame: FA com FC 74, sem B3, sopro diastólico suave. HD: EM reumática pós-valvoplastia com ótimo resultado, FA permanente.', 'Manter varfarina (alvo de INR 2-3), metoprolol e penicilina benzatina. ECO anual. INR mensal se estável. Retorno em 6 meses.');
