insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (388, '2023-11-27', 'melhorou', 'Estenose mitral reumática com FA tratada com varfarina e valvoplastia por balão, com área valvar de 1,0 para 1,8 cm² e gradiente de 14 para 6 mmHg. Assintomática, voltou a trabalhar e mantém INR no alvo e profilaxia secundária da febre reumática.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (389, 'Elias Dorneles Arruda', 'M', '1959-05-04', 'Aquidauana', 'MS', 'Peão de boiadeiro aposentado', 'Doença de Chagas conhecida desde 2005, nascido em casa de barro no interior de Goiás. Já teve tonturas e quedas ocasionais. Sem tratamento específico. HAS leve. Ex-tabagista.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1317, 389, 6, '2022-03-12 05:10', 'pronto_socorro', 'Desmaiei de manhã quando levantei da cama', 138, 74, 34, 76.5, 'Pcte de 62 anos, chagásico, com síncope súbita ao levantar, sem pródromos, com recuperação em 1 minuto, e episódio anterior semelhante há 2 meses. Cansaço aos esforços. Ao exame: pulso 34, bradicárdico, regular, PA 138x74, ausculta com B1 variável (ondas "em canhão" no pescoço), pulmões limpos. ECG: BAVT com ritmo de escape juncional a 34 bpm e BRD. HD: BAVT de origem chagásica com síncope.', 'Monitorização contínua, pás de marca-passo transcutâneo à beira do leito, atropina sem resposta esperada. Internar na UTI e programar marca-passo definitivo. Evitar betabloqueador e outros bradicardizantes. Não é caso de benznidazol pela cardiopatia crônica.'),
  (1318, 389, 4, '2022-03-14 08:00', 'internacao', 'Implante de marca-passo', 126, 74, 70, 76.2, 'Implante de marca-passo definitivo dupla câmara por punção da veia subclávia esquerda sob anestesia local, eletrodo ventricular em septo e atrial em apêndice direito. Limiares agudos adequados (0,6 V ventricular), sem pneumotórax na radiografia. ECO: FEVE 52%, aneurisma apical pequeno, átrio esquerdo 42 mm. Holter prévio sem TV. FC de 70 bpm por estimulação sequencial. HD: BAVT chagásico tratado com MP DDD.', 'Alta em 24h com curativo seco, restrição de elevação do braço esquerdo por 2 semanas. Carteira de marca-passo entregue. Controle do aparelho em 30 dias. Manter acompanhamento por cardiopatia chagásica.'),
  (1319, 389, 4, '2022-04-18 09:00', 'retorno', 'Estou ótimo, nunca mais tive tontura', 130, 78, 72, 77.0, 'Cinco semanas de pós-implante, sem síncope, sem dor na loja do gerador, ferida cicatrizada. Interrogação do marca-passo: limiares estáveis, estimulação ventricular de 98%, bateria adequada, sem arritmias atriais ou TV. Caminha 40 minutos. Ao exame: ferida limpa, RCR 2T, sem edema. HD: Chagas crônico com MP DDD funcionante, sem síncope.', 'Iniciar enalapril 5 mg 12/12h por HAS e proteção ventricular (pois a FEVE é limítrofe). Revisão do aparelho em 6 meses, telemonitoramento. Orientar sobre interferência de campos magnéticos. Retorno em 3 meses.'),
  (1320, 389, 11, '2024-02-26 09:10', 'retorno', 'Começou um cansaço nos esforços', 124, 72, 70, 79.4, 'Dois anos de MP, assintomático para síncope. Há 4 meses dispneia aos médios esforços e edema leve de tornozelos. ECO: FEVE caiu para 38%, aneurisma apical aumentado, sem trombo. Estimulação ventricular direita de 99% pode estar contribuindo. NT-proBNP 1.450. Creatinina 1,1, potássio 4,5. Ao exame: B3, estertores discretos em bases, edema 1+/4+. HD: cardiopatia chagásica com ICFEr (NYHA II-III), cardiomiopatia por estimulação ventricular concomitante.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36h de pausa. Iniciar carvedilol 3,125 mg 12/12h (seguro com MP), espironolactona 25 mg e dapagliflozina 10 mg. Avaliar upgrade para ressincronização. Retorno em 4 semanas com K e creatinina.');
