insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (389, '2024-02-26', 'estavel', 'BAVT chagásico tratado com marca-passo dupla câmara, sem síncope desde o implante. Evoluiu com ICFEr (FEVE 38%) em início de terapia dos quatro pilares e avaliação de ressincronização, seguindo em acompanhamento ambulatorial.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (390, 'Yara Sacramento Lobo', 'F', '1946-11-09', 'Porto Velho', 'RO', 'Professora aposentada', 'HAS há 30 anos controlada com anlodipino e losartana. Sedentária por tontura. Dois episódios de desmaio nos últimos 6 meses. Filha vive em Manaus e a convida para morar com ela.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1321, 390, 4, '2025-02-10 10:00', 'consulta', 'Desmaiei duas vezes e sinto o coração parar', 134, 76, 46, 62.0, 'Paciente de 78 anos com episódios de tontura, pré-síncope e dois desmaios súbitos em 6 meses, além de palpitações rápidas alternadas com sensação de coração "parando". Ao exame: pulso 46 regular, PA 134x76, RCR 2T BNF, sem sopros. ECG: bradicardia sinusal 44 bpm. Holter 48h: pausas sinusais de até 5,2 s durante vigília, episódios de FA paroxística com resposta ventricular de 140 e bradicardia de 38 bpm ao reverter (taqui-bradi). TSH normal. ECO com FEVE 58%. HD: doença do nó sinusal sintomática (síndrome taqui-bradi), CHA2DS2-VASc 4.', 'Indicação clara de marca-passo definitivo. Iniciar apixabana 5 mg 12/12h pela FA paroxística (idade 78, mulher, HAS, CHA2DS2-VASc 4). Suspender betabloqueadores se houver. Agendar implante. Orientada a não dirigir e a evitar ficar sozinha.'),
  (1322, 390, 4, '2025-03-04 07:30', 'internacao', 'Vim para colocar o marca-passo', 138, 78, 48, 61.8, 'Internação eletiva para implante de marca-passo definitivo dupla câmara (DDD) com modo de reduzir estimulação ventricular. Apixabana suspensa 24h antes. Implante pela veia cefálica esquerda, limiares agudos adequados (atrial 0,8 V, ventricular 0,6 V), sem complicações. FC sob estimulação atrial 70 bpm. Radiografia sem pneumotórax. Alta no dia seguinte, assintomática.', 'Retornar à apixabana 5 mg 12/12h após 24h do procedimento. Curativo seco, evitar elevar o braço esquerdo por 2 semanas. Primeira interrogação em 30 dias. Encaminhar carteira do marca-passo.'),
  (1323, 390, 4, '2025-04-14 10:10', 'retorno', 'Sem tontura, mas vou me mudar para Manaus', 130, 74, 70, 63.2, '6 semanas de pós-implante, sem síncope ou pré-síncope, caminhando 30 minutos. Interrogação do marca-passo: estimulação atrial de 45%, ventricular de 3%, limiares estáveis, 2 episódios de FA com duração menor que 30 minutos, bateria adequada. Sem sangramento em uso de apixabana. Informa mudança para Manaus em maio para morar com a filha. Ao exame: ferida bem cicatrizada. HD: doença do nó sinusal tratada com MP DDD, FA paroxística controlada.', 'Manter apixabana, losartana e anlodipino. Entregues relatório completo, laudo do implante e carta de encaminhamento para a cardiologia e o ambulatório de marca-passo em Manaus. Alta do serviço após a mudança. Telemonitoramento do aparelho continuará até 3 meses.');
