insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (390, '2025-05-20', 'transferido', 'Doença do nó sinusal (síndrome taqui-bradi) tratada com marca-passo dupla câmara e anticoagulação, sem síncope após o implante. Mudou-se para Manaus em maio de 2025 e foi encaminhada com relatório completo para seguimento do marca-passo e da FA em serviço local.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (391, 'Rafael Ueda Bonfim', 'M', '1987-03-14', 'Apucarana', 'PR', 'Bancário', 'Sem comorbidades diagnosticadas. Pai hipertenso desde os 45 anos. Sedentário, trabalho sentado de 9 horas, toma bastante refrigerante e come fast-food no almoço. Bebe cerveja aos sábados, não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1324, 391, 5, '2025-02-17 12:10', 'consulta', 'Check-up da empresa disse que a pressão está no limite', 134, 86, 76, 91.0, 'Paciente de 37 anos, assintomático, com PA de 132-138 / 84-88 no exame periódico. IMC 29,6, circunferência abdominal 102 cm. Perfil lipídico com LDL 132 e triglicerídeos 190, glicemia 98. Ao exame: RCR 2T BNF, sem sopros, sem edemas. ECG normal. Sem lesão de órgão-alvo na avaliação inicial, albuminúria negativa. HD: pré-hipertensão com excesso de peso e risco cardiovascular baixo.', 'Sem medicação. MEV intensiva: reduzir sal e refrigerante, atividade física aeróbica 150 min por semana, perder 5 a 8 kg. MRPA por 5 dias para ver se há hipertensão sustentada. Retorno em 3 meses.'),
  (1325, 391, 5, '2025-05-05 12:20', 'retorno', 'Vim mostrar que perdi peso', 124, 80, 70, 85.6, 'Perdeu 5,4 kg em 11 semanas, caminha 40 minutos 4 vezes por semana e trocou refrigerante por água. MRPA com média de 122x78 mmHg. Triglicerídeos 120 e LDL 118. Ao exame: IMC 27,8, RCR 2T BNF. HD: pré-hipertensão com melhora somente com mudança de estilo de vida, sem necessidade de medicamento.', 'Manter MEV. Meta de mais 3 kg. Repetir MRPA a cada 6 meses e exames anuais. Orientado a procurar a unidade se PA domiciliar ≥ 135/85 em mais de 3 dias. Retorno em 6 meses.');
