insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (392, '2024-07-22', 'controlado', 'Angina estável CCS III com isquemia na circunflexa, tratada com angioplastia e stent farmacológico. Assintomático em reabilitação, LDL 48 mg/dL, HbA1c 6,8% e PA 126x72 mmHg, mantido em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (393, 'Carolina Zahn Fiedler', 'F', '1993-08-05', 'Ponta Grossa', 'PR', 'Analista de sistemas', 'Primeira gestação, pré-natal sem intercorrências, parto vaginal a termo em 26/04/2024. Sem comorbidades prévias. Em aleitamento materno exclusivo. Sem histórico familiar de cardiopatia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1329, 393, 6, '2024-05-20 22:30', 'pronto_socorro', 'Falta de ar para deitar e inchaço nas pernas depois do parto', 110, 70, 118, 70.5, 'Puérpera de 30 anos, 24 dias após parto, com dispneia progressiva há 10 dias, ortopneia, tosse noturna e edema bilateral de pernas. Ao exame: taquipneica, SpO2 91%, PA 110x70, FC 118, B3, estertores até metade dos pulmões, jugular ingurgitada, edema 3+/4+. BNP 1.350 pg/mL, troponina discretamente elevada. ECO beira-leito: FEVE 28%, dilatação do VE. HD: cardiomiopatia periparto com IC aguda.', 'O2 suplementar, furosemida 40 mg EV, internação em unidade coronariana. Evitar iSGLT2 e sacubitril/valsartana durante lactação, usar enalapril, carvedilol e espironolactona (compatíveis). Heparina profilática. Discutir suspensão da lactação com bromocriptina.'),
  (1330, 393, 11, '2024-05-22 09:00', 'internacao', 'Melhor da falta de ar na internação', 108, 66, 92, 67.2, 'Após diurético, perdeu 3,3 kg e saiu do O2. ECO formal: FEVE 30%, DDVE 62 mm, regurgitação mitral funcional leve, sem trombo. Ressonância cardíaca sem realce tardio, descartando miocardite. Sem arritmias na telemetria. Decidido pela suspensão da lactação com cabergolina, já que a bromocriptina aumenta risco trombótico. Orientada que gestações futuras têm alto risco.', 'Iniciar enalapril 2,5 mg 12/12h, carvedilol 3,125 mg 12/12h e espironolactona 25 mg. Manter furosemida VO 20 mg. Cabergolina 1 mg dose única para inibir lactação. Alta em 6 dias. Contracepção com DIU. Retorno em 3 semanas.'),
  (1331, 393, 11, '2024-08-19 08:30', 'retorno', 'Estou conseguindo cuidar do bebê sem cansar', 104, 64, 66, 62.8, 'Três meses depois, NYHA I-II, sem ortopneia nem edema, cuida do bebê com apoio da mãe. Tolera enalapril e carvedilol; tontura leve só ao levantar, com PA em 100-108 de sistólica em casa. ECO: FEVE 42%, DDVE 57 mm. Creatinina 0,8, potássio 4,4. Ao exame: pulmões limpos, sem B3, edema ausente. HD: cardiomiopatia periparto em recuperação.', 'Subir enalapril para 5 mg 12/12h e carvedilol 6,25 mg 12/12h aos poucos, evitando hipotensão. Suspender furosemida. Manter espironolactona. DIU mantido. Retorno em 6 meses com ECO.'),
  (1332, 393, 11, '2025-02-17 08:40', 'retorno', 'Voltei ao trabalho e à academia leve', 108, 66, 62, 60.5, 'Nove meses após o episódio, assintomática, voltou ao trabalho em jornada integral, faz caminhadas e musculação leve. ECO: FEVE 55%, DDVE 52 mm, sem regurgitação mitral. NT-proBNP 85. Sem arritmias no Holter. Tolera medicação sem efeitos adversos. Ao exame normal. HD: cardiomiopatia periparto com recuperação funcional.', 'Manter terapia por pelo menos 12 meses após normalização da FEVE e depois desmame gradual com monitorização. Reforçada a contraindicação de nova gestação sem aconselhamento especializado. Retorno em 6 meses com ECO.');
