insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (395, '2025-07-28', 'controlado', 'Flutter atrial típico sintomático curado com ablação do istmo cavotricuspídeo, sem recorrência em 3 meses (Holter em ritmo sinusal 100%). Anticoagulante encerrado após 2 meses; segue com losartana, perda de peso e investigação de apneia do sono.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (396, 'Verônica Seabra Hunziker', 'F', '1970-02-02', 'Florianópolis', 'SC', 'Bióloga marinha', 'Sopro conhecido desde a juventude. Prolapso da valva mitral diagnosticado há 10 anos, sem acompanhamento regular. Pratica mergulho e corrida, sem comorbidades. Mãe com valvopatia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1340, 396, 2, '2025-03-10 15:00', 'consulta', 'Cansaço nas corridas e palpitações, estou piorando', 118, 70, 82, 60.0, 'Paciente de 55 anos com piora progressiva da capacidade de exercício nos últimos 10 meses, dispneia aos médios esforços e palpitações. Ao exame: ritmo regular, estalido mesossistólico e sopro holossistólico apical 4+/6+ irradiado para axila, B3, pulmões limpos. ETT: prolapso do folheto posterior (P2) com flail parcial, regurgitação mitral importante, VE dilatado (DSVE 42 mm), FEVE 60%, PSAP 44 mmHg. ETE confirma jato excêntrico. HD: insuficiência mitral degenerativa grave sintomática por prolapso de P2.', 'Indicação cirúrgica por sintomas e dilatação do VE. Preferência por plástica mitral (alta chance de reparo em P2). Cateterismo coronariano pré-operatório, avaliação com cirurgia cardíaca. Suspender mergulho. Sem medicações específicas por ora. Retorno em 3 semanas.'),
  (1341, 396, 12, '2025-05-19 07:00', 'internacao', 'Cirurgia da válvula mitral', 110, 64, 78, 59.8, 'Coronárias normais no cateterismo. Realizada plástica da valva mitral por esternotomia mediana: ressecção quadrangular de P2 com anuloplastia por anel rígido 32 mm, tempo de CEC 112 min. ETE intraoperatório sem regurgitação residual e gradiente médio de 3 mmHg. Extubada em 5 horas, ritmo sinusal, sem inotrópicos. Dreno com 140 mL em 12h. HD: pós-operatório imediato de plástica mitral, evolução favorável.', 'Alta da UTI em 24h. AAS 100 mg e varfarina com alvo de INR 2-3 por 3 meses (anel), com ponte de heparina. Analgesia e fisioterapia respiratória. Retirada de drenos em 48 horas. Alta hospitalar em 6 dias.'),
  (1342, 396, 2, '2025-08-25 15:20', 'retorno', 'Estou bem, queria saber quando posso mergulhar', 114, 68, 66, 61.2, 'Três meses de pós-operatório de plástica mitral, esternotomia cicatrizada, sem dispneia, voltou a correr 5 km. INR mantido em alvo e agora na terceira revisão mensal. ETT: sem regurgitação residual, gradiente médio 3 mmHg, DDVE 54 mm, FEVE 57%, PSAP 28 mmHg. Ao exame: ritmo regular, sem sopros, sem edema. HD: pós-plástica mitral com ótimo resultado.', 'Suspender varfarina após os 3 meses. Manter AAS 100 mg por mais 3 meses. Orientar profilaxia de endocardite antes de procedimentos dentários. Mergulho liberado após 6 meses com ECO de controle. Retorno em 6 meses.');
