insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (396, '2025-08-25', 'melhorou', 'Insuficiência mitral degenerativa grave por prolapso de P2 tratada com plástica mitral e anuloplastia, sem regurgitação residual aos 3 meses. Assintomática e correndo 5 km, com anticoagulante suspenso e mergulho liberado após 6 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (397, 'Odete Ramalho Duque', 'F', '1958-12-12', 'Maracaju', 'MS', 'Doméstica aposentada', 'Chagas crônica conhecida, com ECG alterado há anos (BRD e BDAS) e extrassístoles frequentes. Nunca investigada a fundo ou tratada para IC. HAS leve. Mora com o filho, distante 70 km do hospital de referência.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1343, 397, 11, '2025-01-27 08:30', 'consulta', 'Tive um derrame no braço e na fala, saí do hospital há uma semana', 118, 72, 60, 58.0, 'Paciente de 66 anos, chagásica, alta há 1 semana de internação por AVC isquêmico de território da cerebral média esquerda, com afasia leve e paresia braquiofacial direita já em melhora. TC mostrou infarto cortical e ECO identificou aneurisma apical de 32 mm com trombo mural de 15 mm. FEVE 33%. Dispneia aos médios esforços (NYHA II). Ao exame: ritmo regular, B3, edema ausente, disartria discreta. HD: cardiopatia chagásica com ICFEr, trombo em aneurisma apical e AVC cardioembólico.', 'Iniciar varfarina com alvo de INR 2-3 (sem DOAC por ser chagásica com trombo mural, conduta de serviço) com ponte de enoxaparina. Sacubitril/valsartana 24/26 mg, carvedilol 3,125 mg, espironolactona 25 mg e dapagliflozina 10 mg. Não é caso de benznidazol. Holter e avaliação para CDI. Retorno em 3 semanas.'),
  (1344, 397, 11, '2025-03-17 08:40', 'retorno', 'Estou sem força na perna e as tonteiras voltaram', 104, 64, 56, 57.2, 'Tomou todos os remédios, mas o INR variou entre 1,6 e 3,4 por falta de acesso ao laboratório. Sem sangramentos. Refere duas tonteiras e uma quase-síncope em casa. Holter: ritmo sinusal com 6.200 extrassístoles ventriculares, 3 episódios de TV não sustentada de até 12 batimentos e 2 pausas de 2,8 s. Ao exame: FC 56, B3 e hipotensão leve. ECO de controle: trombo menor (10 mm), FEVE 31%. HD: Chagas com ICFEr, arritmia ventricular complexa, indicação de CDI em avaliação.', 'Manter varfarina e quatro pilares com redução do carvedilol para 3,125 mg 1x/dia devido à bradicardia. Solicitado CDI com urgência pelo SUS e parecer da arritmologia. Orientado a não ficar sozinha. INR a cada 15 dias na UBS. Retorno em 6 semanas.'),
  (1345, 397, 6, '2025-08-09 06:50', 'pronto_socorro', 'Filho conta que ela caiu na cozinha e ficou desacordada', 60, 40, 30, 56.0, 'Pcte de 66 anos, chagásica, trazida pelo filho após colapso súbito na cozinha às 06:10, sem respostas, e familiar iniciou compressões orientado pelo SAMU. Chegou ao PS em PCR em ritmo de fibrilação ventricular, que reverteu com 2 choques e adrenalina. Retorno de circulação espontânea após 18 min, com bradicardia 30 bpm e PA 60x40, sem resposta a estímulos (Glasgow 3). Aguardava CDI desde março, sem vaga. INR da UBS 1,7. HD: parada cardiorrespiratória por FV em cardiopatia chagásica, encefalopatia pós-anóxia.', 'Intubação orotraqueal, noradrenalina, hipotermia terapêutica controlada, encaminhamento à UTI. Pesquisa de causas reversíveis (potássio, isquemia) sem alterações. Conversa com o filho sobre prognóstico reservado devido ao tempo de parada.');
