insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (397, '2025-08-11', 'obito', 'Óbito em 11/08/2025, 48 horas após parada cardíaca por fibrilação ventricular em cardiopatia chagásica avançada (FEVE 31%, TV não sustentada), com encefalopatia anóxica irreversível. CDI estava solicitado desde março e não havia sido implantado por falta de vaga.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (398, 'Thiago Nishimura Pavani', 'M', '2001-05-17', 'Cianorte', 'PR', 'Estudante de educação física', 'Saudável, joga futebol amador três vezes por semana. Crises de palpitações súbitas desde os 15 anos, duração de minutos. Nega drogas. Tio materno com marca-passo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1346, 398, 4, '2024-10-07 14:00', 'consulta', 'Tenho crises de coração disparado que começam sozinhas', 118, 72, 74, 74.0, 'Paciente de 23 anos com crises de palpitação de início e fim súbitos, FC contada em 190-200, duração de 5 a 40 minutos, duas vezes ao mês, uma delas durante partida de futebol com tontura e quase-síncope. Ao exame normal. ECG de repouso: ritmo sinusal com PR curto (100 ms) e onda delta em parede inferior e V4-V6. ECO normal. Holter: episódios curtos de taquicardia regular 188. HD: síndrome de Wolff-Parkinson-White com taquicardia por reentrada atrioventricular sintomática.', 'Evitar esportes de competição até o tratamento. Indicado estudo eletrofisiológico com ablação da via acessória, pois evita risco de FA pré-excitada. Evitar digoxina, verapamil e amiodarona na crise. Manobras vagais orientadas. Programar procedimento.'),
  (1347, 398, 4, '2024-11-18 07:30', 'internacao', 'Vim para a ablação', 122, 74, 68, 73.8, 'Estudo eletrofisiológico sob sedação: via acessória atrioventricular de condução anterógrada e retrógrada, localizada em parede posteroseptal direita, com período refratário anterógrado de 260 ms. Induzida taquicardia ortodrômica a 190 bpm. Ablação por radiofrequência com desaparecimento da onda delta em 3 segundos e bloqueio da via. Reteste com isoproterenol sem condução anterógrada ou reentrada. Sem complicações. Alta no mesmo dia.', 'Sem medicação. Evitar esforço por 1 semana. Retorno em 3 meses com ECG e Holter. Liberação para exercício após 7 dias, jogos após consulta de retorno.'),
  (1348, 398, 4, '2025-02-10 14:10', 'retorno', 'Voltei a jogar e não tive mais crise', 116, 70, 62, 74.5, 'Quase 3 meses após a ablação, sem palpitações, jogando futebol duas vezes por semana sem queixas. ECG de repouso: PR 148 ms, sem onda delta. Holter: ritmo sinusal, FC média 70, sem taquicardias. Ao exame normal, sem sopros. HD: WPW tratada com ablação da via acessória, sem recorrência.', 'Alta do ambulatório de arritmia. Liberado para atividade esportiva sem restrições. Retornar se voltar a ter palpitações. Não há necessidade de medicamentos.');
