insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (398, '2025-02-10', 'controlado', 'Síndrome de Wolff-Parkinson-White com taquicardias recorrentes, curada por ablação por radiofrequência da via acessória posteroseptal direita. Sem recorrência em 3 meses, ECG sem onda delta e liberado para o futebol.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (399, 'Lourdes Camargos Bittencourt', 'F', '1962-02-24', 'Brasília', 'DF', 'Servidora pública aposentada', 'Valva aórtica bicúspide conhecida, com estenose leve em acompanhamento irregular. Fez extração dentária há 6 semanas sem profilaxia antibiótica. HAS controlada com losartana 50 mg. Nega uso de drogas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1349, 399, 6, '2025-06-16 11:20', 'pronto_socorro', 'Febre há quatro semanas, suores à noite e cansaço', 118, 52, 104, 58.4, 'Pcte de 63 anos, febre vespertina de 38-38,8 °C há 4 semanas, sudorese noturna, perda de 5 kg, astenia e dispneia progressiva. Ao exame: pálida, febril 38,4 °C, taquicárdica, sopro diastólico aórtico novo 3+/6+ e sopro sistólico de ejeção, pulsos amplos (PA divergente 118x52), hemorragias em lasca em unhas, baço palpável. Hb 9,8 g/dL, leucocitose 13.200, PCR 96. 3 de 3 hemoculturas com cocos Gram-positivos em cadeia. HD: endocardite infecciosa de valva aórtica bicúspide, por Streptococcus provável pós-dentário, com insuficiência aórtica.', 'Internar na cardiologia. Ceftriaxona 2 g EV 1x/dia associada a gentamicina enquanto aguarda identificação. ETE urgente para vegetações e abscesso. Avaliação de cirurgia cardíaca se IC, abscesso ou embolia. Solicitar colonoscopia depois se S. gallolyticus.'),
  (1350, 399, 2, '2025-06-17 10:00', 'internacao', 'Dia 1 de internação', 112, 48, 98, 58.0, 'ETE: valva aórtica bicúspide com vegetação de 14 mm em cúspide coronariana direita, perfuração da cúspide e regurgitação aórtica importante, sem abscesso perianular. Hemocultura identificou Streptococcus gallolyticus (bovis). Creatinina 1,0. Sem sinais de embolia periférica, TC de crânio sem lesões. Início de dispneia em repouso a partir de hoje, SpO2 94%, estertores nas bases. HD: endocardite por S. gallolyticus em valva bicúspide com IAo grave e início de IC.', 'Suspender gentamicina (agente sensível a penicilina), manter ceftriaxona 2 g/dia por 4-6 semanas. Furosemida 40 mg EV e vasodilatador cuidadoso. Colonoscopia após estabilização pela associação com neoplasia colorretal. Reunir equipe cardiológica e de infectologia; cirurgia valvar urgente se IC progredir.'),
  (1351, 399, 12, '2025-06-30 09:00', 'internacao', 'Dia 14 de antibiótico, piora da falta de ar', 102, 38, 110, 60.1, 'Apesar de 14 dias de ceftriaxona e febre resolvida, evolui com IC refratária por regurgitação aórtica grave, dispneia em repouso e necessidade de O2 a 3 L/min. ETE de controle: vegetação 11 mm, IAo importante, VE dilatado (DDVE 68 mm), sem abscesso. Colonoscopia: pólipo adenomatoso séssil de 18 mm em cólon ascendente com displasia de alto grau, retirado. PA diferencial 102x38. HD: endocardite aórtica com IAo grave e IC refratária, indicação cirúrgica por Classe I.', 'Indicada troca valvar aórtica em tempo hábil. O serviço local não dispõe de equipe para a cirurgia valvar no momento; solicitada transferência para o hospital de referência em cirurgia cardíaca, com antibiótico mantido. Transporte em UTI móvel e documentação anexada. Furosemida e vasodilatador de acordo com PA.');
