insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (399, '2025-07-04', 'transferido', 'Endocardite por S. gallolyticus em valva aórtica bicúspide com insuficiência aórtica grave e IC refratária ao tratamento clínico, em antibiótico há 14 dias. Transferida em UTI móvel para hospital de referência em cirurgia cardíaca para troca valvar; pólipo colônico com displasia de alto grau já ressecado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (400, 'Cíntia Mendonça Zanchet', 'F', '1980-01-30', 'Pato Branco', 'PR', 'Representante comercial', 'Obesidade grau I e uso de anticoncepcional oral combinado há 8 anos. Viagem de ônibus de 14 horas há 6 dias. Não fuma. Sem história prévia de trombose. Mãe com trombose venosa profunda aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1352, 400, 6, '2025-09-02 18:10', 'pronto_socorro', 'Falta de ar súbita e dor no lado do peito ao respirar', 118, 74, 112, 88.0, 'Pcte de 45 anos, dispneia de início agudo há 2 dias e dor torácica pleurítica à direita, com 1 episódio de síncope hoje. Perna direita edemaciada e dolorida na panturrilha há 4 dias. Ao exame: taquipneica, SpO2 90% em ar ambiente, FC 112, PA 118x74, panturrilha D com empastamento e diferença de 3 cm. ECG: taquicardia sinusal, padrão S1Q3T3. D-dímero 4.800 ng/mL, troponina 0,09, BNP 420. Angio-TC: TEP bilateral em artérias pulmonares lobares e segmentares, relação VD/VE 1,1. Score de Wells alto. HD: TEP de risco intermediário-alto (PESI), TVP de MID.', 'O2 suplementar, anticoagulação plena com enoxaparina 1 mg/kg 12/12h. Sem trombólise, por estabilidade hemodinâmica. Monitorização contínua e troponina seriada. Internação na unidade intensiva por 24h. Doppler venoso de MMII. Suspensão do anticoncepcional.'),
  (1353, 400, 14, '2025-09-03 09:00', 'internacao', 'Dia 1 de internação, ainda com dor ao respirar', 122, 76, 92, 87.6, 'Estável hemodinamicamente, sem necessidade de vasopressor, SpO2 95% com cateter nasal 2 L/min. Troponina em queda (0,04). ECO: VD discretamente dilatado, sem disfunção sistólica significativa (TAPSE 19 mm), PSAP 42 mmHg. Doppler venoso: trombose de veia poplítea e femoral superficial direitas. Plaquetas e creatinina normais. HD: TEP bilateral de risco intermediário, melhorando com anticoagulação.', 'Transição para rivaroxabana 15 mg 12/12h por 21 dias e depois 20 mg 1x/dia. Alta no 4º dia com orientação. Estudo de trombofilia não é necessário no momento (fator desencadeante evidente). Meias elásticas, deambulação e hidratação. Retorno em 4 semanas.'),
  (1354, 400, 1, '2025-12-10 16:30', 'retorno', 'Respiro bem, só um cansaço leve nas escadas', 122, 78, 74, 84.0, 'Três meses do TEP. Sem sangramentos, tomando rivaroxabana 20 mg corretamente. Dispneia leve só em subida longa. Perna direita com discreta dor residual ao fim do dia. ECO: PSAP 32 mmHg, VD normal. Cintilografia V/Q sem defeitos de perfusão persistentes. Anticoncepcional suspenso; usa DIU de cobre. Ao exame: sem edema, panturrilhas livres, SpO2 98%. HD: TEP provocado (viagem longa, estrogênio, obesidade), boa evolução.', 'Manter rivaroxabana por mais 3 meses completando 6 meses, depois suspender (fatores desencadeantes transitórios). Estimular atividade física e perda de peso. Evitar estrogênio para sempre. Orientada sobre profilaxia em viagens longas. Retorno em 3 meses.'),
  (1355, 400, 1, '2026-03-11 16:40', 'retorno', 'Concluí os seis meses, sem sintomas', 120, 76, 70, 80.5, 'Seis meses de anticoagulação completos. Sem dispneia e sem dor na perna, caminha 5 km. Perdeu 7 kg. Doppler venoso: recanalização parcial das veias poplítea e femoral, sem trombo agudo. Sem sangramentos. Ao exame: sem edema, sem sinais de síndrome pós-trombótica. HD: TEP e TVP provocados, tratados por 6 meses, sem sequelas hemodinâmicas.', 'Suspender rivaroxabana. Manter DIU e evitar estrogênio. Profilaxia com meias e deambulação em viagens longas. Orientada a procurar o PS em caso de dispneia ou edema unilateral. Alta do ambulatório, retorno SN.');
