insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (400, '2026-03-11', 'melhorou', 'TEP bilateral de risco intermediário com TVP de MID, provocado por viagem prolongada, estrogênio e obesidade, tratado com anticoagulação por 6 meses. Sem sequelas, ECO normal, recanalização venosa parcial, perdeu 7 kg e alta do ambulatório com DIU e anticoagulante suspenso.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (401, 'Wellington Cássio Brandão Moura', 'M', '1977-05-12', 'Goiânia', 'GO', 'Motorista de aplicativo', 'Sem diagnóstico prévio de hipertensão, nunca mediu a pressão de rotina. Trabalha 12 horas por dia sentado, come em lanchonetes e toma refrigerante diariamente. Pai hipertenso, infartou aos 61 anos. Sedentário, não fuma, bebe cerveja nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1356, 401, 5, '2023-03-06 18:20', 'consulta', 'Medi a pressão na farmácia e deu alta', 152, 96, 80, 98.6, 'Homem de 45 anos, motorista de aplicativo, procurou a unidade após aferição de 156x98 na farmácia. Assintomático, nega cefaleia, dor torácica ou dispneia. IMC 32. Circunferência abdominal 109 cm. Ao exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, sem edemas. PA em duas medidas, sentado, 152x96 e 150x94 mmHg. HD: hipertensão estágio 1 a confirmar com medidas fora do consultório, obesidade, provável síndrome metabólica.', 'Solicitado MRPA por 5 dias, exames de rotina e ECG. Orientado a reduzir sal, trocar o refrigerante por água e fazer caminhadas de 30 minutos 5x por semana mesmo nos intervalos entre corridas. Retorno em 6 semanas com o diário da pressão.'),
  (1357, 401, 5, '2023-04-17 18:45', 'retorno', 'Trouxe o caderninho da pressão', 148, 92, 78, 97.2, 'Retorna com MRPA completo: média de 31 medidas 147x91 mmHg, confirmando hipertensão. Conseguiu reduzir o refrigerante, mas diz que a rotina de aplicativo impede caminhar: ''só paro para o banheiro''. Perdeu 1,4 kg. Exames: potássio 4,3, ácido úrico 6,8 mg/dL, sem proteinúria. Sem lesão de órgão-alvo evidente. Aceita iniciar medicação após conversa sobre o risco familiar.', 'Iniciar losartana 50 mg 1x ao dia. Manter MEV, reduzir sal, combinar com a esposa a caminhada após o jantar. Reavaliar PA e função renal com potássio em 30 dias. Orientado a não interromper se a pressão normalizar.'),
  (1358, 401, 5, '2023-07-24 19:00', 'retorno', 'Vim ver se a pressão normalizou', 128, 78, 72, 93.0, 'Pcte em uso regular de losartana 50 mg, sem tosse, sem tontura. Perdeu 5,6 kg desde a primeira consulta, passou a levar marmita e caminha 40 minutos à noite. MRPA domiciliar com média 126x77. Potássio 4,5 e creatinina 0,9 após o início do BRA. Ao exame: PA 128x78, RCR 2T BNF, sem edemas. PA na meta.', 'Manter losartana 50 mg. Reforçar meta de perda de peso para 88 kg. Repetir perfil lipídico em 3 meses; LDL será reavaliado com estratificação de risco. Retorno semestral.');
