insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (401, '2023-07-24', 'controlado', 'Hipertensão estágio 1 diagnosticada com MRPA, tratada com losartana 50 mg e mudança de estilo de vida. Perdeu quase 6 kg, mantém PA em 126x77 em casa e segue em acompanhamento semestral na atenção primária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (402, 'Raimunda Neuza Ferraz de Albuquerque', 'F', '1966-09-03', 'Ceilândia', 'DF', 'Auxiliar de limpeza', 'HAS há 9 anos e DM2 há 6 anos, em uso de metformina e losartana. Nunca fez dosagem de albuminúria. Mãe diabética e dialítica. Não fuma. Trabalha em escola e pega dois ônibus para ir ao serviço.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1359, 402, 1, '2022-08-15 08:30', 'consulta', 'Médica do posto mandou eu vir por causa do rim', 158, 94, 82, 79.5, 'Pcte de 55 anos, HAS e DM2, encaminhada da UBS por albuminúria em exame de rotina. Refere esquecer o comprimido da tarde com frequência. Assintomática. Ao exame: BEG, RCR 2T BNF, sem sopros, MV+ sem RA, edema de tornozelos 1+/4+. PA 158x94. HbA1c 8,1%, relação albumina/creatinina 186 mg/g em duas amostras, creatinina 1,0 mg/dL. HD: HAS não controlada com lesão renal incipiente por nefropatia diabética e hipertensiva.', 'Losartana ajustada para 100 mg em dose única pela manhã, para facilitar a adesão. Adicionar anlodipino 5 mg. Orientada restrição de sal. Encaminhar à endocrinologia para otimizar o diabetes. Controle de creatinina e potássio em 3 semanas.'),
  (1360, 402, 9, '2022-10-03 09:10', 'retorno', 'Vim mostrar os exames do açúcar', 142, 86, 78, 78.2, 'Paciente retorna após ajuste do anti-hipertensivo, sem tosse, com leve edema vespertino de tornozelos que atribui ao anlodipino. Creatinina 1,0 e potássio 4,7 estáveis. HbA1c ainda 7,9% e RAC 142 mg/g. Relata tomar o remédio de manhã sem falhas desde que ficou em dose única. Discutido risco renal e cardiovascular da diabetes com albuminúria.', 'Associar dapagliflozina 10 mg pela manhã pelo benefício renal e cardiovascular, orientada sobre higiene genital e hidratação. Manter metformina. Reforçar dieta com nutricionista da UBS. Repetir RAC, creatinina e potássio em 90 dias.'),
  (1361, 402, 1, '2023-05-22 08:50', 'retorno', 'Estou me sentindo bem, só vim buscar receita', 126, 76, 74, 75.8, 'Retorno de 7 meses. Sem queixas, sem infecção urinária ou candidíase. Perdeu 3,7 kg. HbA1c 6,9%, RAC caiu para 54 mg/g, creatinina 1,0 mg/dL com TFGe 62 (queda inicial esperada com iSGLT2 estabilizada). Potássio 4,8 mEq/L. PA na meta. Edema discreto, sem repercussão. Aderência ótima com a receita em dose única matinal.', 'Manter esquema atual. Dosar RAC, creatinina e potássio a cada 4 meses. Consulta anual com oftalmologista para fundo de olho e avaliação dos pés. Manter metas de PA abaixo de 130x80.');
