insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (402, '2023-05-22', 'melhorou', 'Albuminúria reduziu de 186 para 54 mg/g com losartana em dose máxima, anlodipino e dapagliflozina. PA 126x76 e HbA1c 6,9%. Segue em acompanhamento com monitorização renal a cada 4 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (403, 'Sandra Mara Pimenteira Dutra', 'F', '1971-02-18', 'Rio Verde', 'GO', 'Cozinheira de restaurante', 'HAS há 10 anos, encaminhada como hipertensão ''que não baixa com nada''. Em uso prescrito de losartana, anlodipino e hidroclorotiazida. Obesidade grau I. Nega tabagismo. Mora com a filha adolescente, faz jornadas de 11 horas na cozinha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1362, 403, 2, '2023-01-09 14:00', 'consulta', 'Tomo três remédios e a pressão continua nas alturas', 178, 108, 84, 88.3, 'Pcte de 51 anos, encaminhada por HAS resistente. Diz tomar losartana 100, anlodipino 10 e hidroclorotiazida 25 mg. Ao detalhar a rotina: toma ''quando lembra'', geralmente só quando sente cefaleia, e a caixa do anlodipino está quase cheia. Chegou sem tomar os comprimidos hoje. Refere gasto com remédios por conta de pagar convênio de saúde. PA 178x108 (manguito adequado, 3 medidas). Exame cardiovascular sem alterações. Suspeita de pseudorresistência por má adesão.', 'Não escalar o tratamento. Esquema mantido, com reforço de que a medicação é contínua. Combinada caixa organizadora semanal e alarme no celular. Solicitados exames de rotina, ECG e dosagem de aldosterona/renina por ser suspeita de resistência. Retorno em 6 semanas trazendo as caixas dos remédios.'),
  (1363, 403, 2, '2023-02-20 14:20', 'retorno', 'Vim mostrar as caixinhas, estou tomando direitinho', 138, 84, 76, 87.5, 'Retorna com as três caixas e o organizador semanal, que a filha passou a preencher aos domingos. Adesão confirmada, apenas dois esquecimentos em 6 semanas. PA 138x84 sem alteração de dose, confirmando pseudorresistência. Relação aldosterona/renina normal e potássio normal. Refere desconforto por edema leve de tornozelos, aceitável. Sem cefaleia.', 'Manter losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg, sem mudança. Solicitado MAPA 24h para confirmar controle. Retorno em 3 meses. Orientadas fontes de sódio escondidas na cozinha (caldos e temperos prontos).'),
  (1364, 403, 2, '2023-06-12 15:00', 'retorno', 'Trouxe o exame da pressão de 24 horas', 124, 76, 72, 85.1, 'MAPA de 24h: média 122x74 mmHg nas 24h, vigília 126x77, sono 114x67 com descenso preservado. Controle adequado com três drogas tomadas de forma regular. Perdeu 3,2 kg. PA de consultório 124x76. Mantém organizador semanal e relata que a filha lembra nas viagens. Nega cefaleia.', 'Controle confirmado, mantém esquema. Futuramente, com perda de peso adicional, tentar retirar um dos fármacos. Retorno em 6 meses com creatinina e potássio. Orientada a trazer a receita para renovação anual.');
