insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (403, '2023-06-12', 'controlado', 'Pseudorresistência por má adesão, resolvida com organizador semanal e apoio da filha. MAPA confirmou controle com média de 122x74 mmHg, sem necessidade de escalonar o tratamento nem de espironolactona.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (404, 'Odair Hideki Takahashi', 'M', '1984-07-29', 'Sinop', 'MT', 'Operador de colheitadeira', 'HAS diagnosticada aos 36 anos, em uso de losartana e anlodipino, com PA sempre acima de 150x95. Cãibras frequentes e fraqueza nas pernas no fim do dia. Não fuma, não bebe. Pai hipertenso, falecido de AVC hemorrágico aos 58 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1365, 404, 1, '2022-05-10 10:20', 'consulta', 'Pressão alta aos 37 anos e muita câimbra', 168, 104, 70, 79.0, 'Homem de 37 anos, hipertensão estágio 2 desde os 36, refratária a losartana 100 mg/dia mais anlodipino 10 mg. Cãibras e fraqueza proximal, poliúria noturna. Sem edemas, sem sopros. Potássio 3,1 mEq/L sem uso de diurético. Paciente jovem com hipocalemia espontânea e HAS resistente: rastrear hiperaldosteronismo primário.', 'Suspender losartana por 2 semanas (interfere no teste) e manter anlodipino mais doxazosina quando necessário, repor potássio. Coletar aldosterona e renina. Solicitar TC de adrenais. Retorno com resultados em 3 semanas.'),
  (1366, 404, 9, '2022-07-19 09:00', 'retorno', 'Vim ver o resultado do cateterismo das adrenais', 162, 100, 68, 78.4, 'Razão aldosterona/renina muito elevada, com teste confirmatório por infusão salina positivo (aldosterona pós-infusão 14 ng/dL). TC mostra adenoma de 1,6 cm à esquerda. Por idade abaixo de 35 anos não seria obrigatório, mas dado que tem adenoma e hipocalemia espontânea optamos por cateterismo de veias adrenais, que lateralizou para a esquerda (índice de lateralização 6,2). Discutida cirurgia curativa.', 'Indicada adrenalectomia esquerda laparoscópica. Pré-operatório com espironolactona 50 mg/dia por 4 semanas para corrigir potássio, monitorar K e creatinina. Encaminho para cirurgia de adrenal. Retorno logo após a cirurgia.'),
  (1367, 404, 9, '2022-11-28 10:00', 'retorno', 'Operei e estou sem remédio, vim conferir', 124, 78, 66, 80.3, 'Adrenalectomia esquerda laparoscópica há 7 semanas, sem intercorrências. Histopatológico: adenoma cortical. Suspensas espironolactona e suplemento de potássio no pós-operatório imediato; potássio manteve-se normal. Sem câimbras, fraqueza resolvida. Hoje PA 124x78 sem nenhum anti-hipertensivo. Potássio 4,4, aldosterona 6 ng/dL com renina normalizada.', 'Cura bioquímica e clínica. Suspender anlodipino com monitorização domiciliar por 2 semanas. Reavaliar potássio e PA em 6 meses e depois anualmente. Orientado a avisar se houver recorrência de cãibras.');
