insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (404, '2022-11-28', 'controlado', 'Hiperaldosteronismo primário por adenoma esquerdo tratado com adrenalectomia laparoscópica. PA normal e potássio normal sem nenhum medicamento, caracterizando cura clínica e bioquímica. Segue com revisão anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (405, 'Jair Wanderley Soares Pinheiro', 'M', '1969-11-08', 'Araguaína', 'TO', 'Caminhoneiro', 'HAS há 6 anos em uso de losartana 50 mg 12/12h, mas interrompeu há 3 semanas por falta de dinheiro e porque ''estava na estrada''. Tabagista de 15 cigarros/dia. Dorme pouco, come em postos de beira de estrada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1368, 405, 6, '2024-02-14 04:10', 'pronto_socorro', 'Dor de cabeça fraca e pressão 220 no posto', 214, 124, 88, 96.0, 'Pcte 54 anos, caminhoneiro, chega de madrugada por PA 220x120 aferida em posto. Refere cefaleia occipital leve, sem alteração visual, dor torácica, dispneia ou déficit neurológico. Sem uso de losartana há 3 semanas. Ao exame: BEG, RCR 2T BNF sem sopros, MV+ sem RA, neuro sem déficit focal, fundo de olho sem papiledema. ECG sem isquemia aguda. Troponina negativa. Creatinina normal. HD: urgência hipertensiva sem lesão aguda de órgão-alvo.', 'Repouso por 2h, reintrodução de anti-hipertensivo oral, sem queda abrupta da PA. Após 2h, PA 176x102. Alta com losartana 50 mg 12/12h e anlodipino 5 mg, orientado retorno ambulatorial em 14 dias, retorno ao PS se cefaleia intensa, déficit ou dor no peito.'),
  (1369, 405, 2, '2024-02-28 08:40', 'retorno', 'Voltei como o doutor do plantão mandou', 148, 92, 80, 95.2, 'Retorna após alta do PS. Tomando losartana e anlodipino todos os dias, retirados na farmácia popular. Sem cefaleia. Entende que a pressão não pode ficar sem remédio durante as viagens e pegou duas caixas extras. Ecocardiograma: HVE leve, FEVE 62%. Perfil lipídico com LDL 158. Ainda tabagista, 10 cigarros/dia. PA 148x92, ainda acima da meta.', 'Associar clortalidona 12,5 mg pela manhã. Troca para losartana 100 mg em dose única pela manhã para facilitar nas viagens. Orientada cessação do tabagismo, oferecida terapia de reposição de nicotina. Dosar potássio e sódio em 2 semanas.'),
  (1370, 405, 2, '2024-05-23 08:20', 'retorno', 'Estou bem, parei de fumar', 128, 78, 70, 93.4, 'Retorno de 3 meses. Parou de fumar há 6 semanas com adesivo de nicotina, orgulhoso. MRPA com média de 126x77 mmHg. Sódio 140 e potássio 4,2 mEq/L após início da clortalidona. Sem cefaleia, sem sintomas ao exame. Perdeu 1,8 kg. Compra comida em marmitex e leva o aparelho de pressão na cabine.', 'Manter losartana 100 mg, anlodipino 5 mg e clortalidona 12,5 mg. Iniciar atorvastatina 20 mg pelo LDL 158 e risco elevado. Retorno em 6 meses; reforçado que nunca deve parar o remédio por falta de rotina.');
