insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (405, '2024-05-23', 'controlado', 'Urgência hipertensiva por interrupção da losartana, sem lesão de órgão-alvo aguda. Com esquema de três drogas, estatina e cessação do tabagismo, mantém PA em 126x77 no domiciliar e segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (406, 'Aline Cristiane Vasconcellos Dias', 'F', '1996-03-11', 'Palmas', 'TO', 'Professora do ensino fundamental', 'Primeira gestação, 32 semanas na primeira avaliação do nosso serviço. Sem HAS prévia. Mãe teve pré-eclâmpsia. IMC pré-gestacional 29. Não fuma, não bebe.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1371, 406, 7, '2025-05-26 09:00', 'consulta', 'Inchaço nas pernas e pressão alta no pré-natal', 148, 96, 88, 83.5, 'Gestante de 29 anos, G1P0, 32 semanas, com PA 148x96 em duas aferições com 4h de intervalo na UBS. Edema de membros inferiores 2+/4+, sem cefaleia, epigastralgia ou escotomas. Fundo uterino compatível, BCF 142 bpm, movimentação fetal presente. Proteinúria de 24h 0,6 g. Plaquetas 168.000, TGO 28, TGP 24, creatinina 0,7. HD: pré-eclâmpsia sem sinais de gravidade.', 'Iniciar metildopa 250 mg 8/8h e AAS 100 mg. Dopplers obstétricos e perfil biofísico semanais. Reavaliação em 1 semana com exames de laboratório para pré-eclâmpsia. Orientados sinais de alarme: dor epigástrica, cefaleia forte, alteração visual.'),
  (1372, 406, 7, '2025-06-12 03:10', 'internacao', 'Dor forte na boca do estômago e vista turva', 176, 112, 102, 85.0, '34 semanas. Chega ao PS obstétrico de madrugada com epigastralgia em barra há 6h, náuseas, vista turva e mal-estar. PA 176x112 confirmada. Reflexos vivos, sem clônus. Laboratório: plaquetas 72.000, TGO 410, TGP 360, LDH 1.100, bilirrubina indireta 2,1, creatinina 1,0, haptoglobina baixa. Diagnóstico de síndrome HELLP. BCF 120 bpm com desacelerações tardias.', 'Sulfato de magnésio (esquema Zuspan) para neuroproteção, nifedipino de ação rápida via oral e hidralazina EV se necessário para PAS ≥ 160. Corticoide fetal iniciado. Indicada interrupção imediata: cesariana sob raquianestesia após plaquetas > 50.000. RN 2.050 g, Apgar 7/9, encaminhado à UTI neonatal. Mãe observada em UTI 24h.'),
  (1373, 406, 7, '2025-06-30 10:00', 'retorno', 'Estou me sentindo bem, mas a pressão não abaixou', 150, 96, 84, 76.4, 'Retorno puerperal de 18 dias. Alta hospitalar no 4º dia, plaquetas normalizadas (214.000), TGO 38. Ferida operatória sem sinais flogísticos. Amamentando bebê que saiu da UTI neonatal. PA domiciliar entre 144x92 e 154x98 sob nifedipino. Sem cefaleia ou sintomas visuais. Perdeu 8,6 kg desde o parto.', 'Introduzir enalapril 10 mg 12/12h, compatível com amamentação, e retirar nifedipino. Dosar creatinina e potássio em 2 semanas. Contracepção sem estrogênio (DIU de cobre ou progestágeno isolado). Encaminhada à cardiologia para investigar hipertensão persistente pós-HELLP.'),
  (1374, 406, 1, '2025-10-08 08:30', 'retorno', 'Quero saber se vou ter pressão alta pra sempre', 124, 78, 72, 72.0, 'Quatro meses após HELLP. Bebê saudável, 4 kg, em aleitamento. PA 124x78 com enalapril. Creatinina 0,7 e potássio 4,3. Proteinúria de 24h 0,08 g. Refere preocupação por futuras gestações e risco cardiovascular aumentado. Perfil lipídico e glicemia normais. Fez DIU de cobre há 2 meses.', 'Manter enalapril por enquanto, reavaliar desmame em 6 meses com MRPA. Orientada sobre risco de recorrência em nova gestação e profilaxia com AAS 100 mg a partir de 12 semanas e cálcio. Seguimento cardiológico anual pelo risco cardiovascular elevado pós-pré-eclâmpsia.');
