insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (407, '2025-03-20', 'melhorou', 'IAMCSST anterior tratado com angioplastia primária e stent farmacológico em DA. Recuperou FEVE de 45% para 52%, abandonou o tabagismo, completou reabilitação cardiovascular e retornou ao trabalho. Segue em prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (408, 'Edvaldo Gomes de Lacerda Neto', 'M', '1958-12-04', 'Campina Grande', 'PB', 'Pedreiro aposentado', 'IAM prévio em 2018 com ATC em DA, HAS e diabetes tipo 2. ICFEr diagnosticada há 1 ano, em uso de enalapril, carvedilol e furosemida. Ex-tabagista (40 maços-ano, parou em 2018). Mora sozinho, filha vive em outra cidade.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1379, 408, 11, '2023-02-13 10:30', 'consulta', 'Cansaço para andar até a padaria', 118, 74, 74, 76.4, 'Pcte de 64 anos com ICFEr isquêmica (FEVE 28% em 2022), CF NYHA III. Dispneia aos pequenos esforços, ortopneia com dois travesseiros, sem DPN, edema discreto 1+/4+. Em uso de enalapril 10 mg 12/12h, carvedilol 12,5 mg 12/12h e furosemida 40 mg. Falta espironolactona e iSGLT2. Creatinina 1,2, potássio 4,5. NT-proBNP 2.400 pg/mL. ECO: FEVE 28%, VE dilatado, IM moderada funcional.', 'Associar espironolactona 25 mg/dia e dapagliflozina 10 mg/dia, mantendo enalapril, carvedilol e furosemida. Orientado peso diário e restrição de sal a 2 g. Exames de potássio e creatinina em 7 e 30 dias. Retorno em 8 semanas para avaliar troca por sacubitril/valsartana.'),
  (1380, 408, 11, '2023-04-24 10:00', 'retorno', 'Estou melhor, mas ainda canso', 112, 70, 68, 73.8, 'Retorno de 10 semanas. Perdeu 2,6 kg de líquido, ortopneia resolvida, sem edemas. CF NYHA II-III. Potássio 5,1 mEq/L e creatinina 1,3 após espironolactona, sem hipercalemia grave. PA 112x70 tolerável. Paciente sem tontura. Passou 36 horas sem enalapril para entrada do sacubitril/valsartana, como combinado, sem intercorrências.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h, após pausa de 36h do IECA. Manter carvedilol, espironolactona 25 mg, dapagliflozina e furosemida. Dosar potássio e creatinina em 10 dias. Evitar dieta rica em potássio e substitutos de sal.'),
  (1381, 408, 11, '2023-09-18 09:30', 'retorno', 'Voltei a ajudar o vizinho na obra', 108, 66, 64, 72.0, 'Após 5 meses de quatro pilares, CF NYHA I-II. Caminha 3 km, voltou a ajudar em pequenos serviços de obra. Sem hipotensão sintomática, sem hipercalemia. NT-proBNP caiu para 900. ECO: FEVE 36%, VE menos dilatado, IM leve. Sacubitril/valsartana titulado para 49/51 mg 12/12h há 2 meses. Dapagliflozina tolerada. Sem infecção genital.', 'Manter quatro pilares. Reduzir furosemida para 20 mg e usar 40 mg se ganho de peso > 2 kg em 3 dias. Tentar chegar a sacubitril/valsartana 97/103 mg se PAS > 100. ECO em 6 meses; avaliar CDI se FEVE permanecer ≤ 35% após 3 meses de terapia otimizada.');
