insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (408, '2023-09-18', 'melhorou', 'ICFEr isquêmica com melhora de CF NYHA III para I-II após otimização dos quatro pilares. FEVE subiu de 28% para 36% e NT-proBNP caiu de 2.400 para 900 pg/mL. Segue em titulação e reavaliação para CDI.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (409, 'Ilse Margarete Kowalczyk Stein', 'F', '1951-06-17', 'Passo Fundo', 'RS', 'Agricultora aposentada', 'HAS há 25 anos em uso de losartana e hidroclorotiazida. Nega diabetes. Hipotireoidismo tratado com levotiroxina. Sem tabagismo. Neta mora com ela. Mãe teve AVC aos 80 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1382, 409, 2, '2022-10-03 10:00', 'consulta', 'Coração dispara e fico cansada para ordenhar', 138, 84, 112, 68.0, 'Mulher de 71 anos com palpitações há 3 semanas, episódios de duração prolongada, cansaço aos esforços e sensação de peso no peito. Sem síncope. ECG: fibrilação atrial com resposta ventricular de 112 bpm, sem sinais de isquemia. RCR irregular, sem sopros. TSH 2,1. CHA2DS2-VASc 3 (idade 65-74, sexo feminino, HAS). HAS-BLED 1.', 'Iniciar apixabana 5 mg 12/12h (idade < 80, peso > 60, creatinina < 1,5). Metoprolol succinato 50 mg/dia para controle de frequência. ECO transtorácico e exames de rotina. Orientado sobre sangramentos e interações. Retorno em 4 semanas.'),
  (1383, 409, 2, '2022-11-21 10:30', 'retorno', 'Estou melhor do coração, só um pouco de tontura', 124, 72, 72, 67.4, 'Retorna com FC bem controlada, 72 bpm, ainda em FA. Tontura leve ao levantar, sem síncope; PA 124x72 sentada e 112x68 em pé. ECO: átrio esquerdo 46 mm, FEVE 60%, sem valvopatia significativa. Creatinina 0,9, Hb 13,4. Sem sangramentos com apixabana. Optado por estratégia de controle de frequência pela idade e pouca sintomatologia.', 'Manter apixabana e metoprolol. Suspender hidroclorotiazida por queda de PA postural, manter losartana. Orientada hidratação e levantar devagar. Retorno em 6 meses com hemograma e creatinina anuais para ajuste de dose.'),
  (1384, 409, 2, '2023-11-06 09:50', 'retorno', 'Controle anual do coração', 126, 74, 70, 66.9, 'Retorno de um ano. Assintomática, ordenha as vacas pela manhã e cuida da horta. Sem sangramentos, sem equimoses. FA permanente com FC 70 bpm. Hb 13,1, creatinina 0,9 mg/dL, TFGe 66. Sem tontura. Neta ajuda a organizar a medicação semanal. Adesão ao anticoagulante excelente.', 'Manter apixabana 5 mg 12/12h, metoprolol e losartana. Hemograma e creatinina anuais. Orientada a avisar antes de procedimentos odontológicos. Retorno em 12 meses ou antes se palpitações, sangramento ou sintomas neurológicos.');
