insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (409, '2023-11-06', 'controlado', 'Fibrilação atrial permanente com controle de frequência adequado e anticoagulação com apixabana sem eventos hemorrágicos ou embólicos. Paciente ativa, com boa adesão, em acompanhamento anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (410, 'Álvaro Augusto Peçanha Lins', 'M', '1946-04-02', 'Niterói', 'RJ', 'Engenheiro naval aposentado', 'HAS há 30 anos controlada, dislipidemia em uso de rosuvastatina. Sopro cardíaco conhecido há anos, nunca investigado. Caminha todos os dias na orla, mas vem reduzindo o ritmo. Viúvo, mora com a filha mais nova.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1385, 410, 2, '2023-05-22 09:00', 'consulta', 'Quase desmaiei subindo a rampa da garagem', 126, 70, 72, 74.5, 'Homem de 77 anos com dispneia aos médios esforços e episódio de pré-síncope ao subir rampa há 2 semanas. Refere aperto torácico leve. Ao exame: sopro sistólico ejetivo 4+/6+ em foco aórtico irradiado para carótidas, B2 hipofonética, pulso parvus et tardus. Eco: estenose aórtica grave, área valvar 0,7 cm², gradiente médio 52 mmHg, Vmax 4,6 m/s, FEVE 55%. Escore STS 3,8%.', 'Indicação de intervenção valvar pela sintomatologia. Encaminhado ao Heart Team. Solicitada angiotomografia para planejamento de TAVI e cineangiocoronariografia. Evitar esforços físicos intensos. Suspender anti-hipertensivo que cause hipotensão excessiva. Retorno após exames.'),
  (1386, 410, 10, '2023-08-14 07:30', 'internacao', 'Internação eletiva para implante de válvula', 132, 72, 68, 74.0, 'Heart Team indicou TAVI (idade, anatomia favorável: anel 24 mm, acessos ilíacos adequados). CATE: coronárias sem lesões significativas. Internado para TAVI transfemoral com prótese balonável 26 mm sob sedação. Procedimento sem intercorrências, sem vazamento paravalvar relevante, sem BAV novo. Gradiente residual 8 mmHg. Extubado na sala. Alta no 3º dia.', 'AAS 100 mg continuamente. Manter rosuvastatina. Profilaxia de endocardite antes de procedimentos dentários. Reabilitação leve. ECO de controle em 30 dias.'),
  (1387, 410, 2, '2023-09-18 09:20', 'retorno', 'Voltei a caminhar na orla sem falta de ar', 130, 74, 66, 75.2, 'Cinco semanas após TAVI. Assintomático, caminha 4 km na orla, sem pré-síncope. Sítio de punção femoral sem hematoma. ECO: prótese biológica normofuncionante, gradiente médio 9 mmHg, sem vazamento paravalvar, FEVE 58%. ECG sem BAV. Sem equimoses. Contou que vai se mudar para o Rio de Janeiro para morar com o filho mais velho e pediu encaminhamento para seguimento por lá.', 'Entregue relatório completo com ECO pós-TAVI, tipo da prótese e orientações. Encaminhado ao serviço de cardiologia de referência do filho para seguimento em 6 meses e depois anual. Manter AAS e losartana.');
