insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (410, '2023-09-18', 'transferido', 'Estenose aórtica grave sintomática tratada com TAVI transfemoral, evolução excelente e prótese normofuncionante. Mudou de cidade e foi encaminhado com relatório para seguimento em serviço de cardiologia no Rio de Janeiro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (411, 'Zilda Beatriz Cavalcanti Fontenelle', 'F', '1942-01-15', 'Brasília', 'DF', 'Professora aposentada', 'HAS há 40 anos, osteoporose, artrose de joelhos. Em uso de losartana, anlodipino e hidroclorotiazida. Mora sozinha em apartamento, filhos moram em outro estado. Faz hidroginástica 2x por semana. Nunca fumou.', 'Alergia a sulfa (rash)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1388, 411, 3, '2023-03-07 09:30', 'consulta', 'Caí no banheiro quando levantei da privada', 152, 84, 70, 58.0, 'Idosa de 81 anos, queda ao levantar do vaso há 5 dias, com tontura e escurecimento visual de segundos, sem perda de consciência, sem trauma grave (equimose em quadril direito). Em uso de losartana 100, anlodipino 10 e hidroclorotiazida 25. PA deitada 152x84, em pé após 3 min 118x70 (queda de 34 mmHg na sistólica), sem aumento de FC. Compatível com hipotensão ortostática. Sem déficit focal. ECG com FC 70, sem bloqueios.', 'Suspender hidroclorotiazida (que também pode estar relacionada à sulfa) e reduzir anlodipino para 5 mg. Hidratação, levantar em etapas, meia elástica. Meta PA sentada 130-140 sem queda ortostática. Exames de sódio, potássio e glicemia. Retorno em 6 semanas com PA deitada e em pé.'),
  (1389, 411, 3, '2023-04-18 10:00', 'retorno', 'Não caí mais, mas fico com medo', 138, 78, 68, 58.8, 'Sem novas quedas após ajuste. Tontura rara ao levantar da cama pela manhã. PA deitada 138x78 e em pé após 3 min 128x72 (queda de 10 mmHg, sem sintomas). Perdeu o medo de tomar banho sozinha com banco e barra de apoio. Bebe 1,5 L de água. Densitometria prévia com osteoporose, faz cálcio e vitamina D.', 'Manter losartana 100 mg e anlodipino 5 mg. Fisioterapia para equilíbrio e força de membros inferiores. Revisão domiciliar do banheiro. Avaliar vitamina D e densitometria com ortopedia. Retorno em 6 meses.'),
  (1390, 411, 3, '2023-10-24 09:40', 'retorno', 'Vim ver a pressão, estou bem', 134, 76, 66, 59.2, 'Seis meses sem quedas. Faz fisioterapia e hidroginástica, mais confiante. PA deitada 134x76, em pé 130x74, sem tontura. MRPA domiciliar entre 128-138 sistólica. Creatinina 0,9, potássio 4,2. Pé calçado com solado antiderrapante. Ainda mora sozinha mas a vizinha passa todos os dias. Sem edema.', 'Manter esquema atual. Meta flexível por fragilidade: PAS 130-140 sem ortostase. Vacinação da gripe e covid. Retorno em 6 meses; ligar se tontura ou queda.');
