insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (411, '2023-10-24', 'estavel', 'Hipotensão ortostática com queda resolvida pela retirada de hidroclorotiazida e redução de anlodipino. Sem novas quedas em 6 meses, PA sentada 134x76 e sem ortostase, com fisioterapia e adaptação do banheiro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (412, 'Gilmar Aparecido Zanatta Rosa', 'M', '1976-10-20', 'Cuiabá', 'MT', 'Vendedor externo de materiais elétricos', 'Descobriu pressão alta há 2 meses numa campanha da empresa. Tabagista de 10 cigarros/dia, bebe cerveja aos fins de semana. Pai com diabetes. Passa o dia na rua visitando clientes, almoça em lanchonete.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1391, 412, 5, '2021-06-14 17:30', 'consulta', 'Quero ver essa pressão alta', 164, 102, 82, 91.0, 'Homem de 44 anos, assintomático, com PA 164x102 e 160x100 em duas medidas, estágio 2. Sem outras comorbidades. IMC 29,5. Exame físico normal, sem sopros, pulsos simétricos. Exames: creatinina 0,9, potássio 4,2, glicemia 102 mg/dL, LDL 134. Conversamos sobre risco e tratamento. Aceitou começar medicação mas disse ''não quero ficar dependente de remédio''.', 'Iniciar enalapril 10 mg 12/12h e hidroclorotiazida 12,5 mg pela manhã. MEV: reduzir sal, parar de fumar com apoio da unidade. Retorno em 6 semanas com creatinina e potássio.'),
  (1392, 412, 5, '2021-08-02 17:50', 'retorno', 'Essa tosse não passa, parei o remédio', 168, 104, 80, 91.4, 'Retorna com tosse seca persistente, irritativa, que piora à noite e atrapalha as visitas aos clientes, iniciada 3 semanas após o enalapril. Parou por conta própria os dois remédios há 3 semanas. Sem febre, sem dispneia. Ausculta pulmonar normal. PA 168x104 sem medicação. Rx de tórax normal. Tosse compatível com efeito de IECA.', 'Suspender enalapril, trocar por losartana 50 mg 12/12h e manter hidroclorotiazida 12,5 mg. Explicado que a tosse não volta com a losartana. Orientado a não suspender sem avisar. Retorno em 30 dias.'),
  (1393, 412, 5, '2021-11-15 18:00', 'retorno', 'Passou a tosse mas parei o remédio de novo', 158, 98, 78, 92.0, 'Pcte afirma que a tosse sumiu após a troca, mas tomou a losartana apenas 3 semanas porque ''achei que ia viciar e a pressão estava boa quando medi na farmácia''. Voltou ao cigarro (12/dia). PA 158x98 sem remédio há dois meses. Conversa longa sobre natureza crônica da HAS e risco de AVC e infarto. Apresentou resistência, disse que ''depois eu volto''.', 'Reiniciar losartana 50 mg 12/12h com hidroclorotiazida. Ofereci acompanhamento semanal por telefone da enfermagem e grupo de cessação do tabagismo. Agendado retorno em 30 dias; reforçado que o remédio não vicia.');
