insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (412, '2022-03-30', 'abandonou', 'Faltou a três retornos agendados e não atendeu os contatos da enfermagem. Em contato final disse que a pressão estava boa e que não queria ''ficar dependente de remédio''. Sem seguimento desde novembro de 2021, com PA não controlada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (413, 'Cleiton Everaldo Mourão Peixoto', 'M', '1966-03-09', 'Gurupi', 'TO', 'Pecuarista', 'HAS há 14 anos. Em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg há 2 anos sem atingir meta. Obesidade, ronca muito e tem sonolência diurna. Bebe 2 cervejas/dia. Pai faleceu de AVC aos 68 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1394, 413, 1, '2022-02-08 08:10', 'consulta', 'Pressão sempre alta, mesmo com os três remédios', 168, 102, 76, 104.5, 'Homem de 55 anos, HAS refratária a 3 drogas em doses plenas. Traz a caixa dos remédios, adesão boa pelo cartão de retirada na farmácia e relato do filho que prepara os comprimidos. Sem AINE ou anti-inflamatório, sem uso de descongestionante. Sono ruim, sonolência, roncos e apneias presenciadas. PA 168x102 em medida correta com manguito largo. IMC 36. MAPA: 24h 162x98, vigília 166x101, confirmando HAS resistente. Aldosterona/renina normais.', 'Resistência verdadeira. Associar espironolactona 25 mg/dia, com K e creatinina em 7 e 30 dias. Solicitar polissonografia (suspeita de SAOS). Reduzir álcool a no máximo uma dose/dia e dieta hipossódica. Retorno em 6 semanas.'),
  (1395, 413, 1, '2022-03-22 08:30', 'retorno', 'Estou me sentindo melhor da cabeça', 142, 88, 74, 103.0, 'Após 6 semanas de espironolactona 25 mg, PA caiu para 142x88. Potássio 4,9 e creatinina 1,1 mg/dL. Sem ginecomastia nem dor mamária. Polissonografia: IAH 28/h, SpO2 mínima 82%, apneia obstrutiva moderada a grave. Sonolência diurna persiste. Orientação sobre CPAP aceita, a contragosto: ''vou dormir parecendo um piloto''.', 'Aumentar espironolactona para 50 mg/dia com controle de potássio em 2 semanas. Encaminhado para titulação de CPAP automático. Manter losartana, anlodipino e clortalidona. Orientar não usar substitutos de sal com potássio.'),
  (1396, 413, 1, '2022-06-06 08:40', 'retorno', 'Estou usando o aparelho, a pressão melhorou', 134, 82, 70, 100.2, 'Em uso de CPAP há 6 semanas, uso médio de 6h por noite, sonolência diurna resolvida. Perdeu 4,3 kg. PA 134x82. Potássio 5,0 mEq/L, creatinina 1,2. Refere discreto desconforto mamário à esquerda, sem nódulo palpável, atribuído à espironolactona. Sem queixas urinárias. Adesão ótima.', 'Manter quatro drogas. Repetir potássio e creatinina em 30 dias. Se desconforto mamário piorar, trocar por eplerenona. Perda de peso alvo 90 kg. Retorno em 4 meses com MRPA.'),
  (1397, 413, 1, '2022-10-17 09:00', 'retorno', 'Vim mostrar a pressão de casa', 128, 78, 68, 96.8, 'MRPA com média 126x78. Perdeu 7,7 kg desde o início, usa o CPAP todas as noites. Potássio 4,8 e creatinina 1,1. Desconforto mamário leve e estável, sem ginecomastia ao exame. Diz que vem andando no pasto e que parou a cerveja de segunda a sexta. Sem tontura.', 'PA na meta com quatro fármacos. Manter doses. Controle de potássio e creatinina a cada 4 meses. Se perda de peso continuar, reavaliar redução progressiva. Retorno em 6 meses.');
