insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (413, '2022-10-17', 'controlado', 'Hipertensão resistente verdadeira associada a apneia obstrutiva do sono, controlada com espironolactona 50 mg adicionada ao esquema triplo, CPAP e perda de quase 8 kg. MRPA 126x78 e potássio monitorado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (414, 'Larissa Dantas Valente Bittencourt', 'F', '1990-04-25', 'Belo Horizonte', 'MG', 'Designer gráfica', 'Hipertensão detectada aos 30 anos em exame admissional, sem história familiar de HAS. Usa anticoncepcional oral combinado há 8 anos. Nunca fumou. Faz yoga. Há seis meses PA subindo apesar de losartana 50 mg que o médico anterior iniciou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1398, 414, 1, '2021-08-30 14:00', 'consulta', 'Pressão alta em mulher jovem sem causa', 178, 108, 78, 61.5, 'Mulher de 31 anos, magra, sem história familiar, com HAS estágio 2-3 iniciada aos 30 anos e piora recente. Cefaleia pulsátil esporádica. Exame: sopro sistólico-diastólico em flanco direito à ausculta abdominal, restante normal. Creatinina 1,0, potássio 3,9. Suspeita de hipertensão secundária de causa renovascular por displasia fibromuscular. Contraceptivo combinado contribui.', 'Suspender anticoncepcional combinado, orientar DIU de cobre. Iniciar anlodipino 10 mg e carvedilol 12,5 mg 12/12h, interromper losartana até definir anatomia renal. Solicitada angiotomografia de artérias renais e Doppler. Encaminhar à nefrologia.'),
  (1399, 414, 8, '2021-10-18 10:30', 'retorno', 'Vim saber o resultado da tomografia', 156, 96, 64, 61.0, 'Angiotomografia: aspecto em ''colar de contas'' na artéria renal direita médio-distal com estenose de 70% e rim direito 9,6 cm; artéria renal esquerda normal, rim esquerdo 11,2 cm. Aspecto típico de displasia fibromuscular, sem aneurismas intracranianos em angiorressonância de rastreio. PA 156x96 com duas drogas. Discutido tratamento percutâneo: angioplastia com balão sem stent, por tratar-se de estenose fibromuscular com hipertensão resistente em jovem.', 'Encaminhada à cardiologia intervencionista para angioplastia renal com balão. Manter anlodipino e carvedilol. Evitar IECA/BRA até o procedimento. Retorno com função renal pós-procedimento.'),
  (1400, 414, 10, '2021-11-23 07:30', 'internacao', 'Internação para angioplastia renal', 150, 94, 66, 61.2, 'Internada eletivamente. Arteriografia renal via femoral confirmou estenose de 70% por displasia fibromuscular na artéria renal direita, gradiente pressórico trans-estenótico de 32 mmHg. Realizada angioplastia com balão 5 mm, sem stent, com resultado angiográfico bom (estenose residual < 20%) e redução do gradiente para 4 mmHg. Sem dissecção. Tratada com heparina durante o procedimento. Alta no dia seguinte.', 'AAS 100 mg por 3 meses após procedimento. Observar função renal em 48h. Seguimento por nefrologia e Doppler de controle em 30 dias. Manter anlodipino, reduzir carvedilol conforme PA.'),
  (1401, 414, 8, '2022-02-14 10:00', 'retorno', 'Pressão normalizou?', 122, 76, 62, 62.0, 'Três meses após angioplastia renal, PA entre 118x72 e 126x78 em casa. Cefaleias desapareceram. Doppler: artéria renal direita pérvia, velocidade de pico 150 cm/s, sem reestenose. Creatinina 0,9. Rim direito sem alteração. Carvedilol suspenso gradualmente há 4 semanas com boa tolerância. Mantém DIU de cobre.', 'Manter apenas anlodipino 5 mg/dia. Suspender AAS. Doppler anual por 3 anos. Orientada sobre risco de recorrência e acompanhamento em gestação futura com obstetrícia.');
