insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (414, '2022-02-14', 'controlado', 'Hipertensão renovascular por displasia fibromuscular de artéria renal direita, tratada com angioplastia com balão. PA 122x76 com apenas anlodipino 5 mg, artéria pérvia no Doppler e função renal normal. Segue com Doppler anual.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (415, 'Genivaldo Franklin Duarte Machado', 'M', '1980-12-02', 'Taguatinga', 'DF', 'Mestre de obras', 'HAS há 8 anos sem acompanhamento, usou losartana de forma irregular até abandonar há um ano. Tabagista de 20 cigarros/dia, bebe cachaça nos fins de semana. Perdeu o pai por AVC aos 59 anos. Nega diabetes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1402, 415, 6, '2023-09-17 02:30', 'pronto_socorro', 'Dor de cabeça terrível e confusão, vômitos', 238, 142, 104, null, 'Trazido pela esposa de madrugada com cefaleia holocraniana intensa há 2 dias, vômitos, visão turva e desorientação, com uma crise convulsiva tônico-clônica generalizada em casa. PA 238x142. Sonolento, desorientado em tempo, sem déficit focal. Fundo de olho: edema de papila bilateral e exsudatos. ECG com sobrecarga ventricular esquerda, sem isquemia aguda. Creatinina 2,4, ureia 78, hemoglobina 12,1, urina com proteinúria 3+. HD: encefalopatia hipertensiva.', 'Nitroprussiato de sódio EV em bomba, meta de redução de 20-25% da PAM na primeira hora. Midazolam se nova convulsão, elevação da cabeceira. TC de crânio sem sangramento. Transferido para UTI. Solicitada RM de encéfalo.'),
  (1403, 415, 14, '2023-09-17 07:20', 'internacao', 'UTI: controle de PA e investigação', 180, 108, 88, 86.4, 'Desperto, orientado após 5h de controle pressórico, cefaleia em melhora. Sem novas crises. PA 180x108 com nitroprussiato. RM de encéfalo: hipersinal em FLAIR em regiões parieto-occipitais bilaterais compatível com PRES (síndrome da encefalopatia posterior reversível). Ecocardiograma: HVE importante (septo 15 mm), FEVE 58%. Ultrassom renal com rins de tamanho reduzido bilateral (9,8 cm), sugerindo nefroesclerose hipertensiva crônica. Creatinina 2,2.', 'Transição para anti-hipertensivos orais em 24h: anlodipino 10 mg, carvedilol 25 mg 12/12h, hidralazina 50 mg 8/8h e furosemida 40 mg. Evitar IECA/BRA até Doppler de artérias renais e K. Nefrologia avalia DRC. Alta em 7 dias.'),
  (1404, 415, 8, '2023-10-24 09:00', 'retorno', 'Primeira consulta depois da alta', 148, 92, 76, 84.0, 'Seis semanas após alta. Sem cefaleia ou convulsão, visão normalizada. PA 148x92. Creatinina 1,8 (TFGe 44), potássio 4,5, proteinúria de 24h 1,6 g. Doppler de artérias renais: sem estenose. Interrompeu o cigarro por ''susto'', segue sem beber. Esposa controla a medicação. Orientações sobre cuidado com o rim.', 'Iniciar losartana 50 mg 12/12h (Doppler normal, K normal) para nefroproteção, com creatinina e K em 10 dias. Manter demais fármacos. Reduzir hidralazina conforme resposta. Retorno em 8 semanas.'),
  (1405, 415, 8, '2024-02-19 09:20', 'retorno', 'Retorno do rim', 130, 80, 70, 83.2, 'PA 130x80. Sem cefaleia. Creatinina 1,6 e potássio 4,8 com losartana, TFGe 51. Proteinúria 24h 0,7 g, redução de 56%. Hidralazina reduzida a 25 mg 8/8h para reduzir cefaleia e taquicardia. Sem retorno ao tabaco. Pai ex-AVC: lembra do pai com frequência. Faz exercício leve.', 'Manter losartana 50 mg 12/12h, anlodipino 10 mg, carvedilol 25 mg 12/12h, furosemida 40 mg. Hidralazina reduzida para 25 mg 8/8h, possível suspensão. Meta PA < 130x80. Controle de creatinina e K a cada 3 meses. Retorno 3 meses.');
