insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (415, '2024-02-19', 'estavel', 'Encefalopatia hipertensiva (PRES) por interrupção do tratamento, resolvida sem sequelas neurológicas. Evoluiu com doença renal crônica estágio 3 (TFGe 51) e proteinúria em queda, PA 130x80 sob cinco fármacos, segue em acompanhamento nefrológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (416, 'Tainá Kaiapó Nascimento Ferreira', 'F', '1992-07-14', 'Rondonópolis', 'MT', 'Vendedora de loja', 'G2P1 (parto normal há 5 anos sem intercorrências). Normotensa antes da gestação. Sem diabetes. IMC pré-gestacional 27. Mãe com hipertensão. Sem tabagismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1406, 416, 7, '2024-03-05 08:40', 'consulta', 'Pressão alta na consulta do pré-natal', 144, 92, 86, 79.5, 'Gestante de 31 anos, G2P1, 36 semanas, encaminhada da UBS por PA 144x94 em duas aferições com 4h de intervalo. Sem cefaleia, escotomas, epigastralgia ou edema importante. Reflexos normais. BCF 144 bpm, altura uterina 35 cm, feto cefálico. Fita urinária negativa, relação proteína/creatinina 0,12. Hemograma, plaquetas 210.000, TGO/TGP normais, creatinina 0,6. HD: hipertensão gestacional sem proteinúria.', 'Iniciar nifedipino retard 20 mg 12/12h. Monitorização domiciliar da PA 2x/dia, perfil biofísico fetal e Doppler semanais. Orientar sinais de alarme. Retorno em 2 semanas, ou antes se sintomas. Parto programado entre 37 e 39 semanas.'),
  (1407, 416, 7, '2024-03-19 09:10', 'retorno', 'Pressão em casa anda 140 por 90', 150, 96, 82, 80.8, '38 semanas. Sem sintomas de pré-eclâmpsia. Diário domiciliar com PA entre 138x88 e 152x96. Exame de proteinúria ainda negativo, plaquetas 198.000, TGO 26, creatinina 0,6. USG: líquido amniótico normal, peso fetal estimado 3.150 g, Doppler normal. Colo desfavorável. Discussão sobre indução eletiva com 39 semanas pelo agravamento pressórico.', 'Aumentar nifedipino retard para 20 mg de 8/8h. Marcada internação para indução na semana seguinte. Manter vigilância dos sinais de alarme.'),
  (1408, 416, 7, '2024-03-26 07:00', 'internacao', 'Internação para indução de parto', 146, 90, 84, 81.0, '39 semanas. Internada para indução com misoprostol 25 mcg e posterior ocitocina. PA 146x90 estável, sem sinais de pré-eclâmpsia, exames de admissão normais. Parto vaginal espontâneo após 11h, sem episiotomia. RN masculino, 3.220 g, Apgar 9/10. Sem hemorragia. PA pós-parto 138x86.', 'Alta em 48h. Manter nifedipino retard 20 mg 12/12h por 7 dias, depois reavaliar pela PA domiciliar. Orientar sobre aleitamento, sinais de pré-eclâmpsia pós-parto e retorno em 7 a 10 dias para aferição.'),
  (1409, 416, 1, '2024-05-14 08:30', 'retorno', 'Quero saber se a pressão voltou ao normal', 118, 74, 72, 71.2, 'Retorno puerperal de 7 semanas. Amamentando exclusivamente. Nifedipino suspenso há 4 semanas sem recidiva, PA domiciliar média 116x72. Perdeu 9,8 kg. Creatinina 0,7, glicemia de jejum 88, perfil lipídico normal. Orientada que hipertensão gestacional aumenta risco futuro de HAS e doença cardiovascular.', 'Sem medicação. Aferir PA anualmente, manter peso, atividade física e dieta com pouco sal. Informar em futuras gestações o antecedente; AAS 100 mg profilático a partir de 12 semanas. Alta do ambulatório obstétrico com seguimento na atenção primária.');
