insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (416, '2024-05-14', 'controlado', 'Hipertensão gestacional sem proteinúria, tratada com nifedipino e resolvida com parto vaginal induzido com 39 semanas. Normotensa sem medicação no puerpério (118x74), orientada a seguir com aferição anual de PA pelo risco futuro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (417, 'Odete Maria Pavanello Cunha', 'F', '1964-11-30', 'Aparecida de Goiânia', 'GO', 'Costureira autônoma', 'HAS há 15 anos, DM2 há 10 anos e dislipidemia. Em uso de losartana, metformina e sinvastatina 20 mg. Ex-tabagista (parou há 8 anos). Irmão teve infarto aos 52 anos. Sedentária, trabalha em casa na máquina de costura.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1410, 417, 1, '2023-06-12 10:00', 'consulta', 'Dor no peito quando subo a ladeira', 144, 86, 82, 78.0, 'Mulher de 58 anos com dor retroesternal em aperto desencadeada por esforço (subir ladeira, 2 quarteirões), irradiada para mandíbula, que melhora em 5 min com repouso, há 6 semanas. CCS II. Sem dor em repouso. Exame cardiovascular normal. ECG de repouso normal. Teste ergométrico: infradesnivelamento de ST de 2,5 mm em V4-V6 aos 6 METs com angina limitante. LDL 118 mg/dL com sinvastatina.', 'Angina estável de alto risco. Iniciar AAS 100 mg, metoprolol succinato 50 mg, trocar sinvastatina por atorvastatina 80 mg, mononitrato de isossorbida 20 mg 12 h/dia se necessário. Agendar cineangiocoronariografia. Orientada sobre sinais de alarme.'),
  (1411, 417, 10, '2023-07-04 07:30', 'internacao', 'Cateterismo e angioplastia', 136, 82, 64, 77.5, 'Internação eletiva. CATE por via radial direita: lesão de 85% em DA média, excêntrica, calcificação moderada; Cx e CD com lesões de 30%. FEVE normal. Realizada angioplastia com implante de stent farmacológico 3,0 x 23 mm na DA, sem intercorrências, resultado angiográfico ótimo, TIMI 3. Dupla antiagregação indicada por 6 meses por síndrome coronariana crônica.', 'Associar clopidogrel 75 mg à AAS por 6 meses. Alta no dia seguinte. Manter atorvastatina 80 mg, metoprolol e demais. Retorno em 60 dias; iniciar reabilitação cardiovascular.'),
  (1412, 417, 1, '2023-09-05 10:20', 'retorno', 'Sem dor no peito, só vim receita', 124, 74, 62, 75.2, 'Dois meses após angioplastia com stent. Assintomática, sobe a ladeira sem dor. Faz caminhada no condomínio e reabilitação 2x por semana. Sem sangramentos com dupla antiagregação. LDL caiu para 54 mg/dL, HbA1c 7,0%. Creatinina 0,8. Acesso radial sem complicações. PA 124x74, FC 62.', 'Manter dupla antiagregação até janeiro/2024, depois AAS isolado. Manter atorvastatina 80 mg e metoprolol. Perda de peso adicional, dieta. Retorno em 4 meses com perfil lipídico.');
