insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (417, '2023-09-05', 'melhorou', 'Angina estável por lesão de 85% em DA média tratada com stent farmacológico. Assintomática, LDL 54 mg/dL, HbA1c 7,0% e em reabilitação. Segue com dupla antiagregação até janeiro e prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (418, 'Marilene Cordeiro Albuquerque Silva', 'F', '1955-02-08', 'Recife', 'PE', 'Do lar', 'HAS há 30 anos, obesidade grau II, DM2 com HbA1c 7,4% em uso de metformina. Sem história de infarto. Nunca fumou. Mora com o marido idoso e dois netos, renda de um salário mínimo e meio.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1413, 418, 11, '2022-04-11 09:30', 'consulta', 'Falta de ar para varrer a casa e pernas inchadas', 148, 88, 78, 94.2, 'Mulher de 67 anos, obesa, hipertensa e diabética, com dispneia aos esforços habituais há 4 meses, ortopneia leve e edema de MMII 2+/4+. CF NYHA III. Exame: turgência jugular a 45º discreta, RCR 2T BNF, B4 presente, estertores finos em bases. NT-proBNP 1.100 pg/mL. ECO: FEVE 58%, HVE concêntrica, E/e'' 16, átrio esquerdo aumentado. HD: ICFEp por cardiopatia hipertensiva e obesidade.', 'Iniciar empagliflozina 10 mg/dia, espironolactona 25 mg/dia e furosemida 40 mg pela manhã. Manter losartana 100 mg e anlodipino 5 mg. Restrição de sódio, pesagem diária. Dosar K e creatinina em 1 semana. Orientada perda de peso.'),
  (1414, 418, 11, '2022-06-20 09:00', 'retorno', 'Melhorei muito, desinchou', 130, 78, 72, 89.6, 'Perdeu 4,6 kg de líquido. Dispneia só para subir escada, ortopneia resolvida, edema discreto. CF NYHA II. K 4,9 mEq/L e creatinina 1,0. Tolera empagliflozina, relata uma infecção urinária tratada na UBS com cefalexina. Orientados higiene e hidratação. Satisfeita, ''voltei a fazer o almoço de domingo''.', 'Manter esquema, reduzir furosemida para 20 mg. Orientações dietéticas com nutricionista. Retorno em 6 meses com NT-proBNP, creatinina e K. Reforçar que a empagliflozina é de uso contínuo e disponível pelo programa estadual.'),
  (1415, 418, 11, '2022-12-05 10:30', 'retorno', 'Estou cansando de novo e inchando', 156, 92, 80, 95.0, 'Retorna após 6 meses com ganho de 5,4 kg, edema 2+/4+ e dispneia aos pequenos esforços, CF NYHA III. Diz que a empagliflozina e a espironolactona acabaram há 2 meses e ''não deu para comprar'', pois a farmácia estadual estava sem estoque; mantém só furosemida e losartana. Voltou aos alimentos industrializados. Ausculta com estertores bibasais, jugular 45º evidente. Sem dor torácica.', 'Descompensação por interrupção do tratamento. Represcrever empagliflozina e espironolactona com apoio da assistente social para retirada contínua. Furosemida 40 mg. Exames: K, creatinina, NT-proBNP. Retorno em 3 semanas.');
