insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (418, '2023-06-01', 'abandonou', 'Não compareceu ao retorno marcado em dezembro nem às duas remarcações. Contato telefônico sem sucesso. Seguimento perdido após descompensação de ICFEp por falta de acesso contínuo à medicação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (419, 'Natanael Gonçalves Barbosa Ribeiro', 'M', '1960-09-05', 'Jataí', 'GO', 'Trabalhador rural aposentado', 'Nasceu e viveu em casa de pau a pique no interior de Goiás. Sorologia positiva para Chagas há 20 anos, sem acompanhamento. Sem HAS conhecida. Etilista social. Tem 5 filhos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1416, 419, 6, '2022-11-03 04:30', 'pronto_socorro', 'Desmaiei no banheiro de madrugada', 168, 74, 34, null, 'Pcte de 62 anos, chagásico conhecido, com síncope súbita ao levantar de madrugada, recuperação espontânea em 1 min, sem convulsão. Há 2 meses cansaço e tontura aos esforços. Ao exame: pálido, bradicárdico, PA 168x74, pulso 34 bpm regular, ''ondas a'' em canhão no pescoço, sem congestão pulmonar. ECG: bloqueio atrioventricular total com escape juncional largo de 34 bpm e BRD prévio. Troponina negativa.', 'Monitorização contínua, atropina 1 mg se instabilidade, marca-passo transcutâneo à beira leito se piorar. Contato com arritmologia para marca-passo definitivo. Internação para implante.'),
  (1417, 419, 4, '2022-11-03 10:00', 'internacao', 'Implante de marca-passo definitivo', 150, 80, 60, 67.0, 'Mantido monitorizado com FC 32-36 bpm. ETT: dilatação de VE (DDVE 60 mm), FEVE 44%, aneurisma apical de 2 cm sem trombo. Implantado marca-passo definitivo dupla câmara (DDD) por veia subclávia esquerda, parâmetros adequados, sem complicações. Rx de tórax: eletrodos em posição. Estável. Indicado tratamento da disfunção ventricular.', 'Alta em 48h. Iniciar enalapril 5 mg 12/12h e espironolactona 25 mg. Carvedilol 3,125 mg 12/12h após estabilização com MP. Não indicado benznidazol por cardiopatia estabelecida. Cuidados com a ferida e retorno para verificação do MP em 30 dias.'),
  (1418, 419, 4, '2023-01-17 09:00', 'retorno', 'Revisão do marca-passo', 128, 76, 70, 67.8, 'Retorno 10 semanas após implante. Sem síncope, bem melhor, ''não sinto mais cansaço e tontura''. Ferida cicatrizada, bolsa sem hematoma. Interrogatório do MP: DDD 60-120, estimulação ventricular 98%, limiares estáveis. Holter 24h sem TVNS, extrassístoles ventriculares raras. Potássio 4,8, creatinina 1,0. Tolera carvedilol 6,25 mg 12/12h.', 'Manter enalapril 10 mg 12/12h, carvedilol 6,25 mg, espironolactona 25 mg. ECO em 6 meses. Retorno em 6 meses com revisão de MP. Orientação sobre interferências (ressonância não condicional, detectores).'),
  (1419, 419, 4, '2024-01-23 09:30', 'retorno', 'Controle de um ano', 124, 74, 66, 69.0, 'Um ano depois, estável, sem síncope, CF NYHA I-II. MP com estimulação ventricular 97% e bateria ok. ECO: FEVE 42%, sem trombo no aneurisma apical. Holter sem arritmias complexas. Creatinina 1,1, K 4,7. Pergunta sobre benznidazol: explicado que não há benefício na fase crônica com cardiopatia estabelecida. Etilismo reduzido.', 'Manter enalapril 10 mg 12/12h, carvedilol, espironolactona. Avaliar dapagliflozina 10 mg. Seguimento anual com ECO e Holter. Triagem de familiares conviventes (sorologia dos filhos).');
