insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (419, '2024-01-23', 'estavel', 'Cardiopatia chagásica com BAVT tratada com marca-passo dupla câmara e disfunção ventricular leve (FEVE 42%) em terapia para IC. Sem síncope, CF I-II, seguimento anual e triagem de familiares.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (420, 'Yasmin Eiko Nakamura Oliveira', 'F', '1997-01-22', 'Joinville', 'SC', 'Enfermeira', 'Palpitações súbitas desde a adolescência, 2 a 3 episódios por ano, com início e término bruscos, durando minutos. Sem comorbidades. Bebe café em excesso nos plantões. Sem tabagismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1420, 420, 6, '2022-05-19 22:40', 'pronto_socorro', 'Coração disparou durante o plantão', 104, 66, 188, 58.0, 'Paciente de 25 anos, enfermeira, com palpitações de início súbito há 40 min, sensação de pescoço batendo e leve tontura. Sem dor torácica nem síncope. ECG: taquicardia regular de QRS estreito a 188 bpm, sem onda P visível. Estável hemodinamicamente. Realizada manobra de Valsalva modificada sem reversão. Adenosina 6 mg EV rápida sem resposta, depois 12 mg com reversão para ritmo sinusal. ECG pós: sinusal 76 bpm, sem pré-excitação.', 'Observação por 2h sem recidiva. Alta com orientação de manobras vagais, evitar excesso de cafeína. Encaminhamento à arritmologia. Retorno ao PS se novo episódio prolongado ou síncope.'),
  (1421, 420, 4, '2022-06-14 10:00', 'consulta', 'Quero me livrar disso de vez', 110, 68, 74, 57.8, 'Retorna para avaliação eletiva. Duas novas crises desde o PS, uma de 15 min revertida com manobra de Valsalva. Quadro típico de taquicardia por reentrada nodal (AVNRT). ETT normal, TSH 1,6. Holter 24h sem episódios, ritmo sinusal com FC média 78. Explicadas opções: betabloqueador contínuo ou ablação por cateter, que tem taxa de cura superior a 95%. Prefere ablação pois não quer tomar remédio diário, e também por trabalhar em turnos de plantão.', 'Indicada ablação por cateter (via lenta). Orientada preparo: jejum, suspender cafeína, antiarrítmicos não necessários. Marcado estudo eletrofisiológico eletivo. Metoprolol tartarato 25 mg SN em crise até a data.'),
  (1422, 420, 4, '2022-08-23 07:30', 'internacao', 'Internação eletiva para ablação', 108, 64, 70, 58.2, 'Estudo eletrofisiológico sob sedação: indução de taquicardia por reentrada nodal típica (lenta-rápida), ciclo 310 ms, com demonstração de dupla via nodal. Ablação por radiofrequência da via lenta na região do septo posterior com junção acelerada. Teste pós-ablação com isoproterenol: sem indução de taquicardia, sem eco nodal residual. Sem BAV ou complicações. Alta no dia seguinte.', 'Repouso relativo por 3 dias, evitar esforço com membro de punção por 7 dias. Ibuprofeno SN para desconforto. Sem necessidade de antiarrítmico. Retorno em 6 semanas com ECG.'),
  (1423, 420, 4, '2022-10-04 09:30', 'retorno', 'Sem palpitações desde a ablação', 106, 64, 68, 58.5, 'Seis semanas após ablação. Sem nenhum episódio de palpitação, voltou aos plantões noturnos e à academia. Sem dor no peito ou dispneia. Local de punção sem hematoma. ECG: ritmo sinusal, PR 148 ms, sem pré-excitação. Satisfeita: ''agora consigo dormir sem medo de acordar com o coração disparado''. Reduziu o café a duas xícaras.', 'Considerada curada. Alta da arritmologia com orientação de procurar se palpitações voltarem. Revisão anual opcional com ECG pela atenção primária.');
