insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (420, '2022-10-04', 'controlado', 'Taquicardia por reentrada nodal tratada com ablação por radiofrequência da via lenta, com cura clínica e eletrofisiológica. Sem recidiva em seis semanas, sem uso de antiarrítmico e com alta da arritmologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (421, 'Murilo Augusto Pestana Lobo', 'M', '1986-06-03', 'Várzea Grande', 'MT', 'Bancário', 'Sem comorbidades conhecidas. Pai hipertenso. Sedentário desde que começou a trabalhar no banco, almoça fora e usa bastante sal. Não fuma, bebe cerveja 2 a 3 vezes por semana. Sem medicações.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1424, 421, 5, '2022-09-12 12:30', 'consulta', 'Check-up da empresa deu pressão limítrofe', 132, 84, 78, 88.0, 'Homem de 36 anos, assintomático, check-up com PA 134x86. Hoje 132x84 e 130x82 em duas medidas. IMC 29,4, circunferência abdominal 98 cm. Exame cardiovascular normal. Glicemia 96, LDL 128, creatinina 0,9, urina normal. Sem sinais de lesão de órgão-alvo. MRPA de 5 dias com média 128x82. Classificação: pré-hipertensão (130-139/80-89). Risco cardiovascular baixo.', 'Sem medicação neste momento. MEV intensiva: dieta DASH, reduzir sal, ficar abaixo de 5 g/dia, perder 5 a 7 kg, caminhada ou corrida 150 min por semana, reduzir álcool. Reavaliar em 3 meses com MRPA.'),
  (1425, 421, 5, '2022-12-19 12:40', 'retorno', 'Vim ver se emagreci o suficiente', 124, 80, 72, 83.4, 'Perdeu 4,6 kg em 3 meses. Corre 3x por semana na orla do Rio Cuiabá, troca o almoço por marmita com salada e carne grelhada. Diminuiu cerveja. PA 124x80. MRPA com média 122x78. Sem sintomas. Circunferência abdominal 92 cm. Esposa está acompanhando a dieta e participando.', 'Manter MEV sem medicação. Meta: mais 3 kg. Retorno em 6 meses com lipidograma. Orientado que, pelo histórico familiar, a PA deve ser checada pelo menos duas vezes ao ano.'),
  (1426, 421, 5, '2023-06-26 12:30', 'retorno', 'Controle semestral', 118, 76, 66, 80.5, 'Mantém corridas, peso 80,5 kg (perda total de 7,5 kg). PA 118x76. LDL 104 mg/dL, glicemia 90, creatinina 0,9. Sem queixas. Dieta com pouco sal incorporada à rotina. Meta alcançada, não necessitou medicação. Esposa também aderiu à dieta e perdeu 4 kg, o que ajuda a manter a rotina em casa. Sem edema, sem queixas de cefaleia ou palpitações.', 'Alta do acompanhamento intensivo. Manter hábitos e checar PA a cada 6 meses. Retornar caso PA domiciliar > 130x80 por mais de uma semana.');
