insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (421, '2023-06-26', 'controlado', 'Pré-hipertensão manejada exclusivamente com mudança de estilo de vida: perdeu 7,5 kg, corre 3x por semana e reduziu sal e álcool. PA normalizada em 118x76 sem medicação, em seguimento com aferições semestrais.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (422, 'Neusa Maria Cardozo Araújo', 'F', '1968-09-27', 'Formosa', 'GO', 'Professora de ensino médio', 'HAS há 8 anos. Em uso de losartana 100 mg, anlodipino 10 mg, clortalidona 25 mg e espironolactona 25 mg, por ''hipertensão resistente'' prescrita no consultório de outro médico. Ansiosa, PA sempre alta no consultório. Menopausa aos 49 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1427, 422, 2, '2023-04-04 08:00', 'consulta', 'Quatro remédios e a pressão no consultório sempre alta', 172, 98, 88, 69.0, 'Mulher de 54 anos, encaminhada por HAS resistente a quatro drogas. Chega ansiosa, relata tontura leve à tarde e cãibras nas pernas. PA de consultório 172x98; em casa o aparelho dela marca 118 a 126 por 70 a 78. Adesão boa, confere caixas. Potássio 3,4 mEq/L e creatinina 0,8. ECG normal, sem HVE. Alta suspeita de efeito do avental branco, possível hipertensão resistente falsa.', 'Solicitados MAPA 24h e MRPA antes de qualquer ajuste. Manter esquema até resultado. Repor potássio com dieta (banana, feijão) e controle de K em 7 dias. Retorno em 3 semanas com MAPA e diário domiciliar.'),
  (1428, 422, 2, '2023-04-27 08:20', 'retorno', 'Trouxe o exame de 24 horas', 168, 96, 86, 68.8, 'MAPA de 24h com os quatro fármacos: média 24h 112x68, vigília 116x71, sono 104x60, descenso noturno preservado, com episódios de PA < 100x60 às 15h, coincidindo com a tontura. MRPA 118x72. Pseudorresistência por efeito do avental branco, hoje com PA 168x96 no consultório. Sobretratamento: tontura, hipocalemia (K 3,4) e possível hipotensão relativa.', 'Suspender espironolactona e clortalidona. Manter losartana 100 mg e anlodipino 10 mg e reavaliar com MRPA em 4 semanas. Ensinada técnica correta de medida em casa. Orientada a não valorizar medidas em consultório isoladas.'),
  (1429, 422, 2, '2023-09-11 08:00', 'retorno', 'Sem tontura, mas ainda fico nervosa quando medem', 152, 88, 80, 68.0, 'Cinco meses depois, sem tontura e sem cãibras, K 4,3. MRPA domiciliar com média 122x74 sob losartana 100 e anlodipino 10 mg. PA de consultório 152x88 (efeito do avental branco confirmado, diferença de 30 mmHg). Reduzido anlodipino para 5 mg há 6 semanas com MRPA mantendo 120-126. Orientada técnica de relaxamento antes da consulta.', 'Manter losartana 100 mg e anlodipino 5 mg. Decisões terapêuticas baseadas em MRPA, não na PA de consultório. Retorno em 6 meses. Reavaliar necessidade de ansiolítico com a médica de família.');
