insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (422, '2023-09-11', 'controlado', 'Pseudorresistência por efeito do avental branco identificada na MAPA, com sobretratamento e hipocalemia. Após retirada de espironolactona e clortalidona e redução do anlodipino, mantém MRPA em 122x74 com duas drogas, sem sintomas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (423, 'Beatriz Helena Kuhnen Moreira', 'F', '1976-03-18', 'Curitiba', 'PR', 'Advogada', 'Depressão maior em tratamento há 5 meses, em uso de venlafaxina 225 mg/dia prescrita pela psiquiatra. Sem HAS prévia: PA de 114x72 no último check-up de 2021. Pai hipertenso. Não fuma, toma uma taça de vinho nos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1430, 423, 1, '2023-02-20 16:00', 'consulta', 'Pressão subiu depois do antidepressivo novo', 156, 98, 92, 64.5, 'Mulher de 46 anos, depressão tratada com venlafaxina 225 mg (aumentada há 3 meses). Percebeu cefaleia e palpitações, PA 150-160x95-100 em casa, sendo antes normal. Sem outros fatores: não usa AINE, descongestionante ou anticoncepcional. Exame cardiovascular normal. MRPA com média de 154x96. Creatinina 0,7, potássio 4,1, TSH 2,3, metanefrinas urinárias normais. HAS secundária ao uso de venlafaxina (efeito noradrenérgico dose-dependente).', 'Discutido com a psiquiatra. Iniciar anlodipino 5 mg para alívio imediato enquanto se reduz venlafaxina para 150 mg e troca gradual por sertralina. Não suspender abruptamente o antidepressivo. Retorno com MRPA em 6 semanas.'),
  (1431, 423, 1, '2023-04-10 16:20', 'retorno', 'Estou trocando o antidepressivo', 138, 86, 80, 64.0, 'Em transição supervisionada pela psiquiatra: venlafaxina reduzida para 75 mg e sertralina 100 mg já em uso há 3 semanas, humor estável. Cefaleia e palpitações desapareceram. PA 138x86, MRPA média 134x84 com anlodipino 5 mg. Sem edema de tornozelo. Tem receio de ficar dependente de anti-hipertensivo.', 'Manter anlodipino 5 mg até suspensão completa da venlafaxina; depois tentar retirada. Retorno em 8 semanas com MRPA para decidir suspensão do anlodipino.'),
  (1432, 423, 1, '2023-08-14 16:00', 'retorno', 'Venlafaxina suspensa, vim ver se posso parar o anlodipino', 118, 74, 70, 64.2, 'Venlafaxina suspensa há 10 semanas, só sertralina 100 mg, humor bom. PA 118x74 em consulta, MRPA 116x72 mesmo após suspender o anlodipino por conta própria há 3 semanas, com autorização por telefone. Sem cefaleia, sem palpitações. Normotensa sem medicação. Sem efeitos adversos da sertralina, sono regular e retomou a rotina de trabalho no escritório sem queixas.', 'Sem anti-hipertensivo. PA a cada 6 meses; reavaliar se trocar de antidepressivo para classes noradrenérgicas. Informar o psiquiatra do ocorrido. Alta do ambulatório de cardiologia.');
