insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (423, '2023-08-14', 'melhorou', 'Hipertensão secundária ao uso de venlafaxina 225 mg, resolvida após troca para sertralina. Normotensa (MRPA 116x72) sem anti-hipertensivo, com depressão estável e alta do ambulatório de cardiologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (424, 'Dorival Lúcio Tenório Sampaio', 'M', '1961-01-30', 'Palmas', 'TO', 'Taxista', 'HAS há 15 anos, abandonou o tratamento há 1 ano porque ''a pressão estava boa e o remédio dava tosse''. Tabagista (30 maços-ano), dislipidemia sem tratamento. Trabalha 14h por dia. Mora com a esposa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1433, 424, 6, '2024-06-08 07:40', 'pronto_socorro', 'Perdi a força do braço e perna direitos e a fala enrolou', 226, 124, 92, 90.0, 'Pcte de 63 anos, deixado no PS pelo filho, com hemiparesia direita (força 2/5 em MSD, 3/5 em MID), desvio de rima à direita e disartria, iniciados às 06:10 ao acordar no táxi. NIHSS 11. Glicemia capilar 142. PA 226x124. ECG em FC 92, ritmo sinusal, HVE. TC de crânio sem sangramento, sem hipodensidade extensa (ASPECTS 9). Janela de 1h30 do início dos sintomas. Hipótese: AVC isquêmico em território de ACM esquerda com crise hipertensiva.', 'Código AVC acionado. Reduzir PA para < 185x110 com nitroprussiato EV antes da trombólise, sem queda abrupta. Alteplase 0,9 mg/kg (10% em bolus) iniciada às 07:55 após critérios de inclusão checados. Transferido para unidade de AVC e angiotomografia.'),
  (1434, 424, 13, '2024-06-08 14:00', 'internacao', 'Unidade de AVC pós-trombólise', 160, 92, 78, 90.0, 'Pós-trombólise, NIHSS 11 para 5 em 12h, com melhora da força em MSD (4/5) e persistência de disartria leve. Sem sangramento na TC de controle em 24h. Angiotomografia: oclusão de M1 esquerda, recanalizada, e estenose de 40% em carótida interna esquerda proximal. ETT sem trombo, FEVE 55%. Holter 24h sem FA. LDL 164. Hba1c 5,7%. PA controlada com anlodipino. Etiologia: aterosclerose de grande artéria com HAS descontrolada.', 'Após 24h, iniciar AAS 100 mg, atorvastatina 80 mg, anlodipino 5 mg e losartana 50 mg 12/12h, aumentando gradualmente. Fisioterapia e fonoaudiologia precoces. Alta hospitalar em 7 dias. Meta PA < 130x80 a longo prazo, parar de fumar.'),
  (1435, 424, 13, '2024-08-20 09:00', 'retorno', 'Ainda fico com a mão direita fraca', 138, 84, 74, 87.5, 'Retorno 10 semanas após o AVC. Persistem monoparesia leve de MSD (força 4/5, dificuldade de fino motor), disartria leve e fadiga. Não conseguiu voltar a dirigir o táxi, a renda da família caiu. Parou de fumar desde o AVC. PA 138x84. Sem novos eventos. Funcionalidade com Rankin 2. Humor deprimido, chorando com frequência.', 'Manter AAS, atorvastatina 80 mg, anlodipino e losartana. Aumentar losartana para 100 mg/dia. Continuar fisioterapia ocupacional. Triagem para depressão pós-AVC, encaminhar à psicologia. Avaliação para endarterectomia na carótida se estenose progredir.'),
  (1436, 424, 1, '2025-02-18 09:30', 'retorno', 'Retorno do coração, estou me virando em casa', 128, 78, 72, 85.0, 'Oito meses após AVC isquêmico. Mantém hemiparesia leve residual em mão direita e disartria discreta, não voltou a dirigir. Faz fisioterapia 2x por semana. PA 128x78, LDL 62 mg/dL. Doppler de carótidas estável, estenose de 40%. Sem tabaco há 8 meses. Esposa passou a ajudar com a medicação. Ainda deprimido, sem tratamento medicamentoso por recusa.', 'Manter AAS, atorvastatina 80 mg, losartana 100 mg e anlodipino 5 mg. Doppler de carótidas anual. Reencaminhar para saúde mental. Reforçar importância de manter o tratamento mesmo com PA normal.');
