insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (424, '2025-02-18', 'piorou', 'AVC isquêmico de ACM esquerda em crise hipertensiva, após abandono do tratamento, trombolisado com melhora parcial. Ficou com sequelas motoras e de fala, sem retornar ao trabalho de taxista, mas com PA e LDL controlados.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (425, 'Ismael Torquato Bezerra Campos', 'M', '1973-08-22', 'Samambaia', 'DF', 'Policial militar', 'Sem diagnóstico de HAS. Check-ups anuais da corporação sempre com PA entre 120x78 e 128x80. Trabalha em plantões de 24h com pouco sono. Bebe cerveja 3 vezes por semana, usa muito sal. Pai faleceu de AVC aos 62 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1437, 425, 2, '2023-07-10 08:30', 'consulta', 'Pressão normal no consultório mas o ECG deu alterado', 128, 80, 74, 90.5, 'Homem de 49 anos, assintomático. Em exame periódico, ECG com critérios de HVE e microalbuminúria discreta. PA de consultório 128x80 em duas medidas, mas relata PA ''mais alta em casa'', 140-148 por 90-94 após o plantão. Exame normal. Creatinina 1,0, RAC 41 mg/g, LDL 140. Eco: septo 12 mm e parede posterior 12 mm, massa VE aumentada. Hipótese: hipertensão mascarada.', 'Solicitar MAPA 24h e MRPA para confirmar. Reduzir sal e álcool. Retorno em 3 semanas com os resultados.'),
  (1438, 425, 2, '2023-08-14 08:40', 'retorno', 'Vim buscar o resultado da MAPA', 126, 80, 72, 90.2, 'MAPA 24h: média 24h 136x86, vigília 142x90, sono 122x74 com descenso reduzido. MRPA 140x90. Confirmada hipertensão mascarada (PA normal no consultório e elevada fora), com lesão de órgão-alvo (HVE e albuminúria). Plantões estressantes e consumo de sal elevado como fatores. Sem outras causas. Creatinina 1,0, K 4,3.', 'Iniciar losartana 50 mg 12/12h, dieta hipossódica, reduzir álcool, atividade física regular. Orientado a registrar PA domiciliar por 7 dias antes do retorno. Retorno em 8 semanas com K e creatinina.'),
  (1439, 425, 2, '2023-12-04 08:20', 'retorno', 'Controle de pressão depois do remédio', 118, 74, 68, 87.0, 'Em uso de losartana 50 mg 12/12h sem efeitos colaterais. Perdeu 3,2 kg. MAPA de controle: média 24h 120x74, vigília 124x78, sono 110x64, descenso preservado. RAC caiu para 14 mg/g. Potássio 4,5, creatinina 1,0. PA consultório 118x74. Diz que ''agora levo o aparelho no plantão'' para checar em alguma folga.', 'Manter losartana 50 mg 12/12h. Repetir ECO em 12 meses para acompanhar a regressão da HVE. Retorno em 6 meses. Manter dieta e atividade física.');
