insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (425, '2023-12-04', 'controlado', 'Hipertensão mascarada com HVE e microalbuminúria diagnosticada por MAPA, tratada com losartana e redução de sal. MAPA de controle com média de 120x74 e albuminúria normalizada. Segue com ECO anual para regressão da HVE.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (426, 'Valdir Eurípedes Weber Andrade', 'M', '1956-10-14', 'Sorriso', 'MT', 'Produtor rural', 'HAS há 20 anos, DM2 há 12 anos em uso de metformina e glibenclamida. Dislipidemia com atorvastatina 20 mg irregular. Ex-tabagista (parou há 10 anos, 25 maços-ano). Pai morreu de infarto aos 66 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1440, 426, 6, '2025-03-11 23:50', 'pronto_socorro', 'Dor no peito em repouso que vai e volta há 2 dias', 164, 92, 88, 92.0, 'Pcte 68 anos com dor retroesternal em aperto, em repouso, de 15-20 min, 3 episódios em 48h, a última há 1h com irradiação para ombro esquerdo. Última semana com angina aos mínimos esforços, antes só em subida. Ao exame: PA 164x92, RCR 2T BNF, MV+ sem RA. ECG: infradesnivelamento de ST de 1,5 mm em V4-V6, T negativas. Troponina seriada 14 e 16 ng/L (limite 14), sem curva ascendente. HD: angina instável (SCA sem supra de ST), GRACE intermediário.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol 25 mg, nitrato SL se dor. Internação em unidade coronariana, cateterismo em 24h. Controle glicêmico.'),
  (1441, 426, 10, '2025-03-12 09:00', 'internacao', 'Cateterismo', 138, 80, 66, 92.0, 'Sem dor desde a madrugada. CATE radial: lesão de 90% em coronária direita média, irregular e com trombo, lesão de 40% em DA proximal, Cx sem lesão, FEVE normal. Angioplastia com stent farmacológico 3,5 x 24 mm em CD sem intercorrências, resultado ótimo TIMI 3. Lesão em DA não crítica, tratamento clínico. Alta no 2º dia.', 'Dupla antiagregação por 12 meses (AAS + ticagrelor), atorvastatina 80 mg, bisoprolol 5 mg, losartana 50 mg 12/12h. Reabilitação cardiovascular. Retorno em 30 dias.'),
  (1442, 426, 1, '2025-04-29 08:30', 'retorno', 'Sem dor no peito, vim receita', 124, 74, 56, 90.5, 'Seis semanas após angioplastia. Sem angina, voltou a cavalgar na fazenda e a caminhar. Dispneia leve em alguns esforços com o ticagrelor, tolerável. Sem sangramentos. FC 56 sob bisoprolol, sem tontura. LDL 48. HbA1c 7,6%. Glibenclamida suspensa pela cardiologia pelo risco de hipoglicemia; endocrinologia substituiu por dapagliflozina.', 'Manter DAPT até março/2026 e depois AAS isolado. Reduzir bisoprolol para 2,5 mg se FC < 55. Manter atorvastatina 80 mg e losartana. Reabilitação. Retorno em 6 meses.'),
  (1443, 426, 1, '2025-10-27 08:40', 'retorno', 'Controle de seis meses', 126, 76, 58, 89.0, 'Sete meses de angioplastia. Mantém-se assintomático, sem angina. Sangramento gengival leve ocasional. Teste ergométrico sem isquemia aos 9 METs. PA 126x76. Creatinina 1,0, LDL 52, HbA1c 7,0%. Adesão excelente. Não retornou ao fumo. Retomou as atividades na lavoura, dirige o trator sem dor. Exame cardiovascular normal, sem sopros ou edema, pulsos simétricos.', 'Manter conduta. DAPT até completar 12 meses. Depois AAS isolado. Orientado sobre sinais de angina. Retorno em 6 meses.');
