insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (426, '2025-10-27', 'estavel', 'Angina instável por lesão de 90% em coronária direita tratada com stent farmacológico. Assintomático, teste ergométrico sem isquemia, LDL 52 e HbA1c 7,0%. Mantém dupla antiagregação até completar 12 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (427, 'Conceição Aparecida Bertolini Mendes', 'F', '1959-12-21', 'Itumbiara', 'GO', 'Empregada doméstica aposentada', 'DM2 há 18 anos com HbA1c oscilante, HAS há 25 anos, dislipidemia. Em uso de metformina, enalapril, anlodipino e sinvastatina. Nunca fumou. Mãe morreu de infarto aos 58 anos. Obesidade grau I.', 'Alergia a iodo (rash cutâneo com contraste em tomografia)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1444, 427, 1, '2023-09-18 09:00', 'consulta', 'Dor no peito e cansaço ao varrer o quintal', 150, 86, 84, 82.0, 'Mulher de 63 anos, diabética e hipertensa, com angina de esforço CCS III há 3 meses, que piorou nas últimas semanas, com dispneia ao subir 10 degraus. Exame sem sopros, sem congestão. ECG com infradesnivelamento de ST em parede lateral. Cintilografia: isquemia extensa em parede anterior e lateral. ETT: FEVE 50%. Pré-medicada para cateterismo por história de alergia a contraste (prednisona e anti-histamínico).', 'Solicitar CATE com preparo para alergia a contraste (prednisona 50 mg 13h, 7h e 1h antes). Iniciar AAS 100 mg, metoprolol succinato 50 mg e atorvastatina 80 mg. Manter enalapril 10 mg 12/12h e anlodipino 5 mg. Retorno com resultado do cateterismo.'),
  (1445, 427, 12, '2023-11-14 07:00', 'internacao', 'Internação para revascularização cirúrgica', 138, 80, 66, 81.5, 'CATE prévio: lesão de 60% em tronco da coronária esquerda, 90% em DA proximal, 80% em Cx e 85% em CD, SYNTAX 38. Discussão no Heart Team: diabética multiarterial com tronco, indicada cirurgia de revascularização. Realizada RM com LIMA para DA e safena para Cx e CD, 3 pontes, em CEC, sem intercorrências. UTI por 2 dias. Extubada em 6h. Sem fibrilação atrial pós-op. Alta no 7º dia.', 'AAS 100 mg e atorvastatina 80 mg contínuas, metoprolol succinato 50 mg, enalapril 5 mg 12/12h. Cuidados com esterno e safenectomia. Insulinização temporária no pós-op, retorno à metformina. Reabilitação cardiovascular.'),
  (1446, 427, 12, '2023-12-19 09:30', 'retorno', 'Retorno da cirurgia do coração', 124, 72, 68, 79.0, 'Cinco semanas de pós-operatório. Esterno estável, ferida esternal e da perna esquerda sem sinais de infecção. Sem angina, sem dispneia. Anda 20 minutos pelo bairro. Refere dor torácica à tosse, melhorando. PA 124x72. Sem edema relevante em membro inferior. Hemograma Hb 12,0, creatinina 0,9.', 'Liberada para atividades leves, sem carga de peso por 3 meses. Iniciar reabilitação cardiovascular. Manter medicamentos. Retorno à cardiologia em 90 dias.'),
  (1447, 427, 1, '2024-06-24 09:00', 'retorno', 'Estou sem dor e fazendo caminhada', 120, 70, 62, 76.4, 'Sete meses de pós-operatório. Sem angina, completou reabilitação. Perdeu 5,6 kg. PA 120x70, FC 62. LDL 52, HbA1c 6,8%. ECO: FEVE 55%, sem alterações segmentares novas. Teste ergométrico sem isquemia aos 7 METs. Enalapril 5 mg sem tosse. Está contente, ''voltei a cuidar dos netos''.', 'Manter AAS, atorvastatina, metoprolol e enalapril. Aumentar enalapril para 10 mg 12/12h. Retorno em 6 meses. Vacinação de rotina.');
