insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (427, '2024-06-24', 'melhorou', 'Doença coronária multiarterial com lesão de tronco, tratada com revascularização cirúrgica de 3 pontes. Sem angina, teste ergométrico negativo, LDL 52 e HbA1c 6,8%. Retomou atividades e segue em prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (428, 'Eunice Rosália Pimentel Barreto', 'F', '1950-05-09', 'Salvador', 'BA', 'Aposentada, ex-merendeira', 'HAS há 40 anos, DRC estágio 3b (creatinina basal 1,6), ICFEr de etiologia hipertensiva com FEVE 30% há 3 anos. Em uso de sacubitril/valsartana, carvedilol, espironolactona e furosemida. Duas internações prévias por IC descompensada. Mora com a filha. Usa muito caldo industrializado.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1448, 428, 6, '2024-11-02 01:40', 'pronto_socorro', 'Não consigo respirar deitada, acordei sufocada', 188, 102, 112, 74.5, 'Pcte 74 anos, madrugada, com dispneia súbita grave, tosse com escarro rosado, sudorese. Há 5 dias com ganho de peso de 4 kg e edema; esquecera a furosemida por 3 dias após comemoração com feijoada. SpO2 84% em ar ambiente, FR 34, uso de musculatura acessória, estertores até ápices. PA 188x102. TJ evidente. ECG: taquicardia sinusal 112 bpm, BRE conhecido. Rx: congestão e derrame pleural bilateral. BNP 1.850. HD: EAP hipertensivo em ICFEr descompensada.', 'O2, VNI com CPAP 8 cmH2O, furosemida 80 mg EV, nitroglicerina EV para reduzir pós-carga, Resposta clínica boa em 1h com diurese 900 mL, SpO2 94%. Internação em UTI. Suspender temporariamente espironolactona se K > 5,5.'),
  (1449, 428, 14, '2024-11-02 08:00', 'internacao', 'UTI: pós-edema agudo de pulmão', 134, 80, 92, 72.0, 'Extubada de VNI, SpO2 96% em cateter nasal. Diurese de 2,4 L nas primeiras 8h, peso de 74,5 para 72,0 kg. Sem arritmias na telemetria, troponina negativa, descartado IAM. PA 134x80. ETT: FEVE 28%, VE dilatado, IM moderada, pressão sistólica de artéria pulmonar de 52 mmHg. K 4,9, Cr 1,8. Transferida para enfermaria no 3º dia, alta no 8º com peso seco 69 kg.', 'Retornar sacubitril/valsartana 24/26 mg 12/12h (PA permite), carvedilol 6,25 mg 12/12h, espironolactona 25 mg, furosemida 80 mg/dia. Dapagliflozina 10 mg adicionada (TFGe > 25). Orientação de sal com nutricionista e peso diário.'),
  (1450, 428, 11, '2024-12-03 10:00', 'retorno', 'Estou melhor, mas inchada de novo na perna', 118, 70, 76, 71.0, 'Retorno 1 mês após a alta. Dispneia a médios esforços, CF NYHA III. Edema de MMII 1+/4+ e peso 2 kg acima do peso seco. K 5,0, Cr 1,8, TFGe 28. PA 118x70. Filha controla o sal em casa. Dapagliflozina bem tolerada. Sem hipotensão ou tontura. Dificuldade para locomoção e para ir às consultas.', 'Aumentar furosemida para 80 mg 12/12h por 5 dias e depois voltar a 80 mg/dia. Manter quatro pilares sem aumentar espironolactona. K e Cr em 7 dias. Telemonitorização por enfermagem a cada 15 dias. Retorno em 30 dias.'),
  (1451, 428, 6, '2025-05-19 21:10', 'pronto_socorro', 'Falta de ar de novo, pernas muito inchadas', 96, 58, 108, 77.0, 'Pcte 75 anos, terceira internação em 7 meses por IC. Dispneia em repouso, ortopneia, edema até coxas, ascite e hepatomegalia. PA 96x58, extremidades frias e mal perfundidas, lactato 3,1. Cr 2,6, K 5,6, Na 128. Perfil frio-úmido (choque cardiogênico incipiente). Suspende-se sacubitril/valsartana e espironolactona por hipotensão e hipercalemia. Discussão com a família sobre prognóstico: filha relata queda funcional e cansaço constante.', 'Internação em UTI, furosemida em bomba, dobutamina em dose baixa para suporte, manter O2. Suspender espironolactona e sacubitril/valsartana. Conversa de metas de cuidado com a família; iniciar cuidados paliativos em conjunto à terapia otimizada.');
