insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (428, '2025-05-19', 'piorou', 'ICFEr hipertensiva avançada, com síndrome cardiorrenal e terceira descompensação em sete meses. Evoluiu para perfil frio-úmido com hipotensão, sem tolerar espironolactona e sacubitril/valsartana. Mantida em UTI, com início de cuidados paliativos em paralelo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (429, 'Wanderson Aurélio Cavalcante Duarte', 'M', '1967-08-19', 'Porto Nacional', 'TO', 'Servidor público estadual', 'HAS há 10 anos em uso de losartana 50 mg 12/12h. Sem diabetes. Sedentário, sobrepeso, consome 3 doses de uísque nos fins de semana. Sem história de doença cardíaca. Pai teve fibrilação atrial.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1452, 429, 6, '2025-01-14 19:30', 'pronto_socorro', 'Coração acelerado desde ontem à noite', 132, 84, 148, 92.0, 'Pcte 57 anos, palpitações regulares e taquicardia, início há aproximadamente 24 horas, cansaço, dispneia leve e mal-estar após festa com bebida. Sem dor torácica, sem síncope. Ao exame: pulso regular a 148 bpm, PA 132x84, SpO2 97%. ECG: flutter atrial típico com condução 2:1, FC 148 bpm, ondas F em dente de serra em DII, DIII e aVF. Troponina negativa, TSH normal.', 'Controle de FC com diltiazem endovenoso, FC caiu para 108 bpm. Iniciar rivaroxabana 20 mg/dia (CHA2DS2-VASc 1, mas flutter típico com duração < 48h tem baixo risco; mantida por cautela). Internar para cardioversão elétrica eletiva na manhã seguinte.'),
  (1453, 429, 4, '2025-01-15 09:00', 'internacao', 'Cardioversão elétrica', 126, 78, 104, 92.0, 'Em jejum, ETE sem trombo em apêndice atrial esquerdo, velocidade de esvaziamento 52 cm/s. Cardioversão elétrica sincronizada com 100 J sob sedação com propofol, revertendo ao ritmo sinusal com o primeiro choque. ECG pós: ritmo sinusal 72 bpm, sem pré-excitação, PR 168 ms. ETT: FEVE 62%, átrio esquerdo 41 mm, sem valvopatia. Alta no mesmo dia.', 'Manter rivaroxabana por 4 semanas pós-cardioversão. Reduzir álcool. Metoprolol succinato 25 mg/dia. Retorno em 30 dias com ECG e Holter. Se recorrência, discutir ablação do istmo cavotricuspídeo.'),
  (1454, 429, 4, '2025-02-20 09:30', 'retorno', 'O coração disparou de novo ontem', 130, 82, 126, 91.0, 'Retorna com recidiva de palpitações há 16 horas. Rivaroxabana tomada até 3 dias atrás (4 semanas completas). ECG no consultório: flutter atrial típico 2:1 com FC 126, recidiva. Estável, PA 130x82. Holter de 24h antes: carga de flutter 100% em episódios. Recorrência precoce após CVE reforça indicação de ablação do istmo cavotricuspídeo, com taxa de sucesso > 95%.', 'Reiniciar rivaroxabana 20 mg e manter até a ablação. Aumentar metoprolol succinato para 50 mg. Agendar ablação do istmo cavotricuspídeo. Orientações sobre hidratação e álcool.'),
  (1455, 429, 4, '2025-04-08 07:30', 'internacao', 'Internação para ablação de flutter', 128, 78, 72, 90.0, 'Ritmo sinusal na admissão. Estudo eletrofisiológico: flutter típico anti-horário induzido, ciclo 245 ms. Ablação por radiofrequência da linha do istmo cavotricuspídeo com bloqueio bidirecional confirmado. Sem indução de arritmias. Sem complicações; alta no dia seguinte. Perdeu 2 kg com dieta.', 'Manter anticoagulação por mais 2 semanas pós-ablação e suspender se ritmo sinusal sem FA. Suspender metoprolol, manter losartana. ECG e Holter em 3 meses. Orientado sobre risco de desenvolver FA no futuro; seguir controle de álcool e pressão.');
