insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (430, '2024-08-13', 'melhorou', 'Pericardite aguda pós-viral tratada com ibuprofeno e colchicina por 3 meses, com resolução clínica, normalização do PCR, ECG e ecocardiograma. Liberado para atividades esportivas e recebeu alta do ambulatório.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (431, 'Soraya Aziz Haddad Figueiredo', 'F', '1975-04-28', 'Goiânia', 'GO', 'Cabeleireira', 'Hipertensão descoberta há 1 ano, sem tratamento por medo de efeitos colaterais. Mãe e duas tias hipertensas. Sobrepeso, fica 10 horas em pé no salão. Não fuma. Anticoncepcional oral combinado suspenso há 2 anos por laqueadura.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1459, 431, 1, '2022-10-03 11:00', 'consulta', 'Quero começar a tratar a pressão, mas sem tomar muitos comprimidos', 168, 104, 80, 74.5, 'Mulher de 47 anos, assintomática, PA 168x104 e 166x102 em duas medidas, MRPA domiciliar com média de 164x100 em 5 dias. Estágio 2. IMC 28,6. Creatinina 0,7, potássio 4,1, glicemia 92, LDL 136, urina 1 normal. ECG normal. Sem sinais de lesão de órgão-alvo. Prefere esquema simples por esquecer remédios na rotina corrida do salão. Orientada sobre vantagem do comprimido único.', 'Iniciar combinação fixa olmesartana 20 mg + anlodipino 5 mg em um único comprimido pela manhã. Reduzir sal e comida pronta. Retorno em 6 semanas com creatinina e potássio.'),
  (1460, 431, 1, '2022-11-14 11:20', 'retorno', 'Estou tomando direitinho, mas ainda dá um pouco de dor de cabeça', 140, 88, 78, 74.0, 'Adesão ótima com comprimido único. PA 140x88, MRPA com média 138x86. Cefaleia leve no início, já resolveu. Sem edema de tornozelo. K 4,3, creatinina 0,7. Tolerância ótima. Ainda não atingiu meta, mas queda de 28 mmHg na sistólica. Perdeu 500 g.', 'Aumentar a combinação para olmesartana 40 mg + anlodipino 5 mg, ainda comprimido único. Retorno em 8 semanas com MRPA. Reforçada caminhada nos intervalos de almoço.'),
  (1461, 431, 1, '2023-02-20 11:00', 'retorno', 'Pressão boa, vim renovar a receita', 126, 76, 72, 72.3, 'Pcte assintomática, sem tontura ou edema. PA 126x76, MRPA 124x76. Perdeu 2,2 kg. K 4,5, creatinina 0,7 após aumento da dose. Satisfeita com a comodidade de um comprimido por dia, ''esse eu não esqueço''. Orientações de dieta com redução do sal nos temperos do salão e almoço.', 'Manter olmesartana 40 mg + anlodipino 5 mg. Controle de creatinina e potássio anuais. Retorno em 6 meses. Meta de peso 68 kg.');
