insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (431, '2023-02-20', 'controlado', 'Hipertensão estágio 2 tratada com combinação em comprimido único olmesartana/anlodipino, com boa adesão. PA caiu de 168x104 para 126x76 em 4 meses, sem efeitos adversos, e segue em acompanhamento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (432, 'Ricardo Ivo Spiering Matos', 'M', '1970-09-08', 'Lucas do Rio Verde', 'MT', 'Representante comercial de sementes', 'HAS há 9 anos, em uso de losartana, anlodipino e hidroclorotiazida. Obesidade grau II, esteatose hepática, pré-diabetes. Muito tempo viajando de carro e alimentação irregular. Ex-tabagista há 12 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1462, 432, 1, '2021-03-15 07:50', 'consulta', 'Tomo três remédios e quero tentar emagrecer para largar eles', 142, 90, 80, 118.0, 'Homem de 50 anos, 118 kg, IMC 38,4. Em uso de losartana 100, anlodipino 10 e hidroclorotiazida 25. Tem tornozelos inchados e cansaço. PA 142x90, ainda acima da meta mesmo com três drogas. Apneia suspeita: ronco, sonolência. Glicemia 112, HbA1c 5,9%, triglicerídeos 240, TGP 62. ECG com HVE. Motivado a perder peso por estar cansado das viagens.', 'Programa de perda de peso com nutricionista e endocrinologista, meta -15 kg em 6 meses. Atividade física progressiva. Manter medicação inalterada por ora. Solicitada polissonografia. Retorno em 3 meses.'),
  (1463, 432, 1, '2021-09-20 08:10', 'retorno', 'Perdi mais de 10 quilos, estou me sentindo outro', 122, 76, 68, 105.8, 'Perdeu 12,2 kg em 6 meses com dieta e caminhada de 40 min. Menos edema, mais disposição, ronco reduzido. PA 122x76, com leve hipotensão ao levantar à tarde. Polissonografia: IAH 12 (leve). Sódio 138, K 3,7, ácido úrico 8,1 em uso de tiazídico. TGP caiu para 38.', 'Suspender hidroclorotiazida e reduzir anlodipino para 5 mg. Manter losartana 100 mg. MRPA por 7 dias e retorno em 6 semanas. Segue com nutricionista. Cuidado de manter hidratação nas viagens.'),
  (1464, 432, 1, '2022-06-06 08:00', 'retorno', 'Quero ver se posso deixar mais um remédio', 118, 72, 64, 96.4, 'Perdeu 21,6 kg desde o início, mantendo o peso há 3 meses. Corre 30 minutos 3x por semana, dieta com nutricionista. MRPA média 116x72 com losartana 100 e anlodipino 5 mg. Sem edema. Sem ronco, sem sonolência. Glicemia 94, HbA1c 5,4%, triglicerídeos 120, TGP 28. Está feliz, não precisa mais de ''caixinha'' de remédios nas viagens.', 'Suspender anlodipino. Manter losartana 100 mg em dose única. MRPA semanal por 4 semanas e informar. Se PA domiciliar > 130x80, retomar. Retorno em 3 meses.');
