insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (432, '2022-06-06', 'controlado', 'Perdeu 21,6 kg com dieta e exercício, o que permitiu retirar hidroclorotiazida e anlodipino. Controle com losartana em monoterapia (MRPA 116x72), com resolução de esteatose e melhora de glicemia, em acompanhamento trimestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (433, 'Maria da Penha Rodrigues Nunes', 'F', '1960-02-11', 'Planaltina', 'DF', 'Diarista', 'HAS há 18 anos, sempre mal controlada. Obesidade grau I. Sem diabetes. Mora sozinha, trabalha em casas de família e pega 3 conduções. Nega tabagismo. Pai falecido de AVC aos 65 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1465, 433, 2, '2021-05-19 09:10', 'consulta', 'Cansaço e pressão alta há muito tempo', 176, 104, 82, 84.0, 'Pcte 61 anos, HAS de longa data com adesão irregular, refere cansaço aos médios esforços e palpitações esporádicas. PA 176x104. Exame: B4 presente, ictus desviado para a esquerda, sem sopros, sem edema. ECG: HVE com padrão de sobrecarga (strain) em V5-V6. ECO: septo 14 mm, parede posterior 13 mm, massa de VE 142 g/m², FEVE 60%, disfunção diastólica grau I. HD: cardiopatia hipertensiva com HVE.', 'Iniciar losartana 100 mg e anlodipino 5 mg, mais clortalidona 12,5 mg. Solicitados creatinina, K, albuminúria e fundo de olho. Reforçado o risco de IC e AVC se não tratar. Retorno em 30 dias.'),
  (1466, 433, 2, '2021-07-07 09:30', 'retorno', 'Estou me sentindo melhor da cabeça', 144, 88, 76, 83.0, 'PA 144x88 após 7 semanas. Tomando os três remédios, mas diz que ''às vezes pulo quando estou na casa da patroa''. K 3,6 mEq/L, creatinina 0,9. Albuminúria 38 mg/g. Fundo de olho com retinopatia hipertensiva grau I. Dispneia aos grandes esforços. Gasta metade do salário nas conduções e sente-se cansada.', 'Manter esquema, com orientação para tomar à noite se esquecer de manhã. Repor potássio na dieta. Retorno em 6 semanas. Adiantei receita de 90 dias para reduzir deslocamentos.'),
  (1467, 433, 2, '2021-10-27 09:10', 'retorno', 'Vim buscar a receita, já acabou', 164, 98, 84, 84.5, 'Retorno com 4 meses e meio, depois de faltar à consulta agendada. Receita acabou há 3 semanas; tomou somente os dias em que se sentiu mal. PA 164x98. Perdeu o emprego numa das casas e está sem condição de ir à UBS pegar remédio. Cansaço semelhante, sem dor torácica. Entendeu o risco de IC mas afirma ''quando a vida melhorar eu volto''.', 'Receita renovada por 90 dias, reforço sobre contato com assistente social para benefício de transporte. Agendado retorno em 8 semanas e telefone de contato anotado. Orientada a procurar UBS para retirar medicação gratuita.');
