insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (433, '2022-04-12', 'abandonou', 'Não compareceu ao retorno de dezembro e às duas remarcações. Telefone não atende. Última PA de 164x98 com cardiopatia hipertensiva e HVE, em risco de IC, sem seguimento desde outubro de 2021.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (434, 'Francisca Laurentina Gadelha Coelho', 'F', '1964-08-05', 'Fortaleza', 'CE', 'Dona de bar', 'HAS há 20 anos, DM2 há 14 anos com HbA1c ao redor de 8,5%, obesidade grau I, dislipidemia sem tratamento regular. Tabagista de 20 cigarros/dia há 35 anos. Mãe com infarto aos 54 anos. Trabalha até tarde da noite no balcão.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1468, 434, 6, '2023-05-14 05:20', 'pronto_socorro', 'Dor no meio do peito que não passa, suando', 178, 100, 98, 86.0, 'Pcte 58 anos, diabética, dor precordial em aperto há 4h, acordou com sudorese e náuseas, sem irradiação clara. PA 178x100. Ausculta com raros estertores em bases. ECG: infradesnivelamento de ST de 2 mm em V3-V6, sem supra. Troponina ultrassensível 3,8 ng/mL (muito elevada). Glicemia 312. HD: infarto sem supra de ST (IAMSSST), alto risco (GRACE > 140), com hiperglicemia.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, nitroglicerina EV, insulina regular conforme protocolo. Transferência para a hemodinâmica, estratégia invasiva precoce em 24h.'),
  (1469, 434, 10, '2023-05-15 10:30', 'internacao', 'Cateterismo e angioplastia', 144, 82, 80, 86.0, 'CATE: DA média 95% (culpada) e CD proximal 80%, Cx com lesão de 50%. Angioplastia com stent farmacológico na DA e, no mesmo ato, na CD proximal. Sem complicações. FEVE 48% na ventriculografia, hipocinesia anterior. Glicemia controlada com insulina NPH. Alta no 4º dia.', 'DAPT por 12 meses, atorvastatina 80 mg, metoprolol succinato 50 mg, enalapril 5 mg 12/12h, insulina NPH 10 UI à noite associada à metformina. Cessação do tabagismo; reabilitação cardiovascular.'),
  (1470, 434, 1, '2023-07-03 08:50', 'retorno', 'Voltei a fumar e estou com falta de ar', 150, 90, 84, 88.5, 'Retorno 7 semanas após IAM. Voltou a trabalhar no bar já na 2ª semana e ao cigarro (10/dia), não fez reabilitação. Dispneia aos esforços leves, ortopneia nova com dois travesseiros, edema de MMII 1+/4+, ganho de 2,5 kg. Crepitações em bases. HbA1c 8,9%. ECO: FEVE 40%, hipocinesia anterior e apical, IM leve. Perfil de IC pós-IAM.', 'Iniciar furosemida 40 mg, aumentar enalapril para 10 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg pelo benefício na IC e no diabetes. Manter DAPT e demais. Terapia para cessação de tabagismo com adesivo. Retorno em 4 semanas.'),
  (1471, 434, 6, '2024-01-22 22:40', 'pronto_socorro', 'Sufocando, não consigo deitar', 90, 60, 116, 91.0, 'Pcte 59 anos, suspendeu os remédios há 3 semanas após ficar sem dinheiro e no meio de festas de fim de ano, continua tabagista. Dispneia em repouso, ortopneia, estertores até campos médios, jugular evidente, edema de MMII 3+/4+, extremidades frias. PA 90x60, SpO2 88%. ECG: taquicardia sinusal 116, sem alterações agudas. Troponina 0,09. BNP 2.900. ECO: FEVE 28%, VE dilatado. Perfil frio e úmido.', 'Internar em UTI. Furosemida EV, O2 suplementar, evitar vasodilatadores pela PA, dobutamina se persistir hipoperfusão. Reiniciar terapia de IC progressivamente quando estável. Serviço social acionado para o acesso a medicação.');
