insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (434, '2024-01-22', 'piorou', 'IAM sem supra de ST tratado com angioplastia de DA e CD. Evoluiu com insuficiência cardíaca por disfunção ventricular (FEVE 28%) após abandonar medicação e reabilitação e voltar a fumar, com internação em UTI por descompensação grave em janeiro de 2024.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (435, 'Hélio Frederico Sobrinho Lopes', 'M', '1968-06-30', 'Catalão', 'GO', 'Soldador industrial', 'IAM inferior em dezembro de 2021 tratado com angioplastia primária da CD (stent farmacológico). HAS há 10 anos, dislipidemia. Fumou 20 anos, parou no dia do infarto. Pai teve infarto aos 55 anos. Divorciado, vive sozinho, trabalha em fábrica de fertilizantes.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1472, 435, 1, '2022-02-14 08:00', 'consulta', 'Primeira consulta depois do infarto, medo de ter outro', 128, 78, 60, 91.5, 'Homem de 53 anos, 2 meses após IAM de parede inferior com ATC primária da CD. Alta sem complicações. Sem angina, dispneia só em esforços intensos. Muito apreensivo e evita esforço, receoso do coração. Relata ''não consigo nem subir escada com medo''. ECO de alta: FEVE 52%. Exame: PA 128x78, FC 60, RCR 2T BNF, sem sopros. Ansiedade pós-infarto, sem critérios de depressão.', 'Encaminhar para reabilitação cardiovascular supervisionada (3x/semana, 12 semanas) com teste ergoespirométrico inicial. Manter AAS, ticagrelor, atorvastatina 80 mg, bisoprolol 5 mg, ramipril 5 mg. Acompanhamento psicológico. Retorno em 3 meses.'),
  (1473, 435, 1, '2022-05-23 08:20', 'retorno', 'Terminei a reabilitação, vim mostrar', 120, 72, 56, 87.0, 'Completou 12 semanas de reabilitação cardiovascular, com ergoespirometria final: VO2 pico 27 mL/kg/min (inicial 19), sem isquemia, limiar ventilatório em FC 118. Perdeu 4,5 kg. Voltou ao trabalho há 4 semanas. Relata ter recuperado a confiança, ''agora subo a escada sem pensar''. LDL 58, creatinina 1,0, potássio 4,4. Sem sangramentos. FC 56 sob bisoprolol, tolera bem.', 'Manter esquema. Completar 12 meses de ticagrelor em dezembro/2022 e seguir AAS isolado. Continuar atividade física 150 min/semana mantida de forma autônoma. Retorno em 6 meses.'),
  (1474, 435, 1, '2022-12-12 08:10', 'retorno', 'Completei um ano do infarto', 118, 70, 58, 85.2, 'Um ano do infarto. Assintomático, corre 5 km 3x por semana, treina na academia da empresa. Sem sangramentos. PA 118x70, FC 58. LDL 54, HbA1c 5,3%, creatinina 0,9. ECG sem alterações. Sem tabagismo, relata ter virado ''o fiscal do cigarro'' entre os colegas. Dieta ajustada, perdeu mais 1,8 kg.', 'Suspender ticagrelor após 12 meses. Manter AAS 100 mg, atorvastatina 80 mg, bisoprolol 5 mg e ramipril 5 mg. Retorno em 6 meses. Vacinação anual contra influenza.');
