insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (435, '2022-12-12', 'controlado', 'Reabilitação cardiovascular completa após IAM inferior e angioplastia, com VO2 pico subindo de 19 para 27 mL/kg/min. Assintomático há um ano, sem tabagismo, LDL 54 e PA 118x70, em prevenção secundária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (436, 'Inácio Teodoro Brito Guimarães', 'M', '1956-03-19', 'Araguaína', 'TO', 'Mecânico aposentado', 'IAM prévio extenso em 2018 sem revascularização completa, HAS, DM2. ICFEr isquêmica com FEVE 27% em 2021. Ex-tabagista (50 maços-ano). Em uso de enalapril, carvedilol e furosemida. Casado, filhos moram longe.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1475, 436, 11, '2021-08-09 10:00', 'consulta', 'Cansaço cada vez maior, não consigo trabalhar na oficina', 110, 68, 72, 70.5, 'Homem de 65 anos, ICFEr isquêmica, CF NYHA III, dispneia ao caminhar 100 metros, edema vespertino. Em uso de enalapril 10 mg 12/12h, carvedilol 6,25 mg 12/12h e furosemida 40 mg. Não usava espironolactona nem iSGLT2. ECO: FEVE 27%, aneurisma apical. NT-proBNP 3.100. Cr 1,3, K 4,6. Ficou internado duas vezes no último ano. Tem receio de efeitos dos novos remédios.', 'Associar espironolactona 25 mg e dapagliflozina 10 mg. Manter enalapril e carvedilol com titulação futura. Exames em 1 semana. Encaminhar para avaliação de CDI para prevenção primária, pois FEVE ≤ 35% há mais de 3 meses de tratamento. Retorno em 6 semanas.'),
  (1476, 436, 14, '2022-01-17 07:40', 'internacao', 'Dispneia intensa e edema há uma semana', 100, 62, 96, 74.0, 'Internado por descompensação de IC após infecção respiratória: ganho de 4 kg, ortopneia, edema 3+/4+, estertores até médios campos. PA 100x62, SpO2 91%. Troponina negativa, BNP 2.700, Cr 1,6, K 4,9. Rx com derrame pleural direito e congestão. Tratado com furosemida EV, restrição hídrica e antibiótico (amoxicilina/clavulanato) para pneumonia. Perdeu 5,5 kg e teve alta no 9º dia com peso seco de 68,5 kg.', 'Alta com furosemida 40 mg, enalapril 5 mg 12/12h (reduzido pela creatinina), carvedilol 6,25 mg, espironolactona 25 mg, dapagliflozina. Retorno em 14 dias. Vacina antipneumocócica e contra gripe.'),
  (1477, 436, 11, '2022-04-25 09:30', 'retorno', 'Estou bem mais firme, só canso na ladeira', 112, 70, 64, 68.8, 'Estável há 3 meses, sem novas internações. CF NYHA II. Peso seco mantido. Cr 1,3, K 5,0. Esposa faz diário de peso e restringe o sal. Sem tontura ao se levantar. Passou por avaliação eletrofisiológica: Holter com TVNS frequentes, FEVE 29% após 8 meses de terapia otimizada. Indicado CDI para prevenção primária; aceita, aguardando vaga no serviço.', 'Manter quatro pilares nas mesmas doses. Trocar enalapril por sacubitril/valsartana quando PA permitir (PAS > 110). CDI agendado por regulação. Retorno em 2 meses. Orientações sobre sinais de piora.'),
  (1478, 436, 4, '2022-09-19 10:20', 'internacao', 'Internação eletiva para implante de CDI', 114, 70, 66, 68.2, 'Internado após liberação de vaga. Compensado, CF NYHA II, peso seco 68,2 kg. Implante de CDI unicameral por acesso subclávio esquerdo, limiar adequado, detecção de FV em 200 bpm, terapia antitaquicardia. Teste de desfibrilação não realizado por rotina atual. Sem pneumotórax no Rx. Recebeu alta no dia seguinte, em boas condições.', 'Controle da ferida, evitar elevar braço esquerdo acima do ombro por 4 semanas. Cartão de CDI entregue. Retorno em 30 dias para interrogatório e programação. Manter terapia de IC. Orientação sobre choques e acionamento do serviço.');
