insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (436, '2022-09-20', 'melhorou', 'ICFEr isquêmica com FEVE entre 27 e 29%, internada uma vez em janeiro por descompensação infecciosa. Estabilizado em CF NYHA II com quatro pilares e implante de CDI para prevenção primária de morte súbita, sem choques até a alta.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (437, 'Therezinha Alves Mascarenhas Dória', 'F', '1948-10-16', 'Londrina', 'PR', 'Professora aposentada', 'HAS há 35 anos, DM2 há 15 anos, DRC estágio 3a. ICFEp diagnosticada há 2 anos. Em uso de losartana, anlodipino, metformina e furosemida. Vegetariana. Cuida do marido com Alzheimer. Nunca fumou.', 'Alergia a penicilina (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1479, 437, 11, '2023-02-13 14:00', 'consulta', 'Cansaço, falta de ar mesmo sem fazer esforço', 134, 74, 88, 64.0, 'Mulher de 74 anos com ICFEp (FEVE 62%, E/e'' 15), dispneia crescente e fadiga progressiva nos últimos 3 meses, apesar de euvolêmica ao exame: sem edema, ausculta limpa, jugular normal. Palidez de mucosas, taquicardia sinusal leve. Hemoglobina 9,4 g/dL, VCM 76, ferritina 14 ng/mL, saturação de transferrina 9%. Anemia ferropriva (vegetariana, perda oculta?). NT-proBNP 780.', 'Investigar a causa da deficiência de ferro: solicitar EDA e colonoscopia. Reposição de ferro endovenoso (carboximaltose férrica 1000 mg) por benefício na IC com deficiência de ferro. Manter losartana, anlodipino e furosemida 20 mg. Adicionar empagliflozina 10 mg. Retorno em 8 semanas.'),
  (1480, 437, 11, '2023-04-17 14:30', 'retorno', 'Melhorei do cansaço, mas fiz uns exames', 128, 72, 78, 63.0, 'Após ferro EV, Hb subiu para 11,6 e ferritina 220. Dispneia em franca melhora, passeia no parque com o marido. Colonoscopia: pólipo séssil de 1,2 cm em cólon ascendente, retirado, adenoma tubular com displasia de baixo grau. EDA com gastrite leve, sem sangramento. Sem sangue oculto. K 4,6 e creatinina 1,2 em uso de empagliflozina. Sem infecção genitourinária.', 'Manter empagliflozina, losartana, anlodipino e furosemida 20 mg. Controle de ferritina e Hb em 3 meses; repetir ferro EV se ferritina < 100 ou saturação < 20%. Colonoscopia de controle em 3 anos. Retorno em 3 meses.'),
  (1481, 437, 11, '2023-08-21 14:10', 'retorno', 'Estou ótima, voltei a fazer hidroginástica', 126, 70, 72, 62.4, 'CF NYHA I-II. Hb 12,4 g/dL, ferritina 160, saturação de transferrina 24%. NT-proBNP 310 (era 780). Sem edema, ausculta limpa, jugular normal. Furosemida 20 mg usada apenas quando o peso sobe 1,5 kg. Creatinina 1,2 e TFGe 46. HbA1c 6,6%. Hidroginástica 2x por semana, descobriu que gosta de dançar com o marido. Está atenta à função renal.', 'Manter esquema. Furosemida 20 mg SN conforme peso. Seguimento a cada 6 meses com ferritina e Hb. Vacinas anuais. Colonoscopia de controle conforme planejado.');
