insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (437, '2023-08-21', 'melhorou', 'ICFEp com sintomas agravados por anemia ferropriva, cuja causa foi um adenoma de cólon retirado na colonoscopia. Com ferro endovenoso e empagliflozina, NT-proBNP caiu de 780 para 310 e passou para CF I-II, sem necessidade de diurético fixo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (438, 'Alzira Bernardete Wolf Tavares', 'F', '1941-11-12', 'Tangará da Serra', 'MT', 'Agricultora aposentada', 'HAS há 40 anos em uso de losartana e hidroclorotiazida. FA paroxística documentada em 2019, recusou anticoagulante por medo de sangramento e usava apenas AAS. Mora com a filha. Magra, 55 kg. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1482, 438, 6, '2022-02-06 10:15', 'pronto_socorro', 'A boca entortou e não consegue falar', 186, 98, 124, null, 'Pcte de 80 anos, filha relata que às 08:50 acordou com desvio de rima à direita, afasia e hemiparesia direita, ficando muda e sem força. Ao exame: sonolenta, afasia global, NIHSS 17, PA 186x98. ECG: fibrilação atrial com resposta ventricular rápida de 124 bpm. Glicemia 118. TC de crânio sem sangramento, sinal de ACM hiperdensa à esquerda. Sem anticoagulante em uso e dentro da janela de trombólise (1h25 do início).', 'Código AVC acionado, angiotomografia e avaliação neurológica imediata. Trombólise indicada pela janela de 1h25 e ausência de anticoagulação; alteplase iniciada às 10:40 após controle da PA para < 185x110. Controle de FC com metoprolol EV titulado.'),
  (1483, 438, 13, '2022-02-06 15:30', 'internacao', 'Unidade de AVC', 150, 84, 92, 55.0, 'Pós-trombólise. Angiotomografia: oclusão de M1 esquerda sem recanalização, indicada trombectomia mecânica em serviço de referência: não transferida pelo risco e pela família. NIHSS 14 em 6h. TC de 24h: infarto extenso em território de ACM esquerda, sem transformação hemorrágica. ECO: átrio esquerdo 52 mm, FEVE 55%, sem valvopatia relevante. Creatinina 1,1. Mantida internada por 12 dias, com disfagia, necessitou de sonda nasoenteral.', 'Iniciar anticoagulação com apixabana 2,5 mg 12/12h no 7º dia (idade ≥ 80 e peso ≤ 60 kg) após TC sem hemorragia, suspender AAS. Atorvastatina 40 mg. Fonoaudiologia, fisioterapia motora, nutrição enteral. Suspender hidroclorotiazida por hiponatremia.'),
  (1484, 438, 13, '2022-04-11 09:00', 'retorno', 'Filha trouxe para consulta de seguimento', 140, 80, 76, 52.5, 'Dois meses após AVC cardioembólico. Persiste afasia de expressão importante, hemiparesia direita (força 2/5 em MSD, 3/5 em MID) e disfagia, em uso de gastrostomia por falência de reabilitação fonoaudiológica. Acamada/cadeira de rodas, dependente de cuidador. Rankin 4. Anticoagulada sem sangramentos. PA 140x80. Humor retraído. Filha cuidadora refere exaustão.', 'Manter apixabana 2,5 mg 12/12h, atorvastatina 40 mg e losartana 50 mg. Continuar reabilitação domiciliar e fonoaudiologia. Orientação à família sobre prevenção de úlceras de pressão e broncoaspiração. Encaminhar equipe de atenção domiciliar. Retorno em 3 meses.'),
  (1485, 438, 2, '2022-09-12 10:00', 'teleconsulta', 'Filha conta que ela continua do mesmo jeito', 132, 76, 80, null, 'Teleconsulta com a filha. Mantém afasia e hemiparesia direita, sem novas intercorrências. PA domiciliar medida pela agente de saúde 132x76, FC 80. Sem sangramentos, sem quedas. Alimentação por gastrostomia. Houve uma pneumonia aspirativa em julho tratada em domicílio. Fisioterapia domiciliar semanal. A filha é a cuidadora principal, muito cansada.', 'Manter apixabana 2,5 mg 12/12h, atorvastatina, losartana. Exames de creatinina e hemograma anuais. Apoio social e psicológico para a cuidadora. Retorno em 6 meses, presencial se possível.');
