insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (438, '2022-09-12', 'piorou', 'AVC cardioembólico extenso de ACM esquerda por FA sem anticoagulação (recusada previamente), com sequela grave: afasia, hemiparesia direita e disfagia com gastrostomia, Rankin 4. Anticoagulada com apixabana sem sangramentos e em assistência domiciliar.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (439, 'Jurema Pereira Santana Goulart', 'F', '1969-07-22', 'Luziânia', 'GO', 'Lavadeira', 'Nasceu em zona rural do interior de Minas Gerais, morou em casa de barro até os 18 anos. Sorologia positiva para Chagas há 15 anos, sem acompanhamento. HAS leve. Mãe faleceu ''do coração'' aos 58 anos. Quatro filhos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1486, 439, 4, '2021-02-22 09:00', 'consulta', 'Desmaio, coração dispara e cansaço', 104, 66, 108, 52.5, 'Mulher de 51 anos, chagásica conhecida, com 3 episódios de síncope e palpitações taquicárdicas no último mês, dispneia aos pequenos esforços (CF NYHA III) e edema vespertino. Ao exame: PA 104x66, FC 108 irregular, B3 presente, estertores em bases, edema de MMII 1+/4+. ECG: bloqueio de ramo direito e hemibloqueio anterior esquerdo, extrassístoles ventriculares frequentes. ETT: FEVE 25%, dilatação biventricular, aneurisma apical. Holter: TV sustentada de 30 s a 190 bpm.', 'Chagas crônica com cardiopatia grave, TV sustentada e síncope: indicado CDI para prevenção secundária. Não indicado benznidazol (cardiopatia estabelecida). Iniciar enalapril 5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg e furosemida 40 mg. Amiodarona 200 mg/dia para suprimir TV até o CDI.'),
  (1487, 439, 4, '2021-04-19 07:30', 'internacao', 'Internação eletiva para CDI', 110, 68, 64, 53.0, 'Compensada, CF NYHA II-III, sem síncopes após amiodarona. Implante de CDI dupla câmara, com acesso subclávio esquerdo, parâmetros adequados. Programada terapia antitaquicardia (ATP) antes de choque para TV, FV zona > 220 bpm. Sem complicações. Rx de tórax sem pneumotórax. Alta no 2º dia.', 'Manter amiodarona 200 mg/dia, enalapril, carvedilol, espironolactona, furosemida. Orientações sobre choques: procurar serviço se um choque e se > 1 choque seguido, acionar socorro. Retorno em 30 dias. TSH e função hepática a cada 6 meses por causa da amiodarona.'),
  (1488, 439, 6, '2022-03-14 14:20', 'pronto_socorro', 'Levei um choque no peito, três vezes', 92, 58, 118, 50.5, 'Pcte de 52 anos com CDI, relata 3 choques em 40 minutos enquanto lavava roupa. Dispneia, palpitações e mal-estar. ECG: taquicardia ventricular monomórfica a 118 bpm lenta, abaixo da zona de detecção do CDI. Interrogatório: choques apropriados por TV rápida e FV prévias. PA 92x58, estertores bibasais. Hipocalemia leve (K 3,3) e Mg 1,6. Cr 1,5, BNP 2.100. Provável descompensação com gatilho eletrolítico.', 'Reposição de K e Mg EV, amiodarona EV 150 mg e depois infusão, furosemida EV, monitorização. Internação para ajuste de terapia e programação do CDI. Aumentar carvedilol cautelosamente. Reforçar adesão e orientação.'),
  (1489, 439, 14, '2022-11-07 03:50', 'internacao', 'Dispneia intensa e fraqueza, não consegue andar', 84, 50, 124, 48.0, 'Admitida em UTI com IC avançada refratária: caquexia cardíaca, ascite, edema anasarca, extremidades frias, oligúria, lactato 4,2, Cr 2,8, Na 126. ECO: FEVE 18%, disfunção de VD, trombo apical de VE. Suporte com dobutamina e diuréticos EV, anticoagulação com heparina. Não candidata a transplante pelo quadro de caquexia, disfunção renal e condições sociais; discutidos cuidados paliativos com a família. Novos choques de CDI (2) na madrugada, parada cardiorrespiratória em FV às 03:50, revertida, depois bradicardia e atividade elétrica sem pulso. Óbito após 40 minutos de manobras, sem retorno.', 'Comunicado óbito à família. Orientação para rastreio sorológico dos filhos para Chagas. Orientações de atestado de óbito: choque cardiogênico por cardiopatia chagásica.');
