insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (439, '2022-11-07', 'obito', 'Cardiopatia chagásica grave com TV sustentada, CDI com choques múltiplos e IC refratária. Faleceu em UTI por choque cardiogênico e parada cardiorrespiratória, não candidata a transplante. Filhos encaminhados para triagem sorológica de Chagas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (440, 'Adriano Luiz Zimmermann Pontes', 'M', '1963-12-03', 'Porto Alegre', 'RS', 'Contador', 'Sopro cardíaco conhecido desde a juventude, nunca investigado. HAS leve em uso de losartana. Ex-corredor amador de maratonas, parou há 2 anos por cansaço. Sem tabagismo, bebe vinho nas refeições.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1490, 440, 2, '2023-01-23 15:00', 'consulta', 'Falta de ar para correr e palpitações', 134, 76, 82, 79.0, 'Homem de 59 anos com dispneia progressiva aos esforços e palpitações esporádicas há 1 ano. Ao exame: sopro holossistólico 3+/6+ em foco mitral irradiado para axila, B3 audível, sem edema, estertores raros. ECG: FA paroxística documentada em Holter prévio. ETT: prolapso do folheto posterior (P2) com insuficiência mitral grave excêntrica, VE com DDVE 62 mm, DSVE 41 mm, FEVE 58%, átrio esquerdo 54 mm, PSAP 44 mmHg.', 'Indicação cirúrgica por IM primária grave sintomática. Solicitada ETE para avaliar reparabilidade e CATE para estratificação. Iniciar apixabana 5 mg 12/12h (CHA2DS2-VASc 1 mas FA paroxística com IM grave). Encaminhar à cirurgia cardiovascular.'),
  (1491, 440, 12, '2023-04-17 07:00', 'internacao', 'Internação para plastia mitral', 128, 72, 70, 78.5, 'ETE confirmou prolapso isolado de P2 com cordas rotas, reparável. CATE sem lesões coronárias. Realizada plastia valvar mitral com ressecção quadrangular de P2, anuloplastia com anel rígido 34 mm e ablação cirúrgica de FA (Cox-Maze simplificado) com fechamento do apêndice atrial esquerdo. Separação de CEC sem intercorrências. ETE intraoperatório sem IM residual. UTI por 2 dias, alta no 8º dia em ritmo sinusal.', 'Varfarina por 3 meses com alvo de INR 2-3 (anel protético), em seguida reavaliar. Amiodarona 200 mg/dia por 3 meses. Metoprolol succinato 25 mg. Reabilitação. Retorno em 30 dias com ECO e INR.'),
  (1492, 440, 2, '2023-06-12 15:30', 'retorno', 'Voltei a caminhar, quero saber se posso correr', 122, 74, 62, 80.2, 'Dois meses de pós-operatório. Assintomático, caminha 6 km, sem dispneia nem palpitações. Ferida esternal ok. ECO: reparo mitral competente, IM mínima, gradiente médio de 3 mmHg, FEVE 55%, redução do átrio esquerdo para 44 mm, PSAP 28. Holter: ritmo sinusal 100%, sem FA. INR 2,4 com varfarina 5 mg 5 dias/semana e 2,5 mg nos outros dias. Sem sangramentos.', 'Suspender varfarina em 1 mês (completa 3 meses de INR) e manter AAS 100 mg. Manter metoprolol. Suspender amiodarona ao final de 3 meses. Reabilitação cardíaca para progressão a corrida leve. Profilaxia de endocardite antes de procedimentos dentários indicada pelo anel protético; manter boa higiene oral.');
