insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (440, '2023-06-12', 'melhorou', 'Insuficiência mitral grave por prolapso tratada com plastia mitral e ablação cirúrgica de FA, mantendo ritmo sinusal. Assintomático, IM residual mínima, átrio esquerdo reduzido de 54 para 44 mm e liberado para reabilitação e corrida leve.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (441, 'Ozéas Benedito Ferrari Quintanilha', 'M', '1957-03-02', 'Trindade', 'GO', 'Pedreiro', 'HAS há 20 anos, DM2 há 10 anos, dislipidemia, tabagista de 40 maços-ano, ainda fumando. Pai morreu de infarto aos 58 anos. Nunca fez exame de esforço. Toma losartana e metformina de forma irregular, ''quando lembra''.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1493, 441, 1, '2022-06-13 08:30', 'consulta', 'Aperto no peito quando carrego saco de cimento', 158, 94, 84, 87.0, 'Homem de 65 anos com dor retroesternal em aperto aos esforços (carregar peso, subir laje) há 2 meses, com alívio ao repouso em 5 a 10 minutos. Piora recente: agora com esforços menores, CCS III. Exame sem sopros, pulsos periféricos diminuídos em pés. ECG com ondas Q em derivação inferior (IAM antigo silencioso?). ETT: FEVE 48%, acinesia inferior. LDL 168 mg/dL, HbA1c 9,0%. Alto risco. Indicada cinecoronariografia.', 'Iniciar AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg, mononitrato de isossorbida. Solicitado CATE com urgência. Orientado a parar de fumar. Paciente relutante: ''se eu parar de trabalhar a família passa fome''. Retorno em 15 dias com o exame.'),
  (1494, 441, 6, '2022-10-21 04:15', 'pronto_socorro', 'Dor insuportável no peito há 1 hora, suor frio', 82, 50, 118, null, 'Pcte 65 anos, não fez o cateterismo (''não consegui folga''), parou os remédios e voltou ao cigarro. Dor precordial em aperto intensa há 1h, sudorese, palidez, extremidades frias e dispneia. PA 82x50, FC 118, SpO2 86%, estertores até ápices. ECG: supradesnivelamento de ST de 5 mm V1-V6 e DI-aVL. Troponina 12,4. Killip IV: choque cardiogênico por IAM de parede anterior extensa. Lactato 5,2.', 'Ativado protocolo de IAM. AAS 300 mg e ticagrelor 180 mg, heparina, noradrenalina para PAM > 65, intubação orotraqueal por insuficiência respiratória. Encaminhado imediatamente para angioplastia primária com balão intra-aórtico. Família informada da gravidade e do prognóstico reservado.'),
  (1495, 441, 14, '2022-10-21 06:30', 'internacao', 'UTI, pós-angioplastia em choque cardiogênico', 88, 54, 110, null, 'CATE: oclusão trombótica da DA proximal, lesão de 90% em CD e Cx ocluída crônica, doença triarterial. Angioplastia primária da DA com stent farmacológico, TIMI 3 final. Balão intra-aórtico, noradrenalina e dobutamina. ECO: FEVE 15%, hipocinesia difusa e acinesia anterior. Anúria nas primeiras 10h, Cr 2,4, lactato mantido alto, hipotensão persistente. Evoluiu com TV sustentada às 11h, cardiovertida, e parada em assistolia às 13:40, sem resposta a 35 minutos de reanimação.', 'Suporte máximo em UTI. Óbito declarado às 14:15 após manobras de reanimação sem sucesso. Família acompanhada pela equipe e pelo serviço social.');
