insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (441, '2022-10-21', 'obito', 'Faleceu em UTI por choque cardiogênico refratário após infarto anterior extenso em doença triarterial, apesar de angioplastia primária e balão intra-aórtico. Não realizou o cateterismo solicitado em junho e abandonou medicação e tratamento antes do evento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (442, 'Genésio Aparício Lourenço Meirelles', 'M', '1964-12-20', 'Cuiabá', 'MT', 'Churrasqueiro', 'Etilismo pesado há 30 anos (garrafa de cachaça por dia), tabagista. HAS leve. Duas internações por pancreatite aguda. Sem diabetes. Sem filhos, mora com a irmã. Começou a ter falta de ar há 4 meses.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1496, 442, 11, '2023-03-20 09:00', 'consulta', 'Falta de ar e pernas inchadas, já não consigo trabalhar', 118, 76, 102, 71.0, 'Homem de 58 anos, etilista crônico (cerca de 250 g de álcool/dia), com dispneia aos mínimos esforços, ortopneia e edema 3+/4+ há 4 meses. Emagrecido, sinais de má nutrição. PA 118x76, FC 102 regular, B3, estertores até meio dos campos, hepatomegalia dolorosa, ascite discreta. ECO: FEVE 24%, VE muito dilatado (DDVE 72 mm). Coronariografia sem lesões obstrutivas. Hemoglobina 11,2, TSH normal, ferritina normal, sorologia para Chagas negativa. HD: cardiomiopatia alcoólica com ICFEr.', 'Abstinência total do álcool como medida principal, apoio do CAPS-AD. Tiamina 300 mg/dia. Iniciar enalapril 2,5 mg 12/12h, carvedilol 3,125 mg 12/12h, espironolactona 25 mg, furosemida 40 mg. Dapagliflozina 10 mg depois de 15 dias. Retorno em 15 dias.'),
  (1497, 442, 11, '2023-04-10 09:20', 'retorno', 'Estou há 18 dias sem beber', 110, 70, 88, 66.5, 'Manteve abstinência há 18 dias, com ajuda da irmã e do CAPS-AD, sofrimento por tremores iniciais já passados. Perdeu 4,5 kg de líquido, ortopneia melhor, edema 1+/4+. Cr 1,1, K 4,5. Sem tontura. Tolera medicamentos. Ainda cansaço aos médios esforços, CF NYHA III. Emocionado: ''é a primeira vez que consigo passar tantos dias''.', 'Adicionar dapagliflozina 10 mg. Aumentar enalapril para 5 mg 12/12h e carvedilol para 6,25 mg 12/12h. Reforçar abstinência e dieta com apoio nutricional. Retorno em 4 semanas com K e creatinina.'),
  (1498, 442, 11, '2023-09-18 09:10', 'retorno', 'Seis meses sem beber, voltei a trabalhar', 114, 72, 66, 68.8, 'Seis meses de abstinência confirmada (GGT normalizada, VCM normal). Ganhou massa magra, peso estável em 68,8 kg. CF NYHA I-II. Voltou ao trabalho no churrasco, sem beber. ECO: FEVE 38%, DDVE 64 mm, IM leve. NT-proBNP 880. Carvedilol 12,5 mg 12/12h já titulado. Furosemida usada apenas se edema. Ainda tabagista, 10 cigarros/dia. Irmã controla a dieta e a medicação.', 'Manter quatro pilares. Reduzir furosemida para 20 mg. Trocar enalapril por sacubitril/valsartana 24/26 mg se persistir FEVE < 40%, após 36 h sem IECA, no próximo retorno. Terapia de cessação do tabagismo. ECO em 6 meses.'),
  (1499, 442, 11, '2024-06-24 09:30', 'retorno', 'Um ano e três meses sem uma gota', 112, 70, 62, 72.5, 'Um ano e três meses de abstinência. Assintomático, CF NYHA I, caminha 5 km, trabalha no churrasco sem beber, reaproximou-se da família. Parou de fumar há 5 meses. ECO: FEVE 48%, DDVE 58 mm, IM mínima. NT-proBNP 210. Cr 1,1, K 4,6. Sem edema. Sem efeitos colaterais. Peso aumentou com recuperação nutricional.', 'Recuperação importante da função ventricular. Manter enalapril 10 mg 12/12h, carvedilol 12,5 mg, espironolactona e dapagliflozina; suspender furosemida. Não reduzir os pilares da IC antes de 12 meses com FEVE normal. Seguir apoio do CAPS-AD. Retorno em 6 meses.');
