insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (442, '2024-06-24', 'melhorou', 'Cardiomiopatia alcoólica com FEVE 24% que recuperou para 48% após abstinência alcoólica sustentada e terapia dos quatro pilares. Assintomático, CF NYHA I, sem tabagismo e trabalhando normalmente.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (443, 'Edinalva Corrêa Quaresma Paixão', 'F', '1953-05-30', 'Paraíso do Tocantins', 'TO', 'Costureira aposentada', 'HAS há 30 anos, artrose de joelhos e coluna com dor crônica, usa diclofenaco por conta própria. FA permanente diagnosticada em 2023 em UBS. Sem diabetes. Mora com o marido, que também é idoso. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1500, 443, 2, '2024-02-05 09:00', 'consulta', 'Coração batendo irregular e cansaço', 142, 86, 96, 67.0, 'Mulher de 70 anos, FA permanente, em uso de rivaroxabana 20 mg que recebeu da UBS junto de losartana e metoprolol, sem orientação sobre AINE. Queixas de cansaço aos esforços; refere dor nos joelhos e uso de diclofenaco 50 mg 2x/dia há meses. CHA2DS2-VASc 3 (idade 65-74, sexo feminino, HAS). Creatinina 0,9 (ClCr 62), Hb 12,6. ECO: átrio esquerdo 49 mm, FEVE 58%. FC 96 em repouso.', 'Manter rivaroxabana 20 mg junto ao jantar. Alerta: suspender diclofenaco pelo risco de sangramento digestivo com anticoagulante e pelo efeito na PA. Dipirona SN e paracetamol para dor. Aumentar metoprolol succinato para 50 mg. Orientada sobre sinais de sangramento. Retorno em 6 semanas.'),
  (1501, 443, 6, '2024-03-28 02:50', 'pronto_socorro', 'Vomitei sangue e as fezes estão pretas', 84, 52, 122, null, 'Pcte 70 anos, em uso de rivaroxabana, volta a usar diclofenaco para dor no joelho (aliviava a dor ''que o paracetamol não resolvia''). Início há 12h com epigastralgia, hematêmese em borra de café e 2 episódios de melena. Pálida, sudoréica, PA 84x52, FC 122, FA de alta resposta. Hb 6,8 g/dL (era 12,6), ureia 92, creatinina 1,3. INR 1,6. Abdome sem peritonismo. Choque hemorrágico classe III por hemorragia digestiva alta.', 'Suspender rivaroxabana e diclofenaco. Dois acessos calibrosos, cristaloide, transfusão de 2 concentrados de hemácias, omeprazol 80 mg EV em bolus e 8 mg/h. EDA nas primeiras 24h. Reversão do anticoagulante com andexanet/concentrado de complexo protrombínico se instabilidade. Internação em UTI.'),
  (1502, 443, 2, '2024-05-06 09:30', 'retorno', 'Vim ver se posso voltar a tomar o remédio de afinar o sangue', 136, 82, 80, 65.0, 'Seis semanas após hemorragia digestiva alta. EDA na internação: úlcera duodenal Forrest IIb tratada com clipes, H. pylori positivo, erradicado com terapia tríplice. Recebeu 3 concentrados de hemácias. Hb atual 11,8. Sem melena desde alta. Usa omeprazol, não usa mais diclofenaco. Muito assustada: ''não quero mais saber desse remédio de sangue, quase morri''. Marido entende o risco. Ressalto CHA2DS2-VASc 3 e HAS-BLED 3 (idade, AINE, sangramento).', 'Reiniciar anticoagulação com apixabana 5 mg 12/12h, com inibidor de bomba contínuo, após cicatrização da úlcera. Nunca mais usar AINE. Hb e creatinina em 30 dias. Retorno em 4 semanas. Discutida possibilidade de oclusão do apêndice atrial caso ela recuse anticoagular.');
