insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (443, '2024-09-10', 'abandonou', 'Após hemorragia digestiva alta grave por AINE e anticoagulante, recebeu orientação para reiniciar apixabana, mas não retornou ao agendamento de junho nem aos contatos. Segundo o agente comunitário, suspendeu o anticoagulante por medo de novo sangramento, permanecendo em FA sem proteção.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (444, 'Mauro Hiroshi Kimura Albuquerque', 'M', '1971-08-14', 'Brasília', 'DF', 'Engenheiro civil', 'HAS leve em uso de losartana 50 mg. Triatleta amador, corre 40 km por semana. Bebe vinho nos fins de semana e um café forte pela manhã. Sem diabetes. Sem história familiar de FA. Apneia leve tratada com perda de peso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1503, 444, 4, '2022-09-12 18:00', 'consulta', 'Não consigo mais correr como antes, o coração dispara', 132, 80, 98, 78.0, 'Homem de 51 anos, atleta amador, com episódios de palpitações irregulares cada vez mais longos (último de 3 dias), queda de desempenho e cansaço ao treino. ECG de consultório: fibrilação atrial, FC 98. TSH normal, ECO: átrio esquerdo 44 mm, FEVE 60%, sem valvopatia. Teste ergométrico: FA conduzida a 175 bpm no esforço. CHA2DS2-VASc 1 (HAS). Quadro de FA persistente sintomática em jovem, atleta, que não quer fármaco antiarrítmico.', 'Estratégia de controle do ritmo com ablação por cateter (isolamento das veias pulmonares), após período de anticoagulação. Iniciar apixabana 5 mg 12/12h. Orientado a reduzir café e álcool, evitar excesso de volume de treino. Cardioversão eletiva antes da ablação.'),
  (1504, 444, 4, '2022-11-08 07:00', 'internacao', 'Internação eletiva para ablação de FA', 126, 76, 92, 77.5, 'Após 8 semanas de anticoagulação, internado em FA. ETE sem trombo em apêndice atrial esquerdo. Ablação por crioenergia (crioablação com balão) das quatro veias pulmonares, com isolamento elétrico confirmado em todas, sob anestesia geral. Reversão para ritmo sinusal ao final do procedimento. Sem complicações (sem tamponamento, sem lesão do nervo frênico). Alta no dia seguinte.', 'Manter apixabana por no mínimo 3 meses após ablação. Repouso relativo por 7 dias, sem corrida por 3 semanas. Metoprolol succinato 25 mg. Retorno em 30 dias com ECG e depois em 3 meses com Holter.'),
  (1505, 444, 4, '2023-02-20 18:10', 'retorno', 'Voltei a treinar, tive uns ''sustos''', 124, 74, 60, 76.8, 'Três meses depois, retomou treino leve. Teve dois episódios breves de palpitações nas primeiras semanas (período de blanking esperado). Holter 24h: ritmo sinusal 100%, extrassístoles atriais raras, sem FA. ECG ritmo sinusal 60. Sem sangramentos, sem dor torácica. Bebe café com moderação. Sem queixas.', 'Suspender apixabana após 3 meses (CHA2DS2-VASc 1 e ritmo sinusal). Manter losartana 50 mg. Suspender metoprolol. Retorno em 6 meses com Holter de 7 dias.'),
  (1506, 444, 4, '2023-09-11 18:00', 'retorno', 'Corri uma meia maratona sem problemas', 120, 72, 56, 75.5, 'Dez meses após ablação, assintomático, treina normalmente e fez meia maratona em 1h50. Holter de 7 dias: ritmo sinusal 100%, FC média 58 bpm, sem FA. ECO: átrio esquerdo 38 mm, FEVE 62%. PA 120x72. Reduziu o álcool, sem sintomas. Satisfeito: ''me devolveu a vida de atleta''.', 'Sem antiarrítmico e sem anticoagulante. Manter losartana. Seguimento anual com Holter e ECG, ou antes se palpitações. Orientações de prevenção de recorrência: sono, álcool moderado e peso.');
