insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (444, '2023-09-11', 'controlado', 'Fibrilação atrial persistente sintomática em atleta tratada com crioablação de veias pulmonares. Em ritmo sinusal há 10 meses sem antiarrítmico nem anticoagulante, treinando normalmente e com átrio esquerdo reduzido para 38 mm.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (445, 'Raimunda Tarsila Cardoso Furtado', 'F', '1974-09-11', 'Belém', 'PA', 'Vendedora de açaí', 'Febre reumática na infância, sem profilaxia regular com penicilina benzatina. Sopro cardíaco conhecido. Não tem HAS. Quatro filhos, trabalha em pé na feira desde madrugada. Nega tabagismo. Há 1 ano falta de ar progressiva.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1507, 445, 2, '2023-03-13 08:40', 'consulta', 'Falta de ar para carregar rasa de açaí e palpitações', 108, 68, 104, 58.0, 'Mulher de 48 anos com sequela de febre reumática, dispneia aos médios esforços (CF NYHA III), palpitações irregulares e tosse noturna. Ao exame: rubor malar, 1ª bulha hiperfonética, estalido de abertura e ruflar diastólico em foco mitral, RCR irregular em 2T, FC 104. ECG: fibrilação atrial. ETT: estenose mitral reumática grave (área valvar 0,9 cm², gradiente médio 14 mmHg), átrio esquerdo 58 mm, FEVE 62%, PSAP 54 mmHg, sem trombo visível ao ETE.', 'FA com estenose mitral moderada/grave: anticoagular com varfarina (DOAC contraindicado), alvo de INR 2-3. Iniciar com heparina e varfarina 5 mg, metoprolol succinato 50 mg para FC, furosemida 20 mg. Solicitar ETE e avaliar valvuloplastia por balão. Penicilina benzatina 1.200.000 UI a cada 21 dias.'),
  (1508, 445, 2, '2023-04-17 08:50', 'retorno', 'Fiz o exame do sangue, dizem que está fraco', 106, 66, 82, 57.2, 'Quatro semanas de varfarina. INR de hoje 1,6, subterapêutico, após dois dias em que esqueceu a dose e comeu muitas folhas verdes (maniçoba na semana). FC 82 sob metoprolol, dispneia um pouco melhor. ETE: sem trombo em apêndice atrial, contraste espontâneo denso em átrio esquerdo, valva com folhetos de mobilidade preservada, sem calcificação grave, sem IM significativa, escore de Wilkins 7. Candidata a valvuloplastia mitral por balão.', 'Aumentar varfarina para 7,5 mg 3 dias/semana e 5 mg nos outros, INR em 7 dias. Orientação nutricional sobre vitamina K. Programar valvuloplastia mitral percutânea por balão em hemodinâmica após INR estável e 3 semanas de anticoagulação adequada.'),
  (1509, 445, 10, '2023-06-26 07:30', 'internacao', 'Valvuloplastia mitral por balão', 112, 70, 78, 57.0, 'INR 2,4 nas últimas 3 semanas. Realizada valvuloplastia mitral percutânea por balão (técnica de Inoue) com punção transeptal. Área valvar passou de 0,9 para 1,9 cm², gradiente médio de 14 para 5 mmHg, sem aumento da insuficiência mitral (grau leve). Sem tamponamento, sem embolia. PSAP caiu de 54 para 36 mmHg. Alta no dia seguinte, dispneia ausente.', 'Manter varfarina (FA persistente com EM), metoprolol, penicilina benzatina. Suspender furosemida. ECO de controle em 30 dias. Retorno em 30 dias com INR. Reforçar a profilaxia da febre reumática.'),
  (1510, 445, 2, '2024-01-22 08:40', 'retorno', 'Controle do coração, estou muito melhor', 110, 68, 68, 60.5, 'Sete meses após valvuloplastia. Sem dispneia, trabalha na feira normalmente, CF NYHA I. ECO: área mitral 1,8 cm², gradiente médio 6 mmHg, IM leve, PSAP 32 mmHg, átrio esquerdo 54 mm. FA persistente com FC 68 sob metoprolol. INR nos últimos 6 meses dentro de 2-3 em 75% das medidas, usa caderneta de controle. Sem sangramentos. Recebe penicilina na UBS a cada 3 semanas.', 'Manter varfarina com INR mensal, metoprolol e penicilina benzatina. ECO anual. Se reestenose, nova valvuloplastia ou troca valvar. Avisar em caso de gravidez, que é contraindicada com varfarina. Retorno em 6 meses.');
