insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (445, '2024-01-22', 'melhorou', 'Estenose mitral reumática grave com FA tratada com valvuloplastia por balão, aumentando a área valvar de 0,9 para 1,8 cm². Assintomática, CF NYHA I, anticoagulada com varfarina e em profilaxia secundária com penicilina benzatina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (446, 'Arlindo Cipriano Machado Neto', 'M', '1958-01-25', 'Uberaba', 'MG', 'Ex-lavrador', 'Chagas crônica conhecida desde 2010, nasceu em fazenda em Minas Gerais. IC com FEVE 32%, em uso de enalapril, carvedilol e espironolactona. Tabagista antigo (parou há 8 anos). Ficou sem anticoagulação apesar do trombo apical visto em ECO anterior, por receio do paciente.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1511, 446, 11, '2023-04-10 09:00', 'consulta', 'Cansaço aos médios esforços e a perna esquerda esquenta e esfria', 104, 66, 60, 64.0, 'Homem de 65 anos, chagásico com ICFEr, CF NYHA II-III. FC 60, PA 104x66, sem congestão. Queixa de episódios de frieza e dor em pé esquerdo ao caminhar. ECO: FEVE 30%, aneurisma apical de 3 cm com trombo laminar de 1,8 cm, átrio esquerdo 46 mm. Holter com EV frequentes e episódios de TVNS. BNP 640. Cr 1,2, K 4,8. Indicada anticoagulação oral com varfarina pelo trombo apical, apesar da resistência do paciente.', 'Iniciar varfarina 5 mg com alvo INR 2-3 e controle semanal. Não usar DOAC por indicação de varfarina em trombo mural de cardiomiopatia chagásica. Manter enalapril 10 mg 12/12h, carvedilol 12,5 mg 12/12h, espironolactona 25 mg. Avaliar dapagliflozina. Examinar pulsos em todos os retornos.'),
  (1512, 446, 6, '2023-04-24 03:20', 'pronto_socorro', 'A perna esquerda ficou gelada e sem sensibilidade', 138, 84, 72, null, 'Pcte com início súbito há 4h de dor intensa, palidez, parestesia e frialdade em perna esquerda, sem pulsos distais palpáveis em poplítea, tibial e pediosa à esquerda. Perna direita normal. Sensibilidade e motricidade parcialmente diminuídas (isquemia Rutherford IIb). Estava tomando a varfarina havia 2 semanas, INR 1,4. Embolia arterial aguda de origem cardíaca (trombo apical de VE). Doppler: sem fluxo em artéria poplítea esquerda, fluxo normal à direita.', 'Heparina não fracionada em bolus e infusão, analgesia, aquecimento passivo. Cirurgia vascular de emergência para embolectomia com cateter de Fogarty. Avisar ao centro cirúrgico, transferência imediata.'),
  (1513, 446, 12, '2023-04-24 08:30', 'internacao', 'Pós-operatório de embolectomia', 124, 78, 76, 64.0, 'Embolectomia femoropoplítea com Fogarty em perna esquerda sob raquianestesia, retirando trombo longo, com retorno de fluxo na poplítea e pulso pedioso fraco. Fasciotomia profilática da perna. Após 12h, edema e CPK 18.000, Cr de 1,2 para 1,9. No 5º dia, manchas de necrose em hálux e 2º pododáctilo. Mantida heparina e depois varfarina com alvo INR 2-3. Mioglobinúria tratada com hidratação.', 'Heparina até INR 2 por 2 dias consecutivos, depois varfarina isolada. Cuidados com a ferida de fasciotomia. Desbridamento dos dedos necróticos adiado. Alta no 14º dia com curativos, controle de creatinina e retorno ambulatorial. Manter terapia de IC.'),
  (1514, 446, 11, '2023-09-18 09:20', 'retorno', 'Perdi dois dedos do pé e ainda sinto dor', 108, 68, 62, 61.0, 'Cinco meses depois da embolia arterial, ficou com sequela: amputação do hálux e do 2º pododáctilo esquerdos e dor neuropática no pé. Marcha com muleta. Desânimo importante. INR 2,3, sem sangramentos, adesão agora rigorosa. FEVE 29%, trombo apical em redução (1,0 cm). Cr 1,2, K 4,9. CF NYHA III, mais cansaço pelo repouso prolongado. PA 108x68, FC 62.', 'Manter varfarina e controlar INR a cada 2 semanas. Adicionar dapagliflozina 10 mg. Trocar enalapril por sacubitril/valsartana quando PA permitir. Encaminhar à reabilitação física e ao serviço de dor. Avaliar CDI para prevenção primária e transplante em centro de referência.');
