insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (446, '2023-09-18', 'piorou', 'Cardiopatia chagásica com trombo apical que embolizou para a perna esquerda após demora em anticoagular, exigindo embolectomia, com sequela de amputação de dois dedos, lesão renal aguda e piora funcional. Mantido em varfarina e encaminhado para avaliação de CDI e transplante.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (447, 'Keilla Cristina Brandão Moura', 'F', '1992-06-17', 'Gurupi', 'TO', 'Técnica de enfermagem', 'Palpitações súbitas desde os 20 anos, crises raras que melhoravam com manobras vagais. Sem outras doenças. Faz plantões de 12 horas e usa energéticos. Sem uso de medicamentos. Mãe com taquicardia ''nervosa''.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1515, 447, 4, '2023-11-08 14:00', 'consulta', 'Crises de coração acelerado, cada vez mais frequentes', 108, 66, 72, 59.0, 'Mulher de 31 anos com crises de taquicardia regular de início e fim súbitos, 4 em 2 meses, a última de 40 minutos com tontura. Exame normal. ECG de repouso: PR curto (96 ms), onda delta positiva em V4-V6 e negativa em aVL, sugerindo via acessória lateral esquerda. ECO normal. Holter sem episódios. Explicado risco de arritmias com condução rápida pela via acessória, especialmente se evoluir com fibrilação atrial.', 'Quadro de síndrome de Wolff-Parkinson-White sintomática. Indicado estudo eletrofisiológico com ablação da via acessória. Evitar energéticos. Orientada a procurar emergência se crise com síncope ou dor torácica. Aguardar vaga em serviço de eletrofisiologia.'),
  (1516, 447, 6, '2024-01-14 22:40', 'pronto_socorro', 'Coração disparou de repente, quase desmaiei no plantão', 92, 58, 214, 59.0, 'Pcte 31 anos, técnica de enfermagem, palpitações súbitas há 30 min, tontura intensa e pré-síncope, após ingestão de energético. FC 214 bpm, PA 92x58. ECG: taquicardia irregular de QRS largo com variação do intervalo RR e morfologias diferentes, compatível com fibrilação atrial pré-excitada (WPW). Instabilidade hemodinâmica leve. Contraindicados adenosina, verapamil, diltiazem, betabloqueadores EV e digoxina.', 'Cardioversão elétrica sincronizada sob sedação, 100 J, restabelecendo ritmo sinusal com onda delta evidente. Observação por 6h em monitorização, sem recidiva. Programada ablação em caráter prioritário. Alta com orientação clara: evitar medicamentos que bloqueiam o nó AV. Contato direto com arritmologia.'),
  (1517, 447, 4, '2024-02-27 07:30', 'internacao', 'Estudo eletrofisiológico e ablação', 110, 68, 74, 58.8, 'Estudo eletrofisiológico: via acessória manifesta de parede livre lateral esquerda, período refratário anterógrado de 220 ms (risco alto), indução de taquicardia atrioventricular ortodrômica e de FA com condução pré-excitada rápida (RR mínimo 190 ms). Ablação por radiofrequência por acesso transeptal com perda da pré-excitação em 2 s, confirmada bloqueio anterógrado e retrógrado da via, sem reindução. Sem complicações. Alta no dia seguinte.', 'Sem antiarrítmicos. Repouso por 3 dias. ECG de controle em 6 semanas. Orientação sobre sinais de recorrência. Liberada para voltar ao trabalho em 1 semana. Alta da arritmologia se ECG sem delta.'),
  (1518, 447, 4, '2024-04-08 14:20', 'retorno', 'Sem crises depois da cirurgia, vim para a alta', 106, 64, 68, 59.5, 'Dez semanas após ablação, sem nenhuma crise, trabalhando em plantões noturnos. ECG: ritmo sinusal 68 bpm, PR 146 ms, sem onda delta, QRS estreito. Holter de 24h sem arritmias. Parou com energéticos. Pergunta se pode engravidar, quer ser mãe nos próximos anos.', 'Cura da pré-excitação. Alta da arritmologia. Não há restrições para gravidez do ponto de vista cardiológico; acompanhar com obstetrícia rotineiramente. Retorno somente se palpitações.');
