insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (447, '2024-04-08', 'controlado', 'Síndrome de Wolff-Parkinson-White com fibrilação atrial pré-excitada tratada com cardioversão elétrica e ablação por radiofrequência da via acessória lateral esquerda. Sem pré-excitação ou crises, em alta da arritmologia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (448, 'Ermelinda Soares Bastos Lacerda', 'F', '1941-02-08', 'Ceilândia', 'DF', 'Costureira aposentada', 'HAS há 40 anos em uso de losartana e anlodipino. Hipotireoidismo tratado. Duas quedas em 2022. Tontura frequente, desmaiou na cozinha em maio. Mora com a neta. Evita sair de casa por medo de cair.', 'Alergia a dipirona (angioedema)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1519, 448, 4, '2023-06-05 09:30', 'consulta', 'Tonturas e desmaios, caí duas vezes no mês', 138, 68, 44, 59.0, 'Mulher de 82 anos com síncope e pré-síncope há 2 meses, tontura ao esforço leve, cansaço e confusão. Ao exame: bradicardia 44 bpm regular, PA 138x68, sem sopros relevantes, sem edema. Sem uso de betabloqueador ou digoxina; usa losartana e anlodipino. ECG: bradicardia sinusal 44 bpm, ritmo sinusal com pausas ocasionais de 2,4 s. Holter: FC média 48, pausas até 5,2 s (em vigília), fibrilação atrial paroxística curta com taquicardia seguida de pausa (síndrome taquicardia-bradicardia). TSH 2,3.', 'Doença do nó sinusal sintomática (síndrome bradi-taquicardia), sem causa reversível: indicado marca-passo definitivo. Evitar fármacos cronotrópicos negativos. Encaminhar à internação eletiva. Recomendações de segurança em casa para evitar quedas.'),
  (1520, 448, 4, '2023-07-03 08:00', 'internacao', 'Implante de marca-passo', 144, 72, 46, 59.0, 'Implante de marca-passo definitivo dupla câmara (DDDR) por veia cefálica esquerda sob anestesia local e sedação leve, com parâmetros ótimos: limiar atrial 0,7 V, ventricular 0,6 V. Sem complicações, Rx de tórax sem pneumotórax. Estimulação atrial predominante. Sem síncope após o implante. Alta no 2º dia, com orientação do cuidador e da neta.', 'Cuidados com a ferida por 10 dias. Evitar elevar braço esquerdo acima do ombro por 4 semanas. Iniciar apixabana 2,5 mg 12/12h para FA paroxística (CHA2DS2-VASc 4: idade ≥ 75 = 2, sexo, HAS), pois tem 82 anos e peso 59 kg. Retorno em 30 dias.'),
  (1521, 448, 4, '2023-08-07 09:00', 'retorno', 'Não caí mais, estou saindo de casa', 132, 70, 64, 60.2, 'Um mês de marca-passo. Sem síncope nem tonturas, já vai à padaria sozinha. Ferida cicatrizada. Interrogatório: 84% de estimulação atrial, 3% ventricular, sem arritmias atriais registradas, bateria 100%. FC 64 bpm. Neta relata que ''minha avó voltou a conversar normalmente''. Sem sangramentos na apixabana. Hb 12,2, Cr 0,9.', 'Manter apixabana 2,5 mg 12/12h, losartana. Anlodipino segue suspenso desde a primeira consulta por tontura, com PA aceitável só com losartana. Retorno em 6 meses com interrogatório do MP. Estimular caminhada e fisioterapia para equilíbrio.');
