insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (448, '2023-08-07', 'controlado', 'Doença do nó sinusal com síncopes e quedas, resolvida com marca-passo dupla câmara. Sem desmaios há um mês, voltou a sair de casa sozinha e mantém anticoagulação por FA paroxística, em controle semestral do dispositivo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (449, 'Cauã Rodrigues Valverde', 'M', '1982-10-04', 'Goiânia', 'GO', 'Motoboy', 'Valva aórtica bicúspide conhecida desde os 25 anos, sem seguimento regular. Cárie dentária extensa e abscesso dentário não tratado há 2 meses. Sem comorbidades. Fuma maconha ocasionalmente. Trabalha 12 horas por dia entregando pedidos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1522, 449, 6, '2025-02-10 23:10', 'pronto_socorro', 'Febre há 3 semanas, suor, cansaço e falta de ar', 104, 40, 118, 66.0, 'Pcte 42 anos, motoboy, febre diária de até 39,5 ºC há 3 semanas, sudorese noturna, perda de 7 kg, astenia e dispneia progressiva, ortopneia. Dente com abscesso ainda não tratado. Ao exame: emagrecido, pálido, PA 104x40 (pressão de pulso alargada), pulso em martelo d''água, sopro diastólico aspirativo 3+/4+ em foco aórtico, sopro sistólico novo, estertores em bases, hemorragias em estilhaço em unhas, petéquias na conjuntiva. Hb 8,9, leucócitos 17.800 com desvio, PCR 160, VHS 98.', 'Coletadas 3 hemoculturas em horários distintos antes do antibiótico, ecocardiograma urgente. Iniciar empiricamente vancomicina 25 mg/kg e ceftriaxona 2 g 12/12h, mais gentamicina conforme infectologia. Internação em UTI.'),
  (1523, 449, 14, '2025-02-11 08:30', 'internacao', 'UTI: endocardite com insuficiência aórtica grave', 98, 36, 124, 66.0, 'ETE: valva aórtica bicúspide com vegetação móvel de 16 mm no folheto não coronariano e perfuração, insuficiência aórtica grave, abscesso periaórtico de 12 mm, e BAV de 1º grau novo. Culturas: S. mitis sensível à ceftriaxona. Evoluiu em 48h com EAP e necessidade de ventilação mecânica, noradrenalina. Maior risco por abscesso perianular e insuficiência cardíaca refratária: indicação cirúrgica urgente. TC de crânio sem lesões embólicas.', 'Heart Team: troca valvar aórtica com desbridamento do abscesso em até 48h. Manter ceftriaxona 2 g 12/12h por 6 semanas, suspender vancomicina. Suporte ventilatório e vasoativo. Tratar o foco dentário após a cirurgia. Família informada do risco elevado.'),
  (1524, 449, 12, '2025-02-14 07:00', 'internacao', 'Cirurgia de troca valvar aórtica urgente', 90, 44, 112, 66.0, 'Troca valvar aórtica por prótese biológica, com ressecção do abscesso periaórtico e reconstrução com remendo de pericárdio bovino, sem intercorrências intraoperatórias. Saída de CEC com noradrenalina e adrenalina. No pós-operatório imediato, choque vasoplégico, BAVT necessitando de marca-passo epicárdico, insuficiência renal aguda anúrica (Cr 3,8). No 3º dia, queda súbita do nível de consciência: TC de crânio com hematoma intraparenquimatoso frontal direito de 4,5 cm (embolia séptica com transformação hemorrágica), desvio de linha média de 8 mm.', 'Heparina suspensa, reversão da coagulação, terapia hiperosmolar, neurocirurgia avaliou: sem benefício cirúrgico pelo estado crítico. Discussão com a família sobre prognóstico muito reservado. Evoluiu com midríase bilateral fixa e morte encefálica confirmada em 24h por protocolo.');
