insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (449, '2025-02-18', 'obito', 'Endocardite infecciosa por Streptococcus mitis em valva aórtica bicúspide, com abscesso periaórtico e insuficiência aórtica grave. Operado com troca valvar, evoluiu com BAVT, lesão renal e hematoma intracerebral por embolia séptica, falecendo por morte encefálica em 18/02/2025.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (450, 'Fabiana Cordeiro Nogueira Sales', 'F', '1982-03-21', 'Ribeirão Preto', 'SP', 'Professora de educação física', 'Irmão morreu subitamente aos 28 anos durante jogo de futebol, sem autópsia conclusiva. Mãe com ''coração grande'' e marca-passo. Sem HAS, diabetes ou outras doenças. Praticava corrida e musculação, parou há um ano por cansaço. Nunca fumou.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1525, 450, 2, '2024-04-15 10:00', 'consulta', 'Falta de ar e dor no peito quando subo escada, quase desmaiei', 118, 74, 78, 64.0, 'Mulher de 42 anos, atleta, com dispneia aos médios esforços, dor torácica atípica aos esforços e uma pré-síncope durante aula. História familiar de morte súbita (irmão aos 28 anos). Exame: sopro sistólico ejetivo 3+/6+ em borda esternal esquerda baixa e ápice que aumenta com Valsalva e diminui ao agachar, pulso bisferiens. ECG: HVE e ondas T negativas amplas em V3-V6. ETT: hipertrofia assimétrica, septo basal de 24 mm, movimento sistólico anterior da mitral, gradiente de via de saída de 78 mmHg com Valsalva, IM moderada, FEVE 68%. Holter com 3 episódios de TV não sustentada.', 'Cardiomiopatia hipertrófica obstrutiva com marcadores de risco de morte súbita. Proibido esforço intenso e esporte competitivo. Iniciar bisoprolol 5 mg. Evitar desidratação e vasodilatadores. RM cardíaca e painel genético. Triagem familiar com ECG e ECO dos parentes de primeiro grau.'),
  (1526, 450, 2, '2024-06-10 10:20', 'retorno', 'Os remédios ajudaram pouco, ainda canso', 112, 70, 58, 64.5, 'Dois meses com bisoprolol titulado para 10 mg. FC 58, sem tontura, mas mantém dispneia aos médios esforços (CF NYHA III) e dor torácica aos esforços. RM cardíaca: hipertrofia assimétrica septal de 25 mm, realce tardio extenso (12% da massa do VE) em septo e ponto de inserção do VD. Painel genético: variante patogênica no gene MYBPC3. Risco calculado de morte súbita em 5 anos pelo HCM Risk-SCD: 6,3%. A irmã e a filha de 12 anos serão testadas.', 'Risco intermediário-alto e história familiar: indicado CDI para prevenção primária. Manter bisoprolol 10 mg (verapamil evitado pelo betabloqueador já em dose plena) e orientar hidratação. Encaminhar a centro de referência em cardiomiopatia para miectomia septal e CDI. Aconselhamento genético.'),
  (1527, 450, 2, '2024-09-23 14:00', 'teleconsulta', 'Aguardando a vaga no centro de referência', 114, 72, 60, 64.0, 'Teleconsulta de seguimento. Mantém dispneia aos médios esforços com bisoprolol 10 mg, sem síncope, sem choques, sem novas palpitações. PA e FC medidas em casa. Familiares rastreados: irmã com hipertrofia leve e a filha de 12 anos com genótipo positivo e fenótipo negativo, em seguimento. Foi aceita para avaliação na equipe de miectomia septal de um centro de referência em São Paulo, com data para 2 semanas.', 'Entregue relatório completo com ECO, RM, painel genético e Holter. Encaminhada para centro de referência quaternário para miectomia septal e implante de CDI. Manter bisoprolol 10 mg e orientações de hidratação e evitar esforço. Saída do acompanhamento local.');
