insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (450, '2024-09-23', 'transferido', 'Cardiomiopatia hipertrófica obstrutiva familiar (MYBPC3) com realce tardio extenso e risco de morte súbita de 6,3% em 5 anos, sintomática apesar do betabloqueador. Encaminhada a centro de referência em São Paulo para miectomia septal e implante de CDI.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (451, 'Raimundo Nonato Pantoja Cardoso', 'M', '1978-05-14', 'Belém', 'PA', 'Motorista de ônibus urbano', 'Sem diagnóstico prévio de HAS, mas PA elevada em exames admissionais. Sedentário, come marmita e fast-food nos intervalos do turno. Pai hipertenso, falecido de AVC aos 63 anos. Etilismo social aos fins de semana.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1528, 451, 5, '2024-02-06 14:20', 'consulta', 'Pressão veio alta no exame da empresa', 156, 98, 80, 94.2, 'Pcte de 45 anos, assintomático, encaminhado após PA 152x96 em exame periódico. Trabalha 8h sentado, dorme pouco, consome muito sal e embutidos. Ao exame: BEG, IMC 30,6, circunferência abdominal 106 cm. RCR 2T BNF, sem sopros, pulsos simétricos. PA aferida 3 vezes em duas visitas de bairro e hoje, média 156x98. HD: HAS estágio 1 provável, obesidade grau I. Solicitado MAPA e exames de rotina antes de medicar.', 'Orientada MEV: reduzir sal e embutidos, caminhada 30 min 5x/semana, reduzir álcool. Solicitados MAPA 24h, creatinina, potássio, glicemia, perfil lipídico, EAS e ECG. Retorno em 30 dias com resultados.'),
  (1529, 451, 5, '2024-03-12 15:00', 'retorno', 'Trouxe os exames e a MAPA', 150, 94, 78, 93.6, 'Retorna com MAPA: média 24h 148x93, vigília 152x96, sono 138x84, descenso preservado. Creatinina 0,9, K 4,3, glicemia de jejum 98, LDL 142, TFGe > 90. Manteve MEV parcialmente, perdeu 600 g. Diagnóstico de HAS estágio 1 confirmado, risco cardiovascular moderado. Discutido início de tratamento medicamentoso por não ter atingido meta apenas com MEV. Paciente concorda, quer um comprimido só por causa dos plantões.', 'Iniciar losartana 50 mg 1x/dia pela manhã. Reforçar MEV e dieta com nutricionista. Dosar creatinina e potássio em 4 semanas. Retorno em 60 dias com MRPA.'),
  (1530, 451, 5, '2024-09-10 16:10', 'retorno', 'Quero saber se posso parar o remédio', 126, 78, 72, 88.0, 'Paciente refere que passou a caminhar no terminal nos intervalos e trocou marmita por comida caseira. Perdeu 5,6 kg em 6 meses. MRPA com média de 124x76. Sem queixas, sem tosse ou edema. Creatinina 0,9 e K 4,5 após o início da losartana. Explicado que HAS é doença crônica e que a pressão normalizou por causa do tratamento; ele entendeu e não pretende parar por conta própria. Mantém bom humor e motivação.', 'Manter losartana 50 mg/dia. Meta < 130/80 atingida. Seguir MEV, reavaliar em 6 meses; se perda de peso continuar, discutir redução da dose. Orientado a não interromper por conta própria.');
