insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (451, '2024-09-10', 'controlado', 'HAS estágio 1 diagnosticada com MAPA, controlada com losartana 50 mg e perda de 6,2 kg com MEV. MRPA média 124x76. Mantém acompanhamento semestral na atenção primária.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (452, 'Maria Edilene Bessa Albuquerque', 'F', '1965-11-03', 'Manaus', 'AM', 'Professora da rede estadual', 'HAS há 10 anos, em uso de losartana 100 mg/dia, anlodipino 10 mg/dia e clortalidona 25 mg/dia. Encaminhada como hipertensa resistente. Nunca fumou. Refere ficar muito tensa em consultório.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1531, 452, 1, '2023-05-08 08:30', 'consulta', 'Minha pressão não baixa nunca na consulta', 168, 100, 84, 71.5, 'Paciente de 57 anos, com PA de consultório persistentemente entre 160-170x96-100 apesar de 3 anti-hipertensivos, incluindo diurético. Em casa, refere medidas de 120-130 mas nunca registrou. Assintomática, sem edema, sem sopros. Fundo de olho sem retinopatia hipertensiva, creatinina normal. Suspeita de pseudorresistência por efeito do avental branco. Adesão boa, usa caixinha organizadora; confirma tomada diária. Manguito adequado, aferição repetida com paciente em repouso: 164x98.', 'Não intensificar tratamento. Solicitar MAPA 24h e MRPA para confirmar efeito do avental branco. Solicitar creatinina, potássio, aldosterona/renina e EAS para rastreio rápido. Manter medicações. Retorno com resultados em 3 semanas.'),
  (1532, 452, 1, '2023-05-30 08:50', 'retorno', 'Trouxe a MAPA', 162, 96, 82, 71.2, 'MAPA 24h: média 24h 122x74, vigília 126x77, sono 112x65, descenso preservado; pico de 158x94 ao chegar na clínica. Relação aldosterona/renina normal. Fica claro o efeito do avental branco: PA de consultório 162x96 versus média ambulatorial dentro da meta. Paciente refere nos últimos meses pequena tontura ao levantar à tarde e inchaço leve de tornozelos, possível excesso de tratamento e efeito do anlodipino 10 mg. Pseudorresistência. Explicado o resultado e tranquilizada.', 'Reduzir anlodipino para 5 mg/dia para diminuir edema e tontura. Manter losartana e clortalidona. Usar MRPA em casa 2x/semana para controle. Retorno em 3 meses com registros.'),
  (1533, 452, 1, '2023-11-14 10:00', 'teleconsulta', 'Mostrar o diário de pressão', 124, 76, 70, null, 'Teleconsulta. Paciente envia diário com MRPA de 14 dias: média 124x76, sem valores > 135x85. Edema de tornozelo desapareceu e a tontura vespertina também. Mantém adesão. Relata que agora aferir em casa a deixa mais tranquila e que na consulta presencial continua com leve ansiedade. Sem queixas cardíacas. Entendido que o diagnóstico é HAS controlada com efeito do avental branco, não resistente.', 'Manter esquema atual. Seguir orientação de sempre usar MRPA para ajustar tratamento, não a PA de consultório. Retorno presencial em 6 meses com exames de rotina.');
