insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (452, '2023-11-14', 'controlado', 'Pseudorresistência por efeito do avental branco confirmada na MAPA. Evitada a intensificação desnecessária com espironolactona; anlodipino reduzido para 5 mg com resolução do edema. MRPA domiciliar na meta.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (453, 'Jaime Tavares Corrêa Neto', 'M', '1970-02-27', 'Santarém', 'PA', 'Comandante de embarcação fluvial', 'HAS há 6 anos mal controlada com 3 fármacos. Obesidade, ronco alto, sonolência diurna e cochilos ao volante da lancha. Etilismo moderado. Pai com HAS e infarto aos 58 anos. Em uso de losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1534, 453, 1, '2022-08-15 09:10', 'consulta', 'Pressão alta e muito sono durante o dia', 178, 108, 88, 118.4, 'Pcte de 52 anos, comandante de lancha entre Santarém e Alenquer, com viagens longas e sono fragmentado. Esposa relata roncos e pausas respiratórias. Epworth 16. Ao exame: IMC 38, pescoço 46 cm, Mallampati III. RCR 2T BNF, sem sopros. MV+ sem RA. Sem edema. PA 178x108 apesar de 3 anti-hipertensivos. Pseudorresistência afastada com MRPA média 170x104 e boa adesão. HD: HAS resistente com forte suspeita de apneia obstrutiva do sono como causa secundária.', 'Solicitar polissonografia, ECO, ECG e rastreio: creatinina, K, aldosterona/renina, TSH. Orientar perda de peso, restrição de álcool à noite e não conduzir embarcação com sonolência. Retorno com exames.'),
  (1535, 453, 1, '2022-09-20 10:30', 'retorno', 'Vim buscar o resultado da polissonografia', 172, 104, 86, 118.0, 'Polissonografia: IAH 46 eventos/h, dessaturação mínima 71%, tempo com SpO2 < 90% de 22%: apneia obstrutiva grave. ECO com HVE concêntrica leve, FEVE 62%, átrio esquerdo 41 mm. Aldosterona/renina normal, TSH 2,1, creatinina 1,0, K 4,0. Concluído que a apneia contribui de forma importante para a HAS resistente. Encaminhado ao serviço de sono, que prescreveu CPAP automático; ele estava resistente à máscara, mas aceitou testar.', 'Iniciar CPAP automático 5-15 cmH2O, máscara nasal, uso todas as noites e nas folgas de viagem. Manter anti-hipertensivos por ora. Meta de perda de 10% do peso. Retorno em 3 meses com download do CPAP.'),
  (1536, 453, 1, '2023-02-07 09:40', 'retorno', 'Estou dormindo melhor, sem sono na lancha', 132, 82, 74, 110.2, 'Adaptou-se ao CPAP: uso médio de 5,5 h/noite em 82% das noites, IAH residual 3,4. Epworth 6. Esposa diz que acabou o ronco. Perdeu 7,8 kg com ajuda de caminhadas ao amanhecer. MRPA média 128x80. Sem edema nem cefaleia matinal. Boa resposta pressórica após tratamento da causa. Sugiro retirar a hidroclorotiazida para evitar alterações metabólicas e manter a PA monitorada.', 'Suspender hidroclorotiazida. Manter losartana 100 mg e anlodipino 10 mg. Manter CPAP todas as noites. MRPA por 7 dias em 1 mês. Retorno em 3 meses.');
