insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (453, '2023-02-07', 'melhorou', 'HAS secundária à apneia obstrutiva grave. Com CPAP e perda de 8 kg, PA caiu de 178x108 para 132x82 e foi possível suspender a hidroclorotiazida. Sem sonolência ao conduzir a embarcação.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (454, 'Francisca Leocádia Mendes Pinheiro', 'F', '1961-07-19', 'Rio Branco', 'AC', 'Empregada doméstica', 'HAS há 15 anos, parou a losartana há 3 meses porque “a pressão tinha ficado boa”. Sem outras comorbidades conhecidas. Não fuma. Dieta rica em charque, salgados e café forte.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1537, 454, 6, '2024-03-02 03:20', 'pronto_socorro', 'Dor de cabeça forte e pressão 210', 214, 124, 88, null, 'Pcte 62a, HAS sem uso de medicação há 3 meses, chega com cefaleia occipital intensa desde o fim da tarde, sem alteração visual, sem dor torácica, sem déficit focal, sem vômitos. Ao exame: REG leve por dor, consciente, sem déficit, pupilas isocóricas, sem rigidez de nuca. RCR 2T BNF, B4 presente, MV+ sem RA. Fundo de olho sem papiledema. ECG sem isquemia aguda. Troponina negativa. Creatinina normal. HD: urgência hipertensiva sem lesão aguda de órgão-alvo.', 'Repouso em ambiente calmo, analgesia com dipirona, captopril 25 mg VO e reavaliação em 1 hora. PA caiu para 176x102 em 2 h, cefaleia melhorou. Alta com losartana e anlodipino. Orientada a não interromper. Retorno ambulatorial em 7-10 dias.'),
  (1538, 454, 1, '2024-03-12 14:00', 'retorno', 'Voltei depois do pronto-socorro', 152, 92, 78, 76.8, 'Retorna após urgência hipertensiva. Tomou os medicamentos todos os dias, cefaleia resolvida. PA 152x92. Conta que parou o remédio porque achava que “o remédio viciava” e que a pressão tinha normalizado. Explicado que o controle depende da medicação. Creatinina 0,9, K 4,2, EAS sem proteinúria, ECO com HVE leve e FEVE 64%. Sem lesão de órgão-alvo grave. Aceitou voltar a se tratar, mas sem fazer dieta com pouco sal por conta do trabalho.', 'Manter losartana 50 mg 12/12h e anlodipino 5 mg, aumentar anlodipino para 10 mg se PA > 140x90 em 15 dias. Orientação de sal com nutricionista. Agente de saúde da UBS fará busca ativa. Retorno em 30 dias.'),
  (1539, 454, 13, '2025-01-19 22:45', 'internacao', 'Boca torta e fraqueza no braço direito', 202, 116, 92, 77.0, 'Familiar relata que parou novamente os remédios em novembro por falta na UBS e por trabalhar na casa de uma patroa viajando. Início há 2 h de desvio de rima labial à direita, hemiparesia braquiocrural direita grau 3 e disartria. NIHSS 8. TC de crânio sem sangramento, sem sinais precoces extensos. Fora da janela de trombólise por horário incerto; sem oclusão de grande vaso em angiotomografia. PA mantida < 220x120 nas primeiras 24 h. Fibrilação atrial excluída no monitor.', 'Internação em unidade de AVC. AAS 300 mg, atorvastatina 80 mg, controle gradual da PA. Fisioterapia motora e fonoaudiologia. Reintrodução de anti-hipertensivos após 48 h. Ecocardiograma e Doppler de carótidas. Alta com seguimento.');
