insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (454, '2025-02-04', 'piorou', 'Após nova interrupção dos anti-hipertensivos por falta na UBS, evoluiu com AVC isquêmico e hemiparesia direita leve residual. Alta em fisioterapia, com PA controlada em 138x84 e acompanhamento neurológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (455, 'Osvaldo Quaresma Brito', 'M', '1962-09-30', 'Macapá', 'AP', 'Taxista', 'HAS há 8 anos, dislipidemia sem tratamento regular e tabagismo de 40 maços-ano, ainda fumante. Sedentário, passa o dia no carro. Pai morreu de infarto aos 55 anos. Usava apenas enalapril 10 mg de manhã.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1540, 455, 6, '2023-06-18 23:10', 'pronto_socorro', 'Dor forte no peito que irradia pro braço', 148, 92, 96, 91.0, 'Pcte 60a, dor precordial em aperto com irradiação para MSE, sudorese e náuseas há 1h30, após jantar. Fumante. Ao exame: sudoreico, REG, RCR 2T BNF, sem sopros, MV+ sem RA. ECG: supradesnivelamento de ST de 3 mm V1-V5 com espelhamento em DII, DIII e aVF. Troponina 4,2 ng/mL (ref < 0,04). HD: IAMCSST anterior extenso, Killip I. Dispensa bloqueio inicial. Acionada hemodinâmica, janela estimada < 3 h.', 'AAS 300 mg mastigado, ticagrelor 180 mg, heparina não fracionada 70 U/kg, atorvastatina 80 mg, morfina em dose baixa. Encaminhado ao CATE para ATC primária. Familiar orientada.'),
  (1541, 455, 10, '2023-06-19 00:40', 'internacao', 'Dor persistente aguardando cateterismo', 138, 84, 80, 91.0, 'CATE por acesso radial direito: oclusão trombótica proximal da DA, circunflexa com lesão de 40%, CD sem lesões críticas. Realizada ATC com implante de stent farmacológico 3,5x28 mm na DA proximal, fluxo TIMI 3 final, sem complicações. Alta da hemodinâmica para UTI coronariana, assintomático, ST resolveu 70%. Pico de troponina 78 ng/mL. ECO: FEVE 44% com hipocinesia anterior e apical, sem trombo.', 'Dupla antiagregação por 12 meses (AAS 100 + ticagrelor 90 12/12h). Iniciar carvedilol, enalapril e atorvastatina 80 mg. Tabagismo: orientação intensiva, reposição de nicotina. Programa de reabilitação cardíaca. Alta em 4 dias.'),
  (1542, 455, 1, '2023-07-24 08:30', 'retorno', 'Estou sem dor, mas fumei de novo', 124, 76, 62, 89.4, 'Retorno 5 semanas pós-IAM. Sem angina, sem dispneia, CF I. Voltou a fumar 5 cigarros/dia por estresse, “não aguentei ficar sem”. Iniciou reabilitação cardíaca, caminha 30 min 3x/semana. Sem sangramentos, leve dispneia ao esforço máximo atribuída ao ticagrelor. PA 124x76, FC 62. LDL 58 mg/dL, creatinina 1,0, K 4,5. Adesão ótima à dupla antiagregação.', 'Manter esquema, reforçar cessação do tabagismo com vareniclina e acompanhamento no grupo da UBS. Reabilitação 3x/semana. Novo ECO em 3 meses para avaliar FEVE. Retorno em 90 dias.'),
  (1543, 455, 1, '2024-07-09 09:00', 'retorno', 'Vim fazer a revisão de um ano', 120, 74, 60, 86.2, '1 ano pós-IAMCSST. Parou de fumar há 8 meses com vareniclina. Assintomático, caminha 5 km 4x/semana. ECO: FEVE 52%, recuperação do miocárdio atordoado, hipocinesia apical residual. Teste ergométrico sem isquemia a 10 METs. LDL 49. Sem sangramentos. Fim do período de DAPT de 12 meses.', 'Suspender ticagrelor; manter AAS 100 mg contínuo, atorvastatina 80 mg, carvedilol e enalapril. Manter MEV e não fumar. Retorno em 6 meses.');
