insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (455, '2024-07-09', 'melhorou', 'IAM anterior tratado com ATC primária e stent na DA. Um ano depois, FEVE recuperou de 44% para 52%, sem angina, ex-fumante há 8 meses, LDL 49 e capacidade funcional de 10 METs. DAPT concluída.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (456, 'Lindalva Pereira da Conceição Souza', 'F', '1953-12-08', 'Ananindeua', 'PA', 'Aposentada, ex-merendeira', 'HAS há 25 anos, DM2 há 12 anos, obesidade grau II. ICFEp diagnosticada há 2 anos. Uso de enalapril 10 mg 12/12h, furosemida 40 mg/dia, metformina 850 mg 2x/dia. Sedentária, mora com a filha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1544, 456, 11, '2022-11-04 10:00', 'consulta', 'Cansaço e pernas inchadas', 154, 86, 82, 96.5, 'Pcte 68a, ICFEp NYHA III, com dispneia aos pequenos esforços há 2 meses, ortopneia com 2 travesseiros, edema bilateral de MMII 2+/4+. Ganhou 5 kg em 6 semanas. Ao exame: BEG, estase jugular a 45°, estertores bibasais, RCR 2T BNF, B4. PA 154x86. NT-proBNP 2.140 pg/mL. ECO prévio: FEVE 58%, E/e'' 16, AE aumentado. HD: ICFEp descompensada por sobrecarga volêmica e HAS mal controlada, associada a ingestão de sal acima do habitual.', 'Aumentar furosemida para 40 mg 12/12h por 5 dias, depois 40 mg/dia. Iniciar dapagliflozina 10 mg/dia (HbA1c 8,1%). Restrição de sal e peso diário. Solicitado creatinina e K em 1 semana. Retorno em 15 dias.'),
  (1545, 456, 11, '2022-11-21 09:30', 'retorno', 'Melhorou bastante do inchaço', 138, 80, 74, 91.8, 'Retorno com peso 91,8 kg (-4,7 kg). Dispneia agora aos médios esforços, dorme com 1 travesseiro, sem DPN. Edema 1+/4+. Estertores ausentes. Creatinina 1,2 (TFGe 47), K 4,4: discreta queda esperada da TFGe pelo iSGLT2. Relata aumento da diurese e uma candidíase vulvar leve tratada pela filha com creme. Orientada higiene. Entendeu a importância de pesar-se todas as manhãs.', 'Manter dapagliflozina e furosemida 40 mg/dia. Adicionar espironolactona 25 mg/dia, com controle de K e creatinina em 1 semana. Trocar enalapril por losartana 50 mg 12/12h por tosse seca persistente que a paciente atribuiu ao enalapril. Retorno em 1 mês.'),
  (1546, 456, 11, '2023-09-12 11:20', 'retorno', 'Vim para revisão, estou bem', 128, 74, 70, 85.3, 'Paciente estável NYHA II, sem internações em 10 meses. Perdeu 11 kg desde o início, caminha 20 min diários com a neta. Edema ausente. PA 128x74. NT-proBNP 480 pg/mL. HbA1c 6,9%. Creatinina 1,2, K 4,9, sem hipercalemia. Aceitável. Sem tosse após trocar para losartana. Continua com sal controlado e pesagem diária; peso seco ao redor de 85 kg.', 'Manter esquema atual. Monitorar K e creatinina a cada 3-4 meses. Vacinas de influenza e pneumococo em dia. Plano de ação se ganhar > 2 kg em 3 dias: aumentar furosemida e procurar UBS. Retorno em 6 meses.');
