insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (456, '2023-09-12', 'estavel', 'ICFEp compensada em NYHA II, com perda de 11 kg, NT-proBNP de 2.140 para 480 pg/mL e sem internações. Segue com iSGLT2, espironolactona e BRA, em controle semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (457, 'Walter Seixas Loureiro', 'M', '1955-04-21', 'Porto Velho', 'RO', 'Aposentado, ex-seringueiro', 'HAS há 20 anos em uso irregular de enalapril. Ex-tabagista (30 maços-ano, parou há 8 anos). Malária várias vezes na juventude. Bebe 2 a 3 doses de cachaça ao dia. Mora sozinho em bairro da periferia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1547, 457, 6, '2021-03-09 07:50', 'pronto_socorro', 'Coração disparado e cansaço', 146, 90, 138, 72.0, 'Pcte 65a, palpitações e dispneia há 2 dias, sem dor torácica ou síncope. Hoje piorou ao subir degraus. Ao exame: ansioso, taquicárdico, RCI 2T, sem sopros, MV+ com estertores finos em bases. Sat 95% AA. ECG: FA com resposta ventricular rápida 138 bpm, sem isquemia aguda. Troponina negativa. TSH normal. HD: FA de início indeterminado, alta resposta, CHA2DS2-VASc 2 (idade 65-74 e HAS), provável contribuição do etilismo.', 'Metoprolol 5 mg EV lento e depois succinato oral; FC 98 em 3h. Início de rivaroxabana 20 mg/dia com o jantar. Solicitado ECO ambulatorial. Aconselhado a reduzir o álcool. Encaminhado à cardiologia em 7 dias.'),
  (1548, 457, 4, '2021-03-18 10:30', 'retorno', 'Retorno da fibrilação', 132, 80, 84, 72.4, 'Retorna ainda em FA com FC controlada, 84 bpm. Sem dispneia, menos fadiga. ECO: FEVE 55%, AE 49 mm, HVE leve, sem valvopatia importante. Creatinina 1,0, Hb 14,2. Discutida estratégia: cardioversão elétrica após 3 semanas de anticoagulação não é indicada de imediato pela duração incerta e AE aumentado; optada pela estratégia de controle de frequência, ritmo a reavaliar. Paciente informa que tem tomado rivaroxabana de manhã, ajustado o horário.', 'Manter rivaroxabana 20 mg com a refeição principal, metoprolol succinato 100 mg/dia. Holter de 24 h em 1 mês. Abstinência alcoólica. Retorno em 60 dias.'),
  (1549, 457, 4, '2021-06-03 09:00', 'retorno', 'Estou me sentindo bem', 128, 78, 72, 73.6, 'Holter: FA permanente, FC média 76, máx 118 em atividade, sem pausas > 2s e sem TV. Parou a cachaça diária e agora bebe apenas aos domingos, bom engajamento. Sem sangramentos, hematúria ou melena. PA 128x78. Hb 14,0, creatinina 1,0, ClCr 74 mL/min. CHA2DS2-VASc 2, HAS-BLED 2 (idade e álcool). Assintomático, CF I.', 'Manter FA permanente com controle de frequência. Rivaroxabana 20 mg e metoprolol succinato 100 mg. Retornos semestrais com Hb e creatinina anuais. Orientado sobre sinais de sangramento.');
