insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (458, '2024-06-18', 'melhorou', 'Estenose aórtica grave sintomática tratada com TAVI transfemoral. Um mês depois, assintomático, gradiente residual de 9 mmHg, FEVE 62% e função renal estável. Segue em acompanhamento com ECO semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (459, 'Benedito Guimarães Ferreira', 'M', '1960-01-25', 'Barcelos', 'AM', 'Extrativista de piaçaba aposentado', 'Cardiopatia chagásica crônica com ICFEr conhecida (FEVE 28%), contato com o barbeiro na infância em casa de palha, sorologia reagente. Tabagismo antigo, etilismo importante até 5 anos atrás. Usava enalapril, carvedilol e furosemida de forma irregular por morar em área ribeirinha distante.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1554, 459, 11, '2021-10-05 09:00', 'consulta', 'Falta de ar até pra tomar banho', 98, 64, 58, 58.4, 'Pcte 61a, vindo de comunidade ribeirinha de barco, com dispneia aos mínimos esforços, ortopneia, edema de MMII 3+/4+ e ascite leve. NYHA III-IV. Ao exame: REG, caquexia cardíaca, estase jugular 4 cm, estertores até terço médio, hepatomegalia dolorosa, RCR 3T com galope. ECG: BAV de 1º grau, BRD + HBAE e extrassístoles ventriculares. ECO: FEVE 28%, VE dilatado com aneurisma apical, sem trombo visível. HD: cardiopatia chagásica crônica, ICFEr descompensada.', 'Furosemida 40 mg EV e depois oral, espironolactona 25 mg, sacubitril/valsartana 24/26 mg 12/12h após suspender enalapril por 36 h, carvedilol 3,125 mg 12/12h, dapagliflozina 10 mg. Solicitado Holter. Não indicado benznidazol (fase crônica com cardiopatia). Retorno em 15 dias.'),
  (1555, 459, 4, '2021-11-24 10:30', 'retorno', 'Dei umas apagadas em casa', 104, 66, 54, 56.0, 'Melhora do edema (-2,4 kg), NYHA III. Mas refere 2 episódios de síncope abrupta há 3 semanas, sem pródromo. Holter 24h: TVNS com 14 batimentos a 190 bpm, EV 9.400/24h e BAV de 1º grau sem BAV avançado. K 4,6, creatinina 1,2. FEVE 28%, com síncope e TV: alto risco de morte súbita. Pcte entende o risco, mas mora longe e tem pouco recurso financeiro para viajar.', 'Indicação de CDI para prevenção secundária. Iniciar amiodarona 200 mg/dia como ponte, aumentar carvedilol para 6,25 mg 12/12h. Encaminhado para implante de CDI via regulação estadual. Orientações de risco, evitar dirigir ou nadar sozinho.'),
  (1556, 459, 14, '2022-02-17 14:30', 'internacao', 'Choque no peito e falta de ar intensa', 86, 54, 112, 60.1, 'Admitido em UTI após remoção de lancha e ambulância: CDI implantado em dezembro em Manaus, com 3 choques apropriados nas últimas 48 h por TV sustentada. Dispneia intensa, extremidades frias, perfusão lentificada, lactato 4,2, congestão pulmonar e edema. Choque cardiogênico por IC refratária, creatinina 2,3, K 5,4. Iniciada dobutamina e furosemida em infusão. Interrogação do CDI: TV 210 bpm, terapias eficazes. Sem resposta renal sustentada.', 'UTI, dobutamina, furosemida em infusão contínua, suspensão de espironolactona e sacubitril/valsartana por hipercalemia e IRA. Avaliada ventilação não invasiva. Conversado com família sobre prognóstico reservado; paciente fora de critérios de transplante e dispositivos pela dependência e distância. Cuidados paliativos envolvidos.');
