insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (460, '2024-09-10', 'controlado', 'BAVT tratado com implante de marca-passo dupla câmara, sem recorrência de síncope. Ferida cicatrizada, dispositivo com parâmetros estáveis, HAS com anlodipino reintroduzido; seguimento semestral.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (461, 'Ednaldo Rabelo Sampaio', 'M', '1976-09-09', 'Boa Vista', 'RR', 'Vigilante noturno', 'PA elevada anotada em consultas de urgência nos últimos 3 anos, nunca investigada. Trabalha em escala 12x36, dorme mal de dia. Consome refrigerante e embutidos. Pai hipertenso. Sem uso de medicações contínuas.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1560, 461, 1, '2025-03-11 10:30', 'consulta', 'Dor de cabeça na nuca quando saio do plantão', 172, 106, 82, 83.0, 'Pcte 48a, cefaleia occipital matinal esporádica. Em consultório PA 172x106 e 168x104 em medidas repetidas; MRPA de 5 dias trazido por ele: média 164x102. Ao exame: BEG, IMC 28, RCR 2T BNF, sem sopros, pulsos femorais simétricos, abdome sem sopros, sem edema. Fundoscopia normal. ECG com SVE leve. HAS estágio 2 sem sinais de emergência. Risco CV alto pelo estágio 2 com lesão de órgão-alvo provável.', 'Iniciar combinação em comprimido único: losartana 50 mg + hidroclorotiazida 12,5 mg 1x/dia, para simplificar a rotina do plantão. MEV e redução do sal. Pedidos: creatinina, K, glicemia, perfil lipídico, EAS, relação albumina/creatinina e ECO. Retorno em 6 semanas.'),
  (1561, 461, 1, '2025-04-22 10:00', 'retorno', 'Cefaleia melhorou, mas pressão ainda não normalizou', 148, 92, 78, 82.2, 'Adesão ótima, toma o comprimido ao chegar em casa. Cefaleia quase ausente. PA 148x92, MRPA média 142x88. Sem tosse, sem tontura. Exames: creatinina 1,0, K 3,9, glicemia 94, LDL 128, relação albumina/creatinina 18 mg/g, ácido úrico 7,1. ECO: HVE concêntrica leve (septo 12 mm), FEVE 66%, sem valvopatia. Resposta parcial, ainda acima da meta de < 130/80. Discutido aumento da dose em vez de novo fármaco.', 'Aumentar para losartana 100 mg + hidroclorotiazida 25 mg em comprimido único. Repetir creatinina e potássio em 4 semanas. Orientado a manter MRPA. Retorno em 8 semanas.'),
  (1562, 461, 1, '2025-09-16 11:20', 'retorno', 'Vim mostrar a pressão de casa', 126, 78, 70, 79.8, 'Paciente sem queixas, relata caminhar 40 min antes do plantão e ter cortado o refrigerante. Perdeu 3 kg. MRPA média 124x76, sem valores > 135x85. K 4,0 e creatinina 1,0 após o aumento de dose. Sem gota nem cãibras. PA no consultório 126x78. Boa adesão ao comprimido único, relata que a praticidade foi decisiva.', 'Manter losartana/hidroclorotiazida 100/25 mg. Meta atingida. Retorno em 6 meses com K, creatinina e ácido úrico. Reforçar MEV e sono.');
