insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (461, '2025-09-16', 'controlado', 'HAS estágio 2 com HVE leve, controlada com combinação fixa losartana/hidroclorotiazida 100/25 mg. MRPA 124x76 após 6 meses, perda de 3 kg e boa adesão pela simplicidade do esquema.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (462, 'Eunice Maciel Cordeiro', 'F', '1962-03-17', 'Cruzeiro do Sul', 'AC', 'Agricultora familiar (farinha de mandioca)', 'HAS há 14 anos e DM2 há 9 anos em uso de metformina 850 mg 2x/dia e enalapril 20 mg/dia, com tosse seca. Retinopatia diabética leve. Mora em comunidade rural a 3 horas de barco da cidade. Não fuma.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1563, 462, 1, '2022-06-07 09:00', 'consulta', 'Tosse seca que não passa', 162, 92, 80, 74.6, 'Pcte 60a, HAS e DM2, tosse seca incomodando à noite há 8 meses, desde o enalapril. Parou o remédio ''por conta'' há 2 semanas e a tosse diminuiu, porém PA subiu. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, sem edema. PA 162x92. HbA1c 8,4%, creatinina 1,1 (TFGe 56), relação albumina/creatinina 210 mg/g (moderadamente aumentada), K 4,5. Tosse por IECA e albuminúria persistente: indicação de bloqueio do SRAA, trocando para BRA.', 'Trocar enalapril por losartana 50 mg 12/12h. Adicionar anlodipino 5 mg. Orientar dieta e controle da glicemia. Repetir albuminúria, creatinina e K em 4 semanas. Retorno em 30 dias.'),
  (1564, 462, 1, '2022-07-12 09:20', 'retorno', 'A tosse parou, a pressão melhorou', 138, 82, 76, 74.0, 'Tosse resolvida. PA 138x82. Creatinina 1,2 e K 4,7 após BRA, aceitável (aumento < 30%). Albuminúria 160 mg/g, melhorou. Paciente conta que viaja de barco para a consulta uma vez a cada 2 meses e que o dinheiro do barco pesa no orçamento. Dificuldade para vir. Dapagliflozina 10 mg proposta pelo benefício renal e cardiovascular; disponibilidade pelo programa de farmácia popular a confirmar.', 'Manter losartana 50 mg 12/12h e anlodipino 5 mg. Iniciar dapagliflozina 10 mg/dia se disponível na UBS de origem. Combinar telemonitoramento com agente de saúde. Retorno em 3 meses, de preferência junto de outras consultas.'),
  (1565, 462, 1, '2022-10-18 09:40', 'retorno', 'Acabou o remédio faz um mês', 170, 98, 84, 75.3, 'Chegou após 4 meses sem retornar à UBS de origem; remédios acabaram há 30 dias, rio estava seco e o barco não subia. PA 170x98. Refere poliúria e cansaço, glicemia capilar 240. Sem sintomas neurológicos nem dor torácica. Creatinina 1,3. Explicado o risco renal e cardiovascular de ficar sem tratamento; paciente chora, diz que tem a roça e os netos para cuidar. Receita renovada para 3 meses, e combinou-se contato com o agente de saúde.', 'Reiniciar losartana 50 mg 12/12h, anlodipino 5 mg, metformina e dapagliflozina com receita para 3 meses. Pedido de exames para antes do retorno. Retorno em 90 dias. Contato com a secretaria de saúde para apoio de transporte.');
