insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (462, '2023-04-20', 'abandonou', 'Não retornou após a consulta de outubro de 2022, mesmo com a receita de 3 meses e contato da UBS. A comunidade fica isolada nas secas do rio. Última PA 170x98, albuminúria e função renal sem reavaliação. Registrada perda de seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (463, 'Marinalva Oliveira Teixeira Gomes', 'F', '1986-02-12', 'Marabá', 'PA', 'Comerciante (loja de roupas)', 'HAS diagnosticada há 3 anos, hoje com 3 medicamentos. Ganho de 18 kg em 2 anos, irregularidade menstrual, hirsutismo e hematomas fáceis. Pré-diabetes. Sem uso de corticoide. Mãe hipertensa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1566, 463, 1, '2023-04-04 14:00', 'consulta', 'Engordei muito e minha pressão não controla', 164, 104, 84, 92.5, 'Pcte 37a, HAS em uso de losartana 100, anlodipino 10 e clortalidona 25 sem controle. Ganho ponderal centrípeto, fraqueza proximal ao levantar da cadeira, estrias violáceas largas em abdome, face arredondada, giba, equimoses em braços e amenorreia há 4 meses. Glicemia 118, K 3,3. Pseudorresistência afastada com MAPA (média 24h 156x98). Quadro compatível com síndrome de Cushing. Encaminhada à endocrinologia em paralelo.', 'Solicitar cortisol salivar noturno, cortisol após 1 mg de dexametasona, ACTH, cortisol urinário de 24h, aldosterona/renina. Suspender clortalidona (hipocalemia) e iniciar espironolactona 25 mg + KCl. Retorno com resultados em 3 semanas.'),
  (1567, 463, 9, '2023-04-26 08:40', 'retorno', 'Resultado dos exames hormonais', 156, 96, 80, 92.8, 'Cortisol salivar noturno 4,2 nmol/L (ref < 3,6) em duas amostras, cortisol pós-dexametasona 1 mg: 8,4 mcg/dL (não suprime), cortisol urinário 24h 3,1 vezes o limite superior, ACTH suprimido < 5 pg/mL: Cushing ACTH-independente. Aldosterona/renina normal, metanefrinas normais. TC de adrenais: nódulo hipodenso de 3,2 cm na adrenal esquerda, adrenal contralateral atrófica. HbA1c 6,2%, K 3,9 com reposição. Diagnóstico de adenoma cortisol-secretor. Tratamento: adrenalectomia unilateral.', 'Encaminhar para adrenalectomia esquerda laparoscópica em serviço de referência, com cobertura de hidrocortisona no perioperatório. Manter anti-hipertensivos e espironolactona até a cirurgia. Orientada sobre insuficiência adrenal pós-operatória. Retorno em 30 dias após a cirurgia.'),
  (1568, 463, 9, '2023-09-19 09:10', 'retorno', 'Fiz a cirurgia e estou me sentindo muito mais disposta', 122, 76, 72, 80.4, 'Adrenalectomia esquerda laparoscópica há 5 meses, sem complicações. Anatomopatológico: adenoma cortical de 3,3 cm. Teve insuficiência adrenal transitória com fadiga e dor articular, tratada com hidrocortisona 20 mg/dia em redução; teste de ACTH recente mostra cortisol 19 mcg/dL e a hidrocortisona foi suspensa. Perdeu 12 kg, estrias clareando, menstruação voltou. Na MRPA, média 118x74 já sem espironolactona e sem clortalidona. K 4,3.', 'Suspender espironolactona e reduzir anlodipino para 5 mg; manter losartana 100 mg. Reavaliar PA em 30 dias com MRPA e tentar retirar mais medicação. Controle de glicemia e densitometria óssea.');
