insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (465, '2026-04-14', 'melhorou', 'Pré-eclâmpsia que evoluiu de moderada para grave com iminência de eclâmpsia, tratada com sulfato de magnésio e cesárea às 34 semanas. Mãe e bebê bem; PA 134x84 no puerpério com enalapril e plaquetas normalizadas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (466, 'Aristides Bonfim de Magalhães', 'M', '1957-06-23', 'Goiânia', 'GO', 'Aposentado, ex-engenheiro civil', 'HAS há 25 anos, DM2 há 15 anos em uso de metformina e glicazida, dislipidemia. Ex-tabagista (parou há 12 anos). Angina aos esforços há 1 ano, tratada com isossorbida e atenolol. Pai faleceu de infarto aos 62 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1576, 466, 1, '2023-01-17 08:30', 'consulta', 'Dor no peito ao caminhar uma quadra', 144, 86, 64, 84.0, 'Pcte 65a, angina CCS III com piora progressiva em 3 meses, aliviada com repouso em 5 min, aperto retroesternal sem irradiação. Sem dispneia em repouso. Ao exame: BEG, RCR 2T BNF, B4, sem sopros, pulsos periféricos presentes. PA 144x86, FC 64. ECG: ritmo sinusal, alteração inespecífica de ST. Cintilografia há 2 meses com isquemia extensa em paredes anterior e inferior. HD: DAC estável com angina refratária, alto risco. Programado cateterismo.', 'Trocar atenolol por metoprolol succinato 100 mg/dia, otimizar atorvastatina 80 mg, manter AAS 100 mg e isossorbida. Encaminhar para CATE eletivo. Retorno com resultado.'),
  (1577, 466, 12, '2023-02-14 10:00', 'retorno', 'Resultado do cateterismo e avaliação para cirurgia', 138, 80, 60, 83.6, 'CATE: DA com lesão de 90% proximal e 80% média, Cx com 90% no ramo marginal, CD ocluída crônica com circulação colateral; FEVE 52%. SYNTAX alto (34). Diabético multiarterial: indicação de revascularização cirúrgica. Veia safena e artéria mamária esquerda adequadas ao mapeamento. Explicadas opções: cirurgia com enxertos tem melhor resultado a longo prazo que ATC em DM multiarterial. O paciente aceita, preocupado com a idade e a recuperação.', 'Agendar RM com mamária esquerda para DA e safenas para Cx e CD. Suspender metformina na véspera, AAS mantido. Pré-operatório completo: Doppler de carótidas, espirometria. Retorno pós-alta.'),
  (1578, 466, 12, '2023-03-06 07:00', 'internacao', 'Internação eletiva para cirurgia de revascularização', 130, 76, 58, 83.0, 'Realizada revascularização miocárdica com circulação extracorpórea: mamária esquerda para DA e duas pontes de safena (marginal e descendente posterior). Tempo de CEC 78 min, sem intercorrências. Extubado em 6 h, UTI por 48 h. FA transitória no 3º dia revertida com amiodarona. Dreno retirado no 2º dia, ferida esternal sem secreção. Troponina pico 1,8 ng/mL, esperado. Alta no 7º dia, deambulando. Glicemia controlada com insulina.', 'Alta com AAS 100 mg, atorvastatina 80 mg, metoprolol, enalapril introduzido após 5º dia; metformina reiniciada. Fisioterapia respiratória e reabilitação cardíaca. Cuidados com o esterno por 6 semanas. Retorno em 30 dias.'),
  (1579, 466, 1, '2023-09-26 09:00', 'retorno', 'Estou sem dor e fazendo caminhada', 122, 74, 62, 80.5, '6 meses de RM, sem angina, caminha 5 km 4x/semana, concluiu a reabilitação cardíaca. Esterno consolidado, sem dor residual. PA 122x74, FC 62. LDL 54, HbA1c 7,0%, creatinina 1,0, K 4,6. Teste ergométrico sem isquemia a 9 METs. Retirou isossorbida sem recorrência de angina. Nega tosse com enalapril. Referiu desânimo nos primeiros meses, melhor atualmente.', 'Manter AAS, atorvastatina 80 mg, metoprolol e enalapril. Suspensa isossorbida. Retornos semestrais; ergométrico anual. Manter atividade física e dieta.');
