insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (466, '2023-09-26', 'melhorou', 'Angina grave por DAC triarterial em diabético tratada com revascularização miocárdica (mamária mais duas safenas). Seis meses depois, sem angina, 9 METs no ergométrico, LDL 54 e HbA1c 7,0%.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (467, 'Eliésio Tenório da Silva Lopes', 'M', '1968-10-15', 'Parintins', 'AM', 'Agricultor e pescador', 'HAS há 10 anos, sem acompanhamento regular. Diagnóstico de cardiomiopatia dilatada há 6 meses com FEVE 30%, sem coronariopatia na cintilografia. Etilismo social. Usava enalapril 10 mg irregular e furosemida quando sentia inchaço.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1580, 467, 11, '2023-07-11 09:20', 'consulta', 'Falta de ar ao pescar e inchaço nos pés', 118, 74, 92, 79.0, 'Pcte 54a, ICFEr NYHA III, dispneia aos médios esforços, ortopneia e edema 2+/4+ de MMII. Ao exame: estase jugular 2 cm, estertores bibasais, RCR 3T com B3, sopro holossistólico 2+/6+ em foco mitral. ECO: FEVE 30%, DDVE 66 mm, IM funcional moderada. NT-proBNP 3.100. Creatinina 1,2, K 4,5. HD: ICFEr por cardiomiopatia dilatada (provavelmente cardiopatia hipertensiva + etilismo) com baixa adesão. Sem os 4 pilares do tratamento até agora.', 'Iniciar sacubitril/valsartana 24/26 mg 12/12h (pausa de 36h do enalapril), carvedilol 3,125 mg 12/12h, espironolactona 25 mg/dia, dapagliflozina 10 mg/dia, furosemida 40 mg/dia. Abstinência alcoólica. Pesagem diária. Exames de K e creatinina em 1 semana. Retorno em 3 semanas.'),
  (1581, 467, 11, '2023-08-01 09:00', 'retorno', 'Estou respirando melhor mas fico tonto', 96, 60, 76, 74.8, 'Perdeu 4,2 kg, edema resolvido, NYHA II. Refere tontura leve ao levantar, PA 96x60 sem queda postural importante. K 5,3, creatinina 1,4 (TFGe 56). Como o K está no limite, reduzida a ingestão de alimentos ricos em potássio (banana, açaí em grande quantidade). Toma todos os remédios desde a primeira consulta. Reduzir furosemida pois está seco e discretamente hipotenso.', 'Reduzir furosemida para 20 mg/dia. Manter sacubitril/valsartana 24/26 mg, carvedilol 3,125 mg 12/12h, dapagliflozina; manter espironolactona 25 mg em dias alternados até K < 5,0. Repetir K e creatinina em 10 dias. Retorno em 30 dias.'),
  (1582, 467, 11, '2024-01-23 10:40', 'retorno', 'Voltei a trabalhar na roça', 110, 68, 64, 76.0, 'Seis meses após início da terapia otimizada, NYHA I-II, volta a trabalhar na roça e a pescar sem dispneia. Carvedilol titulado para 12,5 mg 12/12h, sacubitril/valsartana 49/51 mg 12/12h bem tolerado. K 4,8, creatinina 1,2. NT-proBNP 410. ECO de controle: FEVE 42%, DDVE 58 mm, IM leve. Sem álcool há 5 meses. Peso seco 76 kg, sem edema.', 'Manter os 4 pilares nas doses atuais, tentar subir sacubitril/valsartana para 97/103 mg se PA permitir. Controle de K e creatinina a cada 3 meses. Nova avaliação do ECO em 6 meses; reavaliar indicação de CDI se FEVE voltar a cair. Retorno em 3 meses.');
