insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (467, '2024-01-23', 'melhorou', 'Cardiomiopatia dilatada com ICFEr descompensada, otimizada com os quatro pilares. FEVE subiu de 30% para 42%, NT-proBNP caiu de 3.100 para 410, NYHA I-II e retomada do trabalho na roça. Abstinente de álcool.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (468, 'Matilde Soares Gadelha', 'F', '1940-05-08', 'Ji-Paraná', 'RO', 'Aposentada, ex-professora primária', 'FA permanente há 8 anos, HAS, osteoartrose de coluna e joelhos, DRC estágio 3b. Usava rivaroxabana 15 mg e diclofenaco 50 mg por conta própria para dores. Mora com a filha. Peso baixo, fragilidade moderada.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1583, 468, 1, '2023-02-09 14:30', 'consulta', 'Vim revisar o remédio do coração', 138, 74, 76, 55.0, 'Pcte 82a, FA permanente, CHA2DS2-VASc 5 (idade, sexo, HAS, ICFEp leve em ECO, DRC), usa rivaroxabana 15 mg com ClCr estimado em 28 mL/min (creatinina 1,3, peso 55 kg). Descobri ao interrogar que toma diclofenaco 50 mg por 2-3 dias na semana para dor nos joelhos, comprado sem receita. Hb 11,6. Sem melena referida. Ao exame: palidez leve, RCI 2T, sem sopros, MV+ sem RA, sem edema. FC 76 em uso de metoprolol 50 mg. Alto risco hemorrágico: HAS-BLED 4.', 'Suspender diclofenaco, alertando para risco de sangramento e piora renal. Dor: paracetamol 750 mg SN e fisioterapia. Manter rivaroxabana 15 mg com refeição, metoprolol succinato 50 mg. Orientar sinais de sangramento. Hemograma e creatinina em 3 meses. Retorno em 3 meses.'),
  (1584, 468, 1, '2023-08-22 09:50', 'retorno', 'Fraqueza e fezes escuras', 108, 62, 92, 53.5, 'Retorna com fraqueza progressiva e fezes escuras e fétidas há 5 dias; filha conta que voltou a tomar diclofenaco por conta da dor. Palidez importante, mucosas descoradas, PA 108x62, FC 92 (aumentou). Toque retal com melena. Hb 7,4 (caiu de 11,6), ureia elevada. Sem sinais de choque. HD: hemorragia digestiva alta em uso de DOAC e AINE.', 'Encaminhada ao PS para internação: suspensão da rivaroxabana, IBP em altas doses, hemotransfusão e EDA. Orientada a nunca mais usar anti-inflamatórios. Reavaliar anticoagulação após estabilização.'),
  (1585, 468, 14, '2023-12-04 03:50', 'internacao', 'Vômito com sangue e queda da pressão', 74, 42, 124, null, 'Reinternada em UTI com hematêmese volumosa e choque hemorrágico. Segundo a filha, após a alta de setembro, a rivaroxabana foi reintroduzida em outro serviço e voltou ao diclofenaco por dor. PA 74x42, FC 124 em FA, Hb 5,9, lactato 5,1, creatinina 2,4. EDA: úlcera gástrica com vaso visível, injeção de adrenalina e clipes, ressangramento no D2. Intubada, em noradrenalina e hemotransfusão de 4 concentrados. Evoluiu com acidose lática, disfunção renal e pneumonia aspirativa.', 'UTI, ventilação mecânica, noradrenalina, transfusão, IBP em infusão, antibiótico para pneumonia aspirativa, reversão do anticoagulante com andexanet não disponível; suporte. Discutido prognóstico e limitação de esforço com a família.');
