insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (468, '2023-12-09', 'obito', 'Faleceu na UTI no 5º dia de internação por choque hemorrágico e sepse pulmonar, complicação de hemorragia digestiva alta associada a anticoagulante e anti-inflamatório comprado sem receita. Família orientada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (469, 'Raimunda Nazaré Picanço', 'F', '1969-08-19', 'Rio Branco', 'AC', 'Cozinheira', 'Doença de Chagas crônica diagnosticada na doação de sangue há 8 anos, nascida em área rural do Acre. Cardiopatia chagásica com BRD + HBAE e extrassístoles frequentes, FEVE 48%. Amiodarona 200 mg/dia, carvedilol 6,25 mg 12/12h. HAS leve.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1586, 469, 4, '2022-09-13 10:20', 'consulta', 'Palpitação forte e quase desmaiei', 124, 78, 58, 66.0, 'Pcte 53a, cardiopatia chagásica, relata 4 episódios de palpitação súbita com tontura e pré-síncope em 2 meses, na cozinha, durando 2-5 min. Ao exame: RCR 2T BNF, sem sopros, sem congestão. ECG: ritmo sinusal 58 bpm, BRD + HBAE, QT 460 ms. Holter 24h: 1.200 EV, 3 episódios de TV não sustentada de 8-15 batimentos até 180 bpm, sem pausas. ECO: FEVE 46%, aneurisma apical pequeno. K 4,3, TSH normal. HD: TV não sustentada sintomática, risco de TV sustentada.', 'Aumentar amiodarona para 400 mg/dia por 1 mês e voltar a 200 mg, mantendo carvedilol. Pedir RM cardíaca para quantificar fibrose e avaliar CDI. Não indicado benznidazol. Evitar esforço físico intenso e estimulantes. Retorno em 30 dias.'),
  (1587, 469, 4, '2022-12-06 08:50', 'retorno', 'Tive um desmaio de verdade no mercado', 118, 72, 54, 65.4, 'Um episódio de síncope sem pródromos há 1 semana no mercado, recuperação rápida. RM cardíaca: realce tardio mesocárdico/transmural apical e inferolateral (14% da massa do VE), FEVE 44%. Holter novo com TV sustentada de 22 s a 190 bpm, autolimitada, sob amiodarona 200 mg e carvedilol. TSH 3,8, função hepática normal. Síncope + TV sustentada + cicatriz extensa: prevenção secundária de morte súbita com CDI e tratamento invasivo da TV (ablação).', 'Encaminhar para CDI e ablação por cateter de TV em centro de referência (Brasília/São Paulo). Aumentar carvedilol para 12,5 mg 12/12h se FC permitir; amiodarona mantida. Orientada a não dirigir; contato com regulação estadual.');
