insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (470, '2024-09-24', 'melhorou', 'Miocardite aguda pós-viral em jovem atleta, FEVE chegou a 49% e recuperou para 60% em 6 meses. Holter e ergométrico normais, medicações suspensas e retorno gradual ao treino liberado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (471, 'Sirlene Pinto Barbosa de Lima', 'F', '1975-04-05', 'Macapá', 'AP', 'Operadora de caixa de supermercado', 'HAS diagnosticada há 4 meses em consulta de urgência, iniciou anlodipino 10 mg. Obesidade grau I. Fica em pé 8 horas por dia e quase não pode ir ao banheiro. Mãe com HAS e AVC.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1591, 471, 5, '2024-10-08 16:00', 'consulta', 'Parei o remédio porque meus pés incharam', 158, 96, 82, 84.7, 'Pcte 49a, hipertensa há 4 meses, interrompeu anlodipino há 1 semana por edema de tornozelos bilateral que piora no fim do dia, com sensação de peso nas pernas. Ao exame: edema 2+/4+ até terço médio de pernas, sem sinais de TVP, RCR 2T BNF, MV+ sem RA, IMC 31,5. PA 158x96 sem medicação. Creatinina 0,8, K 4,2, glicemia 102. HD: HAS estágio 2 com intolerância ao anlodipino (edema periférico dose-dependente).', 'Suspender anlodipino. Iniciar losartana 50 mg 12/12h. Orientar elevar as pernas e meia de compressão leve. Dieta com menos sal e nutricionista. Dosar creatinina e K em 3 semanas. Retorno em 6 semanas.'),
  (1592, 471, 5, '2024-11-19 16:30', 'retorno', 'O inchaço sumiu mas a pressão ainda sobe', 144, 90, 80, 84.0, 'Edema desapareceu em 10 dias após suspensão do anlodipino. Toma losartana 50 mg 12/12h, mas esquece a dose da noite quando fecha o caixa tarde. PA 144x90, creatinina 0,9 e K 4,5. Sem tosse. Combinado esquema com menos tomadas. Discutida inclusão de clortalidona, ela recusa diurético porque no caixa não consegue ir ao banheiro quando quiser; propõe aumentar a losartana.', 'Losartana 100 mg em dose única pela manhã. Adicionar anlodipino 2,5 mg só se necessário. Reforçar MEV: caminhada e dieta. MRPA por 5 dias antes do retorno. Retorno em 8 semanas.'),
  (1593, 471, 5, '2025-03-04 16:20', 'retorno', 'Veio pegar a receita', 150, 92, 84, 85.5, 'Retorna após 3,5 meses, previsto em 8 semanas. Perdeu consulta marcada porque trocou de escala. Tem tomado losartana 100 mg irregularmente, ''quando lembro'', MRPA média 148x90. Ganhou 1,5 kg. Edema ausente. Paciente consciente do risco, diz que o tempo é curto, trabalha 6x1 e o posto de saúde fecha antes do fim do turno. Combinada receita para 6 meses e teleconsulta de acompanhamento.', 'Manter losartana 100 mg/dia. Adicionar anlodipino 2,5 mg (dose baixa para reduzir risco de edema). Teleconsulta em 1 mês com MRPA. Entregar receita de 6 meses e lembrete por WhatsApp da UBS. Retorno presencial em 3 meses.');
