insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (471, '2025-09-30', 'abandonou', 'Não compareceu à teleconsulta nem ao retorno de junho e não atendeu as ligações da UBS. A última PA registrada foi 150x92. A rotina de trabalho 6x1 e o edema com anlodipino foram as barreiras ao tratamento. Registrada perda de seguimento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (472, 'Moacir Ferreira Lacerda Neto', 'M', '1966-12-20', 'Manaus', 'AM', 'Motorista de caminhão de carga', 'HAS há 14 anos, em uso de losartana 100 mg, anlodipino 10 mg e clortalidona 25 mg há 2 anos, sem atingir a meta. Obesidade grau I e dislipidemia. Faz viagens longas, alimenta-se em postos de beira de estrada. Pai com HAS e infarto aos 65 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1594, 472, 1, '2023-09-05 08:40', 'consulta', 'Pressão sempre alta mesmo tomando tudo', 172, 104, 76, 98.5, 'Pcte 56a, HAS com 3 fármacos em dose plena (BRA, BCC, diurético) e PA persistentemente > 160x100. Adesão confirmada pelo registro da farmácia e pelo relato da esposa. Aferição correta com manguito de obeso (33 cm). MAPA: média 24h 162x98, vigília 166x100, sono 154x92, sem efeito do avental branco. Ronco leve, STOP-Bang 3. Creatinina 1,1, K 3,9, aldosterona/renina normal. Fundo de olho com cruzamentos arteriovenosos. HD: HAS resistente verdadeira.', 'Adicionar espironolactona 25 mg/dia, com K e creatinina em 1 semana e em 4 semanas. Orientação para reduzir sal de estrada (embutidos, salgados) e pesar-se. Polissonografia domiciliar. Retorno em 30 dias.'),
  (1595, 472, 1, '2023-10-03 08:30', 'retorno', 'Pressão baixou bastante', 140, 88, 72, 97.8, 'Após espironolactona, PA caiu de 172x104 para 140x88; MRPA média 138x86. K 4,6 em 1 semana e 4,8 em 4 semanas; creatinina 1,2 (subida de 0,1, esperada). Polissonografia: IAH 9, apneia leve, sem indicação de CPAP no momento. Sem dor no peito, sem edema. Refere cansaço leve nas viagens e um aumento discreto de mamas dolorosas, ''meio doloridas'', sem nódulo. Decidido titular a dose.', 'Aumentar espironolactona para 50 mg/dia. Repetir K e creatinina em 2 semanas e depois a cada 3 meses. Examinar mamas e explicar risco de ginecomastia; se persistir, trocar por amilorida. Retorno em 3 meses.'),
  (1596, 472, 1, '2024-02-06 09:10', 'retorno', 'Aparecendo um caroço doloroso no peito', 126, 78, 70, 94.0, 'PA 126x78, MRPA média 124x76: resistência controlada com quatro fármacos. K 5,0, creatinina 1,2. Queixa de ginecomastia dolorosa bilateral há 2 meses, com botão palpável subareolar de 2 cm, sem secreção, que o incomoda ao deitar e na vergonha com os colegas. Perdeu 4,5 kg. Exame de mamas: tecido glandular firme, simétrico. Sem alteração hormonal grave: testosterona total normal, prolactina normal.', 'Trocar espironolactona por amilorida 10 mg/dia; K e creatinina em 1 semana. Manter losartana, anlodipino e clortalidona. Retornar em 6 semanas; se a PA subir, discutir outra opção como eplerenona. Orientação de MEV mantida.');
