insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (472, '2024-02-06', 'controlado', 'Hipertensão resistente verdadeira, confirmada por MAPA, controlada com a adição de espironolactona (MRPA 124x76). Ginecomastia dolorosa levou à troca por amilorida, mantendo PA na meta. Perdeu 4,5 kg.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (473, 'Odete Cavalcanti Freire', 'F', '1959-03-28', 'Belém', 'PA', 'Aposentada, ex-auxiliar administrativa', 'DM2 há 18 anos com mau controle, HAS há 20 anos, DRC estágio 4 com seguimento irregular. Retinopatia diabética. Uso de losartana, anlodipino e insulina NPH. Usava diclofenaco por dor em coluna por 2 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1597, 473, 8, '2022-05-17 09:40', 'consulta', 'Inchaço e pressão alta que não cede', 176, 98, 78, 74.2, 'Pcte 63a, DRC por nefropatia diabética e hipertensiva, edema de MMII 3+/4+ e dispneia aos médios esforços; piora de 2 semanas. Parou o diclofenaco há 1 mês. PA 176x98 em 3 aferições. Ao exame: estertores finos em bases, estase jugular discreta. Creatinina 2,6 (TFGe 19), K 5,1, bicarbonato 19, Hb 10,2, albuminúria 850 mg/g. HAS secundária ao componente renal e hipervolemia. Sobrecarga de volume contribuindo para a resistência.', 'Furosemida 80 mg de manhã, dieta com restrição de sal (2 g de sódio) e de potássio, bicarbonato de sódio. Manter anlodipino, suspender losartana temporariamente pelo K 5,1. Orientada a não usar AINE. Controle de PA domiciliar. Retorno em 15 dias.'),
  (1598, 473, 8, '2022-06-01 09:20', 'retorno', 'Perdi o inchaço, mas me sinto fraca', 150, 86, 74, 69.0, 'Perda de 5,2 kg, edema discreto 1+, dispneia melhor. PA 150x86. Creatinina 2,8, K 4,8, bicarbonato 22. Reintrodução de bloqueio do SRAA: discutido com cuidado a relação entre benefício e risco; K agora aceitável. Hb 10,0. Refere cãibras e fraqueza. Seguiu com dieta, mas relata dificuldade por conta do custo de alimentos ''sem sal''. Fundo de olho com retinopatia não proliferativa estável.', 'Reiniciar losartana 25 mg/dia, K e creatinina em 1 semana. Manter furosemida 80 mg e anlodipino 10 mg, adicionar carvedilol 6,25 mg 12/12h. Solicitado ferro sérico/ferritina e PTH. Encaminhada à nutricionista renal. Retorno em 30 dias.'),
  (1599, 473, 8, '2023-04-11 10:00', 'retorno', 'Muito enjoo, sem apetite e coceira', 156, 90, 82, 66.5, 'Dez meses após, evolução desfavorável: creatinina 4,1 (TFGe 11), ureia 168, K 5,6, bicarbonato 16, Hb 8,6, fósforo 6,4. Náuseas, anorexia, prurido e fraqueza; edema de MMII 2+/4+. PA 156x90 com carvedilol, anlodipino e furosemida; losartana suspensa por K. Sinais de uremia, pericárdio sem atrito. DRC G5 com indicação de diálise. Já tinha sido orientada a fazer fístula, mas ainda sem acesso definitivo por demora na regulação.', 'Internação eletiva para início de hemodiálise por cateter de duplo lúmen, com programação de fístula. Eritropoetina e ferro EV nas sessões. Dieta renal. Suspensão de losartana. Orientados a família e transporte para 3 sessões semanais.');
