insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (473, '2023-05-20', 'piorou', 'DRC por nefropatia diabética e hipertensiva progrediu para estágio 5 (TFGe 11) apesar do controle de volume e pressão. Iniciou hemodiálise por cateter em maio de 2023 e aguarda confecção de fístula arteriovenosa.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (474, 'Leandro Schneider Wagner', 'M', '1982-07-14', 'Curitiba', 'PR', 'Gerente de banco', 'Pais hipertensos. Tabagista social, 1 maço por semana. Consumo de café e energético em excesso no trabalho, jornada longa e estresse. PA em consultório sempre normal, mas sente cefaleia no fim do dia.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1600, 474, 1, '2025-02-18 12:10', 'consulta', 'Dor de cabeça no fim do expediente e histórico de pressão alta na família', 128, 80, 78, 86.0, 'Pcte 42a, assintomático além de cefaleia vespertina leve. Em consultório PA 128x80. Traz MRPA de 7 dias com média 144x92 (manhã 142x90, noite 148x94) feita por conta própria com aparelho validado. Ao exame: IMC 27,5, RCR 2T BNF, sem sopros. ECG sem HVE, ECO com septo 11 mm, creatinina 0,9, K 4,3. HD: suspeita de hipertensão mascarada (PA normal no consultório, elevada fora dele). Pedido MAPA para confirmar.', 'Solicitar MAPA 24h. Reduzir cafeína, energético e cigarro. Iniciar caminhadas. Pedir perfil lipídico, glicemia e relação albumina/creatinina. Retorno com MAPA em 2-3 semanas.'),
  (1601, 474, 1, '2025-03-11 12:00', 'retorno', 'Resultado da MAPA', 126, 80, 76, 85.4, 'MAPA 24h: média 24h 138x88, vigília 146x94, sono 122x72, com carga pressórica de 62% na vigília. Confirmada hipertensão mascarada: PA de consultório 126x80, mas elevada durante o dia, associada a estresse no trabalho. Glicemia 96, LDL 138, HbA1c 5,4%. Com lesão de órgão-alvo ausente, mas risco aumentado pela mascarada (equivalente à HAS). Conversado que a PA normal no consultório não é garantia de normalidade. Paciente entende e aceita medicação.', 'Iniciar losartana 50 mg pela manhã, manter MEV, reduzir estresse e cafeína. MRPA contínuo semanal. Repetir MAPA em 3 meses para conferir resposta. Retorno em 6 semanas.'),
  (1602, 474, 1, '2025-06-17 12:30', 'retorno', 'Quero ver a segunda MAPA', 120, 76, 72, 83.2, 'Parou de fumar há 2 meses e trocou o energético por água. MRPA com média de 122x76. Segunda MAPA: média 24h 120x74, vigília 126x78, sono 108x64, dentro da meta. Cefaleia desapareceu. Sem tosse, tontura ou alteração de função renal; creatinina 0,9, K 4,4. Perdeu 2,8 kg. Mantém a medicação sem dificuldade.', 'Manter losartana 50 mg. Meta atingida com MEV. Retorno anual com MAPA ou MRPA. Se mantiver o estilo de vida saudável por 12 meses, reavaliar necessidade do fármaco.');
