insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (474, '2025-06-17', 'controlado', 'Hipertensão mascarada diagnosticada pela MRPA e confirmada por MAPA, com PA de consultório normal. Controlada com losartana 50 mg, abandono do tabagismo e redução de cafeína; segunda MAPA com média de 120x74.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (475, 'Conceição Aparecida Drummond', 'F', '1953-09-02', 'Belo Horizonte', 'MG', 'Aposentada, ex-bancária', 'HAS, DM2 e dislipidemia. Ex-fumante (15 maços-ano). Angina aos esforços há 6 meses sem investigação, em uso de AAS, atenolol 50 mg, sinvastatina 20 mg. Irmão com infarto aos 58 anos. Faz caminhada 3x/semana.', 'Alergia a dipirona (urticária)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1603, 475, 6, '2023-11-06 05:10', 'pronto_socorro', 'Dor no peito em repouso me acordou', 164, 90, 86, 71.8, 'Pcte 70a, dor retroesternal em aperto, 25 min de duração, em repouso, às 4h, associada à sudorese. Essa é a 3ª vez em 2 dias, com melhora parcial pela nitroglicerina SL. Ao exame: ansiosa, RCR 2T BNF, MV+ sem RA, sem edema. ECG: infradesnivelamento de ST de 1,5 mm V4-V6, sem supra. Troponina ultrassensível 0,012 ng/mL (normal) e repetição 3 h depois: 0,014. HD: angina instável (Braunwald IIIB), alto risco (GRACE 128).', 'Internação, AAS 200 mg, clopidogrel 300 mg de ataque, enoxaparina 1 mg/kg 12/12h, atorvastatina 80 mg, metoprolol e nitrato EV se dor. CATE em até 24-48 horas. Dieta zero após meia-noite.'),
  (1604, 475, 10, '2023-11-07 14:00', 'internacao', 'Cateterismo', 140, 82, 72, 71.8, 'CATE radial direita: lesão de 90% na artéria coronária direita proximal com trombo, lesão de 75% na DA média, Cx sem lesões significativas. FEVE 58%. Realizada ATC com stent farmacológico na CD proximal (3,5x24 mm), com pós-dilatação, sem complicações, TIMI 3 final; segunda lesão da DA com FFR 0,74 e tratada com stent farmacológico 3,0x18 mm na mesma sessão. Sem dor após o procedimento, sem complicações no acesso.', 'DAPT com AAS 100 mg + clopidogrel 75 mg por 12 meses. Atorvastatina 80 mg, metoprolol 50 mg, enalapril 5 mg 12/12h, suspensão do atenolol. Alta em 48 h. Reabilitação cardíaca. Retorno em 30 dias.'),
  (1605, 475, 1, '2023-12-12 10:30', 'retorno', 'Estou sem dor, só um pouco de hematoma no braço', 128, 74, 60, 71.0, '30 dias pós-ATC. Sem angina, sem dispneia. Pequeno hematoma no antebraço direito resolvido. Iniciou reabilitação cardíaca e caminha 40 min. PA 128x74, FC 60. Sem sangramento digestivo. LDL 48, HbA1c 7,2%, creatinina 0,9, K 4,4. Sem tosse com enalapril. Evitar dipirona (alergia), analgesia com paracetamol.', 'Manter DAPT por 12 meses, atorvastatina 80 mg, metoprolol 50 mg, enalapril 5 mg 12/12h. Reabilitação 3x/semana. Retorno em 6 meses.');
