insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (475, '2023-12-12', 'melhorou', 'Angina instável tratada com ATC e dois stents farmacológicos (CD e DA). Um mês depois, sem angina, LDL 48 e em reabilitação cardíaca, mantendo dupla antiagregação e estatina de alta potência.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (476, 'Jorge Luiz Marinho Cavalcante', 'M', '1970-01-11', 'Rio Branco', 'AC', 'Mecânico de automóveis', 'Tabagista de 25 maços-ano. Dislipidemia sem tratamento, LDL 190. Sedentário, come muita fritura. Pai morreu de infarto aos 60 anos. Sem diagnóstico de HAS ou DM até então.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1606, 476, 6, '2024-06-27 18:30', 'pronto_socorro', 'Aperto no peito e suor frio', 152, 94, 88, 92.0, 'Pcte 54a, dor precordial em aperto, irradiada para mandíbula, há 2 h, iniciada durante o trabalho, com sudorese e náusea. Ao exame: pálido, sudoreico, RCR 2T BNF, MV+ sem RA, sem sinais de IC. ECG: infradesnivelamento de ST 2 mm V3-V6 e onda T negativa, sem supradesnivelamento. Troponina de 1ª amostra 0,9 ng/mL, 2ª 2,6 ng/mL. HD: IAM sem supra (IAMSSST), GRACE 118.', 'AAS 300 mg, ticagrelor 180 mg, enoxaparina 1 mg/kg, atorvastatina 80 mg, metoprolol; dor tratada com nitroglicerina EV. Estratificação invasiva em 24 h. Internação em unidade coronariana.'),
  (1607, 476, 10, '2024-06-28 10:00', 'internacao', 'Cateterismo no dia seguinte ao infarto', 134, 80, 70, 92.0, 'Sem dor desde a admissão, ECG sem novas alterações, troponina pico 5,8 ng/mL. CATE: lesão culpada de 95% na circunflexa proximal, DA com placa de 50% e CD sem lesões. ATC com stent farmacológico 3,0x22 mm na Cx proximal, TIMI 3 final. FEVE 54%, hipocinesia lateral. Ecocardiograma sem derrame. Ficou 3 dias internado, orientado sobre cessação do tabagismo, dieta e atividade física. Sem complicações.', 'Alta com DAPT por 12 meses, atorvastatina 80 mg + ezetimiba 10 mg (LDL 190), metoprolol e losartana 25 mg (PA 134x80 limítrofe, FEVE 54%). Reabilitação cardíaca. Retorno em 30 dias.'),
  (1608, 476, 1, '2024-08-01 14:30', 'retorno', 'Cheguei a fumar de novo, 3 cigarros por dia', 124, 76, 64, 90.5, '5 semanas pós-IAMSSST, sem angina. Voltou ao trabalho, mas recaiu com cigarro (3/dia). Refere dispneia ao esforço máximo e leve gosto ruim ao tomar ticagrelor. PA 124x76. Sem sangramentos. LDL 72 com atorvastatina 80 + ezetimiba. TGO/TGP normais, CPK normal. Iniciou reabilitação, falta de transporte atrapalha as sessões.', 'Manter DAPT por 12 meses. Reforçar tabagismo: iniciar vareniclina e adesivo de nicotina, grupo na UBS. Manter demais fármacos. Reabilitação em casa com caminhadas orientadas. Retorno em 3 meses.');
