insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (476, '2024-08-01', 'melhorou', 'IAMSSST tratado com ATC e stent na circunflexa, assintomático e LDL de 190 para 72. Recaiu parcialmente no tabagismo (3 cigarros/dia), em tratamento com vareniclina, mantendo DAPT e acompanhamento.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (477, 'Geni Pereira Montenegro', 'F', '1958-08-30', 'Santarém', 'PA', 'Vendedora de peixe na feira', 'IAM de parede anterior em 2019, com ATC e stent na DA. HAS e DM2. Sedentária, fica em pé na feira o dia todo. Gosta de peixe salgado e farinha. Tabagista até o IAM. Usava AAS, enalapril, metformina, atorvastatina 40 mg.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1609, 477, 11, '2022-02-15 10:30', 'consulta', 'Cansaço para trabalhar e inchaço', 124, 76, 88, 68.3, 'Pcte 63a, cardiomiopatia isquêmica pós-IAM, ICFEr NYHA II-III, dispneia aos médios esforços, edema vespertino. Ao exame: sem estase jugular, MV+ com estertores finos em bases, RCR 2T B3, edema 1+/4+. ECO: FEVE 28%, hipocinesia anterior e apical com aneurisma apical, IM leve. NT-proBNP 2.400. Creatinina 1,0, K 4,5. HD: ICFEr isquêmica, em uso de enalapril e BB só em dose baixa, sem espironolactona ou iSGLT2.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36 h sem IECA. Iniciar espironolactona 25 mg, dapagliflozina 10 mg e titular carvedilol 6,25 mg 12/12h. Restrição de sal. Exames de K e creatinina em 1 semana. Retorno em 1 mês.'),
  (1610, 477, 6, '2022-04-09 01:50', 'pronto_socorro', 'Acordei sem ar, afogada', 186, 104, 118, null, 'Pcte 63a, ICFEr, acorda com dispneia súbita intensa, tosse com secreção rosada, sudorese. Come peixe seco e salgado na festa de família nos dias anteriores e deixou de tomar furosemida. Ao exame: taquipneica, SatO2 82% AA, estertores até ápices, B3, PA 186x104, FC 118. RX com congestão perihilar. ECG: taquicardia sinusal, sem supra. Troponina 0,04, BNP muito elevado. HD: edema agudo de pulmão cardiogênico por descompensação de ICFEr.', 'O2 por máscara com reservatório, CPAP, furosemida 80 mg EV, nitroglicerina EV; mantido sacubitril/valsartana. Observação em UTI. Dispneia melhorou em 2h com SatO2 95%. Reforçar dieta e furosemida diária.'),
  (1611, 477, 11, '2022-05-03 09:30', 'retorno', 'Voltei depois do susto', 112, 70, 70, 65.0, 'Retorna 3,5 semanas após o EAP, com perda de 3,3 kg, sem ortopneia, NYHA II. Explicou que parou a furosemida porque ''urinava demais na feira''. Agora entende o risco; propõe tomar o diurético após a feira. Cumprindo a restrição de sal. K 4,9, creatinina 1,1. PA 112x70 sem tontura. Carvedilol titulado para 12,5 mg 12/12h. Peso seco ~65 kg.', 'Manter 4 pilares: sacubitril/valsartana 49/51 mg 12/12h, carvedilol 12,5 mg 12/12h, espironolactona 25 mg, dapagliflozina 10 mg. Furosemida 40 mg à tarde. K e creatinina em 2 semanas. Retorno em 2 meses com ECO e NT-proBNP.'),
  (1612, 477, 11, '2023-02-14 09:40', 'retorno', 'Estou bem, trabalhando normal', 108, 66, 62, 65.4, '9 meses depois, NYHA I-II, sem nova internação nem EAP. Segue com dieta e pesagem. ECO: FEVE 36%, aneurisma apical estável, sem trombo, IM leve. NT-proBNP 380 pg/mL. K 4,6, creatinina 1,0. Sem tosse nem angioedema. Sobre prevenção de morte súbita: FEVE de 36% está no limiar, sem indicação imediata de CDI; segue em terapia otimizada com nova reavaliação do ECO em 6 meses.', 'Manter os 4 pilares, tentar sacubitril/valsartana 97/103 mg se PA permitir. Vacinação em dia. Controle laboratorial a cada 3-4 meses. Reavaliar FEVE em 6 meses para decisão sobre CDI. Retorno em 6 meses.');
