insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (477, '2023-02-14', 'estavel', 'ICFEr isquêmica estável em NYHA I-II com os quatro pilares após um episódio de EAP por transgressão de sal e abandono do diurético. FEVE 36%, NT-proBNP 380, sem novas internações; indicação de CDI será reavaliada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (478, 'Hildegard Becker Ramos', 'F', '1967-05-21', 'Palmas', 'TO', 'Professora universitária', 'Sopro cardíaco conhecido desde a juventude, sem acompanhamento. Prolapso de valva mitral sem sintomas até recentemente. Hipotireoidismo tratado com levotiroxina 75 mcg. Caminha 3x/semana, vem notando mais cansaço.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1613, 478, 1, '2024-03-12 15:30', 'consulta', 'Estou me cansando mais e sinto o coração disparar', 128, 74, 88, 62.0, 'Pcte 56a, dispneia aos médios esforços há 6 meses, palpitações esporádicas, sem síncope. Ao exame: RCR 2T, sopro holossistólico 4+/6+ em foco mitral irradiado para axila, B3 presente. MV+ sem RA, sem edema. ECG: ritmo sinusal, sobrecarga atrial esquerda. ECO: prolapso de VM com folheto P2 flutuante (flail leaflet), jato excêntrico, IM grave (ORE 0,5 cm²), AE 52 mm, DSVE 42 mm, FEVE 58%, PSAP 46 mmHg. HD: IM grave primária sintomática por prolapso/flail de P2.', 'Indicação de tratamento cirúrgico (plástica mitral é preferível). Solicitar ETE e angiotomografia de coronárias antes. Diurético em dose baixa para sintomas. Discutir caso com Heart Team. Encaminhar para centro de referência em cirurgia mitral. Retorno em 4 semanas.'),
  (1614, 478, 12, '2024-04-23 14:00', 'retorno', 'Resultado do eco transesofágico e avaliação cirúrgica', 124, 72, 84, 61.6, 'ETE: ruptura de cordoalha em P2, plástica mitral factível, sem trombo em apêndice atrial, sem vegetação. Angio-TC: coronárias sem lesões. FEVE 56%, DSVE 44 mm, tendência à dilatação: indicação cirúrgica não pode esperar. Paciente em ritmo sinusal, mas com fibrilação atrial paroxística ao Holter (2 episódios de 40 min). Optado por encaminhamento para serviço terciário com experiência em plástica mitral minimamente invasiva em São Paulo, já aceito pela regulação. Cirurgia prevista em 3 semanas.', 'Transferir o seguimento ao hospital de referência para plástica mitral e ablação concomitante de FA, se indicada. Anticoagulação peri-operatória a critério da equipe de destino. Entregues relatório, ETE e Angio-TC. Orientados sinais de IC e FA.');
