insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (478, '2024-05-02', 'transferido', 'Insuficiência mitral grave por flail de P2 com FA paroxística, encaminhada ao hospital de referência em São Paulo para plástica mitral. Deixou o acompanhamento da clínica com relatório e exames anexados.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (479, 'Camila Yumi Takahashi Prado', 'F', '1991-10-09', 'Campinas', 'SP', 'Analista de sistemas', 'Palpitações súbitas desde a adolescência, 2 a 3 episódios por ano, com início e fim abruptos, aliviados por manobra de Valsalva. Sem cardiopatia conhecida. Consome muito café e energético, sono irregular. Sem uso de medicamentos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1615, 479, 6, '2023-04-18 03:20', 'pronto_socorro', 'Coração disparou e não passa', 104, 66, 184, 57.0, 'Pcte 31a, palpitações súbitas há 50 minutos, sem dor torácica, com tontura leve e mal-estar. Valsalva sem efeito. Ao exame: ansiosa, pálida, sem sinais de IC, PA 104x66, FC 184 regular. ECG: taquicardia de QRS estreito regular a 184 bpm, sem onda P visível, RP curto, sem pré-excitação. HD: TSV por reentrada nodal (provável TRN).', 'Manobra de Valsalva modificada sem sucesso, adenosina 6 mg EV rápido sem reversão e depois 12 mg com reversão a ritmo sinusal de 76 bpm, curta pausa. ECG pós-reversão sem pré-excitação. Alta após 3 h de observação. Evitar cafeína. Encaminhar à arritmologia. TSH e eletrólitos solicitados.'),
  (1616, 479, 4, '2023-05-16 09:00', 'consulta', 'Quero saber se tem tratamento definitivo', 110, 68, 72, 57.2, 'Retorna sem novas crises. Exame físico normal. ECO normal (FEVE 64%, sem cardiopatia estrutural), TSH 1,9, K 4,2, Mg normal. Holter sem arritmias. Conta que os episódios afetam o trabalho e as viagens. Discutidas as opções: betabloqueador de uso contínuo, ''pílula do bolso'' ou ablação por cateter (cura em > 95% para TRN, risco de BAV de 1%). Ela prefere tratamento definitivo e não quer medicação diária.', 'Agendar estudo eletrofisiológico e ablação por radiofrequência. Em crise, repetir manobras vagais; se não reverter em 20 min, ir ao PS. Evitar café e energético. Retorno após o procedimento.'),
  (1617, 479, 4, '2023-07-10 07:30', 'internacao', 'Procedimento de ablação', 112, 70, 70, 57.0, 'Estudo eletrofisiológico sob sedação: intervalo AH 78 ms, indução de taquicardia por reentrada nodal comum (TRN lento-rápida) com isoproterenol, ciclo 330 ms. Ablação por radiofrequência da via lenta com junção acelerada transitória e sem BAV; não induzível ao final do procedimento mesmo com isoproterenol. Acesso venoso femoral direito sem complicações. Alta em 24 h, deambulando, ECG normal.', 'Repouso relativo por 3 dias, sem esforço físico intenso por 1 semana, curativo inguinal. Sem medicação contínua. Retorno em 30 dias.'),
  (1618, 479, 4, '2023-08-14 08:50', 'retorno', 'Estou ótima, sem palpitação', 108, 66, 68, 57.4, 'Cinco semanas após ablação, sem recorrência de taquicardia, sem desconforto no local da punção. Retomou academia e as viagens. ECG normal, PR 148 ms, sem pré-excitação. Holter de 24 h sem eventos. Paciente aliviada: ''não penso mais em ir pro pronto-socorro a cada palpitação''. Mantém consumo moderado de café.', 'Alta do seguimento arritmológico ambulatorial. Retorno apenas se recorrência dos sintomas. Orientar procurar PS se palpitação sustentada.');
