insert into exame (id_atendimento, nome, resultado) values
  (1615, 'ECG durante a crise', 'Taquicardia regular de QRS estreito, 184 bpm, sem onda P visível'),
  (1615, 'ECG pós-reversão', 'Ritmo sinusal 76 bpm, PR 140 ms, sem pré-excitação'),
  (1616, 'Ecocardiograma transtorácico', 'FEVE 64% (Simpson), sem cardiopatia estrutural'),
  (1616, 'Holter 24h', 'Ritmo sinusal, sem arritmias sustentadas'),
  (1616, 'TSH', '1,9 mUI/L'),
  (1617, 'Estudo eletrofisiológico', 'TRN comum induzível (ciclo 330 ms); ablação da via lenta com sucesso; sem BAV; não induzível ao final'),
  (1618, 'ECG', 'Ritmo sinusal 68 bpm, PR 148 ms, sem pré-excitação'),
  (1618, 'Holter 24h', 'Ritmo sinusal, FC 52-132 bpm, sem taquiarritmias');
insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (479, '2023-08-14', 'controlado', 'TSV por reentrada nodal tratada com ablação por radiofrequência da via lenta, sem BAV nem complicações. Sem recorrência em 5 semanas e Holter normal. Recebeu alta do seguimento arritmológico.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (480, 'Nilton Gomes de Almeida Rocha', 'M', '1950-06-06', 'Porto Velho', 'RO', 'Aposentado, ex-pescador', 'HAS há 25 anos, tomando só enalapril às vezes. Ex-tabagista pesado. Sem diagnóstico prévio de arritmia. Vizinho teve hemorragia grave com varfarina, o que gerou receio em usar anticoagulantes. Mora com a esposa.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1619, 480, 1, '2021-08-10 10:00', 'consulta', 'Pressão alta e coração irregular', 154, 90, 96, 78.5, 'Pcte 71a, assintomático, notou pulso irregular quando a UBS mediu a pressão. Ao exame: RCI 2T, sem sopros, pulso irregularmente irregular, MV+ sem RA, sem edema. ECG: fibrilação atrial com resposta ventricular média de 96 bpm. ECO: AE 46 mm, FEVE 55%, HVE leve. Creatinina 1,1, Hb 14. CHA2DS2-VASc 2 (idade 65-74 e HAS), com tabagismo pesado prévio e aterosclerose provável; anticoagulação indicada.', 'Recomendada anticoagulação com apixabana 5 mg 12/12h. Paciente recusa por medo de sangramento. Combinada nova conversa com a esposa presente. Iniciado metoprolol succinato 50 mg para controle de FC e losartana 50 mg. Retorno em 30 dias para nova discussão. Orientados sinais de AVC.'),
  (1620, 480, 1, '2021-09-21 10:20', 'retorno', 'Vim só buscar a receita da pressão', 138, 84, 72, 78.0, 'Mantém recusa à anticoagulação, mesmo após a conversa. Diz: ''meu vizinho sangrou até morrer com remédio de sangue''. FC controlada com metoprolol, 72 bpm, sem sintomas. Risco explicado: risco de AVC de ~7% ao ano sem anticoagulação, com comparação de números com risco de sangramento do DOAC (baixo). Registrada recusa informada. Apixabana disponível pelo SUS. Esposa apoia o tratamento. PA 138x84.', 'Manter metoprolol e losartana. Novamente oferecida apixabana; paciente adia a decisão. Orientado sobre sinais de AVC (boca torta, fraqueza, fala embolada) e ir imediatamente ao PS. Retorno em 3 meses.'),
  (1621, 480, 13, '2022-01-30 07:40', 'internacao', 'Boca torta e fala enrolada', 188, 100, 110, null, 'Início há 90 min de afasia de expressão, desvio de rima à direita e hemiparesia direita grau 2, NIHSS 14. Esposa conta que ele nunca iniciou anticoagulante. TC de crânio sem hemorragia, angio-TC com oclusão de M1 esquerda. FA com FC 110. Dentro da janela de 4,5 h: trombólise com alteplase iniciada, seguida de trombectomia mecânica com recanalização TICI 2b-3 em 3h. Admitido na unidade de AVC, NIHSS final 7.', 'Unidade de AVC, controle de PA < 180x105 após trombólise, repetição de TC em 24 h sem transformação hemorrágica. Anticoagulação oral com apixabana a partir de 5-7 dias (AVC moderado). Fisioterapia, fonoaudiologia, atorvastatina 80 mg.'),
  (1622, 480, 1, '2022-03-15 10:30', 'retorno', 'Agora quero tomar o remédio do sangue', 136, 82, 68, 75.0, '6 semanas pós-AVC cardioembólico. Sequela: hemiparesia direita leve (força 4/5), disartria discreta, caminhando com bengala, em fisioterapia. Agora aceita anticoagulante: ''o AVC me deu medo, depois de ficar sem fala''. Iniciou apixabana há 3 semanas por orientação do neurologista, sem sangramentos. Creatinina 1,2; Hb 13,5; ClCr 62. PA 136x82. FA com FC 68 sob metoprolol.', 'Manter apixabana 5 mg 12/12h (sem critério de redução), metoprolol succinato 50 mg, losartana 50 mg 12/12h, atorvastatina 80 mg. Fisioterapia e fonoterapia. Hemograma e creatinina em 6 meses. Retorno em 3 meses.');
