insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (480, '2022-03-15', 'piorou', 'FA permanente não anticoagulada por recusa do paciente evoluiu com AVC isquêmico cardioembólico (oclusão de M1), tratado com trombólise e trombectomia. Ficou com hemiparesia leve e disartria; só então aceitou a apixabana.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (481, 'Arnaldo Sebastião Vilhena', 'M', '1964-01-18', 'Altamira', 'PA', 'Pecuarista', 'HAS há 11 anos e DM2 há 7 anos. Em uso de enalapril 20 mg/dia e metformina 1.000 mg 2x/dia. Obesidade grau I. Ex-fumante há 10 anos. Vem à cidade só a cada poucos meses. Pai diabético com doença renal.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1623, 481, 1, '2022-08-23 09:00', 'consulta', 'Vim fazer os exames do diabetes e da pressão', 156, 92, 78, 93.0, 'Pcte 58a, HAS e DM2 com PA 156x92 apesar de enalapril 20 mg/dia, assintomático. Ao exame: IMC 31, RCR 2T BNF, sem edema, pulsos pediosos presentes. Exames: HbA1c 8,2%, creatinina 1,1 (TFGe 76), K 4,6, LDL 118, relação albumina/creatinina 280 mg/g (moderadamente aumentada, confirmada em 2 amostras). Fundo de olho sem retinopatia. HD: HAS não controlada + DM2 com albuminúria (nefropatia diabética incipiente).', 'Trocar enalapril por losartana 100 mg/dia, mais apropriado em dose única para quem vem pouco à cidade. Adicionar anlodipino 5 mg. Orientado dieta com menos sal e redução de peso. HbA1c e albuminúria em 3 meses. Retorno em 5 semanas.'),
  (1624, 481, 9, '2022-09-27 09:20', 'retorno', 'Retorno para ajustar o diabetes', 138, 84, 74, 92.0, 'PA 138x84 com losartana + anlodipino, sem edema ou tosse. Creatinina 1,2, K 4,9 (aumento da creatinina de 9%). Glicemia de jejum 160, HbA1c 8,2% ainda. Reforçada a orientação alimentar; refere churrasco todo fim de semana e grande consumo de farinha. Usa metformina corretamente, sem sintomas de hipoglicemia. Discutida a adição de iSGLT2 pelo benefício renal e cardiovascular, com indicação formal pela albuminúria.', 'Adicionar dapagliflozina 10 mg/dia (higiene genital, hidratação, suspender se doença aguda febril/vômitos). Manter losartana 100 mg, anlodipino 5 mg, metformina. Creatinina, K, HbA1c e albuminúria em 3 meses. Retorno em 3 meses.'),
  (1625, 481, 1, '2023-03-14 08:50', 'retorno', 'Estou me sentindo bem, vim ver os exames', 126, 76, 70, 87.4, 'Perdeu 5,6 kg em 6 meses. PA 126x76, MRPA domiciliar média 124x74. Sem infecção genital, sem tontura. HbA1c 7,1%, creatinina 1,2 (TFGe 69), K 4,7, relação albumina/creatinina 90 mg/g (queda de 68% em relação ao basal). LDL 74 com atorvastatina 20 mg. Fundo de olho normal. Orgulhoso dos resultados, diz que o filho o ajudou a organizar os remédios numa caixinha semanal.', 'Manter losartana 100 mg, anlodipino 5 mg, metformina e dapagliflozina. Continuar MEV. Controle de creatinina/K/albuminúria a cada 6 meses. Retorno em 6 meses.');
