insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (481, '2023-03-14', 'controlado', 'HAS e DM2 com albuminúria controlados: PA 126x76, HbA1c 7,1% e albuminúria reduzida de 280 para 90 mg/g com losartana 100 mg e dapagliflozina. Perdeu 5,6 kg; função renal estável.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (482, 'Vanessa Kunz Albrecht', 'F', '1971-06-26', 'Florianópolis', 'SC', 'Advogada', 'HAS há 8 anos, obesidade grau II (IMC 38) há muitos anos, em uso de losartana + hidroclorotiazida 100/25 mg e anlodipino 10 mg. Apneia leve. Mãe com DM2. Sedentária, jornadas longas, come tarde da noite.', 'Alergia a sulfa (rash cutâneo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1626, 482, 2, '2022-01-18 18:00', 'consulta', 'Quero emagrecer e reduzir os remédios', 138, 86, 80, 102.4, 'Pcte 50a, HAS controlada por pouco com 3 fármacos, mas cansada dos efeitos: edema de tornozelos com anlodipino, nictúria com diurético. Aferição 138x86, MRPA 134x84. IMC 38,3, circunferência abdominal 118 cm. Creatinina 0,8, K 3,8, HbA1c 5,9%, LDL 126, ácido úrico 7,6. Optou por um programa multiprofissional com nutricionista, educador físico e terapia comportamental; já tem indicação de semaglutida para obesidade discutida com endócrino. Alergia a sulfa registrada (hidroclorotiazida é derivado de sulfonamida, tolerou até hoje).', 'Manter os anti-hipertensivos até alcançar perda sustentada de peso. Iniciar plano de emagrecimento (déficit calórico, caminhada, apoio psicológico). Auto-monitorizar PA em casa e comunicar PA < 110x70 ou tontura. Retorno em 3 meses.'),
  (1627, 482, 2, '2022-11-08 18:30', 'retorno', 'Perdi bastante peso e a pressão ficou baixa', 108, 66, 68, 81.0, 'Perdeu 21,4 kg em 10 meses com dieta, musculação e semaglutida 1 mg/sem prescrita pela endocrinologia. PA 108x66, MRPA média 106x64, com episódios de tontura ao levantar e fadiga à tarde. Sem síncope. Edema de tornozelos desapareceu com a perda de peso. Creatinina 0,8, K 3,6 (limite inferior) com a hidroclorotiazida. HbA1c 5,3%, LDL 98. Hipotensão relativa por excesso de tratamento agora que o peso caiu.', 'Suspender anlodipino e a combinação com hidroclorotiazida. Manter apenas losartana 50 mg/dia. K em 1 semana. MRPA diária por 2 semanas e retorno em 1 mês; reintroduzir se PA > 130x80 de forma sustentada.'),
  (1628, 482, 2, '2023-09-12 18:00', 'retorno', 'Mantendo o peso, acho que posso parar a losartana', 118, 72, 64, 76.5, 'Dez meses depois, 25,9 kg a menos desde o início (IMC 28,6). MRPA estável 114x70 com losartana 50 mg. Sem queixas, treino 4x/semana. Creatinina 0,8, K 4,2, HbA1c 5,2%, ácido úrico 5,4. Sem apneia relevante pelo ronco. Combinamos retirar a losartana de forma supervisionada, mantendo MRPA semanal, com retorno em 6 semanas para checar.', 'Suspender losartana, mantendo MEV e peso. MRPA 3x/semana e retorno em 6 semanas. Se PA > 135x85 em média, reiniciar losartana 25 mg. Manter semaglutida conforme endocrinologia.');
