insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (482, '2023-12-05', 'controlado', 'Com perda de quase 26 kg, deixou três anti-hipertensivos. Após a suspensão da losartana manteve MRPA média de 118x72 na última verificação. Segue em MEV e controle semestral, com reinício do fármaco se a PA subir.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (483, 'Edvaldo Pires Albuquerque Filho', 'M', '1958-02-09', 'Manaus', 'AM', 'Aposentado, ex-estivador do porto', 'HAS há 22 anos com tratamento irregular, parou o anlodipino e a losartana há 2 meses por falta de dinheiro. Cardiopatia hipertensiva com HVE conhecida. Tabagista de 40 maços-ano. Consome cerveja diariamente. Mora com a neta.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1629, 483, 6, '2024-09-14 02:30', 'pronto_socorro', 'Falta de ar terrível, não consigo deitar', 232, 128, 118, null, 'Pcte 66a, dispneia súbita intensa há 2 h, tosse com escarro espumoso róseo, agitação, sudorese. Ao exame: sentado, taquipneico (FR 34), SatO2 80% AA, estertores até ápices bilaterais, B3, PA 232x128, FC 118. ECG: taquicardia sinusal, SVE com strain, sem supra. Troponina 0,09 (leve elevação por demanda). RX com edema pulmonar alveolar. HD: emergência hipertensiva com edema agudo de pulmão cardiogênico.', 'O2, CPAP com PEEP 8, nitroglicerina EV em bomba (10 mcg/min, titular) com redução da PA em ~25% em 1 h, furosemida 80 mg EV. Melhora clínica em 40 min, SatO2 94% com cateter. Internação em UTI para observação e investigação.'),
  (1630, 483, 14, '2024-09-16 09:00', 'internacao', 'Seguimento na UTI', 142, 84, 84, 79.5, 'D2 de UTI, sem O2 suplementar, balanço negativo de 3,2 L com furosemida. PA 142x84 após transição para anlodipino e carvedilol. ECO: HVE concêntrica importante (septo 17 mm), FEVE 46%, disfunção diastólica grau III, IM leve. Troponina em queda (0,04). Cinecoronariografia sem lesões obstrutivas. Doppler de renais sem estenose. Creatinina 1,3, K 4,3. Causa do EAP: crise hipertensiva por interrupção de medicação, em cardiopatia hipertensiva avançada.', 'Alta da UTI para enfermaria. Iniciar enalapril 10 mg 12/12h e espironolactona 25 mg, manter carvedilol e anlodipino; furosemida 40 mg. Orientado a não interromper, assistência social para fornecer medicação. Alta em 3 dias. Retorno em 15 dias.'),
  (1631, 483, 11, '2024-10-08 10:20', 'retorno', 'Estou respirando bem, vim ver como estou', 128, 76, 68, 76.0, '3 semanas após o EAP. Dorme com 1 travesseiro, caminha 1 quarteirão sem parar. Estável em NYHA II, sem edema. PA 128x76, FC 68. Creatinina 1,4, K 4,9 após IECA + espironolactona. NT-proBNP 620. Conseguiu pegar todos os remédios na farmácia popular, a neta agora controla. Parou de fumar na internação e está há 3 semanas sem cigarro; diminuiu a cerveja.', 'Manter esquema. Controlar K e creatinina em 15 dias e a cada 3 meses. Plano de dieta com pouco sal. Considerar dapagliflozina no próximo retorno. Terapia de cessação do tabagismo com adesivo de nicotina. Retorno em 2 meses.');
