insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (483, '2024-10-08', 'melhorou', 'EAP hipertensivo por interrupção dos anti-hipertensivos, tratado na UTI. Três semanas depois, em NYHA II, PA 128x76, NT-proBNP 620, sem fumar e com acesso garantido aos remédios pela farmácia popular.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (484, 'Dayane Cristina Rodrigues Façanha', 'F', '1999-03-12', 'Rio Branco', 'AC', 'Técnica de enfermagem', 'Primigesta, 26 anos, gestação sem intercorrências até 34 semanas. IMC pré-gestacional 29. Sem HAS prévia. Trabalha em plantões noturnos. Mãe com pré-eclâmpsia na gestação da irmã.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1632, 484, 7, '2026-01-13 14:30', 'consulta', 'Pressão subiu no pré-natal', 148, 96, 84, 78.2, 'Gestante de 34 sem + 1 d, sem queixas, encaminhada da UBS com PA de 146x94 e 148x96 em duas aferições com 4 h de intervalo, e proteinúria de fita 1+. Sem cefaleia, escotomas, epigastralgia ou edema importante. Ao exame: BEG, edema discreto de pés, reflexos normais, BCF 140 bpm, AU 33 cm. PA 148x96 após repouso de 10 min. Exames: plaquetas 238 mil, creatinina 0,6, TGO 21, ácido úrico 5,1, proteína/creatinina 0,4 g/g. HD: pré-eclâmpsia sem sinais de gravidade.', 'Ambulatorial: iniciar nifedipino retard 20 mg 12/12h. Evitar IECA/BRA. Monitorização de PA domiciliar 2x/dia, USG com Doppler e perfil de líquido amniótico, cardiotocografia semanal. Retorno em 1 semana; sinais de alarme explicados.'),
  (1633, 484, 7, '2026-01-27 15:00', 'retorno', 'Sem queixas, vim pro controle', 140, 90, 80, 79.0, 'IG 36 sem + 1 d. PA em casa média 138x88, sem picos graves. Sem cefaleia ou dor epigástrica. Movimentos fetais normais. USG: feto no p48, líquido normal, Doppler umbilical e de cerebral média normais. Plaquetas 226 mil, TGO 24, creatinina 0,6, proteína/creatinina 0,5 g/g. Mantém quadro estável de pré-eclâmpsia sem critérios de gravidade, em uso de nifedipino. Plano de resolução com 37-38 semanas.', 'Manter nifedipino. Reavaliação com exames em 1 semana. Indução do trabalho de parto às 37 sem + 3 d se mantiver estável. Retornar imediatamente se cefaleia intensa, escotomas, dor epigástrica ou PA > 160x110.'),
  (1634, 484, 7, '2026-02-10 07:00', 'internacao', 'Internação para indução do parto', 144, 92, 86, 80.1, 'IG 37 sem + 6 d. PA 144x92, assintomática, exames laboratoriais estáveis (plaquetas 219 mil, TGO 26, creatinina 0,6). Cérvix favorável, Bishop 6; realizada indução com misoprostol e ocitocina; parto vaginal em 11 h, sem sulfato de magnésio (sem critérios de gravidade), RN feminino 3.040 g, Apgar 9/10, sem intercorrências. PA pós-parto 136x86, sem hemorragia, dequitação normal. Puérpera estável e amamentando.', 'Manter nifedipino por ora. Monitorizar PA no puerpério a cada 6 h por 48 h. Alta no 2º dia pós-parto com orientação de PA domiciliar. Retorno em 7-10 dias.'),
  (1635, 484, 7, '2026-03-25 14:00', 'retorno', 'Revisão do puerpério', 116, 74, 72, 69.5, '6 semanas pós-parto, amamentando exclusivamente, bebê ganhando peso bem. Assintomática. MRPA nas últimas 2 semanas com média 114x72 após suspensão do nifedipino, que ocorreu com 3 semanas pós-parto por PA < 120x80. Proteína/creatinina 0,1 g/g, plaquetas e função renal normais. Orientada sobre risco aumentado de HAS e de doença cardiovascular na vida: manter peso, atividade física, PA anual e informar em futuras gestações para uso de AAS desde 12 semanas.', 'Sem medicações. Contracepção: método sem estrogênio. Aferir PA anual e glicemia, perfil lipídico em 1 ano. Cartão de gestação com registro de pré-eclâmpsia. Alta do seguimento obstétrico; retorno cardiológico em 12 meses.');
