insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (484, '2026-03-25', 'melhorou', 'Pré-eclâmpsia sem sinais de gravidade, manejada com nifedipino e indução às 37 semanas, com parto vaginal e RN saudável. PA normalizada no puerpério sem medicação e proteinúria resolvida; orientada quanto ao risco cardiovascular futuro.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (485, 'Raul Bastos Menezes de Sá', 'M', '1952-11-22', 'Salvador', 'BA', 'Aposentado, ex-professor de matemática', 'HAS há 18 anos, dislipidemia, ex-tabagista (parou há 20 anos). Angina aos grandes esforços há 4 meses. Faz uso de AAS, losartana 50 mg e sinvastatina 20 mg. Pai com infarto aos 66 anos.', 'Alergia a AAS (broncoespasmo)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1636, 485, 2, '2022-04-05 08:30', 'consulta', 'Dor no peito quando subo a ladeira rápido', 136, 82, 74, 76.3, 'Pcte 69a, angina típica CCS II aos esforços moderados há 4 meses, alívio com repouso em 3 min, sem dor em repouso. Nega dispneia. Ao exame: BEG, RCR 2T BNF, sem sopros, pulsos normais. Ergometria: positiva em 7 METs, infra de 2 mm V4-V6 em estágio 3 com dor, recuperação em 4 min. Referia uso de AAS, mas cita broncoespasmo em ocasião prévia: orientado a suspender o AAS e usar clopidogrel. LDL 112. HD: DAC estável, angina CCS II com teste de risco intermediário.', 'Suspender AAS (alergia respiratória). Iniciar clopidogrel 75 mg/dia, atorvastatina 40 mg, metoprolol succinato 50 mg. Nitrato sublingual SN. Solicitar cintilografia e discussão para CATE. Retorno em 30 dias.'),
  (1637, 485, 10, '2022-05-31 09:00', 'retorno', 'Resultado do cateterismo', 128, 76, 58, 76.0, 'Cintilografia com isquemia leve (5% do VE) em parede inferior. CATE (acesso radial): DA com lesão de 40%, Cx sem lesões, CD com estenose de 70% no terço médio com FFR 0,86 (não funcionalmente significativa). FEVE 62%. Pouca angina atual, uma vez a cada 10 dias, em esforço intenso. Metoprolol bem tolerado, FC de repouso 58. Discutidas as opções: tratamento clínico otimizado versus angioplastia. Optado por tratamento clínico dado FFR não significativo e sintomas leves.', 'Manter tratamento clínico: clopidogrel, atorvastatina 80 mg, metoprolol, losartana, adicionar anlodipino 5 mg se angina persistir. MEV. Reabilitação cardíaca. Revisão em 3 meses; reavaliar ATC se angina limitante.'),
  (1638, 485, 2, '2023-01-17 08:40', 'retorno', 'Estou fazendo caminhada e quase sem dor', 124, 72, 60, 74.0, 'Quase 8 meses de tratamento clínico, concluiu reabilitação cardíaca e caminha 5 km 4x/semana. Angina somente em 2 episódios no período, em esforço máximo, aliviados com repouso. Ergométrico: 9,5 METs, sem infra de ST, FC máxima 124 sob BB. LDL 52 com atorvastatina 80 mg. Sem sangramentos, sem dispneia por clopidogrel. PA 124x72. Mantém dieta mediterrânea. Paciente satisfeito por ter evitado stent.', 'Manter clopidogrel 75 mg, atorvastatina 80 mg, metoprolol, losartana. Sem necessidade de nitrato de uso contínuo. Retorno em 6 meses; ergométrico anual. Orientar sinais de piora.');
