insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (485, '2023-01-17', 'estavel', 'DAC estável com lesão em CD sem significado funcional (FFR 0,86), tratada clinicamente com clopidogrel por alergia a AAS, estatina e betabloqueador. Reabilitação concluída, ergométrico de 9,5 METs sem isquemia e LDL de 52.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (486, 'Iracema Tavares Bittencourt', 'F', '1966-09-04', 'Macapá', 'AP', 'Feirante (venda de açaí e frutas)', 'HAS há 15 anos, cardiopatia hipertensiva dilatada com ICFEr diagnosticada há 1 ano. Obesidade, sem DM. Tabagismo pesado há décadas, parou há 3 anos. Usava losartana 50 mg e furosemida 40 mg quando lembrava. Divide a casa com três filhos e é a única que trabalha.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1639, 486, 11, '2021-10-12 09:50', 'consulta', 'Cansada e com a barriga inchada', 144, 90, 94, 88.4, 'Pcte 55a, ICFEr NYHA III, dispneia aos pequenos esforços, edema 3+/4+ até joelhos, ortopneia e distensão abdominal. Ao exame: estase jugular, estertores nas bases, hepatomegalia a 3 cm do RCD, B3. PA 144x90. ECO: FEVE 30%, DDVE 64 mm, IM funcional leve a moderada. NT-proBNP 4.200. Creatinina 1,0, K 4,3. HD: ICFEr hipertensiva descompensada por baixa adesão (custo e esquecimento).', 'Furosemida 80 mg/dia, espironolactona 25 mg, carvedilol 3,125 mg 12/12h e enalapril 10 mg 12/12h (disponível no SUS, em vez de sacubitril/valsartana por custo). Dapagliflozina 10 mg se disponível pelo programa. Orientações de sal e peso diário. Retorno em 15 dias.'),
  (1640, 486, 11, '2021-11-23 10:10', 'retorno', 'Melhorei, mas o remédio da pressão me dá tosse', 118, 74, 76, 79.6, 'Perdeu 8,8 kg, edema resolvido, NYHA II. Mas tosse seca persistente à noite desde o enalapril, que a faz acordar; chegou a pensar em parar. K 4,9, creatinina 1,2. PA 118x74. Entende a importância de seguir o tratamento. Troca por BRA indicada. Dapagliflozina ainda não disponível na UBS dela. Pediu para não precisar vir todo mês pelo gasto com transporte e com a perda de dias de feira.', 'Trocar enalapril por losartana 50 mg 12/12h (tosse por IECA). Manter furosemida 40 mg/dia, espironolactona 25 mg e carvedilol 6,25 mg 12/12h. Fornecer receita para 3 meses. Retorno em 3 meses com K e creatinina.'),
  (1641, 486, 11, '2022-03-08 10:30', 'retorno', 'Voltou o inchaço nas pernas', 150, 94, 92, 86.0, 'Retorna após 3,5 meses; ganhou 6,4 kg e tem edema 2+/4+, ortopneia e dispneia aos médios esforços. Tomou os remédios por 6 semanas e depois interrompeu ''porque acabaram e não tinha quem trouxesse'', a receita terminou antes do esperado. Confessa que também reduziu o carvedilol por sentir cansaço. PA 150x94, FC 92. NT-proBNP 3.100. Orientada de que o risco de nova internação é alto; paciente emocionada, fala em dificuldades financeiras e dois empregos temporários.', 'Reiniciar furosemida 40 mg 12/12h por 7 dias, depois 40 mg/dia, losartana 50 mg 12/12h, espironolactona 25 mg e carvedilol 3,125 mg 12/12h. Agentes de saúde para busca ativa mensal. Retorno em 30 dias.');
