insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (486, '2022-09-30', 'abandonou', 'ICFEr hipertensiva que melhorou no início, mas a paciente não retornou após março de 2022 nem atendeu à busca ativa da UBS. Custo, perda de dias de feira e falta de medicação foram as principais barreiras. Perda de seguimento com NT-proBNP elevado.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (487, 'Fábio Henrique Ostrowski', 'M', '1973-04-27', 'São Paulo', 'SP', 'Contador', 'HAS leve tratada com losartana 50 mg. Consumo alto de álcool em fins de semana (binge) e muito café. Dorme pouco em épocas de fechamento fiscal. Sem cardiopatia estrutural conhecida. Pai com FA aos 65 anos.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1642, 487, 4, '2025-01-14 08:30', 'consulta', 'Coração acelerado há três semanas', 138, 86, 118, 90.2, 'Pcte 51a, palpitações e cansaço desde um fim de semana de excesso de álcool, no fim do ano. Sem dor torácica nem síncope. Ao exame: RCI 2T, FC 118, sem sopros, pulmões limpos, sem edema. ECG: fibrilação atrial com resposta ventricular de 118 bpm. ECO: AE 44 mm, FEVE 58%, sem valvopatia. TSH 1,7, K 4,2, creatinina 0,9, Hb 15. CHA2DS2-VASc 1 (HAS). FA persistente com menos de 6 semanas, provável gatilho: álcool/estresse/sono ruim.', 'Iniciar anticoagulação com rivaroxabana 20 mg ao jantar por no mínimo 3 semanas antes de cardioversão elétrica eletiva. Metoprolol succinato 50 mg para controle da frequência. Abstinência de álcool e redução do café. Retorno em 3 semanas para agendar a CVE.'),
  (1643, 487, 4, '2025-02-18 07:30', 'internacao', 'Cardioversão elétrica eletiva', 134, 82, 104, 89.5, 'Após 5 semanas de anticoagulação regular (confirmada por contagem de comprimidos), sem perda de doses. Ainda em FA, FC 104 sob metoprolol. Jejum de 8 h. Sedação com propofol, CVE sincronizada de 150 J bifásica, reversão a ritmo sinusal na 1ª tentativa, FC 66. ECG pós-CVE com PR 168 ms. Sem queimaduras ou complicações. Alta em 4 h com orientação de manter o anticoagulante por no mínimo 4 semanas.', 'Manter rivaroxabana por pelo menos 4 semanas pós-CVE e avaliar necessidade posterior. Metoprolol 50 mg. Evitar álcool. Retorno em 30 dias com ECG e Holter.'),
  (1644, 487, 4, '2025-07-08 08:40', 'retorno', 'A palpitação voltou', 132, 84, 112, 91.0, 'Manteve ritmo sinusal por 4 meses e suspendeu a rivaroxabana em março. Há 10 dias, novas palpitações com cansaço, em episódio de bebida num casamento. ECG: FA, resposta ventricular 112. Holter prévio de 2 semanas atrás com FA paroxística de 6 horas. Segunda recorrência em 5 meses. Discutido com o paciente: controle de ritmo definitivo com ablação por cateter (isolamento das veias pulmonares), que ele prefere ao uso crônico de antiarrítmico. CHA2DS2-VASc 1: manter anticoagulação por conta da ablação.', 'Reiniciar rivaroxabana 20 mg. Manter metoprolol. Agendar ablação de FA por crioablação. Abstinência completa de álcool. Retorno após o procedimento.'),
  (1645, 487, 4, '2025-08-26 06:30', 'internacao', 'Ablação de fibrilação atrial', 128, 80, 74, 88.6, 'Angio-TC sem trombo em apêndice atrial, 4 veias pulmonares típicas. Ablação por crioenergia com isolamento de todas as veias pulmonares, confirmado por bloqueio de entrada e de saída. Reversão espontânea para sinusal durante o procedimento. Sem derrame pericárdico no ECO ao final, sem lesão do nervo frênico. Punções femorais sem hematoma. Alta no dia seguinte, ritmo sinusal, FC 74.', 'Manter rivaroxabana 20 mg por pelo menos 3 meses pós-ablação. Manter metoprolol por 3 meses e depois reavaliar. Evitar esforço pesado por 7 dias. Monitor de eventos por 30 dias; retorno em 3 meses com Holter de 7 dias.');
