insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (487, '2025-08-27', 'melhorou', 'FA persistente após cardioversão elétrica com recorrência em 5 meses, tratada com ablação por crioenergia e isolamento das veias pulmonares. Alta em ritmo sinusal, mantendo anticoagulação e sem álcool; aguarda reavaliação com Holter em 3 meses.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (488, 'Zacarias Rodrigues Cunha Dias', 'M', '1955-12-17', 'Tefé', 'AM', 'Aposentado, ex-barqueiro', 'Doença de Chagas diagnosticada há 12 anos, vivia em casa de palha às margens do Solimões. Cardiopatia chagásica com BRD + HBAE. HAS. Uso irregular de carvedilol 6,25 mg 12/12h e enalapril 10 mg 12/12h. Tabagista ocasional. Nega etilismo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1646, 488, 4, '2024-02-20 09:00', 'consulta', 'Apagões e tontura, desmaiei duas vezes', 150, 70, 34, 69.8, 'Pcte 68a, chagásico, com 2 síncopes em 2 semanas e fadiga progressiva. Bradicardia ao exame: pulso 34 bpm regular, ondas A em canhão no pescoço, RCR 2T, B1 variável, sem congestão. ECG: BAV total com escape ventricular a 34 bpm, QRS alargado (BRD + HBAE de base). ECO: FEVE 38%, VE dilatado (DDVE 62 mm), hipocinesia inferolateral, sem trombo. Hb 13,0, creatinina 1,0, K 4,5. HD: BAVT de causa chagásica com síncope; indicado marca-passo definitivo. Cardiopatia chagásica com disfunção sistólica.', 'Suspender carvedilol por BAVT sem estimulação. Internação imediata para implante de marca-passo definitivo. Manter enalapril 10 mg 12/12h. Não indicado tratamento etiológico (benznidazol) na cardiopatia crônica. Telemetria e pás transcutâneas.'),
  (1647, 488, 4, '2024-02-22 08:00', 'internacao', 'Implante de marca-passo', 140, 80, 36, 69.8, 'Implante de marca-passo dupla câmara via veia cefálica esquerda sob anestesia local, sem intercorrências. Eletrodo de ventrículo direito com fixação ativa no septo, limiar 0,7 V, onda R 9 mV. Átrio com onda P 2,8 mV. Estimulação sequencial a 60 bpm, FC 62 ao final. RX sem pneumotórax. Dada a FEVE de 38% e o BAVT dependente, a estimulação ventricular será praticamente contínua; programados parâmetros de resposta de frequência conservadores.', 'Antibioticoprofilaxia (cefazolina), repouso do braço e curativo. Alta em 24 h. Reiniciar betabloqueador em dose baixa após 1 semana com a estimulação garantida. Retorno em 15 dias para ferida e checagem do MP; depois iniciar otimização da IC.'),
  (1648, 488, 11, '2024-06-04 10:30', 'retorno', 'Estou bem, sem desmaiar', 118, 72, 64, 71.0, '3,5 meses após o implante de MP, sem síncopes nem tonturas, dispneia somente em esforço intenso (NYHA II). Ferida íntegra. Interrogação do MP: estimulação VD 98%, sem arritmias ventriculares sustentadas, bateria 10 anos. ECO: FEVE 40%, DDVE 62 mm. NT-proBNP 780. K 4,6, creatinina 1,1. Betabloqueador reintroduzido há 6 semanas com boa tolerância. Quer saber se vai poder voltar a fazer o barco do filho; orientado que sim, sem esforços extremos.', 'Otimizar IC chagásica: manter enalapril, carvedilol 6,25 mg 12/12h, adicionar espironolactona 25 mg e dapagliflozina 10 mg. Monitorar K e creatinina. Holter para detectar TV; se TVNS ou FEVE < 35%, reavaliar CDI. Retorno em 3 meses.');
