insert into exame (id_atendimento, nome, resultado) values
  (1649, 'ECG durante a taquicardia', 'Taquicardia irregular de QRS largo a 214 bpm, RR variáveis (FA pré-excitada)'),
  (1649, 'ECG pós-cardioversão', 'Ritmo sinusal 82 bpm, PR 96 ms, onda delta positiva em DII, V4-V6 (via lateral esquerda)'),
  (1650, 'Estudo eletrofisiológico', 'Via acessória lateral esquerda, PRE anterógrado 240 ms, FA pré-excitada com RR mínimo 210 ms; ablação bem-sucedida, sem recondução'),
  (1650, 'Ecocardiograma transtorácico', 'FEVE 63% (Simpson), sem cardiopatia estrutural'),
