insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (489, '2025-07-22', 'controlado', 'Síndrome de Wolff-Parkinson-White com FA pré-excitada tratada com cardioversão elétrica e ablação por radiofrequência da via acessória lateral esquerda. Sem recorrência, ergométrico normal e liberado para o esporte; familiares orientados a fazer ECG.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (490, 'Iolanda Maria Cardoso Pantoja', 'F', '1972-03-15', 'Belém', 'PA', 'Servidora pública (assistente administrativa)', 'Câncer de mama invasivo, carcinoma ductal HER2 positivo, estágio II, diagnosticado em fevereiro de 2024, com cirurgia conservadora e quimioterapia programada. HAS leve em uso de losartana 50 mg. Sem cardiopatia prévia. Nunca fumou. Mãe falecida de câncer de mama.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1652, 490, 11, '2024-03-05 14:00', 'consulta', 'Avaliação do coração antes da quimioterapia', 134, 82, 78, 71.0, 'Pcte 51a, encaminhada pela oncologia (cardio-oncologia) antes do esquema AC-T (doxorrubicina 60 mg/m² + ciclofosfamida por 4 ciclos, seguidos de paclitaxel) + trastuzumabe. Assintomática, NYHA I. Exame cardiovascular normal. ECG normal. ECO basal: FEVE 63%, strain longitudinal global (GLS) -20,5%, sem valvopatia. Troponina e NT-proBNP normais. Risco cardiovascular para cardiotoxicidade intermediário (HAS, idade > 50, antraciclina + trastuzumabe).', 'Liberada para quimioterapia. Monitorização com ECO com strain e troponina a cada 3 meses. Manter losartana 50 mg, controle rigoroso da PA. Iniciar atorvastatina 20 mg para possível cardioproteção (LDL 128). Retorno em 3 meses ou antes se sintomas.'),
  (1653, 490, 11, '2024-09-17 14:20', 'retorno', 'Cansaço maior depois das últimas sessões', 118, 74, 92, 68.5, 'Após 4 ciclos de AC (dose cumulativa de doxorrubicina 240 mg/m²) e 12 de paclitaxel + trastuzumabe, refere dispneia aos médios esforços e cansaço novo, sem edema. Exame: FC 92, B3 discreta, sem estase jugular. ECO: FEVE 49% (queda de 14 pontos), GLS -14,8% (queda relativa de 28%), troponina ultrassensível elevada (48 ng/L), NT-proBNP 710. Cardiotoxicidade (disfunção sistólica sintomática leve) por antraciclina e trastuzumabe.', 'Discutido com oncologia: interromper trastuzumabe temporariamente. Iniciar enalapril 5 mg 12/12h (trocando losartana) e carvedilol 3,125 mg 12/12h, com titulação gradual. Manter atorvastatina. ECO em 4 semanas. Retorno em 1 mês.'),
  (1654, 490, 11, '2024-12-10 14:00', 'retorno', 'Piorei do cansaço e já não consigo subir um lance de escada', 106, 66, 84, 69.8, 'Em NYHA II-III apesar de enalapril 10 mg 12/12h e carvedilol 6,25 mg 12/12h. Edema discreto de tornozelos, estertores de bases, B3. Tentativa de retomar trastuzumabe em novembro (ciclo único) levou a dispneia intensa; suspenso. ECO: FEVE 38%, GLS -11%, VE discretamente dilatado. NT-proBNP 1.480. Cardiotoxicidade grau moderado a grave, sem recuperação. Oncologia concorda em suspender definitivamente o trastuzumabe (completou 9 de 17 ciclos).', 'Otimizar IC: trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h após 36 h sem IECA; adicionar espironolactona 25 mg e dapagliflozina 10 mg; carvedilol para 12,5 mg 12/12h. Furosemida 20 mg/dia. Controle de K e creatinina em 1 semana. Retorno em 1 mês.'),
  (1655, 490, 11, '2025-06-17 14:30', 'retorno', 'Estou melhor, mas ainda me canso', 110, 68, 66, 67.0, 'Seis meses de terapia otimizada, NYHA II. Câncer em remissão por exames de imagem. Sem edema, caminha 20 min com pausa. Tolera sacubitril/valsartana 49/51 mg 12/12h; PA 110x68. K 4,7 e creatinina 0,9. ECO: FEVE 41%, GLS -12,5%. NT-proBNP 520. Melhorou pouco: dano miocárdico provavelmente permanente. Sem arritmias ao Holter. Em uso de tamoxifeno; discutido com oncologia, sem conflito cardiológico.', 'Manter os quatro pilares nas doses atuais, subir sacubitril/valsartana conforme PA. ECO a cada 6 meses. Reavaliar CDI se FEVE ≤ 35% após 3 meses de dose máxima tolerada. Acompanhar com cardio-oncologia anualmente.');
