insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (490, '2025-06-17', 'piorou', 'Cardiotoxicidade por antraciclina e trastuzumabe com queda da FEVE de 63% para 38%, sem recuperação completa (41%) e trastuzumabe suspenso antes do fim do esquema. Câncer de mama em remissão, mas ficou com ICFEr crônica em terapia otimizada.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (491, 'Aldo Bertolini Fusco', 'M', '1944-07-30', 'Santos', 'SP', 'Aposentado, ex-estivador', 'HAS há 30 anos, hiperplasia prostática e osteoartrose. Em uso de losartana + hidroclorotiazida 100/25 mg, anlodipino 10 mg e tamsulosina 0,4 mg. Duas quedas nos últimos 6 meses. Mora sozinho no 2º andar, sem elevador, viúvo.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1656, 491, 5, '2023-06-13 09:30', 'consulta', 'Caí de novo no banheiro, fiquei tonto', 164, 84, 70, 68.0, 'Pcte 78a, 2ª queda em 6 meses, ao levantar da cama e ir ao banheiro de madrugada, sem perda de consciência referida, sem trauma grave (hematoma em quadril esquerdo). PA deitado 164x84, após 3 min em pé 126x70, queda de 38 mmHg sistólica, com tontura e sem aumento da FC (70 para 74). Hipotensão ortostática grave associada a HAS supina. Ao exame: BEG, RCR 2T BNF, MV+ sem RA, marcha lenta, Timed Up and Go 16 s. Polifarmácia; tamsulosina e diurético contribuem. Sódio 134, creatinina 1,2.', 'Suspender hidroclorotiazida e reduzir carga anti-hipertensiva: manter losartana 50 mg/dia e anlodipino 5 mg. Tamsulosina à noite com cuidado. Orientações: levantar devagar, hidratar, meia elástica de compressão média, elevar cabeceira. Fisioterapia, avaliação de domicílio. Meta de PA flexível (< 140/90 sentado). Retorno em 4 semanas.'),
  (1657, 491, 5, '2023-07-18 09:50', 'retorno', 'Não caí mais, mas sinto a cabeça leve às vezes', 148, 80, 68, 68.4, 'Sem novas quedas. PA deitado 148x80, em pé 3 min 138x76 (queda de 10), sem tontura. Dorme com a cabeceira elevada e usa meia de compressão. Na MRPA, picos de 160x90 pela manhã e sem hipotensão à tarde. Sódio 137, creatinina 1,1. Aumentou a ingestão de água e sal moderado após orientação; fisioterapia 2x/semana, TUG 12 s. Filha instalou barras no banheiro e sensor de luz no corredor.', 'Manter losartana 50 mg e anlodipino 5 mg. Meta de PA sentada < 140/90 sem hipotensão postural, individualizada pela fragilidade. Continuar fisioterapia. Evitar medicações sedativas. Retorno em 3 meses.'),
  (1658, 491, 5, '2024-01-23 10:00', 'retorno', 'Vim fazer a revisão, estou bem', 142, 78, 66, 69.0, 'Sete meses depois, sem quedas desde junho. Caminha 20 min com o andador de manhã. PA 142x78 deitado e 134x74 em pé, sem sintomas ortostáticos. Creatinina 1,1, sódio 138. Denosumabe iniciado pela ortopedia por osteoporose. Aceitou que PA ligeiramente acima de 130/80 é preferível ao risco de nova queda e fratura de fêmur.', 'Manter losartana 50 mg e anlodipino 5 mg. Meta individualizada, evitar PA sentada < 130. Vitamina D, fisioterapia contínua. Retorno em 4 meses; MRPA mensal por cuidador.');
