insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (491, '2024-01-23', 'estavel', 'Idoso frágil com hipotensão ortostática e quedas. Retirado o diurético e reduzidos anti-hipertensivos, sem novas quedas em 7 meses e queda postural de apenas 8 mmHg. Segue com meta de PA individualizada e fisioterapia.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (492, 'Francisca Ivone Brasil de Oliveira', 'F', '1949-02-20', 'Boa Vista', 'RR', 'Aposentada, ex-lavadeira', 'IAM antigo em 2016, sem revascularização. ICFEr isquêmica com FEVE 34%. HAS e DM2 com metformina. Ex-tabagista. Vive com a filha e dois netos, em bairro afastado. Usa AAS, enalapril, carvedilol e furosemida.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1659, 492, 11, '2023-02-07 10:00', 'consulta', 'Falta de ar quando ando dentro de casa', 112, 70, 78, 64.2, 'Pcte 73a, ICFEr isquêmica NYHA III, dispneia aos pequenos esforços e ortopneia leve. Ao exame: sem estase jugular, estertores nas bases, edema 1+/4+. ECO: FEVE 34%, hipocinesia inferior e anterior, IM leve. NT-proBNP 2.600. Creatinina 1,2, K 4,6, HbA1c 7,4%. Em uso de IECA e BB, sem espironolactona e sem iSGLT2. HD: ICFEr com terapia subótima. Boa adesão, mas custo dos remédios é uma preocupação da filha.', 'Trocar enalapril por sacubitril/valsartana 24/26 mg 12/12h (após 36 h de pausa do IECA). Adicionar espironolactona 25 mg e dapagliflozina 10 mg. Manter carvedilol 6,25 mg 12/12h. K e creatinina em 1 semana. Solicitado ao CAF para os medicamentos de alto custo. Retorno em 1 mês.'),
  (1660, 492, 6, '2023-05-19 23:40', 'pronto_socorro', 'Muito cansada, febre e tosse', 92, 58, 108, 67.0, 'Pcte 74a, febre de 38,6 °C, tosse com escarro amarelado há 4 dias e piora da falta de ar nas últimas 24 h. Ao exame: taquipneica, SatO2 90% AA, estertores em base direita, edema 2+/4+, PA 92x58. RX: consolidação em lobo inferior direito e congestão. Leucocitose 17.800, PCR 180, lactato 2,4, creatinina 1,7 (de 1,2), K 5,3. HD: pneumonia comunitária com descompensação de ICFEr e lesão renal aguda; suspender espironolactona, dapagliflozina e IECA/ARNI temporariamente.', 'Internar. Antibiótico (ceftriaxona + azitromicina), O2 suplementar, diurético titulado. Suspender sacubitril/valsartana, espironolactona, dapagliflozina e metformina por IRA/hipotensão. Manter carvedilol em dose reduzida (3,125 mg) e reavaliar diariamente.'),
  (1661, 492, 11, '2023-07-04 10:20', 'retorno', 'Alta do hospital, vim reiniciar os remédios', 108, 66, 74, 62.8, 'Após 8 dias de internação com pneumonia tratada, alta há 3 semanas. Hoje sem febre, NYHA II-III, sem edema. Creatinina normalizou para 1,2, K 4,7. Os medicamentos suspensos ainda não foram retomados. PA 108x66. NT-proBNP 1.400. Vacinas contra influenza e pneumococo feitas. Filha ansiosa; esclarecido que a recuperação é possível.', 'Reintroduzir de forma escalonada: sacubitril/valsartana 24/26 mg 12/12h agora; dapagliflozina 10 mg e espironolactona 12,5 mg na próxima semana com checagem de K/creatinina. Carvedilol 6,25 mg 12/12h. Sinais de alerta (febre, vômitos, diarreia): suspender iSGLT2/diurético e procurar o PS. Retorno em 1 mês.'),
  (1662, 492, 11, '2024-01-16 10:00', 'retorno', 'Estou bem, ando até a padaria', 114, 68, 64, 62.0, '6 meses após reintrodução gradual dos 4 pilares, NYHA II, sem internações. Anda 500 m até a padaria sem parar. Sem edema, estertores ausentes. Creatinina 1,2, K 4,8, NT-proBNP 520. ECO: FEVE 40%, melhora da contratilidade inferior. HbA1c 6,8%. Metformina reiniciada em dose reduzida de 500 mg 12/12h pela TFGe de 44. Paciente grata, a filha ajuda com a caixa semanal de remédios.', 'Manter sacubitril/valsartana, carvedilol, espironolactona 25 mg, dapagliflozina e furosemida. Metformina 500 mg 12/12h. Vacinas anuais. Monitorar K/creatinina a cada 3-4 meses. Retorno em 4 meses.');
