insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (492, '2024-01-16', 'melhorou', 'ICFEr isquêmica com terapia subótima, que teve pneumonia e IRA em maio de 2023. Reintrodução escalonada dos quatro pilares levou a NYHA II, NT-proBNP de 2.600 para 520 e FEVE de 34% para 40%.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (493, 'Laércio Marques Tupinambá', 'M', '1967-10-11', 'Porto Velho', 'RO', 'Mestre de obras', 'HAS há 9 anos, obesidade e etilismo de fim de semana. Em tratamento com losartana 100 mg, anlodipino 10 mg e hidroclorotiazida 25 mg, encaminhado como hipertenso resistente. Toma os medicamentos ''quando lembra'', às vezes no meio do dia ou só um deles.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1663, 493, 1, '2024-07-02 08:40', 'consulta', 'Médico disse que minha pressão é resistente', 178, 108, 82, 112.0, 'Pcte 56a, encaminhado com PA 170-180x100-110 em 3 fármacos. O braço mede 38 cm de circunferência e foi usado manguito padrão (de adulto médio), que superestima a PA. Com manguito largo adequado (obeso), PA 156x94. Conferido com ele: toma o losartana de manhã, mas esquece do anlodipino e da hidroclorotiazida em 3-4 dias por semana, e bebe 12-15 doses de cerveja nos fins de semana. Creatinina 1,0, K 4,0. HD: suspeita de pseudorresistência por técnica de medida inadequada e baixa adesão.', 'Reeducação sobre a medida correta (manguito adequado). Reorganizar para dose única pela manhã: losartana 100 mg + hidroclorotiazida 25 mg em comprimido único e anlodipino 10 mg. Caixa de comprimidos. Reduzir álcool. MAPA com manguito apropriado e MRPA em 3 semanas. Retorno em 4 semanas.'),
  (1664, 493, 1, '2024-08-20 08:30', 'retorno', 'Trouxe a MAPA e o diário', 138, 86, 76, 109.5, 'Com tudo no mesmo horário, a PA caiu. MAPA com manguito grande: média 24h 132x82, vigília 136x85, sono 122x72. MRPA 134x84. Adesão agora quase completa (esqueceu 2 doses no mês). Perdeu 2,5 kg. Sem edema de MMII, creatinina 1,1, K 3,9. Resistência descartada: era pseudorresistência por manguito e má adesão. Fica na meta apenas com a rotina simplificada, a PA ainda está um pouco acima de 130/80.', 'Manter as medicações em horário único. Reforçar redução de peso e álcool. Retorno em 3 meses com MRPA. Se a PA continuar > 130/80, aumentar a combinação; não indicada espironolactona neste momento.'),
  (1665, 493, 1, '2024-12-03 08:50', 'retorno', 'Pressão boa em casa', 124, 78, 72, 104.0, 'Quatro meses depois, perdeu 8 kg no total. Caminha e reduziu a cerveja a 3-4 doses no fim de semana. PA em consultório com manguito adequado 124x78 e MRPA média 122x76. Adesão boa, usa lembrete no celular. Sem edema, creatinina 1,0, K 4,1, glicemia de jejum 108. Entendeu a diferença entre medir com o manguito certo e medir ''no chute'' em outros serviços, dizia que levaria o manguito próprio para a empresa.', 'Manter losartana/hidroclorotiazida 100/25 mg e anlodipino 10 mg. Meta atingida. Pedir glicemia e HbA1c. Retorno em 6 meses; MRPA mensal.');
