insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (493, '2024-12-03', 'controlado', 'Falsa hipertensão resistente: o manguito padrão superestimava a PA e a adesão era baixa. Com manguito adequado, rotina simplificada e perda de 8 kg, a PA ficou em 124x78 com os mesmos três fármacos, sem precisar de espironolactona.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (494, 'Terezinha Paiva Montenegro Lima', 'F', '1960-04-16', 'Fortaleza', 'CE', 'Costureira', 'HAS há 20 anos com controle irregular, usa anlodipino 5 mg e hidroclorotiazida 25 mg. Obesidade grau I. Sedentária. Mãe com insuficiência cardíaca. Cansaço progressivo aos esforços nos últimos 8 meses.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1666, 494, 2, '2022-10-04 10:30', 'consulta', 'Cansaço ao subir escada e coração apertado', 158, 94, 82, 79.0, 'Pcte 62a, dispneia aos médios esforços e cansaço progressivo, sem dor torácica, sem edema, sem ortopneia. Ao exame: RCR 2T, B4, sem sopros, MV+ sem RA, PA 158x94. ECG: SVE com strain. ECO: HVE concêntrica (septo 15 mm, parede posterior 14 mm), massa do VE aumentada (índice 138 g/m²), FEVE 64%, disfunção diastólica grau II, AE 42 mm. NT-proBNP 410. Diagnóstico: cardiopatia hipertensiva com HVE importante. Descartar amiloidose cardíaca pelo grau de hipertrofia.', 'Iniciar losartana 50 mg 12/12h, manter anlodipino 5 mg e hidroclorotiazida 25 mg. Solicitar eletroforese e imunofixação de proteínas séricas/urinárias e cadeias leves. Ressonância cardíaca. Meta de PA < 130/80 e redução de sal. Retorno em 6 semanas.'),
  (1667, 494, 2, '2022-11-15 10:00', 'retorno', 'Resultado dos exames', 142, 86, 76, 78.0, 'Eletroforese de proteínas e imunofixação sem componente monoclonal, cadeias leves kappa/lambda com razão normal. RM cardíaca: HVE concêntrica simétrica (massa 128 g/m²), sem realce tardio, T1 nativo normal, volume extracelular normal: sem amiloidose ou outra infiltração. Cardiopatia hipertensiva pura. PA 142x86, MRPA 138x84. Creatinina 0,9, K 4,0. Paciente aliviada por não ser doença rara.', 'Intensificar a terapia anti-hipertensiva: aumentar losartana para 100 mg/dia em dose única, manter anlodipino 5 mg e hidroclorotiazida 25 mg. Reduzir sódio e peso. Repetir ECO em 6 meses para avaliar regressão da massa. Retorno em 2 meses.'),
  (1668, 494, 2, '2023-06-20 10:20', 'retorno', 'Estou subindo a escada sem parar', 124, 76, 68, 73.2, 'Oito meses de controle estrito da PA. Perdeu 5,8 kg, caminha 40 min 4x/semana e cozinha com menos sal. Sem dispneia, sem edema, NYHA I. MRPA média 122x74. ECO de controle: septo 12 mm, parede posterior 11 mm, massa indexada 104 g/m² (regressão de 24%), FEVE 66%, relaxamento melhor (E/e'' 10). NT-proBNP 140. K 4,2, creatinina 0,9. Regressão de HVE confirma o benefício do controle pressórico.', 'Manter losartana 100 mg, anlodipino 5 mg e hidroclorotiazida 25 mg. ECO anual. Seguir MEV. Retorno em 6 meses.');
