insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (494, '2023-06-20', 'controlado', 'Cardiopatia hipertensiva com HVE importante, amiloidose descartada por RM e imunofixação. Com PA controlada (MRPA 122x74) e perda de 5,8 kg, a massa do VE regrediu 24% e ela ficou assintomática.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (495, 'Elenilson Gomes de Souza', 'M', '1967-02-14', 'Coari', 'AM', 'Operador de máquinas em base de petróleo', 'Tabagista de 30 maços-ano, hipertensão leve e dislipidemia sem tratamento. Faz trabalho em turnos de 14 dias embarcado, distante de hospitais. Pai falecido de infarto aos 54 anos. Sem diagnóstico de DM.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1669, 495, 6, '2025-04-26 05:10', 'pronto_socorro', 'Dor forte no peito, sudorese, acordei assim', 104, 64, 52, 86.0, 'Pcte 58a, dor retroesternal intensa há 1h30 com sudorese fria e náuseas, de início ao acordar. Ao exame: pálido, sudoreico, bradicárdico, PA 104x64, pulmões limpos, sem sinais de IC. ECG: supradesnivelamento de ST de 3 mm em DII, DIII, aVF, com infra recíproco em DI e aVL e BAV de 1º grau; V4R sem supra. Troponina 1,8 ng/mL. HD: IAMCSST de parede inferior (Killip I). Distância do centro de hemodinâmica: > 5 h por barco e avião, sem hemodinâmica disponível em Coari.', 'AAS 300 mg, clopidogrel 300 mg, enoxaparina 30 mg EV + 1 mg/kg SC, tenecteplase em dose ajustada ao peso (ausência de contraindicações), atorvastatina 80 mg. Monitorização, atropina SN. Transferência por UTI aérea para Manaus para angiografia em 3-24 h (estratégia farmacoinvasiva).'),
  (1670, 495, 10, '2025-04-26 17:30', 'internacao', 'Angiografia após trombólise', 118, 72, 64, 86.0, 'Chegou a Manaus 8 h pós-trombólise, sem dor há 6 h, resolução de 80% do supradesnível de ST, critério de reperfusão clínica. CATE: CD ocluída parcialmente no segmento proximal (95% com trombo residual), DA e Cx com lesões moderadas de 50%. ATC com stent farmacológico 3,5x28 mm na CD, fluxo TIMI 3. FEVE 50%, hipocinesia inferior. Sem sangramentos ou arritmias. Transferido a enfermaria no 2º dia, alta no 4º dia.', 'AAS 100 mg + clopidogrel 75 mg por 12 meses (ticagrelor evitado pós-fibrinolítico em fase precoce). Atorvastatina 80 mg, metoprolol 25 mg, enalapril 5 mg 12/12h. Cessação do tabagismo com vareniclina. Reabilitação cardíaca. Retorno em 30 dias.'),
  (1671, 495, 1, '2025-06-10 09:00', 'retorno', 'Sem dor, queria voltar ao trabalho embarcado', 118, 74, 60, 83.4, '6 semanas pós-IAM inferior. Sem angina, sem dispneia, caminha 4 km por dia. Parou de fumar há 6 semanas com vareniclina, ''não coloquei um cigarro na boca''. ECO: FEVE 54%, hipocinesia inferior discreta. LDL 62, glicemia 99, K 4,5, creatinina 1,0. Sem sangramentos. Quer voltar ao trabalho embarcado; avaliação: ergométrico sem isquemia a 10 METs. A distância de acesso a hemodinâmica preocupa, orientado a levar AAS e plano escrito de emergência.', 'Liberado para o trabalho com restrição de esforço nos 2 primeiros meses e plano de emergência. Manter DAPT por 12 meses, atorvastatina 80 mg, metoprolol, enalapril. Reabilitação domiciliar. Retorno em 3 meses.');
