insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (495, '2025-06-10', 'melhorou', 'IAMCSST inferior em localidade sem hemodinâmica, tratado com trombólise e transferência para ATC com stent na CD (estratégia farmacoinvasiva). Seis semanas depois, FEVE 54%, sem tabaco, ergométrico de 10 METs e retorno ao trabalho.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (496, 'Ivanildo Tonini Zanotti', 'M', '1959-05-05', 'Vitória', 'ES', 'Comerciante (bar)', 'Angina aos esforços há 6 meses, HAS e DM2 sem tratamento regular, tabagista ativo (35 maços-ano). Dono de bar, trabalha à noite, consumo de álcool diário. Irmão com stent. Acredita que ''remédio demais faz mal''.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1672, 496, 2, '2021-09-14 11:00', 'consulta', 'Dor no peito quando carrego caixa de cerveja', 156, 94, 80, 95.0, 'Pcte 62a, angina CCS II-III, aperto retroesternal em esforço moderado, aliviado em 5 min com repouso. Sem dor em repouso. Ao exame: RCR 2T BNF, B4, sem sopros, sem edema. PA 156x94. ECG: ritmo sinusal, sem alterações. Ergométrico positivo para isquemia em 5 METs com infra de ST de 2,5 mm V4-V6. Glicemia 168, HbA1c 8,6%, LDL 158. HD: DAC provável com angina CCS II-III, alto risco isquêmico.', 'Iniciar AAS 100 mg, atorvastatina 80 mg, metoprolol succinato 50 mg, losartana 50 mg, metformina 850 mg 12/12h. Nitrato SL SN. Agendar cateterismo. Orientado sobre parar de fumar e beber. Retorno após o CATE.'),
  (1673, 496, 10, '2021-10-05 07:30', 'internacao', 'Cateterismo e angioplastia', 140, 86, 66, 94.5, 'CATE radial direito: DA com lesão de 90% no terço proximal, Cx 50% e CD 40%; FEVE 58%. ATC com stent farmacológico 3,5x24 mm na DA proximal, TIMI 3 final, sem complicações. Alta no dia seguinte, sem dor. Orientado que o stent exige DAPT por pelo menos 6 meses (12 se possível) e que a interrupção precoce de clopidogrel aumenta o risco de trombose do stent e infarto.', 'AAS 100 mg + clopidogrel 75 mg por 6-12 meses. Manter atorvastatina 80 mg, metoprolol, losartana, metformina. Reabilitação cardíaca e abandono do tabagismo. Retorno em 6 semanas.'),
  (1674, 496, 2, '2021-11-16 11:30', 'retorno', 'Estou bem, não preciso mais de tanto remédio', 138, 84, 64, 94.0, '6 semanas pós-ATC, sem angina e sem dor. Voltou a trabalhar no bar, ainda fuma 10 cigarros/dia e bebe cerveja todos os dias. Diz que ''depois do stent a gente tá curado'' e que só vai tomar o remédio ''até acabar a caixa''. Já reduziu por conta própria atorvastatina e metoprolol por sentir cansaço. PA 138x84. Orientado novamente sobre risco de trombose do stent com a interrupção do clopidogrel e o papel das estatinas. Pouca receptividade; promete voltar.', 'Manter AAS, clopidogrel e atorvastatina; receita para 4 meses. Reforçar adesão, cessação do tabagismo (vareniclina oferecida e recusada) e controle do diabetes. Reavaliar em 3 meses com perfil lipídico e glicemia. Retorno em 3 meses.');
insert into diagnostico (id_atendimento, cid, descricao) values
