insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (496, '2022-09-30', 'abandonou', 'Após angioplastia com stent, o paciente achou que estava curado, reduziu medicações por conta própria e não retornou ao fim da receita de 4 meses. Não foi localizado nas tentativas de contato. Última PA 138x84, tabagismo ativo.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (497, 'Severino Raimundo Ferraz Gaspar', 'M', '1938-01-22', 'Bragança', 'PA', 'Aposentado, ex-pescador', 'IAM há 14 anos sem revascularização, evoluindo com ICFEr isquêmica (FEVE 25%), DRC estágio 3b e FA permanente. HAS antiga. Mora com a esposa idosa e um filho. Toma furosemida, carvedilol, espironolactona, enalapril e varfarina com INR mal controlado por dificuldade de acesso.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1675, 497, 11, '2022-12-06 09:30', 'consulta', 'Muito cansado, não consigo fazer nada', 98, 60, 88, 58.0, 'Pcte 84a, ICFEr avançada NYHA III-IV, dispneia a pequenos esforços e ortopneia, edema 2+/4+, ascite leve. Ao exame: caquexia cardíaca discreta, estase jugular a 45°, estertores bibasais, RCI, B3. PA 98x60, FC 88. ECO: FEVE 25%, VE dilatado, IM moderada, PSAP 52. NT-proBNP 8.900. Creatinina 1,9 (TFGe 32), K 5,1, Na 130. INR 1,6 (alvo 2-3). Limitação de doses pelas PA baixa e DRC. HD: ICFEr isquêmica avançada, refratária ao tratamento clínico tolerável.', 'Ajustar furosemida 80 mg/dia, suspender espironolactona (K 5,1), manter carvedilol 3,125 mg 12/12h e enalapril 2,5 mg 12/12h. Varfarina com INR semanal na UBS. Conversa franca com paciente e família sobre prognóstico e metas de cuidado; encaminhado à equipe de cuidados paliativos.'),
  (1676, 497, 6, '2023-03-04 02:50', 'pronto_socorro', 'Não consigo respirar, acordei sufocado', 90, 54, 112, 62.5, 'Pcte 85a, dispneia grave e ortopneia, edema generalizado, oligúria. SatO2 84% AA, FR 30, extremidades frias, perfusão lentificada, PA 90x54, FC 112 em FA. Estertores até ápices, anasarca. Creatinina 2,6, K 5,4, lactato 3,0, NT-proBNP 14.000. Descompensação de ICFEr com baixo débito (perfil C frio e úmido). A família conta que estava com tosse e pouca urina há uma semana. Decisão compartilhada: paciente e esposa optam por tratamento de suporte sem intubação.', 'Internação em UTI, O2 por máscara/VNI, furosemida EV em bolus e infusão, dobutamina em dose baixa como ponte, sem intubação nem diálise (decisão do paciente e da família). Manter sedação leve e analgesia se desconforto. Cuidados paliativos acompanhando.'),
  (1677, 497, 14, '2023-03-12 10:00', 'internacao', 'Seguimento na UTI', 96, 58, 96, 58.4, 'D9 de internação. Melhorou da congestão com balanço negativo de 6 L; dobutamina suspensa no D5, mas com recidiva de dispneia ao reduzir. Creatinina 2,2 (basal 1,9), K 5,0. Dependência de baixas doses de inotrópico para manter perfusão. Sem condições de transplante ou dispositivos pela idade e comorbidades. Paciente consciente e lúcido, pede para ir para casa. Família preparada. Estabelecido plano de cuidados paliativos domiciliares.', 'Alta hospitalar com cuidados paliativos domiciliares: furosemida via oral, morfina em baixa dose se dispneia, ansiolítico SN. Suspender varfarina por risco de sangramento e decisão compartilhada. Visita da equipe de saúde da família semanal.');
