insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (497, '2023-04-19', 'obito', 'Faleceu em casa, em cuidados paliativos domiciliares, por insuficiência cardíaca terminal (ICFEr isquêmica avançada) com baixo débito, cercado pela família, sem sofrimento intenso. Havia declinado intubação e diálise.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (498, 'Rosimeire Sales Fontenele', 'F', '1963-11-08', 'Natal', 'RN', 'Professora de ensino médio', 'HAS há 12 anos em uso de losartana 50 mg e anlodipino 5 mg. Hipotireoidismo tratado. Corre 3x/semana. Sem cardiopatia estrutural prévia. Sem tabagismo e com consumo mínimo de álcool.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1678, 498, 4, '2025-02-11 16:00', 'consulta', 'Coração batendo a 150 mesmo parada', 134, 82, 150, 62.5, 'Pcte 61a, cansaço e palpitações regulares há 12 dias, sem síncope ou dor. FC fixa em 150 bpm, regular. Ao exame: RCR 2T BNF, sem sopros, PA 134x82. ECG: flutter atrial típico (ondas F em dente de serra negativas em DII, DIII, aVF) com condução 2:1, FC ventricular 150. ECO: FEVE 58%, AE 40 mm, sem trombo visível, sem valvopatia. TSH 2,3. CHA2DS2-VASc 2 (HAS e sexo feminino). Indicado anticoagulante e controle de frequência.', 'Iniciar apixabana 5 mg 12/12h, metoprolol succinato 50 mg para controle de FC. Programar cardioversão elétrica ou ablação do istmo cavotricuspídeo, que é curativa em > 95% dos casos de flutter típico. Retorno em 3 semanas.'),
  (1679, 498, 4, '2025-03-25 07:00', 'internacao', 'Ablação de flutter atrial', 128, 78, 110, 62.0, 'Após 6 semanas de apixabana regular, persiste flutter com FC 110 sob metoprolol. Estudo eletrofisiológico: flutter dependente do istmo cavotricuspídeo, sentido anti-horário. Ablação por radiofrequência com linha completa do istmo, com reversão a ritmo sinusal durante a aplicação e bloqueio bidirecional confirmado (duplo potencial e diferencial de 150 ms). Sem complicações, punção femoral sem hematoma. Alta em 24 h em ritmo sinusal 64 bpm.', 'Manter apixabana por no mínimo 2 meses, depois reavaliar. Suspender metoprolol em 2 semanas se sem sintomas. Evitar esforço extremo por 1 semana. Retorno em 45 dias com ECG.'),
  (1680, 498, 4, '2025-05-13 16:30', 'retorno', 'Voltei a correr e estou ótima', 122, 74, 62, 62.8, 'Seis semanas após ablação, sem palpitações, voltou a correr 5 km sem sintomas. ECG: ritmo sinusal 62 bpm, PR 164 ms. Holter de 7 dias: sem flutter nem FA, extrassístoles atriais raras. Sem sangramentos com apixabana. Hb 13,6, creatinina 0,8. Sobre anticoagulação: CHA2DS2-VASc 2 (HAS, sexo feminino) com risco moderado; discutido com a paciente. Optou por seguir o anticoagulante por ora, com nova decisão após um ano sem recorrência.', 'Manter apixabana 5 mg 12/12h até reavaliação em 6 meses com novo Holter. Manter losartana 50 mg e anlodipino 5 mg. Retorno em 6 meses. Se palpitações, ECG imediato.');
