insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (498, '2025-05-13', 'controlado', 'Flutter atrial típico tratado com apixabana e ablação por radiofrequência do istmo cavotricuspídeo, com bloqueio bidirecional. Seis semanas depois em ritmo sinusal, Holter de 7 dias sem recorrência e de volta às corridas.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (499, 'Marilene Cruz dos Santos Brito', 'F', '1978-03-02', 'Macapá', 'AP', 'Cabeleireira', 'Febre reumática na infância com cardite, sem profilaxia secundária regular com penicilina benzatina. Dispneia progressiva aos esforços nos últimos 2 anos, palpitações ocasionais. Duas gestações com cesáreas. Sem HAS. Em uso de furosemida 20 mg quando sente inchaço.', 'Nega alergias medicamentosas');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1681, 499, 1, '2024-05-14 10:30', 'consulta', 'Falta de ar ao subir a rua e coração disparado', 118, 70, 108, 58.0, 'Pcte 46a, dispneia NYHA II-III, piora com esforços e episódios de palpitação. Ao exame: ritmo irregular, B1 hiperfonética, estalido de abertura mitral e ruflar diastólico em foco mitral com reforço pré-sistólico ausente. ECG: FA com FC 108. ECO: estenose mitral reumática grave, área valvar 1,0 cm² (PHT), gradiente médio 12 mmHg, AE 56 mm, sem trombo, Wilkins 7, IM leve, PSAP 48. Em FA: anticoagulação com varfarina (DOAC contraindicado em EM moderada/grave).', 'Iniciar varfarina 5 mg com alvo de INR 2-3 (enoxaparina de ponte até INR terapêutico), metoprolol succinato 50 mg para controle de FC e furosemida 20 mg. Penicilina benzatina 1.200.000 UI IM a cada 21 dias. Indicação de valvoplastia mitral percutânea por balão. Retorno em 3 semanas.'),
  (1682, 499, 10, '2024-07-08 07:30', 'internacao', 'Valvoplastia mitral percutânea', 120, 72, 84, 57.5, 'INR 2,4 estável há 4 semanas. ETE pré-procedimento sem trombo em apêndice atrial; septo interatrial bom, Wilkins 7, sem IM moderada/grave. Valvoplastia por balão (Inoue 26 mm), com punção transeptal, ganho de área valvar de 1,0 para 1,9 cm², gradiente caiu para 5 mmHg, IM leve sem piora, sem derrame pericárdico. Alta em 48 h, sem dispneia em repouso, FC 84 em FA.', 'Manter varfarina (FA persistente e AE dilatado), metoprolol e penicilina benzatina. Controle de INR mensal. ECO em 1 mês. Retorno em 8 semanas.'),
  (1683, 499, 1, '2024-09-17 10:00', 'retorno', 'Estou conseguindo trabalhar o dia todo sem cansaço', 116, 68, 74, 59.0, 'Dois meses pós-valvoplastia, NYHA I, trabalha de pé o dia todo no salão sem dispneia. FC 74 em FA controlada. ECO: AVM 1,8 cm², gradiente médio 6 mmHg, IM leve, PSAP 32. INR em 2,6, 2,2 e 2,8 nos últimos meses (controle satisfatório). Sem sangramentos. Mantém as injeções de penicilina benzatina a cada 3 semanas na UBS, relata que a injeção é dolorosa mas entendeu a importância. Hb 12,9.', 'Manter varfarina (INR 2-3), metoprolol, penicilina benzatina. Suspender furosemida. ECO anual. Orientar sobre planejamento familiar (varfarina é teratogênica) e profilaxia de endocardite em procedimentos dentários. Retorno em 6 meses.');
