insert into desfecho (id_paciente, data_desfecho, situacao, descricao) values
  (499, '2024-09-17', 'melhorou', 'Estenose mitral reumática grave com FA, tratada com valvoplastia por balão (área de 1,0 para 1,9 cm²). Em NYHA I dois meses depois, em uso de varfarina com INR na faixa e profilaxia secundária com penicilina benzatina.');
insert into paciente (id_paciente, nome, sexo, data_nascimento, cidade, uf, profissao, antecedentes, alergias) values
  (500, 'Caio Nascimento Vasconcelos', 'M', '1986-09-12', 'Goiânia', 'GO', 'Analista de logística', 'Prolapso de valva mitral com sopro conhecido, sem acompanhamento. Procedimento odontológico (extração) há 5 semanas, sem profilaxia. Sem comorbidades. Não usa drogas injetáveis. Não fuma.', 'Alergia a penicilina (urticária na infância)');
insert into atendimento (id_atendimento, id_paciente, id_medico, data_atendimento, tipo, queixa_principal, pressao_sistolica, pressao_diastolica, frequencia_cardiaca, peso_kg, evolucao, conduta) values
  (1684, 500, 6, '2024-08-05 20:10', 'pronto_socorro', 'Febre há três semanas e muito cansaço', 110, 62, 104, 68.0, 'Pcte 37a, febre vespertina de 38-39 °C há 3 semanas, calafrios, sudorese noturna, perda de 4 kg, fadiga e dor articular. Ao exame: febril, pálido, sopro holossistólico 3+/6+ em foco mitral (já presente, mas mais intenso), lesões petequiais em conjuntiva e 2 nódulos de Osler em polpas digitais, baço palpável. Hb 10,1, leucócitos 12.400, PCR 140, VHS 88. ECO transtorácico: vegetação móvel de 11 mm em folheto anterior da valva mitral, IM moderada. 3 hemoculturas colhidas. HD: endocardite infecciosa subaguda em valva mitral.', 'Internação. Colher 3 pares de hemoculturas antes de antibiótico. Início empírico com vancomicina EV (alergia a penicilina) + gentamicina. ETE para avaliar complicações perivalvares e embolização. Avaliação do cirurgião cardíaco.'),
  (1685, 500, 2, '2024-08-08 09:00', 'internacao', 'Resultado das hemoculturas', 114, 66, 88, 67.5, 'Hemoculturas: 3/3 positivas para Streptococcus gordonii (grupo viridans), sensível à penicilina (CIM 0,06) e à ceftriaxona. ETE: vegetação de 11 mm no folheto anterior, IM moderada, sem perfuração valvar nem abscesso perivalvar. Sem sinais de embolização cerebral na ressonância de crânio. Afebril há 48 h com antibiótico. Alergia à penicilina era leve e antiga; ceftriaxona escolhida com boa tolerância (teste com primeira dose sem reação).', 'Trocar por ceftriaxona 2 g EV 1x/dia por 4 semanas total (tratamento de 4 semanas por válvula nativa). Suspender vancomicina e gentamicina. Avaliação odontológica e tratamento de focos. Hemoculturas de controle em 48 h. Cirurgia somente se IC, embolias ou aumento da vegetação.'),
  (1686, 500, 2, '2024-11-12 14:00', 'retorno', 'Retorno após o tratamento da endocardite', 116, 70, 70, 71.5, 'Concluiu 4 semanas de ceftriaxona sem intercorrências, afebril desde o 3º dia, sem embolias. Recuperou 4 kg. Hemoculturas de controle negativas. PCR 4. ECO: vegetação resolvida, restou espessamento do folheto anterior, IM leve a moderada, FEVE 62%. Foi à odontologia e tratou cáries. Orientado sobre profilaxia antes de procedimentos dentários (alergia à penicilina: azitromicina 500 mg em dose única) e higiene bucal.', 'Sem antibiótico. Profilaxia de endocardite antes de procedimentos dentários invasivos (azitromicina 500 mg 1 h antes). ECO em 6 meses; avaliar necessidade de plástica valvar se IM progredir. Higiene oral e visitas ao dentista a cada 6 meses. Retorno em 6 meses.');
